// Generated by scripts/build-alilab-catalogue.mjs; source and licences in catalogue/.
export const EXDB=JSON.parse("[{\"id\":\"0001\",\"n\":\"3/4 sit-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0001.webp\",\"gif\":\"0001.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A shortened sit-up that stops at about 45 degrees, keeping tension on the abs the whole time.\",\"fv\":\"2476\"},{\"id\":\"0002\",\"n\":\"45° side bend\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms extended straight down by your sides.\",\"Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0002.webp\",\"gif\":\"0002.mp4\",\"cat\":\"strength\",\"desc\":\"A standing side bend that works the obliques by leaning the torso sideways and coming back up.\"},{\"id\":\"0003\",\"n\":\"air bike\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your hands placed behind your head.\",\"Lift your legs off the ground and bend your knees at a 90-degree angle.\",\"Bring your right elbow towards your left knee while simultaneously straightening your right leg.\",\"Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.\",\"Continue alternating sides in a pedaling motion for the desired number of repetitions.\"],\"img\":\"0003.webp\",\"gif\":\"0003.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bicycle-style crunch where opposite elbow and knee meet while the other leg straightens. Hits the abs and obliques.\"},{\"id\":\"1512\",\"n\":\"all fours squad stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Start on all fours with your hands directly under your shoulders and your knees directly under your hips.\",\"Extend one leg straight back, keeping your knee bent and your foot flexed.\",\"Slowly lower your hips towards the ground, feeling a stretch in your quads.\",\"Hold this position for 20-30 seconds.\",\"Switch legs and repeat the stretch on the other side.\"],\"img\":\"1512.webp\",\"gif\":\"1512.mp4\",\"cat\":\"stretching\",\"desc\":\"On all fours you pull one foot toward your glutes to stretch the front of the thigh. It eases tight quads.\",\"fv\":\"4513\"},{\"id\":\"0006\",\"n\":\"alternate heel touchers\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Extend your arms straight out to the sides, parallel to the ground.\",\"Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.\",\"Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0006.webp\",\"gif\":\"0006.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you crunch sideways to reach each hand toward its heel in turn. Works the obliques and abs.\",\"fv\":\"3801\"},{\"id\":\"0007\",\"n\":\"alternate lateral pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\"],\"st\":[\"Sit on the cable machine with your back straight and feet flat on the ground.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0007.webp\",\"gif\":\"0007.mp4\",\"cat\":\"strength\",\"desc\":\"A cable lat pulldown done one handle at a time, building the lats with a stretch and squeeze on each side.\"},{\"id\":\"1368\",\"n\":\"ankle circles\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankle stabilizers\",\"sm\":[\"ankle stabilizers\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Lift one leg off the ground and rotate your ankle in a circular motion.\",\"Perform the desired number of circles in one direction, then switch to the other direction.\",\"Repeat with the other leg.\"],\"img\":\"1368.webp\",\"gif\":\"1368.mp4\",\"cat\":\"mobility\",\"desc\":\"Sit and move your foot in slow circles from the ankle. It warms up the ankle joint and the muscles around the calf.\",\"fv\":\"3931\"},{\"id\":\"3293\",\"n\":\"archer pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Engage your core and pull your shoulder blades down and back.\",\"As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.\",\"Continue pulling until your chin is above the bar and your bent arm is fully flexed.\",\"Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.\",\"Alternate sides with each repetition.\"],\"img\":\"3293.webp\",\"gif\":\"3293.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide pull-up where you pull toward one hand while the other arm stays straight. It builds lat strength on the way to the one arm pull-up.\"},{\"id\":\"3294\",\"n\":\"archer push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart.\",\"Extend one arm straight out to the side, parallel to the ground.\",\"Lower your body by bending your elbows, keeping your back straight and core engaged.\",\"Push back up to the starting position.\",\"Repeat on the other side, extending the opposite arm out to the side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3294.webp\",\"gif\":\"3294.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide push-up that shifts the weight to one arm while the other arm stays straight. It trains the chest and triceps on the way to one arm push-ups.\"},{\"id\":\"2355\",\"n\":\"arm slingers hanging bent knee legs\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.\",\"Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2355.webp\",\"gif\":\"2355.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging knee raise bringing knees toward your elbows. Strengthens the abs and hip flexors.\"},{\"id\":\"2333\",\"n\":\"arm slingers hanging straight legs\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your legs straight down.\",\"Engage your core and lift your legs up in front of you until they are parallel to the ground.\",\"Hold for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2333.webp\",\"gif\":\"2333.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging straight-leg raise. Strengthens the abs and hip flexors and challenges your grip.\"},{\"id\":\"3214\",\"n\":\"arms apart circular toe touch (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and arms extended to the sides.\",\"Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.\",\"As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.\",\"Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3214.webp\",\"gif\":\"3214.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing toe touch with a circular path and a leg lifting behind you. It loosens the hamstrings and challenges balance.\"},{\"id\":\"3204\",\"n\":\"arms overhead full sit-up (male)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Extend your arms overhead, keeping them straight.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3204.webp\",\"gif\":\"3204.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A full sit-up with the arms stretched overhead, which makes the lever longer and the move harder. It trains the abs and hip flexors.\"},{\"id\":\"0009\",\"n\":\"assisted chest dip (kneeling)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the machine to your desired height and secure your knees on the pad.\",\"Grasp the handles with your palms facing down and your arms fully extended.\",\"Lower your body by bending your elbows until your upper arms are parallel to the floor.\",\"Pause for a moment, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0009.webp\",\"gif\":\"0009.mp4\",\"cat\":\"strength\",\"desc\":\"A machine-assisted chest dip performed from a kneeling pad, so you can train dips with less of your bodyweight.\",\"fv\":\"2528\"},{\"id\":\"0011\",\"n\":\"assisted hanging knee raise\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.\",\"Pause for a moment at the top of the movement, squeezing your abs.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0011.webp\",\"gif\":\"0011.mp4\",\"cat\":\"strength\",\"desc\":\"A hanging knee raise with machine or band assistance. Builds lower ab and hip flexor strength.\"},{\"id\":\"0010\",\"n\":\"assisted hanging knee raise with throw down\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your knees towards your chest, keeping your legs together.\",\"Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.\",\"Allow your legs to swing back up and repeat the movement for the desired number of repetitions.\"],\"img\":\"0010.webp\",\"gif\":\"0010.mp4\",\"cat\":\"strength\",\"desc\":\"An assisted hanging knee raise that ends with the legs dropping back down under control. Trains the abs and hip flexors.\"},{\"id\":\"1708\",\"n\":\"assisted lying calves stretch\",\"bp\":\"lower legs\",\"eq\":\"assisted\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Lie on your back with your legs extended.\",\"Bend one knee and place your foot flat on the ground.\",\"Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.\",\"Hold the stretch for 20-30 seconds.\",\"Release the stretch and repeat on the other leg.\"],\"img\":\"1708.webp\",\"gif\":\"1708.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch lying on your back for the calves. It lengthens the lower leg.\"},{\"id\":\"1709\",\"n\":\"assisted lying glutes stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Lie on your back with your legs extended.\",\"Bend your right knee and place your right ankle on your left thigh, just above the knee.\",\"Grasp your left thigh with both hands and gently pull it towards your chest.\",\"Hold the stretch for 20-30 seconds.\",\"Release and repeat on the other side.\"],\"img\":\"1709.webp\",\"gif\":\"1709.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch lying down for the glutes. It eases the hips.\"},{\"id\":\"1710\",\"n\":\"assisted lying gluteus and piriformis stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Lie on your back with your legs extended.\",\"Bend your right knee and place your right ankle on your left thigh, just above the knee.\",\"Grasp your left thigh with both hands and gently pull it towards your chest.\",\"Hold the stretch for 20-30 seconds.\",\"Release the stretch and repeat on the other side.\"],\"img\":\"1710.webp\",\"gif\":\"1710.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch lying down for the glutes and piriformis. It releases deep hip tension.\"},{\"id\":\"0012\",\"n\":\"assisted lying leg raise with lateral throw down\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Place your hands under your glutes for support.\",\"Engage your abs and lift your legs off the ground, keeping them straight.\",\"While keeping your legs together, lower them to one side until they are a few inches above the ground.\",\"Pause for a moment, then lift your legs back to the starting position.\",\"Repeat the movement to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0012.webp\",\"gif\":\"0012.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg raise where the legs lower to alternating sides, adding an oblique challenge to the lower abs.\"},{\"id\":\"0013\",\"n\":\"assisted lying leg raise with throw down\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Place your hands under your glutes for support.\",\"Engage your core and lift your legs off the ground, keeping them straight.\",\"Raise your legs until they are perpendicular to the ground.\",\"Lower your legs back down to the starting position.\",\"Simultaneously, throw your legs down towards the ground, keeping them straight.\",\"Raise your legs back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0013.webp\",\"gif\":\"0013.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg raise with the legs lifted straight up and lowered with control. Works the lower abs.\"},{\"id\":\"0014\",\"n\":\"assisted motion russian twist\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the ground with your knees bent and feet flat on the floor.\",\"Hold the medicine ball with both hands in front of your chest.\",\"Lean back slightly, engaging your abs and keeping your back straight.\",\"Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.\",\"Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0014.webp\",\"gif\":\"0014.mp4\",\"cat\":\"strength\",\"desc\":\"A seated medicine ball twist, from side to side, that trains the obliques and abs with a leaned-back torso.\"},{\"id\":\"0015\",\"n\":\"assisted parallel close grip pull-up\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the machine to your desired weight and height.\",\"Place your hands on the parallel bars with a close grip, palms facing each other.\",\"Hang from the bars with your arms fully extended and your feet off the ground.\",\"Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the bars.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0015.webp\",\"gif\":\"0015.mp4\",\"cat\":\"strength\",\"desc\":\"A machine-assisted pull-up on parallel bars with a close neutral grip. Builds the lats and biceps with less bodyweight.\"},{\"id\":\"0016\",\"n\":\"assisted prone hamstring\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Lie face down on a mat or bench with your legs fully extended.\",\"Have a partner or use a resistance band to secure your ankles.\",\"Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0016.webp\",\"gif\":\"0016.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you curl your legs toward your glutes against assistance. Trains the hamstrings.\"},{\"id\":\"1713\",\"n\":\"assisted prone lying quads stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Lie face down on the ground with your legs extended.\",\"Bend your left knee and reach back with your left hand to grab your left foot or ankle.\",\"Gently pull your left foot towards your glutes, feeling a stretch in your left quad.\",\"Hold the stretch for 20-30 seconds, then release.\",\"Repeat with your right leg.\"],\"img\":\"1713.webp\",\"gif\":\"1713.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch lying face down for the quads. It lengthens the front of the thigh.\"},{\"id\":\"1714\",\"n\":\"assisted prone rectus femoris stretch\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\"],\"st\":[\"Lie face down on the ground with your legs straight.\",\"Bend your right knee and reach back with your right hand to grab your right foot or ankle.\",\"Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.\",\"Hold the stretch for 20-30 seconds.\",\"Release and repeat on the other side.\"],\"img\":\"1714.webp\",\"gif\":\"1714.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch lying face down for the rectus femoris. It lengthens the front of the hip and thigh.\"},{\"id\":\"0017\",\"n\":\"assisted pull-up\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the machine to your desired weight and height settings.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang with your arms fully extended and your feet off the ground.\",\"Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the handles.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0017.webp\",\"gif\":\"0017.mp4\",\"cat\":\"strength\",\"desc\":\"A pull-up on an assisted machine that takes some of your weight, so you can build up to full pull-ups.\",\"fv\":\"2529\"},{\"id\":\"1716\",\"n\":\"assisted seated pectoralis major stretch with stability ball\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your back straight.\",\"Hold a stability ball with both hands and extend your arms straight out in front of you.\",\"Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.\",\"Hold the stretch for a few seconds, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1716.webp\",\"gif\":\"1716.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated chest stretch with help from a stability ball. It opens up the pectoralis major.\"},{\"id\":\"1712\",\"n\":\"assisted side lying adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Lie on your side with your legs straight and stacked on top of each other.\",\"Bend your bottom leg slightly for stability.\",\"Place your top foot on a stable surface, such as a bench or step.\",\"Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.\",\"Hold the stretch for 20-30 seconds.\",\"Return to the starting position and repeat on the other side.\"],\"img\":\"1712.webp\",\"gif\":\"1712.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch lying on your side for the inner thigh. It lengthens the adductors.\"},{\"id\":\"1758\",\"n\":\"assisted sit-up\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the edge of a bench or have someone hold your feet down.\",\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1758.webp\",\"gif\":\"1758.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with your feet held down by a partner or anchor. Trains the abs through a full curling motion.\"},{\"id\":\"1431\",\"n\":\"assisted standing chin-up\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the machine to your desired assistance level.\",\"Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your chest up and shoulders back, engage your core, and slightly bend your knees.\",\"Pull your body up by flexing your elbows and driving your elbows down towards your sides.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1431.webp\",\"gif\":\"1431.mp4\",\"cat\":\"strength\",\"desc\":\"A chin-up done on an assisted machine that takes part of your body weight. It builds the lats and biceps while you work up to full chin-ups.\"},{\"id\":\"1432\",\"n\":\"assisted standing pull-up\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the machine to your desired weight and height settings.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Engage your lats and biceps, and pull yourself up towards the handles.\",\"Pause for a moment at the top, squeezing your back muscles.\",\"Slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1432.webp\",\"gif\":\"1432.mp4\",\"cat\":\"strength\",\"desc\":\"A pull-up done on an assisted machine that takes part of your body weight. It builds the lats and upper back while you work up to full pull-ups.\"},{\"id\":\"0018\",\"n\":\"assisted standing triceps extension (with towel)\",\"bp\":\"upper arms\",\"eq\":\"assisted\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.\",\"Keep your elbows close to your ears and your upper arms stationary.\",\"Slowly extend your forearms upward, squeezing your triceps at the top.\",\"Pause for a moment, then slowly lower the towel back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0018.webp\",\"gif\":\"0018.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead triceps extension holding a towel behind the head. A light way to train the triceps.\"},{\"id\":\"0019\",\"n\":\"assisted triceps dip (kneeling)\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Adjust the machine to your desired weight and height.\",\"Kneel down on the pad facing the machine, with your hands gripping the handles.\",\"Lower your body by bending your elbows, keeping your back straight and close to the machine.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0019.webp\",\"gif\":\"0019.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling machine-assisted triceps dip that lowers the load, so you can build pressing strength in the triceps.\",\"fv\":\"2575\"},{\"id\":\"2364\",\"n\":\"assisted wide-grip chest dip (kneeling)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the machine to your desired height and secure your knees on the pad.\",\"Grasp the handles with a wide grip and keep your elbows slightly bent.\",\"Lower your body by bending your elbows until your upper arms are parallel to the floor.\",\"Push yourself back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2364.webp\",\"gif\":\"2364.mp4\",\"cat\":\"strength\",\"desc\":\"A machine-assisted wide-grip dip with your knees on a pad. Lets you train the chest with less bodyweight.\"},{\"id\":\"3220\",\"n\":\"astride jumps (male)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees and lower your body into a squat position.\",\"Jump explosively upwards, extending your legs and arms.\",\"While in the air, spread your legs apart and bring your arms out to the sides.\",\"Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3220.webp\",\"gif\":\"3220.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump from a squat that ends with the legs spread wide, like a jumping jack with a squat start. It raises the heart rate and trains the legs.\"},{\"id\":\"3672\",\"n\":\"back and forth step\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Step forward with your right foot, bending your knee and lowering your body into a lunge position.\",\"Push off with your right foot and step back to the starting position.\",\"Repeat the movement with your left foot, alternating legs with each step.\",\"Continue stepping back and forth, maintaining a steady pace.\",\"Repeat for the desired duration or number of repetitions.\"],\"img\":\"3672.webp\",\"gif\":\"3672.mp4\",\"cat\":\"cardio\",\"desc\":\"A stepping drill moving forward and back with the legs alternating. It raises the heart rate and warms up the legs.\"},{\"id\":\"1314\",\"n\":\"back extension on exercise ball\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.\",\"Position your hands behind your head or crossed over your chest.\",\"Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1314.webp\",\"gif\":\"1314.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down over a stability ball and lift your chest to extend your back. It strengthens the lower back and glutes in a supported way.\"},{\"id\":\"3297\",\"n\":\"back lever\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"core\"],\"st\":[\"Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Engage your core and pull your shoulder blades down and back.\",\"Bend your knees and tuck them towards your chest.\",\"Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.\",\"Hold this position for a few seconds, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3297.webp\",\"gif\":\"3297.mp4\",\"cat\":\"isometric\",\"desc\":\"A gymnastics hold hanging from a bar with the body horizontal and facing down. It trains the upper back, shoulders and core.\",\"hd\":1},{\"id\":\"1405\",\"n\":\"back pec stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Stand tall with your feet shoulder-width apart.\",\"Extend your arms straight out in front of you, parallel to the ground.\",\"Cross your arms in front of your body, with your right arm over your left arm.\",\"Interlock your fingers and rotate your palms away from your body.\",\"Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.\",\"Hold the stretch for 15-30 seconds, then release.\",\"Repeat on the opposite side.\"],\"img\":\"1405.webp\",\"gif\":\"1405.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the chest and front of the shoulder with your arms reached behind you. It opens up the pecs and lats.\"},{\"id\":\"1473\",\"n\":\"backward jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees slightly and jump backwards, pushing off with both feet.\",\"Land softly on the balls of your feet, bending your knees to absorb the impact.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1473.webp\",\"gif\":\"1473.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bodyweight jump backward with a soft landing. It builds explosive power in the quads and trains control.\"},{\"id\":\"0020\",\"n\":\"balance board\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"hamstrings\",\"glutes\"],\"st\":[\"Place the balance board on a flat surface.\",\"Step onto the balance board with one foot, ensuring it is centered.\",\"Slowly shift your weight onto the foot on the balance board, keeping your core engaged.\",\"Maintain your balance and stability as you hold the position for a desired amount of time.\",\"Repeat the exercise with the other foot.\"],\"img\":\"0020.webp\",\"gif\":\"0020.mp4\",\"cat\":\"mobility\",\"desc\":\"Standing on a balance board to challenge stability. Improves balance and wakes up the muscles of the legs and ankles.\"},{\"id\":\"0968\",\"n\":\"band alternating biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.\",\"Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.\",\"Lower the arm back down to the starting position and repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0968.webp\",\"gif\":\"0968.mp4\",\"cat\":\"strength\",\"desc\":\"A band curl alternating one arm at a time. It trains the biceps.\"},{\"id\":\"0969\",\"n\":\"band alternating v-up\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs straight and your arms extended overhead, holding the band.\",\"Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.\",\"As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.\",\"Repeat the movement, alternating the position of your legs with each repetition.\",\"Continue for the desired number of repetitions.\"],\"img\":\"0969.webp\",\"gif\":\"0969.mp4\",\"cat\":\"strength\",\"desc\":\"A V-up with a band, alternating the leg position each rep. It trains the abs and hip flexors.\"},{\"id\":\"0970\",\"n\":\"band assisted pull-up\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach the band to a pull-up bar or sturdy anchor point.\",\"Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.\",\"Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.\",\"Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.\",\"Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0970.webp\",\"gif\":\"0970.mp4\",\"cat\":\"strength\",\"desc\":\"A pull-up with a band looped under the feet for assistance. It builds the lats and biceps while you work toward unassisted pull-ups.\"},{\"id\":\"0971\",\"n\":\"band assisted wheel rollerout\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\"],\"st\":[\"Kneel on the floor and hold the handles of the band with both hands, palms facing down.\",\"Place the band on the ground in front of you and position your hands shoulder-width apart.\",\"Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.\",\"Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0971.webp\",\"gif\":\"0971.mp4\",\"cat\":\"strength\",\"desc\":\"An ab wheel rollout with a band to help bring you back. It trains the abs with a lighter load.\",\"fv\":\"2649\"},{\"id\":\"1254\",\"n\":\"band bench press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Extend your arms fully, pushing the bands away from your chest.\",\"Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1254.webp\",\"gif\":\"1254.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press using resistance bands. It trains the chest, shoulders and triceps.\"},{\"id\":\"0980\",\"n\":\"band bent-over hip extension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Attach the band to a sturdy anchor point at ankle height.\",\"Stand facing away from the anchor point with your feet shoulder-width apart.\",\"Step back to create tension in the band, keeping your knees slightly bent.\",\"Hinge at the hips and lean forward, maintaining a neutral spine.\",\"Extend your right leg straight back, squeezing your glutes at the top.\",\"Lower your right leg back down and repeat with the left leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"0980.webp\",\"gif\":\"0980.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over hip extension with a band, kicking one leg back. It trains the glutes.\",\"mv\":\"4035\"},{\"id\":\"0972\",\"n\":\"band bicycle crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie flat on your back with your hands behind your head and your knees bent.\",\"Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.\",\"Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.\",\"Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0972.webp\",\"gif\":\"0972.mp4\",\"cat\":\"strength\",\"desc\":\"A bicycle crunch with a band, rotating the torso and alternating the knees. It trains the abs and obliques.\"},{\"id\":\"0974\",\"n\":\"band close-grip pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.\",\"Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.\",\"Step back to create tension in the band, keeping your feet hip-width apart.\",\"Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0974.webp\",\"gif\":\"0974.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip pulldown with a band, pulling down toward the chest. It trains the lats and biceps.\"},{\"id\":\"0975\",\"n\":\"band close-grip push-up\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Place a band around your upper arms, just above the elbows.\",\"Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.\",\"Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0975.webp\",\"gif\":\"0975.mp4\",\"cat\":\"strength\",\"desc\":\"A push-up with a band around the upper arms to keep the elbows in. It trains the triceps and chest.\"},{\"id\":\"0976\",\"n\":\"band concentration curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench or chair with your legs spread apart and your feet flat on the ground.\",\"Hold one end of the band in your hand and step on the other end with your foot on the same side.\",\"Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.\",\"With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.\",\"Pause for a moment at the top, then slowly lower your hand back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0976.webp\",\"gif\":\"0976.mp4\",\"cat\":\"strength\",\"desc\":\"A seated concentration curl with a band, with the elbow braced on the thigh. It isolates the biceps.\"},{\"id\":\"3117\",\"n\":\"band fixed back close grip pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.\",\"Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.\",\"Grasp the band with a close grip, palms facing towards you.\",\"Keep your back straight and engage your core.\",\"Pull the band down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, feeling the contraction in your lats.\",\"Slowly release the band back to the starting position, maintaining control throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3117.webp\",\"gif\":\"3117.mp4\",\"cat\":\"strength\",\"desc\":\"A band pulldown with a close grip from an overhead anchor. Builds the lats and biceps.\"},{\"id\":\"3116\",\"n\":\"band fixed back underhand pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Attach the band to a sturdy anchor point above your head.\",\"Stand facing the anchor point with your feet shoulder-width apart.\",\"Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.\",\"Step back to create tension in the band, keeping your arms fully extended.\",\"Engage your core and squeeze your shoulder blades together.\",\"Pull the band down towards your chest, leading with your elbows.\",\"Pause for a moment at the bottom of the movement, feeling the contraction in your lats.\",\"Slowly release the tension in the band and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3116.webp\",\"gif\":\"3116.mp4\",\"cat\":\"strength\",\"desc\":\"A band pulldown with an underhand grip from an overhead anchor. Builds the lats and biceps.\"},{\"id\":\"0977\",\"n\":\"band front lateral raise\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.\",\"Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the band back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0977.webp\",\"gif\":\"0977.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with a band, lifting straight arms to shoulder height. It trains the front delts.\",\"fv\":\"3975\"},{\"id\":\"0978\",\"n\":\"band front raise\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.\",\"Keep your arms straight and slowly raise them forward until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0978.webp\",\"gif\":\"0978.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with a band, raising both arms forward. It builds the front shoulders.\"},{\"id\":\"1408\",\"n\":\"band hip lift\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Lie on your back with your knees bent and feet flat on the ground.\",\"Place a resistance band just above your knees.\",\"Engage your glutes and core muscles.\",\"Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1408.webp\",\"gif\":\"1408.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on your back with a band around your thighs and lift your hips. It strengthens the glutes and the outer hips.\"},{\"id\":\"0979\",\"n\":\"band horizontal pallof press\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\"],\"st\":[\"Attach the band to a sturdy anchor point at waist height.\",\"Stand perpendicular to the anchor point with your feet shoulder-width apart.\",\"Grasp the band handle with both hands and step away from the anchor point to create tension in the band.\",\"Bring your hands to your chest, keeping your elbows bent and close to your body.\",\"Engage your core and maintain a stable stance.\",\"Extend your arms straight out in front of you, pushing the band away from your body.\",\"Hold the extended position for a few seconds, focusing on maintaining tension in your core.\",\"Slowly bring your hands back to your chest, resisting the pull of the band.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0979.webp\",\"gif\":\"0979.mp4\",\"cat\":\"isometric\",\"desc\":\"A Pallof press with a band anchored to the side, pressing out and holding. It trains the core to resist rotation.\"},{\"id\":\"0981\",\"n\":\"band jack knife sit-up\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs straight and your arms extended overhead, holding the band.\",\"Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.\",\"Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0981.webp\",\"gif\":\"0981.mp4\",\"cat\":\"strength\",\"desc\":\"A jackknife sit-up with a band, lifting legs and torso together. It trains the abs and hip flexors.\",\"fv\":\"2541\"},{\"id\":\"0983\",\"n\":\"band kneeling one arm pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\"],\"st\":[\"Attach the band to a sturdy anchor point above your head.\",\"Kneel down and hold the band with one hand, palm facing down.\",\"Extend your arm fully overhead, keeping your elbow slightly bent.\",\"Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.\",\"Pause for a moment at the bottom, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0983.webp\",\"gif\":\"0983.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling one-arm pulldown with a band, driving the elbow toward the ribs. It trains the lats.\",\"fv\":\"3842\"},{\"id\":\"0985\",\"n\":\"band kneeling twisting crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Attach the band to a sturdy anchor point at waist height.\",\"Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.\",\"Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0985.webp\",\"gif\":\"0985.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling crunch with a twist using a band. It trains the abs and obliques.\"},{\"id\":\"0984\",\"n\":\"band lying hip internal rotation\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Lie on your back with your legs straight and a resistance band looped around your feet.\",\"Bend your knees and bring them towards your chest, keeping your feet together.\",\"Slowly rotate your knees outwards, away from each other, while keeping your feet together.\",\"Pause for a moment at the end of the rotation, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0984.webp\",\"gif\":\"0984.mp4\",\"cat\":\"mobility\",\"desc\":\"A lying hip rotation with a band around the feet or legs, rotating the knees out and back. It works the glutes and hips.\"},{\"id\":\"1002\",\"n\":\"band lying straight leg raise\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs straight and your feet together.\",\"Place the band around the arches of your feet and hold the ends of the band with your hands.\",\"Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1002.webp\",\"gif\":\"1002.mp4\",\"cat\":\"strength\",\"desc\":\"A lying straight leg raise with a band held in the hands. It trains the abs and hip flexors.\"},{\"id\":\"0986\",\"n\":\"band one arm overhead biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and place one end of the band under your foot.\",\"Hold the other end of the band with your arm fully extended overhead, palm facing forward.\",\"Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.\",\"Pause for a moment at the top, then slowly lower your forearm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0986.webp\",\"gif\":\"0986.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm curl with the arm held overhead against band tension. It trains the biceps.\"},{\"id\":\"0987\",\"n\":\"band one arm single leg split squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Stand with your feet hip-width apart and place a resistance band around your ankles.\",\"Extend one leg forward and rest the top of your foot on a bench or step behind you.\",\"Hold onto a support with one hand for balance.\",\"Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.\",\"Push through your heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0987.webp\",\"gif\":\"0987.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg split squat with a band, back foot raised. It trains the quads and glutes.\"},{\"id\":\"0988\",\"n\":\"band one arm standing low row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Attach the band to a stable anchor point at waist height.\",\"Stand facing the anchor point with your feet shoulder-width apart.\",\"Hold the band with one hand, palm facing inward, and step back to create tension in the band.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Pull the band towards your waist, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release the band back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0988.webp\",\"gif\":\"0988.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm low row with a band. It trains the back and biceps.\"},{\"id\":\"0989\",\"n\":\"band one arm twisting chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Attach the band to a sturdy anchor point at chest height.\",\"Stand with your side facing the anchor point and grab the band with one hand.\",\"Step away from the anchor point to create tension in the band.\",\"Position your feet shoulder-width apart and slightly bend your knees.\",\"Bring your hand holding the band across your body, towards the opposite shoulder.\",\"While maintaining tension in the band, push your hand forward and away from your body, extending your arm.\",\"Slowly return to the starting position and repeat for the desired number of repetitions.\",\"Switch sides and repeat the exercise with the other hand.\"],\"img\":\"0989.webp\",\"gif\":\"0989.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm chest press with a band that adds a twist. It trains the chest and core.\"},{\"id\":\"0990\",\"n\":\"band one arm twisting seated row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground and your back straight.\",\"Hold the band with one hand and extend your arm fully in front of you.\",\"Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.\",\"At the same time, twist your torso towards the side of the pulling arm.\",\"Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0990.webp\",\"gif\":\"0990.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm row with a band and a torso twist. It trains the back and obliques.\",\"fv\":\"3843\"},{\"id\":\"0991\",\"n\":\"band pull through\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Attach a resistance band to a sturdy anchor point at ground level.\",\"Stand facing away from the anchor point with your feet shoulder-width apart.\",\"Step forward to create tension in the band, keeping your knees slightly bent.\",\"Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.\",\"Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.\",\"Drive your hips forward and squeeze your glutes to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0991.webp\",\"gif\":\"0991.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge pulling a band through the legs. It trains the glutes and hamstrings.\",\"fv\":\"3024\"},{\"id\":\"0992\",\"n\":\"band push sit-up\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Attach the band securely to a stable anchor point.\",\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Hold the band with both hands and extend your arms straight up towards the ceiling.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0992.webp\",\"gif\":\"0992.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up that pushes a band forward as you come up. It trains the abs.\"},{\"id\":\"0993\",\"n\":\"band reverse fly\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Attach the band to a stationary object at chest height.\",\"Stand with your feet shoulder-width apart and hold the band with both hands in front of you.\",\"Keep your arms straight and lift them out to the sides until they are parallel to the ground.\",\"Squeeze your shoulder blades together at the top of the movement.\",\"Slowly lower your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0993.webp\",\"gif\":\"0993.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse fly with a band, opening the arms to the sides. It trains the rear delts and upper back.\"},{\"id\":\"0994\",\"n\":\"band reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"band\",\"tg\":\"forearms\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground.\",\"Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.\",\"Rest your forearms on your thighs, with your wrists hanging off the edge.\",\"Slowly curl your wrists upward, squeezing your forearms.\",\"Pause for a moment at the top, then slowly lower your wrists back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0994.webp\",\"gif\":\"0994.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse wrist curl with a band, lifting the back of the hands. It strengthens the forearms.\"},{\"id\":\"0996\",\"n\":\"band seated hip internal rotation\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Sit on a chair or bench with your back straight and feet flat on the ground.\",\"Place a resistance band around your thighs, just above your knees.\",\"Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.\",\"Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0996.webp\",\"gif\":\"0996.mp4\",\"cat\":\"strength\",\"desc\":\"A seated hip rotation against a band around the thighs. It works the glutes and hip muscles.\"},{\"id\":\"1011\",\"n\":\"band seated twist\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Sit on the ground with your legs extended in front of you and your back straight.\",\"Wrap the band around your waist and hold the ends with both hands.\",\"Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.\",\"Pause for a moment at the end of the twist, then slowly return to the starting position.\",\"Repeat the twist to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1011.webp\",\"gif\":\"1011.mp4\",\"cat\":\"strength\",\"desc\":\"A seated twist with a band around the waist. It trains the abs and obliques.\",\"fv\":\"2446\"},{\"id\":\"0997\",\"n\":\"band shoulder press\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band under your feet.\",\"Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.\",\"Press the band overhead, fully extending your arms.\",\"Pause for a moment at the top, then slowly lower the band back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0997.webp\",\"gif\":\"0997.mp4\",\"cat\":\"strength\",\"desc\":\"A shoulder press with a band under the feet. It builds the shoulders and triceps.\"},{\"id\":\"1018\",\"n\":\"band shrug\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.\",\"Keep your arms straight and relaxed, and let the band hang in front of your thighs.\",\"Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.\",\"Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1018.webp\",\"gif\":\"1018.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug with a band, lifting the shoulders toward the ears. It trains the traps.\"},{\"id\":\"0998\",\"n\":\"band side triceps extension\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.\",\"Extend your arms straight out to the sides, keeping them parallel to the ground.\",\"Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.\",\"Pause for a moment, then slowly extend your arms back out to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0998.webp\",\"gif\":\"0998.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension with a band, extending the arms out to the sides. It works the triceps.\"},{\"id\":\"0999\",\"n\":\"band single leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand with your feet hip-width apart and place the band around the ball of your left foot.\",\"Hold onto a stable object for balance if needed.\",\"Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.\",\"Pause for a moment at the top, then slowly lower your left heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the right leg.\"],\"img\":\"0999.webp\",\"gif\":\"0999.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg calf raise with a band around the foot. It trains the calves.\"},{\"id\":\"1000\",\"n\":\"band single leg reverse calf raise\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet hip-width apart and place the band around the ball of your foot.\",\"Hold onto a stable object for balance.\",\"Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other leg.\"],\"img\":\"1000.webp\",\"gif\":\"1000.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg calf raise with a band, rising onto the ball of the foot. It trains the calves.\"},{\"id\":\"1001\",\"n\":\"band single leg split squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Stand with your feet hip-width apart and place a resistance band around your ankles.\",\"Take a big step forward with your right foot and a smaller step back with your left foot.\",\"Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.\",\"Push through your right heel to return to the starting position.\",\"Repeat on the other side.\"],\"img\":\"1001.webp\",\"gif\":\"1001.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg split squat with a band. It trains the quads and glutes.\"},{\"id\":\"1004\",\"n\":\"band squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, with the band placed just above your knees.\",\"Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.\",\"Make sure your knees are tracking over your toes and your weight is in your heels.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1004.webp\",\"gif\":\"1004.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a band above the knees. It trains the glutes and thighs.\"},{\"id\":\"1003\",\"n\":\"band squat row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"back\"],\"st\":[\"Attach the band to a sturdy anchor point at waist height.\",\"Stand facing the anchor point with your feet shoulder-width apart.\",\"Hold the band handles with your palms facing each other and your arms extended in front of you.\",\"Bend your knees and lower into a squat position, keeping your back straight and chest lifted.\",\"From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1003.webp\",\"gif\":\"1003.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a band row, pulling the handles as you stand. It works the legs and back.\"},{\"id\":\"1005\",\"n\":\"band standing crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Attach the band to a sturdy anchor point at waist height.\",\"Stand facing away from the anchor point with your feet shoulder-width apart.\",\"Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.\",\"Engage your abs and slowly crunch forward, bringing your chest towards your knees.\",\"Pause for a moment at the top of the crunch, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1005.webp\",\"gif\":\"1005.mp4\",\"cat\":\"strength\",\"desc\":\"A standing crunch with a band, curling the torso forward. It trains the abs.\",\"fv\":\"3839\"},{\"id\":\"1022\",\"n\":\"band standing rear delt row\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band under your feet.\",\"Hold the band handles with your palms facing each other and your arms extended in front of you.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Pull the band towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1022.webp\",\"gif\":\"1022.mp4\",\"cat\":\"strength\",\"desc\":\"A standing rear delt row with a band, pulling the handles toward the chest. It trains the rear delts.\",\"fv\":\"3976\"},{\"id\":\"1007\",\"n\":\"band standing twisting crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.\",\"Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.\",\"Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.\",\"Pause for a moment, then return to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1007.webp\",\"gif\":\"1007.mp4\",\"cat\":\"strength\",\"desc\":\"A standing twisting crunch with a band, bringing the elbow toward the opposite knee. It trains the abs and obliques.\"},{\"id\":\"1008\",\"n\":\"band step-up\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Place a band around your thighs, just above your knees.\",\"Stand facing a step or platform with your feet hip-width apart.\",\"Step up onto the platform with your right foot, pushing through your heel.\",\"Extend your left leg behind you, keeping it straight.\",\"Lower your left foot back down to the ground.\",\"Repeat with your left foot stepping up onto the platform.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"1008.webp\",\"gif\":\"1008.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with a band around the thighs. It trains the glutes and quads.\"},{\"id\":\"1009\",\"n\":\"band stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band around your ankles.\",\"Hold the band with both hands in front of your thighs, palms facing your body.\",\"Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.\",\"As you lower, push your hips back and allow your knees to bend slightly.\",\"Lower the band towards the ground, feeling a stretch in your hamstrings.\",\"Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1009.webp\",\"gif\":\"1009.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-leg deadlift with a band, hinging at the hips. It trains the hamstrings and glutes.\"},{\"id\":\"1023\",\"n\":\"band straight back stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band around your upper legs.\",\"Hold the band with both hands in front of your thighs, palms facing your body.\",\"Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.\",\"Feel the stretch in your hamstrings as you lower the band.\",\"Engage your glutes and hamstrings to lift your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1023.webp\",\"gif\":\"1023.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-leg deadlift with a band, hinging at the hips with a straight back. It trains the glutes and hamstrings.\"},{\"id\":\"1010\",\"n\":\"band straight leg deadlift\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band around your feet.\",\"Hold the band with both hands, palms facing your body, and keep your arms straight.\",\"Engage your core and maintain a slight bend in your knees.\",\"Slowly hinge forward at your hips, keeping your back straight and chest lifted.\",\"Lower the band towards the ground while keeping your legs straight.\",\"Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1010.webp\",\"gif\":\"1010.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-leg deadlift with a band, hinging forward at the hips. It trains the lower back and hamstrings.\"},{\"id\":\"1012\",\"n\":\"band twisting overhead press\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and place the band under your feet.\",\"Hold the band handles at shoulder height with your palms facing forward.\",\"Engage your core and press the band overhead, fully extending your arms.\",\"As you press, twist your torso to one side, keeping your hips stable.\",\"Pause for a moment at the top, then return to the starting position.\",\"Repeat the press and twist on the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1012.webp\",\"gif\":\"1012.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with a band, twisting the torso as you press. It trains the shoulders and core.\"},{\"id\":\"1369\",\"n\":\"band two legs calf raise - (band under both legs) v. 2\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand with your feet shoulder-width apart and place a resistance band under both feet.\",\"Hold the ends of the band with your hands for stability.\",\"Raise your heels off the ground as high as possible, using your calves.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1369.webp\",\"gif\":\"1369.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise with a resistance band under both feet. It builds the calves and ankle strength with progressive tension.\",\"fv\":\"3974\"},{\"id\":\"1013\",\"n\":\"band underhand pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.\",\"Stand facing the anchor point with your feet shoulder-width apart.\",\"Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.\",\"Extend your arms fully overhead, keeping your elbows slightly bent.\",\"Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1013.webp\",\"gif\":\"1013.mp4\",\"cat\":\"strength\",\"desc\":\"An underhand pulldown with a band, pulling toward the chest. It trains the lats and biceps.\"},{\"id\":\"1014\",\"n\":\"band v-up\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs straight and your arms extended overhead, holding the band.\",\"Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.\",\"Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1014.webp\",\"gif\":\"1014.mp4\",\"cat\":\"strength\",\"desc\":\"A V-up with a band, lifting legs and torso together. It trains the abs and hip flexors.\"},{\"id\":\"1015\",\"n\":\"band vertical pallof press\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.\",\"Hold the band with both hands and step away from the anchor point, creating tension in the band.\",\"Position yourself perpendicular to the anchor point, with your side facing the band.\",\"Extend your arms straight out in front of you, keeping your hands at chest height.\",\"Engage your core and press the band away from your chest, fully extending your arms.\",\"Hold the position for a few seconds, then slowly bring the band back towards your chest.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1015.webp\",\"gif\":\"1015.mp4\",\"cat\":\"isometric\",\"desc\":\"A vertical Pallof press with a band, pressing at chest height and holding. It trains the core to resist rotation.\"},{\"id\":\"1016\",\"n\":\"band wrist curl\",\"bp\":\"lower arms\",\"eq\":\"band\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground.\",\"Hold the band with both hands, palms facing up, and rest your forearms on your thighs.\",\"Slowly curl your wrists upward, squeezing your forearms.\",\"Pause for a moment at the top, then slowly lower your wrists back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1016.webp\",\"gif\":\"1016.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with a band, curling the wrists upward. It strengthens the forearms.\"},{\"id\":\"1017\",\"n\":\"band y-raise\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.\",\"Keep your arms straight and lift them up and out to the sides, forming a 'Y' shape with your body.\",\"Squeeze your shoulder blades together at the top of the movement.\",\"Slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1017.webp\",\"gif\":\"1017.mp4\",\"cat\":\"strength\",\"desc\":\"A Y-raise with a band, lifting the arms into a Y shape. It trains the delts and upper back.\"},{\"id\":\"0023\",\"n\":\"barbell alternate biceps curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.\",\"Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.\",\"Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale as you slowly begin to lower the barbells back to the starting position.\",\"Repeat for the desired number of repetitions, alternating arms.\"],\"img\":\"0023.webp\",\"gif\":\"0023.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl where the arms lift the bar alternately, keeping tension on the biceps.\"},{\"id\":\"0024\",\"n\":\"barbell bench front squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.\",\"Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.\",\"Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.\",\"Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0024.webp\",\"gif\":\"0024.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat variation with the bar held on the upper chest, putting the focus on the quads and an upright torso.\",\"fv\":\"3025\"},{\"id\":\"0025\",\"n\":\"barbell bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.\",\"Lower the barbell slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0025.webp\",\"gif\":\"0025.mp4\",\"cat\":\"strength\",\"desc\":\"The classic flat bench press. Lower the bar to your chest and press it up to build the chest, shoulders and triceps.\",\"fv\":\"2440\"},{\"id\":\"0026\",\"n\":\"barbell bench squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Set up a barbell on a squat rack at chest height.\",\"Stand facing away from the rack, with your feet shoulder-width apart.\",\"Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.\",\"Lower your body down into a squat, keeping your knees in line with your toes.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0026.webp\",\"gif\":\"0026.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat with a bench behind you as a depth target. Trains the quads and glutes.\",\"fv\":\"2225\"},{\"id\":\"1316\",\"n\":\"barbell bent arm pullover\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet on the floor.\",\"Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.\",\"Lower the barbell behind your head while keeping your arms slightly bent.\",\"Pause for a moment, then raise the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1316.webp\",\"gif\":\"1316.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, move a barbell in an arc behind your head and back over your chest with soft elbows. It works the lats and chest.\",\"nd\":[\"bench\"],\"fv\":\"11441\"},{\"id\":\"0027\",\"n\":\"barbell bent over row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Bend forward at the hips while keeping your back straight and chest up.\",\"Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0027.webp\",\"gif\":\"0027.mp4\",\"cat\":\"strength\",\"desc\":\"A hip-hinged row pulling the bar to your lower chest. A staple for the upper back and lats.\",\"fv\":\"2242\"},{\"id\":\"2407\",\"n\":\"barbell biceps curl (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.\",\"Place your upper arms against the arm blaster, keeping your elbows close to your torso.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2407.webp\",\"gif\":\"2407.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell curl with an arm blaster. Keeps your elbows still so the biceps do the work.\"},{\"id\":\"0028\",\"n\":\"barbell clean and press\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"shoulders\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and the barbell on the floor in front of you.\",\"Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.\",\"As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.\",\"As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.\",\"From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.\",\"Lower the barbell back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0028.webp\",\"gif\":\"0028.mp4\",\"cat\":\"olympic\",\"desc\":\"Lift the bar from the floor to your shoulders in one movement, then press it overhead. A full-body power exercise.\",\"fv\":\"3648\"},{\"id\":\"0029\",\"n\":\"barbell clean-grip front squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.\",\"Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.\",\"Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0029.webp\",\"gif\":\"0029.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat with the bar racked on the shoulders in a clean grip. Trains the quads and glutes with an upright torso.\"},{\"id\":\"0030\",\"n\":\"barbell close-grip bench press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0030.webp\",\"gif\":\"0030.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with a narrower grip that shifts more of the work to the triceps while still working the chest.\",\"fv\":\"2391\"},{\"id\":\"0031\",\"n\":\"barbell curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.\",\"Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.\",\"Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale as you slowly begin to lower the bar back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0031.webp\",\"gif\":\"0031.mp4\",\"cat\":\"strength\",\"desc\":\"The standard standing barbell curl. A simple and effective way to build the biceps.\",\"fv\":\"3592\"},{\"id\":\"0032\",\"n\":\"barbell deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and the barbell on the ground in front of you.\",\"Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.\",\"As you stand up straight, squeeze your glutes and keep your core engaged.\",\"Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0032.webp\",\"gif\":\"0032.mp4\",\"cat\":\"strength\",\"desc\":\"Lift the bar from the floor by driving the hips and legs until you stand tall. Trains the glutes, hamstrings and back.\",\"fv\":\"2214\"},{\"id\":\"0033\",\"n\":\"barbell decline bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your feet secured and your head lower than your hips.\",\"Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0033.webp\",\"gif\":\"0033.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press performed on a decline bench, which emphasises the lower chest.\",\"fv\":\"2453\"},{\"id\":\"0034\",\"n\":\"barbell decline bent arm pullover\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Lie down on a decline bench with your head lower than your hips and your feet secured.\",\"Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.\",\"Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.\",\"Pause for a moment, then raise the barbell back to the starting position by contracting your lats.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0034.webp\",\"gif\":\"0034.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover on a decline bench with slightly bent arms, stretching and working the lats.\"},{\"id\":\"0035\",\"n\":\"barbell decline close grip to skull press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.\",\"Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.\",\"Pause for a moment, then extend your arms to press the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0035.webp\",\"gif\":\"0035.mp4\",\"cat\":\"strength\",\"desc\":\"A decline skull crusher that lowers the bar toward the forehead and presses it back up. Targets the triceps.\",\"fv\":\"3026\"},{\"id\":\"1255\",\"n\":\"barbell decline pullover\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie down on a decline bench with your head lower than your hips and your feet secured.\",\"Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.\",\"Extend your arms above your chest, keeping a slight bend in your elbows.\",\"Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.\",\"Pause for a moment, then return the barbell to the starting position by reversing the motion.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1255.webp\",\"gif\":\"1255.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover on a decline bench with a barbell. It trains the chest and lats.\"},{\"id\":\"0036\",\"n\":\"barbell decline wide-grip press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your feet secured and your head lower than your hips.\",\"Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.\",\"Lower the barbell to your chest, keeping your elbows out to the sides.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0036.webp\",\"gif\":\"0036.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip decline bench press that spreads the load across the lower chest.\"},{\"id\":\"0037\",\"n\":\"barbell decline wide-grip pullover\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Lie on a decline bench with your head lower than your hips and your feet secured.\",\"Hold a barbell with a wide grip and extend your arms straight above your chest.\",\"Lower the barbell behind your head in a controlled manner, keeping your arms straight.\",\"Pause for a moment, then raise the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0037.webp\",\"gif\":\"0037.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip pullover on a decline bench. Stretches and works the lats and chest.\"},{\"id\":\"0038\",\"n\":\"barbell drag curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.\",\"Let the barbell hang at arm's length in front of your thighs.\",\"Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0038.webp\",\"gif\":\"0038.mp4\",\"cat\":\"strength\",\"desc\":\"A curl where the bar is dragged up along the torso with the elbows moving back. Targets the biceps.\",\"fv\":\"3027\"},{\"id\":\"1370\",\"n\":\"barbell floor calf raise\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Place a barbell on the floor in front of you.\",\"Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.\",\"Hold onto a stable object for balance if needed.\",\"Raise your heels as high as possible, using your calves to lift your body.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1370.webp\",\"gif\":\"1370.mp4\",\"cat\":\"strength\",\"desc\":\"Stand with a barbell across your back and raise onto your toes from the floor. It works the calves, with the full range limited to flat ground.\"},{\"id\":\"0039\",\"n\":\"barbell front chest squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.\",\"Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0039.webp\",\"gif\":\"0039.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat holding the bar at the front of the chest. Trains the quads, glutes and core.\"},{\"id\":\"0041\",\"n\":\"barbell front raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.\",\"Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0041.webp\",\"gif\":\"0041.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm raise of the bar in front of you to shoulder height. Targets the front delts.\",\"fv\":\"2477\"},{\"id\":\"0040\",\"n\":\"barbell front raise and pullover\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.\",\"Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Next, lower the barbell behind your head, keeping your arms straight.\",\"Pause for a moment at the bottom, then raise the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0040.webp\",\"gif\":\"0040.mp4\",\"cat\":\"strength\",\"desc\":\"Two moves in one: raise the bar in front to shoulder height, then take it back overhead. Hits the shoulders and chest.\"},{\"id\":\"0042\",\"n\":\"barbell front squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.\",\"Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0042.webp\",\"gif\":\"0042.mp4\",\"cat\":\"strength\",\"desc\":\"The barbell front squat with the bar resting on the front of the shoulders. Heavy on the quads and core.\",\"fv\":\"2502\"},{\"id\":\"0043\",\"n\":\"barbell full squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the barbell across your upper back, resting it on your traps or rear delts.\",\"Engage your core and keep your chest up as you begin to lower your body down.\",\"Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.\",\"Lower yourself until your thighs are parallel to the ground or slightly below.\",\"Keep your knees in line with your toes and your weight in your heels.\",\"Drive through your heels to stand back up, extending your hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0043.webp\",\"gif\":\"0043.mp4\",\"cat\":\"strength\",\"desc\":\"A deep back squat with the bar across the upper back. Builds the quads, glutes and overall leg strength.\"},{\"id\":\"1461\",\"n\":\"barbell full squat (back pov)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the barbell across your upper back, resting it on your traps or rear delts.\",\"Engage your core and keep your chest up as you begin to lower your body down.\",\"Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.\",\"Lower your body until your thighs are parallel to the ground or slightly below.\",\"Keep your knees in line with your toes and your weight in your heels.\",\"Drive through your heels to stand back up, extending your hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1461.webp\",\"gif\":\"1461.mp4\",\"cat\":\"strength\",\"desc\":\"A full-depth barbell squat shown from behind. It builds the quads, glutes and core and is a great check of back and knee alignment.\"},{\"id\":\"1462\",\"n\":\"barbell full squat (side pov)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the barbell across your upper back, resting it on your traps or rear delts.\",\"Engage your core and keep your chest up as you begin to lower your body down.\",\"Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.\",\"Lower your body until your thighs are parallel to the ground or slightly below.\",\"Keep your knees in line with your toes and your weight in your heels.\",\"Drive through your heels to stand back up, extending your hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1462.webp\",\"gif\":\"1462.mp4\",\"cat\":\"strength\",\"desc\":\"A full-depth barbell squat shown from the side. It builds the quads, glutes and core and shows your depth and back angle clearly.\"},{\"id\":\"1545\",\"n\":\"barbell full zercher squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and toes slightly turned out.\",\"Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.\",\"Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.\",\"Keep your knees in line with your toes and your weight in your heels.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Drive through your heels to stand back up, squeezing your glutes at the top of the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1545.webp\",\"gif\":\"1545.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with the bar held in the crooks of your elbows at full depth. It hits the quads, glutes and upper back.\"},{\"id\":\"1409\",\"n\":\"barbell glute bridge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.\",\"Place a barbell across your hips, holding it securely with both hands.\",\"Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, squeezing your glutes.\",\"Slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1409.webp\",\"gif\":\"1409.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on your back with a barbell across your hips and lift your hips high. It builds the glutes and the back of the thighs.\"},{\"id\":\"3562\",\"n\":\"barbell glute bridge two legs on bench (male)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.\",\"Place a barbell across your hips, holding it securely with both hands.\",\"Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, squeezing your glutes.\",\"Slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3562.webp\",\"gif\":\"3562.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell glute bridge with your upper back on a bench and a bar across the hips. It builds the glutes and hamstrings.\"},{\"id\":\"0044\",\"n\":\"barbell good morning\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"lower back\",\"sm\":[\"lower back\"],\"st\":[\"Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.\",\"Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.\",\"Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.\",\"Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0044.webp\",\"gif\":\"0044.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge forward at the hips with the bar on your upper back and return by driving the hips forward. Trains the hamstrings and glutes.\",\"fv\":\"2215\"},{\"id\":\"0045\",\"n\":\"barbell guillotine bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.\",\"Pause for a moment when the barbell is just above your neck.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0045.webp\",\"gif\":\"0045.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press where the bar travels down to the neck area. A demanding variation for the chest and shoulders.\"},{\"id\":\"0046\",\"n\":\"barbell hack squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart and your toes slightly turned out.\",\"Hold the barbell behind your legs, resting it on your upper thighs.\",\"Lower your body by bending at the knees and hips, keeping your back straight and your chest up.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0046.webp\",\"gif\":\"0046.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding the bar behind your legs. Puts extra work on the quads and glutes.\",\"fv\":\"2638\"},{\"id\":\"1436\",\"n\":\"barbell high bar squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Place the barbell on your upper back, resting it on your traps.\",\"Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.\",\"Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Drive through your heels to stand back up, extending your hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1436.webp\",\"gif\":\"1436.mp4\",\"cat\":\"strength\",\"desc\":\"The classic back squat with the bar sitting high on the traps and a more upright torso. It is a staple for quad and glute strength.\"},{\"id\":\"0047\",\"n\":\"barbell incline bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie down on the bench with your feet flat on the ground.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0047.webp\",\"gif\":\"0047.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell press on an incline bench, favouring the upper chest and front delts.\",\"fv\":\"2388\"},{\"id\":\"1719\",\"n\":\"barbell incline close grip bench press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie down on the bench with your feet flat on the ground.\",\"Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1719.webp\",\"gif\":\"1719.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip bench press on an incline. It targets the triceps and the upper chest.\",\"fv\":\"2519\"},{\"id\":\"0048\",\"n\":\"barbell incline reverse-grip press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0048.webp\",\"gif\":\"0048.mp4\",\"cat\":\"strength\",\"desc\":\"An incline press with a reverse grip, loading the upper chest and triceps.\"},{\"id\":\"0049\",\"n\":\"barbell incline row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie face down on the bench with your chest against the pad and your feet flat on the ground.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and your core engaged.\",\"Pull the barbell towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0049.webp\",\"gif\":\"0049.mp4\",\"cat\":\"strength\",\"desc\":\"Chest supported on an incline bench, you row the bar toward your chest. Works the upper back with little lower back stress.\",\"fv\":\"2503\"},{\"id\":\"0050\",\"n\":\"barbell incline shoulder raise\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"serratus anterior\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"trapezius\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your back against the pad and feet flat on the ground.\",\"Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell up to shoulder height, keeping your elbows slightly bent.\",\"Slowly raise the barbell overhead, extending your arms fully.\",\"Pause for a moment at the top, then slowly lower the barbell back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0050.webp\",\"gif\":\"0050.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell raise on an incline bench that lifts the bar overhead. Trains the serratus anterior and shoulders.\"},{\"id\":\"0051\",\"n\":\"barbell jefferson squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and toes slightly turned out.\",\"Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.\",\"Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.\",\"Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.\",\"Push through your heels to stand back up to the starting position.\",\"Repeat the movement, alternating your forward and back foot with each repetition.\"],\"img\":\"0051.webp\",\"gif\":\"0051.mp4\",\"cat\":\"strength\",\"desc\":\"A squat straddling the bar, with one foot ahead of the other. Works the glutes, quads and core.\"},{\"id\":\"0052\",\"n\":\"barbell jm bench press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lower the barbell to your chest, keeping your elbows tucked in close to your body.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0052.webp\",\"gif\":\"0052.mp4\",\"cat\":\"strength\",\"desc\":\"A hybrid between a close-grip bench press and a skull crusher. Heavily loads the triceps.\",\"fv\":\"3028\"},{\"id\":\"0053\",\"n\":\"barbell jump squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"Once you reach the bottom of the squat, explode upwards by jumping off the ground.\",\"As you jump, extend your hips, knees, and ankles, pushing through your toes.\",\"Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions.\"],\"img\":\"0053.webp\",\"gif\":\"0053.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat with an explosive jump while holding the bar on the upper back. Builds leg power.\"},{\"id\":\"1410\",\"n\":\"barbell lateral lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a barbell across your upper back.\",\"Take a big step to the side with your right foot, keeping your left foot planted.\",\"Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.\",\"Push off with your right foot and return to the starting position.\",\"Repeat on the other side, stepping with your left foot.\"],\"img\":\"1410.webp\",\"gif\":\"1410.mp4\",\"cat\":\"strength\",\"desc\":\"With a barbell on your upper back, step to the side and sit into a lateral lunge. It works the glutes, inner thighs and quads.\",\"fv\":\"2228\"},{\"id\":\"1435\",\"n\":\"barbell low bar squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and the barbell resting on your upper back.\",\"Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.\",\"Continue lowering until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1435.webp\",\"gif\":\"1435.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with the bar resting low across the rear delts, which leans you forward a bit more. It loads the glutes, hamstrings and lower back heavily.\"},{\"id\":\"0054\",\"n\":\"barbell lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.\",\"Take a step forward with your right foot, keeping your torso upright.\",\"Lower your body by bending your right knee until your thigh is parallel to the ground.\",\"Push through your right heel to return to the starting position.\",\"Repeat with your left leg, alternating legs for the desired number of repetitions.\"],\"img\":\"0054.webp\",\"gif\":\"0054.mp4\",\"cat\":\"strength\",\"desc\":\"A walking-style lunge with the bar on the upper back. Works the glutes and quads, one leg at a time.\",\"fv\":\"2478\"},{\"id\":\"1720\",\"n\":\"barbell lying back of the head tricep extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.\",\"Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1720.webp\",\"gif\":\"1720.mp4\",\"cat\":\"strength\",\"desc\":\"A lying barbell triceps extension that lowers the bar behind your head. It stretches and builds the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"0055\",\"n\":\"barbell lying close-grip press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.\",\"Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.\",\"Slowly lower the barbell towards your chest, keeping your elbows close to your body.\",\"Pause for a moment when the barbell touches your chest, then push it back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0055.webp\",\"gif\":\"0055.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip press from a lying position. Targets the triceps with chest involvement.\",\"nd\":[\"bench\"]},{\"id\":\"0056\",\"n\":\"barbell lying close-grip triceps extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.\",\"Extend your arms fully, lifting the barbell above your chest.\",\"Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.\",\"Pause for a moment at the bottom, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0056.webp\",\"gif\":\"0056.mp4\",\"cat\":\"strength\",\"desc\":\"A lying triceps extension with a close grip, lowering the bar toward the forehead and pressing it back.\",\"nd\":[\"bench\"],\"fv\":\"2607\"},{\"id\":\"0057\",\"n\":\"barbell lying extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.\",\"Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0057.webp\",\"gif\":\"0057.mp4\",\"cat\":\"strength\",\"desc\":\"Lie back and bend only at the elbows to lower the bar, then extend again. A direct triceps builder.\",\"nd\":[\"bench\"]},{\"id\":\"0058\",\"n\":\"barbell lying lifting (on hip)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Lie flat on your back on a bench with your feet flat on the ground and your knees bent.\",\"Hold the barbell with an overhand grip and position it on your hips.\",\"Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0058.webp\",\"gif\":\"0058.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust style lift with the bar resting on your hips. Strong work for the glutes.\",\"nd\":[\"bench\"]},{\"id\":\"0059\",\"n\":\"barbell lying preacher curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0059.webp\",\"gif\":\"0059.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl performed while lying on the bench, isolating the biceps with no body swing.\"},{\"id\":\"0061\",\"n\":\"barbell lying triceps extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.\",\"Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.\",\"Pause for a moment at the bottom, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0061.webp\",\"gif\":\"0061.mp4\",\"cat\":\"strength\",\"desc\":\"A lying triceps extension with the bar, bending only at the elbows. A staple triceps exercise.\",\"nd\":[\"bench\"],\"fv\":\"2692\"},{\"id\":\"0060\",\"n\":\"barbell lying triceps extension skull crusher\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.\",\"Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.\",\"Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0060.webp\",\"gif\":\"0060.mp4\",\"cat\":\"strength\",\"desc\":\"The classic skull crusher: lower the bar to the forehead and extend the arms. Isolates the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"0063\",\"n\":\"barbell narrow stance squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and toes pointing slightly outward.\",\"Hold the barbell across your upper back, resting it on your traps or rear delts.\",\"Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.\",\"Continue lowering until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0063.webp\",\"gif\":\"0063.mp4\",\"cat\":\"strength\",\"desc\":\"A back squat with a narrower stance, shifting more work to the quads.\",\"fv\":\"2389\"},{\"id\":\"0064\",\"n\":\"barbell one arm bent over row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.\",\"Bend forward at the hips, keeping your back straight and your head in a neutral position.\",\"Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\",\"Lower the barbell back down to the starting position in a controlled manner.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0064.webp\",\"gif\":\"0064.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row holding the bar in one hand at a time. Trains the upper back and lats.\"},{\"id\":\"0065\",\"n\":\"barbell one arm floor press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on your back on the floor with your knees bent and feet flat on the ground.\",\"Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.\",\"Slowly lower the barbell towards your chest, keeping your elbow close to your body.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0065.webp\",\"gif\":\"0065.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press with one hand on the bar. Limits range of motion to be gentle on the shoulder and trains the triceps.\"},{\"id\":\"0066\",\"n\":\"barbell one arm side deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.\",\"Keep your back straight and your core engaged.\",\"Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.\",\"Lower the barbell as far as you can while maintaining good form.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0066.webp\",\"gif\":\"0066.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift variation where the bar is lowered along one side of the body. Works the glutes and hips.\"},{\"id\":\"0067\",\"n\":\"barbell one arm snatch\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"forearms\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing slightly outwards.\",\"Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.\",\"Explosively extend your hips, knees, and ankles, driving the barbell upwards.\",\"As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.\",\"Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.\",\"Lower the barbell back down to the starting position in a controlled manner.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0067.webp\",\"gif\":\"0067.mp4\",\"cat\":\"olympic\",\"desc\":\"A one-handed snatch that takes the bar from the floor to overhead in one fast pull. Needs power and coordination.\"},{\"id\":\"0068\",\"n\":\"barbell one leg squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell across your upper back.\",\"Lift one foot off the ground and extend it forward, keeping it parallel to the ground.\",\"Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.\",\"Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"0068.webp\",\"gif\":\"0068.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat with the bar on your back. Challenges the quads, glutes and balance.\"},{\"id\":\"0069\",\"n\":\"barbell overhead squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and toes slightly turned out.\",\"Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.\",\"Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0069.webp\",\"gif\":\"0069.mp4\",\"cat\":\"olympic\",\"desc\":\"A squat with the bar held locked out overhead. Builds mobility, stability and leg strength.\"},{\"id\":\"1411\",\"n\":\"barbell palms down wrist curl over a bench\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.\",\"Hold a barbell with an overhand grip, hands shoulder-width apart.\",\"Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.\",\"Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1411.webp\",\"gif\":\"1411.mp4\",\"cat\":\"strength\",\"desc\":\"Sit with your forearms on your thighs or a bench, palms down, and curl a barbell up with your wrists. It strengthens the back of the forearms.\",\"fv\":\"2681\"},{\"id\":\"1412\",\"n\":\"barbell palms up wrist curl over a bench\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.\",\"Rest your forearms on the bench, allowing your wrists to hang off the edge.\",\"Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.\",\"Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1412.webp\",\"gif\":\"1412.mp4\",\"cat\":\"strength\",\"desc\":\"Sit with your forearms on a bench, palms up, and curl a barbell with your wrists. It strengthens the front of the forearms and grip.\",\"fv\":\"2682\"},{\"id\":\"3017\",\"n\":\"barbell pendlay row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Bend forward at the hips, keeping your back straight and your chest up.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.\",\"Lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3017.webp\",\"gif\":\"3017.mp4\",\"cat\":\"strength\",\"desc\":\"A pendlay row from the floor, pulling the barbell to your upper abdomen. Builds the upper back and lats.\"},{\"id\":\"1751\",\"n\":\"barbell pin presses\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Set up a barbell on a power rack at chest height.\",\"Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.\",\"Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.\",\"Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1751.webp\",\"gif\":\"1751.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell press from pins set in a rack, starting from a dead stop. Builds pressing strength through the triceps and chest.\"},{\"id\":\"0070\",\"n\":\"barbell preacher curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.\",\"Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.\",\"Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0070.webp\",\"gif\":\"0070.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with the upper arms resting on a preacher pad, which keeps the focus on the biceps.\",\"fv\":\"2497\"},{\"id\":\"0071\",\"n\":\"barbell press sit-up\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Lie flat on your back on a mat with your knees bent and feet flat on the ground.\",\"Hold the barbell with an overhand grip, resting it on your chest.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0071.webp\",\"gif\":\"0071.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted sit-up holding the bar on your chest. Strengthens the abs.\"},{\"id\":\"0072\",\"n\":\"barbell prone incline curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie face down on the bench with your chest and stomach resting against it.\",\"Hold a barbell with an underhand grip, shoulder-width apart.\",\"Extend your arms fully, allowing the barbell to hang down towards the floor.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0072.webp\",\"gif\":\"0072.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down on an incline bench, you curl the bar up. Works the biceps with a strict stretch at the bottom.\",\"fv\":\"2506\"},{\"id\":\"0073\",\"n\":\"barbell pullover\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet on the floor.\",\"Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.\",\"Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.\",\"Pause for a moment, then raise the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0073.webp\",\"gif\":\"0073.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you lower the bar behind your head with straight arms and bring it back over the chest. Works the lats and chest.\",\"nd\":[\"bench\"]},{\"id\":\"0022\",\"n\":\"barbell pullover to press\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet on the ground.\",\"Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.\",\"Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.\",\"Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0022.webp\",\"gif\":\"0022.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you lower a barbell overhead in an arc and then press it back up. Works the lats, chest and triceps.\",\"nd\":[\"bench\"]},{\"id\":\"0074\",\"n\":\"barbell rack pull\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Set up a barbell on a rack at knee height.\",\"Stand with your feet shoulder-width apart, toes pointing slightly outwards.\",\"Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.\",\"Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.\",\"Lower the barbell back down to the starting position by bending at the hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0074.webp\",\"gif\":\"0074.mp4\",\"cat\":\"strength\",\"desc\":\"A partial deadlift from a rack at knee height. Overloads the upper back, glutes and hips.\"},{\"id\":\"0075\",\"n\":\"barbell rear delt raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0075.webp\",\"gif\":\"0075.mp4\",\"cat\":\"strength\",\"desc\":\"Bent over, you raise the bar with straight arms to shoulder height. Targets the rear delts.\",\"fv\":\"2637\"},{\"id\":\"0076\",\"n\":\"barbell rear delt row\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Bend forward at the hips, keeping your back straight and chest up.\",\"Pull the barbell towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0076.webp\",\"gif\":\"0076.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip bent-over row that emphasises the rear delts and upper back.\"},{\"id\":\"0078\",\"n\":\"barbell rear lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.\",\"Take a step backward with your right foot, landing on the ball of your foot.\",\"Bend both knees to lower your body until your left thigh is parallel to the ground.\",\"Push through your left heel to return to the starting position.\",\"Repeat with the other leg.\"],\"img\":\"0078.webp\",\"gif\":\"0078.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge with the bar across the back. Easy on the knees and strong for the glutes.\",\"fv\":\"2226\"},{\"id\":\"0077\",\"n\":\"barbell rear lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell across your upper back.\",\"Take a step backward with your right foot, landing on the ball of your foot.\",\"Bend both knees to lower your body until your left thigh is parallel to the ground.\",\"Push through your left heel to return to the starting position.\",\"Repeat with the other leg.\"],\"img\":\"0077.webp\",\"gif\":\"0077.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge with the bar on your back, stepping back and returning to standing. Works the glutes and quads.\"},{\"id\":\"0079\",\"n\":\"barbell revers wrist curl v. 2\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and your knees bent.\",\"Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.\",\"Rest your forearms on your thighs, allowing your wrists to hang off the edge.\",\"Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.\",\"Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0079.webp\",\"gif\":\"0079.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse wrist curl with the forearms resting on the thighs. Builds the muscles on top of the forearms.\"},{\"id\":\"2187\",\"n\":\"barbell reverse close-grip bench press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with a reverse grip, hands shoulder-width apart.\",\"Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.\",\"Slowly lower the barbell down towards your chest, keeping your elbows close to your body.\",\"Pause for a moment when the barbell is just above your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2187.webp\",\"gif\":\"2187.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip bench press using a reverse (underhand) grip. Emphasises the triceps and upper chest.\"},{\"id\":\"0080\",\"n\":\"barbell reverse curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.\",\"Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.\",\"Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0080.webp\",\"gif\":\"0080.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with an overhand grip. Trains the biceps, brachialis and forearms.\",\"fv\":\"2479\"},{\"id\":\"0118\",\"n\":\"barbell reverse grip bent over row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.\",\"Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.\",\"Pull the barbell towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0118.webp\",\"gif\":\"0118.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with an underhand grip. Targets the upper back and biceps.\",\"fv\":\"2467\"},{\"id\":\"1256\",\"n\":\"barbell reverse grip decline bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your feet secured and your head lower than your hips.\",\"Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1256.webp\",\"gif\":\"1256.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse-grip bench press on a decline bench. It trains the lower chest and triceps.\"},{\"id\":\"1257\",\"n\":\"barbell reverse grip incline bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie down on the bench with your feet flat on the ground.\",\"Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1257.webp\",\"gif\":\"1257.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse-grip bench press on an incline bench. It trains the upper chest and triceps.\"},{\"id\":\"1317\",\"n\":\"barbell reverse grip incline bench row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench facing the backrest with your chest against it.\",\"Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.\",\"Keep your back straight and core engaged.\",\"Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement.\",\"Slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1317.webp\",\"gif\":\"1317.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell row with an underhand grip, done chest down on an incline bench. The support removes momentum and targets the upper back and biceps.\"},{\"id\":\"1721\",\"n\":\"barbell reverse grip skullcrusher\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.\",\"Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.\",\"Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.\",\"Pause for a moment at the bottom, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1721.webp\",\"gif\":\"1721.mp4\",\"cat\":\"strength\",\"desc\":\"A skullcrusher with a reverse grip. It targets the triceps with a different wrist angle.\",\"nd\":[\"bench\"]},{\"id\":\"0081\",\"n\":\"barbell reverse preacher curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.\",\"Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.\",\"Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0081.webp\",\"gif\":\"0081.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with an overhand grip, hitting the brachialis and forearms along with the biceps.\",\"fv\":\"2508\"},{\"id\":\"0082\",\"n\":\"barbell reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.\",\"Rest your forearms on your thighs, allowing your wrists to hang off the edge.\",\"Slowly curl your wrists upward, bringing the barbell towards your body.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0082.webp\",\"gif\":\"0082.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with an overhand grip, which trains the extensors on the top of the forearm.\",\"fv\":\"3029\"},{\"id\":\"0084\",\"n\":\"barbell rollerout\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\"],\"st\":[\"Kneel on the floor and hold a barbell with both hands, shoulder-width apart.\",\"Roll the barbell forward, extending your arms and keeping your core engaged.\",\"Continue rolling forward until your body is fully extended and your arms are overhead.\",\"Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0084.webp\",\"gif\":\"0084.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling, you roll the barbell forward and pull it back in. A demanding exercise for the abs.\",\"fv\":\"2699\"},{\"id\":\"0083\",\"n\":\"barbell rollerout from bench\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Start by kneeling on the floor with a barbell placed on a bench in front of you.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.\",\"Continue rolling the barbell forward until your body is fully extended and your arms are overhead.\",\"Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0083.webp\",\"gif\":\"0083.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling at a bench, you roll the barbell out and back. A tough core exercise for the abs.\"},{\"id\":\"0085\",\"n\":\"barbell romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and your toes pointing forward.\",\"Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Bend at the hips, keeping your back straight and your knees slightly bent.\",\"Lower the barbell towards the ground, keeping it close to your body.\",\"Feel the stretch in your hamstrings as you lower the barbell.\",\"Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.\",\"Squeeze your glutes at the top of the movement.\",\"Lower the barbell back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0085.webp\",\"gif\":\"0085.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge at the hips with the bar close to your legs to feel a hamstring stretch, then stand tall. Trains the hamstrings and glutes.\",\"fv\":\"2213\"},{\"id\":\"0086\",\"n\":\"barbell seated behind head military press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and bring it down to shoulder level, behind your head.\",\"Press the barbell upward until your arms are fully extended.\",\"Lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0086.webp\",\"gif\":\"0086.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with the bar lowered behind your head. Works the shoulders and triceps.\",\"fv\":\"2603\"},{\"id\":\"0087\",\"n\":\"barbell seated bradford rocky press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.\",\"Press the barbell overhead, fully extending your arms.\",\"Lower the barbell back to shoulder height and repeat for the desired number of repetitions.\"],\"img\":\"0087.webp\",\"gif\":\"0087.mp4\",\"cat\":\"strength\",\"desc\":\"A seated press in which the bar moves between the front of the shoulders and just above the head, never fully locking out.\"},{\"id\":\"0088\",\"n\":\"barbell seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.\",\"Place the balls of your feet on a raised platform, such as a block or step.\",\"Position the barbell across your thighs and hold it securely with your hands.\",\"Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0088.webp\",\"gif\":\"0088.mp4\",\"cat\":\"strength\",\"desc\":\"Seated calf raise with the bar resting on your thighs. Isolates the soleus and calves.\",\"fv\":\"2676\"},{\"id\":\"1371\",\"n\":\"barbell seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.\",\"Place the balls of your feet on a raised platform, such as a block or step.\",\"Lower your heels as far as possible, feeling a stretch in your calves.\",\"Raise your heels as high as possible, contracting your calves.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1371.webp\",\"gif\":\"1371.mp4\",\"cat\":\"strength\",\"desc\":\"Seated calf raise with a barbell resting on your thighs. The bent knee shifts the work to the soleus muscle under the calf.\"},{\"id\":\"1718\",\"n\":\"barbell seated close grip behind neck triceps extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold the barbell with a close grip behind your neck, palms facing forward.\",\"Keep your elbows close to your head and slowly lower the barbell towards the back of your head.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1718.webp\",\"gif\":\"1718.mp4\",\"cat\":\"strength\",\"desc\":\"A seated barbell triceps extension behind the neck with a close grip. It isolates the triceps.\"},{\"id\":\"0089\",\"n\":\"barbell seated close-grip concentration curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.\",\"Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.\",\"Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.\",\"Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0089.webp\",\"gif\":\"0089.mp4\",\"cat\":\"strength\",\"desc\":\"A seated close-grip curl with the arms braced on the thighs. Isolates the biceps.\"},{\"id\":\"0090\",\"n\":\"barbell seated good morning\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.\",\"Keep your back straight and your chest up.\",\"Slowly hinge forward at the hips, lowering your torso towards the ground.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0090.webp\",\"gif\":\"0090.mp4\",\"cat\":\"strength\",\"desc\":\"A seated good morning with the bar on your back. Trains the lower back and glutes.\",\"fv\":\"2602\"},{\"id\":\"0091\",\"n\":\"barbell seated overhead press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.\",\"Press the barbell overhead by extending your arms fully.\",\"Pause for a moment at the top, then slowly lower the barbell back to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0091.webp\",\"gif\":\"0091.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with the barbell. Builds the shoulders and triceps.\",\"fv\":\"2604\"},{\"id\":\"0092\",\"n\":\"barbell seated overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.\",\"Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.\",\"Pause for a moment, then extend your arms to raise the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0092.webp\",\"gif\":\"0092.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension holding the bar. Isolates the triceps.\",\"fv\":\"2606\"},{\"id\":\"0094\",\"n\":\"barbell seated twist\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on a flat bench with your feet flat on the ground and your knees bent.\",\"Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.\",\"Engage your core and slowly twist your torso to one side, keeping your back straight.\",\"Pause for a moment at the end of the twist, then slowly rotate back to the starting position.\",\"Repeat the twist to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0094.webp\",\"gif\":\"0094.mp4\",\"cat\":\"strength\",\"desc\":\"A seated torso twist with the bar on your back. Works the obliques and abs.\"},{\"id\":\"0095\",\"n\":\"barbell shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.\",\"Keep your arms straight and your back straight throughout the exercise.\",\"Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.\",\"Hold for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0095.webp\",\"gif\":\"0095.mp4\",\"cat\":\"strength\",\"desc\":\"Shrug the shoulders toward your ears while holding the bar. Builds the upper traps.\",\"fv\":\"2480\"},{\"id\":\"0096\",\"n\":\"barbell side bent v. 2\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.\",\"Keep your back straight and core engaged throughout the exercise.\",\"Slowly bend your torso to the right side, lowering the barbell towards your right knee.\",\"Pause for a moment, then return to the starting position.\",\"Repeat the movement on the left side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0096.webp\",\"gif\":\"0096.mp4\",\"cat\":\"strength\",\"desc\":\"A side bend with the bar on your shoulders. Works the obliques.\"},{\"id\":\"0098\",\"n\":\"barbell side split squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.\",\"Hold a barbell across your upper back, resting it on your traps.\",\"Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.\",\"As you lower, push your knees out to the sides and keep your weight on your heels.\",\"Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0098.webp\",\"gif\":\"0098.mp4\",\"cat\":\"strength\",\"desc\":\"A side-to-side lunge with the bar across the back. Strengthens the quads and adductors.\"},{\"id\":\"0097\",\"n\":\"barbell side split squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.\",\"Hold a barbell across your upper back, resting it on your shoulders.\",\"Take a big step to the side with your right foot, keeping your left foot planted.\",\"Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.\",\"Push through your right heel to return to the starting position.\",\"Repeat on the other side, stepping out with your left foot.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0097.webp\",\"gif\":\"0097.mp4\",\"cat\":\"strength\",\"desc\":\"A side split squat with the bar on your back, sinking toward one leg. Works the quads and adductors.\"},{\"id\":\"1756\",\"n\":\"barbell single leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.\",\"Shift your weight onto your left foot and lift your right foot slightly off the ground.\",\"Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.\",\"Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.\",\"Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1756.webp\",\"gif\":\"1756.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip hinge holding a barbell. Trains the glutes and hamstrings while challenging balance and core stability.\",\"fv\":\"2634\"},{\"id\":\"0099\",\"n\":\"barbell single leg split squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a barbell across your upper back.\",\"Take a large step forward with one leg, keeping your torso upright.\",\"Lower your body by bending your front knee and hip, while keeping your back leg straight.\",\"Continue lowering until your front thigh is parallel to the ground.\",\"Pause for a moment, then push through your front heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0099.webp\",\"gif\":\"0099.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with the rear foot raised and a bar on your back. Strong work for the quads and glutes.\",\"fv\":\"2227\"},{\"id\":\"2799\",\"n\":\"barbell sitted alternate leg raise\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on a bench with your back straight and hold a barbell across your thighs.\",\"Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.\",\"Lower the raised leg back down and repeat with the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"2799.webp\",\"gif\":\"2799.mp4\",\"cat\":\"strength\",\"desc\":\"A seated alternate leg raise holding a barbell across the thighs. Works the abs and hip flexors.\",\"fv\":\"2800\"},{\"id\":\"2800\",\"n\":\"barbell sitted alternate leg raise (female)\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Sit on a bench with your back straight and hold a barbell across your thighs.\",\"Place your hands on the sides of the bench for support.\",\"Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.\",\"Lower the leg back down and repeat with the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"2800.webp\",\"gif\":\"2800.mp4\",\"cat\":\"strength\",\"desc\":\"A seated alternate leg raise with a barbell across the thighs and hands on the bench. Works the abs and hip flexors.\",\"mv\":\"2799\"},{\"id\":\"0100\",\"n\":\"barbell skier\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\",\"Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.\",\"As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0100.webp\",\"gif\":\"0100.mp4\",\"cat\":\"strength\",\"desc\":\"A shoulder exercise in which you swing the barbell through a skiing-like pattern. Trains the delts and core.\",\"fv\":\"2817\"},{\"id\":\"0101\",\"n\":\"barbell speed squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the barbell across your upper back, resting it on your traps or rear delts.\",\"Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Drive through your heels to stand back up, squeezing your glutes at the top.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0101.webp\",\"gif\":\"0101.mp4\",\"cat\":\"strength\",\"desc\":\"A fast, light back squat. Builds explosive leg power and speed out of the hole.\"},{\"id\":\"2810\",\"n\":\"barbell split squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.\",\"Take a large step forward with your right foot, keeping your torso upright.\",\"Lower your body by bending your knees and hips until your right thigh is parallel to the ground.\",\"Pause for a moment, then push through your right heel to return to the starting position.\",\"Repeat with your left leg forward for the desired number of repetitions.\"],\"img\":\"2810.webp\",\"gif\":\"2810.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell split squat with a long stance. Builds the quads and glutes one leg at a time.\",\"mv\":\"2809\"},{\"id\":\"0102\",\"n\":\"barbell squat (on knees)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.\",\"Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.\",\"Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0102.webp\",\"gif\":\"0102.mp4\",\"cat\":\"strength\",\"desc\":\"A squat performed from a kneeling position with the bar on the back. Trains the quads and glutes.\"},{\"id\":\"2798\",\"n\":\"barbell squat jump step rear lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"Explode upwards, jumping off the ground as high as you can.\",\"Land softly on your feet and immediately step back with one leg into a reverse lunge.\",\"Lower your body down until your front thigh is parallel to the ground, keeping your back straight.\",\"Push through your front heel to return to the starting position.\",\"Repeat the jump and lunge sequence on the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"2798.webp\",\"gif\":\"2798.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A barbell squat jump followed by a rear lunge. Builds explosive leg power.\",\"mv\":\"2797\"},{\"id\":\"0103\",\"n\":\"barbell standing ab rollerout\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lower back\"],\"st\":[\"Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.\",\"Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.\",\"Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.\",\"Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0103.webp\",\"gif\":\"0103.mp4\",\"cat\":\"strength\",\"desc\":\"A standing roll-out with the barbell. Requires strong abs and a firm back.\",\"fv\":\"2826\"},{\"id\":\"0104\",\"n\":\"barbell standing back wrist curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.\",\"Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.\",\"Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.\",\"Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0104.webp\",\"gif\":\"0104.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with the bar held behind the back, building the grip and forearms.\",\"fv\":\"2481\"},{\"id\":\"0105\",\"n\":\"barbell standing bradford press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.\",\"Press the barbell overhead, fully extending your arms.\",\"Lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0105.webp\",\"gif\":\"0105.mp4\",\"cat\":\"strength\",\"desc\":\"A standing Bradford press, lifting the bar from the front of the shoulders to behind the head and back. Works the delts.\"},{\"id\":\"1372\",\"n\":\"barbell standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart and place a barbell across your upper back.\",\"Raise your heels off the ground as high as possible, using only your toes.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1372.webp\",\"gif\":\"1372.mp4\",\"cat\":\"strength\",\"desc\":\"Stand with a barbell on your upper back and rise onto your toes. It builds the calves and ankle strength.\",\"fv\":\"2668\"},{\"id\":\"0106\",\"n\":\"barbell standing close grip curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.\",\"Keep your elbows close to your torso and your upper arms stationary throughout the movement.\",\"Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale as you slowly begin to bring the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0106.webp\",\"gif\":\"0106.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with a narrow grip. Builds the biceps.\",\"fv\":\"2693\"},{\"id\":\"1456\",\"n\":\"barbell standing close grip military press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.\",\"Lift the barbell to shoulder height, keeping your elbows close to your body.\",\"Press the barbell overhead, extending your arms fully.\",\"Lower the barbell back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1456.webp\",\"gif\":\"1456.mp4\",\"cat\":\"strength\",\"desc\":\"A standing barbell overhead press with a narrow grip. It hits the front delts and triceps and asks your core to keep you steady.\",\"fv\":\"3031\"},{\"id\":\"2414\",\"n\":\"barbell standing concentration curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.\",\"Rest your opposite hand on your thigh for support.\",\"Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the weight back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"2414.webp\",\"gif\":\"2414.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm barbell curl while standing, with the other hand resting on your thigh. Isolates the biceps.\"},{\"id\":\"0107\",\"n\":\"barbell standing front raise over head\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.\",\"Keep your back straight and engage your core.\",\"Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.\",\"Continue lifting until the barbell is slightly above shoulder level.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0107.webp\",\"gif\":\"0107.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise where the bar travels past shoulder height up to overhead. Targets the front delts.\",\"fv\":\"2688\"},{\"id\":\"0108\",\"n\":\"barbell standing leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart and place a barbell across your upper back.\",\"Raise your heels off the ground as high as possible, using your calves.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0108.webp\",\"gif\":\"0108.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise with the barbell on the shoulders. Builds the calves.\"},{\"id\":\"0109\",\"n\":\"barbell standing overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.\",\"Raise the barbell overhead, fully extending your arms.\",\"Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then raise the barbell back to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0109.webp\",\"gif\":\"0109.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead triceps extension with the barbell. Isolates the triceps.\",\"fv\":\"2605\"},{\"id\":\"0110\",\"n\":\"barbell standing reverse grip curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.\",\"Keep your elbows close to your torso and your upper arms stationary.\",\"Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0110.webp\",\"gif\":\"0110.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with an overhand grip. Trains the biceps, brachialis and forearms.\"},{\"id\":\"0111\",\"n\":\"barbell standing rocking leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell across your upper back.\",\"Raise your heels off the ground as high as possible, balancing on the balls of your feet.\",\"Slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0111.webp\",\"gif\":\"0111.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise in a rocking motion, loading the calf muscles.\"},{\"id\":\"0112\",\"n\":\"barbell standing twist\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.\",\"Engage your core and keep your back straight throughout the exercise.\",\"Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.\",\"Pause for a moment at the end of the twist, then slowly return to the starting position.\",\"Repeat the twist to the left side.\",\"Continue alternating twists for the desired number of repetitions.\"],\"img\":\"0112.webp\",\"gif\":\"0112.mp4\",\"cat\":\"strength\",\"desc\":\"A standing torso twist with the bar on your shoulders. Works the obliques.\",\"fv\":\"2320\"},{\"id\":\"1629\",\"n\":\"barbell standing wide grip biceps curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.\",\"Keep your back straight and your elbows close to your torso.\",\"Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the barbell back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1629.webp\",\"gif\":\"1629.mp4\",\"cat\":\"strength\",\"desc\":\"A standing barbell curl with a wide grip. It puts more load on the inner biceps.\"},{\"id\":\"1457\",\"n\":\"barbell standing wide military press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.\",\"Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.\",\"Press the barbell overhead, extending your arms fully.\",\"Lower the barbell back to shoulder height and repeat for the desired number of repetitions.\"],\"img\":\"1457.webp\",\"gif\":\"1457.mp4\",\"cat\":\"strength\",\"desc\":\"A standing barbell overhead press with a wide grip, which shifts more work to the shoulders. Keep your ribs down and your core tight.\",\"fv\":\"3032\"},{\"id\":\"0113\",\"n\":\"barbell standing wide-grip curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.\",\"Let the barbell hang at arm's length in front of your thighs, with your palms facing away from your body.\",\"Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.\",\"Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0113.webp\",\"gif\":\"0113.mp4\",\"cat\":\"strength\",\"desc\":\"A standing wide-grip curl. Emphasises the inner biceps.\"},{\"id\":\"0114\",\"n\":\"barbell step-up\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in front of a bench or step with a barbell resting on your upper back.\",\"Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.\",\"Push through your heel and step up onto the bench or step, fully extending your hip and knee.\",\"Pause briefly at the top, then lower yourself back down to the starting position.\",\"Repeat with the opposite leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"0114.webp\",\"gif\":\"0114.mp4\",\"cat\":\"strength\",\"desc\":\"Step up onto a box with the bar on your back. Works the glutes and quads, one leg at a time.\",\"fv\":\"2501\"},{\"id\":\"0115\",\"n\":\"barbell stiff leg good morning\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Hold the barbell across your upper back, resting it on your traps.\",\"Keeping your back straight, hinge forward at the hips, pushing your glutes back.\",\"Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.\",\"Engage your glutes and hamstrings to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0115.webp\",\"gif\":\"0115.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-leg good morning with the bar on the upper back. Trains the glutes, hamstrings and lower back.\"},{\"id\":\"0116\",\"n\":\"barbell straight leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and your toes pointing forward.\",\"Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.\",\"Lower the barbell until you feel a stretch in your hamstrings.\",\"Engage your hamstrings and glutes to lift the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0116.webp\",\"gif\":\"0116.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with nearly straight legs, which targets the hamstrings.\",\"fv\":\"3594\"},{\"id\":\"0117\",\"n\":\"barbell sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointing outwards.\",\"Place a barbell on the ground in front of you, centered between your feet.\",\"Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.\",\"Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.\",\"As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0117.webp\",\"gif\":\"0117.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a wide stance and narrow grip. Works the glutes, hamstrings and inner thighs.\",\"fv\":\"2517\"},{\"id\":\"3305\",\"n\":\"barbell thruster\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.\",\"Lower into a squat position by bending your knees and pushing your hips back.\",\"As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.\",\"Lower the barbell back to shoulder height as you lower back into the squat position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3305.webp\",\"gif\":\"3305.mp4\",\"cat\":\"olympic\",\"desc\":\"A front squat followed by an overhead press in one fluid movement with a barbell. It trains the legs, shoulders and heart rate.\"},{\"id\":\"0120\",\"n\":\"barbell upright row\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Let the barbell hang in front of your thighs, arms fully extended.\",\"Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0120.webp\",\"gif\":\"0120.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row with the barbell pulled toward the chin. Works the delts and traps.\",\"fv\":\"2229\"},{\"id\":\"0119\",\"n\":\"barbell upright row v. 2\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Let the barbell hang in front of your thighs, arms fully extended.\",\"Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0119.webp\",\"gif\":\"0119.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row with the barbell pulled toward the chin. Works the delts and traps.\"},{\"id\":\"0121\",\"n\":\"barbell upright row v. 3\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Let the barbell hang in front of your thighs, arms fully extended.\",\"Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0121.webp\",\"gif\":\"0121.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row with the barbell pulled toward the chin. Works the delts and traps.\"},{\"id\":\"0122\",\"n\":\"barbell wide bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.\",\"Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.\",\"Pause for a moment when the barbell touches your chest, then push it back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0122.webp\",\"gif\":\"0122.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with a wide grip. Emphasises the chest.\",\"fv\":\"7069\"},{\"id\":\"1258\",\"n\":\"barbell wide reverse grip bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.\",\"Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.\",\"Pause for a moment when the barbell touches your chest, then push it back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1258.webp\",\"gif\":\"1258.mp4\",\"cat\":\"strength\",\"desc\":\"A wide reverse-grip bench press. It trains the chest and triceps.\"},{\"id\":\"0124\",\"n\":\"barbell wide squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.\",\"Hold the barbell across your upper back, resting it on your traps or rear delts.\",\"Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0124.webp\",\"gif\":\"0124.mp4\",\"cat\":\"strength\",\"desc\":\"A back squat with a wide stance. Works the quads, glutes and adductors.\",\"fv\":\"2518\"},{\"id\":\"0123\",\"n\":\"barbell wide-grip upright row\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.\",\"Let the barbell hang in front of your thighs, arms fully extended.\",\"Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0123.webp\",\"gif\":\"0123.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip upright row, favouring the side delts and traps.\",\"fv\":\"3595\"},{\"id\":\"0126\",\"n\":\"barbell wrist curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.\",\"Allow the barbell to roll down to your fingertips, keeping your wrists straight.\",\"Slowly curl the barbell up towards your forearms by flexing your wrists.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0126.webp\",\"gif\":\"0126.mp4\",\"cat\":\"strength\",\"desc\":\"A seated wrist curl with palms up. Builds the forearm flexors.\",\"fv\":\"3033\"},{\"id\":\"0125\",\"n\":\"barbell wrist curl v. 2\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and your knees bent.\",\"Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Rest your forearms on your thighs, allowing your wrists to hang off the edge.\",\"Slowly curl your wrists upward, bringing the barbell towards your forearms.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0125.webp\",\"gif\":\"0125.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with palms up, resting the forearms on a bench. Builds the forearm flexors.\",\"fv\":\"11881\"},{\"id\":\"0127\",\"n\":\"barbell zercher squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and toes slightly turned out.\",\"Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.\",\"Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.\",\"Keep your knees in line with your toes and your weight in your heels.\",\"Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0127.webp\",\"gif\":\"0127.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with the bar held in the crook of the elbows. Works the quads, glutes and core.\"},{\"id\":\"3212\",\"n\":\"basic toe touch (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms by your sides.\",\"Bend forward at the waist, keeping your back straight and your knees slightly bent.\",\"Reach down towards your toes with your hands, keeping your legs as straight as possible.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3212.webp\",\"gif\":\"3212.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple standing forward fold to reach your toes. It loosens the hamstrings and lower back and gets the hips moving.\"},{\"id\":\"0128\",\"n\":\"battling ropes\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"delts\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold one end of the rope in each hand, with your palms facing each other.\",\"Raise your arms to shoulder height, keeping your elbows slightly bent.\",\"Begin making alternating waves with the ropes by rapidly raising and lowering each arm.\",\"Continue for the desired duration or number of repetitions.\"],\"img\":\"0128.webp\",\"gif\":\"0128.mp4\",\"cat\":\"cardio\",\"desc\":\"Wave the heavy ropes rhythmically to raise heart rate and challenge the shoulders and arms.\",\"fv\":\"2565\"},{\"id\":\"3360\",\"n\":\"bear crawl\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"triceps\"],\"st\":[\"Start on all fours with your hands directly under your shoulders and your knees directly under your hips.\",\"Lift your knees slightly off the ground, keeping your back flat and your core engaged.\",\"Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.\",\"Continue crawling forward, alternating your hand and foot movements.\",\"Maintain a steady pace and keep your core tight throughout the exercise.\",\"Continue for the desired distance or time.\"],\"img\":\"3360.webp\",\"gif\":\"3360.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crawl on hands and feet with the knees hovering off the floor. It works the shoulders, core and legs together.\"},{\"id\":\"1259\",\"n\":\"behind head chest stretch\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand tall with your feet shoulder-width apart.\",\"Interlace your fingers behind your head with your elbows pointing outwards.\",\"Slowly squeeze your shoulder blades together and push your chest forward.\",\"Hold the stretch for 15-30 seconds.\",\"Release the stretch and repeat as desired.\"],\"img\":\"1259.webp\",\"gif\":\"1259.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch with the hands behind the head, pulling the elbows back. It opens the chest and shoulders.\"},{\"id\":\"0129\",\"n\":\"bench dip (knees bent)\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.\",\"Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.\",\"Bend your elbows and lower your body towards the ground, keeping your back close to the bench.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0129.webp\",\"gif\":\"0129.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bench dip with knees bent. A manageable way to train the triceps.\",\"fv\":\"2376\"},{\"id\":\"1399\",\"n\":\"bench dip on floor\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.\",\"Slide your butt off the bench, supporting your weight with your hands.\",\"Lower your body by bending your elbows until your upper arms are parallel to the floor.\",\"Push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1399.webp\",\"gif\":\"1399.mp4\",\"cat\":\"calisthenics\",\"desc\":\"With your hands on a bench behind you and your feet on the floor, you bend and straighten your elbows. It builds the triceps, chest and shoulders.\",\"fv\":\"2546\"},{\"id\":\"0130\",\"n\":\"bench hip extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on a bench with your back against the bench and your feet flat on the ground.\",\"Place your hands on the bench for support.\",\"Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0130.webp\",\"gif\":\"0130.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip extension from a bench, lifting the hips to work the glutes.\",\"fv\":\"11437\"},{\"id\":\"3019\",\"n\":\"bench pull-ups\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Position yourself under a bar or a sturdy horizontal surface that is at chest height.\",\"Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang with your arms fully extended and your body straight.\",\"Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.\",\"Continue pulling until your chin is above the bar or surface.\",\"Lower yourself back down to the starting position with control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3019.webp\",\"gif\":\"3019.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight bench pull-up variation hanging beneath a bar. Works the lats and biceps.\",\"fv\":\"3020\"},{\"id\":\"3639\",\"n\":\"bent knee lying twist (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Extend your arms out to the sides, perpendicular to your body.\",\"Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.\",\"Pause for a moment, then engage your core and slowly lift your knees back to the starting position.\",\"Repeat the movement to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3639.webp\",\"gif\":\"3639.mp4\",\"cat\":\"mobility\",\"desc\":\"A lying twist with the knees bent, lowering them to each side. It loosens the lower back and hips.\",\"fv\":\"0132\"},{\"id\":\"1770\",\"n\":\"biceps leg concentration curl\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your legs spread apart and your feet flat on the ground.\",\"Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.\",\"With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.\",\"Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1770.webp\",\"gif\":\"1770.mp4\",\"cat\":\"strength\",\"desc\":\"A seated curl with your elbow braced on your inner thigh. Isolates the biceps and cuts out swinging.\"},{\"id\":\"0139\",\"n\":\"biceps narrow pull-ups\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.\",\"Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.\",\"Pause for a moment at the top, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0139.webp\",\"gif\":\"0139.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with a narrow grip. Emphasises the biceps and lats.\",\"fv\":\"2694\"},{\"id\":\"0140\",\"n\":\"biceps pull-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.\",\"Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.\",\"Pause at the top of the movement, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0140.webp\",\"gif\":\"0140.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with an underhand grip. Targets the biceps.\"},{\"id\":\"0137\",\"n\":\"body-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.\",\"Extend your legs out in front of you, keeping your heels on the ground and your body straight.\",\"Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.\",\"Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0137.webp\",\"gif\":\"0137.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight press-up that pushes the body back toward the hands. Trains the triceps.\"},{\"id\":\"3543\",\"n\":\"bodyweight drop jump squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"Jump up explosively, extending your hips, knees, and ankles.\",\"While in mid-air, quickly bring your feet together.\",\"Land softly on the balls of your feet and immediately drop back into a squat position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3543.webp\",\"gif\":\"3543.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat that ends with an explosive jump, bringing the feet together in the air. It builds leg power and cardio.\"},{\"id\":\"3544\",\"n\":\"bodyweight incline side plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Start by lying on your side with your legs extended and stacked on top of each other.\",\"Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.\",\"Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.\",\"Hold this position for the desired amount of time.\",\"Lower your hips back down to the ground and repeat on the other side.\"],\"img\":\"3544.webp\",\"gif\":\"3544.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank held on an incline, resting on the forearm with the body in a straight line. It trains the obliques and core.\",\"hd\":1},{\"id\":\"1771\",\"n\":\"bodyweight kneeling triceps extension\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Kneel down on the ground with your knees hip-width apart.\",\"Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.\",\"Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.\",\"Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.\",\"Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1771.webp\",\"gif\":\"1771.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling bodyweight triceps press with elbows kept tight to your sides. Builds triceps strength without equipment.\",\"fv\":\"3036\"},{\"id\":\"1769\",\"n\":\"bodyweight side lying biceps curl\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie on your side with your legs extended and your head supported by your arm.\",\"Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.\",\"Pause for a moment at the top, then slowly lower your forearm back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1769.webp\",\"gif\":\"1769.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight curl performed while lying on your side. A gentle way to train the biceps without equipment.\"},{\"id\":\"3168\",\"n\":\"bodyweight squatting row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.\",\"Lower your body into a squat position, keeping your back straight and your knees behind your toes.\",\"From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3168.webp\",\"gif\":\"3168.mp4\",\"cat\":\"strength\",\"desc\":\"A squat paired with a pulling motion on a sturdy anchor or suspension trainer. It trains the legs and upper back in one flowing movement.\",\"fv\":\"3170\"},{\"id\":\"3167\",\"n\":\"bodyweight squatting row (with towel)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.\",\"Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.\",\"As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3167.webp\",\"gif\":\"3167.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a towel row, so legs and upper back work together. You pull the towel toward your chest as you sink down.\",\"fv\":\"3169\"},{\"id\":\"1373\",\"n\":\"bodyweight standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing forward.\",\"Place your hands on a wall or stable surface for balance.\",\"Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1373.webp\",\"gif\":\"1373.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing calf raise using just your body weight. It strengthens the calves and ankles and needs no equipment.\"},{\"id\":\"3156\",\"n\":\"bodyweight standing close-grip one arm row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.\",\"Bend forward at the hips, keeping your back straight and your core engaged.\",\"Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"3156.webp\",\"gif\":\"3156.mp4\",\"cat\":\"strength\",\"desc\":\"A standing, bent-over one arm row with a close grip, working the muscles between and around the shoulder blades. A light handheld weight keeps the pull honest.\",\"fv\":\"3155\"},{\"id\":\"3158\",\"n\":\"bodyweight standing close-grip row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Bend forward at the waist, keeping your back straight and your core engaged.\",\"Extend your arms straight in front of you, gripping the bar or handles with a close grip.\",\"Pull the bar or handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3158.webp\",\"gif\":\"3158.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over standing row with a close grip, pulling the hands toward your body. It builds the upper back and the muscles that squeeze the shoulder blades together.\",\"fv\":\"3157\"},{\"id\":\"3162\",\"n\":\"bodyweight standing one arm row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.\",\"Bend forward at the hips, keeping your back straight and your core engaged.\",\"Let the dumbbell hang straight down in front of you, with your arm fully extended.\",\"Pull the dumbbell up towards your chest, keeping your elbow close to your body.\",\"Squeeze your shoulder blades together at the top of the movement.\",\"Lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"3162.webp\",\"gif\":\"3162.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one arm row from a hip hinge, pulling a weight toward your chest one side at a time. Good for the upper back and lats.\",\"fv\":\"3159\"},{\"id\":\"3161\",\"n\":\"bodyweight standing one arm row (with towel)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.\",\"Bend forward at the hips, keeping your back straight and your core engaged.\",\"Pull the towel towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the towel back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"3161.webp\",\"gif\":\"3161.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one arm row using a towel as the handle, pulled toward the chest. It trains the upper back with very little equipment.\",\"fv\":\"3160\"},{\"id\":\"3166\",\"n\":\"bodyweight standing row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Grasp a bar or handles with an overhand grip, palms facing down.\",\"Keep your back straight and core engaged.\",\"Pull the bar or handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement.\",\"Slowly release and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3166.webp\",\"gif\":\"3166.mp4\",\"cat\":\"strength\",\"desc\":\"A standing, bent-over row pulling a bar or handles toward your body with an overhand grip. It builds the upper back and the muscles that retract the shoulder blades.\",\"fv\":\"3163\"},{\"id\":\"3165\",\"n\":\"bodyweight standing row (with towel)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Pull the towel towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3165.webp\",\"gif\":\"3165.mp4\",\"cat\":\"strength\",\"desc\":\"A standing row done with both hands on a towel, pulling toward your chest. It trains the upper back and shoulder blade squeeze with no gear.\",\"fv\":\"3164\"},{\"id\":\"0138\",\"n\":\"bottoms-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Bend your knees and bring them towards your chest, keeping your feet off the ground.\",\"Engaging your abs, lift your hips off the ground, bringing your knees towards your head.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0138.webp\",\"gif\":\"0138.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight ab exercise that rocks the hips up toward the ceiling. Works the abs.\",\"fv\":\"2436\"},{\"id\":\"1374\",\"n\":\"box jump down with one leg stabilization\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Stand in front of a box or platform with your feet shoulder-width apart.\",\"Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.\",\"Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.\",\"Hold this position for a few seconds, engaging your calf muscles to maintain balance.\",\"Slowly step down with the foot that is on the box, returning to the starting position.\",\"Repeat the exercise with the other leg.\"],\"img\":\"1374.webp\",\"gif\":\"1374.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Step off a box and land on both feet, then hold the landing on one leg. It builds landing control and strengthens the calves and ankle.\"},{\"id\":\"2466\",\"n\":\"bridge - mountain climber (cross body)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"hamstrings\",\"shoulders\",\"triceps\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line.\",\"Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.\",\"Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.\",\"Continue alternating sides, moving at a controlled pace.\",\"Keep your hips level and avoid lifting your hips too high or sagging them too low.\",\"Maintain a steady breathing pattern throughout the exercise.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2466.webp\",\"gif\":\"2466.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank-position mountain climber driving knee across the body. Works the abs and obliques, and raises your heart rate.\",\"fv\":\"0141\"},{\"id\":\"1160\",\"n\":\"burpee\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"shoulders\",\"chest\"],\"st\":[\"Start in a standing position with your feet shoulder-width apart.\",\"Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.\",\"Kick your feet back into a push-up position.\",\"Perform a push-up, keeping your body in a straight line.\",\"Jump your feet back into the squat position.\",\"Jump up explosively, reaching your arms overhead.\",\"Land softly and immediately lower back into a squat position to begin the next repetition.\"],\"img\":\"1160.webp\",\"gif\":\"1160.mp4\",\"cat\":\"cardio\",\"desc\":\"A full-body move: squat, kick back to a plank, push-up, jump up. It builds endurance and strength.\",\"fv\":\"2794\"},{\"id\":\"0870\",\"n\":\"butt-ups\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands by your sides, palms facing down.\",\"Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.\",\"At the top of the movement, squeeze your abs and pause for a moment.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0870.webp\",\"gif\":\"0870.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying move where the hips lift off the floor as the knees come toward the chest. It trains the lower abs.\"},{\"id\":\"1494\",\"n\":\"butterfly yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"groin\"],\"st\":[\"Sit on the floor with your legs extended in front of you.\",\"Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.\",\"Hold onto your ankles or feet with your hands.\",\"Sit up tall and lengthen your spine.\",\"Gently press your knees down towards the floor, feeling a stretch in your inner thighs.\",\"Hold this position for a few breaths.\",\"To release, slowly bring your knees back up and extend your legs.\"],\"img\":\"1494.webp\",\"gif\":\"1494.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated pose with the soles of your feet together and knees dropped out. It opens the inner thighs and hips.\",\"fv\":\"4508\"},{\"id\":\"0148\",\"n\":\"cable alternate shoulder press\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.\",\"Position your hands at shoulder height, with your palms facing forward.\",\"Keep your core engaged and your back straight.\",\"Press one handle up and forward until your arm is fully extended.\",\"Pause for a moment at the top, then slowly lower the handle back to the starting position.\",\"Repeat with the other arm.\",\"Alternate between arms for the desired number of repetitions.\"],\"img\":\"0148.webp\",\"gif\":\"0148.mp4\",\"cat\":\"strength\",\"desc\":\"A cable shoulder press alternating arms. Trains the delts and triceps.\",\"fv\":\"3038\"},{\"id\":\"0149\",\"n\":\"cable alternate triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.\",\"Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat with your left arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0149.webp\",\"gif\":\"0149.mp4\",\"cat\":\"strength\",\"desc\":\"A cable triceps extension alternating arms. Isolates the triceps.\",\"fv\":\"3039\"},{\"id\":\"3235\",\"n\":\"cable assisted inverse leg curl\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Adjust the cable machine so that the ankle attachment is at the lowest setting.\",\"Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.\",\"Hold onto the handles of the bench for stability.\",\"Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.\",\"Pause for a moment at the top of the movement, squeezing your hamstrings.\",\"Inhale and slowly lower your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3235.webp\",\"gif\":\"3235.mp4\",\"cat\":\"strength\",\"desc\":\"A cable-resisted leg curl from a face-down position. It isolates the hamstrings with smooth, constant tension.\",\"nd\":[\"bench\"]},{\"id\":\"0150\",\"n\":\"cable bar lateral pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the cable pulley to a high position and attach a straight bar.\",\"Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.\",\"Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0150.webp\",\"gif\":\"0150.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown on the cable machine with a straight bar. Builds the lats.\",\"fv\":\"2247\"},{\"id\":\"0151\",\"n\":\"cable bench press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the cable machine to chest height and attach the handles.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Grasp the handles with an overhand grip and step forward to create tension in the cables.\",\"Position your feet firmly on the ground and engage your core.\",\"Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.\",\"Push the handles forward, extending your arms fully in front of you.\",\"Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0151.webp\",\"gif\":\"0151.mp4\",\"cat\":\"strength\",\"desc\":\"A cable press from a bench. Trains the chest, shoulders and triceps.\",\"fv\":\"2678\"},{\"id\":\"1630\",\"n\":\"cable close grip curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to a low pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Exhale and curl the bar up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the bar back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1630.webp\",\"gif\":\"1630.mp4\",\"cat\":\"strength\",\"desc\":\"A cable curl with a close grip. It keeps constant tension on the biceps.\",\"fv\":\"3041\"},{\"id\":\"1631\",\"n\":\"cable concentration curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.\",\"Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.\",\"Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.\",\"Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1631.webp\",\"gif\":\"1631.mp4\",\"cat\":\"strength\",\"desc\":\"A concentration curl using a cable. The elbow stays braced so the biceps do the work.\",\"fv\":\"3042\"},{\"id\":\"0152\",\"n\":\"cable concentration extension (on knee)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench or chair with your knees bent and feet flat on the ground.\",\"Hold the cable handle with your right hand and place your elbow on the inside of your right knee.\",\"Extend your arm fully, keeping your elbow stationary and close to your knee.\",\"Pause for a moment at the top, then slowly lower your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0152.webp\",\"gif\":\"0152.mp4\",\"cat\":\"strength\",\"desc\":\"A cable triceps extension while kneeling, which keeps the body steady and isolates the triceps.\",\"fv\":\"3043\"},{\"id\":\"0153\",\"n\":\"cable cross-over lateral pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Attach a cable handle to each side of a cable machine at shoulder height.\",\"Stand in the middle of the machine with your feet shoulder-width apart.\",\"Grasp the handles with an overhand grip and step back to create tension in the cables.\",\"Lean forward slightly from the hips, keeping your back straight and your chest up.\",\"Pull the handles down and across your body, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0153.webp\",\"gif\":\"0153.mp4\",\"cat\":\"strength\",\"desc\":\"A cable pulldown with arms crossing over. Trains the lats.\",\"fv\":\"3044\"},{\"id\":\"0154\",\"n\":\"cable cross-over revers fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\"],\"st\":[\"Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.\",\"Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.\",\"Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.\",\"With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.\",\"Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0154.webp\",\"gif\":\"0154.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse fly using crossed cables. Targets the rear delts and upper back.\",\"fv\":\"2492\"},{\"id\":\"0155\",\"n\":\"cable cross-over variation\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Adjust the cable pulleys to chest height.\",\"Stand in the center of the cable machine with one foot in front of the other.\",\"Grasp the handles with your palms facing down and your arms extended out to the sides.\",\"Take a step forward, keeping your arms slightly bent.\",\"With a slight bend in your elbows, bring your hands together in front of your chest.\",\"Pause for a moment, then slowly return your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0155.webp\",\"gif\":\"0155.mp4\",\"cat\":\"strength\",\"desc\":\"A variation of the cable crossover for the chest.\"},{\"id\":\"0868\",\"n\":\"cable curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the cable attachment with an underhand grip, palms facing up.\",\"Keep your elbows close to your sides and your upper arms stationary.\",\"Exhale and curl the cable attachment towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the cable attachment back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0868.webp\",\"gif\":\"0868.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl using a cable and an underhand grip. It keeps constant tension on the biceps.\",\"fv\":\"0156\"},{\"id\":\"0157\",\"n\":\"cable deadlift\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Bend at the hips and knees, lowering your torso until your back is parallel to the ground.\",\"Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.\",\"Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.\",\"Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0157.webp\",\"gif\":\"0157.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift using the cable stack. Trains the glutes, hamstrings and lower back.\",\"fv\":\"3045\"},{\"id\":\"0158\",\"n\":\"cable decline fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Adjust the cable machine to a decline position.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Hold the handles with your palms facing forward and your arms extended straight out in front of you.\",\"Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.\",\"Pause for a moment at the fully extended position, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0158.webp\",\"gif\":\"0158.mp4\",\"cat\":\"strength\",\"desc\":\"A decline cable fly for the lower chest.\",\"fv\":\"2512\"},{\"id\":\"1260\",\"n\":\"cable decline one arm press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the cable machine to a decline position.\",\"Stand facing away from the machine and grab the handle with one hand.\",\"Position yourself with your back against the decline bench and your arm extended straight in front of you.\",\"Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.\",\"Pause for a moment at the bottom, then push the handle back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1260.webp\",\"gif\":\"1260.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable press from a decline angle. It trains the chest and triceps.\"},{\"id\":\"1261\",\"n\":\"cable decline press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the cable machine to a decline position.\",\"Sit on the decline bench facing the cable machine.\",\"Grasp the handles with an overhand grip and position them at chest level.\",\"Keep your feet flat on the ground and your back firmly against the bench.\",\"Exhale and push the handles away from your body, extending your arms fully.\",\"Pause for a moment at the end of the movement, squeezing your chest muscles.\",\"Inhale and slowly return the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1261.webp\",\"gif\":\"1261.mp4\",\"cat\":\"strength\",\"desc\":\"A decline cable press for the lower chest. It trains the chest, shoulders and triceps.\",\"fv\":\"3046\"},{\"id\":\"0159\",\"n\":\"cable decline seated wide-grip row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.\",\"Grasp the cable attachment with a wide overhand grip, palms facing down.\",\"Lean back slightly, keeping your back straight and your core engaged.\",\"Pull the cable towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0159.webp\",\"gif\":\"0159.mp4\",\"cat\":\"strength\",\"desc\":\"A seated wide-grip cable row on a decline. Targets the upper back.\"},{\"id\":\"1632\",\"n\":\"cable drag curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1632.webp\",\"gif\":\"1632.mp4\",\"cat\":\"strength\",\"desc\":\"A cable curl where you drag the handle up along your body. It trains the biceps with the elbows pulled back.\"},{\"id\":\"0160\",\"n\":\"cable floor seated wide-grip row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the floor with your legs extended and your back straight.\",\"Attach a cable handle to a low pulley and position the cable machine behind you.\",\"Grasp the handle with a wide overhand grip, palms facing down.\",\"Lean back slightly, keeping your back straight and your chest lifted.\",\"Pull the handle towards your waist, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0160.webp\",\"gif\":\"0160.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip cable row seated on the floor. Targets the upper back.\"},{\"id\":\"0161\",\"n\":\"cable forward raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.\",\"Keeping your arms straight, raise the cable handle up to shoulder level.\",\"Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0161.webp\",\"gif\":\"0161.mp4\",\"cat\":\"strength\",\"desc\":\"A cable raise in front of you. Works the front delts.\"},{\"id\":\"0162\",\"n\":\"cable front raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.\",\"Keep your back straight and your core engaged.\",\"Raise the cable handle in front of you, keeping your arms straight and your palms facing down.\",\"Continue lifting until your arms are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0162.webp\",\"gif\":\"0162.mp4\",\"cat\":\"strength\",\"desc\":\"A cable front raise. Works the front delts.\",\"fv\":\"2230\"},{\"id\":\"0164\",\"n\":\"cable front shoulder raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.\",\"Keep your back straight and your core engaged.\",\"Raise the cable handle in front of you, keeping your arms straight and your palms facing down.\",\"Continue lifting until your arms are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0164.webp\",\"gif\":\"0164.mp4\",\"cat\":\"strength\",\"desc\":\"A cable front raise for the shoulders.\"},{\"id\":\"0165\",\"n\":\"cable hammer curl (with rope)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand upright with your feet shoulder-width apart and a slight bend in your knees.\",\"Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the cable rope attachment back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0165.webp\",\"gif\":\"0165.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl with a rope attachment. Trains the biceps and brachialis.\"},{\"id\":\"1722\",\"n\":\"cable high pulley overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope to a high pulley and stand facing away from the machine.\",\"Grasp the rope with both hands and extend your arms overhead.\",\"Keep your elbows close to your head and your upper arms stationary.\",\"Slowly lower the rope behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1722.webp\",\"gif\":\"1722.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension at a high pulley, with the cable overhead. It targets the long head of the triceps.\",\"fv\":\"3047\"},{\"id\":\"0167\",\"n\":\"cable high row (kneeling)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Attach a straight bar to a cable machine at chest height.\",\"Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.\",\"Sit back on your heels, keeping your back straight and your core engaged.\",\"Pull the bar towards your upper abdomen, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0167.webp\",\"gif\":\"0167.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling high cable row. Targets the upper back and rear delts.\",\"fv\":\"2244\"},{\"id\":\"0168\",\"n\":\"cable hip adduction\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\"],\"st\":[\"Attach the ankle cuff to your ankle and stand facing the cable machine.\",\"Position yourself far enough away from the machine so that there is tension on the cable.\",\"Place your hands on the machine for support.\",\"Keeping your leg straight, slowly move your leg across your body towards the midline.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0168.webp\",\"gif\":\"0168.mp4\",\"cat\":\"strength\",\"desc\":\"A cable hip adduction, bringing the leg across the body. Works the inner thighs.\",\"fv\":\"2313\"},{\"id\":\"0169\",\"n\":\"cable incline bench press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Adjust the bench to a 45-degree incline.\",\"Attach the cable handles to the high pulleys.\",\"Sit on the bench facing the cable machine with your feet flat on the ground.\",\"Grasp the handles with an overhand grip and bring them to shoulder height.\",\"Push the handles forward and upward until your arms are fully extended.\",\"Pause for a moment, then slowly lower the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0169.webp\",\"gif\":\"0169.mp4\",\"cat\":\"strength\",\"desc\":\"An incline cable press. Emphasises the upper chest.\",\"fv\":\"3049\"},{\"id\":\"1318\",\"n\":\"cable incline bench row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rear deltoids\"],\"st\":[\"Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.\",\"Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.\",\"Grasp the cable handle with an overhand grip and extend your arms fully in front of you.\",\"Lean forward from your hips while keeping your back straight and your core engaged.\",\"Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.\",\"Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1318.webp\",\"gif\":\"1318.mp4\",\"cat\":\"strength\",\"desc\":\"A cable row done on an incline bench so your torso is supported. It works the upper back and biceps without lower back strain.\"},{\"id\":\"0171\",\"n\":\"cable incline fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Adjust the cable machine to a low position and attach the handles.\",\"Sit on an incline bench with your back against the pad and feet flat on the floor.\",\"Grasp the handles with an overhand grip and extend your arms straight out in front of you.\",\"Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.\",\"Pause for a moment at the fully extended position, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0171.webp\",\"gif\":\"0171.mp4\",\"cat\":\"strength\",\"desc\":\"An incline cable fly. Targets the upper chest.\",\"fv\":\"3050\"},{\"id\":\"0170\",\"n\":\"cable incline fly (on stability ball)\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Set up a stability ball at an incline angle.\",\"Attach the cable handles to the high pulleys of a cable machine.\",\"Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.\",\"Grasp the cable handles with an overhand grip, palms facing forward.\",\"Lean forward slightly, keeping your back straight and core engaged.\",\"With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.\",\"Continue the motion until your arms are parallel to the ground.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0170.webp\",\"gif\":\"0170.mp4\",\"cat\":\"strength\",\"desc\":\"An incline cable fly performed on a stability ball. Trains the chest and core stability.\"},{\"id\":\"0172\",\"n\":\"cable incline pushdown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Attach a straight bar to a high pulley cable machine.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Lean forward slightly and keep your back straight.\",\"Pull the bar down towards your thighs by extending your elbows.\",\"Pause for a moment at the bottom, then slowly return the bar to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0172.webp\",\"gif\":\"0172.mp4\",\"cat\":\"strength\",\"desc\":\"An incline cable pushdown with straight arms. Targets the lats.\",\"fv\":\"3051\"},{\"id\":\"0173\",\"n\":\"cable incline triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Adjust the cable machine to a low pulley position.\",\"Attach a straight bar to the cable.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip and extend your arms straight overhead.\",\"Lean forward slightly, keeping your back straight and core engaged.\",\"Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0173.webp\",\"gif\":\"0173.mp4\",\"cat\":\"strength\",\"desc\":\"Overhead cable triceps extension from a low pulley with a straight bar. It isolates the triceps, especially the long head, through a deep stretch behind the head.\",\"fv\":\"3052\"},{\"id\":\"0174\",\"n\":\"cable judo flip\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Hold the cable handle with both hands at chest level, palms facing down.\",\"Engage your core and rotate your torso to the right, pulling the cable across your body.\",\"As you rotate, pivot your back foot and allow your hips to rotate naturally.\",\"Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.\",\"Return to the starting position by reversing the movement, rotating your torso back to the center.\",\"Repeat the movement on the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0174.webp\",\"gif\":\"0174.mp4\",\"cat\":\"strength\",\"desc\":\"A rotational cable move where you sweep the handle across the body and up over the shoulder. It builds twisting power and trains the core and obliques.\",\"fv\":\"3053\"},{\"id\":\"0860\",\"n\":\"cable kickback\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Hold the cable handle with your right hand and step back to create tension in the cable.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Keep your upper arm close to your body and your elbow bent at a 90-degree angle.\",\"Extend your forearm backward, straightening your arm fully.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0860.webp\",\"gif\":\"0860.mp4\",\"cat\":\"strength\",\"desc\":\"A cable triceps kickback, hinging forward and extending the forearm back. It isolates the triceps.\",\"fv\":\"2640\"},{\"id\":\"0175\",\"n\":\"cable kneeling crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Attach a rope handle to a high pulley and kneel down facing away from the machine.\",\"Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.\",\"Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0175.webp\",\"gif\":\"0175.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling cable crunch with a rope behind the head. Crunching down against the pulley loads the abs with steady tension.\",\"fv\":\"2369\"},{\"id\":\"3697\",\"n\":\"cable kneeling rear delt row (with rope) (male)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Attach a rope handle to a low cable pulley and kneel down facing the machine.\",\"Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.\",\"Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.\",\"Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.\",\"Slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3697.webp\",\"gif\":\"3697.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable row with a rope that targets the rear delts. It trains the shoulders and upper back.\"},{\"id\":\"0176\",\"n\":\"cable kneeling triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope handle to a high pulley and kneel down facing the cable machine.\",\"Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.\",\"Keep your elbows close to your head and your upper arms stationary throughout the exercise.\",\"Extend your forearms by contracting your triceps until your arms are fully extended.\",\"Pause for a moment, then slowly return to the starting position by bending your elbows.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0176.webp\",\"gif\":\"0176.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling cable triceps extension with a rope. Your elbows stay put while the forearms extend, which keeps the work on the triceps.\"},{\"id\":\"2330\",\"n\":\"cable lat pulldown full range of motion\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit on the lat pulldown machine with your knees positioned under the pads.\",\"Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.\",\"Pull the bar down towards your upper chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2330.webp\",\"gif\":\"2330.mp4\",\"cat\":\"strength\",\"desc\":\"A cable lat pulldown using the full range of motion. Builds the lats and upper back.\"},{\"id\":\"0177\",\"n\":\"cable lateral pulldown (with rope attachment)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach a rope attachment to the cable machine at a high position.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the rope with an overhand grip, palms facing each other.\",\"Keep your back straight and lean slightly back.\",\"Pull the rope down towards your sides, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement.\",\"Slowly release the tension and allow the rope to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0177.webp\",\"gif\":\"0177.mp4\",\"cat\":\"strength\",\"desc\":\"A high-pulley rope pulldown that sweeps the hands down to your sides. It works the lats and the muscles between the shoulder blades.\"},{\"id\":\"2616\",\"n\":\"cable lateral pulldown with v-bar\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.\",\"Adjust the knee pad so that your thighs are secured under it.\",\"Keep your back straight and lean back slightly.\",\"Pull the v-bar down towards your upper chest while keeping your elbows close to your body.\",\"Squeeze your back muscles at the bottom of the movement.\",\"Slowly return the v-bar to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"2616.webp\",\"gif\":\"2616.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown with a v-bar attachment. Builds the lats and upper back.\"},{\"id\":\"0178\",\"n\":\"cable lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.\",\"Keep your arms straight and your core engaged.\",\"Raise your arms out to the sides until they are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0178.webp\",\"gif\":\"0178.mp4\",\"cat\":\"strength\",\"desc\":\"Standing cable lateral raise: arms lift out to the sides against constant cable tension. It targets the side delts for broader shoulders.\",\"fv\":\"3054\"},{\"id\":\"0179\",\"n\":\"cable low fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Attach the handles to the low pulleys of a cable machine and select an appropriate weight.\",\"Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.\",\"Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.\",\"Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.\",\"Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.\",\"Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0179.webp\",\"gif\":\"0179.mp4\",\"cat\":\"strength\",\"desc\":\"A cable fly from low pulleys, sweeping the arms up and together in front of you. It emphasises the upper chest with constant tension.\",\"fv\":\"2252\"},{\"id\":\"0180\",\"n\":\"cable low seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the machine with your feet flat on the footrests and your knees slightly bent.\",\"Grasp the handles with an overhand grip, palms facing down.\",\"Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.\",\"Pull the handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0180.webp\",\"gif\":\"0180.mp4\",\"cat\":\"strength\",\"desc\":\"Seated cable row from a low pulley. You pull the handles to your torso and squeeze the shoulder blades, building the mid back.\",\"fv\":\"5964\"},{\"id\":\"1634\",\"n\":\"cable lying bicep curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to a low pulley cable machine.\",\"Lie face up on a flat bench with your feet flat on the ground.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Extend your arms fully, keeping your elbows close to your sides.\",\"Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the bar back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1634.webp\",\"gif\":\"1634.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl lying on your back with a cable. It keeps tension constant through the whole motion.\",\"nd\":[\"bench\"],\"fv\":\"3055\"},{\"id\":\"0182\",\"n\":\"cable lying close-grip curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to a low pulley cable machine.\",\"Lie face up on a flat bench with your feet flat on the ground.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Extend your arms fully, keeping your elbows close to your sides.\",\"Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Slowly lower the bar back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0182.webp\",\"gif\":\"0182.mp4\",\"cat\":\"strength\",\"desc\":\"Biceps curl performed lying on a bench with a close grip on a low-pulley bar. Lying down keeps the tension on the biceps through the whole curl.\",\"nd\":[\"bench\"]},{\"id\":\"0184\",\"n\":\"cable lying extension pullover (with rope attachment)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Attach a rope to a cable machine and set the pulley at the highest position.\",\"Lie down on a bench with your head towards the cable machine.\",\"Hold the rope with both hands and extend your arms straight up above your chest.\",\"Keeping your arms straight, slowly lower the rope behind your head while maintaining control.\",\"Pause for a moment at the bottom, then slowly raise the rope back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0184.webp\",\"gif\":\"0184.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you take a rope overhead and back in an arc with straight arms. It stretches and trains the lats and chest.\",\"nd\":[\"bench\"],\"fv\":\"3056\"},{\"id\":\"0185\",\"n\":\"cable lying fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.\",\"Hold the handles with your palms facing each other and your arms extended straight above your chest.\",\"Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0185.webp\",\"gif\":\"0185.mp4\",\"cat\":\"strength\",\"desc\":\"A cable fly done lying on a flat bench. The arms open in a wide arc and close again, working the chest through a deep stretch.\",\"nd\":[\"bench\"],\"fv\":\"2426\"},{\"id\":\"0186\",\"n\":\"cable lying triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope handle to a low pulley cable machine.\",\"Lie down on a flat bench facing up, with your head towards the cable machine.\",\"Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.\",\"Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.\",\"Pause for a moment at the bottom, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0186.webp\",\"gif\":\"0186.mp4\",\"cat\":\"strength\",\"desc\":\"Lying cable triceps extension with a rope. You lower the rope toward the forehead and extend again, isolating the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"0188\",\"n\":\"cable middle fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Attach cables to both sides of a cable machine at chest height.\",\"Stand in the center of the machine with one foot slightly in front of the other.\",\"Grasp the handles with an overhand grip and extend your arms out to the sides.\",\"Keep a slight bend in your elbows and maintain a slight forward lean.\",\"Engage your chest muscles and bring your arms forward in a sweeping motion.\",\"Pause for a moment at the center, then slowly return your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0188.webp\",\"gif\":\"0188.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable fly at chest height. You bring the handles together in front of you to squeeze the chest.\",\"fv\":\"2439\"},{\"id\":\"0189\",\"n\":\"cable one arm bent over row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.\",\"Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.\",\"Pause for a moment, then slowly extend your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0189.webp\",\"gif\":\"0189.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row from a hinged position. It trains the back one side at a time and shows up any strength imbalance.\"},{\"id\":\"0190\",\"n\":\"cable one arm curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the cable handle with an underhand grip, palm facing up.\",\"Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.\",\"Pause for a moment at the top, then slowly lower your forearm back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0190.webp\",\"gif\":\"0190.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm standing cable curl. The cable keeps the biceps under tension from bottom to top.\",\"fv\":\"2581\"},{\"id\":\"1262\",\"n\":\"cable one arm decline chest fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.\",\"Lie down on the bench with your head towards the machine and grab the handle with your right hand.\",\"Extend your arm straight up above your chest, keeping a slight bend in your elbow.\",\"With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.\",\"Pause for a moment, then reverse the motion and bring your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise.\"],\"img\":\"1262.webp\",\"gif\":\"1262.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm decline chest fly with a cable. It trains the lower chest.\"},{\"id\":\"1263\",\"n\":\"cable one arm fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.\",\"Keep your elbow slightly bent and your palm facing forward.\",\"Slowly bring your arm across your body, squeezing your chest muscles.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1263.webp\",\"gif\":\"1263.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable fly seated on an exercise ball. It trains the chest and core.\"},{\"id\":\"1264\",\"n\":\"cable one arm incline fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.\",\"Hold a cable handle in one hand with your arm extended and palm facing inward.\",\"Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.\",\"Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1264.webp\",\"gif\":\"1264.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm incline cable fly on an exercise ball. It trains the upper chest.\"},{\"id\":\"1265\",\"n\":\"cable one arm incline press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Adjust the cable machine to a low pulley position.\",\"Sit on an incline bench facing away from the cable machine.\",\"Grasp the handle with one hand and bring it up to shoulder height.\",\"Position your feet firmly on the ground and maintain a stable position.\",\"Press the handle forward and upward, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the handle back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1265.webp\",\"gif\":\"1265.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm incline cable press. It trains the upper chest and shoulders.\"},{\"id\":\"1266\",\"n\":\"cable one arm incline press on exercise ball\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.\",\"Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.\",\"Press the cable handle forward and upward, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1266.webp\",\"gif\":\"1266.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm incline cable press on an exercise ball. It trains the upper chest and balance.\"},{\"id\":\"0191\",\"n\":\"cable one arm lateral bent-over\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"trapezius\"],\"st\":[\"Stand with your feet shoulder-width apart, facing a cable machine.\",\"Grasp the handle with one hand and step back to create tension on the cable.\",\"Bend forward at the waist, keeping your back straight and your core engaged.\",\"Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.\",\"Slowly bring your arm back to the starting position, maintaining control throughout the movement.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0191.webp\",\"gif\":\"0191.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable raise done bent over, moving the arm out to the side. It works the upper back and rear shoulder with a controlled sweep.\",\"fv\":\"2513\"},{\"id\":\"0192\",\"n\":\"cable one arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart, facing the cable machine.\",\"Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.\",\"Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arm back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0192.webp\",\"gif\":\"0192.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable lateral raise. You lift the arm out to the side until it is level, targeting the side delt.\",\"fv\":\"2231\"},{\"id\":\"1633\",\"n\":\"cable one arm preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the cable machine so that the preacher curl pad is at chest height.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.\",\"Keep your back straight and your core engaged.\",\"Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch arms and repeat the exercise.\"],\"img\":\"1633.webp\",\"gif\":\"1633.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm preacher curl on a cable. The pad blocks swinging, so the biceps take the load.\"},{\"id\":\"1267\",\"n\":\"cable one arm press on exercise ball\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a cable handle in one hand and position your arm at chest height, elbow bent.\",\"Place your other hand on your hip for stability.\",\"Press the cable handle forward, extending your arm fully.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1267.webp\",\"gif\":\"1267.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable press on an exercise ball. It trains the chest and core.\"},{\"id\":\"3563\",\"n\":\"cable one arm pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach a single handle to a high pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the handle with an overhand grip and extend your arm fully.\",\"Keep your back straight and your core engaged.\",\"Pull the handle down towards your side while keeping your elbow close to your body.\",\"Pause for a moment at the bottom of the movement, squeezing your lat muscle.\",\"Slowly release the handle back to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch sides and repeat the exercise with the other arm.\"],\"img\":\"3563.webp\",\"gif\":\"3563.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm cable pulldown from a high pulley, pulling the handle down to your side. It trains the lats.\"},{\"id\":\"1635\",\"n\":\"cable one arm reverse preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the cable machine so that the pulley is at the lowest position.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.\",\"Keep your back straight and your core engaged throughout the exercise.\",\"Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.\",\"Pause for a moment at the top of the movement, squeezing your bicep.\",\"Slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch arms and repeat the exercise.\"],\"img\":\"1635.webp\",\"gif\":\"1635.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm reverse grip preacher curl on a cable. It works the brachialis and forearms along with the biceps.\"},{\"id\":\"0193\",\"n\":\"cable one arm straight back high row (kneeling)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Attach a handle to a cable machine at waist height.\",\"Kneel down facing the cable machine and grab the handle with one hand.\",\"Keep your back straight and your core engaged.\",\"Pull the handle towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement.\",\"Slowly release the handle back to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch sides and repeat the exercise with the other arm.\"],\"img\":\"0193.webp\",\"gif\":\"0193.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling one-arm cable row at a higher pulley, pulling straight back to the chest. It targets the upper back, one side at a time.\"},{\"id\":\"1723\",\"n\":\"cable one arm tricep pushdown\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand facing a cable machine with a straight bar attachment at chest height.\",\"Grasp the bar with an overhand grip and step back to create tension in the cable.\",\"Position your feet shoulder-width apart and slightly bend your knees.\",\"Keep your back straight and core engaged throughout the exercise.\",\"Start with your arm fully extended and perpendicular to the floor.\",\"Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.\",\"Pause for a moment, then inhale and slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1723.webp\",\"gif\":\"1723.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm triceps pushdown on a cable. It isolates the triceps on one side at a time.\"},{\"id\":\"1636\",\"n\":\"cable overhead curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Attach a straight bar to a high pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary.\",\"Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.\",\"Pause for a moment at the bottom of the movement, squeezing your biceps.\",\"Inhale and slowly return the bar to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1636.webp\",\"gif\":\"1636.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with the cable set high so the arms are lifted overhead. It trains the biceps through a short range.\"},{\"id\":\"1637\",\"n\":\"cable overhead curl on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Sit on an exercise ball and hold the cable handle with an underhand grip.\",\"Extend your arms fully overhead, keeping your elbows close to your ears.\",\"Slowly curl the cable down towards your forehead, keeping your upper arms stationary.\",\"Pause for a moment at the bottom of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1637.webp\",\"gif\":\"1637.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead cable curl while sitting on an exercise ball. The ball adds core demand to the biceps work.\"},{\"id\":\"0194\",\"n\":\"cable overhead triceps extension (rope attachment)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope to a cable machine at a high position.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Grasp the rope with both hands, palms facing each other, and bring your hands above your head.\",\"Keep your upper arms close to your head and your elbows pointing forward.\",\"Slowly lower the rope behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0194.webp\",\"gif\":\"0194.mp4\",\"cat\":\"strength\",\"desc\":\"Overhead triceps extension with a rope on a high pulley. Extending the arms against the cable loads the triceps through a long range.\",\"fv\":\"2248\"},{\"id\":\"1319\",\"n\":\"cable palm rotational row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach a handle to a cable machine at waist height.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the handle with an overhand grip, palms facing down.\",\"Step back to create tension on the cable, keeping your back straight and knees slightly bent.\",\"Pull the handle towards your body, rotating your palms to face upwards as you do so.\",\"Squeeze your shoulder blades together at the end of the movement.\",\"Slowly release the handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1319.webp\",\"gif\":\"1319.mp4\",\"cat\":\"strength\",\"desc\":\"A cable row where your palms rotate from facing down to facing up as you pull. It works the upper back, lats and biceps through a twisting path.\"},{\"id\":\"0195\",\"n\":\"cable preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the cable machine so that the preacher curl pad is at chest height.\",\"Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.\",\"Keep your back straight and your elbows tucked in at your sides.\",\"Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.\",\"Pause for a moment, then slowly lower the cable attachment back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0195.webp\",\"gif\":\"0195.mp4\",\"cat\":\"strength\",\"desc\":\"A cable curl with the upper arms resting on a preacher pad. The pad stops swinging so the biceps do the work.\"},{\"id\":\"1268\",\"n\":\"cable press on exercise ball\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.\",\"Hold the cable handles at chest height with your palms facing down and your elbows bent.\",\"Engage your core and press the cable handles forward until your arms are fully extended.\",\"Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1268.webp\",\"gif\":\"1268.mp4\",\"cat\":\"strength\",\"desc\":\"A cable chest press on an exercise ball. It trains the chest and challenges balance.\"},{\"id\":\"0196\",\"n\":\"cable pull through (with rope)\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand facing away from the cable machine with your feet shoulder-width apart.\",\"Grab the rope attachment with both hands and step forward, creating tension in the cable.\",\"Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.\",\"Engage your glutes and hamstrings to pull your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0196.webp\",\"gif\":\"0196.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge facing away from a low pulley with a rope between the legs. You drive the hips forward to strengthen the glutes and hamstrings.\"},{\"id\":\"0198\",\"n\":\"cable pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.\",\"Sit on the seat with your back straight and your feet flat on the ground.\",\"Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Lean back slightly and engage your core.\",\"Pull the cable bar down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0198.webp\",\"gif\":\"0198.mp4\",\"cat\":\"strength\",\"desc\":\"A classic seated cable pulldown with a wide bar. You pull to the chest to train the lats and the muscles around the shoulder blades.\",\"fv\":\"2243\"},{\"id\":\"0197\",\"n\":\"cable pulldown (pro lat bar)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.\",\"Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Sit down and lean back slightly, keeping your chest up and your back straight.\",\"Pull the bar down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0197.webp\",\"gif\":\"0197.mp4\",\"cat\":\"strength\",\"desc\":\"A seated pulldown using a pro lat bar. You pull the bar to the upper chest to build the lats and upper back.\"},{\"id\":\"1638\",\"n\":\"cable pulldown bicep curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to the cable machine at the highest setting.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary.\",\"Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.\",\"Pause for a moment at the bottom of the movement, squeezing your biceps.\",\"Inhale and slowly return the bar to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1638.webp\",\"gif\":\"1638.mp4\",\"cat\":\"strength\",\"desc\":\"A curl at a high pulley that begins with a pulldown. It builds the biceps and also the lats.\",\"fv\":\"3057\"},{\"id\":\"0201\",\"n\":\"cable pushdown\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to a high pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.\",\"Grasp the bar with an overhand grip, hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary.\",\"Exhale and push the bar down until your elbows are fully extended.\",\"Pause for a moment, then inhale and slowly return the bar to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0201.webp\",\"gif\":\"0201.mp4\",\"cat\":\"strength\",\"desc\":\"The classic triceps pushdown on a high pulley with a straight bar. Elbows stay at your sides while the forearms drive down.\",\"fv\":\"9739\"},{\"id\":\"0199\",\"n\":\"cable pushdown (straight arm) v. 2\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Attach a straight bar to a high pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.\",\"Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.\",\"Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.\",\"Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0199.webp\",\"gif\":\"0199.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pushdown from a high pulley, moving the bar from overhead to the thighs. It isolates the lats without bending the elbows.\"},{\"id\":\"0200\",\"n\":\"cable pushdown (with rope attachment)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a rope attachment to a high pulley on a cable machine.\",\"Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.\",\"Grasp the rope with an overhand grip, palms facing each other.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Exhale and push the rope downward by extending your elbows until your arms are fully extended.\",\"Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0200.webp\",\"gif\":\"0200.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps pushdown with a rope. Splitting the rope at the bottom gives the triceps a strong squeeze.\",\"fv\":\"2438\"},{\"id\":\"0202\",\"n\":\"cable rear delt row (stirrups)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Attach a stirrup handle to a low cable pulley and stand facing the machine.\",\"Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.\",\"With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.\",\"Pause for a moment at the top of the movement, squeezing your shoulder blade.\",\"Slowly release the handle back to the starting position and repeat for the desired number of repetitions.\",\"Switch sides and repeat the exercise with your right arm.\"],\"img\":\"0202.webp\",\"gif\":\"0202.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row with a stirrup handle, aimed at the rear delts. You pull back and squeeze the shoulder blade, then switch sides.\",\"fv\":\"3058\"},{\"id\":\"0203\",\"n\":\"cable rear delt row (with rope)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Attach a rope handle to a low pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the rope handle with an overhand grip, palms facing each other.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0203.webp\",\"gif\":\"0203.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over cable row with a rope, pulling toward the face and chest. It builds the rear delts and the upper back.\"},{\"id\":\"0204\",\"n\":\"cable rear drive\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Attach a handle to a low pulley cable machine and stand facing away from the machine.\",\"Grasp the handle with an overhand grip and extend your arms straight out in front of you.\",\"Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.\",\"Slowly return the handle to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0204.webp\",\"gif\":\"0204.mp4\",\"cat\":\"strength\",\"desc\":\"A cable move where you drive the handle back behind you with the arms extended. It works the triceps and rear shoulders.\",\"fv\":\"3059\"},{\"id\":\"0205\",\"n\":\"cable rear pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the cable machine so that the pulley is at the highest position.\",\"Sit facing the machine with your feet flat on the ground and your knees slightly bent.\",\"Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Lean back slightly, keeping your back straight and your chest up.\",\"Pull the cable attachment down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0205.webp\",\"gif\":\"0205.mp4\",\"cat\":\"strength\",\"desc\":\"A pulldown to the chest from a high pulley, with a slight lean back. It trains the lats and the upper back.\"},{\"id\":\"0873\",\"n\":\"cable reverse crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Attach a cable to a low pulley and lie down facing up on a mat.\",\"Hold the cable with both hands and extend your arms straight up towards the ceiling.\",\"Bend your knees and lift your legs up, bringing your thighs towards your chest.\",\"While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0873.webp\",\"gif\":\"0873.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse crunch using a low cable, curling the hips off the mat. It trains the lower abs.\",\"fv\":\"2650\"},{\"id\":\"0206\",\"n\":\"cable reverse curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to a low pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Exhale and curl the bar up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the bar back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0206.webp\",\"gif\":\"0206.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse curl with a bar on a low pulley, using an overhand grip. It works the forearms and the biceps under steady tension.\"},{\"id\":\"2406\",\"n\":\"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to the cable machine at the highest setting.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Engage your triceps and slowly push the bar down until your arms are fully extended.\",\"Pause for a moment at the bottom, then slowly return the bar to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2406.webp\",\"gif\":\"2406.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse grip cable pushdown with an arm blaster. Targets the triceps with a different hand angle.\"},{\"id\":\"1413\",\"n\":\"cable reverse one arm curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Grasp the cable handle with an underhand grip, palm facing down.\",\"Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.\",\"Pause for a moment at the top, then slowly lower your forearm back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1413.webp\",\"gif\":\"1413.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl with a cable using an overhand grip. It works the forearms and the outer part of the biceps.\",\"fv\":\"2695\"},{\"id\":\"0209\",\"n\":\"cable reverse preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the cable machine so that the preacher curl pad is at chest height.\",\"Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.\",\"Grab the cable handles with an underhand grip, shoulder-width apart.\",\"Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the handles back to the starting position, fully extending your elbows.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0209.webp\",\"gif\":\"0209.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl on a cable with an overhand grip. It targets the brachialis and forearms while the pad keeps you strict.\"},{\"id\":\"0210\",\"n\":\"cable reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"wrists\"],\"st\":[\"Attach a cable to a low pulley and sit on a bench facing the cable machine.\",\"Grasp the cable handle with an overhand grip, palms facing down.\",\"Rest your forearms on your thighs, with your wrists hanging off the edge.\",\"Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.\",\"Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0210.webp\",\"gif\":\"0210.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable wrist curl with an overhand grip, with the wrists hanging past the thighs. It strengthens the top of the forearms.\"},{\"id\":\"0207\",\"n\":\"cable reverse-grip pushdown\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a straight bar to a high pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.\",\"Pause for a moment, then slowly return the bar to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0207.webp\",\"gif\":\"0207.mp4\",\"cat\":\"strength\",\"desc\":\"A pushdown with an underhand grip on a high pulley. Switching the grip shifts more load onto the triceps' medial head.\",\"fv\":\"2520\"},{\"id\":\"0208\",\"n\":\"cable reverse-grip straight back seated high row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the seat facing the cable machine with your feet flat on the floor.\",\"Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Keep your back straight and lean slightly forward from your hips.\",\"Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.\",\"Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0208.webp\",\"gif\":\"0208.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row from a high pulley with an underhand grip. Pull to the torso and squeeze the back, keeping the back straight.\"},{\"id\":\"1320\",\"n\":\"cable rope crossover seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.\",\"Grasp the cable ropes with an overhand grip, palms facing each other.\",\"Lean back slightly, keeping your back straight and your core engaged.\",\"Pull the cable ropes towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1320.webp\",\"gif\":\"1320.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row using a rope so your hands can cross and finish wide. It works the upper back and lats with a longer range of motion.\"},{\"id\":\"1321\",\"n\":\"cable rope elevated seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the elevated seat facing the cable machine.\",\"Grab the cable rope handles with an overhand grip, palms facing each other.\",\"Keep your back straight and lean slightly back, maintaining a slight bend in your knees.\",\"Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.\",\"Pause for a moment at the fully contracted position.\",\"Slowly release the tension and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1321.webp\",\"gif\":\"1321.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row using a rope from an elevated seat position. It trains the upper back, lats and biceps with a neutral grip.\"},{\"id\":\"1322\",\"n\":\"cable rope extension incline bench row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.\",\"Attach a rope handle to the cable machine and sit on the incline bench facing the machine.\",\"Grab the rope handle with an overhand grip and lean forward, keeping your back straight.\",\"Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.\",\"Squeeze your shoulder blades together at the end of the movement.\",\"Slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1322.webp\",\"gif\":\"1322.mp4\",\"cat\":\"strength\",\"desc\":\"A rope cable row done chest down on an incline bench. The support keeps your torso still so the upper back does the pulling.\"},{\"id\":\"1639\",\"n\":\"cable rope hammer preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a rope attachment to a low pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the rope with a neutral grip (palms facing each other).\",\"Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.\",\"Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the rope back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1639.webp\",\"gif\":\"1639.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer grip preacher curl with a rope on a cable. It targets the brachialis and the biceps.\"},{\"id\":\"1724\",\"n\":\"cable rope high pulley overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope to a high pulley and adjust the weight accordingly.\",\"Stand facing away from the pulley machine with your feet shoulder-width apart.\",\"Grasp the rope with both hands, palms facing down, and bring your hands above your head.\",\"Keep your upper arms close to your head and perpendicular to the floor.\",\"Slowly lower the rope behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1724.webp\",\"gif\":\"1724.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead triceps extension using a rope on a high pulley. It trains the long head of the triceps.\"},{\"id\":\"1725\",\"n\":\"cable rope incline tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.\",\"Stand facing away from the pulley with your feet shoulder-width apart.\",\"Grasp the rope with an overhand grip and extend your arms straight overhead.\",\"Keep your elbows close to your head and your upper arms stationary throughout the exercise.\",\"Lower the rope behind your head by bending your elbows until your forearms touch your biceps.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1725.webp\",\"gif\":\"1725.mp4\",\"cat\":\"strength\",\"desc\":\"An incline triceps extension with a rope on a cable. It stretches and builds the triceps.\"},{\"id\":\"1726\",\"n\":\"cable rope lying on floor tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Attach a rope to a cable machine and set it to the lowest position.\",\"Lie on the floor facing up, with your head towards the cable machine.\",\"Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.\",\"Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1726.webp\",\"gif\":\"1726.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension with a rope while lying on the floor. It isolates the triceps.\"},{\"id\":\"1640\",\"n\":\"cable rope one arm hammer preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a rope handle to a low pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the rope handle with an underhand grip, palms facing up.\",\"Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.\",\"Keep your back straight and your core engaged throughout the exercise.\",\"Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.\",\"Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1640.webp\",\"gif\":\"1640.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm hammer preacher curl with a rope on a cable. It targets the brachialis and the biceps on one side.\"},{\"id\":\"1323\",\"n\":\"cable rope seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.\",\"Grasp the cable ropes with an overhand grip, palms facing each other.\",\"Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.\",\"Pull the cable ropes towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1323.webp\",\"gif\":\"1323.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row with a rope attachment on a cable station. The neutral grip works the upper back, lats and biceps.\"},{\"id\":\"0211\",\"n\":\"cable russian twists (on stability ball)\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold the cable handle with both hands and extend your arms straight out in front of you.\",\"Lean back slightly while keeping your back straight and your core engaged.\",\"Twist your torso to the right, bringing the cable handle towards your right hip.\",\"Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.\",\"Continue alternating twists for the desired number of repetitions.\"],\"img\":\"0211.webp\",\"gif\":\"0211.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a stability ball, you rotate a cable handle from hip to hip. It trains the abs and obliques and also challenges your balance.\",\"fv\":\"3060\"},{\"id\":\"2144\",\"n\":\"cable seated chest press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Adjust the seat height and cable handles to a comfortable position.\",\"Sit on the bench with your back straight and feet flat on the floor.\",\"Grasp the cable handles with an overhand grip at shoulder height.\",\"Push the handles forward and away from your body, extending your arms fully.\",\"Pause for a moment, then slowly bring the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2144.webp\",\"gif\":\"2144.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable press pushing the handles away from your chest. Builds the chest, shoulders and triceps.\",\"fv\":\"3061\"},{\"id\":\"0212\",\"n\":\"cable seated crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Sit on a cable machine with your feet flat on the ground and your knees bent.\",\"Hold the cable handle with both hands and position it behind your head.\",\"Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.\",\"Pause for a moment at the top, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0212.webp\",\"gif\":\"0212.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable crunch with the handle behind the head. You curl the torso forward against the pull to work the abs.\",\"fv\":\"2700\"},{\"id\":\"1641\",\"n\":\"cable seated curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a cable machine with your feet flat on the ground and your back straight.\",\"Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1641.webp\",\"gif\":\"1641.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable biceps curl. The seat keeps you steady so the biceps do the lifting.\",\"fv\":\"3062\"},{\"id\":\"0213\",\"n\":\"cable seated high row (v-bar)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit on the cable machine with your feet flat on the floor and your knees slightly bent.\",\"Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.\",\"Keep your back straight and lean slightly forward from the hips.\",\"Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.\",\"Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0213.webp\",\"gif\":\"0213.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row from a high position using a v-bar. You pull toward the torso to work the lats and the middle back.\",\"fv\":\"3063\"},{\"id\":\"0214\",\"n\":\"cable seated one arm alternate row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.\",\"Grasp the handle with one hand and keep your arm fully extended in front of you.\",\"Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.\",\"Pause for a moment at the top of the movement, squeezing your back muscles.\",\"Slowly release the handle back to the starting position.\",\"Repeat with the other arm.\",\"Alternate between arms for the desired number of repetitions.\"],\"img\":\"0214.webp\",\"gif\":\"0214.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row that alternates between arms. It works the back one side at a time with a full squeeze each rep.\"},{\"id\":\"1642\",\"n\":\"cable seated one arm concentration curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the floor and your back straight.\",\"Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.\",\"Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Slowly lower the cable handle back to the starting position while inhaling.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1642.webp\",\"gif\":\"1642.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm concentration curl using a cable. It isolates the biceps on one side at a time.\",\"fv\":\"3064\"},{\"id\":\"1643\",\"n\":\"cable seated overhead curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Sit on a bench facing the cable machine with your feet flat on the ground.\",\"Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Keep your upper arms stationary and your elbows close to your sides.\",\"Exhale and curl the cable attachment towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1643.webp\",\"gif\":\"1643.mp4\",\"cat\":\"strength\",\"desc\":\"A seated curl at a high cable stack with your arms overhead. It stresses the biceps in a different way.\",\"fv\":\"3065\"},{\"id\":\"0215\",\"n\":\"cable seated rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Sit on a bench facing the cable machine with your feet flat on the ground.\",\"Grasp the cable handles with an overhand grip and extend your arms straight in front of you.\",\"Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0215.webp\",\"gif\":\"0215.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable rear raise: arms sweep out to the sides to the level of the shoulders. It trains the rear delts and upper back.\"},{\"id\":\"0861\",\"n\":\"cable seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.\",\"Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.\",\"Pull the handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0861.webp\",\"gif\":\"0861.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row, pulling the handles toward the torso. It trains the back and biceps.\",\"fv\":\"2245\"},{\"id\":\"0216\",\"n\":\"cable seated shoulder internal rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"triceps\"],\"st\":[\"Sit on a bench or chair facing the cable machine with your feet flat on the ground.\",\"Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.\",\"Keep your elbow slightly bent and your shoulder blades pulled back and down.\",\"Slowly rotate your arm inward, bringing the cable handle towards the center of your body.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0216.webp\",\"gif\":\"0216.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable shoulder rotation where the arm turns inward. It builds control of the rotator cuff and the shoulder.\"},{\"id\":\"2399\",\"n\":\"cable seated twist\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Sit on a cable machine with your feet flat on the ground and your knees slightly bent.\",\"Hold the cable handle with both hands and extend your arms straight in front of you.\",\"Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.\",\"Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"2399.webp\",\"gif\":\"2399.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable twist, rotating the torso against resistance. Works the obliques and core.\"},{\"id\":\"0218\",\"n\":\"cable seated wide-grip row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.\",\"Grasp the handle with a wide overhand grip, palms facing down.\",\"Keep your back straight and lean slightly forward from the hips.\",\"Pull the handle towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the contraction.\",\"Slowly release the handle back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0218.webp\",\"gif\":\"0218.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row with a wide grip handle. The wide hold puts more emphasis on the upper back and rear shoulders.\",\"fv\":\"3598\"},{\"id\":\"0219\",\"n\":\"cable shoulder press\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Adjust the cable machine so that the handles are at shoulder height.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.\",\"Press the handles upwards until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the handles back down to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0219.webp\",\"gif\":\"0219.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press using cable handles. The constant tension challenges the shoulders and triceps all the way up.\",\"fv\":\"3066\"},{\"id\":\"0220\",\"n\":\"cable shrug\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the cable handles with an overhand grip and let your arms hang down in front of you.\",\"Keeping your arms straight, shrug your shoulders up towards your ears.\",\"Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0220.webp\",\"gif\":\"0220.mp4\",\"cat\":\"strength\",\"desc\":\"A cable shrug with the arms hanging in front. You lift the shoulders toward the ears to train the traps.\",\"fv\":\"2579\"},{\"id\":\"0222\",\"n\":\"cable side bend\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart and grasp the cable handle with one hand.\",\"Keep your back straight and your core engaged.\",\"Slowly bend sideways at the waist, lowering the cable handle towards your knee.\",\"Pause for a moment, then return to the starting position.\",\"Repeat on the other side.\",\"Alternate sides for the desired number of repetitions.\"],\"img\":\"0222.webp\",\"gif\":\"0222.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable side bend, lowering the handle toward the knee. It trains the obliques and the side of the waist.\",\"fv\":\"2576\"},{\"id\":\"0221\",\"n\":\"cable side bend crunch (bosu ball)\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a cable handle in one hand.\",\"Place the other hand on your hip.\",\"Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.\",\"Pause for a moment at the bottom of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0221.webp\",\"gif\":\"0221.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm cable side bend. You bend sideways against the cable to work the obliques and the abs.\"},{\"id\":\"0223\",\"n\":\"cable side crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Attach a cable handle to a low pulley and stand sideways to the machine.\",\"Grasp the handle with the hand furthest from the machine and place your other hand on your hip.\",\"Keep your feet shoulder-width apart and your knees slightly bent.\",\"With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0223.webp\",\"gif\":\"0223.mp4\",\"cat\":\"strength\",\"desc\":\"A cable side crunch from a low pulley, bringing the elbow toward the hip. It works the obliques with steady tension.\",\"fv\":\"2577\"},{\"id\":\"1717\",\"n\":\"cable squat row (with rope attachment)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Attach a rope to a cable machine at waist height.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Bend your knees and lower your body into a squat position, keeping your back straight and chest up.\",\"Grasp the rope with an overhand grip, with your hands shoulder-width apart.\",\"Engage your core and pull the rope towards your body, squeezing your shoulder blades together.\",\"Keep your elbows close to your body and continue pulling until your hands reach your chest.\",\"Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1717.webp\",\"gif\":\"1717.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a cable row, using a rope. It trains the lats and legs together.\",\"fv\":\"2550\"},{\"id\":\"1644\",\"n\":\"cable squatting curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a cable handle to the lowest setting on a cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.\",\"Lower your body into a squat position, keeping your back straight and knees behind your toes.\",\"As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.\",\"Pause for a moment at the top of the curl, squeezing your biceps.\",\"Slowly lower the cable handle back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1644.webp\",\"gif\":\"1644.mp4\",\"cat\":\"strength\",\"desc\":\"A curl you perform in a squat position with a cable. The legs hold you low while the biceps curl.\",\"fv\":\"3067\"},{\"id\":\"0224\",\"n\":\"cable standing back wrist curl\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Hold the cable handle with an overhand grip, palms facing down.\",\"Keep your arms straight and your elbows close to your sides.\",\"Slowly curl your wrists upward, bringing the cable handle towards your body.\",\"Pause for a moment at the top, then slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0224.webp\",\"gif\":\"0224.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable wrist curl with the arms hanging behind or at the sides. It builds the forearms and grip.\",\"fv\":\"11301\"},{\"id\":\"1375\",\"n\":\"cable standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"cable\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Hold onto the cable machine handles or attach a cable ankle strap to your ankles.\",\"Raise your heels off the ground by extending your ankles as high as possible.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1375.webp\",\"gif\":\"1375.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise using a cable for resistance. It builds the calves with a steady pull through the whole movement.\"},{\"id\":\"0225\",\"n\":\"cable standing cross-over high reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Attach a D-handle to each side of a cable machine at shoulder height.\",\"Stand in the middle of the cable machine with your feet shoulder-width apart.\",\"Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.\",\"Keep a slight bend in your elbows and maintain a straight back throughout the exercise.\",\"Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.\",\"Pause for a moment at the peak of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0225.webp\",\"gif\":\"0225.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable reverse fly that crosses over at the end. You open the arms out and back to hit the rear delts and upper back.\"},{\"id\":\"0226\",\"n\":\"cable standing crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Attach a cable handle to a high pulley and stand facing away from the machine.\",\"Hold the handle with both hands and place it behind your head, keeping your elbows bent.\",\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.\",\"Pause for a moment at the bottom of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0226.webp\",\"gif\":\"0226.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable crunch with the rope held behind the head. You round the torso down toward the knees to work the abs.\",\"fv\":\"2578\"},{\"id\":\"0874\",\"n\":\"cable standing crunch (with rope attachment)\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Attach a rope to a cable machine at chest height.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Hold the rope with both hands and bring it behind your head, keeping your elbows bent.\",\"Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.\",\"Pause for a moment at the top of the crunch, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0874.webp\",\"gif\":\"0874.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable crunch with a rope held behind the head, curling the torso forward. It strengthens the abs.\",\"fv\":\"2674\"},{\"id\":\"0227\",\"n\":\"cable standing fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Attach the handles to the cables at chest height.\",\"Stand with your feet shoulder-width apart, facing away from the cable machine.\",\"Grasp the handles with an overhand grip, palms facing forward.\",\"Step forward slightly to create tension in the cables.\",\"Keep your core engaged and your back straight throughout the exercise.\",\"With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.\",\"Squeeze your chest muscles at the peak of the movement.\",\"Slowly reverse the movement, returning your arms to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0227.webp\",\"gif\":\"0227.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable fly where you bring the handles together in front of the chest. It trains the pecs with constant tension.\"},{\"id\":\"0228\",\"n\":\"cable standing hip extension\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Attach a cable to a low pulley and stand facing away from the machine.\",\"Place the cable around your ankle and stand with your feet shoulder-width apart.\",\"Keep your core engaged and your back straight throughout the exercise.\",\"Slowly extend your leg straight back, squeezing your glutes at the top of the movement.\",\"Pause for a moment, then return to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch sides and repeat with the other leg.\"],\"img\":\"0228.webp\",\"gif\":\"0228.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable hip extension with an ankle cuff. Kicking the leg back squeezes the glutes, one side at a time.\"},{\"id\":\"0229\",\"n\":\"cable standing inner curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Grasp the cable handle with an underhand grip, palms facing up.\",\"Keep your elbows close to your sides and your upper arms stationary.\",\"Exhale and curl the cable handle towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0229.webp\",\"gif\":\"0229.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable curl with the palms facing up. Keep the elbows close and curl for a strong biceps contraction.\",\"fv\":\"2580\"},{\"id\":\"0230\",\"n\":\"cable standing lift\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Hold the cable handle with both hands and position it at waist height.\",\"Engage your core and maintain a straight back throughout the exercise.\",\"Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.\",\"Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0230.webp\",\"gif\":\"0230.mp4\",\"cat\":\"strength\",\"desc\":\"A cable lift that sweeps the handle up and across the body with a rotating torso. It builds twisting core strength.\"},{\"id\":\"0231\",\"n\":\"cable standing one arm triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, facing the cable machine.\",\"Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.\",\"Keep your elbow stationary and close to your body.\",\"Slowly bend your elbow, lowering the cable handle towards the back of your head.\",\"Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm.\"],\"img\":\"0231.webp\",\"gif\":\"0231.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable triceps extension from a standing position. You bend and straighten the elbow while keeping the upper arm still.\",\"fv\":\"2696\"},{\"id\":\"1376\",\"n\":\"cable standing one leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"cable\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Hold onto the cable machine for support.\",\"Lift one leg off the ground and balance on the other leg.\",\"Slowly raise your heel off the ground, lifting your body up onto your toes.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"1376.webp\",\"gif\":\"1376.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg standing calf raise using a cable for resistance. It trains each calf separately and helps balance.\"},{\"id\":\"0232\",\"n\":\"cable standing pulldown (with rope)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Attach a rope to the cable machine at the highest setting.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the rope with an overhand grip, palms facing down.\",\"Keep your back straight and core engaged throughout the exercise.\",\"Pull the rope down towards your thighs, squeezing your biceps.\",\"Pause for a moment at the bottom, then slowly release the rope back up.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0232.webp\",\"gif\":\"0232.mp4\",\"cat\":\"strength\",\"desc\":\"A standing rope pulldown from a high pulley, pulling toward the thighs. It trains the arms and the lats.\"},{\"id\":\"0233\",\"n\":\"cable standing rear delt row (with rope)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Stand facing a cable machine with your feet shoulder-width apart.\",\"Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.\",\"Keep your back straight and your core engaged.\",\"Pull the cable towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0233.webp\",\"gif\":\"0233.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable row with a rope or attachment pulled toward the body. It targets the rear delts and upper back.\",\"fv\":\"2882\"},{\"id\":\"1727\",\"n\":\"cable standing reverse grip one arm overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand facing away from the cable machine with your feet shoulder-width apart.\",\"Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.\",\"Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.\",\"Pause for a moment at the bottom, then extend your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1727.webp\",\"gif\":\"1727.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm overhead triceps extension with a reverse grip. It trains the triceps, long head included.\"},{\"id\":\"0234\",\"n\":\"cable standing row (v-bar)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the v-bar attachment with an overhand grip, palms facing down.\",\"Keep your back straight and your core engaged.\",\"Pull the v-bar towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0234.webp\",\"gif\":\"0234.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable row with a v-bar. You pull toward your torso and squeeze the shoulder blades together.\"},{\"id\":\"0235\",\"n\":\"cable standing shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"trapezius\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Hold the cable handle with your arm extended in front of you, parallel to the ground.\",\"Keep your elbow slightly bent and your shoulder blades pulled back.\",\"Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0235.webp\",\"gif\":\"0235.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable external rotation. The forearm turns outward while the elbow stays fixed, strengthening the rotator cuff.\",\"fv\":\"2675\"},{\"id\":\"0236\",\"n\":\"cable standing twist row (v-bar)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Attach a v-bar attachment to a cable machine at chest height.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the v-bar with an overhand grip, palms facing down.\",\"Take a step back to create tension in the cable.\",\"Keep your back straight and core engaged throughout the exercise.\",\"Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.\",\"As you pull, twist your torso to one side, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, feeling the contraction in your upper back.\",\"Slowly release the tension and return to the starting position, untwisting your torso.\",\"Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep.\"],\"img\":\"0236.webp\",\"gif\":\"0236.mp4\",\"cat\":\"strength\",\"desc\":\"A standing v-bar cable row with a twist. You pull and rotate the torso a little to work the upper back and the core.\"},{\"id\":\"1269\",\"n\":\"cable standing up straight crossovers\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Stand in the middle of a cable machine with your feet shoulder-width apart.\",\"Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.\",\"Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.\",\"Pause for a moment, then slowly return to the starting position, keeping your arms extended.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1269.webp\",\"gif\":\"1269.mp4\",\"cat\":\"strength\",\"desc\":\"Standing cable crossovers with the hands crossing in front. It trains the chest.\",\"fv\":\"2387\"},{\"id\":\"0238\",\"n\":\"cable straight arm pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Attach a straight bar to the high pulley of a cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.\",\"Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.\",\"Pause for a moment at the bottom, then slowly return the bar to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0238.webp\",\"gif\":\"0238.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pulldown with a bar on a high pulley. Sweeping the bar to the thighs isolates the lats.\"},{\"id\":\"0237\",\"n\":\"cable straight arm pulldown (with rope)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Attach a rope to the cable machine at the highest setting.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the rope with both hands, palms facing down.\",\"Extend your arms fully in front of you, keeping your elbows slightly bent.\",\"Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.\",\"Pause for a moment at the bottom, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0237.webp\",\"gif\":\"0237.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pulldown with a rope from a high pulley. Keep the arms nearly straight to isolate the lats.\"},{\"id\":\"0239\",\"n\":\"cable straight back seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"shoulders\"],\"st\":[\"Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.\",\"Grasp the cable handles with an overhand grip, palms facing down.\",\"Keep your back straight and lean slightly forward from the hips.\",\"Pull the cable handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0239.webp\",\"gif\":\"0239.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row with a straight back and an overhand grip. It builds the muscles of the mid and upper back.\",\"fv\":\"3069\"},{\"id\":\"0240\",\"n\":\"cable supine reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.\",\"Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.\",\"Keeping your arms straight, raise them out to the sides until they are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0240.webp\",\"gif\":\"0240.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down on a bench, you raise the cable handles out to the sides. It works the rear delts and upper back.\",\"nd\":[\"bench\"]},{\"id\":\"2464\",\"n\":\"cable thibaudeau kayak row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.\",\"Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.\",\"Lean forward from your hips, keeping your back straight and your abs engaged.\",\"Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.\",\"Squeeze your back muscles at the top of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides and perform with your left arm.\"],\"img\":\"2464.webp\",\"gif\":\"2464.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row with a rotating kayak-style pull. Trains the lats and upper back.\"},{\"id\":\"0241\",\"n\":\"cable triceps pushdown (v-bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a v-bar attachment to the cable machine at the highest setting.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.\",\"Pause for a moment at the bottom of the movement, squeezing your triceps.\",\"Inhale as you slowly return the v-bar to the starting position, maintaining control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0241.webp\",\"gif\":\"0241.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps pushdown with a v-bar on a high pulley. The angled grip lets you press hard and squeeze the triceps.\"},{\"id\":\"2405\",\"n\":\"cable triceps pushdown (v-bar) (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a v-bar attachment to the cable machine at the highest setting.\",\"Stand facing the cable machine with your feet shoulder-width apart.\",\"Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary throughout the exercise.\",\"Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.\",\"Pause for a moment at the bottom of the movement, squeezing your triceps.\",\"Inhale as you slowly return the v-bar to the starting position, maintaining control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2405.webp\",\"gif\":\"2405.mp4\",\"cat\":\"strength\",\"desc\":\"A cable pushdown with a v-bar and an arm blaster. Isolates the triceps.\"},{\"id\":\"0242\",\"n\":\"cable tuck reverse crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Attach a cable to a low pulley and lie down on a mat facing up.\",\"Hold the cable with both hands and extend your arms straight up above your chest.\",\"Bend your knees and lift your legs up, bringing your knees towards your chest.\",\"At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.\",\"Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0242.webp\",\"gif\":\"0242.mp4\",\"cat\":\"strength\",\"desc\":\"A cable reverse crunch lying on a mat. You tuck the knees in and curl the hips up to work the lower abs.\"},{\"id\":\"0243\",\"n\":\"cable twist\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart, facing the cable machine.\",\"Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.\",\"Engage your core and twist your torso to the right, pulling the cable across your body.\",\"Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.\",\"Slowly return to the starting position, resisting the cable's pull.\",\"Repeat the movement to the left side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0243.webp\",\"gif\":\"0243.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable twist with the handle held at the chest. You rotate the torso side to side to work the abs and obliques.\",\"fv\":\"2451\"},{\"id\":\"0862\",\"n\":\"cable twist (up-down)\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart, facing the cable machine.\",\"Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.\",\"Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.\",\"Pause for a moment at the end of the rotation, then slowly return to the starting position.\",\"Repeat the rotation to the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0862.webp\",\"gif\":\"0862.mp4\",\"cat\":\"strength\",\"desc\":\"A cable twist that rotates the torso with a handle held at the chest. It trains the obliques and abs.\"},{\"id\":\"0244\",\"n\":\"cable twisting pull\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Attach a cable handle to a low pulley and stand facing the machine.\",\"Grasp the handle with your left hand and step away from the machine, extending your arm fully.\",\"Position your feet shoulder-width apart, with your knees slightly bent.\",\"Keep your back straight and your core engaged throughout the exercise.\",\"Pull the handle towards your body, rotating your torso to the right as you do so.\",\"Squeeze your back muscles at the end of the movement.\",\"Slowly return to the starting position, keeping tension on the cable.\",\"Repeat for the desired number of repetitions, then switch sides and perform with your right hand.\"],\"img\":\"0244.webp\",\"gif\":\"0244.mp4\",\"cat\":\"strength\",\"desc\":\"A cable pull that rotates the torso as you pull the handle toward the body. It trains the lats and the core together.\"},{\"id\":\"1645\",\"n\":\"cable two arm curl on incline bench\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an incline bench with your back against the pad and your feet flat on the ground.\",\"Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the handles back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1645.webp\",\"gif\":\"1645.mp4\",\"cat\":\"strength\",\"desc\":\"A two-arm cable curl on an incline bench. The incline puts the biceps in a stretched position.\"},{\"id\":\"1728\",\"n\":\"cable two arm tricep kickback\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.\",\"Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1728.webp\",\"gif\":\"1728.mp4\",\"cat\":\"strength\",\"desc\":\"A two-arm triceps kickback with cables. It gives constant tension to the triceps.\",\"fv\":\"3070\"},{\"id\":\"0245\",\"n\":\"cable underhand pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the cable machine so that the pulldown bar is at a height above your head.\",\"Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your back straight and lean back slightly.\",\"Pull the bar down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0245.webp\",\"gif\":\"0245.mp4\",\"cat\":\"strength\",\"desc\":\"A cable pulldown with an underhand grip. You pull the bar to the chest, which brings the biceps in along with the lats.\"},{\"id\":\"1270\",\"n\":\"cable upper chest crossovers\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Attach the handles to the cables at chest height.\",\"Stand in the center of the cable machine with one foot slightly in front of the other.\",\"Grasp the handles with your palms facing down and your arms extended out to the sides.\",\"Keep a slight bend in your elbows and engage your core.\",\"Pull the cables together in front of your chest, crossing them over each other.\",\"Squeeze your chest muscles at the peak of the movement.\",\"Slowly release the cables back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1270.webp\",\"gif\":\"1270.mp4\",\"cat\":\"strength\",\"desc\":\"Cable crossovers aimed at the upper chest. It trains the upper pecs.\",\"fv\":\"2442\"},{\"id\":\"1324\",\"n\":\"cable upper row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Attach a straight bar to a cable machine at chest height.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your back straight and your core engaged.\",\"Pull the bar towards your upper chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement.\",\"Slowly release the bar back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1324.webp\",\"gif\":\"1324.mp4\",\"cat\":\"strength\",\"desc\":\"A cable row with a straight bar pulled toward your upper chest. It targets the upper back and rear shoulders.\"},{\"id\":\"0246\",\"n\":\"cable upright row\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.\",\"Keep your back straight and your core engaged throughout the exercise.\",\"Pull the cable attachment straight up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, squeezing your shoulder blades together.\",\"Slowly lower the cable attachment back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0246.webp\",\"gif\":\"0246.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row using a cable. You pull the handle up toward the chin, leading with the elbows, to work the shoulders and traps.\",\"fv\":\"2232\"},{\"id\":\"1325\",\"n\":\"cable wide grip rear pulldown behind neck\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the cable machine so that the pulldown bar is at a height above your head.\",\"Sit down on the seat and grab the pulldown bar with a wide overhand grip.\",\"Keep your back straight and your chest up as you lean back slightly.\",\"Pull the bar down towards your upper chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1325.webp\",\"gif\":\"1325.mp4\",\"cat\":\"strength\",\"desc\":\"A wide grip pulldown where the bar travels behind your neck. It works the lats and upper back but needs good shoulder mobility and control.\"},{\"id\":\"0247\",\"n\":\"cable wrist curl\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Attach a straight bar to a low pulley cable machine.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Rest your forearms on a bench or pad, with your wrists hanging off the edge.\",\"Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.\",\"Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0247.webp\",\"gif\":\"0247.mp4\",\"cat\":\"strength\",\"desc\":\"A cable wrist curl with the forearms resting on a pad. It builds the muscles on the palm side of the forearm.\"},{\"id\":\"1407\",\"n\":\"calf push stretch with hands against wall\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Stand facing a wall with your feet hip-width apart.\",\"Place your hands against the wall at shoulder height.\",\"Step back with one foot, keeping your heel on the ground and your leg straight.\",\"Bend your front knee slightly and lean forward, feeling a stretch in your calf.\",\"Hold the stretch for 20-30 seconds.\",\"Switch legs and repeat the stretch.\"],\"img\":\"1407.webp\",\"gif\":\"1407.mp4\",\"cat\":\"stretching\",\"desc\":\"Stand facing a wall with your hands on it and push your heel down on the back leg. It stretches the calf of the back leg.\"},{\"id\":\"1377\",\"n\":\"calf stretch with hands against wall\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Stand facing a wall with your feet hip-width apart.\",\"Place your hands against the wall at shoulder height.\",\"Step your right foot back, keeping your heel on the ground and your leg straight.\",\"Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.\",\"Hold the stretch for 20-30 seconds.\",\"Switch legs and repeat the stretch.\"],\"img\":\"1377.webp\",\"gif\":\"1377.mp4\",\"cat\":\"stretching\",\"desc\":\"Stand facing a wall and place your hands on it, one foot back with heel down. It stretches the calf of the back leg.\"},{\"id\":\"1378\",\"n\":\"calf stretch with rope\",\"bp\":\"lower legs\",\"eq\":\"rope\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Stand facing a wall or sturdy object with your feet hip-width apart.\",\"Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.\",\"Step back with your left foot, keeping your heel on the ground and your leg straight.\",\"Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.\",\"Hold the stretch for 20-30 seconds, then release.\",\"Repeat on the other leg.\"],\"img\":\"1378.webp\",\"gif\":\"1378.mp4\",\"cat\":\"stretching\",\"desc\":\"A calf stretch where you use a rope to help pull your toes toward you. It stretches the calf and the back of the lower leg.\",\"fv\":\"4277\"},{\"id\":\"0248\",\"n\":\"cambered bar lying row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.\",\"Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.\",\"Pull the barbell towards your chest, squeezing your shoulder blades together.\",\"Lower the barbell back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0248.webp\",\"gif\":\"0248.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell row done lying face down on a bench. The bench removes lower back strain so the upper back does the pulling.\",\"nd\":[\"bench\"],\"fv\":\"5267\"},{\"id\":\"2963\",\"n\":\"captains chair straight leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.\",\"Keep your upper body stable and your back straight.\",\"Engage your abs and lift your legs up in front of you, keeping them straight.\",\"Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2963.webp\",\"gif\":\"2963.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A straight leg raise on a captain's chair, lifting your legs in front of you. Works the abs and hip flexors.\",\"fv\":\"4614\"},{\"id\":\"1548\",\"n\":\"chair leg extended stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"calves\"],\"st\":[\"Sit on the edge of a chair with your back straight and feet flat on the ground.\",\"Extend one leg straight out in front of you, keeping your heel on the ground.\",\"Lean forward slightly, feeling a stretch in your quadriceps.\",\"Hold this position for 20-30 seconds.\",\"Switch legs and repeat the stretch.\"],\"img\":\"1548.webp\",\"gif\":\"1548.mp4\",\"cat\":\"stretching\",\"desc\":\"Using a chair for support, you extend one leg to stretch the thigh and hip. It loosens up the quads.\"},{\"id\":\"1271\",\"n\":\"chest and front of shoulder stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\"],\"st\":[\"Stand tall with your feet shoulder-width apart.\",\"Extend your arms straight out in front of you at shoulder height.\",\"Cross your arms in front of your body, with your right arm on top of your left arm.\",\"Interlace your fingers and press your palms together.\",\"Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.\",\"Hold the stretch for 20-30 seconds, then release.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1271.webp\",\"gif\":\"1271.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the chest and the fronts of the shoulders with the hands clasped. It loosens the chest.\"},{\"id\":\"0251\",\"n\":\"chest dip\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Position yourself on parallel bars with your arms fully extended and your body straight.\",\"Lower your body by bending your elbows until your shoulders are below your elbows.\",\"Push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0251.webp\",\"gif\":\"0251.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight dip with a forward lean on parallel bars. It targets the lower chest, triceps and shoulders.\",\"fv\":\"3599\"},{\"id\":\"1430\",\"n\":\"chest dip (on dip-pull-up cage)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the dip bars to a height that allows you to comfortably grip them.\",\"Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.\",\"Jump up and straighten your arms, supporting your body weight on the bars.\",\"Bend your knees and cross your ankles behind you.\",\"Lower your body by bending your elbows, keeping your chest up and your shoulders down.\",\"Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.\",\"Push through your palms and extend your elbows to raise your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1430.webp\",\"gif\":\"1430.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chest dip done on a dip station with a forward lean. It works the lower chest, triceps and front shoulders.\"},{\"id\":\"2462\",\"n\":\"chest dip on straight bar\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Grab the parallel bars with your palms facing down and your arms fully extended.\",\"Bend your knees and cross your ankles.\",\"Lower your body by bending your arms until your shoulders are below your elbows.\",\"Push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2462.webp\",\"gif\":\"2462.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chest dip on a bar, leaning forward and crossing your ankles. Targets the chest and triceps.\"},{\"id\":\"1272\",\"n\":\"chest stretch with exercise ball\",\"bp\":\"chest\",\"eq\":\"stability ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your back straight.\",\"Hold the exercise ball with both hands and extend your arms straight out in front of you.\",\"Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.\",\"Hold the stretch for a few seconds, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1272.webp\",\"gif\":\"1272.mp4\",\"cat\":\"stretching\",\"desc\":\"A chest stretch using an exercise ball held out in front. It loosens the chest.\"},{\"id\":\"3216\",\"n\":\"chest tap push-up (male)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.\",\"Lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"As you lower yourself, tap your chest with your right hand.\",\"Push yourself back up to the starting position.\",\"Repeat the movement, this time tapping your chest with your left hand.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3216.webp\",\"gif\":\"3216.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where one hand taps the chest at the bottom of each rep, alternating sides. It adds a stability challenge to the chest and triceps.\"},{\"id\":\"1326\",\"n\":\"chin-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.\",\"Engage your core and pull your body up towards the bar, leading with your chest.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1326.webp\",\"gif\":\"1326.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hang from a bar with an underhand grip and pull until your chin clears it. A classic builder of the lats and biceps.\",\"fv\":\"2379\"},{\"id\":\"0253\",\"n\":\"chin-ups (narrow parallel grip)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.\",\"Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0253.webp\",\"gif\":\"0253.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up on a bar with a narrow parallel grip and the palms facing in. It works the lats, upper back and biceps.\",\"fv\":\"3600\"},{\"id\":\"0257\",\"n\":\"circles knee stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Stand with your feet shoulder-width apart and your hands on your hips.\",\"Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.\",\"Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.\",\"Perform the movement for the desired number of repetitions.\"],\"img\":\"0257.webp\",\"gif\":\"0257.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing knee circle drill with the heels lifted. It warms up the knees and calves and can ease tight lower legs.\",\"fv\":\"3932\"},{\"id\":\"1273\",\"n\":\"clap push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart.\",\"Lower your body towards the ground by bending your elbows, keeping your core engaged.\",\"Push through your palms explosively to propel your body off the ground.\",\"While in mid-air, clap your hands together before landing back in the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1273.webp\",\"gif\":\"1273.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive push-up with a clap in mid-air. It builds power in the chest, shoulders and triceps.\"},{\"id\":\"0258\",\"n\":\"clock push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line.\",\"Lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"As you lower, rotate your body to the left, extending your left arm straight out to the side.\",\"Push back up to the starting position, while rotating your body to the center.\",\"Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.\",\"Continue alternating sides with each repetition.\"],\"img\":\"0258.webp\",\"gif\":\"0258.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up that moves around like a clock, with an arm reaching out to the side on each rep. It works the chest, shoulders and core.\"},{\"id\":\"1327\",\"n\":\"close grip chin-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your feet off the ground.\",\"Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1327.webp\",\"gif\":\"1327.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up with your hands close together on an underhand grip. It works the lats and puts extra load on the biceps.\",\"fv\":\"2382\"},{\"id\":\"0259\",\"n\":\"close-grip push-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands placed close together, directly under your shoulders.\",\"Engage your core and lower your body towards the ground, keeping your elbows close to your sides.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0259.webp\",\"gif\":\"0259.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the hands placed close together under the chest. It shifts more of the load onto the triceps.\",\"fv\":\"2615\"},{\"id\":\"2398\",\"n\":\"close-grip push-up (on knees)\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.\",\"Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.\",\"Pause for a moment when your chest is just above the ground.\",\"Push through your palms to straighten your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2398.webp\",\"gif\":\"2398.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A close-grip push-up done on your knees. An easier way to train the triceps and chest.\",\"fv\":\"2613\"},{\"id\":\"0260\",\"n\":\"cocoons\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0260.webp\",\"gif\":\"0260.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor ab move where you curl the upper body up while lying on your back. It targets the abs with controlled crunching.\",\"fv\":\"2582\"},{\"id\":\"1468\",\"n\":\"crab twist toe touch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Start by sitting on the ground with your knees bent and feet flat on the floor.\",\"Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.\",\"Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.\",\"Return to the starting position and repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1468.webp\",\"gif\":\"1468.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a crab position you twist and reach one hand to the opposite foot. It works the abs and obliques and gets the shoulders moving.\"},{\"id\":\"0262\",\"n\":\"cross body crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat on the other side, bringing your left elbow towards your right knee.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0262.webp\",\"gif\":\"0262.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where you rotate to bring one elbow toward the opposite knee. It targets the abs and the obliques.\"},{\"id\":\"0267\",\"n\":\"crunch (hands overhead)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Extend your arms straight above your head.\",\"Engaging your abs, lift your upper body off the ground, curling forward towards your knees.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0267.webp\",\"gif\":\"0267.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with the arms stretched overhead. Reaching long makes the move harder and works the abs.\"},{\"id\":\"0271\",\"n\":\"crunch (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.\",\"Place your hands behind your head or across your chest.\",\"Engage your abs and lift your upper body towards your knees, curling your torso forward.\",\"Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0271.webp\",\"gif\":\"0271.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch done on a stability ball. The ball adds a wider range and demands balance, working the abs.\",\"fv\":\"2701\"},{\"id\":\"0272\",\"n\":\"crunch (on stability ball, arms straight)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0272.webp\",\"gif\":\"0272.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A stability ball crunch with the arms held straight. The extended arms make it harder for the abs.\"},{\"id\":\"0274\",\"n\":\"crunch floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engage your abs and lift your shoulders off the ground, curling forward towards your knees.\",\"Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0274.webp\",\"gif\":\"0274.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A basic floor crunch. You curl the shoulders off the ground to work the upper abs.\"},{\"id\":\"3016\",\"n\":\"curl-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3016.webp\",\"gif\":\"3016.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A curl-up lifting your shoulders off the floor. Works the abs.\",\"fv\":\"3015\"},{\"id\":\"3769\",\"n\":\"curtsey squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.\",\"Bend both knees as if you were curtsying, lowering your body towards the ground.\",\"Keep your torso upright and your weight on your front foot.\",\"Push through your front foot to return to the starting position.\",\"Repeat on the other side, stepping diagonally behind and across your body with your left foot.\"],\"img\":\"3769.webp\",\"gif\":\"3769.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat where the leg steps diagonally behind and across the body, like a curtsy. It trains the glutes and outer thighs.\",\"fv\":\"5177\"},{\"id\":\"2331\",\"n\":\"cycle cross trainer\",\"bp\":\"cardio\",\"eq\":\"leverage machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the seat height and position yourself on the cycle cross trainer.\",\"Place your feet on the pedals and grip the handlebars.\",\"Start pedaling in a smooth and controlled motion.\",\"Maintain a steady pace and increase the resistance if desired.\",\"Continue pedaling for the desired duration of your cardio workout.\"],\"img\":\"2331.webp\",\"gif\":\"2331.mp4\",\"cat\":\"cardio\",\"desc\":\"Pedalling a cycle cross trainer with arms and legs moving together. Steady, low-impact cardio.\"},{\"id\":\"0276\",\"n\":\"dead bug\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your arms extended towards the ceiling.\",\"Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.\",\"Engage your core and lower back to press your lower back into the ground.\",\"Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.\",\"Pause for a moment, then return to the starting position.\",\"Repeat the movement with your left arm and right leg.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0276.webp\",\"gif\":\"0276.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A core drill where you extend opposite arm and leg while keeping the lower back pressed to the floor. It builds stability in the abs.\",\"fv\":\"3071\"},{\"id\":\"0277\",\"n\":\"decline crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.\",\"Place your hands behind your head or across your chest.\",\"Engage your abs and lift your upper body towards your knees, curling your torso.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0277.webp\",\"gif\":\"0277.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch performed on a decline bench with the feet secured. The slope adds resistance for the abs.\",\"fv\":\"2450\"},{\"id\":\"0279\",\"n\":\"decline push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.\",\"Keep your body in a straight line from head to toe, engaging your core muscles.\",\"Lower your chest towards the ground by bending your elbows, keeping them close to your body.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0279.webp\",\"gif\":\"0279.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the feet raised on a surface. The incline puts more load on the upper chest and shoulders.\",\"fv\":\"0280\"},{\"id\":\"0282\",\"n\":\"decline sit-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie on a decline bench with your feet secured and your knees bent.\",\"Place your hands behind your head or across your chest.\",\"Engage your abs and lift your upper body off the bench, curling forward towards your knees.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0282.webp\",\"gif\":\"0282.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up on a decline bench with the feet secured. The slope makes it harder and works the abs and hip flexors.\",\"fv\":\"2449\"},{\"id\":\"1274\",\"n\":\"deep push up\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.\",\"Lower your chest towards the ground by bending your elbows, keeping them close to your body.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1274.webp\",\"gif\":\"1274.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep push-up with a longer range of motion. It trains the chest, shoulders and triceps.\",\"fv\":\"2823\"},{\"id\":\"0283\",\"n\":\"diamond push-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.\",\"Keep your body in a straight line from head to toe, engaging your core and glutes.\",\"Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0283.webp\",\"gif\":\"0283.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the hands forming a diamond under the chest. It puts heavy focus on the triceps.\",\"fv\":\"2697\"},{\"id\":\"0284\",\"n\":\"donkey calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your toes on an elevated surface, such as a step or block.\",\"Place your hands on a stable support, such as a wall or railing, for balance.\",\"Raise your heels as high as possible, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0284.webp\",\"gif\":\"0284.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A donkey calf raise with the toes on a raised surface. You lift and lower the heels through a full range to work the calves.\",\"fv\":\"2677\"},{\"id\":\"1275\",\"n\":\"drop push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart.\",\"Lower your chest towards the ground, keeping your elbows close to your body.\",\"Once your chest is just above the ground, quickly drop your knees to the ground.\",\"Push yourself back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1275.webp\",\"gif\":\"1275.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push-up that drops to the knees and presses back up. It trains the chest and triceps.\"},{\"id\":\"0285\",\"n\":\"dumbbell alternate biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions, alternating arms.\"],\"img\":\"0285.webp\",\"gif\":\"0285.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell curl that alternates arms. Each rep isolates the biceps through a full range.\",\"fv\":\"2584\"},{\"id\":\"2403\",\"n\":\"dumbbell alternate biceps curl (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.\",\"Place the arm blaster on your upper arms, ensuring a secure fit.\",\"Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the movement with the opposite arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"2403.webp\",\"gif\":\"2403.mp4\",\"cat\":\"strength\",\"desc\":\"An alternating dumbbell curl with an arm blaster. Keeps your upper arms fixed so the biceps do the work.\"},{\"id\":\"1646\",\"n\":\"dumbbell alternate hammer preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.\",\"Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the recommended amount of repetitions.\"],\"img\":\"1646.webp\",\"gif\":\"1646.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating hammer curls on a preacher bench. It builds the brachialis and the biceps with strict form.\",\"fv\":\"2641\"},{\"id\":\"1647\",\"n\":\"dumbbell alternate preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with a dumbbell in each hand, palms facing up.\",\"Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.\",\"Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.\",\"Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the movement with your left arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"1647.webp\",\"gif\":\"1647.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating dumbbell curls on a preacher bench. It builds the biceps with no momentum.\",\"fv\":\"2642\"},{\"id\":\"1648\",\"n\":\"dumbbell alternate seated hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.\",\"Keep your back straight and your elbows close to your torso.\",\"Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the movement with your left arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"1648.webp\",\"gif\":\"1648.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating hammer curls while seated. The neutral grip trains the brachialis and forearms.\",\"fv\":\"2643\"},{\"id\":\"0286\",\"n\":\"dumbbell alternate side press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.\",\"Press one dumbbell overhead while keeping the other dumbbell at shoulder height.\",\"Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0286.webp\",\"gif\":\"0286.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell shoulder press that alternates arms. One arm presses overhead while the other stays at the shoulder.\",\"fv\":\"2592\"},{\"id\":\"1649\",\"n\":\"dumbbell alternating bicep curl with leg raised on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.\",\"Place an exercise ball behind you and position one foot on top of it, keeping your balance.\",\"With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.\",\"Lower the dumbbell back down to the starting position and repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"1649.webp\",\"gif\":\"1649.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating dumbbell curls with one leg lifted while sitting on an exercise ball. It trains the biceps and challenges balance.\"},{\"id\":\"1650\",\"n\":\"dumbbell alternating seated bicep curl on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the curl with the other arm.\",\"Continue alternating curls for the desired number of repetitions.\"],\"img\":\"1650.webp\",\"gif\":\"1650.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating dumbbell curls seated on an exercise ball. It trains the biceps while the core keeps you upright.\",\"fv\":\"2698\"},{\"id\":\"2137\",\"n\":\"dumbbell arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.\",\"Press the dumbbells upward until your arms are fully extended and your palms are facing forward.\",\"Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2137.webp\",\"gif\":\"2137.mp4\",\"cat\":\"strength\",\"desc\":\"A seated dumbbell press that rotates the palms from facing you to facing forward as you lift. Hits all three heads of the shoulder.\",\"fv\":\"2386\"},{\"id\":\"0287\",\"n\":\"dumbbell arnold press v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.\",\"Press the dumbbells upward until your arms are fully extended and your palms are facing forward.\",\"Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0287.webp\",\"gif\":\"0287.mp4\",\"cat\":\"strength\",\"desc\":\"A seated Arnold press variation. You rotate the palms as you press, working all heads of the shoulder.\"},{\"id\":\"0288\",\"n\":\"dumbbell around pullover\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"latissimus dorsi\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet firmly on the ground.\",\"Hold a dumbbell with both hands and extend your arms straight above your chest.\",\"Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.\",\"Pause for a moment at the bottom, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0288.webp\",\"gif\":\"0288.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell pullover done in a wide arc lying on a bench. It stretches and trains the chest and lats.\",\"nd\":[\"bench\"]},{\"id\":\"0289\",\"n\":\"dumbbell bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.\",\"Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.\",\"Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0289.webp\",\"gif\":\"0289.mp4\",\"cat\":\"strength\",\"desc\":\"The classic dumbbell press on a flat bench. It builds the chest, shoulders and triceps with a good range of motion.\",\"fv\":\"2254\"},{\"id\":\"0290\",\"n\":\"dumbbell bench seated press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, resting on your thighs.\",\"Lean back and position the dumbbells to the sides of your chest, palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0290.webp\",\"gif\":\"0290.mp4\",\"cat\":\"strength\",\"desc\":\"A seated dumbbell press on a bench with back support. It targets the shoulders and the triceps.\"},{\"id\":\"0291\",\"n\":\"dumbbell bench squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Place a dumbbell on the ground in front of a bench.\",\"Stand facing away from the bench with your feet shoulder-width apart.\",\"Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.\",\"Once your glutes touch the bench, push through your heels to stand back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0291.webp\",\"gif\":\"0291.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell squat to a bench. Touching the bench gives a consistent depth and works the glutes and thighs.\",\"fv\":\"2217\"},{\"id\":\"0293\",\"n\":\"dumbbell bent over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.\",\"Bend forward at the hips, keeping your back straight and your core engaged.\",\"Let your arms hang straight down towards the floor, with your elbows slightly bent.\",\"Pull the dumbbells up towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0293.webp\",\"gif\":\"0293.mp4\",\"cat\":\"strength\",\"desc\":\"A two-arm dumbbell row done bent over. You pull the weights to the chest to build the upper back.\",\"fv\":\"2482\"},{\"id\":\"1651\",\"n\":\"dumbbell bicep curl lunge with bowling motion\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.\",\"Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.\",\"As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.\",\"At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.\",\"Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.\",\"Repeat the lunge and curl motion, this time rotating your torso to the left.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1651.webp\",\"gif\":\"1651.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge combined with a bicep curl in a bowling-style motion. It trains the biceps, glutes and legs together.\"},{\"id\":\"1652\",\"n\":\"dumbbell bicep curl on exercise ball with leg raised\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.\",\"Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.\",\"Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.\",\"While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1652.webp\",\"gif\":\"1652.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl on an exercise ball with one leg raised. It trains the biceps while testing balance.\"},{\"id\":\"1653\",\"n\":\"dumbbell bicep curl with stork stance\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.\",\"Extend one leg behind you, balancing on the toes of that foot.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1653.webp\",\"gif\":\"1653.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl while balancing on one leg in a stork stance. It trains the biceps and balance.\"},{\"id\":\"0294\",\"n\":\"dumbbell biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0294.webp\",\"gif\":\"0294.mp4\",\"cat\":\"strength\",\"desc\":\"The standard standing dumbbell biceps curl. You curl both weights up while keeping the upper arms still.\",\"fv\":\"2483\"},{\"id\":\"2401\",\"n\":\"dumbbell biceps curl (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward.\",\"Keep your elbows close to your torso and your upper arms stationary.\",\"Exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2401.webp\",\"gif\":\"2401.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell curl with an arm blaster to keep your upper arms still. Isolates the biceps.\",\"fv\":\"3074\"},{\"id\":\"1654\",\"n\":\"dumbbell biceps curl reverse\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1654.webp\",\"gif\":\"1654.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl using an overhand grip. It trains the brachialis and forearms along with the biceps.\",\"fv\":\"2644\"},{\"id\":\"1655\",\"n\":\"dumbbell biceps curl squat\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.\",\"Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1655.webp\",\"gif\":\"1655.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a dumbbell curl. It works the legs and biceps in one move.\"},{\"id\":\"1656\",\"n\":\"dumbbell biceps curl v sit on bosu ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1656.webp\",\"gif\":\"1656.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell biceps curl while sitting on a bosu ball with your legs in a V. It trains the biceps and the core.\"},{\"id\":\"1201\",\"n\":\"dumbbell burpee\",\"bp\":\"cardio\",\"eq\":\"dumbbell\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.\",\"Lower your body into a squat position, placing the dumbbells on the ground in front of you.\",\"Kick your feet back into a push-up position, keeping your body in a straight line.\",\"Perform a push-up, bending your elbows and lowering your chest towards the ground.\",\"Jump your feet back towards your hands, landing in a squat position.\",\"Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.\",\"Press the dumbbells overhead, fully extending your arms.\",\"Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions.\"],\"img\":\"1201.webp\",\"gif\":\"1201.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee with dumbbells that finishes with an overhead press. It builds strength and endurance.\"},{\"id\":\"0295\",\"n\":\"dumbbell clean\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.\",\"Explosively extend your hips and knees, driving through your heels to jump off the ground.\",\"As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.\",\"Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.\",\"Lower the dumbbells back down to the starting position by reversing the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0295.webp\",\"gif\":\"0295.mp4\",\"cat\":\"olympic\",\"desc\":\"A dumbbell clean where you explode up and catch the weights at the shoulders. It builds power in the hips, legs and back.\"},{\"id\":\"1731\",\"n\":\"dumbbell close grip press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a flat bench with a dumbbell in each hand, resting on your thighs.\",\"Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.\",\"Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.\",\"As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.\",\"As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.\",\"After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.\"],\"img\":\"1731.webp\",\"gif\":\"1731.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip dumbbell press. It builds the triceps along with the chest.\",\"fv\":\"3075\"},{\"id\":\"0296\",\"n\":\"dumbbell close-grip press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a flat bench with a dumbbell in each hand, resting on your thighs.\",\"Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.\",\"Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.\",\"As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.\",\"As you exhale, use your triceps to lift the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0296.webp\",\"gif\":\"0296.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip dumbbell press with the weights held together. It places the load on the triceps.\",\"fv\":\"2645\"},{\"id\":\"0297\",\"n\":\"dumbbell concentration curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.\",\"Fully extend your arm and hold the dumbbell with an underhand grip.\",\"Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0297.webp\",\"gif\":\"0297.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm curl with the elbow braced on the inner thigh. The brace stops cheating and focuses on the biceps.\",\"fv\":\"2372\"},{\"id\":\"3635\",\"n\":\"dumbbell contralateral forward lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Take a step forward with your right foot, keeping your back straight and core engaged.\",\"Lower your body by bending both knees until your right thigh is parallel to the ground.\",\"Push through your right heel to return to the starting position.\",\"Repeat with your left leg.\",\"Alternate legs for the desired number of repetitions.\"],\"img\":\"3635.webp\",\"gif\":\"3635.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell lunge stepping forward with the opposite arm movement. It trains the glutes, quads and balance.\"},{\"id\":\"0298\",\"n\":\"dumbbell cross body hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your body.\",\"Keep your elbows close to your torso and your upper arms stationary.\",\"Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0298.webp\",\"gif\":\"0298.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl that crosses the body toward the opposite shoulder. It works the biceps and the brachialis.\"},{\"id\":\"1657\",\"n\":\"dumbbell cross body hammer curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your body.\",\"Keep your elbows close to your torso and your upper arms stationary.\",\"Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1657.webp\",\"gif\":\"1657.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl across the body toward the opposite shoulder, version 2. It hits the brachialis and biceps.\",\"fv\":\"2646\"},{\"id\":\"0299\",\"n\":\"dumbbell cuban press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.\",\"Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.\",\"Rotate your wrists so that your palms are facing forward.\",\"Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0299.webp\",\"gif\":\"0299.mp4\",\"cat\":\"strength\",\"desc\":\"A Cuban press combining an upright row, a rotation and a press. It trains the shoulders and the rotator cuff.\"},{\"id\":\"2136\",\"n\":\"dumbbell cuban press v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.\",\"Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.\",\"Rotate your wrists so that your palms are facing forward.\",\"Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2136.webp\",\"gif\":\"2136.mp4\",\"cat\":\"strength\",\"desc\":\"A cuban press variation with dumbbells that mixes a press and a wrist rotation. Works the shoulders and rotator cuff.\"},{\"id\":\"0300\",\"n\":\"dumbbell deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing forward.\",\"Hold a dumbbell in each hand, palms facing your body, arms extended downwards.\",\"Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.\",\"Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0300.webp\",\"gif\":\"0300.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a dumbbell in each hand. You hinge and stand to work the glutes, hamstrings and back.\",\"fv\":\"2484\"},{\"id\":\"0301\",\"n\":\"dumbbell decline bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie down on a decline bench with your feet secured and your head lower than your hips.\",\"Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.\",\"Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.\",\"Push the dumbbells back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0301.webp\",\"gif\":\"0301.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell press on a decline bench. The angle emphasises the lower chest.\",\"fv\":\"2452\"},{\"id\":\"0302\",\"n\":\"dumbbell decline fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie on a decline bench with your feet secured and your head lower than your hips.\",\"Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.\",\"Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0302.webp\",\"gif\":\"0302.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly on a decline bench. The arms open in a wide arc to stretch and train the lower chest.\"},{\"id\":\"0303\",\"n\":\"dumbbell decline hammer press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your feet secured and your head lower than your hips.\",\"Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.\",\"Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.\",\"Press the dumbbells back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0303.webp\",\"gif\":\"0303.mp4\",\"cat\":\"strength\",\"desc\":\"A decline press with the palms facing each other, using dumbbells. The neutral grip is easier on the shoulders and works the chest.\"},{\"id\":\"1276\",\"n\":\"dumbbell decline one arm fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.\",\"Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.\",\"Rotate your wrist so that the palm of your hand is facing forward.\",\"As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.\",\"Exhale and use your chest muscles to bring the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1276.webp\",\"gif\":\"1276.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a decline bench, you open one arm out to the side with a dumbbell and bring it back over your chest. It works the lower chest one side at a time.\"},{\"id\":\"1617\",\"n\":\"dumbbell decline one arm hammer press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a decline bench with a dumbbell in one hand, resting on your chest.\",\"Extend your arm straight up, keeping your elbow slightly bent.\",\"Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.\",\"Press the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1617.webp\",\"gif\":\"1617.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm press on a decline bench with a neutral grip. It targets the triceps and the lower chest.\"},{\"id\":\"0305\",\"n\":\"dumbbell decline shrug\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rhomboids\"],\"st\":[\"Set up a decline bench at a 45-degree angle.\",\"Lie face down on the bench with your chest and stomach resting against it.\",\"Hold a dumbbell in each hand with your arms fully extended towards the floor.\",\"Keeping your arms straight, raise your shoulders towards your ears as high as possible.\",\"Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0305.webp\",\"gif\":\"0305.mp4\",\"cat\":\"strength\",\"desc\":\"A face-down dumbbell shrug on a decline bench. You raise the shoulders toward the ears to work the traps.\"},{\"id\":\"0304\",\"n\":\"dumbbell decline shrug v. 2\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rhomboids\"],\"st\":[\"Set up a decline bench at a 45-degree angle.\",\"Lie face down on the bench with your chest and stomach resting on it.\",\"Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.\",\"Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.\",\"Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0304.webp\",\"gif\":\"0304.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug performed lying face down on a bench. Pulling the shoulders up trains the traps without the lower back.\"},{\"id\":\"0306\",\"n\":\"dumbbell decline triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.\",\"Extend your arms fully, keeping your elbows close to your head.\",\"Lower the dumbbells slowly behind your head, bending your elbows.\",\"Pause for a moment, then raise the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0306.webp\",\"gif\":\"0306.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell triceps extension on a decline bench. You lower the weights behind the head and extend to work the triceps.\",\"fv\":\"2673\"},{\"id\":\"0307\",\"n\":\"dumbbell decline twist fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Lie down on a decline bench with your head lower than your hips.\",\"Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.\",\"Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\",\"As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.\",\"Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0307.webp\",\"gif\":\"0307.mp4\",\"cat\":\"strength\",\"desc\":\"A decline fly with a twist of the wrists. The rotating action adds a squeeze to the chest.\",\"fv\":\"2585\"},{\"id\":\"1437\",\"n\":\"dumbbell finger curls\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.\",\"Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.\",\"Repeat for the desired number of repetitions, then switch to the other hand.\"],\"img\":\"1437.webp\",\"gif\":\"1437.mp4\",\"cat\":\"strength\",\"desc\":\"Small dumbbell curls where the bar rolls down to your fingertips and back up. A simple way to build finger and forearm grip strength.\",\"fv\":\"3076\"},{\"id\":\"0308\",\"n\":\"dumbbell fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing each other.\",\"Extend your arms straight up over your chest, with a slight bend in your elbows.\",\"Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0308.webp\",\"gif\":\"0308.mp4\",\"cat\":\"strength\",\"desc\":\"The classic flat bench dumbbell fly. The arms open in an arc to stretch and squeeze the chest.\",\"nd\":[\"bench\"],\"fv\":\"2253\"},{\"id\":\"1277\",\"n\":\"dumbbell fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball and hold a dumbbell in each hand.\",\"Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.\",\"Extend your arms straight up above your chest, palms facing each other.\",\"Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1277.webp\",\"gif\":\"1277.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly done lying back on a stability ball. The unstable surface makes your core work while the chest does the opening and closing.\",\"fv\":\"2620\"},{\"id\":\"1732\",\"n\":\"dumbbell forward lunge triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Take a step forward with your right foot, lowering your body into a lunge position.\",\"Keep your back straight and your chest up.\",\"Extend your arms straight overhead, keeping your elbows close to your ears.\",\"Lower the dumbbells behind your head by bending your elbows.\",\"Pause for a moment, then straighten your arms to return to the starting position.\",\"Repeat the movement for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1732.webp\",\"gif\":\"1732.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge combined with a triceps extension. It trains the triceps and legs.\"},{\"id\":\"0310\",\"n\":\"dumbbell front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"trapezius\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.\",\"Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0310.webp\",\"gif\":\"0310.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell front raise. You lift the weights to shoulder height to train the front delts.\",\"fv\":\"2233\"},{\"id\":\"0309\",\"n\":\"dumbbell front raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.\",\"Keep your back straight and engage your core.\",\"Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0309.webp\",\"gif\":\"0309.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell front raise lifting the weights in front to shoulder level. It trains the front delts.\"},{\"id\":\"0311\",\"n\":\"dumbbell full can lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rotator cuff\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.\",\"Keep your back straight and engage your core.\",\"Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0311.webp\",\"gif\":\"0311.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise with the thumbs up, as if holding full cans. It works the side delts and the rotator cuff.\",\"fv\":\"2583\"},{\"id\":\"1760\",\"n\":\"dumbbell goblet squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.\",\"Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1760.webp\",\"gif\":\"1760.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding one dumbbell at your chest. Trains the quads and glutes while keeping your torso upright.\",\"fv\":\"2281\"},{\"id\":\"0313\",\"n\":\"dumbbell hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your torso.\",\"Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\",\"This will be your starting position.\",\"Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Then, inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the recommended amount of repetitions.\"],\"img\":\"0313.webp\",\"gif\":\"0313.mp4\",\"cat\":\"strength\",\"desc\":\"The standard hammer curl with the palms facing in. It trains the brachialis, biceps and forearms.\",\"fv\":\"2239\"},{\"id\":\"1659\",\"n\":\"dumbbell hammer curl on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1659.webp\",\"gif\":\"1659.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl while sitting on an exercise ball. It trains the brachialis, biceps and core.\",\"fv\":\"2647\"},{\"id\":\"0312\",\"n\":\"dumbbell hammer curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your torso.\",\"Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\",\"This will be your starting position.\",\"Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Then, inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the recommended amount of repetitions.\"],\"img\":\"0312.webp\",\"gif\":\"0312.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl with a neutral grip. It works the biceps and the forearms, especially the brachialis.\"},{\"id\":\"2402\",\"n\":\"dumbbell hammer curls (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your torso.\",\"Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\",\"This will be your starting position.\",\"Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Then, inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the recommended amount of repetitions.\"],\"img\":\"2402.webp\",\"gif\":\"2402.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hammer curl with an arm blaster to prevent swinging. Targets the biceps and brachialis.\",\"fv\":\"3077\"},{\"id\":\"1664\",\"n\":\"dumbbell high curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward.\",\"Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1664.webp\",\"gif\":\"1664.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl lifted high toward the shoulder. It trains the peak of the biceps contraction.\"},{\"id\":\"3545\",\"n\":\"dumbbell incline alternate press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, resting on your thighs.\",\"Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.\",\"Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.\",\"Push the dumbbells up with your chest and shoulders, extending your arms fully.\",\"Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.\",\"Repeat for the desired number of repetitions, alternating arms.\"],\"img\":\"3545.webp\",\"gif\":\"3545.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell press on an incline bench, with the arms alternating. It trains the upper chest and shoulders.\"},{\"id\":\"0314\",\"n\":\"dumbbell incline bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.\",\"Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.\",\"Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.\",\"Push the dumbbells back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0314.webp\",\"gif\":\"0314.mp4\",\"cat\":\"strength\",\"desc\":\"An incline dumbbell bench press. The raised bench shifts the work toward the upper chest.\",\"fv\":\"2441\"},{\"id\":\"0315\",\"n\":\"dumbbell incline biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0315.webp\",\"gif\":\"0315.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl performed on an incline bench. The stretched start position gives a good challenge to the biceps.\",\"fv\":\"2493\"},{\"id\":\"0316\",\"n\":\"dumbbell incline breeding\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your back against the pad and feet flat on the ground.\",\"Hold a dumbbell in each hand with an overhand grip, palms facing forward.\",\"Start with your arms fully extended, perpendicular to the ground.\",\"Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.\",\"Pause for a moment at the bottom, then push the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0316.webp\",\"gif\":\"0316.mp4\",\"cat\":\"strength\",\"desc\":\"An incline dumbbell move that lowers the weights to the chest sides and presses up. It targets the upper chest.\"},{\"id\":\"0318\",\"n\":\"dumbbell incline curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.\",\"Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0318.webp\",\"gif\":\"0318.mp4\",\"cat\":\"strength\",\"desc\":\"The incline dumbbell curl. You sit back on an inclined bench and curl up, stretching the biceps at the start.\"},{\"id\":\"0317\",\"n\":\"dumbbell incline curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0317.webp\",\"gif\":\"0317.mp4\",\"cat\":\"strength\",\"desc\":\"An incline dumbbell curl on a bench. Your arms hang behind the body to stretch the biceps.\"},{\"id\":\"0319\",\"n\":\"dumbbell incline fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Set an incline bench to a 45-degree angle.\",\"Sit on the bench with a dumbbell in each hand, palms facing each other.\",\"Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.\",\"Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0319.webp\",\"gif\":\"0319.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly on an incline bench. The arms open in an arc to work the upper chest.\",\"fv\":\"2514\"},{\"id\":\"1278\",\"n\":\"dumbbell incline fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.\",\"Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.\",\"Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1278.webp\",\"gif\":\"1278.mp4\",\"cat\":\"strength\",\"desc\":\"Dumbbell fly with your upper back on an incline bench and your hips supported by a stability ball. It hits the upper chest and challenges balance.\",\"fv\":\"2626\"},{\"id\":\"0320\",\"n\":\"dumbbell incline hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.\",\"Keep your back against the bench and your feet flat on the floor.\",\"While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0320.webp\",\"gif\":\"0320.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl performed sitting back on an incline bench. The neutral grip works the brachialis and biceps.\",\"fv\":\"2494\"},{\"id\":\"0321\",\"n\":\"dumbbell incline hammer press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.\",\"Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.\",\"Press the dumbbells up and away from your body until your arms are fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0321.webp\",\"gif\":\"0321.mp4\",\"cat\":\"strength\",\"desc\":\"An incline press with dumbbells held palms facing each other. The neutral grip focuses on the upper chest and spares the shoulders.\",\"fv\":\"2504\"},{\"id\":\"1618\",\"n\":\"dumbbell incline hammer press on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on an exercise ball with a dumbbell in each hand, palms facing each other.\",\"Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.\",\"Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.\",\"Press the dumbbells up and slightly inward, keeping your palms facing each other.\",\"Extend your arms fully, squeezing your triceps at the top of the movement.\",\"Slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1618.webp\",\"gif\":\"1618.mp4\",\"cat\":\"strength\",\"desc\":\"A neutral-grip press on an incline bench set on an exercise ball. The ball adds an unstable challenge for the triceps.\"},{\"id\":\"0322\",\"n\":\"dumbbell incline inner biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, palms facing each other.\",\"Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0322.webp\",\"gif\":\"0322.mp4\",\"cat\":\"strength\",\"desc\":\"An incline curl that emphasises the inner biceps. The dumbbells curl up from a deep stretch behind the body.\",\"fv\":\"2521\"},{\"id\":\"1279\",\"n\":\"dumbbell incline one arm fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Adjust the incline bench to a 30-45 degree angle.\",\"Sit on the bench with a dumbbell in one hand, resting it on your thigh.\",\"Lie back on the bench, keeping your feet flat on the ground.\",\"Hold the dumbbell with your arm extended straight up over your chest.\",\"Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.\",\"Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1279.webp\",\"gif\":\"1279.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm fly on an incline bench that targets the upper chest. Working one side at a time helps you spot and fix left-right differences.\"},{\"id\":\"1280\",\"n\":\"dumbbell incline one arm fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on an exercise ball with a dumbbell in one hand.\",\"Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.\",\"Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.\",\"Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.\",\"Pause for a moment when your arm is parallel to the ground.\",\"Engage your chest muscles to bring the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1280.webp\",\"gif\":\"1280.mp4\",\"cat\":\"strength\",\"desc\":\"One-arm incline fly with your back supported on a stability ball. The unstable base adds a core challenge to the upper chest stretch.\"},{\"id\":\"1619\",\"n\":\"dumbbell incline one arm hammer press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Sit on an incline bench with a dumbbell in one hand, resting on your thigh.\",\"Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.\",\"Rotate your wrist so that your palm is facing inward, towards your body.\",\"Press the dumbbell up and away from your body, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1619.webp\",\"gif\":\"1619.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm neutral-grip press on an incline bench. It trains the triceps and upper chest on one side at a time.\"},{\"id\":\"1620\",\"n\":\"dumbbell incline one arm hammer press on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Sit on an exercise ball with a dumbbell in one hand.\",\"Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.\",\"Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.\",\"Press the dumbbell up towards the ceiling, straightening your arm.\",\"Lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1620.webp\",\"gif\":\"1620.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm hammer press on an incline with an exercise ball. It works the triceps and adds a balance challenge.\"},{\"id\":\"0323\",\"n\":\"dumbbell incline one arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"triceps\"],\"st\":[\"Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.\",\"Lean forward and position your upper arm against the inside of your thigh.\",\"Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.\",\"Continue lifting until your arm is parallel to the floor.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0323.webp\",\"gif\":\"0323.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm lateral raise on an incline bench. It isolates the side delt, one arm at a time.\",\"fv\":\"2818\"},{\"id\":\"1281\",\"n\":\"dumbbell incline one arm press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an incline bench with a dumbbell in one hand, resting on your thigh.\",\"Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.\",\"Press the dumbbell upward and slightly inward, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1281.webp\",\"gif\":\"1281.mp4\",\"cat\":\"strength\",\"desc\":\"Press a single dumbbell up from shoulder height on an incline bench. It builds the upper chest and shoulders and evens out strength between sides.\"},{\"id\":\"1282\",\"n\":\"dumbbell incline one arm press on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.\",\"Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.\",\"Hold the dumbbell at shoulder height with your palm facing forward.\",\"Press the dumbbell upward until your arm is fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1282.webp\",\"gif\":\"1282.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm dumbbell press done with your upper back on a stability ball. Your core has to stay tight to keep you steady while the chest presses.\"},{\"id\":\"0324\",\"n\":\"dumbbell incline palm-in press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with a dumbbell in each hand, palms facing each other.\",\"Plant your feet firmly on the ground and keep your back straight against the bench.\",\"Start with the dumbbells at shoulder level, elbows bent and palms facing each other.\",\"Press the dumbbells up and away from your body, extending your arms fully.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0324.webp\",\"gif\":\"0324.mp4\",\"cat\":\"strength\",\"desc\":\"An incline dumbbell press with the palms facing in. It works the upper chest and the front shoulders.\",\"fv\":\"2505\"},{\"id\":\"1283\",\"n\":\"dumbbell incline press on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with a dumbbell in each hand, palms facing forward.\",\"Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.\",\"Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.\",\"Press the dumbbells upward, extending your arms fully.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1283.webp\",\"gif\":\"1283.mp4\",\"cat\":\"strength\",\"desc\":\"A two-dumbbell press with your upper back on a stability ball. It trains the chest and shoulders while your core works to keep you balanced.\",\"fv\":\"2627\"},{\"id\":\"0325\",\"n\":\"dumbbell incline raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"triceps\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, resting on your thighs.\",\"Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.\",\"Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0325.webp\",\"gif\":\"0325.mp4\",\"cat\":\"strength\",\"desc\":\"An incline dumbbell raise pressing overhead from shoulder height. It works the shoulders and the triceps.\",\"fv\":\"2516\"},{\"id\":\"0326\",\"n\":\"dumbbell incline rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.\",\"Extend your arms straight down with your palms facing each other.\",\"Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0326.webp\",\"gif\":\"0326.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported rear lateral raise on an incline bench. It isolates the rear delts and the upper back.\"},{\"id\":\"0327\",\"n\":\"dumbbell incline row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Grab a dumbbell in each hand and sit on the bench with your chest against the incline.\",\"Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.\",\"Pull the dumbbells up towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0327.webp\",\"gif\":\"0327.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported dumbbell row on an incline bench. Supporting the chest takes the lower back out of the move.\",\"fv\":\"2510\"},{\"id\":\"0328\",\"n\":\"dumbbell incline shoulder raise\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"serratus anterior\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"trapezius\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.\",\"Rest the dumbbells on your thighs and lean back onto the bench.\",\"Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.\",\"Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0328.webp\",\"gif\":\"0328.mp4\",\"cat\":\"strength\",\"desc\":\"An incline shoulder raise with dumbbells moving overhead. It works the shoulder blades and the serratus anterior.\"},{\"id\":\"0329\",\"n\":\"dumbbell incline shrug\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.\",\"Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.\",\"Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.\",\"Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0329.webp\",\"gif\":\"0329.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug using dumbbells on an incline bench. Lifting the shoulders trains the traps.\",\"fv\":\"3938\"},{\"id\":\"3542\",\"n\":\"dumbbell incline t-raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.\",\"Lean forward and let your arms hang straight down, perpendicular to the floor.\",\"Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a 'T' shape with your body.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3542.webp\",\"gif\":\"3542.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell raise on an incline bench, lifting the arms into a T shape. It trains the rear delts and upper back.\"},{\"id\":\"0330\",\"n\":\"dumbbell incline triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, palms facing inwards.\",\"Extend your arms fully overhead, keeping your elbows close to your head.\",\"Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.\",\"Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0330.webp\",\"gif\":\"0330.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell triceps extension on an incline bench. You lower the weights behind the head and extend to target the triceps.\",\"fv\":\"2507\"},{\"id\":\"0331\",\"n\":\"dumbbell incline twisted flyes\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.\",\"Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.\",\"Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\",\"As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.\",\"Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0331.webp\",\"gif\":\"0331.mp4\",\"cat\":\"strength\",\"desc\":\"An incline fly with a wrist twist at the bottom. The rotation adds a squeeze to the upper chest.\"},{\"id\":\"1733\",\"n\":\"dumbbell incline two arm extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on an incline bench with a dumbbell in each hand, resting on your thighs.\",\"Slowly lie back on the bench, keeping the dumbbells close to your chest.\",\"Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1733.webp\",\"gif\":\"1733.mp4\",\"cat\":\"strength\",\"desc\":\"A two-arm dumbbell triceps extension on an incline bench. It stretches and builds the triceps.\",\"fv\":\"3078\"},{\"id\":\"3541\",\"n\":\"dumbbell incline y-raise\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rear deltoids\"],\"st\":[\"Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.\",\"Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.\",\"Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3541.webp\",\"gif\":\"3541.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell raise on an incline bench, lifting the arms into a Y shape. It trains the lower traps and upper back.\"},{\"id\":\"0332\",\"n\":\"dumbbell iron cross\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\",\"Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.\",\"Pause for a moment, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0332.webp\",\"gif\":\"0332.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell lateral raise to a T position, like an iron cross. It strengthens the delts and the upper back.\",\"fv\":\"3601\"},{\"id\":\"0333\",\"n\":\"dumbbell kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.\",\"Extend your arms straight back, squeezing your triceps at the top of the movement.\",\"Pause for a moment, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0333.webp\",\"gif\":\"0333.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell kickback done in a hinged position. You extend the arms back to isolate the triceps.\",\"fv\":\"2437\"},{\"id\":\"1734\",\"n\":\"dumbbell kickbacks on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.\",\"Extend your arms straight back, squeezing your triceps at the top of the movement.\",\"Pause for a moment, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1734.webp\",\"gif\":\"1734.mp4\",\"cat\":\"strength\",\"desc\":\"Triceps kickbacks on an exercise ball. It isolates the triceps and adds core demand.\"},{\"id\":\"1660\",\"n\":\"dumbbell kneeling bicep curl exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Kneel on the floor with an exercise ball in front of you.\",\"Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.\",\"Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1660.webp\",\"gif\":\"1660.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl while kneeling on an exercise ball. It trains the biceps and demands balance.\"},{\"id\":\"0334\",\"n\":\"dumbbell lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\",\"Keep your back straight and engage your core.\",\"Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0334.webp\",\"gif\":\"0334.mp4\",\"cat\":\"strength\",\"desc\":\"The standard standing dumbbell lateral raise. Lifting the arms out to the sides builds the side delts.\"},{\"id\":\"0335\",\"n\":\"dumbbell lateral to front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.\",\"Keep your back straight and engage your core.\",\"Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0335.webp\",\"gif\":\"0335.mp4\",\"cat\":\"strength\",\"desc\":\"A combination raise that goes out to the side and then to the front. It works all the delts in one move.\"},{\"id\":\"0336\",\"n\":\"dumbbell lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Take a step forward with your right foot, lowering your body into a lunge position.\",\"Keep your back straight and your chest up as you lower your body.\",\"Push through your right heel to return to the starting position.\",\"Repeat with your left leg.\",\"Alternate legs for the desired number of repetitions.\"],\"img\":\"0336.webp\",\"gif\":\"0336.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell lunge stepping forward with each leg in turn. It trains the glutes, quads and hamstrings.\",\"fv\":\"2218\"},{\"id\":\"1658\",\"n\":\"dumbbell lunge with bicep curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.\",\"Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.\",\"As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.\",\"Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.\",\"Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1658.webp\",\"gif\":\"1658.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge paired with a bicep curl. It trains the biceps, quads and glutes together.\",\"fv\":\"2549\"},{\"id\":\"0337\",\"n\":\"dumbbell lying extension (across face)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.\",\"Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.\",\"Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0337.webp\",\"gif\":\"0337.mp4\",\"cat\":\"strength\",\"desc\":\"A lying dumbbell triceps extension that moves across the face. It isolates the triceps.\",\"nd\":[\"bench\"],\"fv\":\"2586\"},{\"id\":\"1729\",\"n\":\"dumbbell lying alternate extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing each other.\",\"Extend your arms straight up over your chest, keeping a slight bend in your elbows.\",\"Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.\",\"Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.\",\"Repeat with the other arm, alternating sides for the desired number of repetitions.\"],\"img\":\"1729.webp\",\"gif\":\"1729.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating dumbbell triceps extensions while lying down. It isolates each arm in turn.\",\"nd\":[\"bench\"],\"fv\":\"3940\"},{\"id\":\"0338\",\"n\":\"dumbbell lying elbow press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.\",\"Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.\",\"Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0338.webp\",\"gif\":\"0338.mp4\",\"cat\":\"strength\",\"desc\":\"A lying elbow press with dumbbells. Bending and extending the elbows loads the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"0863\",\"n\":\"dumbbell lying external shoulder rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"triceps\"],\"st\":[\"Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.\",\"Hold a dumbbell in your hand with your palm facing down.\",\"Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.\",\"Pause for a moment at the top, then slowly lower your forearm back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0863.webp\",\"gif\":\"0863.mp4\",\"cat\":\"rehab\",\"desc\":\"A side-lying rotation with a light dumbbell, turning the forearm upward with the elbow at the side. It strengthens the rotator cuff.\",\"nd\":[\"bench\"],\"fv\":\"3079\"},{\"id\":\"0339\",\"n\":\"dumbbell lying femoral\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.\",\"Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0339.webp\",\"gif\":\"0339.mp4\",\"cat\":\"strength\",\"desc\":\"A lying hamstring curl with a dumbbell. You bend the knees to bring the weight toward the glutes.\",\"fv\":\"2669\"},{\"id\":\"0340\",\"n\":\"dumbbell lying hammer press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.\",\"Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.\",\"Press the dumbbells back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0340.webp\",\"gif\":\"0340.mp4\",\"cat\":\"strength\",\"desc\":\"A lying press with the palms facing each other. It works the chest and arms with a shoulder-friendly grip.\",\"nd\":[\"bench\"],\"fv\":\"2486\"},{\"id\":\"2470\",\"n\":\"dumbbell lying on floor rear delt raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Lie face down on the floor with a dumbbell in each hand, palms facing each other.\",\"Extend your arms straight out in front of you, keeping a slight bend in your elbows.\",\"Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2470.webp\",\"gif\":\"2470.mp4\",\"cat\":\"strength\",\"desc\":\"A rear delt raise performed lying face down on the floor. Targets the rear shoulders and upper back.\"},{\"id\":\"0341\",\"n\":\"dumbbell lying one arm deltoid rear\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.\",\"Extend your arm straight down towards the floor, keeping it close to your body.\",\"Raise your arm up and back, squeezing your shoulder blade towards your spine.\",\"Pause for a moment at the top, then slowly lower your arm back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0341.webp\",\"gif\":\"0341.mp4\",\"cat\":\"strength\",\"desc\":\"A face-down one-arm dumbbell raise for the rear delt. You lift the arm up and back, squeezing the shoulder blade.\",\"nd\":[\"bench\"]},{\"id\":\"0343\",\"n\":\"dumbbell lying one arm press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.\",\"Hold the dumbbell at shoulder level with your palm facing forward.\",\"Press the dumbbell upward until your arm is fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0343.webp\",\"gif\":\"0343.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm dumbbell press on a flat bench. Working one side at a time shows up any imbalance.\",\"nd\":[\"bench\"],\"fv\":\"2680\"},{\"id\":\"0342\",\"n\":\"dumbbell lying one arm press v. 2\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your back supported and feet flat on the ground.\",\"Hold a dumbbell in one hand with your palm facing towards your feet.\",\"Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.\",\"Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.\",\"Pause for a moment at the bottom, then push the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0342.webp\",\"gif\":\"0342.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm lying dumbbell press. The weight lowers to the chest side and presses up, working the pecs and triceps.\",\"nd\":[\"bench\"]},{\"id\":\"0344\",\"n\":\"dumbbell lying one arm pronated triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your back and head supported, and your feet flat on the ground.\",\"Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.\",\"Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.\",\"Pause for a moment at the bottom, then extend your arm back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0344.webp\",\"gif\":\"0344.mp4\",\"cat\":\"strength\",\"desc\":\"A lying one-arm triceps extension with an overhand grip. It isolates the triceps, one side at a time.\",\"nd\":[\"bench\"],\"fv\":\"2588\"},{\"id\":\"0345\",\"n\":\"dumbbell lying one arm rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.\",\"Keep your arm straight and lift the dumbbell out to the side, away from your body.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0345.webp\",\"gif\":\"0345.mp4\",\"cat\":\"strength\",\"desc\":\"A face-down one-arm rear lateral raise on a bench. It works the rear delts and the upper back.\",\"nd\":[\"bench\"]},{\"id\":\"0346\",\"n\":\"dumbbell lying one arm supinated triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie flat on a bench with your back and head supported, and your feet flat on the ground.\",\"Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.\",\"Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.\",\"Pause for a moment at the bottom, then extend your arm back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0346.webp\",\"gif\":\"0346.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you extend one arm overhead with a palm-up grip to hit the back of the upper arm. A focused way to build triceps one side at a time.\",\"nd\":[\"bench\"],\"fv\":\"2587\"},{\"id\":\"0347\",\"n\":\"dumbbell lying pronation\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.\",\"Rotate your palms so they are facing up.\",\"Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.\",\"Inhale and slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0347.webp\",\"gif\":\"0347.mp4\",\"cat\":\"strength\",\"desc\":\"A lying forearm rotation with a dumbbell, turning the palm from facing in to facing down. It works the muscles that control forearm rotation.\",\"nd\":[\"bench\"]},{\"id\":\"2705\",\"n\":\"dumbbell lying pronation on floor\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.\",\"Rotate your palms so they are facing down towards the floor.\",\"Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.\",\"Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.\",\"Hold for a moment, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2705.webp\",\"gif\":\"2705.mp4\",\"cat\":\"strength\",\"desc\":\"A lying dumbbell forearm pronation on the floor. Works the forearm muscles.\"},{\"id\":\"1284\",\"n\":\"dumbbell lying pullover on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"back\"],\"st\":[\"Sit on an exercise ball and roll forward until your upper back is resting on the ball.\",\"Hold a dumbbell with both hands and extend your arms straight up over your chest.\",\"Slowly lower the dumbbell behind your head while keeping your arms straight.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1284.webp\",\"gif\":\"1284.mp4\",\"cat\":\"strength\",\"desc\":\"Lying across a stability ball, you arc one dumbbell back over your head and return it. It stretches and works the chest and lats.\"},{\"id\":\"1328\",\"n\":\"dumbbell lying rear delt row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.\",\"Extend your arms straight down towards the floor, keeping a slight bend in your elbows.\",\"Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1328.webp\",\"gif\":\"1328.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down on a bench and row two dumbbells up and out. It targets the rear shoulders and upper back without any body swing.\",\"nd\":[\"bench\"],\"fv\":\"2618\"},{\"id\":\"0348\",\"n\":\"dumbbell lying rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.\",\"Extend your arms straight down towards the floor, keeping a slight bend in your elbows.\",\"Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0348.webp\",\"gif\":\"0348.mp4\",\"cat\":\"strength\",\"desc\":\"Chest-down on a bench, you raise dumbbells out to the sides. It targets the rear shoulders and upper back muscles.\",\"nd\":[\"bench\"]},{\"id\":\"1735\",\"n\":\"dumbbell lying single extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.\",\"Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.\",\"Pause briefly at the bottom of the movement, then extend your arm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1735.webp\",\"gif\":\"1735.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm dumbbell triceps extension lying down. It isolates one triceps at a time.\",\"nd\":[\"bench\"],\"fv\":\"3080\"},{\"id\":\"0349\",\"n\":\"dumbbell lying supination\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground.\",\"Hold a dumbbell in each hand with your palms facing up and your arms fully extended.\",\"Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0349.webp\",\"gif\":\"0349.mp4\",\"cat\":\"strength\",\"desc\":\"A lying forearm rotation with a dumbbell, turning the palm up. It trains the muscles that rotate the forearm and supports elbow and wrist control.\",\"nd\":[\"bench\"]},{\"id\":\"2706\",\"n\":\"dumbbell lying supination on floor\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.\",\"Rotate your palms to face up, keeping your elbows close to your sides.\",\"Slowly curl the dumbbells towards your shoulders, squeezing your forearms.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2706.webp\",\"gif\":\"2706.mp4\",\"cat\":\"strength\",\"desc\":\"A lying dumbbell forearm supination on the floor. Works the forearm muscles.\"},{\"id\":\"1661\",\"n\":\"dumbbell lying supine biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie flat on a bench with your back and head supported, and your feet flat on the ground.\",\"Hold a dumbbell in each hand with your palms facing up and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1661.webp\",\"gif\":\"1661.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl lying on your back. It isolates the biceps with your upper arms supported.\",\"nd\":[\"bench\"]},{\"id\":\"0350\",\"n\":\"dumbbell lying supine curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0350.webp\",\"gif\":\"0350.mp4\",\"cat\":\"strength\",\"desc\":\"You lie on a bench and curl dumbbells with palms up. The lying position keeps the biceps working under steady tension.\",\"nd\":[\"bench\"],\"fv\":\"3602\"},{\"id\":\"0351\",\"n\":\"dumbbell lying triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing each other.\",\"Extend your arms straight up over your chest, keeping your elbows close to your body.\",\"Lower the dumbbells down towards your forehead, bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0351.webp\",\"gif\":\"0351.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you bend and straighten the elbows to lower dumbbells toward your forehead and press back up. A classic triceps builder.\",\"nd\":[\"bench\"],\"fv\":\"2251\"},{\"id\":\"1662\",\"n\":\"dumbbell lying wide curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1662.webp\",\"gif\":\"1662.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl lying down with the arms wide. It emphasizes the inner biceps.\",\"nd\":[\"bench\"]},{\"id\":\"0352\",\"n\":\"dumbbell neutral grip bench press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.\",\"Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.\",\"Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0352.webp\",\"gif\":\"0352.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell bench press with palms facing each other. It works the chest, front shoulders and triceps with a shoulder-friendly grip.\"},{\"id\":\"1285\",\"n\":\"dumbbell one arm bench fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.\",\"Lie back on the bench, keeping the dumbbell pressed against your thigh.\",\"Using your free hand, help lift the dumbbell up to the starting position.\",\"Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.\",\"Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.\",\"Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms and repeat.\"],\"img\":\"1285.webp\",\"gif\":\"1285.mp4\",\"cat\":\"strength\",\"desc\":\"Flat bench fly with a single dumbbell. Lowering in a wide arc stretches one side of the chest, and bringing it back squeezes it.\"},{\"id\":\"0292\",\"n\":\"dumbbell one arm bent-over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.\",\"Let the dumbbell hang straight down towards the floor, with your arm fully extended.\",\"Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0292.webp\",\"gif\":\"0292.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm dumbbell row from a hinged stance. It trains the upper back one side at a time.\"},{\"id\":\"1286\",\"n\":\"dumbbell one arm chest fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.\",\"Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.\",\"Extend your arm with the dumbbell straight up above your chest, palm facing inward.\",\"Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.\",\"Pause for a moment when your arm is parallel to the ground.\",\"Engage your chest muscles to bring the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1286.webp\",\"gif\":\"1286.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm chest fly with your upper back on a stability ball. The wobbly base brings your core in while the chest does the work.\"},{\"id\":\"0353\",\"n\":\"dumbbell one arm concentration curl (on stability ball)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.\",\"Rest your elbow on the inside of your thigh, just above the knee.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.\",\"Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms and repeat.\"],\"img\":\"0353.webp\",\"gif\":\"0353.mp4\",\"cat\":\"strength\",\"desc\":\"A seated concentration curl done while balancing on a stability ball. It isolates the biceps and adds a bit of core work to stay steady.\",\"fv\":\"2590\"},{\"id\":\"1287\",\"n\":\"dumbbell one arm decline chest press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a decline bench with a dumbbell in one hand, resting on your chest.\",\"Place your feet flat on the ground and keep your back pressed against the bench.\",\"Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1287.webp\",\"gif\":\"1287.mp4\",\"cat\":\"strength\",\"desc\":\"Press a single dumbbell up from a decline bench. It focuses on the lower chest and lets you train each side separately.\"},{\"id\":\"1288\",\"n\":\"dumbbell one arm fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.\",\"Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.\",\"Extend your arm with the dumbbell straight up above your chest, palm facing inwards.\",\"Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.\",\"Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1288.webp\",\"gif\":\"1288.mp4\",\"cat\":\"strength\",\"desc\":\"One-arm dumbbell fly with your upper back on a stability ball. It stretches and shapes the chest while your core keeps you steady.\"},{\"id\":\"1736\",\"n\":\"dumbbell one arm french press on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.\",\"Extend your arm straight up towards the ceiling, keeping your elbow stationary.\",\"Slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1736.webp\",\"gif\":\"1736.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm French press on an exercise ball. It trains the triceps and tests balance.\",\"fv\":\"2648\"},{\"id\":\"1663\",\"n\":\"dumbbell one arm hammer preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.\",\"Hold the dumbbell with a neutral grip (palms facing your body).\",\"Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1663.webp\",\"gif\":\"1663.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm hammer curl over a preacher bench. It builds the brachialis and biceps without swinging.\"},{\"id\":\"1621\",\"n\":\"dumbbell one arm hammer press on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.\",\"Place your other hand on your hip for stability.\",\"Press the dumbbell upwards, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1621.webp\",\"gif\":\"1621.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm neutral-grip press while lying on an exercise ball. It trains the triceps while the core keeps you stable.\"},{\"id\":\"1289\",\"n\":\"dumbbell one arm incline chest press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Adjust the incline bench to a 45-degree angle.\",\"Sit on the bench with your back against the pad and feet flat on the ground.\",\"Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.\",\"Push the dumbbell up and away from your body, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1289.webp\",\"gif\":\"1289.mp4\",\"cat\":\"strength\",\"desc\":\"Press one dumbbell up on an incline bench to train the upper chest and front shoulder. Working one arm at a time helps balance both sides.\"},{\"id\":\"0354\",\"n\":\"dumbbell one arm kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Bring your right elbow up to your side, keeping it bent at a 90-degree angle.\",\"Extend your right arm straight back, squeezing your triceps at the top of the movement.\",\"Slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0354.webp\",\"gif\":\"0354.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over, one-arm movement where you straighten the elbow behind you. It isolates the triceps, especially at the top of the squeeze.\",\"fv\":\"2373\"},{\"id\":\"0355\",\"n\":\"dumbbell one arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.\",\"Keep your back straight and your core engaged throughout the exercise.\",\"Raise the dumbbell to the side, keeping your arm straight and your palm facing down.\",\"Continue lifting until your arm is parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0355.webp\",\"gif\":\"0355.mp4\",\"cat\":\"strength\",\"desc\":\"You raise one dumbbell out to the side to shoulder height, one arm at a time. It builds the side of the shoulder.\",\"fv\":\"2591\"},{\"id\":\"0356\",\"n\":\"dumbbell one arm lateral raise with support\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.\",\"Place your other hand on a stable surface, such as a bench or wall, for support.\",\"Keep your back straight and engage your core.\",\"Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.\",\"Continue lifting until your arm is parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0356.webp\",\"gif\":\"0356.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm lateral raise with your free hand braced on a support. The support lets you focus on the side shoulder without swinging.\",\"fv\":\"2690\"},{\"id\":\"1290\",\"n\":\"dumbbell one arm press on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.\",\"Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1290.webp\",\"gif\":\"1290.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm dumbbell press done seated or lying on a stability ball. Balance and core control are part of every rep.\"},{\"id\":\"1665\",\"n\":\"dumbbell one arm prone curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie face down on a flat bench with a dumbbell in one hand, palm facing down.\",\"Extend your arm fully, letting it hang straight down towards the floor.\",\"Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1665.webp\",\"gif\":\"1665.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl lying chest down on an incline bench. It isolates the biceps on one side.\",\"nd\":[\"bench\"]},{\"id\":\"1666\",\"n\":\"dumbbell one arm prone hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.\",\"Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1666.webp\",\"gif\":\"1666.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm hammer curl lying chest down on a bench. It trains the brachialis and biceps.\",\"nd\":[\"bench\"]},{\"id\":\"1291\",\"n\":\"dumbbell one arm pullover on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"latissimus dorsi\",\"rhomboids\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a dumbbell with one hand and extend your arm straight up above your chest.\",\"Slowly lower the dumbbell behind your head while keeping your arm straight.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1291.webp\",\"gif\":\"1291.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover with one dumbbell while your upper back rests on a stability ball. It stretches the chest and lats and asks your core to stay braced.\"},{\"id\":\"0358\",\"n\":\"dumbbell one arm reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground.\",\"Hold a dumbbell in one hand with an overhand grip, palm facing down.\",\"Rest your forearm on your thigh, with your wrist hanging off the edge.\",\"Slowly lower the dumbbell towards the ground by flexing your wrist.\",\"Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0358.webp\",\"gif\":\"0358.mp4\",\"cat\":\"strength\",\"desc\":\"Forearm on a bench or thigh, palm down, you curl the dumbbell up with your wrist. It builds the muscles on top of the forearm.\",\"fv\":\"2684\"},{\"id\":\"0359\",\"n\":\"dumbbell one arm reverse fly (with support)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Sit on a bench with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with your palm facing inwards.\",\"Lean forward and place your free hand on the bench for support.\",\"Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arm back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0359.webp\",\"gif\":\"0359.mp4\",\"cat\":\"strength\",\"desc\":\"Braced on a support, you raise one dumbbell out to the side with a bent torso. It targets the rear shoulder and upper back, one side at a time.\",\"fv\":\"2691\"},{\"id\":\"1622\",\"n\":\"dumbbell one arm reverse grip press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.\",\"Place your feet flat on the ground and keep your back straight.\",\"Raise the dumbbell to shoulder height, keeping your elbow close to your body.\",\"Press the dumbbell upwards until your arm is fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1622.webp\",\"gif\":\"1622.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm dumbbell press with your palm facing you. It shifts focus to the upper chest and biceps.\"},{\"id\":\"1414\",\"n\":\"dumbbell one arm reverse preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.\",\"Lower the dumbbell slowly until your arm is fully extended.\",\"Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.\",\"Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1414.webp\",\"gif\":\"1414.mp4\",\"cat\":\"strength\",\"desc\":\"Rest your arm on a preacher bench and curl a dumbbell with an overhand grip. It targets the biceps and forearms with no body swing.\"},{\"id\":\"1667\",\"n\":\"dumbbell one arm reverse spider curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.\",\"Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1667.webp\",\"gif\":\"1667.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm reverse spider curl, with an overhand grip over a bench. It works the forearms and brachialis.\"},{\"id\":\"1668\",\"n\":\"dumbbell one arm seated bicep curl on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with your palm facing up and your arm fully extended.\",\"Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1668.webp\",\"gif\":\"1668.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm seated dumbbell curl on an exercise ball. It trains the biceps and your balance.\"},{\"id\":\"1669\",\"n\":\"dumbbell one arm seated hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in one hand with a neutral grip (palms facing each other).\",\"Rest your elbow on the inside of your thigh, just above the knee.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1669.webp\",\"gif\":\"1669.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm seated hammer curl. It trains the brachialis and biceps on one side at a time.\"},{\"id\":\"1415\",\"n\":\"dumbbell one arm seated neutral wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.\",\"Rest your forearm on your thigh, allowing your wrist to hang off the edge.\",\"Keeping your forearm stationary, curl your wrist upward as far as possible.\",\"Pause for a moment at the top, then slowly lower your wrist back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other hand.\"],\"img\":\"1415.webp\",\"gif\":\"1415.mp4\",\"cat\":\"strength\",\"desc\":\"Sit with your forearm supported and curl a dumbbell with your wrist in a neutral position. It strengthens the forearms and builds grip.\",\"fv\":\"2685\"},{\"id\":\"0361\",\"n\":\"dumbbell one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.\",\"Press the dumbbell upward until your arm is fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0361.webp\",\"gif\":\"0361.mp4\",\"cat\":\"strength\",\"desc\":\"You press one dumbbell from shoulder height to overhead. It builds the shoulders and triceps one side at a time.\"},{\"id\":\"0360\",\"n\":\"dumbbell one arm shoulder press v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.\",\"Engage your core and press the dumbbell straight up overhead, fully extending your arm.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0360.webp\",\"gif\":\"0360.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead dumbbell press, second variation. It trains the shoulder and triceps while your core resists leaning.\"},{\"id\":\"3888\",\"n\":\"dumbbell one arm snatch\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\",\"Lower the dumbbell towards the ground, keeping it close to your body.\",\"Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.\",\"As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.\",\"Catch the dumbbell overhead with a slight bend in your knees and hips.\",\"Lower the dumbbell back down to the starting position in a controlled manner.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"3888.webp\",\"gif\":\"3888.mp4\",\"cat\":\"olympic\",\"desc\":\"A one-armed dumbbell snatch, pulling the weight from the floor to overhead in one explosive movement. It trains the hips, legs and shoulders.\",\"fv\":\"5786\"},{\"id\":\"1670\",\"n\":\"dumbbell one arm standing curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.\",\"Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1670.webp\",\"gif\":\"1670.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm dumbbell curl. It builds the biceps on one side at a time.\"},{\"id\":\"1671\",\"n\":\"dumbbell one arm standing hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your torso.\",\"Keep your elbows close to your torso and your upper arms stationary.\",\"Exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1671.webp\",\"gif\":\"1671.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm hammer curl. It trains the brachialis and biceps with a neutral grip.\"},{\"id\":\"0362\",\"n\":\"dumbbell one arm triceps extension (on bench)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in one hand and place your other hand on the bench for support.\",\"Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.\",\"Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.\",\"Extend your arm back up to the starting position, fully straightening your elbow.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0362.webp\",\"gif\":\"0362.mp4\",\"cat\":\"strength\",\"desc\":\"With one arm supported on a bench, you extend the other arm to work the back of the upper arm. A strict triceps isolation move.\",\"fv\":\"2601\"},{\"id\":\"0363\",\"n\":\"dumbbell one arm upright row\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.\",\"Let the dumbbell hang at arm's length in front of your thighs, with your palm facing your body.\",\"Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0363.webp\",\"gif\":\"0363.mp4\",\"cat\":\"strength\",\"desc\":\"You pull one dumbbell up along your body toward chin height with the elbow leading. It trains the side shoulders and upper traps.\",\"fv\":\"2600\"},{\"id\":\"0364\",\"n\":\"dumbbell one arm wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground.\",\"Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.\",\"Allow your wrist to extend, letting the dumbbell roll down towards your fingers.\",\"Slowly curl your wrist back up, bringing the dumbbell towards your forearm.\",\"Repeat for the desired number of repetitions, then switch to the other hand.\"],\"img\":\"0364.webp\",\"gif\":\"0364.mp4\",\"cat\":\"strength\",\"desc\":\"Forearm supported and palm up, you curl a dumbbell with only the wrist. It builds the muscles on the underside of the forearm.\",\"fv\":\"2686\"},{\"id\":\"1672\",\"n\":\"dumbbell one arm zottman preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.\",\"Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.\",\"Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.\",\"At the top of the curl, rotate your wrist so that your palm faces up.\",\"Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1672.webp\",\"gif\":\"1672.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm Zottman curl over a preacher bench: curl up palm up, turn the palm down to lower. It works biceps and forearms.\",\"fv\":\"3763\"},{\"id\":\"1292\",\"n\":\"dumbbell one leg fly on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with a dumbbell in each hand, palms facing each other.\",\"Place one foot on the ground and extend the other leg straight out in front of you.\",\"Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.\",\"Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.\",\"Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1292.webp\",\"gif\":\"1292.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly on a stability ball with one leg lifted, which makes balance harder. It works the chest and trains core stability.\"},{\"id\":\"0365\",\"n\":\"dumbbell over bench neutral wrist curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.\",\"Rest your forearms on the bench, allowing your wrists to hang off the edge.\",\"Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0365.webp\",\"gif\":\"0365.mp4\",\"cat\":\"strength\",\"desc\":\"Forearms rest over the end of a bench with palms facing in, and you move the dumbbells with your wrists. It builds forearm strength and grip.\",\"fv\":\"2628\"},{\"id\":\"0366\",\"n\":\"dumbbell over bench one arm neutral wrist curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.\",\"Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0366.webp\",\"gif\":\"0366.mp4\",\"cat\":\"strength\",\"desc\":\"One forearm rests over a bench with the palm facing in, and you move the dumbbell with the wrist. A grip and forearm builder done one side at a time.\",\"fv\":\"2629\"},{\"id\":\"1441\",\"n\":\"dumbbell over bench one arm reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.\",\"Rest your forearm on the bench with your wrist hanging off the edge.\",\"Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1441.webp\",\"gif\":\"1441.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm reverse wrist curl with your forearm resting over a bench. It strengthens the wrist extensors on the top of the forearm.\"},{\"id\":\"0367\",\"n\":\"dumbbell over bench one arm wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.\",\"Rest your forearm on the bench with your wrist hanging off the edge.\",\"Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0367.webp\",\"gif\":\"0367.mp4\",\"cat\":\"strength\",\"desc\":\"One forearm rests over a bench with the palm up while you curl the dumbbell with your wrist. It builds the underside of the forearm.\",\"fv\":\"2687\"},{\"id\":\"0368\",\"n\":\"dumbbell over bench revers wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.\",\"Rest your forearms on the bench, allowing your wrists to hang off the edge.\",\"Slowly curl your wrists upward, bringing the dumbbells towards your body.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0368.webp\",\"gif\":\"0368.mp4\",\"cat\":\"strength\",\"desc\":\"Forearms over a bench with palms down, you lift the dumbbells with your wrists. It strengthens the top of the forearms.\",\"fv\":\"2630\"},{\"id\":\"0369\",\"n\":\"dumbbell over bench wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.\",\"Allow your wrists to hang over the edge of the bench.\",\"Slowly curl your wrists upward, squeezing your forearms at the top of the movement.\",\"Pause for a moment, then slowly lower your wrists back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0369.webp\",\"gif\":\"0369.mp4\",\"cat\":\"strength\",\"desc\":\"Forearms rest over a bench with palms up, and you curl the dumbbells with your wrists. A direct move for forearm size and grip.\",\"fv\":\"2631\"},{\"id\":\"1329\",\"n\":\"dumbbell palm rotational bent over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Bend forward at the hips, keeping your back straight and your knees slightly bent.\",\"Let your arms hang straight down, palms facing your body.\",\"Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.\",\"As you pull the dumbbells up, rotate your palms so they face away from your body.\",\"Squeeze your shoulder blades together at the top of the movement.\",\"Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1329.webp\",\"gif\":\"1329.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over dumbbell row where your palms rotate as you pull. It works the upper back, lats and biceps through a varied path.\",\"fv\":\"2622\"},{\"id\":\"1623\",\"n\":\"dumbbell palms in incline bench press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your back against the backrest and feet flat on the ground.\",\"Hold a dumbbell in each hand with an overhand grip, palms facing inwards.\",\"Extend your arms straight up above your chest, keeping a slight bend in your elbows.\",\"Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.\",\"Pause for a moment at the bottom, then press the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1623.webp\",\"gif\":\"1623.mp4\",\"cat\":\"strength\",\"desc\":\"An incline bench press with palms facing in. It trains the triceps and the front delts with a shoulder-friendly grip.\"},{\"id\":\"0370\",\"n\":\"dumbbell peacher hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your torso.\",\"Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\",\"This will be your starting position.\",\"Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Then, inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the recommended amount of repetitions.\"],\"img\":\"0370.webp\",\"gif\":\"0370.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl with the upper arms braced on a preacher pad. The neutral grip hits the biceps and the muscles beside them.\"},{\"id\":\"0371\",\"n\":\"dumbbell plyo squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"As you reach the bottom of the squat, explode upward, jumping off the ground.\",\"While in the air, quickly switch the position of your feet, landing with your opposite foot forward.\",\"Immediately lower your body back into a squat position and repeat the jump, switching your feet again.\",\"Continue alternating the position of your feet with each jump for the desired number of repetitions.\"],\"img\":\"0371.webp\",\"gif\":\"0371.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A dumbbell squat finished with an explosive jump. It builds leg power and gets the heart rate up.\"},{\"id\":\"0372\",\"n\":\"dumbbell preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.\",\"Hold a dumbbell in each hand with your palms facing up and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0372.webp\",\"gif\":\"0372.mp4\",\"cat\":\"strength\",\"desc\":\"You curl a dumbbell with the upper arm braced on a preacher pad. The pad stops swinging so the biceps do the work.\",\"fv\":\"2385\"},{\"id\":\"1673\",\"n\":\"dumbbell preacher curl over exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1673.webp\",\"gif\":\"1673.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with the arm supported over an exercise ball. It trains the biceps with some balance demand.\",\"fv\":\"3762\"},{\"id\":\"1293\",\"n\":\"dumbbell press on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.\",\"Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.\",\"Raise the dumbbells to shoulder height, palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1293.webp\",\"gif\":\"1293.mp4\",\"cat\":\"strength\",\"desc\":\"Press two dumbbells up while your upper back rests on a stability ball. A good way to train the chest with extra core and balance demand.\",\"fv\":\"3081\"},{\"id\":\"0373\",\"n\":\"dumbbell pronate-grip triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench or chair with your back straight and feet flat on the ground.\",\"Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.\",\"Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0373.webp\",\"gif\":\"0373.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension with a palms-down grip. It loads the back of the upper arm in a slightly different way.\",\"fv\":\"3941\"},{\"id\":\"0374\",\"n\":\"dumbbell prone incline curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the bench to a 45-degree incline.\",\"Lie face down on the bench with your chest and stomach resting against it.\",\"Hold a dumbbell in each hand with your palms facing down and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0374.webp\",\"gif\":\"0374.mp4\",\"cat\":\"strength\",\"desc\":\"Chest down on an incline bench, you curl dumbbells from a hanging position. It stretches and works the biceps hard.\",\"fv\":\"2496\"},{\"id\":\"1674\",\"n\":\"dumbbell prone incline hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the bench to a 45-degree incline.\",\"Lie face down on the bench with a dumbbell in each hand, palms facing each other.\",\"Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1674.webp\",\"gif\":\"1674.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl lying chest down on an incline bench. It trains the brachialis and biceps.\",\"fv\":\"2495\"},{\"id\":\"0375\",\"n\":\"dumbbell pullover\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"latissimus dorsi\",\"sm\":[\"latissimus dorsi\",\"triceps\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet on the floor.\",\"Hold a dumbbell with both hands and extend your arms straight above your chest.\",\"Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0375.webp\",\"gif\":\"0375.mp4\",\"cat\":\"strength\",\"desc\":\"Lying across or along a bench, you lower one dumbbell behind your head and pull it back over your chest. It works the chest and lats with a deep stretch.\",\"nd\":[\"bench\"]},{\"id\":\"1294\",\"n\":\"dumbbell pullover hip extension on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.\",\"Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.\",\"Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.\",\"Lower the dumbbell behind your head, keeping your arms straight and maintaining control.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.\",\"Lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1294.webp\",\"gif\":\"1294.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell pullover on a stability ball combined with a hip lift. It trains the chest and lats while the glutes and core hold your body steady.\"},{\"id\":\"1295\",\"n\":\"dumbbell pullover on exercise ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"latissimus dorsi\"],\"st\":[\"Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.\",\"Slowly lower the dumbbell behind your head while keeping your arms straight.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1295.webp\",\"gif\":\"1295.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell pullover performed on a stability ball. The arc behind your head stretches the chest and lats and keeps your core busy.\",\"fv\":\"2621\"},{\"id\":\"1700\",\"n\":\"dumbbell push press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.\",\"Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.\",\"Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1700.webp\",\"gif\":\"1700.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead dumbbell press that uses a small leg dip and drive for momentum. It builds the shoulders and triceps.\"},{\"id\":\"0376\",\"n\":\"dumbbell raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\",\"Keep your back straight and engage your core.\",\"Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0376.webp\",\"gif\":\"0376.mp4\",\"cat\":\"strength\",\"desc\":\"You lift dumbbells in front of you or to the side with straight arms. A simple shoulder builder.\"},{\"id\":\"2292\",\"n\":\"dumbbell rear delt raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2292.webp\",\"gif\":\"2292.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over dumbbell raise to the sides. Trains the rear delts and upper back.\",\"fv\":\"3429\"},{\"id\":\"0377\",\"n\":\"dumbbell rear delt row_shoulder\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold a dumbbell in each hand with your palms facing your body.\",\"Bend forward at the waist, keeping your back straight and your core engaged.\",\"Extend your arms straight down towards the floor, with a slight bend in your elbows.\",\"Raise the dumbbells out to the sides, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0377.webp\",\"gif\":\"0377.mp4\",\"cat\":\"strength\",\"desc\":\"Bent over, you row dumbbells with elbows flared out. It targets the rear shoulders and upper back.\",\"fv\":\"3755\"},{\"id\":\"0378\",\"n\":\"dumbbell rear fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Extend your arms straight down towards the ground, palms facing each other.\",\"Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0378.webp\",\"gif\":\"0378.mp4\",\"cat\":\"strength\",\"desc\":\"Bent forward, you swing dumbbells out to the sides with a soft elbow bend. It builds the rear shoulders and upper back.\",\"fv\":\"2392\"},{\"id\":\"0380\",\"n\":\"dumbbell rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.\",\"Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0380.webp\",\"gif\":\"0380.mp4\",\"cat\":\"strength\",\"desc\":\"Bent over at the hips, you raise dumbbells out to the sides. It trains the rear shoulders and the muscles between the shoulder blades.\"},{\"id\":\"0379\",\"n\":\"dumbbell rear lateral raise (support head)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0379.webp\",\"gif\":\"0379.mp4\",\"cat\":\"strength\",\"desc\":\"A rear lateral raise with your forehead supported on a bench or pad. The support protects your lower back and keeps the focus on the rear delts.\"},{\"id\":\"0381\",\"n\":\"dumbbell rear lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Take a step backward with your right foot, lowering your body into a lunge position.\",\"Bend your left knee and lower your body until your left thigh is parallel to the ground.\",\"Pause for a moment, then push through your left heel to return to the starting position.\",\"Repeat on the other side, stepping back with your left foot.\"],\"img\":\"0381.webp\",\"gif\":\"0381.mp4\",\"cat\":\"strength\",\"desc\":\"You step back into a lunge while holding dumbbells. It works the glutes and thighs with less knee strain than a forward lunge.\",\"fv\":\"2219\"},{\"id\":\"0382\",\"n\":\"dumbbell revers grip biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0382.webp\",\"gif\":\"0382.mp4\",\"cat\":\"strength\",\"desc\":\"You curl dumbbells with an overhand grip. It trains the biceps, the muscle under them and the forearms.\"},{\"id\":\"1624\",\"n\":\"dumbbell reverse bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your knees bent.\",\"Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.\",\"Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.\",\"Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.\",\"Pause for a moment at the bottom, then push the dumbbells back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1624.webp\",\"gif\":\"1624.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with a reverse grip using dumbbells. It targets the upper chest and the triceps.\",\"fv\":\"3451\"},{\"id\":\"0383\",\"n\":\"dumbbell reverse fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Extend your arms straight down in front of you, palms facing each other.\",\"Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0383.webp\",\"gif\":\"0383.mp4\",\"cat\":\"strength\",\"desc\":\"Bent forward, you open your arms wide with dumbbells. It targets the rear shoulders and upper back.\"},{\"id\":\"1330\",\"n\":\"dumbbell reverse grip incline bench one arm row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Place a dumbbell on the floor next to the bench.\",\"Stand facing the bench with your feet shoulder-width apart.\",\"Bend at the waist and place your left knee and left hand on the bench for support.\",\"Pick up the dumbbell with your right hand using a reverse grip (palm facing down).\",\"Keep your back straight and your core engaged.\",\"Pull the dumbbell up towards your chest, keeping your elbow close to your body.\",\"Squeeze your back muscles at the top of the movement.\",\"Lower the dumbbell back down to the starting position in a controlled manner.\",\"Repeat for the desired number of repetitions.\",\"Switch sides and repeat the exercise with your left arm.\"],\"img\":\"1330.webp\",\"gif\":\"1330.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row with an underhand grip, supported on an incline bench. It works the upper back and biceps one side at a time.\",\"fv\":\"2623\"},{\"id\":\"1331\",\"n\":\"dumbbell reverse grip incline bench two arm row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your chest against the backrest and your feet flat on the ground.\",\"Hold a dumbbell in each hand with an underhand grip.\",\"Lean forward and let your arms hang straight down, fully extended.\",\"Pull the dumbbells up towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1331.webp\",\"gif\":\"1331.mp4\",\"cat\":\"strength\",\"desc\":\"A two-arm dumbbell row with an underhand grip, chest down on an incline bench. The support keeps you strict so the back and biceps work.\"},{\"id\":\"2327\",\"n\":\"dumbbell reverse grip row (female)\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold a dumbbell in each hand with an overhand grip, palms facing your body.\",\"Bend forward at the waist, keeping your back straight and your core engaged.\",\"Let your arms hang straight down, fully extended, with a slight bend in your elbows.\",\"Pull the dumbbells up towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2327.webp\",\"gif\":\"2327.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over dumbbell row using an underhand grip. Trains the upper back and biceps.\"},{\"id\":\"0384\",\"n\":\"dumbbell reverse preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.\",\"Hold a dumbbell in each hand with an underhand grip, palms facing up.\",\"Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.\",\"Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0384.webp\",\"gif\":\"0384.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with an overhand grip. It strengthens the biceps, the arm flexor beneath them and the forearms.\"},{\"id\":\"1675\",\"n\":\"dumbbell reverse spider curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1675.webp\",\"gif\":\"1675.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse spider curl with both dumbbells, chest down on a bench. It trains the forearms and brachialis.\"},{\"id\":\"0385\",\"n\":\"dumbbell reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground.\",\"Hold a dumbbell in each hand with an overhand grip, palms facing down.\",\"Rest your forearms on your thighs, allowing your wrists to hang off the edge.\",\"Slowly curl your wrists upward, bringing the dumbbells towards your body.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0385.webp\",\"gif\":\"0385.mp4\",\"cat\":\"strength\",\"desc\":\"With palms down and forearms supported, you curl the dumbbells up with your wrists. It builds the top of the forearms.\"},{\"id\":\"1459\",\"n\":\"dumbbell romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.\",\"Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1459.webp\",\"gif\":\"1459.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with dumbbells that lowers them down the legs while your back stays flat. It trains the hamstrings and glutes.\",\"fv\":\"2222\"},{\"id\":\"0386\",\"n\":\"dumbbell rotation reverse fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\",\"Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.\",\"Rotate your arms so that your palms are facing downwards.\",\"Slowly lower your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0386.webp\",\"gif\":\"0386.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse fly with a rotation of the arms at the top. It works the rear shoulders, rotator cuff and upper back.\"},{\"id\":\"2397\",\"n\":\"dumbbell scott press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing forward.\",\"Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2397.webp\",\"gif\":\"2397.mp4\",\"cat\":\"strength\",\"desc\":\"A seated dumbbell press from shoulder height. Builds the shoulders and triceps.\",\"fv\":\"3430\"},{\"id\":\"0387\",\"n\":\"dumbbell seated alternate front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.\",\"Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat with the other arm.\",\"Alternate between arms for the desired number of repetitions.\"],\"img\":\"0387.webp\",\"gif\":\"0387.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you raise one dumbbell at a time to the front. It builds the front of the shoulders without much body swing.\",\"fv\":\"2595\"},{\"id\":\"1676\",\"n\":\"dumbbell seated alternate hammer curl on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the movement with the opposite arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"1676.webp\",\"gif\":\"1676.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating hammer curls while seated on an exercise ball. It trains the brachialis, biceps and core.\"},{\"id\":\"0388\",\"n\":\"dumbbell seated alternate press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing forward.\",\"Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.\",\"Press one dumbbell up overhead, fully extending your arm.\",\"Lower the dumbbell back down to shoulder height.\",\"Repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0388.webp\",\"gif\":\"0388.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you press dumbbells overhead one arm after the other. It builds the shoulders and triceps.\",\"fv\":\"2594\"},{\"id\":\"3546\",\"n\":\"dumbbell seated alternate shoulder\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.\",\"Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.\",\"Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.\",\"Continue alternating between arms for the desired number of repetitions.\"],\"img\":\"3546.webp\",\"gif\":\"3546.mp4\",\"cat\":\"strength\",\"desc\":\"A seated dumbbell shoulder press with the arms alternating. It trains the delts and triceps.\"},{\"id\":\"0389\",\"n\":\"dumbbell seated bench extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell with both hands and extend your arms straight up above your head.\",\"Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.\",\"Pause for a moment, then raise the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0389.webp\",\"gif\":\"0389.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you extend the arms from behind the head or over the bench to work the triceps. A solid isolation move for the back of the arm.\"},{\"id\":\"2317\",\"n\":\"dumbbell seated bent arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.\",\"Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2317.webp\",\"gif\":\"2317.mp4\",\"cat\":\"strength\",\"desc\":\"A seated lateral raise with bent elbows. Targets the side delts with a shorter lever.\"},{\"id\":\"1730\",\"n\":\"dumbbell seated bent over alternate kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing inwards.\",\"Bend forward at the waist, keeping your back straight and parallel to the ground.\",\"Extend one arm straight back, keeping it close to your body, until your arm is fully extended.\",\"Pause for a moment, then slowly lower the dumbbell back to the starting position.\",\"Repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"1730.webp\",\"gif\":\"1730.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating triceps kickbacks, seated and bent over. It isolates the triceps with a squeeze at the top.\"},{\"id\":\"1737\",\"n\":\"dumbbell seated bent over triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.\",\"Bend forward at the waist, keeping your back straight and your head up.\",\"Extend your arms straight back, keeping your elbows close to your head.\",\"Pause for a moment, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1737.webp\",\"gif\":\"1737.mp4\",\"cat\":\"strength\",\"desc\":\"Bent-over dumbbell extension that isolates the triceps while you sit and hinge forward. Great for building the back of the upper arm.\"},{\"id\":\"1677\",\"n\":\"dumbbell seated bicep curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.\",\"Keep your back straight and your elbows close to your torso.\",\"Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1677.webp\",\"gif\":\"1677.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell biceps curl performed seated. It keeps your legs out of the movement.\"},{\"id\":\"0390\",\"n\":\"dumbbell seated biceps curl (on stability ball)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0390.webp\",\"gif\":\"0390.mp4\",\"cat\":\"strength\",\"desc\":\"You curl dumbbells while sitting on a stability ball. It works the biceps and challenges your balance and core.\"},{\"id\":\"3547\",\"n\":\"dumbbell seated biceps curl to shoulder press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in each hand with your palms facing forward and arms fully extended.\",\"Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.\",\"Once your forearms are vertical, rotate your wrists so that your palms are facing forward.\",\"Press the dumbbells overhead until your arms are fully extended.\",\"Lower the dumbbells back down to the starting position by reversing the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3547.webp\",\"gif\":\"3547.mp4\",\"cat\":\"strength\",\"desc\":\"A seated dumbbell curl that flows straight into an overhead press. It trains the biceps and shoulders in one rep.\"},{\"id\":\"1379\",\"n\":\"dumbbell seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.\",\"Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.\",\"Hold onto the dumbbell for stability.\",\"Raise your heels as high as possible, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1379.webp\",\"gif\":\"1379.mp4\",\"cat\":\"strength\",\"desc\":\"Seated calf raise with a dumbbell resting on your knees. The bent knee focuses on the soleus beneath the calf.\",\"fv\":\"3082\"},{\"id\":\"0391\",\"n\":\"dumbbell seated curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.\",\"Keep your back straight and your elbows close to your torso.\",\"Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0391.webp\",\"gif\":\"0391.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with an upright back, you curl dumbbells toward your shoulders. Sitting limits cheating so the biceps work harder.\",\"fv\":\"2240\"},{\"id\":\"0392\",\"n\":\"dumbbell seated front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\"],\"st\":[\"Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.\",\"Keep your back straight and core engaged.\",\"Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0392.webp\",\"gif\":\"0392.mp4\",\"cat\":\"strength\",\"desc\":\"Sitting tall, you lift dumbbells to the front to shoulder height. It trains the front of the shoulders.\",\"fv\":\"2235\"},{\"id\":\"1678\",\"n\":\"dumbbell seated hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1678.webp\",\"gif\":\"1678.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl seated on a bench. It trains the brachialis and the forearms.\"},{\"id\":\"0393\",\"n\":\"dumbbell seated inner biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.\",\"Rest your upper arms on your thighs, allowing the dumbbells to hang down.\",\"Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0393.webp\",\"gif\":\"0393.mp4\",\"cat\":\"strength\",\"desc\":\"A seated curl that emphasises the inner part of the biceps. You keep the elbows tight and curl with control.\"},{\"id\":\"0394\",\"n\":\"dumbbell seated kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.\",\"Bend your knees slightly and lean forward from your hips, keeping your back straight.\",\"Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.\",\"Extend your arms straight back, squeezing your triceps at the top of the movement.\",\"Pause for a moment, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0394.webp\",\"gif\":\"0394.mp4\",\"cat\":\"strength\",\"desc\":\"Seated and bent forward, you straighten your arms behind you with dumbbells. It isolates the triceps.\",\"fv\":\"3421\"},{\"id\":\"0396\",\"n\":\"dumbbell seated lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"upper back\"],\"st\":[\"Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.\",\"Keep your back straight and core engaged.\",\"Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0396.webp\",\"gif\":\"0396.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you raise dumbbells out to the sides to shoulder height. It builds the side shoulders without leg drive.\"},{\"id\":\"0395\",\"n\":\"dumbbell seated lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"triceps\"],\"st\":[\"Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.\",\"Keep your back straight and core engaged.\",\"Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0395.webp\",\"gif\":\"0395.mp4\",\"cat\":\"strength\",\"desc\":\"A seated lateral raise, second variation. It builds the side of the shoulders with strict form.\",\"fv\":\"2236\"},{\"id\":\"0397\",\"n\":\"dumbbell seated neutral wrist curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.\",\"Rest your forearms on your thighs, allowing the dumbbells to hang down.\",\"Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0397.webp\",\"gif\":\"0397.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with forearms on your thighs and palms facing in, you move the dumbbells with your wrists. It builds forearm strength and grip.\",\"fv\":\"2632\"},{\"id\":\"1679\",\"n\":\"dumbbell seated one arm bicep curl on exercise ball with leg raised\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand with your palm facing up and your arm fully extended.\",\"Place your other hand on your hip for stability.\",\"Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.\",\"Pause for a moment at the top of the movement, squeezing your bicep.\",\"Slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch arms and repeat the exercise.\"],\"img\":\"1679.webp\",\"gif\":\"1679.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl seated on an exercise ball with one leg raised. It trains the biceps and balance.\"},{\"id\":\"0398\",\"n\":\"dumbbell seated one arm kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.\",\"Bend your torso forward at the waist, keeping your back straight and parallel to the ground.\",\"Extend your arm straight back, keeping your elbow close to your body.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0398.webp\",\"gif\":\"0398.mp4\",\"cat\":\"strength\",\"desc\":\"Seated and bent forward, you straighten one arm behind you with a dumbbell. It isolates the triceps one side at a time.\"},{\"id\":\"0399\",\"n\":\"dumbbell seated one arm rotate\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.\",\"Raise the dumbbell up to shoulder height, keeping your elbow close to your body.\",\"Rotate your forearm outward, away from your body, while keeping your upper arm stationary.\",\"Pause for a moment at the top, then slowly rotate your forearm back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0399.webp\",\"gif\":\"0399.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you rotate a dumbbell with one forearm, turning the palm up and down. It trains forearm control and wrist strength.\"},{\"id\":\"0400\",\"n\":\"dumbbell seated one leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.\",\"Extend your left leg straight out in front of you, keeping your foot flexed.\",\"Place the ball of your right foot on an elevated surface, such as a step or weight plate.\",\"Using your calf muscles, raise your right heel as high as possible.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0400.webp\",\"gif\":\"0400.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with a dumbbell on one knee, you lift your heel and lower it slowly. It works the calf, especially the deeper soleus.\"},{\"id\":\"1380\",\"n\":\"dumbbell seated one leg calf raise - hammer grip\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.\",\"Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.\",\"Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.\",\"Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other leg.\"],\"img\":\"1380.webp\",\"gif\":\"1380.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg seated calf raise with a dumbbell held in a hammer grip. It trains the soleus under the calf one side at a time.\"},{\"id\":\"1381\",\"n\":\"dumbbell seated one leg calf raise - palm up\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Sit on a bench or chair with your back straight and your feet flat on the ground.\",\"Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.\",\"Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.\",\"Raise your heel as high as possible by pushing through the ball of your foot.\",\"Pause for a moment at the top, then slowly lower your heel back down.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1381.webp\",\"gif\":\"1381.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg seated calf raise with a dumbbell held with your palm up. It works the soleus under the calf one side at a time.\"},{\"id\":\"0401\",\"n\":\"dumbbell seated palms up wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.\",\"Rest your forearms on your thighs, allowing your wrists to hang off the edge.\",\"Slowly curl your wrists upward, squeezing your forearms at the top of the movement.\",\"Pause for a moment, then lower your wrists back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0401.webp\",\"gif\":\"0401.mp4\",\"cat\":\"strength\",\"desc\":\"Forearms rest on your thighs with palms up, and you curl the dumbbells with your wrists. It builds the underside of the forearms.\",\"fv\":\"2633\"},{\"id\":\"0402\",\"n\":\"dumbbell seated preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher curl bench with your feet flat on the floor.\",\"Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0402.webp\",\"gif\":\"0402.mp4\",\"cat\":\"strength\",\"desc\":\"Seated at a preacher bench, you curl dumbbells with your upper arms on the pad. It keeps tension on the biceps.\"},{\"id\":\"0403\",\"n\":\"dumbbell seated revers grip concentration curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.\",\"Rest your elbow on the inside of your thigh, just above the knee.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0403.webp\",\"gif\":\"0403.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with your elbow against your thigh, you curl a dumbbell with an overhand grip. It targets the forearm and the upper arm flexors.\"},{\"id\":\"1738\",\"n\":\"dumbbell seated reverse grip one arm overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell with an underhand grip and extend your arm straight up overhead.\",\"Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.\",\"Pause for a moment, then extend your arm back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1738.webp\",\"gif\":\"1738.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead extension done seated with an underhand grip on the dumbbell. It works the triceps through a long, stretched range.\"},{\"id\":\"0405\",\"n\":\"dumbbell seated shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, resting on your thighs.\",\"Raise the dumbbells to shoulder height, palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0405.webp\",\"gif\":\"0405.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with back support, you press dumbbells from shoulder height to overhead. It builds the shoulders and triceps.\",\"fv\":\"2237\"},{\"id\":\"0404\",\"n\":\"dumbbell seated shoulder press (parallel grip)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing inward.\",\"Raise the dumbbells to shoulder height, elbows bent and palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0404.webp\",\"gif\":\"0404.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you press dumbbells overhead with palms facing each other. A shoulder-friendly press for the shoulders and triceps.\",\"fv\":\"2593\"},{\"id\":\"2188\",\"n\":\"dumbbell seated triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell with both hands and extend your arms straight up overhead.\",\"Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.\",\"Pause for a moment, then straighten your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2188.webp\",\"gif\":\"2188.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension with one dumbbell held in both hands. Builds the back of the upper arms.\",\"fv\":\"2488\"},{\"id\":\"0406\",\"n\":\"dumbbell shrug\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.\",\"Keep your arms straight and let the dumbbells hang by your sides.\",\"Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.\",\"Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0406.webp\",\"gif\":\"0406.mp4\",\"cat\":\"strength\",\"desc\":\"Standing tall with dumbbells at your sides, you lift your shoulders toward your ears. It builds the upper traps and grip.\",\"fv\":\"2596\"},{\"id\":\"0407\",\"n\":\"dumbbell side bend\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.\",\"Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides and repeat.\"],\"img\":\"0407.webp\",\"gif\":\"0407.mp4\",\"cat\":\"strength\",\"desc\":\"Standing with a dumbbell in one hand, you bend sideways and return. It works the side abs, the obliques.\",\"fv\":\"2597\"},{\"id\":\"0408\",\"n\":\"dumbbell side lying one hand raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Lie on your side with your legs extended and your head supported by your arm.\",\"Hold a dumbbell in your top hand with your palm facing down.\",\"Keeping your arm straight, raise the dumbbell up to shoulder height.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0408.webp\",\"gif\":\"0408.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your side, you raise a dumbbell with one hand. It works the shoulder through a different angle with the body supported.\"},{\"id\":\"3664\",\"n\":\"dumbbell side plank with rear fly\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Start by lying on your side with your legs extended and stacked on top of each other.\",\"Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.\",\"Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.\",\"Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.\",\"While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.\",\"Lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"3664.webp\",\"gif\":\"3664.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell side plank with a reverse fly. It trains the rear delts, upper back and obliques.\"},{\"id\":\"3548\",\"n\":\"dumbbell single arm overhead carry\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"core\"],\"st\":[\"Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.\",\"Raise the dumbbell overhead, fully extending your arm.\",\"Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.\",\"Continue walking for the desired distance or time.\",\"Switch hands and repeat the exercise.\"],\"img\":\"3548.webp\",\"gif\":\"3548.mp4\",\"cat\":\"strength\",\"desc\":\"A one-handed overhead carry, walking while holding a dumbbell above your head. It trains the shoulders, core and balance.\"},{\"id\":\"0409\",\"n\":\"dumbbell single leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\"],\"st\":[\"Stand on the edge of a step or platform with your heels hanging off and your toes on the step.\",\"Hold a dumbbell in one hand and place your other hand on a wall or railing for support.\",\"Raise your heel as high as possible, lifting your body up onto your toes.\",\"Pause for a moment at the top, then slowly lower your heel back down below the step.\",\"Repeat for the desired number of repetitions, then switch to the other leg.\"],\"img\":\"0409.webp\",\"gif\":\"0409.mp4\",\"cat\":\"strength\",\"desc\":\"Standing on one leg with a dumbbell, you rise onto your toes and lower slowly. It works the calf and balance.\",\"fv\":\"2624\"},{\"id\":\"1757\",\"n\":\"dumbbell single leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet hip-width apart, holding a dumbbell in your right hand.\",\"Shift your weight onto your left leg and lift your right foot slightly off the ground.\",\"Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.\",\"At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.\",\"Lower the dumbbell until your torso and right leg are parallel to the ground.\",\"Pause for a moment, then engage your glutes and hamstrings to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1757.webp\",\"gif\":\"1757.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip hinge holding a dumbbell. Works the glutes and hamstrings and improves balance.\",\"fv\":\"2635\"},{\"id\":\"2805\",\"n\":\"dumbbell single leg deadlift with stepbox support\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet hip-width apart, holding a dumbbell in your right hand.\",\"Place your left foot on a stepbox or elevated surface behind you.\",\"Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.\",\"As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.\",\"Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"2805.webp\",\"gif\":\"2805.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg dumbbell deadlift with the rear foot supported on a step box. Works the glutes and hamstrings.\",\"mv\":\"2806\"},{\"id\":\"0410\",\"n\":\"dumbbell single leg split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.\",\"Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.\",\"Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"0410.webp\",\"gif\":\"0410.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with a dumbbell where the rear foot is raised or the body shifts to one leg. It builds the thighs and glutes and challenges balance.\"},{\"id\":\"0411\",\"n\":\"dumbbell single leg squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Extend one leg forward and keep it off the ground throughout the exercise.\",\"Bend your standing leg and lower your body down as if sitting back into a chair.\",\"Keep your chest up and your back straight.\",\"Pause for a moment at the bottom, then push through your heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0411.webp\",\"gif\":\"0411.mp4\",\"cat\":\"strength\",\"desc\":\"You squat down on one leg while holding a dumbbell, then stand up. It builds single-leg strength and balance.\",\"fv\":\"3521\"},{\"id\":\"0413\",\"n\":\"dumbbell squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\",\"Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0413.webp\",\"gif\":\"0413.mp4\",\"cat\":\"strength\",\"desc\":\"Holding a dumbbell at your chest or sides, you squat down and stand back up. It builds the thighs and glutes.\",\"fv\":\"2220\"},{\"id\":\"3560\",\"n\":\"dumbbell standing alternate hammer curl and press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your body.\",\"Keep your elbows close to your torso and your back straight.\",\"Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the curl with your left hand.\",\"After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.\",\"Extend your arm fully and hold for a moment at the top.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat the press with your left hand.\",\"Continue alternating between curls and presses for the desired number of repetitions.\"],\"img\":\"3560.webp\",\"gif\":\"3560.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell sequence that alternates hammer curls with overhead presses. It trains the biceps and shoulders.\"},{\"id\":\"0414\",\"n\":\"dumbbell standing alternate overhead press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.\",\"Press one dumbbell overhead, fully extending your arm.\",\"Lower the dumbbell back to shoulder level.\",\"Repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0414.webp\",\"gif\":\"0414.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you press dumbbells overhead one arm at a time. It builds the shoulders and triceps while the core stays braced.\"},{\"id\":\"0415\",\"n\":\"dumbbell standing alternate raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.\",\"Keep your back straight and your core engaged.\",\"Raise one dumbbell to the side, keeping your arm straight and your palm facing down.\",\"Continue lifting until your arm is parallel to the ground.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat with the other arm.\",\"Alternate between arms for the desired number of repetitions.\"],\"img\":\"0415.webp\",\"gif\":\"0415.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you raise dumbbells one after the other. It works the shoulders with a controlled rhythm.\"},{\"id\":\"1739\",\"n\":\"dumbbell standing alternating tricep kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Extend your arms straight back, keeping your elbows close to your body.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat with the other arm, alternating sides with each repetition.\"],\"img\":\"1739.webp\",\"gif\":\"1739.mp4\",\"cat\":\"strength\",\"desc\":\"Standing kickbacks done one arm at a time with a hinged torso. Trains the triceps with a strong squeeze at full extension.\"},{\"id\":\"2143\",\"n\":\"dumbbell standing around world\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Extend your arms straight out to the sides at shoulder height, palms facing down.\",\"Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.\",\"Continue the circular motion, bringing the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2143.webp\",\"gif\":\"2143.mp4\",\"cat\":\"strength\",\"desc\":\"Dumbbell circles around the body with straight arms, going out to the side and overhead. Works the shoulders through a wide range.\"},{\"id\":\"1740\",\"n\":\"dumbbell standing bent over one arm triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand.\",\"Bend forward at the waist, keeping your back straight and parallel to the ground.\",\"Extend your arm straight back, keeping your elbow close to your body.\",\"Slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1740.webp\",\"gif\":\"1740.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm triceps extension performed bent over with the upper arm pinned to your side. Builds triceps strength and control.\"},{\"id\":\"1741\",\"n\":\"dumbbell standing bent over two arm triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend forward at the waist, keeping your back straight and your knees slightly bent.\",\"Extend your arms straight back, keeping your elbows close to your body.\",\"Slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1741.webp\",\"gif\":\"1741.mp4\",\"cat\":\"strength\",\"desc\":\"Both arms extend dumbbells backward at once from a hinged position. A simple way to load the triceps from the back of the arm.\"},{\"id\":\"0416\",\"n\":\"dumbbell standing biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0416.webp\",\"gif\":\"0416.mp4\",\"cat\":\"strength\",\"desc\":\"Standing tall, you curl dumbbells to your shoulders. The classic biceps builder.\"},{\"id\":\"0417\",\"n\":\"dumbbell standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand.\",\"Raise your heels off the ground as high as possible, using your calves.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0417.webp\",\"gif\":\"0417.mp4\",\"cat\":\"strength\",\"desc\":\"Holding dumbbells, you rise onto your toes and lower slowly. It builds the calf muscles.\",\"fv\":\"2210\"},{\"id\":\"0418\",\"n\":\"dumbbell standing concentration curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.\",\"Place your opposite hand on your thigh for support.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0418.webp\",\"gif\":\"0418.mp4\",\"cat\":\"strength\",\"desc\":\"Standing and leaning slightly forward, you curl a dumbbell with your elbow against your inner thigh. It isolates the biceps.\"},{\"id\":\"0419\",\"n\":\"dumbbell standing front raise above head\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Keep your arms straight and lift the dumbbells in front of you, raising them above your head.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0419.webp\",\"gif\":\"0419.mp4\",\"cat\":\"strength\",\"desc\":\"You lift dumbbells in front of you and up above head height. It works the front shoulders and upper chest.\"},{\"id\":\"2321\",\"n\":\"dumbbell standing inner biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your torso.\",\"Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\",\"While holding your upper arms stationary, curl the weights while contracting your biceps.\",\"Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Slowly begin to bring the dumbbells back to the starting position as your breathe in.\",\"Repeat for the recommended amount of repetitions.\"],\"img\":\"2321.webp\",\"gif\":\"2321.mp4\",\"cat\":\"strength\",\"desc\":\"A standing biceps curl with the palms turning to face forward as you lift. Works the biceps and brachialis.\"},{\"id\":\"0420\",\"n\":\"dumbbell standing kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Extend your arms straight back, squeezing your triceps at the top of the movement.\",\"Pause for a moment, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0420.webp\",\"gif\":\"0420.mp4\",\"cat\":\"strength\",\"desc\":\"Bent forward, you straighten your arms behind you with dumbbells. It isolates the triceps.\",\"fv\":\"2598\"},{\"id\":\"0421\",\"n\":\"dumbbell standing one arm concentration curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.\",\"Place your free hand on your thigh for support.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.\",\"Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0421.webp\",\"gif\":\"0421.mp4\",\"cat\":\"strength\",\"desc\":\"Standing and leaning forward, you curl one dumbbell with your elbow braced on your thigh. It isolates the biceps one side at a time.\"},{\"id\":\"0422\",\"n\":\"dumbbell standing one arm curl (over incline bench)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.\",\"Place your other hand on an incline bench for support.\",\"Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"0422.webp\",\"gif\":\"0422.mp4\",\"cat\":\"strength\",\"desc\":\"Standing beside an incline bench, you curl one dumbbell with the upper arm braced on the pad. It keeps the biceps working without swing.\",\"fv\":\"3085\"},{\"id\":\"1680\",\"n\":\"dumbbell standing one arm curl over incline bench\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand.\",\"Place your other hand on an incline bench for support.\",\"Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1680.webp\",\"gif\":\"1680.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm curl with your chest over an incline bench. It isolates the biceps.\"},{\"id\":\"0423\",\"n\":\"dumbbell standing one arm extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand.\",\"Raise the dumbbell overhead, fully extending your arm.\",\"Keep your upper arm close to your head and perpendicular to the ground.\",\"Slowly lower the dumbbell behind your head, bending your elbow.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0423.webp\",\"gif\":\"0423.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you extend one arm overhead with a dumbbell, bending and straightening the elbow. It works the back of the upper arm.\"},{\"id\":\"0424\",\"n\":\"dumbbell standing one arm palm in press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.\",\"Engage your core and keep your back straight.\",\"Press the dumbbell upwards until your arm is fully extended.\",\"Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0424.webp\",\"gif\":\"0424.mp4\",\"cat\":\"strength\",\"desc\":\"You press one dumbbell overhead with the palm facing in. It trains the shoulders and triceps, with a joint-friendly grip.\"},{\"id\":\"0425\",\"n\":\"dumbbell standing one arm reverse curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.\",\"Keep your arm fully extended and close to your body, with your palm facing down.\",\"Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.\",\"Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0425.webp\",\"gif\":\"0425.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you curl one dumbbell with an overhand grip. It works the biceps, the muscle under them and the forearm.\"},{\"id\":\"0426\",\"n\":\"dumbbell standing overhead press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0426.webp\",\"gif\":\"0426.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you press dumbbells from your shoulders to overhead. It builds the shoulders, triceps and trunk stability.\",\"fv\":\"2380\"},{\"id\":\"0427\",\"n\":\"dumbbell standing palms in press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.\",\"Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0427.webp\",\"gif\":\"0427.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you press dumbbells overhead with palms facing each other. It builds the shoulders and triceps.\",\"fv\":\"2599\"},{\"id\":\"0428\",\"n\":\"dumbbell standing preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.\",\"Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0428.webp\",\"gif\":\"0428.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with the upper arms supported on a preacher pad. It isolates the biceps through a strict range.\"},{\"id\":\"0429\",\"n\":\"dumbbell standing reverse curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0429.webp\",\"gif\":\"0429.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you curl dumbbells with an overhand grip. It builds the muscle under the biceps and the forearms.\"},{\"id\":\"0430\",\"n\":\"dumbbell standing triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand.\",\"Raise the dumbbell overhead, keeping your arm straight.\",\"Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.\",\"Extend your arm back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0430.webp\",\"gif\":\"0430.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you lower a dumbbell behind your head and press it back up. It builds the back of the upper arm.\",\"fv\":\"2390\"},{\"id\":\"2293\",\"n\":\"dumbbell standing zottman preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward.\",\"Place your upper arms against the preacher bench and keep your elbows slightly bent.\",\"Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.\",\"At the top of the movement, rotate your wrists so that your palms are facing downward.\",\"Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2293.webp\",\"gif\":\"2293.mp4\",\"cat\":\"strength\",\"desc\":\"A standing zottman curl against a preacher bench, curling up then turning your palms down to lower. Works the biceps and forearms.\"},{\"id\":\"1684\",\"n\":\"dumbbell step up single leg balance with bicep curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\"],\"st\":[\"Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.\",\"Place your right foot on the step, ensuring your entire foot is in contact with the surface.\",\"Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.\",\"At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.\",\"Lower the dumbbells back down and simultaneously lower your left foot back to the ground.\",\"Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1684.webp\",\"gif\":\"1684.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg step up combined with a bicep curl. It trains the biceps, glutes and balance.\"},{\"id\":\"0431\",\"n\":\"dumbbell step-up\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.\",\"Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.\",\"Push through your right heel and lift your body up onto the bench or step, straightening your right leg.\",\"Bring your left foot up onto the bench or step, standing fully upright.\",\"Step back down with your left foot, followed by your right foot, returning to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0431.webp\",\"gif\":\"0431.mp4\",\"cat\":\"strength\",\"desc\":\"Holding dumbbells, you step up onto a bench or box and step down. It builds the glutes and thighs, one leg at a time.\",\"fv\":\"2221\"},{\"id\":\"2796\",\"n\":\"dumbbell step-up lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.\",\"Place your right foot on the step, ensuring your entire foot is on the surface.\",\"Push through your right heel and lift your body up onto the step, bringing your left foot up as well.\",\"Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.\",\"Repeat the movement, alternating which foot you step up with each time.\",\"Continue for the desired number of repetitions.\"],\"img\":\"2796.webp\",\"gif\":\"2796.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell step-up that finishes with a lunge motion. Builds the quads and glutes.\",\"mv\":\"2795\"},{\"id\":\"2812\",\"n\":\"dumbbell step-up split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.\",\"Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.\",\"Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.\",\"As you step up, simultaneously lift your left knee towards your chest.\",\"Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.\",\"Repeat the movement with your left foot on the bench or step.\",\"Continue alternating between your right and left foot for the desired number of repetitions.\"],\"img\":\"2812.webp\",\"gif\":\"2812.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell step-up combined with a knee drive. Builds the quads and glutes.\",\"fv\":\"2813\"},{\"id\":\"0432\",\"n\":\"dumbbell stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.\",\"Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0432.webp\",\"gif\":\"0432.mp4\",\"cat\":\"strength\",\"desc\":\"With soft knees, you lower dumbbells down your legs and stand back up. It trains the hamstrings, glutes and lower back.\",\"fv\":\"2636\"},{\"id\":\"0433\",\"n\":\"dumbbell straight arm pullover\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"latissimus dorsi\",\"sm\":[\"latissimus dorsi\",\"triceps\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet planted firmly on the ground.\",\"Hold a dumbbell with both hands and extend your arms straight above your chest.\",\"Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.\",\"Pause for a moment, then raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0433.webp\",\"gif\":\"0433.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you move a dumbbell in an arc over your head with straight arms and bring it back over your chest. It works the chest and lats.\",\"nd\":[\"bench\"],\"fv\":\"2241\"},{\"id\":\"0434\",\"n\":\"dumbbell straight leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.\",\"Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.\",\"Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0434.webp\",\"gif\":\"0434.mp4\",\"cat\":\"strength\",\"desc\":\"You hinge at the hips with nearly straight legs and lower dumbbells down your legs. It builds the hamstrings and glutes.\"},{\"id\":\"2808\",\"n\":\"dumbbell sumo pull through\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointed outwards.\",\"Hold a dumbbell with both hands in front of your body, arms extended.\",\"Bend your knees and lower your hips down into a squat position, keeping your back straight.\",\"Lower the dumbbell down between your legs, keeping your arms straight.\",\"Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.\",\"Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2808.webp\",\"gif\":\"2808.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo-stance dumbbell pull through between the legs. Trains the glutes and hamstrings.\",\"mv\":\"2807\"},{\"id\":\"2803\",\"n\":\"dumbbell supported squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\",\"Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2803.webp\",\"gif\":\"2803.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell squat done with a support for balance. Builds the quads and glutes.\",\"mv\":\"2804\"},{\"id\":\"0436\",\"n\":\"dumbbell tate press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a flat bench with a dumbbell in each hand, palms facing each other.\",\"Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.\",\"Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.\",\"Rotate your wrists back to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0436.webp\",\"gif\":\"0436.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you lower dumbbells to your chest with elbows flared and press back up. It strongly targets the triceps.\"},{\"id\":\"1742\",\"n\":\"dumbbell tricep kickback with stork stance\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Bring your right elbow up to your side, keeping it bent at a 90-degree angle.\",\"Extend your right arm straight back, squeezing your triceps.\",\"Pause for a moment, then slowly lower the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1742.webp\",\"gif\":\"1742.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps kickback done in a stork stance, balancing on one leg. Adds a balance challenge to the usual triceps isolation.\"},{\"id\":\"1743\",\"n\":\"dumbbell twisting bench press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Hold a dumbbell in each hand with an overhand grip, palms facing away from you.\",\"Extend your arms straight up over your chest, keeping a slight bend in your elbows.\",\"Lower the dumbbells down towards your chest, keeping your elbows close to your body.\",\"As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.\",\"Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.\",\"As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1743.webp\",\"gif\":\"1743.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell bench press with a wrist twist through the rep. Works chest and triceps while adding a rotating element.\"},{\"id\":\"0437\",\"n\":\"dumbbell upright row\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Let the dumbbells hang in front of your thighs, with your arms fully extended.\",\"Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0437.webp\",\"gif\":\"0437.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you pull dumbbells up along your body toward chin height. It builds the side shoulders and upper traps.\",\"fv\":\"3431\"},{\"id\":\"1765\",\"n\":\"dumbbell upright row (back pov)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\",\"Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.\",\"Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.\",\"Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1765.webp\",\"gif\":\"1765.mp4\",\"cat\":\"strength\",\"desc\":\"A standing upright row with dumbbells, pulling the weights up toward your chin. Trains the shoulders and traps.\"},{\"id\":\"0864\",\"n\":\"dumbbell upright shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"trapezius\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.\",\"Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.\",\"Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.\",\"Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0864.webp\",\"gif\":\"0864.mp4\",\"cat\":\"strength\",\"desc\":\"A shoulder exercise raising the arms to the side and rotating the dumbbells upward. It strengthens the rotator cuff and delts.\"},{\"id\":\"5201\",\"n\":\"dumbbell waiter biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing forward.\",\"Keep your upper arms close to your body and your elbows tucked in.\",\"Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.\",\"Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"5201.webp\",\"gif\":\"5201.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell curl in which the weights are held and curled up in front of the shoulders. It trains the biceps.\"},{\"id\":\"0438\",\"n\":\"dumbbell w-press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing forward.\",\"Raise the dumbbells to shoulder height, elbows bent and palms facing forward.\",\"Press the dumbbells upward until your arms are fully extended overhead.\",\"Lower the dumbbells back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0438.webp\",\"gif\":\"0438.mp4\",\"cat\":\"strength\",\"desc\":\"You press dumbbells overhead in a W-shaped path. It trains the shoulders and the muscles that stabilise them.\",\"fv\":\"3432\"},{\"id\":\"0439\",\"n\":\"dumbbell zottman curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your body.\",\"Keep your elbows close to your torso and rotate your palms to face forward.\",\"Curl the dumbbells up to your shoulders while keeping your upper arms stationary.\",\"At the top of the movement, rotate your wrists so that your palms are facing away from your body.\",\"Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0439.webp\",\"gif\":\"0439.mp4\",\"cat\":\"strength\",\"desc\":\"You curl up with palms up, rotate the palms down, and lower slowly. It works the biceps on the way up and the forearms on the way down.\"},{\"id\":\"2294\",\"n\":\"dumbbell zottman preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.\",\"Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.\",\"At the top of the curl, rotate your wrists so that your palms are facing down.\",\"Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2294.webp\",\"gif\":\"2294.mp4\",\"cat\":\"strength\",\"desc\":\"A seated zottman curl on a preacher bench, curling up then turning your palms down to lower. Works the biceps and forearms.\"},{\"id\":\"2189\",\"n\":\"dumbbells seated triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a dumbbell in both hands with an overhand grip, and raise it above your head.\",\"Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.\",\"Extend your arms and raise the dumbbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2189.webp\",\"gif\":\"2189.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension with one dumbbell held in both hands. Builds the back of the upper arms.\"},{\"id\":\"1167\",\"n\":\"dynamic chest stretch (male)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand tall with your feet shoulder-width apart.\",\"Extend your arms straight out to the sides, parallel to the ground.\",\"Slowly bring your arms forward, crossing them in front of your body.\",\"Feel the stretch in your chest muscles.\",\"Hold the stretch for 10-30 seconds.\",\"Return to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"1167.webp\",\"gif\":\"1167.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic chest stretch, swinging the arms out and across the chest. It loosens the chest and shoulders.\",\"fv\":\"0441\"},{\"id\":\"3287\",\"n\":\"elbow dips\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.\",\"Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.\",\"Bend your elbows and lower your body towards the ground, keeping your back close to the bench.\",\"Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3287.webp\",\"gif\":\"3287.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bench dip variation that bends the elbows to lower the hips. It trains the triceps and the front of the shoulders.\"},{\"id\":\"1772\",\"n\":\"elbow lift - reverse push-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.\",\"Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.\",\"Pause at the top for a moment, squeezing your upper back muscles.\",\"Slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1772.webp\",\"gif\":\"1772.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor push-up variation that lifts the upper body with elbows close to your sides. Works the upper back and posture muscles.\"},{\"id\":\"0443\",\"n\":\"elbow-to-knee\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Start by lying flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.\",\"At the same time, bring your left knee towards your right elbow, creating a twisting motion.\",\"Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.\",\"Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0443.webp\",\"gif\":\"0443.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing or floor crunch where you bring an elbow toward the opposite knee. It trains the abs and obliques.\"},{\"id\":\"3292\",\"n\":\"elevator\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"trapezius\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Place your hands on your hips or cross them in front of your chest.\",\"Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.\",\"Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3292.webp\",\"gif\":\"3292.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight hinge forward and back up again with the hands on the hips. It works the upper back and the muscles along the spine.\"},{\"id\":\"1332\",\"n\":\"exercise ball alternating arm ups\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.\",\"Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.\",\"Pause for a moment at the top, then slowly lower your arm back down to the starting position.\",\"Repeat the movement with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"1332.webp\",\"gif\":\"1332.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a stability ball, you raise dumbbells one arm at a time. It trains the shoulders and upper back while your core keeps you balanced.\"},{\"id\":\"1333\",\"n\":\"exercise ball back extension with arms extended\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.\",\"Extend your arms straight out in front of you, with your palms facing down.\",\"Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1333.webp\",\"gif\":\"1333.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down on a stability ball with your arms reaching forward and lift your torso. It strengthens the lower back and glutes with extra leverage.\"},{\"id\":\"1334\",\"n\":\"exercise ball back extension with hands behind head\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.\",\"Position your feet against a wall or other stable surface for support.\",\"Cross your arms behind your head, with your hands touching the back of your head.\",\"Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.\",\"Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1334.webp\",\"gif\":\"1334.mp4\",\"cat\":\"strength\",\"desc\":\"A stability ball back extension with your hands behind your head. It strengthens the lower back, glutes and upper back.\",\"fv\":\"2821\"},{\"id\":\"1335\",\"n\":\"exercise ball back extension with knees off ground\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.\",\"Position your hands behind your head or crossed over your chest.\",\"Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1335.webp\",\"gif\":\"1335.mp4\",\"cat\":\"strength\",\"desc\":\"A back extension on a stability ball with your legs braced so your knees stay off the ground. It works the lower back and glutes.\"},{\"id\":\"1336\",\"n\":\"exercise ball back extension with rotation\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.\",\"Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.\",\"Return to the center and repeat the rotation to the other side.\",\"Lower your upper body back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"1336.webp\",\"gif\":\"1336.mp4\",\"cat\":\"strength\",\"desc\":\"A stability ball back extension where you add a twist at the top. It trains the lower back, glutes and obliques.\"},{\"id\":\"1744\",\"n\":\"exercise ball dip\",\"bp\":\"upper arms\",\"eq\":\"stability ball\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Place your hands on the ball beside your hips, fingers pointing forward.\",\"Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.\",\"Lower your body back down by bending your elbows, keeping them close to your sides.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1744.webp\",\"gif\":\"1744.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight dip using a stability ball as the support. The unstable surface makes your triceps and shoulders work harder to stay steady.\"},{\"id\":\"1559\",\"n\":\"exercise ball hip flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\"],\"st\":[\"Place the stability ball on the ground and kneel in front of it.\",\"Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.\",\"Extend your left leg behind you, keeping it straight.\",\"Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.\",\"Hold the stretch for 20-30 seconds, then switch sides and repeat.\"],\"img\":\"1559.webp\",\"gif\":\"1559.mp4\",\"cat\":\"stretching\",\"desc\":\"You kneel with a stability ball for support and push the hips forward. It stretches the hip flexors at the front of the hip.\"},{\"id\":\"1338\",\"n\":\"exercise ball hug\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your back straight.\",\"Hold the stability ball with both hands, hugging it close to your chest.\",\"Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.\",\"Continue leaning back until you feel a stretch in your back muscles.\",\"Hold the position for a few seconds, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1338.webp\",\"gif\":\"1338.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit on a stability ball and lean back into it while hugging the ball. It gently opens up the back and stretches the spine.\"},{\"id\":\"1339\",\"n\":\"exercise ball lat stretch\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand and extend your arm straight up overhead.\",\"Slowly lean to the opposite side, feeling a stretch in your lat muscle.\",\"Hold the stretch for 20-30 seconds, then return to the starting position.\",\"Repeat on the other side.\"],\"img\":\"1339.webp\",\"gif\":\"1339.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit on a stability ball and reach one arm overhead as you lean to the other side. It stretches the lat and the side of your torso.\"},{\"id\":\"1341\",\"n\":\"exercise ball lower back stretch (pyramid)\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"lats\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.\",\"Hold the stretch for a few seconds, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1341.webp\",\"gif\":\"1341.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie back over a stability ball to open up and stretch the lower back. It is a gentle, supported way to ease tightness.\"},{\"id\":\"1342\",\"n\":\"exercise ball lying side lat stretch\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Lie on your side with your legs extended and your head supported by the stability ball.\",\"Place your top arm on the ball for stability.\",\"Reach your top arm overhead and allow your torso to rotate slightly.\",\"Feel the stretch in your lat muscles on the side of your body.\",\"Hold the stretch for 20-30 seconds, then switch sides and repeat.\"],\"img\":\"1342.webp\",\"gif\":\"1342.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie on your side with a stability ball supporting you and reach overhead. It stretches the lat and the side of your torso.\"},{\"id\":\"1382\",\"n\":\"exercise ball on the wall calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Stand with your back against a wall and place an exercise ball between your lower back and the wall.\",\"Position your feet shoulder-width apart, with your toes pointing forward.\",\"Hold a dumbbell in each hand, with your arms extended by your sides.\",\"Raise your heels off the ground, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1382.webp\",\"gif\":\"1382.mp4\",\"cat\":\"strength\",\"desc\":\"Calf raises with a stability ball held between your back and a wall. It works the calves while the ball helps you stay balanced.\"},{\"id\":\"3241\",\"n\":\"exercise ball on the wall calf raise (tennis ball between ankles)\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Stand facing a wall with your feet shoulder-width apart.\",\"Place an exercise ball between the wall and your lower back.\",\"Hold a dumbbell in each hand, with your arms extended by your sides.\",\"Place a tennis ball between your ankles.\",\"Raise your heels off the ground, lifting your body up onto your toes.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3241.webp\",\"gif\":\"3241.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise with your back on an exercise ball against a wall, dumbbells in hand, and a ball squeezed between the ankles. It trains the calves.\"},{\"id\":\"3240\",\"n\":\"exercise ball on the wall calf raise (tennis ball between knees)\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\"],\"st\":[\"Stand with your back against a wall and place an exercise ball between your lower back and the wall.\",\"Position your feet shoulder-width apart and slightly in front of you.\",\"Hold a dumbbell in each hand, with your arms extended by your sides.\",\"Place a tennis ball between your knees.\",\"Raise your heels off the ground, lifting your body up onto your toes.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3240.webp\",\"gif\":\"3240.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise with your back on an exercise ball against a wall, dumbbells in hand, and a ball squeezed between the knees. It trains the calves and inner thighs.\"},{\"id\":\"1416\",\"n\":\"exercise ball one leg prone lower body rotation\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.\",\"Place your hands on the ground in front of you for support.\",\"Engage your glutes and core muscles to stabilize your body.\",\"Slowly lift one leg off the ground, keeping it straight and parallel to the floor.\",\"Rotate your leg outward, away from your body, while keeping your hips and upper body stable.\",\"Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.\",\"Repeat the rotation with the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"1416.webp\",\"gif\":\"1416.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down over a stability ball with one leg lifted and rotate it slightly. It strengthens the glutes and hips while your core balances.\"},{\"id\":\"1417\",\"n\":\"exercise ball one legged diagonal kick hamstring curl\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"calves\"],\"st\":[\"Start by lying on your back with your legs extended and your heels resting on top of the stability ball.\",\"Place your arms by your sides for stability.\",\"Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.\",\"Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.\",\"Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.\",\"Slowly return your right leg to the starting position, maintaining control and stability.\",\"Repeat the movement with your left leg, alternating sides for the desired number of repetitions.\"],\"img\":\"1417.webp\",\"gif\":\"1417.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on your back with your heels on a stability ball and curl one leg toward you while kicking diagonally. It works the hamstrings, glutes and core.\",\"fv\":\"2825\"},{\"id\":\"1296\",\"n\":\"exercise ball pike push up\",\"bp\":\"chest\",\"eq\":\"stability ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a push-up position with your hands on the floor and your shins resting on the stability ball.\",\"Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.\",\"Keep your legs straight and your body in a pike position, forming an inverted V shape.\",\"Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.\",\"Push through your hands and extend your arms to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1296.webp\",\"gif\":\"1296.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push-up with your feet on a stability ball. It builds shoulders and chest and works your core to hold the ball steady.\"},{\"id\":\"1343\",\"n\":\"exercise ball prone leg raise\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"abdominals\",\"sm\":[\"abdominals\",\"glutes\"],\"st\":[\"Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.\",\"Place your hands on the ground, shoulder-width apart, and engage your core muscles.\",\"Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1343.webp\",\"gif\":\"1343.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down with your toes on a stability ball and lift your legs. It works the lower back and glutes with a gentle range.\"},{\"id\":\"1560\",\"n\":\"exercise ball seated hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.\",\"Place your hands on your hips for support.\",\"Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.\",\"Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.\",\"Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1560.webp\",\"gif\":\"1560.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated on a stability ball with one leg extended, you lean forward to stretch the back of the thigh.\"},{\"id\":\"1745\",\"n\":\"exercise ball seated triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"stability ball\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your back straight.\",\"Hold a dumbbell in one hand and extend your arm straight up above your head.\",\"Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.\",\"Hold the stretch for a few seconds, then return to the starting position.\",\"Repeat with the other arm.\"],\"img\":\"1745.webp\",\"gif\":\"1745.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated overhead stretch for the back of the upper arm, done on a stability ball. Helps loosen tight triceps and shoulders.\"},{\"id\":\"1746\",\"n\":\"exercise ball supine triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.\",\"Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.\",\"Pause for a moment, then raise the dumbbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1746.webp\",\"gif\":\"1746.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell triceps extension done on an exercise ball, lowering the weight behind your head. Targets the triceps and challenges your balance.\"},{\"id\":\"1747\",\"n\":\"ez bar french press on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on an exercise ball and hold an EZ barbell with an overhand grip.\",\"Extend your arms straight up, keeping your elbows close to your head.\",\"Slowly lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1747.webp\",\"gif\":\"1747.mp4\",\"cat\":\"strength\",\"desc\":\"A french press with an EZ bar while seated on an exercise ball. Builds triceps strength and asks your core to keep you stable.\"},{\"id\":\"3010\",\"n\":\"ez bar lying bent arms pullover\",\"bp\":\"back\",\"eq\":\"ez barbell\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Lie flat on a bench with your head at one end and your feet on the floor.\",\"Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.\",\"Extend your arms straight above your chest, keeping a slight bend in your elbows.\",\"Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.\",\"Pause for a moment, then return the barbell to the starting position by reversing the arc motion.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3010.webp\",\"gif\":\"3010.mp4\",\"cat\":\"strength\",\"desc\":\"A lying EZ bar pullover with slightly bent arms. Works the lats and chest.\",\"nd\":[\"bench\"]},{\"id\":\"1748\",\"n\":\"ez bar lying close grip triceps extension behind head\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.\",\"Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.\",\"Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1748.webp\",\"gif\":\"1748.mp4\",\"cat\":\"strength\",\"desc\":\"A lying close-grip extension with an EZ bar, lowering the bar behind your head. Puts strong focus on the long head of the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"1344\",\"n\":\"ez bar reverse grip bent over row\",\"bp\":\"back\",\"eq\":\"ez barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.\",\"Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.\",\"Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1344.webp\",\"gif\":\"1344.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over row with an ez barbell and an underhand grip. It targets the upper back and lats with extra work for the biceps.\"},{\"id\":\"1682\",\"n\":\"ez bar seated close grip concentration curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.\",\"Rest your elbow on the inside of your thigh, just above the knee.\",\"Curl the barbell up towards your shoulder while keeping your upper arm stationary.\",\"Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1682.webp\",\"gif\":\"1682.mp4\",\"cat\":\"strength\",\"desc\":\"A seated close grip concentration curl using an EZ bar. It isolates the biceps with strict form.\"},{\"id\":\"1749\",\"n\":\"ez bar standing french press\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.\",\"Raise the barbell above your head, fully extending your arms.\",\"Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1749.webp\",\"gif\":\"1749.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead EZ bar extension, bending only at the elbows. Builds triceps size and strength.\"},{\"id\":\"0445\",\"n\":\"ez barbell anti gravity press\",\"bp\":\"shoulders\",\"eq\":\"ez barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.\",\"Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.\",\"Press the barbell overhead, extending your arms fully.\",\"Lower the barbell back to shoulder height and repeat for the desired number of repetitions.\"],\"img\":\"0445.webp\",\"gif\":\"0445.mp4\",\"cat\":\"strength\",\"desc\":\"An EZ-bar press with a gravity-fighting path that works the shoulders and triceps. Keep the movement smooth and controlled.\",\"fv\":\"3603\"},{\"id\":\"1627\",\"n\":\"ez barbell close grip preacher curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.\",\"Rest your triceps on the pad and fully extend your arms, keeping your back straight.\",\"Slowly curl the barbell towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Lower the barbell back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1627.webp\",\"gif\":\"1627.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with an EZ bar and a close grip. It emphasizes the outer biceps.\"},{\"id\":\"0446\",\"n\":\"ez barbell close-grip curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.\",\"Keep your elbows close to your torso and your upper arms stationary throughout the movement.\",\"Curl the barbell up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0446.webp\",\"gif\":\"0446.mp4\",\"cat\":\"strength\",\"desc\":\"You curl an EZ bar with a narrow grip. It emphasises the outer part of the biceps.\",\"fv\":\"2499\"},{\"id\":\"0447\",\"n\":\"ez barbell curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.\",\"Keep your elbows close to your torso and your upper arms stationary throughout the movement.\",\"Exhale as you curl the barbell up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0447.webp\",\"gif\":\"0447.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you curl an EZ bar to your shoulders. The angled grip is easier on the wrists while working the biceps.\",\"fv\":\"2238\"},{\"id\":\"0448\",\"n\":\"ez barbell decline close grip face press\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your head lower than your feet.\",\"Grasp the ez barbell with a close grip, palms facing each other.\",\"Extend your arms straight up above your chest, keeping your elbows close to your body.\",\"Lower the barbell towards your forehead by bending your elbows.\",\"Pause for a moment, then press the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0448.webp\",\"gif\":\"0448.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a decline bench, you lower an EZ bar toward your face with a close grip and press up. It strongly works the triceps.\",\"fv\":\"2884\"},{\"id\":\"2186\",\"n\":\"ez barbell decline triceps extension\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie on a decline bench with your head lower than your feet and your feet secured.\",\"Hold the ez barbell with an overhand grip, hands shoulder-width apart.\",\"Extend your arms fully, keeping your elbows close to your head.\",\"Lower the barbell slowly towards your forehead, bending your elbows.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2186.webp\",\"gif\":\"2186.mp4\",\"cat\":\"strength\",\"desc\":\"A decline EZ bar triceps extension lowering the bar toward your forehead. Builds triceps strength.\"},{\"id\":\"0449\",\"n\":\"ez barbell incline triceps extension\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.\",\"Extend your arms fully overhead, keeping your elbows close to your head.\",\"Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0449.webp\",\"gif\":\"0449.mp4\",\"cat\":\"strength\",\"desc\":\"On an incline bench, you lower an EZ bar behind your head and extend your arms. It stretches and works the triceps.\"},{\"id\":\"0450\",\"n\":\"ez barbell jm bench press\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lower the barbell to your chest, keeping your elbows tucked in close to your body.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0450.webp\",\"gif\":\"0450.mp4\",\"cat\":\"strength\",\"desc\":\"A hybrid between a close-grip press and a skull crusher using an EZ bar. It builds the triceps and the front of the shoulders.\"},{\"id\":\"0451\",\"n\":\"ez barbell reverse grip curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.\",\"Keep your elbows close to your torso and your upper arms stationary throughout the exercise.\",\"Curl the barbell upwards by contracting your biceps, while exhaling.\",\"Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Slowly begin to bring the barbell back to the starting position as you inhale.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0451.webp\",\"gif\":\"0451.mp4\",\"cat\":\"strength\",\"desc\":\"You curl an EZ bar with an overhand grip. It works the biceps, the muscle under them and the forearms.\",\"fv\":\"2498\"},{\"id\":\"0452\",\"n\":\"ez barbell reverse grip preacher curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a preacher bench with your chest against the pad and your feet flat on the floor.\",\"Grasp the ez barbell with an underhand grip, hands shoulder-width apart.\",\"Rest your upper arms on the pad, allowing your forearms to hang down.\",\"Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.\",\"Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0452.webp\",\"gif\":\"0452.mp4\",\"cat\":\"strength\",\"desc\":\"At a preacher bench, you curl an EZ bar with an overhand grip. It strengthens the forearms and upper arm flexors.\"},{\"id\":\"1458\",\"n\":\"ez barbell seated curls\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a bench with your feet flat on the ground and your back straight.\",\"Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.\",\"Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.\",\"Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the ez barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1458.webp\",\"gif\":\"1458.mp4\",\"cat\":\"strength\",\"desc\":\"Seated curls with an EZ bar, which is gentler on the wrists. A good way to build the biceps without swinging your body.\"},{\"id\":\"0453\",\"n\":\"ez barbell seated triceps extension\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold the ez barbell with an overhand grip, hands shoulder-width apart.\",\"Raise the barbell overhead, fully extending your arms.\",\"Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then raise the barbell back to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0453.webp\",\"gif\":\"0453.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you lower an EZ bar behind your head and extend your arms. It builds the back of the upper arm.\"},{\"id\":\"0454\",\"n\":\"ez barbell spider curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.\",\"Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.\",\"Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0454.webp\",\"gif\":\"0454.mp4\",\"cat\":\"strength\",\"desc\":\"Chest down on an incline bench, you curl an EZ bar from a hanging position. It isolates the biceps with a strict range.\"},{\"id\":\"1628\",\"n\":\"ez barbell spider curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.\",\"Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.\",\"Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1628.webp\",\"gif\":\"1628.mp4\",\"cat\":\"strength\",\"desc\":\"A spider curl with an EZ bar, lying chest down on an incline bench. It isolates the biceps with no swing.\"},{\"id\":\"2404\",\"n\":\"ez-bar biceps curl (with arm blaster)\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.\",\"Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.\",\"Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the barbell back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2404.webp\",\"gif\":\"2404.mp4\",\"cat\":\"strength\",\"desc\":\"An EZ bar curl with an arm blaster. Isolates the biceps with a comfortable wrist angle.\",\"fv\":\"3087\"},{\"id\":\"2432\",\"n\":\"ez-bar close-grip bench press\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\",\"Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.\",\"Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.\",\"Slowly lower the barbell towards your chest, keeping your elbows close to your body.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2432.webp\",\"gif\":\"2432.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip bench press with an EZ bar. Targets the triceps with less wrist strain.\",\"fv\":\"2433\"},{\"id\":\"2741\",\"n\":\"ez-barbell standing wide grip biceps curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.\",\"Keep your elbows close to your torso and your upper arms stationary throughout the movement.\",\"Curl the barbell up towards your shoulders by contracting your biceps.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2741.webp\",\"gif\":\"2741.mp4\",\"cat\":\"strength\",\"desc\":\"A standing EZ bar curl with a wide grip. Emphasises the biceps.\"},{\"id\":\"2133\",\"n\":\"farmers walk\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"forearms\",\"core\"],\"st\":[\"Stand up straight with a dumbbell in each hand, palms facing your sides.\",\"Keep your back straight and your shoulders back.\",\"Take small, controlled steps forward, maintaining an upright posture.\",\"Continue walking for the desired distance or time.\",\"To finish, stop walking and carefully lower the dumbbells to your sides.\"],\"img\":\"2133.webp\",\"gif\":\"2133.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded carry holding a dumbbell in each hand while walking tall. Builds grip, core and total-body strength.\"},{\"id\":\"0455\",\"n\":\"finger curls\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.\",\"Rest your forearms on your thighs, allowing your wrists to hang off the edge.\",\"Slowly curl your fingers towards your palms, squeezing the barbell tightly.\",\"Hold the contraction for a moment, then slowly release your fingers back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0455.webp\",\"gif\":\"0455.mp4\",\"cat\":\"strength\",\"desc\":\"You let a barbell roll to your fingertips and curl it back up. It builds finger and forearm strength for a better grip.\"},{\"id\":\"3303\",\"n\":\"flag\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.\",\"Engage your core and lift your legs off the ground, keeping them straight.\",\"Using your core and upper body strength, raise your legs until they are parallel to the ground.\",\"Hold this position for as long as you can, maintaining a straight body line.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3303.webp\",\"gif\":\"3303.mp4\",\"cat\":\"isometric\",\"desc\":\"A gymnastics hold where you grip a vertical pole and hold your body out to the side. It trains the obliques, shoulders and lats.\",\"hd\":1},{\"id\":\"0456\",\"n\":\"flexion leg sit up (bent knee)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.\",\"Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0456.webp\",\"gif\":\"0456.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with bent knees. It strengthens the abs and hip flexors.\"},{\"id\":\"0457\",\"n\":\"flexion leg sit up (straight arm)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie flat on your back with your legs extended and arms straight above your head.\",\"Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.\",\"Reach your hands towards your toes as you lift your upper body and legs.\",\"Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0457.webp\",\"gif\":\"0457.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with the arms straight. It works the abs and hip flexors.\",\"fv\":\"4284\"},{\"id\":\"0458\",\"n\":\"floor fly (with barbell)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Lie flat on your back on the floor with your knees bent and feet flat on the ground.\",\"Hold a barbell with an overhand grip, arms extended straight up over your chest.\",\"Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.\",\"Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.\",\"Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0458.webp\",\"gif\":\"0458.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on the floor, you open your arms and press a barbell up. The floor limits the range, so it is easy on the shoulders while it works the chest.\"},{\"id\":\"0459\",\"n\":\"flutter kicks\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie flat on your back with your legs extended and your hands by your sides.\",\"Engage your core and lift your legs off the ground about 6 inches.\",\"Keeping your legs straight, alternate lifting one leg slightly higher than the other.\",\"Continue this fluttering motion for the desired number of repetitions.\"],\"img\":\"0459.webp\",\"gif\":\"0459.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You lie on your back and kick your legs up and down in small alternating motions. It works the lower abs and hip flexors.\"},{\"id\":\"1472\",\"n\":\"forward jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees and lower your body into a squat position.\",\"Swing your arms back for momentum.\",\"Jump forward explosively, extending your hips, knees, and ankles.\",\"Land softly on the balls of your feet and immediately go into the next jump.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1472.webp\",\"gif\":\"1472.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bodyweight jump forward with a soft landing. It builds explosive power in the quads and glutes.\"},{\"id\":\"3470\",\"n\":\"forward lunge (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet hip-width apart and hands on your hips.\",\"Take a big step forward with your right foot, lowering your body into a lunge position.\",\"Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.\",\"Push off with your right foot and return to the starting position.\",\"Repeat with your left leg, alternating sides for the desired number of repetitions.\"],\"img\":\"3470.webp\",\"gif\":\"3470.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight lunge stepping forward and pushing back, alternating legs. It builds the glutes, quads and balance.\"},{\"id\":\"3194\",\"n\":\"frankenstein squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.\",\"Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3194.webp\",\"gif\":\"3194.mp4\",\"cat\":\"strength\",\"desc\":\"A front-loaded barbell squat held out in front of the body with straight arms. It hits the glutes and quads and demands a tall, braced torso.\"},{\"id\":\"2429\",\"n\":\"frog crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2429.webp\",\"gif\":\"2429.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch that curls your upper body up with your knees bent. Works the abs.\",\"fv\":\"2522\"},{\"id\":\"3301\",\"n\":\"frog planche\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"triceps\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and your feet together.\",\"Bend your elbows and lower your body towards the ground, keeping your back straight.\",\"As you lower your body, lift your feet off the ground and bring your knees towards your chest.\",\"Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3301.webp\",\"gif\":\"3301.mp4\",\"cat\":\"isometric\",\"desc\":\"A planche hold with the knees tucked in toward the arms. It builds shoulder, chest and wrist strength as a stepping stone to the full planche.\",\"hd\":1},{\"id\":\"3296\",\"n\":\"front lever\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"forearms\"],\"st\":[\"Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.\",\"Engage your core and pull your shoulder blades down and back.\",\"Bend your knees and tuck them towards your chest.\",\"Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.\",\"Hold this position for as long as you can, aiming for a full front lever position.\",\"To release, slowly lower your legs back down and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3296.webp\",\"gif\":\"3296.mp4\",\"cat\":\"isometric\",\"desc\":\"A gymnastics hold with the body straight and parallel to the ground while hanging from a bar. It trains the abs, lats and upper back.\",\"hd\":1},{\"id\":\"3295\",\"n\":\"front lever reps\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with an overhand grip, palms facing away from you.\",\"Engage your core and pull your shoulder blades down and back.\",\"Keeping your body straight, lift your legs up until they are parallel to the ground.\",\"Hold this position for as long as you can, aiming for 10-20 seconds.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3295.webp\",\"gif\":\"3295.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A rep-based version of the front lever, pulling the body in a horizontal line from a bar. It trains the lats, upper back and core.\"},{\"id\":\"0464\",\"n\":\"front plank with twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.\",\"Engage your core and glutes to maintain a stable position.\",\"Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.\",\"Keep your hips and legs stable as you twist.\",\"Hold for a moment, then return to the starting position.\",\"Repeat the twist on the left side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0464.webp\",\"gif\":\"0464.mp4\",\"cat\":\"isometric\",\"desc\":\"A front plank with a trunk twist. It works the abs, obliques and shoulders while you stay stable.\"},{\"id\":\"3315\",\"n\":\"full maltese\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.\",\"Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.\",\"Engage your core and hold this position for a few seconds.\",\"Return to the starting position by pushing through your feet and standing back up.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3315.webp\",\"gif\":\"3315.mp4\",\"cat\":\"isometric\",\"desc\":\"An advanced gymnastics hold on rings with the arms out wide and the body straight. It demands huge strength in the chest, shoulders and core.\",\"hd\":1},{\"id\":\"3299\",\"n\":\"full planche\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"triceps\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.\",\"Engage your core and slowly shift your weight forward, lifting your feet off the ground.\",\"Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.\",\"Hold this position for as long as you can, maintaining a straight body line.\",\"Slowly lower your feet back to the ground and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3299.webp\",\"gif\":\"3299.mp4\",\"cat\":\"isometric\",\"desc\":\"A gymnastics hold where the body is parallel to the floor and balanced on the hands. It builds extreme strength in the shoulders, chest and core.\",\"hd\":1},{\"id\":\"3327\",\"n\":\"full planche push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a push-up position with your hands placed slightly wider than shoulder-width apart.\",\"Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.\",\"As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.\",\"Continue to lower your body until your chest is just above the ground.\",\"Push through your hands and extend your arms to lift your body back up to the starting position.\",\"Maintain a straight line from your head to your heels throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3327.webp\",\"gif\":\"3327.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up from the planche position with the feet off the ground. It is an elite bodyweight move for the chest, shoulders and triceps.\"},{\"id\":\"0466\",\"n\":\"gironda sternum chin\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Stand facing a high bar with your feet shoulder-width apart.\",\"Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body straight.\",\"Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.\",\"Pause for a moment at the top, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0466.webp\",\"gif\":\"0466.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up variation where you pull toward the sternum. It builds the lats, upper back and biceps.\"},{\"id\":\"3561\",\"n\":\"glute bridge march\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.\",\"While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.\",\"Lower your foot back to the ground and repeat the movement with the other leg.\",\"Continue alternating legs in a marching motion while maintaining the bridge position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3561.webp\",\"gif\":\"3561.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge held at the top while you alternate marching the knees. It trains the glutes and core stability.\"},{\"id\":\"3523\",\"n\":\"glute bridge two legs on bench (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Sit on the edge of a bench with your back against it and your feet flat on the ground.\",\"Place your hands on the bench beside your hips for support.\",\"Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3523.webp\",\"gif\":\"3523.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight glute bridge with the shoulders on a bench and both feet on the floor. It trains the glutes and hamstrings.\",\"fv\":\"2472\"},{\"id\":\"3193\",\"n\":\"glute-ham raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Adjust the glute-ham raise machine to fit your body.\",\"Position yourself face down on the machine with your ankles secured.\",\"Place your hands on your chest or cross them over your chest.\",\"Engage your hamstrings and glutes to lift your upper body up towards the ceiling.\",\"Continue lifting until your body is in a straight line from your head to your heels.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3193.webp\",\"gif\":\"3193.mp4\",\"cat\":\"strength\",\"desc\":\"A hamstring exercise where you lift your torso from a face-down position on a glute-ham bench. It strengthens the hamstrings, glutes and lower back.\"},{\"id\":\"0467\",\"n\":\"gorilla chin\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and pull your body up towards the bar, bringing your chin above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0467.webp\",\"gif\":\"0467.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up variation with a crunch at the top. It works the lats and abs together.\",\"fv\":\"2651\"},{\"id\":\"0469\",\"n\":\"groin crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"inner thighs\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0469.webp\",\"gif\":\"0469.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch that brings the knees and chest together. It targets the abs and the hip flexors.\",\"fv\":\"3089\"},{\"id\":\"1383\",\"n\":\"hack calf raise\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the sled machine to a comfortable weight.\",\"Stand on the sled machine with your toes on the platform and your heels hanging off.\",\"Hold onto the handles for stability.\",\"Raise your heels as high as possible by pushing through the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1383.webp\",\"gif\":\"1383.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise on a hack machine, pushing through the balls of your feet. It builds the calves under a supported load.\"},{\"id\":\"1384\",\"n\":\"hack one leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the sled machine to an appropriate weight.\",\"Stand on the sled machine with one foot, keeping the other foot off the ground.\",\"Hold onto the handles for stability.\",\"Raise your heel as high as possible, lifting your body up on the ball of your foot.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions.\",\"Switch legs and repeat the exercise.\"],\"img\":\"1384.webp\",\"gif\":\"1384.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf raise on a hack machine. It lets you train each calf on its own under a supported load.\"},{\"id\":\"3221\",\"n\":\"half knee bends (male)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees and lower your body down as if you were sitting back into a chair.\",\"Keep your chest up and your weight in your heels.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3221.webp\",\"gif\":\"3221.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A shallow squat that bends the knees only partway. It is a gentle leg exercise good for warming up or high rep sets.\"},{\"id\":\"3202\",\"n\":\"half sit-up (male)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3202.webp\",\"gif\":\"3202.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up that stops at roughly half height, keeping constant tension on the abs. A gentle way to train the midsection.\"},{\"id\":\"1511\",\"n\":\"hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Step forward with your right foot and shift your weight onto your right leg.\",\"Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.\",\"Hold the stretch for 20-30 seconds, then return to the starting position.\",\"Repeat on the other side.\"],\"img\":\"1511.webp\",\"gif\":\"1511.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the back of the thigh. You reach toward your toes with a long spine and feel the hamstrings lengthen.\",\"fv\":\"4285\"},{\"id\":\"2139\",\"n\":\"hands bike\",\"bp\":\"chest\",\"eq\":\"upper body ergometer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and handlebar position to a comfortable level.\",\"Sit on the ergometer with your back straight and feet on the pedals.\",\"Grasp the handles with your hands and position your arms at a 90-degree angle.\",\"Start pedaling with your hands, pushing and pulling the handles in a controlled motion.\",\"Continue pedaling for the desired duration or number of repetitions.\"],\"img\":\"2139.webp\",\"gif\":\"2139.mp4\",\"cat\":\"cardio\",\"desc\":\"Cranking pedals with your hands on an upper body ergometer. Gets your heart rate up using the arms and shoulders.\"},{\"id\":\"3218\",\"n\":\"hands clasped circular toe touch (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3218.webp\",\"gif\":\"3218.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing toe touch with the hands clasped and moved in a circular path. It stretches the hamstrings and warms up the hips and back.\"},{\"id\":\"3215\",\"n\":\"hands reversed clasped circular toe touch (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms extended to the sides.\",\"Bend forward at the waist, keeping your back straight and your knees slightly bent.\",\"Reach down with your hands and clasp them together behind your legs.\",\"Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.\",\"Continue the circular motion until your hands touch your toes.\",\"Reverse the motion and bring your hands back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3215.webp\",\"gif\":\"3215.mp4\",\"cat\":\"mobility\",\"desc\":\"A toe touch with the hands clasped in reverse and moved in a circle. It opens the hamstrings and back while warming up the hips.\"},{\"id\":\"3302\",\"n\":\"handstand\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Find an open space with enough room to perform a handstand.\",\"Place your hands on the ground shoulder-width apart, fingers pointing forward.\",\"Kick your legs up towards the wall, using your core and shoulders to maintain balance.\",\"Once in a handstand position, engage your triceps to support your body weight.\",\"Hold the handstand for as long as you can maintain balance.\",\"To come down, slowly lower your legs back to the ground.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3302.webp\",\"gif\":\"3302.mp4\",\"cat\":\"isometric\",\"desc\":\"A balance hold on the hands with the body upside down, usually against a wall to start. It trains the shoulders, triceps and core.\",\"hd\":1},{\"id\":\"0471\",\"n\":\"handstand push-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\"],\"st\":[\"Find a wall and face away from it, standing a few feet away.\",\"Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.\",\"Bend your elbows and lower your head towards the ground, keeping your body in a straight line.\",\"Push through your hands and extend your arms to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0471.webp\",\"gif\":\"0471.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You press your body upward while inverted against a wall. It builds the shoulders and triceps.\",\"fv\":\"2383\"},{\"id\":\"1764\",\"n\":\"hanging leg hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1764.webp\",\"gif\":\"1764.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging raise where you lift your legs and curl your hips up. Strengthens the lower abs and hip flexors.\",\"fv\":\"2551\"},{\"id\":\"0472\",\"n\":\"hanging leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your legs up in front of you, keeping them straight.\",\"Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0472.webp\",\"gif\":\"0472.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you raise your legs in front of you. It works the lower abs and hip flexors.\"},{\"id\":\"1761\",\"n\":\"hanging oblique knee raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat on the other side, twisting your torso in the opposite direction.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1761.webp\",\"gif\":\"1761.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging knee raise with a twist to each side. Targets the obliques and abs, and challenges your grip.\",\"fv\":\"3090\"},{\"id\":\"0473\",\"n\":\"hanging pike\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your legs up towards the bar, keeping them straight.\",\"Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.\",\"Hold the position for a moment, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0473.webp\",\"gif\":\"0473.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you fold your legs up toward the bar in a pike. It works the abs and hip flexors.\",\"fv\":\"2652\"},{\"id\":\"0474\",\"n\":\"hanging straight leg hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your legs up in front of you until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0474.webp\",\"gif\":\"0474.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you lift your straight legs and raise the hips. It trains the lower abs.\",\"fv\":\"3604\"},{\"id\":\"0475\",\"n\":\"hanging straight leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your legs up in front of you, keeping them straight.\",\"Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0475.webp\",\"gif\":\"0475.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you raise your straight legs in front of you. It builds the abs and hip flexors.\",\"fv\":\"2530\"},{\"id\":\"0476\",\"n\":\"hanging straight twisting leg hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your legs straight.\",\"Engage your core and lift your legs up towards your chest, keeping them straight.\",\"Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.\",\"Pause for a moment, then return to the starting position.\",\"Repeat the movement, but this time twist your hips to the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0476.webp\",\"gif\":\"0476.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you raise your straight legs while twisting your hips. It trains the abs and obliques.\",\"fv\":\"2702\"},{\"id\":\"3636\",\"n\":\"high knee against wall\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand facing a wall with your feet hip-width apart.\",\"Place your hands on the wall for support.\",\"Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.\",\"Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.\",\"Continue alternating legs in a running motion, bringing your knees up as high as possible.\",\"Maintain a fast pace and keep your upper body stable throughout the exercise.\",\"Repeat for the desired duration or number of repetitions.\"],\"img\":\"3636.webp\",\"gif\":\"3636.mp4\",\"cat\":\"cardio\",\"desc\":\"A high-knee run in place with the hands on a wall for support. It raises the heart rate and trains the hip flexors.\"},{\"id\":\"0484\",\"n\":\"hip raise (bent knee)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands by your sides, palms facing down.\",\"Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0484.webp\",\"gif\":\"0484.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back with bent knees, you raise your hips toward the ceiling. It works the lower abs and glutes.\",\"fv\":\"2653\"},{\"id\":\"1418\",\"n\":\"hug keens to chest\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Start by standing with your feet shoulder-width apart.\",\"Bend your knees and lower your body down into a squat position.\",\"As you squat down, bring your knees up towards your chest and hug them with your arms.\",\"Hold this position for a moment, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1418.webp\",\"gif\":\"1418.mp4\",\"cat\":\"stretching\",\"desc\":\"Stand and pull one knee up to your chest with both hands. It stretches the glutes and loosens the hip and lower back.\"},{\"id\":\"3234\",\"n\":\"hyght dumbbell fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand, palms facing each other.\",\"Extend your arms straight up over your chest, with a slight bend in your elbows.\",\"Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.\",\"Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3234.webp\",\"gif\":\"3234.mp4\",\"cat\":\"strength\",\"desc\":\"A flat-bench dumbbell fly done with a wide arc and a stretch across the chest. It isolates the pecs.\",\"nd\":[\"bench\"],\"fv\":\"3424\"},{\"id\":\"0489\",\"n\":\"hyperextension\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.\",\"Cross your arms over your chest or place your hands behind your head.\",\"Lower your upper body towards the ground while keeping your back straight.\",\"Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0489.webp\",\"gif\":\"0489.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Using a hyperextension bench, you lower and raise your torso. It strengthens the lower back, glutes and hamstrings.\",\"fv\":\"2531\"},{\"id\":\"0488\",\"n\":\"hyperextension (on bench)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.\",\"Cross your arms over your chest or place your hands behind your head.\",\"Slowly lower your upper body towards the ground while keeping your back straight.\",\"Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0488.webp\",\"gif\":\"0488.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face-down on a bench, you raise your torso and lower it. It builds the lower back, glutes and hamstrings.\"},{\"id\":\"3289\",\"n\":\"impossible dips\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.\",\"Bend your knees and cross your ankles.\",\"Lower your body by bending your elbows until your upper arms are parallel to the ground.\",\"Pause for a moment, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3289.webp\",\"gif\":\"3289.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced dip on parallel bars with the legs crossed or lifted. It trains the triceps and chest through a tough range.\"},{\"id\":\"1471\",\"n\":\"inchworm\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hamstrings\"],\"st\":[\"Start in a standing position with your feet hip-width apart.\",\"Bend forward at the waist and place your hands on the ground in front of you.\",\"Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.\",\"Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.\",\"Once your hands reach your feet, stand back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1471.webp\",\"gif\":\"1471.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You walk your hands out from standing into a plank and walk them back. It warms up the hamstrings, shoulders and core in one go.\"},{\"id\":\"3698\",\"n\":\"inchworm v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hamstrings\"],\"st\":[\"Start in a standing position with your feet hip-width apart.\",\"Bend forward at the waist and place your hands on the ground in front of you.\",\"Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.\",\"Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.\",\"Continue walking your hands forward, repeating the movement for the desired number of repetitions.\"],\"img\":\"3698.webp\",\"gif\":\"3698.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inchworm walk-out, walking the hands forward into a plank and the feet back in. It stretches the hamstrings and trains the core and shoulders.\"},{\"id\":\"0490\",\"n\":\"incline close-grip push-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.\",\"Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.\",\"Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0490.webp\",\"gif\":\"0490.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An incline push-up with a narrow hand position. It targets the triceps and chest.\"},{\"id\":\"0491\",\"n\":\"incline leg hip raise (leg straight)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.\",\"Place your hands on the sides of the bench for support.\",\"Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0491.webp\",\"gif\":\"0491.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on an incline with straight legs, you raise your hips by lifting the legs. It works the lower abs.\",\"fv\":\"2703\"},{\"id\":\"0492\",\"n\":\"incline push up depth jump\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.\",\"Step your feet back, keeping your body in a straight line from head to heels.\",\"Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Jump off the edge of the surface, landing softly with your knees slightly bent.\",\"Repeat the push-up and depth jump for the desired number of repetitions.\"],\"img\":\"0492.webp\",\"gif\":\"0492.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An incline push-up with a drop and explosive rebound. It builds chest power and quickness.\"},{\"id\":\"0493\",\"n\":\"incline push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.\",\"Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.\",\"Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0493.webp\",\"gif\":\"0493.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You perform a push-up with hands elevated. It makes the push-up easier and trains the chest, shoulders and triceps.\"},{\"id\":\"3785\",\"n\":\"incline push-up (on box)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.\",\"Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.\",\"Lower your chest towards the box by bending your elbows, keeping your body in a straight line.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3785.webp\",\"gif\":\"3785.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An incline push-up with the hands on a box. It trains the chest, shoulders and triceps with less load than a floor push-up.\"},{\"id\":\"0494\",\"n\":\"incline reverse grip push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.\",\"Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.\",\"Lower your chest towards the bench by bending your elbows, keeping them close to your sides.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0494.webp\",\"gif\":\"0494.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An incline push-up with your palms facing back. It trains the chest and shoulders in a different way.\"},{\"id\":\"3011\",\"n\":\"incline scapula push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Place your hands on the bench slightly wider than shoulder-width apart.\",\"Position your feet on the ground, hip-width apart.\",\"Lower your chest towards the bench, keeping your elbows tucked in.\",\"As you lower, retract your shoulder blades, squeezing your scapulae together.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3011.webp\",\"gif\":\"3011.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An incline push-up where you retract your shoulder blades. Strengthens the serratus anterior and upper back.\"},{\"id\":\"0495\",\"n\":\"incline twisting sit-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Set up an incline bench at a 45-degree angle.\",\"Lie down on the bench with your feet secured under the foot pads.\",\"Place your hands behind your head or across your chest.\",\"Engage your abs and lift your upper body off the bench, curling forward.\",\"As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat the movement, this time twisting your torso to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0495.webp\",\"gif\":\"0495.mp4\",\"cat\":\"calisthenics\",\"desc\":\"On an incline, you sit up and twist toward each side. It works the abs and obliques.\"},{\"id\":\"1564\",\"n\":\"intermediate hip flexor and quad stretch\",\"bp\":\"upper legs\",\"eq\":\"rope\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand upright with your feet shoulder-width apart.\",\"Hold onto a stable object for support.\",\"Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.\",\"Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.\",\"Hold the stretch for 20-30 seconds.\",\"Release the stretch and repeat on the left side.\"],\"img\":\"1564.webp\",\"gif\":\"1564.mp4\",\"cat\":\"stretching\",\"desc\":\"A deeper stretch for the hip flexors and quads, using a rope or strap to pull the foot toward you.\",\"fv\":\"4281\"},{\"id\":\"0496\",\"n\":\"inverse leg curl (bench support)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Lie face down on a bench with your hips at the edge and your legs extended straight behind you.\",\"Hold onto the bench for support.\",\"Keeping your upper body still, bend your knees and curl your legs towards your glutes.\",\"Pause for a moment at the top, then slowly extend your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0496.webp\",\"gif\":\"0496.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying or kneeling with your feet anchored on a bench, you bend the knees and bring your body upright. It strongly works the hamstrings.\"},{\"id\":\"2400\",\"n\":\"inverse leg curl (on pull-up cable machine)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Adjust the cable machine so that the ankle straps are at the lowest setting.\",\"Lie face down on the bench with your legs extended and the ankle straps attached to your feet.\",\"Hold onto the handles of the bench for stability.\",\"Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.\",\"Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2400.webp\",\"gif\":\"2400.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight inverse leg curl using a pull-up cable machine setup. Targets the hamstrings.\",\"nd\":[\"bench\"]},{\"id\":\"0499\",\"n\":\"inverted row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up a bar at waist height or use a suspension trainer.\",\"Stand facing the bar or suspension trainer, with your feet shoulder-width apart.\",\"Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Lean back, keeping your body straight and your heels on the ground.\",\"Pull your chest towards the bar or handles, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower yourself back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0499.webp\",\"gif\":\"0499.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying beneath a bar with a straight body, you pull your chest to the bar. It builds the upper back and biceps.\",\"nd\":[\"pull-up bar\"],\"fv\":\"2299\"},{\"id\":\"2300\",\"n\":\"inverted row bent knees\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up a bar at waist height and lie underneath it.\",\"Grab the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Position your body so that your heels are on the ground and your body is straight.\",\"Pull your chest up towards the bar by squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2300.webp\",\"gif\":\"2300.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row beneath a bar with knees bent to make it easier. Builds the upper back and biceps.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"2298\",\"n\":\"inverted row on bench\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up a bench at a height that allows your body to hang freely underneath it.\",\"Lie face up on the ground with your head towards the bench.\",\"Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.\",\"Position your body so that your heels are on the ground and your arms are fully extended.\",\"Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.\",\"Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2298.webp\",\"gif\":\"2298.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row hanging beneath a bench or bar, pulling your chest up. Trains the upper back and biceps.\"},{\"id\":\"0497\",\"n\":\"inverted row v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up a bar at waist height on a Smith machine or use a suspension trainer.\",\"Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.\",\"Walk your feet forward, leaning back until your body is at a slight angle.\",\"Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0497.webp\",\"gif\":\"0497.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging beneath a bar, you pull your chest up with a straight body. This version changes the grip or angle. It builds the upper back and biceps.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"0498\",\"n\":\"inverted row with straps\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up a suspension trainer or straps at chest height.\",\"Stand facing the anchor point and grab the handles with an overhand grip.\",\"Walk your feet forward, leaning back until your body is at an angle.\",\"Keep your body straight and engage your core.\",\"Pull your chest towards the handles, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower yourself back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0498.webp\",\"gif\":\"0498.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from straps with a straight body, you row your chest up. It trains the upper back and biceps.\",\"fv\":\"3897\"},{\"id\":\"1419\",\"n\":\"iron cross stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Lie flat on your back with your arms extended out to the sides.\",\"Raise your legs up towards the ceiling, keeping them straight.\",\"Slowly lower your legs to one side, aiming to touch the floor with your feet.\",\"Hold the stretch for a few seconds, then return your legs to the starting position.\",\"Repeat the stretch on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1419.webp\",\"gif\":\"1419.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie on your back with your arms out and cross one leg over your body toward the opposite hand. It stretches the glutes and lower back.\",\"fv\":\"3285\"},{\"id\":\"1297\",\"n\":\"isometric chest squeeze\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.\",\"Squeeze your chest muscles together as hard as you can, while keeping your arms straight.\",\"Hold this position for a few seconds, focusing on contracting your chest muscles.\",\"Release the squeeze and relax your chest muscles.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1297.webp\",\"gif\":\"1297.mp4\",\"cat\":\"isometric\",\"desc\":\"Press your palms or arms together in front of your chest and hold the squeeze. A simple way to feel and train the chest with no equipment.\",\"hd\":1},{\"id\":\"0500\",\"n\":\"isometric wipers\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start by lying flat on your back on a mat or bench.\",\"Extend your arms straight out to the sides, perpendicular to your body.\",\"Engage your core and lift both legs off the ground, keeping them together and straight.\",\"Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.\",\"Pause for a moment, then use your core to lift your legs back to the starting position.\",\"Repeat the movement, this time lowering your legs to the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0500.webp\",\"gif\":\"0500.mp4\",\"cat\":\"isometric\",\"desc\":\"Lying on your back, you hold your arms up and move them like windshield wipers. It works the chest, shoulders and core.\"},{\"id\":\"0501\",\"n\":\"jack burpee\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a standing position with your feet shoulder-width apart.\",\"Lower your body into a squat position, placing your hands on the ground in front of you.\",\"Kick your feet back, landing in a push-up position.\",\"Perform a push-up, lowering your chest to the ground and then pushing back up.\",\"Jump your feet forward, landing in a squat position.\",\"Jump up explosively, reaching your arms overhead.\",\"Land softly and immediately lower back into the squat position to begin the next repetition.\"],\"img\":\"0501.webp\",\"gif\":\"0501.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee with a jumping jack at the end. It raises your heart rate and trains the whole body.\"},{\"id\":\"3224\",\"n\":\"jack jump (male)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet together and your arms by your sides.\",\"Jump up, spreading your feet apart and raising your arms above your head.\",\"As you land, quickly jump back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3224.webp\",\"gif\":\"3224.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping jack, hopping the feet apart while the arms go overhead and back again. A classic warm-up and cardio move.\"},{\"id\":\"0507\",\"n\":\"jackknife sit-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs extended and your arms overhead.\",\"Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.\",\"Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0507.webp\",\"gif\":\"0507.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You lie flat and fold your body, bringing hands and feet together. It strongly trains the abs.\",\"fv\":\"3884\"},{\"id\":\"0508\",\"n\":\"janda sit-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0508.webp\",\"gif\":\"0508.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with the glutes and quads squeezed to take the hip flexors out of play. It focuses on the abs.\",\"fv\":\"3093\"},{\"id\":\"2612\",\"n\":\"jump rope\",\"bp\":\"cardio\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Hold the handles of the jump rope with your hands, palms facing inward.\",\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Swing the rope over your head and jump over it as it comes towards your feet.\",\"Land softly on the balls of your feet and repeat the jump as the rope comes around again.\",\"Continue jumping for the desired duration or number of repetitions.\"],\"img\":\"2612.webp\",\"gif\":\"2612.mp4\",\"cat\":\"cardio\",\"desc\":\"Skipping over a rope at a steady pace. Classic cardio that builds endurance and coordination.\",\"fv\":\"0511\"},{\"id\":\"0514\",\"n\":\"jump squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"Jump explosively off the ground, extending your hips, knees, and ankles.\",\"While in mid-air, quickly bring your arms forward for balance.\",\"Land softly on the balls of your feet and immediately go into the next repetition.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0514.webp\",\"gif\":\"0514.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bodyweight squat finished with an explosive jump. It builds leg power and conditioning.\",\"fv\":\"2374\"},{\"id\":\"0513\",\"n\":\"jump squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"Jump explosively, extending your hips and knees fully.\",\"Land softly on the balls of your feet and immediately lower your body back into a squat position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0513.webp\",\"gif\":\"0513.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bodyweight squat finished with an explosive jump, second variation. It builds leg power and conditioning.\"},{\"id\":\"0517\",\"n\":\"kettlebell advanced windmill\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.\",\"Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.\",\"Rotate your left foot slightly to the right, and shift your weight onto your left leg.\",\"Bend your left knee and hinge at the hip, lowering your torso towards the left side.\",\"Keep your right arm extended overhead and your eyes on the kettlebell.\",\"As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.\",\"Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.\",\"Pause for a moment, then engage your core and push through your left heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0517.webp\",\"gif\":\"0517.mp4\",\"cat\":\"strength\",\"desc\":\"An advanced kettlebell windmill where you hold the bell overhead and hinge sideways. It trains the obliques, shoulders and hips.\"},{\"id\":\"0518\",\"n\":\"kettlebell alternating hang clean\",\"bp\":\"lower arms\",\"eq\":\"kettlebell\",\"tg\":\"forearms\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"traps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\",\"Allow the kettlebells to hang in front of your body with your arms fully extended.\",\"In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.\",\"As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.\",\"Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0518.webp\",\"gif\":\"0518.mp4\",\"cat\":\"olympic\",\"desc\":\"You alternately clean a kettlebell from a hang to the rack position. It works the hips, back, shoulders and grip.\"},{\"id\":\"0520\",\"n\":\"kettlebell alternating press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\",\"Press one kettlebell overhead, fully extending your arm.\",\"Lower the kettlebell back to shoulder height.\",\"Repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0520.webp\",\"gif\":\"0520.mp4\",\"cat\":\"strength\",\"desc\":\"You press kettlebells overhead one after the other. It builds the shoulders and triceps.\"},{\"id\":\"0519\",\"n\":\"kettlebell alternating press on floor\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Start by lying on your back on the floor with your knees bent and feet flat on the ground.\",\"Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.\",\"Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.\",\"Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.\",\"Continue alternating the press motion with each kettlebell for the desired number of repetitions.\"],\"img\":\"0519.webp\",\"gif\":\"0519.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on the floor, you press kettlebells up one at a time. It works the chest, shoulders and triceps.\",\"fv\":\"2532\"},{\"id\":\"0521\",\"n\":\"kettlebell alternating renegade row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"upper back\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.\",\"Engage your core and keep your body in a straight line from head to heels.\",\"Pull one kettlebell up towards your chest, keeping your elbow close to your body.\",\"Lower the kettlebell back down to the starting position and repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0521.webp\",\"gif\":\"0521.mp4\",\"cat\":\"strength\",\"desc\":\"In a push-up position holding kettlebells, you row one at a time. It builds the back and core.\",\"fv\":\"2533\"},{\"id\":\"0522\",\"n\":\"kettlebell alternating row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.\",\"Bend forward at the hips, keeping your back straight and your core engaged.\",\"Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\",\"Lower the kettlebell back down to the starting position and repeat with the other arm.\",\"Continue alternating arms for the desired number of repetitions.\"],\"img\":\"0522.webp\",\"gif\":\"0522.mp4\",\"cat\":\"strength\",\"desc\":\"You row a kettlebell with one arm after the other. It builds the back, biceps and grip.\"},{\"id\":\"0523\",\"n\":\"kettlebell arnold press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.\",\"Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.\",\"Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0523.webp\",\"gif\":\"0523.mp4\",\"cat\":\"strength\",\"desc\":\"You press kettlebells overhead while rotating your palms. It trains all three parts of the shoulder.\"},{\"id\":\"0524\",\"n\":\"kettlebell bent press\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.\",\"Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.\",\"Rotate your torso to the left, shifting your weight onto your left foot.\",\"Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.\",\"As you lower, keep your eyes on the kettlebell and your chest lifted.\",\"Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.\",\"As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0524.webp\",\"gif\":\"0524.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell press that takes you from standing to leaning back while the bell stays overhead. It trains the shoulders, trunk and hips.\",\"fv\":\"2654\"},{\"id\":\"0525\",\"n\":\"kettlebell bottoms up clean from the hang position\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\",\"Allow the kettlebell to hang down between your legs, with your arm fully extended.\",\"In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.\",\"As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.\",\"Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.\",\"Lower the kettlebell back down to the starting position by reversing the movement.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0525.webp\",\"gif\":\"0525.mp4\",\"cat\":\"olympic\",\"desc\":\"You clean a kettlebell upside down from a hang to the rack. It builds grip, shoulders and forearm control.\"},{\"id\":\"0526\",\"n\":\"kettlebell double alternating hang clean\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\",\"Allow the kettlebells to hang straight down in front of your body.\",\"In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.\",\"As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.\",\"Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.\",\"Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0526.webp\",\"gif\":\"0526.mp4\",\"cat\":\"olympic\",\"desc\":\"You clean two kettlebells alternately from a hang to the rack. It works the hips, back, shoulders and grip.\"},{\"id\":\"0527\",\"n\":\"kettlebell double jerk\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\",\"Bend your knees slightly and engage your core.\",\"Press the kettlebells overhead, fully extending your arms.\",\"Bend your knees and quickly drop into a partial squat.\",\"Explosively extend your hips and knees, driving the kettlebells overhead.\",\"Lock out your arms and catch the kettlebells overhead with your knees slightly bent.\",\"Stand up straight and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0527.webp\",\"gif\":\"0527.mp4\",\"cat\":\"olympic\",\"desc\":\"With two kettlebells you drive from the rack to overhead using legs and arms. It builds the shoulders and legs.\"},{\"id\":\"0528\",\"n\":\"kettlebell double push press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\",\"Bend your knees slightly and engage your core.\",\"Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.\",\"As the kettlebells reach the top, press them fully overhead, locking out your arms.\",\"Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0528.webp\",\"gif\":\"0528.mp4\",\"cat\":\"olympic\",\"desc\":\"With two kettlebells, you dip your knees and drive the bells overhead. It builds the shoulders and legs.\",\"fv\":\"2534\"},{\"id\":\"0529\",\"n\":\"kettlebell double snatch\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"forearms\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm's length in front of your thighs.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.\",\"In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.\",\"As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.\",\"Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0529.webp\",\"gif\":\"0529.mp4\",\"cat\":\"olympic\",\"desc\":\"You swing two kettlebells from the floor to overhead in one motion. It builds the hips, shoulders and grip.\"},{\"id\":\"0530\",\"n\":\"kettlebell double windmill\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hamstrings\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.\",\"Extend your right arm overhead, keeping your eyes on the kettlebell.\",\"Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.\",\"Bend at the waist to the left, keeping your right arm extended overhead.\",\"Lower the kettlebell towards the ground, reaching towards your left foot.\",\"Pause for a moment, then engage your core and push through your right foot to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0530.webp\",\"gif\":\"0530.mp4\",\"cat\":\"strength\",\"desc\":\"Holding two kettlebells, you hinge sideways with one overhead. It trains the obliques, shoulders and hips.\",\"fv\":\"4520\"},{\"id\":\"0531\",\"n\":\"kettlebell extended range one arm press on floor\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start by lying on your back on the floor with your knees bent and feet flat on the ground.\",\"Hold a kettlebell in one hand, with your palm facing towards your feet.\",\"Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.\",\"Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0531.webp\",\"gif\":\"0531.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on the floor, you press a kettlebell straight up with one arm. A simple way to work the chest and shoulder one side at a time.\"},{\"id\":\"0532\",\"n\":\"kettlebell figure 8\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.\",\"As the kettlebell comes forward, pass it to the other hand between your legs.\",\"Continue passing the kettlebell between your legs in a figure 8 motion.\",\"Maintain a steady pace and engage your core throughout the exercise.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0532.webp\",\"gif\":\"0532.mp4\",\"cat\":\"strength\",\"desc\":\"You pass a kettlebell in a figure 8 pattern around and between your legs. It trains the core, hips and grip while keeping you moving.\",\"fv\":\"2535\"},{\"id\":\"0533\",\"n\":\"kettlebell front squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Hold the kettlebell with both hands in front of your chest, close to your body.\",\"Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Drive through your heels to stand back up, squeezing your glutes at the top.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0533.webp\",\"gif\":\"0533.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a kettlebell held at chest height. The front load builds the quads and glutes and keeps your torso upright.\",\"fv\":\"2639\"},{\"id\":\"0534\",\"n\":\"kettlebell goblet squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.\",\"Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0534.webp\",\"gif\":\"0534.mp4\",\"cat\":\"strength\",\"desc\":\"Hold a kettlebell close to your chest and squat down between your hips. A friendly squat variation for legs, glutes and core.\",\"fv\":\"2356\"},{\"id\":\"0535\",\"n\":\"kettlebell hang clean\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Lower the kettlebell towards the ground, allowing it to swing between your legs.\",\"Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.\",\"As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.\",\"Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions.\"],\"img\":\"0535.webp\",\"gif\":\"0535.mp4\",\"cat\":\"olympic\",\"desc\":\"You swing a kettlebell from a hang position up to the rack at your shoulder in one smooth pull. Trains the hips, back and shoulders for power.\"},{\"id\":\"0536\",\"n\":\"kettlebell lunge pass through\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.\",\"Take a step forward with your right foot, lowering your body into a lunge position.\",\"As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.\",\"Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.\",\"Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.\",\"Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions.\"],\"img\":\"0536.webp\",\"gif\":\"0536.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge where you pass the kettlebell around your front leg at the bottom. Works the legs and glutes while challenging your balance and core.\",\"fv\":\"2536\"},{\"id\":\"0537\",\"n\":\"kettlebell one arm clean and jerk\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.\",\"Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.\",\"Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.\",\"As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.\",\"Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0537.webp\",\"gif\":\"0537.mp4\",\"cat\":\"olympic\",\"desc\":\"You clean a kettlebell to your shoulder, then dip and drive it overhead with one arm. A full body power move for legs, shoulders and core.\"},{\"id\":\"1298\",\"n\":\"kettlebell one arm floor press\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie flat on your back on the floor with your knees bent and feet flat on the ground.\",\"Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.\",\"Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.\",\"Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1298.webp\",\"gif\":\"1298.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on the floor, press a kettlebell straight up with one arm. The floor limits the range, which is gentle on the shoulder while building the chest and triceps.\"},{\"id\":\"0538\",\"n\":\"kettlebell one arm jerk\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.\",\"Bend your knees slightly and engage your core.\",\"Press the kettlebell overhead in a straight line, fully extending your arm.\",\"As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.\",\"As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.\",\"Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.\",\"Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.\",\"Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions.\"],\"img\":\"0538.webp\",\"gif\":\"0538.mp4\",\"cat\":\"olympic\",\"desc\":\"Dip and drive with your legs to throw a kettlebell from the shoulder to overhead with one arm. Builds explosive shoulder and leg power.\"},{\"id\":\"0539\",\"n\":\"kettlebell one arm military press to the side\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.\",\"Engage your core and keep your back straight.\",\"Press the kettlebell overhead, extending your arm fully.\",\"Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0539.webp\",\"gif\":\"0539.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one arm kettlebell press where the path drifts out to the side. Works the shoulder and upper back while your core resists leaning.\"},{\"id\":\"0540\",\"n\":\"kettlebell one arm push press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.\",\"Bend your knees slightly and engage your core.\",\"Press the kettlebell overhead by extending your arm and fully extending your legs.\",\"Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0540.webp\",\"gif\":\"0540.mp4\",\"cat\":\"strength\",\"desc\":\"Use a small leg dip and drive to push one kettlebell overhead. It lets you move more weight than a strict press and trains shoulders, triceps and legs.\"},{\"id\":\"0541\",\"n\":\"kettlebell one arm row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.\",\"Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.\"],\"img\":\"0541.webp\",\"gif\":\"0541.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge forward and row a kettlebell to your hip with one arm. Targets the lats and upper back while your core keeps you steady.\"},{\"id\":\"0542\",\"n\":\"kettlebell one arm snatch\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"forearms\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.\",\"Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.\",\"Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.\",\"As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.\",\"Lower the kettlebell back down between your legs and repeat for the desired number of repetitions.\"],\"img\":\"0542.webp\",\"gif\":\"0542.mp4\",\"cat\":\"olympic\",\"desc\":\"You swing a kettlebell from between your legs to overhead in one fluid motion with a single arm. A power exercise for hips, shoulders and back.\"},{\"id\":\"0543\",\"n\":\"kettlebell pirate supper legs\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in one hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Raise the kettlebell up to shoulder height, keeping your elbow close to your body.\",\"Extend your arm fully overhead, straightening your elbow.\",\"Lower the kettlebell back down to shoulder height, then return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0543.webp\",\"gif\":\"0543.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell hinge and carry style move that works the hips and lower back while you keep a flat back and steady core.\"},{\"id\":\"0544\",\"n\":\"kettlebell pistol squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.\",\"Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.\",\"Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.\",\"Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0544.webp\",\"gif\":\"0544.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg squat holding a kettlebell at your chest as a counterweight. Builds leg strength, balance and mobility.\"},{\"id\":\"0545\",\"n\":\"kettlebell plyo push-up\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank position with your hands on the kettlebells, shoulder-width apart.\",\"Lower your chest towards the ground, keeping your elbows close to your body.\",\"Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.\",\"Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0545.webp\",\"gif\":\"0545.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive push-up with your hands on kettlebells. You push hard enough to lift off, which trains chest and arm power.\"},{\"id\":\"0546\",\"n\":\"kettlebell seated press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a kettlebell in each hand at shoulder height, palms facing forward.\",\"Press the kettlebells overhead, fully extending your arms.\",\"Lower the kettlebells back to shoulder height.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0546.webp\",\"gif\":\"0546.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a bench, you press a kettlebell in each hand overhead. Takes the legs out so your shoulders and triceps do the work.\"},{\"id\":\"1438\",\"n\":\"kettlebell seated two arm military press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a bench with your back straight and feet flat on the ground.\",\"Hold a kettlebell in each hand at shoulder level with your palms facing forward.\",\"Press the kettlebells overhead by extending your arms fully.\",\"Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1438.webp\",\"gif\":\"1438.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with a kettlebell in each hand. It trains the shoulders and triceps while the seat keeps your legs out of the lift.\"},{\"id\":\"0547\",\"n\":\"kettlebell seesaw press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\",\"Press one kettlebell overhead while keeping the other kettlebell at shoulder height.\",\"Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.\",\"Continue alternating the pressing motion, creating a seesaw-like movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0547.webp\",\"gif\":\"0547.mp4\",\"cat\":\"strength\",\"desc\":\"You press one kettlebell up while the other lowers, like a seesaw. Works the shoulders and triceps with a steady rhythm.\"},{\"id\":\"0548\",\"n\":\"kettlebell sumo high pull\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"hamstrings\"],\"st\":[\"Stand with your feet wider than shoulder-width apart, toes pointing outwards.\",\"Hold a kettlebell with both hands in front of your body, arms extended downwards.\",\"Bend your knees and lower your hips into a squat position, keeping your back straight.\",\"Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.\",\"As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.\",\"Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0548.webp\",\"gif\":\"0548.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance pull where you drive through your legs and row a kettlebell up to chest height. Hits the traps, shoulders and hips.\"},{\"id\":\"0549\",\"n\":\"kettlebell swing\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointed slightly outward.\",\"Hold the kettlebell with both hands in front of your body, arms extended.\",\"Bend your knees slightly and hinge at the hips, pushing your butt back.\",\"Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.\",\"Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.\",\"Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions.\"],\"img\":\"0549.webp\",\"gif\":\"0549.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge move where you swing a kettlebell to chest height using your hips. Great for glutes, hamstrings and posterior chain power.\",\"fv\":\"2537\"},{\"id\":\"0550\",\"n\":\"kettlebell thruster\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.\",\"Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.\",\"As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.\",\"Lock out your arms at the top of the movement, fully extending your elbows.\",\"Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0550.webp\",\"gif\":\"0550.mp4\",\"cat\":\"strength\",\"desc\":\"You squat with a kettlebell at your chest, then stand and press it overhead in one motion. A full body move for legs and shoulders.\",\"fv\":\"4517\"},{\"id\":\"0551\",\"n\":\"kettlebell turkish get up (squat style)\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.\",\"Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.\",\"Pressing through your right foot, lift your hips off the ground, coming into a bridge position.\",\"Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.\",\"Rotate your torso to the left, bringing your left hand to the ground for support.\",\"Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.\",\"From the kneeling position, stand up, keeping the kettlebell extended overhead.\",\"Reverse the movement to return to the starting position.\",\"Repeat the exercise on the other side, starting with the kettlebell in your left hand.\"],\"img\":\"0551.webp\",\"gif\":\"0551.mp4\",\"cat\":\"strength\",\"desc\":\"A Turkish get up where you come up through a squat style transition while keeping the kettlebell overhead. Trains full body control, stability and strength.\"},{\"id\":\"0552\",\"n\":\"kettlebell two arm clean\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.\",\"Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.\",\"Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.\",\"As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.\",\"Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0552.webp\",\"gif\":\"0552.mp4\",\"cat\":\"olympic\",\"desc\":\"You pull a kettlebell from between your thighs up to the rack position with both hands. Trains hip power, back and shoulders.\"},{\"id\":\"0553\",\"n\":\"kettlebell two arm military press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.\",\"Engage your core and press the kettlebells overhead, fully extending your arms.\",\"Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0553.webp\",\"gif\":\"0553.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you press a kettlebell in each hand overhead from shoulder height. Builds shoulder and triceps strength with a braced core.\"},{\"id\":\"1345\",\"n\":\"kettlebell two arm row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.\",\"Bend forward at the hips, keeping your back straight and your core engaged.\",\"Pull the kettlebells up towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1345.webp\",\"gif\":\"1345.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge forward and row a kettlebell in each hand to your sides. It works the upper back and lats and trains grip strength.\"},{\"id\":\"0554\",\"n\":\"kettlebell windmill\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.\",\"Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.\",\"Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.\",\"Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.\",\"Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0554.webp\",\"gif\":\"0554.mp4\",\"cat\":\"strength\",\"desc\":\"With a kettlebell held overhead, you push your hips out and reach down toward your foot. Builds shoulder stability, flexibility and core strength.\",\"fv\":\"4519\"},{\"id\":\"0555\",\"n\":\"kick out sit\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\"],\"st\":[\"Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Lean back slightly and place your hands on the edge of the bench or chair for support.\",\"Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.\",\"Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0555.webp\",\"gif\":\"0555.mp4\",\"cat\":\"strength\",\"desc\":\"A seated core move where you lean back and kick your legs out and in. Works the abs and hip flexors without any equipment.\"},{\"id\":\"0558\",\"n\":\"kipping muscle up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Engage your core and use a swinging motion to generate momentum.\",\"As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.\",\"Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.\",\"Lower yourself back down to the starting position by bending your arms and controlling the descent.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0558.webp\",\"gif\":\"0558.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up bar move where you use a swing to get above the bar and then press out. Trains lats, arms and chest, and needs good control.\"},{\"id\":\"3640\",\"n\":\"knee touch crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.\",\"Return to the starting position and repeat, this time reaching your left hand towards your right knee.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3640.webp\",\"gif\":\"3640.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where the opposite hand reaches toward the knee on each rep. It trains the abs and obliques.\",\"fv\":\"4269\"},{\"id\":\"1420\",\"n\":\"kneeling jump squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.\",\"Hold a barbell across your upper back, resting it on your shoulders.\",\"Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.\",\"As you jump, push through your toes and fully extend your ankles, knees, and hips.\",\"Land softly back on the ground, bending your knees to absorb the impact.\",\"Immediately go into the next repetition, repeating the jump squat motion.\"],\"img\":\"1420.webp\",\"gif\":\"1420.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Start on your knees and explosively swing your arms to jump up onto your feet. It builds power in the glutes and hips.\"},{\"id\":\"1346\",\"n\":\"kneeling lat stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Kneel on the ground with your knees hip-width apart and your toes pointing back.\",\"Extend your arms overhead and interlace your fingers.\",\"Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.\",\"Hold the stretch for 20-30 seconds, then return to the starting position.\",\"Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1346.webp\",\"gif\":\"1346.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneel and reach your arms overhead, then lean to one side. It stretches the lat and the side of your torso.\",\"fv\":\"4298\"},{\"id\":\"3239\",\"n\":\"kneeling plank tap shoulder (male)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Start in a kneeling position with your hands on the ground, shoulder-width apart.\",\"Extend your legs behind you, resting on your toes, and lift your body into a plank position.\",\"Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.\",\"Return the hand to the ground and repeat with the other hand.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3239.webp\",\"gif\":\"3239.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling plank where you tap the opposite shoulder with one hand at a time. It trains the abs and shoulder stability.\"},{\"id\":\"3211\",\"n\":\"kneeling push-up (male)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.\",\"Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.\",\"Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3211.webp\",\"gif\":\"3211.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A beginner-friendly push-up with the knees on the floor. It builds chest, shoulder and triceps strength with less load than a standard push-up.\"},{\"id\":\"3288\",\"n\":\"korean dips\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Position yourself between two parallel bars with your arms extended and supporting your body weight.\",\"Lower your body by bending your elbows until your upper arms are parallel to the ground.\",\"Pause for a moment, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3288.webp\",\"gif\":\"3288.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep dip variation performed on parallel bars with a different hand and body position. It trains the chest and triceps.\"},{\"id\":\"3418\",\"n\":\"l-pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang with your arms fully extended and your body straight.\",\"Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3418.webp\",\"gif\":\"3418.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with the legs held out straight in an L shape. It trains the lats, biceps and core.\"},{\"id\":\"3419\",\"n\":\"l-sit on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the floor with your legs extended in front of you.\",\"Place your hands on the floor beside your hips, fingers pointing forward.\",\"Engage your core and lift your legs off the ground, keeping them straight.\",\"Try to bring your legs parallel to the floor, forming an 'L' shape with your body.\",\"Hold this position for as long as you can.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3419.webp\",\"gif\":\"3419.mp4\",\"cat\":\"isometric\",\"desc\":\"A seated hold on the floor, hands beside the hips, with the legs lifted straight out. It trains the abs, hip flexors and triceps.\",\"hd\":1},{\"id\":\"0562\",\"n\":\"landmine 180\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"quadriceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.\",\"Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.\",\"As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.\",\"Continue this twisting motion, alternating sides, for the desired number of repetitions.\"],\"img\":\"0562.webp\",\"gif\":\"0562.mp4\",\"cat\":\"strength\",\"desc\":\"You hold a landmine barbell at chest height and rotate it in an arc from side to side. Works the obliques and core with strong hip drive.\",\"fv\":\"3605\"},{\"id\":\"3237\",\"n\":\"landmine lateral raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold the barbell with an overhand grip, resting it on the front of your shoulders.\",\"Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3237.webp\",\"gif\":\"3237.mp4\",\"cat\":\"strength\",\"desc\":\"A raise done with a barbell anchored in a landmine setup, lifting out and up to shoulder height. It works the shoulders with a smooth arc.\"},{\"id\":\"3300\",\"n\":\"lean planche\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"triceps\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and your body straight.\",\"Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.\",\"Keep your elbows slightly bent and your body straight as you lean forward.\",\"Hold this position for a few seconds, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3300.webp\",\"gif\":\"3300.mp4\",\"cat\":\"isometric\",\"desc\":\"A leaning plank where the shoulders move forward past the hands. It trains the shoulders, wrists and core on the way to the planche.\",\"hd\":1},{\"id\":\"2271\",\"n\":\"left hook. boxing\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Keep your left hand up to protect your face and your right hand by your chin.\",\"Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.\",\"Twist your torso and engage your core muscles to generate power in the punch.\",\"Snap your arm back to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"2271.webp\",\"gif\":\"2271.mp4\",\"cat\":\"combat\",\"desc\":\"A boxing left hook thrown with a hip and torso rotation. Builds rotational power and conditioning.\"},{\"id\":\"0570\",\"n\":\"leg pull in flat bench\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Sit on a flat bench with your legs extended straight out in front of you.\",\"Place your hands on the bench beside your hips for support.\",\"Engage your abs and lift your legs off the ground, bringing your knees towards your chest.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0570.webp\",\"gif\":\"0570.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a flat bench, you pull your knees in toward your chest and extend them again. Works the lower abs and hip flexors.\"},{\"id\":\"1576\",\"n\":\"leg up hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie flat on your back with your legs extended.\",\"Bend one knee and bring it towards your chest, holding onto your thigh or shin.\",\"Straighten your leg as much as possible while keeping it elevated.\",\"Hold the stretch for 20-30 seconds.\",\"Repeat with the other leg.\"],\"img\":\"1576.webp\",\"gif\":\"1576.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back with one leg raised, you draw it toward you to stretch the hamstring.\"},{\"id\":\"2287\",\"n\":\"lever alternate leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the seat and foot platform of the leverage machine to your desired position.\",\"Sit on the machine with your back against the backrest and your feet on the foot platform.\",\"Place your hands on the handles or sides of the machine for stability.\",\"Push one foot against the foot platform, extending your leg until it is almost fully straight.\",\"Pause for a moment, then slowly bend your leg and return to the starting position.\",\"Repeat with the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"2287.webp\",\"gif\":\"2287.mp4\",\"cat\":\"strength\",\"desc\":\"A machine leg press done one leg at a time, alternating. Builds the quads and glutes.\"},{\"id\":\"0571\",\"n\":\"lever alternating narrow grip seated row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and footplate position to ensure proper alignment.\",\"Sit on the machine with your back straight and feet flat on the footplate.\",\"Grasp the handles with a narrow grip, palms facing each other.\",\"Keep your chest up and shoulders back throughout the exercise.\",\"Pull one handle towards your torso while keeping the other handle stationary.\",\"Squeeze your shoulder blades together at the end of the movement.\",\"Slowly return the handle to the starting position and repeat with the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0571.webp\",\"gif\":\"0571.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you pull the handles one arm at a time toward your torso with a narrow grip. Targets the lats and mid back.\"},{\"id\":\"0572\",\"n\":\"lever assisted chin-up\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the leverage machine to your desired resistance level.\",\"Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang with your arms fully extended, keeping your body straight.\",\"Engage your back muscles and pull your body up towards the handles, leading with your chest.\",\"Continue pulling until your chin is above the handles.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0572.webp\",\"gif\":\"0572.mp4\",\"cat\":\"strength\",\"desc\":\"A machine that helps lift your body weight so you can train chin-ups at a lower load. Builds the lats and biceps.\"},{\"id\":\"0573\",\"n\":\"lever back extension\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Adjust the machine to fit your body size and range of motion.\",\"Sit on the machine with your back against the pad and your feet secured.\",\"Place your hands on the handles or grip bars.\",\"Engage your core and slowly lean forward, allowing your back to round slightly.\",\"Pause for a moment at the bottom position, feeling a stretch in your lower back.\",\"Using your back muscles, slowly raise your torso back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0573.webp\",\"gif\":\"0573.mp4\",\"cat\":\"strength\",\"desc\":\"On a machine, you extend your torso against a pad to work the lower back. Also brings in the glutes and hamstrings.\",\"fv\":\"3607\"},{\"id\":\"0574\",\"n\":\"lever bent over row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Bend forward at the hips, keeping your back straight and chest up.\",\"Pull the barbell towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0574.webp\",\"gif\":\"0574.mp4\",\"cat\":\"strength\",\"desc\":\"A lever machine version of the bent over row. You pull the handles toward your torso to train the back and lats.\",\"fv\":\"3097\"},{\"id\":\"3200\",\"n\":\"lever bent-over row with v-bar\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and position yourself facing the machine.\",\"Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.\",\"Pull the v-bar towards your abdomen, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3200.webp\",\"gif\":\"3200.mp4\",\"cat\":\"strength\",\"desc\":\"A machine row done in a bent-over stance with a v-bar handle. It builds the upper back and lats by pulling the handle toward your abdomen.\"},{\"id\":\"0575\",\"n\":\"lever bicep curl\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the pad.\",\"Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.\",\"Exhale and curl the handles upward, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the handles back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0575.webp\",\"gif\":\"0575.mp4\",\"cat\":\"strength\",\"desc\":\"Seated at a lever machine, you curl the handles up with an underhand grip. Isolates the biceps with a smooth path.\",\"fv\":\"3098\"},{\"id\":\"2289\",\"n\":\"lever calf press\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.\",\"Place your toes on the lever pad, with your heels hanging off the edge.\",\"Grasp the handles or side supports for stability.\",\"Push the lever pad down by extending your ankles, contracting your calf muscles.\",\"Pause for a moment at the bottom of the movement.\",\"Slowly return to the starting position by allowing your heels to rise back up.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2289.webp\",\"gif\":\"2289.mp4\",\"cat\":\"strength\",\"desc\":\"A machine calf press pushing the pad with your toes. Builds the calf muscles.\"},{\"id\":\"0577\",\"n\":\"lever chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back flat against the pad.\",\"Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.\",\"Push the handles forward until your arms are fully extended, exhaling during the movement.\",\"Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0577.webp\",\"gif\":\"0577.mp4\",\"cat\":\"strength\",\"desc\":\"A machine press where you push the handles forward from your chest. Works the chest, front shoulders and triceps.\",\"fv\":\"2457\"},{\"id\":\"0576\",\"n\":\"lever chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back flat against the pad.\",\"Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.\",\"Push the handles forward until your arms are fully extended, exhaling during the movement.\",\"Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0576.webp\",\"gif\":\"0576.mp4\",\"cat\":\"strength\",\"desc\":\"A machine press where you push the handles forward from your chest. Works the chest, front shoulders and triceps.\",\"fv\":\"2456\"},{\"id\":\"0578\",\"n\":\"lever deadlift\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Adjust the seat height and foot platform to your desired position.\",\"Sit on the machine with your back against the pad and your feet flat on the foot platform.\",\"Grasp the handles or the sides of the seat for stability.\",\"Engage your glutes and hamstrings, and push through your heels to lift the weight up.\",\"Keep your back straight and avoid rounding your shoulders.\",\"Extend your hips fully at the top of the movement, squeezing your glutes.\",\"Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0578.webp\",\"gif\":\"0578.mp4\",\"cat\":\"strength\",\"desc\":\"A machine deadlift that lets you hinge and stand up against a set load. Works the glutes, hamstrings and lower back.\",\"fv\":\"3099\"},{\"id\":\"1300\",\"n\":\"lever decline chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and backrest of the leverage machine to a comfortable position.\",\"Sit on the machine with your back against the backrest and your feet flat on the floor.\",\"Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.\",\"Push the handles forward and away from your body until your arms are fully extended.\",\"Slowly lower the handles back towards your chest, keeping your elbows slightly bent.\",\"Pause for a moment at the bottom, then push the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1300.webp\",\"gif\":\"1300.mp4\",\"cat\":\"strength\",\"desc\":\"A machine press that travels along a decline path. It focuses on the lower chest and triceps in a fixed, stable motion.\",\"fv\":\"2454\"},{\"id\":\"1253\",\"n\":\"lever donkey calf raise\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the leverage machine to the appropriate height for your body.\",\"Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.\",\"Place your hands on the handles or the support bars for stability.\",\"Engage your calves and lift your heels as high as possible, using the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1253.webp\",\"gif\":\"1253.mp4\",\"cat\":\"strength\",\"desc\":\"A donkey calf raise on a lever machine. It trains the calves.\"},{\"id\":\"0579\",\"n\":\"lever front pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.\",\"Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0579.webp\",\"gif\":\"0579.mp4\",\"cat\":\"strength\",\"desc\":\"Seated at a lever machine, you pull the handles down toward your chest. Builds the lats and upper back.\",\"fv\":\"7071\"},{\"id\":\"0580\",\"n\":\"lever gripless shrug\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the leverage machine.\",\"Grasp the handles with your palms facing inwards and your arms fully extended.\",\"Keeping your back straight, exhale and elevate your shoulders as high as possible.\",\"Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0580.webp\",\"gif\":\"0580.mp4\",\"cat\":\"strength\",\"desc\":\"A machine shrug without gripping a bar, so you lift your shoulders straight up. Focuses on the upper traps.\"},{\"id\":\"1439\",\"n\":\"lever gripless shrug v. 2\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the pad.\",\"Grasp the handles or bars with an overhand grip, keeping your arms straight.\",\"Keeping your back straight, lift your shoulders up towards your ears as high as possible.\",\"Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1439.webp\",\"gif\":\"1439.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug on a lever machine without handles to grip, so the lift comes from the traps alone. Version 2 of the machine drawing.\"},{\"id\":\"2288\",\"n\":\"lever gripper hands\",\"bp\":\"lower arms\",\"eq\":\"leverage machine\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Adjust the seat height and grip the handles of the leverage machine.\",\"Keep your back straight and your feet flat on the ground.\",\"Exhale and squeeze the handles, contracting your forearms.\",\"Hold the contraction for a second, then slowly release and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2288.webp\",\"gif\":\"2288.mp4\",\"cat\":\"strength\",\"desc\":\"A machine gripper where you squeeze the handles closed. Strengthens the forearms and grip.\"},{\"id\":\"1615\",\"n\":\"lever hammer grip preacher curl\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the leverage machine.\",\"Place your upper arms on the preacher pad, ensuring your chest is pressed against it.\",\"Grasp the handles with a hammer grip (palms facing each other).\",\"Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1615.webp\",\"gif\":\"1615.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl on a lever machine with a neutral hammer grip. It hits the brachialis and forearms along with the biceps.\"},{\"id\":\"0581\",\"n\":\"lever high row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rear deltoids\"],\"st\":[\"Adjust the seat height and foot platform to a comfortable position.\",\"Sit on the machine with your chest against the pad and your feet flat on the foot platform.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and engage your core.\",\"Pull the handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0581.webp\",\"gif\":\"0581.mp4\",\"cat\":\"strength\",\"desc\":\"On a machine, you pull the handles down and back from a high position. Targets the lats and upper back.\",\"fv\":\"3100\"},{\"id\":\"2286\",\"n\":\"lever hip extension v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Adjust the machine to fit your body and sit on it with your back against the backrest.\",\"Place your feet on the footrests and grip the handles for stability.\",\"Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.\",\"Pause for a moment at the top, then slowly lower your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2286.webp\",\"gif\":\"2286.mp4\",\"cat\":\"strength\",\"desc\":\"A machine hip extension that drives your leg back against resistance. Targets the glutes and hamstrings.\"},{\"id\":\"2611\",\"n\":\"lever horizontal one leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.\",\"Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.\",\"Place your hands on the handles or sides of the machine for stability.\",\"Push the footplate away from your body by extending your leg, keeping your back against the backrest.\",\"Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"2611.webp\",\"gif\":\"2611.mp4\",\"cat\":\"strength\",\"desc\":\"A horizontal machine leg press done one leg at a time. Builds the glutes and quads.\",\"fv\":\"0883\"},{\"id\":\"1299\",\"n\":\"lever incline chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Adjust the seat and backrest of the leverage machine to a comfortable position.\",\"Sit on the machine with your back against the backrest and your feet flat on the floor.\",\"Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.\",\"Push the handles forward and away from your body until your arms are fully extended.\",\"Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1299.webp\",\"gif\":\"1299.mp4\",\"cat\":\"strength\",\"desc\":\"A machine press with the handles set on an incline path. It works the upper chest and front shoulders with a fixed, stable motion.\"},{\"id\":\"1479\",\"n\":\"lever incline chest press v. 2\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and backrest angle on the leverage machine to a comfortable position.\",\"Sit on the machine with your back against the backrest and your feet flat on the floor.\",\"Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.\",\"Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.\",\"Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1479.webp\",\"gif\":\"1479.mp4\",\"cat\":\"strength\",\"desc\":\"A lever machine chest press with an inclined path, version 2. It builds the upper chest, front delts and triceps.\",\"fv\":\"2455\"},{\"id\":\"0582\",\"n\":\"lever kneeling leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Adjust the machine to fit your body and select the desired weight.\",\"Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.\",\"Grasp the handles or the sides of the machine for stability.\",\"Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.\",\"Pause for a moment at the top of the movement, squeezing your hamstrings.\",\"Inhale and slowly lower your legs back to the starting position, fully extending your knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0582.webp\",\"gif\":\"0582.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling on a machine, you curl your lower legs up against a pad. Isolates the hamstrings.\",\"fv\":\"3609\"},{\"id\":\"0583\",\"n\":\"lever kneeling twist\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.\",\"Grasp the handles or the sides of the machine for stability.\",\"Keeping your core engaged, twist your torso to one side as far as comfortably possible.\",\"Pause for a moment, then slowly return to the starting position.\",\"Repeat the twist to the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0583.webp\",\"gif\":\"0583.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling on a machine, you rotate your torso against resistance. Trains the obliques and core.\"},{\"id\":\"0584\",\"n\":\"lever lateral raise\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"upper back\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the pad.\",\"Grasp the handles with an overhand grip and keep your arms straight.\",\"Exhale and raise your arms out to the sides until they are parallel to the floor.\",\"Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0584.webp\",\"gif\":\"0584.mp4\",\"cat\":\"strength\",\"desc\":\"On a lever machine, you raise your arms out to the sides against resistance. Isolates the side delts.\",\"fv\":\"3629\"},{\"id\":\"0585\",\"n\":\"lever leg extension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Adjust the seat height and backrest of the machine to fit your body.\",\"Sit on the machine with your back against the backrest and your feet on the footpad.\",\"Grasp the handles or sidebars for stability.\",\"Extend your legs forward by straightening your knees, lifting the weight.\",\"Pause for a moment at the top, then slowly lower the weight back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0585.webp\",\"gif\":\"0585.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you straighten your legs against a pad. A simple quad builder.\",\"fv\":\"2256\"},{\"id\":\"0586\",\"n\":\"lever lying leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\"],\"st\":[\"Adjust the machine to fit your body and select the desired weight.\",\"Lie face down on the machine with your legs straight and your heels against the padded lever.\",\"Grasp the handles or the sides of the machine for stability.\",\"Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.\",\"Hold the contracted position for a brief pause as you squeeze your hamstrings.\",\"Inhale and slowly lower the lever back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0586.webp\",\"gif\":\"0586.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down on a machine, you curl your heels toward your glutes. Isolates the hamstrings.\",\"fv\":\"2223\"},{\"id\":\"3195\",\"n\":\"lever lying two-one leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Adjust the machine to fit your body and sit on it with your back against the backrest.\",\"Place your legs on the lever pad, just above your ankles.\",\"Grasp the handles on the sides of the machine for support.\",\"Keeping your upper body still, exhale and curl your legs up towards your glutes.\",\"Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3195.webp\",\"gif\":\"3195.mp4\",\"cat\":\"strength\",\"desc\":\"A lying machine leg curl that starts with both legs and finishes with one. It targets the hamstrings with a controlled, heavier lowering phase.\"},{\"id\":\"0587\",\"n\":\"lever military press\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the backrest.\",\"Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.\",\"Push the handles upward until your arms are fully extended, but do not lock your elbows.\",\"Pause for a moment at the top, then slowly lower the handles back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0587.webp\",\"gif\":\"0587.mp4\",\"cat\":\"strength\",\"desc\":\"On a machine, you press the handles overhead from shoulder height. Builds the shoulders and triceps.\",\"fv\":\"3101\"},{\"id\":\"0588\",\"n\":\"lever narrow grip seated row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and footrests to ensure proper form.\",\"Sit on the machine with your feet flat on the footrests and your knees slightly bent.\",\"Grasp the handles with a narrow grip, palms facing each other.\",\"Keep your back straight and lean slightly forward.\",\"Pull the handles towards your torso, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement.\",\"Slowly release the handles and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0588.webp\",\"gif\":\"0588.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you pull a narrow grip handle toward your torso. Trains the lats and mid back.\"},{\"id\":\"0589\",\"n\":\"lever one arm bent over row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.\",\"Bend forward at the hips, keeping your back straight and your head up.\",\"Let the barbell hang in front of you with your arms fully extended.\",\"Pull the barbell up towards your chest, keeping your elbows close to your body.\",\"Squeeze your shoulder blades together at the top of the movement.\",\"Lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0589.webp\",\"gif\":\"0589.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm row on a lever machine, pulling the handle toward your hip. Works the lats and upper back one side at a time.\"},{\"id\":\"1356\",\"n\":\"lever one arm lateral high row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself facing the machine.\",\"Grasp the handle with one hand and keep your back straight.\",\"Pull the handle towards your body, keeping your elbow close to your side.\",\"Squeeze your back muscles at the top of the movement.\",\"Slowly release the handle back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1356.webp\",\"gif\":\"1356.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm high row on a lever machine. It works the upper back and lats and lets you train each side on its own.\"},{\"id\":\"1347\",\"n\":\"lever one arm lateral wide pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.\",\"Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.\",\"Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.\",\"Slowly return the handle to the starting position, fully extending your arm.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1347.webp\",\"gif\":\"1347.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm pulldown on a lever machine that works the lats one side at a time. It helps even out strength between left and right.\"},{\"id\":\"0590\",\"n\":\"lever one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the pad.\",\"Grasp the lever handle with one hand and position your elbow at a 90-degree angle.\",\"Press the lever upward until your arm is fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the lever back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"0590.webp\",\"gif\":\"0590.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you press one handle overhead at a time. Trains each shoulder separately with help from the triceps.\"},{\"id\":\"0591\",\"n\":\"lever overhand triceps dip\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Adjust the machine to the appropriate height and secure your body in position.\",\"Grasp the handles with an overhand grip and position your body so that your arms are fully extended.\",\"Lower your body by bending your elbows, keeping your upper arms close to your sides.\",\"Continue lowering until your upper arms are parallel to the floor.\",\"Pause for a moment, then push yourself back up to the starting position by extending your elbows.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0591.webp\",\"gif\":\"0591.mp4\",\"cat\":\"strength\",\"desc\":\"On a dip machine, you press the handles down and extend your elbows. Focuses on the triceps and chest.\"},{\"id\":\"0592\",\"n\":\"lever preacher curl\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the leverage machine.\",\"Place your upper arms on the pad and grip the handles with an underhand grip.\",\"Keep your back straight and your elbows positioned on the pad.\",\"Exhale and curl your forearms towards your upper arms, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0592.webp\",\"gif\":\"0592.mp4\",\"cat\":\"strength\",\"desc\":\"With your arms on a preacher pad, you curl the handles up. Isolates the biceps with no swinging.\"},{\"id\":\"1614\",\"n\":\"lever preacher curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.\",\"Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.\",\"Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale as you slowly lower the handles back to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1614.webp\",\"gif\":\"1614.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl on a lever machine, version 2. The pad locks your upper arms in place so the biceps do the work.\",\"fv\":\"2819\"},{\"id\":\"2285\",\"n\":\"lever pullover\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat and handles of the leverage machine to a comfortable position.\",\"Sit on the machine with your back against the pad and grasp the handles with an overhand grip.\",\"Keep your arms slightly bent and your core engaged.\",\"Slowly pull the handles towards your chest, squeezing your lats.\",\"Pause for a moment at the peak contraction, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2285.webp\",\"gif\":\"2285.mp4\",\"cat\":\"strength\",\"desc\":\"A machine pullover that sweeps the handles toward you. Works the lats with a long range of motion.\"},{\"id\":\"2736\",\"n\":\"lever reverse grip lateral pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.\",\"Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2736.webp\",\"gif\":\"2736.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse grip lat pulldown on a machine. Builds the lats and biceps.\",\"fv\":\"11302\"},{\"id\":\"1616\",\"n\":\"lever reverse grip preacher curl\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the leverage machine.\",\"Grasp the handles with an underhand grip, palms facing up.\",\"Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.\",\"Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the handles back to the starting position, fully extending your elbows.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1616.webp\",\"gif\":\"1616.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl on a lever machine with an overhand grip. It shifts work to the forearms and brachialis.\"},{\"id\":\"1348\",\"n\":\"lever reverse grip vertical row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and footplate position to ensure proper alignment.\",\"Sit on the machine with your chest against the pad and your feet flat on the footplate.\",\"Grasp the handles with an underhand grip, palms facing up.\",\"Keep your back straight and engage your core.\",\"Pull the handles towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1348.webp\",\"gif\":\"1348.mp4\",\"cat\":\"strength\",\"desc\":\"A machine row with an underhand grip and a vertical handle path. It works the upper back, lats and biceps.\",\"fv\":\"2619\"},{\"id\":\"0593\",\"n\":\"lever reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Adjust the leverage machine to fit your body and secure your feet in the foot pads.\",\"Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.\",\"Cross your arms over your chest or place them behind your head.\",\"Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0593.webp\",\"gif\":\"0593.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a machine, you swing your legs up behind you. Works the glutes and lower back.\",\"fv\":\"3177\"},{\"id\":\"1349\",\"n\":\"lever reverse t-bar row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and footplate position on the leverage machine.\",\"Sit on the machine with your chest against the pad and your feet flat on the footplate.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and engage your core.\",\"Pull the handles towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1349.webp\",\"gif\":\"1349.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse grip row on a t-bar style machine, chest supported. It builds the upper back and lats with a strict path.\",\"fv\":\"3104\"},{\"id\":\"2315\",\"n\":\"lever rotary calf\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankle stabilizers\"],\"st\":[\"Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.\",\"Place your toes on the footplate, with your heels hanging off the edge.\",\"Grasp the handles or the sides of the machine for stability.\",\"Push through the balls of your feet, raising your heels as high as possible.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2315.webp\",\"gif\":\"2315.mp4\",\"cat\":\"strength\",\"desc\":\"A seated rotary calf raise on a machine. Builds the calf muscles.\",\"fv\":\"3105\"},{\"id\":\"2335\",\"n\":\"lever seated calf press\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"hamstrings\"],\"st\":[\"Adjust the seat of the machine so that your shoulders are aligned with the lever pad.\",\"Place your toes on the lower portion of the platform and position your knees under the lever pad.\",\"Grasp the handles on the sides of the seat for stability.\",\"Press the lever pad down by extending your ankles, lifting your heels as high as possible.\",\"Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2335.webp\",\"gif\":\"2335.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine calf press. Builds the calf muscles.\",\"fv\":\"2558\"},{\"id\":\"0594\",\"n\":\"lever seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankle stabilizers\"],\"st\":[\"Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.\",\"Place your toes on the footplate with your heels hanging off the edge.\",\"Grasp the handles or the sides of the seat for stability.\",\"Push through the balls of your feet to raise your heels as high as possible.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0594.webp\",\"gif\":\"0594.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you press through the balls of your feet to raise your heels. Isolates the calves, especially the soleus.\",\"fv\":\"3106\"},{\"id\":\"1452\",\"n\":\"lever seated crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Sit on the leverage machine with your back against the pad and your feet flat on the floor.\",\"Grasp the handles or place your hands on the side pads for support.\",\"Engage your abs and slowly lean back, allowing the pad to move with you.\",\"Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.\",\"Pause for a moment at the top, then slowly release and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1452.webp\",\"gif\":\"1452.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine crunch where you curl your torso toward your hips against resistance. It trains the abs with a controlled, fixed path.\",\"fv\":\"2445\"},{\"id\":\"0595\",\"n\":\"lever seated crunch (chest pad)\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Adjust the seat height and chest pad position according to your comfort.\",\"Sit on the machine with your back against the chest pad and your feet flat on the floor.\",\"Grasp the handles or side bars for stability.\",\"Engage your abs and slowly lean back, allowing the chest pad to move with you.\",\"Pause for a moment at the maximum contraction, feeling the tension in your abs.\",\"Slowly return to the starting position by contracting your abs and pulling yourself back up.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0595.webp\",\"gif\":\"0595.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine with a chest pad, you curl your torso forward against resistance. Works the abs.\",\"fv\":\"3753\"},{\"id\":\"3760\",\"n\":\"lever seated crunch v. 2\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit on the leverage machine with your back against the pad and your feet secured under the footpads.\",\"Place your hands on the handles or the sides of the seat for support.\",\"Engage your abs and slowly crunch forward, bringing your chest towards your knees.\",\"Pause for a moment at the top of the movement, squeezing your abs.\",\"Slowly return to the starting position, allowing your back to round slightly.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3760.webp\",\"gif\":\"3760.mp4\",\"cat\":\"strength\",\"desc\":\"A second take on the seated machine crunch, curling forward against resistance. It trains the abs.\"},{\"id\":\"1451\",\"n\":\"lever seated dip\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.\",\"Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.\",\"Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.\",\"Pause for a moment, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1451.webp\",\"gif\":\"1451.mp4\",\"cat\":\"strength\",\"desc\":\"A seated dip on a lever machine that mimics the dip motion with guided support. It targets the triceps and also works the chest and front delts.\",\"fv\":\"2250\"},{\"id\":\"0596\",\"n\":\"lever seated fly\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"trapezius\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the pad.\",\"Grasp the handles with a pronated grip and keep your elbows slightly bent.\",\"Exhale and push the handles forward, bringing them together in front of your chest.\",\"Pause for a moment, squeezing your chest muscles.\",\"Inhale and slowly return to the starting position, allowing your chest muscles to stretch.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0596.webp\",\"gif\":\"0596.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you bring the handles together in front of you with arms nearly straight. Isolates the chest.\",\"fv\":\"2255\"},{\"id\":\"3759\",\"n\":\"lever seated good morning\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Adjust the seat height so that your hips are slightly higher than your knees.\",\"Sit on the machine with your back against the pad and your feet flat on the footrests.\",\"Grasp the handles or the sides of the seat for stability.\",\"Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.\",\"Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3759.webp\",\"gif\":\"3759.mp4\",\"cat\":\"strength\",\"desc\":\"A seated good morning on a lever machine, hinging forward at the hips and back up. It trains the glutes, hamstrings and lower back.\"},{\"id\":\"0597\",\"n\":\"lever seated hip abduction\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Adjust the seat height so that your knees are at a 90-degree angle.\",\"Sit on the machine with your back against the backrest and your feet on the footrests.\",\"Place your hands on the side handles for stability.\",\"Engage your abductors and slowly push your legs apart, away from the midline of your body.\",\"Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0597.webp\",\"gif\":\"0597.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you push your knees apart against pads. Works the outer hips and glutes.\",\"fv\":\"3611\"},{\"id\":\"0598\",\"n\":\"lever seated hip adduction\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the backrest.\",\"Place your feet on the footrests and grasp the handles for stability.\",\"Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.\",\"Pause for a moment at the peak contraction, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0598.webp\",\"gif\":\"0598.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you squeeze your knees together against pads. Trains the inner thighs.\",\"fv\":\"3612\"},{\"id\":\"0599\",\"n\":\"lever seated leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\"],\"st\":[\"Adjust the machine to fit your body and sit on it with your back against the backrest.\",\"Place your lower legs under the padded lever, just above your ankles.\",\"Grasp the handles on the sides of the machine for support.\",\"Keeping your upper legs stationary, exhale and curl your legs up as far as possible.\",\"Hold the contracted position for a brief pause as you squeeze your hamstrings.\",\"Inhale and slowly lower the lever back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0599.webp\",\"gif\":\"0599.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you curl your lower legs back and down against a pad. Isolates the hamstrings.\",\"fv\":\"2257\"},{\"id\":\"0600\",\"n\":\"lever seated leg raise crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the leverage machine with your back against the backrest and your feet on the footrests.\",\"Grasp the handles or sidebars for stability.\",\"Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.\",\"Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0600.webp\",\"gif\":\"0600.mp4\",\"cat\":\"strength\",\"desc\":\"On a machine, you raise your legs while curling your torso. Works the lower abs and hip flexors.\",\"fv\":\"3647\"},{\"id\":\"0602\",\"n\":\"lever seated reverse fly\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.\",\"Grasp the handles with an overhand grip and keep your arms slightly bent.\",\"Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.\",\"Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0602.webp\",\"gif\":\"0602.mp4\",\"cat\":\"strength\",\"desc\":\"Chest against the pad, you pull the handles back and out in a wide arc. Targets the rear delts and upper back.\",\"fv\":\"2822\"},{\"id\":\"0601\",\"n\":\"lever seated reverse fly (parallel grip)\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.\",\"Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.\",\"Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.\",\"Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0601.webp\",\"gif\":\"0601.mp4\",\"cat\":\"strength\",\"desc\":\"Chest against the pad, you pull the handles back and out with a parallel grip. Targets the rear delts and upper back.\"},{\"id\":\"1350\",\"n\":\"lever seated row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and footrests to a comfortable position.\",\"Sit on the machine with your chest against the pad and your feet on the footrests.\",\"Grasp the handles with an overhand grip, shoulder-width apart.\",\"Keep your back straight and your core engaged.\",\"Pull the handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement.\",\"Slowly release the handles and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1350.webp\",\"gif\":\"1350.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row on a lever machine with chest support. It works the upper back and lats with minimal lower back strain.\",\"fv\":\"2246\"},{\"id\":\"1385\",\"n\":\"lever seated squat calf raise on leg press machine\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.\",\"Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.\",\"Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.\",\"Release the safety handles and push the footplate away from you by extending your knees.\",\"Once your knees are fully extended, slowly lower your heels by flexing your calves.\",\"Pause for a moment at the bottom, then push the footplate back up by extending your calves.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1385.webp\",\"gif\":\"1385.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise performed on a leg press machine by pressing with your toes. It builds the calves with a stable, supported load.\",\"fv\":\"2610\"},{\"id\":\"0603\",\"n\":\"lever shoulder press\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the backrest.\",\"Grasp the handles with an overhand grip and position your hands at shoulder level.\",\"Push the handles upward until your arms are fully extended, but do not lock your elbows.\",\"Pause for a moment at the top, then slowly lower the handles back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0603.webp\",\"gif\":\"0603.mp4\",\"cat\":\"strength\",\"desc\":\"Seated at a lever machine, you press the handles overhead. Builds the shoulders and triceps.\"},{\"id\":\"0869\",\"n\":\"lever shoulder press v. 2\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Adjust the seat height and backrest of the leverage machine to a comfortable position.\",\"Sit on the machine with your back against the backrest and your feet flat on the floor.\",\"Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.\",\"Push the handles upward and forward until your arms are fully extended, but not locked.\",\"Pause for a moment at the top, then slowly lower the handles back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0869.webp\",\"gif\":\"0869.mp4\",\"cat\":\"strength\",\"desc\":\"A machine shoulder press with a lever arm, pressing the handles overhead. It builds the shoulders and triceps.\"},{\"id\":\"2318\",\"n\":\"lever shoulder press v. 3\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Adjust the seat height and backrest of the leverage machine to a comfortable position.\",\"Sit on the machine with your back against the backrest and your feet flat on the floor.\",\"Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.\",\"Push the handles upward and forward until your arms are fully extended, but not locked.\",\"Pause for a moment at the top, then slowly lower the handles back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2318.webp\",\"gif\":\"2318.mp4\",\"cat\":\"strength\",\"desc\":\"A machine shoulder press, pushing the handles overhead. Builds shoulder and triceps strength.\"},{\"id\":\"0604\",\"n\":\"lever shrug\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself on the leverage machine with your back against the pad.\",\"Grasp the handles with an overhand grip and keep your arms straight.\",\"Keeping your back straight, lift your shoulders up towards your ears as high as possible.\",\"Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0604.webp\",\"gif\":\"0604.mp4\",\"cat\":\"strength\",\"desc\":\"On a lever machine, you lift your shoulders straight up and lower with control. Builds the upper traps.\",\"fv\":\"3107\"},{\"id\":\"0605\",\"n\":\"lever standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankle stabilizers\"],\"st\":[\"Adjust the machine to your height and stand with your feet shoulder-width apart.\",\"Place your shoulders under the pads and hold onto the handles for stability.\",\"Raise your heels as high as possible by extending your ankles.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0605.webp\",\"gif\":\"0605.mp4\",\"cat\":\"strength\",\"desc\":\"Standing with pads on your shoulders, you rise onto your toes and lower back down. Isolates the calves.\",\"fv\":\"2211\"},{\"id\":\"3758\",\"n\":\"lever standing chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your feet flat on the ground.\",\"Grasp the handles with an overhand grip and position your hands at chest level.\",\"Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.\",\"Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3758.webp\",\"gif\":\"3758.mp4\",\"cat\":\"strength\",\"desc\":\"A standing chest press on a lever machine, pressing the handles forward. It builds the chest, shoulders and triceps.\"},{\"id\":\"0606\",\"n\":\"lever t bar row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and footplate position to ensure proper alignment.\",\"Sit on the machine with your chest against the pad and your feet flat on the footplate.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and engage your core.\",\"Pull the handles towards your torso, squeezing your shoulder blades together.\",\"Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0606.webp\",\"gif\":\"0606.mp4\",\"cat\":\"strength\",\"desc\":\"Chest on the pad, you row a T-bar style handle toward your torso. Works the lats, mid back and rear delts.\",\"fv\":\"2885\"},{\"id\":\"1351\",\"n\":\"lever t-bar reverse grip row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and engage your core.\",\"Pull the handles towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1351.webp\",\"gif\":\"1351.mp4\",\"cat\":\"strength\",\"desc\":\"A t-bar style machine row with a reverse grip and chest support. It works the upper back, lats and biceps.\"},{\"id\":\"0607\",\"n\":\"lever triceps extension\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back against the pad.\",\"Grasp the handles with an overhand grip and fully extend your arms in front of you.\",\"Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.\",\"Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0607.webp\",\"gif\":\"0607.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a machine, you press the handles down by extending your elbows. Isolates the triceps.\",\"fv\":\"3614\"},{\"id\":\"1313\",\"n\":\"lever unilateral row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and position yourself facing the machine.\",\"Grasp the handles with an overhand grip and keep your back straight.\",\"Pull the handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1313.webp\",\"gif\":\"1313.mp4\",\"cat\":\"strength\",\"desc\":\"A machine row where you pull each handle independently. It works the upper back and lets you even out strength differences between sides.\"},{\"id\":\"0609\",\"n\":\"london bridge\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"forearms\"],\"st\":[\"Attach the rope to a high anchor point.\",\"Stand facing away from the anchor point with your feet shoulder-width apart.\",\"Grasp the rope with an overhand grip, palms facing down.\",\"Lean forward slightly, keeping your back straight and core engaged.\",\"Pull the rope towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0609.webp\",\"gif\":\"0609.mp4\",\"cat\":\"strength\",\"desc\":\"Using a rope anchored high, you lean back and pull your body through a controlled swing. Trains the back, shoulders and core.\"},{\"id\":\"3013\",\"n\":\"low glute bridge on floor\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your arms by your sides, palms facing down.\",\"Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.\",\"Pause for a moment at the top, squeezing your glutes.\",\"Slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3013.webp\",\"gif\":\"3013.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A low glute bridge on the floor, lifting your hips. Works the glutes and hamstrings.\",\"fv\":\"3014\"},{\"id\":\"1352\",\"n\":\"lower back curl\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie flat on your stomach with your legs extended and your arms by your sides.\",\"Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1352.webp\",\"gif\":\"1352.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down and lift your chest off the floor in a curling motion. It strengthens the lower back with a gentle bodyweight movement.\"},{\"id\":\"3582\",\"n\":\"lunge with jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing with your feet shoulder-width apart.\",\"Take a step forward with your right foot, lowering your body into a lunge position.\",\"Push off with your right foot and jump into the air, switching the position of your feet mid-air.\",\"Land softly with your left foot forward and immediately lower your body into a lunge position.\",\"Continue alternating between lunges and jumps for the desired number of repetitions.\"],\"img\":\"3582.webp\",\"gif\":\"3582.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lunge followed by a jump where the legs switch in mid-air. It builds leg power and raises your heart rate.\"},{\"id\":\"1688\",\"n\":\"lunge with twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\"],\"st\":[\"Start by standing with your feet shoulder-width apart.\",\"Take a step forward with your right foot, lowering your body into a lunge position.\",\"As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.\",\"Pause for a moment, then return to the starting position.\",\"Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1688.webp\",\"gif\":\"1688.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge with a torso twist. It works the legs and the obliques.\"},{\"id\":\"0613\",\"n\":\"lying (side) quads stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Lie on your side with your legs straight.\",\"Bend your top leg and grab your ankle or foot with your hand.\",\"Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.\",\"Hold the stretch for 20-30 seconds.\",\"Release the stretch and repeat on the other side.\"],\"img\":\"0613.webp\",\"gif\":\"0613.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your side, you pull your top foot toward your glutes to stretch the front of the thigh. A gentle quad stretch.\"},{\"id\":\"2312\",\"n\":\"lying elbow to knee\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.\",\"At the same time, extend your right leg straight out and lift it off the ground.\",\"Pause for a moment, then return to the starting position.\",\"Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"2312.webp\",\"gif\":\"2312.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor crunch that brings elbow to opposite knee. Works the abs and obliques.\"},{\"id\":\"0620\",\"n\":\"lying leg raise flat bench\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on a flat bench with your back pressed against it.\",\"Place your hands under your glutes for support.\",\"Keep your legs straight and together, and lift them up towards the ceiling.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0620.webp\",\"gif\":\"0620.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a flat bench, you raise and lower straight legs. Works the lower abs and hip flexors.\"},{\"id\":\"0865\",\"n\":\"lying leg-hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Place your hands under your glutes for support.\",\"Engage your core and lift your legs off the ground, raising them towards the ceiling.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0865.webp\",\"gif\":\"0865.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying leg raise that also lifts the hips off the floor at the top. It trains the lower abs.\",\"fv\":\"2447\"},{\"id\":\"1301\",\"n\":\"machine inner chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your back flat against the pad.\",\"Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.\",\"Push the handles forward until your arms are fully extended, exhaling during the movement.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1301.webp\",\"gif\":\"1301.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine chest press where the handles bring your hands together. It emphasises the inner chest in a stable path.\",\"fv\":\"11440\"},{\"id\":\"0624\",\"n\":\"march sit (wall)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your back against a wall and your feet hip-width apart.\",\"Slowly slide your back down the wall until your knees are bent at a 90-degree angle.\",\"Lift your right foot off the ground and bring your knee towards your chest.\",\"Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.\",\"Continue alternating between lifting your right and left foot for the desired number of repetitions.\"],\"img\":\"0624.webp\",\"gif\":\"0624.mp4\",\"cat\":\"isometric\",\"desc\":\"With your back against a wall, you hold a seated position with knees bent to 90 degrees. Builds endurance in the quads and glutes.\"},{\"id\":\"1353\",\"n\":\"medicine ball catch and overhead throw\",\"bp\":\"back\",\"eq\":\"medicine ball\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.\",\"Bend your knees slightly and engage your core.\",\"Lower your body into a squat position, keeping your back straight and chest up.\",\"Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.\",\"Release the ball at the top of the movement and catch it on the way down.\",\"Lower your body back into the squat position and repeat for the desired number of repetitions.\"],\"img\":\"1353.webp\",\"gif\":\"1353.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Squat down, then explode up and throw a medicine ball overhead and catch it again. It trains power through the hips, back and shoulders.\"},{\"id\":\"1302\",\"n\":\"medicine ball chest pass\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart, holding the medicine ball at chest level.\",\"Extend your arms forward, pushing the medicine ball away from your chest with force.\",\"As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.\",\"Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.\",\"Continue for the desired number of repetitions.\"],\"img\":\"1302.webp\",\"gif\":\"1302.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Throw a medicine ball forward from your chest with a quick push, then catch it and repeat. It builds explosive pushing power in the chest and arms.\"},{\"id\":\"1303\",\"n\":\"medicine ball chest push from 3 point stance\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.\",\"Extend your legs and position your body in a straight line.\",\"Lower your chest towards the ground while keeping your back straight.\",\"Push the medicine ball away from your body, extending your arm fully.\",\"Return to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"1303.webp\",\"gif\":\"1303.mp4\",\"cat\":\"plyometrics\",\"desc\":\"From a three point stance with one hand on a medicine ball, you push the ball away explosively. It trains the chest and arms with power and balance.\"},{\"id\":\"1304\",\"n\":\"medicine ball chest push multiple response\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a medicine ball at chest level.\",\"Extend your arms forward, pushing the medicine ball away from your chest.\",\"Pause for a moment, then slowly bring the medicine ball back to your chest.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1304.webp\",\"gif\":\"1304.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Push a medicine ball away from your chest and catch it again in a quick, repeated flow. It builds explosive chest and arm power.\"},{\"id\":\"1305\",\"n\":\"medicine ball chest push single response\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart, holding the medicine ball at chest level.\",\"Extend your arms forward, pushing the medicine ball away from your chest.\",\"Pause for a moment, then slowly bring the medicine ball back to your chest.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1305.webp\",\"gif\":\"1305.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Push a medicine ball away from your chest in one strong effort, reset, then go again. It trains explosive power in the chest and arms.\"},{\"id\":\"1312\",\"n\":\"medicine ball chest push with run release\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a medicine ball at chest level.\",\"Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.\",\"As you push the ball forward, release it and let it roll forward.\",\"Quickly run forward and catch the ball before it hits the ground.\",\"Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.\",\"Continue alternating legs and repeating the exercise for the desired number of repetitions.\"],\"img\":\"1312.webp\",\"gif\":\"1312.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Push a medicine ball forward from your chest, then sprint after it and catch it. It trains explosive chest power plus quick acceleration.\"},{\"id\":\"1701\",\"n\":\"medicine ball close grip push up\",\"bp\":\"upper arms\",\"eq\":\"medicine ball\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands on the medicine ball, shoulder-width apart.\",\"Lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"Push back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1701.webp\",\"gif\":\"1701.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A close grip push-up with your hands on a medicine ball. It hits the triceps and challenges stability.\"},{\"id\":\"1354\",\"n\":\"medicine ball overhead slam\",\"bp\":\"back\",\"eq\":\"medicine ball\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.\",\"Engage your core and keep your back straight.\",\"Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.\",\"As you slam the ball down, use your entire body to generate power, including your shoulders and core.\",\"Catch the ball on the bounce and repeat for the desired number of repetitions.\"],\"img\":\"1354.webp\",\"gif\":\"1354.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Lift a medicine ball overhead and slam it into the floor with force. It builds full body power and trains the lats, core and shoulders.\",\"fv\":\"2545\"},{\"id\":\"1750\",\"n\":\"medicine ball supine chest throw\",\"bp\":\"upper arms\",\"eq\":\"medicine ball\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie flat on your back on a bench with your knees bent and feet flat on the ground.\",\"Hold the medicine ball with both hands, extending your arms straight up above your chest.\",\"Lower the medicine ball towards your chest, keeping your elbows close to your body.\",\"Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.\",\"Catch the medicine ball and repeat for the desired number of repetitions.\"],\"img\":\"1750.webp\",\"gif\":\"1750.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive chest throw with a medicine ball while lying on your back. Develops fast pressing power in the triceps and chest.\",\"nd\":[\"bench\"]},{\"id\":\"0627\",\"n\":\"mixed grip chin-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your feet off the ground.\",\"Engage your back muscles and pull your body up towards the bar, leading with your chest.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position with control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0627.webp\",\"gif\":\"0627.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up with one hand overhand and one underhand. Builds the lats, biceps and grip, and you switch hands between sets.\"},{\"id\":\"3217\",\"n\":\"modified hindu push-up (male)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.\",\"Lower your body towards the ground, bending your elbows and keeping your core engaged.\",\"As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.\",\"Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3217.webp\",\"gif\":\"3217.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A modified hindu push-up that flows from a pike through a low dive to a lifted chest. It trains the chest, shoulders and triceps while opening up the spine.\"},{\"id\":\"1421\",\"n\":\"modified push up to lower arms\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\",\"shoulders\"],\"st\":[\"Start in a push-up position with your hands directly under your shoulders and your body in a straight line.\",\"Lower your body down towards the ground by bending your elbows, keeping them close to your sides.\",\"Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.\",\"Pause for a moment, then push through your palms to lift your forearms back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1421.webp\",\"gif\":\"1421.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A modified push-up variation where you shift your weight toward your wrists. It strengthens the forearms, chest and shoulders.\"},{\"id\":\"0628\",\"n\":\"monster walk\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Place a resistance band around your ankles.\",\"Stand with your feet shoulder-width apart and slightly bend your knees.\",\"Take a step to the side with your right foot, maintaining tension on the resistance band.\",\"Follow with your left foot, stepping to the side to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0628.webp\",\"gif\":\"0628.mp4\",\"cat\":\"strength\",\"desc\":\"With a band around your ankles, you step sideways in a slight squat. Fires up the glutes and outer hips.\"},{\"id\":\"0630\",\"n\":\"mountain climber\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"triceps\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line.\",\"Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.\",\"Continue alternating legs in a running motion, keeping your hips low and your core engaged.\",\"Maintain a steady pace and breathe evenly throughout the exercise.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0630.webp\",\"gif\":\"0630.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a high plank, you drive your knees toward your chest one after another. Works the core, shoulders and gets your heart rate up.\",\"fv\":\"4645\"},{\"id\":\"0631\",\"n\":\"muscle up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"shoulders\",\"chest\"],\"st\":[\"Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.\",\"Engage your core and pull your body up towards the bar, leading with your chest.\",\"As you reach the top of the movement, transition your grip so that your palms are facing towards you.\",\"Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.\",\"Reverse the movement by slowly lowering yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0631.webp\",\"gif\":\"0631.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You pull yourself above a bar and then press up into a dip position. Trains the lats, chest and arms in a powerful transition.\"},{\"id\":\"1401\",\"n\":\"muscle-up (on vertical bar)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"forearms\"],\"st\":[\"Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.\",\"Engage your core and pull your body up towards the bar, leading with your chest.\",\"As you pull yourself up, lean back slightly and bring your elbows towards your sides.\",\"Continue pulling until your chest reaches the bar and your elbows are fully bent.\",\"Pause for a moment at the top, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1401.webp\",\"gif\":\"1401.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A muscle-up on a vertical bar, pulling up and then pressing over the top. It trains the lats, chest and triceps in one flowing move.\"},{\"id\":\"2328\",\"n\":\"narrow push-up on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"stability ball\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.\",\"Engage your core and keep your body in a straight line from head to toe.\",\"Lower your chest towards the ball by bending your elbows, keeping them close to your body.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2328.webp\",\"gif\":\"2328.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A close-hand push-up with hands on a stability ball. Hits the triceps and chest while the ball challenges your balance.\"},{\"id\":\"1403\",\"n\":\"neck side stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Stand or sit up straight with your shoulders relaxed.\",\"Tilt your head to one side, bringing your ear towards your shoulder.\",\"Hold the stretch for 15-30 seconds.\",\"Repeat on the other side.\",\"Perform 2-4 sets on each side.\"],\"img\":\"1403.webp\",\"gif\":\"1403.mp4\",\"cat\":\"stretching\",\"desc\":\"Gently tilt your head sideways to stretch the side of your neck. It eases tension in the neck and upper shoulder.\",\"fv\":\"4289\"},{\"id\":\"0634\",\"n\":\"negative crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0634.webp\",\"gif\":\"0634.mp4\",\"cat\":\"strength\",\"desc\":\"A slow lowering crunch where you control the way down. Works the abs with extra time under tension.\"},{\"id\":\"1495\",\"n\":\"oblique crunch v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.\",\"Pause for a moment, then lower your shoulder blades back down to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1495.webp\",\"gif\":\"1495.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An oblique crunch where you curl up and to the side, version 2. It trains the side abs.\",\"fv\":\"2443\"},{\"id\":\"0635\",\"n\":\"oblique crunches floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with your knees bent and feet flat on the floor.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.\",\"Pause for a moment, then lower your shoulder blades back down to the floor.\",\"Repeat on the other side, alternating sides with each repetition.\"],\"img\":\"0635.webp\",\"gif\":\"0635.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you crunch up and rotate toward one knee, then the other. Targets the obliques and abs.\"},{\"id\":\"0636\",\"n\":\"olympic barbell hammer curl\",\"bp\":\"upper arms\",\"eq\":\"olympic barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.\",\"Let the barbell hang at arm's length in front of your thighs, with your palms facing your body.\",\"Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\",\"Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.\",\"Hold the contracted position for a brief pause as you squeeze your biceps.\",\"Inhale and slowly begin to lower the barbell back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0636.webp\",\"gif\":\"0636.mp4\",\"cat\":\"strength\",\"desc\":\"Standing with an Olympic barbell, you curl with a neutral style grip. Works the biceps and brachialis along with the forearms.\"},{\"id\":\"0637\",\"n\":\"olympic barbell triceps extension\",\"bp\":\"upper arms\",\"eq\":\"olympic barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.\",\"Raise the barbell above your head, fully extending your arms.\",\"Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.\",\"Pause for a moment, then extend your arms back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0637.webp\",\"gif\":\"0637.mp4\",\"cat\":\"strength\",\"desc\":\"Holding an Olympic barbell overhead, you bend and straighten your elbows. Isolates the triceps.\"},{\"id\":\"1355\",\"n\":\"one arm against wall\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand facing a wall with your feet shoulder-width apart.\",\"Extend one arm straight out in front of you and place your palm against the wall.\",\"Engage your core and lean your body forward, keeping your arm straight and your back flat.\",\"Slowly push against the wall with your palm, activating your lat muscles.\",\"Hold the position for a few seconds, then release and repeat with the other arm.\"],\"img\":\"1355.webp\",\"gif\":\"1355.mp4\",\"cat\":\"isometric\",\"desc\":\"Stand facing a wall and press one arm into it while you lean in. It switches on the lats and shoulder with no equipment.\"},{\"id\":\"0638\",\"n\":\"one arm chin-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand facing a pull-up bar with your feet shoulder-width apart.\",\"Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.\",\"Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.\",\"Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.\",\"Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms and repeat.\"],\"img\":\"0638.webp\",\"gif\":\"0638.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced pull-up using only one arm. Builds big lat and biceps strength and takes lots of practice.\"},{\"id\":\"0639\",\"n\":\"one arm dip\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Stand facing away from a bench or chair, with your feet shoulder-width apart.\",\"Place one hand on the bench or chair behind you, fingers pointing towards your body.\",\"Extend your legs out in front of you, keeping your heels on the ground.\",\"Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.\",\"Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.\"],\"img\":\"0639.webp\",\"gif\":\"0639.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip using one arm on a bench or chair behind you. Works the triceps and shoulders on one side at a time.\"},{\"id\":\"0640\",\"n\":\"one arm slam (with medicine ball)\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"back\"],\"st\":[\"Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.\",\"Bend your knees slightly and engage your core.\",\"Raise the medicine ball above your head, fully extending your arm.\",\"Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.\",\"Catch the medicine ball on the bounce and repeat for the desired number of repetitions.\"],\"img\":\"0640.webp\",\"gif\":\"0640.mp4\",\"cat\":\"plyometrics\",\"desc\":\"You lift a medicine ball overhead with one hand and slam it to the floor. Builds explosive power in the shoulders, core and lats.\"},{\"id\":\"1773\",\"n\":\"one arm towel row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.\",\"Bend forward at the waist, keeping your back straight and your core engaged.\",\"Extend your arm fully, allowing the towel to hang in front of you.\",\"Pull the towel towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the towel back to the starting position.\",\"Repeat for the desired number of repetitions, then switch arms.\"],\"img\":\"1773.webp\",\"gif\":\"1773.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-arm row using a towel while hinged forward. Trains the upper back and builds grip strength.\"},{\"id\":\"1386\",\"n\":\"one leg donkey calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing forward.\",\"Place your hands on a stable surface for support, such as a wall or a bar.\",\"Lift one leg off the ground, keeping your knee slightly bent.\",\"Raise your heel as high as possible, using your calf muscles.\",\"Pause for a moment at the top, then slowly lower your heel back down.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"1386.webp\",\"gif\":\"1386.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg donkey calf raise where you bend forward and rise onto your toes. It trains the calf with a deep stretch at the bottom.\"},{\"id\":\"1387\",\"n\":\"one leg floor calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.\",\"Lift one foot off the ground and balance on the other foot.\",\"Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1387.webp\",\"gif\":\"1387.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg calf raise on the floor with a hand on a wall for balance. It builds calf strength and ankle stability.\",\"fv\":\"2625\"},{\"id\":\"1476\",\"n\":\"one leg squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Extend one leg forward, keeping it off the ground.\",\"Bend your standing leg and lower your body down as if sitting back into a chair.\",\"Keep your chest up and your back straight.\",\"Push through your heel to return to the starting position.\",\"Repeat with the other leg.\"],\"img\":\"1476.webp\",\"gif\":\"1476.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat on a single leg that challenges strength and balance. It targets the glutes and quads on one side at a time.\"},{\"id\":\"0641\",\"n\":\"otis up\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0641.webp\",\"gif\":\"0641.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up variation where you curl up with your hands behind your head. Works the abs and hip flexors.\",\"fv\":\"3837\"},{\"id\":\"0642\",\"n\":\"outside leg kick push-up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.\",\"As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.\",\"Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.\",\"Continue alternating leg kicks and push-ups for the desired number of repetitions.\"],\"img\":\"0642.webp\",\"gif\":\"0642.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where you kick one leg out to the side at the top. Adds core and hip work to the chest and arm effort.\"},{\"id\":\"0643\",\"n\":\"overhead triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand or sit upright with your feet shoulder-width apart.\",\"Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.\",\"With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.\",\"Hold the stretch for 15-30 seconds, then release.\",\"Repeat on the other side.\"],\"img\":\"0643.webp\",\"gif\":\"0643.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching one arm overhead and bending the elbow, you pull gently on it with the other hand. Stretches the triceps and shoulder.\"},{\"id\":\"3147\",\"n\":\"pelvic tilt\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands by your sides.\",\"Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.\",\"Hold this position for a few seconds, focusing on contracting your abs.\",\"Release the tilt and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3147.webp\",\"gif\":\"3147.mp4\",\"cat\":\"mobility\",\"desc\":\"A small rocking movement of the pelvis while lying on your back. It wakes up the abs and teaches you to control the position of your lower back.\",\"fv\":\"3148\"},{\"id\":\"1422\",\"n\":\"pelvic tilt into bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with your knees bent and feet flat on the ground.\",\"Place your arms by your sides with your palms facing down.\",\"Engage your glutes and core muscles.\",\"Tilt your pelvis upward, lifting your hips off the ground.\",\"Hold the bridge position for a few seconds.\",\"Slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1422.webp\",\"gif\":\"1422.mp4\",\"cat\":\"mobility\",\"desc\":\"Lie on your back with your knees bent, tilt your pelvis, then lift into a bridge. It warms up the glutes, lower back and core.\"},{\"id\":\"1388\",\"n\":\"peroneals stretch\",\"bp\":\"lower legs\",\"eq\":\"rope\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Loop the rope around the ball of your foot and hold the ends of the rope with your hands.\",\"Gently pull the rope towards you, flexing your foot and stretching your calf muscles.\",\"Hold the stretch for 15-30 seconds.\",\"Release the tension on the rope and repeat the stretch on the other leg.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1388.webp\",\"gif\":\"1388.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch where you turn your foot to open the outer side of your lower leg. It targets the peroneal muscles beside the calf.\",\"fv\":\"4325\"},{\"id\":\"3662\",\"n\":\"pike-to-cobra push-up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"triceps\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.\",\"Lower your upper body towards the ground by bending your elbows, keeping them close to your body.\",\"As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.\",\"Reverse the movement by bending your elbows and lowering your chest back down towards the ground.\",\"Push through your hands to return to the inverted V position.\",\"Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3662.webp\",\"gif\":\"3662.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up flow that moves from pike position down and through to a cobra. It trains the shoulders, chest and spine mobility.\"},{\"id\":\"1306\",\"n\":\"plyo push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart.\",\"Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.\",\"Push explosively off the ground, using your chest muscles to propel your upper body off the ground.\",\"Land softly with your hands back in the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1306.webp\",\"gif\":\"1306.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push-up that you drive explosively so your hands leave the floor. It builds fast pressing power in the chest, shoulders and triceps.\"},{\"id\":\"1687\",\"n\":\"posterior step to overhead reach\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"quadriceps\",\"shoulders\"],\"st\":[\"Stand with your feet hip-width apart and your arms by your sides.\",\"Take a step back with your right foot, landing on the ball of your foot.\",\"Bend your left knee and lower your body into a lunge position.\",\"As you lower into the lunge, simultaneously reach your arms overhead.\",\"Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.\",\"Repeat the movement on the other side, stepping back with your left foot and bending your right knee.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1687.webp\",\"gif\":\"1687.mp4\",\"cat\":\"mobility\",\"desc\":\"A step back with an overhead reach. It warms up the hips and core and stretches the front of the body.\"},{\"id\":\"1389\",\"n\":\"posterior tibialis stretch\",\"bp\":\"lower legs\",\"eq\":\"rope\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Loop the rope around the ball of your foot and hold the ends of the rope with your hands.\",\"Gently pull the rope towards you, flexing your foot and stretching your calf muscles.\",\"Hold the stretch for 20-30 seconds.\",\"Release the tension on the rope and relax your foot.\",\"Repeat the stretch on the other leg.\"],\"img\":\"1389.webp\",\"gif\":\"1389.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that opens the inner side of the lower leg. It targets the posterior tibialis along your shin and ankle.\"},{\"id\":\"3119\",\"n\":\"potty squat\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing slightly outward.\",\"Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.\",\"Keep your chest up and your back straight throughout the movement.\",\"Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3119.webp\",\"gif\":\"3119.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat done as a deep, comfortable squat. Works the legs, glutes and core.\",\"fv\":\"3118\"},{\"id\":\"3132\",\"n\":\"potty squat with support\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing slightly outward.\",\"Hold onto a stable support, such as a chair or wall, for balance.\",\"Lower your body down into a squat position by bending your knees and pushing your hips back.\",\"Keep your chest up and your back straight throughout the movement.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3132.webp\",\"gif\":\"3132.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep squat done holding a support for balance. Works the glutes and legs.\",\"fv\":\"3131\"},{\"id\":\"0648\",\"n\":\"power clean\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Start with the barbell on the ground in front of you, with your feet shoulder-width apart.\",\"Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.\",\"As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.\",\"As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.\",\"Stand up with the barbell, fully extending your hips and knees.\",\"Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0648.webp\",\"gif\":\"0648.mp4\",\"cat\":\"olympic\",\"desc\":\"You pull the bar from the floor and catch it on your shoulders in a quarter squat. Builds explosive power in the legs, hips and back.\"},{\"id\":\"3665\",\"n\":\"power point plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"glutes\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.\",\"Engage your core and squeeze your glutes to maintain a stable position.\",\"Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.\",\"Hold this position for the desired amount of time, keeping your core and glutes engaged.\",\"To return to the starting position, push through your forearms and lift your body back up into a high plank position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3665.webp\",\"gif\":\"3665.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank where you shift from your hands to your forearms and back, one arm at a time. It trains the abs and shoulders.\"},{\"id\":\"3203\",\"n\":\"prisoner half sit-up (male)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3203.webp\",\"gif\":\"3203.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A half sit-up with the hands held behind the head, like a prisoner. It trains the abs through a short, controlled range.\"},{\"id\":\"1707\",\"n\":\"prone twist on stability ball\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.\",\"Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.\",\"Pause for a moment, then return to the starting position.\",\"Repeat the rotation to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"1707.webp\",\"gif\":\"1707.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A twisting motion lying face down on a stability ball. It trains the abs and obliques.\"},{\"id\":\"0651\",\"n\":\"pull up (neutral grip)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.\",\"Engage your core and squeeze your shoulder blades together.\",\"Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position with control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0651.webp\",\"gif\":\"0651.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You hang from a bar with a neutral grip and pull your chin above it. Works the lats and biceps with a shoulder friendly grip.\"},{\"id\":\"0650\",\"n\":\"pull-in (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Place your hands on the sides of the stability ball for support.\",\"Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.\",\"Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0650.webp\",\"gif\":\"0650.mp4\",\"cat\":\"strength\",\"desc\":\"Hands on the floor and feet on a stability ball, you pull the ball toward your chest. Works the abs and hip flexors while challenging balance.\",\"fv\":\"6030\"},{\"id\":\"0652\",\"n\":\"pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Hang from a pull-up bar with your palms facing away from you and your arms fully extended.\",\"Engage your core and squeeze your shoulder blades together.\",\"Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.\",\"Pause at the top of the movement, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0652.webp\",\"gif\":\"0652.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You hang from a bar with an overhand grip and pull your chin above it. A classic builder for the lats and upper back.\"},{\"id\":\"1689\",\"n\":\"push and pull bodyweight\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"deltoids\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.\",\"Lower your chest towards the ground by bending your elbows, keeping your body straight.\",\"Push through your palms to extend your arms and return to the starting position.\",\"From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1689.webp\",\"gif\":\"1689.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight movement of pushing and pulling against your own resistance. It trains the chest and arms.\"},{\"id\":\"3638\",\"n\":\"push to run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and your body in a straight line.\",\"Lower your chest towards the ground by bending your elbows, keeping your body straight.\",\"Push through your hands to extend your arms and return to the starting position.\",\"Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.\",\"Continue alternating knees as fast as you can while maintaining good form.\",\"Continue for the desired duration or number of repetitions.\"],\"img\":\"3638.webp\",\"gif\":\"3638.mp4\",\"cat\":\"cardio\",\"desc\":\"A push-up that flows into fast alternating knee drives in the plank position. It raises the heart rate and trains the chest and core.\"},{\"id\":\"1307\",\"n\":\"push up on bosu ball\",\"bp\":\"chest\",\"eq\":\"bosu ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place the bosu ball on the ground with the flat side facing up.\",\"Position yourself in a push-up position with your hands on the outer edges of the bosu ball.\",\"Engage your core and lower your body down towards the bosu ball by bending your elbows.\",\"Push yourself back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1307.webp\",\"gif\":\"1307.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a bosu ball. The unstable surface makes your chest, shoulders and core work harder to stay steady.\"},{\"id\":\"0662\",\"n\":\"push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"deltoids\",\"core\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.\",\"Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0662.webp\",\"gif\":\"0662.mp4\",\"cat\":\"calisthenics\",\"desc\":\"The classic push-up from a high plank. Works the chest, shoulders, triceps and core in one move.\",\"fv\":\"2881\"},{\"id\":\"0653\",\"n\":\"push-up (bosu ball)\",\"bp\":\"chest\",\"eq\":\"bosu ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place the bosu ball on the ground with the flat side facing up.\",\"Position yourself in a push-up position with your hands on the outer edges of the bosu ball.\",\"Engage your core and lower your body down towards the bosu ball by bending your elbows.\",\"Push yourself back up to the starting position by extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0653.webp\",\"gif\":\"0653.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a bosu ball. The unstable surface trains the chest, arms and core stabilizers.\",\"fv\":\"8097\"},{\"id\":\"0655\",\"n\":\"push-up (on stability ball)\",\"bp\":\"chest\",\"eq\":\"stability ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.\",\"Extend your legs straight out behind you, balancing on your toes.\",\"Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0655.webp\",\"gif\":\"0655.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a stability ball. The unstable surface adds core and shoulder stability work to the chest effort.\",\"fv\":\"2679\"},{\"id\":\"0656\",\"n\":\"push-up (on stability ball)\",\"bp\":\"chest\",\"eq\":\"stability ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.\",\"Extend your legs straight out behind you, balancing on your toes.\",\"Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0656.webp\",\"gif\":\"0656.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a stability ball. The unstable surface adds core and shoulder stability work to the chest effort.\"},{\"id\":\"0659\",\"n\":\"push-up (wall)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"deltoids\"],\"st\":[\"Stand facing a wall, about arm's length away.\",\"Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.\",\"Step back a few feet, keeping your body straight and your feet hip-width apart.\",\"Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.\",\"Push back up to the starting position, straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0659.webp\",\"gif\":\"0659.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up against a wall, a gentle version for beginners. Works the chest, shoulders and triceps.\",\"fv\":\"2614\"},{\"id\":\"0658\",\"n\":\"push-up (wall) v. 2\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Stand facing a wall, about arm's length away.\",\"Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.\",\"Step back with your feet, keeping them hip-width apart.\",\"Engage your core and keep your body in a straight line from head to heels.\",\"Bend your elbows and lower your chest towards the wall, keeping your body straight.\",\"Pause for a moment, then push yourself back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0658.webp\",\"gif\":\"0658.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up against a wall, a gentle version for beginners. Works the chest, shoulders and triceps.\"},{\"id\":\"0660\",\"n\":\"push-up close-grip off dumbbell\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start in a push-up position with your hands placed close together, directly under your shoulders.\",\"Hold a dumbbell in each hand, resting them on the ground.\",\"Lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0660.webp\",\"gif\":\"0660.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A close grip push-up with your hands on dumbbells. Puts extra focus on the triceps and gives a deeper range.\"},{\"id\":\"0661\",\"n\":\"push-up inside leg kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.\",\"As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.\",\"Lower your leg back down and repeat the push-up, then switch to the other leg.\",\"Continue alternating leg kicks with each push-up repetition.\"],\"img\":\"0661.webp\",\"gif\":\"0661.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where you kick one leg inward at the top. Adds core and hip work to the chest effort.\"},{\"id\":\"0663\",\"n\":\"push-up medicine ball\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank position with your hands on the medicine ball, shoulder-width apart.\",\"Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0663.webp\",\"gif\":\"0663.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a medicine ball. The unstable base adds core and shoulder stability work.\",\"fv\":\"11439\"},{\"id\":\"1467\",\"n\":\"push-up on lower arms\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start in a plank position with your forearms on the ground and elbows directly below your shoulders.\",\"Engage your core and keep your body in a straight line from head to toe.\",\"Lower your chest towards the ground by bending your elbows, keeping them close to your body.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1467.webp\",\"gif\":\"1467.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your forearms on the floor instead of your hands. It is tough on the triceps and the core.\"},{\"id\":\"3145\",\"n\":\"push-up plus\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.\",\"Lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.\",\"At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.\",\"Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3145.webp\",\"gif\":\"3145.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up finished with an extra shove that spreads the shoulder blades at the top. It trains the chest and the serratus muscles that stabilise the shoulder blades.\",\"fv\":\"3146\"},{\"id\":\"0664\",\"n\":\"push-up to side plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"triceps\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and your body in a straight line.\",\"Lower your body towards the ground by bending your elbows, keeping your core engaged.\",\"Push back up to the starting position.\",\"Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.\",\"Hold the side plank position for a few seconds, then return to the starting position.\",\"Repeat the push-up and side plank on the opposite side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0664.webp\",\"gif\":\"0664.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You do a push-up, then rotate into a side plank. Works the chest, arms, shoulders and obliques.\",\"fv\":\"0682\"},{\"id\":\"3533\",\"n\":\"quads\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Lower your body by bending your knees and pushing your hips back as if sitting on a chair.\",\"Keep your chest up and your back straight.\",\"Lower yourself until your thighs are parallel to the ground.\",\"Push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3533.webp\",\"gif\":\"3533.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat variation focused on the front of the thighs. It trains the quads and glutes.\"},{\"id\":\"3201\",\"n\":\"quarter sit-up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3201.webp\",\"gif\":\"3201.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A short-range sit-up where you curl only partway up. It keeps tension on the abs and is easier on the lower back than a full sit-up.\",\"fv\":\"3261\"},{\"id\":\"3552\",\"n\":\"quick feet v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"hamstrings\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms by your sides.\",\"Begin by rapidly moving your feet up and down, as if you were running in place.\",\"Keep your movements quick and light, focusing on staying on the balls of your feet.\",\"Continue for the desired duration or number of repetitions.\"],\"img\":\"3552.webp\",\"gif\":\"3552.mp4\",\"cat\":\"cardio\",\"desc\":\"A quick on-the-spot footwork drill with fast, light steps. It raises the heart rate and builds foot speed.\",\"fv\":\"5494\"},{\"id\":\"0666\",\"n\":\"raise single arm push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Extend one arm straight out to the side, parallel to the ground.\",\"Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.\",\"Push back up to the starting position, using your chest muscles to lift your body.\",\"Repeat with the other arm extended.\"],\"img\":\"0666.webp\",\"gif\":\"0666.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where you lift one arm out to the side at the top. Challenges the core and shoulder stability.\"},{\"id\":\"0668\",\"n\":\"rear decline bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie on your back with your feet flat on the ground and your knees bent.\",\"Place your arms by your sides with your palms facing down.\",\"Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.\",\"Hold this position for a few seconds, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0668.webp\",\"gif\":\"0668.mp4\",\"cat\":\"isometric\",\"desc\":\"Lying on your back, you lift your hips and hold with your feet on the floor. Works the glutes, hamstrings and lower back.\",\"hd\":1},{\"id\":\"0669\",\"n\":\"rear deltoid stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\"],\"st\":[\"Stand tall with your feet shoulder-width apart.\",\"Extend your right arm across your chest, placing your left hand on your right elbow.\",\"Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.\",\"Hold the stretch for 15-30 seconds, then release.\",\"Repeat on the other side.\"],\"img\":\"0669.webp\",\"gif\":\"0669.mp4\",\"cat\":\"stretching\",\"desc\":\"You pull one arm across your chest to stretch the back of the shoulder. Hold it gently on each side.\",\"fv\":\"4301\"},{\"id\":\"0670\",\"n\":\"rear pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body straight.\",\"Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0670.webp\",\"gif\":\"0670.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up where you pull toward the back of your neck. Challenges the upper back and shoulders, so keep it controlled.\"},{\"id\":\"1582\",\"n\":\"reclining big toe pose with rope\",\"bp\":\"upper legs\",\"eq\":\"rope\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie on your back with your legs extended and your arms by your sides.\",\"Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.\",\"Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.\",\"Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.\",\"Repeat with your left leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"1582.webp\",\"gif\":\"1582.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back, you hold your big toe with a rope and raise the leg straight. It stretches the hamstrings.\"},{\"id\":\"3236\",\"n\":\"resistance band hip thrusts on knees (female)\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Start by kneeling on the ground with your knees hip-width apart and your feet flexed.\",\"Wrap the resistance band around your thighs, just above your knees.\",\"Place your hands on your hips or extend them out in front of you for balance.\",\"Engage your glutes and core muscles.\",\"Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.\",\"Hold the position for a moment, then slowly lower your knees back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3236.webp\",\"gif\":\"3236.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling hip thrust against a resistance band around the thighs. It trains the glutes with a hip extension.\",\"mv\":\"7277\"},{\"id\":\"3007\",\"n\":\"resistance band leg extension\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Attach the resistance band to a sturdy anchor point and secure it around your ankle.\",\"Stand facing the anchor point with your feet shoulder-width apart.\",\"Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.\",\"Pause for a moment at the top, then slowly return your leg to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"3007.webp\",\"gif\":\"3007.mp4\",\"cat\":\"strength\",\"desc\":\"A leg extension with a resistance band around your ankle. Builds the quads.\",\"fv\":\"3008\"},{\"id\":\"3123\",\"n\":\"resistance band seated biceps curl\",\"bp\":\"upper arms\",\"eq\":\"resistance band\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a chair or bench with your back straight and feet flat on the ground.\",\"Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.\",\"Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the resistance band back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3123.webp\",\"gif\":\"3123.mp4\",\"cat\":\"strength\",\"desc\":\"A seated biceps curl using a resistance band. Builds the biceps.\",\"fv\":\"3134\"},{\"id\":\"3124\",\"n\":\"resistance band seated chest press\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit on a chair or bench with your back straight and feet flat on the ground.\",\"Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.\",\"Extend your arms forward, pushing the resistance band away from your chest.\",\"Pause for a moment at the end of the movement, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3124.webp\",\"gif\":\"3124.mp4\",\"cat\":\"strength\",\"desc\":\"A seated chest press using a resistance band. Builds the chest, shoulders and triceps.\",\"fv\":\"3135\"},{\"id\":\"3006\",\"n\":\"resistance band seated hip abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Sit on a chair or bench with your back straight and feet flat on the ground.\",\"Wrap the resistance band around your thighs, just above your knees.\",\"Place your hands on the sides of the chair or bench for support.\",\"Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.\",\"Pause for a moment at the end of the movement, then slowly bring your knees back together.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3006.webp\",\"gif\":\"3006.mp4\",\"cat\":\"strength\",\"desc\":\"A seated hip abduction pushing your knees apart against a resistance band. Works the outer hips and glutes.\",\"fv\":\"3005\"},{\"id\":\"3122\",\"n\":\"resistance band seated shoulder press\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Sit on a chair or bench with your back straight and feet flat on the ground.\",\"Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.\",\"Press the band overhead, extending your arms fully.\",\"Pause for a moment at the top, then slowly lower the band back down to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3122.webp\",\"gif\":\"3122.mp4\",\"cat\":\"strength\",\"desc\":\"A seated shoulder press using a resistance band. Builds the shoulders and triceps.\",\"fv\":\"3133\"},{\"id\":\"3144\",\"n\":\"resistance band seated straight back row\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Sit on the floor with your legs extended and loop the resistance band around your feet.\",\"Hold the ends of the resistance band with your hands, palms facing each other.\",\"Keep your back straight and lean slightly back, engaging your core.\",\"Pull the resistance band towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly release the tension and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3144.webp\",\"gif\":\"3144.mp4\",\"cat\":\"strength\",\"desc\":\"A seated straight-back row using a resistance band. Builds the upper back and lats.\",\"fv\":\"3143\"},{\"id\":\"0872\",\"n\":\"reverse crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your arms extended along your sides.\",\"Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.\",\"Contract your abs and curl your hips off the floor, bringing your knees towards your chest.\",\"Pause for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0872.webp\",\"gif\":\"0872.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch that curls the hips off the floor with the knees bent. It targets the lower abs.\",\"fv\":\"0671\"},{\"id\":\"0672\",\"n\":\"reverse dip\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Position yourself between two parallel bars with your arms fully extended and your body straight.\",\"Lower your body by bending your elbows until your upper arms are parallel to the ground.\",\"Pause for a moment, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0672.webp\",\"gif\":\"0672.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You lower and press your body between parallel bars with your hands behind you. Works the triceps and shoulders.\",\"fv\":\"4302\"},{\"id\":\"0673\",\"n\":\"reverse grip machine lat pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.\",\"Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.\",\"Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.\",\"Pull the handles down towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0673.webp\",\"gif\":\"0673.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a lat pulldown machine, you pull the bar down with a reverse grip. Works the lats and biceps.\",\"fv\":\"3615\"},{\"id\":\"0674\",\"n\":\"reverse grip pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with an underhand grip, hands shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body straight.\",\"Engage your back muscles and pull your body up towards the bar, leading with your chest.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0674.webp\",\"gif\":\"0674.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with an underhand grip. Puts extra emphasis on the biceps along with the lats.\",\"fv\":\"3895\"},{\"id\":\"0675\",\"n\":\"reverse hyper extension (on stability ball)\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.\",\"Place your hands on the ground in front of you for stability.\",\"Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0675.webp\",\"gif\":\"0675.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down on a stability ball, you raise your legs behind you. Works the glutes and lower back.\"},{\"id\":\"1423\",\"n\":\"reverse hyper on flat bench\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.\",\"Hold onto the bench for stability.\",\"Keeping your legs straight, raise them up towards the ceiling as high as you can.\",\"Squeeze your glutes at the top of the movement.\",\"Slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1423.webp\",\"gif\":\"1423.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down with your hips at the end of a bench and swing your legs up behind you. It works the glutes and lower back.\"},{\"id\":\"3663\",\"n\":\"reverse plank with leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\"],\"st\":[\"Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.\",\"Press through your hands and lift your hips off the ground, coming into a reverse plank position.\",\"Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.\",\"Hold for a moment, then lower your leg back down.\",\"Repeat with the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"3663.webp\",\"gif\":\"3663.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse plank where you lift one leg at a time. It trains the abs, glutes and the back of the body.\"},{\"id\":\"0677\",\"n\":\"ring dips\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Start by hanging from the rings with your arms fully extended and your body straight.\",\"Lower your body by bending your elbows until your shoulders are below your elbows.\",\"Push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0677.webp\",\"gif\":\"0677.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip performed on gymnastic rings. The unstable rings train the chest, triceps and shoulder stability.\"},{\"id\":\"2571\",\"n\":\"rocking frog stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Start by kneeling on the ground with your knees hip-width apart.\",\"Place your hands on the ground in front of you for support.\",\"Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.\",\"Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.\",\"Hold this position for a few seconds, feeling a stretch in your glutes.\",\"Slowly return to the starting position by bending your knees and lowering your hips back down.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2571.webp\",\"gif\":\"2571.mp4\",\"cat\":\"stretching\",\"desc\":\"A rocking frog stretch that opens the hips and inner thighs. Helps loosen the glutes and groin.\"},{\"id\":\"0678\",\"n\":\"rocky pull-up pulldown\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand in front of a pull-up bar with your feet shoulder-width apart.\",\"Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body straight.\",\"Engage your back muscles and pull your body up towards the bar, leading with your chest.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0678.webp\",\"gif\":\"0678.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up bar move that mixes a pull-up with a controlled pulldown. Builds the lats, upper back and arms.\",\"fv\":\"2704\"},{\"id\":\"2208\",\"n\":\"roller back stretch\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Start by sitting on the ground with your legs extended in front of you.\",\"Place the roller perpendicular to your body, just below your glutes.\",\"Slowly roll your body backwards, allowing the roller to move up your back.\",\"Continue rolling until the roller reaches your upper back.\",\"Pause for a moment, then slowly roll back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2208.webp\",\"gif\":\"2208.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling your back over a roller to loosen it up. Helps ease stiffness along the spine.\"},{\"id\":\"2204\",\"n\":\"roller body saw\",\"bp\":\"waist\",\"eq\":\"roller\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a plank position with your forearms on the roller and your body in a straight line.\",\"Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.\",\"Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2204.webp\",\"gif\":\"2204.mp4\",\"cat\":\"strength\",\"desc\":\"A plank with forearms on a roller, rolling forward and back like a saw. Challenges the abs and core.\",\"fv\":\"5435\"},{\"id\":\"2205\",\"n\":\"roller hip lat stretch\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Start by kneeling on the ground with the roller positioned under your hips.\",\"Place your hands on the roller for support.\",\"Slowly roll the roller forward, extending your hips and stretching your glutes.\",\"Hold the stretch for a few seconds, then roll back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2205.webp\",\"gif\":\"2205.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling roller stretch that opens the hips and glutes. Helps release tension around the hips.\"},{\"id\":\"2202\",\"n\":\"roller hip stretch\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Start by sitting on the ground with your legs extended in front of you.\",\"Place the roller under your glutes, just above your knees.\",\"Lean back and place your hands on the ground behind you for support.\",\"Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.\",\"Pause for a moment at the end of the movement, feeling a stretch in your glutes.\",\"Slowly roll the roller back to the starting position, extending your legs.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2202.webp\",\"gif\":\"2202.mp4\",\"cat\":\"mobility\",\"desc\":\"A roller-assisted hip opener for the glutes. Helps loosen tight hips with a controlled rolling motion.\",\"fv\":\"5434\"},{\"id\":\"2206\",\"n\":\"roller reverse crunch\",\"bp\":\"waist\",\"eq\":\"roller\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.\",\"Place the roller between your feet and grip it with your toes.\",\"Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2206.webp\",\"gif\":\"2206.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse crunch where you roll a roller toward you with your feet. Trains the lower abs.\",\"fv\":\"5438\"},{\"id\":\"2203\",\"n\":\"roller seated shoulder flexor depresor retractor\",\"bp\":\"chest\",\"eq\":\"roller\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Sit on a flat surface with your legs extended in front of you.\",\"Hold the roller with both hands, palms facing down, and place it on your thighs.\",\"Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.\",\"Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2203.webp\",\"gif\":\"2203.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated roller drill that rolls forward and back to work shoulder control. Helps with shoulder mobility and posture.\",\"fv\":\"5431\"},{\"id\":\"2209\",\"n\":\"roller seated single leg shoulder flexor depresor retractor\",\"bp\":\"chest\",\"eq\":\"roller\",\"tg\":\"pectorals\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"triceps\"],\"st\":[\"Sit on a flat surface with your legs extended in front of you.\",\"Hold the roller with both hands, palms facing down, and place it on your thighs.\",\"Lean back slightly and engage your core muscles.\",\"Raise the roller up to shoulder level, keeping your arms straight.\",\"Slowly lower the roller back down to your thighs.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2209.webp\",\"gif\":\"2209.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated single-leg roller drill for shoulder control. Helps with shoulder mobility and posture.\",\"fv\":\"5439\"},{\"id\":\"2207\",\"n\":\"roller side lat stretch\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.\",\"Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2207.webp\",\"gif\":\"2207.mp4\",\"cat\":\"stretching\",\"desc\":\"A roller stretch that reaches forward to lengthen the sides of your back. Helps loosen the lats.\"},{\"id\":\"0680\",\"n\":\"rope climb\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"upper back\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"biceps\",\"shoulders\"],\"st\":[\"Stand facing the rope with your feet shoulder-width apart.\",\"Grab the rope with both hands, palms facing towards you.\",\"Bend your knees slightly and engage your core.\",\"Begin pulling yourself up the rope by alternating hand-over-hand movements.\",\"Use your legs to assist in the upward movement.\",\"Continue climbing until you reach the desired height or the top of the rope.\",\"To descend, reverse the hand-over-hand movement while controlling your descent.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0680.webp\",\"gif\":\"0680.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You climb a rope using your arms and legs. A full body pull that builds the grip, lats and arms.\"},{\"id\":\"0685\",\"n\":\"run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing upright with your feet hip-width apart.\",\"Engage your core and keep your upper body relaxed.\",\"Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.\",\"Maintain a steady pace and continue jogging for the desired duration or distance.\",\"Remember to breathe deeply and maintain good posture throughout the exercise.\"],\"img\":\"0685.webp\",\"gif\":\"0685.mp4\",\"cat\":\"cardio\",\"desc\":\"A running style move that gets your heart rate up. Keep a steady pace for as long as you like.\",\"fv\":\"2196\"},{\"id\":\"0684\",\"n\":\"run (equipment)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start by standing upright with your feet hip-width apart.\",\"Engage your core and keep your upper body relaxed.\",\"Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.\",\"Maintain a steady pace and continue jogging for the desired duration or distance.\",\"Remember to breathe deeply and maintain good posture throughout the exercise.\"],\"img\":\"0684.webp\",\"gif\":\"0684.mp4\",\"cat\":\"cardio\",\"desc\":\"A running style move that gets your heart rate up. Keep a steady pace for as long as you like.\"},{\"id\":\"1585\",\"n\":\"runners stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\"],\"st\":[\"Stand with your feet hip-width apart.\",\"Take a step forward with your right foot, keeping your left foot planted.\",\"Bend your right knee and lower your body down, keeping your left leg straight.\",\"Place your hands on your right thigh for support.\",\"Hold the stretch for 20-30 seconds, then switch sides and repeat.\"],\"img\":\"1585.webp\",\"gif\":\"1585.mp4\",\"cat\":\"stretching\",\"desc\":\"A lunge position stretch for the hips, thighs and hamstrings, often used by runners to loosen up.\",\"fv\":\"4303\"},{\"id\":\"0687\",\"n\":\"russian twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Sit on the ground with your knees bent and feet flat on the floor.\",\"Lean back slightly while keeping your back straight and your core engaged.\",\"Hold your hands together in front of your chest or hold a weight if desired.\",\"Lift your feet off the ground, balancing on your sit bones.\",\"Twist your torso to the right, bringing your hands or weight towards the right side of your body.\",\"Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0687.webp\",\"gif\":\"0687.mp4\",\"cat\":\"strength\",\"desc\":\"Seated and leaning back, you rotate your torso from side to side. Works the obliques and abs.\",\"fv\":\"2538\"},{\"id\":\"3012\",\"n\":\"scapula dips\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"deltoids\"],\"st\":[\"Start by standing with your feet shoulder-width apart and your arms extended in front of you.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.\",\"Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3012.webp\",\"gif\":\"3012.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A scapular dip, moving the shoulder blades while your arms stay straight. Strengthens the traps and shoulder stabilisers.\",\"fv\":\"3937\"},{\"id\":\"3021\",\"n\":\"scapula push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line.\",\"Lower your chest towards the ground, keeping your elbows close to your body.\",\"As you lower, squeeze your shoulder blades together and push your chest forward.\",\"Pause for a moment at the bottom, then push back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3021.webp\",\"gif\":\"3021.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A scapular push-up, protracting and retracting the shoulder blades. Strengthens the serratus anterior and upper back.\"},{\"id\":\"0688\",\"n\":\"scapular pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.\",\"Retract your shoulder blades by pulling them down and back.\",\"Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0688.webp\",\"gif\":\"0688.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you pull your shoulder blades down without bending your arms. Builds shoulder control and the lower traps.\"},{\"id\":\"3219\",\"n\":\"scissor jumps (male)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Jump off the ground and simultaneously cross your right leg in front of your left leg.\",\"As you land, quickly switch legs, crossing your left leg in front of your right leg.\",\"Continue alternating legs and jumping as quickly as possible.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3219.webp\",\"gif\":\"3219.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick jumping drill where the legs cross in front of each other in the air. It raises your heart rate and builds light, springy legs.\"},{\"id\":\"1390\",\"n\":\"seated calf stretch (male)\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on the edge of a chair or bench with your feet flat on the ground.\",\"Extend one leg straight out in front of you, keeping your heel on the ground.\",\"Lean forward slightly, feeling a stretch in your calf muscle.\",\"Hold the stretch for 20-30 seconds.\",\"Switch legs and repeat the stretch.\"],\"img\":\"1390.webp\",\"gif\":\"1390.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit on a chair and reach to pull your toes toward you. It stretches the calf and the back of the lower leg.\",\"fv\":\"4304\"},{\"id\":\"1424\",\"n\":\"seated glute stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Bend your right knee and cross your right ankle over your left thigh.\",\"Place your right hand on the ground behind you for support.\",\"With your left hand, gently press down on your right knee to deepen the stretch.\",\"Hold the stretch for 30 seconds to 1 minute.\",\"Switch sides and repeat.\"],\"img\":\"1424.webp\",\"gif\":\"1424.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit on the floor and cross one ankle over the opposite knee, then lean in. It stretches the glutes and the outer hip.\"},{\"id\":\"0689\",\"n\":\"seated leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on a flat bench with your back straight and your feet flat on the ground.\",\"Place your hands on the sides of the bench for support.\",\"Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0689.webp\",\"gif\":\"0689.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a bench, you lift your legs and lower them again. Works the lower abs and hip flexors.\",\"fv\":\"2539\"},{\"id\":\"0690\",\"n\":\"seated lower back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Sit on the edge of a chair with your feet flat on the ground.\",\"Place your hands on your thighs or on the sides of the chair for support.\",\"Slowly lean forward from your hips, keeping your back straight.\",\"Feel the stretch in your lower back and hold for 20-30 seconds.\",\"Slowly return to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"0690.webp\",\"gif\":\"0690.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated on a chair, you lean forward to stretch the lower back. Hold it gently and breathe slowly.\",\"fv\":\"4305\"},{\"id\":\"2567\",\"n\":\"seated piriformis stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Bend your right knee and place your right foot on the outside of your left knee.\",\"Place your left elbow on the outside of your right knee and gently twist your torso to the right.\",\"Hold the stretch for 20-30 seconds, then switch sides and repeat.\"],\"img\":\"2567.webp\",\"gif\":\"2567.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch for the piriformis and glute muscles. Helps loosen tight hips.\"},{\"id\":\"0691\",\"n\":\"seated side crunch (wall)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Sit on the floor with your back against a wall and your legs extended in front of you.\",\"Bend your knees and place your feet flat on the floor, hip-width apart.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engage your abs and lean to one side, bringing your elbow towards your hip.\",\"Pause for a moment, then return to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0691.webp\",\"gif\":\"0691.mp4\",\"cat\":\"strength\",\"desc\":\"Seated against a wall, you crunch from side to side. Works the obliques with back support.\"},{\"id\":\"1587\",\"n\":\"seated wide angle pose sequence\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\"],\"st\":[\"Sit on the ground with your legs extended in a wide angle.\",\"Flex your feet and engage your quadriceps.\",\"Place your hands on the ground behind you for support.\",\"Keeping your back straight, lean forward from your hips.\",\"Continue leaning forward until you feel a stretch in your hamstrings.\",\"Hold this position for a few breaths.\",\"Slowly release the stretch and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1587.webp\",\"gif\":\"1587.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated sequence with legs wide that stretches the inner thighs and hamstrings. Move slowly with the breath.\",\"fv\":\"4306\"},{\"id\":\"0697\",\"n\":\"self assisted inverse leg curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Lie flat on your back on a mat or bench with your legs extended.\",\"Place your hands by your sides or under your glutes for support.\",\"Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.\",\"Pause for a moment at the top, then slowly lower your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0697.webp\",\"gif\":\"0697.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you curl your heels toward your glutes. A body weight move for the hamstrings.\"},{\"id\":\"1766\",\"n\":\"self assisted inverse leg curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.\",\"Place your hands on the side handles of the machine for support.\",\"Keeping your upper body stationary, exhale and curl your legs upward as far as possible.\",\"Hold the contracted position for a brief pause as you squeeze your hamstrings.\",\"Slowly lower your legs back to the starting position while inhaling.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1766.webp\",\"gif\":\"1766.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight leg curl on a lying leg curl station. Works the hamstrings with a controlled curl and slow lowering.\"},{\"id\":\"0696\",\"n\":\"self assisted inverse leg curl (on floor)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Bend your knees and place your feet flat on the ground, hip-width apart.\",\"Lift your hips off the ground, engaging your glutes and hamstrings.\",\"Slowly curl your legs towards your glutes, keeping your hips lifted.\",\"Pause for a moment at the top, then slowly extend your legs back to the starting position.\",\"Lower your hips back down to the ground.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0696.webp\",\"gif\":\"0696.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you slide your heels toward your glutes to train the hamstrings. Uses only your body weight.\"},{\"id\":\"3222\",\"n\":\"semi squat jump (male)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees and lower your body into a squat position.\",\"Jump explosively, extending your hips and knees while swinging your arms for momentum.\",\"Land softly on the balls of your feet and immediately go into the next repetition.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3222.webp\",\"gif\":\"3222.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A shallow squat followed by a jump, with the arms swinging for momentum. It trains the leg power and gets the heart rate up.\"},{\"id\":\"3656\",\"n\":\"short stride run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Find an open space or a treadmill to perform the exercise.\",\"Stand tall with your feet hip-width apart.\",\"Start jogging in place, lifting your knees high and pumping your arms.\",\"After a few seconds, start taking short strides forward, maintaining a quick pace.\",\"Continue running with short strides for the desired duration or distance.\"],\"img\":\"3656.webp\",\"gif\":\"3656.mp4\",\"cat\":\"cardio\",\"desc\":\"A run with short, quick strides. It raises the heart rate and builds foot speed.\"},{\"id\":\"1763\",\"n\":\"shoulder grip pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with a shoulder-width grip, palms facing away from you.\",\"Hang freely with your arms fully extended.\",\"Engage your back muscles and pull your body up towards the bar until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1763.webp\",\"gif\":\"1763.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with hands about shoulder-width apart. Builds the lats, upper back and biceps.\",\"fv\":\"3900\"},{\"id\":\"3699\",\"n\":\"shoulder tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Start in a high plank position with your hands directly under your shoulders and your body in a straight line.\",\"Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.\",\"Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.\",\"Continue alternating shoulder taps while keeping your hips and torso stable.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3699.webp\",\"gif\":\"3699.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A high plank where you tap the opposite shoulder with each hand. It trains the abs and builds shoulder stability.\",\"fv\":\"4660\"},{\"id\":\"0699\",\"n\":\"shoulder tap push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.\",\"Lower your body towards the ground by bending your elbows, keeping them close to your sides.\",\"As you push back up, lift your right hand off the ground and tap your left shoulder.\",\"Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.\",\"Continue alternating shoulder taps with each push-up repetition.\",\"Maintain a stable core and avoid excessive hip rotation throughout the exercise.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0699.webp\",\"gif\":\"0699.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a high plank, you tap one shoulder with the opposite hand. Works the shoulders and core stability.\"},{\"id\":\"1774\",\"n\":\"side bridge hip abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Lie on your side with your legs extended and stacked on top of each other.\",\"Prop yourself up on your forearm, keeping your elbow directly below your shoulder.\",\"Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.\",\"While keeping your core engaged, lift your top leg as high as possible without rotating your hips.\",\"Pause for a moment at the top, then lower your leg back down.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1774.webp\",\"gif\":\"1774.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side bridge with a top leg lift. Works the outer hips and glutes plus the core.\",\"fv\":\"0704\"},{\"id\":\"0705\",\"n\":\"side bridge v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\"],\"st\":[\"Lie on your side with your legs extended and stacked on top of each other.\",\"Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.\",\"Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.\",\"Hold this position for the desired amount of time.\",\"Lower your hips back down to the starting position.\",\"Repeat on the other side.\"],\"img\":\"0705.webp\",\"gif\":\"0705.mp4\",\"cat\":\"isometric\",\"desc\":\"Lying on your side, you hold your hips up off the floor on your forearm. Works the obliques and core.\",\"hd\":1},{\"id\":\"0709\",\"n\":\"side hip (on parallel bars)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Stand between two parallel bars with your feet shoulder-width apart.\",\"Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.\",\"Engage your abs and slowly lift your legs to the side, keeping them straight.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0709.webp\",\"gif\":\"0709.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Between parallel bars, you lift your body and swing your hips side to side. Works the obliques and core.\"},{\"id\":\"0710\",\"n\":\"side hip abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\"],\"st\":[\"Stand with your feet shoulder-width apart and your hands on your hips.\",\"Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.\",\"Pause for a moment at the top, then slowly lower your leg back down to the starting position.\",\"Repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0710.webp\",\"gif\":\"0710.mp4\",\"cat\":\"strength\",\"desc\":\"Standing on one leg, you lift the other leg out to the side. Works the outer hips and glutes.\"},{\"id\":\"1358\",\"n\":\"side lying floor stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\"],\"st\":[\"Lie on your side with your legs straight and your bottom arm extended straight overhead.\",\"Bend your top knee and place your foot on the ground in front of your bottom leg.\",\"Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.\",\"Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.\",\"Hold the stretch for 20-30 seconds, then slowly lower your leg back down.\",\"Repeat on the other side.\"],\"img\":\"1358.webp\",\"gif\":\"1358.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie on your side and reach overhead to open up the side of your torso. It stretches the lats and the muscles between your ribs.\"},{\"id\":\"3667\",\"n\":\"side lying hip adduction (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie on your side with your legs straight and stacked on top of each other.\",\"Place your bottom arm under your head for support.\",\"Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.\",\"Pause for a moment at the top, then slowly lower your leg back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"3667.webp\",\"gif\":\"3667.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying leg exercise that targets the inner thighs. It trains the adductors and hip stability.\",\"fv\":\"4657\"},{\"id\":\"1775\",\"n\":\"side plank hip adduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\"],\"st\":[\"Start by lying on your side with your legs extended and stacked on top of each other.\",\"Prop yourself up on your forearm, keeping your elbow directly below your shoulder.\",\"Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.\",\"While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.\",\"Slowly lower your leg back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1775.webp\",\"gif\":\"1775.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with a top leg raise. Challenges the inner and outer thighs while keeping the core braced.\"},{\"id\":\"0716\",\"n\":\"side push neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Stand or sit up straight with your shoulders relaxed.\",\"Tilt your head to the right, bringing your right ear towards your right shoulder.\",\"Place your right hand on the left side of your head and gently apply pressure to increase the stretch.\",\"Hold the stretch for 15-30 seconds.\",\"Repeat on the other side, tilting your head to the left and applying pressure with your left hand.\",\"Repeat the stretch 2-3 times on each side.\"],\"img\":\"0716.webp\",\"gif\":\"0716.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilting your head to one side, you add gentle pressure with your hand. Stretches the side of the neck.\"},{\"id\":\"0717\",\"n\":\"side push-up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\"],\"st\":[\"Start by lying on your side with your legs extended and stacked on top of each other.\",\"Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.\",\"Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.\",\"Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.\",\"Lower your body back down to the starting position with control.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0717.webp\",\"gif\":\"0717.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your side, you push your body away from the floor with one arm. Works the chest, shoulder and triceps.\"},{\"id\":\"0721\",\"n\":\"side wrist pull stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrists\",\"sm\":[\"wrists\",\"hands\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms extended in front of you.\",\"Extend your right arm out to the side, parallel to the ground, with your palm facing down.\",\"With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.\",\"Hold the stretch for 15-30 seconds, then release.\",\"Repeat on the other side.\"],\"img\":\"0721.webp\",\"gif\":\"0721.mp4\",\"cat\":\"stretching\",\"desc\":\"You pull your wrist gently with the other hand to stretch the forearm. Hold on each side.\",\"fv\":\"4308\"},{\"id\":\"0720\",\"n\":\"side-to-side chin\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body relaxed.\",\"Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.\",\"Once your chin is above the bar, lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0720.webp\",\"gif\":\"0720.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You pull yourself up to one side of the bar, then slide across to the other. Builds the lats, arms and grip.\"},{\"id\":\"3213\",\"n\":\"side-to-side toe touch (male)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms extended to the sides.\",\"Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.\",\"Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.\",\"Repeat the side-to-side bending motion for the desired number of repetitions.\"],\"img\":\"3213.webp\",\"gif\":\"3213.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing side bend where each hand slides down toward the same-side foot in turn. It mobilises the trunk and trains the obliques.\"},{\"id\":\"0725\",\"n\":\"single arm push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.\",\"Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.\",\"As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.\",\"Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.\",\"Repeat the movement, alternating the arm you extend with each repetition.\"],\"img\":\"0725.webp\",\"gif\":\"0725.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced push-up using one arm. Works the chest, shoulder, triceps and core.\"},{\"id\":\"3645\",\"n\":\"single leg bridge with outstretched leg\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Lie on your back with your knees bent and feet flat on the ground.\",\"Extend one leg straight out in front of you.\",\"Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.\",\"Hold for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"3645.webp\",\"gif\":\"3645.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single leg glute bridge with the other leg held straight out. It trains the glutes and hamstrings and tests the core.\"},{\"id\":\"0727\",\"n\":\"single leg calf raise (on a dumbbell)\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand with your feet hip-width apart and hold a dumbbell in one hand.\",\"Lift one foot off the ground and balance on the other foot.\",\"Slowly raise your heel as high as possible, using your calf muscles.\",\"Pause for a moment at the top, then slowly lower your heel back down.\",\"Repeat for the desired number of repetitions, then switch to the other leg.\"],\"img\":\"0727.webp\",\"gif\":\"0727.mp4\",\"cat\":\"strength\",\"desc\":\"Standing on one leg, you rise up onto your toes with the ball of your foot on a dumbbell. Works the calves with extra range.\"},{\"id\":\"0730\",\"n\":\"single leg platform slide\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\"],\"st\":[\"Start by standing with one foot on a platform or slide board.\",\"Bend your knee slightly and slide the foot on the platform backward, extending your leg.\",\"Keep your core engaged and maintain a straight posture throughout the movement.\",\"Slowly return to the starting position by sliding your foot back to the initial position.\",\"Repeat the movement for the desired number of repetitions, then switch legs.\"],\"img\":\"0730.webp\",\"gif\":\"0730.mp4\",\"cat\":\"strength\",\"desc\":\"Standing on one foot on a slide board, you slide your other leg back and forth. Works the legs and glutes with a balance challenge.\"},{\"id\":\"1759\",\"n\":\"single leg squat (pistol) male\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and arms extended in front of you.\",\"Lift your right foot off the ground and extend it forward.\",\"Slowly lower your body down by bending your left knee and pushing your hips back.\",\"Keep your chest up and your back straight as you lower yourself down.\",\"Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your left heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"1759.webp\",\"gif\":\"1759.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep single-leg squat with the other leg held out in front. Builds leg strength, balance and mobility.\",\"fv\":\"0732\"},{\"id\":\"1489\",\"n\":\"sissy squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart and your toes pointing slightly outward.\",\"Hold onto a stable object for balance if needed.\",\"Slowly lower your body by bending your knees and leaning back, keeping your torso upright.\",\"Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1489.webp\",\"gif\":\"1489.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat where your knees travel far forward as you lean back. It isolates the quads with only your body weight.\"},{\"id\":\"0735\",\"n\":\"sit-up v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0735.webp\",\"gif\":\"0735.mp4\",\"cat\":\"strength\",\"desc\":\"You lie on your back and curl your torso up toward your knees. Works the abs and hip flexors.\"},{\"id\":\"3679\",\"n\":\"sit-up with arms on chest\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Cross your arms over your chest.\",\"Engaging your abs, lift your upper body off the ground towards your knees.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3679.webp\",\"gif\":\"3679.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with the arms crossed on the chest. It trains the abs and hip flexors.\"},{\"id\":\"3361\",\"n\":\"skater hops\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees slightly and jump to the right, landing on your right foot.\",\"As you land, swing your left leg behind your right leg and tap the ground with your left toes.\",\"Immediately jump to the left, landing on your left foot.\",\"As you land, swing your right leg behind your left leg and tap the ground with your right toes.\",\"Continue alternating sides, jumping and tapping the ground with each leg.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3361.webp\",\"gif\":\"3361.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side-to-side hop that mimics a speed skater, landing on one foot at a time. It builds leg power and balance.\"},{\"id\":\"2142\",\"n\":\"ski ergometer\",\"bp\":\"upper arms\",\"eq\":\"skierg machine\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Adjust the seat height and footrests to a comfortable position.\",\"Grasp the handles with an overhand grip, palms facing down.\",\"Sit up straight with your feet flat on the footrests.\",\"Extend your arms straight out in front of you, keeping your elbows slightly bent.\",\"Engage your triceps and push the handles down towards your thighs.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2142.webp\",\"gif\":\"2142.mp4\",\"cat\":\"cardio\",\"desc\":\"Pulling the handles of a ski ergometer down in a rhythmic stroke. Works the arms, back and core while raising your heart rate.\"},{\"id\":\"3671\",\"n\":\"ski step\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Bend your knees slightly and keep your back straight.\",\"Jump to the right, landing on your right foot while swinging your left leg behind your right leg.\",\"Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.\",\"Continue alternating jumps from side to side, mimicking a skiing motion.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3671.webp\",\"gif\":\"3671.mp4\",\"cat\":\"cardio\",\"desc\":\"A side-to-side hopping drill that imitates a skier. It raises the heart rate and builds leg stamina.\"},{\"id\":\"3304\",\"n\":\"skin the cat\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Start by hanging from a bar with your arms fully extended and your body relaxed.\",\"Engage your core and lift your legs up, bringing your knees towards your chest.\",\"Continue to lift your legs up and over your head, allowing your body to pass through the arms.\",\"Once your legs are fully extended over your head, begin to lower them back down towards the starting position.\",\"As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3304.webp\",\"gif\":\"3304.mp4\",\"cat\":\"mobility\",\"desc\":\"A ring or bar move where you tuck up, pass the legs through the arms and then roll over the bar. It trains the back and shoulder mobility.\"},{\"id\":\"1425\",\"n\":\"sled 45 degrees one leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the sled machine to a 45-degree angle.\",\"Sit on the sled machine with your back against the pad and your feet on the footplate.\",\"Place one foot on the footplate and extend your leg, pushing the sled away from you.\",\"Slowly bend your knee and lower the sled back to the starting position.\",\"Repeat with the other leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"1425.webp\",\"gif\":\"1425.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg press on a sled machine set at a 45 degree angle. It trains the glutes, quads and hamstrings one side at a time.\",\"fv\":\"2609\"},{\"id\":\"0738\",\"n\":\"sled 45° calf press\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Adjust the sled machine to a 45-degree angle.\",\"Place your feet on the sled platform with your toes pointing forward.\",\"Push the sled platform away from you by extending your ankles and calves.\",\"Pause for a moment at the top, then slowly lower the sled platform back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0738.webp\",\"gif\":\"0738.mp4\",\"cat\":\"strength\",\"desc\":\"On a 45 degree sled, you press the platform with your toes. Isolates the calves.\"},{\"id\":\"0739\",\"n\":\"sled 45° leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat and footplate of the sled machine to a comfortable position.\",\"Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.\",\"Grip the handles on the sides of the seat for stability.\",\"Push the footplate away from your body by extending your legs, keeping your heels on the footplate.\",\"Continue pushing until your legs are almost fully extended, but without locking your knees.\",\"Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0739.webp\",\"gif\":\"0739.mp4\",\"cat\":\"strength\",\"desc\":\"On a 45 degree sled, you press the platform away with your feet. Works the quads and glutes.\"},{\"id\":\"1464\",\"n\":\"sled 45° leg press (back pov)\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat of the sled machine so that your knees are at a 45-degree angle.\",\"Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.\",\"Grip the handles on the sides of the seat for stability.\",\"Push the footplate away from your body by extending your legs, keeping your heels on the footplate.\",\"Pause for a moment at the fully extended position.\",\"Slowly bend your knees and lower the footplate back towards your body, controlling the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1464.webp\",\"gif\":\"1464.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press on a 45 degree sled, shown from behind. It loads the quads and glutes with your back supported.\"},{\"id\":\"1463\",\"n\":\"sled 45° leg press (side pov)\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.\",\"Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.\",\"Grip the handles on the sides of the seat for stability.\",\"Push against the footplate to extend your legs, straightening them completely.\",\"Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1463.webp\",\"gif\":\"1463.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press on a 45 degree sled, shown from the side. It loads the quads and glutes with your back supported.\"},{\"id\":\"0740\",\"n\":\"sled 45° leg wide press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the sled machine to a 45-degree angle.\",\"Sit on the sled machine with your back against the pad and your feet on the foot platform.\",\"Position your feet wider than shoulder-width apart.\",\"Push against the foot platform to extend your legs and straighten your knees.\",\"Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0740.webp\",\"gif\":\"0740.mp4\",\"cat\":\"strength\",\"desc\":\"On a 45 degree sled, you press with a wide stance. Works the inner thighs, glutes and quads.\"},{\"id\":\"1391\",\"n\":\"sled calf press on leg press\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.\",\"Place your feet shoulder-width apart on the sled, with your toes pointing forward.\",\"Release the safety handles and push the sled away from you by extending your knees and ankles.\",\"Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1391.webp\",\"gif\":\"1391.mp4\",\"cat\":\"strength\",\"desc\":\"A calf press done on a leg press sled using only your toes. It builds the calves under a supported load.\",\"fv\":\"2212\"},{\"id\":\"0741\",\"n\":\"sled closer hack squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.\",\"Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.\",\"Grip the handles on the sides of the machine for stability.\",\"Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.\",\"Continue lowering until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0741.webp\",\"gif\":\"0741.mp4\",\"cat\":\"strength\",\"desc\":\"On a sled hack squat machine, you squat with your feet close together. Puts more focus on the quads.\"},{\"id\":\"0742\",\"n\":\"sled forward angled calf raise\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.\",\"Place your hands on the handles or the sides of the machine for support.\",\"Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.\",\"Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0742.webp\",\"gif\":\"0742.mp4\",\"cat\":\"strength\",\"desc\":\"On a sled, you raise your heels with the machine angled forward. Works the calves.\"},{\"id\":\"0743\",\"n\":\"sled hack squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the sled machine to a comfortable position for your height.\",\"Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.\",\"Hold onto the handles or bars for stability.\",\"Lower your body by bending your knees and hips, keeping your back straight and chest up.\",\"Continue lowering until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment, then push through your heels to raise your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0743.webp\",\"gif\":\"0743.mp4\",\"cat\":\"strength\",\"desc\":\"On a sled machine, you squat with your back against the pad. Works the quads and glutes.\",\"fv\":\"2384\"},{\"id\":\"2334\",\"n\":\"sled lying calf press\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the sled machine to a comfortable weight.\",\"Sit on the sled machine with your back against the pad and your feet on the platform.\",\"Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.\",\"Push the platform away from you by extending your ankles, keeping your knees slightly bent.\",\"Continue pushing until your calves are fully contracted.\",\"Hold the contraction for a moment, then slowly lower the platform back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2334.webp\",\"gif\":\"2334.mp4\",\"cat\":\"strength\",\"desc\":\"A calf press on a sled machine while lying back. Builds the calf muscles.\"},{\"id\":\"0744\",\"n\":\"sled lying squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the sled machine to a comfortable weight.\",\"Lie on your back on the sled machine with your feet on the footplate.\",\"Position your feet shoulder-width apart and slightly angled outwards.\",\"Grip the handles of the sled machine for stability.\",\"Engage your glutes and core muscles.\",\"Push through your heels and extend your legs to lift the sled.\",\"Lower the sled back down by bending your knees and hips.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0744.webp\",\"gif\":\"0744.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a sled, you bend your knees and press the platform away. Works the quads and glutes.\"},{\"id\":\"1392\",\"n\":\"sled one leg calf press on leg press\",\"bp\":\"lower legs\",\"eq\":\"sled machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.\",\"Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.\",\"Place your toes and the balls of your feet on the sled, keeping your heels off.\",\"Push the sled forward by extending your ankles, keeping your knees slightly bent.\",\"Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1392.webp\",\"gif\":\"1392.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf press on a leg press sled using only your toes. It trains each calf separately under a supported load.\"},{\"id\":\"1496\",\"n\":\"sledge hammer\",\"bp\":\"waist\",\"eq\":\"hammer\",\"tg\":\"abs\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.\",\"Engage your core and keep your back straight.\",\"Swing the sledge hammer down towards the ground, using your core and upper body strength.\",\"As you swing down, pivot your hips and transfer the force to the hammer.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1496.webp\",\"gif\":\"1496.mp4\",\"cat\":\"strength\",\"desc\":\"Swinging a sledgehammer down onto a tire in a controlled arc. It trains the abs and obliques and also the shoulders and grip.\"},{\"id\":\"0746\",\"n\":\"smith back shrug\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your arms straight and allow the barbell to hang in front of your thighs.\",\"Lift your shoulders straight up towards your ears, squeezing your traps at the top.\",\"Hold for a moment, then lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0746.webp\",\"gif\":\"0746.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you lift your shoulders straight up with the bar. Builds the upper traps.\"},{\"id\":\"0747\",\"n\":\"smith behind neck press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Adjust the seat height of the smith machine so that the bar is at shoulder level.\",\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the bar off the rack and step back, maintaining a stable stance.\",\"Lower the bar down to the back of your neck, keeping your elbows pointing forward.\",\"Press the bar up overhead until your arms are fully extended.\",\"Pause for a moment at the top, then slowly lower the bar back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0747.webp\",\"gif\":\"0747.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you press the bar overhead from behind your neck. Works the shoulders and triceps, so keep it controlled.\",\"fv\":\"11280\"},{\"id\":\"0748\",\"n\":\"smith bench press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the height of the smith machine bar to chest level.\",\"Lie flat on the bench with your feet firmly planted on the ground.\",\"Grip the bar with an overhand grip slightly wider than shoulder-width apart.\",\"Unrack the bar and lower it towards your chest, keeping your elbows tucked in.\",\"Pause for a moment when the bar touches your chest.\",\"Push the bar back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0748.webp\",\"gif\":\"0748.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you press a smith machine bar up from your chest. Works the chest, shoulders and triceps.\",\"fv\":\"7002\"},{\"id\":\"0749\",\"n\":\"smith bent knee good morning\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Start by standing with your feet shoulder-width apart, toes pointing forward.\",\"Place the barbell across your upper back, resting it on your traps.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.\",\"Engage your glutes and hamstrings to raise your torso back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0749.webp\",\"gif\":\"0749.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you bend your knees slightly and hinge forward with the bar on your upper back. Works the hamstrings, glutes and lower back.\"},{\"id\":\"1359\",\"n\":\"smith bent over row\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up the smith machine with the bar at hip height.\",\"Stand facing the bar with your feet shoulder-width apart.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Pull the bar towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the bar back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1359.webp\",\"gif\":\"1359.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over row using a smith machine bar with an overhand grip. The fixed path helps you focus on the upper back and lats.\"},{\"id\":\"0750\",\"n\":\"smith chair squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the height of the smith machine bar to a comfortable position.\",\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Place the barbell across your upper back, resting it on your traps.\",\"Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.\",\"Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0750.webp\",\"gif\":\"0750.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you squat down until you touch a chair. Works the quads and glutes with a clear depth marker.\",\"fv\":\"2617\"},{\"id\":\"0751\",\"n\":\"smith close-grip bench press\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Adjust the seat height and position yourself on the bench with your feet flat on the ground.\",\"Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.\",\"Lower the barbell towards your chest, keeping your elbows close to your body.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0751.webp\",\"gif\":\"0751.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you bench press with a close grip. Puts more focus on the triceps and inner chest.\"},{\"id\":\"0752\",\"n\":\"smith deadlift\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\"],\"st\":[\"Set up the smith machine with the bar at hip height.\",\"Stand with your feet shoulder-width apart, toes pointing slightly outward.\",\"Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.\",\"Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.\",\"Stand up straight, fully extending your hips and knees.\",\"Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0752.webp\",\"gif\":\"0752.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you lift the bar from hip height or lower with a hip hinge. Works the glutes, hamstrings and lower back.\",\"fv\":\"3618\"},{\"id\":\"0753\",\"n\":\"smith decline bench press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the decline bench to the desired angle.\",\"Lie down on the bench with your feet secured under the foot pads.\",\"Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0753.webp\",\"gif\":\"0753.mp4\",\"cat\":\"strength\",\"desc\":\"On a decline bench, you press a smith machine bar from your lower chest. Works the lower chest and triceps.\"},{\"id\":\"0754\",\"n\":\"smith decline reverse-grip press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the smith machine to a decline position.\",\"Lie down on the bench with your feet secured under the foot pads.\",\"Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0754.webp\",\"gif\":\"0754.mp4\",\"cat\":\"strength\",\"desc\":\"On a decline bench, you press the smith machine bar with a reverse grip. Works the chest and triceps.\"},{\"id\":\"1433\",\"n\":\"smith front squat (clean grip)\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Set up the smith machine with the barbell at shoulder height.\",\"Stand facing the barbell with your feet shoulder-width apart.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.\",\"Keep your chest up, back straight, and core engaged.\",\"Lower your body by bending at the knees and hips, as if sitting back into a chair.\",\"Continue lowering until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1433.webp\",\"gif\":\"1433.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat on a smith machine with a clean grip. The bar path is guided so you can focus on the quads and glutes.\",\"fv\":\"2824\"},{\"id\":\"3281\",\"n\":\"smith full squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Set up the smith machine with the barbell at shoulder height.\",\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Step under the bar and position it across your upper back, resting on your traps.\",\"Grip the bar with your hands slightly wider than shoulder-width apart.\",\"Unrack the bar and take a step back, maintaining a stable stance.\",\"Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.\",\"Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.\",\"Pause for a moment at the bottom, then drive through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3281.webp\",\"gif\":\"3281.mp4\",\"cat\":\"strength\",\"desc\":\"A full-depth back squat on the smith machine, where the fixed bar path gives extra stability. It trains the glutes, quads and thighs.\",\"fv\":\"11305\"},{\"id\":\"0755\",\"n\":\"smith hack squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the barbell on the smith machine to an appropriate height for your body.\",\"Stand with your feet shoulder-width apart, toes slightly pointed outwards.\",\"Position yourself under the barbell, resting it on your upper traps and shoulders.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Engage your core and keep your chest up as you unrack the barbell.\",\"Take a step back and position your feet slightly wider than shoulder-width apart.\",\"Bend your knees and lower your body down, keeping your chest up and back straight.\",\"Continue descending until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0755.webp\",\"gif\":\"0755.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you squat with your feet forward of the bar. Works the quads and glutes.\"},{\"id\":\"0756\",\"n\":\"smith hip raise\",\"bp\":\"waist\",\"eq\":\"smith machine\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.\",\"Place your hands on the barbell, slightly wider than shoulder-width apart.\",\"Engage your core and glutes, then push through your heels to raise your hips off the ground.\",\"Continue lifting until your body forms a straight line from your knees to your shoulders.\",\"Hold for a moment at the top, then slowly lower your hips back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0756.webp\",\"gif\":\"0756.mp4\",\"cat\":\"strength\",\"desc\":\"On the smith machine, you press your hips up with the bar across them. Works the glutes and hamstrings.\"},{\"id\":\"0757\",\"n\":\"smith incline bench press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Adjust the bench to a 30-45 degree incline.\",\"Sit on the bench with your back flat against the pad and feet firmly on the ground.\",\"Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0757.webp\",\"gif\":\"0757.mp4\",\"cat\":\"strength\",\"desc\":\"On an incline bench, you press the smith machine bar up. Works the upper chest, shoulders and triceps.\",\"fv\":\"7003\"},{\"id\":\"0758\",\"n\":\"smith incline reverse-grip press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat of the smith machine to a comfortable incline angle.\",\"Sit on the machine with your back against the pad and your feet flat on the ground.\",\"Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.\",\"Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment when the bar is just above your chest.\",\"Push the bar back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0758.webp\",\"gif\":\"0758.mp4\",\"cat\":\"strength\",\"desc\":\"On an incline bench, you press the smith machine bar with a reverse grip. Works the upper chest and triceps.\"},{\"id\":\"0759\",\"n\":\"smith incline shoulder raises\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"serratus anterior\",\"mg\":\"deltoids\",\"sm\":[\"deltoids\",\"trapezius\"],\"st\":[\"Adjust the smith machine to an incline position.\",\"Stand facing the machine with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and core engaged.\",\"Raise the barbell up towards the ceiling, leading with your elbows.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0759.webp\",\"gif\":\"0759.mp4\",\"cat\":\"strength\",\"desc\":\"On an incline setup, you raise the smith machine bar in front of you. Works the front shoulders.\"},{\"id\":\"0760\",\"n\":\"smith leg press\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat and footplate of the smith machine to a comfortable position.\",\"Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.\",\"Grasp the handles or sides of the machine for stability.\",\"Push the footplate away from you by extending your legs, keeping your back against the backrest.\",\"Pause for a moment at the fully extended position.\",\"Slowly bend your knees and lower the footplate back towards you, returning to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0760.webp\",\"gif\":\"0760.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press done on a smith machine setup, pushing the footplate away with both legs. It builds the thighs and glutes with a guided path.\",\"fv\":\"3619\"},{\"id\":\"1434\",\"n\":\"smith low bar squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.\",\"Stand with your feet shoulder-width apart, toes slightly turned outwards.\",\"Step under the bar and position it across your upper back, resting it on your traps.\",\"Grip the bar with your hands slightly wider than shoulder-width apart.\",\"Unrack the bar by straightening your legs and stepping back from the rack.\",\"Take a deep breath and brace your core.\",\"Initiate the squat by pushing your hips back and bending your knees.\",\"Lower your body until your thighs are parallel to the ground or slightly below.\",\"Keep your chest up and your back straight throughout the movement.\",\"Drive through your heels to stand back up, extending your hips and knees.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1434.webp\",\"gif\":\"1434.mp4\",\"cat\":\"strength\",\"desc\":\"A low bar squat on the smith machine, with the bar sitting lower on the back. It builds the glutes, quads and hamstrings along a fixed bar path.\"},{\"id\":\"1683\",\"n\":\"smith machine bicep curl\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Adjust the height of the smith machine bar to be at waist level.\",\"Stand facing the smith machine with your feet shoulder-width apart.\",\"Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your elbows close to your sides and your upper arms stationary.\",\"Exhale and curl the bar up towards your shoulders, contracting your biceps.\",\"Pause for a moment at the top of the movement, squeezing your biceps.\",\"Inhale and slowly lower the bar back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1683.webp\",\"gif\":\"1683.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl in the smith machine. The fixed bar path makes it easy to focus on the biceps.\"},{\"id\":\"1625\",\"n\":\"smith machine decline close grip bench press\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Adjust the bench on the smith machine to a decline position.\",\"Lie down on the bench with your feet firmly planted on the ground.\",\"Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.\",\"Pause for a moment when the barbell is just above your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1625.webp\",\"gif\":\"1625.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip bench press on a decline bench in the smith machine. It builds the triceps and lower chest.\"},{\"id\":\"1752\",\"n\":\"smith machine incline tricep extension\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Adjust the seat of the smith machine so that the bar is at shoulder height.\",\"Sit on the bench with your back against the pad and your feet flat on the ground.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.\",\"Lower the bar slowly towards your forehead, keeping your elbows close to your head.\",\"Pause for a moment at the bottom, then push the bar back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1752.webp\",\"gif\":\"1752.mp4\",\"cat\":\"strength\",\"desc\":\"An incline smith machine extension that lowers the bar toward your forehead. Guided path lets you focus on the triceps.\"},{\"id\":\"1626\",\"n\":\"smith machine reverse decline close grip bench press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the smith machine to a decline position.\",\"Lie down on the bench with your feet secured under the foot pads.\",\"Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the barbell back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1626.webp\",\"gif\":\"1626.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse grip, close grip decline bench press in the smith machine. It works the chest and triceps.\"},{\"id\":\"0761\",\"n\":\"smith narrow row\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rear deltoids\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your feet flat on the floor.\",\"Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.\",\"Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.\",\"Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0761.webp\",\"gif\":\"0761.mp4\",\"cat\":\"strength\",\"desc\":\"A row with a narrow grip on the smith machine, pulling toward the torso. It works the mid back and the muscles between the shoulder blades.\"},{\"id\":\"1360\",\"n\":\"smith one arm row\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Adjust the height of the smith machine bar to waist level.\",\"Stand facing the smith machine with your feet shoulder-width apart.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Grasp the bar with one hand using an overhand grip, with your palm facing down.\",\"Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.\",\"Repeat for the desired number of repetitions, then switch to the other arm.\"],\"img\":\"1360.webp\",\"gif\":\"1360.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row using a smith machine bar. It trains the upper back and lats one side at a time along a guided path.\"},{\"id\":\"1393\",\"n\":\"smith one leg floor calf raise\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Position yourself on the floor under the smith machine bar, facing away from the machine.\",\"Place the balls of your feet on a raised surface, such as a weight plate or block.\",\"Position the smith machine bar across your lower legs, just above your ankles.\",\"Hold onto the bar with your hands for stability.\",\"Raise your heels off the ground by extending your ankles, lifting your body up.\",\"Pause at the top of the movement, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1393.webp\",\"gif\":\"1393.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf raise lifting a smith machine bar from the floor. It works each calf on its own under a guided bar path.\",\"fv\":\"2672\"},{\"id\":\"0762\",\"n\":\"smith rear delt row\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"biceps\"],\"st\":[\"Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.\",\"Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.\",\"Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0762.webp\",\"gif\":\"0762.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip row that pulls toward the upper chest to hit the back of the shoulders. It trains the rear delts and upper back.\"},{\"id\":\"0763\",\"n\":\"smith reverse calf raises\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Adjust the smith machine bar to a height just below your shoulders.\",\"Stand facing the bar with your feet hip-width apart and toes pointing forward.\",\"Place the balls of your feet on the edge of a step or platform, with your heels hanging off.\",\"Hold onto the bar for support, keeping your back straight and core engaged.\",\"Raise your heels as high as possible, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0763.webp\",\"gif\":\"0763.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise done with the smith bar for support and the toes on a raised edge. It trains the calves through a full range of motion.\",\"fv\":\"2667\"},{\"id\":\"1394\",\"n\":\"smith reverse calf raises\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Adjust the smith machine bar to a height just below your shoulders.\",\"Stand facing the bar with your feet hip-width apart and toes pointing forward.\",\"Place the balls of your feet on the edge of a step or platform, with your heels hanging off.\",\"Hold onto the bar for support.\",\"Raise your heels as high as possible, lifting your body up onto your toes.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1394.webp\",\"gif\":\"1394.mp4\",\"cat\":\"strength\",\"desc\":\"A smith machine calf raise done with the bar in front of you. It targets the calves and the muscles around the shin.\"},{\"id\":\"1361\",\"n\":\"smith reverse grip bent over row\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Set up the smith machine with the bar at hip height.\",\"Stand facing the bar with your feet shoulder-width apart.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Grasp the bar with an underhand grip, hands shoulder-width apart.\",\"Pull the bar towards your lower chest, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower the bar back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1361.webp\",\"gif\":\"1361.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over row on a smith machine with an underhand grip. It works the upper back, lats and biceps along a guided path.\"},{\"id\":\"0764\",\"n\":\"smith reverse-grip press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the height of the smith machine bar to chest level.\",\"Stand facing the bar with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Step back and position yourself with a slight bend in your knees.\",\"Keep your chest up and core engaged throughout the exercise.\",\"Lower the bar towards your chest, keeping your elbows tucked in.\",\"Pause for a moment at the bottom, then push the bar back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0764.webp\",\"gif\":\"0764.mp4\",\"cat\":\"strength\",\"desc\":\"A press with an underhand grip on the smith bar, lowering to the chest and pressing back up. It trains the upper chest, shoulders and triceps.\"},{\"id\":\"1395\",\"n\":\"smith seated one leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\"],\"st\":[\"Sit on the machine with your back against the pad and your feet on the footrest.\",\"Place one leg on the footrest and keep the other leg off the footrest.\",\"Using your calf muscles, raise your heel as high as possible.\",\"Pause for a moment at the top, then slowly lower your heel back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"1395.webp\",\"gif\":\"1395.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-leg calf raise using a smith machine. The bent knee puts the focus on the soleus under the calf.\"},{\"id\":\"0765\",\"n\":\"smith seated shoulder press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Adjust the seat height so that the handles are at shoulder level.\",\"Sit on the machine with your back against the pad and your feet flat on the floor.\",\"Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.\",\"Lower the handles down to shoulder level, keeping your elbows slightly bent.\",\"Press the handles up overhead until your arms are fully extended.\",\"Pause for a moment at the top, then slowly lower the handles back down to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0765.webp\",\"gif\":\"0765.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press on the smith machine, with the back supported. It builds the shoulders and triceps along a fixed path.\",\"fv\":\"3620\"},{\"id\":\"1426\",\"n\":\"smith seated wrist curl\",\"bp\":\"lower arms\",\"eq\":\"smith machine\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\"],\"st\":[\"Sit on a bench in front of a Smith machine with your feet flat on the ground.\",\"Grasp the barbell with an underhand grip, hands shoulder-width apart.\",\"Rest your forearms on your thighs, allowing your wrists to hang off.\",\"Slowly curl your wrists upward, bringing the barbell towards your forearms.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1426.webp\",\"gif\":\"1426.mp4\",\"cat\":\"strength\",\"desc\":\"Sit in front of a smith machine and curl the bar with your wrists. It strengthens the forearms and builds grip.\"},{\"id\":\"0766\",\"n\":\"smith shoulder press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.\",\"Press the bar upward until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the bar back down to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0766.webp\",\"gif\":\"0766.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press using the smith bar, pressed from shoulder height to full extension. It builds strong shoulders and triceps.\"},{\"id\":\"0767\",\"n\":\"smith shrug\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your arms straight and your shoulders relaxed.\",\"Lift your shoulders up towards your ears, squeezing your traps at the top.\",\"Hold for a moment, then slowly lower your shoulders back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0767.webp\",\"gif\":\"0767.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug with the smith bar, lifting the shoulders straight up toward the ears. It builds the upper traps.\",\"fv\":\"11306\"},{\"id\":\"0768\",\"n\":\"smith single leg split squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Stand in front of the smith machine with your feet shoulder-width apart.\",\"Place one foot behind you on a bench or step, with your toes pointing forward.\",\"Hold onto the smith machine bar for stability.\",\"Bend your front knee and lower your body down into a lunge position, keeping your back straight.\",\"Pause for a moment at the bottom, then push through your front heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0768.webp\",\"gif\":\"0768.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg split squat using the smith bar for balance, with the back foot raised. It trains the quads and glutes one side at a time.\",\"fv\":\"2670\"},{\"id\":\"0769\",\"n\":\"smith sprint lunge\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Set up the smith machine with the barbell at hip height.\",\"Stand facing away from the machine with your feet shoulder-width apart.\",\"Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.\",\"Bend your left knee and lower your body into a lunge position, keeping your back straight.\",\"Push through your left heel to return to the starting position.\",\"Repeat on the other side, stepping back with your left foot.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0769.webp\",\"gif\":\"0769.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge variation on the smith machine, stepping back and lowering into a lunge. It works the glutes and thighs and challenges balance.\",\"fv\":\"3111\"},{\"id\":\"0770\",\"n\":\"smith squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Set up the smith machine with the barbell at an appropriate height for your squat.\",\"Stand with your feet shoulder-width apart, toes slightly turned out.\",\"Position yourself under the barbell, resting it on your upper traps and shoulders.\",\"Grip the barbell with a wide grip, slightly wider than shoulder-width apart.\",\"Engage your core and unrack the barbell, stepping back to clear the rack.\",\"Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.\",\"Lower your body until your thighs are parallel to the ground or slightly below.\",\"Pause for a moment at the bottom, then drive through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0770.webp\",\"gif\":\"0770.mp4\",\"cat\":\"strength\",\"desc\":\"A back squat with the bar guided by the smith machine. It builds the thighs and glutes with extra stability.\"},{\"id\":\"0771\",\"n\":\"smith standing back wrist curl\",\"bp\":\"lower arms\",\"eq\":\"smith machine\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Stand facing the smith machine with your feet shoulder-width apart.\",\"Grasp the barbell with an overhand grip, hands shoulder-width apart.\",\"Keep your back straight and your elbows close to your body.\",\"Slowly curl your wrists upwards, bringing the barbell towards your body.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0771.webp\",\"gif\":\"0771.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with the smith bar held behind the body. It strengthens the forearms and grip.\"},{\"id\":\"0772\",\"n\":\"smith standing behind head military press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Adjust the seat height of the smith machine so that the bar is at shoulder level.\",\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the bar off the rack and step back, maintaining a stable stance.\",\"Position the bar behind your head, resting on your upper traps.\",\"Keep your core engaged and your chest lifted throughout the exercise.\",\"Press the bar overhead by extending your arms, fully straightening them.\",\"Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0772.webp\",\"gif\":\"0772.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press with the smith bar lowered behind the head. It builds the shoulders and triceps and needs good shoulder mobility.\"},{\"id\":\"0773\",\"n\":\"smith standing leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.\",\"Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.\",\"Place your hands on the bar for stability.\",\"Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0773.webp\",\"gif\":\"0773.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise with the smith bar resting across the shoulders. It loads the calves for strength and size.\",\"fv\":\"2655\"},{\"id\":\"0774\",\"n\":\"smith standing military press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.\",\"Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.\",\"Press the barbell upward until your arms are fully extended overhead.\",\"Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0774.webp\",\"gif\":\"0774.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press with the smith bar, starting at shoulder height. It builds the shoulders and triceps.\"},{\"id\":\"3142\",\"n\":\"smith sumo squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Set up the smith machine with the barbell at hip height.\",\"Stand with your feet wider than shoulder-width apart, toes pointing outwards.\",\"Position yourself under the barbell, resting it on your upper back and shoulders.\",\"Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.\",\"Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3142.webp\",\"gif\":\"3142.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo squat on a smith machine. Targets the glutes, inner thighs and quads.\",\"fv\":\"4005\"},{\"id\":\"1396\",\"n\":\"smith toe raise\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\"],\"st\":[\"Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.\",\"Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.\",\"Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.\",\"Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Engage your core and keep your back straight throughout the exercise.\",\"Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1396.webp\",\"gif\":\"1396.mp4\",\"cat\":\"strength\",\"desc\":\"A smith machine toe raise where you rise onto the balls of your feet. It builds the calves and ankle strength.\",\"fv\":\"3112\"},{\"id\":\"0775\",\"n\":\"smith upright row\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"traps\",\"sm\":[\"traps\",\"biceps\"],\"st\":[\"Stand with your feet shoulder-width apart, facing the smith machine.\",\"Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\",\"Keep your back straight and your core engaged.\",\"Pull the barbell up towards your chin, leading with your elbows.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0775.webp\",\"gif\":\"0775.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row with the smith bar, pulling the bar up toward the chin with the elbows leading. It trains the side delts and traps.\"},{\"id\":\"1308\",\"n\":\"smith wide grip bench press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the bench to a comfortable position on the smith machine.\",\"Lie down on the bench with your feet flat on the ground.\",\"Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1308.webp\",\"gif\":\"1308.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press on a smith machine with a wide grip. The fixed bar path lets you focus on pressing, with extra work for the outer chest.\"},{\"id\":\"1309\",\"n\":\"smith wide grip decline bench press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the decline bench to the desired angle.\",\"Lie down on the bench with your feet secured under the foot pads.\",\"Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.\",\"Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.\",\"Pause for a moment when the barbell touches your chest.\",\"Push the barbell back up to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1309.webp\",\"gif\":\"1309.mp4\",\"cat\":\"strength\",\"desc\":\"A smith machine bench press on a decline bench with a wide grip. It targets the lower chest along a guided bar path.\"},{\"id\":\"0776\",\"n\":\"snatch pull\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and the barbell on the ground in front of you.\",\"Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.\",\"Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.\",\"As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.\",\"As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.\",\"Catch the barbell overhead with your arms fully extended and your knees bent.\",\"Stand up by extending your hips and knees, keeping the barbell overhead.\",\"Lower the barbell back down to the starting position by reversing the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0776.webp\",\"gif\":\"0776.mp4\",\"cat\":\"olympic\",\"desc\":\"An Olympic lifting pull that drives the barbell from the floor to chest height with a powerful extension and shrug. It builds explosive power in the hips, legs and back.\"},{\"id\":\"0777\",\"n\":\"spell caster\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in one hand.\",\"Bend your knees slightly and hinge forward at the waist, keeping your back straight.\",\"Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.\",\"Return to the starting position and repeat on the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0777.webp\",\"gif\":\"0777.mp4\",\"cat\":\"strength\",\"desc\":\"A rotational move with a dumbbell, sweeping the weight across the body from low to high. It trains the abs and obliques and builds control.\",\"fv\":\"3846\"},{\"id\":\"1362\",\"n\":\"sphinx\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.\",\"Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.\",\"Hold this position for a few seconds, making sure to keep your neck in a neutral position.\",\"Slowly lower your chest back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1362.webp\",\"gif\":\"1362.mp4\",\"cat\":\"yoga\",\"desc\":\"Lie face down and prop yourself up on your forearms with your chest lifted. It gently extends the spine and opens the chest.\"},{\"id\":\"0778\",\"n\":\"spider crawl push up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"chest\",\"shoulders\"],\"st\":[\"Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Bring your right knee towards your right elbow, keeping it off the ground.\",\"As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.\",\"Push back up to the starting position and repeat with your left knee towards your left elbow.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0778.webp\",\"gif\":\"0778.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up combined with a knee drive toward the elbow, like a crawling spider. It trains the chest, core and hips together.\",\"fv\":\"3437\"},{\"id\":\"1363\",\"n\":\"spine stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Place your hands on the ground behind you, fingers pointing towards your body.\",\"Engage your core and slowly lean back, keeping your back straight.\",\"Continue leaning back until you feel a stretch in your spine.\",\"Hold the stretch for a few seconds, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1363.webp\",\"gif\":\"1363.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit with your legs out in front of you and lean back on your hands. It gives the spine and front of the torso a gentle stretch.\",\"fv\":\"4313\"},{\"id\":\"2329\",\"n\":\"spine twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the ground with your legs extended in front of you.\",\"Bend your knees and place your feet flat on the ground, hip-width apart.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.\",\"Pause for a moment at the end of the twist, then slowly return to the starting position.\",\"Repeat the twist to the left side, bringing your left elbow towards your right knee.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"2329.webp\",\"gif\":\"2329.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated torso rotation, twisting side to side. Loosens the spine and works the obliques.\"},{\"id\":\"2368\",\"n\":\"split squats\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Take a step forward with one foot and place it about two feet in front of the other foot.\",\"Lower your body by bending your knees and hips, keeping your back straight.\",\"Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.\",\"Pause for a moment, then push through your front heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs and repeat.\"],\"img\":\"2368.webp\",\"gif\":\"2368.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight split squat with a long stance. Builds the quads and glutes one leg at a time.\"},{\"id\":\"0786\",\"n\":\"squat jerk\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Start with the barbell resting on your shoulders, with your feet shoulder-width apart.\",\"Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.\",\"As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.\",\"As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.\",\"Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.\",\"Stand up from the split position, bringing your feet back together.\",\"Lower the barbell back to your shoulders and repeat for the desired number of repetitions.\"],\"img\":\"0786.webp\",\"gif\":\"0786.mp4\",\"cat\":\"olympic\",\"desc\":\"An Olympic lift where you dip, drive the bar overhead and catch it in a split stance. It builds explosive power and overhead stability.\"},{\"id\":\"1705\",\"n\":\"squat on bosu ball\",\"bp\":\"upper legs\",\"eq\":\"bosu ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Place the bosu ball on the ground with the flat side up.\",\"Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.\",\"Lower your body down by bending your knees and hips, as if sitting back into a chair.\",\"Keep your chest up and your weight on your heels.\",\"Lower yourself until your thighs are parallel to the ground.\",\"Pause for a moment, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1705.webp\",\"gif\":\"1705.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat on a bosu ball. It trains the quads and glutes and tests balance.\",\"fv\":\"8373\"},{\"id\":\"1685\",\"n\":\"squat to overhead reach\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and toes slightly turned out.\",\"Lower your body down into a squat position by bending your knees and pushing your hips back.\",\"As you come up from the squat, extend your arms overhead, reaching towards the ceiling.\",\"Return to the starting position by lowering your arms and bending your knees to squat down again.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1685.webp\",\"gif\":\"1685.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat followed by reaching your arms overhead. It trains the quads and glutes and opens up the shoulders.\"},{\"id\":\"1686\",\"n\":\"squat to overhead reach with twist\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and toes slightly turned out.\",\"Lower your body into a squat position by bending your knees and pushing your hips back.\",\"As you come up from the squat, raise your arms overhead and twist your torso to one side.\",\"Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.\",\"Continue alternating sides with each squat repetition.\"],\"img\":\"1686.webp\",\"gif\":\"1686.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat with an overhead reach and a twist. It trains the legs and mobilizes the torso.\"},{\"id\":\"2297\",\"n\":\"stability ball crunch (full range hands behind head)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.\",\"Pause for a moment at the top, then slowly lower your upper body back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2297.webp\",\"gif\":\"2297.mp4\",\"cat\":\"strength\",\"desc\":\"A full-range crunch on a stability ball with hands behind your head. Works the abs through a longer range.\"},{\"id\":\"3291\",\"n\":\"stalder press\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Start by standing with your feet shoulder-width apart and your arms extended overhead.\",\"Bend your knees slightly and engage your core.\",\"Lower your body down into a squat position while keeping your arms extended overhead.\",\"As you squat down, press your arms down towards the ground, engaging your triceps.\",\"Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3291.webp\",\"gif\":\"3291.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A gymnastics press where you shift your weight over the hands and lift the body up with straight arms. It trains the triceps and shoulders.\"},{\"id\":\"3669\",\"n\":\"standing archer\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Extend your arms straight out in front of you at shoulder height, parallel to the ground.\",\"Rotate your torso to the right, keeping your arms extended and your back straight.\",\"As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.\",\"Hold the position for a moment, then return to the starting position.\",\"Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"3669.webp\",\"gif\":\"3669.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing movement that rotates the torso and draws one arm back like pulling a bow. It mobilises the upper back and shoulders.\"},{\"id\":\"0788\",\"n\":\"standing behind neck press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.\",\"Keep your back straight and core engaged.\",\"Press the barbell overhead by extending your arms, fully extending your elbows.\",\"Pause for a moment at the top, then slowly lower the barbell back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0788.webp\",\"gif\":\"0788.mp4\",\"cat\":\"strength\",\"desc\":\"A standing barbell press from behind the neck to overhead. It builds the shoulders and triceps and calls for good shoulder mobility.\"},{\"id\":\"1490\",\"n\":\"standing calf raise (on a staircase)\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.\",\"Hold onto a railing or wall for balance if needed.\",\"Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1490.webp\",\"gif\":\"1490.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A calf raise with your heels hanging off a stair step for extra range. It trains the calves through a deep stretch.\",\"fv\":\"2378\"},{\"id\":\"1397\",\"n\":\"standing calves\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing forward.\",\"Raise your heels off the ground as high as possible, standing on your toes.\",\"Hold the position for a moment, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1397.webp\",\"gif\":\"1397.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise where you lift your heels as high as you can. It builds the calf muscles.\"},{\"id\":\"1398\",\"n\":\"standing calves calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand facing a wall or sturdy object, about an arm's length away.\",\"Place your hands on the wall or object at shoulder height.\",\"Step back with one foot, keeping your heel flat on the ground.\",\"Bend your front knee slightly and lean forward, keeping your back leg straight.\",\"You should feel a stretch in your calf muscle.\",\"Hold the stretch for 20-30 seconds.\",\"Repeat on the other leg.\"],\"img\":\"1398.webp\",\"gif\":\"1398.mp4\",\"cat\":\"stretching\",\"desc\":\"Stand facing a wall and step one foot back with the heel down. It stretches the calf of the back leg.\",\"fv\":\"4319\"},{\"id\":\"1599\",\"n\":\"standing hamstring and calf stretch with strap\",\"bp\":\"upper legs\",\"eq\":\"rope\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\"],\"st\":[\"Stand upright with your feet shoulder-width apart.\",\"Hold the strap with both hands and place it around the ball of your foot.\",\"Keep your leg straight and slowly lean forward from your hips, keeping your back straight.\",\"Feel the stretch in your hamstring and calf muscles.\",\"Hold the stretch for 20-30 seconds.\",\"Release the stretch and repeat with the other leg.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1599.webp\",\"gif\":\"1599.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing with a strap around your foot, you pull your toes toward you to stretch the hamstring and calf.\",\"fv\":\"4317\"},{\"id\":\"0794\",\"n\":\"standing lateral stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Extend your arms straight out to the sides, parallel to the ground.\",\"Slowly lean your upper body to one side, feeling a stretch in your side and lats.\",\"Hold the stretch for 15-30 seconds.\",\"Return to the starting position and repeat on the other side.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0794.webp\",\"gif\":\"0794.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side bend that stretches the lats and the muscles along the side of the torso. It loosens up the sides and improves mobility.\",\"fv\":\"4320\"},{\"id\":\"1364\",\"n\":\"standing pelvic tilt\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"abdominals\",\"sm\":[\"abdominals\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Place your hands on your hips or let them hang by your sides.\",\"Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.\",\"Hold the position for a few seconds, then release and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1364.webp\",\"gif\":\"1364.mp4\",\"cat\":\"mobility\",\"desc\":\"Stand and tilt your pelvis back and forth to move your lower back. It loosens the lower back and teaches pelvic control.\",\"fv\":\"3406\"},{\"id\":\"0795\",\"n\":\"standing single leg curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Stand with your feet hip-width apart and your hands on your hips.\",\"Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.\",\"Slowly curl your right heel towards your glutes, squeezing your hamstring.\",\"Pause for a moment at the top, then slowly lower your right foot back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0795.webp\",\"gif\":\"0795.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight hamstring curl done standing on one leg, bringing the heel toward the glutes. It trains the hamstrings and balance.\"},{\"id\":\"0796\",\"n\":\"standing wheel rollerout\",\"bp\":\"waist\",\"eq\":\"wheel roller\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"shoulders\"],\"st\":[\"Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.\",\"Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.\",\"Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.\",\"Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0796.webp\",\"gif\":\"0796.mp4\",\"cat\":\"strength\",\"desc\":\"A standing ab wheel rollout, rolling the wheel out in front while hinging at the waist. It is a tough core exercise for the abs.\",\"fv\":\"4324\"},{\"id\":\"3223\",\"n\":\"star jump (male)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms by your sides.\",\"Bend your knees slightly and jump up explosively.\",\"As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.\",\"Land softly on the balls of your feet with your knees slightly bent.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3223.webp\",\"gif\":\"3223.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump where arms and legs spread wide like a star at the top. It is a full-body cardio move that raises your pulse fast.\",\"fv\":\"0797\"},{\"id\":\"2138\",\"n\":\"stationary bike run v. 3\",\"bp\":\"cardio\",\"eq\":\"stationary bike\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat height and position to ensure proper alignment.\",\"Place your feet on the pedals and secure them with the straps if available.\",\"Start pedaling at a comfortable pace.\",\"Maintain a steady rhythm and increase the resistance as desired.\",\"Engage your core muscles to maintain stability and proper posture.\",\"Continue pedaling for the desired duration of your workout.\",\"Gradually decrease the resistance and slow down before coming to a complete stop.\",\"Stretch your legs and cool down after the workout.\"],\"img\":\"2138.webp\",\"gif\":\"2138.mp4\",\"cat\":\"cardio\",\"desc\":\"Steady pedalling on a stationary bike at a pace that suits you. Builds endurance and leg conditioning.\",\"fv\":\"2264\"},{\"id\":\"0798\",\"n\":\"stationary bike walk\",\"bp\":\"cardio\",\"eq\":\"leverage machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat height and position on the stationary bike to ensure proper alignment.\",\"Place your feet on the pedals and secure them with the straps if available.\",\"Start pedaling at a comfortable pace, keeping your back straight and core engaged.\",\"Maintain a steady rhythm and increase the resistance level if desired.\",\"Continue pedaling for the desired duration of your cardio workout.\",\"Cool down by gradually reducing your pace and resistance level.\",\"Stretch your leg muscles after the workout to prevent tightness and promote recovery.\"],\"img\":\"0798.webp\",\"gif\":\"0798.mp4\",\"cat\":\"cardio\",\"desc\":\"Easy, steady pedaling on a stationary bike at a walking-like pace. It builds endurance and warms up the legs.\"},{\"id\":\"3314\",\"n\":\"straddle maltese\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.\",\"Spread your legs wide apart, forming a straddle position.\",\"Engage your core and slowly lower your body until your arms are parallel to the ground.\",\"Hold this position for a few seconds, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3314.webp\",\"gif\":\"3314.mp4\",\"cat\":\"isometric\",\"desc\":\"A ring hold with the arms out and the legs straddled. It builds the chest and shoulders and is a stepping stone toward the full maltese.\",\"hd\":1},{\"id\":\"3298\",\"n\":\"straddle planche\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"chest\"],\"st\":[\"Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.\",\"Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.\",\"Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.\",\"Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3298.webp\",\"gif\":\"3298.mp4\",\"cat\":\"isometric\",\"desc\":\"A planche hold with the legs spread wide, which makes the lever shorter. It trains the shoulders, chest and core.\",\"hd\":1},{\"id\":\"1427\",\"n\":\"straight leg outer hip abductor\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie on your side with your legs straight and stacked on top of each other.\",\"Place your bottom arm under your head for support.\",\"Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.\",\"Pause for a moment at the top, then slowly lower your leg back down to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"1427.webp\",\"gif\":\"1427.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on your side with your legs straight and lift the top leg. It works the outer hip and glute muscles that stabilise your pelvis.\"},{\"id\":\"0803\",\"n\":\"superman push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Engage your core and lower your body towards the ground, keeping your elbows close to your sides.\",\"As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.\",\"Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.\",\"Repeat the movement, this time lifting your left arm and right leg.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0803.webp\",\"gif\":\"0803.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up in which you lift the opposite arm and leg at the top, like Superman. It trains the chest, back and core stability.\"},{\"id\":\"0805\",\"n\":\"suspended abdominal fallout\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Attach a suspension trainer to a high anchor point and adjust the straps to waist height.\",\"Stand facing away from the anchor point and hold the handles with your arms extended in front of you.\",\"Lean forward at the waist, keeping your body straight and your core engaged.\",\"Lower your body as far as you can while maintaining control and tension in your abs.\",\"Pause for a moment at the bottom, then slowly raise your body back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0805.webp\",\"gif\":\"0805.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A fallout with suspension straps, leaning forward and lowering the body with straight arms. It builds deep core strength in the abs.\"},{\"id\":\"0806\",\"n\":\"suspended push-up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Find a suspension trainer and adjust it to an appropriate height.\",\"Stand facing away from the anchor point and hold the handles with an overhand grip.\",\"Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.\",\"Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.\",\"Push through your chest and arms to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0806.webp\",\"gif\":\"0806.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the hands in suspension handles, so the body has to stay stable. It trains the chest, shoulders, triceps and core.\"},{\"id\":\"0807\",\"n\":\"suspended reverse crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.\",\"Pause for a moment at the top, then slowly lower your knees back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0807.webp\",\"gif\":\"0807.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging reverse crunch, curling the knees and pelvis up toward the chest. It targets the lower abs.\"},{\"id\":\"0808\",\"n\":\"suspended row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"shoulders\"],\"st\":[\"Set up a suspension trainer at an appropriate height.\",\"Stand facing the anchor point with your feet shoulder-width apart.\",\"Hold the handles with an overhand grip, palms facing each other.\",\"Lean back, keeping your body straight and your heels on the ground.\",\"Pull your chest towards the handles, squeezing your shoulder blades together.\",\"Pause for a moment at the top, then slowly lower yourself back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0808.webp\",\"gif\":\"0808.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row with suspension handles, leaning back and pulling the chest to the hands. It trains the back and biceps.\"},{\"id\":\"0809\",\"n\":\"suspended split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing away from a suspension trainer with your feet shoulder-width apart.\",\"Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.\",\"Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.\",\"Push through your heel to return to the starting position.\",\"Repeat for the desired number of repetitions, then switch legs.\"],\"img\":\"0809.webp\",\"gif\":\"0809.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A split squat with the rear foot in a suspension strap. It builds the quads and glutes and challenges balance.\"},{\"id\":\"3433\",\"n\":\"swimmer kicks v. 2 (male)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Lie face down on a mat with your arms extended overhead.\",\"Engage your core and lift your chest and legs off the ground simultaneously.\",\"Kick your legs up and down in a fluttering motion, as if you were swimming.\",\"Continue kicking for the desired number of repetitions.\",\"Lower your chest and legs back down to the starting position.\"],\"img\":\"3433.webp\",\"gif\":\"3433.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A face-down flutter kick, lifting the chest and legs off the floor and kicking in a swimming motion. It trains the glutes and lower back.\",\"fv\":\"3434\"},{\"id\":\"3318\",\"n\":\"swing 360\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and knees slightly bent.\",\"Hold your arms straight out in front of you, parallel to the ground.\",\"Engage your core and swing your arms in a circular motion, rotating your torso as you do so.\",\"Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.\",\"Remember to breathe throughout the exercise.\"],\"img\":\"3318.webp\",\"gif\":\"3318.mp4\",\"cat\":\"cardio\",\"desc\":\"A rotating movement that swings the arms and torso in a full circle. It gets the heart rate up and loosens the trunk.\"},{\"id\":\"1753\",\"n\":\"three bench dip\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a bench with your hands gripping the edge, fingers pointing forward.\",\"Slide your butt off the bench, supporting your weight with your hands.\",\"Bend your elbows and lower your body until your upper arms are parallel to the ground.\",\"Push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1753.webp\",\"gif\":\"1753.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bench dip with hands on the bench edge and body hanging off the front. A classic bodyweight move for the triceps.\"},{\"id\":\"2459\",\"n\":\"tire flip\",\"bp\":\"upper legs\",\"eq\":\"tire\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart, facing the tire.\",\"Bend your knees and hinge at the hips, lowering into a squat position.\",\"Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.\",\"Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.\",\"As the tire flips over, use your upper body strength to guide it and maintain control.\",\"Once the tire is fully flipped, quickly step back and reset your stance.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2459.webp\",\"gif\":\"2459.mp4\",\"cat\":\"strength\",\"desc\":\"Flipping a heavy tire end over end by driving through your legs. Builds full-body power, especially glutes and legs.\"},{\"id\":\"0811\",\"n\":\"trap bar deadlift\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.\",\"Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.\",\"Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.\",\"As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.\",\"Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0811.webp\",\"gif\":\"0811.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift standing inside a hex bar, lifting by extending the hips and knees. It builds the glutes, quads and back with a friendly lifting position.\"},{\"id\":\"0814\",\"n\":\"triceps dip\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.\",\"Slide your butt off the bench, supporting your weight with your hands.\",\"Bend your elbows and lower your body towards the ground, keeping your back close to the bench.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0814.webp\",\"gif\":\"0814.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A triceps dip using the edge of a bench or chair, lowering the body and pressing back up. It builds the triceps.\",\"fv\":\"3115\"},{\"id\":\"0812\",\"n\":\"triceps dip (bench leg)\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.\",\"Walk your feet forward, sliding your butt off the bench, and straighten your arms.\",\"Bend your elbows and lower your body towards the ground, keeping your back close to the bench.\",\"Push through your palms to straighten your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0812.webp\",\"gif\":\"0812.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bench dip with the legs extended on the floor or a bench, lowering and pressing the body up. It trains the triceps.\",\"fv\":\"9736\"},{\"id\":\"0813\",\"n\":\"triceps dip (between benches)\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.\",\"Slide your butt off the bench, supporting your weight with your hands.\",\"Bend your elbows and lower your body towards the ground, keeping your back close to the bench.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0813.webp\",\"gif\":\"0813.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A triceps dip with the hands on one bench and the feet on another. It trains the triceps and shoulders.\"},{\"id\":\"0815\",\"n\":\"triceps dips floor\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.\",\"Slide your butt off the front of the chair with your legs extended in front of you.\",\"Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.\",\"Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.\",\"Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0815.webp\",\"gif\":\"0815.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A triceps dip with the hands on a chair behind you and the body lowered toward the floor. It builds the triceps and shoulders.\"},{\"id\":\"0816\",\"n\":\"triceps press\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart and your knees slightly bent.\",\"Extend your arms straight out in front of you, parallel to the ground.\",\"Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0816.webp\",\"gif\":\"0816.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight triceps press that lowers the body by bending the elbows, then presses back up. It works the triceps.\"},{\"id\":\"0817\",\"n\":\"triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand or sit upright with your back straight.\",\"Extend one arm overhead, bending it at the elbow.\",\"Place your opposite hand on the bent elbow and gently pull it towards your head.\",\"Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.\",\"Release the stretch and repeat on the other arm.\"],\"img\":\"0817.webp\",\"gif\":\"0817.mp4\",\"cat\":\"stretching\",\"desc\":\"An overhead stretch for the back of the upper arm, pulling the elbow toward the head. It loosens the triceps and shoulders.\"},{\"id\":\"0871\",\"n\":\"tuck crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Place your hands behind your head with your elbows pointing outwards.\",\"Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.\",\"Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0871.webp\",\"gif\":\"0871.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch that pulls the knees toward the chest as the upper body curls up. It trains the abs.\"},{\"id\":\"0818\",\"n\":\"twin handle parallel grip lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the seat height and position yourself facing the cable machine.\",\"Grasp the handles with an overhand grip, hands shoulder-width apart.\",\"Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.\",\"Lean back slightly and keep your chest up, maintaining a neutral spine.\",\"Pull the handles down towards your upper chest, squeezing your shoulder blades together.\",\"Pause for a moment at the bottom of the movement, feeling the contraction in your lats.\",\"Slowly release the handles and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0818.webp\",\"gif\":\"0818.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown with two handles and a neutral parallel grip. It trains the lats and biceps.\"},{\"id\":\"1466\",\"n\":\"twist hip lift\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\"],\"st\":[\"Lie on your back with your knees bent and feet flat on the ground.\",\"Place your hands by your sides for support.\",\"Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.\",\"While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.\",\"Return to the starting position and repeat the twist to the left side.\",\"Continue alternating twists for the desired number of repetitions.\"],\"img\":\"1466.webp\",\"gif\":\"1466.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you lift your hips and add a gentle twist. It wakes up the glutes and obliques.\"},{\"id\":\"2802\",\"n\":\"twisted leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Place your hands under your glutes for support.\",\"Engage your abs and lift both legs off the ground, keeping them straight.\",\"As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat the movement, this time twisting your hips to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"2802.webp\",\"gif\":\"2802.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying leg raise with a hip twist and hands under the glutes. Works the abs and obliques.\",\"fv\":\"2801\"},{\"id\":\"2801\",\"n\":\"twisted leg raise (female)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie flat on your back with your legs extended and your arms by your sides.\",\"Bend your knees and lift your legs off the ground, bringing them towards your chest.\",\"As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat the movement, this time twisting your hips to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"2801.webp\",\"gif\":\"2801.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying leg raise with a hip twist. Works the abs and obliques.\",\"mv\":\"2802\"},{\"id\":\"3231\",\"n\":\"two toe touch (male)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms extended out to the sides.\",\"Bend forward at the waist, keeping your back straight and your knees slightly bent.\",\"Reach down towards your toes with both hands, keeping your legs straight.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3231.webp\",\"gif\":\"3231.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing forward bend reaching both hands toward the toes. It loosens the hamstrings and lower back.\"},{\"id\":\"1365\",\"n\":\"upper back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand up straight with your feet shoulder-width apart.\",\"Extend your arms straight in front of you, parallel to the ground.\",\"Interlace your fingers and rotate your palms away from your body.\",\"Slowly raise your arms overhead, keeping them straight and parallel to each other.\",\"As you raise your arms, squeeze your shoulder blades together.\",\"Hold the stretch for 15-30 seconds, then release and repeat.\"],\"img\":\"1365.webp\",\"gif\":\"1365.mp4\",\"cat\":\"stretching\",\"desc\":\"Reach your arms forward and round your upper back to open up the space between your shoulder blades. It stretches the upper back.\"},{\"id\":\"1366\",\"n\":\"upward facing dog\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Lie face down on the floor with your legs extended behind you.\",\"Place your hands on the floor next to your lower ribs, fingers pointing forward.\",\"Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.\",\"Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.\",\"Hold this position for a few breaths, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1366.webp\",\"gif\":\"1366.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga pose where you lift your chest and thighs off the floor on straight arms. It opens the chest and strengthens the back.\"},{\"id\":\"3420\",\"n\":\"v-sit on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the floor with your legs extended in front of you.\",\"Lean back slightly and lift your legs off the ground, keeping them straight.\",\"Simultaneously, lift your upper body off the ground and reach your arms towards your legs.\",\"Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3420.webp\",\"gif\":\"3420.mp4\",\"cat\":\"isometric\",\"desc\":\"A seated hold with both the legs and the upper body lifted into a V shape. It trains the abs, hip flexors and balance.\",\"hd\":1},{\"id\":\"0826\",\"n\":\"vertical leg raise (on parallel bars)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Hang from the parallel bars with your arms fully extended and your body straight.\",\"Engage your core and lift your legs up in front of you, keeping them straight.\",\"Continue lifting until your legs are parallel to the ground or slightly higher.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0826.webp\",\"gif\":\"0826.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A leg raise done hanging or supported between parallel bars, lifting straight legs in front. It trains the abs and hip flexors.\",\"fv\":\"2448\"},{\"id\":\"2141\",\"n\":\"walk elliptical cross trainer\",\"bp\":\"cardio\",\"eq\":\"elliptical machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Adjust the resistance level and incline of the elliptical machine to your desired settings.\",\"Step onto the pedals of the machine and grip the handles lightly.\",\"Begin by pushing down with your feet and pulling the handles towards your body.\",\"Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.\",\"Maintain a steady pace and keep your core engaged throughout the exercise.\",\"Continue for the desired duration of your cardio workout.\",\"Gradually decrease the intensity and speed of the machine before stepping off.\"],\"img\":\"2141.webp\",\"gif\":\"2141.mp4\",\"cat\":\"cardio\",\"desc\":\"Smooth walking-style motion on an elliptical cross trainer. Low-impact cardio that builds endurance.\",\"fv\":\"3624\"},{\"id\":\"3655\",\"n\":\"walking high knees lunge\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Stand with your feet hip-width apart.\",\"Lift your right knee up towards your chest as high as you can while balancing on your left leg.\",\"Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.\",\"Push off with your right foot and bring your left knee up towards your chest.\",\"Step forward with your left foot and lower your body into a lunge position.\",\"Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3655.webp\",\"gif\":\"3655.mp4\",\"cat\":\"cardio\",\"desc\":\"A walking lunge with a high knee between each step. It raises your heart rate and trains the legs.\"},{\"id\":\"1460\",\"n\":\"walking lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Take a step forward with your right leg, lowering your body into a lunge position.\",\"Keep your torso upright and your front knee aligned with your ankle.\",\"Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.\",\"Continue alternating legs and walking forward, maintaining a controlled and steady pace.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1460.webp\",\"gif\":\"1460.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Stepping forward into one lunge after another, moving across the room. It works the quads and glutes and challenges balance.\",\"fv\":\"3811\"},{\"id\":\"3666\",\"n\":\"walking on incline treadmill\",\"bp\":\"cardio\",\"eq\":\"leverage machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the incline level on the treadmill to your desired intensity.\",\"Stand on the treadmill with your feet shoulder-width apart.\",\"Start walking at a comfortable pace, ensuring that you maintain proper form.\",\"Engage your core muscles and keep your back straight throughout the exercise.\",\"Continue walking on the incline treadmill for the desired duration of your cardio workout.\",\"Gradually decrease the incline and speed of the treadmill to cool down before stopping.\"],\"img\":\"3666.webp\",\"gif\":\"3666.mp4\",\"cat\":\"cardio\",\"desc\":\"A walk on a treadmill with an incline, which makes the glutes and calves work harder. A steady, low impact cardio option.\",\"fv\":\"5209\"},{\"id\":\"2311\",\"n\":\"walking on stepmill\",\"bp\":\"cardio\",\"eq\":\"stepmill machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Adjust the stepmill machine to a comfortable level.\",\"Step onto the machine and place your hands on the handrails for support.\",\"Start walking by placing one foot on a step and then the other, alternating between legs.\",\"Maintain an upright posture and engage your core muscles.\",\"Continue walking for the desired duration or distance.\",\"Gradually increase the intensity or speed as you become more comfortable with the exercise.\",\"Remember to cool down and stretch after completing the exercise.\"],\"img\":\"2311.webp\",\"gif\":\"2311.mp4\",\"cat\":\"cardio\",\"desc\":\"Stepping on a stepmill at a steady pace. A tough, low-impact cardio workout for legs and glutes.\",\"fv\":\"2490\"},{\"id\":\"0830\",\"n\":\"weighted bench dip\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a bench with your hands gripping the edge, fingers pointing forward.\",\"Slide your butt off the bench, supporting your weight with your hands.\",\"Lower your body by bending your elbows until your upper arms are parallel to the floor.\",\"Push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0830.webp\",\"gif\":\"0830.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bench dip with added weight on the lap or hips. It builds the triceps and chest.\",\"fv\":\"11442\"},{\"id\":\"2987\",\"n\":\"weighted close grip chin-up on dip cage\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.\",\"Hang from the bars with your arms fully extended, feet off the ground, and body straight.\",\"Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.\",\"Continue pulling until your chin is above the bars, then pause for a moment.\",\"Slowly lower your body back down to the starting position, fully extending your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2987.webp\",\"gif\":\"2987.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A weighted close-grip chin-up on a dip cage. Builds the lats, biceps and upper back.\"},{\"id\":\"3643\",\"n\":\"weighted cossack squats (male)\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.\",\"Hold a weight in front of your chest with both hands.\",\"Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.\",\"Go as low as you can while maintaining balance and keeping your chest up.\",\"Push through the heel of the bent leg to return to the starting position.\",\"Repeat on the other side, alternating between legs.\"],\"img\":\"3643.webp\",\"gif\":\"3643.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted side-to-side squat, shifting weight deeply over one leg with the other straight. It trains the glutes, quads and adductors.\"},{\"id\":\"0832\",\"n\":\"weighted crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie flat on your back with your knees bent and feet flat on the ground.\",\"Hold a weight plate or dumbbell on your chest.\",\"Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0832.webp\",\"gif\":\"0832.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch holding a weight on the chest. It strengthens the abs with added resistance.\",\"fv\":\"2540\"},{\"id\":\"3670\",\"n\":\"weighted decline sit-up\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on a decline bench with your feet secured under the foot pads.\",\"Place your hands behind your head or across your chest.\",\"Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3670.webp\",\"gif\":\"3670.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted sit-up on a decline bench. It trains the abs through a long range.\"},{\"id\":\"0833\",\"n\":\"weighted donkey calf raise\",\"bp\":\"lower legs\",\"eq\":\"weighted\",\"tg\":\"calves\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand on a raised platform with your toes on the edge and your heels hanging off.\",\"Hold onto a stable object for support.\",\"Raise your heels as high as possible by extending your ankles.\",\"Pause for a moment at the top, then slowly lower your heels back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0833.webp\",\"gif\":\"0833.mp4\",\"cat\":\"strength\",\"desc\":\"A donkey calf raise with extra weight, bent at the hips with the toes on a platform. It works the calves through a long range of motion.\"},{\"id\":\"1310\",\"n\":\"weighted drop push up\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.\",\"Lower your chest towards the ground, keeping your elbows close to your body.\",\"Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.\",\"As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.\",\"Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.\",\"Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.\",\"Continue alternating between the wider and narrower hand positions for the desired number of repetitions.\"],\"img\":\"1310.webp\",\"gif\":\"1310.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A weighted push-up variation where you drop and shift your hands between push-ups for extra load. It challenges the chest and triceps.\"},{\"id\":\"2135\",\"n\":\"weighted front plank\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lower back\"],\"st\":[\"Start by lying face down on the floor.\",\"Place your forearms on the ground, with your elbows directly under your shoulders.\",\"Extend your legs straight out behind you, with your toes on the ground.\",\"Engage your core and lift your body off the ground, balancing on your forearms and toes.\",\"Keep your body in a straight line from your head to your heels.\",\"Hold this position for the desired amount of time.\",\"Lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2135.webp\",\"gif\":\"2135.mp4\",\"cat\":\"isometric\",\"desc\":\"A forearm plank held with extra weight on your back. Builds core strength and stability.\",\"hd\":1},{\"id\":\"0834\",\"n\":\"weighted front raise\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.\",\"Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.\",\"Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0834.webp\",\"gif\":\"0834.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with weights, lifting straight arms to shoulder height. It builds the front delts.\"},{\"id\":\"0866\",\"n\":\"weighted hanging leg-hip raise\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Hang from a pull-up bar with your arms fully extended and your palms facing away from you.\",\"Engage your core and lift your legs up in front of you, keeping them straight.\",\"Continue lifting until your legs are parallel to the ground or slightly higher.\",\"Pause for a moment at the top, then slowly lower your legs back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0866.webp\",\"gif\":\"0866.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging leg raise with added weight. It builds the abs and hip flexors.\",\"fv\":\"7004\"},{\"id\":\"0835\",\"n\":\"weighted hyperextension (on stability ball)\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.\",\"Place your hands behind your head or cross them over your chest.\",\"Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.\",\"Pause for a moment at the top, then slowly lower your upper body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0835.webp\",\"gif\":\"0835.mp4\",\"cat\":\"strength\",\"desc\":\"A back extension over a stability ball while holding a weight. It strengthens the lower back and glutes.\"},{\"id\":\"3641\",\"n\":\"weighted kneeling step with swing\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Start in a kneeling position with your knees hip-width apart and your back straight.\",\"Hold a weight in each hand, with your arms extended straight down in front of you.\",\"Engage your core and swing the weights up and overhead, keeping your arms straight.\",\"Lower the weights back down to the starting position and repeat for the desired number of repetitions.\"],\"img\":\"3641.webp\",\"gif\":\"3641.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling step combined with a weighted swing. It trains the shoulders and core.\"},{\"id\":\"3644\",\"n\":\"weighted lunge with swing\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, holding a weight in each hand.\",\"Take a step forward with your right foot, lowering your body into a lunge position.\",\"As you lunge forward, swing the weights forward and upward, keeping your arms straight.\",\"Push off with your right foot and return to the starting position, swinging the weights back down.\",\"Repeat with your left foot and continue alternating legs for the desired number of repetitions.\"],\"img\":\"3644.webp\",\"gif\":\"3644.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted lunge with an arm swing as you step forward. It trains the glutes, quads and shoulders.\"},{\"id\":\"3286\",\"n\":\"weighted muscle up\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"shoulders\",\"chest\"],\"st\":[\"Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.\",\"Engage your core and pull your body up towards the bar, leading with your chest.\",\"As you reach the top of the movement, transition your grip so that your palms are facing towards you.\",\"Continue pulling yourself up until your chest reaches the bar, then pause for a moment.\",\"Slowly lower yourself back down to the starting position, maintaining control throughout the movement.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3286.webp\",\"gif\":\"3286.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A muscle up with added weight, pulling from a hang up and over the bar into a dip position. It is an advanced move for lats, chest and triceps.\"},{\"id\":\"3312\",\"n\":\"weighted muscle up (on bar)\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"shoulders\",\"forearms\"],\"st\":[\"Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.\",\"Engage your core and pull your shoulder blades down and back.\",\"Bend your elbows and pull your chest towards the bar, keeping your body straight.\",\"Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.\",\"Pause at the top of the movement, then slowly lower yourself back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3312.webp\",\"gif\":\"3312.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A weighted muscle up performed with the added load on a bar. An advanced pull and dip that trains the lats, chest and triceps.\"},{\"id\":\"3290\",\"n\":\"weighted one hand pull up\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang from the bar with your arm fully extended and your body straight.\",\"Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.\",\"Continue pulling until your chin is above the bar.\",\"Lower your body back down to the starting position with control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3290.webp\",\"gif\":\"3290.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced one arm pull-up with added weight. It builds the lats and biceps and needs great pulling strength.\"},{\"id\":\"0840\",\"n\":\"weighted overhead crunch (on stability ball)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a weight plate or dumbbell with both hands and extend your arms overhead.\",\"Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.\",\"Pause for a moment at the top, then slowly lower your torso back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0840.webp\",\"gif\":\"0840.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted crunch on a stability ball with the arms overhead. It trains the abs through a larger range of motion.\"},{\"id\":\"0841\",\"n\":\"weighted pull-up\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body straight.\",\"Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0841.webp\",\"gif\":\"0841.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with added weight on a belt or vest. It builds the lats and biceps and increases strength.\"},{\"id\":\"0844\",\"n\":\"weighted round arm\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand.\",\"Bend your knees slightly and hinge forward at the hips, keeping your back straight.\",\"Raise your arms out to the sides, keeping a slight bend in your elbows.\",\"Continue lifting your arms until they are parallel to the ground.\",\"Pause for a moment at the top, then slowly lower your arms back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0844.webp\",\"gif\":\"0844.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over lateral raise with weights, lifting the arms out to the sides. It trains the rear and side delts.\"},{\"id\":\"0846\",\"n\":\"weighted russian twist\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the ground with your knees bent and your feet flat on the floor.\",\"Hold a weight or medicine ball with both hands in front of your chest.\",\"Lean back slightly, keeping your back straight and your core engaged.\",\"Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.\",\"Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0846.webp\",\"gif\":\"0846.mp4\",\"cat\":\"strength\",\"desc\":\"A seated Russian twist holding a weight, rotating side to side. It trains the obliques and abs.\",\"fv\":\"2559\"},{\"id\":\"0845\",\"n\":\"weighted russian twist (legs up)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.\",\"Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.\",\"Lean back slightly to engage your core muscles.\",\"Twist your torso to the right, bringing the weight towards the ground on your right side.\",\"Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0845.webp\",\"gif\":\"0845.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted Russian twist with the feet lifted, rotating the torso side to side. It trains the abs and obliques.\"},{\"id\":\"2371\",\"n\":\"weighted russian twist v. 2\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the ground with your knees bent and feet flat on the floor.\",\"Hold the weight with both hands in front of your chest.\",\"Lean back slightly to engage your core muscles.\",\"Twist your torso to the right, bringing the weight towards the right side of your body.\",\"Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"2371.webp\",\"gif\":\"2371.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted russian twist, rotating a weight side to side while leaning back. Works the abs and obliques.\"},{\"id\":\"0847\",\"n\":\"weighted seated bicep curl (on stability ball)\",\"bp\":\"upper arms\",\"eq\":\"medicine ball\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your back straight.\",\"Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.\",\"Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.\",\"Pause for a moment at the top, squeezing your biceps.\",\"Inhale and slowly lower the medicine ball back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0847.webp\",\"gif\":\"0847.mp4\",\"cat\":\"strength\",\"desc\":\"A seated biceps curl on a stability ball holding a medicine ball. It trains the biceps and balance.\"},{\"id\":\"0849\",\"n\":\"weighted seated twist (on stability ball)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\",\"Hold a weight plate or dumbbell with both hands close to your chest.\",\"Engage your core and slowly rotate your torso to one side, keeping your hips stable.\",\"Pause for a moment at the end of the rotation, then slowly return to the starting position.\",\"Repeat the rotation to the other side.\",\"Continue alternating sides for the desired number of repetitions.\"],\"img\":\"0849.webp\",\"gif\":\"0849.mp4\",\"cat\":\"strength\",\"desc\":\"A seated twist on a stability ball holding a weight at the chest. It trains the obliques and builds core control.\"},{\"id\":\"0850\",\"n\":\"weighted side bend (on stability ball)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on a stability ball with your feet shoulder-width apart and flat on the ground.\",\"Hold a weight in one hand and place your other hand on your hip.\",\"Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.\",\"Pause for a moment at the bottom, then slowly return to the starting position.\",\"Repeat for the desired number of repetitions, then switch sides.\"],\"img\":\"0850.webp\",\"gif\":\"0850.mp4\",\"cat\":\"strength\",\"desc\":\"A side bend on a stability ball holding a weight in one hand. It trains the obliques.\"},{\"id\":\"0851\",\"n\":\"weighted sissy squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart and your toes pointing slightly outward.\",\"Hold a weight in front of your chest with both hands, or place a barbell across your upper back.\",\"Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.\",\"Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.\",\"Pause for a moment at the bottom, then push through your heels to return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0851.webp\",\"gif\":\"0851.mp4\",\"cat\":\"strength\",\"desc\":\"A sissy squat with added weight, leaning back while the knees travel forward. It isolates the quads.\",\"fv\":\"4032\"},{\"id\":\"0852\",\"n\":\"weighted squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart, toes pointing slightly outward.\",\"Hold a weight in front of your chest or on your shoulders.\",\"Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.\",\"Lower until your thighs are parallel to the ground, or as low as you can comfortably go.\",\"Push through your heels to stand back up, squeezing your glutes at the top.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0852.webp\",\"gif\":\"0852.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with weight held at the chest or shoulders. It builds the glutes and thighs.\"},{\"id\":\"0853\",\"n\":\"weighted standing curl\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.\",\"Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.\",\"Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0853.webp\",\"gif\":\"0853.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with weights in both hands. It trains the biceps.\",\"fv\":\"3626\"},{\"id\":\"0854\",\"n\":\"weighted standing hand squeeze\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a weight in each hand.\",\"Extend your arms straight in front of you, palms facing each other.\",\"Squeeze your hands together as hard as you can, engaging your forearms.\",\"Hold the squeeze for a few seconds, then release.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0854.webp\",\"gif\":\"0854.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hand squeeze holding weights, squeezing the hands together. It works the forearms and grip.\"},{\"id\":\"3313\",\"n\":\"weighted straight bar dip\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Position yourself between parallel bars with your arms fully extended and your body straight.\",\"Lower your body by bending your elbows until your upper arms are parallel to the ground.\",\"Pause for a moment, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3313.webp\",\"gif\":\"3313.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A weighted dip on a straight bar or parallel bars. It builds the chest, triceps and shoulders with added resistance.\"},{\"id\":\"3642\",\"n\":\"weighted stretch lunge\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Take a step forward with your right foot, keeping your back straight.\",\"Lower your body by bending your knees until your right thigh is parallel to the ground.\",\"Push through your right heel to return to the starting position.\",\"Repeat with your left leg.\",\"Continue alternating legs for the desired number of repetitions.\"],\"img\":\"3642.webp\",\"gif\":\"3642.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted lunge into a deep stretch for the hips. It trains the glutes and quads while opening up the hip flexors.\"},{\"id\":\"0856\",\"n\":\"weighted svend press\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.\",\"Keep your elbows slightly bent and your palms facing each other.\",\"Press the weight plate straight out in front of you, fully extending your arms.\",\"Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0856.webp\",\"gif\":\"0856.mp4\",\"cat\":\"strength\",\"desc\":\"A chest squeeze press holding a plate between the palms and pushing it forward. It trains the inner chest and shoulders.\",\"fv\":\"3426\"},{\"id\":\"1754\",\"n\":\"weighted three bench dips\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.\",\"Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.\",\"Lower your body by bending your elbows, keeping your back close to the bench.\",\"Pause for a moment at the bottom, then push yourself back up to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1754.webp\",\"gif\":\"1754.mp4\",\"cat\":\"strength\",\"desc\":\"A bench dip with extra weight added for more resistance. Builds triceps and front shoulder strength once bodyweight gets easy.\"},{\"id\":\"1755\",\"n\":\"weighted tricep dips\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.\",\"Slide your butt off the front of the bench with your legs extended in front of you.\",\"Keep your back close to the bench and your elbows slightly bent.\",\"Lower your body by bending your elbows until your upper arms are parallel to the floor.\",\"Push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1755.webp\",\"gif\":\"1755.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted dip off a bench or chair with legs extended. Loads the triceps harder than the bodyweight version.\",\"fv\":\"10585\"},{\"id\":\"1767\",\"n\":\"weighted triceps dip on high parallel bars\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.\",\"Bend your elbows and lower your body until your upper arms are parallel to the ground.\",\"Pause for a moment, then push through your palms to straighten your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1767.webp\",\"gif\":\"1767.mp4\",\"cat\":\"strength\",\"desc\":\"A dip between two high parallel bars with extra weight attached. Builds triceps, chest and shoulder strength.\"},{\"id\":\"0857\",\"n\":\"wheel rollerout\",\"bp\":\"waist\",\"eq\":\"wheel roller\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\"],\"st\":[\"Kneel on the floor and place the wheel roller in front of you.\",\"Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.\",\"Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.\",\"Continue rolling forward until your body is fully extended and your arms are overhead.\",\"Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0857.webp\",\"gif\":\"0857.mp4\",\"cat\":\"strength\",\"desc\":\"An ab wheel rollout from the knees, rolling forward and back with control. It builds a strong core and abs.\",\"fv\":\"2332\"},{\"id\":\"3637\",\"n\":\"wheel run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Start in a plank position with your hands on the wheel and your body straight.\",\"Engage your core and start rolling the wheel forward by extending your arms.\",\"Continue rolling until your body is fully extended and your arms are overhead.\",\"Reverse the movement by pulling the wheel back towards your body, using your core and arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"3637.webp\",\"gif\":\"3637.mp4\",\"cat\":\"cardio\",\"desc\":\"A fast running motion while holding on to a wheel. It raises your heart rate and challenges the core and shoulders.\"},{\"id\":\"1429\",\"n\":\"wide grip pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.\",\"Engage your core and squeeze your shoulder blades together.\",\"Pull your body up towards the bar until your chin is above the bar.\",\"Lower your body back down to the starting position with control.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1429.webp\",\"gif\":\"1429.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up on a wide overhand grip, pulling your chin above the bar. It targets the lats and upper back.\",\"fv\":\"3627\"},{\"id\":\"1367\",\"n\":\"wide grip rear pull-up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\"],\"st\":[\"Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.\",\"Hang from the bar with your arms fully extended and your body straight.\",\"Engage your back muscles and pull your body up towards the bar, leading with your chest.\",\"Continue pulling until your chin is above the bar.\",\"Pause for a moment at the top, then slowly lower your body back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1367.webp\",\"gif\":\"1367.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up on a wide overhand grip, pulling to the back of your neck or upper chest. It targets the lats and upper back.\",\"fv\":\"3628\"},{\"id\":\"1311\",\"n\":\"wide hand push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Start in a high plank position with your hands wider than shoulder-width apart.\",\"Keep your body in a straight line from head to toe.\",\"Lower your chest towards the ground by bending your elbows, keeping them close to your sides.\",\"Push through your palms to extend your arms and return to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"1311.webp\",\"gif\":\"1311.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands placed wider than your shoulders. It puts more emphasis on the chest and less on the triceps.\",\"fv\":\"4037\"},{\"id\":\"2363\",\"n\":\"wide-grip chest dip on high parallel bars\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.\",\"Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.\",\"Pause for a moment, then push yourself back up to the starting position by straightening your arms.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"2363.webp\",\"gif\":\"2363.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide-grip dip on high parallel bars, leaning forward. Targets the chest and shoulders.\"},{\"id\":\"0858\",\"n\":\"wind sprints\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Find an open space or a track to perform the exercise.\",\"Start by standing with your feet shoulder-width apart.\",\"Begin running as fast as you can, pumping your arms and driving your knees up.\",\"Continue sprinting for a specific distance or time period.\",\"Rest and repeat for the desired number of repetitions.\"],\"img\":\"0858.webp\",\"gif\":\"0858.mp4\",\"cat\":\"cardio\",\"desc\":\"Short, all-out runs followed by rest. They build speed, stamina and a strong cardio base.\"},{\"id\":\"1604\",\"n\":\"world greatest stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Start in a lunge position with your right foot forward and your left foot back.\",\"Place your hands on the ground on either side of your right foot.\",\"Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.\",\"Rotate your torso to the right, reaching your right arm up towards the ceiling.\",\"Hold this position for a few seconds, then return to the starting position.\",\"Switch sides and repeat the stretch with your left foot forward.\"],\"img\":\"1604.webp\",\"gif\":\"1604.mp4\",\"cat\":\"mobility\",\"desc\":\"A flowing lunge with a twist and reach that opens the hips, hamstrings and upper back. A favorite warm-up move.\"},{\"id\":\"1428\",\"n\":\"wrist circles\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrists\"],\"st\":[\"Extend your arms straight out in front of you.\",\"Make a fist with both hands.\",\"Rotate your wrists in a circular motion, keeping your arms still.\",\"Continue the wrist circles for the desired number of repetitions.\"],\"img\":\"1428.webp\",\"gif\":\"1428.mp4\",\"cat\":\"mobility\",\"desc\":\"Hold your arms out and move your wrists in slow circles. It warms up the wrist joints and forearm muscles.\",\"fv\":\"4323\"},{\"id\":\"0859\",\"n\":\"wrist rollerer\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\"],\"st\":[\"Attach a weight to one end of a rope or bar.\",\"Hold the other end of the rope or bar with both hands, palms facing down.\",\"Stand with your feet shoulder-width apart and your arms fully extended in front of you.\",\"Slowly roll the weight up towards your hands by flexing your wrists.\",\"Pause for a moment at the top, then slowly lower the weight back down to the starting position.\",\"Repeat for the desired number of repetitions.\"],\"img\":\"0859.webp\",\"gif\":\"0859.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist roller that winds a weight up on a rope or bar by turning the wrists. It builds the forearms and grip.\"},{\"id\":\"5965\",\"n\":\"1 2 stick drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand in an athletic stance with knees slightly bent.\",\"Take quick steps in the set pattern, one then two.\",\"Stay on the balls of your feet.\",\"Keep your arms bent and swinging naturally.\",\"Repeat for 20-30 seconds with sharp, light steps.\"],\"img\":\"5965.webp\",\"gif\":\"5965.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick footwork drill that builds agility and coordination with fast, light steps.\"},{\"id\":\"4209\",\"n\":\"1 to 2 jump box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a sturdy box on one leg.\",\"Drive your arms up and push off explosively from that leg.\",\"Land softly on the box with both feet at once.\",\"Stand fully upright before stepping down.\",\"Complete your reps, then switch legs.\",\"Keep your knees tracking over your toes.\"],\"img\":\"4209.webp\",\"gif\":\"4209.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Push off with one leg to land on a box with both feet. It trains explosive single-leg power and a stable landing.\"},{\"id\":\"5984\",\"n\":\"123 back drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Set a cone line a few yards apart.\",\"Sprint to the first cone and touch it, then back to the start.\",\"Sprint to the second cone and back.\",\"Go to the third cone and back.\",\"Stay low when turning.\",\"Rest, then repeat.\"],\"img\":\"5984.webp\",\"gif\":\"5984.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A cone drill with a set number of steps forward and back to sharpen speed and quick direction changes.\"},{\"id\":\"4208\",\"n\":\"2 to 1 jump box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a sturdy box with your feet shoulder-width apart.\",\"Swing your arms and jump up, landing softly on the box with both feet.\",\"Stand tall on top of the box.\",\"Step down with one leg first, then the other.\",\"Reset and repeat, alternating the leading leg.\",\"Land quietly with bent knees.\"],\"img\":\"4208.webp\",\"gif\":\"4208.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jump up onto a box with both feet and step or drop down with one. It builds explosive leg power and single-leg control.\"},{\"id\":\"5915\",\"n\":\"3 leg chaturanga pose\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\",\"glutes\"],\"st\":[\"Start in a high plank and lift one leg behind you.\",\"Keep your hips level.\",\"Bend your elbows back and lower.\",\"Hold briefly with your body in line.\",\"Press up, lower the leg and switch.\"],\"img\":\"5915.webp\",\"gif\":\"5915.mp4\",\"cat\":\"yoga\",\"desc\":\"A low plank with one leg lifted. Adds a balance challenge to the arms and core.\"},{\"id\":\"5887\",\"n\":\"3 leg dog pose\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"calves\",\"glutes\",\"core\"],\"st\":[\"Start in downward dog with hands shoulder-width apart.\",\"Press your hands into the floor and lengthen your spine.\",\"Lift one leg straight up behind you, keeping your hips square.\",\"Hold for 5 slow breaths.\",\"Lower and switch legs.\"],\"img\":\"5887.webp\",\"gif\":\"5887.mp4\",\"cat\":\"yoga\",\"desc\":\"Downward dog with one leg lifted behind you. Stretches the back of the legs while building shoulder and hip stability.\"},{\"id\":\"9066\",\"n\":\"4 way single leg hop\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"ankles\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Hop forward and land softly.\",\"Hop back to the start, then hop to each side.\",\"Hold each landing for a moment.\",\"Keep your chest up and your knee over your foot.\",\"Repeat the pattern, then switch legs.\"],\"img\":\"9066.webp\",\"gif\":\"9066.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Hopping on one leg forward, back and side to side trains balance, ankle stability and power.\"},{\"id\":\"10818\",\"n\":\"4 way single leg hop v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\",\"ankles\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Hop forward and land softly.\",\"Hop back to the start, then out to the side and back.\",\"Hop in the fourth direction.\",\"Stick every landing.\",\"Switch legs.\"],\"img\":\"10818.webp\",\"gif\":\"10818.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A balance hop on one leg in four directions. It trains power, balance and ankle stability.\"},{\"id\":\"5265\",\"n\":\"45 degree bicycle twisting crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit and lean back to about 45 degrees with your feet raised.\",\"Place your hands behind your head.\",\"Bring one knee in as you twist the opposite elbow toward it.\",\"Alternate sides in a pedalling motion.\",\"Keep your chest lifted and your core tight.\"],\"img\":\"5265.webp\",\"gif\":\"5265.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A twisting bicycle crunch with the torso leaning back at 45 degrees. It strongly targets the abs and obliques.\",\"fv\":\"1185\"},{\"id\":\"4937\",\"n\":\"45 degree hip extension glute focused\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Set up on a 45 degree bench with your ankles locked.\",\"Cross your arms over your chest and round your upper back slightly.\",\"Lower your torso by hinging at the hips.\",\"Squeeze the glutes to raise back up.\",\"Stop when your body is in a straight line.\",\"Avoid overarching your lower back.\"],\"img\":\"4937.webp\",\"gif\":\"4937.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip extension on a 45 degree bench with a rounded upper back. This shifts the focus onto the glutes.\"},{\"id\":\"9314\",\"n\":\"45 degree hip extension glute focused v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Set the pad at hip height and lock your heels in.\",\"Cross your arms over your chest.\",\"Hinge forward at the hips with a straight back.\",\"Drive your hips forward and squeeze your glutes.\",\"Stop when your body is in a straight line.\",\"Lower slowly each rep.\"],\"img\":\"9314.webp\",\"gif\":\"9314.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip extension on a 45 degree bench that emphasises the glutes. It strengthens the posterior chain.\"},{\"id\":\"5813\",\"n\":\"45 degree hyperextension (arms in front of chest)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set the pad at hip height and hook your heels under the rollers.\",\"Cross your arms over your chest.\",\"Lower your torso with a straight back.\",\"Raise yourself until your body forms a straight line.\",\"Squeeze your glutes at the top and lower slowly.\"],\"img\":\"5813.webp\",\"gif\":\"5813.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A back extension on a 45 degree bench with arms crossed at the chest. It strengthens the lower back and glutes.\",\"fv\":\"0877\"},{\"id\":\"1465\",\"n\":\"45 degree hyperextension (arms in front of chest) (side pov)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set the pad at hip height and hook your heels under the roller.\",\"Cross your arms over your chest and keep your body straight.\",\"Lower your torso with a flat back until you feel a hamstring stretch.\",\"Raise back up until your body is in line, without overarching.\",\"Move slowly and squeeze your glutes at the top.\"],\"img\":\"1465.webp\",\"gif\":\"1465.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A back extension on a 45 degree bench viewed from the side, targeting the lower back, glutes and hamstrings.\"},{\"id\":\"1170\",\"n\":\"45 degree one leg hyperextension (arms in front of chest)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Set the pad under your hips and hook one foot under the roller, with the other leg lifted off.\",\"Cross your arms over your chest and keep your body in a straight line.\",\"Lower your torso toward the floor with a flat back.\",\"Raise back up by squeezing your glute until your body is level, without overarching.\",\"Complete all reps, then switch legs.\"],\"img\":\"1170.webp\",\"gif\":\"1170.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg back extension on a 45 degree bench that trains the glutes, hamstrings and lower back one side at a time.\"},{\"id\":\"1171\",\"n\":\"45 degree twisting hyperextension\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"obliques\"],\"st\":[\"Position yourself on the bench with your ankles under the pads and your hips just off the edge.\",\"Cross your arms over your chest and lower your torso with a flat back.\",\"Raise your torso back up, squeezing your glutes.\",\"At the top, rotate your upper body gently to one side, then return to center.\",\"Alternate sides each rep and keep the movement slow and controlled.\"],\"img\":\"1171.webp\",\"gif\":\"1171.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A back extension on a 45 degree bench with a rotation at the top that adds work for the obliques and lower back.\"},{\"id\":\"4455\",\"n\":\"45 degrees back extension\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Set the pad at hip level and hook your heels under the rollers.\",\"Cross your arms over your chest or hold them behind your head.\",\"Lower your torso with a straight spine until you feel a hamstring stretch.\",\"Raise your torso by squeezing your glutes and lower back.\",\"Stop when your body forms a straight line.\",\"Avoid over-arching at the top.\"],\"img\":\"4455.webp\",\"gif\":\"4455.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A back extension on an angled bench that strengthens the lower back and glutes. Hinging at the hips keeps the movement safe and smooth.\"},{\"id\":\"8895\",\"n\":\"45 degrees back extension scapular adduction\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"glutes\",\"hamstrings\"],\"st\":[\"Set up on the 45 degree bench with your hips on the pad and your feet locked in.\",\"Cross your arms or hold them out wide.\",\"Raise your torso until your body forms a straight line.\",\"At the top, pull your shoulder blades together.\",\"Lower back down slowly without rounding.\",\"Do not overarch at the top.\"],\"img\":\"8895.webp\",\"gif\":\"8895.mp4\",\"cat\":\"calisthenics\",\"desc\":\"On a 45 degree bench you lift your torso and pull your shoulder blades together. It works the lower back and upper back at once.\"},{\"id\":\"5699\",\"n\":\"45 degrees side bend\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Set up on a 45 degree bench, lying on your side with your feet anchored.\",\"Cross your arms over your chest.\",\"Lower your upper body toward the floor.\",\"Bend up sideways by contracting your oblique.\",\"Finish all reps, then switch sides.\"],\"img\":\"5699.webp\",\"gif\":\"5699.mp4\",\"cat\":\"strength\",\"desc\":\"A side bend done on a 45 degree bench that trains the obliques through a long range of motion.\",\"fv\":\"2435\"},{\"id\":\"4007\",\"n\":\"90 degree heel touch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie with your legs up and knees bent at 90 degrees.\",\"Lift your shoulders.\",\"Reach one hand toward the heel.\",\"Switch sides.\",\"Keep your legs still.\"],\"img\":\"4007.webp\",\"gif\":\"4007.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lie with legs raised and reach toward your heels. It works the abs and obliques.\"},{\"id\":\"6428\",\"n\":\"90 degree heel touch v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Lift your shoulders slightly off the floor.\",\"Reach your right hand toward your right heel.\",\"Switch and reach your left hand to your left heel.\",\"Keep your core tight and continue alternating.\"],\"img\":\"6428.webp\",\"gif\":\"6428.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back with your knees bent, you reach side to side to tap your heels, working your obliques.\"},{\"id\":\"10565\",\"n\":\"90 to 90 press stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"lower back\"],\"st\":[\"Sit on the floor with both knees bent at 90 degrees, one leg in front, one to the side.\",\"Sit tall.\",\"Hinge forward over the front shin with a flat back.\",\"Hold for 20-30 seconds.\",\"Switch sides and repeat.\"],\"img\":\"10565.webp\",\"gif\":\"10565.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit in a 90-degree hip position and press forward to stretch the glutes and hips. It improves hip rotation.\"},{\"id\":\"6560\",\"n\":\"90 to 90 stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"lower back\"],\"st\":[\"Sit on the floor with one leg bent in front and the other bent out to the side, both at about 90 degrees.\",\"Sit tall with your hands on the floor.\",\"Hinge forward over the front shin until you feel a stretch in the hip.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Come back up slowly.\",\"Switch sides.\"],\"img\":\"6560.webp\",\"gif\":\"6560.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated hip stretch with both legs bent at right angles. It loosens the hip rotators and the glutes.\"},{\"id\":\"6555\",\"n\":\"ab mat sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie back on an ab mat with knees bent and feet flat.\",\"Cross your arms over your chest or place your hands by your ears.\",\"Curl your torso up until you are sitting tall.\",\"Pause briefly at the top.\",\"Lower back down slowly.\",\"Avoid pulling on your neck.\"],\"img\":\"6555.webp\",\"gif\":\"6555.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up on a shaped ab mat that supports the lower back and allows a fuller range of motion.\"},{\"id\":\"2269\",\"n\":\"ab roller crunch\",\"bp\":\"waist\",\"eq\":\"wheel roller\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"shoulders\"],\"st\":[\"Kneel on a mat and hold the ab wheel with both hands in front of your knees.\",\"Round your lower back slightly and brace your abs.\",\"Roll forward a short distance while keeping your hips stable.\",\"Pull the wheel back toward your knees by curling your ribs toward your hips.\",\"Exhale as you crunch and avoid arching your back.\",\"Repeat with smooth control.\"],\"img\":\"2269.webp\",\"gif\":\"2269.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch done with an ab wheel that works the abdominal wall through a compact range.\"},{\"id\":\"6033\",\"n\":\"ab tuck\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Sit on the floor and lean back slightly.\",\"Extend your legs in front of you.\",\"Pull your knees to your chest as you bring your torso forward.\",\"Extend again under control.\",\"Keep your core braced.\"],\"img\":\"6033.webp\",\"gif\":\"6033.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated or lying tuck that draws knees and chest together to train the abs.\"},{\"id\":\"4348\",\"n\":\"abdominal 4 points\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hip flexors\"],\"st\":[\"Start on hands and knees with wrists under shoulders and knees under hips.\",\"Keep your back flat and neck neutral.\",\"Draw your belly button toward your spine.\",\"Hold for 15-30 seconds while breathing normally.\",\"Relax and repeat.\"],\"img\":\"4348.webp\",\"gif\":\"4348.mp4\",\"cat\":\"isometric\",\"desc\":\"A four-point hold on hands and knees where you engage the abs. A gentle way to learn core bracing.\",\"hd\":1},{\"id\":\"3244\",\"n\":\"abdominal stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"chest\"],\"st\":[\"Lie face down with hands under your shoulders.\",\"Press up, lifting your chest.\",\"Keep your hips on the floor.\",\"Look straight ahead and relax.\",\"Hold for 20-30 seconds.\"],\"img\":\"3244.webp\",\"gif\":\"3244.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch lengthening the front of the trunk and the abs.\"},{\"id\":\"1906\",\"n\":\"abduction of one leg flexion stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"hip flexors\"],\"st\":[\"Lie on your back with your legs straight.\",\"Bend one knee, let it fall out to the side and, if needed, ease it down with your hand until the inner thigh stretches.\",\"Keep your lower back and the opposite hip flat on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1906.webp\",\"gif\":\"1906.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back, you open one leg out to the side to stretch the inner thigh and groin.\"},{\"id\":\"1777\",\"n\":\"above head chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall and interlace your fingers, then raise your arms overhead.\",\"Press your arms slightly back and lift your chest without arching your lower back.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1777.webp\",\"gif\":\"1777.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching both arms overhead and back opens the front of your chest and shoulders. It is an easy stretch to undo hunched posture.\",\"fv\":\"4514\"},{\"id\":\"1980\",\"n\":\"across chest shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\"],\"st\":[\"Stand tall and bring one arm straight across your chest.\",\"Use your other forearm to press the arm gently toward your body.\",\"Keep the shoulder relaxed and down.\",\"Feel the stretch in the back of the shoulder.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1980.webp\",\"gif\":\"1980.mp4\",\"cat\":\"stretching\",\"desc\":\"A classic cross-body stretch for the back of the shoulder.\"},{\"id\":\"2098\",\"n\":\"adduction hand with elbow extended stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Stand tall and extend one arm in front of you with the elbow straight.\",\"Turn the palm so the thumb points up.\",\"Grab the hand with your other hand and tilt it gently toward the little finger side.\",\"Keep the elbow locked and the shoulder down.\",\"Hold for 20-30 seconds.\",\"Release and repeat on the other arm.\"],\"img\":\"2098.webp\",\"gif\":\"2098.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilts the hand sideways at the wrist with a straight elbow to stretch the forearm muscles along the outer edge of the arm.\"},{\"id\":\"1977\",\"n\":\"adduction of arm in back stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand or sit tall.\",\"Reach one arm behind your back.\",\"Grab that wrist with the other hand and gently pull it across your body.\",\"Keep your shoulders level.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1977.webp\",\"gif\":\"1977.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching one arm behind your back and pulling it across to stretch the shoulder.\"},{\"id\":\"4512\",\"n\":\"adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Sit on the floor with the soles of your feet together.\",\"Hold your ankles and sit tall.\",\"Let your knees fall out to the sides.\",\"Gently press your elbows on your thighs.\",\"Hold for 20-30 seconds.\",\"Release slowly.\"],\"img\":\"4512.webp\",\"gif\":\"4512.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch for the inner thighs. Improves hip flexibility.\",\"fv\":\"0936\"},{\"id\":\"5967\",\"n\":\"agility ball drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Set up with a ball in front of you in an athletic stance.\",\"Move quickly around or over the ball with short, light steps.\",\"Keep your hips low and eyes up.\",\"Change direction without crossing your feet.\",\"Work for 20-30 seconds, rest, then repeat.\"],\"img\":\"5967.webp\",\"gif\":\"5967.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A footwork and reaction drill with a ball that sharpens agility, balance and quick direction changes.\"},{\"id\":\"2395\",\"n\":\"air bike v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with your hands behind your head.\",\"Lift your shoulders and bring your knees up.\",\"Bring one elbow toward the opposite knee while extending the other leg.\",\"Switch sides in a smooth pedalling motion.\",\"Keep your lower back pressed down.\",\"Continue for the planned reps or time.\"],\"img\":\"2395.webp\",\"gif\":\"2395.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bicycle crunch variation that trains the abs and obliques through alternating twists.\"},{\"id\":\"3948\",\"n\":\"air squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Reach your arms forward for balance.\",\"Sit your hips back and down until your thighs are parallel.\",\"Keep your chest up.\",\"Drive through your feet to stand.\"],\"img\":\"3948.webp\",\"gif\":\"3948.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A basic bodyweight squat that builds leg strength and mobility.\"},{\"id\":\"4714\",\"n\":\"air squat (version 2)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart, toes slightly out.\",\"Push your hips back and bend your knees.\",\"Lower until thighs are at least parallel with chest up.\",\"Drive through your heels to stand.\",\"Keep your knees tracking over your toes.\"],\"img\":\"4714.webp\",\"gif\":\"4714.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A basic bodyweight squat that trains the legs and hips and builds a solid movement pattern.\"},{\"id\":\"5266\",\"n\":\"air twisting crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees raised.\",\"Place your hands behind your head.\",\"Lift your shoulders and twist toward one knee.\",\"Return and twist toward the other side.\",\"Keep a slow rhythm and press your lower back down.\"],\"img\":\"5266.webp\",\"gif\":\"5266.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A twisting crunch with the legs held in the air. It works your abs and obliques.\",\"fv\":\"0004\"},{\"id\":\"3479\",\"n\":\"alternate heel touch side kick squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand with feet hip-width apart.\",\"Squat down.\",\"Stand and kick one leg to the side.\",\"Touch the heel with your hand.\",\"Squat again.\",\"Alternate sides.\"],\"img\":\"3479.webp\",\"gif\":\"3479.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat that adds a side kick and a heel touch for legs and coordination.\"},{\"id\":\"4918\",\"n\":\"alternate high hop\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"glutes\"],\"st\":[\"Stand tall with your arms ready to swing.\",\"Hop off one foot and drive the opposite knee up.\",\"Land softly on the ball of your foot.\",\"Switch legs on the next hop.\",\"Swing your arms in rhythm with your legs.\",\"Keep a quick, bouncy pace.\"],\"img\":\"4918.webp\",\"gif\":\"4918.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Springy hops from one foot to the other with a high knee. It raises your heart rate and trains leg power.\"},{\"id\":\"4826\",\"n\":\"alternate leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie flat on your back with your legs straight and arms at your sides.\",\"Press your lower back into the floor.\",\"Raise one leg up toward the ceiling.\",\"Lower it slowly while lifting the other leg.\",\"Keep alternating without arching your back.\"],\"img\":\"4826.webp\",\"gif\":\"4826.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you raise one leg at a time. It works the lower abs and hip flexors.\",\"fv\":\"1613\"},{\"id\":\"4001\",\"n\":\"alternate leg raise with head up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with your head slightly lifted.\",\"Raise one leg to vertical.\",\"Lower it without touching the floor.\",\"Raise the other leg.\",\"Keep your lower back pressed down.\"],\"img\":\"4001.webp\",\"gif\":\"4001.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise one leg at a time while lying with your head lifted. It works the lower abs.\"},{\"id\":\"3590\",\"n\":\"alternate lying floor leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with legs straight and arms at your sides.\",\"Press your lower back into the floor.\",\"Raise one leg to about 90 degrees.\",\"Lower it slowly and lift the other leg.\",\"Alternate without arching your back.\"],\"img\":\"3590.webp\",\"gif\":\"3590.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise one leg at a time while lying on the floor, working the lower abs.\",\"fv\":\"0008\"},{\"id\":\"4354\",\"n\":\"alternate oblique crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Lift your shoulders off the floor.\",\"Twist and bring one elbow toward the opposite knee.\",\"Return to center and switch sides.\",\"Move slowly and avoid pulling on your neck.\"],\"img\":\"4354.webp\",\"gif\":\"4354.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch that alternates elbow-to-knee across the body, hitting the obliques.\"},{\"id\":\"3531\",\"n\":\"alternate punching\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\",\"obliques\"],\"st\":[\"Stand with a staggered stance and fists up.\",\"Punch forward with one arm, rotating your torso slightly.\",\"Pull it back as you punch with the other.\",\"Keep your core tight.\",\"Keep a steady rhythm for 30-60 seconds.\",\"Rest briefly and repeat.\"],\"img\":\"3531.webp\",\"gif\":\"3531.mp4\",\"cat\":\"cardio\",\"desc\":\"Alternating punches at a steady pace to raise the heart rate.\",\"fv\":\"3802\"},{\"id\":\"4394\",\"n\":\"alternate shoulder flexion back to wall\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"upper back\",\"core\"],\"st\":[\"Stand with your back, head and hips against a wall.\",\"Keep your ribs down and your lower back near the wall.\",\"Raise one arm forward and overhead as far as you can without arching.\",\"Lower it with control.\",\"Alternate arms for the set.\"],\"img\":\"4394.webp\",\"gif\":\"4394.mp4\",\"cat\":\"mobility\",\"desc\":\"A wall-supported drill to improve overhead reach, one arm at a time, while keeping the back flat against the wall.\"},{\"id\":\"3480\",\"n\":\"alternate sprinter lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall.\",\"Step back into a deep lunge.\",\"Drive your arms like a sprinter.\",\"Push back to standing.\",\"Alternate legs.\",\"Keep your torso upright.\"],\"img\":\"3480.webp\",\"gif\":\"3480.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge with a sprint-style arm drive and alternating legs.\"},{\"id\":\"1186\",\"n\":\"alternate straight leg raise (on bosu ball)\",\"bp\":\"waist\",\"eq\":\"bosu ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie back on a bosu ball with your lower back supported and your hands holding it lightly.\",\"Brace your abs and extend both legs.\",\"Raise one leg while keeping it straight.\",\"Lower it and switch to the other leg.\",\"Keep your torso steady and move with control.\"],\"img\":\"1186.webp\",\"gif\":\"1186.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg raise on a bosu ball that adds an unstable surface to challenge the lower abs and balance.\"},{\"id\":\"5106\",\"n\":\"alternate toe tap leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with both legs raised straight up.\",\"Press your lower back into the floor.\",\"Reach one leg up so your toes tap toward the ceiling.\",\"Alternate legs with control.\",\"Keep your core tight and breathe steadily.\"],\"img\":\"5106.webp\",\"gif\":\"5106.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on your back and tap each toe up toward the ceiling in turn. It targets the lower abs.\"},{\"id\":\"10438\",\"n\":\"alternating dead hang\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"grip muscles\",\"shoulders\",\"core\"],\"st\":[\"Grab a pull-up bar with an overhand grip, hands about shoulder width apart.\",\"Hang with your arms long and your body relaxed.\",\"Shift your weight toward one hand, letting that side stretch.\",\"Shift to the other side and keep alternating.\",\"Hold the hang for 20-30 seconds in total.\"],\"img\":\"10438.webp\",\"gif\":\"10438.mp4\",\"cat\":\"stretching\",\"desc\":\"Hang from a bar and shift your weight from side to side. It decompresses the shoulders and stretches the lats.\"},{\"id\":\"4437\",\"n\":\"alternating hamstring curl with punches\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Stand tall with your fists in front of your chin.\",\"Curl one heel up toward your glute.\",\"Punch forward as you curl the leg.\",\"Lower the leg and repeat on the other side.\",\"Keep a steady rhythm and stay light on your feet.\"],\"img\":\"4437.webp\",\"gif\":\"4437.mp4\",\"cat\":\"cardio\",\"desc\":\"A cardio combination of heel-to-glute kicks and punches that works the hamstrings and arms together.\"},{\"id\":\"10058\",\"n\":\"alternating kneeling to half kneeling\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"core\"],\"st\":[\"Kneel upright with both knees on the floor.\",\"Step one foot forward into a half-kneeling position.\",\"Pause and keep your torso tall.\",\"Step back to full kneeling.\",\"Repeat with the other foot.\",\"Move slowly and use your arms for balance if needed.\"],\"img\":\"10058.webp\",\"gif\":\"10058.mp4\",\"cat\":\"mobility\",\"desc\":\"A floor-to-stand drill moving from kneeling to half kneeling, alternating sides. It builds hip mobility and control.\"},{\"id\":\"4436\",\"n\":\"alternating step out\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"core\"],\"st\":[\"Stand with feet together and hands in front of your chest.\",\"Step one foot out to the side.\",\"Bring it back and step the other foot out.\",\"Keep your knees slightly bent.\",\"Keep a steady rhythm for 30-60 seconds.\"],\"img\":\"4436.webp\",\"gif\":\"4436.mp4\",\"cat\":\"cardio\",\"desc\":\"A low-impact move stepping one leg out at a time, raising your heart rate while working the legs.\"},{\"id\":\"4702\",\"n\":\"alternating superman\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"hamstrings\"],\"st\":[\"Lie face down with arms extended in front.\",\"Lift one arm and the opposite leg together.\",\"Hold for a second.\",\"Lower and switch to the other side.\",\"Keep your neck neutral and move with control.\"],\"img\":\"4702.webp\",\"gif\":\"4702.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A face-down lift of opposite arm and leg to strengthen the lower back and glutes.\"},{\"id\":\"4715\",\"n\":\"alternating superman v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"hamstrings\"],\"st\":[\"Lie face down with arms extended overhead.\",\"Raise your right arm and left leg.\",\"Hold briefly and lower.\",\"Raise your left arm and right leg.\",\"Keep your neck neutral and move smoothly.\"],\"img\":\"4715.webp\",\"gif\":\"4715.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lifting opposite arm and leg while face down to strengthen the lower back and glutes.\"},{\"id\":\"4365\",\"n\":\"animal resting yoga pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"hip flexors\"],\"st\":[\"Kneel on a mat and sit back toward your heels.\",\"Fold forward and stretch your arms ahead.\",\"Rest your forehead on the floor.\",\"Breathe deeply and hold for 30-60 seconds.\",\"Release slowly.\"],\"img\":\"4365.webp\",\"gif\":\"4365.mp4\",\"cat\":\"yoga\",\"desc\":\"A resting yoga pose that gently stretches the back and hips, similar to child pose.\"},{\"id\":\"2761\",\"n\":\"ankle dorsal flexion\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Sit with one leg out and your heel resting on the floor.\",\"Pull your toes and the top of your foot toward your shin as far as is comfortable.\",\"Pause briefly, then lower the foot back down slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2761.webp\",\"gif\":\"2761.mp4\",\"cat\":\"mobility\",\"desc\":\"Pulling the toes up toward the shin, working the front of the lower leg. A simple way to keep the ankle moving well.\"},{\"id\":\"2762\",\"n\":\"ankle plantar flexion\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Sit with one leg out and your foot relaxed.\",\"Point your toes down and away from you, as if pressing a gas pedal.\",\"Pause briefly at the end, then return to the neutral position.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2762.webp\",\"gif\":\"2762.mp4\",\"cat\":\"mobility\",\"desc\":\"Pointing the foot away from the shin, engaging the calf. Good for warming up and mobilising the ankle.\"},{\"id\":\"10729\",\"n\":\"aquabike\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand in chest-deep water, holding the pool edge.\",\"Lift your knees alternately.\",\"Pedal at a steady rhythm.\",\"Keep your core tight.\",\"Continue for several minutes.\"],\"img\":\"10729.webp\",\"gif\":\"10729.mp4\",\"cat\":\"cardio\",\"desc\":\"Pedal your legs in the water as if cycling. It raises your heart rate with low impact.\"},{\"id\":\"6121\",\"n\":\"ardha matsyendrasana yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hip flexors\"],\"st\":[\"Sit tall with your legs extended.\",\"Bend one knee and place that foot outside the opposite thigh.\",\"Hug the bent knee with the opposite arm.\",\"Place your other hand behind you and twist toward it.\",\"Lengthen the spine and hold for 20-30 seconds.\",\"Release and repeat on the other side.\"],\"img\":\"6121.webp\",\"gif\":\"6121.mp4\",\"cat\":\"yoga\",\"desc\":\"The half spinal twist, a seated yoga pose. It stretches the spine and outer hip and improves rotation.\"},{\"id\":\"3905\",\"n\":\"arm circles\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"trapezius\",\"upper back\"],\"st\":[\"Stand tall with your arms out to the sides at shoulder height.\",\"Make small circles forward.\",\"Gradually make the circles larger.\",\"Do 10 to 15 circles, then reverse direction.\",\"Keep your shoulders relaxed.\",\"Breathe normally.\"],\"img\":\"3905.webp\",\"gif\":\"3905.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple warm-up that loosens the shoulder joints by moving the arms in circles.\"},{\"id\":\"5172\",\"n\":\"arm crossover\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall with your arms out to the sides at shoulder height.\",\"Swing both arms forward and cross them in front of your chest.\",\"Open them back out and squeeze your shoulder blades slightly.\",\"Alternate which arm is on top.\",\"Keep a steady, relaxed rhythm.\"],\"img\":\"5172.webp\",\"gif\":\"5172.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic arm swing across the chest that warms up the pecs and shoulders.\",\"fv\":\"4664\"},{\"id\":\"1987\",\"n\":\"arm down rotator stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Stand tall and place one arm behind your back, bent at the elbow.\",\"Hold the wrist with the other hand.\",\"Gently draw the hand away from your body and slightly up.\",\"Keep your shoulders relaxed.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1987.webp\",\"gif\":\"1987.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the rotator cuff with the arm held low behind the body.\"},{\"id\":\"6014\",\"n\":\"arm raise step in place\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"quadriceps\",\"calves\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Step in place, lifting your knees.\",\"Raise your arms overhead as you step.\",\"Lower them as you continue.\",\"Keep a steady rhythm for 30-60 seconds.\"],\"img\":\"6014.webp\",\"gif\":\"6014.mp4\",\"cat\":\"cardio\",\"desc\":\"Stepping in place while raising your arms, a gentle cardio drill.\",\"fv\":\"6015\"},{\"id\":\"1986\",\"n\":\"arm up rotator stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"triceps\"],\"st\":[\"Raise one arm overhead and bend the elbow, palm resting on your upper back.\",\"Use your other hand to hold the elbow.\",\"Gently press the elbow back and down.\",\"Keep your ribs down and chest open.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1986.webp\",\"gif\":\"1986.mp4\",\"cat\":\"stretching\",\"desc\":\"An overhead stretch for the rotator cuff and back of the arm.\"},{\"id\":\"6539\",\"n\":\"armless prayer stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lower back\"],\"st\":[\"Kneel on the floor and sit your hips back toward your heels.\",\"Reach your arms forward and lower your chest.\",\"Let your forehead rest near the floor.\",\"Relax your shoulders and breathe deeply.\",\"Hold for 20-30 seconds.\"],\"img\":\"6539.webp\",\"gif\":\"6539.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling stretch that opens up your shoulders and lats as you sink your chest toward the floor.\"},{\"id\":\"1817\",\"n\":\"arms stretch on a support\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\",\"chest\"],\"st\":[\"Place your hands or forearms on a bench or other stable support behind you.\",\"Lower your body slightly and lean away until you feel a stretch in the front of your arms.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1817.webp\",\"gif\":\"1817.mp4\",\"cat\":\"stretching\",\"desc\":\"Resting your arms on a support and sinking down stretches the biceps and front of the shoulders. The support does part of the work for you.\"},{\"id\":\"4935\",\"n\":\"around the world superman\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"hamstrings\"],\"st\":[\"Lie face down with your arms extended overhead.\",\"Lift your chest, arms and legs off the floor.\",\"Sweep your arms out to the sides toward your hips.\",\"Return them overhead in a wide arc.\",\"Keep your legs lifted.\",\"Lower to the floor to rest.\"],\"img\":\"4935.webp\",\"gif\":\"4935.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A superman hold where the arms sweep in a circle. It works the lower back, glutes and shoulders.\"},{\"id\":\"3483\",\"n\":\"around the world superman hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hamstrings\",\"rear deltoids\",\"core\"],\"st\":[\"Lie face down with your arms extended overhead and legs straight.\",\"Lift your arms, chest and legs a few centimetres off the floor.\",\"Sweep your arms out to the sides and down toward your hips in a wide arc.\",\"Sweep them back overhead along the same path.\",\"Keep your neck neutral and legs lifted throughout.\",\"Lower down with control after your set.\"],\"img\":\"3483.webp\",\"gif\":\"3483.mp4\",\"cat\":\"isometric\",\"desc\":\"A face-down superman hold with the arms sweeping in a circle. It strengthens the glutes, lower back and rear shoulders.\"},{\"id\":\"3893\",\"n\":\"assault bike run\",\"bp\":\"cardio\",\"eq\":\"stationary bike\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Adjust the seat height and sit on the bike.\",\"Grip the handles and push and pull with your arms.\",\"Pedal at a steady, strong pace.\",\"Increase the effort for intervals.\",\"Keep your breathing controlled.\",\"Ride for a set time or distance.\"],\"img\":\"3893.webp\",\"gif\":\"3893.mp4\",\"cat\":\"cardio\",\"desc\":\"A hard-effort ride on an air bike that gets your heart rate up and trains the legs and arms.\"},{\"id\":\"4229\",\"n\":\"assault run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Step onto the curved treadmill and hold the handles.\",\"Lean slightly forward and begin to run.\",\"Drive your knees and push the belt back with each stride.\",\"Keep a steady rhythm, or alternate sprints and rest.\",\"Land on the balls of your feet.\",\"Slow down gradually to finish.\"],\"img\":\"4229.webp\",\"gif\":\"4229.mp4\",\"cat\":\"cardio\",\"desc\":\"A run on a self-powered curved treadmill where your effort sets the speed. It is a hard cardio workout for the legs and lungs.\"},{\"id\":\"4442\",\"n\":\"assisted bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand facing away from a bench and hold a sturdy post or rack with one hand for balance.\",\"Place the top of your rear foot on a bench behind you.\",\"Step your front foot far enough forward to stay balanced.\",\"Lower straight down until your front thigh is about parallel to the floor.\",\"Keep your torso upright and your front knee tracking over your toes.\",\"Drive through the front heel to stand, then switch legs after your set.\"],\"img\":\"4442.webp\",\"gif\":\"4442.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat with the rear foot raised on a bench and a hand lightly holding a support for balance. Trains quads and glutes with less wobble.\"},{\"id\":\"3150\",\"n\":\"assisted chin tuck\",\"bp\":\"neck\",\"eq\":\"assisted\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\",\"trapezius\"],\"st\":[\"Sit or stand tall with your eyes level.\",\"Place two fingers on your chin.\",\"Gently guide your chin straight back.\",\"Keep your head level and your shoulders relaxed.\",\"Hold for 3-5 seconds.\",\"Release and repeat 8-10 times.\"],\"img\":\"3150.webp\",\"gif\":\"3150.mp4\",\"cat\":\"mobility\",\"desc\":\"A chin tuck with light help from your hand to guide the movement and feel the right position.\",\"fv\":\"3152\"},{\"id\":\"4716\",\"n\":\"assisted chin up (low bar position)\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Set a bar at about chest height and sit or lie beneath it.\",\"Grip the bar with palms facing you.\",\"Pull your chest toward the bar using your arms and back.\",\"Use your legs only as much as needed.\",\"Lower with control.\"],\"img\":\"4716.webp\",\"gif\":\"4716.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up from a low bar with your feet helping, a stepping stone toward full chin-ups.\"},{\"id\":\"4970\",\"n\":\"assisted chin up (squat position)\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Grab a bar with an underhand grip.\",\"Bend your knees into a squat position.\",\"Pull your chest toward the bar.\",\"Use your legs only as much as you need.\",\"Lower slowly.\",\"Keep your shoulders down.\"],\"img\":\"4970.webp\",\"gif\":\"4970.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin up where you use your legs in a squat position to assist. It helps you build toward full chin ups.\"},{\"id\":\"1222\",\"n\":\"assisted close grip underhand chin up\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"upper back\"],\"st\":[\"Set the assistance weight and kneel or stand on the platform.\",\"Grip the bar with palms facing you, hands close together.\",\"Pull yourself up until your chin clears the bar.\",\"Squeeze your back and biceps at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"1222.webp\",\"gif\":\"1222.mp4\",\"cat\":\"strength\",\"desc\":\"A chin-up with machine assistance and a narrow underhand grip. It lets you build pulling strength with less bodyweight.\",\"fv\":\"2543\"},{\"id\":\"4717\",\"n\":\"assisted commando pull up\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"obliques\",\"forearms\"],\"st\":[\"Grip a bar with one hand in front of the other.\",\"Use a band or feet for assistance.\",\"Pull until your head passes the bar to one side.\",\"Lower with control.\",\"Switch the head side on the next rep.\"],\"img\":\"4717.webp\",\"gif\":\"4717.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with a neutral staggered grip and some help, building back and arm strength.\"},{\"id\":\"3415\",\"n\":\"assisted inverse leg curl\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Kneel with your ankles secured and your torso upright.\",\"Use the assistance as needed.\",\"Lean forward slowly, resisting with your hamstrings.\",\"Lower as far as you can control.\",\"Pull yourself back up with your hamstrings and hands if needed.\",\"Keep your hips extended.\"],\"img\":\"3415.webp\",\"gif\":\"3415.mp4\",\"cat\":\"strength\",\"desc\":\"A supported nordic-style curl where assistance lets you control the lowering for the hamstrings.\"},{\"id\":\"1907\",\"n\":\"assisted lying adductors stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Lie on your back with your legs straight.\",\"Have your partner lift one leg slightly and move it out to the side.\",\"Keep your hips level.\",\"Tell your partner to stop at a comfortable stretch.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1907.webp\",\"gif\":\"1907.mp4\",\"cat\":\"stretching\",\"desc\":\"Partner-assisted stretch for the inner thighs.\"},{\"id\":\"1923\",\"n\":\"assisted lying hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie on your back with your legs straight and relax completely.\",\"Have a partner lift one leg by the heel, keeping the knee straight.\",\"Tell your partner to stop when you feel a pull behind the thigh.\",\"Keep your other leg and lower back flat on the floor.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1923.webp\",\"gif\":\"1923.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner lifts your straight leg to deepen a relaxed hamstring stretch.\"},{\"id\":\"1932\",\"n\":\"assisted lying hip stretch in supine position\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie on your back with your legs straight and relax.\",\"Have a partner bring one knee slowly toward your chest.\",\"Tell them to stop when you feel a stretch in the hip and buttock.\",\"Keep the other leg flat on the floor.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1932.webp\",\"gif\":\"1932.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner guides your bent knee toward your chest to stretch the hips and glutes while you stay relaxed.\"},{\"id\":\"1715\",\"n\":\"assisted oblique and latissimus dorsi stretch on stability ball\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Lie sideways over a stability ball with your hips supported and one arm reaching overhead.\",\"Let your partner gently guide your reaching arm further while you roll slightly over the ball.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1715.webp\",\"gif\":\"1715.mp4\",\"cat\":\"stretching\",\"desc\":\"Draped over a stability ball with a partner helping, you lengthen the side of your trunk and your lats. It opens up the whole flank.\"},{\"id\":\"1711\",\"n\":\"assisted oblique glute minimus and medius stretch\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"abductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your back or side while your partner supports your top leg.\",\"Have your partner gently guide the leg across your body while you stay relaxed.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1711.webp\",\"gif\":\"1711.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner-assisted stretch for the outer hip and side of the trunk. It eases tightness in the small gluteal muscles and obliques.\"},{\"id\":\"2123\",\"n\":\"assisted obliques stretch\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"lower back\"],\"st\":[\"Stand upright with feet shoulder-width apart.\",\"Raise one arm overhead while your partner steadies your hips.\",\"Lean away from the raised arm while your partner gently guides your arm.\",\"Keep your chest open and avoid leaning forward.\",\"Hold for 20-30 seconds.\",\"Come back to upright and switch sides.\"],\"img\":\"2123.webp\",\"gif\":\"2123.mp4\",\"cat\":\"stretching\",\"desc\":\"With help from a partner, this stretch lengthens the oblique muscles on the side of the trunk through a slow bend or twist.\"},{\"id\":\"1952\",\"n\":\"assisted one leg extension\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\"],\"st\":[\"Lie on your back and relax.\",\"Have a partner support one leg and gently extend it.\",\"Let the partner move the leg only to a mild stretch.\",\"Keep your lower back flat on the floor.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1952.webp\",\"gif\":\"1952.mp4\",\"cat\":\"mobility\",\"desc\":\"A partner-assisted leg movement that gently stretches the hip and thigh.\"},{\"id\":\"3747\",\"n\":\"assisted pistol squat with bed sheet\",\"bp\":\"upper legs\",\"eq\":\"assisted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"ankles\"],\"st\":[\"Hold the ends of a bed sheet anchored to a door or post.\",\"Stand on one leg with the other leg extended forward.\",\"Sit down on your standing leg, using the sheet as support.\",\"Lower as far as you can control.\",\"Push up to stand and switch legs after your reps.\"],\"img\":\"3747.webp\",\"gif\":\"3747.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat where you hold a bed sheet anchored to something sturdy for assistance.\"},{\"id\":\"1790\",\"n\":\"assisted pulling arms in prone position chest stretch\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie face down with your arms out to the sides and your forehead resting on the floor.\",\"Have your partner hold your wrists and slowly lift your arms up and back.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1790.webp\",\"gif\":\"1790.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying face down, your partner lifts your arms back to open your chest. A deep, controlled chest and shoulder stretch.\"},{\"id\":\"1784\",\"n\":\"assisted pulling backs chest stretch\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand or sit tall with your arms extended behind you at hip to shoulder height.\",\"Have your partner hold your wrists and gently pull your arms back and slightly up.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1784.webp\",\"gif\":\"1784.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner pulls your arms backward to deepen the chest stretch. It works well when you want more range than you get alone.\"},{\"id\":\"1843\",\"n\":\"assisted rotating neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Sit tall with your shoulders relaxed.\",\"Turn your head to one side as far as is comfortable.\",\"Place one hand on your chin and the other on the back of your head.\",\"Add light pressure to deepen the turn.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1843.webp\",\"gif\":\"1843.mp4\",\"cat\":\"stretching\",\"desc\":\"A hand-assisted head turn that stretches the muscles at the side of the neck.\"},{\"id\":\"1779\",\"n\":\"assisted seated chest stretch\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Sit upright on a bench or chair with your hands behind your head or arms out wide.\",\"Have your partner stand behind you and gently draw your elbows or wrists back.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1779.webp\",\"gif\":\"1779.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated with a partner pulling your arms back, you stretch your chest and the front of your shoulders. Sitting keeps your trunk stable.\"},{\"id\":\"2122\",\"n\":\"assisted side bent\",\"bp\":\"waist\",\"eq\":\"assisted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Stand tall with feet shoulder-width apart and one arm overhead.\",\"Have your partner stand behind you with a hand on your hip and a hand on your raised arm.\",\"Lean sideways as your partner gently guides the movement.\",\"Tell your partner to stop at a mild pull.\",\"Hold for 20-30 seconds.\",\"Return upright and switch sides.\"],\"img\":\"2122.webp\",\"gif\":\"2122.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner helps guide a sideways bend of the trunk, making it easier to relax into the stretch along the flank.\"},{\"id\":\"1027\",\"n\":\"assisted single leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit on the machine and place one foot on the platform.\",\"Release the safety and lower the platform until your knee is bent about 90 degrees.\",\"Press through your heel to straighten the leg without locking the knee.\",\"Lower back with control.\",\"Keep your hips on the seat. Finish the reps, then switch legs.\"],\"img\":\"1027.webp\",\"gif\":\"1027.mp4\",\"cat\":\"strength\",\"desc\":\"A machine press done with one leg at a time, helping you build leg strength and fix imbalances.\"},{\"id\":\"1973\",\"n\":\"assisted sitting reverse shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"assisted\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\"],\"st\":[\"Sit tall and put your arms behind you, palms facing down.\",\"Have a partner stand behind and hold your wrists or forearms.\",\"Ask them to lift your arms slowly until you feel a stretch.\",\"Keep your shoulders relaxed and chest open.\",\"Hold for 20-30 seconds, then lower slowly.\"],\"img\":\"1973.webp\",\"gif\":\"1973.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner gently draws your arms back to stretch the front of the shoulders.\"},{\"id\":\"1778\",\"n\":\"assisted standing chest stretch\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall with your arms out to the sides and your hands at shoulder height or slightly lower.\",\"Have your partner hold your wrists and slowly pull your arms back until you feel a stretch across your chest.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1778.webp\",\"gif\":\"1778.mp4\",\"cat\":\"stretching\",\"desc\":\"A partner draws your arms back while you stand, opening up your chest. It is a deeper stretch than you can usually reach alone.\"},{\"id\":\"1028\",\"n\":\"assisted standing triceps dip\",\"bp\":\"upper arms\",\"eq\":\"assisted\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Set the assistance and stand on the pad holding the handles.\",\"Keep your elbows close and your chest up.\",\"Lower your body by bending the elbows until they are at 90 degrees.\",\"Press back up until your arms are straight.\",\"Avoid shrugging your shoulders and move smoothly.\"],\"img\":\"1028.webp\",\"gif\":\"1028.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip with machine assistance that lets you build triceps strength while handling less of your bodyweight.\"},{\"id\":\"1789\",\"n\":\"assisted straight arms lying stretch (chest)\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"upper chest\"],\"st\":[\"Lie on your back with your arms stretched out straight to the sides or overhead.\",\"Have your partner gently press your wrists or arms down toward the floor.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1789.webp\",\"gif\":\"1789.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying down with your arms out, a partner gently presses your arms toward the floor. It stretches the chest and the front of the shoulders.\"},{\"id\":\"1786\",\"n\":\"assisted trunk flex chest stretch\",\"bp\":\"chest\",\"eq\":\"assisted\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Sit or stand with your hands clasped behind your head and your elbows wide.\",\"Have your partner pull your elbows back as you gently tilt your trunk forward.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1786.webp\",\"gif\":\"1786.mp4\",\"cat\":\"stretching\",\"desc\":\"With a partner helping you lean the trunk forward, you stretch your chest and front shoulders. It gives a controlled, deeper opening.\"},{\"id\":\"1172\",\"n\":\"assisted weighted push up\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Get into a plank with hands under your shoulders and load placed on your upper back.\",\"Brace your core and keep your body in a straight line.\",\"Lower your chest toward the floor.\",\"Press back up until your elbows are straight.\",\"Use the assistance as needed to keep every rep clean.\"],\"img\":\"1172.webp\",\"gif\":\"1172.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with extra load and assistance so you can adjust difficulty while keeping good form.\"},{\"id\":\"3502\",\"n\":\"back forward leg swings\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"adductors\",\"core\"],\"st\":[\"Stand tall beside a wall or support and hold it for balance.\",\"Shift your weight onto the inside leg.\",\"Swing the outside leg forward and back in a controlled arc.\",\"Keep your torso upright.\",\"Increase the range gradually.\",\"Switch legs after your reps.\"],\"img\":\"3502.webp\",\"gif\":\"3502.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic warm-up swinging one leg forward and back. It loosens the hips and hamstrings.\",\"fv\":\"2573\"},{\"id\":\"6097\",\"n\":\"back kick overhead press\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet hip-width apart and your hands at shoulder height.\",\"Press both hands straight overhead as you kick one leg back.\",\"Squeeze the glute at the top without arching your lower back.\",\"Bring the hands and foot back to the start.\",\"Switch legs and repeat at a lively pace.\",\"Keep your core tight throughout.\"],\"img\":\"6097.webp\",\"gif\":\"6097.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A dynamic combo of a backward leg kick with an overhead arm press. It works the shoulders and glutes together and raises your heart rate.\",\"fv\":\"6096\"},{\"id\":\"4515\",\"n\":\"back pec stretch v. 2\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Clasp your hands together behind your back.\",\"Straighten your arms and lift them gently away from your body.\",\"Open your chest and pull your shoulder blades together.\",\"Hold for 20-30 seconds while breathing slowly.\",\"Release and repeat.\"],\"img\":\"4515.webp\",\"gif\":\"4515.mp4\",\"cat\":\"stretching\",\"desc\":\"A back-clasped chest opener that lengthens the pecs and the front of the shoulders.\"},{\"id\":\"1315\",\"n\":\"back relaxation\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\"],\"st\":[\"Get into a comfortable resting position, such as kneeling with your torso folded forward.\",\"Rest your arms in a relaxed position.\",\"Let your back round and release.\",\"Breathe slowly into your lower back.\",\"Hold for 30-60 seconds.\"],\"img\":\"1315.webp\",\"gif\":\"1315.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle resting position that lets the back relax and lengthen after training.\"},{\"id\":\"3995\",\"n\":\"back slaps wrap around stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rhomboids\",\"lats\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Swing your arms wide.\",\"Wrap them around your body so the hands slap your upper back.\",\"Open them wide again.\",\"Keep it loose and rhythmic.\"],\"img\":\"3995.webp\",\"gif\":\"3995.mp4\",\"cat\":\"stretching\",\"desc\":\"Swing your arms across your body, wrapping them around the trunk. It loosens the upper back and shoulders.\"},{\"id\":\"1404\",\"n\":\"back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"upper back\"],\"st\":[\"Stand or sit tall and clasp your hands in front of you.\",\"Press your arms forward and round your upper back.\",\"Let your head drop gently.\",\"Breathe slowly into your back.\",\"Hold for 20-30 seconds.\"],\"img\":\"1404.webp\",\"gif\":\"1404.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple stretch to lengthen the back and ease tightness.\"},{\"id\":\"4663\",\"n\":\"backhand raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"lower back\"],\"st\":[\"Lie face down with your arms by your sides, palms up.\",\"Lift your chest and arms slightly off the floor.\",\"Raise your hands up and back by squeezing your shoulder blades.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4663.webp\",\"gif\":\"4663.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lifting your arms behind you from a face-down position. It strengthens the rear shoulders and upper back.\"},{\"id\":\"4006\",\"n\":\"backward abdominal stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie face down with hands under your shoulders.\",\"Press your chest up.\",\"Keep your hips on the floor.\",\"Hold for 20-30 seconds.\",\"Lower slowly.\"],\"img\":\"4006.webp\",\"gif\":\"4006.mp4\",\"cat\":\"stretching\",\"desc\":\"Arch back to stretch the front of the trunk. It lengthens the abs.\",\"fv\":\"4270\"},{\"id\":\"11795\",\"n\":\"backward press shoulders mobilization\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Stand tall with your arms at your sides.\",\"Press one arm backward, keeping the elbow straight.\",\"Move through a comfortable range.\",\"Return slowly and repeat 8-12 times.\",\"Switch arms.\"],\"img\":\"11795.webp\",\"gif\":\"11795.mp4\",\"cat\":\"mobility\",\"desc\":\"A shoulder mobility drill moving the arm backward to open the front of the shoulder.\"},{\"id\":\"4258\",\"n\":\"backwards run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"hamstrings\",\"glutes\"],\"st\":[\"Find a clear, flat area or treadmill at a low speed.\",\"Stand tall with your arms bent.\",\"Run backwards, landing on the balls of your feet.\",\"Glance over your shoulder from time to time.\",\"Keep a steady, controlled pace.\",\"Slow down gradually to finish.\"],\"img\":\"4258.webp\",\"gif\":\"4258.mp4\",\"cat\":\"cardio\",\"desc\":\"Running backwards at a comfortable pace. It raises your heart rate and strengthens the quads and calves.\"},{\"id\":\"11790\",\"n\":\"balance 3 point toe tap\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"ankles\"],\"st\":[\"Stand on one leg with a slight knee bend and your hands on your hips.\",\"Tap the free foot out in front of you, then lightly out to the side.\",\"Tap it behind you, keeping your torso upright.\",\"Return to center and repeat the sequence under control.\",\"Complete all reps, then switch legs.\"],\"img\":\"11790.webp\",\"gif\":\"11790.mp4\",\"cat\":\"mobility\",\"desc\":\"A balance drill where you stand on one leg and tap the other foot to three points, training hip control and stability.\"},{\"id\":\"10733\",\"n\":\"balance board single leg balance\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"core\",\"glutes\"],\"st\":[\"Place a balance board on a flat floor next to a wall for safety.\",\"Step on with one foot and find your centre.\",\"Lift the other foot off the floor.\",\"Hold steady for 20-30 seconds.\",\"Keep your hips level.\",\"Switch legs.\"],\"img\":\"10733.webp\",\"gif\":\"10733.mp4\",\"cat\":\"mobility\",\"desc\":\"A single-leg stand on a balance board. It trains ankle stability and control.\"},{\"id\":\"5302\",\"n\":\"balance board v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"core\"],\"st\":[\"Place the board on a flat, non-slip surface.\",\"Step onto it with your feet shoulder-width apart.\",\"Keep your knees soft and your core tight.\",\"Tilt gently without letting the edges touch the floor.\",\"Balance for 30-60 seconds.\"],\"img\":\"5302.webp\",\"gif\":\"5302.mp4\",\"cat\":\"rehab\",\"desc\":\"Standing on a balance board to train stability. It strengthens the ankles and the small stabilisers in the feet.\",\"fv\":\"6694\"},{\"id\":\"10734\",\"n\":\"balance pad single leg balance\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"core\",\"glutes\"],\"st\":[\"Place the pad on a flat floor.\",\"Step on with one foot and stand tall.\",\"Lift the other foot off the floor.\",\"Hold for 20-30 seconds.\",\"Keep your eyes on a fixed point.\",\"Switch legs.\"],\"img\":\"10734.webp\",\"gif\":\"10734.mp4\",\"cat\":\"mobility\",\"desc\":\"A one-legged stand on a foam balance pad. It improves ankle stability and body control.\"},{\"id\":\"9994\",\"n\":\"ball assisted lying bent knee isometric hip adduction\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"glutes\",\"core\"],\"st\":[\"Lie on your back with your knees bent.\",\"Place a ball between your knees.\",\"Squeeze the ball with your inner thighs.\",\"Hold for 5 to 10 seconds.\",\"Release slowly.\",\"Repeat for several reps.\"],\"img\":\"9994.webp\",\"gif\":\"9994.mp4\",\"cat\":\"isometric\",\"desc\":\"A lying hip adduction hold squeezing a ball between the knees. It trains the inner thighs.\",\"hd\":1},{\"id\":\"10014\",\"n\":\"ball assisted lying supine hip adduction\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\",\"core\"],\"st\":[\"Lie on your back with knees bent and a ball between your knees.\",\"Rest your arms by your sides and keep your lower back relaxed.\",\"Squeeze the ball with your inner thighs.\",\"Hold for a moment, then release slowly.\",\"Keep your hips level throughout.\"],\"img\":\"10014.webp\",\"gif\":\"10014.mp4\",\"cat\":\"strength\",\"desc\":\"Squeeze a ball between your knees while lying on your back. It targets the inner thighs.\"},{\"id\":\"0021\",\"n\":\"ball sit up (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Sit on a stability ball and walk your feet out until your lower back is supported.\",\"Place your hands by your head or across your chest.\",\"Curl your torso up, bringing your ribs toward your hips.\",\"Squeeze your abs at the top.\",\"Lower slowly back over the ball.\",\"Keep your feet planted and your neck relaxed.\"],\"img\":\"0021.webp\",\"gif\":\"0021.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up with your back resting on a stability ball. The curved surface lets you move through more range than on the floor.\"},{\"id\":\"5985\",\"n\":\"balloon drill\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Toss a balloon into the air in an open space.\",\"Stay on the balls of your feet with bent knees.\",\"Move under the balloon and tap it up.\",\"Use small hops to reach it.\",\"Keep it up for 30-60 seconds.\"],\"img\":\"5985.webp\",\"gif\":\"5985.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A playful balance and leg drill where you keep a balloon in the air using quick footwork and small jumps.\"},{\"id\":\"4087\",\"n\":\"band 45 degrees biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band and hold the ends, then set your arms about 45 degrees behind your torso.\",\"Keep your chest up and shoulders back.\",\"Curl your hands up while your upper arms stay in that angled position.\",\"Squeeze at the top and lower slowly.\",\"Avoid leaning back to finish the rep.\"],\"img\":\"4087.webp\",\"gif\":\"4087.mp4\",\"cat\":\"strength\",\"desc\":\"A band curl with your arms angled about 45 degrees behind your body, which stretches the biceps and works the long head.\"},{\"id\":\"4699\",\"n\":\"band air bike\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"lower abs\"],\"st\":[\"Lie on your back with the band looped around your feet and hold the ends.\",\"Raise your legs and shoulders slightly off the floor.\",\"Pedal one leg in while extending the other.\",\"Twist your torso to bring the opposite elbow to the knee.\",\"Keep a steady rhythm and keep your core tight.\"],\"img\":\"4699.webp\",\"gif\":\"4699.mp4\",\"cat\":\"strength\",\"desc\":\"A pedaling motion on your back with band resistance. It works the lower abs and hip flexors.\"},{\"id\":\"0005\",\"n\":\"band alternate biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the middle of a band and hold an end in each hand.\",\"Keep your elbows at your sides with palms forward.\",\"Curl one hand up toward your shoulder.\",\"Lower it slowly while curling the other hand.\",\"Keep your upper arms still and avoid leaning back.\",\"Alternate sides for your reps.\"],\"img\":\"0005.webp\",\"gif\":\"0005.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl done one arm at a time against a band stood on with your feet. It gives rising tension toward the top of the curl.\"},{\"id\":\"3324\",\"n\":\"band alternate incline chest press with twist\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Anchor a band low behind you and hold the handles at chest height.\",\"Stand in a split stance with your core braced.\",\"Press one hand up and forward while rotating your torso slightly.\",\"Return under control and press with the other arm.\",\"Keep your hips steady and alternate sides for the full set.\"],\"img\":\"3324.webp\",\"gif\":\"3324.mp4\",\"cat\":\"strength\",\"desc\":\"An alternating band press angled upward, with a torso twist added to bring in your core. It works the upper chest and trunk together.\"},{\"id\":\"3326\",\"n\":\"band alternate lat pulldown with twist\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"obliques\",\"core\"],\"st\":[\"Anchor a band high in front of you and hold both handles with arms overhead.\",\"Stand tall in a staggered stance.\",\"Pull one handle down toward your ribs while rotating your torso.\",\"Keep your elbow tucked and shoulder down.\",\"Return slowly and switch to the other arm.\"],\"img\":\"3326.webp\",\"gif\":\"3326.mp4\",\"cat\":\"strength\",\"desc\":\"A standing band pulldown done one arm at a time with a trunk twist. It trains your lats and adds core work.\"},{\"id\":\"4078\",\"n\":\"band alternate low chest fly\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Anchor the band low behind you and hold the ends.\",\"Stand in a staggered stance.\",\"Sweep one arm up and across in front of your chest.\",\"Return slowly.\",\"Alternate arms.\"],\"img\":\"4078.webp\",\"gif\":\"4078.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating single arm chest fly from a low anchor.\"},{\"id\":\"3325\",\"n\":\"band alternate low row with twist\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"obliques\",\"core\"],\"st\":[\"Anchor a band in front of you at low height and hold both handles.\",\"Stand in a staggered stance with arms extended.\",\"Pull one handle back toward your hip while rotating your torso.\",\"Squeeze your shoulder blade, then return slowly.\",\"Repeat with the other arm and keep alternating.\"],\"img\":\"3325.webp\",\"gif\":\"3325.mp4\",\"cat\":\"strength\",\"desc\":\"An alternating band row with a rotation, training your back and the muscles that twist your trunk.\"},{\"id\":\"4718\",\"n\":\"band assisted chin up\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Hang from a bar with an underhand grip and the band looped under your feet.\",\"Engage your lats and keep your core tight.\",\"Pull your chin over the bar.\",\"Pause at the top.\",\"Lower slowly until your arms are straight and repeat.\"],\"img\":\"4718.webp\",\"gif\":\"4718.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up with a band under your feet or knees to reduce the load. It helps you build toward unassisted reps.\"},{\"id\":\"4206\",\"n\":\"band assisted chin up (from knee)\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Attach a band to a pull-up bar and place one knee in the loop.\",\"Grab the bar with an underhand, shoulder-width grip.\",\"Hang with your arms straight and your core tight.\",\"Pull your chest up until your chin clears the bar.\",\"Lower yourself slowly until your arms are straight.\",\"Switch knees halfway through your sets.\"],\"img\":\"4206.webp\",\"gif\":\"4206.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up with a band under one knee to lighten the load. It builds lats and biceps on the way to full chin-ups.\"},{\"id\":\"4205\",\"n\":\"band assisted dip\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Loop a band around the dip bars and set your knees or feet in it.\",\"Grip the bars and straighten your arms with your chest up.\",\"Lower your body until your upper arms are about parallel to the floor.\",\"Keep your elbows close and your shoulders down.\",\"Press back up until your arms are straight.\",\"Use a thinner band as you get stronger.\"],\"img\":\"4205.webp\",\"gif\":\"4205.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Dips with a band looped around the bars to take some of your weight. It builds triceps and chest strength while you work toward unassisted dips.\"},{\"id\":\"4719\",\"n\":\"band assisted dip (version 2)\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Loop a band across dip bars and place your knees in it.\",\"Support yourself with straight arms.\",\"Lower until your elbows reach about 90 degrees.\",\"Press back up.\",\"Keep your shoulders away from your ears.\"],\"img\":\"4719.webp\",\"gif\":\"4719.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip with a band under your knees to help with the load while building triceps and chest strength.\"},{\"id\":\"4985\",\"n\":\"band assisted floor glute ham raise\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"lower back\"],\"st\":[\"Anchor a band at head height and loop it around your chest or hold it to your chest.\",\"Kneel with your feet held firmly under a stable object.\",\"Lower your torso forward slowly with a straight line from knees to head.\",\"Pull yourself back up with your hamstrings and glutes, using the band to help.\",\"Keep your hips extended throughout.\"],\"img\":\"4985.webp\",\"gif\":\"4985.mp4\",\"cat\":\"strength\",\"desc\":\"Floor glute ham raise where a band helps you come back up. It builds the hamstrings and glutes with a manageable load.\"},{\"id\":\"5801\",\"n\":\"band assisted muscle up\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"chest\",\"shoulders\",\"core\"],\"st\":[\"Loop a band over the bar and place your foot or knee in it.\",\"Hang from the bar with a false or overhand grip.\",\"Pull explosively, bringing your chest to the bar.\",\"Lean over the bar and press yourself up to straight arms.\",\"Lower back down slowly and repeat.\"],\"img\":\"5801.webp\",\"gif\":\"5801.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A muscle up where a band under your feet or knees takes some of your weight. It lets you learn the pull and transition on the bar.\"},{\"id\":\"2997\",\"n\":\"band assisted pull up v. 3\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"grip muscles\",\"forearms\"],\"st\":[\"Loop a band over the pull-up bar and place a foot or knee in it.\",\"Grab the bar with an overhand grip a little wider than your shoulders.\",\"Hang with your arms long and your shoulders engaged.\",\"Pull your chest toward the bar by driving your elbows down.\",\"Lower slowly until your arms are straight again.\",\"Use a thinner band as you get stronger.\"],\"img\":\"2997.webp\",\"gif\":\"2997.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up where a band under your foot or knee takes some of your weight, so you can build up to full reps.\",\"fv\":\"3844\"},{\"id\":\"6959\",\"n\":\"band assisted push up\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Anchor a band across a rack or set of bars at chest height.\",\"Rest your torso on the band in a plank position.\",\"Lower your chest toward the floor, elbows at 45 degrees.\",\"Press up using the bounce of the band as help.\",\"Keep your body in a straight line.\"],\"img\":\"6959.webp\",\"gif\":\"6959.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with a band supporting the body to make the rep easier. It helps you build toward full push-ups.\"},{\"id\":\"3653\",\"n\":\"band assisted sprinter run\",\"bp\":\"cardio\",\"eq\":\"band\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Anchor a band behind you and loop it around your waist.\",\"Lean forward into a sprint position.\",\"Drive your knees and pump your arms.\",\"Stay light on your feet.\",\"Repeat for short bursts.\"],\"img\":\"3653.webp\",\"gif\":\"3653.mp4\",\"cat\":\"cardio\",\"desc\":\"A sprinting drill with band assistance to practice fast leg turnover.\"},{\"id\":\"0891\",\"n\":\"band back extension\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Anchor the band and secure it across your upper back.\",\"Hinge forward at the hips with a flat back.\",\"Extend your torso up until your body is in a straight line.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"0891.webp\",\"gif\":\"0891.mp4\",\"cat\":\"strength\",\"desc\":\"A back extension with band resistance. It strengthens the lower back and glutes.\"},{\"id\":\"1499\",\"n\":\"band behind neck shoulder press\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"trapezius\",\"upper back\"],\"st\":[\"Stand on the band and hold the ends at the back of your shoulders.\",\"Brace your core and keep your head forward.\",\"Press your hands straight up until your arms are extended.\",\"Lower slowly back behind your head to shoulder level.\",\"Only use this variation if your shoulders move comfortably in that position.\"],\"img\":\"1499.webp\",\"gif\":\"1499.mp4\",\"cat\":\"strength\",\"desc\":\"A band-resisted overhead press from behind the neck. It trains the shoulders and triceps with rising tension.\"},{\"id\":\"4035\",\"n\":\"band bent over hip extension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Anchor the band low and loop it around one ankle.\",\"Hinge forward at the hips with a flat back, hands on a support.\",\"Extend the working leg back and up against the band.\",\"Squeeze your glute at the top.\",\"Return slowly, finish the reps, then switch legs.\"],\"img\":\"4035.webp\",\"gif\":\"4035.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over kick-back against a band. The hinged torso gives the glutes and hamstrings a deeper stretch and squeeze.\",\"fv\":\"0980\"},{\"id\":\"4144\",\"n\":\"band bent over lat pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rear deltoids\"],\"st\":[\"Anchor the band high and hold it with both hands, arms extended.\",\"Hinge at the hips with a flat back and soft knees.\",\"Pull the band down toward your hips, driving your elbows back.\",\"Squeeze your lats at the bottom for a moment.\",\"Let the band rise slowly until your arms are straight again.\",\"Keep your torso still and your neck neutral.\"],\"img\":\"4144.webp\",\"gif\":\"4144.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge forward and pull a band down toward your hips, like a lat pulldown from a bent over position. It trains the lats and the muscles between your shoulder blades.\"},{\"id\":\"4682\",\"n\":\"band bent over rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Stand on the band and hold the ends in each hand.\",\"Hinge at the hips with a flat back.\",\"Raise your arms out to the sides with slight elbow bends.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4682.webp\",\"gif\":\"4682.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over fly with a band. It targets the rear shoulders and upper back.\"},{\"id\":\"3971\",\"n\":\"band bent over rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\"],\"st\":[\"Stand on the band and hinge forward with a flat back.\",\"Hold the band ends with arms hanging.\",\"Raise your arms out to the sides to shoulder height.\",\"Pause, then lower slowly.\",\"Keep your elbows slightly bent.\"],\"img\":\"3971.webp\",\"gif\":\"3971.mp4\",\"cat\":\"strength\",\"desc\":\"A band raise to the sides while bent forward. It targets the rear delts.\"},{\"id\":\"6486\",\"n\":\"band bent over rear lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Stand on a band and hinge forward with a flat back.\",\"Hold the band ends in each hand.\",\"Raise your arms out to the sides up to shoulder height.\",\"Squeeze your shoulder blades together.\",\"Lower slowly and repeat.\"],\"img\":\"6486.webp\",\"gif\":\"6486.mp4\",\"cat\":\"strength\",\"desc\":\"Bent over with a band, you raise your arms out wide to work the back of your shoulders and upper back.\"},{\"id\":\"0893\",\"n\":\"band bent over rear lateral raise v. 3\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Stand on the band and hold the ends in each hand.\",\"Hinge forward with a flat back.\",\"Raise your arms out to the sides with slightly bent elbows.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly.\"],\"img\":\"0893.webp\",\"gif\":\"0893.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over raise to the sides with a band. It focuses on the rear delts.\"},{\"id\":\"3899\",\"n\":\"band bent over row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Stand on the band with feet hip-width apart and hold the ends.\",\"Hinge forward at the hips with a flat back.\",\"Let your arms hang straight down.\",\"Pull your elbows back toward your hips.\",\"Squeeze your shoulder blades together, then lower slowly.\",\"Keep your neck neutral.\"],\"img\":\"3899.webp\",\"gif\":\"3899.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a band that strengthens the mid back and lats.\"},{\"id\":\"0892\",\"n\":\"band bent over row v. 2\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\"],\"st\":[\"Stand on the band and hold the ends in your hands.\",\"Hinge forward with a flat back and soft knees.\",\"Pull your elbows back toward your hips.\",\"Squeeze your shoulder blades together.\",\"Lower with control.\"],\"img\":\"0892.webp\",\"gif\":\"0892.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a band. It builds the muscles between your shoulder blades and the lats.\"},{\"id\":\"4698\",\"n\":\"band bent over row v. 3\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Stand on the band and hold the ends, hinging forward with a flat back.\",\"Let your arms hang straight down.\",\"Row your elbows back toward your hips.\",\"Squeeze your shoulder blades together.\",\"Lower slowly and repeat.\"],\"img\":\"4698.webp\",\"gif\":\"4698.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a band. It builds the upper back and lats.\"},{\"id\":\"4452\",\"n\":\"band bent over wide grip row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"rear deltoids\",\"biceps\",\"lower back\"],\"st\":[\"Stand on the band with feet hip width apart and grab it with a wide overhand grip.\",\"Hinge at the hips with a flat back and soft knees.\",\"Pull your hands toward your lower ribs, elbows flaring out.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly until your arms are straight.\",\"Keep your torso still throughout.\"],\"img\":\"4452.webp\",\"gif\":\"4452.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a band and a wide grip. Targets the upper back and rear shoulders.\"},{\"id\":\"4063\",\"n\":\"band biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band and hold the ends with palms forward.\",\"Keep your elbows at your sides.\",\"Curl your hands up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly without swinging.\"],\"img\":\"4063.webp\",\"gif\":\"4063.mp4\",\"cat\":\"strength\",\"desc\":\"Standing curl using a band under your feet. It builds the biceps with rising tension.\"},{\"id\":\"4357\",\"n\":\"band biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band with feet shoulder-width apart and hold the ends, palms up.\",\"Keep your elbows pinned to your sides.\",\"Curl your hands toward your shoulders.\",\"Squeeze at the top.\",\"Lower slowly against the band.\"],\"img\":\"4357.webp\",\"gif\":\"4357.mp4\",\"cat\":\"strength\",\"desc\":\"A simple biceps curl with a band underfoot. It trains the front of the arms with elastic resistance.\"},{\"id\":\"0894\",\"n\":\"band calf raise\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit or stand with the band looped under the balls of your feet.\",\"Hold the ends firmly.\",\"Press up onto your toes against the band.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"0894.webp\",\"gif\":\"0894.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise with band resistance. It builds the calves and ankle strength.\"},{\"id\":\"0973\",\"n\":\"band calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Sit or stand with the band looped under the balls of your feet.\",\"Hold the ends firmly so the band is taut.\",\"Press up onto your toes as high as you can.\",\"Pause at the top, then lower slowly.\",\"Keep your ankles straight and avoid rolling out.\"],\"img\":\"0973.webp\",\"gif\":\"0973.mp4\",\"cat\":\"strength\",\"desc\":\"Rise onto your toes against band resistance. It builds calf strength and ankle stability.\"},{\"id\":\"1505\",\"n\":\"band calf raise v. 3\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Secure the band under your feet or around your shoulders as set up.\",\"Stand tall with your feet hip-width apart.\",\"Rise onto the balls of your feet as high as you can.\",\"Pause and squeeze your calves.\",\"Lower slowly until your heels are back on the floor.\"],\"img\":\"1505.webp\",\"gif\":\"1505.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise using a band for resistance. It builds calf strength and ankle control.\"},{\"id\":\"4075\",\"n\":\"band chest fly\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"upper chest\"],\"st\":[\"Anchor the band behind you at chest height and hold the ends.\",\"Stand in a staggered stance.\",\"Start with arms out to the sides and slightly bent.\",\"Bring your hands together in front of your chest.\",\"Return slowly under control.\"],\"img\":\"4075.webp\",\"gif\":\"4075.mp4\",\"cat\":\"strength\",\"desc\":\"Standing band fly bringing the hands together in front of the chest. It trains the pecs.\"},{\"id\":\"4138\",\"n\":\"band close grip biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band and grip it close to your feet with a narrow hold.\",\"Keep your elbows at your sides.\",\"Curl your hands to your shoulders.\",\"Squeeze the top.\",\"Lower slowly.\"],\"img\":\"4138.webp\",\"gif\":\"4138.mp4\",\"cat\":\"strength\",\"desc\":\"A band curl with a narrow hand position to emphasize the outer biceps.\"},{\"id\":\"4145\",\"n\":\"band close grip row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\"],\"st\":[\"Anchor the band at chest height and hold both ends with hands close together.\",\"Step back until the band is taut and stand tall with soft knees.\",\"Row your hands toward your lower ribs, elbows brushing your sides.\",\"Squeeze your shoulder blades together at the end.\",\"Extend your arms slowly back to the start.\",\"Keep your shoulders down and avoid leaning back.\"],\"img\":\"4145.webp\",\"gif\":\"4145.mp4\",\"cat\":\"strength\",\"desc\":\"A row with the hands close together against band tension. It works the mid back and lats with extra focus on the elbows staying tight to the body.\"},{\"id\":\"4136\",\"n\":\"band cross abduction\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Attach the band to a low anchor and loop it around your outer ankle.\",\"Stand tall and hold support if needed.\",\"Move that leg across then out to the side.\",\"Control the return.\",\"Switch legs after your set.\"],\"img\":\"4136.webp\",\"gif\":\"4136.mp4\",\"cat\":\"strength\",\"desc\":\"A hip abduction with a band that crosses the body, working the outer hips.\"},{\"id\":\"4076\",\"n\":\"band cross body one arm chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Anchor the band behind you and hold the end in one hand.\",\"Stand in a staggered stance.\",\"Press your hand forward and across your body.\",\"Return slowly while resisting rotation.\",\"Finish the reps, then switch arms.\"],\"img\":\"4076.webp\",\"gif\":\"4076.mp4\",\"cat\":\"strength\",\"desc\":\"Single arm band press that travels across the body, working the chest and core.\"},{\"id\":\"4088\",\"n\":\"band cross chest biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Stand on the band and hold the ends with palms facing in.\",\"Keep your elbows near your sides.\",\"Curl one hand across your chest toward the opposite shoulder.\",\"Lower under control, then repeat on the other arm.\",\"Keep your torso still and avoid swinging.\"],\"img\":\"4088.webp\",\"gif\":\"4088.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer-style curl that crosses the band toward the opposite shoulder, hitting the biceps and brachialis.\"},{\"id\":\"4618\",\"n\":\"band deadlift\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Stand on the band with feet hip-width apart and grab it with both hands.\",\"Hinge at the hips with a flat back and slightly bent knees.\",\"Lower your hands along your legs until you feel a hamstring stretch.\",\"Drive your hips forward to stand tall and squeeze your glutes.\",\"Keep the band close to your body.\"],\"img\":\"4618.webp\",\"gif\":\"4618.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge using a band under your feet for rising tension, working the glutes and hamstrings.\",\"fv\":\"0895\"},{\"id\":\"3771\",\"n\":\"band deadlift with single arm row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"lats\",\"upper back\",\"biceps\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Stand with soft knees and the band under light tension.\",\"Push your hips back and lower your torso with a flat back.\",\"Drive your hips forward to stand, then row the handle to your ribs.\",\"Lower the handle under control. Finish your reps, then switch sides.\"],\"img\":\"3771.webp\",\"gif\":\"3771.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge paired with a one-arm band row. It works your posterior chain and your upper back.\"},{\"id\":\"1498\",\"n\":\"band decline sit up\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Anchor a band behind you and hold the other end at your chest.\",\"Lie on a decline bench with your feet secured.\",\"Curl your torso up toward your knees, keeping tension on the band.\",\"Pause at the top without pulling on your neck.\",\"Lower back down slowly under control.\"],\"img\":\"1498.webp\",\"gif\":\"1498.mp4\",\"cat\":\"strength\",\"desc\":\"A decline sit-up with a band adding resistance. It trains the abs through a long range.\",\"fv\":\"3840\"},{\"id\":\"4696\",\"n\":\"band down to up twist\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Anchor the band low and stand sideways to it, holding the end with both hands.\",\"Start with your hands near the low hip.\",\"Pull diagonally upward across your body as you rotate your torso.\",\"Pivot your back foot and keep your arms long.\",\"Return slowly, repeat, then switch sides.\"],\"img\":\"4696.webp\",\"gif\":\"4696.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal twisting movement with a band from low to high. It trains the obliques and core.\"},{\"id\":\"1506\",\"n\":\"band ez barbell close grip curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band and hold the EZ bar with a close grip, palms up.\",\"Keep your elbows at your sides and your chest tall.\",\"Curl the bar up toward your shoulders.\",\"Squeeze at the top without swinging.\",\"Lower slowly until your arms are straight.\"],\"img\":\"1506.webp\",\"gif\":\"1506.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip curl on an EZ bar with a band adding tension near the top. It targets the biceps.\"},{\"id\":\"5607\",\"n\":\"band face pull\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Anchor a band at head height and hold the ends.\",\"Step back to create tension.\",\"Pull the band toward your face, elbows high.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"5607.webp\",\"gif\":\"5607.mp4\",\"cat\":\"strength\",\"desc\":\"Face pull using a band to train the rear delts and upper back.\",\"fv\":\"0896\"},{\"id\":\"3777\",\"n\":\"band front plank with single arm pulldown\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\",\"obliques\"],\"st\":[\"Anchor the band overhead and set up in a forearm or high plank.\",\"Brace your abs and keep your hips level.\",\"Pull the band down with one hand toward your hip without twisting.\",\"Return the arm slowly to the start.\",\"Alternate arms and keep your body in one straight line.\"],\"img\":\"3777.webp\",\"gif\":\"3777.mp4\",\"cat\":\"strength\",\"desc\":\"A front plank with a one-arm band pulldown. It trains core stability while your arm works against the band.\"},{\"id\":\"1513\",\"n\":\"band good morning\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on the band and loop it behind your neck across your shoulders.\",\"Keep your knees softly bent and your back flat.\",\"Push your hips back and lean your torso forward.\",\"Stop when you feel a stretch in the hamstrings.\",\"Drive your hips forward to stand tall again.\"],\"img\":\"1513.webp\",\"gif\":\"1513.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a band across your shoulders. It strengthens the hamstrings, glutes and lower back.\"},{\"id\":\"4573\",\"n\":\"band half kneeling chop\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Anchor a band high and kneel on one knee side-on to the anchor.\",\"Hold the band with both hands near your high shoulder.\",\"Pull the band diagonally down across your body.\",\"Rotate your torso and keep your hips square.\",\"Return slowly to the start.\",\"Complete your reps, then switch sides.\"],\"img\":\"4573.webp\",\"gif\":\"4573.mp4\",\"cat\":\"strength\",\"desc\":\"A band chop from a half kneeling position, building core stability and rotation.\"},{\"id\":\"0897\",\"n\":\"band hammer curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band and hold the ends with palms facing in.\",\"Keep your elbows at your sides.\",\"Curl your hands up toward your shoulders.\",\"Pause briefly.\",\"Lower slowly without swinging.\"],\"img\":\"0897.webp\",\"gif\":\"0897.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl with a band. The neutral grip hits the brachialis and forearms along with the biceps.\"},{\"id\":\"3757\",\"n\":\"band high fly\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Anchor a band high and hold one end in each hand, facing away.\",\"Step forward and lean slightly.\",\"Bring your hands together in front of your waist with a soft elbow.\",\"Squeeze your chest at the end.\",\"Return slowly.\"],\"img\":\"3757.webp\",\"gif\":\"3757.mp4\",\"cat\":\"strength\",\"desc\":\"A band chest fly from a high anchor, pulling downward to work the lower chest.\",\"fv\":\"0898\"},{\"id\":\"3772\",\"n\":\"band high knee lunge with single arm row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lats\",\"upper back\",\"core\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Step back into a lunge and lower until your front thigh is about parallel.\",\"Push through your front foot and drive the rear knee up to hip height.\",\"Row the handle to your ribs while balancing on one leg.\",\"Return to the start under control. Finish your reps, then switch sides.\"],\"img\":\"3772.webp\",\"gif\":\"3772.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge that finishes with a high knee, combined with a one-arm band row. It builds leg strength and balance.\"},{\"id\":\"4031\",\"n\":\"band hip abduction\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Anchor the band low and loop it around the ankle farthest from the anchor.\",\"Stand tall and hold a support for balance.\",\"Lift the working leg out to the side without leaning.\",\"Pause, then lower slowly against the band.\",\"Finish all reps, then switch legs.\"],\"img\":\"4031.webp\",\"gif\":\"4031.mp4\",\"cat\":\"strength\",\"desc\":\"Standing leg raise to the side against a band. It targets the outer hip and glute muscles.\",\"fv\":\"0899\"},{\"id\":\"4029\",\"n\":\"band hip adduction\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\",\"glutes\"],\"st\":[\"Anchor the band low and loop it around the ankle nearest the anchor.\",\"Stand tall and hold a support for balance.\",\"Pull the working leg across in front of the other leg.\",\"Pause for a moment and return slowly.\",\"Finish all reps, then switch legs.\"],\"img\":\"4029.webp\",\"gif\":\"4029.mp4\",\"cat\":\"strength\",\"desc\":\"Standing leg movement against a band that squeezes the thigh inward. It strengthens the inner thigh.\",\"fv\":\"0900\"},{\"id\":\"0901\",\"n\":\"band hip extension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Loop the band around your ankles or anchor it low.\",\"Stand tall and hold support.\",\"Press one leg straight back against the band.\",\"Squeeze your glute at the top.\",\"Return slowly, then switch legs.\"],\"img\":\"0901.webp\",\"gif\":\"0901.mp4\",\"cat\":\"strength\",\"desc\":\"A band-resisted leg kick back. It strengthens the glutes and hamstrings.\"},{\"id\":\"1507\",\"n\":\"band hip flexion\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Attach a band to a low anchor and loop it around one ankle.\",\"Stand tall and hold a support for balance.\",\"Lift the knee forward and up toward hip height.\",\"Pause briefly, then lower with control.\",\"Finish your reps and switch legs.\"],\"img\":\"1507.webp\",\"gif\":\"1507.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hip flexion with a band around the foot or leg. It trains the hip flexors and quads.\"},{\"id\":\"4084\",\"n\":\"band horizontal biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Anchor the band at chest height and face away from the anchor, holding the ends.\",\"Step out until the band is taut and raise your arms out to the sides at shoulder height.\",\"Bend your elbows to bring your hands toward your head.\",\"Squeeze your biceps, then slowly extend your arms again.\",\"Keep your elbows level with your shoulders the whole time.\"],\"img\":\"4084.webp\",\"gif\":\"4084.mp4\",\"cat\":\"strength\",\"desc\":\"A band curl done with the band pulling horizontally, which keeps constant tension on your biceps through the whole range.\"},{\"id\":\"3524\",\"n\":\"band horizontal pallof press with resistance band squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"obliques\",\"shoulders\"],\"st\":[\"Anchor a band at chest height and stand side-on, holding it at your chest.\",\"Squat down, keeping your torso tall.\",\"Stand and press the band straight out in front.\",\"Resist the band trying to rotate you.\",\"Bring your hands back to your chest.\",\"Finish your reps, then switch sides.\"],\"img\":\"3524.webp\",\"gif\":\"3524.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a Pallof press. It builds leg strength with anti-rotation core work.\"},{\"id\":\"0902\",\"n\":\"band hyperextension\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Secure the band over your shoulders and under your feet or anchor.\",\"Hinge at the hips with a flat back.\",\"Rise until your torso is in line with your legs.\",\"Squeeze your glutes.\",\"Lower slowly and repeat.\"],\"img\":\"0902.webp\",\"gif\":\"0902.mp4\",\"cat\":\"strength\",\"desc\":\"A hyperextension with band resistance. It strengthens the lower back and glutes.\"},{\"id\":\"4544\",\"n\":\"band incline bench press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"triceps\"],\"st\":[\"Set an incline bench and anchor a band behind it or under the bench.\",\"Sit back with the band handles at chest level.\",\"Brace your core and keep your shoulder blades pulled together.\",\"Press the handles up and slightly forward until your arms are straight.\",\"Lower slowly back to the start, feeling the band pull.\",\"Keep your wrists straight throughout.\"],\"img\":\"4544.webp\",\"gif\":\"4544.mp4\",\"cat\":\"strength\",\"desc\":\"An incline press using a band for resistance, targeting the upper chest and front shoulders.\"},{\"id\":\"3782\",\"n\":\"band jump lunge with single arm row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"lats\",\"upper back\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Start in a lunge position with your chest up.\",\"Jump and switch legs in mid-air.\",\"Land softly in a lunge and pull the handle to your ribs.\",\"Keep your front knee over your ankle on each landing.\",\"Switch rowing arm for the next set.\"],\"img\":\"3782.webp\",\"gif\":\"3782.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping lunge combined with a one-arm band row. It raises your heart rate and builds leg power.\"},{\"id\":\"0903\",\"n\":\"band kickback\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Stand on the band, hinge forward and hold the ends.\",\"Keep your upper arms close to your sides.\",\"Straighten your elbows, pushing your hands back.\",\"Squeeze your triceps at the top.\",\"Bend slowly to return.\"],\"img\":\"0903.webp\",\"gif\":\"0903.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps kickback with a band. It isolates the back of the upper arm.\"},{\"id\":\"4080\",\"n\":\"band kneeling crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Anchor the band high and kneel facing it, holding the ends beside your head.\",\"Keep your hips still.\",\"Crunch your ribs toward your hips.\",\"Pause and squeeze your abs.\",\"Return slowly.\"],\"img\":\"4080.webp\",\"gif\":\"4080.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling crunch against a band anchored overhead. It trains the abs with steady resistance.\",\"fv\":\"0904\"},{\"id\":\"4720\",\"n\":\"band kneeling crunch v. 2\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Anchor the band overhead and kneel facing it.\",\"Hold the band beside your head.\",\"Crunch down, bringing your elbows toward your thighs.\",\"Round your spine and tighten your abs.\",\"Return slowly and repeat.\"],\"img\":\"4720.webp\",\"gif\":\"4720.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling crunch against band resistance. It strengthens the abs through a loaded crunch.\"},{\"id\":\"4684\",\"n\":\"band kneeling incline press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Anchor the band low behind you and kneel facing away from it.\",\"Hold the ends at chest height.\",\"Press your hands up and forward at an incline.\",\"Squeeze your chest at the top.\",\"Return slowly with control and repeat.\"],\"img\":\"4684.webp\",\"gif\":\"4684.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling upward press using a band. It targets the upper chest and shoulders.\"},{\"id\":\"4358\",\"n\":\"band kneeling lat pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\"],\"st\":[\"Anchor a band high and kneel facing it, holding the ends.\",\"Lean back slightly and brace your core.\",\"Pull your elbows down toward your ribs.\",\"Squeeze your shoulder blades together.\",\"Return slowly with control.\"],\"img\":\"4358.webp\",\"gif\":\"4358.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling pulldown using a band anchored overhead. It builds the lats at home.\"},{\"id\":\"4085\",\"n\":\"band kneeling preacher curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Anchor the band low and kneel facing it with your upper arms resting on a bench or pad.\",\"Hold the band ends with palms up and arms extended.\",\"Curl your hands toward your shoulders.\",\"Squeeze at the top, then lower slowly until your arms are nearly straight.\",\"Keep your upper arms pressed down on the pad.\"],\"img\":\"4085.webp\",\"gif\":\"4085.mp4\",\"cat\":\"strength\",\"desc\":\"A curl performed kneeling with your upper arms braced on a bench or pad, so the biceps do the work without momentum.\"},{\"id\":\"0905\",\"n\":\"band kneeling pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Anchor the band high and kneel facing it.\",\"Grab the ends with arms extended up.\",\"Pull your elbows down toward your ribs.\",\"Squeeze your shoulder blades together.\",\"Return slowly with control.\"],\"img\":\"0905.webp\",\"gif\":\"0905.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling pulldown with a band anchored overhead. It trains the lats and mid-back.\"},{\"id\":\"0906\",\"n\":\"band kneeling rear kick\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Get on all fours with the band around one foot and in your hands.\",\"Keep your core tight.\",\"Kick the banded leg back and up.\",\"Squeeze your glute at the top.\",\"Lower slowly, then switch legs.\"],\"img\":\"0906.webp\",\"gif\":\"0906.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling glute kick against a band. It strengthens the glutes with a stable base.\"},{\"id\":\"10668\",\"n\":\"band kneeling single arm horizontal row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"core\"],\"st\":[\"Anchor a band at chest height and kneel facing it.\",\"Hold the band with one hand and keep your torso upright.\",\"Pull the elbow back past your ribs.\",\"Squeeze your shoulder blade in.\",\"Return slowly against the tension.\",\"Switch arms after the set.\"],\"img\":\"10668.webp\",\"gif\":\"10668.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm band row from a kneeling position. It builds the lats and mid back with simple equipment.\"},{\"id\":\"4677\",\"n\":\"band kneeling single leg kick\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Get on all fours with a band looped around your foot and hands.\",\"Brace your core and keep your back flat.\",\"Extend one leg back, squeezing your glute.\",\"Pause briefly at full extension.\",\"Return with control and repeat, then switch legs.\"],\"img\":\"4677.webp\",\"gif\":\"4677.mp4\",\"cat\":\"strength\",\"desc\":\"Kicking one leg back from a kneeling position against a band. It isolates the glutes.\"},{\"id\":\"0907\",\"n\":\"band lateral raise\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand on the band and hold the ends at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to shoulder height.\",\"Lower slowly under control.\",\"Avoid shrugging.\"],\"img\":\"0907.webp\",\"gif\":\"0907.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise with a band. It builds the side delts.\"},{\"id\":\"1508\",\"n\":\"band lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Stand on the band and hold the ends at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides until they reach shoulder height.\",\"Pause briefly without shrugging.\",\"Lower slowly back to your sides.\"],\"img\":\"1508.webp\",\"gif\":\"1508.mp4\",\"cat\":\"strength\",\"desc\":\"A band lateral raise that builds the sides of the shoulders.\"},{\"id\":\"6607\",\"n\":\"band lateral walk\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Put a loop band around your legs just above the knees or ankles.\",\"Stand in a quarter squat with feet hip-width apart.\",\"Step sideways with the lead foot, keeping tension on the band.\",\"Bring the trailing foot in without letting the feet touch.\",\"Walk several steps one way, then return the other way.\"],\"img\":\"6607.webp\",\"gif\":\"6607.mp4\",\"cat\":\"strength\",\"desc\":\"Side stepping with a loop band around the legs. It fires up the hip abductors and glutes.\",\"fv\":\"2460\"},{\"id\":\"4077\",\"n\":\"band low alternate chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Anchor the band low behind you and hold both ends.\",\"Stand in a staggered stance.\",\"Press one hand up and forward.\",\"Return, then press the other hand.\",\"Keep your core braced.\"],\"img\":\"4077.webp\",\"gif\":\"4077.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating band presses from a low anchor. It trains the upper chest.\"},{\"id\":\"4073\",\"n\":\"band low chest fly\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Anchor the band low behind you and hold the ends.\",\"Step forward with a slight lean.\",\"Start with arms out to the sides and slightly bent.\",\"Sweep your hands up and together in front of your chest.\",\"Return slowly.\"],\"img\":\"4073.webp\",\"gif\":\"4073.mp4\",\"cat\":\"strength\",\"desc\":\"Chest fly with the band anchored low, so you sweep your arms up and together. It focuses on the upper chest.\"},{\"id\":\"4074\",\"n\":\"band low chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Anchor the band low behind you and hold the ends at chest level.\",\"Step forward into a staggered stance.\",\"Press your hands up and forward.\",\"Pause, then return slowly.\",\"Keep your core braced.\"],\"img\":\"4074.webp\",\"gif\":\"4074.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing a band upward from a low anchor. It trains the upper chest and triceps.\"},{\"id\":\"0908\",\"n\":\"band low fly\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\"],\"st\":[\"Anchor the band low and stand with a staggered stance.\",\"Hold the ends with arms slightly bent.\",\"Sweep your arms up and together in front of your chest.\",\"Squeeze your chest at the top.\",\"Return slowly.\"],\"img\":\"0908.webp\",\"gif\":\"0908.mp4\",\"cat\":\"strength\",\"desc\":\"A fly where your arms sweep upward from low to high. It targets the upper chest.\"},{\"id\":\"0909\",\"n\":\"band lunges\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on the band with the ends held at your shoulders.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor.\",\"Press through the front heel to return.\",\"Alternate legs.\"],\"img\":\"0909.webp\",\"gif\":\"0909.mp4\",\"cat\":\"strength\",\"desc\":\"Lunges with band resistance. They build the quads and glutes with extra tension.\"},{\"id\":\"4681\",\"n\":\"band lying alternate leg press\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Lie on your back and loop the band around the soles of your feet, holding the ends.\",\"Bend both knees toward your chest.\",\"Press one foot out straight against the band.\",\"Bring it back and press the other leg.\",\"Alternate smoothly with control.\"],\"img\":\"4681.webp\",\"gif\":\"4681.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing one leg at a time against a band while lying down. It builds leg strength with light equipment.\"},{\"id\":\"6810\",\"n\":\"band lying bent knee raise\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with a band looped around your feet or anchored.\",\"Place your hands by your sides and brace your core.\",\"Bring your knees toward your chest against the band.\",\"Pause briefly at the top.\",\"Lower your feet slowly without arching your back.\"],\"img\":\"6810.webp\",\"gif\":\"6810.mp4\",\"cat\":\"strength\",\"desc\":\"A lying knee raise against band resistance. It builds the lower abs and hip flexors.\"},{\"id\":\"0982\",\"n\":\"band lying hip external rotation\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Lie on your side with knees bent and a loop band around your thighs just above the knees.\",\"Keep your feet together and your hips stacked.\",\"Rotate the top knee upward, opening like a clamshell.\",\"Pause at the top.\",\"Lower slowly and repeat, then switch sides.\",\"Keep your pelvis still so the movement comes from the hip.\"],\"img\":\"0982.webp\",\"gif\":\"0982.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying clam-style move with a band around the knees that fires up the outer hip and glute muscles.\",\"fv\":\"3022\"},{\"id\":\"3023\",\"n\":\"band lying hip internal rotation v. 2\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hip flexors\"],\"st\":[\"Lie on your back with a band around your lower leg anchored to the side.\",\"Bend your knees with your feet on the floor.\",\"Rotate your lower leg outward against the band, turning the hip inward.\",\"Return slowly to the start.\",\"Complete your reps and switch legs.\"],\"img\":\"3023.webp\",\"gif\":\"3023.mp4\",\"cat\":\"strength\",\"desc\":\"Lying hip internal rotation against a band to build control through the hip.\"},{\"id\":\"0910\",\"n\":\"band lying leg and hip raise\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with the band set around your feet or anchored.\",\"Lift your legs toward the ceiling.\",\"Curl your hips off the floor.\",\"Lower slowly.\",\"Keep your lower back controlled.\"],\"img\":\"0910.webp\",\"gif\":\"0910.mp4\",\"cat\":\"strength\",\"desc\":\"A lying raise lifting the legs and hips with a band. It works the lower abs.\"},{\"id\":\"0911\",\"n\":\"band lying leg curl\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie face down with a band anchored to your ankles.\",\"Keep your hips pressed down.\",\"Curl your heels toward your glutes.\",\"Squeeze your hamstrings.\",\"Lower slowly.\"],\"img\":\"0911.webp\",\"gif\":\"0911.mp4\",\"cat\":\"strength\",\"desc\":\"A leg curl while lying down using a band. It targets the hamstrings.\"},{\"id\":\"0912\",\"n\":\"band lying leg raise\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with the band around your legs.\",\"Keep your legs straight.\",\"Raise one leg against the band.\",\"Lower slowly.\",\"Alternate sides.\"],\"img\":\"0912.webp\",\"gif\":\"0912.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg raise against a band. It works the hip muscles.\"},{\"id\":\"4142\",\"n\":\"band lying reverse grip pressdown\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Lie on your back with the band anchored overhead and grip it palms up.\",\"Keep your elbows pointing at the ceiling.\",\"Press your hands down toward your thighs.\",\"Squeeze your triceps.\",\"Return slowly.\"],\"img\":\"4142.webp\",\"gif\":\"4142.mp4\",\"cat\":\"strength\",\"desc\":\"A lying pressdown with an underhand grip, targeting the triceps.\"},{\"id\":\"0913\",\"n\":\"band middle fly\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Anchor the band at chest height and stand facing away.\",\"Hold the ends with slightly bent elbows.\",\"Bring your hands together in front of your chest.\",\"Squeeze your pecs.\",\"Return slowly.\"],\"img\":\"0913.webp\",\"gif\":\"0913.mp4\",\"cat\":\"strength\",\"desc\":\"A chest fly with the band at mid-chest height. It works the pecs through a sweeping motion.\"},{\"id\":\"4147\",\"n\":\"band narrow grip high row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"biceps\",\"rhomboids\"],\"st\":[\"Anchor the band at or above head height and grip it with hands close together.\",\"Step back until there is tension and stand tall.\",\"Pull your hands toward your upper chest, elbows high and out.\",\"Squeeze your shoulder blades together.\",\"Return slowly with control.\",\"Keep your ribs down and avoid arching your back.\"],\"img\":\"4147.webp\",\"gif\":\"4147.mp4\",\"cat\":\"strength\",\"desc\":\"A high row with a narrow grip against a band. It targets the upper back and rear shoulders as you pull toward the face.\"},{\"id\":\"4148\",\"n\":\"band narrow grip high row v. 2\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"biceps\",\"rhomboids\"],\"st\":[\"Anchor the band high and grip it with hands close together.\",\"Step back to create tension and stand tall.\",\"Pull your hands toward your upper chest, elbows flaring slightly.\",\"Pause and squeeze your shoulder blades together.\",\"Extend your arms slowly back to the start.\",\"Keep your torso upright throughout.\"],\"img\":\"4148.webp\",\"gif\":\"4148.mp4\",\"cat\":\"strength\",\"desc\":\"A second variation of the narrow grip high row using a band. It builds the upper back and rear shoulders.\"},{\"id\":\"4453\",\"n\":\"band one arm standing wide grip low row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Anchor a band low and stand facing it, holding the end in one hand.\",\"Step back until the band is taut, feet hip width apart.\",\"Pull your elbow back and out, leading with the elbow.\",\"Squeeze your shoulder blade toward your spine.\",\"Return slowly to a straight arm.\",\"Finish your reps, then switch arms.\"],\"img\":\"4453.webp\",\"gif\":\"4453.mp4\",\"cat\":\"strength\",\"desc\":\"A standing single-arm row from a low anchor, using a band. Trains the lats and mid back one side at a time.\"},{\"id\":\"4082\",\"n\":\"band overhead side bend\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Stand on the band and hold the ends overhead.\",\"Keep your core braced.\",\"Bend sideways at your waist.\",\"Return to upright.\",\"Finish the reps, then switch sides.\"],\"img\":\"4082.webp\",\"gif\":\"4082.mp4\",\"cat\":\"strength\",\"desc\":\"Standing side bend with a band stretched overhead, training the obliques.\"},{\"id\":\"4140\",\"n\":\"band overhead single arm triceps extension\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Stand on the band and hold the other end overhead with one hand.\",\"Bend your elbow behind your head.\",\"Extend your arm upward.\",\"Keep your upper arm still.\",\"Switch arms after your set.\"],\"img\":\"4140.webp\",\"gif\":\"4140.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm overhead band extension to isolate each triceps.\"},{\"id\":\"4141\",\"n\":\"band overhead single arm triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Anchor or stand on the band and hold it overhead in one hand.\",\"Bend your elbow so your hand drops behind your head.\",\"Extend your arm fully.\",\"Keep your core tight.\",\"Switch arms after your set.\"],\"img\":\"4141.webp\",\"gif\":\"4141.mp4\",\"cat\":\"strength\",\"desc\":\"A second version of the one arm overhead band extension.\"},{\"id\":\"3939\",\"n\":\"band overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Anchor the band low or stand on it and hold the other end behind your head.\",\"Keep your elbows pointing up and close to your ears.\",\"Straighten your arms overhead.\",\"Bend the elbows slowly to return.\",\"Keep your upper arms still and your ribs down.\"],\"img\":\"3939.webp\",\"gif\":\"3939.mp4\",\"cat\":\"strength\",\"desc\":\"Press a band overhead from behind your head to straighten the elbows. It isolates the triceps.\",\"fv\":\"0914\"},{\"id\":\"4139\",\"n\":\"band overhead triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Stand on one end of the band and hold the other overhead with both hands.\",\"Bend your elbows behind your head.\",\"Extend your arms upward.\",\"Keep your elbows close to your ears.\",\"Lower under control.\"],\"img\":\"4139.webp\",\"gif\":\"4139.mp4\",\"cat\":\"strength\",\"desc\":\"A second version of the band overhead extension for the triceps.\"},{\"id\":\"4359\",\"n\":\"band overhead triceps extension v. 3\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand holding a band behind your head, one hand low and one hand high.\",\"Keep your elbows close to your head.\",\"Extend your top arm straight overhead.\",\"Pause briefly.\",\"Lower slowly, then switch sides.\"],\"img\":\"4359.webp\",\"gif\":\"4359.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension with a band held overhead. It trains the long head of the triceps.\"},{\"id\":\"4694\",\"n\":\"band overhead triceps extension v. 4\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand on the band and hold the ends behind your head with elbows bent.\",\"Keep your elbows pointing forward.\",\"Extend your arms overhead.\",\"Squeeze your triceps at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4694.webp\",\"gif\":\"4694.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead triceps extension with a band. It isolates the back of the arms.\"},{\"id\":\"1503\",\"n\":\"band pull apart\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Hold a band in front of you at shoulder height with your arms straight.\",\"Keep your ribs down and your shoulders away from your ears.\",\"Pull the band apart by moving your hands out to the sides.\",\"Squeeze your shoulder blades together at the end.\",\"Return slowly with control.\"],\"img\":\"1503.webp\",\"gif\":\"1503.mp4\",\"cat\":\"strength\",\"desc\":\"A simple band move pulling the arms apart in front of you. It strengthens the upper back and rear shoulders and helps posture.\"},{\"id\":\"0915\",\"n\":\"band push up\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Loop the band across your upper back, holding the ends under your palms.\",\"Set up in a high plank.\",\"Lower your chest toward the floor.\",\"Press back up against the band.\",\"Keep your body in a straight line.\"],\"img\":\"0915.webp\",\"gif\":\"0915.mp4\",\"cat\":\"strength\",\"desc\":\"A push up with a band across your back for extra resistance. It strengthens the chest and triceps.\"},{\"id\":\"1502\",\"n\":\"band pushdown\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Anchor the band high and hold the ends with your elbows at your sides.\",\"Stand tall with a slight forward lean.\",\"Push your hands down until your arms are straight.\",\"Pause and squeeze your triceps.\",\"Return slowly while keeping your elbows pinned to your sides.\"],\"img\":\"1502.webp\",\"gif\":\"1502.mp4\",\"cat\":\"strength\",\"desc\":\"A band version of the triceps pushdown that isolates the back of the arm.\",\"fv\":\"0916\"},{\"id\":\"1006\",\"n\":\"band rear delt row\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"biceps\"],\"st\":[\"Anchor a band at chest height and hold the ends with arms extended.\",\"Step back until the band is taut.\",\"Pull your hands toward your chest with elbows high.\",\"Squeeze your shoulder blades together.\",\"Return slowly without letting your shoulders round forward.\"],\"img\":\"1006.webp\",\"gif\":\"1006.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a band toward you with elbows flared wide. It targets the rear delts and upper back.\"},{\"id\":\"4415\",\"n\":\"band resisted chin up\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Attach a band to the bar and loop it around your body or waist.\",\"Hang from the bar with an underhand grip.\",\"Pull yourself up until your chin clears the bar.\",\"Squeeze your back at the top.\",\"Lower with control to a full hang.\"],\"img\":\"4415.webp\",\"gif\":\"4415.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up with a band adding resistance, building the lats and biceps.\"},{\"id\":\"4081\",\"n\":\"band reverse crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with the band anchored overhead and held in your hands.\",\"Bend your knees and lift your feet.\",\"Curl your hips off the floor toward your chest.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"4081.webp\",\"gif\":\"4081.mp4\",\"cat\":\"strength\",\"desc\":\"Lying reverse crunch with a band for added resistance, focusing on the lower abs.\"},{\"id\":\"0917\",\"n\":\"band reverse curl\",\"bp\":\"lower arms\",\"eq\":\"band\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\"],\"st\":[\"Stand on the band and hold the ends with palms down.\",\"Keep your elbows at your sides.\",\"Curl your hands up toward your shoulders.\",\"Lower slowly.\",\"Avoid swinging.\"],\"img\":\"0917.webp\",\"gif\":\"0917.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with an overhand grip using a band. It builds the forearms and brachialis.\"},{\"id\":\"6785\",\"n\":\"band seated hip abduction v. 2\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Sit tall on a bench with a band around your thighs above the knees.\",\"Keep your feet flat and planted.\",\"Press your knees apart against the band.\",\"Hold for a second at the widest point.\",\"Bring the knees back together slowly.\"],\"img\":\"6785.webp\",\"gif\":\"6785.mp4\",\"cat\":\"strength\",\"desc\":\"A seated move pushing the knees outward against a band. It strengthens the outer hips and glutes.\",\"fv\":\"6784\"},{\"id\":\"0995\",\"n\":\"band seated hip external rotation\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Sit on a bench or chair with a band looped around your knees or thighs.\",\"Keep your feet planted and your back tall.\",\"Push your knees apart against the band.\",\"Hold briefly at the widest point.\",\"Bring your knees back together slowly.\",\"Keep your torso still and avoid leaning.\"],\"img\":\"0995.webp\",\"gif\":\"0995.mp4\",\"cat\":\"strength\",\"desc\":\"A seated hip rotation with a band for resistance, working the glutes and deep hip rotators.\"},{\"id\":\"3518\",\"n\":\"band seated leg extension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Sit on a chair with a band anchored behind and looped around one ankle.\",\"Start with your knee bent to 90 degrees.\",\"Extend your leg until it is straight.\",\"Squeeze the quad at the top.\",\"Lower with control.\",\"Complete your reps, then switch legs.\"],\"img\":\"3518.webp\",\"gif\":\"3518.mp4\",\"cat\":\"strength\",\"desc\":\"A seated leg extension with a loop band around the ankle. It isolates the quadriceps.\",\"fv\":\"3519\"},{\"id\":\"3896\",\"n\":\"band seated row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Sit on the floor with your legs extended and loop a band around your feet.\",\"Hold the ends with your arms extended.\",\"Sit tall with your chest up.\",\"Pull your elbows back and squeeze your shoulder blades together.\",\"Slowly extend your arms.\",\"Keep your shoulders away from your ears.\"],\"img\":\"3896.webp\",\"gif\":\"3896.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row with a band that works the mid back and lats.\",\"fv\":\"0918\"},{\"id\":\"3121\",\"n\":\"band seated straight back row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\"],\"st\":[\"Sit on the floor with legs extended and a band around your feet.\",\"Hold the ends with your arms straight.\",\"Sit tall with a flat back.\",\"Pull the band toward your waist, squeezing your shoulder blades.\",\"Return slowly.\"],\"img\":\"3121.webp\",\"gif\":\"3121.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row with a band and a straight back that trains the lats and mid back.\"},{\"id\":\"5005\",\"n\":\"band seated underhand grip row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\",\"rear deltoids\"],\"st\":[\"Sit with your legs extended and the band looped around your feet.\",\"Hold the band ends with an underhand grip, arms straight.\",\"Pull your hands toward your lower ribs, keeping elbows close.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the start.\"],\"img\":\"5005.webp\",\"gif\":\"5005.mp4\",\"cat\":\"strength\",\"desc\":\"Seated row using a band and an underhand grip. This grip adds extra work for the lats and biceps.\"},{\"id\":\"4454\",\"n\":\"band seated wide grip row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Sit with your legs extended and loop the band around your feet.\",\"Grab the band with a wide grip and sit tall.\",\"Pull your hands toward your chest with elbows flared.\",\"Squeeze your shoulder blades together.\",\"Return slowly with control and repeat.\"],\"img\":\"4454.webp\",\"gif\":\"4454.mp4\",\"cat\":\"strength\",\"desc\":\"Seated rowing with a band and a wide grip. It works the upper back and rear shoulders.\"},{\"id\":\"3841\",\"n\":\"band side bend\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"lower back\"],\"st\":[\"Stand on the band and hold the handle in one hand.\",\"Keep your chest up and your hips square.\",\"Bend sideways toward the band hand.\",\"Return to upright.\",\"Finish your reps, then switch sides.\"],\"img\":\"3841.webp\",\"gif\":\"3841.mp4\",\"cat\":\"strength\",\"desc\":\"A standing side bend against band tension. It trains your obliques.\",\"fv\":\"1019\"},{\"id\":\"4700\",\"n\":\"band side bend press\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"triceps\",\"core\"],\"st\":[\"Stand on the band and hold the end in one hand at your shoulder.\",\"Press the band overhead as you bend gently to the opposite side.\",\"Keep your hips steady and your chest open.\",\"Return to upright as you lower your hand.\",\"Finish your reps, then switch sides.\"],\"img\":\"4700.webp\",\"gif\":\"4700.mp4\",\"cat\":\"strength\",\"desc\":\"Combining a side bend and an overhead press with a band. It trains the shoulders and obliques.\"},{\"id\":\"1020\",\"n\":\"band side crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Anchor a band overhead and kneel or stand beside it.\",\"Hold the band at your shoulder with the near hand.\",\"Bend sideways toward your hip.\",\"Return to upright under control.\",\"Finish all reps, then switch sides.\"],\"img\":\"1020.webp\",\"gif\":\"1020.mp4\",\"cat\":\"strength\",\"desc\":\"Crunch sideways against a band. It works the obliques.\"},{\"id\":\"1501\",\"n\":\"band side plank row with partner\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"rhomboids\",\"biceps\",\"core\"],\"st\":[\"Get into a side plank on one forearm, with a partner holding the band in front of you.\",\"Grip the band with your top hand and keep your hips lifted.\",\"Row your hand back toward your ribs, squeezing the shoulder blade.\",\"Return slowly without letting your hips drop.\",\"Finish your reps, then switch sides.\"],\"img\":\"1501.webp\",\"gif\":\"1501.mp4\",\"cat\":\"strength\",\"desc\":\"A side plank with a rowing motion against a band held by a partner. It trains the lats and trunk stability.\"},{\"id\":\"3776\",\"n\":\"band side step with horizontal pallof hold\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"obliques\",\"shoulders\"],\"st\":[\"Anchor the band at chest height and stand side-on to it.\",\"Press the handle straight out and sink into a quarter squat.\",\"Take small steps sideways away from the anchor, keeping your torso square.\",\"Step back in under control.\",\"Repeat for your set, then switch sides.\"],\"img\":\"3776.webp\",\"gif\":\"3776.mp4\",\"cat\":\"strength\",\"desc\":\"Side steps in a half squat while holding the band out in front of you. It works your hips and resists rotation through the core.\"},{\"id\":\"2996\",\"n\":\"band single arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Stand on the band with your feet hip width apart and hold the other end at shoulder height.\",\"Brace your core and keep your ribs down.\",\"Press the hand straight overhead until your arm is almost straight.\",\"Lower under control back to your shoulder.\",\"Complete your reps without leaning sideways.\",\"Switch arms and repeat.\"],\"img\":\"2996.webp\",\"gif\":\"2996.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press against a band. It trains the shoulders and makes your core resist twisting.\",\"fv\":\"2995\"},{\"id\":\"4701\",\"n\":\"band single leg reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down with a band looped around one foot and anchored under you.\",\"Rest your arms under your head.\",\"Lift one leg up, keeping it straight.\",\"Squeeze your glute at the top.\",\"Lower slowly, repeat, then switch legs.\"],\"img\":\"4701.webp\",\"gif\":\"4701.mp4\",\"cat\":\"strength\",\"desc\":\"A leg lift from a face-down position against a band. It trains the glutes and lower back.\"},{\"id\":\"0919\",\"n\":\"band single stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on the band on one leg and hold the ends.\",\"Keep a slight bend in the standing knee.\",\"Hinge forward with a flat back and kick the free leg back.\",\"Return by driving your hips forward.\",\"Finish reps, then switch legs.\"],\"img\":\"0919.webp\",\"gif\":\"0919.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg stiff-leg deadlift with a band. It builds the hamstrings and balance.\"},{\"id\":\"3773\",\"n\":\"band single stiff leg deadlift with single arm row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"lats\",\"upper back\",\"core\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Stand on one leg with a soft knee and the band under light tension.\",\"Hinge forward at the hips while the free leg extends behind you.\",\"Keep your back flat, then pull the handle to your ribs.\",\"Lower the handle and stand tall again. Finish your reps, then switch sides.\"],\"img\":\"3773.webp\",\"gif\":\"3773.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge with a one-arm band row. It challenges your balance and trains hamstrings, glutes and back.\"},{\"id\":\"3779\",\"n\":\"band skier\",\"bp\":\"full body\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Anchor the band overhead and hold a handle in each hand.\",\"Stand with soft knees and arms extended in front of you.\",\"Pull the handles down and back past your hips as you hinge forward.\",\"Return the arms up and stand tall in one smooth motion.\",\"Keep your back flat and move with control.\"],\"img\":\"3779.webp\",\"gif\":\"3779.mp4\",\"cat\":\"strength\",\"desc\":\"A skiing motion with the band: swing both arms down and back while hinging at the hips. It works your lats, hips and core.\"},{\"id\":\"4697\",\"n\":\"band skier v. 2\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"lats\",\"sm\":[\"lats\",\"core\",\"glutes\"],\"st\":[\"Anchor the band overhead and hold the ends with both hands.\",\"Stand with a slight bend in your knees.\",\"Pull your arms down and back past your hips.\",\"Squeeze your lats and keep your core braced.\",\"Return slowly overhead and repeat.\"],\"img\":\"4697.webp\",\"gif\":\"4697.mp4\",\"cat\":\"strength\",\"desc\":\"Swinging the arms down against a band like a skier. It works the shoulders, lats and core.\"},{\"id\":\"1504\",\"n\":\"band skull crusher\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Anchor the band behind your head and lie on your back holding the ends.\",\"Start with your arms straight above your chest.\",\"Bend only your elbows to lower your hands toward your forehead.\",\"Extend your arms back up against the band.\",\"Keep your upper arms still throughout.\"],\"img\":\"1504.webp\",\"gif\":\"1504.mp4\",\"cat\":\"strength\",\"desc\":\"A lying triceps extension using a band for resistance. It isolates the back of the upper arm.\"},{\"id\":\"3781\",\"n\":\"band split jump with single arm row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"lats\",\"upper back\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Start in a split stance with a slight bend in both knees.\",\"Jump up and switch legs in mid-air.\",\"Land softly in the opposite split stance and row the handle to your ribs.\",\"Alternate legs, and switch rowing arm for the next set.\"],\"img\":\"3781.webp\",\"gif\":\"3781.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive split jump with a one-arm band row. It builds power in your legs and trains your back.\"},{\"id\":\"4135\",\"n\":\"band split squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand on the band in a split stance and hold the ends at your shoulders.\",\"Lower your back knee toward the floor.\",\"Keep your front shin vertical.\",\"Push back up.\",\"Switch legs after your set.\"],\"img\":\"4135.webp\",\"gif\":\"4135.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with a band adding resistance for the legs.\"},{\"id\":\"4679\",\"n\":\"band split squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand on the band with your front foot and hold the other end at your shoulders.\",\"Step your other foot back into a split stance.\",\"Lower your back knee toward the floor.\",\"Keep your torso upright and your front knee stable.\",\"Drive up through the front foot, then switch legs after your set.\"],\"img\":\"4679.webp\",\"gif\":\"4679.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with band resistance. It works the quads and glutes one leg at a time.\"},{\"id\":\"3775\",\"n\":\"band split squat with horizontal pallof hold\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"obliques\"],\"st\":[\"Anchor the band at chest height and stand side-on to it.\",\"Take a split stance and press the handle straight out with both hands.\",\"Lower your back knee toward the floor without letting the band twist you.\",\"Push through your front foot to rise.\",\"Finish your reps, then switch legs and anchor side.\"],\"img\":\"3775.webp\",\"gif\":\"3775.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat done while holding the band out in front of you. It builds single-leg strength and core stability.\"},{\"id\":\"4137\",\"n\":\"band squat twist\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"quadriceps\",\"core\"],\"st\":[\"Anchor the band at chest height and stand sideways, holding the end.\",\"Squat down.\",\"Rise and rotate your arms away from the anchor.\",\"Return to the center.\",\"Complete all reps, then switch sides.\"],\"img\":\"4137.webp\",\"gif\":\"4137.mp4\",\"cat\":\"strength\",\"desc\":\"A squat paired with a band twist for core and legs.\"},{\"id\":\"4683\",\"n\":\"band squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand on the band with your feet shoulder-width apart and hold the ends at your shoulders.\",\"Brace your core and keep your chest up.\",\"Sit your hips back and down.\",\"Go to at least parallel without letting your knees cave in.\",\"Drive up through your heels and repeat.\"],\"img\":\"4683.webp\",\"gif\":\"4683.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with band resistance. It builds the thighs and glutes.\"},{\"id\":\"3774\",\"n\":\"band squat with horizontal pallof hold\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"obliques\",\"shoulders\"],\"st\":[\"Anchor the band at chest height and stand side-on to it.\",\"Hold the handle with both hands at your chest, then press it straight out.\",\"Keep your hips and shoulders square as you squat down.\",\"Stand back up while holding the band steady.\",\"Complete your reps, then turn around and repeat on the other side.\"],\"img\":\"3774.webp\",\"gif\":\"3774.mp4\",\"cat\":\"strength\",\"desc\":\"A squat while holding the band out in front of you against sideways pull. It trains your legs and anti-rotation core strength.\"},{\"id\":\"3770\",\"n\":\"band squat with single arm row\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lats\",\"upper back\",\"biceps\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Stand tall with feet shoulder width apart and the band under light tension.\",\"Sit your hips back and down into a squat while keeping your chest up.\",\"Stand up and, at the top, pull the handle to your ribs with your elbow close to your body, then let it return slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"3770.webp\",\"gif\":\"3770.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a one-arm band row. It trains your legs and your back together.\"},{\"id\":\"4086\",\"n\":\"band standard biceps curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the middle of the band with your feet hip-width apart and grip the ends.\",\"Keep your elbows at your sides and your chest tall.\",\"Curl your hands up toward your shoulders without swinging.\",\"Pause briefly, then lower slowly until your arms are straight.\",\"Keep your wrists neutral throughout.\"],\"img\":\"4086.webp\",\"gif\":\"4086.mp4\",\"cat\":\"strength\",\"desc\":\"The classic standing curl with a band underfoot. It builds the biceps with smooth, rising resistance.\"},{\"id\":\"4079\",\"n\":\"band standing alternate chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Anchor the band behind you at chest height and hold both ends.\",\"Stand in a staggered stance.\",\"Press one hand straight forward.\",\"Return and press the other hand.\",\"Keep your torso steady.\"],\"img\":\"4079.webp\",\"gif\":\"4079.mp4\",\"cat\":\"strength\",\"desc\":\"Standing band press, one arm at a time, hitting the chest and triceps.\"},{\"id\":\"4686\",\"n\":\"band standing behind head military press\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"trapezius\"],\"st\":[\"Stand on the band and hold the ends behind your head at shoulder level.\",\"Brace your core and keep your ribs down.\",\"Press your hands straight overhead.\",\"Lock out your arms without shrugging.\",\"Lower slowly back behind your head and repeat.\"],\"img\":\"4686.webp\",\"gif\":\"4686.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with the band starting behind the head. It trains the shoulders and triceps.\"},{\"id\":\"3780\",\"n\":\"band standing chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Anchor the band behind you at chest height and hold the handles at your chest.\",\"Stand in a staggered stance with your core braced.\",\"Press both hands forward until your arms are straight.\",\"Pause briefly, then return slowly to your chest.\",\"Keep your shoulders down and your back still.\"],\"img\":\"3780.webp\",\"gif\":\"3780.mp4\",\"cat\":\"strength\",\"desc\":\"A standing press against band tension. It builds your chest, shoulders and triceps.\",\"fv\":\"0920\"},{\"id\":\"5608\",\"n\":\"band standing chest press v. 2\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Anchor a band behind you and hold the ends at chest height.\",\"Stand in a split stance for balance.\",\"Press your hands forward until arms are straight.\",\"Return slowly.\",\"Keep your core braced.\"],\"img\":\"5608.webp\",\"gif\":\"5608.mp4\",\"cat\":\"strength\",\"desc\":\"Standing chest press against a band anchored behind you.\"},{\"id\":\"0921\",\"n\":\"band standing external shoulder rotation\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Anchor the band at elbow height and stand sideways to it.\",\"Hold the end with your elbow bent at 90 degrees.\",\"Rotate your forearm outward away from your body.\",\"Return slowly.\",\"Finish reps, then switch arms.\"],\"img\":\"0921.webp\",\"gif\":\"0921.mp4\",\"cat\":\"strength\",\"desc\":\"An external rotation with a band. It strengthens the rotator cuff.\"},{\"id\":\"4619\",\"n\":\"band standing hammer curl\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band and hold the ends with palms facing each other.\",\"Keep your elbows at your sides.\",\"Curl your hands up toward your shoulders without turning your wrists.\",\"Pause briefly at the top.\",\"Lower slowly back to the start.\"],\"img\":\"4619.webp\",\"gif\":\"4619.mp4\",\"cat\":\"strength\",\"desc\":\"A neutral-grip curl against band tension that builds the biceps, brachialis and forearms.\"},{\"id\":\"4034\",\"n\":\"band standing hip extension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Anchor the band low and loop it around one ankle.\",\"Stand facing the anchor, holding a support and keeping your torso upright.\",\"Press the working leg straight back.\",\"Squeeze your glute at the top without arching your back.\",\"Return slowly, finish the reps, then switch legs.\"],\"img\":\"4034.webp\",\"gif\":\"4034.mp4\",\"cat\":\"strength\",\"desc\":\"Standing kick-back against a band that works the glutes and the back of the thigh.\",\"fv\":\"0922\"},{\"id\":\"0923\",\"n\":\"band standing incline chest press\",\"bp\":\"chest\",\"eq\":\"band\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Anchor the band low behind you and hold the ends at your chest.\",\"Step into a staggered stance.\",\"Press your hands up and forward.\",\"Squeeze your chest at the top.\",\"Return slowly.\"],\"img\":\"0923.webp\",\"gif\":\"0923.mp4\",\"cat\":\"strength\",\"desc\":\"A standing press angled upward using a band. It targets the upper chest.\"},{\"id\":\"0924\",\"n\":\"band standing internal shoulder rotation\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\"],\"st\":[\"Anchor the band at elbow height and stand sideways to it.\",\"Hold the end with your elbow bent at 90 degrees.\",\"Rotate your forearm across toward your belly.\",\"Return slowly.\",\"Finish reps, then switch arms.\"],\"img\":\"0924.webp\",\"gif\":\"0924.mp4\",\"cat\":\"strength\",\"desc\":\"An internal rotation with a band. It strengthens the rotator cuff.\"},{\"id\":\"0793\",\"n\":\"band standing lateral raise\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand on the middle of the band and hold an end in each hand.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides to shoulder height.\",\"Lower slowly against the band tension.\",\"Avoid shrugging or swinging your body.\"],\"img\":\"0793.webp\",\"gif\":\"0793.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise using a band underfoot. It builds the side delts for broader-looking shoulders.\"},{\"id\":\"4033\",\"n\":\"band standing leg curl\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Anchor the band low and loop it around one ankle.\",\"Stand tall facing the anchor and hold a support.\",\"Bend your knee and curl your heel toward your glute.\",\"Keep your thighs together and hips still.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"4033.webp\",\"gif\":\"4033.mp4\",\"cat\":\"strength\",\"desc\":\"Standing leg curl using a band around the ankle. It isolates the hamstrings.\",\"fv\":\"0925\"},{\"id\":\"0926\",\"n\":\"band standing leg extension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Anchor the band behind you and loop it around one ankle.\",\"Hold support and lift the knee slightly.\",\"Straighten your knee forward.\",\"Squeeze your quad.\",\"Bend slowly to return, then switch legs.\"],\"img\":\"0926.webp\",\"gif\":\"0926.mp4\",\"cat\":\"strength\",\"desc\":\"A leg extension while standing with a band around the ankle. It works the quads.\"},{\"id\":\"1021\",\"n\":\"band standing leg raise\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"glutes\"],\"st\":[\"Loop a band around your ankles or one ankle and anchor it.\",\"Stand tall and hold a support if needed.\",\"Lift one straight leg forward to hip height.\",\"Lower slowly.\",\"Complete reps, then switch legs.\"],\"img\":\"1021.webp\",\"gif\":\"1021.mp4\",\"cat\":\"strength\",\"desc\":\"Raise a leg forward against a band loop. It targets the hip flexors and front thigh.\"},{\"id\":\"10651\",\"n\":\"band standing on bosu ball single leg abduction\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"ankles\"],\"st\":[\"Place a band around your ankles and stand on the bosu with one foot.\",\"Hold your core tight and stay tall.\",\"Lift your free leg out to the side against the band.\",\"Pause briefly at the top.\",\"Return slowly without leaning.\",\"Finish the reps, then switch legs.\"],\"img\":\"10651.webp\",\"gif\":\"10651.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hip abduction on a bosu ball against band tension. It works the outer hip and challenges your balance.\"},{\"id\":\"6195\",\"n\":\"band standing reverse curl\",\"bp\":\"lower arms\",\"eq\":\"band\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"wrist extensors\"],\"st\":[\"Stand on a band holding the ends with an overhand grip.\",\"Keep your elbows at your sides.\",\"Curl your hands up toward your shoulders.\",\"Pause at the top.\",\"Lower slowly.\",\"Keep your wrists straight.\"],\"img\":\"6195.webp\",\"gif\":\"6195.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with an overhand grip on a band. It strengthens the forearms and brachialis.\"},{\"id\":\"0930\",\"n\":\"band standing row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\"],\"st\":[\"Anchor the band at chest height and hold the ends.\",\"Step back to create tension.\",\"Pull your elbows back past your ribs.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"0930.webp\",\"gif\":\"0930.mp4\",\"cat\":\"strength\",\"desc\":\"A standing row with a band. It works the mid-back and lats.\"},{\"id\":\"4685\",\"n\":\"band standing side bend\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Stand on one end of the band and hold the other end at your side.\",\"Keep your feet shoulder-width apart.\",\"Bend sideways at the waist away from the band.\",\"Squeeze your obliques and return upright.\",\"Finish your reps, then switch sides.\"],\"img\":\"4685.webp\",\"gif\":\"4685.mp4\",\"cat\":\"strength\",\"desc\":\"A side bend with a band for oblique resistance. It strengthens the sides of the waist.\"},{\"id\":\"4575\",\"n\":\"band standing single arm row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Anchor a band at chest height and stand facing it.\",\"Hold the band in one hand with your arm extended.\",\"Step back until there is tension and brace your core.\",\"Pull your elbow back past your ribs.\",\"Squeeze your shoulder blade toward your spine.\",\"Return slowly, then switch arms.\"],\"img\":\"4575.webp\",\"gif\":\"4575.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm row with a band to train the lats and mid-back.\"},{\"id\":\"4146\",\"n\":\"band standing single arm twist row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"obliques\",\"biceps\"],\"st\":[\"Anchor the band at chest height and hold the handle in one hand.\",\"Stand sideways to the anchor with feet shoulder width apart.\",\"Row the handle toward your ribs while turning your torso gently toward the pulling side.\",\"Squeeze your back at the end of the pull.\",\"Return slowly, untwisting as your arm extends.\",\"Finish all reps, then switch sides.\"],\"img\":\"4146.webp\",\"gif\":\"4146.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm band row where you rotate the torso as you pull. It trains the lats and back while the trunk resists and controls the twist.\"},{\"id\":\"4695\",\"n\":\"band standing single arm upright row\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\"],\"st\":[\"Stand on the band and hold the other end in one hand at your thigh.\",\"Keep your elbow leading the movement.\",\"Pull your hand up toward your chest, elbow higher than the wrist.\",\"Pause at the top.\",\"Lower slowly, then repeat and switch arms.\"],\"img\":\"4695.webp\",\"gif\":\"4695.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm upright row with a band. It works the shoulders and traps.\"},{\"id\":\"4576\",\"n\":\"band standing straight arm pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper back\"],\"st\":[\"Anchor a band overhead and hold the ends with arms extended in front of you.\",\"Stand with a slight forward lean and a braced core.\",\"Keep your arms nearly straight.\",\"Pull the band down in an arc until your hands reach your thighs.\",\"Squeeze your lats.\",\"Return slowly to the start.\"],\"img\":\"4576.webp\",\"gif\":\"4576.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm band pulldown that isolates the lats.\"},{\"id\":\"0927\",\"n\":\"band standing straight leg raise\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Loop the band around your ankle and anchor it behind you.\",\"Stand tall holding support.\",\"Raise the straight leg forward.\",\"Lower slowly.\",\"Finish reps, then switch legs.\"],\"img\":\"0927.webp\",\"gif\":\"0927.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-leg raise forward while standing with a band. It works the hip flexors and quads.\"},{\"id\":\"4680\",\"n\":\"band standing triceps extension\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Anchor the band overhead and hold the ends with both hands.\",\"Keep your elbows tucked at your sides.\",\"Press your hands down until your arms are straight.\",\"Squeeze your triceps at the bottom.\",\"Let your hands rise slowly and repeat.\"],\"img\":\"4680.webp\",\"gif\":\"4680.mp4\",\"cat\":\"strength\",\"desc\":\"A standing triceps pressdown using a band. It isolates the back of the arms.\"},{\"id\":\"0928\",\"n\":\"band straight arm pulldown\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Anchor the band overhead and stand facing it.\",\"Hold the ends with straight arms.\",\"Pull your hands down toward your thighs.\",\"Squeeze your lats.\",\"Return slowly.\"],\"img\":\"0928.webp\",\"gif\":\"0928.mp4\",\"cat\":\"strength\",\"desc\":\"A pulldown with straight arms using a band. It isolates the lats.\"},{\"id\":\"3845\",\"n\":\"band straight back seated row\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"rhomboids\"],\"st\":[\"Sit with legs extended and the band around your feet.\",\"Hold the handles with your arms straight and your back tall.\",\"Pull your elbows back and squeeze your shoulder blades.\",\"Pause briefly.\",\"Return slowly without rounding your back.\"],\"img\":\"3845.webp\",\"gif\":\"3845.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row with a band while keeping your back straight. It builds your upper back and lats.\",\"fv\":\"0929\"},{\"id\":\"4678\",\"n\":\"band swing\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Stand on the band holding the other end with both hands.\",\"Hinge your hips back with a flat back.\",\"Drive your hips forward to swing your arms up to chest height.\",\"Squeeze your glutes at the top.\",\"Control the return and repeat.\"],\"img\":\"4678.webp\",\"gif\":\"4678.mp4\",\"cat\":\"strength\",\"desc\":\"A hip-hinge swing using a resisted band. It builds hip power and glute strength.\"},{\"id\":\"2970\",\"n\":\"band thruster\",\"bp\":\"full body\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\",\"hamstrings\"],\"st\":[\"Stand on the band and hold the ends at your shoulders.\",\"Squat down with your chest up.\",\"Drive up and press your hands overhead in one motion.\",\"Lock out your arms at the top.\",\"Lower your hands to your shoulders and repeat.\"],\"img\":\"2970.webp\",\"gif\":\"2970.mp4\",\"cat\":\"strength\",\"desc\":\"A squat into an overhead press using a band for resistance. It trains the legs, shoulders and heart in one move.\",\"fv\":\"2971\"},{\"id\":\"4143\",\"n\":\"band triceps kickback\",\"bp\":\"upper arms\",\"eq\":\"band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Stand on the band and hinge forward holding the other end.\",\"Pin your upper arm to your side.\",\"Extend your elbow straight back.\",\"Squeeze your triceps.\",\"Return slowly, then switch arms.\"],\"img\":\"4143.webp\",\"gif\":\"4143.mp4\",\"cat\":\"strength\",\"desc\":\"A kickback with a band for the back of the arm.\"},{\"id\":\"3591\",\"n\":\"band twist\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Anchor a band at chest height and hold the handle with both hands.\",\"Stand sideways with arms extended.\",\"Rotate your torso away from the anchor.\",\"Return under control.\",\"Finish reps, then switch sides.\"],\"img\":\"3591.webp\",\"gif\":\"3591.mp4\",\"cat\":\"strength\",\"desc\":\"A standing rotation against band resistance for the obliques and core.\",\"fv\":\"0933\"},{\"id\":\"0931\",\"n\":\"band twist (down up)\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Anchor the band low and hold it with both hands beside the anchor.\",\"Keep your hips facing forward.\",\"Rotate your torso, pulling the band diagonally up.\",\"Return slowly.\",\"Finish reps, then switch sides.\"],\"img\":\"0931.webp\",\"gif\":\"0931.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal twist with a band moving from low to high. It trains the obliques.\"},{\"id\":\"3847\",\"n\":\"band twist (up down)\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Anchor the band at a low point and stand side-on to it.\",\"Hold the handle with both hands.\",\"Rotate your torso and pull the band diagonally upward across your body.\",\"Return slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"3847.webp\",\"gif\":\"3847.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal twisting movement against band tension. It trains your obliques and rotational strength.\",\"fv\":\"0932\"},{\"id\":\"3778\",\"n\":\"band upper body lying air bike\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Lie on your back with the band anchored behind your head, a handle in each hand.\",\"Lift your shoulders and legs slightly off the floor.\",\"Alternate pulling one handle toward your opposite knee in a pedalling motion.\",\"Keep your lower back pressed down.\",\"Continue at a steady pace for your set.\"],\"img\":\"3778.webp\",\"gif\":\"3778.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you pedal your arms against the band like a bicycle. It hits your abs with added resistance.\"},{\"id\":\"2938\",\"n\":\"band upper body resistance dead bug\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lower abs\",\"shoulders\",\"hip flexors\"],\"st\":[\"Lie on your back holding a band overhead and bring your knees up at 90 degrees.\",\"Press your lower back into the floor.\",\"Lower the opposite arm and leg while keeping band tension.\",\"Return to the start and switch sides.\",\"Keep your ribs down and move slowly.\"],\"img\":\"2938.webp\",\"gif\":\"2938.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug with a band resisting your arms. It adds shoulder and trunk demand to a classic core drill.\"},{\"id\":\"4083\",\"n\":\"band upper crunch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\"],\"st\":[\"Lie on your back with your knees bent and the band anchored overhead, ends in hand.\",\"Hold the band near your chest.\",\"Curl your shoulders off the floor.\",\"Pause and squeeze your abs.\",\"Lower slowly.\"],\"img\":\"4083.webp\",\"gif\":\"4083.mp4\",\"cat\":\"strength\",\"desc\":\"Crunch lifting just the upper torso against a band for resistance.\"},{\"id\":\"0934\",\"n\":\"band upright row\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\"],\"st\":[\"Stand on the middle of the band with feet hip-width apart and grip the ends with both hands.\",\"Let your arms hang in front of your thighs with the band slightly taut.\",\"Pull your hands up along your body, leading with the elbows, until they reach about chest height.\",\"Pause briefly, then lower under control without letting the band snap back.\",\"Keep your chest tall and your shoulders away from your ears.\"],\"img\":\"0934.webp\",\"gif\":\"0934.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a band up along your body toward chest height. It works the shoulders and upper traps with gentle, joint-friendly resistance.\"},{\"id\":\"1500\",\"n\":\"band upright row (under two feet)\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\"],\"st\":[\"Stand with both feet on the middle of the band and hold the ends in front of your thighs.\",\"Keep your chest up and your core tight.\",\"Pull your hands up along your body until they reach chest height, elbows leading.\",\"Pause briefly without shrugging too high.\",\"Lower slowly back down.\"],\"img\":\"1500.webp\",\"gif\":\"1500.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row where the band is held under both feet. It builds the shoulders and upper traps.\"},{\"id\":\"0935\",\"n\":\"band upright shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Anchor a band at elbow height and stand sideways to it, holding the handle with the far hand.\",\"Tuck your elbow against your side with the elbow bent to 90 degrees.\",\"Rotate your forearm away from your belly, keeping the elbow pinned in place.\",\"Pause when your hand points slightly outward, then return slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"0935.webp\",\"gif\":\"0935.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your forearm outward against a band while the elbow stays at your side. It strengthens the small rotator cuff muscles that steady the shoulder.\"},{\"id\":\"4516\",\"n\":\"band warm up shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Hold a light band with both hands in front of your thighs, hands wide.\",\"Keep your arms straight and your core braced.\",\"Lift the band overhead and continue back behind your head as far as is comfortable.\",\"Return along the same path to the start.\",\"Keep the movement slow and controlled.\",\"Repeat for 10-15 reps, widening your grip if it feels tight.\"],\"img\":\"4516.webp\",\"gif\":\"4516.mp4\",\"cat\":\"mobility\",\"desc\":\"A light band drill that warms up the shoulder joint and loosens the surrounding muscles before training.\",\"fv\":\"1846\"},{\"id\":\"4849\",\"n\":\"banded glute ham raise v. 2\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"calves\"],\"st\":[\"Set up on a glute-ham bench or anchor your feet with a band assisting you.\",\"Start with your torso down and hips locked.\",\"Curl up using your hamstrings.\",\"Squeeze your glutes at the top.\",\"Lower with control.\"],\"img\":\"4849.webp\",\"gif\":\"4849.mp4\",\"cat\":\"strength\",\"desc\":\"A glute-ham raise with a band assisting the movement. It strengthens the hamstrings and glutes.\"},{\"id\":\"4905\",\"n\":\"banded glute ham raise v. 3\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"calves\"],\"st\":[\"Set up on a glute ham bench with your ankles locked and a band for support.\",\"Cross your arms or hold the band in front of you.\",\"Lower your torso toward the floor with a straight body.\",\"Squeeze your hamstrings and glutes to pull yourself back up.\",\"Stop when your body is in a straight line.\",\"Move slowly and avoid jerking.\"],\"img\":\"4905.webp\",\"gif\":\"4905.mp4\",\"cat\":\"strength\",\"desc\":\"A glute ham raise with a band for assistance, a third variation. It builds the hamstrings and glutes.\"},{\"id\":\"4839\",\"n\":\"banded lower body dead bug\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with a band around your feet and legs bent over your hips.\",\"Press your lower back into the floor.\",\"Extend one leg away against the band.\",\"Return it and switch legs.\",\"Keep your ribs down and your core braced.\"],\"img\":\"4839.webp\",\"gif\":\"4839.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug with a band around the feet that adds resistance for the legs. It trains the lower abs and anti-extension control.\"},{\"id\":\"4721\",\"n\":\"bar biceps curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding a bar with an underhand shoulder-width grip.\",\"Keep your elbows at your sides.\",\"Curl the bar up to shoulder height.\",\"Squeeze your biceps.\",\"Lower slowly without swinging.\"],\"img\":\"4721.webp\",\"gif\":\"4721.mp4\",\"cat\":\"strength\",\"desc\":\"A standard bar curl for building the biceps with a steady, controlled lift.\"},{\"id\":\"11093\",\"n\":\"barbell 2 3 deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with your feet hip width and the bar over your mid foot.\",\"Grip the bar, brace your core, and keep your back flat.\",\"Push the floor away and stand up.\",\"Lower the bar back toward the floor under control.\",\"Reset each rep and keep your back neutral.\"],\"img\":\"11093.webp\",\"gif\":\"11093.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift variation with a two-thirds range of motion. It is a good way to drill the lower, hardest part of the lift.\"},{\"id\":\"5659\",\"n\":\"barbell anderson squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set the bar in safety pins at the bottom of a squat.\",\"Get under it and brace.\",\"Drive up from a dead stop.\",\"Lower back to the pins.\",\"Reset on every rep.\"],\"img\":\"5659.webp\",\"gif\":\"5659.mp4\",\"cat\":\"strength\",\"desc\":\"Squat starting from the bottom position, pausing each rep to build strength.\"},{\"id\":\"5226\",\"n\":\"barbell back wide shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"forearms\",\"grip muscles\"],\"st\":[\"Hold a barbell behind your thighs with a wide overhand grip.\",\"Stand tall with your chest up.\",\"Shrug your shoulders straight up.\",\"Squeeze at the top for a second.\",\"Lower slowly without leaning forward.\"],\"img\":\"5226.webp\",\"gif\":\"5226.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip shrug with the barbell held behind your body. It hits the traps from a slightly different angle.\"},{\"id\":\"4841\",\"n\":\"barbell band assisted deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"quadriceps\"],\"st\":[\"Attach a band to the barbell and anchor it overhead or to a rack.\",\"Stand with the bar over midfoot and grip just outside your knees.\",\"Brace and push the floor away to lift.\",\"Stand tall and lock out your hips.\",\"Lower with control.\"],\"img\":\"4841.webp\",\"gif\":\"4841.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell deadlift with a band that assists off the floor. It lets you train heavy lockout work and hip drive.\"},{\"id\":\"7620\",\"n\":\"barbell banded bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Set bands on the bar and lie on a flat bench with your feet planted.\",\"Unrack the bar over your chest with a firm grip.\",\"Lower it to your mid chest under control.\",\"Press up and out until your arms are straight.\",\"Keep your shoulder blades pinched and your feet down.\"],\"img\":\"7620.webp\",\"gif\":\"7620.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with bands attached to the bar, so resistance rises toward lockout. It builds pressing power across the chest and triceps.\"},{\"id\":\"4061\",\"n\":\"barbell banded bench squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Set a bench behind you and place the bar on your upper back with bands attached.\",\"Stand with feet shoulder-width apart.\",\"Sit back and down until you touch the bench.\",\"Keep your chest up and knees pushing out.\",\"Drive through your heels to stand.\"],\"img\":\"4061.webp\",\"gif\":\"4061.mp4\",\"cat\":\"strength\",\"desc\":\"Squat to a bench with bands adding tension. It teaches depth control and builds the glutes and thighs.\"},{\"id\":\"4173\",\"n\":\"barbell banded romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand on the band with it attached to the barbell and hold the bar at your thighs.\",\"Push your hips back with soft knees.\",\"Lower the bar along your legs to mid shin.\",\"Drive your hips forward to stand tall.\",\"Squeeze your glutes at the top.\",\"Keep your back flat throughout.\"],\"img\":\"4173.webp\",\"gif\":\"4173.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift with a band adding resistance as you stand. It builds the hamstrings and glutes.\"},{\"id\":\"3530\",\"n\":\"barbell banded squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Set the bands on the rack and barbell.\",\"Rest the bar on your upper back.\",\"Stand with feet shoulder-width apart.\",\"Squat down with your chest up.\",\"Drive up through your heels.\",\"Brace your core throughout.\"],\"img\":\"3530.webp\",\"gif\":\"3530.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat with bands attached to increase tension at the top.\"},{\"id\":\"4203\",\"n\":\"barbell banded sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hamstrings\",\"lower back\"],\"st\":[\"Set the band over the bar.\",\"Stand wide.\",\"Grip inside your legs.\",\"Drive up.\",\"Squeeze glutes.\",\"Lower with control.\"],\"img\":\"4203.webp\",\"gif\":\"4203.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance deadlift with band resistance.\"},{\"id\":\"9932\",\"n\":\"barbell banded weighted plate bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench and make sure the bands and plates are secured on the barbell.\",\"Unrack the bar and hold it over your chest with your arms extended.\",\"Lower the bar to your mid chest under control.\",\"Press it back up, fighting the rising band tension.\",\"Lock out your elbows without losing shoulder position.\",\"Keep your feet planted and shoulder blades pinched together.\"],\"img\":\"9932.webp\",\"gif\":\"9932.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with resistance bands and plates added to the bar so the load gets heavier as you lock out. It builds chest and triceps strength through the top range.\"},{\"id\":\"1610\",\"n\":\"barbell behind back finger curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand holding a barbell behind your back with an overhand grip, arms straight.\",\"Let the bar roll down to your fingertips.\",\"Curl your fingers closed and lift the bar back into your palms.\",\"Curl your wrists up a little at the top.\",\"Lower with control and repeat.\"],\"img\":\"1610.webp\",\"gif\":\"1610.mp4\",\"cat\":\"strength\",\"desc\":\"A forearm exercise where you hold the bar behind your back and roll it down to your fingertips. It builds grip and forearm strength.\"},{\"id\":\"5663\",\"n\":\"barbell behind the back deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand in front of the bar behind your legs.\",\"Squat down and grip the bar behind you.\",\"Stand up by driving your hips forward.\",\"Lower the bar under control.\",\"Keep your back flat.\"],\"img\":\"5663.webp\",\"gif\":\"5663.mp4\",\"cat\":\"strength\",\"desc\":\"Deadlift with the bar held behind you, a quad-friendly lift.\"},{\"id\":\"4857\",\"n\":\"barbell behind the back push press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"quadriceps\",\"upper chest\",\"core\"],\"st\":[\"Hold a barbell on your upper back with a wide grip.\",\"Dip your knees slightly.\",\"Drive up explosively and press overhead.\",\"Lock out your arms.\",\"Lower the bar back to your shoulders.\"],\"img\":\"4857.webp\",\"gif\":\"4857.mp4\",\"cat\":\"strength\",\"desc\":\"A push press with the bar behind the neck. It builds overhead power.\"},{\"id\":\"3730\",\"n\":\"barbell behind the back shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"grip muscles\",\"upper back\"],\"st\":[\"Stand holding a barbell behind your back with straight arms.\",\"Keep your chest up and shoulders relaxed.\",\"Shrug your shoulders straight up toward your ears.\",\"Pause at the top.\",\"Lower slowly without rolling your shoulders.\"],\"img\":\"3730.webp\",\"gif\":\"3730.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug with the bar held behind your thighs, which shifts the load slightly to the mid traps.\"},{\"id\":\"6797\",\"n\":\"barbell bench lateral step up\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"calves\"],\"st\":[\"Place the bar on your upper back and stand beside a bench.\",\"Put the inside foot flat on the bench.\",\"Press through that heel and stand up on the bench.\",\"Lower the other foot back down under control.\",\"Complete your reps, then switch sides.\"],\"img\":\"6797.webp\",\"gif\":\"6797.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways step up onto a bench with a barbell on the back. It builds single-leg strength in the quads and glutes.\"},{\"id\":\"3174\",\"n\":\"barbell bench press (knees at 90 degrees)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Lie on a bench and lift your feet with your knees bent to 90 degrees.\",\"Grip the bar slightly wider than your shoulders.\",\"Unrack and hold it over your chest.\",\"Lower the bar to your mid chest with control.\",\"Press it back up until your arms are straight.\",\"Keep your lower back flat on the bench.\"],\"img\":\"3174.webp\",\"gif\":\"3174.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with your feet up and your knees bent to 90 degrees. This keeps your lower back flat and your trunk working.\"},{\"id\":\"6813\",\"n\":\"barbell bench press (side pov)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with your eyes under the bar and feet planted.\",\"Grip the bar slightly wider than shoulder width and unrack it.\",\"Lower the bar to your mid chest with elbows at about 45 degrees.\",\"Touch lightly and press back up over your shoulders.\",\"Keep your shoulder blades pinched throughout.\"],\"img\":\"6813.webp\",\"gif\":\"6813.mp4\",\"cat\":\"strength\",\"desc\":\"The barbell bench press seen from the side to check bar path and form. It builds the chest, shoulders and triceps.\"},{\"id\":\"3185\",\"n\":\"barbell bench press (with hanging band technique)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Hang weights from each end of the bar with bands.\",\"Lie on the bench and unrack the bar.\",\"Hold it over your chest.\",\"Lower the bar slowly to your mid chest.\",\"Press up and keep the bar steady.\",\"Use a lighter load than a normal bench press.\"],\"img\":\"3185.webp\",\"gif\":\"3185.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with bands hanging weights from the bar. The shaky load trains control and stability.\"},{\"id\":\"4201\",\"n\":\"barbell bench press against chains\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on bench.\",\"Unrack the bar.\",\"Lower to chest.\",\"Press up.\",\"Lock out.\",\"Keep feet planted.\"],\"img\":\"4201.webp\",\"gif\":\"4201.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with chains adding load.\"},{\"id\":\"10560\",\"n\":\"barbell bench press catch\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with a spotter or safety pins set.\",\"Unrack the bar over your chest.\",\"Lower the bar toward your chest under control.\",\"Stop it just above the chest and press up.\",\"Keep your feet planted and your shoulder blades pinched.\"],\"img\":\"10560.webp\",\"gif\":\"10560.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press where you lower the bar and catch it quickly before pressing. It trains chest strength and control.\"},{\"id\":\"4070\",\"n\":\"barbell bench press with 1 board\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with a single board on your chest.\",\"Grip the bar slightly wider than shoulders.\",\"Lower the bar until it touches the board.\",\"Press back up to full extension.\",\"Keep your feet planted and shoulder blades pinched.\"],\"img\":\"4070.webp\",\"gif\":\"4070.mp4\",\"cat\":\"strength\",\"desc\":\"Bench press with a single board, shortening the range just a little. It builds pressing power near lockout.\"},{\"id\":\"4069\",\"n\":\"barbell bench press with 2 board\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with two boards stacked on your chest.\",\"Grip the bar slightly wider than shoulders.\",\"Lower the bar until it touches the boards.\",\"Press back up to full extension.\",\"Keep your feet planted and shoulder blades pinched.\"],\"img\":\"4069.webp\",\"gif\":\"4069.mp4\",\"cat\":\"strength\",\"desc\":\"Bench press with two boards on the chest, giving a slightly longer range than the three board press.\"},{\"id\":\"4068\",\"n\":\"barbell bench press with 3 board\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with three boards stacked on your chest.\",\"Grip the bar slightly wider than shoulders.\",\"Lower the bar until it touches the boards.\",\"Press back up to full extension.\",\"Keep your feet planted and shoulder blades pinched.\"],\"img\":\"4068.webp\",\"gif\":\"4068.mp4\",\"cat\":\"strength\",\"desc\":\"Bench press with three boards on the chest limiting the range. It overloads the lockout phase.\"},{\"id\":\"4414\",\"n\":\"barbell bench press with band suspended kettlebell\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Lie on a bench and unrack the barbell with kettlebells hung from bands.\",\"Plant your feet and brace your core.\",\"Lower the bar slowly to your mid chest.\",\"Press it up to full extension while keeping the bar steady.\",\"Rack the bar safely when finished.\"],\"img\":\"4414.webp\",\"gif\":\"4414.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with kettlebells hanging from bands on the bar. The swinging load forces your stabilising muscles to work harder.\"},{\"id\":\"1509\",\"n\":\"barbell bench squat (with chains)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Set a bench behind you and load the bar with chains.\",\"Place the bar on your upper back and stand with feet shoulder-width apart.\",\"Sit back and down until you touch the bench lightly.\",\"Keep your chest up and your knees tracking over your toes.\",\"Drive through your feet to stand, feeling the chains add weight.\"],\"img\":\"1509.webp\",\"gif\":\"1509.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat to a bench with chains adding load as you stand. It builds leg and hip strength and teaches consistent depth.\"},{\"id\":\"7565\",\"n\":\"barbell bent arm pullover v. 2\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on a bench holding a barbell above your chest.\",\"Keep a slight elbow bend.\",\"Lower the bar behind your head.\",\"Pull it back over your chest.\",\"Keep your ribs down.\"],\"img\":\"7565.webp\",\"gif\":\"7565.mp4\",\"cat\":\"strength\",\"desc\":\"Pullover with slightly bent arms using a barbell for lats and chest.\",\"nd\":[\"bench\"]},{\"id\":\"3991\",\"n\":\"barbell bent over wide alternate row plus\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Hinge forward holding the barbell with a wide grip.\",\"Keep your back flat.\",\"Pull one side toward your ribs.\",\"Lower and pull the other side.\",\"Keep your hips still.\"],\"img\":\"3991.webp\",\"gif\":\"3991.mp4\",\"cat\":\"strength\",\"desc\":\"A wide grip bent over row done with alternating pulls. It builds the upper back and lats.\"},{\"id\":\"3721\",\"n\":\"barbell bent over wide grip row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"rear deltoids\",\"biceps\",\"lower back\"],\"st\":[\"Hold a barbell with a wide overhand grip and hinge forward with a flat back.\",\"Let the bar hang at arm length below your chest.\",\"Pull the bar toward your lower chest, flaring your elbows.\",\"Squeeze your shoulder blades together.\",\"Lower the bar with control.\"],\"img\":\"3721.webp\",\"gif\":\"3721.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a wide overhand grip that emphasises the upper back and rear delts.\"},{\"id\":\"3992\",\"n\":\"barbell bent over wide row plus\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Hinge forward with a wide overhand grip.\",\"Keep a flat back.\",\"Row the bar toward your upper abdomen.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\"],\"img\":\"3992.webp\",\"gif\":\"3992.mp4\",\"cat\":\"strength\",\"desc\":\"A wide grip bent over row aimed at the upper back. It builds the lats and rear shoulders.\"},{\"id\":\"4962\",\"n\":\"barbell box squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"lower back\"],\"st\":[\"Place a box behind you and a barbell on your upper back.\",\"Push your hips back and sit onto the box.\",\"Pause briefly without relaxing.\",\"Drive through your feet to stand.\",\"Keep your chest up.\",\"Keep your knees tracking over your toes.\"],\"img\":\"4962.webp\",\"gif\":\"4962.mp4\",\"cat\":\"strength\",\"desc\":\"A squat to a box behind you. It trains the hips and legs while teaching depth control.\"},{\"id\":\"10049\",\"n\":\"barbell butterfly z press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Sit on the floor with legs out in front and the bar at upper-chest height.\",\"Take a wide grip and brace your abs.\",\"Press the bar overhead until your arms are straight.\",\"Lower it back to your upper chest under control.\",\"Keep your back tall and avoid arching.\",\"Use a light weight at first.\"],\"img\":\"10049.webp\",\"gif\":\"10049.mp4\",\"cat\":\"strength\",\"desc\":\"A seated floor press overhead with a barbell and a wide hand position. It builds strong shoulders with a stable trunk.\"},{\"id\":\"9930\",\"n\":\"barbell california press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a flat bench and hold a barbell above your chest with a shoulder width grip.\",\"Bend your elbows to lower the bar toward your forehead like a skull crusher.\",\"As it nears your head, let the elbows travel down so the bar moves toward the upper chest.\",\"Press the bar up and slightly back over your shoulders.\",\"Lower again along the same path and repeat.\",\"Use a lighter weight and keep your wrists straight.\"],\"img\":\"9930.webp\",\"gif\":\"9930.mp4\",\"cat\":\"strength\",\"desc\":\"A hybrid of a skull crusher and a bench press where the bar lowers toward the forehead then presses up and back over the chest. It hits the chest and triceps together.\",\"nd\":[\"bench\"]},{\"id\":\"2336\",\"n\":\"barbell chest bench press forearms (form check)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench with your eyes under the bar and your feet planted.\",\"Grip the bar slightly wider than shoulder-width.\",\"Keep your forearms vertical when the bar is at your chest.\",\"Lower the bar with control to the mid-chest.\",\"Press it up to straight arms without flaring the elbows.\",\"Repeat for the planned reps.\"],\"img\":\"2336.webp\",\"gif\":\"2336.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press form check that shows how the forearms should line up under the bar for a safe and strong press.\"},{\"id\":\"3729\",\"n\":\"barbell chest press on stability ball\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Sit on a stability ball and walk your feet out until your upper back rests on it.\",\"Keep your hips up and take the barbell above your chest.\",\"Lower the bar to your chest.\",\"Press it back up to full extension.\",\"Keep your core tight and feet planted.\"],\"img\":\"3729.webp\",\"gif\":\"3729.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell press with your upper back on a stability ball, which adds a core and balance challenge.\"},{\"id\":\"5122\",\"n\":\"barbell clean and jerk\",\"bp\":\"full body\",\"eq\":\"olympic barbell\",\"tg\":\"traps\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"shoulders\",\"triceps\",\"hamstrings\"],\"st\":[\"Set up over the bar with a flat back and hands outside your knees.\",\"Pull the bar off the floor and catch it at your shoulders in a squat.\",\"Stand up with the bar racked.\",\"Dip slightly and drive the bar overhead, splitting your feet.\",\"Recover your feet, stand tall and lower the bar under control.\"],\"img\":\"5122.webp\",\"gif\":\"5122.mp4\",\"cat\":\"olympic\",\"desc\":\"Lift a barbell from the floor to your shoulders, then drive it overhead. A technical full-body lift for power and speed.\"},{\"id\":\"5190\",\"n\":\"barbell clean and jerk v. 2\",\"bp\":\"full body\",\"eq\":\"olympic barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"triceps\",\"upper back\"],\"st\":[\"Grip the bar just outside your knees with a flat back.\",\"Pull explosively and drop under the bar, catching it on your shoulders.\",\"Stand up fully and reset your feet.\",\"Dip, drive, and split your legs as you punch the bar overhead.\",\"Recover your feet and lower the bar with control.\"],\"img\":\"5190.webp\",\"gif\":\"5190.mp4\",\"cat\":\"olympic\",\"desc\":\"The classic Olympic lift. You clean the bar to your shoulders, then jerk it overhead.\"},{\"id\":\"1515\",\"n\":\"barbell clean deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"upper back\",\"grip muscles\"],\"st\":[\"Stand with the bar over your mid-foot and grip just outside your knees.\",\"Set a flat back, chest up and shoulders over the bar.\",\"Push the floor away to lift the bar, keeping it close to your legs.\",\"Stand tall with hips and knees fully extended.\",\"Lower the bar back down with control along the same path.\"],\"img\":\"1515.webp\",\"gif\":\"1515.mp4\",\"cat\":\"olympic\",\"desc\":\"A deadlift performed with a clean-style setup and path. It trains the pulling position used in the clean.\"},{\"id\":\"1516\",\"n\":\"barbell clean from blocks\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Set the bar on blocks and grip it just outside your knees with a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull yourself under the bar and catch it on your front shoulders in a full squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1516.webp\",\"gif\":\"1516.mp4\",\"cat\":\"olympic\",\"desc\":\"A clean started from blocks at about knee height. It trains the explosive pull and the catch without the first pull from the floor.\"},{\"id\":\"5705\",\"n\":\"barbell clean high pull\",\"bp\":\"upper legs\",\"eq\":\"olympic barbell\",\"tg\":\"traps\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"upper back\",\"quadriceps\"],\"st\":[\"Set up over the bar with feet hip-width apart and a flat back.\",\"Lift the bar to your knees with your chest up.\",\"Extend your hips and knees explosively and shrug hard.\",\"Pull the bar up to chest height with elbows high and outside.\",\"Lower the bar back to the floor with control.\"],\"img\":\"5705.webp\",\"gif\":\"5705.mp4\",\"cat\":\"olympic\",\"desc\":\"A powerful pull from the floor that sends the bar to chest height. It develops explosive hips, traps and shoulders.\"},{\"id\":\"1517\",\"n\":\"barbell clean pull\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Set up over the bar with a flat back and a grip just outside your knees.\",\"Lift the bar past your knees, keeping it close.\",\"Extend your hips and knees explosively and shrug.\",\"Let your elbows rise high, but do not catch the bar.\",\"Lower the bar with control and reset.\"],\"img\":\"1517.webp\",\"gif\":\"1517.mp4\",\"cat\":\"olympic\",\"desc\":\"The explosive pull of a clean, finished with a shrug and without the catch. It builds power and bar speed.\"},{\"id\":\"4981\",\"n\":\"barbell close grip biceps curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding a barbell with an underhand grip, hands closer than shoulder width.\",\"Keep your elbows tucked against your sides.\",\"Curl the bar up toward your shoulders without swinging.\",\"Squeeze your biceps at the top for a moment.\",\"Lower the bar slowly until your arms are straight.\"],\"img\":\"4981.webp\",\"gif\":\"4981.mp4\",\"cat\":\"strength\",\"desc\":\"Barbell curl with hands placed close together. This grip puts extra emphasis on the outer part of the biceps.\"},{\"id\":\"6271\",\"n\":\"barbell close grip larsen press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a bench and hold the bar with a close, shoulder-width grip.\",\"Lift your feet off the floor and stretch your legs out in front of you.\",\"Lower the bar to your lower chest under control.\",\"Press the bar back up until your arms are straight.\",\"Keep your back flat on the bench and your core tight throughout.\"],\"img\":\"6271.webp\",\"gif\":\"6271.mp4\",\"cat\":\"strength\",\"desc\":\"A larsen press with a close grip: you bench with your feet off the floor, which removes leg drive and puts the work on chest and triceps.\",\"nd\":[\"bench\"]},{\"id\":\"3328\",\"n\":\"barbell complex stiff leg deadlift clean step\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"upper back\",\"shoulders\",\"quadriceps\"],\"st\":[\"Stand holding a light barbell with an overhand grip at thigh height.\",\"Lower the bar down your legs with soft knees and a flat back.\",\"Stand up, then pull the bar explosively and catch it on your shoulders.\",\"Take a controlled step forward with the bar racked.\",\"Step back, lower the bar and begin the next round.\"],\"img\":\"3328.webp\",\"gif\":\"3328.mp4\",\"cat\":\"olympic\",\"desc\":\"A barbell complex that links a stiff leg deadlift into a clean and then a step. It builds posterior chain power and rhythm.\"},{\"id\":\"10092\",\"n\":\"barbell core squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"lower back\",\"adductors\"],\"st\":[\"Rest a barbell on your upper back and stand with feet shoulder width apart.\",\"Take a deep breath and brace your abs.\",\"Squat down until your thighs are about parallel.\",\"Keep your torso tight and chest up.\",\"Drive through your feet to stand back up.\",\"Exhale at the top and reset your brace each rep.\"],\"img\":\"10092.webp\",\"gif\":\"10092.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat focused on bracing your core hard through the lift. It builds leg strength and trunk stability.\"},{\"id\":\"5883\",\"n\":\"barbell curl press extension\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"forearms\"],\"st\":[\"Stand holding a barbell with an underhand grip at thigh level.\",\"Curl the bar up to your shoulders without swinging.\",\"Press it overhead until your arms are straight.\",\"Bend your elbows to lower the bar behind your head, keeping your upper arms still.\",\"Extend, bring the bar back to the front and lower it under control.\",\"Use a light weight to keep your form tidy.\"],\"img\":\"5883.webp\",\"gif\":\"5883.mp4\",\"cat\":\"strength\",\"desc\":\"A three-part arm combo: curl, press overhead, then lower behind the head for a triceps extension. It works the whole arm in one set.\"},{\"id\":\"3723\",\"n\":\"barbell curtsey lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Rest a barbell across your upper back and stand tall.\",\"Step one leg back and across behind the other, like a curtsey.\",\"Lower until your front thigh is near parallel.\",\"Push through your front heel to stand.\",\"Alternate sides or finish one side first.\"],\"img\":\"3723.webp\",\"gif\":\"3723.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge where you step diagonally behind you with a barbell on your back. It works the glutes and outer hips.\",\"fv\":\"8190\"},{\"id\":\"0966\",\"n\":\"barbell deadlift (back view)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"upper back\",\"grip muscles\"],\"st\":[\"Stand with feet hip width apart, bar over mid-foot.\",\"Hinge at the hips and grip the bar just outside your legs.\",\"Brace your core and keep your back flat.\",\"Push the floor away and stand up, keeping the bar close to your legs.\",\"Lock out your hips at the top without leaning back.\",\"Lower the bar by pushing your hips back and bending your knees.\"],\"img\":\"0966.webp\",\"gif\":\"0966.mp4\",\"cat\":\"strength\",\"desc\":\"The barbell deadlift shown from behind. It's a full posterior chain lift for the glutes, hamstrings and back.\"},{\"id\":\"0967\",\"n\":\"barbell deadlift (front pov)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"upper back\",\"grip muscles\"],\"st\":[\"Stand with feet hip width apart, bar over mid-foot.\",\"Hinge at the hips and grip the bar just outside your legs.\",\"Brace your core and keep your back flat.\",\"Push the floor away and stand up, keeping the bar close to your legs.\",\"Lock out your hips at the top without leaning back.\",\"Lower the bar by pushing your hips back and bending your knees.\"],\"img\":\"0967.webp\",\"gif\":\"0967.mp4\",\"cat\":\"strength\",\"desc\":\"The barbell deadlift seen from the front. A strong lift for the glutes, hamstrings and back.\"},{\"id\":\"6692\",\"n\":\"barbell deadlift (side pov)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"grip muscles\",\"trapezius\"],\"st\":[\"Stand with the bar over mid-foot and grip it just outside your legs.\",\"Brace your core, flatten your back and pull the slack out of the bar.\",\"Push the floor away and stand up, keeping the bar close to your legs.\",\"Lock out the hips without leaning back.\",\"Hinge at the hips and lower the bar under control.\"],\"img\":\"6692.webp\",\"gif\":\"6692.mp4\",\"cat\":\"strength\",\"desc\":\"The classic barbell deadlift shown from the side to check form. It trains the whole posterior chain.\"},{\"id\":\"4199\",\"n\":\"barbell deadlift against chains\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\"],\"st\":[\"Set chains on the bar.\",\"Grip the bar.\",\"Brace.\",\"Drive your feet through the floor.\",\"Stand tall.\",\"Lower with control.\"],\"img\":\"4199.webp\",\"gif\":\"4199.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with chains adding load toward lockout.\"},{\"id\":\"6034\",\"n\":\"barbell deadlift from blocks\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"grip muscles\"],\"st\":[\"Set the bar on blocks or a raised platform.\",\"Stand with the bar over your mid-foot.\",\"Hinge and grip the bar just outside your knees.\",\"Brace your core and keep your back flat.\",\"Drive through your feet to stand tall.\",\"Lower the bar back to the blocks with control.\"],\"img\":\"6034.webp\",\"gif\":\"6034.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with the bar raised on blocks, which shortens the range of motion and lets you lift heavier.\"},{\"id\":\"5702\",\"n\":\"barbell deadlift from deficit\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"grip muscles\",\"core\"],\"st\":[\"Stand on a low plate or platform with the bar over mid-foot.\",\"Hinge down and grip the bar just outside your legs.\",\"Flatten your back and brace your core.\",\"Push the floor away and stand tall.\",\"Lower the bar back under control.\"],\"img\":\"5702.webp\",\"gif\":\"5702.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift performed while standing on a low platform. The longer range of motion trains the start of the pull and the legs.\"},{\"id\":\"4126\",\"n\":\"barbell deadstop row with rack\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"lower back\"],\"st\":[\"Set the bar on pins at knee height.\",\"Hinge forward and grip the bar.\",\"Row it to your lower ribs.\",\"Lower it back to the pins and pause.\",\"Reset your back before the next rep.\"],\"img\":\"4126.webp\",\"gif\":\"4126.mp4\",\"cat\":\"strength\",\"desc\":\"A row starting from the rack pins, resetting every rep for strict pulling.\"},{\"id\":\"1518\",\"n\":\"barbell decline bench lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Place the bar on your upper back and rest one foot behind you on a decline bench.\",\"Step the front foot out to set a stable stance.\",\"Lower your back knee toward the floor, torso upright.\",\"Drive through the front foot to rise.\",\"Finish your reps, then switch legs.\"],\"img\":\"1518.webp\",\"gif\":\"1518.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with the back foot on a decline bench and a barbell on your back. It builds single-leg strength.\"},{\"id\":\"10115\",\"n\":\"barbell decline close grip press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a decline bench and grab the bar with hands about shoulder width apart.\",\"Unrack the bar and hold it over your lower chest with locked elbows.\",\"Lower the bar to your lower chest, keeping elbows tucked close.\",\"Press the bar back up until your arms are straight.\",\"Keep your wrists stacked over your elbows and use a spotter.\"],\"img\":\"10115.webp\",\"gif\":\"10115.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip press on a decline bench that loads the triceps and lower chest together.\"},{\"id\":\"9516\",\"n\":\"barbell elevated heel clean grip squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"lower back\",\"core\"],\"st\":[\"Place your heels on small plates and hold a bar across your upper back with a clean-width grip.\",\"Brace your core and keep your chest up.\",\"Sit down into a deep squat with knees tracking over toes.\",\"Pause at the bottom.\",\"Drive up through your feet to stand.\"],\"img\":\"9516.webp\",\"gif\":\"9516.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with your heels raised and a clean-width grip, which keeps the torso upright and loads the quads.\"},{\"id\":\"4178\",\"n\":\"barbell elevated heel squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Place your heels on small plates under the bar.\",\"Set the bar on your upper back.\",\"Brace your core and squat down.\",\"Keep your torso upright.\",\"Drive through your feet to stand.\",\"Keep your knees tracking over your toes.\"],\"img\":\"4178.webp\",\"gif\":\"4178.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat with heels on a plate for extra knee travel. It emphasises the quads.\"},{\"id\":\"10110\",\"n\":\"barbell fat bar reverse curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"grip muscles\"],\"st\":[\"Hold a fat barbell with an overhand grip.\",\"Stand with elbows by your sides.\",\"Curl the bar up toward your shoulders.\",\"Squeeze at the top.\",\"Lower slowly.\",\"Keep your wrists straight.\"],\"img\":\"10110.webp\",\"gif\":\"10110.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse curl with a thick bar, which challenges your grip and the forearm muscles even more.\"},{\"id\":\"6584\",\"n\":\"barbell feet flat bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a bench and place your feet flat on it, knees bent.\",\"Grip the bar slightly wider than your shoulders.\",\"Lower the bar to your mid-chest.\",\"Press it back up until your arms are straight.\",\"Keep your lower back flat and your core tight.\"],\"img\":\"6584.webp\",\"gif\":\"6584.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with your feet flat on the bench or surface instead of the floor, limiting leg drive and focusing on the chest.\"},{\"id\":\"3724\",\"n\":\"barbell floor chest press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on the floor with your knees bent and a barbell set above your chest.\",\"Grip the bar slightly wider than shoulder width.\",\"Lower the bar until your upper arms touch the floor.\",\"Pause briefly.\",\"Press the bar back up to full extension.\"],\"img\":\"3724.webp\",\"gif\":\"3724.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell press from the floor. The floor limits the range and takes pressure off your shoulders.\"},{\"id\":\"9696\",\"n\":\"barbell frog stance deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet wide, toes turned out, and a bar over mid-foot.\",\"Hinge and bend your knees to grip the bar.\",\"Brace your core and keep your back flat.\",\"Drive through your feet to stand tall.\",\"Lower the bar with control.\"],\"img\":\"9696.webp\",\"gif\":\"9696.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a wide, toes-out stance. It shortens the range and loads the glutes and inner thighs.\"},{\"id\":\"3727\",\"n\":\"barbell front bench squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\"],\"st\":[\"Place a bench behind you and rest the bar across your front shoulders.\",\"Keep your elbows high and your chest up.\",\"Sit back and down until you lightly touch the bench.\",\"Drive through your feet to stand.\",\"Avoid rocking or collapsing onto the bench.\"],\"img\":\"3727.webp\",\"gif\":\"3727.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat to a bench behind you, which helps with depth control and keeps the load in front.\"},{\"id\":\"3871\",\"n\":\"barbell front chest squat with resistance band\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\",\"upper back\"],\"st\":[\"Set up a band under your feet or anchored to the floor and attach it to the bar.\",\"Rest the bar on your front shoulders with elbows high.\",\"Stand with feet shoulder-width apart and brace your core.\",\"Squat down until your thighs are about parallel.\",\"Drive up through your heels against the band tension.\",\"Keep your chest tall throughout.\"],\"img\":\"3871.webp\",\"gif\":\"3871.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat with a band adding resistance, building strong quads and a tall, braced torso.\"},{\"id\":\"3399\",\"n\":\"barbell front rack lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"upper back\"],\"st\":[\"Rest the barbell on your front shoulders with elbows high.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor.\",\"Keep your chest tall and your core braced.\",\"Push through the front foot to return.\",\"Alternate legs or finish all reps on one side.\"],\"img\":\"3399.webp\",\"gif\":\"3399.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge with the barbell in the front rack, emphasizing quads and an upright torso.\"},{\"id\":\"4382\",\"n\":\"barbell front rack lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Rest the barbell on the front of your shoulders with elbows high.\",\"Stand tall with feet hip-width apart.\",\"Step forward into a long stride and lower until both knees reach about 90 degrees.\",\"Push through the front foot to return to standing.\",\"Alternate legs, keeping your torso upright.\"],\"img\":\"4382.webp\",\"gif\":\"4382.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge with the bar resting on your front shoulders. The front load works the quads and glutes and challenges your core.\"},{\"id\":\"4390\",\"n\":\"barbell front rack rear lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Rest the barbell across your front shoulders with elbows high.\",\"Stand tall with your feet hip-width apart.\",\"Step one leg back and lower until both knees are around 90 degrees.\",\"Push through the front foot to return to standing.\",\"Alternate legs and keep your torso upright.\"],\"img\":\"4390.webp\",\"gif\":\"4390.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge with the barbell in a front rack. Stepping back keeps the load on the glutes and quads with less knee stress.\"},{\"id\":\"4397\",\"n\":\"barbell front rack split squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Rest the barbell on your front shoulders with elbows high.\",\"Take a split stance with one foot well in front of the other.\",\"Lower your back knee toward the floor while keeping your torso upright.\",\"Press through the front foot to rise.\",\"Finish your reps, then switch legs.\"],\"img\":\"4397.webp\",\"gif\":\"4397.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with the bar in a front rack position, building leg strength and core control.\",\"fv\":\"6556\"},{\"id\":\"4409\",\"n\":\"barbell front rack walking lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Rest the barbell across your front shoulders with elbows high.\",\"Step forward into a long stride.\",\"Lower until both knees reach about 90 degrees.\",\"Push through the front foot and bring the back leg through into the next step.\",\"Keep walking, alternating legs, with an upright torso.\"],\"img\":\"4409.webp\",\"gif\":\"4409.mp4\",\"cat\":\"strength\",\"desc\":\"A walking lunge with the barbell in a front rack, challenging the legs, balance and core.\"},{\"id\":\"3311\",\"n\":\"barbell front squat (from blocks)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\",\"hamstrings\"],\"st\":[\"Set the bar on the blocks or rack at front shoulder height.\",\"Step in, rest the bar on your front shoulders with elbows high.\",\"Lift it off and stand tall with feet shoulder width apart.\",\"Squat down with a tall chest until your thighs pass parallel.\",\"Stand back up by driving through your feet, then re-rack the bar.\"],\"img\":\"3311.webp\",\"gif\":\"3311.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat started from a rack or blocks height, so you begin the rep with the bar already set. It builds quad and trunk strength.\"},{\"id\":\"3728\",\"n\":\"barbell front step up\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Rack a barbell across your front shoulders and stand facing a box.\",\"Place one foot fully on the box.\",\"Drive through that heel to step up and stand tall.\",\"Lower back down slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"3728.webp\",\"gif\":\"3728.mp4\",\"cat\":\"strength\",\"desc\":\"A step up with a barbell racked on your front shoulders, which keeps your torso upright and works the quads.\"},{\"id\":\"5287\",\"n\":\"barbell full clean\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\",\"shoulders\",\"forearms\"],\"st\":[\"Stand with the bar over mid-foot and grip it just outside your knees.\",\"Pull the bar explosively with a flat back.\",\"Drop under the bar and catch it on your shoulders in a front squat.\",\"Stand up fully.\",\"Lower the bar with control to the floor.\"],\"img\":\"5287.webp\",\"gif\":\"5287.mp4\",\"cat\":\"olympic\",\"desc\":\"The full clean lifts the barbell from the floor to the shoulders while dropping into a front squat. It builds explosive power.\"},{\"id\":\"0878\",\"n\":\"barbell full squat (with rack)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"lower back\"],\"st\":[\"Set the bar at upper chest height in a rack and step under it, resting it on your upper back.\",\"Unrack and step back with your feet shoulder width apart.\",\"Bend your hips and knees and squat down as deep as you comfortably can.\",\"Keep your chest up and knees tracking over your toes.\",\"Drive through your whole foot to stand back up.\",\"Set the safety pins just below your lowest depth.\"],\"img\":\"0878.webp\",\"gif\":\"0878.mp4\",\"cat\":\"strength\",\"desc\":\"A deep back squat performed in a power rack for safety. It builds strength across the legs and hips.\"},{\"id\":\"2964\",\"n\":\"barbell glute bridge (hands on bar)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Sit on the floor with a barbell over your hips, padded if needed.\",\"Roll back, set your feet, and hold the bar with both hands.\",\"Drive through your heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2964.webp\",\"gif\":\"2964.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with the barbell resting on your hips and your hands on the bar. It builds the glutes and hamstrings with load.\",\"fv\":\"2965\"},{\"id\":\"9694\",\"n\":\"barbell half kneeling shoulders press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel on one knee with the other foot forward and a barbell at your shoulder.\",\"Squeeze your glutes and brace your core.\",\"Press the bar overhead until your arms are straight.\",\"Lower under control to your shoulder.\",\"Finish your reps, then switch legs.\"],\"img\":\"9694.webp\",\"gif\":\"9694.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press from a half-kneeling stance, which demands core and hip stability.\"},{\"id\":\"10195\",\"n\":\"barbell half kneeling thor lift\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Kneel on one knee holding one end of a barbell in a landmine setup near your hip.\",\"Brace your core and stay tall.\",\"Lift the bar diagonally across your body and up toward the opposite shoulder.\",\"Return the bar slowly to the start.\",\"Keep your hips square. Finish the reps, then switch sides.\"],\"img\":\"10195.webp\",\"gif\":\"10195.mp4\",\"cat\":\"strength\",\"desc\":\"A half kneeling barbell lift that sweeps the bar diagonally up, training the core to control rotation.\"},{\"id\":\"1520\",\"n\":\"barbell hang clean\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Stand holding the bar at mid-thigh with a grip just outside your legs and a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull yourself under the bar and catch it on your front shoulders in a squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1520.webp\",\"gif\":\"1520.mp4\",\"cat\":\"olympic\",\"desc\":\"A clean that starts from the hang at the thighs. It trains the explosive hip drive and the catch.\"},{\"id\":\"1521\",\"n\":\"barbell hang clean below the knees\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Hold the bar just below your knees with a flat back and your shoulders over the bar.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull yourself under the bar and catch it on your front shoulders in a squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1521.webp\",\"gif\":\"1521.mp4\",\"cat\":\"olympic\",\"desc\":\"A hang clean started from below the knees. It lengthens the pull for more power.\"},{\"id\":\"3183\",\"n\":\"barbell hang clean below the knees v. 2\",\"bp\":\"full body\",\"eq\":\"olympic barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"quadriceps\",\"lats\",\"core\"],\"st\":[\"Stand with the bar hanging below your knees in an overhand grip.\",\"Hinge back with a flat back and shoulders over the bar.\",\"Drive your hips forward and jump explosively.\",\"Shrug and pull your elbows high.\",\"Drop under the bar and catch it on your shoulders.\",\"Stand tall, then lower the bar under control.\"],\"img\":\"3183.webp\",\"gif\":\"3183.mp4\",\"cat\":\"olympic\",\"desc\":\"A clean started with the bar hanging below the knees. It builds explosive hip power.\"},{\"id\":\"10107\",\"n\":\"barbell hang clean high pull\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"glutes\",\"hamstrings\",\"forearms\"],\"st\":[\"Hold a barbell just above the knees with an overhand grip.\",\"Hinge at the hips and keep your back flat.\",\"Explode up through the legs and shrug.\",\"Pull the bar to chest height with high elbows.\",\"Lower to the hang position.\",\"Reset and repeat. Keep the bar close.\"],\"img\":\"10107.webp\",\"gif\":\"10107.mp4\",\"cat\":\"olympic\",\"desc\":\"A high pull starting from the hang position above the knees, training explosive hip and shoulder power.\"},{\"id\":\"5704\",\"n\":\"barbell hang power clean\",\"bp\":\"upper legs\",\"eq\":\"olympic barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"quadriceps\",\"shoulders\",\"forearms\"],\"st\":[\"Hold the bar at mid-thigh with an overhand grip and a flat back.\",\"Hinge slightly so the bar sits just above your knees.\",\"Jump and shrug explosively, extending hips and knees.\",\"Pull yourself under the bar and catch it on your shoulders in a quarter squat.\",\"Stand tall, then lower the bar back to the hang.\"],\"img\":\"5704.webp\",\"gif\":\"5704.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive lift from the hang position that brings the bar to the shoulders. It trains power through the hips, legs and traps.\"},{\"id\":\"1522\",\"n\":\"barbell hang snatch\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Hold the bar at mid-thigh with a wide snatch grip and a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull under the bar and catch it overhead with locked arms in a squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1522.webp\",\"gif\":\"1522.mp4\",\"cat\":\"olympic\",\"desc\":\"A snatch that starts from the hang at the thighs. It trains the explosive pull and catching the bar overhead.\"},{\"id\":\"1523\",\"n\":\"barbell hang snatch below the knees\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Hold the bar just below your knees with a wide grip and a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull under the bar and catch it overhead with locked arms in a squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1523.webp\",\"gif\":\"1523.mp4\",\"cat\":\"olympic\",\"desc\":\"A hang snatch started from below the knees. It lengthens the pull for more power.\"},{\"id\":\"1524\",\"n\":\"barbell heaving snatch balance\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"glutes\",\"core\",\"upper back\"],\"st\":[\"Rest the bar on your upper back and take a wide snatch grip.\",\"Dip and drive up explosively, pushing the bar off your shoulders.\",\"Drop quickly into a squat while pressing the bar overhead.\",\"Catch it with locked arms over your mid-foot.\",\"Stand up with control and return the bar to your back.\"],\"img\":\"1524.webp\",\"gif\":\"1524.mp4\",\"cat\":\"olympic\",\"desc\":\"A snatch drill where you dip, drive and drop under a bar on your back into an overhead squat. It builds speed and overhead stability.\"},{\"id\":\"10106\",\"n\":\"barbell high pull\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"glutes\",\"hamstrings\",\"forearms\"],\"st\":[\"Hold a barbell at mid-thigh with an overhand grip, hips hinged slightly.\",\"Drive your hips forward and shrug hard.\",\"Pull the bar up to chest height, elbows high.\",\"Let the bar settle and lower it to the thighs.\",\"Reset your stance.\",\"Keep the bar close to your body.\"],\"img\":\"10106.webp\",\"gif\":\"10106.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive pull taking the bar from the thighs to chest height. It builds power in the traps, hips and legs.\"},{\"id\":\"1060\",\"n\":\"barbell hip thrust\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit on the floor with your upper back against a bench and a padded barbell over your hips.\",\"Plant your feet hip-width apart and drive through your heels.\",\"Lift your hips until your torso is level with the floor.\",\"Squeeze your glutes at the top and keep your chin tucked.\",\"Lower your hips under control.\",\"Repeat without arching your lower back.\"],\"img\":\"1060.webp\",\"gif\":\"1060.mp4\",\"cat\":\"strength\",\"desc\":\"A bench-supported bridge with a barbell across your hips. It is a go-to move for building strong glutes.\",\"fv\":\"2216\"},{\"id\":\"3873\",\"n\":\"barbell hip thrust with resistance band\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\",\"adductors\"],\"st\":[\"Sit with your upper back against a bench and the loaded bar across your hips.\",\"Set a band over your hips or around your thighs as the setup allows.\",\"Plant your feet hip-width apart.\",\"Drive your hips up until your torso is level with the floor.\",\"Squeeze your glutes at the top.\",\"Lower with control and repeat.\"],\"img\":\"3873.webp\",\"gif\":\"3873.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell hip thrust with a band adding extra tension at the top, focused on the glutes.\"},{\"id\":\"7237\",\"n\":\"barbell hook grip deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"upper back\"],\"st\":[\"Stand with the bar over mid-foot and grip it with your thumbs under your fingers.\",\"Hinge down, brace your core and keep your back flat.\",\"Push the floor away and stand up, keeping the bar close to your legs.\",\"Lock out with hips and knees extended.\",\"Lower the bar under control by hinging at the hips first.\"],\"img\":\"7237.webp\",\"gif\":\"7237.mp4\",\"cat\":\"strength\",\"desc\":\"Deadlift using a hook grip, where the thumb is trapped under the fingers, for a secure hold on heavy pulls.\"},{\"id\":\"3722\",\"n\":\"barbell incline lying rear delt raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie chest down on an incline bench holding a barbell hanging below you.\",\"Keep your arms nearly straight.\",\"Raise the bar by lifting your elbows out and back.\",\"Squeeze your rear delts at the top.\",\"Lower the barbell slowly.\"],\"img\":\"3722.webp\",\"gif\":\"3722.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported raise with a barbell that isolates the rear shoulders.\"},{\"id\":\"5853\",\"n\":\"barbell incline rear delt row\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie face down on an incline bench holding a barbell with a wide grip.\",\"Let your arms hang straight down.\",\"Row the bar up with elbows flared out.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly.\"],\"img\":\"5853.webp\",\"gif\":\"5853.mp4\",\"cat\":\"strength\",\"desc\":\"A row lying chest-down on an incline bench with elbows flared. It targets the rear shoulders and upper back.\"},{\"id\":\"3988\",\"n\":\"barbell incline reverse grip spider curl with chest support\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"wrist extensors\"],\"st\":[\"Lie chest down on an incline bench holding a barbell overhand.\",\"Keep your upper arms vertical.\",\"Curl the bar up.\",\"Squeeze at the top.\",\"Lower fully with control.\"],\"img\":\"3988.webp\",\"gif\":\"3988.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse grip curl done chest down on an incline bench. It targets the forearms and brachialis.\"},{\"id\":\"4344\",\"n\":\"barbell incline triceps extension skull crusher\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie back on an incline bench holding a barbell above your chest, arms straight.\",\"Keep your upper arms still.\",\"Bend your elbows and lower the bar toward your forehead.\",\"Extend your arms to return to the start.\",\"Keep your elbows pointing forward.\"],\"img\":\"4344.webp\",\"gif\":\"4344.mp4\",\"cat\":\"strength\",\"desc\":\"An incline version of the skull crusher, lowering a barbell behind your head to hit the long head of the triceps.\"},{\"id\":\"1173\",\"n\":\"barbell incline wide reverse grip bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"triceps\"],\"st\":[\"Lie on an incline bench and grip the bar wide with palms facing you.\",\"Unrack and hold the bar over your upper chest.\",\"Lower it to the upper chest with elbows slightly tucked.\",\"Press back up to lockout.\",\"Use a spotter, as this grip is less stable.\"],\"img\":\"1173.webp\",\"gif\":\"1173.mp4\",\"cat\":\"strength\",\"desc\":\"An incline bench press with a wide underhand grip that emphasizes the upper chest.\"},{\"id\":\"3987\",\"n\":\"barbell incline wrist curl with chest support\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Lie chest down on an incline bench with the barbell in hands, palms up.\",\"Let your wrists extend gently.\",\"Curl your wrists upward.\",\"Squeeze at the top.\",\"Lower slowly.\"],\"img\":\"3987.webp\",\"gif\":\"3987.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl performed chest down on an incline bench. It isolates the forearm flexors.\"},{\"id\":\"10857\",\"n\":\"barbell jefferson curl\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"upper back\"],\"st\":[\"Stand holding a very light barbell in front of your thighs.\",\"Tuck your chin and roll down one segment at a time.\",\"Let the bar hang close to your legs.\",\"Go only as low as feels controlled.\",\"Roll back up slowly.\",\"Keep your knees soft.\"],\"img\":\"10857.webp\",\"gif\":\"10857.mp4\",\"cat\":\"mobility\",\"desc\":\"A slow, loaded forward bend that rolls through the spine. Keep the barbell light and the motion smooth.\"},{\"id\":\"5706\",\"n\":\"barbell jefferson deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"adductors\",\"lower back\",\"core\"],\"st\":[\"Stand straddling the bar with one foot forward and one back.\",\"Squat down and grip the bar with one hand in front and one behind.\",\"Brace your core and lift your chest.\",\"Stand up by driving through both legs.\",\"Lower the bar with control and switch your stance on the next set.\"],\"img\":\"5706.webp\",\"gif\":\"5706.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with the bar between your legs and a split stance. It loads the legs and hips and trains the back to stay braced.\"},{\"id\":\"1525\",\"n\":\"barbell jerk dip squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\",\"shoulders\"],\"st\":[\"Rack the bar on your front shoulders and stand with feet hip-width apart.\",\"Keep your torso upright and your core tight.\",\"Dip a short way by bending your knees straight down.\",\"Drive up explosively through your whole foot.\",\"Settle back to standing and reset.\"],\"img\":\"1525.webp\",\"gif\":\"1525.mp4\",\"cat\":\"olympic\",\"desc\":\"The dip and drive part of the jerk, practised with a barbell on the shoulders. It trains a vertical dip and strong leg drive.\"},{\"id\":\"5451\",\"n\":\"barbell kas glute bridge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with your knees bent and feet flat, loaded as the exercise requires.\",\"Keep your shins roughly vertical with the knees kept slightly forward of the hips.\",\"Squeeze your glutes and press your hips up until your body forms a line.\",\"Pause for a second at the top without arching your back.\",\"Lower under control and repeat.\"],\"img\":\"5451.webp\",\"gif\":\"5451.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with a barbell across your hips and a knees-forward setup. Keeps tension on the glutes through the whole rep.\"},{\"id\":\"4401\",\"n\":\"barbell knee raise step up\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Rest a barbell on your upper back and stand facing a box.\",\"Place one foot on the box and press up through that heel.\",\"Drive the other knee up toward your hip at the top.\",\"Lower the knee and step back down under control.\",\"Complete your reps, then switch legs.\"],\"img\":\"4401.webp\",\"gif\":\"4401.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up finished with a knee drive, training the glutes and legs along with balance and hip flexor control.\"},{\"id\":\"6270\",\"n\":\"barbell larsen press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench and grip the bar.\",\"Lift your feet off the floor.\",\"Unrack the bar.\",\"Lower it to your chest.\",\"Press back up.\",\"Keep your back flat.\"],\"img\":\"6270.webp\",\"gif\":\"6270.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with your feet raised off the floor. It trains the chest with less leg drive.\",\"nd\":[\"bench\"]},{\"id\":\"2811\",\"n\":\"barbell leg twist press\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Hold a barbell at your shoulders with feet shoulder width apart.\",\"Step one foot out and rotate your hips and torso with it, bending into a rotated lunge.\",\"Drive back up and press the bar overhead as you stand.\",\"Lower the bar to your shoulders.\",\"Alternate sides on each rep.\"],\"img\":\"2811.webp\",\"gif\":\"2811.mp4\",\"cat\":\"strength\",\"desc\":\"A combined move where a leg rotation pairs with an overhead press with a barbell. Trains legs, trunk and shoulders together.\"},{\"id\":\"1868\",\"n\":\"barbell low bar squat (with rack)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"lower back\"],\"st\":[\"Set the bar in the rack and place it on your rear delts, below the traps.\",\"Step back and set your feet shoulder width.\",\"Lean forward slightly and sit your hips back and down.\",\"Descend until your thighs are at least parallel.\",\"Drive through your heels to stand, keeping your chest up.\"],\"img\":\"1868.webp\",\"gif\":\"1868.mp4\",\"cat\":\"strength\",\"desc\":\"Squat with the bar low on the back, taken from a rack, that works the glutes, thighs and back.\"},{\"id\":\"6329\",\"n\":\"barbell low split squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Rest a barbell across your upper back and step into a long split stance.\",\"Brace your core and keep your torso tall.\",\"Lower your back knee toward the floor under control.\",\"Press through your front foot to stand up.\",\"Finish your reps, then switch legs.\"],\"img\":\"6329.webp\",\"gif\":\"6329.mp4\",\"cat\":\"strength\",\"desc\":\"A deep split squat with a barbell on your upper back that builds strong quads and glutes and tests your balance.\"},{\"id\":\"4424\",\"n\":\"barbell lying close grip overhand row on rack\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\",\"core\"],\"st\":[\"Set a barbell in a rack at about waist height.\",\"Lie beneath it and grip the bar overhand with hands close together.\",\"Keep your body straight from head to heels.\",\"Pull your chest to the bar and squeeze your shoulder blades.\",\"Lower with control.\"],\"img\":\"4424.webp\",\"gif\":\"4424.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row under a rack-mounted barbell with a close overhand grip, targeting the upper back and lats.\"},{\"id\":\"4423\",\"n\":\"barbell lying close grip underhand row on rack\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"core\"],\"st\":[\"Set a barbell in a rack at about waist height.\",\"Lie underneath and grab it with a close underhand grip.\",\"Keep your body straight and heels on the floor.\",\"Pull your chest to the bar.\",\"Lower yourself under control.\"],\"img\":\"4423.webp\",\"gif\":\"4423.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row hanging under a barbell set in a rack, using a close underhand grip to target the lats and biceps.\"},{\"id\":\"10588\",\"n\":\"barbell lying front raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"triceps\"],\"st\":[\"Lie on a bench holding a barbell at arm's length over your thighs.\",\"Keep your arms straight with a soft elbow.\",\"Raise the bar in an arc until it is above your chest.\",\"Lower it slowly back down.\",\"Use a light weight and keep your back flat.\"],\"img\":\"10588.webp\",\"gif\":\"10588.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench, you raise a barbell from your thighs to above your chest. It builds the front shoulder.\",\"nd\":[\"bench\"]},{\"id\":\"3654\",\"n\":\"barbell lying row on rack\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\"],\"st\":[\"Set a barbell on a rack at a height you can reach lying down.\",\"Lie under it and grip the bar overhand.\",\"Pull your chest toward the bar.\",\"Squeeze your shoulder blades.\",\"Lower slowly to full extension.\"],\"img\":\"3654.webp\",\"gif\":\"3654.mp4\",\"cat\":\"strength\",\"desc\":\"Lie under a barbell on a rack and pull your chest up to it for the back muscles.\"},{\"id\":\"8798\",\"n\":\"barbell lying seal row on rack\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Lie face down on a raised bench so the bar hangs below you.\",\"Grip the bar slightly wider than shoulders.\",\"Row the bar up toward your chest by pulling elbows back.\",\"Squeeze your shoulder blades together.\",\"Lower slowly.\"],\"img\":\"8798.webp\",\"gif\":\"8798.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported barbell row lying on a raised bench or rack, removing the lower back from the lift.\"},{\"id\":\"3186\",\"n\":\"barbell military press (with hanging band technique)\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Hang weights from each end of the bar with bands.\",\"Hold the bar at your shoulders and stand tall.\",\"Brace your core and squeeze your glutes.\",\"Press the bar straight overhead.\",\"Lower it slowly back to your shoulders.\",\"Use a lighter load and keep the bar steady.\"],\"img\":\"3186.webp\",\"gif\":\"3186.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with bands hanging weights from the bar. The unstable load trains control in the shoulders.\"},{\"id\":\"5075\",\"n\":\"barbell muscle clean\",\"bp\":\"full body\",\"eq\":\"olympic barbell\",\"tg\":\"traps\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"quadriceps\"],\"st\":[\"Set up over the bar with hands just outside your knees and your back flat.\",\"Pull the bar off the floor, extending your hips and knees.\",\"Shrug and pull the elbows high, keeping the bar close.\",\"Rotate your elbows under and catch the bar on your shoulders without dropping into a squat.\",\"Lower the bar back down under control.\"],\"img\":\"5075.webp\",\"gif\":\"5075.mp4\",\"cat\":\"olympic\",\"desc\":\"Pull a barbell from the floor to your shoulders using only arm and hip drive, with no re-bending of the knees. A good clean-technique builder.\"},{\"id\":\"1526\",\"n\":\"barbell muscle snatch\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Hold the bar at the hips with a wide grip, shoulders over the bar.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull the bar up high with your elbows, turn it over and press to locked arms overhead without squatting.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1526.webp\",\"gif\":\"1526.mp4\",\"cat\":\"olympic\",\"desc\":\"A snatch lifted overhead with straight arms and no re-bend of the knees. It trains the upper pull and arm turnover.\"},{\"id\":\"0062\",\"n\":\"barbell narrow row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\",\"lower back\"],\"st\":[\"Hold a barbell with a narrow, underhand or neutral grip, hinge at the hips and keep your back flat.\",\"Let the bar hang at arm's length below your chest.\",\"Pull the bar toward your lower ribs, keeping your elbows close to your sides.\",\"Squeeze your shoulder blades together at the top.\",\"Lower the bar under control until your arms are straight.\",\"Keep your neck neutral and avoid jerking with your lower back.\"],\"img\":\"0062.webp\",\"gif\":\"0062.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a close grip that puts extra work on the lats and the muscles between the shoulder blades.\"},{\"id\":\"5633\",\"n\":\"barbell narrow stance squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Rest a barbell on your upper back with feet close together.\",\"Brace your core.\",\"Squat down with your chest up.\",\"Stand back up through your feet.\",\"Keep your knees tracking over your toes.\"],\"img\":\"5633.webp\",\"gif\":\"5633.mp4\",\"cat\":\"strength\",\"desc\":\"Back squat with a narrow stance for more quad focus.\"},{\"id\":\"1527\",\"n\":\"barbell olympic squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Place the bar high on your upper back and set your feet about shoulder-width.\",\"Brace your core and keep your chest up.\",\"Sit straight down as deep as you can with heels flat.\",\"Keep your knees tracking over your toes.\",\"Drive up through your feet to stand tall.\"],\"img\":\"1527.webp\",\"gif\":\"1527.mp4\",\"cat\":\"strength\",\"desc\":\"A deep, upright high-bar squat in the weightlifting style. It builds leg strength and mobility.\"},{\"id\":\"1061\",\"n\":\"barbell one leg hip thrust\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Set your upper back on a bench with a padded barbell over your hips.\",\"Extend one leg or hold it bent in the air.\",\"Drive through the planted heel to lift your hips level.\",\"Squeeze your glute at the top without twisting.\",\"Lower under control.\",\"Finish the reps, then switch legs.\"],\"img\":\"1061.webp\",\"gif\":\"1061.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg version of the barbell hip thrust that demands more balance and glute strength on each side.\"},{\"id\":\"2914\",\"n\":\"barbell overhead carry\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper back\",\"trapezius\",\"glutes\"],\"st\":[\"Press the barbell overhead with a grip just outside shoulder width.\",\"Squeeze your glutes and keep your ribs down.\",\"Walk with small, steady steps, keeping the bar over your mid-foot.\",\"Cover the set distance without arching your back.\",\"Lower the bar to your shoulders and set it down safely.\"],\"img\":\"2914.webp\",\"gif\":\"2914.mp4\",\"cat\":\"strength\",\"desc\":\"Walking while holding a barbell locked out overhead. It trains shoulder stability and whole-body bracing.\"},{\"id\":\"3725\",\"n\":\"barbell overhead lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\"],\"st\":[\"Press a barbell overhead and hold it with straight arms.\",\"Step forward into a lunge.\",\"Lower until both knees are around 90 degrees.\",\"Push off your front foot back to standing.\",\"Alternate legs and keep the bar steady.\"],\"img\":\"3725.webp\",\"gif\":\"3725.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge performed with a barbell held locked out overhead. It builds leg strength and demands shoulder and core stability.\"},{\"id\":\"2928\",\"n\":\"barbell overhead shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"trapezius\",\"forearms\",\"core\"],\"st\":[\"Hold a barbell locked out overhead with a wide grip.\",\"Keep your arms straight and your ribs down.\",\"Shrug your shoulders up toward your ears.\",\"Pause briefly at the top.\",\"Lower slowly without bending your elbows.\"],\"img\":\"2928.webp\",\"gif\":\"2928.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug done with the barbell locked out overhead. It targets the traps and helps with overhead stability.\"},{\"id\":\"5013\",\"n\":\"barbell pause bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a flat bench with your eyes under the bar and feet planted.\",\"Lower the bar to your mid chest with control.\",\"Pause for a second with the bar resting lightly.\",\"Press up explosively until your arms lock.\",\"Keep your shoulder blades pinched throughout.\"],\"img\":\"5013.webp\",\"gif\":\"5013.mp4\",\"cat\":\"strength\",\"desc\":\"Bench press with a stop on your chest. The pause makes you drive the bar without bounce.\"},{\"id\":\"5014\",\"n\":\"barbell pause deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"grip muscles\",\"trapezius\"],\"st\":[\"Stand with the bar over midfoot and grip just outside your legs.\",\"Brace your core and flatten your back.\",\"Lift the bar a few inches and hold the pause for a second.\",\"Keep your back flat, then drive through your legs to stand tall.\",\"Lower the bar under control.\"],\"img\":\"5014.webp\",\"gif\":\"5014.mp4\",\"cat\":\"strength\",\"desc\":\"Deadlift with a pause just off the floor. It strengthens the start of the pull and teaches strong positions.\"},{\"id\":\"5010\",\"n\":\"barbell pause decline bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a decline bench and grip the bar slightly wider than shoulders.\",\"Unrack the bar and lower it to your lower chest.\",\"Hold the bar still on your chest for a full second.\",\"Press the bar up powerfully until your arms are straight.\",\"Keep your feet secured and shoulder blades tight.\"],\"img\":\"5010.webp\",\"gif\":\"5010.mp4\",\"cat\":\"strength\",\"desc\":\"Decline bench press with a stop on your chest. The pause removes bounce and builds strength out of the bottom.\"},{\"id\":\"5011\",\"n\":\"barbell pause incline bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on an incline bench and grip the bar slightly wider than shoulders.\",\"Unrack the bar and lower it to your upper chest.\",\"Hold the bar still on your chest for a full second.\",\"Press up until your arms are straight.\",\"Keep your shoulder blades pulled back.\"],\"img\":\"5011.webp\",\"gif\":\"5011.mp4\",\"cat\":\"strength\",\"desc\":\"Incline bench press with a stop on your chest. It builds upper chest strength without any bounce.\"},{\"id\":\"5577\",\"n\":\"barbell paused sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with a wide stance, toes out, and grip the bar inside your knees.\",\"Brace and pull the slack out of the bar.\",\"Lift the bar a few centimetres and pause for 1-2 seconds.\",\"Drive your hips forward and stand tall.\",\"Lower the bar under control.\"],\"img\":\"5577.webp\",\"gif\":\"5577.mp4\",\"cat\":\"strength\",\"desc\":\"Sumo deadlift with a pause just off the floor to build strength out of the bottom.\"},{\"id\":\"7621\",\"n\":\"barbell pin bench press conventional grip\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Set the pins at a height just above your chest and lie on the bench.\",\"Grab the bar at about shoulder-width plus a little.\",\"Pause the bar on the pins to remove momentum.\",\"Press the bar straight up until your arms lock out.\",\"Lower back to the pins with control and reset for each rep.\"],\"img\":\"7621.webp\",\"gif\":\"7621.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press started from a dead stop on safety pins, using a standard grip. It builds strength off the chest without any bounce.\"},{\"id\":\"5660\",\"n\":\"barbell pin chest press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Set the pins just above your chest.\",\"Lie under the bar with a firm grip.\",\"Press the bar up.\",\"Lower to the pins and pause.\",\"Repeat.\"],\"img\":\"5660.webp\",\"gif\":\"5660.mp4\",\"cat\":\"strength\",\"desc\":\"Bench press from pins in the rack, starting from a dead stop at the chest.\"},{\"id\":\"4856\",\"n\":\"barbell pin close grip bench press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Set the bar on pins at chest height.\",\"Lie on the bench and grip the bar shoulder-width.\",\"Press the bar up.\",\"Lock out your elbows.\",\"Lower back to the pins.\"],\"img\":\"4856.webp\",\"gif\":\"4856.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip bench press from pins. It builds triceps strength off the dead stop.\"},{\"id\":\"4848\",\"n\":\"barbell pin front squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"adductors\",\"lower back\"],\"st\":[\"Set pins at the bottom depth and place the bar on them.\",\"Get under the bar in a front rack position.\",\"Brace and drive up to stand.\",\"Lower back to the pins under control.\",\"Pause and reset between reps.\"],\"img\":\"4848.webp\",\"gif\":\"4848.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat starting from pins in a rack, removing the stretch reflex. It builds strength out of the bottom.\"},{\"id\":\"4851\",\"n\":\"barbell pin good morning\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Set the pins to a hip-hinge height and set the bar on them.\",\"Get under the bar, brace and unrack.\",\"Hinge forward with a flat back.\",\"Return the bar to the pins.\",\"Stand tall and repeat.\"],\"img\":\"4851.webp\",\"gif\":\"4851.mp4\",\"cat\":\"strength\",\"desc\":\"A good morning starting from pins in a rack. It builds hamstring and lower back strength.\"},{\"id\":\"5701\",\"n\":\"barbell pin squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Set the safety pins at the depth you want and place the bar on them.\",\"Duck under the bar and lift it onto your upper back.\",\"Squat down until the bar rests on the pins.\",\"Pause briefly while staying tight.\",\"Drive up through your whole foot to stand.\"],\"img\":\"5701.webp\",\"gif\":\"5701.mp4\",\"cat\":\"strength\",\"desc\":\"A squat that starts each rep from a dead stop on safety pins. It removes the bounce and builds strength out of the bottom.\"},{\"id\":\"1528\",\"n\":\"barbell power clean from blocks\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Set the bar on blocks and grip it just outside your knees with a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull and catch the bar on your front shoulders in a quarter squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1528.webp\",\"gif\":\"1528.mp4\",\"cat\":\"olympic\",\"desc\":\"A clean caught above parallel, started from blocks. It builds explosive power.\"},{\"id\":\"1529\",\"n\":\"barbell power jerk\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"quadriceps\",\"glutes\",\"core\",\"calves\"],\"st\":[\"Rack the bar on your front shoulders with elbows slightly forward.\",\"Dip a short way with your torso upright.\",\"Drive up explosively and punch the bar overhead.\",\"Dip under slightly and catch it with locked arms.\",\"Stand tall, then lower the bar to your shoulders with control.\"],\"img\":\"1529.webp\",\"gif\":\"1529.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive overhead lift where you dip, drive and catch the bar with locked arms in a quarter squat.\",\"fv\":\"2547\"},{\"id\":\"5662\",\"n\":\"barbell power shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"forearms\",\"grip muscles\"],\"st\":[\"Hold a barbell at mid-thigh.\",\"Dip your knees slightly.\",\"Extend your hips and shrug explosively.\",\"Lower the bar under control.\",\"Keep your arms straight.\"],\"img\":\"5662.webp\",\"gif\":\"5662.mp4\",\"cat\":\"olympic\",\"desc\":\"Explosive shrug with a barbell, using a hip drive to build the traps.\"},{\"id\":\"1530\",\"n\":\"barbell power snatch\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Hold the bar at your shins with a wide grip, flat back and chest up.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull under and catch the bar overhead with locked arms in a quarter squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1530.webp\",\"gif\":\"1530.mp4\",\"cat\":\"olympic\",\"desc\":\"A snatch caught overhead above parallel. It builds explosive power and speed.\",\"fv\":\"10984\"},{\"id\":\"1531\",\"n\":\"barbell power snatch from blocks\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Set the bar on blocks and take a wide grip with a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull under and catch the bar overhead with locked arms in a quarter squat.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1531.webp\",\"gif\":\"1531.mp4\",\"cat\":\"olympic\",\"desc\":\"A power snatch started from blocks. It trains the explosive pull and the overhead catch.\"},{\"id\":\"1448\",\"n\":\"barbell pullover hold\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on a bench holding a light barbell above your chest with arms nearly straight.\",\"Lower the bar back over your head until you feel a deep stretch in your lats.\",\"Brace your core and keep your ribs down and your elbows softly bent.\",\"Hold the position for 15-30 seconds without letting the bar drift.\",\"Return the bar over your chest with control and set it down safely.\"],\"img\":\"1448.webp\",\"gif\":\"1448.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a barbell overhead behind you while lying on a bench. It builds lat and chest control in the stretched position.\",\"hd\":1,\"nd\":[\"bench\"]},{\"id\":\"4339\",\"n\":\"barbell pullover v. 2\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on a bench holding a barbell over your chest with a close grip.\",\"Keep a slight bend in your elbows.\",\"Lower the bar in an arc behind your head until you feel a deep stretch.\",\"Pull it back over your chest using your lats.\",\"Keep your core braced and your ribs down.\"],\"img\":\"4339.webp\",\"gif\":\"4339.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover with a barbell lying on a bench. It stretches and strengthens the lats and chest.\",\"nd\":[\"bench\"]},{\"id\":\"1514\",\"n\":\"barbell quarter squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"lower back\"],\"st\":[\"Rest the bar on your upper back and stand with feet shoulder-width apart.\",\"Brace your core and keep your chest up.\",\"Bend your knees and hips a short way, about a quarter of the full depth.\",\"Keep your knees tracking over your toes.\",\"Drive up through your feet to stand tall.\"],\"img\":\"1514.webp\",\"gif\":\"1514.mp4\",\"cat\":\"strength\",\"desc\":\"A short-range squat that goes only a quarter of the way down. It lets you handle heavier loads and builds leg strength.\"},{\"id\":\"4116\",\"n\":\"barbell reeves deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"adductors\",\"lower back\"],\"st\":[\"Stand with a wide stance and hold the bar with a wide grip.\",\"Set a flat back and chest up.\",\"Drive through your feet to lift.\",\"Lock out your hips at the top.\",\"Lower the bar with control.\"],\"img\":\"4116.webp\",\"gif\":\"4116.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance deadlift variation using a very wide grip, training hips and back.\"},{\"id\":\"4448\",\"n\":\"barbell resistance band hip thrust\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"core\",\"quadriceps\"],\"st\":[\"Sit with your upper back against a bench, a padded barbell over your hips and a band above your knees.\",\"Plant your feet hip width apart and push your knees out against the band.\",\"Drive through your heels and lift your hips until your torso is level.\",\"Keep your chin tucked and ribs down.\",\"Squeeze your glutes hard at the top.\",\"Lower with control and repeat.\"],\"img\":\"4448.webp\",\"gif\":\"4448.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell hip thrust with a band around the knees to add outward tension. Strongly works the glutes and hip stabilisers.\"},{\"id\":\"1497\",\"n\":\"barbell reverse band bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Set up on a bench with bands anchored to the rack and attached to the bar.\",\"Lie back with your eyes under the bar and your shoulder blades pinched.\",\"Lower the bar to your mid chest with control.\",\"Press the bar back up to straight arms, feeling the band resistance change.\",\"Keep your feet planted and your wrists stacked over your elbows.\"],\"img\":\"1497.webp\",\"gif\":\"1497.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with bands that lighten the load at the bottom and add heavier tension near the top. It builds pressing strength.\"},{\"id\":\"5091\",\"n\":\"barbell reverse grip bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Lie on a bench and grip the bar with palms facing you, about shoulder-width.\",\"Unrack the bar over your chest.\",\"Lower it to your lower chest with elbows tucked.\",\"Press it back up until your arms are straight.\",\"Keep your feet down and shoulder blades pinched.\"],\"img\":\"5091.webp\",\"gif\":\"5091.mp4\",\"cat\":\"strength\",\"desc\":\"Bench press with an underhand grip. It shifts more load to the upper chest and also works the triceps.\"},{\"id\":\"3917\",\"n\":\"barbell reverse grip floor press\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper chest\",\"shoulders\",\"forearms\"],\"st\":[\"Lie on the floor with a barbell above your chest, hands in an underhand grip.\",\"Plant your feet and brace your core.\",\"Lower the bar until your upper arms touch the floor.\",\"Pause briefly.\",\"Press the bar back up.\",\"Keep your wrists straight.\"],\"img\":\"3917.webp\",\"gif\":\"3917.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press with a reverse grip, which shifts more work to the triceps and upper chest.\"},{\"id\":\"2509\",\"n\":\"barbell reverse grip incline row\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Lie chest down on an incline bench holding a barbell with an underhand grip.\",\"Let your arms hang straight.\",\"Row the bar toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower slowly until your arms are straight.\",\"Keep your chest on the pad.\"],\"img\":\"2509.webp\",\"gif\":\"2509.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row with an underhand grip that works the lats and upper back.\"},{\"id\":\"2683\",\"n\":\"barbell reverse wrist curl v. 2\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit and rest your forearms on your thighs or a bench, palms down, holding a barbell.\",\"Let your wrists drop so the bar hangs down.\",\"Extend your wrists to raise the bar as high as you can.\",\"Pause briefly at the top.\",\"Lower slowly and keep your forearms still.\"],\"img\":\"2683.webp\",\"gif\":\"2683.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with an overhand grip that builds the muscles on top of the forearm.\"},{\"id\":\"1532\",\"n\":\"barbell romanian deadlift from deficit\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\",\"upper back\"],\"st\":[\"Stand on a low platform holding the bar at your thighs.\",\"Keep your knees soft and your back flat.\",\"Push your hips back and slide the bar down your legs.\",\"Lower as far as you can with a flat back.\",\"Drive your hips forward to stand tall.\"],\"img\":\"1532.webp\",\"gif\":\"1532.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift standing on a small platform for extra range. It builds the hamstrings and glutes.\"},{\"id\":\"3726\",\"n\":\"barbell seated front raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\"],\"st\":[\"Sit on a bench holding a barbell with an overhand grip, resting on your thighs.\",\"Raise the bar straight in front of you to shoulder height.\",\"Pause at the top.\",\"Lower it slowly to your thighs.\",\"Keep your back straight and avoid swinging.\"],\"img\":\"3726.webp\",\"gif\":\"3726.mp4\",\"cat\":\"strength\",\"desc\":\"A seated front raise with a barbell that trains the front delts without using leg drive.\"},{\"id\":\"4411\",\"n\":\"barbell seated high front raise\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"triceps\"],\"st\":[\"Sit on a bench holding a barbell with an overhand grip, in front of your thighs.\",\"Keep your back straight and your core braced.\",\"Lift the bar forward and up to eye level or higher.\",\"Pause briefly.\",\"Lower slowly under control.\"],\"img\":\"4411.webp\",\"gif\":\"4411.mp4\",\"cat\":\"strength\",\"desc\":\"A seated barbell raise that lifts the bar high in front of you, working the front delts.\"},{\"id\":\"1045\",\"n\":\"barbell seated military press (inside squat cage)\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Set a bench inside the cage and the bar at shoulder height.\",\"Sit tall, grip the bar just outside shoulder width and unrack it.\",\"Press the bar straight overhead until your arms are extended.\",\"Lower it to your upper chest with control.\",\"Keep your ribs down and your back against the pad.\"],\"img\":\"1045.webp\",\"gif\":\"1045.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press performed inside a squat cage so the rack gives you safe bar positions. It builds shoulder and triceps strength.\"},{\"id\":\"4016\",\"n\":\"barbell seated shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"forearms\",\"grip muscles\"],\"st\":[\"Sit upright holding the barbell at thigh level.\",\"Keep your arms straight.\",\"Lift your shoulders to your ears.\",\"Pause.\",\"Lower slowly.\"],\"img\":\"4016.webp\",\"gif\":\"4016.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug with a barbell while seated. It builds the upper traps.\"},{\"id\":\"0093\",\"n\":\"barbell seated twist (on stability ball)\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"core\"],\"st\":[\"Sit on a stability ball with a barbell across your upper back and your feet wide.\",\"Sit tall with your core braced.\",\"Rotate your torso to one side without moving your hips.\",\"Return to the centre.\",\"Rotate to the other side.\",\"Keep the movement slow and controlled.\"],\"img\":\"0093.webp\",\"gif\":\"0093.mp4\",\"cat\":\"strength\",\"desc\":\"A seated trunk rotation with a barbell on your shoulders while balancing on a stability ball. It works the obliques and balance.\"},{\"id\":\"5632\",\"n\":\"barbell shoulder grip upright row\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\"],\"st\":[\"Stand holding a barbell at your thighs with hands shoulder width.\",\"Pull the bar up along your body.\",\"Lead with your elbows up to chest height.\",\"Lower slowly.\",\"Keep the bar close.\"],\"img\":\"5632.webp\",\"gif\":\"5632.mp4\",\"cat\":\"strength\",\"desc\":\"Upright row with a shoulder-width grip.\",\"fv\":\"2366\"},{\"id\":\"4850\",\"n\":\"barbell single leg good morning\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Rest a barbell on your upper back and stand on one leg.\",\"Keep your standing knee slightly bent.\",\"Hinge forward while your free leg extends behind you.\",\"Lower until your torso is near parallel.\",\"Return and switch legs after your reps.\"],\"img\":\"4850.webp\",\"gif\":\"4850.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg barbell hip hinge. It trains the hamstrings and balance.\"},{\"id\":\"4349\",\"n\":\"barbell single leg squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Rest a barbell on your upper back and stand on one leg, other leg lifted in front.\",\"Brace your core and keep your chest up.\",\"Sit your hips back and lower as deep as you control.\",\"Drive through your heel to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"4349.webp\",\"gif\":\"4349.mp4\",\"cat\":\"strength\",\"desc\":\"A one-legged squat with a barbell on your back. It builds leg strength and balance, so use light weight.\"},{\"id\":\"4854\",\"n\":\"barbell sitting on floor oblique twist\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Sit on the floor with legs bent and a bar across your shoulders.\",\"Lean back slightly and brace.\",\"Rotate your torso to one side.\",\"Return to center.\",\"Rotate to the other side.\"],\"img\":\"4854.webp\",\"gif\":\"4854.mp4\",\"cat\":\"strength\",\"desc\":\"A seated twist with a barbell across your shoulders. It trains the obliques and core rotation.\"},{\"id\":\"1533\",\"n\":\"barbell snatch\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Grip the bar wide, with it over your mid-foot, flat back and chest up.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull under the bar and catch it overhead in a full squat, then stand up.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1533.webp\",\"gif\":\"1533.mp4\",\"cat\":\"olympic\",\"desc\":\"The full snatch, lifting the bar from the floor to overhead in one motion and catching it in a deep squat.\"},{\"id\":\"1534\",\"n\":\"barbell snatch balance\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"glutes\",\"core\",\"upper back\"],\"st\":[\"Rest the bar on your upper back and take a wide snatch grip.\",\"Dip a short way and drive up.\",\"Drop into a squat while pressing the bar overhead.\",\"Catch it with locked arms and your chest up.\",\"Stand up with control and return the bar to your back.\"],\"img\":\"1534.webp\",\"gif\":\"1534.mp4\",\"cat\":\"olympic\",\"desc\":\"A drill where you drop under a bar on your back into an overhead squat. It builds overhead stability and speed.\"},{\"id\":\"1535\",\"n\":\"barbell snatch deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"upper back\",\"grip muscles\"],\"st\":[\"Stand with the bar over your mid-foot and take a wide snatch grip.\",\"Set your back flat and chest up.\",\"Push the floor away to lift the bar, keeping it close.\",\"Stand tall with your hips and knees extended.\",\"Lower the bar with control along the same path.\"],\"img\":\"1535.webp\",\"gif\":\"1535.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a wide snatch grip. It strengthens the pulling position used in the snatch.\"},{\"id\":\"1536\",\"n\":\"barbell snatch from blocks\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Set the bar on blocks and take a wide grip with a flat back.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Pull under the bar and catch it overhead in a full squat, then stand up.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1536.webp\",\"gif\":\"1536.mp4\",\"cat\":\"olympic\",\"desc\":\"A snatch started from blocks. It trains the pull and the deep overhead catch.\"},{\"id\":\"4338\",\"n\":\"barbell spider curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie chest-down on an incline bench with your arms hanging and a barbell in your hands.\",\"Grip the bar with palms facing up, shoulder-width.\",\"Curl the bar toward your shoulders without moving your upper arms.\",\"Squeeze at the top.\",\"Lower slowly to full extension.\"],\"img\":\"4338.webp\",\"gif\":\"4338.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell curl done chest-down on an incline bench, which removes swinging and isolates the biceps.\"},{\"id\":\"1537\",\"n\":\"barbell split clean\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Grip the bar just outside your legs with a flat back, shoulders over the bar.\",\"Brace your core and keep the bar close to your body.\",\"Extend your hips and knees powerfully and shrug your shoulders.\",\"Split your feet front and back and catch the bar on your front shoulders.\",\"Stand tall to finish, then lower the bar with control.\"],\"img\":\"1537.webp\",\"gif\":\"1537.mp4\",\"cat\":\"olympic\",\"desc\":\"A clean caught in a split stance instead of a squat. It trains the explosive pull and the catch.\"},{\"id\":\"1538\",\"n\":\"barbell split jerk\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"quadriceps\",\"glutes\",\"core\",\"calves\"],\"st\":[\"Rack the bar on your front shoulders with elbows slightly forward.\",\"Dip a short way with your torso upright.\",\"Drive up explosively and press the bar overhead.\",\"Split your feet front and back and catch with locked arms.\",\"Bring your feet back together and lower the bar with control.\"],\"img\":\"1538.webp\",\"gif\":\"1538.mp4\",\"cat\":\"olympic\",\"desc\":\"An overhead lift where you dip, drive and catch the bar with locked arms in a split stance.\"},{\"id\":\"1539\",\"n\":\"barbell split jump\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Rest a light bar on your upper back and take a split stance.\",\"Lower into a shallow lunge.\",\"Jump explosively and switch your legs in the air.\",\"Land softly in the opposite split stance.\",\"Keep your torso upright and continue alternating.\"],\"img\":\"1539.webp\",\"gif\":\"1539.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump with a barbell on the back where you switch the front and back leg in the air. It builds leg power.\"},{\"id\":\"3030\",\"n\":\"barbell split squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Rest a barbell across your upper back and step one foot forward.\",\"Stand with a long stride and your torso upright.\",\"Bend both knees and lower your back knee toward the floor.\",\"Keep your front heel down and your front knee over your foot.\",\"Press through the front foot to rise.\",\"Finish your reps, then switch legs.\"],\"img\":\"3030.webp\",\"gif\":\"3030.mp4\",\"cat\":\"strength\",\"desc\":\"A split-stance squat with a barbell on your back. It works each leg on its own and builds strength and balance.\",\"fv\":\"2370\"},{\"id\":\"2809\",\"n\":\"barbell split squat v. 3\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Rest the barbell across your upper back and step into a split stance.\",\"Keep your torso upright and core braced.\",\"Lower straight down until your back knee nearly touches the floor.\",\"Press through your front foot to rise.\",\"Finish all reps, then switch legs.\"],\"img\":\"2809.webp\",\"gif\":\"2809.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with a barbell on your back, a second variation. Builds single leg strength and balance.\",\"fv\":\"2810\"},{\"id\":\"10047\",\"n\":\"barbell split stance rdl\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\",\"core\"],\"st\":[\"Hold a barbell at your thighs and stand with one foot a step ahead of the other.\",\"Put most of your weight on the front leg.\",\"Hinge at the hips and slide the bar down your front leg.\",\"Lower until you feel a stretch in your hamstring.\",\"Drive your hips forward to stand tall.\",\"Finish your reps, then switch legs.\"],\"img\":\"10047.webp\",\"gif\":\"10047.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift in a split stance, with most of the load on the front leg. It builds hamstrings and glutes and tests balance.\"},{\"id\":\"3593\",\"n\":\"barbell squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\",\"lower back\"],\"st\":[\"Set the bar on your upper back and stand with feet shoulder-width apart.\",\"Brace your core and keep your chest up.\",\"Sit your hips back and down until your thighs are about parallel to the floor.\",\"Keep your knees tracking over your toes.\",\"Drive through your feet to stand tall.\"],\"img\":\"3593.webp\",\"gif\":\"3593.mp4\",\"cat\":\"strength\",\"desc\":\"The classic barbell squat that builds strength in the thighs and hips.\"},{\"id\":\"3184\",\"n\":\"barbell squat (with hanging band technique)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Set up the bar with bands hanging kettlebells or weights from each end.\",\"Rest the bar across your upper back and step out.\",\"Stand with your feet shoulder width apart.\",\"Squat down with a braced core.\",\"Drive up through your feet.\",\"Use a lighter load and move slowly.\"],\"img\":\"3184.webp\",\"gif\":\"3184.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat with bands hanging weights from the bar. The wobble forces you to stay stable.\"},{\"id\":\"4362\",\"n\":\"barbell squat 2 sec hold\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Set a barbell on your upper back and stand with feet shoulder-width apart.\",\"Brace your core and sit down into a deep squat.\",\"Pause for two seconds at the bottom.\",\"Drive through your heels to stand.\",\"Keep your chest up throughout.\"],\"img\":\"4362.webp\",\"gif\":\"4362.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell back squat with a two second pause at the bottom, removing bounce and building strength.\"},{\"id\":\"2361\",\"n\":\"barbell squat hips (form check)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\"],\"st\":[\"Set the bar on your upper back and squat down to depth.\",\"Compare the faulty version with the correct one: your hips and chest rise together, without the hips shooting up first.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2361.webp\",\"gif\":\"2361.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for hip position during a barbell squat, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2797\",\"n\":\"barbell squat jump step rear lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Rest the barbell across your upper back and stand with feet shoulder width apart.\",\"Squat down, then jump up lightly and land softly.\",\"Step one foot back into a rear lunge, lowering your back knee toward the floor.\",\"Push through the front foot to return to standing.\",\"Alternate legs on each rep, keeping your chest tall.\"],\"img\":\"2797.webp\",\"gif\":\"2797.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell squat, a small jump and a step back into a rear lunge. A demanding combo for leg strength and power.\",\"fv\":\"2798\"},{\"id\":\"2359\",\"n\":\"barbell squat knees end position (form check)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Set the bar on your upper back and descend into a full squat.\",\"Compare the faulty version with the correct one: your knees push out over your toes and do not cave inward.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2359.webp\",\"gif\":\"2359.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for knee position at the bottom of a barbell squat, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"1540\",\"n\":\"barbell squat to shoulder press\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"triceps\",\"core\"],\"st\":[\"Hold the barbell at your upper chest with your elbows slightly forward and feet shoulder-width apart.\",\"Squat down until your thighs are about parallel to the floor, keeping your chest up.\",\"Drive up through your heels and use that momentum to press the bar overhead.\",\"Lock out the press with the bar over your mid-foot, then lower it back to your chest.\",\"Keep your core braced the whole time and avoid arching your lower back.\"],\"img\":\"1540.webp\",\"gif\":\"1540.mp4\",\"cat\":\"strength\",\"desc\":\"A squat that flows straight into an overhead press. It trains legs and shoulders together in one fluid rep.\"},{\"id\":\"1541\",\"n\":\"barbell squat to upright row (thighs)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"trapezius\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart, holding the barbell in front of your thighs with an overhand grip.\",\"Push your hips back and squat down, letting the bar slide down to your knees.\",\"Drive up through your heels to stand tall.\",\"As you rise, pull the bar up close to your body until your elbows reach shoulder height.\",\"Lower the bar under control and go straight into the next squat.\"],\"img\":\"1541.webp\",\"gif\":\"1541.mp4\",\"cat\":\"strength\",\"desc\":\"Squat down with the bar hanging in front of you, then stand and pull it up to chest height. Works thighs, glutes and upper back in one move.\"},{\"id\":\"4064\",\"n\":\"barbell squat with chains\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Set chains on the bar and unrack it onto your upper back.\",\"Stand with feet shoulder-width apart.\",\"Squat down with your chest up until your thighs are at least parallel.\",\"Drive up through your feet.\",\"Keep your core braced throughout.\"],\"img\":\"4064.webp\",\"gif\":\"4064.mp4\",\"cat\":\"strength\",\"desc\":\"Back squat with chains hanging from the bar, so the load grows as you stand. It builds leg strength through the whole range.\"},{\"id\":\"5476\",\"n\":\"barbell staggered stance hip thrust\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"adductors\"],\"st\":[\"Sit with your upper back against a bench and a barbell over your hips.\",\"Place one foot slightly ahead of the other.\",\"Drive through your feet to lift your hips until your torso is level.\",\"Squeeze your glutes at the top, keeping your chin tucked.\",\"Lower under control, and swap the foot position on the next set.\"],\"img\":\"5476.webp\",\"gif\":\"5476.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with one foot set slightly ahead of the other. Shifts more load to one side and challenges hip stability.\"},{\"id\":\"11789\",\"n\":\"barbell staggered stance stiff legged deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Hold a barbell in front of your thighs and place one foot slightly behind the other, mostly on the ball of the back foot.\",\"Keep most of your weight on the front leg with a soft knee.\",\"Hinge at the hips, sliding the bar down your legs with a flat back.\",\"Lower until you feel a strong hamstring stretch, then drive your hips forward to stand.\",\"Finish all reps, then switch the stance.\"],\"img\":\"11789.webp\",\"gif\":\"11789.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-leg deadlift with a staggered stance that loads the hamstrings and glutes while shifting weight to the front leg.\"},{\"id\":\"9410\",\"n\":\"barbell standing bent knee calf raise from deficit\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Rest a barbell across your upper back and stand with the balls of your feet on a low platform.\",\"Soften your knees into a slight bend and keep that angle throughout.\",\"Lower your heels below the platform until you feel a stretch in your calves.\",\"Press up onto your toes as high as you can.\",\"Pause briefly at the top, then lower slowly with control.\"],\"img\":\"9410.webp\",\"gif\":\"9410.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise with a bent knee and the balls of your feet on a raised edge, which shifts work toward the soleus. The deficit gives a deeper stretch at the bottom.\"},{\"id\":\"1162\",\"n\":\"barbell standing military press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Unrack the bar at shoulder height, hands just outside your shoulders.\",\"Stand tall with feet hip-width apart and squeeze your glutes.\",\"Press the bar straight up, moving your head slightly back then through.\",\"Lock out overhead with the bar over your mid-foot.\",\"Lower the bar back to your collarbone with control.\"],\"img\":\"1162.webp\",\"gif\":\"1162.mp4\",\"cat\":\"strength\",\"desc\":\"A strict standing overhead press with a barbell. It builds shoulder and triceps strength.\"},{\"id\":\"1165\",\"n\":\"barbell standing military press (without rack)\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Lift the barbell from the floor to your collarbone using a safe clean or deadlift and curl.\",\"Set your feet hip-width apart with hands just outside your shoulders.\",\"Brace your core and glutes.\",\"Press the bar straight overhead to full lockout.\",\"Lower to your collarbone under control and repeat.\"],\"img\":\"1165.webp\",\"gif\":\"1165.mp4\",\"cat\":\"strength\",\"desc\":\"A strict overhead press where you clean or lift the bar to your shoulders without a rack.\"},{\"id\":\"5668\",\"n\":\"barbell standing shoulder pin press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Set the bar on safety pins at about shoulder height in a rack.\",\"Step under it and grip just outside shoulder width.\",\"Brace your core and squeeze your glutes.\",\"Press the bar overhead, moving your head slightly back then through.\",\"Lower the bar to rest on the pins, pause, and repeat.\"],\"img\":\"5668.webp\",\"gif\":\"5668.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press starting from a dead stop on safety pins. Without the stretch reflex, it builds pressing strength out of the bottom position.\"},{\"id\":\"5328\",\"n\":\"barbell standing shoulders press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Hold the bar at shoulder height with hands just outside shoulder-width.\",\"Stand tall with glutes and core braced.\",\"Press the bar straight overhead, moving your head back slightly.\",\"Lock out with the bar over mid-foot.\",\"Lower the bar back to your shoulders.\",\"Avoid leaning back.\"],\"img\":\"5328.webp\",\"gif\":\"5328.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press done standing. It builds shoulder strength and total-body stability.\"},{\"id\":\"4862\",\"n\":\"barbell standing snatch grip shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"grip muscles\",\"forearms\",\"rhomboids\"],\"st\":[\"Hold a barbell with a wide snatch grip at your thighs.\",\"Stand tall with your chest up.\",\"Shrug your shoulders straight up.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"4862.webp\",\"gif\":\"4862.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug with a wide snatch grip. It trains the traps and grip.\"},{\"id\":\"6262\",\"n\":\"barbell standing wrist curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand holding a barbell with an underhand grip.\",\"Let your hands hang.\",\"Curl your wrists up.\",\"Squeeze the forearms.\",\"Lower slowly.\",\"Keep your arms still.\"],\"img\":\"6262.webp\",\"gif\":\"6262.mp4\",\"cat\":\"strength\",\"desc\":\"A standing wrist curl holding a barbell behind or in front of you. It builds the forearm flexors.\"},{\"id\":\"6263\",\"n\":\"barbell standing wrist reverse curl\",\"bp\":\"lower arms\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand holding a barbell with an overhand grip.\",\"Let your hands hang.\",\"Extend your wrists up.\",\"Squeeze the forearms.\",\"Lower slowly.\",\"Keep your arms still.\"],\"img\":\"6263.webp\",\"gif\":\"6263.mp4\",\"cat\":\"strength\",\"desc\":\"A standing wrist curl with an overhand grip. It builds the forearm extensors.\"},{\"id\":\"10054\",\"n\":\"barbell static lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\",\"core\"],\"st\":[\"Place a barbell across your upper back.\",\"Step into a split stance with one foot forward.\",\"Lower straight down until your back knee nearly touches the floor.\",\"Keep your chest tall and torso upright.\",\"Press through the front heel to rise.\",\"Finish your reps, then switch legs.\"],\"img\":\"10054.webp\",\"gif\":\"10054.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge held in one place with a barbell on your back, so the feet stay put while you lower and rise.\"},{\"id\":\"1542\",\"n\":\"barbell stiff leg deadlift on bench\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand on a sturdy bench holding a barbell at thigh level, feet hip-width apart.\",\"Keep your knees almost straight and push your hips back.\",\"Lower the bar toward your toes with a flat back as far as your hamstrings allow.\",\"Pause briefly, then squeeze your glutes to stand back up.\",\"Keep the bar close to your legs and stay in control throughout.\"],\"img\":\"1542.webp\",\"gif\":\"1542.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-legged deadlift performed while standing on a bench, giving you extra range of motion. It stretches and strengthens the hamstrings and lower back.\"},{\"id\":\"1543\",\"n\":\"barbell stiff legged deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand holding a barbell in front of your thighs, feet hip-width apart.\",\"Keep a slight bend in your knees and push your hips back.\",\"Lower the bar along your legs until you feel a deep stretch in your hamstrings.\",\"Keep your back flat and your chest proud the whole way.\",\"Drive your hips forward to return to standing.\"],\"img\":\"1543.webp\",\"gif\":\"1543.mp4\",\"cat\":\"strength\",\"desc\":\"The classic stiff-legged deadlift, hinging at the hips with nearly straight knees. A great builder for hamstrings, glutes and the lower back.\"},{\"id\":\"5669\",\"n\":\"barbell strict curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand tall holding a barbell with an underhand shoulder-width grip.\",\"Keep your elbows pinned to your sides and your torso still.\",\"Curl the bar up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are fully straight.\"],\"img\":\"5669.webp\",\"gif\":\"5669.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell curl done with no body swing, so the biceps do all of the work. It is a simple way to build the front of the upper arm.\"},{\"id\":\"2918\",\"n\":\"barbell suitcase carry\",\"bp\":\"waist\",\"eq\":\"barbell\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"forearms\",\"grip muscles\",\"trapezius\"],\"st\":[\"Stand with the barbell at your side and grip it near its center of balance.\",\"Lift it while keeping your torso tall and level.\",\"Walk with steady steps and resist tilting toward the weight.\",\"Cover the set distance, then lower the bar carefully.\",\"Switch hands and repeat.\"],\"img\":\"2918.webp\",\"gif\":\"2918.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a barbell off to one side with a single-handed grip. It trains your trunk to resist leaning and builds grip.\"},{\"id\":\"4107\",\"n\":\"barbell sumo deadlift from blocks\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand with a wide stance and toes out in front of a bar on blocks.\",\"Grip the bar inside your knees and set a flat back.\",\"Push the floor apart with your feet and stand up.\",\"Lock out by squeezing your glutes.\",\"Lower the bar back to the blocks with control.\"],\"img\":\"4107.webp\",\"gif\":\"4107.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo deadlift with the bar raised on blocks, shortening the pull and loading hips, legs and back.\"},{\"id\":\"4864\",\"n\":\"barbell sumo deadlift from deficit\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand on a low platform with a wide stance and toes out.\",\"Grip the bar inside your knees.\",\"Brace and push the floor away.\",\"Lock your hips out.\",\"Lower the bar under control.\"],\"img\":\"4864.webp\",\"gif\":\"4864.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo deadlift standing on a low platform. It increases range of motion off the floor.\"},{\"id\":\"3731\",\"n\":\"barbell sumo romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Hold a barbell in front of your thighs with a wide stance and toes turned out.\",\"Push your hips back, keeping your knees slightly bent.\",\"Lower the bar along your legs until you feel a hamstring stretch.\",\"Keep your back flat.\",\"Drive your hips forward to stand tall.\"],\"img\":\"3731.webp\",\"gif\":\"3731.mp4\",\"cat\":\"strength\",\"desc\":\"A romanian deadlift in a wide stance, hitting the hamstrings, glutes and inner thighs.\",\"fv\":\"5775\"},{\"id\":\"1063\",\"n\":\"barbell sumo squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Set the bar on your upper back and stand with feet well wider than your shoulders.\",\"Turn your toes out about 30 degrees.\",\"Brace your core and sit down between your legs.\",\"Keep your knees tracking over your toes.\",\"Descend to thigh level or lower, then push through your heels to stand.\",\"Keep your chest tall.\"],\"img\":\"1063.webp\",\"gif\":\"1063.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance squat with a barbell on your back. It hits the glutes and inner thighs along with the quads.\",\"fv\":\"5722\"},{\"id\":\"2990\",\"n\":\"barbell walk calves activation\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\",\"core\"],\"st\":[\"Rest a light barbell across your upper back and hold it with both hands.\",\"Stand tall with your core braced and rise onto the balls of your feet.\",\"Walk forward in small, controlled steps without letting your heels drop.\",\"Keep your ankles steady and your hips level.\",\"Walk 10-15 metres, rest, then repeat for a few rounds.\",\"Use a light load so you can stay high on your toes.\"],\"img\":\"2990.webp\",\"gif\":\"2990.mp4\",\"cat\":\"strength\",\"desc\":\"Walking on the balls of your feet with a barbell on your back to wake up the calves before heavy lower body training.\"},{\"id\":\"5823\",\"n\":\"barbell walking lunge\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Place a barbell on your upper back and stand tall.\",\"Step forward and lower until both knees are bent about 90 degrees.\",\"Keep your torso upright.\",\"Push through your front foot and bring the back leg forward into the next step.\",\"Continue alternating legs for the set distance.\"],\"img\":\"5823.webp\",\"gif\":\"5823.mp4\",\"cat\":\"strength\",\"desc\":\"Lunge forward step by step with a barbell on your back. It builds the legs and glutes and challenges balance.\"},{\"id\":\"3310\",\"n\":\"barbell weighted bench press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on the bench with eyes under the bar and feet flat on the floor.\",\"Grip the bar slightly wider than shoulder width and unrack it over your chest.\",\"Lower the bar under control to your mid chest.\",\"Press it back up until your arms are straight.\",\"Keep your shoulder blades pinched and your feet planted throughout.\"],\"img\":\"3310.webp\",\"gif\":\"3310.mp4\",\"cat\":\"strength\",\"desc\":\"The standard flat bench press with a loaded barbell, the staple lift for chest size and pressing strength.\"},{\"id\":\"5912\",\"n\":\"barbell weighted chains sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Loop chains over the ends of a barbell and take a wide stance, toes angled out.\",\"Bend down and grip the bar with your hands inside your knees.\",\"Brace your core and keep your chest up.\",\"Push through your feet and stand, with the chains adding load as you rise.\",\"Lock out your hips, then lower the bar with control.\"],\"img\":\"5912.webp\",\"gif\":\"5912.mp4\",\"cat\":\"strength\",\"desc\":\"Sumo deadlift with chains added to the bar for extra resistance near lockout, hitting the glutes, thighs and back.\"},{\"id\":\"3308\",\"n\":\"barbell weighted deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"quadriceps\"],\"st\":[\"Stand with feet hip width apart and the bar over your mid foot.\",\"Hinge down, grip the bar just outside your legs and brace your core.\",\"Push the floor away and keep the bar close as you stand up.\",\"Lock out with hips and knees extended and shoulders back.\",\"Lower the bar along your legs with a flat back to the floor.\"],\"img\":\"3308.webp\",\"gif\":\"3308.mp4\",\"cat\":\"strength\",\"desc\":\"A classic deadlift lifting a loaded barbell from the floor to hip height. It trains the whole posterior chain and your grip.\"},{\"id\":\"3309\",\"n\":\"barbell weighted front chest squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\",\"hamstrings\"],\"st\":[\"Rest the bar on your front shoulders with elbows high and hands steadying it.\",\"Stand with feet shoulder width apart and brace your core.\",\"Sit down between your hips, keeping your chest tall.\",\"Descend until your thighs are at least parallel to the floor.\",\"Drive up through your whole foot and keep your elbows up the whole way.\"],\"img\":\"3309.webp\",\"gif\":\"3309.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with the barbell racked across the front of your shoulders. The front load keeps you upright and hits the quads hard.\"},{\"id\":\"3316\",\"n\":\"barbell weightlifting complex\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"cardiovascular system\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"upper back\",\"core\"],\"st\":[\"Load a light to moderate barbell and stand over it with feet hip width apart.\",\"Perform the first lift of your chosen sequence, such as a deadlift.\",\"Move straight into the next lift without setting the bar down.\",\"Keep each rep crisp with a braced core and a flat back.\",\"Finish all lifts for one round, then lower the bar and rest before repeating.\"],\"img\":\"3316.webp\",\"gif\":\"3316.mp4\",\"cat\":\"strength\",\"desc\":\"A flowing series of barbell lifts done back to back without putting the bar down. It works your whole body and your conditioning.\"},{\"id\":\"2413\",\"n\":\"barbell wide grip drag curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"rear deltoids\"],\"st\":[\"Stand holding a barbell with a wide underhand grip.\",\"Keep your elbows pointing back and the bar close to your body.\",\"Drag the bar up your torso by pulling your elbows behind you.\",\"Squeeze your biceps at the top.\",\"Lower slowly along the same path.\",\"Keep your torso upright.\"],\"img\":\"2413.webp\",\"gif\":\"2413.mp4\",\"cat\":\"strength\",\"desc\":\"A curl where the bar drags up your torso with a wide grip, targeting the biceps.\"},{\"id\":\"4340\",\"n\":\"barbell wide pullover\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on a bench with a barbell held wider than shoulder-width above your chest.\",\"Keep your elbows slightly bent.\",\"Lower the bar behind your head in a smooth arc.\",\"Pull the bar back over your chest.\",\"Maintain a stable core and avoid arching your back.\"],\"img\":\"4340.webp\",\"gif\":\"4340.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover using a wider grip, which spreads the load across the lats and chest.\",\"nd\":[\"bench\"]},{\"id\":\"5224\",\"n\":\"barbell wide shrug\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"grip muscles\",\"upper back\"],\"st\":[\"Stand holding a barbell in front with a wide overhand grip.\",\"Keep your arms straight and your chest up.\",\"Lift your shoulders straight toward your ears.\",\"Hold the top for a second.\",\"Lower slowly under control.\"],\"img\":\"5224.webp\",\"gif\":\"5224.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell shrug with a wide grip. It targets the upper traps.\"},{\"id\":\"1544\",\"n\":\"barbell wide stance stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Take a wide stance, toes slightly out, with the barbell held in front of your thighs.\",\"Keep your knees nearly straight and push your hips back.\",\"Lower the bar between your legs while keeping your back flat.\",\"Stop when you feel a strong stretch in the hamstrings and inner thighs.\",\"Squeeze your glutes to rise back to standing.\"],\"img\":\"1544.webp\",\"gif\":\"1544.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-legged deadlift with a wide stance that brings in the inner thighs and glutes. It also keeps the hamstrings under a deep stretch.\"},{\"id\":\"4866\",\"n\":\"barbell z press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\",\"lower back\"],\"st\":[\"Sit on the floor with legs straight and the bar at your shoulders.\",\"Brace your core.\",\"Press the bar overhead.\",\"Lock out your arms.\",\"Lower to the shoulders.\"],\"img\":\"4866.webp\",\"gif\":\"4866.mp4\",\"cat\":\"strength\",\"desc\":\"A seated floor overhead press with legs straight. It builds shoulders and core.\"},{\"id\":\"8991\",\"n\":\"barbell zercher back extension\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the barbell in the crook of your elbows against your chest.\",\"Set up on a back extension bench with your hips on the pad.\",\"Lower your torso with a flat back until you feel a hamstring stretch.\",\"Raise your torso until your body is in a straight line.\",\"Avoid hyperextending at the top.\",\"Use a light weight and control the bar.\"],\"img\":\"8991.webp\",\"gif\":\"8991.mp4\",\"cat\":\"strength\",\"desc\":\"Holding a barbell in the crook of your elbows, you hinge and extend the back. It loads the lower back, glutes and core.\"},{\"id\":\"7552\",\"n\":\"barbell zercher bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\",\"upper back\"],\"st\":[\"Rest the barbell in the crooks of your elbows.\",\"Put your rear foot on a bench.\",\"Lower your back knee toward the floor.\",\"Keep your chest up.\",\"Drive up and switch legs.\"],\"img\":\"7552.webp\",\"gif\":\"7552.mp4\",\"cat\":\"strength\",\"desc\":\"Rear-foot elevated split squat with the barbell in your elbow crooks.\"},{\"id\":\"2915\",\"n\":\"barbell zercher carry\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"biceps\",\"upper back\",\"lower back\"],\"st\":[\"Set the bar in your elbow crooks, hugging it tight to your chest.\",\"Stand tall with your chest up and your abs braced.\",\"Walk with controlled steps while keeping the bar close.\",\"Cover the set distance without rounding forward.\",\"Lower the bar to the rack or floor carefully.\"],\"img\":\"2915.webp\",\"gif\":\"2915.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a barbell in the crooks of your elbows. It loads the legs, upper back and trunk in a tough front-loaded position.\"},{\"id\":\"5670\",\"n\":\"barbell zercher deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"core\",\"forearms\"],\"st\":[\"Place the bar on a low rack or the floor and stand over it.\",\"Squat down and hook the bar in the crooks of your elbows.\",\"Lift your chest and brace your core.\",\"Stand up by driving through your legs and extending your hips.\",\"Lower the bar back down under control, keeping your back flat.\"],\"img\":\"5670.webp\",\"gif\":\"5670.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with the bar cradled in the crooks of your elbows. It loads the glutes, legs and back and trains an upright torso.\"},{\"id\":\"1446\",\"n\":\"barbell zercher squat hold\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"biceps\",\"adductors\"],\"st\":[\"Place the barbell in the crooks of your elbows.\",\"Squat down until your thighs are about parallel.\",\"Keep your chest up and your core tight.\",\"Hold the bottom position steadily.\",\"Hold for 10-20 seconds, then stand up.\"],\"img\":\"1446.webp\",\"gif\":\"1446.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding the bottom of a Zercher squat with the bar in your elbows. It challenges the legs and core.\",\"hd\":1},{\"id\":\"6316\",\"n\":\"basic to cross donkey kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Start on hands and knees.\",\"Lift one leg back with a bent knee, sole toward the ceiling.\",\"Lower it, then kick it across behind your other leg.\",\"Alternate basic and cross kicks.\",\"Keep your hips level, then switch legs.\"],\"img\":\"6316.webp\",\"gif\":\"6316.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A quadruped kick that goes up behind you, then crosses over. It hits the glutes from two angles.\"},{\"id\":\"4709\",\"n\":\"basketball shot jump\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"shoulders\",\"triceps\"],\"st\":[\"Stand in an athletic stance with hands at chest height.\",\"Dip into a quarter squat.\",\"Jump up and extend one arm like shooting a basketball.\",\"Land softly with bent knees.\",\"Reset and repeat.\"],\"img\":\"4709.webp\",\"gif\":\"4709.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump with a shooting arm motion that trains explosive legs and coordination.\"},{\"id\":\"8703\",\"n\":\"battling rope pull\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"grip muscles\",\"core\",\"glutes\"],\"st\":[\"Anchor the rope and hold the ends in a staggered stance.\",\"Lean back slightly with your core tight.\",\"Pull the rope toward you hand over hand.\",\"Keep your chest tall and drive with your legs.\",\"Return smoothly and repeat.\"],\"img\":\"8703.webp\",\"gif\":\"8703.mp4\",\"cat\":\"cardio\",\"desc\":\"A rope pull that brings the rope toward you, working the back, arms and grip with a conditioning effect.\"},{\"id\":\"3370\",\"n\":\"battling ropes alternate arms jump squat\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"shoulders\"],\"st\":[\"Hold the rope ends and stand in a squat position.\",\"Start waving the ropes with alternating arms.\",\"Jump up explosively and land softly.\",\"Go straight into the next squat.\",\"Keep going for a set time and rest when needed.\"],\"img\":\"3370.webp\",\"gif\":\"3370.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A high energy move combining a jump squat with alternating rope waves. It builds power and conditioning.\"},{\"id\":\"3372\",\"n\":\"battling ropes alternate arms side lunge\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"adductors\",\"shoulders\"],\"st\":[\"Hold the rope ends and stand with feet together.\",\"Step wide to one side and sit into a side lunge.\",\"Whip the ropes alternately with your arms.\",\"Push back to the middle.\",\"Alternate sides and keep the waves going.\"],\"img\":\"3372.webp\",\"gif\":\"3372.mp4\",\"cat\":\"cardio\",\"desc\":\"Side lunges while whipping the ropes alternately, working legs, shoulders and heart.\"},{\"id\":\"3369\",\"n\":\"battling ropes alternate arms squat\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Hold one rope end in each hand and stand with feet shoulder width apart.\",\"Sit into a squat position.\",\"Whip the ropes up and down with alternating arms.\",\"Keep your chest tall and your knees stable.\",\"Continue for a set time at a steady pace.\"],\"img\":\"3369.webp\",\"gif\":\"3369.mp4\",\"cat\":\"cardio\",\"desc\":\"Squatting while whipping the battle ropes with alternating arms. It raises your heart rate and works legs and shoulders.\"},{\"id\":\"4131\",\"n\":\"battling ropes alternating waves with kneeling get up\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"quadriceps\",\"glutes\"],\"st\":[\"Kneel holding the rope ends.\",\"Make alternating waves with your arms.\",\"Rise to a standing position while continuing.\",\"Wave for a few more seconds.\",\"Return to kneeling and repeat.\"],\"img\":\"4131.webp\",\"gif\":\"4131.mp4\",\"cat\":\"cardio\",\"desc\":\"Alternating rope waves mixed with standing up from kneeling for a full body conditioning move.\"},{\"id\":\"3375\",\"n\":\"battling ropes fly\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"core\",\"rear deltoids\"],\"st\":[\"Stand with knees bent, a rope end in each hand and arms in front.\",\"Sweep your arms out wide and slightly up.\",\"Bring them back together in front of you.\",\"Keep a steady rhythm.\",\"Continue for a set time.\"],\"img\":\"3375.webp\",\"gif\":\"3375.mp4\",\"cat\":\"cardio\",\"desc\":\"Sweeping the ropes out and in like a fly, hitting the shoulders and upper body.\"},{\"id\":\"4052\",\"n\":\"battling ropes half kneeling\",\"bp\":\"cardio\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"forearms\",\"glutes\"],\"st\":[\"Kneel on one knee with the other foot forward and hold a rope end in each hand.\",\"Brace your core and keep your chest up.\",\"Make fast alternating waves with your arms.\",\"Keep the rhythm steady for a set time.\",\"Switch the front leg for the next set.\"],\"img\":\"4052.webp\",\"gif\":\"4052.mp4\",\"cat\":\"cardio\",\"desc\":\"Rope waves from a half kneeling stance. It raises the heart rate and burns the shoulders and arms.\"},{\"id\":\"3379\",\"n\":\"battling ropes high waves\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"core\",\"forearms\"],\"st\":[\"Stand with feet shoulder width apart and a rope end in each hand.\",\"Bend your knees slightly.\",\"Raise both arms overhead and slam the ropes down.\",\"Repeat quickly to make big waves.\",\"Keep your core braced for the set time.\"],\"img\":\"3379.webp\",\"gif\":\"3379.mp4\",\"cat\":\"cardio\",\"desc\":\"Big overhead wave style rope slams that fire up the shoulders and heart.\"},{\"id\":\"3373\",\"n\":\"battling ropes inside circle\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"core\",\"forearms\"],\"st\":[\"Stand with knees bent and a rope end in each hand.\",\"Move your arms in circles that turn inward.\",\"Keep the circles even and large.\",\"Brace your core and keep your chest up.\",\"Continue for a set time then rest.\"],\"img\":\"3373.webp\",\"gif\":\"3373.mp4\",\"cat\":\"cardio\",\"desc\":\"Drawing circles with the ropes toward each other. It builds shoulder endurance.\"},{\"id\":\"3376\",\"n\":\"battling ropes jumping jack\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"calves\",\"quadriceps\",\"core\"],\"st\":[\"Hold the rope ends with feet together.\",\"Jump your feet apart while raising your arms and making waves.\",\"Jump back to the start.\",\"Keep your landings soft.\",\"Keep a steady pace for the set time.\"],\"img\":\"3376.webp\",\"gif\":\"3376.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping jack with rope waves added, so arms and legs both work hard.\"},{\"id\":\"3380\",\"n\":\"battling ropes low waves\",\"bp\":\"cardio\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"forearms\",\"glutes\"],\"st\":[\"Hold one rope end in each hand and stand in a quarter squat.\",\"Brace your core and keep your chest up.\",\"Whip the ropes down and up so waves travel low along the floor.\",\"Keep the waves even and your hips stable.\",\"Work for 20-30 seconds at a hard pace.\",\"Rest, then repeat for several rounds.\"],\"img\":\"3380.webp\",\"gif\":\"3380.mp4\",\"cat\":\"cardio\",\"desc\":\"Alternating or double low waves with heavy ropes that spike your heart rate and work the shoulders, arms and core.\"},{\"id\":\"3374\",\"n\":\"battling ropes outside circle\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"core\",\"forearms\"],\"st\":[\"Stand with knees bent and a rope end in each hand.\",\"Move your arms in circles that turn outward.\",\"Keep the movement smooth and even.\",\"Keep your core tight.\",\"Continue for a set time.\"],\"img\":\"3374.webp\",\"gif\":\"3374.mp4\",\"cat\":\"cardio\",\"desc\":\"Drawing outward circles with the ropes, training shoulders and conditioning.\"},{\"id\":\"3384\",\"n\":\"battling ropes power slam\",\"bp\":\"cardio\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"lats\",\"glutes\"],\"st\":[\"Hold a rope end in each hand and stand in an athletic stance.\",\"Raise both ropes overhead while rising onto your toes.\",\"Slam them down hard while dropping into a squat.\",\"Keep your back flat and your core braced.\",\"Reset and repeat at a steady, powerful pace.\",\"Work in bursts of 15-30 seconds.\"],\"img\":\"3384.webp\",\"gif\":\"3384.mp4\",\"cat\":\"cardio\",\"desc\":\"An explosive overhead rope slam that builds conditioning and power through the whole body.\"},{\"id\":\"3377\",\"n\":\"battling ropes russian twist\",\"bp\":\"waist\",\"eq\":\"rope\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\",\"hip flexors\"],\"st\":[\"Sit on the floor with knees bent and lean back slightly.\",\"Hold the rope ends in front of you.\",\"Twist your torso to one side and swing the ropes.\",\"Twist to the other side.\",\"Keep your chest lifted and continue for the set time.\"],\"img\":\"3377.webp\",\"gif\":\"3377.mp4\",\"cat\":\"cardio\",\"desc\":\"A seated twist where you swing the ropes side to side. It trains the obliques and conditioning.\"},{\"id\":\"4112\",\"n\":\"battling ropes seated\",\"bp\":\"cardio\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"forearms\",\"upper back\"],\"st\":[\"Sit tall on the floor or a bench holding the ends of the ropes.\",\"Brace your core.\",\"Whip the ropes up and down in alternating waves.\",\"Keep a steady fast rhythm for 20-30 seconds.\",\"Rest, then repeat.\"],\"img\":\"4112.webp\",\"gif\":\"4112.mp4\",\"cat\":\"cardio\",\"desc\":\"Seated battle rope waves that raise your heart rate while working the arms and core.\"},{\"id\":\"2828\",\"n\":\"battling ropes side raise\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"forearms\",\"core\",\"trapezius\"],\"st\":[\"Stand in a slight squat holding a rope end in each hand.\",\"Keep your core braced and elbows soft.\",\"Raise both arms out to the sides to about shoulder height in a quick, controlled motion.\",\"Lower and repeat at a steady fast pace.\",\"Work in intervals of 20-30 seconds.\"],\"img\":\"2828.webp\",\"gif\":\"2828.mp4\",\"cat\":\"cardio\",\"desc\":\"Raising battling ropes out to the side with a fast, wave-making motion. Boosts shoulder endurance and heart rate.\",\"fv\":\"2827\"},{\"id\":\"3371\",\"n\":\"battling ropes side to side arms\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"obliques\",\"upper back\"],\"st\":[\"Hold the rope ends in an athletic stance with knees bent.\",\"Swing both ropes to one side.\",\"Swing them across to the other side in a flowing motion.\",\"Rotate through your torso a little.\",\"Keep a steady rhythm for the set time.\"],\"img\":\"3371.webp\",\"gif\":\"3371.mp4\",\"cat\":\"cardio\",\"desc\":\"Swinging the ropes from side to side to condition your shoulders and trunk.\"},{\"id\":\"3378\",\"n\":\"battling ropes split jump\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"shoulders\"],\"st\":[\"Hold the rope ends and stand in a split stance.\",\"Start making waves with your arms.\",\"Jump and switch legs in mid air.\",\"Land softly in a lunge.\",\"Keep switching for the set time.\"],\"img\":\"3378.webp\",\"gif\":\"3378.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jumping lunges while waving the ropes, a demanding mix of power and cardio.\"},{\"id\":\"6599\",\"n\":\"bear crawl low hip\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"quadriceps\",\"core\"],\"st\":[\"Start on hands and feet with your knees slightly off the floor.\",\"Keep your hips low and your back flat.\",\"Crawl forward with opposite hand and foot.\",\"Stay controlled and quiet.\",\"Crawl for 20-30 seconds.\"],\"img\":\"6599.webp\",\"gif\":\"6599.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A low bear crawl with your hips kept down, which challenges your shoulders, legs and core.\"},{\"id\":\"4170\",\"n\":\"bear plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"quadriceps\"],\"st\":[\"Start on hands and knees with wrists under shoulders.\",\"Tuck your toes and lift your knees a few centimetres off the floor.\",\"Keep your back flat and hips level.\",\"Brace your abs and breathe steadily.\",\"Hold for 20-30 seconds.\",\"Lower your knees to rest.\"],\"img\":\"4170.webp\",\"gif\":\"4170.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank on hands and toes with knees hovering just off the floor. It challenges the core and shoulders.\",\"hd\":1},{\"id\":\"6442\",\"n\":\"bear plank kickback\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"shoulders\"],\"st\":[\"Start on hands and knees, then lift your knees a few centimetres off the floor.\",\"Keep your back flat and core braced.\",\"Extend one leg back and up, squeezing your glute.\",\"Bring the knee back in without touching down.\",\"Repeat, then switch legs.\"],\"img\":\"6442.webp\",\"gif\":\"6442.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a hovering bear plank position, you kick one leg back to fire up your glutes while your core stays steady.\"},{\"id\":\"2346\",\"n\":\"bench dip back arms (form check)\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the edge of a bench, grip it beside your hips and slide your butt off.\",\"Compare the faulty version with the correct one: your back stays close to the bench and your elbows point straight behind you.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2346.webp\",\"gif\":\"2346.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-by-side form check for back and arm position in bench dips, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"4352\",\"n\":\"bench dip on floor v. 2\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Sit on the floor with your back to a bench and place your hands on its edge.\",\"Lift your hips and extend your legs slightly in front.\",\"Bend your elbows and lower your body.\",\"Press back up until your arms are straight.\",\"Keep your shoulders away from your ears.\"],\"img\":\"4352.webp\",\"gif\":\"4352.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip where your hands rest on a bench behind you and your feet stay on the floor. It builds the back of the upper arms.\"},{\"id\":\"5513\",\"n\":\"bench dip on stability ball\",\"bp\":\"upper arms\",\"eq\":\"stability ball\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a bench edge with hands beside your hips and heels on a stability ball.\",\"Slide your hips off the bench with arms straight.\",\"Bend your elbows to about 90 degrees, keeping them close.\",\"Press back up until your arms are straight.\",\"Keep your shoulders down and the ball steady.\"],\"img\":\"5513.webp\",\"gif\":\"5513.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Bench dip with your feet on a stability ball for extra instability, hammering the triceps.\"},{\"id\":\"4360\",\"n\":\"bench dip with legs on bench\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Place your hands on one bench behind you and your heels on another in front.\",\"Straighten your legs and lift your hips.\",\"Bend your elbows to lower your body.\",\"Press back up.\",\"Keep your back close to the bench.\"],\"img\":\"4360.webp\",\"gif\":\"4360.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A harder bench dip with your feet on a second bench. It places greater load on the triceps.\"},{\"id\":\"2560\",\"n\":\"bench full squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand in front of a bench with your feet shoulder-width apart.\",\"Keep your chest up.\",\"Sit your hips back and lower until you touch the bench.\",\"Pause briefly without relaxing.\",\"Push through your heels to stand.\",\"Repeat for the planned reps.\"],\"img\":\"2560.webp\",\"gif\":\"2560.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep squat down to a bench that builds the legs and hips.\"},{\"id\":\"4333\",\"n\":\"bench reverse crunch circle\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on a bench and grip behind your head for support.\",\"Bring your knees up over your hips.\",\"Curl your hips up and draw a small circle with your knees.\",\"Reverse the circle on the next rep.\",\"Lower your hips slowly each time.\"],\"img\":\"4333.webp\",\"gif\":\"4333.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bench reverse crunch where your knees trace a circle. It works the lower abs and obliques.\"},{\"id\":\"1780\",\"n\":\"bent arm chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand beside a wall or doorframe and place your forearm on it with your elbow bent to 90 degrees.\",\"Step forward and turn your body away until you feel the stretch across your chest.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1780.webp\",\"gif\":\"1780.mp4\",\"cat\":\"stretching\",\"desc\":\"Pressing a bent arm against a wall or frame stretches the chest and front shoulder. Changing the arm height shifts which part you feel.\"},{\"id\":\"1981\",\"n\":\"bent arm shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"triceps\"],\"st\":[\"Stand tall and bring one arm across your chest with the elbow bent.\",\"Hold the elbow with your other hand.\",\"Gently pull the elbow toward the opposite shoulder.\",\"Keep your shoulders level and your neck relaxed.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1981.webp\",\"gif\":\"1981.mp4\",\"cat\":\"stretching\",\"desc\":\"A cross-body shoulder stretch with the elbow bent, easing the back of the shoulder.\"},{\"id\":\"5236\",\"n\":\"bent arms chin up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"rhomboids\",\"core\"],\"st\":[\"Hang from a bar with an underhand, shoulder-width grip.\",\"Pull yourself up until your chin clears the bar.\",\"Keep your elbows bent and your body still.\",\"Hold briefly at the top.\",\"Lower slowly until just short of straight arms.\"],\"img\":\"5236.webp\",\"gif\":\"5236.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up holding the arms bent at the top. It builds strength in the lats and biceps.\"},{\"id\":\"4692\",\"n\":\"bent knee back to side kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Start on all fours with a flat back.\",\"Lift one bent knee back and up.\",\"Swing the leg out to the side into a kick.\",\"Return the knee under control.\",\"Switch legs after the set.\"],\"img\":\"4692.webp\",\"gif\":\"4692.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling leg movement combining a rear lift with a side kick to work the glutes and hips.\",\"fv\":\"4668\"},{\"id\":\"11649\",\"n\":\"bent knee calves stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall with hands on it and one foot back.\",\"Bend both knees, keeping the back heel flat on the floor.\",\"Lean forward until you feel a stretch low in the back calf.\",\"Keep your hips square and chest up.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"11649.webp\",\"gif\":\"11649.mp4\",\"cat\":\"stretching\",\"desc\":\"A calf stretch with a bent back knee that targets the deeper soleus muscle near the Achilles tendon.\"},{\"id\":\"0131\",\"n\":\"bent knee lying twist (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"hip flexors\"],\"st\":[\"Lie with your upper back on a stability ball and your knees bent at 90 degrees.\",\"Extend your arms out to the sides for balance.\",\"Rotate your knees and hips slowly to one side.\",\"Pause briefly.\",\"Bring them back through the centre and rotate to the other side.\",\"Keep your shoulders square to the ceiling.\"],\"img\":\"0131.webp\",\"gif\":\"0131.mp4\",\"cat\":\"strength\",\"desc\":\"A lying twist with bent knees while your upper back is on a stability ball. It trains the obliques and trunk control.\"},{\"id\":\"0133\",\"n\":\"bent knee side plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Lie on your side with your knees bent and your elbow under your shoulder.\",\"Stack your hips and knees.\",\"Lift your hips so your body forms a straight line from knee to head.\",\"Hold for 20-30 seconds.\",\"Lower your hips with control.\",\"Repeat on the other side.\"],\"img\":\"0133.webp\",\"gif\":\"0133.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with the knees bent, a more approachable version of the full move. It strengthens the obliques and the side of the hip.\",\"hd\":1},{\"id\":\"2570\",\"n\":\"bent leg circle kick (kneeling)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"obliques\"],\"st\":[\"Start on hands and knees with your hands under your shoulders.\",\"Lift one leg out to the side with the knee bent.\",\"Draw slow circles in the air with your knee.\",\"Keep your hips level and your spine still.\",\"Switch direction, then repeat on the other leg.\"],\"img\":\"2570.webp\",\"gif\":\"2570.mp4\",\"cat\":\"pilates\",\"desc\":\"A kneeling Pilates move where one bent leg draws circles in the air. It works the glutes and hips while the core keeps you steady.\"},{\"id\":\"3034\",\"n\":\"bent leg kickback (kneeling)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Start on hands and knees with your hands under your shoulders.\",\"Brace your core and keep your back flat.\",\"Lift one leg with the knee bent at 90 degrees.\",\"Push the sole of your foot toward the ceiling and squeeze your glute.\",\"Lower slowly without arching your back.\",\"Complete your reps, then switch legs.\"],\"img\":\"3034.webp\",\"gif\":\"3034.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From all fours, you drive one bent knee up toward the ceiling. It targets the glutes without any equipment.\",\"fv\":\"1474\"},{\"id\":\"3035\",\"n\":\"bent leg side kick (kneeling)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Start on hands and knees with a flat back.\",\"Keep your knee bent at about 90 degrees.\",\"Lift the bent leg out to the side to hip height.\",\"Squeeze your outer hip at the top without rotating your torso.\",\"Lower under control.\",\"Finish your reps, then switch legs.\"],\"img\":\"3035.webp\",\"gif\":\"3035.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From all fours, you lift one bent leg out to the side. It works the outer hip and glutes.\",\"fv\":\"1475\"},{\"id\":\"8896\",\"n\":\"bent over back extension scapular adduction\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"glutes\",\"hamstrings\"],\"st\":[\"Stand and hinge forward with a flat back and your arms hanging.\",\"Keep your knees softly bent.\",\"Raise your torso toward upright.\",\"At the top, pull your shoulder blades together.\",\"Lower back to the bent over position slowly.\",\"Keep your neck in line with your spine.\"],\"img\":\"8896.webp\",\"gif\":\"8896.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a bent over position you raise your torso and squeeze the shoulder blades together. It strengthens the whole back chain.\"},{\"id\":\"11798\",\"n\":\"bent over back to side to front arms raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"core\"],\"st\":[\"Hinge forward at the hips with a flat back and let your arms hang down.\",\"Sweep both arms back behind your hips.\",\"Swing them out wide to the sides up to shoulder height.\",\"Continue the arc forward until your arms point ahead of you, then reverse the path.\",\"Keep your neck neutral and move smoothly for the planned reps.\"],\"img\":\"11798.webp\",\"gif\":\"11798.mp4\",\"cat\":\"mobility\",\"desc\":\"A flowing bent-over arm sweep from back to side to front that warms up and strengthens the rear and side shoulders.\"},{\"id\":\"2343\",\"n\":\"bent over row back (form check)\",\"bp\":\"back\",\"eq\":\"barbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"lower back\"],\"st\":[\"Hold the bar and hinge forward at the hips with soft knees.\",\"Compare the faulty version with the correct one: your spine stays long and flat, not rounded.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2343.webp\",\"gif\":\"2343.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for back position during a bent over row, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"3828\",\"n\":\"bent over row with towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rear deltoids\",\"forearms\"],\"st\":[\"Hold a towel with both hands and stretch it taut.\",\"Hinge forward at the hips with a flat back.\",\"Pull the towel toward your chest while pulling it apart.\",\"Squeeze your shoulder blades together.\",\"Return slowly.\"],\"img\":\"3828.webp\",\"gif\":\"3828.mp4\",\"cat\":\"strength\",\"desc\":\"A row using a towel for resistance. It trains your back and arms with no equipment.\"},{\"id\":\"6438\",\"n\":\"bent over shoulder pendulum\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand beside a bench and rest one hand on it, hinging forward at the hips.\",\"Let the other arm hang straight down, relaxed.\",\"Swing the arm gently forward and back in a small arc using your body's motion.\",\"Then swing it side to side and in small circles.\",\"Keep the shoulder loose and the movement easy.\",\"Do equal time on both sides.\"],\"img\":\"6438.webp\",\"gif\":\"6438.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle pendulum swing for the shoulder joint. It loosens the shoulder and warms it up without any load.\"},{\"id\":\"3391\",\"n\":\"bent over twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"hamstrings\"],\"st\":[\"Stand with feet wide and hinge forward at the hips with a flat back.\",\"Extend your arms out to the sides.\",\"Rotate your torso and reach one hand toward the opposite foot.\",\"Return through the middle and twist to the other side.\",\"Move with control and keep your hips square.\",\"Do 10-12 reps per side.\"],\"img\":\"3391.webp\",\"gif\":\"3391.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing bent-over rotation that mobilizes the spine and works the obliques.\"},{\"id\":\"0134\",\"n\":\"bent side knee push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Start in a push-up position with your knees bent and both hands under your shoulders.\",\"Rotate your knees and hips slightly to one side.\",\"Lower your chest to the floor with your elbows at about 45 degrees.\",\"Push back up to the start.\",\"Keep your core tight and your hips from sagging.\",\"Switch the side of your knees between sets.\"],\"img\":\"0134.webp\",\"gif\":\"0134.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the knees bent and turned to one side, adding a gentle twist to the trunk. It trains the chest and the obliques.\"},{\"id\":\"2352\",\"n\":\"biceps curl arms body (form check)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Stand tall holding dumbbells at your sides with palms forward.\",\"Compare the faulty version with the correct one: your elbows stay pinned at your sides and your torso does not swing.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2352.webp\",\"gif\":\"2352.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for arm and body position during a biceps curl, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"5623\",\"n\":\"biceps curl front step\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"shoulders\"],\"st\":[\"Stand tall with your elbows at your sides and palms up.\",\"Step one foot forward while curling your hands up to your shoulders.\",\"Step back as you lower your arms.\",\"Alternate legs at a brisk, steady pace.\",\"Keep your elbows pinned and your core tight.\"],\"img\":\"5623.webp\",\"gif\":\"5623.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A rhythm drill pairing an arm curl with a quick step forward. Raises the heart rate while working the arms and legs.\"},{\"id\":\"8274\",\"n\":\"biceps curl under table\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"upper back\"],\"st\":[\"Lie under a strong table and grip its edge with an underhand grip.\",\"Keep your body straight with heels on the floor.\",\"Pull your chest toward the table by bending the elbows.\",\"Squeeze your biceps.\",\"Lower slowly.\"],\"img\":\"8274.webp\",\"gif\":\"8274.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lie under a sturdy table and curl your body up by gripping the edge. A bodyweight biceps exercise.\"},{\"id\":\"3748\",\"n\":\"biceps curl with bed sheet\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Hold a bed sheet with both hands, one arm pulling down, the other curling up.\",\"Keep your elbow at your side.\",\"Curl the working hand toward your shoulder against the resistance.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"3748.webp\",\"gif\":\"3748.mp4\",\"cat\":\"strength\",\"desc\":\"A bicep curl using a bed sheet and your own opposing arm for resistance.\"},{\"id\":\"1480\",\"n\":\"biceps stretch behind the back\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"chest\",\"shoulders\"],\"st\":[\"Stand tall and reach both arms behind your back.\",\"Straighten your elbows and turn your palms down or clasp your hands.\",\"Lift your hands slightly away from your body until you feel a stretch in the biceps.\",\"Keep your chest open and your neck relaxed.\",\"Hold for 20-30 seconds, breathing steadily, then release slowly.\"],\"img\":\"1480.webp\",\"gif\":\"1480.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch that opens the front of the arm and chest by reaching the arms behind you.\"},{\"id\":\"2838\",\"n\":\"bicycle\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with your hands behind your head.\",\"Lift your legs and curl your shoulders up.\",\"Extend one leg while bringing the opposite elbow toward the other knee.\",\"Switch sides in a slow pedalling motion.\",\"Keep your lower back pressed down.\"],\"img\":\"2838.webp\",\"gif\":\"2838.mp4\",\"cat\":\"pilates\",\"desc\":\"A pedalling leg movement lying on your back that works the abs and hip flexors.\"},{\"id\":\"6211\",\"n\":\"bicycle crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your hands by your head.\",\"Lift your shoulders and bring your knees up.\",\"Twist to bring one elbow to the opposite knee.\",\"Extend the other leg.\",\"Switch sides in a pedalling motion.\",\"Keep your lower back pressed down.\"],\"img\":\"6211.webp\",\"gif\":\"6211.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pedalling crunch where you bring each elbow toward the opposite knee. It works the abs and obliques.\",\"fv\":\"6212\"},{\"id\":\"2193\",\"n\":\"bicycle recline walk\",\"bp\":\"cardio\",\"eq\":\"stationary bike\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Sit on the recumbent bike and adjust the seat so your knees stay slightly bent at full extension.\",\"Place your feet on the pedals and hold the handles.\",\"Pedal at an easy, walking-like pace.\",\"Keep your back against the backrest and breathe steadily.\",\"Continue for 15-30 minutes.\",\"Cool down by slowing the pedalling gradually.\"],\"img\":\"2193.webp\",\"gif\":\"2193.mp4\",\"cat\":\"cardio\",\"desc\":\"A relaxed walking-style pedal motion on a recumbent bike that builds leg endurance with the back well supported.\",\"fv\":\"2428\"},{\"id\":\"0147\",\"n\":\"bicycle twisting crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your hands behind your head and your legs lifted.\",\"Bring one knee toward your chest and rotate to touch the opposite elbow to it.\",\"Extend the other leg straight.\",\"Switch sides in a pedalling motion.\",\"Keep your lower back pressed to the floor.\",\"Move at a steady pace without pulling on your neck.\"],\"img\":\"0147.webp\",\"gif\":\"0147.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where the knees pedal while the elbow reaches for the opposite knee. It works the abs and the obliques.\"},{\"id\":\"6540\",\"n\":\"big turn back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Stand tall with feet hip-width apart and arms out in front.\",\"Slowly rotate your upper body to one side, leading with the arms.\",\"Keep your hips facing forward as much as you can.\",\"Turn until you feel a comfortable stretch through the back.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Return to center and repeat on the other side.\"],\"img\":\"6540.webp\",\"gif\":\"6540.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing or seated rotation that opens the back and the side of the trunk. Good for easing stiffness through the spine.\"},{\"id\":\"1241\",\"n\":\"bird dog\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Start on all fours with hands under your shoulders and knees under your hips.\",\"Extend your right arm forward and left leg back.\",\"Keep your hips level and your back flat.\",\"Hold for a moment, then return.\",\"Repeat on the other side and alternate.\"],\"img\":\"1241.webp\",\"gif\":\"1241.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From hands and knees, you extend opposite arm and leg. It builds core control and back stability.\",\"fv\":\"0135\"},{\"id\":\"9002\",\"n\":\"bird dog plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Get into a plank on your hands or forearms with your body in a line.\",\"Brace your core and squeeze your glutes.\",\"Lift one arm forward and the opposite leg back.\",\"Keep your hips level and do not twist.\",\"Hold for a few seconds.\",\"Return and switch sides.\"],\"img\":\"9002.webp\",\"gif\":\"9002.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank where you extend an opposite arm and leg to challenge balance. It builds trunk stability.\"},{\"id\":\"4060\",\"n\":\"bird dog push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"glutes\"],\"st\":[\"Start in a high plank.\",\"Lower into a push up with elbows about 45 degrees from your body.\",\"Press back up.\",\"Lift one arm and the opposite leg and hold briefly.\",\"Return and alternate sides each rep.\"],\"img\":\"4060.webp\",\"gif\":\"4060.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push up combined with extending an opposite arm and leg. It builds the chest while testing core balance.\"},{\"id\":\"3141\",\"n\":\"bird dog v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"rear deltoids\"],\"st\":[\"Start on all fours with a neutral spine.\",\"Extend one arm forward and the opposite leg back.\",\"Keep your hips level and avoid arching your back.\",\"Pause for a moment.\",\"Return and switch sides.\"],\"img\":\"3141.webp\",\"gif\":\"3141.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor stability move reaching opposite arm and leg to train the back and core.\"},{\"id\":\"6296\",\"n\":\"bird of paradise pose svarga dvijasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Stand and bind one arm behind your back around your bent knee.\",\"Grab your hand with the other arm.\",\"Step in and stand tall on the grounded leg.\",\"Slowly straighten the lifted leg.\",\"Hold for a few breaths, then switch.\"],\"img\":\"6296.webp\",\"gif\":\"6296.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing bind pose that straightens one leg upward. It demands balance and flexibility in the hamstrings.\"},{\"id\":\"4279\",\"n\":\"boat stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Lie on your stomach with your legs together.\",\"Place your hands under your shoulders.\",\"Press up, lifting your chest and straightening your arms.\",\"Keep your hips on the floor.\",\"Hold for 20-30 seconds.\",\"Lower slowly and relax.\"],\"img\":\"4279.webp\",\"gif\":\"4279.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that opens up the front of the torso and abs. It leaves your midsection feeling long and loose.\"},{\"id\":\"0136\",\"n\":\"boat yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"quadriceps\"],\"st\":[\"Sit on the floor with your knees bent and your feet flat.\",\"Lean back slightly while keeping your chest open.\",\"Lift your feet off the floor and straighten your legs if you can.\",\"Reach your arms forward alongside your knees.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Lower your feet gently to rest.\"],\"img\":\"0136.webp\",\"gif\":\"0136.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated yoga balance where you lift your legs and chest into a V shape. It builds core and hip flexor strength.\"},{\"id\":\"4560\",\"n\":\"body extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Kneel with your knees hip-width apart and your body upright.\",\"Cross your arms or put your hands on your hips.\",\"Squeeze your glutes and lean back from the knees as one straight line.\",\"Go back as far as you can control.\",\"Pull yourself back up to the start.\",\"Keep your hips forward.\"],\"img\":\"4560.webp\",\"gif\":\"4560.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling lean-back that stretches and strengthens the front of the thighs and the core.\"},{\"id\":\"4384\",\"n\":\"body saw plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"lower abs\",\"glutes\"],\"st\":[\"Get into a forearm plank with elbows under your shoulders.\",\"Squeeze your glutes and brace your abs.\",\"Shift your body forward so your shoulders move past your elbows.\",\"Rock back to the start in a slow, smooth motion.\",\"Keep your hips level and avoid sagging.\"],\"img\":\"4384.webp\",\"gif\":\"4384.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank variation where you rock your body forward and back in small motions. It heavily challenges the abs and shoulders.\"},{\"id\":\"5672\",\"n\":\"bodyweight b stance good morning\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand with one foot flat and the other slightly behind, toe resting on the floor.\",\"Place your hands behind your head.\",\"Push your hips back and hinge forward with a flat back.\",\"Go down until you feel a stretch in the hamstring of the front leg.\",\"Return to standing and switch legs after your set.\"],\"img\":\"5672.webp\",\"gif\":\"5672.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with one foot staggered slightly behind. It biases one leg to train the hamstrings and glutes and builds balance.\"},{\"id\":\"6541\",\"n\":\"bodyweight bench squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand in front of a bench with feet shoulder-width apart.\",\"Push your hips back and bend your knees to lower.\",\"Lightly touch the bench with your glutes without dropping onto it.\",\"Keep your chest up and knees tracking over your toes.\",\"Drive through your whole foot to stand back up.\",\"Squeeze your glutes at the top.\"],\"img\":\"6541.webp\",\"gif\":\"6541.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat down to a bench and back up. The bench gives you a depth target and builds leg strength with control.\"},{\"id\":\"4172\",\"n\":\"bodyweight bent over rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Hinge forward with a flat back and arms hanging down.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides to shoulder height.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\",\"Keep your neck neutral.\"],\"img\":\"4172.webp\",\"gif\":\"4172.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bent over fly using only your arms as resistance. It trains the rear shoulders and upper back.\"},{\"id\":\"10168\",\"n\":\"bodyweight box squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Place a box behind you and stand with feet a bit wider than shoulders.\",\"Push your hips back and bend your knees to lower toward the box.\",\"Lightly touch the box without dropping onto it.\",\"Drive through your heels to stand back up.\",\"Keep your chest up and knees tracking over your toes.\"],\"img\":\"10168.webp\",\"gif\":\"10168.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat that lightly touches a box behind you to teach depth, hip hinge and control.\"},{\"id\":\"9691\",\"n\":\"bodyweight elevated heel front squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\"],\"st\":[\"Place your heels on a low plate or wedge.\",\"Hold your hands in front of your chest.\",\"Sit down into a deep squat with your chest tall.\",\"Keep your knees tracking over your toes.\",\"Press up to stand and repeat.\"],\"img\":\"9691.webp\",\"gif\":\"9691.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat with your heels raised. It shifts the work to the quads and allows a deeper position.\"},{\"id\":\"4561\",\"n\":\"bodyweight elevated heel squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Place your heels on a small plate or wedge, feet shoulder-width apart.\",\"Hold your arms in front for balance.\",\"Bend your knees and sink down with your chest tall.\",\"Let your knees travel forward over your toes.\",\"Drive back up through your whole foot.\",\"Keep your core tight throughout.\"],\"img\":\"4561.webp\",\"gif\":\"4561.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat with the heels raised on a small platform, shifting more work to the quads and allowing a deeper knee bend.\"},{\"id\":\"4949\",\"n\":\"bodyweight forward lunge (hinge at hips)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall with feet hip width.\",\"Step forward into a lunge.\",\"Hinge your torso forward at the hips.\",\"Lower until both knees are bent.\",\"Push off the front foot to return.\",\"Alternate legs.\"],\"img\":\"4949.webp\",\"gif\":\"4949.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A forward lunge with a forward hinge at the hips. It shifts more work to the glutes and hamstrings.\"},{\"id\":\"4950\",\"n\":\"bodyweight forward lunge (smaller stance upright torso)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall with hands on your hips.\",\"Take a short step forward.\",\"Lower straight down, keeping your torso upright.\",\"Keep the front knee over the ankle.\",\"Push through the front foot to stand.\",\"Alternate legs.\"],\"img\":\"4950.webp\",\"gif\":\"4950.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A forward lunge with a shorter step and an upright torso. It emphasizes the quads.\"},{\"id\":\"6464\",\"n\":\"bodyweight frog hip thrust\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Lie on your back with the soles of your feet together and knees falling out.\",\"Keep your feet close to your hips.\",\"Push through your feet to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6464.webp\",\"gif\":\"6464.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge with the soles of your feet together and knees open, which shifts the focus onto your glutes.\"},{\"id\":\"3181\",\"n\":\"bodyweight frog pump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\"],\"st\":[\"Lie on your back with the soles of your feet together and knees dropped open.\",\"Bring your heels close to your hips.\",\"Drive your hips up by squeezing your glutes.\",\"Pause at the top.\",\"Lower and repeat in quick pumps.\"],\"img\":\"3181.webp\",\"gif\":\"3181.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge with the soles of your feet together, taking glute work to the next level.\"},{\"id\":\"4500\",\"n\":\"bodyweight front plank to downward dog\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Start in a straight-arm plank with hands under shoulders.\",\"Brace your core and squeeze your glutes.\",\"Push your hips up and back into an inverted V.\",\"Press your heels toward the floor and lengthen your spine.\",\"Return to plank with control.\",\"Keep moving smoothly for reps.\"],\"img\":\"4500.webp\",\"gif\":\"4500.mp4\",\"cat\":\"mobility\",\"desc\":\"Moves between a plank and downward dog. Builds core strength and opens up the hamstrings and shoulders.\"},{\"id\":\"4499\",\"n\":\"bodyweight full squat with overhead press\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Stand with feet shoulder width apart and hands at your shoulders.\",\"Squat down until your thighs pass parallel.\",\"Drive up through your heels as you stand.\",\"Press both arms overhead as you reach the top.\",\"Lower your hands back to your shoulders.\",\"Repeat in a smooth rhythm.\"],\"img\":\"4499.webp\",\"gif\":\"4499.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A deep squat followed by a press overhead. Warms up legs and shoulders together.\"},{\"id\":\"4703\",\"n\":\"bodyweight full squat with overhead press (version 2)\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and hands at your shoulders.\",\"Squat deep, keeping chest up.\",\"Drive up out of the squat.\",\"Press your arms overhead as you stand.\",\"Lower your hands and repeat.\"],\"img\":\"4703.webp\",\"gif\":\"4703.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep squat paired with an overhead reach or press, working the legs and shoulders together.\"},{\"id\":\"5277\",\"n\":\"bodyweight glute dominant step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand in front of a bench and place one foot on it.\",\"Lean your torso slightly forward.\",\"Press through your heel and step up until standing.\",\"Lower slowly back down.\",\"Finish your reps, then switch legs.\"],\"img\":\"5277.webp\",\"gif\":\"5277.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-up that emphasises the glutes by leaning slightly forward. It builds single-leg strength.\"},{\"id\":\"5555\",\"n\":\"bodyweight good morning\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Stand with feet hip width and hands behind your head.\",\"Soften your knees and push your hips back.\",\"Lower your torso with a flat back until you feel a hamstring stretch.\",\"Drive your hips forward to stand.\",\"Keep your spine neutral.\"],\"img\":\"5555.webp\",\"gif\":\"5555.mp4\",\"cat\":\"mobility\",\"desc\":\"Hip-hinge pattern with no load that warms up the hamstrings and lower back.\"},{\"id\":\"10907\",\"n\":\"bodyweight half split squat hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Kneel on one knee with the other leg extended in front, heel on the floor.\",\"Sit your hips back toward the rear heel.\",\"Keep the front leg straight and your back long.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"10907.webp\",\"gif\":\"10907.mp4\",\"cat\":\"stretching\",\"desc\":\"A half split position that stretches the back of the front leg while you sit back on the rear leg.\",\"hd\":1},{\"id\":\"7551\",\"n\":\"bodyweight heel elevated bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Place your rear foot on a bench and front heel on a small plate.\",\"Hold your hands at your chest.\",\"Lower straight down.\",\"Keep your front knee over your toes.\",\"Push up and switch legs.\"],\"img\":\"7551.webp\",\"gif\":\"7551.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Split squat with the front heel raised, loading the quads more directly.\"},{\"id\":\"7577\",\"n\":\"bodyweight heel elevated squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Stand with your heels on a small plate.\",\"Extend your arms in front.\",\"Squat deep with your chest up.\",\"Keep your knees tracking over your toes.\",\"Stand back up.\"],\"img\":\"7577.webp\",\"gif\":\"7577.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Squat with heels raised to emphasize the quads.\"},{\"id\":\"10752\",\"n\":\"bodyweight jefferson curl\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"upper back\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Tuck your chin and roll down one vertebra at a time.\",\"Let your arms hang toward the floor.\",\"Reach only as far as is comfortable.\",\"Reverse slowly to stand.\",\"Move with control and keep the load light.\"],\"img\":\"10752.webp\",\"gif\":\"10752.mp4\",\"cat\":\"mobility\",\"desc\":\"A slow forward bend that rolls through the spine one segment at a time. It builds back and hamstring mobility.\"},{\"id\":\"5152\",\"n\":\"bodyweight kneeling hold to stand\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"hamstrings\"],\"st\":[\"Kneel on one knee with the other foot flat in front.\",\"Hold your arms in front of you for balance.\",\"Drive through the front foot to stand tall.\",\"Lower back down under control.\",\"Finish your reps, then switch legs.\"],\"img\":\"5152.webp\",\"gif\":\"5152.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Rise from a half-kneeling position to standing. It is a bodyweight move for hip and leg strength and balance.\"},{\"id\":\"3906\",\"n\":\"bodyweight kneeling push up row\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a kneeling push-up position with your hands on the floor, or on light dumbbells.\",\"Lower your chest to the floor.\",\"Push back up.\",\"Pull one elbow toward your ribs.\",\"Return that hand to the floor and alternate sides.\",\"Keep your hips level.\"],\"img\":\"3906.webp\",\"gif\":\"3906.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling push-up combined with a row that works the chest and back together.\"},{\"id\":\"4722\",\"n\":\"bodyweight kneeling sissy squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Kneel with your knees hip-width apart and a support nearby.\",\"Squeeze your glutes to keep your hips forward.\",\"Lean back slowly as far as you can.\",\"Pull back up with your quads.\",\"Keep a straight line from knees to head.\"],\"img\":\"4722.webp\",\"gif\":\"4722.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling lean-back that isolates the quads with a deep stretch at the front of the thigh.\"},{\"id\":\"6327\",\"n\":\"bodyweight low split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Step one foot forward into a long split stance.\",\"Keep your torso upright and your hands on your hips.\",\"Lower your back knee toward the floor as far as you can control.\",\"Drive through your front foot to stand back up.\",\"Finish all reps, then switch legs.\"],\"img\":\"6327.webp\",\"gif\":\"6327.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A split squat with a deep, low range that challenges your front thigh and glutes while building balance and hip mobility.\"},{\"id\":\"7129\",\"n\":\"bodyweight lying alternate legs curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lie face down with your legs straight and your forehead on your hands.\",\"Bend one knee and bring the heel toward your glute.\",\"Squeeze the back of your thigh at the top.\",\"Lower the leg slowly.\",\"Repeat with the other leg.\",\"Alternate for the planned reps.\"],\"img\":\"7129.webp\",\"gif\":\"7129.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor hamstring curl using your own weight, alternating legs to keep it easy on the joints.\"},{\"id\":\"6108\",\"n\":\"bodyweight lying legs curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Lie on your front with your legs straight.\",\"Rest your forehead on your hands.\",\"Bend your knees and bring your heels toward your glutes.\",\"Squeeze the hamstrings at the top.\",\"Lower your feet slowly back to the floor.\",\"Keep your hips pressed down throughout.\"],\"img\":\"6108.webp\",\"gif\":\"6108.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor-based curl where you bend the knees against no added load. It targets the hamstrings in a simple way.\"},{\"id\":\"5800\",\"n\":\"bodyweight lying prone ys\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"lower back\",\"rhomboids\"],\"st\":[\"Lie face down with your arms extended overhead in a Y.\",\"Turn your thumbs toward the ceiling.\",\"Lift your arms off the floor, squeezing your shoulder blades.\",\"Hold briefly at the top.\",\"Lower with control and repeat.\"],\"img\":\"5800.webp\",\"gif\":\"5800.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lie face down and raise your arms into a Y shape. It strengthens the lower traps and shoulder stabilizers.\"},{\"id\":\"6754\",\"n\":\"bodyweight lying shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie on your side with your elbow bent 90 degrees and tucked at your waist.\",\"Rest your forearm across your stomach.\",\"Rotate your forearm upward, keeping the elbow in.\",\"Pause at the top.\",\"Lower slowly.\",\"Finish the reps, then switch sides.\"],\"img\":\"6754.webp\",\"gif\":\"6754.mp4\",\"cat\":\"rehab\",\"desc\":\"A side-lying rotation that turns the forearm upward. It strengthens the rotator cuff without weights.\"},{\"id\":\"5194\",\"n\":\"bodyweight muscle up v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"chest\",\"core\"],\"st\":[\"Hang from a pull-up bar with a false or standard grip.\",\"Pull explosively, bringing the bar toward your lower chest.\",\"Lean forward and rotate your wrists over the bar.\",\"Press up until your arms are fully straight.\",\"Lower yourself back down with control.\"],\"img\":\"5194.webp\",\"gif\":\"5194.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced pull-up that transitions into a dip above a bar. It builds serious pulling and pushing strength.\"},{\"id\":\"10051\",\"n\":\"bodyweight narrow squat lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand with feet close together and hands on your hips or in front of you.\",\"Step one foot back and lower into a lunge, keeping your feet in a narrow line.\",\"Drop your back knee toward the floor.\",\"Keep your front knee over your ankle and chest up.\",\"Push through the front heel to stand back up.\",\"Switch legs and repeat.\"],\"img\":\"10051.webp\",\"gif\":\"10051.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge done with a narrow stance and no weight. It targets the quads and glutes while challenging balance.\"},{\"id\":\"5630\",\"n\":\"bodyweight narrow stance squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand with feet close together.\",\"Extend your arms forward for balance.\",\"Sit down and back, keeping your heels down.\",\"Descend until your thighs are parallel.\",\"Press up to stand.\"],\"img\":\"5630.webp\",\"gif\":\"5630.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Squat with feet close together to emphasise the quads.\"},{\"id\":\"9611\",\"n\":\"bodyweight overhead forward lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Stand tall with your arms extended overhead.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor.\",\"Keep your ribs down and arms in line with your ears.\",\"Push back to the start and alternate legs.\"],\"img\":\"9611.webp\",\"gif\":\"9611.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A forward lunge with your arms stretched overhead, adding a core and shoulder challenge to the leg work.\"},{\"id\":\"4294\",\"n\":\"bodyweight overhead squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\",\"upper back\"],\"st\":[\"Stand with feet shoulder-width apart and raise both arms straight overhead.\",\"Brace your core and keep your arms in line with your ears.\",\"Sit your hips back and down into a deep squat, chest tall.\",\"Drive through your heels to stand, keeping your arms locked overhead.\"],\"img\":\"4294.webp\",\"gif\":\"4294.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep squat performed with your arms locked out overhead. It trains the legs while testing shoulder and hip mobility.\"},{\"id\":\"4667\",\"n\":\"bodyweight overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Place your hands on a bar or sturdy surface at about waist height, shoulder-width apart.\",\"Walk your feet back and lean forward in a plank.\",\"Bend your elbows and lower your head between your arms.\",\"Keep your elbows pointing forward and your body straight.\",\"Press back up by extending your arms and repeat.\"],\"img\":\"4667.webp\",\"gif\":\"4667.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A triceps extension using your own bodyweight against a stable surface. It targets the back of the arms.\"},{\"id\":\"9601\",\"n\":\"bodyweight patrick step\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on a low step on one leg.\",\"Slowly bend the knee and lower the other heel to the floor.\",\"Keep your knee tracking over your toes.\",\"Tap the floor lightly.\",\"Push through the standing leg to rise.\",\"Do your reps, then switch legs.\"],\"img\":\"9601.webp\",\"gif\":\"9601.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-down drill that builds knee and hip control. It strengthens the quads and glutes.\"},{\"id\":\"9602\",\"n\":\"bodyweight patrick step from stepbox\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on the edge of a step box on one leg.\",\"Lower the other foot toward the floor.\",\"Keep your knee in line with your toes.\",\"Touch the floor lightly.\",\"Push up through the standing leg.\",\"Do your reps, then switch legs.\"],\"img\":\"9602.webp\",\"gif\":\"9602.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-down from a box that strengthens the quads and teaches knee control.\"},{\"id\":\"9605\",\"n\":\"bodyweight peterson step from stepbox\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on a step box on one leg.\",\"Lower the other foot slowly toward the floor.\",\"Keep your knee stable and your torso tall.\",\"Touch the floor lightly.\",\"Rise back up through the working leg.\",\"Do your reps, then switch legs.\"],\"img\":\"9605.webp\",\"gif\":\"9605.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-down drill with a slow, controlled lowering. It builds quad strength and knee stability.\"},{\"id\":\"9603\",\"n\":\"bodyweight poliquin step\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with one foot on a low step.\",\"Lower the other foot toward the floor with control.\",\"Keep your knee in line with your toes.\",\"Touch the floor lightly.\",\"Drive back up through the working leg.\",\"Do your reps, then switch legs.\"],\"img\":\"9603.webp\",\"gif\":\"9603.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A controlled step-up and down drill often used for knee strength. It trains the quads and glutes.\"},{\"id\":\"9604\",\"n\":\"bodyweight poliquin step from stepbox\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on a step box on one leg.\",\"Lower the other foot toward the floor with control.\",\"Keep your torso upright.\",\"Lightly tap the floor.\",\"Press up through your working leg.\",\"Do your reps, then switch legs.\"],\"img\":\"9604.webp\",\"gif\":\"9604.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A box step-down drill that builds knee strength and control in the quads and glutes.\"},{\"id\":\"9702\",\"n\":\"bodyweight pulse goblet squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and hands clasped at your chest.\",\"Squat down to a deep position.\",\"Pulse up and down a few centimetres at the bottom.\",\"Keep your chest tall and heels down.\",\"Stand up after the planned pulses.\"],\"img\":\"9702.webp\",\"gif\":\"9702.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat held low with small pulses, with your hands clasped at your chest as if holding a weight. It builds thigh endurance.\"},{\"id\":\"3535\",\"n\":\"bodyweight pulse squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Squat down until thighs are parallel.\",\"Pulse up and down a few centimetres.\",\"Keep your chest up and knees tracking over your toes.\",\"Keep your weight on your heels.\",\"Stand up fully to finish.\"],\"img\":\"3535.webp\",\"gif\":\"3535.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat held at the bottom with small pulses. It burns the quads and glutes.\",\"fv\":\"3803\"},{\"id\":\"10914\",\"n\":\"bodyweight quarter squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Push your hips back and bend your knees a short way.\",\"Keep your chest up and heels down.\",\"Press through your feet to stand tall.\",\"Repeat at a steady pace.\"],\"img\":\"10914.webp\",\"gif\":\"10914.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A shallow squat that goes only a quarter of the way down. Good for beginners and for warm-ups.\"},{\"id\":\"1581\",\"n\":\"bodyweight rear lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Step one foot back and lower until both knees are bent at about 90 degrees.\",\"Keep your torso upright and your front heel planted.\",\"Push through your front foot to return to standing.\",\"Alternate legs or finish all reps on one side first.\"],\"img\":\"1581.webp\",\"gif\":\"1581.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge where you step back instead of forward. It is gentler on the knees and focuses on the glutes.\"},{\"id\":\"6551\",\"n\":\"bodyweight reverse lunge with overhead reach\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Step one foot back and lower into a lunge.\",\"Reach both arms overhead as you lower.\",\"Push through your front foot to stand.\",\"Alternate legs.\"],\"img\":\"6551.webp\",\"gif\":\"6551.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse lunge with an overhead reach that works your legs and stretches your torso.\"},{\"id\":\"11715\",\"n\":\"bodyweight rope inverted row\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"grip muscles\"],\"st\":[\"Set ropes at about waist height and lie under them, holding the ends.\",\"Keep your body straight from heels to head, heels on the floor.\",\"Pull your chest toward your hands, squeezing your shoulder blades.\",\"Keep your elbows close to your body.\",\"Lower slowly until your arms are straight.\"],\"img\":\"11715.webp\",\"gif\":\"11715.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A horizontal row hanging under rope handles that works the back and grip.\"},{\"id\":\"11714\",\"n\":\"bodyweight rope pull up\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"grip muscles\",\"upper back\"],\"st\":[\"Hang from two ropes with arms straight and legs together.\",\"Brace your core and pull your shoulder blades down.\",\"Pull yourself up until your hands reach chest or chin level.\",\"Keep your elbows pointing down and close.\",\"Lower under control to a full hang.\"],\"img\":\"11714.webp\",\"gif\":\"11714.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up done hanging from ropes, which adds a big grip challenge to the vertical pull.\"},{\"id\":\"3506\",\"n\":\"bodyweight row in doorway\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Stand in a doorway and grip both sides of the frame firmly.\",\"Lean back with arms straight and feet close to the frame.\",\"Keep your body in a straight line.\",\"Pull your chest toward the frame, squeezing your shoulder blades.\",\"Lower with control.\",\"Use a sturdy frame and a non-slip grip.\"],\"img\":\"3506.webp\",\"gif\":\"3506.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A row done by holding both sides of a doorframe and leaning back. It trains the back and arms.\"},{\"id\":\"4361\",\"n\":\"bodyweight shrug\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Stand tall with arms by your sides.\",\"Lift your shoulders straight up toward your ears.\",\"Hold for a second.\",\"Lower them slowly.\",\"Avoid rolling your shoulders.\"],\"img\":\"4361.webp\",\"gif\":\"4361.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A shoulder shrug without weight for warming up or light trap work.\"},{\"id\":\"10934\",\"n\":\"bodyweight side lying shoulder external rotation\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"shoulders\"],\"st\":[\"Lie on your side with a small towel under the top elbow.\",\"Bend the elbow to 90 degrees.\",\"Rotate your forearm up toward the ceiling.\",\"Pause, then lower slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"10934.webp\",\"gif\":\"10934.mp4\",\"cat\":\"rehab\",\"desc\":\"A side-lying outward shoulder rotation with no weight. It trains rotator cuff control.\"},{\"id\":\"3928\",\"n\":\"bodyweight single leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on one foot with a soft knee and your arms hanging in front.\",\"Hinge at the hips and extend the free leg straight behind you.\",\"Lower your torso until it is nearly parallel to the floor, back flat.\",\"Squeeze your glute to stand tall again.\",\"Finish your reps, then switch legs.\"],\"img\":\"3928.webp\",\"gif\":\"3928.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hinge forward on one leg while the other reaches back. It builds hamstring and glute strength and trains balance.\"},{\"id\":\"10862\",\"n\":\"bodyweight single leg deadlift against ball\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand facing a wall with a ball between your hand and the wall.\",\"Lift one foot slightly.\",\"Hinge at the hip as the free leg extends back.\",\"Keep your back flat.\",\"Return to standing.\",\"Switch legs after the set.\"],\"img\":\"10862.webp\",\"gif\":\"10862.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg hinge with a ball against the wall for balance. It trains hamstrings and balance.\"},{\"id\":\"10915\",\"n\":\"bodyweight single leg deadlift hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Hinge forward from the hips as the other leg extends behind you.\",\"Keep your back flat until your torso is nearly parallel to the floor.\",\"Hold for several seconds, hips level.\",\"Return upright and switch legs.\"],\"img\":\"10915.webp\",\"gif\":\"10915.mp4\",\"cat\":\"isometric\",\"desc\":\"A one-legged hinge held at the bottom. It builds balance and the hamstrings.\",\"hd\":1},{\"id\":\"10916\",\"n\":\"bodyweight single leg deadlift toe touch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Hinge forward as the free leg lifts behind you.\",\"Reach your hands toward the toes of the standing foot.\",\"Keep your back flat and hips square.\",\"Stand back up with control. Finish your reps and switch legs.\"],\"img\":\"10916.webp\",\"gif\":\"10916.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg hinge where you reach to touch your toes. It trains balance and the hamstrings.\"},{\"id\":\"5671\",\"n\":\"bodyweight single leg kas glute bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with one foot flat and the other leg lifted.\",\"Keep your standing shin close to vertical.\",\"Drive through your heel and lift your hips until in line with your torso.\",\"Squeeze your glute at the top without arching.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"5671.webp\",\"gif\":\"5671.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg glute bridge with the knee kept forward. Works each glute on its own and tests hip balance.\"},{\"id\":\"4971\",\"n\":\"bodyweight single leg rdl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on one leg with a slight bend in the knee.\",\"Hinge forward as the other leg lifts behind you.\",\"Keep your back flat.\",\"Lower until you feel a hamstring stretch.\",\"Squeeze your glutes to stand.\",\"Finish reps, then switch legs.\"],\"img\":\"4971.webp\",\"gif\":\"4971.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single leg Romanian deadlift without weight. It trains the hamstrings and balance.\"},{\"id\":\"7560\",\"n\":\"bodyweight single leg squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand on one leg with the other lifted in front.\",\"Extend your arms for balance.\",\"Lower down with control.\",\"Keep your knee over your toes.\",\"Push up and switch legs.\"],\"img\":\"7560.webp\",\"gif\":\"7560.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Squat on one leg, building strength and balance.\"},{\"id\":\"7561\",\"n\":\"bodyweight single leg squat with support\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a stable support with one hand.\",\"Stand on one leg with the other lifted.\",\"Lower down as far as you can with control.\",\"Use the support only as much as needed.\",\"Push up and switch legs.\"],\"img\":\"7561.webp\",\"gif\":\"7561.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Supported single leg squat that helps you progress toward the full version.\"},{\"id\":\"4072\",\"n\":\"bodyweight single leg wall squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Lean your back on a wall and lift one foot off the floor.\",\"Place your standing foot forward.\",\"Slide down into a squat as far as you can control.\",\"Press through your heel to rise.\",\"Finish the reps, then switch legs.\"],\"img\":\"4072.webp\",\"gif\":\"4072.mp4\",\"cat\":\"calisthenics\",\"desc\":\"One leg squat with your back against a wall for balance. It builds single leg strength.\"},{\"id\":\"6100\",\"n\":\"bodyweight skipping\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"hip flexors\"],\"st\":[\"Stand tall with your feet together.\",\"Step and hop on one foot while driving the opposite knee up.\",\"Swing the opposite arm forward as you hop.\",\"Switch sides in a rhythmic skip.\",\"Land softly on the balls of your feet.\",\"Keep going for 30-60 seconds.\"],\"img\":\"6100.webp\",\"gif\":\"6100.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Skipping without a rope, with light hops and big arm swings. It lifts your heart rate and warms up the legs.\",\"fv\":\"6101\"},{\"id\":\"6336\",\"n\":\"bodyweight slow to explosive squats\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Lower into a squat over about three seconds.\",\"Pause briefly at the bottom with your chest up.\",\"Explode upward into a jump.\",\"Land softly with bent knees and go straight into the next rep.\"],\"img\":\"6336.webp\",\"gif\":\"6336.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat that goes down slowly and then jumps up fast, training control, leg strength and power together.\"},{\"id\":\"10906\",\"n\":\"bodyweight split squat hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"hamstrings\"],\"st\":[\"Step one foot far forward and the other back into a split stance.\",\"Lower your hips until the front knee is bent to about 90 degrees.\",\"Keep your torso upright and your front heel down.\",\"Hold for 20-30 seconds, breathing steadily.\",\"Rise up and switch legs.\"],\"img\":\"10906.webp\",\"gif\":\"10906.mp4\",\"cat\":\"stretching\",\"desc\":\"A held split stance that opens the front of the hip and loads the front thigh.\",\"hd\":1},{\"id\":\"4612\",\"n\":\"bodyweight standing around the world (wall supported)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"chest\",\"rotator cuff\"],\"st\":[\"Stand with your back flat against a wall, feet slightly forward.\",\"Start with arms straight down at your sides, palms forward.\",\"Sweep your arms out to the sides and overhead in a wide arc, staying close to the wall.\",\"Lower them back down the same way.\",\"Keep your ribs and head against the wall.\"],\"img\":\"4612.webp\",\"gif\":\"4612.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing arm circle against a wall that mobilises the shoulders while keeping your back from compensating.\"},{\"id\":\"4875\",\"n\":\"bodyweight standing back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lats\",\"sm\":[\"lats\",\"core\"],\"st\":[\"Stand tall with feet hip width apart.\",\"Clasp your hands in front of you and press your arms forward.\",\"Round your upper back and tuck your chin slightly.\",\"Feel the stretch between your shoulder blades and along the spine.\",\"Hold for 20-30 seconds.\",\"Release slowly and stand tall.\"],\"img\":\"4875.webp\",\"gif\":\"4875.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch that opens up the back. It is a gentle way to loosen tight muscles along the spine.\"},{\"id\":\"2922\",\"n\":\"bodyweight standing biceps curl\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Place one hand under the wrist of your other hand to give resistance.\",\"Curl the working hand toward your shoulder while the other hand pushes down.\",\"Squeeze the biceps at the top.\",\"Lower slowly, finish the reps, then switch arms.\"],\"img\":\"2922.webp\",\"gif\":\"2922.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A curl done with your own body resistance, such as pushing one hand against the other. It is a simple way to train the biceps without equipment.\"},{\"id\":\"4369\",\"n\":\"bodyweight standing biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Stand tall with arms at your sides.\",\"Make fists and curl your hands to your shoulders.\",\"Tense your biceps at the top.\",\"Lower slowly.\",\"Keep your elbows pinned.\"],\"img\":\"4369.webp\",\"gif\":\"4369.mp4\",\"cat\":\"strength\",\"desc\":\"A light, no-equipment biceps curl using self-resistance, useful for warming up.\"},{\"id\":\"5173\",\"n\":\"bodyweight standing fly\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Stand with your feet hip-width apart and your arms out wide with slightly bent elbows.\",\"Brace your core and keep your chest proud.\",\"Sweep your arms together in front of your chest.\",\"Squeeze your pecs hard for a second.\",\"Open your arms back out with control.\"],\"img\":\"5173.webp\",\"gif\":\"5173.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing fly motion without weights, squeezing the arms together. It teaches chest engagement and works as a warm-up.\"},{\"id\":\"4346\",\"n\":\"bodyweight standing military press\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand tall with feet shoulder-width apart and fists at your shoulders.\",\"Brace your core and squeeze your glutes.\",\"Press your arms straight overhead.\",\"Lower back to your shoulders with control.\",\"Avoid leaning back.\"],\"img\":\"4346.webp\",\"gif\":\"4346.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing overhead press without weight, good for learning the pressing path or warming up.\"},{\"id\":\"4613\",\"n\":\"bodyweight standing military press (wall supported)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\"],\"st\":[\"Stand with your back, head and hips against a wall, hands at shoulder height with elbows bent.\",\"Brace your abs so your lower back stays on the wall.\",\"Press your hands straight overhead until your arms are locked out.\",\"Lower back to shoulder height with control.\",\"Keep your wrists stacked over your elbows.\"],\"img\":\"4613.webp\",\"gif\":\"4613.mp4\",\"cat\":\"mobility\",\"desc\":\"An unloaded overhead press against a wall to groove a clean path and open the shoulders.\"},{\"id\":\"4855\",\"n\":\"bodyweight standing oblique twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and arms at chest height.\",\"Rotate your torso to one side.\",\"Return to center.\",\"Rotate to the other side.\",\"Keep your hips facing forward.\"],\"img\":\"4855.webp\",\"gif\":\"4855.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing trunk rotation without load. It warms up the obliques and spine.\"},{\"id\":\"11288\",\"n\":\"bodyweight standing overhead shrug\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\"],\"st\":[\"Stand tall and raise your arms straight overhead.\",\"Keep your ribs down and core tight.\",\"Shrug your shoulders up toward your ears.\",\"Pause briefly.\",\"Lower slowly and repeat.\"],\"img\":\"11288.webp\",\"gif\":\"11288.mp4\",\"cat\":\"mobility\",\"desc\":\"A shrug done with your arms overhead. It wakes up the upper traps and builds shoulder awareness.\"},{\"id\":\"3534\",\"n\":\"bodyweight standing pulse calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand with feet hip-width apart, holding a support for balance.\",\"Rise up onto the balls of your feet.\",\"Pulse up and down in small movements.\",\"Keep your knees straight.\",\"Lower fully when you finish.\",\"Keep the movement controlled.\"],\"img\":\"3534.webp\",\"gif\":\"3534.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing calf raise with small pulses at the top. It builds calf endurance.\"},{\"id\":\"6137\",\"n\":\"bodyweight standing scapula row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Stand tall with your arms out in front or at your sides.\",\"Keep your arms mostly straight.\",\"Pull your shoulder blades back and together.\",\"Hold the squeeze for a second.\",\"Release slowly.\",\"Avoid shrugging your shoulders to your ears.\"],\"img\":\"6137.webp\",\"gif\":\"6137.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing drill where you squeeze your shoulder blades together with no weight. It wakes up the mid back and helps posture.\"},{\"id\":\"8342\",\"n\":\"bodyweight standing scapular external rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Stand tall with your elbows bent at your sides.\",\"Keep your palms facing forward.\",\"Rotate your forearms outward and squeeze your shoulder blades together.\",\"Hold for a second.\",\"Return slowly to the start.\",\"Keep your ribs down and your shoulders away from your ears.\"],\"img\":\"8342.webp\",\"gif\":\"8342.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing drill that rotates the arms outward while drawing the shoulder blades back. It wakes up the rotator cuff and upper back.\"},{\"id\":\"4723\",\"n\":\"bodyweight standing sissy squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"calves\",\"core\"],\"st\":[\"Stand holding a support, feet hip-width apart.\",\"Rise onto the balls of your feet.\",\"Bend your knees forward and lean back.\",\"Lower as far as you can control.\",\"Press back up.\"],\"img\":\"4723.webp\",\"gif\":\"4723.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing squat where your knees travel forward as you lean back, strongly working the quads.\"},{\"id\":\"8343\",\"n\":\"bodyweight standing t spine press\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"core\"],\"st\":[\"Stand with your feet hip width apart.\",\"Clasp your hands in front of your chest.\",\"Press your arms up and slightly back while lifting your chest.\",\"Extend through your upper back without flaring your ribs.\",\"Return to the start under control.\",\"Repeat for smooth, slow reps.\"],\"img\":\"8343.webp\",\"gif\":\"8343.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing movement that presses the arms overhead to open up the thoracic spine. It improves upper back extension.\"},{\"id\":\"4579\",\"n\":\"bodyweight step up on stepbox\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a step box with feet hip-width apart.\",\"Place one foot fully on the box.\",\"Push through your heel to step up and stand tall.\",\"Bring the other foot up to meet it.\",\"Step down with control.\",\"Finish your reps, then switch the lead leg.\"],\"img\":\"4579.webp\",\"gif\":\"4579.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A basic step-up onto a box that builds leg and hip strength and single-leg control.\"},{\"id\":\"6600\",\"n\":\"bodyweight supported squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Hold on to a sturdy support at chest height.\",\"Stand with feet shoulder-width apart.\",\"Sit your hips back and down into a squat.\",\"Keep your chest up and your heels down.\",\"Stand back up by pushing through your feet.\"],\"img\":\"6600.webp\",\"gif\":\"6600.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat where you hold on to a support to stay balanced, ideal for learning depth and form.\"},{\"id\":\"5077\",\"n\":\"bodyweight svend press\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand or sit tall with your palms together at chest height.\",\"Squeeze your palms hard against each other.\",\"Push your hands straight out in front of you.\",\"Bring them back to your chest while still squeezing.\",\"Keep your shoulders down and repeat.\"],\"img\":\"5077.webp\",\"gif\":\"5077.mp4\",\"cat\":\"isometric\",\"desc\":\"Press your palms together hard in front of your chest and push them forward and back. It needs no equipment and fires the inner chest.\"},{\"id\":\"5864\",\"n\":\"bodyweight swing\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart and arms hanging.\",\"Hinge back at your hips and swing your arms between your legs.\",\"Snap your hips forward and stand tall.\",\"Let your arms float up to chest height.\",\"Repeat in a smooth rhythm.\"],\"img\":\"5864.webp\",\"gif\":\"5864.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip hinge swing with your arms moving like a kettlebell swing, but with no weight. It teaches the hip drive and warms up the glutes.\"},{\"id\":\"8536\",\"n\":\"bodyweight tibialis raise wall supported\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Stand with your back against a wall and your feet a bit in front of you.\",\"Keep your legs straight.\",\"Lift your toes toward your shins as high as you can.\",\"Lower slowly to the floor.\",\"Keep the movement smooth and repeat.\"],\"img\":\"8536.webp\",\"gif\":\"8536.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wall-supported toe raise that strengthens the muscles at the front of the shins.\"},{\"id\":\"6423\",\"n\":\"bodyweight triceps extension from plank position\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Start in a forearm-height plank with your hands under your shoulders.\",\"Keep your body in a straight line.\",\"Lean forward and bend your elbows to lower your head toward your hands.\",\"Press back up by straightening your arms.\",\"Keep your core tight and repeat.\"],\"img\":\"6423.webp\",\"gif\":\"6423.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank, you bend and straighten your elbows to hinge forward and press back, a tough bodyweight move for the triceps.\"},{\"id\":\"5700\",\"n\":\"bodyweight walking calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Rise onto the balls of your feet as high as you can.\",\"Take a step forward, staying on your toes.\",\"Keep alternating steps without dropping your heels.\",\"Lower your heels when you reach the end of the set.\"],\"img\":\"5700.webp\",\"gif\":\"5700.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Walk forward staying high on your toes with every step. It builds calf endurance and ankle control without any equipment.\"},{\"id\":\"9700\",\"n\":\"bodyweight walking low lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall with your hands on your hips.\",\"Step forward into a long stride.\",\"Lower your back knee close to the floor.\",\"Push through your front foot and step the back leg forward.\",\"Continue walking forward, alternating legs.\"],\"img\":\"9700.webp\",\"gif\":\"9700.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A walking lunge with a deep, low position that opens the hips and works the glutes and thighs.\"},{\"id\":\"1546\",\"n\":\"bodyweight wall squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Lean your back against a wall with your feet about a step in front of you.\",\"Slide down until your thighs are roughly parallel to the floor.\",\"Keep your knees in line with your toes and your back flat on the wall.\",\"Press through your heels to slide back up.\",\"Repeat for the planned number of reps.\"],\"img\":\"1546.webp\",\"gif\":\"1546.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat with your back against a wall, which keeps your torso upright and takes pressure off the lower back. Good for building leg endurance.\"},{\"id\":\"3908\",\"n\":\"bodyweight windmill\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet wider than shoulder-width and one arm overhead.\",\"Turn your feet slightly outward.\",\"Hinge at the hips and rotate your torso toward the floor.\",\"Reach your free hand toward the opposite foot.\",\"Return to standing with control.\",\"Switch sides after your reps.\"],\"img\":\"3908.webp\",\"gif\":\"3908.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing side bend and twist that loosens the hips and trains the obliques.\",\"fv\":\"3949\"},{\"id\":\"5882\",\"n\":\"bodyweight wood chop squat\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"quadriceps\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart and hands clasped above one shoulder.\",\"Squat down while chopping your hands diagonally toward the opposite knee.\",\"Rotate through your trunk and let your back foot pivot.\",\"Stand up as you swing your arms back up.\",\"Finish all reps, then switch sides.\"],\"img\":\"5882.webp\",\"gif\":\"5882.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat with a diagonal chopping arm motion that trains the legs and teaches the trunk to rotate with control.\"},{\"id\":\"2876\",\"n\":\"boomerang\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"lower back\"],\"st\":[\"Sit tall with legs extended and crossed at the ankles.\",\"Roll back and lift your legs overhead, then switch the cross.\",\"Roll up to a teaser with your legs lifted.\",\"Hold your hands behind you and then reach forward over your legs.\",\"Move smoothly, using your abs to control each roll.\"],\"img\":\"2876.webp\",\"gif\":\"2876.mp4\",\"cat\":\"pilates\",\"desc\":\"An advanced Pilates sequence of rolling and balancing that tests core control.\"},{\"id\":\"8479\",\"n\":\"bosu ball balance counterbalanced skater squat\",\"bp\":\"upper legs\",\"eq\":\"bosu ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"ankles\"],\"st\":[\"Stand on one foot on the bosu ball and hold your arms in front for balance.\",\"Reach the free leg back behind you.\",\"Sit your hips back and lower into a single-leg squat.\",\"Drive through the standing foot to rise.\",\"Finish the reps, then switch legs.\"],\"img\":\"8479.webp\",\"gif\":\"8479.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat on a bosu ball with the free leg reaching back for balance, challenging the legs and stability.\"},{\"id\":\"10869\",\"n\":\"bosu ball single leg squat\",\"bp\":\"upper legs\",\"eq\":\"bosu ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand on one foot on the Bosu.\",\"Extend your arms for balance.\",\"Lower into a controlled squat.\",\"Keep your knee in line with your toes.\",\"Press back up.\",\"Switch legs after the set.\"],\"img\":\"10869.webp\",\"gif\":\"10869.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat on a Bosu ball. It challenges the legs and balance.\"},{\"id\":\"10868\",\"n\":\"bosu ball squat\",\"bp\":\"upper legs\",\"eq\":\"bosu ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand on the Bosu with feet shoulder width apart.\",\"Hold your arms forward.\",\"Sit your hips back and bend your knees.\",\"Keep your chest lifted.\",\"Stand tall.\",\"Keep your knees tracking over your toes.\"],\"img\":\"10868.webp\",\"gif\":\"10868.mp4\",\"cat\":\"strength\",\"desc\":\"Squat standing on a Bosu ball. The unstable surface adds a balance challenge.\"},{\"id\":\"3554\",\"n\":\"bottle hammer curl\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Hold a filled bottle in each hand with palms facing each other.\",\"Keep your elbows by your sides.\",\"Curl the bottles toward your shoulders.\",\"Squeeze at the top.\",\"Lower with control.\",\"Avoid swinging.\"],\"img\":\"3554.webp\",\"gif\":\"3554.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl with water bottles as light weights. It trains the biceps and forearms.\"},{\"id\":\"6068\",\"n\":\"bottle weighted alternate biceps curl\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand tall with a bottle in each hand, palms forward.\",\"Curl one bottle toward your shoulder.\",\"Lower it slowly as you curl the other.\",\"Keep your elbows by your sides.\",\"Avoid swinging your torso.\"],\"img\":\"6068.webp\",\"gif\":\"6068.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating curls with a bottle in each hand. It builds the biceps and keeps the pace easy.\"},{\"id\":\"6075\",\"n\":\"bottle weighted alternate front raise\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Stand tall with a bottle in each hand.\",\"Raise one arm forward to shoulder height.\",\"Lower it slowly as you raise the other.\",\"Keep your torso still.\",\"Breathe steadily.\"],\"img\":\"6075.webp\",\"gif\":\"6075.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating front raises with a bottle in each hand. It works the front delts.\"},{\"id\":\"6069\",\"n\":\"bottle weighted alternate hammer curl\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand tall with a bottle in each hand, palms facing your body.\",\"Curl one bottle up without rotating your wrist.\",\"Lower it slowly.\",\"Curl the other arm.\",\"Keep your elbows pinned.\"],\"img\":\"6069.webp\",\"gif\":\"6069.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating curls with palms facing in. It works the biceps, brachialis and forearms.\"},{\"id\":\"6072\",\"n\":\"bottle weighted armpit row\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"upper back\",\"biceps\"],\"st\":[\"Hold a bottle in each hand and hinge slightly forward.\",\"Pull your elbows out and up, bottles moving toward your armpits.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\",\"Keep your neck relaxed.\"],\"img\":\"6072.webp\",\"gif\":\"6072.mp4\",\"cat\":\"strength\",\"desc\":\"A high row pulling bottles up toward your armpits. It trains the rear shoulders and upper back.\"},{\"id\":\"6061\",\"n\":\"bottle weighted bent over reverse fly\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Hinge forward with a flat back, a bottle in each hand hanging below you.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides to shoulder height.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\"],\"img\":\"6061.webp\",\"gif\":\"6061.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over fly with bottles that targets the rear shoulders and upper back.\"},{\"id\":\"6059\",\"n\":\"bottle weighted bent over row\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"lower back\"],\"st\":[\"Hold a bottle in each hand and hinge forward with a flat back.\",\"Let your arms hang below your shoulders.\",\"Pull the bottles toward your hips, elbows close to your body.\",\"Squeeze your shoulder blades together.\",\"Lower slowly.\"],\"img\":\"6059.webp\",\"gif\":\"6059.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a bottle in each hand. It trains the mid back and lats.\"},{\"id\":\"6063\",\"n\":\"bottle weighted concentration curl\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Sit with feet wide, a bottle in one hand, and rest your elbow on your inner thigh.\",\"Let your arm hang fully.\",\"Curl the bottle toward your shoulder.\",\"Squeeze your biceps at the top.\",\"Lower slowly, then switch arms.\"],\"img\":\"6063.webp\",\"gif\":\"6063.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm curl with your elbow braced on your thigh. It isolates the biceps.\"},{\"id\":\"5988\",\"n\":\"bottle weighted deadlift\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"forearms\"],\"st\":[\"Hold a bottle in each hand and stand with feet hip-width apart.\",\"Hinge at your hips with a flat back and soft knees.\",\"Lower the bottles along your legs to mid-shin.\",\"Drive your hips forward to stand tall.\",\"Squeeze your glutes at the top.\"],\"img\":\"5988.webp\",\"gif\":\"5988.mp4\",\"cat\":\"strength\",\"desc\":\"A light deadlift holding a bottle in each hand. A good way to learn the hip hinge.\"},{\"id\":\"6047\",\"n\":\"bottle weighted forward lunge\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand tall holding a bottle in each hand at your sides.\",\"Step forward with one leg.\",\"Lower until both knees are bent about 90 degrees.\",\"Push off the front foot to return to standing.\",\"Alternate legs each rep.\"],\"img\":\"6047.webp\",\"gif\":\"6047.mp4\",\"cat\":\"strength\",\"desc\":\"A walking-style lunge stepping forward with bottles in your hands. It works the quads and glutes one leg at a time.\"},{\"id\":\"6053\",\"n\":\"bottle weighted frog crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with soles together, knees open, holding a bottle on your chest.\",\"Curl your upper body up as you pull your knees in.\",\"Bring your chest toward your knees.\",\"Hold for a moment.\",\"Lower with control and repeat.\"],\"img\":\"6053.webp\",\"gif\":\"6053.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch that draws knees and chest together while holding a bottle. It trains the whole abdominal wall.\"},{\"id\":\"6073\",\"n\":\"bottle weighted front raise\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Stand tall with a bottle in each hand in front of your thighs.\",\"Raise both arms straight in front to shoulder height.\",\"Keep a slight bend in your elbows.\",\"Pause.\",\"Lower slowly without swinging.\"],\"img\":\"6073.webp\",\"gif\":\"6073.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with bottles for the front of the shoulders.\"},{\"id\":\"6044\",\"n\":\"bottle weighted front squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\",\"upper back\"],\"st\":[\"Hold a bottle in each hand at your shoulders, elbows pointing forward.\",\"Stand with feet shoulder-width apart.\",\"Sit your hips down and back until your thighs are about parallel.\",\"Keep your chest up and knees tracking over your toes.\",\"Press through your heels to stand.\"],\"img\":\"6044.webp\",\"gif\":\"6044.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding weighted bottles at shoulder height. It works the quads and glutes and keeps your torso upright.\"},{\"id\":\"6050\",\"n\":\"bottle weighted glute bridge\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a bottle across your hips with both hands.\",\"Push through your heels and lift your hips.\",\"Squeeze your glutes at the top, forming a straight line from shoulders to knees.\",\"Lower slowly and repeat.\"],\"img\":\"6050.webp\",\"gif\":\"6050.mp4\",\"cat\":\"strength\",\"desc\":\"A hip bridge with a weighted bottle resting on your hips. It isolates the glutes with light load.\"},{\"id\":\"7276\",\"n\":\"bottle weighted gorilla row\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"grip muscles\"],\"st\":[\"Stand wide with a bottle on the floor between your feet and hinge forward.\",\"Keep your back flat and grip a bottle in each hand.\",\"Row one bottle up to your hip while the other stays down.\",\"Lower it, then row with the other side.\",\"Keep your hips steady and alternate sides.\"],\"img\":\"7276.webp\",\"gif\":\"7276.mp4\",\"cat\":\"strength\",\"desc\":\"Gorilla row using a weighted bottle in each hand, a handy way to train the back at home.\",\"fv\":\"6062\"},{\"id\":\"6077\",\"n\":\"bottle weighted halo\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"trapezius\",\"core\",\"triceps\"],\"st\":[\"Stand tall holding a bottle at chest height with both hands.\",\"Circle it around your head, staying close.\",\"Keep your core braced and ribs down.\",\"Complete the circle back to the front.\",\"Reverse direction on the next set.\"],\"img\":\"6077.webp\",\"gif\":\"6077.mp4\",\"cat\":\"mobility\",\"desc\":\"A circular movement of a bottle around your head. It warms up the shoulders and upper back.\"},{\"id\":\"6065\",\"n\":\"bottle weighted kickback\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rear deltoids\",\"core\"],\"st\":[\"Hinge forward with a flat back, upper arm parallel to the floor, bottle in hand.\",\"Keep your elbow tight at your side.\",\"Straighten your arm behind you.\",\"Squeeze your triceps.\",\"Bend slowly, then switch arms.\"],\"img\":\"6065.webp\",\"gif\":\"6065.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm triceps kickback holding a bottle. It isolates the back of the arm.\"},{\"id\":\"6051\",\"n\":\"bottle weighted kneeling squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Kneel on a mat with hips over knees, holding a bottle at your chest.\",\"Sit your hips back toward your heels.\",\"Pause lightly, keeping your back straight.\",\"Drive your hips forward to return to upright.\",\"Squeeze your glutes at the top.\"],\"img\":\"6051.webp\",\"gif\":\"6051.mp4\",\"cat\":\"strength\",\"desc\":\"A squat from a kneeling position holding a bottle. It trains the glutes and hips without loading your feet.\"},{\"id\":\"6074\",\"n\":\"bottle weighted lateral raise\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with a bottle in each hand at your sides.\",\"Raise your arms out to the sides up to shoulder height.\",\"Lead with your elbows.\",\"Pause briefly.\",\"Lower slowly.\"],\"img\":\"6074.webp\",\"gif\":\"6074.mp4\",\"cat\":\"strength\",\"desc\":\"A side raise with bottles that builds the shoulder caps.\"},{\"id\":\"6057\",\"n\":\"bottle weighted lying chest press\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on your back, knees bent, holding a bottle in each hand at chest level.\",\"Press the bottles straight up until your arms are extended.\",\"Keep your wrists straight.\",\"Lower slowly until your elbows touch the floor or reach chest level.\",\"Repeat for your reps.\"],\"img\":\"6057.webp\",\"gif\":\"6057.mp4\",\"cat\":\"strength\",\"desc\":\"A floor or bench press with a bottle in each hand. It builds the chest and triceps with light load.\"},{\"id\":\"6052\",\"n\":\"bottle weighted overhead crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Lie on your back, knees bent, holding a bottle with both hands above your chest.\",\"Extend your arms overhead or keep them over your face.\",\"Curl your ribs toward your hips and lift your shoulders off the floor.\",\"Pause at the top.\",\"Lower slowly without dropping your head.\"],\"img\":\"6052.webp\",\"gif\":\"6052.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with a bottle held overhead. The extra lever length makes your abs work harder.\"},{\"id\":\"6067\",\"n\":\"bottle weighted overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"forearms\"],\"st\":[\"Stand or sit tall holding a bottle overhead with both hands.\",\"Keep your elbows pointing forward.\",\"Bend your elbows and lower the bottle behind your head.\",\"Extend your arms to lift it back up.\",\"Keep your upper arms still.\"],\"img\":\"6067.webp\",\"gif\":\"6067.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead extension with a bottle held in both hands. It stretches and strengthens the triceps.\"},{\"id\":\"6060\",\"n\":\"bottle weighted pullover\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on your back, knees bent, holding a bottle with both hands over your chest.\",\"Keep your arms nearly straight.\",\"Lower the bottle in an arc behind your head.\",\"Stop when you feel a stretch in your sides.\",\"Pull it back over your chest.\"],\"img\":\"6060.webp\",\"gif\":\"6060.mp4\",\"cat\":\"strength\",\"desc\":\"A lying pullover with a bottle held in both hands. It stretches and works the lats and chest.\"},{\"id\":\"6048\",\"n\":\"bottle weighted rear lunge\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand tall holding a bottle in each hand.\",\"Step one leg back and lower your back knee toward the floor.\",\"Keep your front shin vertical and your chest up.\",\"Push through the front heel to come back.\",\"Alternate legs, or finish one side then switch.\"],\"img\":\"6048.webp\",\"gif\":\"6048.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge stepping backward while holding bottles. It is easy on the knees and trains the glutes and quads.\"},{\"id\":\"6070\",\"n\":\"bottle weighted reverse curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand tall holding a bottle in each hand with palms facing down.\",\"Keep your elbows at your sides.\",\"Curl the bottles up with straight wrists.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"6070.webp\",\"gif\":\"6070.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with an overhand grip holding bottles. It trains the forearms and brachialis.\"},{\"id\":\"6064\",\"n\":\"bottle weighted reverse grip concentration curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit with feet wide, holding a bottle with an overhand grip, elbow resting on your inner thigh.\",\"Let your arm hang straight.\",\"Curl the bottle up without bending your wrist.\",\"Pause at the top.\",\"Lower slowly, then switch arms.\"],\"img\":\"6064.webp\",\"gif\":\"6064.mp4\",\"cat\":\"strength\",\"desc\":\"A seated concentration curl with an overhand grip. It targets the forearms and brachialis.\"},{\"id\":\"6041\",\"n\":\"bottle weighted romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet hip-width apart, holding a bottle in each hand in front of your thighs.\",\"Soften your knees and push your hips back.\",\"Lower the bottles along your legs with a flat back until you feel your hamstrings stretch.\",\"Drive your hips forward to stand tall.\",\"Keep your shoulders back and your core braced.\"],\"img\":\"6041.webp\",\"gif\":\"6041.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge holding a weighted bottle in each hand. It trains the hamstrings and glutes with light load.\"},{\"id\":\"6055\",\"n\":\"bottle weighted russian twist\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor, knees bent, and lean back a little with a straight spine.\",\"Hold a bottle with both hands in front of your chest.\",\"Rotate your torso to one side and tap the bottle near the floor.\",\"Rotate to the other side.\",\"Keep your feet down or lifted for more challenge.\"],\"img\":\"6055.webp\",\"gif\":\"6055.mp4\",\"cat\":\"strength\",\"desc\":\"A seated rotation holding a bottle. It works the obliques and deep core.\"},{\"id\":\"6076\",\"n\":\"bottle weighted shoulder press\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Hold a bottle in each hand at shoulder height.\",\"Brace your core and stand tall.\",\"Press both bottles overhead until your arms are straight.\",\"Lower back to shoulder height.\",\"Do not arch your lower back.\"],\"img\":\"6076.webp\",\"gif\":\"6076.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with a bottle in each hand. It builds shoulders and triceps.\"},{\"id\":\"6054\",\"n\":\"bottle weighted side bend\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet hip-width apart, a bottle in one hand at your side.\",\"Place the other hand lightly behind your head.\",\"Bend sideways toward the bottle without leaning forward.\",\"Return to upright by squeezing your side.\",\"Finish your reps, then switch sides.\"],\"img\":\"6054.webp\",\"gif\":\"6054.mp4\",\"cat\":\"strength\",\"desc\":\"A standing side bend with a bottle in one hand. It strengthens the obliques.\"},{\"id\":\"6042\",\"n\":\"bottle weighted single leg romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"ankles\"],\"st\":[\"Stand on one leg holding a bottle in each hand, with a slight bend in the knee.\",\"Hinge at the hips and extend the free leg straight behind you.\",\"Lower the bottles toward the floor with a flat back.\",\"Squeeze your glute to return to standing.\",\"Finish your reps, then switch legs.\"],\"img\":\"6042.webp\",\"gif\":\"6042.mp4\",\"cat\":\"strength\",\"desc\":\"A one-legged hip hinge holding weighted bottles. It works the hamstrings and glutes and challenges balance.\"},{\"id\":\"6046\",\"n\":\"bottle weighted split squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a bottle in each hand and step into a long split stance.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Press through the front heel to rise.\",\"Complete your reps, then switch legs.\"],\"img\":\"6046.webp\",\"gif\":\"6046.mp4\",\"cat\":\"strength\",\"desc\":\"A stationary lunge holding bottles at your sides. It builds single-leg strength in the quads and glutes.\"},{\"id\":\"6056\",\"n\":\"bottle weighted squatting alternate waves\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart, a bottle in each hand.\",\"Squat down with your hips back.\",\"As you stand, raise one arm up and the other down in a wave motion.\",\"Switch arms on the next squat.\",\"Move at a steady, controlled pace.\"],\"img\":\"6056.webp\",\"gif\":\"6056.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat with arms swinging like waves while holding bottles. It raises your heart rate and works legs and shoulders.\"},{\"id\":\"6049\",\"n\":\"bottle weighted straight legs deadlift\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand tall holding a bottle in each hand in front of your thighs.\",\"Keep your legs almost straight, with a tiny knee bend.\",\"Hinge forward, sliding the bottles down your legs.\",\"Stop when you feel a firm hamstring stretch.\",\"Squeeze your glutes to stand back up.\"],\"img\":\"6049.webp\",\"gif\":\"6049.mp4\",\"cat\":\"strength\",\"desc\":\"A near-straight-leg deadlift with bottles in your hands. It stretches and strengthens the hamstrings.\"},{\"id\":\"6045\",\"n\":\"bottle weighted sumo squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand with feet wide and toes turned out, holding a bottle with both hands in front of you.\",\"Bend your knees and lower your hips straight down.\",\"Keep your knees pushing out over your toes.\",\"Stop when your thighs are about parallel.\",\"Drive up through your heels and squeeze your glutes.\"],\"img\":\"6045.webp\",\"gif\":\"6045.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance squat holding a weighted bottle between your legs. It hits the glutes and inner thighs.\"},{\"id\":\"6058\",\"n\":\"bottle weighted svend press\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Stand tall and press your palms together around a bottle at your chest.\",\"Squeeze inward the whole time.\",\"Push the bottle straight out in front of you.\",\"Pause with your arms extended.\",\"Bring it back to your chest slowly.\"],\"img\":\"6058.webp\",\"gif\":\"6058.mp4\",\"cat\":\"strength\",\"desc\":\"A standing press with a bottle squeezed between your palms. It keeps constant tension on the chest.\"},{\"id\":\"6043\",\"n\":\"bottle weighted swing\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet wider than your hips, holding a bottle with both hands.\",\"Hinge back and let the bottle swing between your legs.\",\"Snap your hips forward and let the bottle swing to chest height.\",\"Keep your arms relaxed, the hips do the work.\",\"Let it fall back and hinge into the next rep.\"],\"img\":\"6043.webp\",\"gif\":\"6043.mp4\",\"cat\":\"strength\",\"desc\":\"A hip-driven swing with a weighted bottle held in both hands. It trains the glutes and hamstrings explosively.\"},{\"id\":\"6066\",\"n\":\"bottle weighted two arms kickback\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rear deltoids\",\"core\"],\"st\":[\"Hinge forward with a flat back, a bottle in each hand, upper arms parallel to the floor.\",\"Keep your elbows tucked.\",\"Extend both arms straight behind you.\",\"Squeeze at the top.\",\"Return slowly.\"],\"img\":\"6066.webp\",\"gif\":\"6066.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps kickback done with both arms together using two bottles.\"},{\"id\":\"6071\",\"n\":\"bottle weighted upright row\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Stand tall holding bottles in front of your thighs, palms facing you.\",\"Pull them up along your body, elbows leading.\",\"Stop at about chest height.\",\"Lower slowly.\",\"Keep the bottles close to your torso.\"],\"img\":\"6071.webp\",\"gif\":\"6071.mp4\",\"cat\":\"strength\",\"desc\":\"A vertical pull with bottles toward your chest. It works the shoulders and traps.\"},{\"id\":\"1481\",\"n\":\"bow yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"chest\",\"lower back\"],\"st\":[\"Lie on your stomach with your arms along your sides.\",\"Bend your knees and reach back to hold your ankles.\",\"Lift your chest and kick your feet gently into your hands to raise your thighs.\",\"Keep your gaze forward and breathe steadily.\",\"Hold for 15-30 seconds, then release slowly and rest on the mat.\"],\"img\":\"1481.webp\",\"gif\":\"1481.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga backbend where you lie on your belly and hold your ankles. It stretches the thighs, chest and front of the hips.\"},{\"id\":\"9511\",\"n\":\"box assisted pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Place a box under a pull-up bar.\",\"Grip the bar and rest one or both feet on the box.\",\"Pull up until your chin clears the bar.\",\"Use your legs as little as possible.\",\"Lower slowly.\",\"Keep your core tight.\"],\"img\":\"9511.webp\",\"gif\":\"9511.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with your feet on a box for light assistance. It helps you build up to full pull-ups.\"},{\"id\":\"9068\",\"n\":\"box drop 2 foot land\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand at the edge of a low box.\",\"Step off without jumping.\",\"Land on both feet at the same time.\",\"Bend your hips and knees to absorb the impact.\",\"Hold the landing for a second.\",\"Step back up and repeat.\"],\"img\":\"9068.webp\",\"gif\":\"9068.mp4\",\"cat\":\"plyometrics\",\"desc\":\"You step off a box and land on both feet to practise soft landings. It builds impact control.\"},{\"id\":\"9606\",\"n\":\"box drop jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand on the edge of a low box with feet hip-width apart.\",\"Step off, do not jump, and land on both feet.\",\"Absorb the landing by bending your knees and hips.\",\"Immediately explode upward into a jump.\",\"Land softly and reset.\"],\"img\":\"9606.webp\",\"gif\":\"9606.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A plyometric where you step off a box, land, and jump up immediately. It trains reactive strength in the legs.\"},{\"id\":\"10160\",\"n\":\"box jump drop 2 foot land\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on a sturdy box with your toes near the edge.\",\"Step off the box, do not jump.\",\"Land on both feet at the same time with soft, bent knees.\",\"Sink into a quarter squat to absorb the impact and hold the landing.\",\"Step back up and repeat. Keep your knees in line with your toes.\"],\"img\":\"10160.webp\",\"gif\":\"10160.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A drop from a box with a soft two foot landing that trains landing control and leg power.\"},{\"id\":\"10738\",\"n\":\"box jump through the arms\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\",\"shoulders\"],\"st\":[\"Stand facing a sturdy box.\",\"Swing your arms back and bend your knees.\",\"Jump onto the box, driving your arms through.\",\"Land softly with both feet.\",\"Stand tall at the top.\",\"Step down and reset.\"],\"img\":\"10738.webp\",\"gif\":\"10738.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A box jump with a swing-through arm action. It builds explosive power and coordination.\"},{\"id\":\"9512\",\"n\":\"box single leg assisted pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Place a box under a pull-up bar.\",\"Grip the bar and rest one foot on the box.\",\"Pull up until your chin clears the bar.\",\"Push lightly with the foot on the box.\",\"Lower slowly.\",\"Switch the assisting leg on the next set.\"],\"img\":\"9512.webp\",\"gif\":\"9512.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with only one foot on a box for assistance. It is a step closer to a full pull-up.\"},{\"id\":\"3532\",\"n\":\"boxer shuffle\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"core\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart, knees soft.\",\"Shift your weight from foot to foot.\",\"Stay on the balls of your feet.\",\"Keep your hands up like a guard.\",\"Keep it light and quick for 30-60 seconds.\",\"Rest briefly and repeat.\"],\"img\":\"3532.webp\",\"gif\":\"3532.mp4\",\"cat\":\"cardio\",\"desc\":\"A light-footed shuffle used by boxers to keep the heart rate up.\"},{\"id\":\"4581\",\"n\":\"boxing block\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"core\",\"upper back\"],\"st\":[\"Stand in a boxing stance with feet staggered and knees slightly bent.\",\"Bring your fists up to your cheeks with elbows tucked in.\",\"Keep your chin down.\",\"Raise your forearms to cover your face as if blocking a punch.\",\"Bring your elbows together to cover your ribs.\",\"Reset to your guard and repeat.\"],\"img\":\"4581.webp\",\"gif\":\"4581.mp4\",\"cat\":\"combat\",\"desc\":\"A defensive boxing guard that covers your head and body from incoming punches.\"},{\"id\":\"2272\",\"n\":\"boxing jab\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\",\"core\"],\"st\":[\"Stand in a boxing stance with your lead foot forward and hands up by your chin.\",\"Extend your lead hand straight toward the target.\",\"Rotate your fist so the palm faces down as it lands.\",\"Keep your chin tucked and your rear hand guarding.\",\"Snap the hand back to the guard quickly.\",\"Repeat, then switch stance if you want.\"],\"img\":\"2272.webp\",\"gif\":\"2272.mp4\",\"cat\":\"combat\",\"desc\":\"A quick straight punch with the lead hand, used to build speed, shoulder endurance and timing.\"},{\"id\":\"4582\",\"n\":\"boxing jab (with boxing bag)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\",\"core\"],\"st\":[\"Stand in a boxing stance facing the bag with your hands up.\",\"Extend your lead hand straight toward the bag.\",\"Rotate your fist so the palm faces down on impact.\",\"Keep your rear hand guarding your chin.\",\"Snap the punch back to your guard right away.\",\"Stay light on your feet and repeat.\"],\"img\":\"4582.webp\",\"gif\":\"4582.mp4\",\"cat\":\"combat\",\"desc\":\"A quick straight punch with your lead hand thrown at a heavy bag.\"},{\"id\":\"4589\",\"n\":\"boxing jab (with partner)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\",\"core\"],\"st\":[\"Face your partner, who holds a pad at head height.\",\"Stand in a boxing stance with hands up.\",\"Throw your lead hand straight to the pad.\",\"Rotate your fist so the palm faces down.\",\"Retract your hand quickly to your guard.\",\"Keep your feet light and repeat.\"],\"img\":\"4589.webp\",\"gif\":\"4589.mp4\",\"cat\":\"combat\",\"desc\":\"A straight lead-hand punch thrown at a partner holding pads, working speed and accuracy.\"},{\"id\":\"2275\",\"n\":\"boxing left uppercut\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"core\",\"chest\"],\"st\":[\"Stand in a boxing stance with hands up.\",\"Bend your knees slightly and dip your left side.\",\"Drive up through your legs as you rotate your hips.\",\"Throw your left fist upward with the palm facing you.\",\"Keep your right hand guarding your chin.\",\"Return to stance and repeat.\"],\"img\":\"2275.webp\",\"gif\":\"2275.mp4\",\"cat\":\"combat\",\"desc\":\"A rising punch with the left hand, thrown upward from the hips and legs.\"},{\"id\":\"4590\",\"n\":\"boxing left uppercut (with partner)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"chest\",\"obliques\",\"core\"],\"st\":[\"Face your partner, who holds a pad low in front of them.\",\"Stand in a boxing stance and bend your knees slightly.\",\"Dip slightly and drive up through your legs.\",\"Rotate your hips as you bring your left fist up in a tight arc.\",\"Hit the pad with the palm facing you.\",\"Reset your guard.\"],\"img\":\"4590.webp\",\"gif\":\"4590.mp4\",\"cat\":\"combat\",\"desc\":\"A rising punch with the left hand thrown to a partner's pad, using leg and hip drive.\"},{\"id\":\"2273\",\"n\":\"boxing right cross\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\",\"core\"],\"st\":[\"Stand in a boxing stance with hands up.\",\"Push off the back foot and rotate your hips and shoulders.\",\"Throw your rear hand straight toward the target.\",\"Keep your lead hand up to protect your chin.\",\"Pull the hand back along the same line.\",\"Return to your stance and repeat.\"],\"img\":\"2273.webp\",\"gif\":\"2273.mp4\",\"cat\":\"combat\",\"desc\":\"A powerful straight punch with the rear hand, driven by a turn of the hips and back foot.\"},{\"id\":\"4583\",\"n\":\"boxing right cross (with boxing bag)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"obliques\",\"core\"],\"st\":[\"Stand in a boxing stance facing the bag.\",\"Rotate your rear foot and hips as you throw the right hand.\",\"Drive your fist straight to the bag.\",\"Rotate your shoulder and keep your chin tucked.\",\"Keep your lead hand up to guard.\",\"Snap back to your stance and repeat.\"],\"img\":\"4583.webp\",\"gif\":\"4583.mp4\",\"cat\":\"combat\",\"desc\":\"A powerful straight punch from the rear hand, driven by the hips and thrown at a bag.\"},{\"id\":\"4591\",\"n\":\"boxing right cross (with partner)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"obliques\",\"core\"],\"st\":[\"Face your partner, who holds a pad at head height.\",\"Stand in a boxing stance with hands up.\",\"Rotate your rear foot and hips as you throw the right hand.\",\"Drive your fist straight to the pad.\",\"Keep your chin tucked and left hand up.\",\"Snap back to your stance.\"],\"img\":\"4591.webp\",\"gif\":\"4591.mp4\",\"cat\":\"combat\",\"desc\":\"A straight rear-hand punch with hip rotation, thrown to a partner's pad.\"},{\"id\":\"3171\",\"n\":\"boxing right hook\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"chest\",\"calves\"],\"st\":[\"Stand in a boxing stance with your hands up.\",\"Bend your right elbow to about 90 degrees.\",\"Pivot on your back foot and rotate your hips and torso.\",\"Swing your fist in an arc to your target.\",\"Snap back to guard position.\",\"Keep your chin tucked and your left hand up.\"],\"img\":\"3171.webp\",\"gif\":\"3171.mp4\",\"cat\":\"combat\",\"desc\":\"A right-handed hook punch thrown in a boxing stance. It trains rotation and power from the hips.\"},{\"id\":\"4584\",\"n\":\"boxing right hook (with boxing bag)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"obliques\",\"core\"],\"st\":[\"Stand in a boxing stance facing the bag.\",\"Bend your right elbow to about 90 degrees.\",\"Rotate your hips and torso to swing the fist in an arc.\",\"Pivot your rear foot as you turn.\",\"Hit the bag and keep your left hand guarding.\",\"Return to your guard and repeat.\"],\"img\":\"4584.webp\",\"gif\":\"4584.mp4\",\"cat\":\"combat\",\"desc\":\"A curved punch thrown from the rear hand, rotating the torso to hit the side of the bag.\"},{\"id\":\"4592\",\"n\":\"boxing right hook (with partner)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"obliques\",\"core\"],\"st\":[\"Face your partner, who holds a pad out to the side.\",\"Stand in a boxing stance with hands up.\",\"Bend your right elbow and rotate your hips and torso.\",\"Swing the fist in an arc into the pad.\",\"Pivot your rear foot as you turn.\",\"Return to your guard.\"],\"img\":\"4592.webp\",\"gif\":\"4592.mp4\",\"cat\":\"combat\",\"desc\":\"A curved rear-hand punch thrown to a partner's pad, using torso rotation for power.\"},{\"id\":\"2274\",\"n\":\"boxing right uppercut\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"core\",\"chest\"],\"st\":[\"Stand in a boxing stance with hands up.\",\"Bend your knees slightly and dip your right side.\",\"Drive up through your legs as you rotate your hips.\",\"Throw your right fist upward with the palm facing you.\",\"Keep your left hand guarding your chin.\",\"Return to stance and repeat.\"],\"img\":\"2274.webp\",\"gif\":\"2274.mp4\",\"cat\":\"combat\",\"desc\":\"A rising punch with the right hand aimed upward, using leg drive and a hip turn.\"},{\"id\":\"4593\",\"n\":\"boxing right uppercut (with partner)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"chest\",\"obliques\",\"core\"],\"st\":[\"Face your partner, who holds a pad low in front of them.\",\"Stand in a boxing stance and bend your knees slightly.\",\"Drive up through your legs and rotate your hips.\",\"Bring your right fist up in a tight arc to the pad.\",\"Keep your left hand guarding.\",\"Reset your stance.\"],\"img\":\"4593.webp\",\"gif\":\"4593.mp4\",\"cat\":\"combat\",\"desc\":\"A rising rear-hand punch thrown to a partner's pad, driven by the legs and hips.\"},{\"id\":\"0142\",\"n\":\"bridge (on knees)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\"],\"st\":[\"Kneel on a mat and lean forward onto your forearms.\",\"Position your elbows under your shoulders.\",\"Lift your hips so your body forms a straight line from knees to head.\",\"Brace your abs and squeeze your glutes.\",\"Hold for 20-30 seconds.\",\"Lower gently and rest.\"],\"img\":\"0142.webp\",\"gif\":\"0142.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank-style bridge hold supported on the knees. It builds trunk endurance with less load than a full plank.\",\"hd\":1},{\"id\":\"0143\",\"n\":\"bridge (straight arm)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Extend your legs behind you with your toes on the floor.\",\"Squeeze your glutes and brace your abs.\",\"Keep your body in a straight line.\",\"Hold for 20-30 seconds.\",\"Lower your knees to rest.\"],\"img\":\"0143.webp\",\"gif\":\"0143.mp4\",\"cat\":\"isometric\",\"desc\":\"A bridge hold on straight arms like the top of a push-up. It trains the abs and shoulder stability.\",\"hd\":1},{\"id\":\"4881\",\"n\":\"bridge hip abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat on the floor.\",\"Drive through your heels and lift your hips into a bridge.\",\"Keeping the hips high, open both knees out to the sides.\",\"Bring the knees back together without dropping the hips.\",\"Lower slowly to the floor and repeat.\",\"Keep your ribs down so your lower back does not arch.\"],\"img\":\"4881.webp\",\"gif\":\"4881.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge where you press the knees apart at the top. It fires up the outer hips and glutes.\",\"fv\":\"0144\"},{\"id\":\"4511\",\"n\":\"bridge pose setu bandhasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"chest\"],\"st\":[\"Lie on your back with your knees bent and feet hip width apart.\",\"Place your arms alongside your body, palms down.\",\"Press through your feet and lift your hips.\",\"Roll your shoulders under and lengthen your chest.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Lower down slowly.\"],\"img\":\"4511.webp\",\"gif\":\"4511.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga backbend that strengthens the glutes and opens the chest and hip flexors.\",\"fv\":\"0941\"},{\"id\":\"3565\",\"n\":\"bridge pose yoga stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"chest\"],\"st\":[\"Lie on your back with knees bent and feet flat near your hips.\",\"Place your hands beside your head, palms down, fingers toward your shoulders.\",\"Press through hands and feet to lift your hips and chest.\",\"Straighten your arms as far as is comfortable and relax your neck.\",\"Hold for 15-30 seconds, then lower slowly.\"],\"img\":\"3565.webp\",\"gif\":\"3565.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep backbend where you press up from the floor, opening the chest and hips and strengthening the back of the body.\"},{\"id\":\"3004\",\"n\":\"briskly walking\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Stand tall with your shoulders relaxed.\",\"Start walking at a pace faster than a stroll.\",\"Swing your arms naturally with elbows bent.\",\"Land on your heel and roll through to your toes.\",\"Keep breathing steadily and stay able to talk.\",\"Walk for 20-45 minutes.\"],\"img\":\"3004.webp\",\"gif\":\"3004.mp4\",\"cat\":\"cardio\",\"desc\":\"A fast-paced walk that lifts your heart rate without the impact of running. Easy on the joints and good for steady fitness.\",\"fv\":\"3003\"},{\"id\":\"4242\",\"n\":\"broad jump to vertical\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart and swing your arms back.\",\"Jump forward as far as you can.\",\"Land softly with bent knees.\",\"Immediately explode into a vertical jump with your arms up.\",\"Land softly and reset.\",\"Take a short rest between reps.\"],\"img\":\"4242.webp\",\"gif\":\"4242.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A forward jump followed straight away by a jump up. It trains explosive power in two directions.\"},{\"id\":\"3863\",\"n\":\"bulgarian jump squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing away from a bench and rest the top of one foot on it.\",\"Lower into a split squat until your front thigh is about parallel.\",\"Drive up explosively through your front foot so it leaves the floor.\",\"Land softly and sink straight back into the next rep.\",\"Keep your torso upright and your front knee stable.\",\"Finish all reps, then switch legs.\"],\"img\":\"3863.webp\",\"gif\":\"3863.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A single-leg squat jump with the rear foot elevated, building explosive power and balance in each leg.\"},{\"id\":\"3743\",\"n\":\"bulgarian split squat with chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand facing away from a chair and rest the top of one foot on it.\",\"Step your front foot forward so it is stable.\",\"Lower your back knee toward the floor.\",\"Push through your front foot to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"3743.webp\",\"gif\":\"3743.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat with your rear foot resting on a chair, which builds strength and balance.\"},{\"id\":\"8704\",\"n\":\"burpee jump box\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"chest\",\"shoulders\",\"core\"],\"st\":[\"Stand facing a box.\",\"Drop into a squat, kick your feet back and lower into a push-up.\",\"Jump your feet back in.\",\"Explode up and jump onto the box.\",\"Step down carefully and repeat.\"],\"img\":\"8704.webp\",\"gif\":\"8704.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A burpee that finishes with a jump onto a box, great for full-body conditioning.\"},{\"id\":\"5187\",\"n\":\"burpee long jump with push up\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"quadriceps\",\"core\"],\"st\":[\"Stand tall, then squat and place your hands on the floor.\",\"Jump your feet back and do one push-up.\",\"Jump your feet back toward your hands.\",\"Explode into a long jump forward.\",\"Land softly with bent knees and go into the next rep.\"],\"img\":\"5187.webp\",\"gif\":\"5187.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee with a push-up that finishes in a long forward jump. It is a tough full-body conditioning move.\"},{\"id\":\"10182\",\"n\":\"burpee over the dumbbell\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"chest\",\"shoulders\",\"core\",\"glutes\"],\"st\":[\"Stand beside a dumbbell lying on the floor.\",\"Squat down, place your hands on the floor, jump your feet back and do a push up.\",\"Jump your feet forward under your hips.\",\"Jump up and sideways over the dumbbell, landing softly.\",\"Turn and repeat in the other direction at a steady pace.\"],\"img\":\"10182.webp\",\"gif\":\"10182.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee where you jump sideways over a dumbbell each rep, raising the heart rate and working the whole body.\"},{\"id\":\"10193\",\"n\":\"burpee power sled push\",\"bp\":\"full body\",\"eq\":\"sled machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"chest\",\"shoulders\",\"triceps\"],\"st\":[\"Stand behind a loaded sled and drop into a burpee, chest to the floor.\",\"Jump up to your feet explosively.\",\"Grab the sled handles with your arms extended and lean in.\",\"Drive with short, powerful steps to push the sled for a set distance.\",\"Return and repeat, keeping your back flat while pushing.\"],\"img\":\"10193.webp\",\"gif\":\"10193.mp4\",\"cat\":\"cardio\",\"desc\":\"A conditioning move that pairs a burpee with a hard sled push for a tough full body effort.\"},{\"id\":\"5337\",\"n\":\"burpee push up mountain climber complex\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\",\"quadriceps\",\"shoulders\"],\"st\":[\"Stand tall, then drop your hands to the floor and jump your feet back.\",\"Do one push-up.\",\"Run your knees in and out for several mountain climbers.\",\"Jump your feet in toward your hands.\",\"Jump up with arms overhead.\",\"Keep a steady pace and a tight core.\"],\"img\":\"5337.webp\",\"gif\":\"5337.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A conditioning chain of a burpee, a push-up and mountain climbers. Raises your heart rate quickly.\"},{\"id\":\"4548\",\"n\":\"burpee squat\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"chest\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Drop into a squat and place your hands on the floor.\",\"Jump or step your feet back into a plank.\",\"Lower your chest down, then press back up.\",\"Jump your feet forward to your hands.\",\"Stand and finish with a bodyweight squat before the next rep.\"],\"img\":\"4548.webp\",\"gif\":\"4548.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A burpee with a squat finish that raises your heart rate and works the whole body.\"},{\"id\":\"5968\",\"n\":\"burpee twist\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"quadriceps\",\"obliques\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Squat down, place your hands on the floor and jump your feet back to a plank.\",\"Perform a push-up if you like.\",\"Jump your feet forward under your hips.\",\"Explode up, rotating your trunk as you jump, and land softly.\",\"Alternate twist directions each rep.\"],\"img\":\"5968.webp\",\"gif\":\"5968.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A burpee with a trunk rotation on the jump, raising your heart rate while challenging the whole body.\"},{\"id\":\"3457\",\"n\":\"burpee with push up\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"quadriceps\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Squat and place your hands on the floor.\",\"Jump your feet back to a plank.\",\"Do a push-up.\",\"Jump your feet in and leap up.\",\"Repeat at a steady pace.\"],\"img\":\"3457.webp\",\"gif\":\"3457.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee that includes a full push-up for conditioning.\",\"fv\":\"3456\"},{\"id\":\"0145\",\"n\":\"butt bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and your feet flat, hip width apart.\",\"Place your arms at your sides.\",\"Press through your heels and lift your hips toward the ceiling.\",\"Squeeze your glutes at the top.\",\"Lower slowly to the floor.\",\"Keep your ribs down and avoid overarching your back.\"],\"img\":\"0145.webp\",\"gif\":\"0145.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip bridge lifting the buttocks off the floor while lying on your back. It strengthens the glutes and hamstrings.\"},{\"id\":\"3037\",\"n\":\"butt kicks\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"glutes\",\"hip flexors\"],\"st\":[\"Stand tall with your arms bent at your sides.\",\"Jog on the spot or move forward slowly.\",\"Kick each heel up toward your glute.\",\"Stay on the balls of your feet and keep your knees pointing down.\",\"Pump your arms in rhythm.\",\"Continue for 20-40 seconds.\"],\"img\":\"3037.webp\",\"gif\":\"3037.mp4\",\"cat\":\"cardio\",\"desc\":\"A running drill where your heels flick up toward your glutes. It warms up the hamstrings and raises your heart rate.\",\"fv\":\"0146\"},{\"id\":\"11571\",\"n\":\"butt walking\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Sit on the floor with legs straight and arms crossed.\",\"Lean back slightly.\",\"Shift your weight to one side and swing the other hip forward.\",\"Alternate sides to walk forward.\",\"Keep your torso upright.\",\"Walk back to reverse.\"],\"img\":\"11571.webp\",\"gif\":\"11571.mp4\",\"cat\":\"mobility\",\"desc\":\"Sitting on the floor with legs extended, you shuffle forward on your glutes to warm up the hips and work the glutes.\"},{\"id\":\"10194\",\"n\":\"butterfly back roll\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"hamstrings\",\"glutes\"],\"st\":[\"Sit with the soles of your feet together and knees open.\",\"Hold your feet or ankles.\",\"Roll back slowly along your spine.\",\"Roll forward to sit up again.\",\"Repeat smoothly for 8 to 10 reps.\"],\"img\":\"10194.webp\",\"gif\":\"10194.mp4\",\"cat\":\"stretching\",\"desc\":\"Rock back and forth on your spine with legs in a butterfly position. It massages the back and loosens the hips.\"},{\"id\":\"4867\",\"n\":\"butterfly yoga flaps\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hip flexors\"],\"st\":[\"Sit with the soles of your feet together.\",\"Hold your feet.\",\"Gently flap your knees up and down.\",\"Keep your spine tall.\",\"Continue for 30 seconds.\"],\"img\":\"4867.webp\",\"gif\":\"4867.mp4\",\"cat\":\"yoga\",\"desc\":\"Seated butterfly pose with gentle knee flapping. It loosens the inner thighs and hips.\"},{\"id\":\"8878\",\"n\":\"cable 45 degrees reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Set two cable handles at a low or mid height and grab them crossed over.\",\"Hinge forward at the hips to about 45 degrees with a flat back.\",\"Keep a slight bend in your elbows.\",\"Pull the handles out and back in a wide arc until your arms are in line with your torso.\",\"Squeeze your shoulder blades gently at the end.\",\"Return slowly and keep your torso still.\"],\"img\":\"8878.webp\",\"gif\":\"8878.mp4\",\"cat\":\"strength\",\"desc\":\"Hinged forward at about 45 degrees, you pull the cable handles apart in a wide arc. It targets the rear shoulders and upper back.\"},{\"id\":\"9867\",\"n\":\"cable 45 degrees reverse grip reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Stand at a cable station and grab the handles with palms up.\",\"Hinge forward about 45 degrees.\",\"Pull your arms out and back in a wide arc.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"9867.webp\",\"gif\":\"9867.mp4\",\"cat\":\"strength\",\"desc\":\"A cable reverse fly with a palms-up grip, angled at 45 degrees to hit the rear delts and upper back.\"},{\"id\":\"9868\",\"n\":\"cable 45 degrees single arm reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Stand at a cable station and take one handle.\",\"Hinge forward about 45 degrees.\",\"Pull your arm out and back in an arc.\",\"Squeeze your shoulder blade.\",\"Return slowly and switch sides.\"],\"img\":\"9868.webp\",\"gif\":\"9868.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable reverse fly, hinged at 45 degrees to target the rear delt.\"},{\"id\":\"9869\",\"n\":\"cable 45 degrees single arm reverse grip reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Stand at a cable station and take one handle with your palm up.\",\"Hinge forward about 45 degrees.\",\"Pull your arm out and back in an arc.\",\"Squeeze your shoulder blade.\",\"Return slowly and switch sides.\"],\"img\":\"9869.webp\",\"gif\":\"9869.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable reverse fly with a palm-up grip, hinged at 45 degrees.\"},{\"id\":\"10597\",\"n\":\"cable 90 degrees internal rotation catch\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"core\"],\"st\":[\"Set the cable at shoulder height and stand sideways to it.\",\"Raise your upper arm out to the side with the elbow bent 90 degrees.\",\"Let the cable pull your forearm back into external rotation.\",\"Catch it, then rotate the forearm forward and down smoothly.\",\"Keep your upper arm still and level.\",\"Complete the reps, then switch arms.\"],\"img\":\"10597.webp\",\"gif\":\"10597.mp4\",\"cat\":\"strength\",\"desc\":\"A cable drill with the upper arm at shoulder height and elbow bent to 90 degrees. It trains the rotator cuff to catch and control a quick rotation.\"},{\"id\":\"3040\",\"n\":\"cable bar high pulley overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Attach a bar to a high pulley and face away from the machine.\",\"Hold the bar behind your head with elbows pointing forward.\",\"Step forward and stagger your feet.\",\"Extend your arms to press the bar overhead.\",\"Lower slowly back and keep your elbows in place.\"],\"img\":\"3040.webp\",\"gif\":\"3040.mp4\",\"cat\":\"strength\",\"desc\":\"A cable overhead extension from a high pulley that isolates the triceps.\"},{\"id\":\"11256\",\"n\":\"cable bench press v. 3\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench between two low pulleys and hold a handle in each hand at chest level.\",\"Plant your feet and keep your shoulder blades back.\",\"Press the handles up until your arms are straight.\",\"Squeeze your chest at the top.\",\"Lower slowly until you feel a stretch.\"],\"img\":\"11256.webp\",\"gif\":\"11256.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press using cables. The steady tension gives your chest and triceps constant work.\"},{\"id\":\"4578\",\"n\":\"cable bent over neutral grip kickback with rope attachment\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Attach a rope to a low pulley and hold both ends.\",\"Hinge forward at the hips with a flat back.\",\"Keep your upper arms parallel to the floor and close to your sides.\",\"Straighten your elbows and spread the rope slightly at the end.\",\"Squeeze your triceps.\",\"Return slowly to the start.\"],\"img\":\"4578.webp\",\"gif\":\"4578.mp4\",\"cat\":\"strength\",\"desc\":\"A rope kickback with both arms that targets the triceps through full extension.\"},{\"id\":\"3912\",\"n\":\"cable bent over one arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"trapezius\"],\"st\":[\"Stand next to a low pulley and bend forward at the hips with a flat back.\",\"Grab the handle with the far hand.\",\"Raise your arm out to the side with a soft elbow.\",\"Lift to shoulder height.\",\"Lower slowly.\",\"Switch sides after your reps.\"],\"img\":\"3912.webp\",\"gif\":\"3912.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over one-arm cable raise that hits the rear delts.\"},{\"id\":\"4367\",\"n\":\"cable bent over reverse grip row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\",\"lower back\"],\"st\":[\"Stand facing a low cable and hinge forward with a flat back.\",\"Grip the bar with palms up.\",\"Pull the bar toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower slowly.\"],\"img\":\"4367.webp\",\"gif\":\"4367.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a cable using an underhand grip, which emphasizes the lower lats and biceps.\"},{\"id\":\"3859\",\"n\":\"cable bent over row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Attach a handle or bar to a low pulley and grab it.\",\"Step back and hinge at the hips with a flat back and soft knees.\",\"Start with your arms extended toward the pulley.\",\"Pull the handle toward your lower ribs, driving your elbows back.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly until your arms are straight again.\"],\"img\":\"3859.webp\",\"gif\":\"3859.mp4\",\"cat\":\"strength\",\"desc\":\"A hinged row on the cable stack that trains the mid back and lats with steady tension all the way through.\"},{\"id\":\"4011\",\"n\":\"cable bent over row with bar\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\"],\"st\":[\"Face the low pulley and hinge forward holding the bar.\",\"Keep a flat back.\",\"Pull the bar toward your waist.\",\"Squeeze your back.\",\"Extend your arms slowly.\"],\"img\":\"4011.webp\",\"gif\":\"4011.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over row with a cable and straight bar. It builds the lats and mid-back.\"},{\"id\":\"4368\",\"n\":\"cable bent over row with rope attachment\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Attach a rope to a low pulley and hinge forward with a flat back.\",\"Grip the rope with palms facing each other.\",\"Pull the rope toward your lower chest.\",\"Spread the rope as you squeeze your back.\",\"Lower with control.\"],\"img\":\"4368.webp\",\"gif\":\"4368.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a cable rope, allowing a neutral grip and a good squeeze at the end.\"},{\"id\":\"4545\",\"n\":\"cable bent over single arm kickback\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set a low pulley with a single handle and hinge forward at the hips.\",\"Hold the handle with your elbow bent at your side, upper arm parallel to the floor.\",\"Keep your upper arm still and straighten your elbow back.\",\"Squeeze your triceps at full extension.\",\"Return slowly to the start.\",\"Finish your reps, then switch arms.\"],\"img\":\"4545.webp\",\"gif\":\"4545.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable kickback that isolates the triceps with constant tension.\"},{\"id\":\"4567\",\"n\":\"cable bent over single arm neutral grip kickback with rope attachment\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Attach a rope to a low pulley and hold one end with a neutral grip.\",\"Hinge at the hips with a flat back.\",\"Keep your upper arm parallel to the floor and tucked in.\",\"Straighten your elbow and pull the rope back.\",\"Squeeze at the end of the motion.\",\"Lower slowly, then switch arms.\"],\"img\":\"4567.webp\",\"gif\":\"4567.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm rope kickback that works the triceps with steady cable tension.\",\"fv\":\"9724\"},{\"id\":\"11269\",\"n\":\"cable bent over single arm row v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Face a low pulley, hinge forward with a flat back and hold the handle.\",\"Brace your core and keep your hips back.\",\"Row the handle toward your hip.\",\"Squeeze your back at the top.\",\"Lower slowly, finish your reps, then switch arms.\"],\"img\":\"11269.webp\",\"gif\":\"11269.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over one-arm row with a low cable. It builds the lats and mid back with steady tension.\"},{\"id\":\"1607\",\"n\":\"cable biceps curl (sz bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach an SZ bar to a low pulley and grip it with an underhand grip.\",\"Stand tall with your elbows at your sides.\",\"Curl the bar up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly and avoid swinging your body.\"],\"img\":\"1607.webp\",\"gif\":\"1607.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable curl with an SZ bar. The cable keeps constant tension on the biceps.\"},{\"id\":\"1047\",\"n\":\"cable close grip front lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Sit at the pulldown station and secure your thighs under the pads.\",\"Grab the bar with a close grip.\",\"Lean back slightly and pull the bar down to your upper chest.\",\"Drive your elbows down and squeeze your lats.\",\"Let the bar rise slowly until your arms are straight.\"],\"img\":\"1047.webp\",\"gif\":\"1047.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown with a narrow grip, pulling the bar to your upper chest. It trains the lats and biceps.\",\"fv\":\"3754\"},{\"id\":\"1861\",\"n\":\"cable curl with multipurpose v bar\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach a multipurpose V bar to a low pulley and grip it with palms up.\",\"Stand tall with your elbows at your sides.\",\"Curl the bar up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly without letting your elbows drift.\"],\"img\":\"1861.webp\",\"gif\":\"1861.mp4\",\"cat\":\"strength\",\"desc\":\"Standing cable curl using a V bar, giving constant tension on the biceps.\"},{\"id\":\"6742\",\"n\":\"cable donkey diagonal kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Attach an ankle cuff to a low pulley and put it on one ankle.\",\"Get on all fours facing the machine.\",\"Keep your core braced and back flat.\",\"Kick the leg back and slightly out on a diagonal.\",\"Squeeze your glute at the top.\",\"Return slowly, then switch legs after your reps.\"],\"img\":\"6742.webp\",\"gif\":\"6742.mp4\",\"cat\":\"strength\",\"desc\":\"A donkey kickback on a cable that sends the leg back and slightly out. It focuses on the glutes.\"},{\"id\":\"4421\",\"n\":\"cable donkey kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Attach an ankle strap to a low cable and get on all fours facing the machine.\",\"Hook the strap around one ankle.\",\"Keeping the knee bent, drive your heel up toward the ceiling.\",\"Squeeze your glute at the top without arching your back.\",\"Return slowly and repeat, then switch legs.\"],\"img\":\"4421.webp\",\"gif\":\"4421.mp4\",\"cat\":\"strength\",\"desc\":\"Kicking one leg back from a hands-and-knees position against cable resistance. It isolates the glutes.\"},{\"id\":\"1046\",\"n\":\"cable elevated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Set a cable handle at about head height and take a stable stance.\",\"Grab the handle and lean back slightly with arms extended.\",\"Pull toward your upper chest, driving your elbows back.\",\"Squeeze your shoulder blades together.\",\"Return slowly until your arms are straight.\"],\"img\":\"1046.webp\",\"gif\":\"1046.mp4\",\"cat\":\"strength\",\"desc\":\"A cable row where the handle sits higher than usual, pulled toward your upper chest. It targets the upper back.\"},{\"id\":\"11060\",\"n\":\"cable face pull with external rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"rhomboids\",\"trapezius\"],\"st\":[\"Set a rope at upper chest height and hold it with both hands, arms extended.\",\"Pull the rope toward your face with elbows high.\",\"At the end, rotate your fists upward so your hands finish above your elbows.\",\"Squeeze your rear shoulders for a second.\",\"Reverse the rotation and return slowly.\"],\"img\":\"11060.webp\",\"gif\":\"11060.mp4\",\"cat\":\"strength\",\"desc\":\"A face pull that finishes with a rotation of the arms. It hits the rear shoulders and rotator cuff for healthy shoulders.\"},{\"id\":\"3868\",\"n\":\"cable fly with chest supported\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Set the pulleys at about shoulder height and position an incline bench facing the stack, chest against the pad.\",\"Hold a handle in each hand with arms out to the sides.\",\"With a slight bend in your elbows, sweep your arms forward in a wide arc.\",\"Squeeze your chest as the handles meet.\",\"Return slowly until you feel a stretch across the chest.\"],\"img\":\"3868.webp\",\"gif\":\"3868.mp4\",\"cat\":\"strength\",\"desc\":\"A cable fly with your chest against a bench, which isolates the pecs with steady tension.\"},{\"id\":\"8881\",\"n\":\"cable forearm pronation\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit beside a low cable and hold the handle with your forearm resting on your thigh.\",\"Start with your palm facing up and your wrist neutral.\",\"Rotate your forearm so the palm turns down.\",\"Pause, then rotate back slowly against the cable.\",\"Keep your elbow still and move only the forearm.\",\"Complete your reps and switch arms.\"],\"img\":\"8881.webp\",\"gif\":\"8881.mp4\",\"cat\":\"strength\",\"desc\":\"You rotate the forearm so the palm turns down against cable resistance. It strengthens the pronator muscles of the forearm.\"},{\"id\":\"3356\",\"n\":\"cable forward lunge\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a low cable handle at your chest and stand facing away from the stack.\",\"Take a big step forward.\",\"Drop your back knee toward the floor.\",\"Keep your front knee stable over the ankle.\",\"Push back to the start and switch legs.\"],\"img\":\"3356.webp\",\"gif\":\"3356.mp4\",\"cat\":\"strength\",\"desc\":\"A forward stepping lunge with cable tension, working quads and glutes.\"},{\"id\":\"6543\",\"n\":\"cable front raise (rope attachment)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Attach a rope to a low pulley and face away from the machine.\",\"Hold the rope ends and let your arms hang with the cable between your legs.\",\"Raise your arms forward to shoulder height with soft elbows.\",\"Pause briefly at the top.\",\"Lower slowly without letting the stack rest.\",\"Keep your torso still, no swinging.\"],\"img\":\"6543.webp\",\"gif\":\"6543.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise using a rope on a low cable. The cable keeps tension on the front shoulder through the whole lift.\"},{\"id\":\"2515\",\"n\":\"cable front raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand facing away from a low pulley, holding the handle in front of your thighs.\",\"Keep a slight bend in your elbow.\",\"Raise your arm forward to shoulder height.\",\"Avoid leaning back.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"2515.webp\",\"gif\":\"2515.mp4\",\"cat\":\"strength\",\"desc\":\"A cable raise to the front that works the front of the shoulders.\"},{\"id\":\"0163\",\"n\":\"cable front seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Sit at a cable row station with your feet on the platform and your knees slightly bent.\",\"Grab the handle with both hands and sit tall.\",\"Pull the handle toward your lower ribs, squeezing your shoulder blades together.\",\"Pause briefly at the end.\",\"Return slowly until your arms are straight.\",\"Keep your chest up and avoid rocking back.\"],\"img\":\"0163.webp\",\"gif\":\"0163.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row facing a cable stack. It builds the mid back and lats with smooth constant tension.\"},{\"id\":\"3349\",\"n\":\"cable front squat\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\"],\"st\":[\"Set the cable low and hold the handle at your chest.\",\"Step back to create tension and stand with feet shoulder width apart.\",\"Sit down and back into a squat with your chest tall.\",\"Descend until your thighs are parallel.\",\"Drive up through your heels.\"],\"img\":\"3349.webp\",\"gif\":\"3349.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a cable held at your chest, keeping you upright while the quads and glutes work.\"},{\"id\":\"3354\",\"n\":\"cable front squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\"],\"st\":[\"Set the cable low and hold the handle against your chest.\",\"Stand with feet shoulder width apart.\",\"Sit down into a deep squat, chest tall.\",\"Keep your knees tracking over your toes.\",\"Press through your heels back to standing.\"],\"img\":\"3354.webp\",\"gif\":\"3354.mp4\",\"cat\":\"strength\",\"desc\":\"A second take on the cable front squat, holding the handle at your chest to stay upright and hit the quads.\"},{\"id\":\"7578\",\"n\":\"cable front squat with v bar\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\"],\"st\":[\"Hold a V bar at chest height.\",\"Stand a step back from the cable.\",\"Squat down with your elbows up.\",\"Keep your chest tall.\",\"Stand up.\"],\"img\":\"7578.webp\",\"gif\":\"7578.mp4\",\"cat\":\"strength\",\"desc\":\"Front squat holding a V bar on a low cable.\"},{\"id\":\"5315\",\"n\":\"cable glute dominant step up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold the cable handle and stand facing a step.\",\"Place one foot on the step.\",\"Lean slightly forward from the hips.\",\"Drive through the heel to stand up.\",\"Lower slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"5315.webp\",\"gif\":\"5315.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with a cable that is set to put more work on the glutes. It builds strength in the hips.\"},{\"id\":\"6544\",\"n\":\"cable goblet squat\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\"],\"st\":[\"Attach a handle or rope to a low pulley and hold it against your chest.\",\"Step back until there is tension and set your feet shoulder-width apart.\",\"Sit your hips down and back, keeping your chest tall.\",\"Lower until your thighs are about parallel to the floor.\",\"Push through your feet to stand up.\",\"Keep your elbows pointing down throughout.\"],\"img\":\"6544.webp\",\"gif\":\"6544.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a low cable at your chest. The front load helps you stay upright and drives the thighs and glutes.\"},{\"id\":\"4196\",\"n\":\"cable half kneeling adductor pallof press\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"obliques\",\"core\"],\"st\":[\"Kneel on one knee with the cable at chest height.\",\"Hold the handle at your chest.\",\"Press it forward.\",\"Squeeze your inner thigh.\",\"Return.\",\"Switch sides.\"],\"img\":\"4196.webp\",\"gif\":\"4196.mp4\",\"cat\":\"strength\",\"desc\":\"A pallof press with the inner thigh engaged.\"},{\"id\":\"4194\",\"n\":\"cable half kneeling external rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Kneel on one knee beside a cable at elbow height.\",\"Hold the handle with elbow at your side.\",\"Rotate your forearm outward.\",\"Pause.\",\"Return slowly.\",\"Switch sides.\"],\"img\":\"4194.webp\",\"gif\":\"4194.mp4\",\"cat\":\"strength\",\"desc\":\"A rotator cuff exercise in a half kneeling stance.\"},{\"id\":\"8879\",\"n\":\"cable half kneeling external rotation press\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"core\",\"triceps\"],\"st\":[\"Kneel on one knee side-on to the cable with the handle at chest height.\",\"Hold the handle near your shoulder with your elbow bent.\",\"Brace your core and keep your hips square.\",\"Rotate your forearm outward, then press the handle overhead.\",\"Return along the same path with control.\",\"Finish your reps and switch sides.\"],\"img\":\"8879.webp\",\"gif\":\"8879.mp4\",\"cat\":\"strength\",\"desc\":\"From a half kneeling stance you rotate the arm outward and press the cable overhead. It trains shoulder stability along with the press.\"},{\"id\":\"7743\",\"n\":\"cable half kneeling face pull\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\",\"core\"],\"st\":[\"Set a rope at head height and half kneel facing the stack.\",\"Hold the rope ends with your palms facing in.\",\"Pull the rope toward your face, elbows high and wide.\",\"Squeeze your shoulder blades together.\",\"Return slowly. Switch the leading knee after your set.\"],\"img\":\"7743.webp\",\"gif\":\"7743.mp4\",\"cat\":\"strength\",\"desc\":\"A face pull from a half-kneeling stance. The stable position keeps the focus on your rear delts and upper back.\"},{\"id\":\"4193\",\"n\":\"cable half kneeling pallof press\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Kneel on one knee side on to a cable at chest height.\",\"Hold the handle at your chest.\",\"Press it straight out.\",\"Resist the twist.\",\"Bring it back.\",\"Switch sides.\"],\"img\":\"4193.webp\",\"gif\":\"4193.mp4\",\"cat\":\"strength\",\"desc\":\"Press a cable away from your chest while kneeling on one knee. It trains anti rotation.\",\"fv\":\"10441\"},{\"id\":\"4228\",\"n\":\"cable half kneeling push pull\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"upper back\",\"core\"],\"st\":[\"Kneel on one knee between two cable stations, holding a handle in each hand.\",\"Keep your torso tall and your core braced.\",\"Press one handle forward while pulling the other toward your ribs.\",\"Return to the start under control.\",\"Do not let your torso twist.\",\"Switch your kneeling leg after a set.\"],\"img\":\"4228.webp\",\"gif\":\"4228.mp4\",\"cat\":\"strength\",\"desc\":\"From a half kneeling stance you press one handle forward and pull another back at the same time. It challenges core stability and coordination.\"},{\"id\":\"8299\",\"n\":\"cable half kneeling single arm row v. 2\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"core\",\"rhomboids\"],\"st\":[\"Half kneel facing the cable with the handle in one hand.\",\"Keep your torso tall.\",\"Row your elbow back past your ribs.\",\"Squeeze your shoulder blade.\",\"Return slowly and switch sides.\"],\"img\":\"8299.webp\",\"gif\":\"8299.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row from a half-kneeling stance. It works the lats and challenges your core stability.\"},{\"id\":\"0166\",\"n\":\"cable hammer curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach a rope or handle to a low pulley and hold it with palms facing each other.\",\"Stand tall with your elbows at your sides.\",\"Curl the handles up toward your shoulders.\",\"Squeeze at the top.\",\"Lower slowly until your arms are straight.\",\"Keep your upper arms still and avoid swinging.\"],\"img\":\"0166.webp\",\"gif\":\"0166.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer-grip curl using a low cable. The neutral grip works the biceps and the forearm muscles together.\"},{\"id\":\"2887\",\"n\":\"cable hanging leg raise\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"forearms\",\"grip muscles\"],\"st\":[\"Hang from a pull-up bar with the cable attached to your ankles.\",\"Keep your arms straight and your body steady.\",\"Raise your legs up in front of you toward hip height or higher.\",\"Curl your pelvis slightly at the top.\",\"Lower slowly without swinging.\"],\"img\":\"2887.webp\",\"gif\":\"2887.mp4\",\"cat\":\"strength\",\"desc\":\"A hanging leg raise with cable resistance at your feet. Strengthens the abs and hip flexors.\",\"fv\":\"2886\"},{\"id\":\"6648\",\"n\":\"cable high pull with rope attachment\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"trapezius\",\"biceps\"],\"st\":[\"Attach a rope to a high pulley and grip an end in each hand.\",\"Step back until the cable is taut, with a slight lean back.\",\"Pull the rope toward your face, elbows flaring high.\",\"Squeeze your shoulder blades together at the end.\",\"Let the rope return slowly to the start.\"],\"img\":\"6648.webp\",\"gif\":\"6648.mp4\",\"cat\":\"strength\",\"desc\":\"A rope pull toward the face from a high pulley. It builds the rear delts and upper back.\"},{\"id\":\"5874\",\"n\":\"cable high pulley straight bar overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Attach a straight bar to a high pulley and face away from it.\",\"Hold the bar behind your head with elbows bent.\",\"Keep your elbows pointing forward.\",\"Extend your arms forward and up.\",\"Return slowly.\"],\"img\":\"5874.webp\",\"gif\":\"5874.mp4\",\"cat\":\"strength\",\"desc\":\"Face away from a high pulley and extend your arms overhead holding a straight bar. It isolates the triceps.\"},{\"id\":\"7597\",\"n\":\"cable high row with chest support\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\",\"rhomboids\"],\"st\":[\"Set the cable high and lean your chest against the support pad.\",\"Grab the handles and extend your arms.\",\"Pull your elbows back and slightly down.\",\"Squeeze your shoulder blades together at the end.\",\"Let your arms extend slowly to the start.\"],\"img\":\"7597.webp\",\"gif\":\"7597.mp4\",\"cat\":\"strength\",\"desc\":\"A two-handed cable row from a high pulley with your chest braced on a pad. It trains the upper back and rear shoulders.\"},{\"id\":\"4960\",\"n\":\"cable high triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set the cable high and face it.\",\"Hold the attachment with elbows bent.\",\"Press down by extending your elbows.\",\"Squeeze at the bottom.\",\"Return slowly.\",\"Keep your elbows near your sides.\"],\"img\":\"4960.webp\",\"gif\":\"4960.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension performed from a high cable position. It builds the triceps.\"},{\"id\":\"2756\",\"n\":\"cable hip abduction (toe in)\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Attach an ankle cuff to a low cable and stand side-on to the stack.\",\"Hold a support for balance.\",\"Turn your toes inward slightly.\",\"Lift the working leg out to the side.\",\"Return slowly, then switch legs.\"],\"img\":\"2756.webp\",\"gif\":\"2756.mp4\",\"cat\":\"strength\",\"desc\":\"A cable leg raise to the side with the toes turned in, shifting the work toward the outer glute.\"},{\"id\":\"2755\",\"n\":\"cable hip abduction (toe out)\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Attach an ankle cuff to a low cable and stand side-on to the stack.\",\"Hold a support for balance.\",\"Turn your toes out slightly.\",\"Lift the working leg out to the side.\",\"Return slowly, then switch legs.\"],\"img\":\"2755.webp\",\"gif\":\"2755.mp4\",\"cat\":\"strength\",\"desc\":\"A cable leg raise to the side with the toes turned out, targeting the outer hip.\"},{\"id\":\"3048\",\"n\":\"cable hip abduction v. 2\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Attach an ankle cuff to a low pulley and strap it to your outer ankle.\",\"Stand sideways to the machine and hold a support.\",\"Keep your torso upright and your standing leg slightly bent.\",\"Lift the cuffed leg out to the side.\",\"Pause at the top, then lower slowly.\",\"Finish your reps and switch legs.\"],\"img\":\"3048.webp\",\"gif\":\"3048.mp4\",\"cat\":\"strength\",\"desc\":\"Standing hip abduction against a low cable that trains the outer hip and glutes.\",\"fv\":\"0879\"},{\"id\":\"1202\",\"n\":\"cable horizontal pallof press\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Set a cable at chest height and stand sideways to the stack.\",\"Hold the handle at your chest with both hands and brace your core.\",\"Press the handle straight out until your arms are extended.\",\"Hold for a second without letting your torso twist.\",\"Bring it back to your chest and finish the set, then switch sides.\"],\"img\":\"1202.webp\",\"gif\":\"1202.mp4\",\"cat\":\"isometric\",\"desc\":\"Pressing a cable straight out from your chest while resisting the pull to rotate. It trains anti-rotation core strength.\",\"fv\":\"8043\"},{\"id\":\"4356\",\"n\":\"cable horizontal pallof press v. 2\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Stand sideways to a cable set at chest height, hands holding the handle at your chest.\",\"Step away to load the cable and brace your core.\",\"Press the handle straight out in front of you.\",\"Hold for a second without rotating.\",\"Bring it back to your chest, then switch sides.\"],\"img\":\"4356.webp\",\"gif\":\"4356.mp4\",\"cat\":\"isometric\",\"desc\":\"An anti-rotation press where you push a cable straight out and resist the twist. Great for core stability.\"},{\"id\":\"11264\",\"n\":\"cable incline bench press v. 3\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Set an incline bench between two low pulleys and hold a handle in each hand.\",\"Plant your feet and pull your shoulder blades back.\",\"Press the handles up and slightly together.\",\"Squeeze your upper chest at the top.\",\"Lower slowly to a comfortable stretch.\"],\"img\":\"11264.webp\",\"gif\":\"11264.mp4\",\"cat\":\"strength\",\"desc\":\"A cable press on an incline bench. It shifts the work toward the upper chest with constant tension.\"},{\"id\":\"5703\",\"n\":\"cable incline biceps curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Set a low cable and lie back on an incline bench facing away from the stack.\",\"Hold the handles with your arms hanging behind you.\",\"Curl the handles up toward your shoulders.\",\"Keep your elbows back and still.\",\"Lower slowly until your arms are straight.\"],\"img\":\"5703.webp\",\"gif\":\"5703.mp4\",\"cat\":\"strength\",\"desc\":\"A cable curl done leaning back on an incline bench. The arms hang behind the body, which stretches the biceps at the start.\"},{\"id\":\"4345\",\"n\":\"cable incline close grip curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lean back on an incline bench in front of a low cable with a straight bar.\",\"Grip the bar close together with palms up.\",\"Curl the bar toward your shoulders, upper arms still.\",\"Squeeze at the top.\",\"Lower slowly until your arms are nearly straight.\"],\"img\":\"4345.webp\",\"gif\":\"4345.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl on an incline bench with a cable and a narrow grip. It keeps constant tension and a deep stretch.\"},{\"id\":\"8662\",\"n\":\"cable incline close grip shoulder press with v bar\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Sit on an incline bench with a cable and V bar anchored low behind you.\",\"Hold the bar at chest height with a narrow grip.\",\"Press upward until your arms are straight.\",\"Lower back to the chest slowly.\",\"Keep your back against the pad.\"],\"img\":\"8662.webp\",\"gif\":\"8662.mp4\",\"cat\":\"strength\",\"desc\":\"A close-grip incline cable press using a V bar that trains the shoulders and triceps.\"},{\"id\":\"4012\",\"n\":\"cable incline cross rear fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\"],\"st\":[\"Lie chest down on an incline bench between two cables, holding opposite handles.\",\"Keep elbows slightly bent.\",\"Pull your arms out and back.\",\"Pause.\",\"Return slowly.\"],\"img\":\"4012.webp\",\"gif\":\"4012.mp4\",\"cat\":\"strength\",\"desc\":\"A rear fly using crossed cables on an incline bench. It targets the rear delts.\"},{\"id\":\"7592\",\"n\":\"cable incline rear delt fly with back support\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie chest down on an incline bench between two cable stations.\",\"Grab the opposite handles, arms hanging with a slight bend.\",\"Raise your arms out to the sides until they reach shoulder level.\",\"Pause and squeeze your rear delts.\",\"Lower slowly without swinging.\"],\"img\":\"7592.webp\",\"gif\":\"7592.mp4\",\"cat\":\"strength\",\"desc\":\"A rear delt fly with cables while your chest rests on an incline bench. It isolates the back of the shoulders.\"},{\"id\":\"9870\",\"n\":\"cable incline single arm y raise with back support\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie face down on an incline bench with a cable handle in one hand.\",\"Let your arm hang down.\",\"Raise it up and out in a Y shape.\",\"Pause with your thumb up.\",\"Lower slowly, then switch arms.\"],\"img\":\"9870.webp\",\"gif\":\"9870.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm Y raise while supported on an incline bench, working the shoulders and upper back.\"},{\"id\":\"9871\",\"n\":\"cable incline single arm y raise wrist straps with back support\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie face down on an incline bench with the strap on one wrist.\",\"Let your arm hang down.\",\"Raise it up and out in a Y shape.\",\"Pause at the top.\",\"Lower slowly, then switch arms.\"],\"img\":\"9871.webp\",\"gif\":\"9871.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm cable Y raise using wrist straps, so your grip does not limit the shoulder work.\"},{\"id\":\"4351\",\"n\":\"cable incline skull crusher\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Set an incline bench facing away from a low cable and hold the bar overhead.\",\"Keep your upper arms still.\",\"Bend your elbows and lower the bar toward your forehead.\",\"Extend your arms to return.\",\"Keep your elbows from flaring.\"],\"img\":\"4351.webp\",\"gif\":\"4351.mp4\",\"cat\":\"strength\",\"desc\":\"A skull crusher on an incline bench with cable resistance, giving steady tension on the triceps.\"},{\"id\":\"8661\",\"n\":\"cable incline y raise with back support\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rear deltoids\",\"upper back\"],\"st\":[\"Lie chest-down on an incline bench with a cable handle in each hand.\",\"Keep your neck neutral.\",\"Raise your arms forward and up in a Y shape.\",\"Pause at the top.\",\"Lower slowly with straight arms.\"],\"img\":\"8661.webp\",\"gif\":\"8661.mp4\",\"cat\":\"strength\",\"desc\":\"A Y-shaped raise with cables while supported on an incline bench, working the shoulders and upper back.\"},{\"id\":\"8663\",\"n\":\"cable incline y raise wrist straps with back support\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rear deltoids\",\"upper back\"],\"st\":[\"Fasten the wrist straps to the cables and lie chest-down on an incline bench.\",\"Keep your neck neutral.\",\"Raise your arms forward and up into a Y shape.\",\"Squeeze your shoulders at the top.\",\"Lower slowly.\"],\"img\":\"8663.webp\",\"gif\":\"8663.mp4\",\"cat\":\"strength\",\"desc\":\"A cable Y raise using wrist straps to reduce grip demand, supported on an incline bench.\"},{\"id\":\"7586\",\"n\":\"cable ipsilateral glute dominant step up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand in front of a box with a cable handle in the hand on your working side.\",\"Place one foot fully on the box.\",\"Lean your torso forward slightly.\",\"Drive through the heel to stand up.\",\"Lower slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"7586.webp\",\"gif\":\"7586.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with a cable held on the same side as the working leg, leaning forward to bias the glutes.\"},{\"id\":\"5120\",\"n\":\"cable kickback v. 2\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Attach an ankle strap to a low cable and hold the machine for support.\",\"Stand tall with a slight bend in the standing knee.\",\"Kick your working leg straight back.\",\"Squeeze your glute at the top without arching your back.\",\"Return slowly and switch legs after your reps.\"],\"img\":\"5120.webp\",\"gif\":\"5120.mp4\",\"cat\":\"strength\",\"desc\":\"Kick one leg straight back against a cable with an ankle strap. It isolates the glutes.\"},{\"id\":\"1068\",\"n\":\"cable kickback v. 3\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Hinge forward and hold a handle with elbow bent.\",\"Keep your upper arm parallel to the floor.\",\"Extend your arm back.\",\"Squeeze the triceps.\",\"Return slowly and switch sides.\"],\"img\":\"1068.webp\",\"gif\":\"1068.mp4\",\"cat\":\"strength\",\"desc\":\"Extend your arm back against cable resistance. It isolates the triceps.\"},{\"id\":\"5741\",\"n\":\"cable kneeling crunch v. 2\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower abs\",\"hip flexors\"],\"st\":[\"Kneel below a high cable with the rope held beside your head.\",\"Keep your hips still and your back slightly rounded.\",\"Crunch down, bringing your elbows toward your knees.\",\"Squeeze your abs at the bottom.\",\"Return slowly to the start without sitting back on your heels.\"],\"img\":\"5741.webp\",\"gif\":\"5741.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable crunch that curls the spine toward the hips. It loads the abs against steady resistance.\"},{\"id\":\"11270\",\"n\":\"cable kneeling crunch v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"obliques\",\"core\"],\"st\":[\"Kneel under a high pulley and hold the rope beside your head.\",\"Keep your hips still.\",\"Curl your torso down, bringing elbows toward your knees.\",\"Squeeze your abs at the bottom.\",\"Return slowly to the upright start.\"],\"img\":\"11270.webp\",\"gif\":\"11270.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable crunch that loads the abs. You curl your spine to bring your elbows toward your knees.\"},{\"id\":\"7589\",\"n\":\"cable kneeling glute kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Attach an ankle cuff to a low cable and kneel on hands and knees facing it.\",\"Brace your core and keep your back flat.\",\"Kick the cuffed leg back and up.\",\"Squeeze at the top.\",\"Return slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"7589.webp\",\"gif\":\"7589.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable kickback that isolates the glutes.\"},{\"id\":\"7584\",\"n\":\"cable kneeling high low anti rotation chop\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Kneel side-on to a high cable and hold the handle with both hands.\",\"Brace your core and keep your hips square.\",\"Chop the handle diagonally down across your body, arms mostly straight.\",\"Do not let your torso rotate; the arms and shoulders do the travel.\",\"Return slowly under control, finish your reps, then switch sides.\"],\"img\":\"7584.webp\",\"gif\":\"7584.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable chop that moves from high to low while your torso resists twisting. It trains the deep core and obliques to stay stable.\"},{\"id\":\"6542\",\"n\":\"cable kneeling high to low fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set the cables high and kneel between them, holding a handle in each hand.\",\"Keep a slight bend in your elbows.\",\"Sweep your arms down and together in front of your hips.\",\"Squeeze your chest at the bottom.\",\"Return slowly and repeat.\"],\"img\":\"6542.webp\",\"gif\":\"6542.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable fly pulling from high to low across your body, working the lower chest.\"},{\"id\":\"6739\",\"n\":\"cable kneeling hip abduction\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Attach an ankle cuff to a low pulley and put it on one ankle.\",\"Kneel on all fours with the cuffed leg on the outside.\",\"Keep your back flat and hips square.\",\"Lift the knee out to the side against the cable.\",\"Pause briefly at the top.\",\"Lower with control, then switch legs after your reps.\"],\"img\":\"6739.webp\",\"gif\":\"6739.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable move that lifts the leg out to the side. It targets the outer hip muscles.\"},{\"id\":\"5518\",\"n\":\"cable kneeling leaning forward one arm row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Kneel facing a low cable with a handle in one hand.\",\"Lean your torso forward and brace your core.\",\"Pull your elbow back toward your hip.\",\"Squeeze your shoulder blade, then return slowly.\",\"Finish reps and switch sides.\"],\"img\":\"5518.webp\",\"gif\":\"5518.mp4\",\"cat\":\"strength\",\"desc\":\"One-arm cable row from a kneeling position, leaning forward to give a long pull for the lats and mid back.\"},{\"id\":\"11260\",\"n\":\"cable kneeling military press v. 3\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel between two low pulleys and hold the handles at shoulder height.\",\"Squeeze your glutes and brace your abs.\",\"Press both handles straight overhead.\",\"Lock out without leaning back.\",\"Lower under control to your shoulders.\"],\"img\":\"11260.webp\",\"gif\":\"11260.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling overhead press with cables. The position keeps your legs out of it, so the shoulders do the work.\"},{\"id\":\"4948\",\"n\":\"cable kneeling one arm lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Kneel facing the cable stack and grab the handle with one hand.\",\"Sit tall with your chest up.\",\"Pull the handle down toward your shoulder.\",\"Squeeze your lat at the bottom.\",\"Let the arm rise back up slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"4948.webp\",\"gif\":\"4948.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm lat pulldown from a kneeling position. It builds the lats and tests your core control.\"},{\"id\":\"5369\",\"n\":\"cable kneeling one arm row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"core\"],\"st\":[\"Kneel facing the cable stack and grab the handle with one hand.\",\"Keep your torso upright and core braced.\",\"Pull your elbow back toward your hip.\",\"Squeeze your shoulder blade at the end.\",\"Return slowly to the start.\",\"Finish your reps, then switch sides.\"],\"img\":\"5369.webp\",\"gif\":\"5369.mp4\",\"cat\":\"strength\",\"desc\":\"Row a cable handle with one arm from a kneeling position. Builds the lats and mid back.\"},{\"id\":\"5297\",\"n\":\"cable kneeling preacher curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Kneel in front of a bench with a low cable beside you.\",\"Rest your upper arms on the pad.\",\"Curl the handle up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"5297.webp\",\"gif\":\"5297.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling curl with the arms propped on a bench and a cable. It isolates the biceps.\"},{\"id\":\"3352\",\"n\":\"cable kneeling pull through\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Kneel facing away from a low cable with a rope held between your legs.\",\"Sit your hips back with a flat back.\",\"Let the rope pull your hands back between your knees.\",\"Drive your hips forward to a tall kneeling position.\",\"Squeeze your glutes at the top and repeat.\"],\"img\":\"3352.webp\",\"gif\":\"3352.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling hip hinge with a cable pulled between your legs. It teaches the hinge and trains glutes with little spinal load.\"},{\"id\":\"11253\",\"n\":\"cable kneeling pulldown v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\",\"core\"],\"st\":[\"Kneel facing a high pulley and hold the bar or handles with arms extended.\",\"Sit tall with your core braced.\",\"Pull the handle down toward your chest, driving your elbows down.\",\"Squeeze your lats at the bottom.\",\"Let the handle rise back slowly to a full stretch.\"],\"img\":\"11253.webp\",\"gif\":\"11253.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm style pulldown from a kneeling position. It targets the lats without help from your legs.\"},{\"id\":\"5821\",\"n\":\"cable kneeling shoulder 90 degrees external rotation press\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"triceps\",\"core\",\"rear deltoids\"],\"st\":[\"Kneel next to a cable with your elbow at shoulder height and bent 90 degrees.\",\"Hold the handle and brace your core.\",\"Rotate your forearm upward until it points to the ceiling.\",\"Press the handle overhead.\",\"Reverse the movement slowly and switch sides.\"],\"img\":\"5821.webp\",\"gif\":\"5821.mp4\",\"cat\":\"strength\",\"desc\":\"From a kneeling position, rotate your forearm up and then press overhead on a cable. It trains shoulder rotation and stability.\"},{\"id\":\"6755\",\"n\":\"cable kneeling shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Kneel side-on to a low cable and hold the handle with the far hand.\",\"Tuck your elbow at your side, bent to 90 degrees.\",\"Rotate your forearm outward, away from your belly.\",\"Pause briefly at the end.\",\"Return slowly and switch arms after your reps.\"],\"img\":\"6755.webp\",\"gif\":\"6755.mp4\",\"cat\":\"strength\",\"desc\":\"A light rotation drill with a cable that turns the arm outward. It strengthens the rotator cuff.\"},{\"id\":\"6756\",\"n\":\"cable kneeling shoulder internal rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Kneel side-on to a low cable and hold the handle with the near hand.\",\"Tuck your elbow at your side, bent to 90 degrees.\",\"Rotate your forearm inward across your belly.\",\"Pause briefly at the end.\",\"Return slowly and switch arms after your reps.\"],\"img\":\"6756.webp\",\"gif\":\"6756.mp4\",\"cat\":\"strength\",\"desc\":\"A light rotation drill with a cable that turns the arm inward. It builds rotator cuff strength and shoulder stability.\"},{\"id\":\"4010\",\"n\":\"cable kneeling shoulder press\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\"],\"st\":[\"Kneel in front of a low cable and hold the handles at shoulder height.\",\"Brace your abs.\",\"Press the handles overhead.\",\"Lower under control.\",\"Keep your hips tall.\"],\"img\":\"4010.webp\",\"gif\":\"4010.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead cable press from a kneeling position. It builds the shoulders and demands core stability.\"},{\"id\":\"6693\",\"n\":\"cable kneeling side crunch\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Attach a rope to a high pulley and kneel beside the stack.\",\"Hold the rope at the side of your head.\",\"Crunch sideways, bringing your elbow toward your hip.\",\"Pause and squeeze your side.\",\"Return slowly, then switch sides after your reps.\"],\"img\":\"6693.webp\",\"gif\":\"6693.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling crunch to the side against a high cable. It targets the obliques with steady resistance.\"},{\"id\":\"10667\",\"n\":\"cable kneeling single arm horizontal row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"core\"],\"st\":[\"Set a cable at chest height and kneel facing it.\",\"Hold the handle with one hand and brace your core.\",\"Pull your elbow back along your side.\",\"Squeeze your shoulder blade toward your spine.\",\"Extend the arm slowly.\",\"Complete the reps, then switch arms.\"],\"img\":\"10667.webp\",\"gif\":\"10667.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row from a kneeling position. Kneeling removes leg drive so your back does the pulling.\"},{\"id\":\"5581\",\"n\":\"cable kneeling single lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Kneel facing a high cable with a single handle in one hand.\",\"Reach up to a full stretch.\",\"Pull your elbow down toward your hip.\",\"Squeeze your lat at the bottom.\",\"Return slowly and switch sides.\"],\"img\":\"5581.webp\",\"gif\":\"5581.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling one-arm lat pulldown for a stretch and strong contraction on each side.\"},{\"id\":\"1859\",\"n\":\"cable kneeling triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Attach a rope or bar to a high pulley and kneel facing away.\",\"Hold it overhead with your elbows bent behind your head.\",\"Keep your upper arms still and straighten your elbows.\",\"Squeeze your triceps at full extension.\",\"Return slowly to the start.\"],\"img\":\"1859.webp\",\"gif\":\"1859.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling cable extension that isolates the triceps by pushing the handle down from head height.\"},{\"id\":\"6760\",\"n\":\"cable kneeling twist\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Set a cable at chest height and kneel sideways to it.\",\"Hold the handle with both hands in front of your chest.\",\"Brace your abs and keep your hips square.\",\"Rotate your torso away from the machine.\",\"Return slowly under control.\",\"Finish the reps, then switch sides.\"],\"img\":\"6760.webp\",\"gif\":\"6760.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling trunk rotation on a cable. It trains the obliques while the base stays stable.\"},{\"id\":\"11251\",\"n\":\"cable kneeling woodchop v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Set the cable high, kneel side-on to it and hold the handle with both hands.\",\"Keep your hips square and your core tight.\",\"Pull the handle diagonally across your body down toward the opposite hip.\",\"Rotate through your torso, not your arms.\",\"Return slowly, finish your reps, then switch sides.\"],\"img\":\"11251.webp\",\"gif\":\"11251.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable chop that works your obliques and core with a diagonal pull.\"},{\"id\":\"3350\",\"n\":\"cable lateral lunge\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a low cable handle at your chest and stand sideways to the stack.\",\"Step wide to one side and sit back into that hip.\",\"Keep the other leg straight and feet flat.\",\"Push off your bent leg to return to center.\",\"Complete the reps, then switch sides.\"],\"img\":\"3350.webp\",\"gif\":\"3350.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways lunge against cable tension, training glutes, inner thighs and side to side strength.\"},{\"id\":\"3355\",\"n\":\"cable lateral lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a cable handle at chest height, standing sideways to the stack.\",\"Step wide to the side and bend that knee.\",\"Push your hips back and keep your chest up.\",\"Push off the bent leg to return.\",\"Finish your reps, then switch sides.\"],\"img\":\"3355.webp\",\"gif\":\"3355.mp4\",\"cat\":\"strength\",\"desc\":\"A second variation of the cable side lunge for the glutes and inner thighs.\"},{\"id\":\"11255\",\"n\":\"cable lateral lunge v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Stand side-on to a low pulley and hold the handle at your chest.\",\"Step wide to the side and sit your hips back.\",\"Keep the other leg straight and your chest up.\",\"Push through the bent leg to return to standing.\",\"Finish your reps, then switch sides.\"],\"img\":\"11255.webp\",\"gif\":\"11255.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge with cable resistance. It builds strength in your hips and thighs through a sideways step.\"},{\"id\":\"6392\",\"n\":\"cable lateral pulldown with mag grip\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit at the pulldown station and grab the grip overhead.\",\"Lean back slightly and lift your chest.\",\"Pull the grip down to your upper chest, driving your elbows down.\",\"Squeeze your lats at the bottom.\",\"Let the bar rise slowly to a full stretch and repeat.\"],\"img\":\"6392.webp\",\"gif\":\"6392.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown using a magnetic grip handle that builds the wide muscles of your back.\"},{\"id\":\"10119\",\"n\":\"cable lateral step up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand sideways to a box with the cable handle held at your chest.\",\"Place the near foot on the box and press through that heel.\",\"Step up until your leg is straight and stand tall on top.\",\"Lower slowly back to the floor with control.\",\"Do all reps on one side, then turn around and switch.\"],\"img\":\"10119.webp\",\"gif\":\"10119.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways step up against cable tension that works the glutes and thighs and challenges balance.\"},{\"id\":\"3880\",\"n\":\"cable leaning lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand sideways to a low pulley and hold the handle with the far hand.\",\"Hold the upright support with the other hand and lean away from the machine.\",\"Start with your working arm across your body.\",\"Raise it out to shoulder height with a soft elbow.\",\"Lower slowly under control.\",\"Finish your reps, then switch sides.\"],\"img\":\"3880.webp\",\"gif\":\"3880.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm lateral raise leaning away from a cable stack, giving constant tension on the side delt.\"},{\"id\":\"5814\",\"n\":\"cable low chest press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Set the pulleys low and hold a handle in each hand.\",\"Step forward into a split stance with elbows bent.\",\"Press the handles up and forward in an arc.\",\"Squeeze your chest as your hands meet.\",\"Return slowly to the start.\"],\"img\":\"5814.webp\",\"gif\":\"5814.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable press with the handles starting low and moving upward. It works the upper chest and front shoulders.\"},{\"id\":\"4391\",\"n\":\"cable low row with rope attachment\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\",\"lower back\"],\"st\":[\"Sit at the low pulley with the rope attached, feet on the platform and knees slightly bent.\",\"Grab the rope ends with a neutral grip and sit tall.\",\"Pull the rope toward your lower stomach, driving your elbows back.\",\"Squeeze your shoulder blades together.\",\"Return slowly until your arms are straight without rounding your back.\"],\"img\":\"4391.webp\",\"gif\":\"4391.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row using a rope that lets your hands travel close to your body. It targets the lats and mid back.\"},{\"id\":\"6032\",\"n\":\"cable low seated row with v bar\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"lower back\"],\"st\":[\"Sit at the low pulley, feet on the platform, knees slightly bent, and hold the V bar.\",\"Sit tall with your chest up and arms straight.\",\"Pull the handle to your lower ribs, squeezing your shoulder blades together.\",\"Pause briefly, keeping your torso still.\",\"Extend your arms slowly until you feel a stretch in your back.\"],\"img\":\"6032.webp\",\"gif\":\"6032.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row with a V handle and a neutral grip. It builds the mid back and lats.\"},{\"id\":\"3351\",\"n\":\"cable lunge\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a cable handle at chest height and step away from the stack.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor.\",\"Keep your torso upright and front heel down.\",\"Push back to standing and alternate legs.\"],\"img\":\"3351.webp\",\"gif\":\"3351.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge with cable resistance, building leg strength with a constant load.\"},{\"id\":\"11262\",\"n\":\"cable lying alternating bent leg jackknife v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your feet attached to a low cable and hands by your sides.\",\"Press your lower back into the floor.\",\"Bring one bent knee toward your chest.\",\"Lower it slowly and switch legs.\",\"Keep a controlled alternating rhythm.\"],\"img\":\"11262.webp\",\"gif\":\"11262.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg-raise style core move against cable resistance, alternating legs. It hits the lower abs.\"},{\"id\":\"9872\",\"n\":\"cable lying bench cross lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\"],\"st\":[\"Lie on a flat bench between two low cable pulleys and grab each handle with the opposite hand.\",\"Start with your arms crossed over your body and a slight bend in the elbows.\",\"Raise both arms out and up in a wide arc until your hands are about shoulder height.\",\"Pause briefly at the top without shrugging.\",\"Lower slowly back to the crossed position.\",\"Keep your back flat on the bench and avoid swinging.\"],\"img\":\"9872.webp\",\"gif\":\"9872.mp4\",\"cat\":\"strength\",\"desc\":\"A lying lateral raise where each hand grips the opposite cable handle and the arms sweep up and across. It hits the side delts with constant tension.\"},{\"id\":\"9873\",\"n\":\"cable lying bench single arm cross lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\"],\"st\":[\"Lie on a flat bench next to a low pulley and take the handle with the far hand.\",\"Start with your arm across your body and a soft bend in the elbow.\",\"Raise the arm out and up in an arc until it reaches about shoulder height.\",\"Hold for a moment, then lower with control.\",\"Keep your torso still and your shoulder away from your ear.\",\"Finish your reps, then switch sides.\"],\"img\":\"9873.webp\",\"gif\":\"9873.mp4\",\"cat\":\"strength\",\"desc\":\"A one-armed lying lateral raise across the body with a low cable. It isolates a single side delt and lets you fix imbalances.\"},{\"id\":\"2396\",\"n\":\"cable lying biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie on your back on the floor facing the cable stack and hold the bar or handle with palms up.\",\"Keep your upper arms still and pinned to the floor.\",\"Curl the handle toward your shoulders, squeezing the biceps at the top.\",\"Lower slowly until your arms are almost straight.\",\"Keep your back flat and avoid lifting your shoulders as you curl.\"],\"img\":\"2396.webp\",\"gif\":\"2396.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back with a cable pulling from the floor, you curl the handle toward your shoulders to isolate the biceps under steady tension.\"},{\"id\":\"0181\",\"n\":\"cable lying close grip curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Set a low pulley with a short bar and lie on your back with your feet toward the stack.\",\"Grab the bar with a close underhand grip and arms extended.\",\"Keep your upper arms still and curl the bar toward your shoulders.\",\"Squeeze your biceps at the top for a moment.\",\"Lower the bar slowly until your arms are straight again.\",\"Don't let your elbows drift away from your sides.\"],\"img\":\"0181.webp\",\"gif\":\"0181.mp4\",\"cat\":\"strength\",\"desc\":\"A curl done lying on the floor facing a low cable, with hands close together. The lying position keeps tension on the biceps through the whole range.\"},{\"id\":\"3362\",\"n\":\"cable lying close press\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a bench with the cable behind your head and hold the handle with a narrow grip.\",\"Start with arms bent over your chest.\",\"Press up until your arms are straight.\",\"Keep your elbows close to your body.\",\"Lower slowly and repeat.\"],\"img\":\"3362.webp\",\"gif\":\"3362.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip press lying down with a cable, putting emphasis on the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"4013\",\"n\":\"cable lying cross lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper chest\"],\"st\":[\"Lie on a bench with a cable running across your body.\",\"Hold the handle with the far hand.\",\"Raise the arm out to the side.\",\"Lower with control.\",\"Finish reps, then switch arms.\"],\"img\":\"4013.webp\",\"gif\":\"4013.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise performed lying down using a crossing cable. It isolates the side delts.\",\"nd\":[\"bench\"]},{\"id\":\"0183\",\"n\":\"cable lying curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie on your back on a mat with your head toward a low pulley and take the bar overhead.\",\"Start with your arms extended.\",\"Curl the bar toward your forehead or chest.\",\"Squeeze your biceps at the top.\",\"Lower with control to full extension.\",\"Keep your elbows pointing upward and your back flat.\"],\"img\":\"0183.webp\",\"gif\":\"0183.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl lying on your back with a low cable. The position keeps your body steady and your arms isolated.\"},{\"id\":\"7591\",\"n\":\"cable lying face pull\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"rotator cuff\"],\"st\":[\"Lie on your back with the cable set low behind your head and hold the rope ends.\",\"Start with your arms extended.\",\"Pull the rope toward your face, elbows flaring out and wide.\",\"Squeeze your shoulder blades together at the end.\",\"Return slowly to the start.\"],\"img\":\"7591.webp\",\"gif\":\"7591.mp4\",\"cat\":\"strength\",\"desc\":\"A face pull performed lying on your back with a cable. It hits the rear delts and upper back with little help from momentum.\"},{\"id\":\"9705\",\"n\":\"cable lying floor front raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Lie on your back with your feet toward a low pulley and hold the handle.\",\"Start with your arm by your thigh.\",\"Raise your arm up over your chest with a slight elbow bend.\",\"Pause at the top.\",\"Lower slowly and repeat, then switch arms.\"],\"img\":\"9705.webp\",\"gif\":\"9705.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on the floor, you lift a cable handle up in front of you to isolate the front delts.\"},{\"id\":\"11273\",\"n\":\"cable lying fly v. 3\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\"],\"st\":[\"Lie on a bench between two low pulleys and hold a handle in each hand over your chest.\",\"Keep a soft bend in your elbows.\",\"Lower your arms out to the sides in a wide arc.\",\"Stop at a comfortable stretch.\",\"Bring the handles back together over your chest.\"],\"img\":\"11273.webp\",\"gif\":\"11273.mp4\",\"cat\":\"strength\",\"desc\":\"A lying cable fly that stretches and squeezes the chest. The cables keep tension on at the top.\",\"nd\":[\"bench\"]},{\"id\":\"4227\",\"n\":\"cable lying front raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"trapezius\"],\"st\":[\"Lie on your back with your head toward a low pulley.\",\"Hold the handle with straight arms by your hips.\",\"Raise your arms in an arc until they point straight up.\",\"Pause at the top.\",\"Lower slowly back toward your thighs.\",\"Keep your ribs down and core braced.\"],\"img\":\"4227.webp\",\"gif\":\"4227.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise lying on your back using a low cable. It isolates the front delts without any body swing.\"},{\"id\":\"8876\",\"n\":\"cable lying hip flexion (reverse squat)\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Lie on your back with the cable attached to both ankles or a strap around your feet.\",\"Start with your legs extended and your core braced.\",\"Pull your knees toward your chest in a smooth curl.\",\"Pause at the top without lifting your head.\",\"Lower your legs slowly until they are almost straight.\",\"Keep your lower back flat on the floor throughout.\"],\"img\":\"8876.webp\",\"gif\":\"8876.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you pull both knees toward your chest against cable resistance, like a squat in reverse. It works the hip flexors and lower abs.\"},{\"id\":\"9927\",\"n\":\"cable lying incline side leg raise\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"obliques\"],\"st\":[\"Lie on your side on an incline surface.\",\"Attach the cuff to your top ankle.\",\"Raise your top leg out to the side.\",\"Pause at the top.\",\"Lower with control.\",\"Do your reps, then switch sides.\"],\"img\":\"9927.webp\",\"gif\":\"9927.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying leg raise with a cable on an incline. It works the outer hip and glutes.\"},{\"id\":\"9928\",\"n\":\"cable lying incline single leg kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on an incline surface with the cuff on one ankle.\",\"Hold the support for stability.\",\"Kick your leg back and up.\",\"Squeeze your glute at the top.\",\"Lower slowly.\",\"Do your reps, then switch legs.\"],\"img\":\"9928.webp\",\"gif\":\"9928.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg kickback lying on an incline with a cable. It focuses on the glutes.\"},{\"id\":\"4224\",\"n\":\"cable lying pallof press\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Lie on your back beside a low cable pulley with a handle in both hands.\",\"Hold the handle at your chest, arms bent.\",\"Brace your core to stay flat.\",\"Press your arms straight up while resisting the cable pull.\",\"Hold a second, then bring the handle back to your chest.\",\"Finish your reps and switch sides.\"],\"img\":\"4224.webp\",\"gif\":\"4224.mp4\",\"cat\":\"strength\",\"desc\":\"A Pallof press done lying on your back that resists rotation. It strengthens the deep core and obliques.\"},{\"id\":\"4350\",\"n\":\"cable lying regular grip curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie on your back with your feet toward a low pulley and grab the bar with an underhand grip.\",\"Pin your upper arms to the floor beside you.\",\"Curl the bar up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower the bar slowly until your arms are straight and repeat.\"],\"img\":\"4350.webp\",\"gif\":\"4350.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl performed lying on your back with a cable. The lying position keeps constant tension on the biceps.\"},{\"id\":\"4226\",\"n\":\"cable lying shrug\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"forearms\"],\"st\":[\"Lie on your back with a low pulley near your feet.\",\"Hold the handle with straight arms down by your sides.\",\"Shrug your shoulders toward your ears.\",\"Squeeze at the top for a second.\",\"Lower slowly to a full stretch.\",\"Keep your arms straight throughout.\"],\"img\":\"4226.webp\",\"gif\":\"4226.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug performed lying down with a cable pulling from your feet. It trains the upper traps with steady tension.\"},{\"id\":\"9874\",\"n\":\"cable lying single arm cross lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\"],\"st\":[\"Lie on the floor next to a low pulley and grip the handle with the far hand.\",\"Begin with your arm across your body and the elbow slightly bent.\",\"Raise your arm out and up in a smooth arc to about shoulder height.\",\"Pause briefly at the top.\",\"Lower slowly back across your body without letting the weight stack rest.\",\"Complete your reps, then switch sides.\"],\"img\":\"9874.webp\",\"gif\":\"9874.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm lateral raise done lying on your side or back on the floor with a low cable crossing the body. It trains the side delt under steady tension.\"},{\"id\":\"8875\",\"n\":\"cable lying single leg hip flexion\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with the ankle strap attached to the low cable and one foot in it.\",\"Brace your core and press your lower back into the floor.\",\"Pull the knee up toward your chest with control.\",\"Pause briefly, then lower the leg slowly against the cable.\",\"Keep the other leg relaxed and your hips still.\",\"Finish all reps, then switch legs.\"],\"img\":\"8875.webp\",\"gif\":\"8875.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back with a cable strapped to one ankle, you pull the knee toward your chest. It builds hip flexor strength.\"},{\"id\":\"0187\",\"n\":\"cable lying triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Set a low pulley with a bar or rope and lie on a bench with your head near the stack.\",\"Hold the handle with arms extended above your chest.\",\"Keep your upper arms still and bend only at the elbows to lower the handle toward your forehead.\",\"Pause when your forearms pass parallel to the floor.\",\"Press back up by straightening your arms.\",\"Keep your elbows pointing at the ceiling and don't flare them.\"],\"img\":\"0187.webp\",\"gif\":\"0187.mp4\",\"cat\":\"strength\",\"desc\":\"A lying triceps extension using a cable, which keeps constant tension on the back of the arms. Good for building triceps size and strength.\",\"nd\":[\"bench\"]},{\"id\":\"5243\",\"n\":\"cable lying triceps extension (low)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Lie on a bench with a low pulley behind your head.\",\"Hold the bar or rope with your arms up over your face.\",\"Keep your upper arms still.\",\"Bend your elbows to lower the handle toward your forehead.\",\"Extend your arms back up.\"],\"img\":\"5243.webp\",\"gif\":\"5243.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on a bench with a low cable, extending the arms. It isolates the triceps.\",\"nd\":[\"bench\"],\"fv\":\"5262\"},{\"id\":\"4353\",\"n\":\"cable lying triceps extension (with rope)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench with your head toward a low pulley and hold the rope above your chest.\",\"Keep your upper arms still.\",\"Bend your elbows and lower the rope behind your head.\",\"Extend your arms to return.\",\"Spread the rope slightly at the end.\"],\"img\":\"4353.webp\",\"gif\":\"4353.mp4\",\"cat\":\"strength\",\"desc\":\"A lying triceps extension on a bench using a cable rope. It keeps constant tension on the triceps.\",\"nd\":[\"bench\"]},{\"id\":\"4225\",\"n\":\"cable lying upright row\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\"],\"st\":[\"Lie on your back with your feet toward a low pulley.\",\"Hold a bar or handle with an overhand grip, arms straight.\",\"Pull the handle up toward your chin, leading with your elbows.\",\"Keep the handle close to your body.\",\"Pause at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"4225.webp\",\"gif\":\"4225.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row done lying on your back with a low cable. The lying position takes your lower back out of the movement.\"},{\"id\":\"9492\",\"n\":\"cable lying upright row (sz bar)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\"],\"st\":[\"Lie on your back with your feet toward a low pulley and grip the SZ bar.\",\"Start with arms extended over your thighs.\",\"Pull the bar up toward your chin, leading with your elbows.\",\"Pause when your elbows reach shoulder height.\",\"Lower the bar slowly to the start.\"],\"img\":\"9492.webp\",\"gif\":\"9492.mp4\",\"cat\":\"strength\",\"desc\":\"An upright row done lying on your back with a cambered bar on a low cable. It hits the delts and traps with steady tension.\"},{\"id\":\"5470\",\"n\":\"cable medius kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Attach an ankle strap to a low pulley and clip it to one ankle.\",\"Stand side-on to the stack, hold the frame and keep your torso tall.\",\"Sweep the working leg out and slightly back, leading with the heel.\",\"Pause briefly, then return slowly without leaning.\",\"Finish all reps, then switch legs.\"],\"img\":\"5470.webp\",\"gif\":\"5470.mp4\",\"cat\":\"strength\",\"desc\":\"Standing cable kickback angled out to the side that targets the upper glutes (gluteus medius) and hip stability.\"},{\"id\":\"2835\",\"n\":\"cable narrow chair stand up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Sit on a chair holding the cable handle at your chest.\",\"Keep your feet close together.\",\"Lean forward slightly.\",\"Push through your heels to stand.\",\"Lower back under control.\"],\"img\":\"2835.webp\",\"gif\":\"2835.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted sit-to-stand with a narrow stance and cable resistance.\"},{\"id\":\"4566\",\"n\":\"cable neutral grip kickback\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Set a low cable with a neutral grip handle and hinge forward at the hips.\",\"Pin your upper arm against your side.\",\"Hold the handle with your palm facing in.\",\"Extend your elbow back until your arm is straight.\",\"Squeeze your triceps for a moment.\",\"Return slowly and switch arms after the set.\"],\"img\":\"4566.webp\",\"gif\":\"4566.mp4\",\"cat\":\"strength\",\"desc\":\"A cable kickback with palms facing in, isolating the triceps.\"},{\"id\":\"7583\",\"n\":\"cable neutral grip lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Sit at the lat pulldown station, thighs secured, and grab the neutral-grip handle.\",\"Lean back slightly and brace your core.\",\"Pull the handle down to your upper chest, driving your elbows toward your ribs.\",\"Squeeze your shoulder blades together at the bottom.\",\"Let the handle rise slowly until your arms are fully extended.\"],\"img\":\"7583.webp\",\"gif\":\"7583.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a neutral-grip handle down to your upper chest on a cable stack. It builds the lats and the muscles between your shoulder blades.\"},{\"id\":\"9304\",\"n\":\"cable neutral grip wide pulldown v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit at the pulldown station with your thighs under the pads.\",\"Grab the wide neutral grip handles.\",\"Lean back slightly and keep your chest up.\",\"Pull the handles down toward your upper chest.\",\"Squeeze your lats at the bottom.\",\"Let the handles rise slowly with control.\"],\"img\":\"9304.webp\",\"gif\":\"9304.mp4\",\"cat\":\"strength\",\"desc\":\"A wide, neutral grip pulldown on a cable machine that builds the lats and upper back.\"},{\"id\":\"2656\",\"n\":\"cable one arm biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand facing the cable with the handle at low height and grip it with one hand, palm up.\",\"Keep your elbow tucked at your side.\",\"Curl the handle toward your shoulder and squeeze the biceps.\",\"Lower slowly until the arm is nearly straight.\",\"Finish all reps, then switch arms.\"],\"img\":\"2656.webp\",\"gif\":\"2656.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl using a cable for constant tension, great for working each biceps on its own.\",\"fv\":\"2657\"},{\"id\":\"2689\",\"n\":\"cable one arm front raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"core\"],\"st\":[\"Stand facing away from a low cable pulley with the handle in one hand.\",\"Keep your arm nearly straight and raise it forward to shoulder height.\",\"Pause briefly at the top.\",\"Lower with control.\",\"Finish your reps, then switch arms.\"],\"img\":\"2689.webp\",\"gif\":\"2689.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm front raise with constant cable tension, training the front of the shoulder.\"},{\"id\":\"3353\",\"n\":\"cable one arm high pulley overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Face away from a high pulley and hold the handle overhead with one hand.\",\"Stand in a split stance with your elbow pointing up.\",\"Extend your arm forward and up until it is straight.\",\"Keep your upper arm still.\",\"Return slowly and switch arms after the set.\"],\"img\":\"3353.webp\",\"gif\":\"3353.mp4\",\"cat\":\"strength\",\"desc\":\"A single arm overhead extension on a high pulley that stretches and loads the long head of the triceps.\"},{\"id\":\"1203\",\"n\":\"cable one arm inner biceps curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach a handle to a low cable and stand facing the stack.\",\"Hold the handle with one hand, palm up, and turn your elbow slightly out.\",\"Curl the handle toward your shoulder.\",\"Squeeze at the top, then lower under control.\",\"Finish your reps, then switch arms.\"],\"img\":\"1203.webp\",\"gif\":\"1203.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm cable curl with the elbow pointing slightly out to emphasise the inner biceps.\"},{\"id\":\"1204\",\"n\":\"cable one arm lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Attach a handle to a high pulley and sit facing the stack.\",\"Grab the handle with one hand and sit tall.\",\"Pull the handle down to the side of your chest, driving your elbow toward your hip.\",\"Pause, then let your arm rise slowly.\",\"Complete your reps and switch sides.\"],\"img\":\"1204.webp\",\"gif\":\"1204.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm pulldown on a high cable. It lets each side of the lats work on its own.\",\"fv\":\"3596\"},{\"id\":\"4122\",\"n\":\"cable one arm reverse fly\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\"],\"st\":[\"Stand sideways to a cable at shoulder height and grab the handle with the far hand.\",\"Keep a slight bend in your elbow.\",\"Pull your arm across and back in an arc.\",\"Squeeze your rear delt.\",\"Return slowly, then switch arms.\"],\"img\":\"4122.webp\",\"gif\":\"4122.mp4\",\"cat\":\"strength\",\"desc\":\"A single arm reverse fly on a cable to isolate the rear delts.\"},{\"id\":\"1609\",\"n\":\"cable one arm side triceps pushdown\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach a handle to a high pulley and stand sideways to the machine.\",\"Grip the handle with the arm closest to the stack and keep your elbow at your side.\",\"Push the handle down until your arm is straight.\",\"Squeeze your triceps at the bottom.\",\"Return slowly, finish your reps, then switch arms.\"],\"img\":\"1609.webp\",\"gif\":\"1609.mp4\",\"cat\":\"strength\",\"desc\":\"A one-armed cable pushdown done from the side. It isolates each triceps and lets you focus on form.\"},{\"id\":\"1205\",\"n\":\"cable one arm twisting seated row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"obliques\"],\"st\":[\"Sit at a low cable with your feet braced and grab the handle with one hand.\",\"Start with your torso turned slightly toward the cable.\",\"Row the handle to your side while rotating your torso open.\",\"Squeeze your shoulder blade back, then return slowly.\",\"Do all reps, then change arms.\"],\"img\":\"1205.webp\",\"gif\":\"1205.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm cable row with a rotation of the torso. It trains the back and gives the core a twist.\",\"fv\":\"3597\"},{\"id\":\"4163\",\"n\":\"cable one arm wrist curl\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit by a low pulley with your forearm resting on your thigh.\",\"Hold the handle with your palm facing up.\",\"Curl your wrist up as far as you can.\",\"Pause at the top.\",\"Lower slowly under control.\",\"Complete all reps, then switch arms.\"],\"img\":\"4163.webp\",\"gif\":\"4163.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl using cable resistance on one arm. It strengthens the forearm flexors.\"},{\"id\":\"4958\",\"n\":\"cable overhead single arm triceps extension (rope attachment)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold a rope with one hand overhead and face away from the stack.\",\"Keep your upper arm close to your head.\",\"Extend your elbow until the arm is straight.\",\"Squeeze the triceps.\",\"Lower slowly.\",\"Finish reps, then switch arms.\"],\"img\":\"4958.webp\",\"gif\":\"4958.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm overhead triceps extension with a rope. It isolates the triceps.\",\"fv\":\"11319\"},{\"id\":\"11252\",\"n\":\"cable overhead squat v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Set a cable low and hold the handle overhead with straight arms, standing tall.\",\"Brace your core and keep your ribs down.\",\"Squat down by pushing your hips back and bending your knees.\",\"Keep the handle over your head and chest up.\",\"Drive through your heels to stand.\"],\"img\":\"11252.webp\",\"gif\":\"11252.mp4\",\"cat\":\"strength\",\"desc\":\"A squat while holding a cable overhead. It trains the legs and challenges shoulder stability and core control.\"},{\"id\":\"4115\",\"n\":\"cable overhead tricep extension straight bar\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Set a straight bar on a low pulley and face away from it.\",\"Hold the bar overhead with elbows bent.\",\"Keep your elbows pointing forward.\",\"Extend your arms to straighten them fully.\",\"Lower the bar back behind your head slowly.\"],\"img\":\"4115.webp\",\"gif\":\"4115.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead cable extension with a straight bar, stretching and loading the triceps.\"},{\"id\":\"4197\",\"n\":\"cable pallof press with glute bridge\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Lie on your back with a cable beside you.\",\"Hold the handle at your chest.\",\"Bridge your hips up.\",\"Press the handle forward.\",\"Return and lower.\",\"Switch sides.\"],\"img\":\"4197.webp\",\"gif\":\"4197.mp4\",\"cat\":\"strength\",\"desc\":\"Combine a pallof press with a glute bridge.\"},{\"id\":\"3358\",\"n\":\"cable parallel grip lat pulldown on floor\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Kneel or sit on the floor under a high cable with a parallel grip handle.\",\"Sit tall and lean back slightly.\",\"Pull the handle down to your upper chest.\",\"Drive your elbows down and back.\",\"Return slowly to full arm extension.\"],\"img\":\"3358.webp\",\"gif\":\"3358.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown done from the floor with a neutral grip, focusing on the lats.\"},{\"id\":\"11276\",\"n\":\"cable prone single leg curl v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie face down with an ankle strap attached to a low cable.\",\"Keep your hips pressed down.\",\"Curl your heel toward your glutes.\",\"Squeeze your hamstring at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"11276.webp\",\"gif\":\"11276.mp4\",\"cat\":\"strength\",\"desc\":\"A lying face-down leg curl on a cable. Training one leg at a time builds the hamstrings evenly.\"},{\"id\":\"1206\",\"n\":\"cable pull through\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Attach a rope to a low pulley and face away from the stack, holding the rope between your legs.\",\"Step forward until the cable is taut and bend your knees slightly.\",\"Push your hips back, letting the rope travel behind you.\",\"Drive your hips forward and squeeze your glutes to stand tall.\",\"Keep your back flat throughout.\"],\"img\":\"1206.webp\",\"gif\":\"1206.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge facing away from a low cable. It builds the glutes and hamstrings and teaches a good hinge.\"},{\"id\":\"3914\",\"n\":\"cable rear delt row\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Set a cable at chest height with a handle or rope.\",\"Hold it with your arms extended.\",\"Step back and lean slightly.\",\"Pull the handle toward your upper chest with your elbows flared out.\",\"Squeeze your rear delts.\",\"Return slowly.\"],\"img\":\"3914.webp\",\"gif\":\"3914.mp4\",\"cat\":\"strength\",\"desc\":\"A row with wide elbows on the cable machine that targets the rear delts.\"},{\"id\":\"6035\",\"n\":\"cable rear delt row (parallel bar)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"upper back\",\"biceps\"],\"st\":[\"Sit facing a low cable with a parallel bar attachment.\",\"Hold the handles with your elbows flared.\",\"Lean back slightly with a straight spine.\",\"Pull the handles toward your chest.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"6035.webp\",\"gif\":\"6035.mp4\",\"cat\":\"strength\",\"desc\":\"A cable row with a parallel bar that targets the rear delts and upper back.\"},{\"id\":\"2837\",\"n\":\"cable rear lunge from stepbox\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand on a step box facing a cable and hold the handle.\",\"Step one leg back and down to lunge.\",\"Lower the back knee toward the floor.\",\"Push through your front foot to return.\",\"Switch legs after your reps.\"],\"img\":\"2837.webp\",\"gif\":\"2837.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge from a step box with cable tension, training the glutes and legs.\"},{\"id\":\"5123\",\"n\":\"cable reverse grip pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit at a pulldown station with palms facing you, hands shoulder-width apart.\",\"Lean back slightly and keep your chest up.\",\"Pull the bar down to your upper chest.\",\"Squeeze your shoulder blades down and together.\",\"Let the bar rise slowly until your arms are straight.\"],\"img\":\"5123.webp\",\"gif\":\"5123.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a bar down to your chest with an underhand grip. It works the lats and gets the biceps more involved.\",\"fv\":\"2491\"},{\"id\":\"1606\",\"n\":\"cable reverse grip triceps pushdown (sz bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"wrist extensors\"],\"st\":[\"Attach an SZ bar to a high pulley and grip it palms up with hands shoulder-width apart.\",\"Keep your elbows tucked at your sides.\",\"Push the bar down until your arms are straight.\",\"Squeeze your triceps at the bottom.\",\"Return slowly without letting your elbows drift forward.\"],\"img\":\"1606.webp\",\"gif\":\"1606.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps pushdown with an underhand grip on an SZ bar. The reverse grip shifts the feel slightly and works the forearms too.\"},{\"id\":\"10503\",\"n\":\"cable reverse narrow grip lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Sit at the pulldown station and secure your thighs.\",\"Grab the bar with a narrow underhand grip.\",\"Lean back a little and pull the bar to your upper chest.\",\"Keep your elbows close to your sides.\",\"Return slowly until your arms are fully extended.\"],\"img\":\"10503.webp\",\"gif\":\"10503.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown with an underhand, narrow grip. It uses the biceps more and works the lower lats.\"},{\"id\":\"8193\",\"n\":\"cable reverse woodchop\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Set the cable low and stand side-on to the stack.\",\"Hold the handle with both hands.\",\"Pull it diagonally up across your body.\",\"Pivot your back foot and rotate your torso.\",\"Return slowly. Switch sides after your set.\"],\"img\":\"8193.webp\",\"gif\":\"8193.mp4\",\"cat\":\"strength\",\"desc\":\"A cable chop that travels from low to high across your body. It trains the obliques and builds rotational power.\"},{\"id\":\"6552\",\"n\":\"cable romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Attach a straight bar to a low pulley and face the machine.\",\"Hold the bar, step back and stand tall with soft knees.\",\"Push your hips back and slide the bar down your thighs.\",\"Keep your back flat and shoulders pulled back.\",\"Lower until you feel a hamstring stretch.\",\"Drive your hips forward to stand up.\"],\"img\":\"6552.webp\",\"gif\":\"6552.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge using a low cable. It trains the hamstrings and glutes with steady tension.\"},{\"id\":\"3869\",\"n\":\"cable seated chest fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Sit on a bench between two cable stacks with the pulleys at chest height.\",\"Grab a handle in each hand and hold your arms out with soft elbows.\",\"Press your back firmly into the bench.\",\"Bring your hands together in front of your chest in a wide arc.\",\"Squeeze, then open your arms slowly.\",\"Stop when you feel a good stretch.\"],\"img\":\"3869.webp\",\"gif\":\"3869.mp4\",\"cat\":\"strength\",\"desc\":\"A seated fly on the cable machine that isolates the chest with constant tension.\"},{\"id\":\"4042\",\"n\":\"cable seated cross arm twist\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Sit next to a cable machine set at chest height and grab the handle with both hands.\",\"Start with your arms extended in front of you.\",\"Rotate your torso away from the stack, pulling the handle across your body.\",\"Pause, then return slowly.\",\"Keep your hips still, finish the reps, then switch sides.\"],\"img\":\"4042.webp\",\"gif\":\"4042.mp4\",\"cat\":\"strength\",\"desc\":\"Seated trunk rotation pulling a cable across the body. It works the obliques and deep core.\"},{\"id\":\"5658\",\"n\":\"cable seated face pull (with rope)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Sit facing a cable with a rope attachment.\",\"Sit tall.\",\"Pull the rope toward your face.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"5658.webp\",\"gif\":\"5658.mp4\",\"cat\":\"strength\",\"desc\":\"Seated rope face pull for the rear delts.\"},{\"id\":\"3925\",\"n\":\"cable seated floor one arm concentration curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit on the floor facing a low cable with a handle in one hand.\",\"Brace your elbow against your inner thigh.\",\"Curl the handle toward your shoulder.\",\"Squeeze your biceps.\",\"Lower slowly.\",\"Switch arms.\"],\"img\":\"3925.webp\",\"gif\":\"3925.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm cable curl with your elbow braced against the thigh, isolating the biceps.\"},{\"id\":\"6745\",\"n\":\"cable seated foot eversion\",\"bp\":\"lower legs\",\"eq\":\"cable\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with your leg extended and a cable cuff on your foot.\",\"Position the cable so it pulls the foot inward.\",\"Keep your leg still.\",\"Turn the sole of your foot outward against the cable.\",\"Pause, then return slowly.\",\"Finish the reps and switch feet.\"],\"img\":\"6745.webp\",\"gif\":\"6745.mp4\",\"cat\":\"strength\",\"desc\":\"A seated ankle move turning the foot outward against a cable. It strengthens the outer ankle and lower leg.\"},{\"id\":\"6746\",\"n\":\"cable seated foot inversion\",\"bp\":\"lower legs\",\"eq\":\"cable\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with your leg extended and a cable cuff on your foot.\",\"Position the cable so it pulls the foot outward.\",\"Keep your leg still.\",\"Turn the sole of your foot inward against the cable.\",\"Pause, then return slowly.\",\"Finish the reps and switch feet.\"],\"img\":\"6746.webp\",\"gif\":\"6746.mp4\",\"cat\":\"strength\",\"desc\":\"A seated ankle move turning the foot inward against a cable. It strengthens the inner ankle and lower leg.\"},{\"id\":\"5916\",\"n\":\"cable seated high pulley overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit facing away from a high pulley and hold the handle overhead with both hands.\",\"Keep your upper arms close to your ears and elbows pointing forward.\",\"Straighten your arms to extend the handle up.\",\"Slowly bend your elbows to lower it behind your head.\",\"Keep your torso upright and your upper arms still.\"],\"img\":\"5916.webp\",\"gif\":\"5916.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead triceps extension on a high pulley that keeps constant tension on the back of the arms.\"},{\"id\":\"11257\",\"n\":\"cable seated high row v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\",\"biceps\",\"trapezius\"],\"st\":[\"Sit at a cable station with the pulley set high and grab the handles.\",\"Sit tall with your chest up.\",\"Pull the handles toward your upper chest, elbows flaring slightly.\",\"Squeeze your shoulder blades together.\",\"Return slowly to full arm extension.\"],\"img\":\"11257.webp\",\"gif\":\"11257.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row with the handle pulled toward your upper chest. It targets the upper back and rear shoulders.\"},{\"id\":\"4111\",\"n\":\"cable seated horizontal shrug\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"traps\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit facing a low cable with a handle in each hand.\",\"Start with arms straight and shoulders forward.\",\"Pull your shoulders back and up.\",\"Squeeze your traps at the end.\",\"Return slowly to the start.\"],\"img\":\"4111.webp\",\"gif\":\"4111.mp4\",\"cat\":\"strength\",\"desc\":\"A seated shrug using a horizontal cable pull, keeping steady tension on the traps.\"},{\"id\":\"11763\",\"n\":\"cable seated incline curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Set a bench to incline and place a low pulley behind you.\",\"Sit back with your arms hanging and grab the handles.\",\"Curl the handles toward your shoulders, keeping elbows back.\",\"Squeeze the biceps at the top.\",\"Lower slowly to a full stretch.\"],\"img\":\"11763.webp\",\"gif\":\"11763.mp4\",\"cat\":\"strength\",\"desc\":\"A curl on an incline seat with cable resistance for a deep, constant-tension biceps stretch.\"},{\"id\":\"5553\",\"n\":\"cable seated lats focused row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Sit at the cable row with feet on the platform and knees slightly bent.\",\"Grab the handle and lean back slightly.\",\"Pull your elbows down and back toward your hips.\",\"Squeeze your lats, then extend slowly.\",\"Keep your chest up.\"],\"img\":\"5553.webp\",\"gif\":\"5553.mp4\",\"cat\":\"strength\",\"desc\":\"Seated cable row set up to emphasise the lats with a pull toward the hips.\"},{\"id\":\"5664\",\"n\":\"cable seated leg extension\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on a bench with an ankle strap attached to a low cable.\",\"Hold the bench.\",\"Extend your leg until straight.\",\"Lower slowly.\",\"Switch legs.\"],\"img\":\"5664.webp\",\"gif\":\"5664.mp4\",\"cat\":\"strength\",\"desc\":\"Seated leg extension using a cable for the quads.\"},{\"id\":\"2411\",\"n\":\"cable seated neck extension (with head harness)\",\"bp\":\"neck\",\"eq\":\"cable\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Fit the head harness and sit facing the cable with it attached at head height.\",\"Start with your head tipped slightly forward.\",\"Pull your head back until it is upright.\",\"Pause, then return slowly against the cable.\",\"Keep the load light and your shoulders relaxed.\"],\"img\":\"2411.webp\",\"gif\":\"2411.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with a harness attached to a cable, you pull your head back against steady resistance to train the neck extensors.\"},{\"id\":\"2412\",\"n\":\"cable seated neck flexion (with head harness)\",\"bp\":\"neck\",\"eq\":\"cable\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Fit the head harness and sit facing away from the cable, attached at head height.\",\"Start with your head tilted slightly back.\",\"Bring your chin toward your chest.\",\"Pause, then return slowly in control.\",\"Keep the load light and your shoulders relaxed.\"],\"img\":\"2412.webp\",\"gif\":\"2412.mp4\",\"cat\":\"strength\",\"desc\":\"Seated with a harness attached to a cable behind you, you tuck your chin forward to train the neck flexors.\"},{\"id\":\"3357\",\"n\":\"cable seated on floor row with rope\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit on the floor facing a low cable with legs extended and the rope in your hands.\",\"Sit tall with a straight back.\",\"Pull the rope toward your lower chest, spreading your hands.\",\"Squeeze your shoulder blades together.\",\"Extend your arms slowly and repeat.\"],\"img\":\"3357.webp\",\"gif\":\"3357.mp4\",\"cat\":\"strength\",\"desc\":\"A floor seated cable row using a rope, which lets you pull the hands apart and squeeze the mid back.\"},{\"id\":\"6266\",\"n\":\"cable seated overhead curl (sz bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit facing the cable machine.\",\"Grip the SZ bar and extend your arms.\",\"Curl the bar toward your head.\",\"Squeeze the biceps.\",\"Lower slowly.\",\"Keep your elbows high.\"],\"img\":\"6266.webp\",\"gif\":\"6266.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable curl with an SZ bar, with the cable set up overhead. It targets the biceps.\"},{\"id\":\"4180\",\"n\":\"cable seated pullover\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Sit at a high pulley holding the rope or bar with straight arms.\",\"Lean slightly forward.\",\"Pull the handle down in an arc to your thighs.\",\"Squeeze your lats.\",\"Return slowly with arms straight.\",\"Avoid bending your elbows.\"],\"img\":\"4180.webp\",\"gif\":\"4180.mp4\",\"cat\":\"strength\",\"desc\":\"A seated pullover using a cable. It isolates the lats with constant tension.\"},{\"id\":\"3943\",\"n\":\"cable seated rear delt fly with chest support\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\"],\"st\":[\"Sit facing the stack with your chest against the pad and hold the handles.\",\"Start with your arms forward and elbows slightly bent.\",\"Sweep your arms out and back to shoulder height.\",\"Pause, then return slowly.\",\"Keep your neck relaxed.\"],\"img\":\"3943.webp\",\"gif\":\"3943.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse fly on a chest-supported seat using cables. It targets the rear delts with little help from momentum.\"},{\"id\":\"7155\",\"n\":\"cable seated reverse shrug\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"traps\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"upper back\"],\"st\":[\"Sit with a low cable behind you, holding the handle behind your back.\",\"Keep your arms straight and chest tall.\",\"Shrug your shoulders up and slightly back.\",\"Hold for a second.\",\"Lower slowly to the start.\"],\"img\":\"7155.webp\",\"gif\":\"7155.mp4\",\"cat\":\"strength\",\"desc\":\"A seated shrug with the cable pulling from behind the body. It trains the traps and the upper back.\"},{\"id\":\"1238\",\"n\":\"cable seated row (bent bar)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\"],\"st\":[\"Sit at a low cable station with your feet on the platform and knees slightly bent.\",\"Grab the bent bar with both hands.\",\"Pull the bar to your lower ribs, keeping your back straight.\",\"Squeeze your shoulder blades.\",\"Extend your arms slowly without rounding forward.\"],\"img\":\"1238.webp\",\"gif\":\"1238.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row using a bent bar. The angled bar suits many wrists while you train the back.\"},{\"id\":\"2661\",\"n\":\"cable seated row with v bar\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Sit at the cable row station with your feet on the platform and knees slightly bent.\",\"Grip the V bar and sit tall with arms extended.\",\"Pull the bar toward your lower ribs and squeeze your shoulder blades.\",\"Return slowly until your arms are straight.\",\"Keep your chest up and avoid rocking.\"],\"img\":\"2661.webp\",\"gif\":\"2661.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row with a V-shaped grip that trains the mid back and lats.\"},{\"id\":\"11057\",\"n\":\"cable seated scapular retraction\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Sit at a low cable station, feet braced, and hold the handle with straight arms.\",\"Sit tall and let your shoulder blades stretch forward.\",\"Pull your shoulder blades together, keeping your arms straight.\",\"Hold the squeeze briefly.\",\"Return slowly to the start.\"],\"img\":\"11057.webp\",\"gif\":\"11057.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable move that trains your shoulder blades to pull back. It helps posture and builds the mid back.\"},{\"id\":\"10112\",\"n\":\"cable seated single arm lats focused row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit at the cable station with your feet braced and grab the handle with one hand.\",\"Sit tall and let the arm extend with a slight stretch in the lat.\",\"Pull your elbow down and back toward your hip, leading with the elbow.\",\"Squeeze the lat for a moment, then slowly let the handle return.\",\"Keep your torso still and shoulders down. Finish all reps, then switch arms.\"],\"img\":\"10112.webp\",\"gif\":\"10112.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm seated cable row that keeps the pull in the lats. Great for fixing side-to-side strength gaps.\"},{\"id\":\"7922\",\"n\":\"cable seated single arm unilateral bicep curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit upright with a low cable handle in one hand.\",\"Keep your elbow tucked in.\",\"Curl up toward your shoulder without leaning back.\",\"Squeeze at the top for a second.\",\"Lower under control, then switch arms.\"],\"img\":\"7922.webp\",\"gif\":\"7922.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm cable curl that keeps tension on the biceps. Good for fixing strength gaps between arms.\"},{\"id\":\"3233\",\"n\":\"cable seated supine grip row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\",\"forearms\"],\"st\":[\"Sit at a cable row with your feet braced.\",\"Grip the handle with your palms facing up.\",\"Sit tall with your chest up.\",\"Pull the handle toward your lower ribs.\",\"Squeeze your shoulder blades.\",\"Return slowly without rounding your back.\"],\"img\":\"3233.webp\",\"gif\":\"3233.mp4\",\"cat\":\"strength\",\"desc\":\"A seated cable row with an underhand grip that brings the biceps and lats into play.\",\"fv\":\"0217\"},{\"id\":\"2434\",\"n\":\"cable seated twist on floor\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"lower back\"],\"st\":[\"Sit on the floor facing a low cable and hold the handle.\",\"Lean back slightly and lift your feet if you can.\",\"Rotate your torso from side to side.\",\"Keep your arms steady and your core tight.\",\"Move slowly without jerking.\",\"Continue for the planned reps.\"],\"img\":\"2434.webp\",\"gif\":\"2434.mp4\",\"cat\":\"strength\",\"desc\":\"A seated rotation with a cable that trains the obliques and core.\"},{\"id\":\"7921\",\"n\":\"cable seated unilateral bicep curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit facing a low cable and hold the handle with one hand.\",\"Rest your elbow near your side.\",\"Curl the handle up toward your shoulder.\",\"Squeeze at the top.\",\"Lower slowly and switch arms after your set.\"],\"img\":\"7921.webp\",\"gif\":\"7921.mp4\",\"cat\":\"strength\",\"desc\":\"A seated biceps curl with a cable, working one arm at a time. It gives constant tension throughout the movement.\"},{\"id\":\"3364\",\"n\":\"cable seating close press\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on a bench facing away from a cable at chest height.\",\"Hold the handle with a narrow grip.\",\"Press forward until your arms are straight.\",\"Keep your back against the pad.\",\"Return slowly and repeat.\"],\"img\":\"3364.webp\",\"gif\":\"3364.mp4\",\"cat\":\"strength\",\"desc\":\"A seated close grip cable press for the triceps with a stable base.\"},{\"id\":\"5087\",\"n\":\"cable shoulder 90 degrees external rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Set a cable at shoulder height and stand sideways to it.\",\"Hold the handle with your upper arm out at 90 degrees and elbow bent 90 degrees.\",\"Rotate your forearm up and back without moving your upper arm.\",\"Pause, then return slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"5087.webp\",\"gif\":\"5087.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your forearm up and back against a cable with your upper arm at shoulder height. It strengthens the rotator cuff external rotators.\"},{\"id\":\"5089\",\"n\":\"cable shoulder 90 degrees internal rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Set a cable at shoulder height and face away from it.\",\"Hold the handle with your upper arm out at 90 degrees and elbow bent 90 degrees.\",\"Rotate your forearm forward and down, keeping your upper arm still.\",\"Pause, then return slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"5089.webp\",\"gif\":\"5089.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your forearm down and forward against a cable with your upper arm held at shoulder height. It builds shoulder internal rotation strength.\"},{\"id\":\"5088\",\"n\":\"cable shoulder internal rotation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Set a cable at elbow height and stand sideways to it.\",\"Hold the handle with your elbow tucked against your side at 90 degrees.\",\"Rotate your forearm across your stomach.\",\"Return slowly, keeping your elbow pinned.\",\"Complete your reps, then switch sides.\"],\"img\":\"5088.webp\",\"gif\":\"5088.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a cable handle across your body with your elbow tucked at your side. It trains the internal rotators of the shoulder.\"},{\"id\":\"5657\",\"n\":\"cable side bend v. 2\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Stand side-on to a low cable holding the handle.\",\"Keep your hips still.\",\"Bend sideways away from the cable.\",\"Return to upright.\",\"Switch sides.\"],\"img\":\"5657.webp\",\"gif\":\"5657.mp4\",\"cat\":\"strength\",\"desc\":\"Side bend using a cable for the obliques.\"},{\"id\":\"10860\",\"n\":\"cable side leg kick from back\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Attach an ankle cuff to a low pulley and strap it to one ankle.\",\"Stand side-on to the machine and hold the frame for balance.\",\"Kick the working leg out and slightly behind you, keeping the knee mostly straight.\",\"Pause, then return slowly without letting the weight stack touch down.\",\"Keep your torso still. Finish all reps, then switch legs.\"],\"img\":\"10860.webp\",\"gif\":\"10860.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable kick that sweeps the leg out and back. It works the outer hip and glutes.\"},{\"id\":\"9863\",\"n\":\"cable side lying floor single leg kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your side with a cuff on your top ankle.\",\"Position the cable behind you.\",\"Kick your top leg back and slightly up.\",\"Squeeze your glute at the top.\",\"Return slowly.\",\"Do your reps, then switch sides.\"],\"img\":\"9863.webp\",\"gif\":\"9863.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying leg kickback with a cable. It isolates the glutes.\"},{\"id\":\"2924\",\"n\":\"cable side lying lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\",\"trapezius\"],\"st\":[\"Lie on your side next to a low cable pulley and grab the handle with your top hand.\",\"Keep your arm straight with a slight bend in the elbow.\",\"Raise your arm out to the side until it is near shoulder height.\",\"Pause briefly at the top.\",\"Lower slowly, finish the reps, then switch sides.\"],\"img\":\"2924.webp\",\"gif\":\"2924.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise performed while lying on your side with a cable. Lying down keeps constant tension on the side delt.\"},{\"id\":\"9491\",\"n\":\"cable side lying single arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Set a low pulley and lie on your side with the handle in your top hand.\",\"Keep your arm straight or slightly bent.\",\"Raise the handle in an arc up to about shoulder height or a bit higher.\",\"Pause briefly at the top.\",\"Lower slowly, finish your reps, then switch sides.\"],\"img\":\"9491.webp\",\"gif\":\"9491.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your side, you raise a cable handle out and up to isolate the side delts with constant tension.\"},{\"id\":\"11275\",\"n\":\"cable side plank row v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"upper back\",\"shoulders\"],\"st\":[\"Set up in a side plank with a low cable handle in your top hand.\",\"Lift your hips so your body is in a straight line.\",\"Row the handle toward your ribs.\",\"Keep your hips high and stable.\",\"Extend slowly, finish your reps, then switch sides.\"],\"img\":\"11275.webp\",\"gif\":\"11275.mp4\",\"cat\":\"strength\",\"desc\":\"A side plank held while you row a cable. It trains the core, shoulders and back at the same time.\"},{\"id\":\"10095\",\"n\":\"cable single arm bear fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Set a cable at chest height and stand with a staggered stance.\",\"Grab the handle with one hand and brace your core.\",\"Keep your elbow slightly bent and sweep your arm across your body.\",\"Squeeze your chest at the end.\",\"Return slowly to the start.\",\"Finish reps and switch arms.\"],\"img\":\"10095.webp\",\"gif\":\"10095.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm cable fly done in a braced, staggered stance, working the chest and keeping the trunk steady.\"},{\"id\":\"6510\",\"n\":\"cable single arm high row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\"],\"st\":[\"Set a cable to a high position and hold the handle with one hand.\",\"Brace your core and stand or kneel tall.\",\"Pull the handle toward your torso, driving your elbow back.\",\"Squeeze your shoulder blade at the end.\",\"Return slowly, then switch arms.\"],\"img\":\"6510.webp\",\"gif\":\"6510.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row from a high cable, pulling toward your torso to train the upper back and lats.\"},{\"id\":\"7587\",\"n\":\"cable single arm high row with chest support\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\",\"rhomboids\"],\"st\":[\"Set a handle on a high pulley and lean your chest against the support.\",\"Grab the handle with one hand and let your arm extend.\",\"Pull your elbow back and down toward your hip.\",\"Squeeze your shoulder blade at the end of the pull.\",\"Return slowly to full extension, finish your reps, then switch arms.\"],\"img\":\"7587.webp\",\"gif\":\"7587.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row from a high pulley while your chest rests on a pad. The support lets you focus on the upper back without cheating.\"},{\"id\":\"6511\",\"n\":\"cable single arm high scapular row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Set a cable high and hold the handle with one hand.\",\"Stand tall with your core braced.\",\"Pull your shoulder blade back and down, bending the elbow slightly.\",\"Squeeze at the end.\",\"Release slowly, then switch arms.\"],\"img\":\"6511.webp\",\"gif\":\"6511.mp4\",\"cat\":\"strength\",\"desc\":\"A high cable row focused on moving your shoulder blade, building control in your upper back.\"},{\"id\":\"8901\",\"n\":\"cable single arm lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand side-on to the low cable and hold the handle with the far hand.\",\"Keep a slight bend in your elbow.\",\"Raise your arm out to the side up to shoulder height.\",\"Pause briefly at the top.\",\"Lower slowly against the cable.\",\"Avoid leaning or swinging, then switch arms.\"],\"img\":\"8901.webp\",\"gif\":\"8901.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting one arm out to the side against a cable keeps constant tension on the side delt. It builds shoulder width.\"},{\"id\":\"10437\",\"n\":\"cable single arm low row (with rope)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\",\"forearms\"],\"st\":[\"Attach a rope to a low pulley and sit facing the stack with your feet braced.\",\"Hold the rope in one hand with your arm extended.\",\"Pull your elbow back along your side, squeezing your shoulder blade.\",\"Pause, then let the arm extend slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"10437.webp\",\"gif\":\"10437.mp4\",\"cat\":\"strength\",\"desc\":\"A one-armed seated row with a rope handle on a low pulley. It works the lats and upper back one side at a time.\"},{\"id\":\"6512\",\"n\":\"cable single arm low scapular row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Set a cable low and hold the handle with one hand.\",\"Hinge slightly forward with a flat back.\",\"Pull your shoulder blade back toward your spine.\",\"Squeeze for a second.\",\"Return slowly, then switch arms.\"],\"img\":\"6512.webp\",\"gif\":\"6512.mp4\",\"cat\":\"strength\",\"desc\":\"A low cable row that emphasises the shoulder blade, training the muscles between and around it.\"},{\"id\":\"5943\",\"n\":\"cable single arm neutral grip front raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Stand facing away from a low pulley and hold the handle with a neutral grip.\",\"Keep your arm nearly straight and your core braced.\",\"Raise your arm forward to about shoulder height.\",\"Pause briefly, then lower slowly.\",\"Finish your reps and switch arms.\"],\"img\":\"5943.webp\",\"gif\":\"5943.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable front raise with a palm-in grip, giving steady tension to the front of the shoulder.\"},{\"id\":\"11263\",\"n\":\"cable single arm row with rotation v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"obliques\"],\"st\":[\"Stand facing a cable at chest height with a single handle in one hand.\",\"Take a staggered stance and brace your core.\",\"Row the handle to your ribs while rotating your torso slightly.\",\"Squeeze your back at the end.\",\"Return slowly, finish your reps, then switch arms.\"],\"img\":\"11263.webp\",\"gif\":\"11263.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row that adds a torso rotation. It trains the back and the twisting muscles of the core.\"},{\"id\":\"5033\",\"n\":\"cable single arm triceps pushdown (rope attachment)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Attach a rope to a high pulley and grip it with one hand.\",\"Keep your elbow tucked at your side.\",\"Press the rope down until your arm is straight, turning the end out slightly.\",\"Squeeze your triceps.\",\"Return slowly, then switch arms.\"],\"img\":\"5033.webp\",\"gif\":\"5033.mp4\",\"cat\":\"strength\",\"desc\":\"One-arm pushdown with a rope on a high cable. The rope lets you spread the ends at the bottom for a strong triceps squeeze.\",\"fv\":\"7399\"},{\"id\":\"9875\",\"n\":\"cable sitting bench single arm twisting row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Sit on a bench facing a low cable with your feet braced and take the handle in one hand.\",\"Sit tall with your arm extended and your torso turned slightly toward the cable.\",\"Pull the handle back while rotating your torso and wrist toward your hip.\",\"Squeeze your shoulder blade toward your spine at the end.\",\"Return slowly with your arm extended and your torso rotating back.\",\"Keep your chest up, then switch sides after your reps.\"],\"img\":\"9875.webp\",\"gif\":\"9875.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm cable row where you rotate the torso and wrist as you pull. It works the lats and mid back through a longer range.\"},{\"id\":\"4106\",\"n\":\"cable split stance horizontal pallof press\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Set the cable at chest height and stand sideways in a split stance.\",\"Hold the handle at your chest with both hands.\",\"Press the handle straight out in front of you.\",\"Hold for a second without letting your torso twist.\",\"Return the handle to your chest, then switch sides.\"],\"img\":\"4106.webp\",\"gif\":\"4106.mp4\",\"cat\":\"strength\",\"desc\":\"An anti-rotation press from a split stance that teaches your core to resist twisting.\"},{\"id\":\"7564\",\"n\":\"cable split stance single arm row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Stand in a split stance facing a low cable.\",\"Grab the handle with one hand.\",\"Row to your hip, squeezing the shoulder blade.\",\"Keep your torso steady.\",\"Return slowly and switch sides.\"],\"img\":\"7564.webp\",\"gif\":\"7564.mp4\",\"cat\":\"strength\",\"desc\":\"Single-arm cable row in a split stance for stable pulling.\"},{\"id\":\"11268\",\"n\":\"cable squat v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a cable handle at your chest and stand with feet shoulder width.\",\"Brace your core and keep your chest up.\",\"Sit down and back until your thighs are about parallel.\",\"Keep your knees tracking over your toes.\",\"Drive through your heels to stand.\"],\"img\":\"11268.webp\",\"gif\":\"11268.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a cable at the chest. The cable adds load and encourages an upright torso.\"},{\"id\":\"2758\",\"n\":\"cable stand up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold the cable handle at your chest and sit back into a deep squat.\",\"Keep your chest tall.\",\"Push through your heels to stand fully.\",\"Squeeze your glutes at the top.\",\"Lower with control.\"],\"img\":\"2758.webp\",\"gif\":\"2758.mp4\",\"cat\":\"strength\",\"desc\":\"Rising from a low squat against cable tension to train the glutes and legs.\"},{\"id\":\"4374\",\"n\":\"cable standing alternate low fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\"],\"st\":[\"Stand between two low pulleys holding the handles.\",\"Take a small step forward with a slight lean.\",\"Sweep one arm up and across toward the center of your chest.\",\"Return slowly.\",\"Alternate sides.\"],\"img\":\"4374.webp\",\"gif\":\"4374.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable fly from a low pulley, sweeping the arms up and across one at a time. It trains the upper chest.\"},{\"id\":\"11274\",\"n\":\"cable standing alternating diagonal chest press v. 3\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Stand in a staggered stance holding a high cable handle in each hand.\",\"Brace your core.\",\"Press one handle forward and down diagonally.\",\"Return slowly and press with the other arm.\",\"Alternate for the set without twisting your hips.\"],\"img\":\"11274.webp\",\"gif\":\"11274.mp4\",\"cat\":\"strength\",\"desc\":\"A standing diagonal cable press done one arm at a time. It trains the chest and challenges your core.\"},{\"id\":\"6367\",\"n\":\"cable standing back wrist curl v. 2\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand with your back to a low cable and hold the handle behind you.\",\"Keep your elbows tucked and your chest up.\",\"Curl your wrists to pull the handle upward.\",\"Squeeze at the top.\",\"Lower with control and repeat.\"],\"img\":\"6367.webp\",\"gif\":\"6367.mp4\",\"cat\":\"strength\",\"desc\":\"A standing wrist curl with a low cable behind you, giving steady tension on your forearm flexors.\"},{\"id\":\"11261\",\"n\":\"cable standing biceps curl (rope attachment) v. 3\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach a rope to a low pulley and hold it with palms facing each other.\",\"Stand tall with your elbows at your sides.\",\"Curl the rope up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly without swinging your body.\"],\"img\":\"11261.webp\",\"gif\":\"11261.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with a rope on a low cable. The rope lets you turn your hands at the top for a stronger squeeze.\"},{\"id\":\"3068\",\"n\":\"cable standing biceps curl (with rope)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach a rope to a low pulley and hold an end in each hand.\",\"Stand tall with elbows by your sides.\",\"Curl the rope up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower under control without swinging.\"],\"img\":\"3068.webp\",\"gif\":\"3068.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable curl with a rope for constant tension on the biceps.\"},{\"id\":\"11272\",\"n\":\"cable standing biceps curl to arnold press v. 3\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"triceps\",\"upper chest\",\"forearms\"],\"st\":[\"Hold low cable handles, palms forward, arms down.\",\"Curl the handles up to your shoulders.\",\"Rotate your palms inward as you start to press.\",\"Press overhead, turning your palms forward.\",\"Reverse the move and lower under control.\"],\"img\":\"11272.webp\",\"gif\":\"11272.mp4\",\"cat\":\"strength\",\"desc\":\"A combo of a biceps curl flowing into an Arnold press with cables. It works arms and shoulders in one fluid move.\"},{\"id\":\"3359\",\"n\":\"cable standing chest press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Set the cables at chest height and hold a handle in each hand.\",\"Step forward into a split stance.\",\"Press the handles forward until your arms are straight.\",\"Squeeze your chest at the end.\",\"Return slowly with control.\"],\"img\":\"3359.webp\",\"gif\":\"3359.mp4\",\"cat\":\"strength\",\"desc\":\"A standing press with cables that trains the chest while your core keeps you steady.\",\"fv\":\"1066\"},{\"id\":\"5179\",\"n\":\"cable standing close grip row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Attach a close grip handle to a cable at chest height and step back.\",\"Stand with a slight knee bend and a braced core.\",\"Pull the handle toward your lower ribs, elbows close to your body.\",\"Squeeze your shoulder blades together.\",\"Return slowly until your arms are straight.\"],\"img\":\"5179.webp\",\"gif\":\"5179.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable row with a close grip. It trains your lats and mid back while challenging posture.\"},{\"id\":\"3363\",\"n\":\"cable standing close press\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Set the cable at chest height and hold the handle with a narrow grip.\",\"Stand in a split stance, core tight.\",\"Press forward until your arms are straight.\",\"Keep your elbows tucked in.\",\"Return slowly to the start.\"],\"img\":\"3363.webp\",\"gif\":\"3363.mp4\",\"cat\":\"strength\",\"desc\":\"A standing close grip cable press that focuses on the triceps.\"},{\"id\":\"8141\",\"n\":\"cable standing crossover\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Set the pulleys at a high position and grab a handle in each hand.\",\"Step forward with a slight lean.\",\"Bring your hands together in a wide arc.\",\"Squeeze your chest as your hands cross.\",\"Return slowly to a stretch.\"],\"img\":\"8141.webp\",\"gif\":\"8141.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable fly where your hands cross in front of the chest. It focuses on squeezing the pecs.\"},{\"id\":\"5528\",\"n\":\"cable standing crossover overhead tricep extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set two high pulleys with handles and face away from the stack.\",\"Hold the handles overhead with elbows bent.\",\"Cross your hands as you straighten your arms.\",\"Pause, then return slowly.\",\"Keep your elbows pointing forward.\"],\"img\":\"5528.webp\",\"gif\":\"5528.mp4\",\"cat\":\"strength\",\"desc\":\"Overhead triceps extension on crossed cables for a strong stretch and squeeze.\"},{\"id\":\"5609\",\"n\":\"cable standing face pull\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Set a cable at upper chest height with a handle.\",\"Stand tall and pull toward your face.\",\"Spread your hands apart at the end.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"5609.webp\",\"gif\":\"5609.mp4\",\"cat\":\"strength\",\"desc\":\"Cable face pull to build the rear delts and strengthen the upper back.\"},{\"id\":\"5656\",\"n\":\"cable standing face pull (with rope)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Attach a rope to a high pulley.\",\"Grab it with both hands.\",\"Pull toward your face, splitting the rope.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"5656.webp\",\"gif\":\"5656.mp4\",\"cat\":\"strength\",\"desc\":\"Face pull with a rope attachment to hit the rear delts.\"},{\"id\":\"11250\",\"n\":\"cable standing fly v. 3\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\"],\"st\":[\"Set both pulleys at shoulder height and hold a handle in each hand.\",\"Step forward with a staggered stance and lean slightly.\",\"With soft elbows, bring your hands together in front of your chest.\",\"Squeeze your chest for a moment.\",\"Open your arms slowly until you feel a stretch.\"],\"img\":\"11250.webp\",\"gif\":\"11250.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable fly that trains your chest through a wide hugging arc. The constant cable tension keeps the muscle working.\"},{\"id\":\"11277\",\"n\":\"cable standing front raise v. 3\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Stand facing away from a low pulley, holding the handle between your legs.\",\"Keep your core tight and arm nearly straight.\",\"Raise the handle forward to shoulder height.\",\"Pause briefly.\",\"Lower slowly, finish your reps, then switch arms.\"],\"img\":\"11277.webp\",\"gif\":\"11277.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise using a low cable. It builds the front of the shoulders with steady tension.\"},{\"id\":\"4014\",\"n\":\"cable standing front raise variation\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"forearms\"],\"st\":[\"Stand facing away from a low pulley.\",\"Hold the handle with a slight elbow bend.\",\"Raise the arm to eye level.\",\"Lower slowly.\",\"Switch arms.\"],\"img\":\"4014.webp\",\"gif\":\"4014.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable front raise. It targets the front delts with steady tension.\"},{\"id\":\"11051\",\"n\":\"cable standing high cross neutral grip triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Set both pulleys high and stand in the middle, holding the handles with palms facing in.\",\"Cross your hands in front of your chest with elbows tucked to your sides.\",\"Press the handles down and out until your arms are straight.\",\"Squeeze your triceps for a moment.\",\"Let the handles rise back slowly without moving your elbows.\"],\"img\":\"11051.webp\",\"gif\":\"11051.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps pushdown with the cable set high and the handles crossed, using a neutral grip. It isolates the back of the arm.\"},{\"id\":\"3719\",\"n\":\"cable standing high cross triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Set a cable to a high position and hold the handle with one hand.\",\"Stand facing the machine with your elbow bent and tucked.\",\"Press the handle down and across your body until your arm is straight.\",\"Return slowly to the start.\",\"Finish your reps, then switch arms.\"],\"img\":\"3719.webp\",\"gif\":\"3719.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable pushdown from a high pulley, crossing the body to isolate the triceps.\"},{\"id\":\"11266\",\"n\":\"cable standing hip abduction v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Attach an ankle strap to a low pulley on the near side and hold something for balance.\",\"Stand tall with your core tight.\",\"Lift your outside leg out to the side.\",\"Pause at the top without leaning.\",\"Return slowly, finish your reps, then switch sides.\"],\"img\":\"11266.webp\",\"gif\":\"11266.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable leg raise to the side. It strengthens the outer hip.\"},{\"id\":\"11267\",\"n\":\"cable standing hip adduction v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Attach an ankle strap to a low pulley on the far side and hold something for balance.\",\"Stand tall with your core tight.\",\"Sweep your working leg across in front of the other leg.\",\"Squeeze your inner thigh.\",\"Return slowly, finish your reps, then switch sides.\"],\"img\":\"11267.webp\",\"gif\":\"11267.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable move where you pull your leg across your body. It works the inner thigh.\"},{\"id\":\"0880\",\"n\":\"cable standing hip extension v. 2\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Attach an ankle strap to a low cable and stand facing the stack.\",\"Hold the frame for support.\",\"Keep your core tight and kick the strapped leg back.\",\"Squeeze your glute at the top.\",\"Return slowly, then switch legs after your reps.\"],\"img\":\"0880.webp\",\"gif\":\"0880.mp4\",\"cat\":\"strength\",\"desc\":\"A cable kickback for the glutes with an ankle strap. This is a second version of the move.\"},{\"id\":\"11259\",\"n\":\"cable standing hip extension v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Attach an ankle strap to a low pulley and stand facing the machine, holding on for balance.\",\"Keep your core tight and your torso upright.\",\"Push your working leg straight back.\",\"Squeeze your glute at the top without arching.\",\"Return slowly, finish your reps, then switch legs.\"],\"img\":\"11259.webp\",\"gif\":\"11259.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable kickback that targets the glutes. It teaches you to extend the hip without arching your back.\"},{\"id\":\"8191\",\"n\":\"cable standing hip flexion\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"quadriceps\"],\"st\":[\"Attach an ankle strap and face away from a low cable.\",\"Hold a support for balance.\",\"Lift your knee in front of you.\",\"Pause at the top.\",\"Lower slowly. Switch legs after your set.\"],\"img\":\"8191.webp\",\"gif\":\"8191.mp4\",\"cat\":\"strength\",\"desc\":\"A standing leg raise to the front against cable resistance. It trains the hip flexors and front thigh.\"},{\"id\":\"11265\",\"n\":\"cable standing hip flexion v. 3\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Attach an ankle strap to a low pulley, face away from the machine, and hold on for balance.\",\"Stand tall with your core braced.\",\"Drive your working knee forward and up.\",\"Pause at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"11265.webp\",\"gif\":\"11265.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable knee raise that trains the hip flexors. It helps lifting your leg with control.\"},{\"id\":\"2744\",\"n\":\"cable standing hip thrust\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Attach a belt or strap to a low cable and stand facing away from the stack.\",\"Hold the cable at your hips with feet shoulder width apart.\",\"Hinge slightly, then thrust your hips forward.\",\"Squeeze your glutes at the top.\",\"Return slowly and keep your ribs down.\"],\"img\":\"2744.webp\",\"gif\":\"2744.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hip thrust against cable resistance, training hip extension and the glutes.\"},{\"id\":\"8880\",\"n\":\"cable standing jab\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand facing away from the cable with the handle at chest height in one hand.\",\"Take a staggered stance and keep your core tight.\",\"Punch the handle forward quickly, rotating your hips a little.\",\"Stop just before your elbow locks out.\",\"Return the hand with control to your chin.\",\"Do all reps, then switch arms.\"],\"img\":\"8880.webp\",\"gif\":\"8880.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick punch thrown against cable resistance builds fast, explosive pushing power. It also trains the trunk to resist twisting.\"},{\"id\":\"8900\",\"n\":\"cable standing jab v. 2\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand facing away from the cable and hold the handle at chest height.\",\"Step into a staggered stance and brace your core.\",\"Punch forward fast and rotate your torso slightly.\",\"Stop short of locking out your elbow.\",\"Pull the hand back under control.\",\"Repeat, then switch arms.\"],\"img\":\"8900.webp\",\"gif\":\"8900.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A second variation of the cable punch, built for quick power in the pushing muscles. Your trunk works to stay stable.\"},{\"id\":\"1229\",\"n\":\"cable standing lat pushdown (rope equipment)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"rear deltoids\",\"core\"],\"st\":[\"Attach a rope to a high pulley and stand facing it, hinging slightly forward.\",\"Grab the rope with straight arms.\",\"Push the rope down to your thighs, keeping your arms nearly straight.\",\"Squeeze your lats at the bottom.\",\"Let the rope rise slowly to shoulder height.\"],\"img\":\"1229.webp\",\"gif\":\"1229.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pushdown with a rope on a high cable. It isolates the lats with almost no help from the arms.\"},{\"id\":\"1547\",\"n\":\"cable standing leg curl\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Attach an ankle cuff to a low pulley and strap it around one ankle.\",\"Stand facing the machine and hold on for balance, with the working leg slightly behind you.\",\"Bend your knee and curl your heel toward your glutes.\",\"Squeeze at the top without swinging your torso.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"1547.webp\",\"gif\":\"1547.mp4\",\"cat\":\"strength\",\"desc\":\"Standing on one leg, you curl the other against a low cable. It isolates the hamstrings one side at a time.\"},{\"id\":\"7416\",\"n\":\"cable standing neutral grip fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Set the pulleys at chest height and grab the handles.\",\"Step forward with a staggered stance and a slight elbow bend.\",\"Bring your hands together in front of your chest.\",\"Squeeze your pecs for a moment.\",\"Return slowly until you feel a stretch.\"],\"img\":\"7416.webp\",\"gif\":\"7416.mp4\",\"cat\":\"strength\",\"desc\":\"Standing cable fly with palms facing each other to squeeze the chest.\"},{\"id\":\"11436\",\"n\":\"cable standing neutral grip overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Attach a rope or neutral handle to a low pulley and face away from the stack.\",\"Hold it overhead with elbows bent and pointing forward, one foot slightly ahead.\",\"Keep your upper arms close to your ears and your ribs down.\",\"Extend your elbows until your arms are straight overhead.\",\"Lower slowly back to a deep stretch and repeat.\"],\"img\":\"11436.webp\",\"gif\":\"11436.mp4\",\"cat\":\"strength\",\"desc\":\"Overhead cable extension with a neutral grip that loads the long head of the triceps through a deep stretch.\",\"fv\":\"11435\"},{\"id\":\"5524\",\"n\":\"cable standing one arm face pull\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Set a cable at upper chest height with a single handle.\",\"Stand tall and grab the handle with one hand.\",\"Pull toward your face, elbow high and out.\",\"Rotate your hand back slightly at the end.\",\"Return slowly and switch sides after the set.\"],\"img\":\"5524.webp\",\"gif\":\"5524.mp4\",\"cat\":\"strength\",\"desc\":\"One-arm face pull on a cable that trains the rear delts and rotator cuff for healthy shoulders.\"},{\"id\":\"5370\",\"n\":\"cable standing one arm hammer curl (with rope)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Attach the rope to a low pulley and hold it with one hand, thumb up.\",\"Stand tall with your elbow tucked in.\",\"Curl the rope toward your shoulder.\",\"Squeeze the top for a second.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"5370.webp\",\"gif\":\"5370.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm hammer curl on a cable using a rope. Hits the biceps and forearm muscles with a neutral grip.\"},{\"id\":\"1227\",\"n\":\"cable standing one arm triceps pushdown (overhand grip)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"core\"],\"st\":[\"Attach a handle to a high pulley and stand facing it.\",\"Hold the handle with an overhand grip and tuck your elbow to your side.\",\"Push down until your arm is fully straight.\",\"Squeeze your triceps, then let the handle rise slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"1227.webp\",\"gif\":\"1227.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm pushdown with an overhand grip. It isolates one triceps at a time.\"},{\"id\":\"11258\",\"n\":\"cable standing push pull v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"biceps\",\"core\"],\"st\":[\"Stand in a staggered stance between two cables, one handle in each hand.\",\"Brace your core and keep your hips square.\",\"Press one handle forward while pulling the other back toward your ribs.\",\"Reverse the roles slowly.\",\"Alternate sides for the set.\"],\"img\":\"11258.webp\",\"gif\":\"11258.mp4\",\"cat\":\"strength\",\"desc\":\"A standing move with one arm pressing while the other rows. It trains pushing and pulling together and tests your core.\"},{\"id\":\"3232\",\"n\":\"cable standing rear delt horizontal row (with rope)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\",\"trapezius\"],\"st\":[\"Attach a rope to a cable at chest height.\",\"Hold the ends and step back.\",\"Stand with your knees slightly bent.\",\"Pull the rope toward your face with your elbows high and wide.\",\"Squeeze your rear shoulders.\",\"Return slowly.\"],\"img\":\"3232.webp\",\"gif\":\"3232.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable row with a rope that pulls the elbows wide. It targets the rear delts.\"},{\"id\":\"1608\",\"n\":\"cable standing reverse curl (sz bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach an SZ bar to a low pulley and grip it overhand with your hands shoulder-width apart.\",\"Stand tall with your elbows pinned to your sides.\",\"Curl the bar up while keeping your wrists straight.\",\"Pause at the top.\",\"Lower slowly and keep your torso still.\"],\"img\":\"1608.webp\",\"gif\":\"1608.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with an overhand grip on a cable SZ bar. It targets the brachialis and forearms.\"},{\"id\":\"11254\",\"n\":\"cable standing reverse fly v. 3\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Set the pulleys at shoulder height and hold the opposite handles, arms crossed.\",\"Stand tall with soft elbows.\",\"Pull your hands apart and back in a wide arc.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the crossed start.\"],\"img\":\"11254.webp\",\"gif\":\"11254.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable reverse fly aimed at the rear shoulders and upper back. It helps balance all the pressing you do.\"},{\"id\":\"2954\",\"n\":\"cable standing reverse grip curl (straight bar)\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"wrist extensors\"],\"st\":[\"Stand facing a low cable with a straight bar in an overhand grip.\",\"Keep your elbows at your sides.\",\"Curl the bar up toward your shoulders without swinging.\",\"Squeeze at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"2954.webp\",\"gif\":\"2954.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl with an overhand grip on a straight cable bar. It targets the forearms and brachialis.\",\"fv\":\"2953\"},{\"id\":\"5090\",\"n\":\"cable standing row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Set a cable at chest height and hold the handle, stepping back until there is tension.\",\"Stand tall with your core braced.\",\"Pull the handle toward your ribs, driving your elbows back.\",\"Squeeze your shoulder blades together.\",\"Return slowly until your arms are straight.\"],\"img\":\"5090.webp\",\"gif\":\"5090.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a cable handle toward your torso from a standing position. It trains the mid-back and teaches a strong, upright posture.\"},{\"id\":\"11278\",\"n\":\"cable standing side bend v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Stand side-on to a low pulley and hold the handle at your side.\",\"Keep your chest tall.\",\"Bend sideways away from the machine.\",\"Contract your obliques to return upright.\",\"Finish your reps, then switch sides.\"],\"img\":\"11278.webp\",\"gif\":\"11278.mp4\",\"cat\":\"strength\",\"desc\":\"A standing side bend that loads the obliques with a cable. It trains your core to resist and control sideways motion.\"},{\"id\":\"6219\",\"n\":\"cable standing single arm fly\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Stand sideways to a cable with the handle at chest height.\",\"Step forward for balance.\",\"Pull the handle across your body.\",\"Squeeze your chest.\",\"Return slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"6219.webp\",\"gif\":\"6219.mp4\",\"cat\":\"strength\",\"desc\":\"A standing fly on a cable, one arm at a time. It builds the chest.\"},{\"id\":\"8614\",\"n\":\"cable standing single arm horizontal triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set the cable at chest height and stand facing away holding the handle by your shoulder.\",\"Take a split stance for balance.\",\"Extend your arm forward until it is straight.\",\"Return slowly while keeping the elbow still.\",\"Finish the reps, then switch arms.\"],\"img\":\"8614.webp\",\"gif\":\"8614.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable pushdown in a horizontal path, isolating the triceps.\"},{\"id\":\"11279\",\"n\":\"cable standing single arm overhead triceps extension v. 3\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold a handle from a low pulley overhead, elbow bent, with your upper arm close to your head.\",\"Brace your core.\",\"Straighten your arm overhead.\",\"Squeeze your triceps at the top.\",\"Lower slowly, finish your reps, then switch arms.\"],\"img\":\"11279.webp\",\"gif\":\"11279.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead triceps extension with a cable. The overhead position stretches and works the long head of the triceps.\"},{\"id\":\"11764\",\"n\":\"cable standing single arm supinated grip chest press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"biceps\",\"core\"],\"st\":[\"Set a cable at chest height and hold the handle with a palm-up grip.\",\"Stand facing away in a staggered stance.\",\"Press the handle forward until your arm is straight.\",\"Keep your torso still and resist twisting.\",\"Return slowly and switch arms after your reps.\"],\"img\":\"11764.webp\",\"gif\":\"11764.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm press with a palm-up grip that works the chest and tests core stability.\"},{\"id\":\"6776\",\"n\":\"cable standing single delt row\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Set a cable at chest height and grab the handle with one hand.\",\"Stand with feet staggered and your torso slightly braced.\",\"Pull the handle toward you with your elbow flared out.\",\"Squeeze the rear shoulder at the end.\",\"Extend slowly, then switch arms after your reps.\"],\"img\":\"6776.webp\",\"gif\":\"6776.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable row with a high elbow. It focuses on the rear delts and upper back.\"},{\"id\":\"7744\",\"n\":\"cable standing supinated face pull (with rope)\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"biceps\",\"rotator cuff\"],\"st\":[\"Set the rope at face height and grip it with your palms facing up.\",\"Step back and stand tall.\",\"Pull the rope toward your face, elbows leading.\",\"Squeeze your shoulder blades at the end.\",\"Return slowly to the start.\"],\"img\":\"7744.webp\",\"gif\":\"7744.mp4\",\"cat\":\"strength\",\"desc\":\"A standing face pull using a rope with an underhand grip. It trains the rear shoulders and upper back, and is gentle on the wrists.\"},{\"id\":\"11271\",\"n\":\"cable standing torso twist v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Stand side-on to a cable set at chest height and hold the handle with both hands.\",\"Keep your arms straight and feet planted.\",\"Rotate your torso away from the machine.\",\"Pause, then return slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"11271.webp\",\"gif\":\"11271.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable rotation that trains the obliques. Turn through your torso with your arms staying in front.\"},{\"id\":\"6360\",\"n\":\"cable standing wrist curl\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Face a low cable pulley and grab the handle with an underhand grip.\",\"Step back and let your arms hang with elbows tucked.\",\"Curl your wrists upward against the cable.\",\"Squeeze at the top.\",\"Lower with control and repeat.\"],\"img\":\"6360.webp\",\"gif\":\"6360.mp4\",\"cat\":\"strength\",\"desc\":\"Wrist curls using a low cable for steady tension through the whole range, working the inside of your forearms.\"},{\"id\":\"6363\",\"n\":\"cable standing wrist reverse curl\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Face a low cable and grab the handle with an overhand grip.\",\"Step back and let your arms hang with elbows close to your sides.\",\"Extend your wrists to pull the handle upward.\",\"Hold for a second.\",\"Lower under control and repeat.\"],\"img\":\"6363.webp\",\"gif\":\"6363.mp4\",\"cat\":\"strength\",\"desc\":\"An overhand wrist curl on a low cable that works the top of your forearms with constant tension.\"},{\"id\":\"6269\",\"n\":\"cable standing wrist roll\",\"bp\":\"lower arms\",\"eq\":\"cable\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand facing the cable machine.\",\"Hold the handle with straight arms.\",\"Roll your wrists up.\",\"Roll them back down.\",\"Repeat smoothly.\",\"Keep your arms still.\"],\"img\":\"6269.webp\",\"gif\":\"6269.mp4\",\"cat\":\"strength\",\"desc\":\"A standing wrist roll with a cable handle. It builds forearm strength.\"},{\"id\":\"8899\",\"n\":\"cable standing y raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand facing the low cable with a handle in each hand or one handle at a time.\",\"Start with your arms low and a slight bend in your elbows.\",\"Lift your arms up and out to form a Y shape.\",\"Keep your thumbs pointing up and your ribs down.\",\"Lower slowly back to the start.\",\"Avoid shrugging toward your ears.\"],\"img\":\"8899.webp\",\"gif\":\"8899.mp4\",\"cat\":\"strength\",\"desc\":\"Raising the arms in a Y shape against cable tension works the lower traps and shoulders. It supports healthy overhead movement.\"},{\"id\":\"10048\",\"n\":\"cable step up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a box or bench with a cable handle in your hands.\",\"Place one foot fully on the box.\",\"Push through that heel to step up.\",\"Stand tall on top of the box.\",\"Step back down with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"10048.webp\",\"gif\":\"10048.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with cable resistance that adds load to the legs and hips.\"},{\"id\":\"2836\",\"n\":\"cable stiff leg deadlift from stepbox\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on a step box facing a low cable and hold the handle.\",\"Keep your knees nearly straight.\",\"Hinge at the hips and lower the handle.\",\"Keep your back flat.\",\"Squeeze your glutes to stand.\"],\"img\":\"2836.webp\",\"gif\":\"2836.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-leg hinge from a raised box for a longer range on the hamstrings.\"},{\"id\":\"8297\",\"n\":\"cable straight arm pulldown (with rope attachment)\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"rear deltoids\"],\"st\":[\"Set a rope on a high pulley and stand facing it.\",\"Hinge forward slightly with arms extended.\",\"Pull the rope down to your thighs.\",\"Spread the rope at the bottom.\",\"Return slowly.\"],\"img\":\"8297.webp\",\"gif\":\"8297.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pulldown using a rope. It isolates the lats with no help from the arms.\"},{\"id\":\"6036\",\"n\":\"cable straight arm pulldown v. 2\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\"],\"st\":[\"Stand facing a high cable and grab the bar with straight arms.\",\"Hinge slightly at the hips.\",\"Pull the bar down in an arc to your thighs.\",\"Squeeze your lats.\",\"Return slowly to the start.\"],\"img\":\"6036.webp\",\"gif\":\"6036.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pulldown variation that isolates the lats by keeping the elbows nearly straight.\"},{\"id\":\"1067\",\"n\":\"cable straight arm pulldown v. 3\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"rear deltoids\"],\"st\":[\"Stand facing a high pulley and grip the bar.\",\"Hinge slightly forward.\",\"Pull the bar down to your thighs.\",\"Squeeze your lats.\",\"Return slowly.\"],\"img\":\"1067.webp\",\"gif\":\"1067.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a cable down with straight arms. It isolates the lats.\"},{\"id\":\"8083\",\"n\":\"cable straight leg diagonal kickback\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Attach an ankle cuff to a low cable pulley and strap it to one ankle.\",\"Face the machine and hold the frame for balance.\",\"Keep your leg straight and kick it back and slightly out to the side.\",\"Squeeze your glute at the top without leaning forward.\",\"Return slowly without letting the weight stack touch down.\",\"Finish your reps, then switch legs.\"],\"img\":\"8083.webp\",\"gif\":\"8083.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable kickback with a straight leg, driven back and slightly out to the side. It isolates the glutes.\"},{\"id\":\"2324\",\"n\":\"cable straight legs pull through (with rope)\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Attach a rope to a low pulley and stand facing away from the stack.\",\"Reach through your legs and grab the rope, then step forward to add tension.\",\"Keep your legs nearly straight and hinge forward at the hips.\",\"Drive your hips forward to stand tall while the rope passes between your legs.\",\"Squeeze your glutes at the top.\",\"Hinge back with control and repeat.\"],\"img\":\"2324.webp\",\"gif\":\"2324.mp4\",\"cat\":\"strength\",\"desc\":\"A cable hinge with straight legs that trains the glutes and hamstrings.\"},{\"id\":\"1800\",\"n\":\"cable suspension back stretch\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"forearms\"],\"st\":[\"Hold the cable attachment or handles with both hands at about chest height.\",\"Lean back with straight arms and sit your hips back until you feel your back lengthen.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1800.webp\",\"gif\":\"1800.mp4\",\"cat\":\"stretching\",\"desc\":\"Holding a cable attachment, you lean back and let your weight stretch your lats and back. Good for opening up the upper body.\"},{\"id\":\"1605\",\"n\":\"cable triceps pushdown (sz bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Attach an SZ bar to a high pulley and grip it with your hands shoulder-width apart.\",\"Pin your elbows to your sides.\",\"Push the bar down until your arms are fully straight.\",\"Squeeze your triceps for a moment.\",\"Let the bar rise slowly until your forearms are just above parallel.\"],\"img\":\"1605.webp\",\"gif\":\"1605.mp4\",\"cat\":\"strength\",\"desc\":\"A cable pushdown using an SZ bar, a staple for building the back of the arm.\"},{\"id\":\"2249\",\"n\":\"cable triceps pushdown (v bar)\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"core\"],\"st\":[\"Attach a V bar to a high pulley and stand facing the stack.\",\"Grip the bar with your elbows pinned to your sides.\",\"Push the bar down until your arms are fully straight.\",\"Squeeze your triceps for a moment at the bottom.\",\"Let the bar rise until your forearms are just past parallel.\",\"Keep your upper arms still throughout the set.\"],\"img\":\"2249.webp\",\"gif\":\"2249.mp4\",\"cat\":\"strength\",\"desc\":\"A cable pushdown with a V bar that isolates the back of the upper arm.\"},{\"id\":\"4355\",\"n\":\"cable triceps pushdown (v bar) v. 2\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\"],\"st\":[\"Stand facing a high pulley and grip the V bar with elbows at your sides.\",\"Keep your torso upright and slightly forward.\",\"Push the bar down until your arms are straight.\",\"Squeeze your triceps for a moment.\",\"Let the bar rise slowly, elbows still.\"],\"img\":\"4355.webp\",\"gif\":\"4355.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps pushdown using a V bar on a high cable, a classic for the back of the arms.\"},{\"id\":\"3920\",\"n\":\"cable triceps pushdown on floor\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"shoulders\",\"core\"],\"st\":[\"Set a cable at a low or mid position and sit on the floor facing it.\",\"Hold the handle with elbows tucked at your sides.\",\"Press the handle down until your arms are straight.\",\"Squeeze your triceps.\",\"Return slowly to the start.\",\"Keep your upper arms still.\"],\"img\":\"3920.webp\",\"gif\":\"3920.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps pushdown performed while sitting or lying on the floor with the cable set low.\"},{\"id\":\"1207\",\"n\":\"cable twist (down up)\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Set the cable pulley low and stand sideways to the machine, holding the handle with both hands.\",\"Start with the handle near your lower hip, arms mostly straight.\",\"Rotate your torso and pull the handle diagonally up across your body.\",\"Pivot your back foot and keep your hips stable.\",\"Return slowly, finish your reps, then switch sides.\"],\"img\":\"1207.webp\",\"gif\":\"1207.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal cable rotation from low to high that trains the obliques and builds rotational strength.\"},{\"id\":\"1208\",\"n\":\"cable twist (up down) v. 2\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Set the cable pulley high and stand sideways to the machine, holding the handle with both hands.\",\"Start with the handle above your shoulder, arms mostly straight.\",\"Rotate your torso and pull the handle diagonally down across your body.\",\"Keep your hips steady and your core braced.\",\"Return slowly, finish your reps, then switch sides.\"],\"img\":\"1208.webp\",\"gif\":\"1208.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal cable rotation from high to low that trains the obliques and builds rotational strength.\"},{\"id\":\"5118\",\"n\":\"cable twist v. 2\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Set a cable at chest height and stand sideways to it.\",\"Hold the handle with both hands in front of your chest.\",\"Rotate your torso away from the cable, arms extended.\",\"Keep your hips facing forward.\",\"Return slowly, then switch sides after your reps.\"],\"img\":\"5118.webp\",\"gif\":\"5118.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your torso against a cable. It strengthens the obliques and builds control of your trunk rotation.\"},{\"id\":\"1069\",\"n\":\"cable twist v. 3\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Stand sideways to the pulley and hold the handle with both hands.\",\"Keep your arms extended.\",\"Rotate your torso away from the stack.\",\"Return slowly.\",\"Switch sides.\"],\"img\":\"1069.webp\",\"gif\":\"1069.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your torso against a cable. It works the obliques.\"},{\"id\":\"1209\",\"n\":\"cable twisting overhead press\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"obliques\",\"core\"],\"st\":[\"Set a cable low and stand sideways, holding the handle at your shoulder.\",\"Brace your core and turn slightly toward the cable.\",\"Press the handle overhead while rotating your torso to face forward.\",\"Lower the handle back to your shoulder with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"1209.webp\",\"gif\":\"1209.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead cable press where you rotate your torso as you push. It works the shoulders and the core together.\",\"fv\":\"2542\"},{\"id\":\"1210\",\"n\":\"cable twisting standing high row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\",\"obliques\"],\"st\":[\"Set a cable at about head height and stand facing it with the handle in one hand.\",\"Take a split stance and lean back slightly.\",\"Pull the handle toward your upper chest, turning your torso as you go.\",\"Squeeze your shoulder blade, then return slowly.\",\"Complete the set and switch sides.\"],\"img\":\"1210.webp\",\"gif\":\"1210.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable row at a high angle with a torso twist. It hits the upper back and rear shoulders.\"},{\"id\":\"1211\",\"n\":\"cable twisting standing one arm chest press\",\"bp\":\"chest\",\"eq\":\"cable\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Set the cable at chest height and stand sideways with the handle in your inside hand.\",\"Take a stable stance and hold the handle at your chest.\",\"Press the handle forward while rotating your torso toward the press.\",\"Return to the start with control.\",\"Complete your reps, then switch sides.\"],\"img\":\"1211.webp\",\"gif\":\"1211.mp4\",\"cat\":\"strength\",\"desc\":\"A standing single-arm cable press with a rotation. It trains the chest and the core's ability to resist and produce twist.\"},{\"id\":\"1212\",\"n\":\"cable twisting standing row\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"obliques\"],\"st\":[\"Set a cable at mid height and stand facing it, holding the handle with one hand.\",\"Stand in a stable stance with a slight lean back.\",\"Pull the handle to your ribs and rotate your torso open.\",\"Squeeze your shoulder blade at the end.\",\"Return slowly, finish your reps, then switch sides.\"],\"img\":\"1212.webp\",\"gif\":\"1212.mp4\",\"cat\":\"strength\",\"desc\":\"A standing cable row where you turn your torso as you pull. It works the back with some added core rotation.\"},{\"id\":\"4838\",\"n\":\"cable unilateral bicep curl\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Attach a handle to a low cable and stand facing the machine.\",\"Hold the handle with one hand, elbow at your side.\",\"Curl the handle toward your shoulder.\",\"Squeeze your biceps at the top.\",\"Lower slowly and switch arms.\"],\"img\":\"4838.webp\",\"gif\":\"4838.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm cable curl that keeps constant tension on the biceps. Train each arm on its own to even out strength.\",\"fv\":\"10776\"},{\"id\":\"10120\",\"n\":\"cable unilateral step up\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Face a box with the cable handle held at your chest or by your side.\",\"Place one foot fully on the box.\",\"Drive through that heel and stand up straight on the box.\",\"Lower your trailing foot back to the floor slowly.\",\"Keep your knee tracking over your toes. Finish the reps, then switch legs.\"],\"img\":\"10120.webp\",\"gif\":\"10120.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg step up with cable resistance that builds leg strength and balance one side at a time.\"},{\"id\":\"1213\",\"n\":\"cable vertical pallof press\",\"bp\":\"waist\",\"eq\":\"cable\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Set a cable at a high or low position and stand sideways to it.\",\"Hold the handle at your chest with both hands.\",\"Press the handle straight up (or down) along a vertical line.\",\"Hold for a second without letting your torso twist.\",\"Return to your chest, finish the set, then switch sides.\"],\"img\":\"1213.webp\",\"gif\":\"1213.mp4\",\"cat\":\"isometric\",\"desc\":\"A cable press performed upward or downward in a vertical line while holding the core still. It trains anti-rotation and shoulder stability.\"},{\"id\":\"2291\",\"n\":\"cable wide grip lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\",\"forearms\"],\"st\":[\"Sit at the pulldown station and secure your thighs under the pads.\",\"Grab the bar with a wide overhand grip.\",\"Lean back slightly and pull the bar down to your upper chest.\",\"Drive your elbows down and back, squeezing your shoulder blades.\",\"Control the bar back up until your arms are fully extended.\",\"Avoid swinging your torso.\"],\"img\":\"2291.webp\",\"gif\":\"2291.mp4\",\"cat\":\"strength\",\"desc\":\"A pulldown with a wide grip that builds the broad muscles of the upper back.\"},{\"id\":\"2544\",\"n\":\"cable wide grip rear pulldown behind neck v. 2\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Sit at the pulldown station with your thighs secured.\",\"Grab the bar with a wide overhand grip.\",\"Lean forward slightly and pull the bar down behind your head to the base of your neck.\",\"Squeeze your shoulder blades together.\",\"Control the bar back up.\",\"Move gently and keep your neck neutral.\"],\"img\":\"2544.webp\",\"gif\":\"2544.mp4\",\"cat\":\"strength\",\"desc\":\"A wide pulldown to the back of the neck that works the lats and upper back.\"},{\"id\":\"4217\",\"n\":\"cable wide neutral grip pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Sit at the pulldown station and lock your thighs under the pads.\",\"Grab the wide neutral-grip handles with straight arms.\",\"Lean back slightly and lift your chest.\",\"Pull the handles down toward your upper chest, driving your elbows down.\",\"Pause, then let the bar rise slowly.\",\"Do not swing your torso.\"],\"img\":\"4217.webp\",\"gif\":\"4217.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown with a wide handle that keeps your palms facing each other. It builds back width with less wrist strain.\"},{\"id\":\"3342\",\"n\":\"cable y raise\",\"bp\":\"shoulders\",\"eq\":\"cable\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"upper back\",\"rotator cuff\"],\"st\":[\"Set the pulleys low and hold a handle in each hand, arms crossed in front.\",\"Stand tall with a slight lean forward.\",\"Raise both arms up and out into a Y shape.\",\"Keep your thumbs pointing up and shoulders down.\",\"Lower slowly to the start.\"],\"img\":\"3342.webp\",\"gif\":\"3342.mp4\",\"cat\":\"strength\",\"desc\":\"A cable raise that moves your arms into a Y shape, building the shoulders and the muscles that stabilise your shoulder blades.\"},{\"id\":\"9878\",\"n\":\"cable zercher squat\",\"bp\":\"upper legs\",\"eq\":\"cable\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\",\"lower back\"],\"st\":[\"Attach a bar or handle to a low cable and hook it in the bends of your elbows, close to your chest.\",\"Stand facing away from the stack with your feet shoulder width apart.\",\"Brace your core and sit down and back until your thighs are about parallel.\",\"Keep your chest tall and your knees tracking over your toes.\",\"Push through your whole foot to stand back up.\",\"Keep your elbows tucked and the load close to your body.\"],\"img\":\"9878.webp\",\"gif\":\"9878.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a low cable in the crook of your elbows in front of you. The front load keeps you upright and works the quads, glutes and core.\"},{\"id\":\"10756\",\"n\":\"calf forward jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall with feet together and knees slightly soft.\",\"Push off the balls of your feet and hop forward a short distance.\",\"Keep your knees nearly straight.\",\"Land softly on the balls of your feet.\",\"Hop back or turn around and repeat.\",\"Stay light and quick through the whole set.\"],\"img\":\"10756.webp\",\"gif\":\"10756.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Small forward hops driven by the calves. They build ankle stiffness and reactive power.\"},{\"id\":\"10751\",\"n\":\"calf jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall.\",\"Keep knees nearly straight.\",\"Jump using your ankles.\",\"Land softly.\",\"Repeat quickly.\"],\"img\":\"10751.webp\",\"gif\":\"10751.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jump using only your calves. It builds explosive lower legs.\"},{\"id\":\"3390\",\"n\":\"calf raise from deficit with chair supported\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand with the balls of your feet on a step edge, holding a chair for balance.\",\"Let your heels drop below the step to stretch your calves.\",\"Rise as high onto your toes as you can.\",\"Pause for a second at the top.\",\"Lower slowly into the deep stretch.\",\"Keep your knees almost straight.\"],\"img\":\"3390.webp\",\"gif\":\"3390.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A calf raise from a raised step with a chair for balance, giving a deeper stretch and fuller range.\"},{\"id\":\"2992\",\"n\":\"calf self massage with barbell\",\"bp\":\"lower legs\",\"eq\":\"barbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\"],\"st\":[\"Sit on the floor with one calf resting on a barbell.\",\"Support yourself with your hands behind you.\",\"Roll your calf slowly back and forth over the bar.\",\"Pause on tender spots for a few breaths.\",\"Switch to the other leg.\"],\"img\":\"2992.webp\",\"gif\":\"2992.mp4\",\"cat\":\"mobility\",\"desc\":\"A self-massage for the calves using a barbell to roll over tight spots.\"},{\"id\":\"10757\",\"n\":\"calf side to side jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall with feet together and knees slightly soft.\",\"Spring off your toes and hop to one side.\",\"Land softly on the balls of your feet.\",\"Immediately hop to the other side.\",\"Keep your chest up and hips level.\",\"Continue alternating for the set.\"],\"img\":\"10757.webp\",\"gif\":\"10757.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Quick lateral hops powered by the calves. They improve ankle strength and foot speed.\"},{\"id\":\"4510\",\"n\":\"calves stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall with your hands on it.\",\"Step one foot back with the heel on the floor.\",\"Bend your front knee and lean forward.\",\"Feel the stretch in the back calf.\",\"Hold for 20-30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"4510.webp\",\"gif\":\"4510.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing wall stretch for the calf muscles. Helps with ankle mobility and tight lower legs.\",\"fv\":\"0937\"},{\"id\":\"1848\",\"n\":\"calves stretch static position\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"hamstrings\",\"ankles\"],\"st\":[\"Stand facing a wall with one foot back and your heel on the floor.\",\"Keep your back leg straight and lean toward the wall.\",\"Press your back heel down until you feel a stretch in the calf.\",\"Keep your hips square and your toes pointing forward.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1848.webp\",\"gif\":\"1848.mp4\",\"cat\":\"stretching\",\"desc\":\"A static calf stretch that lengthens the lower leg muscles and the Achilles area.\"},{\"id\":\"11452\",\"n\":\"calves stretch v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall and place your hands on it at chest height.\",\"Step one foot back with the heel flat on the floor and the toes pointing forward.\",\"Bend the front knee and lean in until you feel the back calf stretch.\",\"Keep the back leg straight and the heel down.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"11452.webp\",\"gif\":\"11452.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing calf stretch variation that lengthens the lower leg muscles and helps ankle mobility.\"},{\"id\":\"3505\",\"n\":\"camel pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"chest\",\"quadriceps\",\"lower back\"],\"st\":[\"Kneel with knees hip-width apart and hands on your lower back.\",\"Push your hips forward and lift your chest.\",\"Lean back and reach for your heels if comfortable.\",\"Let your head relax back gently.\",\"Hold for 20-30 seconds, breathing evenly.\",\"Come up slowly, leading with your chest.\"],\"img\":\"3505.webp\",\"gif\":\"3505.mp4\",\"cat\":\"yoga\",\"desc\":\"A kneeling backbend that opens the chest, abs and front of the hips.\"},{\"id\":\"6303\",\"n\":\"camel pose ustrasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"chest\",\"core\",\"shoulders\"],\"st\":[\"Kneel with knees hip-width apart and hands on your lower back.\",\"Push your hips forward.\",\"Lean back and reach for your heels.\",\"Lift your chest and let your head drop gently if comfortable.\",\"Hold for 15-30 seconds, then rise.\"],\"img\":\"6303.webp\",\"gif\":\"6303.mp4\",\"cat\":\"yoga\",\"desc\":\"A kneeling backbend with hands on your heels. It opens the chest and stretches the thighs and hips.\"},{\"id\":\"5107\",\"n\":\"captains chair leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"grip muscles\"],\"st\":[\"Rest your forearms on the pads and press your back against the support.\",\"Let your legs hang straight down.\",\"Raise your knees or straight legs to hip height or higher.\",\"Pause briefly at the top.\",\"Lower your legs slowly without swinging.\"],\"img\":\"5107.webp\",\"gif\":\"5107.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise your legs while supported by the arm pads of a captain's chair. It is a classic lower-ab exercise.\"},{\"id\":\"3708\",\"n\":\"cardio lunge\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand tall with your hands on your hips or swinging with the movement.\",\"Step forward and lower into a lunge.\",\"Push off the front foot and return to standing.\",\"Switch legs and keep a quick rhythm.\",\"Keep your torso upright throughout.\"],\"img\":\"3708.webp\",\"gif\":\"3708.mp4\",\"cat\":\"cardio\",\"desc\":\"Lunges done at a brisk pace to lift your heart rate while working the legs.\"},{\"id\":\"4580\",\"n\":\"cat cow stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Inhale and drop your belly, lifting your chest and tailbone into cow.\",\"Exhale and round your back toward the ceiling into cat.\",\"Tuck your chin and pull your belly in.\",\"Move slowly between the two positions.\",\"Repeat for 10-12 breaths.\"],\"img\":\"4580.webp\",\"gif\":\"4580.mp4\",\"cat\":\"yoga\",\"desc\":\"A gentle spinal flow between arching and rounding the back to loosen the spine.\",\"fv\":\"5252\"},{\"id\":\"0942\",\"n\":\"cat pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"shoulders\"],\"st\":[\"Start on all fours with wrists under shoulders and knees under hips.\",\"Exhale and press the floor away as you round your back toward the ceiling.\",\"Tuck your chin toward your chest and draw your belly in.\",\"Hold for 20-30 seconds while breathing slowly.\",\"Inhale and return to a neutral back.\"],\"img\":\"0942.webp\",\"gif\":\"0942.mp4\",\"cat\":\"yoga\",\"desc\":\"Round your spine upward from hands and knees to stretch the back. A gentle way to loosen the spine and wake up the core.\"},{\"id\":\"1051\",\"n\":\"cat stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"lower abs\"],\"st\":[\"Start on hands and knees with hands under shoulders.\",\"Tuck your chin and round your back toward the ceiling.\",\"Draw your belly button in and hold for a few breaths.\",\"Return to a neutral spine.\",\"Repeat slowly, holding the rounded position 15-20 seconds.\"],\"img\":\"1051.webp\",\"gif\":\"1051.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle spinal stretch on hands and knees, rounding the back like a cat. It loosens the spine.\",\"fv\":\"0249\"},{\"id\":\"2106\",\"n\":\"cat stretch v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"lower back\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Tuck your chin and tilt the pelvis as you push the floor away.\",\"Round your back up toward the ceiling like a cat.\",\"Hold the rounded position for a few seconds.\",\"Return slowly to the neutral starting position.\",\"Repeat for 8-10 slow reps.\"],\"img\":\"2106.webp\",\"gif\":\"2106.mp4\",\"cat\":\"stretching\",\"desc\":\"Rounds the spine upward from all fours to loosen the back and gently engage the abs. A classic mobility move for stiff backs.\"},{\"id\":\"0250\",\"n\":\"ceiling look stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Sit or stand tall with relaxed shoulders.\",\"Slowly tilt your head back to look at the ceiling.\",\"Open your mouth slightly to relax the jaw.\",\"Feel the stretch along the front of your neck.\",\"Hold for 15-20 seconds.\",\"Return to neutral slowly.\"],\"img\":\"0250.webp\",\"gif\":\"0250.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle neck stretch where you tilt the head back to look at the ceiling. It opens the front of the neck.\"},{\"id\":\"4280\",\"n\":\"ceiling look stretch v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Reach both arms overhead and slightly back.\",\"Tilt your head back to look at the ceiling while pressing your hips forward.\",\"Keep your core engaged so your lower back is not over-arched.\",\"Hold for 20-30 seconds, breathing steadily, then relax.\"],\"img\":\"4280.webp\",\"gif\":\"4280.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch where you reach up and look toward the ceiling to open the front of the body. It opens the hips and thighs.\"},{\"id\":\"6010\",\"n\":\"celebratory knee drives\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Drive one knee up as you raise your arms in a victory pose.\",\"Lower and switch.\",\"Keep a quick, bouncy rhythm.\",\"Land lightly and work for 30 seconds.\"],\"img\":\"6010.webp\",\"gif\":\"6010.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Fast alternating knee drives with arms pumping overhead, a fun cardio drill.\",\"fv\":\"5956\"},{\"id\":\"0944\",\"n\":\"chair pose utkatasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet together or hip-width apart.\",\"Bend your knees and send your hips back, keeping your chest lifted.\",\"Raise your arms overhead with palms facing each other.\",\"Keep your knees over your ankles and your tailbone tucked slightly.\",\"Hold for 5 slow breaths, then stand up.\"],\"img\":\"0944.webp\",\"gif\":\"0944.mp4\",\"cat\":\"yoga\",\"desc\":\"Sit back into an imaginary chair with arms overhead. It strengthens the thighs and glutes while challenging balance.\"},{\"id\":\"0943\",\"n\":\"chair pose utkatasana v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet together and arms at your sides.\",\"Bend your knees and sit your hips back and down as if lowering into a chair.\",\"Reach your arms up beside your ears and lengthen your spine.\",\"Sink a little deeper while keeping your weight in your heels.\",\"Hold for 5 slow breaths, then straighten your legs to stand.\"],\"img\":\"0943.webp\",\"gif\":\"0943.mp4\",\"cat\":\"yoga\",\"desc\":\"A deeper version of chair pose where you sit lower with arms lifted. It builds leg strength and balance.\"},{\"id\":\"6290\",\"n\":\"chaturanga dandasana (four limbed staff pose)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Shift forward slightly.\",\"Bend your elbows straight back to about 90 degrees.\",\"Keep your body in one line, elbows close to your ribs.\",\"Hold briefly, then press back up.\"],\"img\":\"6290.webp\",\"gif\":\"6290.mp4\",\"cat\":\"yoga\",\"desc\":\"A low push-up hold from plank. It builds triceps, chest and core strength.\"},{\"id\":\"5888\",\"n\":\"chaturanga pose\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with your wrists under your shoulders.\",\"Shift slightly forward on your toes.\",\"Bend your elbows straight back and lower to elbow height.\",\"Keep your body in one line and your elbows near your ribs.\",\"Hold briefly, then press back up.\"],\"img\":\"5888.webp\",\"gif\":\"5888.mp4\",\"cat\":\"yoga\",\"desc\":\"A low plank where the elbows are bent back by your ribs. Builds strength in the arms, chest and core.\"},{\"id\":\"5696\",\"n\":\"cheat curl\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand holding a barbell with an underhand grip, arms straight.\",\"Lean back slightly and swing your hips to start the lift.\",\"Curl the bar up to your chest.\",\"Lower the bar slowly, resisting its weight.\",\"Reset your posture before the next rep.\"],\"img\":\"5696.webp\",\"gif\":\"5696.mp4\",\"cat\":\"strength\",\"desc\":\"A heavier biceps curl that uses a small hip swing to get the bar past the sticking point. It lets you overload the biceps on the way up.\"},{\"id\":\"2341\",\"n\":\"chest bench press arms (form check)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on the bench and unrack the bar over your shoulders.\",\"Compare the faulty version with the correct one: your arms move in a controlled line and the bar tracks over the lower chest.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2341.webp\",\"gif\":\"2341.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for arm path during the bench press, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2338\",\"n\":\"chest bench press butt (form check)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on the bench with your eyes under the bar and your feet flat on the floor.\",\"Compare the faulty version with the correct one: your hips stay planted on the pad and never lift off.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2338.webp\",\"gif\":\"2338.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for keeping your butt on the bench during a chest press, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2342\",\"n\":\"chest bench press elbows (form check)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on the bench with the bar unracked above your chest.\",\"Compare the faulty version with the correct one: your elbows sit at roughly 45 degrees from the torso instead of flaring wide.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2342.webp\",\"gif\":\"2342.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for elbow position during the bench press, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2339\",\"n\":\"chest bench press grip width (form check)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on the bench and grip the bar at a moderate width.\",\"Compare the faulty version with the correct one: your forearms are vertical at the bottom, with hands just wider than the shoulders.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2339.webp\",\"gif\":\"2339.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for choosing the right grip width on the bench press, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2340\",\"n\":\"chest bench press shoulders (form check)\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on the bench and pinch your shoulder blades together before unracking.\",\"Compare the faulty version with the correct one: your shoulder blades stay pulled back and down against the bench.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2340.webp\",\"gif\":\"2340.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for shoulder position during the bench press, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2839\",\"n\":\"chest lift with rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Curl your head and shoulders up.\",\"Rotate your torso to one side.\",\"Return to centre and lower.\",\"Alternate sides.\"],\"img\":\"2839.webp\",\"gif\":\"2839.mp4\",\"cat\":\"pilates\",\"desc\":\"A curl up with a twist that trains the abs and obliques.\"},{\"id\":\"4945\",\"n\":\"chest out hands behind (hold)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall and clasp your hands behind your back.\",\"Straighten your arms.\",\"Lift your chest and gently raise your hands.\",\"Feel the stretch across the chest and shoulders.\",\"Hold for 20-30 seconds.\",\"Release slowly.\"],\"img\":\"4945.webp\",\"gif\":\"4945.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing chest stretch with the hands clasped behind your back. It opens the front of the chest.\"},{\"id\":\"0945\",\"n\":\"child pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"shoulders\"],\"st\":[\"Kneel on the floor with big toes touching and knees apart.\",\"Sit your hips back toward your heels.\",\"Fold forward and slide your arms out in front of you.\",\"Rest your forehead on the floor and relax your shoulders.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0945.webp\",\"gif\":\"0945.mp4\",\"cat\":\"stretching\",\"desc\":\"Fold forward over your knees with arms extended on the floor. A restful stretch for the back, hips and shoulders.\"},{\"id\":\"4558\",\"n\":\"child to cobra pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Start in child pose, knees apart, arms stretched forward.\",\"Shift forward and lower your chest toward the floor.\",\"Slide forward and press into your hands to lift your chest into cobra.\",\"Keep your hips down and your shoulders away from your ears.\",\"Hold for a few breaths.\",\"Push back into child pose and repeat.\"],\"img\":\"4558.webp\",\"gif\":\"4558.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga flow that moves from a resting child pose into a gentle backbend, mobilising the spine.\"},{\"id\":\"4509\",\"n\":\"chin to chest stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Slowly lower your chin toward your chest.\",\"Place your hands lightly on the back of your head if you want a deeper stretch.\",\"Keep your shoulders down away from your ears.\",\"Hold for 20-30 seconds.\",\"Return slowly to neutral.\"],\"img\":\"4509.webp\",\"gif\":\"4509.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle neck stretch that lengthens the muscles at the back of the neck. Useful after long periods of sitting.\",\"fv\":\"0252\"},{\"id\":\"3149\",\"n\":\"chin tuck\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\",\"trapezius\"],\"st\":[\"Sit or stand tall with your eyes level.\",\"Place a finger on your chin if it helps.\",\"Draw your chin straight back as if making a double chin.\",\"Keep your head level without tilting.\",\"Hold for 3-5 seconds.\",\"Release and repeat 8-10 times.\"],\"img\":\"3149.webp\",\"gif\":\"3149.mp4\",\"cat\":\"mobility\",\"desc\":\"Drawing your chin straight back to line up your head over your shoulders. It's a simple neck posture exercise.\",\"fv\":\"3151\"},{\"id\":\"4724\",\"n\":\"chin up (in squatting position)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"quadriceps\",\"forearms\"],\"st\":[\"Set a low bar and grip it with palms facing you.\",\"Sit into a deep squat beneath it.\",\"Pull your chest to the bar.\",\"Lower back down.\",\"Use your legs as little as possible.\"],\"img\":\"4724.webp\",\"gif\":\"4724.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up from a low bar while sitting in a squat, using your legs to share the work.\"},{\"id\":\"4725\",\"n\":\"chin up (isometric and negative)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Jump or step up so your chin is above the bar.\",\"Hold the top position for a few seconds.\",\"Lower yourself slowly over several seconds.\",\"Reset on the floor.\",\"Repeat for the reps.\"],\"img\":\"4725.webp\",\"gif\":\"4725.mp4\",\"cat\":\"isometric\",\"desc\":\"A chin-up variation focused on holding at the top and lowering slowly to build strength.\"},{\"id\":\"4207\",\"n\":\"chin up around the bar\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Grab the bar with an underhand grip and hang with straight arms.\",\"Brace your core and pull your elbows down.\",\"Pull your chest toward the bar, sweeping your head around one side.\",\"Pause briefly at the top.\",\"Lower with control back to a full hang.\",\"Alternate the side you pass on each rep.\"],\"img\":\"4207.webp\",\"gif\":\"4207.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up variation where you pull your body around the bar rather than straight over it. It challenges lats, biceps and grip.\"},{\"id\":\"8610\",\"n\":\"chinese plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Set up in a plank on your forearms with elbows under shoulders.\",\"Squeeze your glutes and brace your abs.\",\"Keep your body in one straight line.\",\"Breathe steadily and hold for 20-40 seconds.\",\"Lower down to rest.\"],\"img\":\"8610.webp\",\"gif\":\"8610.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank variation held with a modified base that challenges core stability.\",\"hd\":1},{\"id\":\"3996\",\"n\":\"circles arm\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with arms out to the sides.\",\"Make small circles forward.\",\"Increase to larger circles.\",\"Reverse the direction.\",\"Keep your shoulders relaxed.\"],\"img\":\"3996.webp\",\"gif\":\"3996.mp4\",\"cat\":\"mobility\",\"desc\":\"Draw circles with straight arms to warm up the shoulders. It loosens the shoulder joints.\",\"fv\":\"0254\"},{\"id\":\"4278\",\"n\":\"circles knee stretch v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"hamstrings\"],\"st\":[\"Stand with your feet together and bend your knees slightly.\",\"Place your hands on your knees for support.\",\"Slowly rotate your knees in a circle in one direction.\",\"Keep the movement smooth and controlled.\",\"Switch to the other direction after 8 to 10 circles.\"],\"img\":\"4278.webp\",\"gif\":\"4278.mp4\",\"cat\":\"mobility\",\"desc\":\"Gentle knee circles with the leg slightly bent that loosen up the knee area and calves. Handy as a warm-up or a loosening drill.\"},{\"id\":\"4216\",\"n\":\"climbing monkey bars\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"grip muscles\",\"shoulders\",\"biceps\"],\"st\":[\"Grab the first bar with both hands and hang.\",\"Swing your body slightly and reach for the next bar with one hand.\",\"Release the back hand and reach for the following bar.\",\"Keep a steady rhythm using your hips for momentum.\",\"Continue to the end of the ladder.\",\"Drop down softly and rest before the next pass.\"],\"img\":\"4216.webp\",\"gif\":\"4216.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Swing from bar to bar along a horizontal ladder. It builds grip, shoulders and back with a playful challenge.\"},{\"id\":\"10191\",\"n\":\"clock goblet squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Hold a dumbbell at your chest and picture a clock on the floor around you.\",\"Step to 12 o'clock and squat down with your chest up.\",\"Stand up and return to the center.\",\"Step to the next position on the clock and squat again.\",\"Work your way around the clock with control and switch direction on the next set.\"],\"img\":\"10191.webp\",\"gif\":\"10191.mp4\",\"cat\":\"strength\",\"desc\":\"A goblet squat that steps around an imaginary clock, training the legs from several directions.\"},{\"id\":\"5479\",\"n\":\"close grip pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"upper back\",\"forearms\"],\"st\":[\"Grip the bar with hands a few centimetres apart, palms facing away.\",\"Hang with straight arms and engage your shoulders.\",\"Pull yourself up until your chin passes the bar.\",\"Lower slowly to a full hang.\",\"Keep your core tight and avoid swinging.\"],\"img\":\"5479.webp\",\"gif\":\"5479.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull-up using a narrow overhand grip to emphasise the lower lats and arms.\"},{\"id\":\"5192\",\"n\":\"cluster\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"hamstrings\",\"triceps\",\"core\"],\"st\":[\"Start with the barbell on the floor and pull it to your shoulders in a clean.\",\"Stand up with the bar racked on your shoulders.\",\"Squat down into a deep front squat.\",\"Drive up and press the bar overhead.\",\"Lower the bar to your shoulders and repeat.\"],\"img\":\"5192.webp\",\"gif\":\"5192.mp4\",\"cat\":\"olympic\",\"desc\":\"A weightlifting combo where a clean flows into a front squat and a push press. It trains power and stamina together.\"},{\"id\":\"3488\",\"n\":\"cobra push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"lower back\",\"core\"],\"st\":[\"Start in a push-up position with hands under your shoulders.\",\"Lower your chest to the floor with elbows tucked.\",\"Press up and keep going, letting your hips sink forward.\",\"Lift your chest and look slightly up, like a cobra.\",\"Return to the plank by lifting your hips back.\",\"Keep the movement smooth and controlled.\"],\"img\":\"3488.webp\",\"gif\":\"3488.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up that flows into a cobra-style chest opening at the top. It trains the chest and arms and works the back and spine.\"},{\"id\":\"1482\",\"n\":\"cobra yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"chest\",\"shoulders\"],\"st\":[\"Lie on your stomach with your palms under your shoulders and legs extended.\",\"Press the tops of your feet into the floor.\",\"Lift your chest by straightening your arms partway, keeping your hips down.\",\"Keep your shoulders away from your ears and your neck long.\",\"Hold for 15-30 seconds, then lower slowly.\"],\"img\":\"1482.webp\",\"gif\":\"1482.mp4\",\"cat\":\"yoga\",\"desc\":\"A gentle yoga backbend that opens the chest and stretches the front of the abs while strengthening the back.\",\"fv\":\"4267\"},{\"id\":\"4726\",\"n\":\"commando pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Grab the bar with one hand in front of the other, palms facing each other, and hang with arms straight.\",\"Brace your core and pull your body up, moving your head to one side of the bar.\",\"Get your chin or shoulder level with the bar.\",\"Lower under control to a full hang.\",\"Switch which side your head passes on each rep, or each set.\"],\"img\":\"4726.webp\",\"gif\":\"4726.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with a staggered, side-on grip that you pull to alternating sides of the bar. It builds lats, arms and grip.\",\"fv\":\"5270\"},{\"id\":\"2353\",\"n\":\"concentration curl arms (form check)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Sit on a bench, lean forward and brace your elbow against your inner thigh.\",\"Compare the faulty version with the correct one: your upper arm rests against the inner thigh and only the forearm moves.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2353.webp\",\"gif\":\"2353.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for arm position during a concentration curl, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"5986\",\"n\":\"cone drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Place several cones in a pattern a few yards apart.\",\"Start in an athletic stance.\",\"Sprint or shuffle around the cones in order.\",\"Plant and cut with your hips low.\",\"Finish the course, rest, then go again.\"],\"img\":\"5986.webp\",\"gif\":\"5986.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A cone run that builds acceleration, cutting speed and agility.\"},{\"id\":\"2840\",\"n\":\"control balance\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"core\"],\"st\":[\"Lie on your back and roll your legs overhead.\",\"Hold one ankle with both hands.\",\"Extend the other leg out above you.\",\"Switch legs with control.\",\"Roll down slowly.\"],\"img\":\"2840.webp\",\"gif\":\"2840.mp4\",\"cat\":\"pilates\",\"desc\":\"A challenging Pilates move where you balance on your shoulders while switching legs, building control and core strength.\"},{\"id\":\"2841\",\"n\":\"corkscrew\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with arms by your sides and legs raised up.\",\"Lift your hips slightly and swing your legs across to one side.\",\"Circle them down and around.\",\"Bring them back up to the start.\",\"Reverse the direction.\"],\"img\":\"2841.webp\",\"gif\":\"2841.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates move where the legs trace circles overhead, training the obliques and lower abs.\"},{\"id\":\"0261\",\"n\":\"corkscrew push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Lower your chest toward the floor while rotating your hips slightly to one side.\",\"Push up and return to the centre.\",\"Repeat to the other side.\",\"Keep your core braced and your legs together.\",\"Move smoothly and do not let your hips sag.\"],\"img\":\"0261.webp\",\"gif\":\"0261.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where you twist the hips and body as you descend. It adds trunk rotation to a standard chest exercise.\"},{\"id\":\"1781\",\"n\":\"corner wall chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand facing a wall corner and place a forearm on each wall at about shoulder height.\",\"Step one foot forward and lean your chest into the corner until you feel a stretch.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1781.webp\",\"gif\":\"1781.mp4\",\"cat\":\"stretching\",\"desc\":\"Using a wall corner to lean into, you stretch both sides of the chest at once. The corner lets you control the depth easily.\",\"fv\":\"9600\"},{\"id\":\"5889\",\"n\":\"corpse pose savasana\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"\",\"sm\":[],\"st\":[\"Lie flat on your back with your legs extended and slightly apart.\",\"Let your arms rest by your sides with palms up.\",\"Close your eyes and let your whole body soften.\",\"Breathe slowly for 2-5 minutes.\",\"Roll to your side and sit up gently.\"],\"img\":\"5889.webp\",\"gif\":\"5889.mp4\",\"cat\":\"yoga\",\"desc\":\"The classic resting pose at the end of practice. Lets the body relax fully.\"},{\"id\":\"2569\",\"n\":\"cossack squats\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand with your feet much wider than shoulder width and toes slightly out.\",\"Shift your weight to one side and bend that knee, sitting your hips down and back.\",\"Keep the other leg straight with the heel down and toes up.\",\"Push through the bent leg to slide back to the centre.\",\"Repeat on the other side and keep your chest tall.\"],\"img\":\"2569.webp\",\"gif\":\"2569.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide side-to-side squat where you sink onto one leg while the other stays straight. It builds leg strength and hip mobility.\"},{\"id\":\"4557\",\"n\":\"couch stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Kneel facing away from a wall or couch with one shin up against it.\",\"Place your other foot flat on the floor in front in a lunge.\",\"Squeeze your glute and tuck your pelvis under.\",\"Lift your torso upright until you feel the stretch in the front of your rear thigh.\",\"Hold for 30-60 seconds.\",\"Switch legs.\"],\"img\":\"4557.webp\",\"gif\":\"4557.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep kneeling stretch with the back foot raised, aimed at the thighs and hip flexors.\"},{\"id\":\"4363\",\"n\":\"counterbalanced skater squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand on one leg and extend the other behind you.\",\"Reach your arms forward for balance.\",\"Bend your standing knee and lower slowly.\",\"Touch lightly with your back knee if needed.\",\"Drive back up and switch legs.\"],\"img\":\"4363.webp\",\"gif\":\"4363.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat with arms forward as a counterweight. It builds balance and strength.\"},{\"id\":\"9514\",\"n\":\"countermovement jump arms on hip\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart and hands on your hips.\",\"Dip quickly into a quarter squat.\",\"Explode upward, extending hips, knees and ankles.\",\"Reach for maximum height without using your arms.\",\"Land softly on bent knees and reset.\"],\"img\":\"9514.webp\",\"gif\":\"9514.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A vertical jump with hands on your hips so the legs do all the work. It develops explosive leg power.\"},{\"id\":\"9513\",\"n\":\"countermovement jump arms pull\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart and arms back.\",\"Dip quickly into a quarter squat while swinging your arms down and back.\",\"Swing your arms forward and up as you explode off the floor.\",\"Extend fully through hips, knees and ankles.\",\"Land softly with bent knees and reset.\"],\"img\":\"9513.webp\",\"gif\":\"9513.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A vertical jump with a quick dip and an arm swing that adds momentum. It builds explosive leg power.\"},{\"id\":\"6902\",\"n\":\"cow face yoga pose gomukhasana\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"chest\",\"hip flexors\"],\"st\":[\"Sit with one knee stacked over the other and your feet beside your hips.\",\"Reach one arm up and bend the elbow, hand down your back.\",\"Sweep the other arm behind you and try to clasp your fingers.\",\"Keep your spine tall and your chest open.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch sides and repeat.\"],\"img\":\"6902.webp\",\"gif\":\"6902.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated pose that stretches the shoulders, triceps and hips together.\"},{\"id\":\"2107\",\"n\":\"cow stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"lower back\",\"hip flexors\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Inhale and let your belly drop toward the floor.\",\"Lift your chest and tailbone while looking slightly forward.\",\"Keep your arms straight and shoulders away from your ears.\",\"Hold for a couple of seconds, then return to neutral.\",\"Repeat for 8-10 slow reps.\"],\"img\":\"2107.webp\",\"gif\":\"2107.mp4\",\"cat\":\"stretching\",\"desc\":\"Lets the belly sink and the chest lift from all fours to stretch the front of the trunk and mobilise the spine.\"},{\"id\":\"6901\",\"n\":\"cow yoga pose bitilasana\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"chest\",\"hip flexors\"],\"st\":[\"Start on hands and knees, with wrists under shoulders and knees under hips.\",\"Inhale and let your belly drop toward the floor.\",\"Lift your chest and tailbone while your gaze goes slightly forward.\",\"Keep your shoulders away from your ears.\",\"Hold for 3-5 breaths.\",\"Return to a neutral spine.\"],\"img\":\"6901.webp\",\"gif\":\"6901.mp4\",\"cat\":\"yoga\",\"desc\":\"A gentle spinal extension from all fours that wakes up the back and often pairs with cat pose.\"},{\"id\":\"2842\",\"n\":\"crab\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Sit with your legs crossed and hold your feet.\",\"Roll back onto your shoulders.\",\"Cross your legs the other way.\",\"Roll back up.\",\"Keep your movement smooth.\"],\"img\":\"2842.webp\",\"gif\":\"2842.mp4\",\"cat\":\"pilates\",\"desc\":\"A rolling Pilates move in a seated crab shape that works the core and spine mobility.\"},{\"id\":\"5054\",\"n\":\"crab pose\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"wrist flexors\",\"hip flexors\",\"core\"],\"st\":[\"Sit with knees bent and hands behind you, fingers pointing toward your feet.\",\"Press into your hands and feet.\",\"Lift your hips until your torso is flat.\",\"Let your head relax back gently.\",\"Hold for 20-30 seconds.\"],\"img\":\"5054.webp\",\"gif\":\"5054.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated backbend with hips lifted, like an upside down table. It opens the chest, shoulders and front of the hips.\"},{\"id\":\"5881\",\"n\":\"crab walk\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"quadriceps\"],\"st\":[\"Sit on the floor, place your hands behind you and lift your hips off the ground.\",\"Keep your hips high and your core braced.\",\"Step with opposite hand and foot to move forward.\",\"Walk for several steps, then go backward.\",\"Keep your head neutral and your arms steady.\"],\"img\":\"5881.webp\",\"gif\":\"5881.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Walk on hands and feet with your belly facing up, a playful drill that fires up the glutes, triceps and core.\"},{\"id\":\"0946\",\"n\":\"crane pose bakasana\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"triceps\",\"wrist flexors\"],\"st\":[\"Squat with feet together and place your hands flat on the floor shoulder-width apart.\",\"Bend your elbows slightly and rest your shins against the backs of your upper arms.\",\"Shift your weight forward onto your hands and lift one foot, then the other.\",\"Round your upper back, draw your belly in and gaze slightly ahead.\",\"Hold for a few breaths, then lower your feet gently.\"],\"img\":\"0946.webp\",\"gif\":\"0946.mp4\",\"cat\":\"yoga\",\"desc\":\"An arm balance where your knees rest on the backs of your upper arms and your feet lift. It builds wrist, arm and core strength.\"},{\"id\":\"3950\",\"n\":\"crawl to crab\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"glutes\",\"core\"],\"st\":[\"Start on hands and knees.\",\"Lift your knees slightly into a low crawl.\",\"Rotate your body and sit back into a crab position, face up.\",\"Lift your hips.\",\"Rotate back into the crawl and repeat.\"],\"img\":\"3950.webp\",\"gif\":\"3950.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Move from a crawl position into a crab position to work the whole body.\"},{\"id\":\"0947\",\"n\":\"crescent moon pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"shoulders\",\"core\"],\"st\":[\"Stand tall with feet together and raise your arms overhead, palms joined.\",\"Reach up through your fingertips and keep your hips level.\",\"Lean your upper body slowly to one side in a gentle curve.\",\"Hold for 3 to 5 breaths without twisting forward or back.\",\"Return to center and repeat on the other side.\"],\"img\":\"0947.webp\",\"gif\":\"0947.mp4\",\"cat\":\"yoga\",\"desc\":\"Stand and arch sideways with arms overhead to lengthen one side of the body. It opens the ribs, sides and shoulders.\"},{\"id\":\"4711\",\"n\":\"criss cross jack\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"adductors\",\"quadriceps\"],\"st\":[\"Stand with feet together and arms at your sides.\",\"Jump your feet apart while the arms swing overhead.\",\"Jump and cross one foot in front and the arms across your chest.\",\"Alternate which side crosses.\",\"Keep a quick but controlled pace.\"],\"img\":\"4711.webp\",\"gif\":\"4711.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping jack variation where the arms and legs cross over each other.\"},{\"id\":\"4020\",\"n\":\"criss cross leg raises\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"obliques\",\"adductors\"],\"st\":[\"Lie on your back with legs straight and raised.\",\"Lower them slightly.\",\"Cross one leg over the other.\",\"Switch the cross.\",\"Keep your lower back down.\"],\"img\":\"4020.webp\",\"gif\":\"4020.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying leg raises with legs crossing over each other. It targets the lower abs and inner thighs.\"},{\"id\":\"7194\",\"n\":\"criss cross stepback hops\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall with your feet hip-width apart and your knees soft.\",\"Hop and cross one foot in front of the other.\",\"Hop back out, then step one foot back behind you.\",\"Land softly on the balls of your feet each time.\",\"Keep a quick, rhythmic pace.\",\"Alternate sides for the planned time.\"],\"img\":\"7194.webp\",\"gif\":\"7194.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick hopping drill that crosses the feet and steps back, building agility and leg power.\"},{\"id\":\"11283\",\"n\":\"criss cross tuck jump\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"core\",\"glutes\"],\"st\":[\"Stand tall with feet shoulder width apart.\",\"Jump up and pull your knees toward your chest.\",\"Cross your feet in the air.\",\"Land softly on the balls of your feet.\",\"Uncross on the next jump, alternating the crossing foot.\",\"Keep a steady quick rhythm.\"],\"img\":\"11283.webp\",\"gif\":\"11283.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump where you tuck the knees and cross the feet in the air, great for conditioning and leg power.\"},{\"id\":\"4372\",\"n\":\"crocodile yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Lie face down with palms under your shoulders.\",\"Tuck your toes and lift your body.\",\"Lower into a low plank with elbows tucked in.\",\"Keep your body straight and hold for 20-30 seconds.\",\"Lower to the floor.\"],\"img\":\"4372.webp\",\"gif\":\"4372.mp4\",\"cat\":\"yoga\",\"desc\":\"A low plank-like yoga pose held just above the floor. It strengthens the core and arms.\"},{\"id\":\"3784\",\"n\":\"cross arms push up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with your hands crossed under your chest.\",\"Keep your body in a straight line from head to heels.\",\"Lower your chest toward the floor with your elbows close.\",\"Press back up until your arms are straight.\",\"Switch which hand is on top each set.\"],\"img\":\"3784.webp\",\"gif\":\"3784.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands crossed under your chest. It puts extra load on the triceps.\"},{\"id\":\"5233\",\"n\":\"cross body punch in squat position\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Stand in a wide stance and sink into a half squat.\",\"Keep your fists up near your chin.\",\"Punch one arm across your body, rotating your torso.\",\"Pull it back and punch with the other arm.\",\"Stay low and keep a quick, controlled rhythm.\"],\"img\":\"5233.webp\",\"gif\":\"5233.mp4\",\"cat\":\"combat\",\"desc\":\"Punching across the body from a low squat. It builds leg endurance and trunk rotation.\"},{\"id\":\"3979\",\"n\":\"cross body push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank.\",\"Lower into a push up.\",\"Push up and cross one hand over toward the other side.\",\"Place it down and repeat.\",\"Alternate the crossing hand.\"],\"img\":\"3979.webp\",\"gif\":\"3979.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push up where one hand crosses over toward the other side. It adds an uneven challenge for the chest and core.\"},{\"id\":\"0263\",\"n\":\"cross body twisting crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and your hands behind your head.\",\"Lift your shoulders and twist your torso to one side.\",\"Bring your elbow toward the opposite knee.\",\"Lower back down and repeat on the other side.\",\"Keep your lower back on the floor.\",\"Do not pull on your neck.\"],\"img\":\"0263.webp\",\"gif\":\"0263.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch that twists across the body, bringing the elbow toward the opposite knee. It emphasises the obliques.\"},{\"id\":\"0264\",\"n\":\"cross jacks\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"shoulders\",\"quadriceps\"],\"st\":[\"Stand with your feet together and your arms at your sides.\",\"Jump your feet apart while raising your arms overhead.\",\"Jump back crossing your arms and one leg in front.\",\"Alternate which leg crosses on the next rep.\",\"Land softly on the balls of your feet.\",\"Keep a steady rhythm for 30-60 seconds.\"],\"img\":\"0264.webp\",\"gif\":\"0264.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping-jack variation where the arms and legs cross in front of the body. It raises your heart rate and coordination.\"},{\"id\":\"5105\",\"n\":\"cross jump jack\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"shoulders\"],\"st\":[\"Stand with your feet together and arms by your sides.\",\"Jump your feet apart while raising your arms overhead.\",\"Jump again, crossing your legs and your arms in front of you.\",\"Land softly on the balls of your feet.\",\"Keep a steady rhythm and continue for 30-60 seconds.\"],\"img\":\"5105.webp\",\"gif\":\"5105.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping jack where your arms and legs cross over each other at the center. It raises your heart rate and warms up the whole body.\"},{\"id\":\"1793\",\"n\":\"cross over shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Stand tall and bring one straight arm across your chest.\",\"Use your other hand to hold it just above the elbow and draw it closer to you.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1793.webp\",\"gif\":\"1793.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulling one arm across your chest stretches the rear shoulder. It is a staple warm-up and cooldown stretch.\"},{\"id\":\"5846\",\"n\":\"cross standing crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Stand tall with your hands behind your head.\",\"Lift one knee and rotate your torso.\",\"Bring the opposite elbow toward that knee.\",\"Return to standing.\",\"Alternate sides for the set.\"],\"img\":\"5846.webp\",\"gif\":\"5846.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing crunch that brings your elbow across to the opposite knee. It trains the abs and obliques.\"},{\"id\":\"3951\",\"n\":\"cross twisting sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Curl up and twist toward one knee.\",\"Lower slowly.\",\"Alternate sides.\",\"Avoid pulling on your neck.\"],\"img\":\"3951.webp\",\"gif\":\"3951.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with a twist to bring one elbow toward the opposite knee.\"},{\"id\":\"5334\",\"n\":\"cross twisting sit up v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Sit up while rotating your torso.\",\"Bring one elbow toward the opposite knee.\",\"Lower back down slowly.\",\"Alternate sides each rep.\",\"Avoid pulling on your neck.\"],\"img\":\"5334.webp\",\"gif\":\"5334.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with a cross-body twist, a second variation. It works the abs and obliques together.\"},{\"id\":\"5684\",\"n\":\"crossed arms front leg kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Stand tall with your arms crossed over your chest.\",\"Shift your weight onto one leg.\",\"Kick the other leg forward to about hip height with control.\",\"Lower it and repeat for your reps.\",\"Switch legs and keep your torso upright.\"],\"img\":\"5684.webp\",\"gif\":\"5684.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A standing front kick with your arms crossed over your chest. Warms up the hips and legs while challenging balance.\"},{\"id\":\"4296\",\"n\":\"crossover kneeling hip flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"obliques\"],\"st\":[\"Kneel on one knee with the other foot forward in a lunge, on a mat.\",\"Tuck your pelvis slightly and keep your torso upright.\",\"Reach the arm on the kneeling side up and across toward the opposite side.\",\"Shift your hips gently forward until you feel the stretch at the front of the hip.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"4296.webp\",\"gif\":\"4296.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling lunge stretch with a cross-body reach to deepen the stretch along the front of the hip.\",\"fv\":\"0265\"},{\"id\":\"1510\",\"n\":\"crossover reverse lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand tall with your hands on your hips.\",\"Step one foot back and across behind your other leg.\",\"Lower until both knees are bent about 90 degrees.\",\"Keep your torso upright and your front knee stable.\",\"Push through the front foot to stand, then repeat or switch sides.\"],\"img\":\"1510.webp\",\"gif\":\"1510.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse lunge where the back leg steps behind and across the line of the front leg. It trains glutes, thighs and balance.\"},{\"id\":\"1890\",\"n\":\"crouching heel back achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Crouch down with your hands on the floor for balance.\",\"Extend one leg back with the heel down.\",\"Press the heel toward the floor.\",\"Keep your chest lifted.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1890.webp\",\"gif\":\"1890.mp4\",\"cat\":\"stretching\",\"desc\":\"Low crouch stretch with one heel pushed back to lengthen the Achilles.\"},{\"id\":\"1930\",\"n\":\"crouching heel back calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Crouch down with your feet flat and hands on the floor for balance.\",\"Shift one heel backward and press it toward the floor.\",\"Keep the other leg bent and supporting your weight.\",\"Feel the stretch in the calf of the pressing leg.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1930.webp\",\"gif\":\"1930.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep crouch with the heels pressed back to stretch the calves and Achilles area.\"},{\"id\":\"4727\",\"n\":\"crunch (arms on chest)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Cross your arms over your chest.\",\"Curl your head and shoulders off the floor.\",\"Squeeze your abs at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4727.webp\",\"gif\":\"4727.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A basic crunch with your arms crossed over your chest. It trains the abs without pulling on the neck.\"},{\"id\":\"3821\",\"n\":\"crunch (arms straight)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Extend your arms straight toward your knees.\",\"Curl your shoulders off the floor, keeping your arms reaching.\",\"Pause briefly at the top.\",\"Lower slowly without pulling on your neck.\"],\"img\":\"3821.webp\",\"gif\":\"3821.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with your arms reaching toward your knees. It focuses on your upper abs.\",\"fv\":\"0266\"},{\"id\":\"0268\",\"n\":\"crunch (leg raise)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"obliques\"],\"st\":[\"Lie on your back with your hands by your head and your legs up.\",\"Curl your shoulders off the floor while keeping your legs raised.\",\"Squeeze your abs.\",\"Lower your shoulders slowly.\",\"Lift your legs slightly higher at the top for extra work.\",\"Keep your lower back pressed down.\"],\"img\":\"0268.webp\",\"gif\":\"0268.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch combined with a leg lift so the lower abs work along with the upper. It is a compact full-abs move.\"},{\"id\":\"0269\",\"n\":\"crunch (legs on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your calves on a stability ball and your knees bent at 90 degrees.\",\"Place your hands by your head or across your chest.\",\"Curl your shoulders off the floor.\",\"Squeeze your abs at the top.\",\"Lower slowly.\",\"Keep your neck relaxed and the ball steady.\"],\"img\":\"0269.webp\",\"gif\":\"0269.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with your calves resting on a stability ball. The raised legs fix the hips and focus the work on the abs.\"},{\"id\":\"3838\",\"n\":\"crunch (on bench)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on a bench with your knees bent and feet flat.\",\"Place your hands by your temples.\",\"Curl your shoulders up, bringing your ribs toward your hips.\",\"Pause briefly at the top.\",\"Lower slowly without pulling on your neck.\"],\"img\":\"3838.webp\",\"gif\":\"3838.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch performed lying on a bench. It trains your abs with a slightly larger range of motion.\",\"fv\":\"0270\"},{\"id\":\"1242\",\"n\":\"crunch (on bosu ball)\",\"bp\":\"waist\",\"eq\":\"bosu ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Sit on the bosu ball and lie back so it supports your lower back.\",\"Place your hands lightly behind your head.\",\"Curl your shoulders up by contracting your abs.\",\"Hold the top briefly.\",\"Lower slowly and keep your feet planted.\"],\"img\":\"1242.webp\",\"gif\":\"1242.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch on a bosu ball. The unstable surface asks more from your core.\"},{\"id\":\"0273\",\"n\":\"crunch (straight leg up)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with your legs straight up toward the ceiling.\",\"Extend your arms toward your feet.\",\"Curl your shoulders off the floor and reach toward your toes.\",\"Squeeze your abs at the top.\",\"Lower slowly.\",\"Keep your legs still and your neck relaxed.\"],\"img\":\"0273.webp\",\"gif\":\"0273.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with your legs pointing straight up so you reach toward your toes. It works the abs with less hip flexor pull.\"},{\"id\":\"7414\",\"n\":\"crunch against wall\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your feet and calves resting on a wall, knees bent about 90 degrees.\",\"Place your hands lightly behind your head.\",\"Curl your shoulders off the floor.\",\"Pause at the top.\",\"Lower with control.\",\"Repeat for the planned reps.\"],\"img\":\"7414.webp\",\"gif\":\"7414.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with your legs against a wall that keeps your hips steady and works the abs.\"},{\"id\":\"2344\",\"n\":\"crunch back (form check)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands by your head.\",\"Compare the faulty version with the correct one: your lower back stays gently on the floor while only the upper back curls up.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2344.webp\",\"gif\":\"2344.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for back position during a crunch, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"0275\",\"n\":\"crunch floor v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and your feet flat.\",\"Place your hands lightly by your head or across your chest.\",\"Curl your shoulders off the floor.\",\"Pause and squeeze your abs.\",\"Lower with control.\",\"Keep your chin off your chest and your lower back on the floor.\"],\"img\":\"0275.webp\",\"gif\":\"0275.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A classic floor crunch. It strengthens the abs with a short, controlled curl.\"},{\"id\":\"4332\",\"n\":\"crunch hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Place your hands lightly behind your head or across your chest.\",\"Curl your head and shoulders off the floor.\",\"Hold the top position for 20-30 seconds, breathing steadily.\",\"Lower down with control.\"],\"img\":\"4332.webp\",\"gif\":\"4332.mp4\",\"cat\":\"isometric\",\"desc\":\"A crunch held at the top to keep the abs under tension. Simple and burns quickly.\",\"hd\":1},{\"id\":\"4331\",\"n\":\"crunch single leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Extend one leg and lift it a few inches off the floor.\",\"Curl your shoulders up toward your hips.\",\"Lower slowly, then repeat.\",\"Switch legs halfway through or alternate each rep.\"],\"img\":\"4331.webp\",\"gif\":\"4331.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where one leg lifts as you curl up. It adds a lower-abs challenge to the basic crunch.\"},{\"id\":\"4095\",\"n\":\"crunch with leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your hands behind your head and legs extended.\",\"Crunch your shoulders off the floor.\",\"At the same time lift your legs toward the ceiling.\",\"Hold for a moment, then lower slowly.\",\"Keep your lower back pressed into the floor.\"],\"img\":\"4095.webp\",\"gif\":\"4095.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch paired with a leg raise to train both the upper and lower abdominals.\"},{\"id\":\"3510\",\"n\":\"crunchy frog on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with arms and legs extended.\",\"Lift your shoulders and legs slightly off the floor.\",\"Pull your knees in while reaching your hands toward your shins.\",\"Squeeze your abs.\",\"Extend back out without resting on the floor.\",\"Keep your lower back pressed down.\"],\"img\":\"3510.webp\",\"gif\":\"3510.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor ab move where knees and arms come together in a frog-like crunch. It works the abs.\"},{\"id\":\"6304\",\"n\":\"dancer pose natarajasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"chest\",\"shoulders\"],\"st\":[\"Stand tall and bend one knee, holding that foot behind you.\",\"Kick your foot back into your hand.\",\"Reach your free arm forward.\",\"Tilt your torso forward as the leg lifts.\",\"Hold for 20-30 seconds, then switch.\"],\"img\":\"6304.webp\",\"gif\":\"6304.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing balance with a back-held leg and a forward reach. It stretches the quads and opens the chest.\"},{\"id\":\"1243\",\"n\":\"dead bug v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with arms pointing up and knees bent at 90 degrees.\",\"Press your lower back into the floor.\",\"Lower your right arm and left leg toward the floor.\",\"Return and switch sides.\",\"Move slowly and keep your back flat.\"],\"img\":\"1243.webp\",\"gif\":\"1243.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying core drill where arms and legs reach out while your back stays down. It trains core control.\",\"fv\":\"3800\"},{\"id\":\"7839\",\"n\":\"dead bug v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"shoulders\"],\"st\":[\"Lie on your back with arms straight above you and knees bent at 90 degrees.\",\"Press your lower back into the floor.\",\"Lower one arm and the opposite leg toward the floor.\",\"Return to the start.\",\"Alternate sides with a slow tempo.\",\"Keep your ribs down.\"],\"img\":\"7839.webp\",\"gif\":\"7839.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A back-lying core drill that moves opposite arms and legs while keeping the lower back flat.\"},{\"id\":\"4124\",\"n\":\"dead bug with medicine ball\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back holding a medicine ball above your chest, knees bent over your hips.\",\"Press your lower back into the floor.\",\"Lower the ball overhead while extending the opposite leg.\",\"Return to the start.\",\"Alternate sides.\"],\"img\":\"4124.webp\",\"gif\":\"4124.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dead bug holding a medicine ball overhead to add trunk control demand.\"},{\"id\":\"4056\",\"n\":\"dead bug with stability ball\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lower abs\",\"hip flexors\",\"shoulders\"],\"st\":[\"Lie on your back and hold the ball above your chest with your knees raised.\",\"Press your lower back into the floor.\",\"Extend your opposite arm and leg away, holding the ball with the rest.\",\"Return to the center.\",\"Alternate sides slowly.\"],\"img\":\"4056.webp\",\"gif\":\"4056.mp4\",\"cat\":\"strength\",\"desc\":\"Dead bug holding a stability ball between hands and knees. It builds deep core control.\",\"fv\":\"8508\"},{\"id\":\"5055\",\"n\":\"dead hang stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"grip muscles\",\"forearms\"],\"st\":[\"Grab a pull-up bar with an overhand grip, hands shoulder width apart.\",\"Hang with your arms straight and feet off the floor.\",\"Relax your shoulders and let your body lengthen.\",\"Breathe steadily.\",\"Hold for 20-30 seconds.\"],\"img\":\"5055.webp\",\"gif\":\"5055.mp4\",\"cat\":\"stretching\",\"desc\":\"Hanging from a bar to stretch the lats and shoulders. It also decompresses the spine.\"},{\"id\":\"2354\",\"n\":\"deadlift back (form check)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"upper back\"],\"st\":[\"Stand with the bar over mid-foot, hinge down and grip it just outside your legs.\",\"Compare the faulty version with the correct one: your back stays neutral and braced from the floor to lockout.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2354.webp\",\"gif\":\"2354.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for back position during a deadlift, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2357\",\"n\":\"deadlift hips (form check)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\"],\"st\":[\"Stand with the bar over mid-foot and set your hips at a mid height before gripping.\",\"Compare the faulty version with the correct one: your hips start above the knees and rise together with your shoulders.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2357.webp\",\"gif\":\"2357.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for hip position during a deadlift, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"1845\",\"n\":\"decline bent leg reverse crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on a decline bench and hold the top edge above your head.\",\"Bring your knees up and bend them.\",\"Curl your hips off the bench, drawing your knees toward your chest.\",\"Lower back down slowly without swinging.\",\"Keep the movement controlled throughout.\"],\"img\":\"1845.webp\",\"gif\":\"1845.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Reverse crunch on a decline bench that curls the hips toward the chest and trains the lower abs.\",\"fv\":\"3072\"},{\"id\":\"5866\",\"n\":\"decline diamond push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Place your feet on a bench and your hands close together under your chest.\",\"Form a diamond with your thumbs and index fingers.\",\"Lower your chest toward your hands.\",\"Keep your body in a straight line.\",\"Push back up to straight arms.\"],\"img\":\"5866.webp\",\"gif\":\"5866.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A diamond push-up with your feet raised. It shifts the load toward the triceps and upper chest.\"},{\"id\":\"6548\",\"n\":\"decline knee raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on a decline bench and grip the top behind your head.\",\"Extend your legs with a slight knee bend.\",\"Pull your knees up toward your chest, curling the pelvis off the bench.\",\"Pause briefly at the top.\",\"Lower your legs slowly without letting the hips drop hard.\",\"Keep the movement smooth, not jerky.\"],\"img\":\"6548.webp\",\"gif\":\"6548.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Knee raises on a decline bench. The slope adds difficulty and focuses on the lower abs.\"},{\"id\":\"3490\",\"n\":\"decline kneeling push up on box\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Place a sturdy box in front of you and kneel on the floor.\",\"Put your hands on the box edge, slightly wider than your shoulders.\",\"Form a straight line from head to knees.\",\"Lower your chest to the box with elbows at about 45 degrees.\",\"Press back up until your arms are straight.\",\"Keep your hips from sagging.\"],\"img\":\"3490.webp\",\"gif\":\"3490.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling push-up with the hands on a box, so the body slopes downward. It's an easier push-up that still stresses the chest and shoulders.\"},{\"id\":\"3438\",\"n\":\"decline leg hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on a decline bench and hold the top edge.\",\"Bring your legs up over your hips.\",\"Lift your hips toward the ceiling.\",\"Lower your hips first.\",\"Lower your legs with control.\",\"Avoid swinging.\"],\"img\":\"3438.webp\",\"gif\":\"3438.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A leg raise on a decline bench, finishing with a hip lift for the lower abs.\"},{\"id\":\"3915\",\"n\":\"decline pike press (between benches)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Place your hands on two benches and your feet on a higher surface behind you.\",\"Lift your hips into a pike.\",\"Bend your elbows and lower your head between the benches.\",\"Press up to straight arms.\",\"Keep your core tight.\",\"Control the descent.\"],\"img\":\"3915.webp\",\"gif\":\"3915.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A harder pike push-up with the feet raised, hands on benches, loading the shoulders strongly.\"},{\"id\":\"3935\",\"n\":\"decline push up (kneeling)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Kneel with your knees on a bench or step and hands on the floor.\",\"Keep a straight line from head to knees.\",\"Lower your chest toward the floor.\",\"Press back up.\",\"Keep your core tight and your elbows at about 45 degrees.\"],\"img\":\"3935.webp\",\"gif\":\"3935.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up from your knees with the lower body elevated, shifting the work to the upper chest and shoulders.\"},{\"id\":\"0278\",\"n\":\"decline push up (on stability ball)\",\"bp\":\"chest\",\"eq\":\"stability ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Place your shins or feet on a stability ball and your hands on the floor under your shoulders.\",\"Form a straight line from head to heels.\",\"Lower your chest toward the floor.\",\"Push back up without letting your hips sag.\",\"Brace your core to keep the ball steady.\",\"Keep your elbows at about 45 degrees.\"],\"img\":\"0278.webp\",\"gif\":\"0278.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your feet on a stability ball, so your hands sit lower than your feet. It challenges the upper chest, shoulders and balance.\"},{\"id\":\"3491\",\"n\":\"decline push up against wall\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Place your hands on the floor and walk your feet up a wall behind you.\",\"Set your hands under your shoulders in a straight body line.\",\"Lower your chest toward the floor with elbows tucked.\",\"Press back up to straight arms.\",\"Keep your core tight and your hips level.\",\"Walk your feet down to finish.\"],\"img\":\"3491.webp\",\"gif\":\"3491.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the feet up the wall and hands on the floor. The raised feet put more load on the upper chest and shoulders.\"},{\"id\":\"3823\",\"n\":\"decline shoulder tap\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"chest\",\"triceps\"],\"st\":[\"Place your feet on a bench and your hands on the floor under your shoulders.\",\"Keep your body in a straight line.\",\"Lift one hand and tap the opposite shoulder.\",\"Return it and tap with the other hand.\",\"Keep your hips from rocking.\"],\"img\":\"3823.webp\",\"gif\":\"3823.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank with your feet raised where you tap alternate shoulders. It trains shoulder strength and core stability.\"},{\"id\":\"0281\",\"n\":\"decline sit up (arms straight)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on a decline bench and hook your feet under the pads.\",\"Extend your arms straight in front of you, parallel to the floor.\",\"Curl your torso up, rolling off the bench one section at a time.\",\"Reach your arms toward your knees as you sit up.\",\"Lower back down slowly with control.\",\"Keep your chin off your chest and don't yank with your arms.\"],\"img\":\"0281.webp\",\"gif\":\"0281.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up on a decline bench with your arms held straight out in front. It trains the abs through a longer range, and straight arms make it a bit harder.\"},{\"id\":\"4972\",\"n\":\"decline sit up and russian twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on a decline bench with your feet secured.\",\"Sit up toward your knees.\",\"Twist your torso to one side at the top.\",\"Twist to the other side.\",\"Lower slowly to the bench.\",\"Keep your movements controlled.\"],\"img\":\"4972.webp\",\"gif\":\"4972.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A decline sit up followed by a Russian twist at the top. It trains the abs and obliques.\"},{\"id\":\"5515\",\"n\":\"decline sit up v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Hook your feet under the pads on a decline bench and lie back.\",\"Cross your arms over your chest.\",\"Curl your torso up until you are sitting tall.\",\"Lower back slowly without dropping.\",\"Keep your neck relaxed.\"],\"img\":\"5515.webp\",\"gif\":\"5515.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Sit-up on a decline bench that increases the range and load on the abs.\"},{\"id\":\"2523\",\"n\":\"decline twisting sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on a decline bench with your feet secured.\",\"Place your hands lightly behind your head.\",\"Sit up while rotating your torso to one side.\",\"Pause at the top.\",\"Lower with control.\",\"Alternate sides each rep.\"],\"img\":\"2523.webp\",\"gif\":\"2523.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit up on a decline bench with a twist to work the abs and obliques.\"},{\"id\":\"8220\",\"n\":\"deep knee bend\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Sit your hips back and down as deep as you can.\",\"Keep your heels down and chest up.\",\"Pause at the bottom.\",\"Drive up to standing.\"],\"img\":\"8220.webp\",\"gif\":\"8220.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A full-depth bodyweight squat. It builds leg strength and works the mobility of hips and ankles.\"},{\"id\":\"8162\",\"n\":\"deep lunge to hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"calves\"],\"st\":[\"Step into a deep lunge with both hands on the floor.\",\"Hold for a breath and feel the front of the back hip open.\",\"Shift your hips back and straighten the front leg.\",\"Flex your front foot and fold gently over it.\",\"Hold for 20 to 30 seconds.\",\"Return to the lunge and switch legs.\"],\"img\":\"8162.webp\",\"gif\":\"8162.mp4\",\"cat\":\"stretching\",\"desc\":\"A flowing stretch from a deep lunge into a straight front leg. It opens the hip flexors and stretches the hamstrings.\"},{\"id\":\"6910\",\"n\":\"deep push up on parallel bars\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Grip two parallel bars and hold a straight plank position.\",\"Keep your elbows at about 45 degrees.\",\"Lower your chest below the level of your hands.\",\"Press back up until your arms are straight.\",\"Keep your body in one line throughout.\"],\"img\":\"6910.webp\",\"gif\":\"6910.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up between parallel bars that lets you sink deeper than the floor allows. It gives the chest a greater stretch.\"},{\"id\":\"0948\",\"n\":\"default pose\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"calves\"],\"st\":[\"Stand with feet about hip-width apart and weight even on both feet.\",\"Let your arms hang naturally at your sides.\",\"Lengthen your spine and gently draw your ribs down.\",\"Relax your shoulders and look straight ahead.\",\"Breathe calmly for a few breaths.\"],\"img\":\"0948.webp\",\"gif\":\"0948.mp4\",\"cat\":\"yoga\",\"desc\":\"A relaxed, tall standing posture with arms by your sides. It is the neutral starting point for standing moves.\"},{\"id\":\"1989\",\"n\":\"depression in parallel bars stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"triceps\"],\"st\":[\"Stand between parallel bars and grip them at hip height.\",\"Walk back slightly, letting your arms straighten.\",\"Lower your chest toward the floor and press your head between your arms.\",\"Feel the stretch in the lats and shoulders.\",\"Hold for 20-30 seconds, then walk forward to release.\"],\"img\":\"1989.webp\",\"gif\":\"1989.mp4\",\"cat\":\"stretching\",\"desc\":\"A hanging stretch between parallel bars that opens the shoulders and lengthens the lats.\"},{\"id\":\"4844\",\"n\":\"depth jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand at the edge of a low box.\",\"Step off and land on both feet.\",\"Rebound immediately into a maximum vertical jump.\",\"Spend as little time on the ground as you can.\",\"Land softly and reset for the next rep.\"],\"img\":\"4844.webp\",\"gif\":\"4844.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A drop from a box followed by a quick vertical jump. It develops reactive power.\"},{\"id\":\"4843\",\"n\":\"depth jump to broad jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand at the edge of a low box.\",\"Step off and land on both feet.\",\"Immediately explode forward into a broad jump.\",\"Swing your arms for momentum.\",\"Land softly with bent knees and reset.\"],\"img\":\"4843.webp\",\"gif\":\"4843.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A drop off a box into an immediate broad jump. It trains reactive leg power.\"},{\"id\":\"4198\",\"n\":\"depth jump to hurdle hop\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand on a box.\",\"Step off.\",\"Land softly.\",\"Jump over the hurdle immediately.\",\"Land softly.\",\"Reset.\"],\"img\":\"4198.webp\",\"gif\":\"4198.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Drop off a box and hop over a hurdle.\"},{\"id\":\"6762\",\"n\":\"diagonal bend hold\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"hamstrings\"],\"st\":[\"Stand with feet wider than your hips.\",\"Reach one arm overhead and toward the opposite foot.\",\"Bend diagonally, keeping your hips facing forward.\",\"Reach only as far as is comfortable.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Return to standing and switch sides.\"],\"img\":\"6762.webp\",\"gif\":\"6762.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing diagonal bend held for a stretch through the back and side of the body.\"},{\"id\":\"1832\",\"n\":\"diagonal flexion neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Sit tall and gently turn your head about 45 degrees to one side.\",\"Drop your chin diagonally toward your chest, using your hand for light added pressure.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1832.webp\",\"gif\":\"1832.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilting your head diagonally forward stretches the back and side of the neck. It targets the muscle running from the neck to the shoulder blade.\"},{\"id\":\"4552\",\"n\":\"diagonal lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Step one foot out diagonally, about 45 degrees away from you.\",\"Bend both knees and lower into a lunge, keeping your chest up.\",\"Push off the front foot to return to the start.\",\"Alternate legs each rep.\",\"Keep your front knee pointing the same way as your toes.\"],\"img\":\"4552.webp\",\"gif\":\"4552.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lunge stepped out at an angle that trains the legs and hips in a different plane, with a quick, springy pace.\"},{\"id\":\"4824\",\"n\":\"diagonal punch\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\",\"triceps\",\"chest\"],\"st\":[\"Stand in an athletic stance with your fists up.\",\"Rotate your hips and torso as you throw a punch across your body.\",\"Extend your arm fully and pivot your back foot.\",\"Pull the arm back quickly.\",\"Alternate sides at a brisk, controlled pace.\"],\"img\":\"4824.webp\",\"gif\":\"4824.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A fast, rotating punch that travels across the body. It raises your heart rate and trains shoulders, core and rotation.\",\"fv\":\"5112\"},{\"id\":\"6632\",\"n\":\"diagonal reach on chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Sit tall on the front edge of a chair with feet flat.\",\"Extend your arms out in front of you.\",\"Reach one hand diagonally down toward the opposite foot, rotating your torso.\",\"Return to upright with control.\",\"Reach to the other side and keep alternating.\"],\"img\":\"6632.webp\",\"gif\":\"6632.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated reach across the body toward the opposite foot. It loosens the trunk and works the obliques gently.\"},{\"id\":\"4539\",\"n\":\"diamond press\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Start in a plank position with your hands under your chest, thumbs and index fingers forming a diamond.\",\"Keep your body in a straight line from head to heels.\",\"Lower your chest toward your hands, elbows tracking back close to your ribs.\",\"Pause briefly just above your hands.\",\"Press back up until your arms are straight.\",\"Keep your core tight so your hips do not sag.\"],\"img\":\"4539.webp\",\"gif\":\"4539.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A narrow push-up variation with the hands close together, putting extra load on the triceps and inner chest.\"},{\"id\":\"1174\",\"n\":\"diamond push up (on knees)\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Kneel on the floor and place your hands under your chest, thumbs and fingers forming a diamond.\",\"Keep your body straight from knees to head.\",\"Lower your chest toward your hands, elbows close.\",\"Press up until your arms are straight.\",\"Keep your core tight throughout.\"],\"img\":\"1174.webp\",\"gif\":\"1174.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An easier knee version of the diamond push-up that targets the triceps with hands close together.\"},{\"id\":\"1442\",\"n\":\"dip hold\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Grip the parallel bars and press yourself up with straight arms.\",\"Lean slightly forward and lock your shoulders down.\",\"Hold the position with your body still.\",\"Keep your elbows near your sides.\",\"Hold for 15-30 seconds and step down.\"],\"img\":\"1442.webp\",\"gif\":\"1442.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding the top of a dip on parallel bars. It builds the triceps and shoulder stability.\",\"hd\":1},{\"id\":\"3443\",\"n\":\"dip on floor with chair\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\"],\"st\":[\"Sit on the floor with hands on a chair behind you.\",\"Lift your hips off the floor.\",\"Bend your elbows to lower your body.\",\"Keep elbows pointing back.\",\"Press up.\",\"Brace the chair against a wall.\"],\"img\":\"3443.webp\",\"gif\":\"3443.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated dip with your hands on a chair behind you.\"},{\"id\":\"3387\",\"n\":\"dips between chairs\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"upper chest\"],\"st\":[\"Place two sturdy chairs facing each other and brace them against a wall.\",\"Grip the seats, lift your body and straighten your arms.\",\"Lower yourself by bending your elbows until your upper arms are about parallel to the floor.\",\"Keep your elbows pointing back and your chest up.\",\"Press up to straight arms.\",\"Make sure the chairs cannot slide.\"],\"img\":\"3387.webp\",\"gif\":\"3387.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Bodyweight dips using two sturdy chairs, working the triceps and chest.\"},{\"id\":\"9486\",\"n\":\"dish hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with arms overhead and legs straight.\",\"Press your lower back into the floor and tighten your abs.\",\"Lift your arms, shoulders and legs a few centimetres off the floor.\",\"Keep your body in a shallow dish shape and breathe.\",\"Hold for 20-30 seconds, then relax.\"],\"img\":\"9486.webp\",\"gif\":\"9486.mp4\",\"cat\":\"isometric\",\"desc\":\"A gymnastics-style hollow position on your back with arms and legs reaching away. It builds strong, braced abs.\",\"hd\":1},{\"id\":\"6288\",\"n\":\"dolphin pose\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"upper back\",\"triceps\",\"calves\"],\"st\":[\"Start on hands and knees, then lower to your forearms.\",\"Tuck your toes and lift your hips up high.\",\"Press your forearms into the floor.\",\"Let your head hang between your arms.\",\"Hold for 20-30 seconds.\"],\"img\":\"6288.webp\",\"gif\":\"6288.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga inverted V on your forearms. It stretches the shoulders and hamstrings and builds shoulder strength.\"},{\"id\":\"7553\",\"n\":\"doorway chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Stand in a doorway with forearms on the frame, elbows at 90 degrees.\",\"Step one foot forward.\",\"Lean gently through the door until you feel a stretch.\",\"Hold for 20-30 seconds.\",\"Breathe slowly and step back.\"],\"img\":\"7553.webp\",\"gif\":\"7553.mp4\",\"cat\":\"stretching\",\"desc\":\"Doorway stretch that opens up the chest and the fronts of your shoulders.\"},{\"id\":\"5969\",\"n\":\"dot drill\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"ankles\",\"feet\"],\"st\":[\"Mark five dots on the floor like the five on a die.\",\"Stand on the balls of your feet next to the pattern.\",\"Hop quickly from dot to dot in your chosen order.\",\"Keep your hops small and your knees soft.\",\"Work for 20-30 seconds, then rest.\"],\"img\":\"5969.webp\",\"gif\":\"5969.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A fast foot drill over a pattern of dots that builds foot speed, ankle stability and coordination.\"},{\"id\":\"5038\",\"n\":\"double jump rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"forearms\"],\"st\":[\"Hold a jump rope with the handles at your hips.\",\"Jump slightly higher than normal.\",\"Spin the rope fast with your wrists so it passes twice under your feet.\",\"Land softly on the balls of your feet.\",\"Rest between short rounds as needed.\"],\"img\":\"5038.webp\",\"gif\":\"5038.mp4\",\"cat\":\"cardio\",\"desc\":\"Jumping rope with two passes of the rope per jump. It is great conditioning that builds coordination.\"},{\"id\":\"3704\",\"n\":\"double jump squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Lower into a squat and explode into a jump.\",\"Land softly and immediately jump a second time.\",\"Land with bent knees and sink back into the squat.\",\"Keep your chest up and repeat.\"],\"img\":\"3704.webp\",\"gif\":\"3704.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat followed by two quick jumps in a row. It builds explosive leg power and stamina.\"},{\"id\":\"1960\",\"n\":\"double kneeling shin stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Kneel on a mat with your feet pointing straight back and the tops of the feet on the floor.\",\"Slowly sit back toward your heels until you feel the shins and ankles stretch.\",\"Place your hands on the floor in front of you to control the pressure.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1960.webp\",\"gif\":\"1960.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling and sitting back onto your heels to stretch the front of the shins and ankles.\"},{\"id\":\"1956\",\"n\":\"double lean back quadriceps stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Kneel and sit back so your hips rest on your heels.\",\"Place your hands on the floor behind you.\",\"Lean back slowly and lift the hips slightly until you feel a stretch in the front of both thighs.\",\"Stop if you feel any pinch in the knees.\",\"Hold for 20-30 seconds, then come back up slowly.\"],\"img\":\"1956.webp\",\"gif\":\"1956.mp4\",\"cat\":\"stretching\",\"desc\":\"Sitting back on your heels and leaning back to stretch both quadriceps at once.\"},{\"id\":\"1549\",\"n\":\"double leg butt kick\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Stand tall with your feet hip-width apart and arms relaxed.\",\"Jump up off both feet.\",\"Kick both heels up toward your glutes while you are in the air.\",\"Land softly on the balls of your feet with slightly bent knees.\",\"Go straight into the next jump at a steady rhythm.\"],\"img\":\"1549.webp\",\"gif\":\"1549.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bouncy jump where both heels flick up toward your glutes. It gets your heart rate up and warms up the hamstrings.\"},{\"id\":\"2843\",\"n\":\"double leg stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back and curl your head and shoulders up.\",\"Hug your knees to your chest.\",\"Reach your arms overhead while extending your legs.\",\"Circle your arms and draw your knees back in.\",\"Keep your lower back down.\"],\"img\":\"2843.webp\",\"gif\":\"2843.mp4\",\"cat\":\"pilates\",\"desc\":\"A core-driven move where arms and legs stretch out together and then draw back in.\"},{\"id\":\"5890\",\"n\":\"double pigeon pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\",\"lower back\"],\"st\":[\"Sit with your legs crossed and stack one shin on top of the other.\",\"Flex your feet to protect your knees.\",\"Sit tall, then hinge forward over your shins.\",\"Hold for 5 slow breaths.\",\"Swap which leg is on top and repeat.\"],\"img\":\"5890.webp\",\"gif\":\"5890.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated pose with one shin stacked on the other. Opens the outer hips and glutes.\"},{\"id\":\"7499\",\"n\":\"double plank jack to 4 mountain climber\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Start in a high plank.\",\"Jump your feet wide and together twice.\",\"Do four mountain climbers, driving your knees alternately.\",\"Keep your hips level.\",\"Flow through the sequence at a steady pace.\"],\"img\":\"7499.webp\",\"gif\":\"7499.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Conditioning combo of two plank jacks followed by four mountain climbers.\"},{\"id\":\"3885\",\"n\":\"double under jump rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"forearms\",\"shoulders\",\"core\"],\"st\":[\"Hold the rope handles at your hips with your elbows close.\",\"Stand tall and start with a few normal jumps.\",\"Jump a little higher and spin the rope faster with your wrists.\",\"Let the rope pass twice under your feet before landing.\",\"Land softly on the balls of your feet.\",\"Keep your jumps small and your body upright.\"],\"img\":\"3885.webp\",\"gif\":\"3885.mp4\",\"cat\":\"cardio\",\"desc\":\"A skipping move where the rope passes twice under your feet for each jump, great for conditioning and coordination.\"},{\"id\":\"6986\",\"n\":\"downward dog push up against wall\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand facing a wall and place your hands on it with hips back.\",\"Lower your head toward the wall, bending the elbows.\",\"Push explosively away from the wall.\",\"Land softly back into the start position.\",\"Keep your core braced and back flat.\"],\"img\":\"6986.webp\",\"gif\":\"6986.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A wall-assisted version of a downward dog push-up with a push off at the top. It trains the shoulders in a bent-hip position.\"},{\"id\":\"3469\",\"n\":\"downward facing dog\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"upper back\"],\"st\":[\"Start on hands and knees.\",\"Tuck your toes and lift your hips up and back.\",\"Press your chest toward your thighs.\",\"Keep your arms straight.\",\"Hold for 20-30 seconds.\",\"Lower down gently.\"],\"img\":\"3469.webp\",\"gif\":\"3469.mp4\",\"cat\":\"yoga\",\"desc\":\"A classic yoga pose that stretches the back of the legs and shoulders.\",\"fv\":\"5251\"},{\"id\":\"0949\",\"n\":\"downward facing dog adho mukha svanasana\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"lats\",\"core\"],\"st\":[\"Start on hands and knees with hands slightly ahead of shoulders.\",\"Tuck your toes and lift your hips up and back.\",\"Straighten your legs as far as comfortable and press your chest toward your thighs.\",\"Spread your fingers and push the floor away.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0949.webp\",\"gif\":\"0949.mp4\",\"cat\":\"yoga\",\"desc\":\"An inverted V shape that stretches the back of the legs and spine while loading the shoulders. A classic yoga staple.\"},{\"id\":\"3528\",\"n\":\"downward facing dog spine mobility\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Start in a downward facing dog.\",\"Bend one knee, then the other, pedaling gently.\",\"Shift your hips side to side.\",\"Let your spine twist a little.\",\"Keep your hands pressed into the floor.\",\"Breathe slowly.\"],\"img\":\"3528.webp\",\"gif\":\"3528.mp4\",\"cat\":\"yoga\",\"desc\":\"A downward dog flowing with gentle spine movement. It loosens the back and hamstrings.\"},{\"id\":\"3527\",\"n\":\"downward facing dog toe touch\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"core\"],\"st\":[\"Start in a downward facing dog, hips high.\",\"Press your chest toward your thighs.\",\"Reach one hand back to touch the opposite foot.\",\"Return the hand and switch sides.\",\"Keep your hips high.\",\"Move slowly with steady breathing.\"],\"img\":\"3527.webp\",\"gif\":\"3527.mp4\",\"cat\":\"yoga\",\"desc\":\"A downward dog with alternating hand-to-toe taps. It stretches the hamstrings and calves.\"},{\"id\":\"6299\",\"n\":\"dragonfly pose maksikanagasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"groin\",\"core\",\"shoulders\"],\"st\":[\"Squat with hands on the floor in front of you.\",\"Place your knees high on your upper arms.\",\"Lean forward and lift your feet off the floor.\",\"Extend your legs wide to the sides.\",\"Hold for a few breaths, then release.\"],\"img\":\"6299.webp\",\"gif\":\"6299.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated wide-leg arm balance with legs extended out to the sides. It needs hip flexibility and core strength.\"},{\"id\":\"3867\",\"n\":\"duck walk\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Lower into a deep squat with your chest up.\",\"Place your hands on your hips or in front of you for balance.\",\"Step forward with one foot, keeping the squat low.\",\"Step with the other foot and continue walking.\",\"Keep your heels down and your back straight.\",\"Walk for a set distance or time.\"],\"img\":\"3867.webp\",\"gif\":\"3867.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A walk in a deep squat that challenges the quads, hips and balance.\"},{\"id\":\"5469\",\"n\":\"dumbbell 21s\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding a dumbbell in each hand, palms forward.\",\"Curl from the bottom to halfway up for 7 reps.\",\"Curl from halfway to the top for 7 reps.\",\"Do 7 full-range curls.\",\"Keep your elbows pinned to your sides.\",\"Use a lighter weight than normal.\"],\"img\":\"5469.webp\",\"gif\":\"5469.mp4\",\"cat\":\"strength\",\"desc\":\"A curl format with seven bottom-half reps, seven top-half reps and seven full reps using dumbbells.\"},{\"id\":\"4211\",\"n\":\"dumbbell 4 ways lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand with a light dumbbell in each hand and a slight knee bend.\",\"Raise both arms out to your sides to shoulder height.\",\"Lower, then raise them to the front to shoulder height.\",\"Lower, then hinge forward slightly and raise them out to the rear.\",\"Return and finish with a raise to the sides again.\",\"Keep the weights light and avoid swinging.\"],\"img\":\"4211.webp\",\"gif\":\"4211.mp4\",\"cat\":\"strength\",\"desc\":\"A shoulder series that moves the dumbbells through four raise positions in one set. It hits all heads of the delts with light weight.\"},{\"id\":\"4871\",\"n\":\"dumbbell 6 ways raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"trapezius\",\"upper back\"],\"st\":[\"Hold light dumbbells at your sides.\",\"Raise them to the side and lower.\",\"Raise them to the front and lower.\",\"Then bend forward and raise them out to the rear.\",\"Complete all six variations as one rep.\"],\"img\":\"4871.webp\",\"gif\":\"4871.mp4\",\"cat\":\"strength\",\"desc\":\"A series of six dumbbell raises in different directions. It thoroughly trains the shoulders.\"},{\"id\":\"4067\",\"n\":\"dumbbell alternate arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\"],\"st\":[\"Sit upright holding dumbbells at shoulder height with palms facing you.\",\"Press one dumbbell overhead while rotating your palm forward.\",\"Lower it while rotating back.\",\"Alternate arms.\",\"Keep your back against the pad and avoid arching.\"],\"img\":\"4067.webp\",\"gif\":\"4067.mp4\",\"cat\":\"strength\",\"desc\":\"Seated Arnold press alternating arms. The twist works the front and side delts.\"},{\"id\":\"3695\",\"n\":\"dumbbell alternate bench press (high start)\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a flat bench and press both dumbbells up above your chest.\",\"Keep one arm locked out and lower the other dumbbell to chest level.\",\"Press it back up to the top.\",\"Repeat with the other arm, alternating each rep.\",\"Keep your feet planted and your back flat on the bench.\"],\"img\":\"3695.webp\",\"gif\":\"3695.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell bench press where you press one arm at a time, starting with both weights held high. It challenges chest strength and stability.\"},{\"id\":\"1196\",\"n\":\"dumbbell alternate biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand tall with a dumbbell in each hand, palms facing forward.\",\"Keeping your elbow by your side, curl one dumbbell up toward your shoulder.\",\"Squeeze at the top, then lower it under control.\",\"Repeat with the other arm and keep alternating.\",\"Avoid swinging your torso to lift the weight.\"],\"img\":\"1196.webp\",\"gif\":\"1196.mp4\",\"cat\":\"strength\",\"desc\":\"Curling one dumbbell at a time while standing. A classic way to build the biceps with a steady rhythm.\"},{\"id\":\"4834\",\"n\":\"dumbbell alternate chest press on stability ball\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"upper chest\"],\"st\":[\"Sit on a stability ball holding dumbbells and walk out until your upper back rests on it.\",\"Lift your hips so your body forms a bridge.\",\"Press one dumbbell up over your chest.\",\"Lower it slowly while keeping your hips steady.\",\"Alternate arms for each rep.\"],\"img\":\"4834.webp\",\"gif\":\"4834.mp4\",\"cat\":\"strength\",\"desc\":\"Alternating dumbbell presses while resting on a stability ball. It builds the chest and trains core balance.\"},{\"id\":\"4341\",\"n\":\"dumbbell alternate front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand holding a dumbbell in each hand in front of your thighs.\",\"Keep a slight bend in your elbows and your torso still.\",\"Raise one arm forward to shoulder height.\",\"Lower it slowly as you raise the other arm.\",\"Avoid swinging; keep alternating for your reps.\"],\"img\":\"4341.webp\",\"gif\":\"4341.mp4\",\"cat\":\"strength\",\"desc\":\"Raising one dumbbell at a time in front of you to shoulder height. It targets the front of the shoulders.\"},{\"id\":\"6147\",\"n\":\"dumbbell alternate hammer strict curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding dumbbells with your palms facing in.\",\"Keep your elbows at your sides.\",\"Curl one dumbbell up without swinging.\",\"Lower it slowly.\",\"Repeat with the other arm.\",\"Keep your torso still.\"],\"img\":\"6147.webp\",\"gif\":\"6147.mp4\",\"cat\":\"strength\",\"desc\":\"An alternating hammer curl done with strict form, keeping your body still. It builds the biceps, brachialis and forearms.\"},{\"id\":\"4852\",\"n\":\"dumbbell alternate lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand holding light dumbbells at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise one arm out to shoulder height.\",\"Lower it slowly.\",\"Switch arms.\"],\"img\":\"4852.webp\",\"gif\":\"4852.mp4\",\"cat\":\"strength\",\"desc\":\"Raising dumbbells out to the sides one arm at a time. It builds the side delts.\"},{\"id\":\"3972\",\"n\":\"dumbbell alternate shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand or sit with dumbbells at shoulder height.\",\"Press one dumbbell overhead until the arm is straight.\",\"Lower it back to your shoulder.\",\"Press with the other arm.\",\"Brace your core and avoid leaning back.\"],\"img\":\"3972.webp\",\"gif\":\"3972.mp4\",\"cat\":\"strength\",\"desc\":\"Press dumbbells overhead one arm at a time. It builds the shoulders and triceps.\",\"fv\":\"3073\"},{\"id\":\"6805\",\"n\":\"dumbbell alternate v up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"core\"],\"st\":[\"Lie on your back with a dumbbell in each hand, arms overhead.\",\"Lift your torso and one leg at the same time.\",\"Reach the weights toward your raised foot.\",\"Lower slowly to the floor.\",\"Alternate legs each rep.\"],\"img\":\"6805.webp\",\"gif\":\"6805.mp4\",\"cat\":\"strength\",\"desc\":\"A V-up where one arm and the opposite leg meet, holding a dumbbell. It trains the abs through a big range.\"},{\"id\":\"6891\",\"n\":\"dumbbell alternate z press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"obliques\"],\"st\":[\"Sit on the floor with legs extended, dumbbells at your shoulders.\",\"Brace your core and sit tall.\",\"Press one dumbbell overhead.\",\"Lower it and press the other arm.\",\"Keep alternating without tilting your torso.\"],\"img\":\"6891.webp\",\"gif\":\"6891.mp4\",\"cat\":\"strength\",\"desc\":\"A seated floor press that alternates arms, which adds anti-lean trunk work. It trains the shoulders and the core.\"},{\"id\":\"9693\",\"n\":\"dumbbell alternating arm thruster\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a dumbbell in each hand at shoulder height.\",\"Squat down with your chest tall.\",\"Drive up and press one dumbbell overhead.\",\"Lower it back to your shoulder as you squat again.\",\"Alternate arms each rep.\"],\"img\":\"9693.webp\",\"gif\":\"9693.mp4\",\"cat\":\"strength\",\"desc\":\"A squat into an overhead press, alternating arms with dumbbells. It works legs and shoulders together.\"},{\"id\":\"2982\",\"n\":\"dumbbell alternating floor press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Lie on the floor with a dumbbell in each hand and knees bent.\",\"Press both dumbbells up over your chest.\",\"Lower one dumbbell until your upper arm touches the floor.\",\"Press it back up and lower the other side.\",\"Keep alternating.\"],\"img\":\"2982.webp\",\"gif\":\"2982.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press where you press one dumbbell at a time. It trains the chest and triceps with a limited range for the shoulders.\",\"fv\":\"2983\"},{\"id\":\"3783\",\"n\":\"dumbbell archer\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"rear deltoids\",\"core\"],\"st\":[\"Stand with feet wide and hold a dumbbell in one hand.\",\"Shift your weight toward the empty-hand side and bend that knee.\",\"Raise the dumbbell out to the side, keeping the other leg straight.\",\"Lower with control and shift back to the center.\",\"Repeat all reps, then switch arms.\"],\"img\":\"3783.webp\",\"gif\":\"3783.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance move where one arm extends sideways like drawing a bow. It trains your shoulders and upper back.\"},{\"id\":\"4443\",\"n\":\"dumbbell assisted bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in one hand and rest the other hand on a sturdy support, standing away from a bench.\",\"Place the top of your rear foot on a bench behind you.\",\"Step your front foot far enough forward to stay balanced.\",\"Lower straight down until your front thigh is about parallel to the floor.\",\"Keep your torso upright and your front knee tracking over your toes.\",\"Drive through the front heel to stand, then switch legs after your set.\"],\"img\":\"4443.webp\",\"gif\":\"4443.mp4\",\"cat\":\"strength\",\"desc\":\"A rear-foot-elevated split squat with a dumbbell in one hand and the other hand on a support. Builds single-leg strength in the quads and glutes.\"},{\"id\":\"4184\",\"n\":\"dumbbell banded bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with a band across your upper back and hands.\",\"Hold dumbbells at chest level.\",\"Press up against the band.\",\"Lock out at the top.\",\"Lower slowly.\",\"Keep your feet flat.\"],\"img\":\"4184.webp\",\"gif\":\"4184.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell bench press with a band adding tension at lockout. It builds chest strength.\"},{\"id\":\"6735\",\"n\":\"dumbbell banded hip thrust\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Put a band around your thighs and rest your upper back on a bench.\",\"Place a dumbbell across your hips and hold it steady.\",\"Plant your feet and push your knees out against the band.\",\"Drive your hips up until your torso is level.\",\"Squeeze the glutes at the top.\",\"Lower slowly.\"],\"img\":\"6735.webp\",\"gif\":\"6735.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with a dumbbell on the hips and a band around the thighs. The band keeps the glutes working to hold the knees out.\"},{\"id\":\"6558\",\"n\":\"dumbbell banded wall sit\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Put a band around your thighs and stand with your back against a wall.\",\"Slide down until your thighs are about parallel.\",\"Hold a dumbbell in both hands in front of you.\",\"Push your knees out against the band.\",\"Hold for 20-40 seconds.\"],\"img\":\"6558.webp\",\"gif\":\"6558.mp4\",\"cat\":\"isometric\",\"desc\":\"A wall sit with a band around the knees and a dumbbell held in your lap, adding glute work to the hold.\",\"hd\":1},{\"id\":\"4030\",\"n\":\"dumbbell bar grip sumo squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"inner thighs\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet wider than shoulders and toes turned out.\",\"Hold the dumbbell vertically by its bar with both hands in front of you.\",\"Sit your hips down while keeping your chest up.\",\"Push your knees out over your toes.\",\"Drive through your heels to stand and squeeze your glutes.\"],\"img\":\"4030.webp\",\"gif\":\"4030.mp4\",\"cat\":\"strength\",\"desc\":\"Wide stance squat holding one dumbbell by its bar between the legs. It hits the glutes and inner thighs.\",\"fv\":\"2430\"},{\"id\":\"10185\",\"n\":\"dumbbell bear plank alternating row\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"upper back\",\"obliques\",\"shoulders\",\"biceps\"],\"st\":[\"Start on all fours with a dumbbell in each hand and knees hovering just off the floor.\",\"Brace your core and keep your back flat.\",\"Row one dumbbell to your ribs without twisting your hips.\",\"Lower it back to the floor with control.\",\"Row with the other arm and keep alternating at a steady pace.\"],\"img\":\"10185.webp\",\"gif\":\"10185.mp4\",\"cat\":\"strength\",\"desc\":\"A row from a bear plank position that builds back strength while the core fights to stop hip rotation.\"},{\"id\":\"1611\",\"n\":\"dumbbell behind back finger curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\",\"hands\"],\"st\":[\"Stand tall with a light dumbbell held in one hand behind your back.\",\"Let the dumbbell roll down until it rests on your fingertips.\",\"Close your fingers and curl the weight back into your palm.\",\"Keep your wrist still and your arm close to your body.\",\"Lower under control and repeat, then switch hands.\"],\"img\":\"1611.webp\",\"gif\":\"1611.mp4\",\"cat\":\"strength\",\"desc\":\"Holding a dumbbell behind your back, you roll it down to your fingertips and curl it back up. It builds finger and forearm flexor strength and grip.\",\"fv\":\"3756\"},{\"id\":\"4728\",\"n\":\"dumbbell bench dip\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"forearms\"],\"st\":[\"Sit on a bench edge, hands beside your hips, and slide your hips off the front.\",\"Rest a dumbbell on your thighs, holding it steady with your hips and legs.\",\"Bend your elbows to lower until they reach about 90 degrees.\",\"Keep your back close to the bench and shoulders down.\",\"Press through your palms to straighten your arms.\"],\"img\":\"4728.webp\",\"gif\":\"4728.mp4\",\"cat\":\"strength\",\"desc\":\"A bench dip with a dumbbell resting on your lap for extra load. It hits the triceps and the front of the shoulders.\"},{\"id\":\"4729\",\"n\":\"dumbbell bench dip with legs elevated\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Place two benches facing each other, hands on one and heels on the other.\",\"Set a dumbbell on your lap and keep your legs straight.\",\"Lower your hips by bending your elbows to about 90 degrees.\",\"Keep your chest up and your elbows pointing back.\",\"Press up until your arms are straight again.\"],\"img\":\"4729.webp\",\"gif\":\"4729.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted bench dip with your feet raised on a second bench, which makes the triceps work harder.\"},{\"id\":\"1550\",\"n\":\"dumbbell bench one leg squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Hold a dumbbell in each hand and stand a step in front of a bench, facing away from it.\",\"Rest the top of one foot on the bench behind you.\",\"Lower your back knee toward the floor by bending your front leg.\",\"Keep your front knee over your toes and your chest up.\",\"Push through your front heel to stand, then switch legs after your reps.\"],\"img\":\"1550.webp\",\"gif\":\"1550.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat with the other foot resting on a bench behind you, holding dumbbells. It hammers the quads and glutes and challenges balance.\"},{\"id\":\"3693\",\"n\":\"dumbbell bench supported external rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie on your side on a bench with a light dumbbell in your top hand, elbow bent 90 degrees at your side.\",\"Keep your elbow tucked against your ribs.\",\"Rotate your forearm upward, lifting the dumbbell toward the ceiling.\",\"Lower it slowly back to the start.\",\"Finish your reps, then switch sides.\"],\"img\":\"3693.webp\",\"gif\":\"3693.mp4\",\"cat\":\"strength\",\"desc\":\"A light rotation exercise lying on a bench that strengthens the small rotator cuff muscles around the shoulder.\"},{\"id\":\"4910\",\"n\":\"dumbbell bent arm iso hold\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Stand tall with a dumbbell in each hand.\",\"Curl the weights until your elbows are bent about 90 degrees.\",\"Keep your elbows pinned to your sides.\",\"Hold the position without letting the weights drop.\",\"Breathe steadily during the hold.\",\"Hold for 20-30 seconds, then lower under control.\"],\"img\":\"4910.webp\",\"gif\":\"4910.mp4\",\"cat\":\"isometric\",\"desc\":\"A static hold with the elbows bent and the dumbbells held in place. It builds endurance in the arms.\",\"hd\":1},{\"id\":\"5635\",\"n\":\"dumbbell bent arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand with dumbbells and elbows bent.\",\"Raise your elbows out to shoulder height.\",\"Pause at the top.\",\"Lower slowly.\",\"Keep your torso still.\"],\"img\":\"5635.webp\",\"gif\":\"5635.mp4\",\"cat\":\"strength\",\"desc\":\"Bent-arm lateral raise that shifts load onto the side delts.\",\"fv\":\"4659\"},{\"id\":\"4326\",\"n\":\"dumbbell bent arm pullover\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"shoulders\"],\"st\":[\"Lie back on a bench holding one dumbbell with both hands above your chest.\",\"Bend your elbows slightly and keep them bent throughout.\",\"Lower the dumbbell back over your head until you feel a stretch in your chest.\",\"Keep your ribs down and your core braced.\",\"Pull the dumbbell back over your chest and repeat.\"],\"img\":\"4326.webp\",\"gif\":\"4326.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover with the elbows kept bent, lying on a bench. It stretches and strengthens the chest and lats.\",\"nd\":[\"bench\"]},{\"id\":\"1444\",\"n\":\"dumbbell bent arm pullover hold\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"core\"],\"st\":[\"Lie on a bench holding a dumbbell with both hands over your chest.\",\"Lower it behind your head with your elbows bent.\",\"Stop where you feel a stretch in your chest and lats.\",\"Hold the position with your core tight.\",\"Hold for 15-30 seconds, then lift it back up.\"],\"img\":\"1444.webp\",\"gif\":\"1444.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding a dumbbell over your chest with bent arms in a pullover position. It keeps the chest and lats under tension.\",\"hd\":1,\"nd\":[\"bench\"]},{\"id\":\"2566\",\"n\":\"dumbbell bent arm pullover with knees bent\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"core\"],\"st\":[\"Lie back on a bench or the floor with knees bent and feet flat, holding one dumbbell over your chest.\",\"Bend your elbows slightly and lock that angle.\",\"Lower the dumbbell back over your head in a slow arc until you feel a stretch in your chest.\",\"Pull the weight back over your chest along the same arc.\",\"Keep your ribs down and your lower back from arching.\"],\"img\":\"2566.webp\",\"gif\":\"2566.mp4\",\"cat\":\"strength\",\"desc\":\"A lying pullover with a bent elbow that stretches and works the chest, with help from the lats and triceps.\"},{\"id\":\"3696\",\"n\":\"dumbbell bent over alternate rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\",\"lower back\"],\"st\":[\"Hinge forward at the hips with a flat back, a dumbbell in each hand hanging down.\",\"Raise one arm out to the side to shoulder height with a soft elbow.\",\"Lower it slowly.\",\"Repeat with the other arm, alternating.\",\"Keep your torso still and your neck neutral.\"],\"img\":\"3696.webp\",\"gif\":\"3696.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over fly performed one arm at a time to target the rear shoulders and upper back.\"},{\"id\":\"11799\",\"n\":\"dumbbell bent over back to side to front arms raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"core\"],\"st\":[\"Hold light dumbbells and hinge forward at the hips with a flat back.\",\"Start with your arms back by your hips.\",\"Sweep the dumbbells out to the sides up to shoulder height.\",\"Continue forward in an arc, then reverse the path with control.\",\"Use light weights and avoid swinging your torso.\"],\"img\":\"11799.webp\",\"gif\":\"11799.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over sweeping raise with light dumbbells that targets the rear and side delts through a long arc.\"},{\"id\":\"7625\",\"n\":\"dumbbell bent over curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"upper back\"],\"st\":[\"Hold a dumbbell in each hand and hinge forward with a flat back.\",\"Let your arms hang straight down.\",\"Curl the weights up toward your shoulders, elbows fixed.\",\"Squeeze at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"7625.webp\",\"gif\":\"7625.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl performed while hinged forward at the hips. The position removes swing and keeps tension on the biceps.\"},{\"id\":\"5665\",\"n\":\"dumbbell bent over face pull\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\",\"rhomboids\"],\"st\":[\"Hold a dumbbell in each hand and hinge at the hips with a flat back.\",\"Let the weights hang below your shoulders, palms facing each other.\",\"Pull the dumbbells toward your face, flaring your elbows out and up.\",\"Squeeze your shoulder blades together at the top.\",\"Lower with control and repeat without swinging.\"],\"img\":\"5665.webp\",\"gif\":\"5665.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge forward and pull two dumbbells toward your face with elbows high. It works the rear delts and upper back and helps shoulder posture.\"},{\"id\":\"3799\",\"n\":\"dumbbell bent over reverse row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Hold a dumbbell in each hand with palms facing forward.\",\"Hinge at the hips with a flat back and let the weights hang.\",\"Pull the dumbbells to your lower ribs, squeezing your shoulder blades.\",\"Lower slowly until your arms are straight.\",\"Keep your neck neutral throughout.\"],\"img\":\"3799.webp\",\"gif\":\"3799.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with an underhand grip. It works your upper back, lats and biceps.\"},{\"id\":\"6146\",\"n\":\"dumbbell bent over row against wall\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Stand a step from a wall and hinge forward.\",\"Support your forehead or free hand on the wall.\",\"Hold a dumbbell in each hand with your arms hanging.\",\"Row the weights toward your hips.\",\"Squeeze your shoulder blades together.\",\"Lower with control.\"],\"img\":\"6146.webp\",\"gif\":\"6146.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell row where you lean on a wall for support. It trains the back while sparing the lower back.\"},{\"id\":\"5661\",\"n\":\"dumbbell bent over row with chest support\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Lie chest down on an incline bench with dumbbells.\",\"Let your arms hang.\",\"Row the weights up toward your ribs.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\"],\"img\":\"5661.webp\",\"gif\":\"5661.mp4\",\"cat\":\"strength\",\"desc\":\"Chest-supported dumbbell row to reduce lower back stress.\"},{\"id\":\"6136\",\"n\":\"dumbbell bent over scapula row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Hold dumbbells and hinge forward with a flat back.\",\"Let your arms hang straight down.\",\"Squeeze your shoulder blades together without bending the elbows.\",\"Hold for a moment.\",\"Release the blades and let the weights drop slightly.\",\"Keep your neck neutral throughout.\"],\"img\":\"6136.webp\",\"gif\":\"6136.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over movement where you pull the shoulder blades together with straight arms. It builds the mid-back muscles that stabilize the shoulders.\"},{\"id\":\"4730\",\"n\":\"dumbbell bent over single arm row v. 2\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\",\"forearms\"],\"st\":[\"Hold a dumbbell in one hand and hinge forward with a flat back, knees slightly bent.\",\"Let the weight hang with your arm straight below your shoulder.\",\"Pull the dumbbell toward your hip, leading with your elbow.\",\"Pause briefly, then lower slowly.\",\"Finish all reps, then switch arms.\"],\"img\":\"4730.webp\",\"gif\":\"4730.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row from a hinged position, pulling a dumbbell toward your hip. It trains the lats and mid back.\"},{\"id\":\"7995\",\"n\":\"dumbbell bent over y raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"rhomboids\"],\"st\":[\"Hold a light dumbbell in each hand and hinge at the hips with a flat back.\",\"Let your arms hang below your shoulders, palms facing each other.\",\"Raise both arms forward and up at about 45 degrees to form a Y.\",\"Pause briefly at the top and squeeze your shoulder blades.\",\"Lower the weights slowly under control.\",\"Keep your neck long and avoid swinging your torso.\"],\"img\":\"7995.webp\",\"gif\":\"7995.mp4\",\"cat\":\"strength\",\"desc\":\"Hinge forward and raise light dumbbells out and up into a Y shape. It trains the shoulders and the muscles between the shoulder blades.\"},{\"id\":\"5239\",\"n\":\"dumbbell biceps curl with overhead extension on stability ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"forearms\"],\"st\":[\"Sit tall on a stability ball holding a dumbbell.\",\"Curl the dumbbell up with your elbow at your side.\",\"Raise it overhead, lifting it with both hands.\",\"Lower it behind your head for a triceps extension.\",\"Extend, return to the front, and repeat.\"],\"img\":\"5239.webp\",\"gif\":\"5239.mp4\",\"cat\":\"strength\",\"desc\":\"Sitting on a stability ball, you curl a dumbbell and then press it overhead into an extension. It works both arms muscles and trunk balance.\"},{\"id\":\"4731\",\"n\":\"dumbbell bridge bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on the floor or a bench holding a dumbbell in each hand.\",\"Plant your feet and drive your hips up into a bridge.\",\"Press the dumbbells up until your arms are straight.\",\"Lower them to chest level under control.\",\"Keep your hips high for the whole set.\"],\"img\":\"4731.webp\",\"gif\":\"4731.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell bench press performed with your hips lifted in a glute bridge. It trains the chest while your glutes and core hold you stable.\"},{\"id\":\"2290\",\"n\":\"dumbbell bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand a stride length in front of a bench holding a dumbbell in each hand.\",\"Rest the top of your back foot on the bench.\",\"Lower straight down until your front thigh is about parallel to the floor.\",\"Keep your torso upright and your front knee tracking over your toes.\",\"Drive through your front heel to stand back up.\",\"Finish all reps, then switch legs.\"],\"img\":\"2290.webp\",\"gif\":\"2290.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat with the back foot raised, building leg strength and balance.\"},{\"id\":\"7550\",\"n\":\"dumbbell bulgarian split squat from deficit\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand with your front foot on a low platform and your rear foot on a bench.\",\"Hold dumbbells at your sides.\",\"Lower until your back knee is near the floor.\",\"Keep your front knee steady.\",\"Drive up and switch legs.\"],\"img\":\"7550.webp\",\"gif\":\"7550.mp4\",\"cat\":\"strength\",\"desc\":\"Rear-foot elevated split squat with the front foot raised for greater depth.\"},{\"id\":\"2337\",\"n\":\"dumbbell chest fly arms (form check)\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Lie on a bench with a dumbbell in each hand above your chest.\",\"Keep a slight bend in your elbows.\",\"Lower your arms out to the sides in a wide arc.\",\"Stop when you feel a gentle stretch across the chest.\",\"Bring the dumbbells back together above your chest.\",\"Repeat for the planned reps.\"],\"img\":\"2337.webp\",\"gif\":\"2337.mp4\",\"cat\":\"strength\",\"desc\":\"A chest fly form check that shows how to keep a soft elbow bend and a wide, smooth arc through the movement.\",\"nd\":[\"bench\"]},{\"id\":\"3685\",\"n\":\"dumbbell chest supported lateral raises\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Lie chest-down on an incline bench holding dumbbells.\",\"Raise your arms out to the sides.\",\"Stop at shoulder height.\",\"Lower slowly.\",\"Keep your neck neutral.\"],\"img\":\"3685.webp\",\"gif\":\"3685.mp4\",\"cat\":\"strength\",\"desc\":\"Lateral raises with your chest on an incline bench to remove cheating and isolate the delts.\"},{\"id\":\"9698\",\"n\":\"dumbbell chest supported row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lie face down on an incline bench with a dumbbell in each hand.\",\"Let your arms hang straight down.\",\"Row the weights toward your ribs.\",\"Squeeze your shoulder blades together.\",\"Lower slowly.\"],\"img\":\"9698.webp\",\"gif\":\"9698.mp4\",\"cat\":\"strength\",\"desc\":\"A two-arm dumbbell row with your chest on an incline bench. It isolates the back without strain on the lower spine.\"},{\"id\":\"3400\",\"n\":\"dumbbell clean and press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"quadriceps\",\"upper back\"],\"st\":[\"Stand over two dumbbells and grip them with a flat back.\",\"Pull the weights up explosively and catch them at your shoulders.\",\"Dip slightly and drive them overhead.\",\"Lock out your arms.\",\"Lower to your shoulders, then to the floor with control.\",\"Keep the weights close to your body.\"],\"img\":\"3400.webp\",\"gif\":\"3400.mp4\",\"cat\":\"olympic\",\"desc\":\"A dumbbell clean followed by an overhead press for total-body power.\"},{\"id\":\"4152\",\"n\":\"dumbbell close grip curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand tall holding dumbbells with palms forward and hands close together.\",\"Pin your elbows to your sides.\",\"Curl the weights up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are straight.\",\"Avoid swinging your torso.\"],\"img\":\"4152.webp\",\"gif\":\"4152.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl with the dumbbells held close together. This emphasises the outer biceps through a controlled curl.\"},{\"id\":\"3075\",\"n\":\"dumbbell close grip press v. 2\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a bench with a dumbbell in each hand pressed together over your chest.\",\"Keep your palms facing each other.\",\"Lower the dumbbells to your chest with your elbows tucked.\",\"Press back up while keeping the weights touching.\",\"Keep your wrists straight.\"],\"img\":\"3075.webp\",\"gif\":\"3075.mp4\",\"cat\":\"strength\",\"desc\":\"A press with dumbbells held close together that shifts the work toward the triceps and inner chest.\",\"nd\":[\"bench\"],\"mv\":\"1731\"},{\"id\":\"4621\",\"n\":\"dumbbell close grip shoulder press sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent, holding a dumbbell in each hand at your shoulders, palms facing in.\",\"Sit up using your abs.\",\"Press the dumbbells overhead at the top.\",\"Lower them to your shoulders and roll back down slowly.\",\"Keep your feet planted, or anchor them if needed.\"],\"img\":\"4621.webp\",\"gif\":\"4621.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up that finishes with an overhead press, joining core and shoulder work in a single rep.\"},{\"id\":\"3886\",\"n\":\"dumbbell complex push up row clean and press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"shoulders\",\"triceps\",\"glutes\"],\"st\":[\"Start in a push-up position with your hands on two dumbbells.\",\"Do a push-up, then row one dumbbell to your ribs and switch sides.\",\"Jump or step your feet toward your hands and stand up, cleaning the dumbbells to your shoulders.\",\"Press them overhead.\",\"Lower to the floor and return to the push-up position.\",\"Move smoothly and keep your core tight.\"],\"img\":\"3886.webp\",\"gif\":\"3886.mp4\",\"cat\":\"strength\",\"desc\":\"A flowing combo of push-up, row, clean and press that works the whole body with a pair of dumbbells.\"},{\"id\":\"7598\",\"n\":\"dumbbell contralateral glute dominant bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold one dumbbell in the hand opposite your front leg.\",\"Put your back foot on a bench and step the front foot forward.\",\"Lean your torso forward slightly.\",\"Lower until the front thigh is parallel.\",\"Drive up through the front heel.\",\"Finish all reps, then switch sides.\"],\"img\":\"7598.webp\",\"gif\":\"7598.mp4\",\"cat\":\"strength\",\"desc\":\"A Bulgarian split squat with one dumbbell held in the opposite hand to the front leg.\"},{\"id\":\"4732\",\"n\":\"dumbbell cossack squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand with feet wide and hold a dumbbell at your chest.\",\"Shift your weight to one side and squat down on that leg.\",\"Keep the other leg straight with the toes up.\",\"Drive through the bent leg to stand and shift to the other side.\",\"Keep your chest tall and your heel down.\"],\"img\":\"4732.webp\",\"gif\":\"4732.mp4\",\"cat\":\"strength\",\"desc\":\"A deep side-to-side squat holding a dumbbell at the chest. It works the thighs and glutes and opens up the hips.\"},{\"id\":\"4562\",\"n\":\"dumbbell cossack squats\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell at your chest and stand with a wide stance.\",\"Shift your weight to one side and bend that knee, keeping the other leg straight.\",\"Sit deep with your chest up and the straight leg's toes pointing up.\",\"Push through the bent leg to return to the center.\",\"Move into the other side.\",\"Alternate sides with control.\"],\"img\":\"4562.webp\",\"gif\":\"4562.mp4\",\"cat\":\"strength\",\"desc\":\"A side-to-side squat that trains the legs and loads the inner thighs through a big range of motion.\"},{\"id\":\"10199\",\"n\":\"dumbbell cross romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"forearms\",\"core\"],\"st\":[\"Stand holding a dumbbell in each hand with a soft bend in the knees.\",\"Push your hips back and lower the weights down your legs.\",\"Reach one dumbbell across toward the opposite foot, keeping your back flat.\",\"Drive your hips forward to stand tall.\",\"Alternate the crossing side each rep.\"],\"img\":\"10199.webp\",\"gif\":\"10199.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift where the dumbbells reach across the body, training the hamstrings and glutes.\"},{\"id\":\"4624\",\"n\":\"dumbbell crunch up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with knees bent and a dumbbell held against your chest.\",\"Brace your abs.\",\"Curl your head and shoulders off the floor.\",\"Pause at the top.\",\"Lower back down slowly.\"],\"img\":\"4624.webp\",\"gif\":\"4624.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted crunch holding a dumbbell at the chest to add resistance for the abs.\"},{\"id\":\"5884\",\"n\":\"dumbbell curl press extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"forearms\"],\"st\":[\"Stand with a dumbbell in each hand, arms at your sides.\",\"Curl both dumbbells up to shoulder height.\",\"Press them overhead until your arms are straight.\",\"Bend your elbows to lower the weights behind your head.\",\"Extend your arms, then bring the dumbbells back to your shoulders and down to your sides.\",\"Keep your torso still and choose a manageable weight.\"],\"img\":\"5884.webp\",\"gif\":\"5884.mp4\",\"cat\":\"strength\",\"desc\":\"Curl, press and overhead extension chained into one rep with dumbbells, giving the biceps, shoulders and triceps a full workout.\"},{\"id\":\"3347\",\"n\":\"dumbbell curl to press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"brachialis\"],\"st\":[\"Stand tall holding a dumbbell in each hand, palms forward.\",\"Curl both weights up to shoulder height without swinging.\",\"Rotate your wrists slightly and press the weights overhead.\",\"Lower to your shoulders, then back down to your sides.\",\"Brace your core and keep your ribs down.\"],\"img\":\"3347.webp\",\"gif\":\"3347.mp4\",\"cat\":\"strength\",\"desc\":\"Curl the dumbbells and keep going into an overhead press, training the arms and shoulders in one smooth rep.\"},{\"id\":\"0881\",\"n\":\"dumbbell curtsey lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall holding a dumbbell in each hand at your sides.\",\"Step one leg back and across behind the other.\",\"Bend both knees and lower until your front thigh is near parallel.\",\"Keep your chest up and hips square.\",\"Push through your front foot to return to standing.\",\"Repeat on the other side and alternate.\"],\"img\":\"0881.webp\",\"gif\":\"0881.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge where you step back and across behind you, like a curtsey. It works the glutes and outer hips from a different angle.\"},{\"id\":\"8664\",\"n\":\"dumbbell curtsey lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Stand holding dumbbells at your sides.\",\"Step one foot back and across behind the other leg.\",\"Lower until the front thigh is nearly parallel to the floor.\",\"Push through the front foot to stand.\",\"Alternate legs or finish one side before switching.\"],\"img\":\"8664.webp\",\"gif\":\"8664.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge where one leg crosses behind you, working the glutes and outer hips with added load.\"},{\"id\":\"4914\",\"n\":\"dumbbell deadlift (neutral grip)\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"quadriceps\"],\"st\":[\"Stand with feet hip width and a dumbbell in each hand, palms facing in.\",\"Hinge at the hips with a flat back and lower the weights.\",\"Keep the dumbbells close to your legs.\",\"Push through your heels to stand tall.\",\"Squeeze your glutes at the top.\",\"Do not round your lower back.\"],\"img\":\"4914.webp\",\"gif\":\"4914.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with dumbbells held with palms facing in. It trains the glutes, hamstrings and back.\"},{\"id\":\"5232\",\"n\":\"dumbbell deadlift bent over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"biceps\",\"hamstrings\",\"glutes\",\"lower back\"],\"st\":[\"Stand holding dumbbells in front of your thighs.\",\"Hinge at the hips with a flat back and soft knees.\",\"Row the dumbbells toward your lower ribs.\",\"Squeeze your shoulder blades.\",\"Lower the weights slowly and stand back up.\"],\"img\":\"5232.webp\",\"gif\":\"5232.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift position held into a bent-over row. It trains your back and hamstrings together.\"},{\"id\":\"5119\",\"n\":\"dumbbell deadlift v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"quadriceps\"],\"st\":[\"Stand with feet hip-width apart, dumbbells at your sides or in front of your thighs.\",\"Hinge at the hips and bend your knees slightly.\",\"Lower the dumbbells along your legs with a flat back.\",\"Drive your hips forward to stand tall.\",\"Squeeze your glutes at the top.\"],\"img\":\"5119.webp\",\"gif\":\"5119.mp4\",\"cat\":\"strength\",\"desc\":\"Lift dumbbells from the floor by hinging at the hips. It strengthens your glutes, hamstrings and back.\"},{\"id\":\"1551\",\"n\":\"dumbbell decline bench lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand facing away from a decline bench.\",\"Place the top of one foot on the bench behind you.\",\"Lower your hips straight down until your front thigh is about parallel to the floor.\",\"Keep your torso upright and your front knee tracking over your toes.\",\"Push through your front foot to rise, then switch legs after your reps.\"],\"img\":\"1551.webp\",\"gif\":\"1551.mp4\",\"cat\":\"strength\",\"desc\":\"A rear-foot-elevated lunge using a decline bench and dumbbells. The raised back foot shifts the load onto the front leg.\"},{\"id\":\"4733\",\"n\":\"dumbbell decline lying leg curl\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie face down on a decline bench with the dumbbell held between your feet.\",\"Let your legs hang straight with your hips pressed to the bench.\",\"Curl your heels up toward your glutes.\",\"Squeeze at the top without lifting your hips.\",\"Lower slowly to full extension.\"],\"img\":\"4733.webp\",\"gif\":\"4733.mp4\",\"cat\":\"strength\",\"desc\":\"A leg curl lying on a decline bench with a dumbbell gripped between your feet. It isolates the hamstrings.\"},{\"id\":\"4734\",\"n\":\"dumbbell decline overhead sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"shoulders\"],\"st\":[\"Hook your feet on a decline bench and lie back holding a dumbbell above your chest.\",\"Extend your arms overhead behind you.\",\"Curl your torso up, keeping the dumbbell over your head.\",\"Reach the top with your arms above your knees.\",\"Lower back slowly with control.\"],\"img\":\"4734.webp\",\"gif\":\"4734.mp4\",\"cat\":\"strength\",\"desc\":\"A decline sit-up holding a dumbbell overhead. The long lever makes your abs work harder.\"},{\"id\":\"4735\",\"n\":\"dumbbell decline sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"obliques\"],\"st\":[\"Secure your feet on a decline bench and hold a dumbbell against your chest.\",\"Lie back until your torso is just above the bench.\",\"Curl up until your torso is upright.\",\"Keep your neck relaxed and avoid pulling on your head.\",\"Lower slowly to the start.\"],\"img\":\"4735.webp\",\"gif\":\"4735.mp4\",\"cat\":\"strength\",\"desc\":\"A decline sit-up with a dumbbell held on your chest to add resistance for the abs.\"},{\"id\":\"4736\",\"n\":\"dumbbell deep push up and renegade row\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"lats\",\"core\",\"shoulders\",\"upper back\"],\"st\":[\"Start in a plank with hands on two dumbbells, feet wide.\",\"Lower your chest between the dumbbells in a deep push-up.\",\"Press back up to a plank.\",\"Row one dumbbell to your ribs while bracing to stay level.\",\"Lower it, row the other side, and repeat.\"],\"img\":\"4736.webp\",\"gif\":\"4736.mp4\",\"cat\":\"strength\",\"desc\":\"A combo of a deep push-up on dumbbells and a renegade row. It trains chest, back and core together.\"},{\"id\":\"4164\",\"n\":\"dumbbell devils press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"triceps\"],\"st\":[\"Stand holding a dumbbell in each hand.\",\"Squat and place the dumbbells on the floor, then step or jump your feet back.\",\"Do a push up if you like.\",\"Jump your feet forward and stand up, swinging the dumbbells overhead.\",\"Lower the dumbbells under control.\",\"Keep your back flat and move with rhythm.\"],\"img\":\"4164.webp\",\"gif\":\"4164.mp4\",\"cat\":\"strength\",\"desc\":\"A full body move: burpee onto dumbbells, then swing them overhead. It builds power and conditioning.\"},{\"id\":\"3687\",\"n\":\"dumbbell drag bicep curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Stand tall holding a dumbbell in each hand, palms forward.\",\"Pull your elbows back slightly and curl the weights up, keeping them close to your body.\",\"Squeeze your biceps at the top without letting your elbows drift forward.\",\"Lower the dumbbells slowly along the same path.\",\"Keep your torso still and avoid swinging.\"],\"img\":\"3687.webp\",\"gif\":\"3687.mp4\",\"cat\":\"strength\",\"desc\":\"A curl where the dumbbells travel up close to your torso, dragging along your body. It keeps tension on the biceps and limits shoulder swing.\"},{\"id\":\"9690\",\"n\":\"dumbbell elevated heel front squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\"],\"st\":[\"Place your heels on small plates and hold a dumbbell at your chest.\",\"Brace your core and keep your elbows up.\",\"Sit down into a deep squat.\",\"Keep your chest tall and knees tracking over toes.\",\"Drive up to stand.\"],\"img\":\"9690.webp\",\"gif\":\"9690.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat with a dumbbell and raised heels, which keeps your torso upright and puts the work on the quads.\"},{\"id\":\"5819\",\"n\":\"dumbbell empty can exercise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"trapezius\",\"upper chest\"],\"st\":[\"Hold light dumbbells with your thumbs pointing down.\",\"Stand tall with arms at your sides.\",\"Raise your arms diagonally forward to shoulder height.\",\"Hold briefly without shrugging.\",\"Lower slowly with control.\"],\"img\":\"5819.webp\",\"gif\":\"5819.mp4\",\"cat\":\"strength\",\"desc\":\"Raise light dumbbells with thumbs pointing down, as if emptying a can. It targets the front and side shoulder.\"},{\"id\":\"3684\",\"n\":\"dumbbell external rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Lie on your side with a dumbbell in the top hand and elbow bent.\",\"Keep your elbow tucked at your side.\",\"Rotate your forearm upward.\",\"Lower slowly.\",\"Switch sides after the set.\"],\"img\":\"3684.webp\",\"gif\":\"3684.mp4\",\"cat\":\"strength\",\"desc\":\"A light external rotation for the rotator cuff.\"},{\"id\":\"4125\",\"n\":\"dumbbell face down lying shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"rear deltoids\"],\"st\":[\"Lie face down on an incline bench holding dumbbells at ear height.\",\"Press the dumbbells up and slightly back.\",\"Pause at the top.\",\"Lower slowly.\",\"Keep your chest on the bench.\"],\"img\":\"4125.webp\",\"gif\":\"4125.mp4\",\"cat\":\"strength\",\"desc\":\"A face down press on an incline bench that works the rear shoulder.\"},{\"id\":\"2917\",\"n\":\"dumbbell farmers carry\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"trapezius\",\"core\",\"glutes\",\"upper back\"],\"st\":[\"Hold a dumbbell in each hand at your sides and stand tall.\",\"Pull your shoulders back and down and brace your abs.\",\"Walk with quick, controlled steps without swinging the weights.\",\"Cover the set distance, then lower the dumbbells safely.\"],\"img\":\"2917.webp\",\"gif\":\"2917.mp4\",\"cat\":\"strength\",\"desc\":\"Walking while holding a heavy dumbbell in each hand. It builds grip strength, traps and overall posture.\"},{\"id\":\"3968\",\"n\":\"dumbbell flat around the world\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"lats\"],\"st\":[\"Lie on a flat bench with dumbbells over your chest.\",\"Keep your arms nearly straight.\",\"Lower them out and back in a wide arc.\",\"Take them down toward your hips.\",\"Reverse the arc with control.\"],\"img\":\"3968.webp\",\"gif\":\"3968.mp4\",\"cat\":\"strength\",\"desc\":\"Sweep dumbbells from your hips to overhead in a wide arc on a flat bench. It works the shoulders and chest through a long range.\",\"nd\":[\"bench\"]},{\"id\":\"1450\",\"n\":\"dumbbell flat flye hold\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Lie flat on a bench with a dumbbell in each hand above your chest.\",\"Open your arms wide with soft elbows until the dumbbells are level with your chest.\",\"Keep your shoulder blades pinned back and your feet planted.\",\"Hold the position for 15-30 seconds without letting the weights drop.\",\"Bring the dumbbells back together over your chest and set them down carefully.\"],\"img\":\"1450.webp\",\"gif\":\"1450.mp4\",\"cat\":\"isometric\",\"desc\":\"A static hold at the bottom of a flat flye. It builds chest tension and control in the stretched position.\",\"hd\":1,\"nd\":[\"bench\"]},{\"id\":\"4149\",\"n\":\"dumbbell floor fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"upper chest\"],\"st\":[\"Lie on your back with knees bent and a dumbbell in each hand above your chest.\",\"Soften your elbows slightly and keep that bend.\",\"Open your arms wide until your upper arms touch the floor.\",\"Pause briefly without resting your weight.\",\"Squeeze your chest to bring the dumbbells back together above you.\",\"Move slowly and keep your wrists stacked over your elbows.\"],\"img\":\"4149.webp\",\"gif\":\"4149.mp4\",\"cat\":\"strength\",\"desc\":\"A chest fly performed lying on the floor, which limits the range at the bottom to protect the shoulders. It isolates the pecs.\"},{\"id\":\"4737\",\"n\":\"dumbbell floor wiper\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"hip flexors\"],\"st\":[\"Lie on your back holding a dumbbell above your chest with straight arms.\",\"Lift your legs straight up over your hips.\",\"Lower both legs to one side without touching the floor.\",\"Bring them back to the middle.\",\"Repeat to the other side, keeping your shoulders flat.\"],\"img\":\"4737.webp\",\"gif\":\"4737.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back with a dumbbell held overhead, you swing your legs side to side like a wiper. It challenges the obliques.\"},{\"id\":\"3175\",\"n\":\"dumbbell fly (knees at 90 degrees)\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\",\"upper chest\",\"core\"],\"st\":[\"Lie on a bench holding dumbbells above your chest.\",\"Lift your feet so your knees are bent to 90 degrees.\",\"Keep a slight bend in your elbows.\",\"Open your arms out wide until you feel a chest stretch.\",\"Bring the dumbbells back together over your chest.\",\"Move slowly and keep your back flat.\"],\"img\":\"3175.webp\",\"gif\":\"3175.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly with your feet lifted and knees at 90 degrees. It stretches the chest and keeps your back flat.\",\"nd\":[\"bench\"]},{\"id\":\"1175\",\"n\":\"dumbbell forward leaning lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand tall with your feet hip width apart.\",\"Step forward with one foot and lean your chest slightly forward with a flat back.\",\"Lower until both knees are bent about 90 degrees.\",\"Push through the front heel to return to standing.\",\"Alternate legs or finish all reps on one side before switching.\"],\"img\":\"1175.webp\",\"gif\":\"1175.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge with a forward torso lean that shifts more of the load onto the glutes and hamstrings.\"},{\"id\":\"6160\",\"n\":\"dumbbell frog hip thrust\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Lie on your back with the soles of your feet together and knees out.\",\"Rest a dumbbell on your hips.\",\"Drive your hips up by pressing through your feet.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\",\"Keep your ribs down.\"],\"img\":\"6160.webp\",\"gif\":\"6160.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with the soles of your feet together and knees out, holding a dumbbell on your hips. It focuses on the glutes.\"},{\"id\":\"4627\",\"n\":\"dumbbell front plank arm leg raise\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\"],\"st\":[\"Start in a high plank with a dumbbell in one hand.\",\"Brace your abs and squeeze your glutes.\",\"Lift the dumbbell forward and the opposite leg back at the same time.\",\"Lower both under control.\",\"Alternate sides each rep.\"],\"img\":\"4627.webp\",\"gif\":\"4627.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank where you lift a dumbbell and the opposite leg at once, testing your balance and core control.\"},{\"id\":\"4622\",\"n\":\"dumbbell front plank arm raise\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Start in a forearm or high plank with a dumbbell in one hand.\",\"Brace your abs and keep hips level.\",\"Lift the dumbbell forward in line with your torso.\",\"Lower it with control.\",\"Alternate arms for the set.\"],\"img\":\"4622.webp\",\"gif\":\"4622.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank with one arm lifting a dumbbell forward, challenging your core to stay still.\"},{\"id\":\"3398\",\"n\":\"dumbbell front rack lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell in each hand at shoulder height.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor.\",\"Keep your torso upright and your front knee over your ankle.\",\"Push back to the start.\",\"Alternate legs for each rep.\"],\"img\":\"3398.webp\",\"gif\":\"3398.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge with dumbbells held at your shoulders, which challenges your legs and trunk.\"},{\"id\":\"3428\",\"n\":\"dumbbell front raise v. 3\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\"],\"st\":[\"Stand tall holding a dumbbell in each hand in front of your thighs.\",\"Brace your core and keep a slight bend in your elbows.\",\"Raise the weights in front of you to shoulder height.\",\"Pause briefly.\",\"Lower slowly without swinging your body.\"],\"img\":\"3428.webp\",\"gif\":\"3428.mp4\",\"cat\":\"strength\",\"desc\":\"Lift dumbbells in front of you to work the front of the shoulders.\"},{\"id\":\"2966\",\"n\":\"dumbbell front squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Hold a dumbbell in each hand at your shoulders, elbows forward.\",\"Stand with your feet shoulder-width apart.\",\"Squat down until your thighs are about parallel.\",\"Keep your chest up and knees tracking your toes.\",\"Drive through your heels to stand.\"],\"img\":\"2966.webp\",\"gif\":\"2966.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with dumbbells held at your shoulders. The front load keeps your chest upright and challenges the quads and core.\",\"fv\":\"2967\"},{\"id\":\"10559\",\"n\":\"dumbbell full front raise catch\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\",\"forearms\"],\"st\":[\"Stand tall holding a dumbbell with both hands in front of your thighs.\",\"Raise it straight up in front of you to overhead.\",\"Control it at the top and keep your core braced.\",\"Lower it slowly back down.\",\"Use a moderate weight and avoid arching your back.\"],\"img\":\"10559.webp\",\"gif\":\"10559.mp4\",\"cat\":\"strength\",\"desc\":\"Raise a dumbbell in front of you all the way overhead and catch it with control. It trains the front shoulder.\"},{\"id\":\"3397\",\"n\":\"dumbbell full swing\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Hold one dumbbell with both hands and stand with feet shoulder-width apart.\",\"Hinge back and swing the weight between your legs.\",\"Drive your hips forward to swing the dumbbell overhead.\",\"Let it fall back and hinge again.\",\"Keep your back flat and your arms loose.\",\"Control the dumbbell at all times.\"],\"img\":\"3397.webp\",\"gif\":\"3397.mp4\",\"cat\":\"strength\",\"desc\":\"A hip-driven swing with a dumbbell, taking the weight from between the legs to overhead.\"},{\"id\":\"3335\",\"n\":\"dumbbell glute bridge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and feet flat on the floor.\",\"Hold a dumbbell across your hips.\",\"Drive through your heels and lift your hips toward the ceiling.\",\"Squeeze your glutes hard at the top.\",\"Lower your hips slowly and repeat.\"],\"img\":\"3335.webp\",\"gif\":\"3335.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded hip bridge that targets your glutes. Resting a dumbbell on your hips adds resistance.\",\"fv\":\"3427\"},{\"id\":\"7994\",\"n\":\"dumbbell glute bridge chest press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Lie on your back holding dumbbells at chest level, knees bent.\",\"Lift your hips into a bridge.\",\"Press the dumbbells up over your chest.\",\"Lower with control while holding your hips high.\",\"Finish your reps, then lower your hips.\"],\"img\":\"7994.webp\",\"gif\":\"7994.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell chest press done lying in a glute bridge. It works the chest and triceps while the glutes hold your hips up.\"},{\"id\":\"4751\",\"n\":\"dumbbell glute bridge v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Rest a dumbbell on your hips and hold it in place.\",\"Drive through your heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4751.webp\",\"gif\":\"4751.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with a dumbbell resting on your hips. It strengthens the glutes and hamstrings.\"},{\"id\":\"7590\",\"n\":\"dumbbell glute dominant bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand with your back foot on a bench.\",\"Step the front foot out far enough for your shin to stay near vertical.\",\"Lean your torso forward slightly.\",\"Lower until the thigh is parallel.\",\"Drive through your front heel to rise.\",\"Finish all reps, then switch sides.\"],\"img\":\"7590.webp\",\"gif\":\"7590.mp4\",\"cat\":\"strength\",\"desc\":\"A rear-foot-elevated split squat with a forward lean, loading the glutes.\"},{\"id\":\"5314\",\"n\":\"dumbbell glute dominant step up\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and face a bench or box.\",\"Place one foot fully on the box and lean your torso slightly forward.\",\"Push through the heel of that foot to stand up.\",\"Squeeze your glute at the top.\",\"Lower with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"5314.webp\",\"gif\":\"5314.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with a forward lean and a high box that shifts the work onto the glutes.\"},{\"id\":\"4816\",\"n\":\"dumbbell goblet 2 sec hold squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\",\"hamstrings\"],\"st\":[\"Hold one dumbbell vertically against your chest with both hands.\",\"Stand with feet shoulder-width apart and toes slightly out.\",\"Squat down with your chest tall until your thighs are at least parallel.\",\"Hold the bottom position for two seconds.\",\"Drive through your heels to stand.\"],\"img\":\"4816.webp\",\"gif\":\"4816.mp4\",\"cat\":\"strength\",\"desc\":\"A goblet squat with a two-second pause in the bottom. The pause builds leg strength and control out of the hole.\"},{\"id\":\"3692\",\"n\":\"dumbbell goblet box squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Place a box or bench behind you and hold a dumbbell at your chest.\",\"Stand with your feet shoulder width apart.\",\"Push your hips back and lower until you lightly touch the box.\",\"Keep your chest up and knees in line with your toes.\",\"Drive through your heels to stand up without rocking.\"],\"img\":\"3692.webp\",\"gif\":\"3692.mp4\",\"cat\":\"strength\",\"desc\":\"A goblet squat that touches a box behind you, teaching depth control and sitting back into your hips.\",\"fv\":\"11320\"},{\"id\":\"7549\",\"n\":\"dumbbell goblet bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Place your rear foot on a bench and hold a dumbbell at your chest.\",\"Step the front foot forward.\",\"Lower your back knee toward the floor.\",\"Keep your torso tall.\",\"Push through the front heel and switch legs after your reps.\"],\"img\":\"7549.webp\",\"gif\":\"7549.mp4\",\"cat\":\"strength\",\"desc\":\"Rear-foot elevated split squat with a dumbbell held at the chest.\"},{\"id\":\"3683\",\"n\":\"dumbbell goblet curtsey lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell at your chest.\",\"Step one leg behind and across the other.\",\"Lower until both knees bend.\",\"Press through the front leg to return.\",\"Alternate legs for the set.\"],\"img\":\"3683.webp\",\"gif\":\"3683.mp4\",\"cat\":\"strength\",\"desc\":\"Hold a dumbbell at your chest and step behind and across into a curtsey lunge.\"},{\"id\":\"3691\",\"n\":\"dumbbell goblet split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold one dumbbell vertically against your chest and step into a split stance.\",\"Keep your torso tall and lower your back knee toward the floor.\",\"Stop when your front thigh is about parallel to the ground.\",\"Push through your front foot to stand back up.\",\"Finish your reps, then switch legs.\"],\"img\":\"3691.webp\",\"gif\":\"3691.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat holding one dumbbell at your chest. Great for working each leg on its own while the front load keeps you upright.\"},{\"id\":\"2956\",\"n\":\"dumbbell goblet split squat front foot elevated\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold one dumbbell at your chest and place your front foot on a low platform.\",\"Place your back foot behind you on the floor.\",\"Lower your back knee toward the floor with your torso upright.\",\"Push through your front heel to stand.\",\"Finish the reps, then switch legs.\"],\"img\":\"2956.webp\",\"gif\":\"2956.mp4\",\"cat\":\"strength\",\"desc\":\"A goblet split squat with the front foot on a raised platform. The extra height deepens the range for the quads and glutes.\",\"fv\":\"2955\"},{\"id\":\"5028\",\"n\":\"dumbbell goblet split squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell vertically at your chest and step into a long split stance.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Drive through your front heel to stand back up.\",\"Finish your reps, then switch legs.\"],\"img\":\"5028.webp\",\"gif\":\"5028.mp4\",\"cat\":\"strength\",\"desc\":\"Split squat holding one dumbbell at your chest. It builds the legs and glutes one side at a time.\"},{\"id\":\"4738\",\"n\":\"dumbbell goblet squat and biceps curl\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"biceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart holding a dumbbell by one end at your chest.\",\"Squat down with your chest up and elbows inside your knees.\",\"At the bottom, lower the dumbbell and curl it back up.\",\"Drive through your heels to stand.\",\"Repeat the full sequence for each rep.\"],\"img\":\"4738.webp\",\"gif\":\"4738.mp4\",\"cat\":\"strength\",\"desc\":\"A goblet squat followed by a biceps curl in the bottom position. It combines leg and arm work in one rep.\"},{\"id\":\"7469\",\"n\":\"dumbbell goblet squat with calf raise\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Hold a dumbbell at your chest.\",\"Squat down with your chest up.\",\"Drive up to standing.\",\"Rise onto your toes at the top.\",\"Lower your heels and go into the next squat.\"],\"img\":\"7469.webp\",\"gif\":\"7469.mp4\",\"cat\":\"strength\",\"desc\":\"Goblet squat finished with a calf raise as you stand.\"},{\"id\":\"7547\",\"n\":\"dumbbell goblet sumo squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"inner thighs\",\"core\"],\"st\":[\"Stand with feet wide and toes out, holding a dumbbell at your chest.\",\"Keep your chest up.\",\"Squat down between your legs.\",\"Keep your knees pointing over your toes.\",\"Drive up and squeeze your glutes.\"],\"img\":\"7547.webp\",\"gif\":\"7547.mp4\",\"cat\":\"strength\",\"desc\":\"Wide-stance goblet squat that targets the glutes and inner thighs.\"},{\"id\":\"7559\",\"n\":\"dumbbell goblet wall sit\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\"],\"st\":[\"Hold a dumbbell at your chest and lean on a wall.\",\"Slide down until thighs are parallel.\",\"Keep your knees above your ankles.\",\"Hold for 20-45 seconds.\",\"Stand up slowly.\"],\"img\":\"7559.webp\",\"gif\":\"7559.mp4\",\"cat\":\"isometric\",\"desc\":\"Wall sit holding a dumbbell at the chest for extra load.\",\"hd\":1},{\"id\":\"6424\",\"n\":\"dumbbell good morning\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand with feet hip-width apart, holding one dumbbell against your chest.\",\"Soften your knees slightly.\",\"Push your hips back and lean your torso forward with a flat back.\",\"Stop when you feel a stretch in your hamstrings.\",\"Drive your hips forward to stand tall.\"],\"img\":\"6424.webp\",\"gif\":\"6424.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge holding a dumbbell at your chest, training hamstrings, glutes and lower back.\"},{\"id\":\"5313\",\"n\":\"dumbbell good morning squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"core\"],\"st\":[\"Hold a dumbbell at your chest and stand with feet shoulder-width apart.\",\"Hinge at your hips with a flat back until you feel a hamstring stretch.\",\"Stand back up and then sit down into a squat.\",\"Drive up through your heels.\",\"Repeat the hinge and squat as one rep.\",\"Keep your chest up throughout.\"],\"img\":\"5313.webp\",\"gif\":\"5313.mp4\",\"cat\":\"strength\",\"desc\":\"Blend a good morning hinge with a squat while holding a dumbbell. Builds the posterior chain and legs.\"},{\"id\":\"7566\",\"n\":\"dumbbell hack squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Hold dumbbells behind you with your heels slightly raised.\",\"Keep your chest up.\",\"Squat down.\",\"Stay tall.\",\"Drive up through your feet.\"],\"img\":\"7566.webp\",\"gif\":\"7566.mp4\",\"cat\":\"strength\",\"desc\":\"Hack squat with dumbbells held behind the legs.\"},{\"id\":\"4572\",\"n\":\"dumbbell half kneeling lift and chop\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Kneel on one knee with the other foot forward and hold a dumbbell with both hands.\",\"Start with the weight by your low outside hip.\",\"Lift the dumbbell diagonally across your body to above the opposite shoulder.\",\"Rotate your torso and keep your hips square.\",\"Chop it back down along the same line.\",\"Finish your reps, then switch sides.\"],\"img\":\"4572.webp\",\"gif\":\"4572.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal dumbbell pattern from a half kneeling stance that trains rotational core strength.\"},{\"id\":\"4577\",\"n\":\"dumbbell half kneeling military press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel on one knee with the other foot in front and dumbbells at your shoulders.\",\"Squeeze the glute of the kneeling leg.\",\"Brace your core and keep your ribs down.\",\"Press the dumbbells overhead until your arms are straight.\",\"Lower slowly to shoulder height.\",\"Switch your lead leg halfway through or on the next set.\"],\"img\":\"4577.webp\",\"gif\":\"4577.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead dumbbell press from a half kneeling stance, adding core and hip stability.\"},{\"id\":\"10117\",\"n\":\"dumbbell half kneeling single arm clean press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper back\",\"glutes\"],\"st\":[\"Kneel on one knee with the dumbbell on the floor by your front foot and grab it.\",\"Pull the dumbbell up to your shoulder in one smooth motion, rotating your wrist.\",\"Press it overhead until your arm is straight.\",\"Lower it back to your shoulder, then to the floor with control.\",\"Keep your torso upright. Finish the reps, then switch sides.\"],\"img\":\"10117.webp\",\"gif\":\"10117.mp4\",\"cat\":\"strength\",\"desc\":\"A half kneeling clean and press that trains the shoulder while the stance forces your core and hips to stay stable.\"},{\"id\":\"11016\",\"n\":\"dumbbell half kneeling single arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel on one knee with the other foot flat in front, and hold a dumbbell at shoulder height.\",\"Brace your core and squeeze the glute of the kneeling leg.\",\"Press the dumbbell straight overhead until your arm is extended.\",\"Lower it under control back to your shoulder.\",\"Finish your reps, then switch sides.\"],\"img\":\"11016.webp\",\"gif\":\"11016.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press from a half kneeling stance. It trains the shoulder while the position challenges your balance and core.\"},{\"id\":\"10093\",\"n\":\"dumbbell half kneeling thor lift\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"hip flexors\"],\"st\":[\"Kneel in a half-kneeling position and hold a dumbbell near the outside of your back hip.\",\"Brace your abs and keep your torso upright.\",\"Lift the dumbbell diagonally up and across your body.\",\"Finish with it above the opposite shoulder.\",\"Lower along the same path.\",\"Finish reps, then switch sides.\"],\"img\":\"10093.webp\",\"gif\":\"10093.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal lift from low to high while half kneeling, working the trunk, hips and shoulders together.\"},{\"id\":\"2485\",\"n\":\"dumbbell hammer curl v. 3\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding dumbbells at your sides with palms facing in.\",\"Keep your elbows close to your torso.\",\"Curl the dumbbells up toward your shoulders.\",\"Keep your wrists straight.\",\"Squeeze at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2485.webp\",\"gif\":\"2485.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with a neutral grip that works the biceps and forearms.\"},{\"id\":\"3320\",\"n\":\"dumbbell hammer grip incline bench two arm row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"rhomboids\"],\"st\":[\"Set a bench to a low incline and lie chest down on it with a dumbbell in each hand.\",\"Let your arms hang with palms facing each other.\",\"Row both dumbbells toward your hips, leading with your elbows.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly to full arm extension and repeat.\"],\"img\":\"3320.webp\",\"gif\":\"3320.mp4\",\"cat\":\"strength\",\"desc\":\"A chest supported row on an incline bench with a neutral grip. It targets the mid back with little strain on your lower back.\",\"fv\":\"3901\"},{\"id\":\"5921\",\"n\":\"dumbbell hammer preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit at a preacher bench with your upper arms resting on the pad.\",\"Hold a dumbbell with palm facing in, thumb up.\",\"Curl the weight up toward your shoulder.\",\"Squeeze at the top, then lower slowly until your arm is nearly straight.\",\"Complete your reps, then switch arms or alternate.\"],\"img\":\"5921.webp\",\"gif\":\"5921.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with a neutral hammer grip that targets the brachialis and forearms along with the biceps.\",\"fv\":\"4337\"},{\"id\":\"4449\",\"n\":\"dumbbell hang clean\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"quadriceps\",\"shoulders\",\"core\"],\"st\":[\"Stand holding dumbbells at your thighs, then push your hips back to lower them to the knees.\",\"Keep your back flat and arms straight.\",\"Drive your hips forward powerfully and shrug.\",\"Pull the dumbbells up close to your body and rotate your elbows under them.\",\"Catch them on your shoulders in a slight quarter squat.\",\"Stand tall, then lower them back to your thighs and reset.\"],\"img\":\"4449.webp\",\"gif\":\"4449.mp4\",\"cat\":\"olympic\",\"desc\":\"Explosive lift taking dumbbells from hip level to the shoulders. Builds power through the hips and back.\"},{\"id\":\"4377\",\"n\":\"dumbbell hang clean and jerk\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"shoulders\",\"triceps\",\"upper back\"],\"st\":[\"Stand with feet hip-width apart, holding a dumbbell hanging in front of your thighs.\",\"Hinge at the hips, then drive them forward and shrug as you pull the dumbbell up.\",\"Drop under it and catch it at your shoulder with a slight knee bend.\",\"Dip a little, then drive up through your legs and press the dumbbell overhead.\",\"Lower it back to your shoulder, then to the hang under control.\"],\"img\":\"4377.webp\",\"gif\":\"4377.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive lift that takes a dumbbell from the hang to your shoulder and then overhead. It builds power through the hips, legs and shoulders.\"},{\"id\":\"4739\",\"n\":\"dumbbell hang power clean\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"quadriceps\",\"shoulders\",\"core\"],\"st\":[\"Stand holding dumbbells and hinge until they hang just above your knees.\",\"Keep your back flat and arms straight.\",\"Drive your hips forward and shrug as you pull the weights up.\",\"Drop under them and catch at your shoulders in a quarter squat.\",\"Stand tall, then lower to the hang and repeat.\"],\"img\":\"4739.webp\",\"gif\":\"4739.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive pull that takes dumbbells from the hang position to your shoulders. It builds power in the hips and back.\"},{\"id\":\"4740\",\"n\":\"dumbbell hang power clean and jerk\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"quadriceps\",\"hamstrings\",\"trapezius\"],\"st\":[\"Hold dumbbells hanging just above your knees with a flat back.\",\"Explode up and pull the weights to your shoulders, catching in a quarter squat.\",\"Stand tall, then dip slightly with your knees.\",\"Drive up and press the dumbbells overhead.\",\"Lower to your shoulders, then to the hang, and reset.\"],\"img\":\"4740.webp\",\"gif\":\"4740.mp4\",\"cat\":\"olympic\",\"desc\":\"A hang power clean followed by an overhead jerk. It is a full-body power move for hips, legs and shoulders.\"},{\"id\":\"10044\",\"n\":\"dumbbell hang snatch\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Stand with a dumbbell hanging in front of your thighs, hips hinged slightly.\",\"Drive your hips forward and shrug.\",\"Pull the dumbbell up close to your body.\",\"Punch it overhead and catch it with a straight arm.\",\"Stand tall, then lower back to the hang.\",\"Switch arms and keep the weight light enough to move fast.\"],\"img\":\"10044.webp\",\"gif\":\"10044.mp4\",\"cat\":\"olympic\",\"desc\":\"A powerful one-arm lift where the dumbbell goes from hip height to overhead in one motion.\"},{\"id\":\"4741\",\"n\":\"dumbbell head supported row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"rear deltoids\",\"biceps\"],\"st\":[\"Set a bench at a slight incline and lie chest down on it with a dumbbell in each hand.\",\"Rest your forehead on the top and let your arms hang.\",\"Row both dumbbells toward your ribs.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly to straight arms.\"],\"img\":\"4741.webp\",\"gif\":\"4741.mp4\",\"cat\":\"strength\",\"desc\":\"A row with your forehead resting on a bench pad so your lower back stays relaxed. It focuses on the upper back.\"},{\"id\":\"2911\",\"n\":\"dumbbell high low carry\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"obliques\",\"forearms\",\"grip muscles\"],\"st\":[\"Hold one dumbbell overhead with a locked, stable arm and the other at your side.\",\"Stand tall with your ribs down and abs braced.\",\"Walk with steady steps and keep the top arm stacked over your shoulder.\",\"Walk the set distance, then lower the weights carefully.\",\"Swap positions and repeat.\"],\"img\":\"2911.webp\",\"gif\":\"2911.mp4\",\"cat\":\"strength\",\"desc\":\"A walking carry with one dumbbell overhead and one at your side. The mismatch trains shoulder stability and trunk control.\"},{\"id\":\"5666\",\"n\":\"dumbbell high pull\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"glutes\",\"hamstrings\",\"quadriceps\"],\"st\":[\"Stand with feet shoulder-width apart, dumbbells hanging in front of your thighs.\",\"Bend your knees and hips slightly, keeping your chest up.\",\"Extend your hips and knees powerfully and pull the weights up with elbows leading.\",\"Stop at about chest height, elbows above your wrists.\",\"Lower the dumbbells under control and reset.\"],\"img\":\"5666.webp\",\"gif\":\"5666.mp4\",\"cat\":\"strength\",\"desc\":\"An explosive pull that drives dumbbells up to chest height using the legs and hips. It builds the shoulders and traps and trains power.\"},{\"id\":\"11058\",\"n\":\"dumbbell hip supported romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with your hips lightly against the support, holding dumbbells in front of your thighs.\",\"Soften your knees and keep your back flat.\",\"Push your hips back and slide the dumbbells down your legs.\",\"Stop when you feel a stretch in your hamstrings.\",\"Drive your hips forward to stand tall.\"],\"img\":\"11058.webp\",\"gif\":\"11058.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift with your hips supported against a surface. It teaches a clean hip hinge and loads the hamstrings.\"},{\"id\":\"4742\",\"n\":\"dumbbell hip thrust\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit on the floor with your upper back against a bench and a dumbbell across your hips.\",\"Plant your feet hip-width apart, knees bent.\",\"Drive through your heels and lift your hips until your torso is level.\",\"Squeeze your glutes at the top with your chin tucked.\",\"Lower your hips under control.\"],\"img\":\"4742.webp\",\"gif\":\"4742.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with a dumbbell across your hips. It is a direct way to build the glutes.\"},{\"id\":\"5754\",\"n\":\"dumbbell hip thrust v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit with your upper back against a bench and a dumbbell on your hips.\",\"Plant your feet flat, shoulder-width apart.\",\"Drive through your heels and lift your hips until your torso is level.\",\"Squeeze your glutes at the top with your chin tucked.\",\"Lower under control and repeat.\"],\"img\":\"5754.webp\",\"gif\":\"5754.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with a dumbbell resting on your hips. Strong glute builder for the glutes.\"},{\"id\":\"7328\",\"n\":\"dumbbell hyperextension\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\"],\"st\":[\"Set up on a hyperextension bench with the pads at your hips.\",\"Hold a dumbbell against your chest.\",\"Lower your torso with a flat back.\",\"Raise up until your body forms a straight line.\",\"Avoid overarching at the top.\"],\"img\":\"7328.webp\",\"gif\":\"7328.mp4\",\"cat\":\"strength\",\"desc\":\"Hyperextension with a dumbbell held to your chest to load the lower back and glutes.\"},{\"id\":\"10977\",\"n\":\"dumbbell hyperextension v. 2\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Set the pad at hip height and hold a dumbbell at your chest.\",\"Lower your torso with a flat back.\",\"Lift until you are in a straight line.\",\"Squeeze your glutes.\",\"Lower slowly.\",\"Do not overextend.\"],\"img\":\"10977.webp\",\"gif\":\"10977.mp4\",\"cat\":\"strength\",\"desc\":\"Back extension holding a dumbbell. It trains the lower back and glutes.\"},{\"id\":\"1449\",\"n\":\"dumbbell incline 30 degrees flye hold\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Set a bench to about 30 degrees and lie back with a dumbbell in each hand above your chest.\",\"Open your arms wide with soft elbows until the dumbbells are level with your chest.\",\"Keep your shoulder blades pinned back and down.\",\"Hold the stretched position for 15-30 seconds without sagging.\",\"Bring the weights back together over your chest and set them down carefully.\"],\"img\":\"1449.webp\",\"gif\":\"1449.mp4\",\"cat\":\"isometric\",\"desc\":\"A static hold at the bottom of an incline flye. It teaches chest tension and builds control in the stretched position.\",\"hd\":1},{\"id\":\"3682\",\"n\":\"dumbbell incline alternate bicep curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit back on an incline bench with dumbbells hanging down.\",\"Curl one dumbbell up with the palm facing up.\",\"Lower it slowly.\",\"Curl the other arm.\",\"Keep your upper arms still.\"],\"img\":\"3682.webp\",\"gif\":\"3682.mp4\",\"cat\":\"strength\",\"desc\":\"Curl dumbbells one at a time while lying back on an incline bench to stretch and work the biceps.\"},{\"id\":\"1233\",\"n\":\"dumbbell incline alternate hammer curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit back on an incline bench holding dumbbells with palms facing in.\",\"Let your arms hang straight down.\",\"Curl one dumbbell up without twisting your wrist.\",\"Lower it slowly and repeat with the other arm.\",\"Keep your upper arms still.\"],\"img\":\"1233.webp\",\"gif\":\"1233.mp4\",\"cat\":\"strength\",\"desc\":\"Hammer curls on an incline bench, one arm at a time. The stretched position makes the biceps and brachialis work hard.\"},{\"id\":\"3694\",\"n\":\"dumbbell incline alternate reverse fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\",\"trapezius\"],\"st\":[\"Lie chest down on an incline bench with a dumbbell in each hand, arms hanging.\",\"Raise one arm out to the side with a soft elbow until it is level with your shoulder.\",\"Squeeze your shoulder blade, then lower slowly.\",\"Repeat with the other arm.\",\"Keep your neck relaxed and avoid swinging.\"],\"img\":\"3694.webp\",\"gif\":\"3694.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported reverse fly done one arm at a time, aimed at the rear delts and upper back.\"},{\"id\":\"3967\",\"n\":\"dumbbell incline around the world\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper chest\",\"upper back\"],\"st\":[\"Lie back on an incline bench holding dumbbells over your chest.\",\"Keep your arms nearly straight.\",\"Lower them out to the sides in a wide arc.\",\"Continue down to your hips.\",\"Reverse the arc to return.\"],\"img\":\"3967.webp\",\"gif\":\"3967.mp4\",\"cat\":\"strength\",\"desc\":\"Swing dumbbells in a wide arc over your head while lying on an incline bench. It trains the shoulders and chest.\"},{\"id\":\"4973\",\"n\":\"dumbbell incline biceps curl (70 degrees)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Set a bench to 70 degrees and sit back with a dumbbell in each hand.\",\"Let your arms hang by your sides, palms forward.\",\"Curl the weights up without moving your elbows.\",\"Squeeze your biceps at the top.\",\"Lower slowly to a full stretch.\",\"Keep your back against the bench.\"],\"img\":\"4973.webp\",\"gif\":\"4973.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl seated on a bench set to 70 degrees. The slight lean keeps the arms hanging for a good stretch.\"},{\"id\":\"3764\",\"n\":\"dumbbell incline biceps curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit back on an incline bench with a dumbbell in each hand, arms hanging.\",\"Keep your shoulders against the bench.\",\"Curl both dumbbells toward your shoulders.\",\"Pause and squeeze.\",\"Lower slowly to a full stretch.\"],\"img\":\"3764.webp\",\"gif\":\"3764.mp4\",\"cat\":\"strength\",\"desc\":\"Curling from an incline bench stretches the biceps at the bottom for a deep contraction.\"},{\"id\":\"4743\",\"n\":\"dumbbell incline biceps curl v. 3\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Sit back on an incline bench with a dumbbell in each hand, arms hanging straight.\",\"Keep your elbows back and your shoulders against the bench.\",\"Curl both dumbbells toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are fully extended and repeat.\"],\"img\":\"4743.webp\",\"gif\":\"4743.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl sitting back on an incline bench. The stretch position works the biceps hard.\"},{\"id\":\"4015\",\"n\":\"dumbbell incline close grip press variation\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper chest\",\"shoulders\"],\"st\":[\"Lie on an incline bench with dumbbells together over your chest.\",\"Keep your elbows tucked.\",\"Lower to your chest.\",\"Press up.\",\"Keep the dumbbells touching.\"],\"img\":\"4015.webp\",\"gif\":\"4015.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip dumbbell press on an incline. It targets the triceps and upper chest.\"},{\"id\":\"1176\",\"n\":\"dumbbell incline front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\"],\"st\":[\"Lie face down or back on an incline bench holding dumbbells.\",\"Start with your arms hanging or in front of you.\",\"Raise the weights forward to shoulder height with straight arms.\",\"Pause briefly at the top.\",\"Lower slowly under control.\"],\"img\":\"1176.webp\",\"gif\":\"1176.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise performed lying on an incline bench to reduce swinging and isolate the front delts.\"},{\"id\":\"3980\",\"n\":\"dumbbell incline front raise with chest support\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"upper back\"],\"st\":[\"Lie chest down on an incline bench with dumbbells hanging.\",\"Keep a soft bend in the elbows.\",\"Raise the weights forward to shoulder height.\",\"Lower slowly.\",\"Keep your chest against the pad.\"],\"img\":\"3980.webp\",\"gif\":\"3980.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise done chest down on an incline bench. It isolates the front delts without momentum.\"},{\"id\":\"4744\",\"n\":\"dumbbell incline head supported row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lie chest down on an incline bench with a dumbbell in each hand.\",\"Rest your head on the top of the bench and let your arms hang.\",\"Pull your elbows back and the dumbbells toward your ribs.\",\"Pause and squeeze your shoulder blades.\",\"Lower slowly to full arm extension.\"],\"img\":\"4744.webp\",\"gif\":\"4744.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row on an incline bench with your head resting on the pad. It targets the upper back without loading the spine.\"},{\"id\":\"6162\",\"n\":\"dumbbell incline low fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Set a bench to a low incline and lie back.\",\"Hold dumbbells above your chest with a soft elbow bend.\",\"Open your arms out and down in an arc.\",\"Stop at a comfortable chest stretch.\",\"Bring the dumbbells back together.\",\"Keep the elbow bend constant.\"],\"img\":\"6162.webp\",\"gif\":\"6162.mp4\",\"cat\":\"strength\",\"desc\":\"A fly on an incline bench with the dumbbells traveling low. It stretches and works the chest.\"},{\"id\":\"4071\",\"n\":\"dumbbell incline one arm front raise with chest support\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"biceps\"],\"st\":[\"Set an incline bench and lie chest down on it.\",\"Hold a dumbbell in one hand hanging straight down.\",\"Raise the dumbbell forward to shoulder height with a slight elbow bend.\",\"Lower slowly.\",\"Finish the reps, then switch arms.\"],\"img\":\"4071.webp\",\"gif\":\"4071.mp4\",\"cat\":\"strength\",\"desc\":\"Front raise with your chest supported on an incline bench to reduce swinging. It isolates the front delts.\"},{\"id\":\"7252\",\"n\":\"dumbbell incline powell raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\"],\"st\":[\"Lie chest down on an incline bench holding a light dumbbell in one hand.\",\"Let the arm hang straight below your shoulder.\",\"Raise the dumbbell out to the side, leading with your elbow, up to shoulder height.\",\"Pause, then lower with control.\",\"Complete your reps and switch sides.\"],\"img\":\"7252.webp\",\"gif\":\"7252.mp4\",\"cat\":\"strength\",\"desc\":\"Raise performed lying face down on an incline bench, hitting the rear delts and the small rotator muscles.\"},{\"id\":\"2500\",\"n\":\"dumbbell incline rear fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\"],\"st\":[\"Lie face down on an incline bench with a dumbbell in each hand.\",\"Let your arms hang with a slight bend in the elbows.\",\"Raise the dumbbells out to the sides.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly.\",\"Keep your chest on the pad.\"],\"img\":\"2500.webp\",\"gif\":\"2500.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported rear fly on an incline bench that isolates the rear shoulders.\"},{\"id\":\"1214\",\"n\":\"dumbbell incline reverse grip 30 degrees bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\",\"biceps\"],\"st\":[\"Set a bench to about 30 degrees and lie back with dumbbells held palms facing you.\",\"Start with the dumbbells at your chest.\",\"Press them up until your arms are almost straight.\",\"Lower slowly back to your chest.\",\"Keep your elbows close to your body.\"],\"img\":\"1214.webp\",\"gif\":\"1214.mp4\",\"cat\":\"strength\",\"desc\":\"A low-incline dumbbell press with palms facing you. The reverse grip puts extra focus on the upper chest.\"},{\"id\":\"5261\",\"n\":\"dumbbell incline shoulders press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Set a bench to about 60 to 75 degrees and sit back with a dumbbell in each hand.\",\"Hold the weights at shoulder height.\",\"Press the dumbbells up until your arms are straight.\",\"Lower slowly to shoulder level.\",\"Keep your back against the pad.\"],\"img\":\"5261.webp\",\"gif\":\"5261.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell press on an incline bench. It trains the shoulders and upper chest.\",\"fv\":\"11438\"},{\"id\":\"7231\",\"n\":\"dumbbell incline single arm y raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rear deltoids\",\"upper back\"],\"st\":[\"Lie face down on an incline bench with a dumbbell in one hand.\",\"Let the arm hang straight down.\",\"Raise your arm forward and up in a Y shape, thumb up.\",\"Squeeze at the top.\",\"Lower slowly and switch arms after your reps.\"],\"img\":\"7231.webp\",\"gif\":\"7231.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported raise on an incline bench to a Y position with one arm. It builds the lower traps and rear delts.\"},{\"id\":\"5067\",\"n\":\"dumbbell incline squeeze press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Set a bench to a low incline and lie back with dumbbells pressed together over your chest.\",\"Keep squeezing them against each other the whole set.\",\"Lower them slowly to your upper chest.\",\"Press back up until your arms are straight.\",\"Keep your shoulder blades pinched back and feet planted.\"],\"img\":\"5067.webp\",\"gif\":\"5067.mp4\",\"cat\":\"strength\",\"desc\":\"Press two dumbbells held together up from an incline bench. The constant squeeze keeps the chest working through the whole rep.\",\"fv\":\"8000\"},{\"id\":\"7879\",\"n\":\"dumbbell incline triceps kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"forearms\"],\"st\":[\"Lie chest down on an incline bench with a dumbbell in each hand.\",\"Pin your upper arms to your sides.\",\"Straighten your elbows to kick the weights back.\",\"Squeeze your triceps.\",\"Return slowly.\",\"Keep your upper arms still.\"],\"img\":\"7879.webp\",\"gif\":\"7879.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported kickback on an incline bench that isolates the triceps.\"},{\"id\":\"6218\",\"n\":\"dumbbell incline twist press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Lie on an incline bench holding dumbbells at chest level.\",\"Palms face you.\",\"Press up, rotating your palms forward.\",\"Lock out at the top.\",\"Lower, rotating back.\",\"Keep your shoulders down.\"],\"img\":\"6218.webp\",\"gif\":\"6218.mp4\",\"cat\":\"strength\",\"desc\":\"An incline press where you rotate the dumbbells during the press. It works the upper chest.\"},{\"id\":\"4236\",\"n\":\"dumbbell incline two front raise with chest support\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Set a bench to an incline and lie chest down on it.\",\"Hold a dumbbell in each hand, arms hanging.\",\"Raise both arms forward to shoulder height or just above.\",\"Pause for a second.\",\"Lower under control.\",\"Keep your head neutral and your movement smooth.\"],\"img\":\"4236.webp\",\"gif\":\"4236.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with both arms while lying chest down on an incline bench. The support stops you from cheating with your back.\"},{\"id\":\"7648\",\"n\":\"dumbbell ipsilateral single leg stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Hold a dumbbell in the hand on the same side as your standing leg.\",\"Shift your weight to that leg with a soft knee.\",\"Hinge at the hips and reach the weight toward the floor.\",\"Extend the other leg straight behind you.\",\"Return to standing by squeezing your glute.\",\"Finish all reps, then switch sides.\"],\"img\":\"7648.webp\",\"gif\":\"7648.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg deadlift holding the dumbbell on the same side as the standing leg, for hamstrings and balance.\"},{\"id\":\"4048\",\"n\":\"dumbbell ipsilateral split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in one hand and step into a split stance, the dumbbell on the same side as your front leg.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Press through the front foot to rise.\",\"Finish the reps, then switch sides.\"],\"img\":\"4048.webp\",\"gif\":\"4048.mp4\",\"cat\":\"strength\",\"desc\":\"Split squat with the dumbbell held on the same side as the working front leg. It tests balance and leg strength.\"},{\"id\":\"7329\",\"n\":\"dumbbell jefferson curl\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"core\"],\"st\":[\"Stand on a low step holding a light dumbbell in front of you.\",\"Tuck your chin and slowly roll down one vertebra at a time.\",\"Let the dumbbell hang near your shins.\",\"Pause at the bottom, then roll up slowly.\",\"Keep the weight light and the movement smooth.\"],\"img\":\"7329.webp\",\"gif\":\"7329.mp4\",\"cat\":\"mobility\",\"desc\":\"Slow, light-loaded spinal roll down and up that builds control and flexibility in the back and hamstrings.\"},{\"id\":\"10987\",\"n\":\"dumbbell jump box\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand in front of a sturdy box holding a dumbbell in each hand.\",\"Dip into a quarter squat and swing your arms back.\",\"Jump onto the box, landing softly with bent knees.\",\"Stand tall on top.\",\"Step down carefully and reset.\"],\"img\":\"10987.webp\",\"gif\":\"10987.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A box jump holding dumbbells. It builds explosive leg power.\"},{\"id\":\"1552\",\"n\":\"dumbbell jumping squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart, holding a dumbbell in each hand at your sides.\",\"Squat down until your thighs are about parallel to the floor.\",\"Explode upward and jump as high as you can.\",\"Land softly on the balls of your feet and sink straight into the next squat.\",\"Keep your chest up and your knees tracking your toes.\"],\"img\":\"1552.webp\",\"gif\":\"1552.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive squat jump holding light dumbbells at your sides. It builds power in the legs and gets the heart pumping.\"},{\"id\":\"5554\",\"n\":\"dumbbell kas glute bridge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with your knees bent and feet flat, loaded as the exercise requires.\",\"Keep your shins roughly vertical with the knees kept slightly forward of the hips.\",\"Squeeze your glutes and press your hips up until your body forms a line.\",\"Pause for a second at the top without arching your back.\",\"Lower under control and repeat.\"],\"img\":\"5554.webp\",\"gif\":\"5554.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with a dumbbell on your hips and the knees kept slightly forward. Keeps tension on the glutes.\"},{\"id\":\"4745\",\"n\":\"dumbbell kneeling arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel tall holding dumbbells in front of your shoulders, palms facing you.\",\"Brace your core and squeeze your glutes.\",\"Press up while rotating your palms to face forward.\",\"Finish with your arms straight overhead.\",\"Reverse the rotation as you lower back to the start.\"],\"img\":\"4745.webp\",\"gif\":\"4745.mp4\",\"cat\":\"strength\",\"desc\":\"An Arnold press done from a kneeling position, which takes the legs out and challenges your core. It trains all three heads of the shoulder.\"},{\"id\":\"10200\",\"n\":\"dumbbell kneeling around head rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"core\",\"upper back\"],\"st\":[\"Kneel tall holding a dumbbell by one end at chest level.\",\"Circle the dumbbell around your head, keeping it close.\",\"Keep your ribs down and your hips still.\",\"Complete the circle back to the front.\",\"Do a few reps one way, then reverse direction.\"],\"img\":\"10200.webp\",\"gif\":\"10200.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling dumbbell halo that circles the weight around your head to warm up and mobilize the shoulders.\"},{\"id\":\"3686\",\"n\":\"dumbbell kneeling hold to stand\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"hamstrings\"],\"st\":[\"Kneel on both knees holding a dumbbell at your chest.\",\"Step one foot forward into a half-kneel.\",\"Drive through that foot to stand.\",\"Lower back into the kneeling position.\",\"Alternate lead legs.\"],\"img\":\"3686.webp\",\"gif\":\"3686.mp4\",\"cat\":\"strength\",\"desc\":\"Move from a kneeling position to standing while holding a dumbbell.\"},{\"id\":\"5064\",\"n\":\"dumbbell kneeling hold to stand clean grip\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"hamstrings\"],\"st\":[\"Kneel on one knee with the other foot flat in front and hold dumbbells at your shoulders.\",\"Brace your core and keep your chest up.\",\"Drive through the front foot to stand tall.\",\"Lower back down under control to half kneeling.\",\"Finish all reps, then switch legs.\"],\"img\":\"5064.webp\",\"gif\":\"5064.mp4\",\"cat\":\"strength\",\"desc\":\"Hold dumbbells at your shoulders from a half-kneeling position and rise to standing. It builds single-leg strength, hip drive and balance.\"},{\"id\":\"8502\",\"n\":\"dumbbell kneeling opposite shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"glutes\"],\"st\":[\"Kneel on one knee and hold a dumbbell at shoulder height in the hand opposite the raised knee.\",\"Keep your torso tall and glutes tight.\",\"Press the dumbbell overhead until your arm is straight.\",\"Lower under control to your shoulder.\",\"Finish the reps, then switch sides.\"],\"img\":\"8502.webp\",\"gif\":\"8502.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling one-arm press where the opposite knee is down, adding core and hip stability to the shoulder work.\"},{\"id\":\"11017\",\"n\":\"dumbbell kneeling single arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel on both knees with your hips tall and hold a dumbbell at shoulder height.\",\"Brace your abs and keep your ribs down.\",\"Press the dumbbell overhead until your arm is straight.\",\"Lower it slowly back to your shoulder without leaning sideways.\",\"Complete your reps, then switch arms.\"],\"img\":\"11017.webp\",\"gif\":\"11017.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press done on both knees. The kneeling position takes the legs out so your shoulder and core do the work.\"},{\"id\":\"10988\",\"n\":\"dumbbell kneeling to jump box\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Kneel in front of a box holding dumbbells at your sides.\",\"Swing your arms and drive up to your feet.\",\"Jump onto the box, landing softly.\",\"Stand tall.\",\"Step down carefully and reset to kneeling.\"],\"img\":\"10988.webp\",\"gif\":\"10988.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Starting kneeling, you jump onto a box holding dumbbells. A very explosive move.\"},{\"id\":\"7880\",\"n\":\"dumbbell kneeling triceps kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"core\",\"forearms\"],\"st\":[\"Kneel beside a bench with one hand and the same-side knee on it.\",\"Hold a dumbbell in the free hand with your upper arm against your side.\",\"Extend your elbow to kick the weight back.\",\"Squeeze your triceps.\",\"Lower slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"7880.webp\",\"gif\":\"7880.mp4\",\"cat\":\"strength\",\"desc\":\"A kickback done in a kneeling position, with one hand on a bench for support.\"},{\"id\":\"8505\",\"n\":\"dumbbell kneeling twist down up raise\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Kneel on both knees and hold one dumbbell with both hands beside one hip.\",\"Keep your hips square.\",\"Twist and lift the dumbbell diagonally up across your body.\",\"Reverse the path back down to the hip.\",\"Finish the reps, then switch sides.\"],\"img\":\"8505.webp\",\"gif\":\"8505.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal chopping and lifting pattern from a kneeling position that trains the obliques and shoulders.\"},{\"id\":\"10329\",\"n\":\"dumbbell kroc row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"forearms\",\"grip muscles\",\"rear deltoids\"],\"st\":[\"Stand beside a bench with one hand and knee supported on it and hold a heavy dumbbell.\",\"Let the weight hang with a stretch in the lat.\",\"Row the dumbbell to your hip using controlled momentum.\",\"Lower slowly to a full stretch.\",\"Keep your back flat. Finish the reps, then switch arms.\"],\"img\":\"10329.webp\",\"gif\":\"10329.mp4\",\"cat\":\"strength\",\"desc\":\"A heavy, high rep one-arm row with a little body momentum, great for lat and grip strength.\"},{\"id\":\"6272\",\"n\":\"dumbbell larsen press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Sit on a bench with a dumbbell in each hand and lie back.\",\"Press the dumbbells up and lift your feet off the floor, legs extended.\",\"Lower the weights to the sides of your chest with control.\",\"Press them back up until your arms are straight.\",\"Keep your core braced so your lower back does not arch.\"],\"img\":\"6272.webp\",\"gif\":\"6272.mp4\",\"cat\":\"strength\",\"desc\":\"Dumbbell bench press done with your legs held out in the air, so your chest and triceps do all the work without help from the lower body.\"},{\"id\":\"4853\",\"n\":\"dumbbell lateral lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell at your chest or sides.\",\"Step wide to one side.\",\"Sit your hips back and bend that knee.\",\"Keep your other leg straight.\",\"Push off to return and switch sides.\"],\"img\":\"4853.webp\",\"gif\":\"4853.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways lunge with dumbbells. It trains the glutes and inner thighs.\"},{\"id\":\"1553\",\"n\":\"dumbbell lateral lunge with bicep curl\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"biceps\",\"hamstrings\"],\"st\":[\"Stand tall holding a dumbbell in each hand with your palms facing forward.\",\"Take a big step to the side and sit back into that hip, keeping the other leg straight.\",\"Curl both dumbbells up as you lower into the lunge.\",\"Push off your bent leg to return to the middle while lowering the weights.\",\"Alternate sides or finish all reps on one side before switching.\"],\"img\":\"1553.webp\",\"gif\":\"1553.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge combined with a biceps curl. It works the legs and arms together and also loosens the inner thighs.\"},{\"id\":\"8221\",\"n\":\"dumbbell lateral raise plank\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set up in a plank with your hands on dumbbells.\",\"Brace your core and widen your feet.\",\"Lift one dumbbell out to the side.\",\"Avoid twisting your hips.\",\"Lower and alternate arms.\"],\"img\":\"8221.webp\",\"gif\":\"8221.mp4\",\"cat\":\"strength\",\"desc\":\"In a plank, you raise a dumbbell out to the side. It challenges the core and shoulders together.\"},{\"id\":\"2468\",\"n\":\"dumbbell lateral step up\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Stand beside a bench holding a dumbbell in each hand.\",\"Place your near foot on the bench.\",\"Drive through that heel to step up onto the bench.\",\"Bring your other foot up to balance.\",\"Step down with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"2468.webp\",\"gif\":\"2468.mp4\",\"cat\":\"strength\",\"desc\":\"A side-on step up with dumbbells that builds the legs and glutes.\"},{\"id\":\"3911\",\"n\":\"dumbbell low fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Lie on a flat bench or stand and hold dumbbells with palms facing each other.\",\"Keep a slight bend in your elbows.\",\"Move the dumbbells in a wide arc.\",\"Bring them together in front of your lower chest.\",\"Squeeze your chest.\",\"Lower slowly under control.\"],\"img\":\"3911.webp\",\"gif\":\"3911.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly with a low path that emphasizes the lower chest.\"},{\"id\":\"6328\",\"n\":\"dumbbell low split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Hold a dumbbell in each hand and step into a long split stance.\",\"Keep your chest up and your front foot flat.\",\"Lower your back knee toward the floor in a controlled way.\",\"Push through your front heel to rise.\",\"Complete your reps, then switch legs.\"],\"img\":\"6328.webp\",\"gif\":\"6328.mp4\",\"cat\":\"strength\",\"desc\":\"A deep split squat holding dumbbells at your sides, great for loading the quads and glutes one leg at a time.\"},{\"id\":\"4746\",\"n\":\"dumbbell low windmill\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet wide and a dumbbell in one hand.\",\"Turn your back foot out and push your hips toward the dumbbell side.\",\"Slide the dumbbell down your leg as you bend sideways and hinge.\",\"Keep both legs mostly straight.\",\"Return to standing and finish the set, then switch sides.\"],\"img\":\"4746.webp\",\"gif\":\"4746.mp4\",\"cat\":\"strength\",\"desc\":\"A windmill with a dumbbell held low, bending sideways and down the leg. It trains the obliques and loosens the hips.\"},{\"id\":\"10858\",\"n\":\"dumbbell lu raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand tall holding a light dumbbell in each hand, arms by your sides.\",\"Raise both arms out to the sides until they reach shoulder height, elbows bent to 90 degrees.\",\"Rotate your forearms upward so the dumbbells point to the ceiling.\",\"Pause, then lower back down the same path with control.\",\"Keep your ribs down and avoid shrugging.\"],\"img\":\"10858.webp\",\"gif\":\"10858.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell raise that lifts the arms out and up in an L to U path. It builds shoulder strength and upper back control.\"},{\"id\":\"3341\",\"n\":\"dumbbell lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand tall with a dumbbell in each hand at your sides.\",\"Step forward into a long stride.\",\"Bend both knees until your back knee nearly touches the floor.\",\"Keep your front knee over your ankle and torso upright.\",\"Push back to the start and switch legs.\"],\"img\":\"3341.webp\",\"gif\":\"3341.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell lunge variation for leg strength and balance, working quads and glutes.\"},{\"id\":\"4425\",\"n\":\"dumbbell lying close grip parallel row on rack\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"core\"],\"st\":[\"Lie face down on a high bench or rack with a dumbbell in each hand.\",\"Let your arms hang with palms facing each other.\",\"Row the dumbbells toward your ribs, keeping elbows close.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly to full extension.\"],\"img\":\"4425.webp\",\"gif\":\"4425.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row lying on a rack with a neutral grip, working the lats and mid back.\"},{\"id\":\"4151\",\"n\":\"dumbbell lying floor skullcrusher\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on your back with knees bent, a dumbbell in each hand over your chest.\",\"Keep your upper arms vertical and still.\",\"Bend your elbows to lower the weights toward your head.\",\"Stop when your upper arms touch the floor lightly.\",\"Extend your elbows to press the weights back up.\",\"Keep your elbows pointed forward and avoid flaring them.\"],\"img\":\"4151.webp\",\"gif\":\"4151.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension lying on the floor, bending only at the elbows. The floor limits the range and keeps tension on the triceps.\"},{\"id\":\"10042\",\"n\":\"dumbbell lying floor squeeze press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on the floor with a dumbbell in each hand, pressed together above your chest.\",\"Squeeze the dumbbells against each other.\",\"Lower them until your upper arms touch the floor.\",\"Press back up while still squeezing.\",\"Keep your wrists straight and elbows tucked.\",\"Lower slowly each rep.\"],\"img\":\"10042.webp\",\"gif\":\"10042.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press with the dumbbells pressed together. The squeeze keeps your chest working throughout the lift.\"},{\"id\":\"1177\",\"n\":\"dumbbell lying hammer press v. 2\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Lie on a bench holding dumbbells with palms facing each other.\",\"Start with the weights above your chest.\",\"Lower them to the sides of your chest, elbows slightly tucked.\",\"Press back up until your arms are straight.\",\"Keep your feet planted and shoulder blades pinched.\"],\"img\":\"1177.webp\",\"gif\":\"1177.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with dumbbells held in a neutral grip that is easier on the shoulders.\",\"nd\":[\"bench\"]},{\"id\":\"4292\",\"n\":\"dumbbell lying hamstring curl\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie face down on a bench and grip the edge for support.\",\"Have a dumbbell gripped between your feet, or placed by a partner, with legs straight.\",\"Bend your knees and curl the weight toward your glutes.\",\"Pause briefly at the top without lifting your hips.\",\"Lower slowly until your legs are almost straight.\"],\"img\":\"4292.webp\",\"gif\":\"4292.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you curl a dumbbell held between your feet toward your glutes. A simple way to train the back of the thighs without a machine.\",\"nd\":[\"bench\"]},{\"id\":\"6161\",\"n\":\"dumbbell lying leg curl\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie face down on a bench.\",\"Grip a dumbbell between your feet.\",\"Curl your heels toward your glutes.\",\"Squeeze the hamstrings at the top.\",\"Lower with control.\",\"Keep your hips on the bench.\"],\"img\":\"6161.webp\",\"gif\":\"6161.mp4\",\"cat\":\"strength\",\"desc\":\"A leg curl lying on your front while holding a dumbbell between your feet. It targets the hamstrings.\",\"nd\":[\"bench\"]},{\"id\":\"6799\",\"n\":\"dumbbell lying oblique v up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back holding a dumbbell with both hands overhead.\",\"Lift your legs and torso together, angling toward one side.\",\"Reach the dumbbell toward your feet.\",\"Lower back down slowly.\",\"Alternate sides each rep.\"],\"img\":\"6799.webp\",\"gif\":\"6799.mp4\",\"cat\":\"strength\",\"desc\":\"A lying V-up to the side while holding a dumbbell. It works the abs and obliques hard.\"},{\"id\":\"3668\",\"n\":\"dumbbell lying on floor chest press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on the floor holding dumbbells above your chest.\",\"Lower them until your upper arms touch the floor.\",\"Pause briefly.\",\"Press back up to straight arms.\",\"Keep your wrists straight.\"],\"img\":\"3668.webp\",\"gif\":\"3668.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell press performed lying on the floor, which limits the range of motion and is easy on the shoulders.\",\"fv\":\"7428\"},{\"id\":\"3319\",\"n\":\"dumbbell lying on floor hammer press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on the floor with knees bent and a dumbbell in each hand, palms facing in.\",\"Start with your upper arms resting on the floor.\",\"Press the dumbbells straight up over your chest.\",\"Pause briefly at the top without locking out hard.\",\"Lower slowly until your triceps touch the floor and repeat.\"],\"img\":\"3319.webp\",\"gif\":\"3319.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press with palms facing each other, which is kind to your shoulders. It trains the chest and triceps through a short range.\",\"fv\":\"3425\"},{\"id\":\"1048\",\"n\":\"dumbbell lying one arm rear lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie on your side on a bench holding a light dumbbell in your top hand.\",\"Start with your arm hanging in front of you, slight bend in the elbow.\",\"Raise the arm out and up until it is about shoulder height.\",\"Pause, then lower with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"1048.webp\",\"gif\":\"1048.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your side on a bench, you raise a dumbbell out to the side. It isolates the rear shoulder.\",\"nd\":[\"bench\"]},{\"id\":\"1443\",\"n\":\"dumbbell lying pronated grip maltese hold\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"chest\",\"core\"],\"st\":[\"Lie face up with a dumbbell in each hand, palms down.\",\"Lift your arms out to the sides at about hip level.\",\"Keep your arms straight and your body tight.\",\"Hold the position without letting the weights drop.\",\"Hold for 10-20 seconds, then lower carefully.\"],\"img\":\"1443.webp\",\"gif\":\"1443.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding dumbbells out to the sides in a lying Maltese position. It is an advanced hold for the shoulders and chest.\",\"hd\":1},{\"id\":\"5697\",\"n\":\"dumbbell lying row on rack\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Lie face down on a raised bench with a dumbbell in each hand.\",\"Let your arms hang straight down.\",\"Row the weights up toward your ribs, elbows close to your body.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly to full arm extension.\"],\"img\":\"5697.webp\",\"gif\":\"5697.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row done lying face down on an incline bench or rack. With the body supported, it focuses the work on the upper back.\"},{\"id\":\"11800\",\"n\":\"dumbbell lying single straight arm press on floor\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Lie on your back on the floor with knees bent and one dumbbell held above your chest.\",\"Keep the other arm resting on the floor beside you.\",\"Press the dumbbell up until your arm is straight and the shoulder reaches forward.\",\"Lower it back with control until your upper arm touches the floor.\",\"Complete the reps, then switch arms.\"],\"img\":\"11800.webp\",\"gif\":\"11800.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm press from the floor with a straight arm that trains the chest and shoulder stabilisers.\"},{\"id\":\"9213\",\"n\":\"dumbbell lying straight arm press on floor\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on the floor with a dumbbell in each hand above your chest.\",\"Keep your arms straight and your wrists strong.\",\"Lower your arms slightly and then press back up.\",\"Squeeze your chest at the top.\",\"Keep your feet planted and core tight.\",\"Control the weights through each rep.\"],\"img\":\"9213.webp\",\"gif\":\"9213.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press with the arms kept straight. It trains the chest and shoulders without a big range of motion.\"},{\"id\":\"2738\",\"n\":\"dumbbell lying triceps extension on floor\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on the floor with knees bent, holding a dumbbell in each hand over your chest.\",\"Keep upper arms still and bend your elbows to lower the weights toward your head.\",\"Stop just before the weights touch the floor.\",\"Press back up by straightening your arms.\",\"Keep your elbows pointing up.\"],\"img\":\"2738.webp\",\"gif\":\"2738.mp4\",\"cat\":\"strength\",\"desc\":\"A floor version of the lying triceps extension, where the floor limits how far you lower the weight.\"},{\"id\":\"2589\",\"n\":\"dumbbell lying triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench holding a dumbbell in each hand above your chest, palms facing in.\",\"Keep your upper arms still and bend your elbows to lower the weights beside your head.\",\"Stop when you feel a stretch in the triceps.\",\"Straighten your arms back to the start.\",\"Keep your elbows pointing at the ceiling.\"],\"img\":\"2589.webp\",\"gif\":\"2589.mp4\",\"cat\":\"strength\",\"desc\":\"A classic lying extension that isolates the triceps by bending only at the elbows.\",\"nd\":[\"bench\"]},{\"id\":\"4426\",\"n\":\"dumbbell lying wide grip row on rack\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"lats\",\"biceps\"],\"st\":[\"Lie face down on a high bench with a dumbbell in each hand.\",\"Let your arms hang straight down.\",\"Row the dumbbells up with elbows flaring out to the sides.\",\"Squeeze your shoulder blades together.\",\"Lower under control.\"],\"img\":\"4426.webp\",\"gif\":\"4426.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row with a wide elbow path that emphasises the upper back and rear delts.\"},{\"id\":\"4747\",\"n\":\"dumbbell lying woodchop\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent, holding a dumbbell with both hands beside one hip.\",\"Keep your arms mostly straight.\",\"Sweep the dumbbell diagonally up and across to above the opposite shoulder.\",\"Rotate your torso with the movement.\",\"Return under control and switch sides after the set.\"],\"img\":\"4747.webp\",\"gif\":\"4747.mp4\",\"cat\":\"strength\",\"desc\":\"A woodchop done lying on your back, moving a dumbbell diagonally across your body. It works the obliques.\"},{\"id\":\"6800\",\"n\":\"dumbbell military press russian twist with legs floor off\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"triceps\",\"hip flexors\"],\"st\":[\"Sit leaning back slightly with knees bent and feet off the floor.\",\"Hold dumbbells at your shoulders.\",\"Press both dumbbells overhead.\",\"Lower them, then twist your torso to one side.\",\"Twist to the other side and repeat the sequence.\"],\"img\":\"6800.webp\",\"gif\":\"6800.mp4\",\"cat\":\"strength\",\"desc\":\"A seated combo that pairs an overhead press with a Russian twist, feet off the floor. It challenges the trunk and shoulders together.\"},{\"id\":\"6806\",\"n\":\"dumbbell military press russian twist with legs floor off v. 2\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"triceps\",\"hip flexors\"],\"st\":[\"Sit leaning back slightly with knees bent and feet off the floor.\",\"Hold dumbbells at your shoulders.\",\"Press both dumbbells overhead and lower them.\",\"Twist your torso to one side, then the other.\",\"Keep your chest tall and breathe steadily.\"],\"img\":\"6806.webp\",\"gif\":\"6806.mp4\",\"cat\":\"strength\",\"desc\":\"A variation of the seated overhead press and Russian twist combo with feet off the floor. It works the trunk and shoulders.\"},{\"id\":\"10055\",\"n\":\"dumbbell narrow squat lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand with feet close together, a dumbbell in each hand at your sides.\",\"Step one foot back and lower into a lunge, keeping your feet in a narrow line.\",\"Drop your back knee toward the floor.\",\"Keep your front knee over your ankle and chest up.\",\"Push through the front heel to stand back up.\",\"Switch legs and repeat.\"],\"img\":\"10055.webp\",\"gif\":\"10055.mp4\",\"cat\":\"strength\",\"desc\":\"A narrow-stance lunge holding a dumbbell in each hand to add load for the quads and glutes.\"},{\"id\":\"5634\",\"n\":\"dumbbell narrow stance squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold dumbbells at your sides with feet close together.\",\"Brace your core.\",\"Squat down with your chest up.\",\"Drive up to stand.\",\"Keep your heels down.\"],\"img\":\"5634.webp\",\"gif\":\"5634.mp4\",\"cat\":\"strength\",\"desc\":\"Narrow stance squat holding dumbbells to build the quads.\"},{\"id\":\"2393\",\"n\":\"dumbbell one arm bent over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Hinge forward with a flat back, one hand on a bench or knee for support.\",\"Hold a dumbbell in the other hand with your arm hanging straight.\",\"Pull the dumbbell toward your hip, keeping your elbow close.\",\"Squeeze your shoulder blade toward your spine.\",\"Lower slowly until your arm is straight.\",\"Finish your reps, then switch arms.\"],\"img\":\"2393.webp\",\"gif\":\"2393.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row in a bent-over position that works the back and arm.\"},{\"id\":\"3334\",\"n\":\"dumbbell one arm floor fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Lie on the floor with knees bent and a dumbbell in one hand over your chest.\",\"Keep a slight bend in your elbow.\",\"Open your arm out to the side until your upper arm touches the floor.\",\"Squeeze your chest to bring the dumbbell back above you.\",\"Finish all reps, then switch arms.\"],\"img\":\"3334.webp\",\"gif\":\"3334.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm fly lying on the floor, a safe way to stretch and load the chest with a limited range.\"},{\"id\":\"3913\",\"n\":\"dumbbell one arm front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand with a dumbbell in one hand in front of your thigh.\",\"Keep your core braced.\",\"Raise your arm forward to shoulder height.\",\"Pause at the top.\",\"Lower slowly.\",\"Switch arms after your reps.\"],\"img\":\"3913.webp\",\"gif\":\"3913.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm raise in front of you that trains the front delts.\",\"fv\":\"7430\"},{\"id\":\"2690\",\"n\":\"dumbbell one arm lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand holding a dumbbell in one hand at your side.\",\"Keep a soft bend in the elbow.\",\"Raise the arm out to the side until it reaches shoulder height.\",\"Lower slowly without swinging.\",\"Do all reps, then switch sides.\"],\"img\":\"2690.webp\",\"gif\":\"2690.mp4\",\"cat\":\"strength\",\"desc\":\"A one-sided raise out to the side that builds the middle part of the shoulder.\",\"mv\":\"0356\"},{\"id\":\"4150\",\"n\":\"dumbbell one arm low fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Stand with feet staggered and hold a dumbbell at your side with a slight elbow bend.\",\"Brace your core and keep your chest up.\",\"Sweep the dumbbell out and up in an arc to chest height in front of you.\",\"Squeeze your chest at the top.\",\"Lower slowly along the same arc.\",\"Finish your reps, then switch arms.\"],\"img\":\"4150.webp\",\"gif\":\"4150.mp4\",\"cat\":\"strength\",\"desc\":\"A single arm fly that sweeps the dumbbell from low up to the chest. It works the upper pecs and front shoulder.\"},{\"id\":\"3339\",\"n\":\"dumbbell one arm lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"obliques\"],\"st\":[\"Stand tall holding a dumbbell in one hand at your side.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor, keeping your torso upright.\",\"Push through your front foot to return to standing.\",\"Alternate legs and switch the dumbbell hand halfway.\"],\"img\":\"3339.webp\",\"gif\":\"3339.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge holding a dumbbell in one hand. The uneven load makes your core work to keep you balanced.\"},{\"id\":\"0357\",\"n\":\"dumbbell one arm press (on stability ball)\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Sit on a stability ball with a dumbbell and walk your feet out until your upper back rests on the ball.\",\"Lift your hips so your body is flat like a bench, feet wide for balance.\",\"Hold the dumbbell at chest height and press it up over your shoulder.\",\"Lower it slowly back to chest level.\",\"Finish your reps, then switch arms.\",\"Keep your hips up and don't let your body twist.\"],\"img\":\"0357.webp\",\"gif\":\"0357.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm dumbbell press with your upper back on a stability ball. Staying balanced makes your core work as hard as the chest.\"},{\"id\":\"4239\",\"n\":\"dumbbell one arm reverse fly (with support) v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Hinge forward and brace your free hand on a bench or support.\",\"Hold a light dumbbell hanging straight down.\",\"Raise the dumbbell out to the side with a slight elbow bend.\",\"Lift until your arm is about parallel to the floor.\",\"Pause and lower slowly.\",\"Finish your reps and switch arms.\"],\"img\":\"4239.webp\",\"gif\":\"4239.mp4\",\"cat\":\"strength\",\"desc\":\"A supported one-arm reverse fly that isolates the rear delts. Bracing with your other hand helps you keep a steady torso.\"},{\"id\":\"1236\",\"n\":\"dumbbell one arm row (rack support)\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rear deltoids\"],\"st\":[\"Place one hand on a rack or sturdy support and hinge forward with a flat back.\",\"Hold a dumbbell in your other hand with your arm hanging.\",\"Row the dumbbell toward your hip.\",\"Squeeze your back at the top, then lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"1236.webp\",\"gif\":\"1236.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row with your free hand braced on a rack for support. It lets you pull heavy while keeping your back steady.\"},{\"id\":\"2381\",\"n\":\"dumbbell one arm shoulder press v. 3\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Hold a dumbbell at shoulder height with your palm facing forward.\",\"Stand or sit tall and brace your core.\",\"Press the dumbbell overhead until your arm is straight.\",\"Avoid leaning to the side.\",\"Lower the dumbbell slowly back to your shoulder.\",\"Finish your reps, then switch arms.\"],\"img\":\"2381.webp\",\"gif\":\"2381.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press that builds the shoulders and challenges your core.\"},{\"id\":\"5816\",\"n\":\"dumbbell one arm side lying bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on your side on a flat bench with a dumbbell in the top hand.\",\"Bring the weight to your chest.\",\"Press the dumbbell up until your arm is straight.\",\"Lower it slowly to the chest.\",\"Complete your reps, then switch sides.\"],\"img\":\"5816.webp\",\"gif\":\"5816.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm press done lying on your side on a bench. It targets the chest while the core resists rolling.\"},{\"id\":\"6152\",\"n\":\"dumbbell one arm snatch (left)\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"core\",\"quadriceps\"],\"st\":[\"Stand over a dumbbell with your feet shoulder-width apart.\",\"Grip it with your left hand and hinge at the hips.\",\"Drive up with your legs and hips.\",\"Pull the dumbbell up close to your body and punch it overhead.\",\"Lock out the arm.\",\"Lower the weight back to the floor with control.\"],\"img\":\"6152.webp\",\"gif\":\"6152.mp4\",\"cat\":\"olympic\",\"desc\":\"A single-arm snatch that takes a dumbbell from the floor to overhead in one motion. This version uses the left arm.\"},{\"id\":\"4540\",\"n\":\"dumbbell one arm thruster\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a dumbbell at your shoulder with one hand and stand with feet shoulder-width apart.\",\"Squat down with your chest tall and knees tracking over your toes.\",\"Drive up through your heels.\",\"Use that momentum to press the dumbbell overhead until your arm is straight.\",\"Lower it back to your shoulder as you sink into the next squat.\",\"Finish your reps, then switch arms.\"],\"img\":\"4540.webp\",\"gif\":\"4540.mp4\",\"cat\":\"strength\",\"desc\":\"A squat into an overhead press with a single dumbbell, training the legs and shoulders together.\"},{\"id\":\"4343\",\"n\":\"dumbbell one arm triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold a dumbbell in one hand and press it overhead.\",\"Keep your upper arm close to your head with the elbow pointing up.\",\"Bend the elbow and lower the dumbbell behind your head.\",\"Extend the elbow to press the weight back up.\",\"Finish your reps, then switch arms.\"],\"img\":\"4343.webp\",\"gif\":\"4343.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm overhead extension with a dumbbell. It isolates the triceps and builds arm strength.\"},{\"id\":\"4054\",\"n\":\"dumbbell one arm triceps extension on stability ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit tall on a stability ball and hold a dumbbell overhead in one hand.\",\"Keep your upper arm close to your head.\",\"Bend your elbow and lower the dumbbell behind your head.\",\"Extend your arm back up.\",\"Finish the reps, then switch arms.\"],\"img\":\"4054.webp\",\"gif\":\"4054.mp4\",\"cat\":\"strength\",\"desc\":\"Overhead triceps extension with one dumbbell while seated on a stability ball. The ball adds a core challenge.\"},{\"id\":\"3333\",\"n\":\"dumbbell one arm wide grip bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Lie on a bench with one dumbbell held over your chest.\",\"Place your free arm on your stomach or out to the side.\",\"Lower the dumbbell with elbow flared out until you feel a chest stretch.\",\"Press it back up over your chest.\",\"Keep your torso square, then switch arms after the set.\"],\"img\":\"3333.webp\",\"gif\":\"3333.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm dumbbell bench press with a wide elbow path, stressing the chest while your core resists rotation.\"},{\"id\":\"5002\",\"n\":\"dumbbell one arm y elevation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Hold a light dumbbell in one hand and hinge slightly or lie chest down on an incline bench.\",\"Start with your arm hanging down.\",\"Raise your arm diagonally overhead to form a Y with your thumb up.\",\"Pause at the top.\",\"Lower slowly, finish your reps, and switch sides.\"],\"img\":\"5002.webp\",\"gif\":\"5002.mp4\",\"cat\":\"strength\",\"desc\":\"A light dumbbell raise along a Y-shaped path. It trains the shoulders and the muscles of the upper back.\"},{\"id\":\"0882\",\"n\":\"dumbbell one leg squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell at your chest or by your side.\",\"Stand on one leg with the other lifted in front.\",\"Sit your hips back and lower under control.\",\"Keep your knee in line with your toes.\",\"Press up to stand, then switch legs.\"],\"img\":\"0882.webp\",\"gif\":\"0882.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat holding a dumbbell. It builds leg strength and balance.\"},{\"id\":\"4908\",\"n\":\"dumbbell over bench reverse wrist curl with mat\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Kneel by a bench with forearms on it, palms down, wrists over the edge.\",\"Hold a dumbbell in each hand.\",\"Let your wrists lower gently.\",\"Curl the weights up by extending your wrists.\",\"Pause at the top, then lower slowly.\",\"Keep your forearms still on the bench.\"],\"img\":\"4908.webp\",\"gif\":\"4908.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse wrist curl with your forearms resting on a padded bench. It builds the muscles on top of the forearm.\"},{\"id\":\"6758\",\"n\":\"dumbbell over the bench supination\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"biceps\"],\"st\":[\"Sit by a bench and rest your forearm on it with your hand past the edge.\",\"Hold a dumbbell with a hammer grip.\",\"Keep your forearm still.\",\"Rotate your palm up as far as you can.\",\"Return slowly to the start.\",\"Finish the reps, then switch arms.\"],\"img\":\"6758.webp\",\"gif\":\"6758.mp4\",\"cat\":\"strength\",\"desc\":\"A forearm rotation holding a dumbbell with the arm over the end of a bench. It trains the muscles that turn the palm up.\"},{\"id\":\"11077\",\"n\":\"dumbbell over the chest lying abduction\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Lie on your side with legs stacked and hold a dumbbell over your chest with both hands.\",\"Keep your hips stacked and core braced.\",\"Raise your top leg without rotating your torso.\",\"Pause at the top.\",\"Lower with control, finish your reps, then switch sides.\"],\"img\":\"11077.webp\",\"gif\":\"11077.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying hip abduction while you hold a dumbbell over your chest. It trains the outer hips and adds a core challenge.\"},{\"id\":\"2913\",\"n\":\"dumbbell overhead carry\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper back\",\"trapezius\",\"obliques\"],\"st\":[\"Press a dumbbell overhead and lock out your elbow with the biceps near your ear.\",\"Brace your abs and keep your ribs down.\",\"Walk with steady steps without letting the arm drift forward.\",\"Cover the set distance, then lower the weight with control.\",\"Switch arms and repeat.\"],\"img\":\"2913.webp\",\"gif\":\"2913.mp4\",\"cat\":\"strength\",\"desc\":\"Walking with a dumbbell held overhead. It builds shoulder stability and a strong, braced trunk.\"},{\"id\":\"5076\",\"n\":\"dumbbell overhead lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\"],\"st\":[\"Press two dumbbells overhead with straight arms.\",\"Step forward into a lunge, lowering your back knee toward the floor.\",\"Keep your core tight and the dumbbells over your shoulders.\",\"Push off the front foot to come back.\",\"Alternate legs each rep.\"],\"img\":\"5076.webp\",\"gif\":\"5076.mp4\",\"cat\":\"strength\",\"desc\":\"Hold two dumbbells overhead and lunge. The load above you trains balance, core and shoulder stability along with leg strength.\"},{\"id\":\"1694\",\"n\":\"dumbbell overhead side lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"shoulders\",\"core\"],\"st\":[\"Hold one dumbbell overhead with both hands or one hand and stand tall.\",\"Step out wide to one side and sit back into the hips.\",\"Keep your chest tall and your arm locked out overhead.\",\"Push through the bent leg to return to the middle.\",\"Alternate sides for the planned reps.\"],\"img\":\"1694.webp\",\"gif\":\"1694.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge with a dumbbell held overhead that trains the legs and core stability.\"},{\"id\":\"4748\",\"n\":\"dumbbell overhead sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent and feet flat or anchored.\",\"Hold a dumbbell with both hands, arms extended overhead.\",\"Curl up to a seated position, keeping the dumbbell above you.\",\"Keep your arms by your ears.\",\"Lower back down slowly.\"],\"img\":\"4748.webp\",\"gif\":\"4748.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up holding a dumbbell above your head, which lengthens the lever and makes your abs work harder.\"},{\"id\":\"6809\",\"n\":\"dumbbell overhead sit up with legs on bench\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Lie on the floor with calves resting on a bench, knees bent.\",\"Hold a dumbbell with both hands above your chest or overhead.\",\"Curl up into a sit-up, keeping your arms extended.\",\"Reach toward your knees at the top.\",\"Lower back down slowly.\"],\"img\":\"6809.webp\",\"gif\":\"6809.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up holding a dumbbell overhead with the legs resting on a bench. The extra reach makes the abs work harder.\"},{\"id\":\"3709\",\"n\":\"dumbbell overhead squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"upper back\"],\"st\":[\"Press two dumbbells overhead with your arms straight.\",\"Stand with your feet shoulder width apart.\",\"Sit down into a squat while keeping the weights above your head.\",\"Keep your chest up and ribs down.\",\"Stand back up, driving through your heels.\"],\"img\":\"3709.webp\",\"gif\":\"3709.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with dumbbells held locked out overhead. It builds leg strength and demands strong shoulders and core.\"},{\"id\":\"4865\",\"n\":\"dumbbell overhead walking lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Hold dumbbells overhead with locked arms.\",\"Step forward into a lunge.\",\"Lower your back knee near the floor.\",\"Push through your front foot.\",\"Step through into the next lunge.\"],\"img\":\"4865.webp\",\"gif\":\"4865.mp4\",\"cat\":\"strength\",\"desc\":\"Walking lunges with dumbbells held overhead. It trains the legs and shoulder stability.\"},{\"id\":\"4191\",\"n\":\"dumbbell partials lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand holding dumbbells at your sides.\",\"Raise them out to the sides.\",\"Stay within the mid range, between hip and shoulder height.\",\"Pause briefly.\",\"Lower slowly.\",\"Avoid shrugging.\"],\"img\":\"4191.webp\",\"gif\":\"4191.mp4\",\"cat\":\"strength\",\"desc\":\"Short range lateral raises that keep tension on the side delts.\"},{\"id\":\"5497\",\"n\":\"dumbbell plank pass through\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Start in a high plank with a dumbbell beside one hand and feet wide.\",\"Brace your core and keep hips level.\",\"Reach the free hand under your body and grab the dumbbell.\",\"Pass it across to the other side and place it down.\",\"Repeat, alternating sides.\"],\"img\":\"5497.webp\",\"gif\":\"5497.mp4\",\"cat\":\"strength\",\"desc\":\"Plank variation where you pass a dumbbell under your body from hand to hand, challenging core stability.\"},{\"id\":\"3879\",\"n\":\"dumbbell poliquin lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Hold a dumbbell in each hand, standing with a slight forward lean.\",\"Start with the dumbbells in front of your thighs, palms facing in.\",\"Raise your arms out and up in a slight arc until about shoulder height.\",\"Lead with your elbows and keep your wrists neutral.\",\"Pause briefly, then lower slowly.\",\"Avoid swinging your torso.\"],\"img\":\"3879.webp\",\"gif\":\"3879.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise variation with a slight forward lean that hits the side delts with extra range.\"},{\"id\":\"10330\",\"n\":\"dumbbell powell raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Lie on your side on a bench holding a light dumbbell in your top hand.\",\"Start with the arm hanging in front of your body.\",\"Raise the arm out and back in an arc until it is in line with your torso.\",\"Pause briefly, then lower with control.\",\"Use a light weight and switch sides after your set.\"],\"img\":\"10330.webp\",\"gif\":\"10330.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying raise that targets the rear shoulder with a long range of motion.\",\"nd\":[\"bench\"]},{\"id\":\"4889\",\"n\":\"dumbbell power clean\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Stand over the dumbbells with feet hip width and grab them with a flat back.\",\"Push through the floor and extend your hips and knees fast.\",\"Shrug and pull the dumbbells up close to your body.\",\"Drop under them and catch them on your shoulders in a quarter squat.\",\"Stand tall, then lower with control to the floor.\",\"Keep your back flat and the weights close throughout.\"],\"img\":\"4889.webp\",\"gif\":\"4889.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive pull that takes a pair of dumbbells from the floor to your shoulders. It builds power through the hips.\"},{\"id\":\"4439\",\"n\":\"dumbbell power clean and jerk\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"shoulders\",\"triceps\",\"upper back\"],\"st\":[\"Stand over dumbbells with feet hip-width apart.\",\"Hinge down and grip them with a flat back.\",\"Pull explosively, extend your hips and shrug.\",\"Catch the dumbbells at your shoulders, then dip and drive them overhead.\",\"Lower to your shoulders, then the floor with control.\"],\"img\":\"4439.webp\",\"gif\":\"4439.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive lift pulling dumbbells from the floor to the shoulders and then overhead.\"},{\"id\":\"5298\",\"n\":\"dumbbell preacher curl (turned torso)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Sit at a preacher bench with a dumbbell in one hand.\",\"Rotate your torso slightly toward the working arm.\",\"Curl the dumbbell up to shoulder height.\",\"Squeeze your biceps.\",\"Lower slowly, finish your reps, then switch arms.\"],\"img\":\"5298.webp\",\"gif\":\"5298.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with your torso turned slightly. The changed angle puts extra tension on the biceps.\"},{\"id\":\"8613\",\"n\":\"dumbbell preacher swing curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Rest your upper arms on a preacher pad and hold dumbbells with an underhand grip.\",\"Keep your shoulders down.\",\"Curl the weights up with a small drive from the bottom.\",\"Squeeze at the top.\",\"Lower slowly until your arms are almost straight.\"],\"img\":\"8613.webp\",\"gif\":\"8613.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher curl with a little controlled swing to push past the sticking point.\"},{\"id\":\"3707\",\"n\":\"dumbbell press squat (thighs)\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a dumbbell in each hand at shoulder height.\",\"Squat down until your thighs are about parallel to the floor.\",\"Drive up through your heels as you stand.\",\"Use that momentum to press the dumbbells overhead.\",\"Lower them to your shoulders and go into the next squat.\"],\"img\":\"3707.webp\",\"gif\":\"3707.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with an overhead press. The legs drive the movement while the shoulders finish the press.\"},{\"id\":\"2326\",\"n\":\"dumbbell pronated grip row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Hold a dumbbell in each hand and hinge forward with a flat back.\",\"Let your arms hang with palms facing your legs.\",\"Pull the dumbbells up toward your lower ribs.\",\"Keep your elbows close to your body and squeeze your shoulder blades.\",\"Lower slowly until your arms are straight.\",\"Avoid jerking with your torso.\"],\"img\":\"2326.webp\",\"gif\":\"2326.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with an overhand grip, building the muscles of the mid and upper back.\"},{\"id\":\"2325\",\"n\":\"dumbbell pronated to neutral grip row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Hinge forward with a flat back, holding dumbbells with an overhand grip.\",\"Let your arms hang straight below your shoulders.\",\"Row the weights toward your hips while rotating your palms to face each other.\",\"Squeeze your shoulder blades together at the top.\",\"Lower the dumbbells slowly while turning your palms back down.\",\"Keep your torso still.\"],\"img\":\"2325.webp\",\"gif\":\"2325.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell row that begins with an overhand grip and turns to a neutral grip, working the back and arms.\"},{\"id\":\"6264\",\"n\":\"dumbbell prone alternate hammer curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\"],\"st\":[\"Lie chest down on an incline bench.\",\"Hold dumbbells with palms facing in.\",\"Curl one dumbbell up.\",\"Lower it slowly.\",\"Alternate arms.\",\"Keep your elbows still.\"],\"img\":\"6264.webp\",\"gif\":\"6264.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl lying face down on an incline bench, alternating arms. It builds the forearms and brachialis.\"},{\"id\":\"5820\",\"n\":\"dumbbell prone full can exercise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"upper back\",\"trapezius\"],\"st\":[\"Lie face down on a bench or floor with light dumbbells hanging.\",\"Turn your thumbs to the ceiling.\",\"Raise your arms out diagonally into a Y.\",\"Squeeze your shoulder blades together.\",\"Lower slowly under control.\"],\"img\":\"5820.webp\",\"gif\":\"5820.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, raise light dumbbells out in a Y with thumbs up. It strengthens the rear shoulder and upper back.\"},{\"id\":\"5606\",\"n\":\"dumbbell prone rear delt swing\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Lie face down on an incline bench with dumbbells hanging.\",\"Keep a soft bend in your elbows.\",\"Swing the weights out and up to shoulder height.\",\"Lower slowly.\",\"Keep your torso still.\"],\"img\":\"5606.webp\",\"gif\":\"5606.mp4\",\"cat\":\"strength\",\"desc\":\"Prone swing with dumbbells to target the rear delts.\"},{\"id\":\"4961\",\"n\":\"dumbbell prone triceps kickback\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\"],\"st\":[\"Lie face down on an incline bench holding dumbbells.\",\"Bend your elbows to 90 degrees and keep your upper arms close.\",\"Extend your elbows until your arms are straight.\",\"Squeeze the triceps.\",\"Lower slowly.\",\"Keep your upper arms still.\"],\"img\":\"4961.webp\",\"gif\":\"4961.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps kickback performed lying face down on an incline bench. It isolates the triceps.\"},{\"id\":\"7747\",\"n\":\"dumbbell prone w raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"rotator cuff\"],\"st\":[\"Lie face down on a bench or the floor with a light dumbbell in each hand.\",\"Bend your elbows to about 90 degrees.\",\"Lift your arms out and up into a W shape.\",\"Squeeze your shoulder blades together.\",\"Lower slowly and repeat.\"],\"img\":\"7747.webp\",\"gif\":\"7747.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you raise light dumbbells while bending the elbows into a W shape. It works the rear delts and the upper back.\"},{\"id\":\"4318\",\"n\":\"dumbbell pullover on floor\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on your back with knees bent and hold one dumbbell with both hands above your chest.\",\"Keep a slight bend in your elbows.\",\"Lower the weight in an arc behind your head until your upper arms touch the floor.\",\"Pull it back over your chest using your lats.\",\"Keep your ribs down and core tight throughout.\"],\"img\":\"4318.webp\",\"gif\":\"4318.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover lying on the floor, which limits the stretch range and keeps the focus on the lats and chest.\"},{\"id\":\"10186\",\"n\":\"dumbbell pullover to press bridge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"lats\",\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent and hold a dumbbell over your chest.\",\"Drive through your heels to lift your hips into a bridge.\",\"Lower the dumbbell back overhead in a pullover arc.\",\"Pull it back over your chest and press it straight up.\",\"Lower your hips with control and repeat, keeping your ribs down.\"],\"img\":\"10186.webp\",\"gif\":\"10186.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge combined with a pullover and press, training the hips, chest and triceps in one flow.\"},{\"id\":\"5330\",\"n\":\"dumbbell pullover v. 2\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"core\"],\"st\":[\"Lie across or along a bench holding one dumbbell with both hands over your chest.\",\"Keep a slight bend in your elbows.\",\"Lower the dumbbell back behind your head in an arc.\",\"Feel the stretch through your chest and lats.\",\"Pull it back over your chest.\",\"Keep your hips low and ribs down.\"],\"img\":\"5330.webp\",\"gif\":\"5330.mp4\",\"cat\":\"strength\",\"desc\":\"Arc a dumbbell from overhead to your chest while lying on a bench. Works the chest and lats with a deep stretch.\",\"nd\":[\"bench\"],\"fv\":\"6484\"},{\"id\":\"4389\",\"n\":\"dumbbell push jerk\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"quadriceps\",\"glutes\",\"core\",\"upper chest\"],\"st\":[\"Hold dumbbells at shoulder height, feet hip-width apart.\",\"Dip by bending your knees slightly while keeping your torso upright.\",\"Drive up through your legs explosively.\",\"Press the dumbbells overhead as you straighten, then lock out your arms.\",\"Lower them back to your shoulders with control.\"],\"img\":\"4389.webp\",\"gif\":\"4389.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive overhead lift that uses a leg drive to send dumbbells overhead. It builds power and shoulder strength.\"},{\"id\":\"3993\",\"n\":\"dumbbell push up front raise\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a high plank gripping two dumbbells.\",\"Do a push up.\",\"Lift one dumbbell forward to shoulder height.\",\"Return it to the floor.\",\"Alternate arms.\"],\"img\":\"3993.webp\",\"gif\":\"3993.mp4\",\"cat\":\"strength\",\"desc\":\"A push up on dumbbells followed by a front raise. It trains the chest, arms and core.\"},{\"id\":\"4749\",\"n\":\"dumbbell rdl and bent over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"upper back\",\"lower back\",\"biceps\"],\"st\":[\"Stand holding dumbbells in front of your thighs, knees soft.\",\"Hinge at the hips, pushing them back, until the dumbbells are below your knees.\",\"Keep your back flat and row both dumbbells to your ribs.\",\"Lower them, then drive your hips forward to stand.\",\"Repeat the full sequence for each rep.\"],\"img\":\"4749.webp\",\"gif\":\"4749.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift combined with a bent-over row. It trains the hamstrings, glutes and back in one rep.\"},{\"id\":\"3651\",\"n\":\"dumbbell rdl death march\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Hold dumbbells at your sides and stand tall.\",\"Hinge at the hips on one leg as you step forward.\",\"Keep your back flat and raise the rear leg.\",\"Stand tall and step into the next rep.\",\"Alternate legs as you move forward.\"],\"img\":\"3651.webp\",\"gif\":\"3651.mp4\",\"cat\":\"strength\",\"desc\":\"Walk forward doing Romanian deadlifts with dumbbells, a balance and hamstring challenge.\"},{\"id\":\"1445\",\"n\":\"dumbbell rdl stretch\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand holding dumbbells in front of your thighs.\",\"Push your hips back and lower the dumbbells along your legs.\",\"Stop when you feel a deep stretch in your hamstrings.\",\"Hold the position with a flat back.\",\"Hold for 15-30 seconds, then stand up.\"],\"img\":\"1445.webp\",\"gif\":\"1445.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding the bottom of a Romanian deadlift with dumbbells. It loads the hamstrings in their stretched position.\"},{\"id\":\"4822\",\"n\":\"dumbbell rdl to jump shrug\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"calves\",\"quadriceps\",\"core\"],\"st\":[\"Stand holding dumbbells in front of your thighs.\",\"Hinge your hips back and lower the weights along your legs with a flat back.\",\"Drive your hips forward and jump as you shrug your shoulders.\",\"Land softly with bent knees.\",\"Reset into the hinge and repeat.\"],\"img\":\"4822.webp\",\"gif\":\"4822.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A Romanian deadlift that finishes with an explosive jump and shrug. It trains power through the hips and traps.\"},{\"id\":\"2487\",\"n\":\"dumbbell rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\"],\"st\":[\"Hinge forward with a flat back, holding dumbbells below your chest.\",\"Keep a slight bend in your elbows.\",\"Raise the dumbbells out to the sides.\",\"Squeeze your shoulder blades together.\",\"Lower slowly to the start.\",\"Keep your neck neutral.\"],\"img\":\"2487.webp\",\"gif\":\"2487.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over fly that targets the rear of the shoulders.\"},{\"id\":\"5303\",\"n\":\"dumbbell rear delt fly (45 degrees)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"upper back\"],\"st\":[\"Set a bench to 45 degrees and lie chest down on it, a dumbbell in each hand.\",\"Let your arms hang below you with a soft bend in the elbows.\",\"Raise the weights out to the sides until your arms are level with your torso.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly under control.\",\"Keep your neck neutral and avoid swinging.\"],\"img\":\"5303.webp\",\"gif\":\"5303.mp4\",\"cat\":\"strength\",\"desc\":\"Raise dumbbells out to the sides on an incline of about 45 degrees to hit the rear delts and upper back.\"},{\"id\":\"2367\",\"n\":\"dumbbell rear lunge from step\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand on a low step with a dumbbell in each hand.\",\"Step one foot back and off the step.\",\"Lower your back knee toward the floor while keeping your torso upright.\",\"Keep your front knee over your ankle.\",\"Push through your front heel to return to standing.\",\"Finish your reps, then switch legs.\"],\"img\":\"2367.webp\",\"gif\":\"2367.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge from a raised step that works the legs and glutes with a deeper range.\"},{\"id\":\"4161\",\"n\":\"dumbbell rear lunge front raise\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"shoulders\",\"hamstrings\"],\"st\":[\"Stand tall holding a dumbbell in each hand at your thighs.\",\"Step one foot back into a lunge.\",\"As you lower, raise the dumbbells in front to shoulder height.\",\"Push through your front foot to stand back up.\",\"Lower the dumbbells as you return.\",\"Alternate legs for each rep.\"],\"img\":\"4161.webp\",\"gif\":\"4161.mp4\",\"cat\":\"strength\",\"desc\":\"Step back into a lunge and raise the dumbbells in front. It trains the legs and shoulders together.\"},{\"id\":\"10096\",\"n\":\"dumbbell rear lunge to single arm shoulders press\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell at one shoulder and stand tall.\",\"Step one leg back into a lunge.\",\"Push through the front foot to stand up.\",\"As you rise, press the dumbbell overhead.\",\"Lower it to your shoulder and repeat.\",\"Switch arms or legs each set.\"],\"img\":\"10096.webp\",\"gif\":\"10096.mp4\",\"cat\":\"strength\",\"desc\":\"A combo move: a rear lunge followed by a single-arm press as you stand. It works legs and shoulders together.\"},{\"id\":\"2980\",\"n\":\"dumbbell renegade row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"core\",\"obliques\"],\"st\":[\"Start in a high plank with a dumbbell in each hand and your feet wide.\",\"Brace your core.\",\"Row one dumbbell to your ribs without twisting your hips.\",\"Lower it with control.\",\"Repeat on the other side.\"],\"img\":\"2980.webp\",\"gif\":\"2980.mp4\",\"cat\":\"strength\",\"desc\":\"A row from a plank position with dumbbells. It builds the back while your core fights rotation.\",\"fv\":\"2981\"},{\"id\":\"8223\",\"n\":\"dumbbell renegade row on stability ball\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"upper back\",\"core\",\"shoulders\"],\"st\":[\"Place your feet on a stability ball and your hands on dumbbells.\",\"Brace into a strong plank.\",\"Row one dumbbell up to your ribs.\",\"Keep your hips level.\",\"Lower and alternate arms.\"],\"img\":\"8223.webp\",\"gif\":\"8223.mp4\",\"cat\":\"strength\",\"desc\":\"A renegade row with your feet on a stability ball. The unstable base makes the core work harder.\"},{\"id\":\"4629\",\"n\":\"dumbbell renegade row to squat\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"quadriceps\",\"glutes\",\"biceps\"],\"st\":[\"Start in a high plank with your hands on dumbbells.\",\"Row one dumbbell to your hip, keeping hips level.\",\"Lower it, then hop or step your feet toward your hands.\",\"Stand up with the dumbbells and squat down.\",\"Return to plank and alternate the rowing arm.\"],\"img\":\"4629.webp\",\"gif\":\"4629.mp4\",\"cat\":\"strength\",\"desc\":\"A demanding combo of a plank row and a squat that builds back strength, core stability and leg power.\"},{\"id\":\"8225\",\"n\":\"dumbbell renegade row walk\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"core\",\"shoulders\",\"chest\"],\"st\":[\"Start in a plank with a dumbbell in each hand.\",\"Row one dumbbell up.\",\"Place it down and step the hands forward.\",\"Repeat with the other arm.\",\"Keep your hips level.\"],\"img\":\"8225.webp\",\"gif\":\"8225.mp4\",\"cat\":\"strength\",\"desc\":\"A renegade row combined with walking forward in plank. It is a demanding move for core and shoulder stability.\"},{\"id\":\"2511\",\"n\":\"dumbbell reverse grip incline row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Lie chest down on an incline bench holding dumbbells with an underhand grip.\",\"Let your arms hang straight.\",\"Row the dumbbells toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower slowly until your arms are straight.\",\"Keep your chest on the pad.\"],\"img\":\"2511.webp\",\"gif\":\"2511.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported dumbbell row with an underhand grip for the lats and upper back.\"},{\"id\":\"4836\",\"n\":\"dumbbell reverse grip squeeze bench press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Lie on a bench holding two dumbbells together over your chest with a reverse (palms toward you) grip.\",\"Squeeze the dumbbells together firmly.\",\"Lower them to your chest with elbows close to your body.\",\"Press back up, keeping the squeeze.\",\"Keep your wrists straight throughout.\"],\"img\":\"4836.webp\",\"gif\":\"4836.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell press with a reverse grip and the weights squeezed together. It emphasises the triceps and inner chest.\"},{\"id\":\"6145\",\"n\":\"dumbbell reverse hyperextension on bench\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down on a bench with your hips at the edge.\",\"Hold a dumbbell between your feet.\",\"Hold the bench for support.\",\"Raise your legs until they align with your body.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\"],\"img\":\"6145.webp\",\"gif\":\"6145.mp4\",\"cat\":\"strength\",\"desc\":\"A bench-supported reverse hyper with a dumbbell held between your feet. It strengthens the glutes and hamstrings.\"},{\"id\":\"7326\",\"n\":\"dumbbell reverse lunge from deficit\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your front foot on a low platform, holding dumbbells at your sides.\",\"Step one foot back and lower until the back knee nearly touches the floor.\",\"Keep your torso upright and front knee steady.\",\"Push through the front heel to return.\",\"Finish reps and switch legs.\"],\"img\":\"7326.webp\",\"gif\":\"7326.mp4\",\"cat\":\"strength\",\"desc\":\"Reverse lunge with the front foot raised for a deeper range, hitting the glutes and quads.\"},{\"id\":\"6151\",\"n\":\"dumbbell reverse push up\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\"],\"st\":[\"Place two dumbbells on the floor and grip them.\",\"Set up in a plank position.\",\"Lower your chest with your elbows close to your body.\",\"Stop just above the floor.\",\"Press back up to the start.\",\"Keep your body in a straight line.\"],\"img\":\"6151.webp\",\"gif\":\"6151.mp4\",\"cat\":\"strength\",\"desc\":\"A push-up variation performed with the hands on dumbbells in a reverse hand position. It focuses on the triceps.\"},{\"id\":\"6215\",\"n\":\"dumbbell rollout\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\"],\"st\":[\"Kneel holding a dumbbell in each hand on the floor.\",\"Brace your core.\",\"Roll the dumbbells forward.\",\"Go as far as you can keep your back flat.\",\"Pull back to the start.\",\"Avoid sagging at the hips.\"],\"img\":\"6215.webp\",\"gif\":\"6215.mp4\",\"cat\":\"strength\",\"desc\":\"A rollout using dumbbells in place of a wheel. It challenges the abs.\"},{\"id\":\"9484\",\"n\":\"dumbbell romanian deadlift to squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand holding a dumbbell in each hand in front of your thighs.\",\"Push your hips back and lower the weights along your legs with a flat back.\",\"Feel the hamstring stretch, then drive your hips forward to stand.\",\"Bend your knees and sit down into a squat with your chest up.\",\"Stand back up and repeat the sequence.\"],\"img\":\"9484.webp\",\"gif\":\"9484.mp4\",\"cat\":\"strength\",\"desc\":\"A combo that links a Romanian deadlift with a squat in one fluid rep. It works the hamstrings, glutes and quads together.\"},{\"id\":\"4835\",\"n\":\"dumbbell rotational grip bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench holding dumbbells at chest level with palms facing each other.\",\"Press the weights up while turning your palms to face forward.\",\"Reach full arm extension over your chest.\",\"Lower the weights while rotating back to a neutral grip.\",\"Keep your feet planted and shoulder blades tight.\"],\"img\":\"4835.webp\",\"gif\":\"4835.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell bench press where your grip rotates during the press. It adds a smooth, shoulder-friendly path for the chest.\"},{\"id\":\"3449\",\"n\":\"dumbbell russian twist\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit with knees bent and lean back slightly.\",\"Hold a dumbbell with both hands in front of you.\",\"Rotate your torso to one side.\",\"Rotate to the other side.\",\"Keep your chest lifted.\",\"Move with control.\"],\"img\":\"3449.webp\",\"gif\":\"3449.mp4\",\"cat\":\"strength\",\"desc\":\"A seated rotation with a dumbbell for the obliques.\",\"fv\":\"3450\"},{\"id\":\"4041\",\"n\":\"dumbbell russian twist (on stability ball)\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\",\"glutes\"],\"st\":[\"Sit on a stability ball and walk your feet out until your upper back rests on it, hips lifted.\",\"Hold a dumbbell with both hands above your chest.\",\"Rotate your torso and arms to one side.\",\"Rotate smoothly to the other side.\",\"Keep your hips high and move with control.\"],\"img\":\"4041.webp\",\"gif\":\"4041.mp4\",\"cat\":\"strength\",\"desc\":\"Rotating a dumbbell side to side while balanced on a stability ball. It challenges the obliques and balance.\"},{\"id\":\"4625\",\"n\":\"dumbbell russian twist close grip shoulder press sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"triceps\"],\"st\":[\"Lie on your back with knees bent, holding dumbbells at your shoulders.\",\"Sit up and rotate your torso to one side.\",\"Rotate back to center and press the dumbbells overhead.\",\"Lower them to your shoulders and roll back down.\",\"Alternate sides each rep.\"],\"img\":\"4625.webp\",\"gif\":\"4625.mp4\",\"cat\":\"strength\",\"desc\":\"A compound core move that links a sit-up, a Russian twist and an overhead press with a dumbbell.\"},{\"id\":\"4750\",\"n\":\"dumbbell russian twist with legs floor off\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Sit down and lean back slightly with a dumbbell held in both hands.\",\"Lift your feet off the floor with knees bent.\",\"Rotate your torso to bring the dumbbell beside one hip.\",\"Twist to the other side in a controlled way.\",\"Keep your chest up and your back long.\"],\"img\":\"4750.webp\",\"gif\":\"4750.mp4\",\"cat\":\"strength\",\"desc\":\"A Russian twist with a dumbbell and your feet lifted off the floor. It strongly challenges the obliques and balance.\"},{\"id\":\"3761\",\"n\":\"dumbbell seated alternate biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit upright holding a dumbbell in each hand with arms hanging.\",\"Keep your elbows by your sides.\",\"Curl one dumbbell up to shoulder height.\",\"Lower slowly.\",\"Alternate arms and avoid swinging.\"],\"img\":\"3761.webp\",\"gif\":\"3761.mp4\",\"cat\":\"strength\",\"desc\":\"Seated curls, alternating arms, to build the biceps.\"},{\"id\":\"6148\",\"n\":\"dumbbell seated alternate overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit upright holding a dumbbell in each hand overhead.\",\"Lower one dumbbell behind your head by bending the elbow.\",\"Keep your upper arm close to your head.\",\"Extend the arm back up.\",\"Repeat with the other arm.\",\"Keep your core braced.\"],\"img\":\"6148.webp\",\"gif\":\"6148.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension done one arm after the other. It isolates the triceps through a deep stretch.\"},{\"id\":\"9933\",\"n\":\"dumbbell seated alternating lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Sit upright on a bench with a dumbbell in each hand at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise one arm out to the side until it reaches shoulder height.\",\"Lower it slowly, then raise the other arm.\",\"Keep your torso still and avoid shrugging.\",\"Alternate sides for your reps.\"],\"img\":\"9933.webp\",\"gif\":\"9933.mp4\",\"cat\":\"strength\",\"desc\":\"A seated lateral raise lifting one dumbbell at a time. Sitting reduces body swing so the side delts do the work.\"},{\"id\":\"4066\",\"n\":\"dumbbell seated bent over alternate rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit at the edge of a bench and lean forward with dumbbells hanging below your knees.\",\"Keep your back flat and elbows slightly bent.\",\"Raise one arm out to the side to shoulder height.\",\"Lower slowly.\",\"Alternate arms.\"],\"img\":\"4066.webp\",\"gif\":\"4066.mp4\",\"cat\":\"strength\",\"desc\":\"Seated bent over fly done one arm at a time to hit the rear delts.\"},{\"id\":\"4235\",\"n\":\"dumbbell seated bent over rear delt row\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Sit at the end of a bench with a dumbbell in each hand.\",\"Lean forward with a flat back, arms hanging.\",\"Pull the weights toward your sides with elbows flared out.\",\"Squeeze your rear delts and upper back.\",\"Lower slowly.\",\"Keep your chest close to your thighs.\"],\"img\":\"4235.webp\",\"gif\":\"4235.mp4\",\"cat\":\"strength\",\"desc\":\"A seated bent-over row with elbows flared wide to hit the rear delts. Sitting keeps your legs from helping.\"},{\"id\":\"4237\",\"n\":\"dumbbell seated close grip press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\"],\"st\":[\"Sit upright on a bench with back support, dumbbells at shoulder height.\",\"Hold them close together with palms facing each other.\",\"Press them overhead until your arms are straight.\",\"Keep your core tight and ribs down.\",\"Lower slowly back to your shoulders.\",\"Do not arch your lower back.\"],\"img\":\"4237.webp\",\"gif\":\"4237.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with the dumbbells held close together, palms facing in. It works the front delts and triceps.\"},{\"id\":\"4183\",\"n\":\"dumbbell seated cuban press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Sit tall holding dumbbells at your thighs.\",\"Row them up to chest height with elbows high.\",\"Rotate your forearms upward.\",\"Press the dumbbells overhead.\",\"Reverse the path slowly.\",\"Use light weights.\"],\"img\":\"4183.webp\",\"gif\":\"4183.mp4\",\"cat\":\"strength\",\"desc\":\"A seated move combining an upright row, rotation and press. It strengthens shoulders and rotator cuff.\"},{\"id\":\"3083\",\"n\":\"dumbbell seated curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit on a bench with a dumbbell in each hand.\",\"Let your arms hang by your sides, palms forward.\",\"Curl the weights up toward your shoulders.\",\"Squeeze at the top and keep elbows pinned.\",\"Lower slowly to full extension.\"],\"img\":\"3083.webp\",\"gif\":\"3083.mp4\",\"cat\":\"strength\",\"desc\":\"A seated curl that keeps the body steady while the biceps do the work.\"},{\"id\":\"6150\",\"n\":\"dumbbell seated double concentration curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit on a bench with your feet wide.\",\"Hold a dumbbell in each hand and lean forward.\",\"Rest the backs of your upper arms on your inner thighs.\",\"Curl both dumbbells up toward your shoulders.\",\"Squeeze at the top.\",\"Lower slowly to a full stretch.\"],\"img\":\"6150.webp\",\"gif\":\"6150.mp4\",\"cat\":\"strength\",\"desc\":\"A concentration curl done with both arms at once, elbows braced on your thighs. It isolates the biceps.\"},{\"id\":\"6149\",\"n\":\"dumbbell seated drag curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"rear deltoids\"],\"st\":[\"Sit holding dumbbells with your palms forward.\",\"Keep the weights close to your body.\",\"Pull your elbows back as you curl.\",\"Drag the dumbbells up along your torso.\",\"Squeeze at the top.\",\"Lower with control.\"],\"img\":\"6149.webp\",\"gif\":\"6149.mp4\",\"cat\":\"strength\",\"desc\":\"A curl where the elbows move back and the dumbbells drag up along your torso. It hits the biceps with less shoulder help.\"},{\"id\":\"6140\",\"n\":\"dumbbell seated external rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Sit on a bench holding a light dumbbell.\",\"Rest your elbow on your thigh or bent at your side at 90 degrees.\",\"Rotate your forearm upward and outward.\",\"Pause at the top.\",\"Lower slowly back to the start.\",\"Finish your reps, then switch arms.\"],\"img\":\"6140.webp\",\"gif\":\"6140.mp4\",\"cat\":\"strength\",\"desc\":\"A seated rotator cuff exercise using a light dumbbell. It strengthens the small muscles that stabilize the shoulder.\"},{\"id\":\"5001\",\"n\":\"dumbbell seated external shoulder rotation\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Sit holding a light dumbbell with your elbow bent to 90 degrees and tucked to your side.\",\"Rest your arm on your thigh or a pad for support.\",\"Rotate your forearm upward and outward, keeping the elbow in place.\",\"Pause briefly at the top.\",\"Lower slowly, then switch arms after your reps.\"],\"img\":\"5001.webp\",\"gif\":\"5001.mp4\",\"cat\":\"strength\",\"desc\":\"Seated rotation with a light dumbbell that trains the muscles on the back of the shoulder. It supports healthy shoulders.\"},{\"id\":\"4157\",\"n\":\"dumbbell seated front and back tate press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit upright holding dumbbells above your chest, palms facing your feet.\",\"Keep your upper arms close to your torso.\",\"Lower the weights with elbows flared until they touch your chest.\",\"Extend your elbows to push the weights up and slightly forward.\",\"Return to the start in a controlled path.\",\"Keep your back straight and avoid arching.\"],\"img\":\"4157.webp\",\"gif\":\"4157.mp4\",\"cat\":\"strength\",\"desc\":\"A seated triceps move where the dumbbells go from the chest outward in front and back. It hits the triceps from a unique angle.\"},{\"id\":\"4053\",\"n\":\"dumbbell seated gittleson shrug\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"grip muscles\",\"forearms\"],\"st\":[\"Sit upright on a bench holding a dumbbell in each hand at your sides.\",\"Keep your arms straight and chest up.\",\"Shrug your shoulders straight up toward your ears.\",\"Pause at the top.\",\"Lower slowly and repeat without rolling your shoulders.\"],\"img\":\"4053.webp\",\"gif\":\"4053.mp4\",\"cat\":\"strength\",\"desc\":\"Seated shrug variation with a dumbbell in each hand that builds the upper traps.\"},{\"id\":\"4055\",\"n\":\"dumbbell seated lateral raise on stability ball\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"core\",\"upper back\"],\"st\":[\"Sit upright on a stability ball with a dumbbell in each hand at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides to shoulder height.\",\"Pause briefly.\",\"Lower slowly without swinging.\"],\"img\":\"4055.webp\",\"gif\":\"4055.mp4\",\"cat\":\"strength\",\"desc\":\"Seated side raise performed on a stability ball. It trains the side delts and trunk balance.\"},{\"id\":\"4238\",\"n\":\"dumbbell seated lateral to front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Sit tall on a bench holding light dumbbells at your sides.\",\"Raise both arms out to the sides to shoulder height.\",\"Lower them back to your sides.\",\"Raise both arms to the front to shoulder height.\",\"Lower and repeat.\",\"Avoid leaning back or swinging.\"],\"img\":\"4238.webp\",\"gif\":\"4238.mp4\",\"cat\":\"strength\",\"desc\":\"A seated raise that combines a side raise and a front raise in one rep. It builds the delts from two angles.\"},{\"id\":\"6802\",\"n\":\"dumbbell seated military hold alternate leg raise on floor\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hip flexors\",\"lower abs\",\"triceps\"],\"st\":[\"Sit on the floor leaning back a little and press the dumbbells overhead.\",\"Keep your arms locked and steady.\",\"Raise one leg off the floor.\",\"Lower it and raise the other leg.\",\"Keep alternating, then lower the weights.\"],\"img\":\"6802.webp\",\"gif\":\"6802.mp4\",\"cat\":\"strength\",\"desc\":\"You hold dumbbells overhead while raising the legs alternately. It trains the lower abs and shoulder stability.\"},{\"id\":\"6801\",\"n\":\"dumbbell seated military press in out leg raise on floor\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"hip flexors\",\"lower abs\"],\"st\":[\"Sit on the floor leaning back slightly, dumbbells at your shoulders.\",\"Press the dumbbells overhead.\",\"Pull your knees in, then extend the legs out as the weights stay up.\",\"Lower the dumbbells to your shoulders.\",\"Repeat, keeping your back long and core braced.\"],\"img\":\"6801.webp\",\"gif\":\"6801.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press combined with in and out leg movements. It works the shoulders and the lower abs together.\"},{\"id\":\"3690\",\"n\":\"dumbbell seated on exercise ball shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Sit on a stability ball with your feet wide and a dumbbell in each hand at shoulder height.\",\"Brace your core and sit tall.\",\"Press the dumbbells overhead until your arms are almost straight.\",\"Lower them back to shoulder height with control.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"3690.webp\",\"gif\":\"3690.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press on a stability ball. The unstable seat makes your core work along with the shoulders.\"},{\"id\":\"4120\",\"n\":\"dumbbell seated one arm arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\"],\"st\":[\"Sit upright with a dumbbell in one hand at chest height, palm facing you.\",\"Press up while rotating your palm forward.\",\"Fully extend overhead.\",\"Lower while rotating back.\",\"Finish all reps, then switch arms.\"],\"img\":\"4120.webp\",\"gif\":\"4120.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one arm Arnold press for shoulders with rotation through the movement.\"},{\"id\":\"3689\",\"n\":\"dumbbell seated one arm front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\"],\"st\":[\"Sit upright on a bench holding a dumbbell in one hand, arm down at your thigh.\",\"Raise the dumbbell straight in front of you to shoulder height with a soft elbow.\",\"Pause briefly at the top.\",\"Lower it slowly back to your thigh.\",\"Finish your reps, then switch arms.\"],\"img\":\"3689.webp\",\"gif\":\"3689.mp4\",\"cat\":\"strength\",\"desc\":\"A seated single-arm raise that targets the front of the shoulder without leg drive helping out.\"},{\"id\":\"1231\",\"n\":\"dumbbell seated one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Sit on a bench with back support, holding a dumbbell at your shoulder.\",\"Brace your core.\",\"Press the dumbbell up until your arm is straight.\",\"Lower it slowly to your shoulder.\",\"Finish your reps, then switch arms.\"],\"img\":\"1231.webp\",\"gif\":\"1231.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with one dumbbell. Working one arm at a time shows any imbalances.\"},{\"id\":\"6142\",\"n\":\"dumbbell seated reverse arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"rotator cuff\"],\"st\":[\"Sit upright holding dumbbells overhead with your palms forward.\",\"Lower the weights while rotating your palms toward you.\",\"Stop with the dumbbells in front of your chest.\",\"Rotate your palms back outward as you press up.\",\"Lock out the arms overhead.\",\"Keep your back against the pad.\"],\"img\":\"6142.webp\",\"gif\":\"6142.mp4\",\"cat\":\"strength\",\"desc\":\"The Arnold press performed in reverse, rotating the palms inward on the way down. It works all three heads of the shoulder.\"},{\"id\":\"3688\",\"n\":\"dumbbell seated reverse grip biceps curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"wrist extensors\"],\"st\":[\"Sit on a bench with a dumbbell in each hand, palms facing down, arms hanging at your sides.\",\"Keep your elbows pinned to your sides and curl the weights up.\",\"Stop when your forearms are near vertical and your wrists stay straight.\",\"Lower the dumbbells slowly until your arms are fully extended.\",\"Use a lighter weight than a normal curl.\"],\"img\":\"3688.webp\",\"gif\":\"3688.mp4\",\"cat\":\"strength\",\"desc\":\"A seated curl with an overhand grip that hits the forearms and brachialis hard along with the biceps.\"},{\"id\":\"6143\",\"n\":\"dumbbell seated single arm front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"biceps\",\"core\"],\"st\":[\"Sit tall holding a dumbbell at your side.\",\"Raise the dumbbell forward to shoulder height with a soft elbow.\",\"Pause at the top.\",\"Lower with control.\",\"Avoid leaning back.\",\"Finish your reps, then switch arms.\"],\"img\":\"6143.webp\",\"gif\":\"6143.mp4\",\"cat\":\"strength\",\"desc\":\"A seated front raise done one arm at a time. It targets the front of the shoulder.\"},{\"id\":\"6158\",\"n\":\"dumbbell seated single arm overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit upright holding a dumbbell in one hand overhead.\",\"Keep the upper arm close to your head.\",\"Lower the dumbbell behind your head by bending the elbow.\",\"Extend the arm back to full lockout.\",\"Keep your core braced.\",\"Finish your reps, then switch arms.\"],\"img\":\"6158.webp\",\"gif\":\"6158.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension with one dumbbell. It isolates the triceps.\"},{\"id\":\"6159\",\"n\":\"dumbbell seated single arm overhead triceps extension (left)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit upright holding a dumbbell in your left hand overhead.\",\"Keep the upper arm close to your head.\",\"Lower the dumbbell behind your head by bending the elbow.\",\"Extend the arm back to full lockout.\",\"Keep your core braced.\",\"Finish your reps, then switch to the right arm.\"],\"img\":\"6159.webp\",\"gif\":\"6159.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead triceps extension with one dumbbell. This version uses the left arm.\"},{\"id\":\"7892\",\"n\":\"dumbbell seated triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\",\"core\"],\"st\":[\"Sit on a bench with back support, holding one dumbbell overhead with both hands.\",\"Keep your upper arms close to your head.\",\"Lower the weight behind your head by bending your elbows.\",\"Extend your arms back up.\",\"Keep your core tight.\",\"Repeat for the planned reps.\"],\"img\":\"7892.webp\",\"gif\":\"7892.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension with a dumbbell that builds the triceps.\"},{\"id\":\"4626\",\"n\":\"dumbbell seated tuck crunch on floor\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Sit on the floor holding a dumbbell at your chest and lean back slightly.\",\"Extend your legs and lift your feet off the floor.\",\"Pull your knees in toward your chest.\",\"Extend your legs back out under control.\",\"Keep your spine long throughout.\"],\"img\":\"4626.webp\",\"gif\":\"4626.mp4\",\"cat\":\"strength\",\"desc\":\"A seated tuck crunch holding a dumbbell to work the abs and hip flexors under load.\"},{\"id\":\"4628\",\"n\":\"dumbbell seated tuck twisting crunch on floor\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit on the floor holding a dumbbell at your chest and lean back slightly.\",\"Lift your feet off the floor.\",\"Pull your knees in and rotate your torso to one side.\",\"Extend your legs and rotate back to center.\",\"Repeat on the other side.\"],\"img\":\"4628.webp\",\"gif\":\"4628.mp4\",\"cat\":\"strength\",\"desc\":\"A seated tuck with a twist, adding oblique work to the dumbbell-loaded crunch.\"},{\"id\":\"3946\",\"n\":\"dumbbell seated upright alternate squeeze press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"shoulders\"],\"st\":[\"Sit upright with a dumbbell in each hand, pressed together in front of your chest.\",\"Keep the two dumbbells touching.\",\"Press one dumbbell forward until the arm is straight.\",\"Bring it back and press with the other arm.\",\"Keep squeezing the weights together.\"],\"img\":\"3946.webp\",\"gif\":\"3946.mp4\",\"cat\":\"strength\",\"desc\":\"Press two dumbbells held together, one arm at a time, while seated upright. It trains the chest with a strong inner squeeze.\"},{\"id\":\"4110\",\"n\":\"dumbbell seated zottman curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"wrist extensors\"],\"st\":[\"Sit upright holding dumbbells with palms facing forward.\",\"Curl both dumbbells up to shoulder height.\",\"At the top rotate your palms to face down.\",\"Lower slowly in that reverse grip.\",\"Rotate your palms back up at the bottom.\"],\"img\":\"4110.webp\",\"gif\":\"4110.mp4\",\"cat\":\"strength\",\"desc\":\"A seated curl that turns your palms down on the way back, training biceps and forearms.\"},{\"id\":\"5065\",\"n\":\"dumbbell shoulder internal rotation at 90 abduction\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\"],\"st\":[\"Lie on your side or stand with your upper arm out at 90 degrees and elbow bent 90 degrees.\",\"Hold a light dumbbell with the forearm pointing up.\",\"Rotate your forearm forward and down without moving the upper arm.\",\"Pause briefly at the bottom.\",\"Return slowly to the start, then switch arms after your reps.\"],\"img\":\"5065.webp\",\"gif\":\"5065.mp4\",\"cat\":\"rehab\",\"desc\":\"Rotate a light dumbbell forward with your upper arm held out at shoulder height. It strengthens the internal rotators of the shoulder.\"},{\"id\":\"10196\",\"n\":\"dumbbell shoulders complex\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"trapezius\",\"upper back\",\"core\"],\"st\":[\"Stand with a light dumbbell in each hand at your sides.\",\"Do a set of lateral raises, then straight into front raises.\",\"Move into a set of overhead presses without putting the weights down.\",\"Lower the dumbbells under control and rest.\",\"Keep the weights light and your torso still throughout.\"],\"img\":\"10196.webp\",\"gif\":\"10196.mp4\",\"cat\":\"strength\",\"desc\":\"A chained set of dumbbell shoulder moves done without rest, building shoulder strength and endurance.\"},{\"id\":\"4752\",\"n\":\"dumbbell side bench squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand sideways to a bench holding a dumbbell at your chest, feet wide.\",\"Shift your weight to the leg nearest the bench.\",\"Sit back and down until you lightly touch the bench.\",\"Keep the other leg straight.\",\"Drive up through your heel and repeat, then switch sides.\"],\"img\":\"4752.webp\",\"gif\":\"4752.mp4\",\"cat\":\"strength\",\"desc\":\"A side squat where you sit back toward a bench while holding a dumbbell. It works the thighs and glutes one side at a time.\"},{\"id\":\"4335\",\"n\":\"dumbbell side bend v. 2\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand tall holding a dumbbell in one hand at your side.\",\"Place your other hand behind your head.\",\"Bend sideways toward the weighted side, keeping your hips still.\",\"Squeeze the opposite side to return upright.\",\"Finish your reps, then switch hands.\"],\"img\":\"4335.webp\",\"gif\":\"4335.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted side bend using a dumbbell to load the obliques.\"},{\"id\":\"3337\",\"n\":\"dumbbell side bridge\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on one side with your elbow under your shoulder and legs stacked.\",\"Hold a dumbbell on your top hip.\",\"Lift your hips so your body forms a straight line.\",\"Hold for 20 to 30 seconds without sagging.\",\"Lower, then repeat on the other side.\"],\"img\":\"3337.webp\",\"gif\":\"3337.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with a dumbbell held on your hip or raised overhead. It trains the obliques and lateral stability.\",\"hd\":1,\"fv\":\"2739\"},{\"id\":\"4457\",\"n\":\"dumbbell side bridge with bent leg\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Lie on your side with your knees bent and your forearm under your shoulder.\",\"Hold a dumbbell in your top hand, resting on your hip.\",\"Lift your hips so your body forms a line from head to knees.\",\"Hold the position while breathing steadily.\",\"Keep your hips stacked and do not sink.\",\"Lower and switch sides after your set.\"],\"img\":\"4457.webp\",\"gif\":\"4457.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank on a bent knee holding a dumbbell. Strengthens the obliques and trunk while teaching stability.\",\"hd\":1},{\"id\":\"1215\",\"n\":\"dumbbell side lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a dumbbell in each hand or one at your chest and stand tall.\",\"Step out wide to one side and sit your hips back.\",\"Keep the other leg straight and your chest upright.\",\"Push through the bent leg to return to the middle.\",\"Alternate sides or finish all reps on one side before switching.\"],\"img\":\"1215.webp\",\"gif\":\"1215.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral lunge with dumbbells that trains the glutes, quads and inner thighs in the frontal plane.\"},{\"id\":\"3448\",\"n\":\"dumbbell side lunge v. 3\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Hold a dumbbell in each hand.\",\"Step wide to one side.\",\"Sit your hips back and bend that knee.\",\"Keep your other leg straight.\",\"Push off to return to center.\",\"Alternate sides.\"],\"img\":\"3448.webp\",\"gif\":\"3448.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge with dumbbells that works the thighs and inner thighs.\",\"fv\":\"3447\"},{\"id\":\"4753\",\"n\":\"dumbbell side lunge with shoulder press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand holding dumbbells at your shoulders.\",\"Step out wide to one side and sit your hips back into a side lunge.\",\"Keep the other leg straight and your chest up.\",\"Push back to the middle and press the dumbbells overhead.\",\"Lower to your shoulders and lunge to the other side.\"],\"img\":\"4753.webp\",\"gif\":\"4753.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge paired with an overhead press. It trains the legs and shoulders together.\"},{\"id\":\"5817\",\"n\":\"dumbbell side lying external rotation (on a bench)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie on your side on a bench with a light dumbbell in the top hand.\",\"Keep your elbow bent at 90 degrees and tucked to your side.\",\"Rotate your forearm upward, keeping your elbow still.\",\"Pause at the top.\",\"Lower slowly and switch sides after your set.\"],\"img\":\"5817.webp\",\"gif\":\"5817.mp4\",\"cat\":\"rehab\",\"desc\":\"A gentle shoulder rotation lying on your side with a light dumbbell. It strengthens the rotator cuff for joint stability.\"},{\"id\":\"10041\",\"n\":\"dumbbell side plank v. 2\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Lie on your side, elbow under your shoulder, with a dumbbell in your top hand.\",\"Lift your hips into a straight line from head to feet.\",\"Hold the dumbbell either at your side or pointing to the ceiling.\",\"Hold for 15-30 seconds.\",\"Lower with control, then switch sides.\",\"Keep your hips high and don't rotate.\"],\"img\":\"10041.webp\",\"gif\":\"10041.mp4\",\"cat\":\"strength\",\"desc\":\"A side plank with a dumbbell added, usually held in the top hand, to make the hold harder.\",\"hd\":1},{\"id\":\"4754\",\"n\":\"dumbbell side squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand with feet wide holding a dumbbell at your chest.\",\"Shift to one side and bend that knee, sitting your hips back.\",\"Keep the other leg straight and both feet flat.\",\"Lower until your thigh is parallel to the floor.\",\"Push back to the middle and alternate sides.\"],\"img\":\"4754.webp\",\"gif\":\"4754.mp4\",\"cat\":\"strength\",\"desc\":\"A wide side squat with a dumbbell, bending one leg while the other stays straight. It works the thighs and inner legs.\"},{\"id\":\"5097\",\"n\":\"dumbbell single arm alternate decline bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on a decline bench holding a dumbbell in each hand over your chest.\",\"Lower one dumbbell to the side of your chest.\",\"Press it back up until your arm is straight.\",\"Repeat with the other arm.\",\"Keep your core tight and the bench-side arm steady.\"],\"img\":\"5097.webp\",\"gif\":\"5097.mp4\",\"cat\":\"strength\",\"desc\":\"Press dumbbells on a decline bench one arm at a time. It hits the lower chest and keeps your core working to stay balanced.\"},{\"id\":\"5098\",\"n\":\"dumbbell single arm alternate fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench with a dumbbell in each hand above your chest.\",\"Keep a soft bend in your elbows.\",\"Lower one arm out to the side in a wide arc.\",\"Squeeze your chest to bring it back up.\",\"Alternate with the other arm.\"],\"img\":\"5098.webp\",\"gif\":\"5098.mp4\",\"cat\":\"strength\",\"desc\":\"Perform chest flys with one dumbbell at a time. The alternating pattern challenges stability while working the chest.\",\"nd\":[\"bench\"]},{\"id\":\"4837\",\"n\":\"dumbbell single arm bent over row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Hold a dumbbell in one hand and hinge forward with a flat back.\",\"Let the arm hang straight down.\",\"Pull the dumbbell toward your hip, leading with your elbow.\",\"Squeeze your back at the top.\",\"Lower slowly and switch sides after your reps.\"],\"img\":\"4837.webp\",\"gif\":\"4837.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row in a hinged position. It builds the lats and upper back, one side at a time.\"},{\"id\":\"9699\",\"n\":\"dumbbell single arm chest supported row\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lie face down on an incline bench holding a dumbbell in one hand.\",\"Let your arm hang straight down.\",\"Row the dumbbell toward your hip.\",\"Squeeze your back at the top.\",\"Lower slowly, finish your reps, then switch arms.\"],\"img\":\"9699.webp\",\"gif\":\"9699.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row with your chest braced on an incline bench. It lets you focus on each side of the back.\"},{\"id\":\"11864\",\"n\":\"dumbbell single arm curl with isometric hold\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding a dumbbell at your side, palm forward.\",\"Curl the weight up until your elbow is bent to 90 degrees.\",\"Hold that position for 2-3 seconds.\",\"Finish the curl, then lower slowly.\",\"Complete your reps and switch arms.\"],\"img\":\"11864.webp\",\"gif\":\"11864.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl that pauses at the halfway point to increase biceps tension.\"},{\"id\":\"5093\",\"n\":\"dumbbell single arm floor press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on your back with your knees bent, holding a dumbbell at chest level.\",\"Rest your other arm on the floor.\",\"Press the dumbbell straight up until your arm is straight.\",\"Lower it until your upper arm touches the floor.\",\"Finish your reps, then switch arms.\"],\"img\":\"5093.webp\",\"gif\":\"5093.mp4\",\"cat\":\"strength\",\"desc\":\"Press one dumbbell up from the floor. Lying on the floor limits the range of motion and challenges your core to stay still.\"},{\"id\":\"2415\",\"n\":\"dumbbell single arm leaning lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Hold a support with one hand and lean your body away.\",\"Hold a dumbbell in your free hand by your side.\",\"Raise the dumbbell out to the side until it reaches shoulder height.\",\"Keep a slight bend in your elbow.\",\"Lower slowly to the start.\",\"Finish your reps, then switch arms.\"],\"img\":\"2415.webp\",\"gif\":\"2415.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise done while leaning away from a support for a greater range on the side delt.\"},{\"id\":\"5944\",\"n\":\"dumbbell single arm neutral grip front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Stand tall holding a dumbbell at your side with palm facing in.\",\"Brace your core and keep a soft bend in your elbow.\",\"Raise the dumbbell forward to shoulder height.\",\"Pause briefly, then lower with control.\",\"Avoid swinging, finish all reps and switch arms.\"],\"img\":\"5944.webp\",\"gif\":\"5944.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm dumbbell front raise using a hammer grip, targeting the front deltoid with less wrist strain.\"},{\"id\":\"5095\",\"n\":\"dumbbell single arm overhead lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\"],\"st\":[\"Press a dumbbell overhead with one arm and lock it out.\",\"Step forward into a lunge.\",\"Lower your back knee toward the floor, keeping your torso upright.\",\"Push through the front foot to return.\",\"Finish your reps, then switch arms.\"],\"img\":\"5095.webp\",\"gif\":\"5095.mp4\",\"cat\":\"strength\",\"desc\":\"Lunge while holding one dumbbell overhead. The one-sided load challenges balance and trunk stability.\"},{\"id\":\"3084\",\"n\":\"dumbbell single arm preacher curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit at a preacher bench with your upper arm on the pad.\",\"Hold a dumbbell with your palm facing up.\",\"Curl the weight toward your shoulder.\",\"Squeeze at the top.\",\"Lower slowly until nearly straight, then switch arms.\"],\"img\":\"3084.webp\",\"gif\":\"3084.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl braced on a preacher pad for strict biceps isolation.\"},{\"id\":\"10901\",\"n\":\"dumbbell single arm shrug\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"grip muscles\",\"trapezius\"],\"st\":[\"Stand tall holding a dumbbell in one hand at your side.\",\"Keep your arm straight and your shoulders relaxed.\",\"Lift your shoulder straight up toward your ear.\",\"Hold for a moment at the top.\",\"Lower slowly. Finish your reps and switch arms.\"],\"img\":\"10901.webp\",\"gif\":\"10901.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm shrug with a dumbbell. It builds the upper traps and grip.\"},{\"id\":\"5092\",\"n\":\"dumbbell single arm underhand front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"biceps\"],\"st\":[\"Stand tall with a dumbbell in one hand, palm facing forward.\",\"Keep your core braced.\",\"Raise the dumbbell in front of you to shoulder height.\",\"Lower it slowly to your thigh.\",\"Complete your reps, then switch arms.\"],\"img\":\"5092.webp\",\"gif\":\"5092.mp4\",\"cat\":\"strength\",\"desc\":\"Lift one dumbbell to the front with your palm facing up. This variation trains the front delt and upper chest.\"},{\"id\":\"10043\",\"n\":\"dumbbell single arm z press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"obliques\",\"upper back\"],\"st\":[\"Sit on the floor with legs straight out and back tall.\",\"Hold a dumbbell at shoulder height in one hand.\",\"Press the dumbbell overhead until your arm is straight.\",\"Lower back to your shoulder with control.\",\"Finish your reps and switch arms.\",\"Brace your abs and don't lean back.\"],\"img\":\"10043.webp\",\"gif\":\"10043.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press on the floor with legs straight, using one arm. It removes leg drive and challenges your trunk.\"},{\"id\":\"3973\",\"n\":\"dumbbell single leg calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Hold a dumbbell in one hand and stand on the ball of the opposite foot, ideally on a step.\",\"Rest your free hand on a wall or rail for balance.\",\"Lift your heel as high as you can, squeezing the calf.\",\"Pause for a moment at the top.\",\"Lower your heel slowly below the step level, then repeat and switch legs.\"],\"img\":\"3973.webp\",\"gif\":\"3973.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf raise holding a dumbbell for extra load. It builds calf strength and ankle stability.\"},{\"id\":\"2806\",\"n\":\"dumbbell single leg deadlift with stepbox support v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Hold a dumbbell and rest the toes of one foot on a step box behind you.\",\"Soften the front knee and hinge at the hips, lowering the dumbbell along your leg.\",\"Keep your back flat and go as far as your hamstring allows.\",\"Drive your hips forward to stand tall.\",\"Complete all reps, then switch legs.\"],\"img\":\"2806.webp\",\"gif\":\"2806.mp4\",\"cat\":\"strength\",\"desc\":\"A one leg deadlift with the rear foot resting on a step box for balance. Works hamstrings and glutes with less wobble.\",\"fv\":\"2805\"},{\"id\":\"2750\",\"n\":\"dumbbell single leg deadlift with wall support\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand near a wall, holding a dumbbell and resting one hand on it for balance.\",\"Lift one leg behind you.\",\"Hinge at the hips and lower the dumbbell down your standing leg.\",\"Keep your back flat.\",\"Squeeze your glute to stand tall, then switch legs.\"],\"img\":\"2750.webp\",\"gif\":\"2750.mp4\",\"cat\":\"strength\",\"desc\":\"A one-legged deadlift where a wall helps you balance while the hamstrings and glutes do the work.\"},{\"id\":\"4291\",\"n\":\"dumbbell single leg glute bridge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one knee bent, foot flat, and the other leg extended or raised.\",\"Rest a dumbbell across your hips and hold it steady.\",\"Drive through the planted heel and lift your hips until your body forms a straight line.\",\"Squeeze your glute at the top for a second.\",\"Lower with control and repeat, then switch legs.\"],\"img\":\"4291.webp\",\"gif\":\"4291.mp4\",\"cat\":\"strength\",\"desc\":\"A one-legged hip bridge with a dumbbell resting on your hips. It hits the glutes hard and challenges hip stability.\",\"fv\":\"5755\"},{\"id\":\"4755\",\"n\":\"dumbbell single leg hip thrust\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Sit with your upper back on a bench and a dumbbell across your hips.\",\"Plant one foot and lift the other leg off the floor.\",\"Drive through the planted heel to raise your hips until level.\",\"Squeeze your glute at the top.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"4755.webp\",\"gif\":\"4755.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip thrust with a dumbbell on your hips. It builds glute strength and hip stability.\"},{\"id\":\"8075\",\"n\":\"dumbbell single leg hip thrust v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Sit with your upper back against a bench and a dumbbell on your hips.\",\"Plant one foot and lift the other leg.\",\"Drive your hips up until your body is straight.\",\"Squeeze your glute at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"8075.webp\",\"gif\":\"8075.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip thrust with a dumbbell across your hips. It hits the glutes hard and shows up strength imbalances.\"},{\"id\":\"10865\",\"n\":\"dumbbell single leg romanian deadlift on bench\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Hold dumbbells with your rear foot resting on a bench.\",\"Keep your front knee soft.\",\"Hinge forward at the hips.\",\"Lower the weights along your leg.\",\"Squeeze your glutes to stand up.\",\"Switch legs after the set.\"],\"img\":\"10865.webp\",\"gif\":\"10865.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg Romanian deadlift with the rear foot on a bench. It targets hamstrings and glutes.\"},{\"id\":\"3767\",\"n\":\"dumbbell single leg squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"ankles\"],\"st\":[\"Hold a dumbbell at your chest and stand on one leg.\",\"Extend your other leg in front of you.\",\"Lower into a squat as far as you can control.\",\"Push through your heel to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"3767.webp\",\"gif\":\"3767.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat holding a dumbbell for balance and extra load.\",\"fv\":\"3766\"},{\"id\":\"2925\",\"n\":\"dumbbell single leg step up\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand facing a box or bench.\",\"Place one foot fully on the box.\",\"Drive through that heel to stand up tall.\",\"Lower back down under control without bouncing off the floor foot.\",\"Finish the reps, then switch legs.\"],\"img\":\"2925.webp\",\"gif\":\"2925.mp4\",\"cat\":\"strength\",\"desc\":\"Stepping up onto a bench with one leg while holding dumbbells. It builds single-leg strength in the quads and glutes.\"},{\"id\":\"4821\",\"n\":\"dumbbell single leg step up on bench\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a bench holding a dumbbell in each hand.\",\"Place one foot fully on the bench.\",\"Press through that heel to stand up on the bench.\",\"Lower your other foot back down slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"4821.webp\",\"gif\":\"4821.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg step-up onto a bench with dumbbells at your sides. It builds leg strength and balance.\"},{\"id\":\"5101\",\"n\":\"dumbbell single power clean\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"shoulders\",\"quadriceps\"],\"st\":[\"Stand over a dumbbell with feet hip-width apart.\",\"Hinge down and grip it with a flat back.\",\"Explode up through your hips and shrug.\",\"Pull the dumbbell up and catch it at your shoulder.\",\"Lower it back down under control, then switch arms.\"],\"img\":\"5101.webp\",\"gif\":\"5101.mp4\",\"cat\":\"olympic\",\"desc\":\"Explosively pull one dumbbell from the floor to your shoulder. It builds power through the hips and legs.\"},{\"id\":\"3963\",\"n\":\"dumbbell single spider curl with chest support\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie chest down on an incline bench with one arm hanging, dumbbell in hand.\",\"Keep your upper arm vertical.\",\"Curl the weight up toward your shoulder.\",\"Squeeze, then lower fully.\",\"Finish your reps, then switch arms.\"],\"img\":\"3963.webp\",\"gif\":\"3963.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl done lying chest down on an incline bench. It isolates the biceps with no swinging.\"},{\"id\":\"3338\",\"n\":\"dumbbell single stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Stand on one leg with a dumbbell in the opposite hand or both hands.\",\"Keep a soft bend in your standing knee.\",\"Hinge forward while your free leg extends behind you.\",\"Lower the dumbbell toward the floor with a flat back.\",\"Squeeze your glute to stand back up, then switch legs.\"],\"img\":\"3338.webp\",\"gif\":\"3338.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg hinge holding a dumbbell, which trains your hamstrings, glutes and balance.\"},{\"id\":\"4756\",\"n\":\"dumbbell sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"obliques\"],\"st\":[\"Lie on your back with knees bent and feet flat or anchored.\",\"Hold a dumbbell against your chest with both hands.\",\"Curl your torso up until you are sitting.\",\"Keep your neck neutral.\",\"Lower back down slowly.\"],\"img\":\"4756.webp\",\"gif\":\"4756.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up holding a dumbbell against your chest for extra resistance.\",\"fv\":\"10713\"},{\"id\":\"9515\",\"n\":\"dumbbell sitting good morning\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\",\"upper back\"],\"st\":[\"Sit on a bench with feet flat and hold a dumbbell against your chest.\",\"Sit tall and brace your core.\",\"Hinge forward from the hips, keeping your back flat.\",\"Stop when your torso is about halfway down.\",\"Squeeze your back and glutes to sit tall again.\"],\"img\":\"9515.webp\",\"gif\":\"9515.mp4\",\"cat\":\"strength\",\"desc\":\"A seated good morning with a dumbbell held at your chest, bowing forward to train the lower back with less leg involvement.\"},{\"id\":\"9931\",\"n\":\"dumbbell spider curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie face down on an incline bench with a dumbbell in each hand and your arms hanging straight down.\",\"Keep your upper arms vertical and your palms facing forward.\",\"Curl the dumbbells up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are fully extended.\",\"Keep your chest on the pad and avoid swinging.\"],\"img\":\"9931.webp\",\"gif\":\"9931.mp4\",\"cat\":\"strength\",\"desc\":\"A curl performed chest-down on an incline bench so the arms hang straight. It removes swing and puts the stress on the biceps.\"},{\"id\":\"1554\",\"n\":\"dumbbell split jump\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Hold a dumbbell in each hand and step into a lunge position.\",\"Lower until both knees are bent at about 90 degrees.\",\"Explode upward and swap your leg positions in the air.\",\"Land softly in a lunge with the opposite leg forward.\",\"Keep your torso upright and move fluidly from rep to rep.\"],\"img\":\"1554.webp\",\"gif\":\"1554.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping lunge where you switch legs in the air while holding dumbbells. It builds explosive leg power.\"},{\"id\":\"2960\",\"n\":\"dumbbell split squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and take a long stance, one foot forward.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Push through your front heel to stand.\",\"Finish the reps, then switch legs.\"],\"img\":\"2960.webp\",\"gif\":\"2960.mp4\",\"cat\":\"strength\",\"desc\":\"A stationary lunge with dumbbells at your sides. It strengthens one leg at a time, mainly the quads and glutes.\",\"fv\":\"2959\"},{\"id\":\"2957\",\"n\":\"dumbbell split squat front foot elevated\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and place your front foot on a low platform.\",\"Step your back foot behind you.\",\"Lower your back knee toward the floor with your torso upright.\",\"Push through your front heel to stand.\",\"Finish the reps, then switch legs.\"],\"img\":\"2957.webp\",\"gif\":\"2957.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat holding dumbbells at your sides with the front foot raised. It deepens the range for the quads and glutes.\",\"fv\":\"2958\"},{\"id\":\"3710\",\"n\":\"dumbbell split squat front foot elevated with bosu ball\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Hold a dumbbell in each hand and place your front foot on a bosu ball, back foot behind you.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Press through your front foot to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"3710.webp\",\"gif\":\"3710.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with the front foot on a bosu ball for a deeper range and extra balance work.\"},{\"id\":\"5284\",\"n\":\"dumbbell sprinter thrust chest press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Lie on a bench holding dumbbells at your chest.\",\"Drive one knee up toward your chest.\",\"Press the dumbbells up until your arms are straight.\",\"Lower the dumbbells and switch legs.\",\"Keep a steady rhythm.\"],\"img\":\"5284.webp\",\"gif\":\"5284.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing dumbbells from the chest while driving one knee up like a sprinter. It combines upper body strength with a core-driven leg movement.\",\"nd\":[\"bench\"]},{\"id\":\"0412\",\"n\":\"dumbbell squat (back on stability ball wall)\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Place a stability ball between your lower back and a wall and hold a dumbbell in each hand.\",\"Step your feet forward, shoulder width apart.\",\"Bend your knees and sink down as the ball rolls up your back.\",\"Lower until your thighs are about parallel to the floor.\",\"Push through your heels to stand back up.\",\"Keep your knees tracking over your toes.\"],\"img\":\"0412.webp\",\"gif\":\"0412.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell squat with a stability ball pinned between your back and a wall. The ball guides the movement and takes stress off your lower back.\"},{\"id\":\"4563\",\"n\":\"dumbbell squat hold calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"soleus\"],\"st\":[\"Hold dumbbells at your sides and sink into a half squat.\",\"Keep your chest tall and weight over your feet.\",\"Lift your heels as high as you can.\",\"Pause briefly at the top.\",\"Lower your heels slowly without standing up.\",\"Stay in the squat for the full set.\"],\"img\":\"4563.webp\",\"gif\":\"4563.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise done from a held squat position, mixing calf work with leg endurance.\"},{\"id\":\"4564\",\"n\":\"dumbbell squat lunges jump complex\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold dumbbells at your sides and stand with feet shoulder-width apart.\",\"Do a squat and stand back up.\",\"Step into a lunge on each leg.\",\"Finish with a jump, landing softly with bent knees.\",\"Continue the chain without putting the weights down.\",\"Rest, then repeat the sequence.\"],\"img\":\"4564.webp\",\"gif\":\"4564.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A leg-burning chain of squat, lunge and jump with dumbbells for strength and conditioning.\"},{\"id\":\"5066\",\"n\":\"dumbbell squat to overhead press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart, dumbbells at your shoulders.\",\"Sit your hips back and down into a squat with your chest up.\",\"Drive up through your feet to stand.\",\"Use that momentum to press the dumbbells overhead until your arms are straight.\",\"Lower them to your shoulders and go into the next squat.\"],\"img\":\"5066.webp\",\"gif\":\"5066.mp4\",\"cat\":\"strength\",\"desc\":\"Squat with dumbbells at your shoulders, then press them overhead as you stand. A full-body move that links leg drive into a press.\"},{\"id\":\"1555\",\"n\":\"dumbbell squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart, holding a dumbbell in each hand at your sides.\",\"Push your hips back and bend your knees to lower down.\",\"Go until your thighs are parallel to the floor or a bit lower.\",\"Keep your chest up and your heels planted.\",\"Press through your feet to stand back up.\"],\"img\":\"1555.webp\",\"gif\":\"1555.mp4\",\"cat\":\"strength\",\"desc\":\"A simple squat holding a dumbbell in each hand. It is a solid all-round leg builder that is easy to load.\"},{\"id\":\"3681\",\"n\":\"dumbbell squeeze bench press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench holding dumbbells pressed together above your chest.\",\"Squeeze them together throughout.\",\"Lower them to your chest.\",\"Press back up.\",\"Keep your feet planted.\"],\"img\":\"3681.webp\",\"gif\":\"3681.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with dumbbells pressed together to keep constant tension in the chest.\"},{\"id\":\"4757\",\"n\":\"dumbbell staggered stance romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"forearms\",\"core\"],\"st\":[\"Stand with one foot a half step ahead and hold dumbbells in front of you.\",\"Keep most of your weight on the front leg.\",\"Hinge at the hips, sliding the dumbbells down your legs.\",\"Stop when you feel a stretch in the hamstring, back flat.\",\"Drive your hips forward to stand, then switch feet.\"],\"img\":\"4757.webp\",\"gif\":\"4757.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift with one foot slightly behind the other. It loads the hamstrings and glutes and improves balance.\"},{\"id\":\"4065\",\"n\":\"dumbbell standing alternate arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand holding dumbbells at shoulder height with palms facing you.\",\"Brace your core.\",\"Press one dumbbell overhead while rotating your palm forward.\",\"Lower while rotating back.\",\"Alternate arms.\"],\"img\":\"4065.webp\",\"gif\":\"4065.mp4\",\"cat\":\"strength\",\"desc\":\"Rotating press with dumbbells, done one arm at a time while standing. It works all parts of the shoulder.\"},{\"id\":\"6265\",\"n\":\"dumbbell standing alternate reverse curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"wrist extensors\"],\"st\":[\"Stand holding dumbbells with an overhand grip.\",\"Keep your elbows at your sides.\",\"Curl one dumbbell up.\",\"Lower slowly.\",\"Alternate arms.\",\"Keep your wrists straight.\"],\"img\":\"6265.webp\",\"gif\":\"6265.mp4\",\"cat\":\"strength\",\"desc\":\"An alternating standing curl with an overhand grip. It builds the forearms.\"},{\"id\":\"1230\",\"n\":\"dumbbell standing alternate vertical front raises\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Stand holding dumbbells at your thighs with palms facing in.\",\"Raise one dumbbell straight up to shoulder height.\",\"Pause, then lower it slowly.\",\"Repeat with the other arm and keep alternating.\",\"Avoid swinging your body.\"],\"img\":\"1230.webp\",\"gif\":\"1230.mp4\",\"cat\":\"strength\",\"desc\":\"Raising one dumbbell at a time in front of you with a neutral grip. It works the front shoulders.\"},{\"id\":\"10040\",\"n\":\"dumbbell standing alternating cross raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"chest\",\"obliques\"],\"st\":[\"Stand tall with a dumbbell in each hand at your sides.\",\"Raise one arm up and across your body toward the opposite shoulder, elbow slightly bent.\",\"Pause at the top.\",\"Lower with control.\",\"Repeat with the other arm, alternating.\",\"Keep your torso steady and avoid swinging.\"],\"img\":\"10040.webp\",\"gif\":\"10040.mp4\",\"cat\":\"strength\",\"desc\":\"A raise where each dumbbell sweeps across the front of your body. It trains the front delts and upper chest.\"},{\"id\":\"6267\",\"n\":\"dumbbell standing arms rotate\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand holding light dumbbells at your sides.\",\"Bend your elbows to 90 degrees.\",\"Rotate your palms up.\",\"Rotate your palms down.\",\"Repeat smoothly.\",\"Keep your elbows pinned.\"],\"img\":\"6267.webp\",\"gif\":\"6267.mp4\",\"cat\":\"strength\",\"desc\":\"A standing rotation of the forearms holding dumbbells. It builds forearm strength.\"},{\"id\":\"4108\",\"n\":\"dumbbell standing arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\"],\"st\":[\"Stand holding dumbbells at chest height with palms facing you.\",\"Press up while rotating your palms to face forward.\",\"Fully extend your arms overhead.\",\"Lower while rotating back to palms facing you.\",\"Keep your core tight and avoid arching.\"],\"img\":\"4108.webp\",\"gif\":\"4108.mp4\",\"cat\":\"strength\",\"desc\":\"The rotating shoulder press popularized by Arnold, hitting all heads of the delts.\"},{\"id\":\"6366\",\"n\":\"dumbbell standing back wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand with a dumbbell in each hand behind your back, palms facing back.\",\"Keep your arms still and your chest tall.\",\"Curl your wrists upward.\",\"Squeeze at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6366.webp\",\"gif\":\"6366.mp4\",\"cat\":\"strength\",\"desc\":\"Holding dumbbells behind your body, you curl your wrists to train your forearms and grip.\"},{\"id\":\"5631\",\"n\":\"dumbbell standing bent arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand holding dumbbells with elbows bent about 90 degrees.\",\"Raise your elbows out to the sides to shoulder height.\",\"Pause briefly.\",\"Lower slowly.\",\"Avoid swinging.\"],\"img\":\"5631.webp\",\"gif\":\"5631.mp4\",\"cat\":\"strength\",\"desc\":\"Lateral raise with elbows bent to isolate the side delts.\",\"fv\":\"2316\"},{\"id\":\"4574\",\"n\":\"dumbbell standing biceps curl to shoulder press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"forearms\",\"core\"],\"st\":[\"Stand holding dumbbells at your sides, palms forward.\",\"Curl both dumbbells up to your shoulders.\",\"Rotate your palms to face forward at the top of the curl.\",\"Press the dumbbells overhead until your arms are straight.\",\"Lower them back to your shoulders, then down to your sides.\",\"Keep your core tight and avoid swinging.\"],\"img\":\"4574.webp\",\"gif\":\"4574.mp4\",\"cat\":\"strength\",\"desc\":\"A compound arm move that links a biceps curl into an overhead press.\"},{\"id\":\"10094\",\"n\":\"dumbbell standing cross clean\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"glutes\",\"hamstrings\",\"core\",\"forearms\"],\"st\":[\"Stand with a dumbbell hanging in front of your thigh, hips hinged slightly.\",\"Drive your hips forward and shrug.\",\"Pull the dumbbell up and across your body.\",\"Catch it at the opposite shoulder.\",\"Lower it back to the hang.\",\"Finish reps, then switch arms.\"],\"img\":\"10094.webp\",\"gif\":\"10094.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm clean where the dumbbell travels across your body to the opposite shoulder.\"},{\"id\":\"5449\",\"n\":\"dumbbell standing drag curl v. 2\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"rear deltoids\"],\"st\":[\"Stand tall with a dumbbell in each hand, palms forward.\",\"Curl the weights up, keeping them close to your torso.\",\"Let your elbows travel slightly back.\",\"Squeeze the biceps at the top.\",\"Lower slowly along the same path.\",\"Keep your torso still.\"],\"img\":\"5449.webp\",\"gif\":\"5449.mp4\",\"cat\":\"strength\",\"desc\":\"Curl the dumbbells while dragging them up along your body, with elbows moving back. Keeps tension on the biceps.\"},{\"id\":\"6141\",\"n\":\"dumbbell standing driver\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\"],\"st\":[\"Stand holding a dumbbell at your shoulder.\",\"Bend your knees slightly.\",\"Drive up through your legs and press the dumbbell overhead.\",\"Lock out without leaning back.\",\"Lower the weight to your shoulder.\",\"Switch arms after your set.\"],\"img\":\"6141.webp\",\"gif\":\"6141.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell press that uses a drive from the legs and trunk. It builds shoulder strength and power.\"},{\"id\":\"6221\",\"n\":\"dumbbell standing french press\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand holding one dumbbell overhead with both hands.\",\"Keep your elbows pointing forward.\",\"Lower the dumbbell behind your head.\",\"Extend your arms back up.\",\"Keep your core braced.\",\"Avoid arching your back.\"],\"img\":\"6221.webp\",\"gif\":\"6221.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead extension with a dumbbell held in both hands. It targets the triceps.\"},{\"id\":\"7449\",\"n\":\"dumbbell standing front and lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand holding dumbbells at your sides.\",\"Raise both arms to the front up to shoulder height.\",\"Lower them back down.\",\"Raise them out to your sides to shoulder height.\",\"Lower with control and repeat.\"],\"img\":\"7449.webp\",\"gif\":\"7449.mp4\",\"cat\":\"strength\",\"desc\":\"Combined raise that hits the front and side delts in one rep.\"},{\"id\":\"10183\",\"n\":\"dumbbell standing front raise twist\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Stand with feet shoulder width apart, holding a dumbbell in both hands at thigh level.\",\"Raise the dumbbell in front of you to chest height.\",\"Rotate your torso to one side, turning from the ribs while your hips face forward.\",\"Rotate back to the center and lower the dumbbell with control.\",\"Alternate sides each rep and keep the weight light.\"],\"img\":\"10183.webp\",\"gif\":\"10183.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise combined with a torso twist, working the shoulders and the obliques together.\"},{\"id\":\"7054\",\"n\":\"dumbbell standing hands torsion\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand holding a dumbbell by its handle in front of you.\",\"Keep your elbows bent and close to your sides.\",\"Rotate your forearms and wrists inward and outward.\",\"Move slowly through the full range.\",\"Keep your shoulders relaxed.\"],\"img\":\"7054.webp\",\"gif\":\"7054.mp4\",\"cat\":\"strength\",\"desc\":\"A standing twisting move holding a dumbbell that works the forearm rotators. It builds wrist and grip strength.\"},{\"id\":\"4888\",\"n\":\"dumbbell standing high windmill\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"hamstrings\",\"lower back\"],\"st\":[\"Stand with feet wide and press a dumbbell overhead with one arm.\",\"Turn your feet slightly away from the weighted side.\",\"Push your hips toward the weighted side and hinge forward.\",\"Slide your free hand down your leg while your eyes stay on the dumbbell.\",\"Reverse the movement to stand tall again.\",\"Keep the arm locked and stacked over your shoulder, then switch sides.\"],\"img\":\"4888.webp\",\"gif\":\"4888.mp4\",\"cat\":\"strength\",\"desc\":\"A windmill with the weight held high overhead while you hinge sideways. It trains the obliques and shoulder stability.\"},{\"id\":\"1228\",\"n\":\"dumbbell standing inner biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand tall with a dumbbell in each hand, elbows slightly out from your sides.\",\"Curl the weights toward your shoulders.\",\"Squeeze at the top.\",\"Lower them slowly to the start.\",\"Keep your upper arms still.\"],\"img\":\"1228.webp\",\"gif\":\"1228.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell curl with the elbows turned slightly out to emphasise the inner head of the biceps.\"},{\"id\":\"2234\",\"n\":\"dumbbell standing lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand tall with a dumbbell in each hand at your sides, palms facing in.\",\"Keep a slight bend in your elbows and brace your core.\",\"Raise both arms out to the sides until they reach shoulder height.\",\"Lead with your elbows and avoid shrugging.\",\"Pause briefly at the top.\",\"Lower slowly to the start and repeat.\"],\"img\":\"2234.webp\",\"gif\":\"2234.mp4\",\"cat\":\"strength\",\"desc\":\"Raising dumbbells out to your sides to build the middle part of the shoulders.\"},{\"id\":\"7056\",\"n\":\"dumbbell standing reverse curl rotate\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"wrist extensors\"],\"st\":[\"Stand holding dumbbells with an overhand grip at your thighs.\",\"Curl the weights up while keeping your elbows tucked.\",\"At the top, rotate your forearms so the palms turn up.\",\"Rotate back and lower slowly.\",\"Keep your wrists strong and avoid swinging.\"],\"img\":\"7056.webp\",\"gif\":\"7056.mp4\",\"cat\":\"strength\",\"desc\":\"A standing reverse curl that ends with a forearm rotation. It targets the forearms and brachialis.\"},{\"id\":\"7234\",\"n\":\"dumbbell standing scapular external rotation\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"rhomboids\"],\"st\":[\"Stand tall holding a light dumbbell with your elbow bent at 90 degrees and tucked at your side.\",\"Keep your upper arm still and your shoulder blade pulled back and down.\",\"Rotate your forearm outward as far as you comfortably can.\",\"Pause briefly, then slowly return to the start.\",\"Finish all reps, then switch arms.\"],\"img\":\"7234.webp\",\"gif\":\"7234.mp4\",\"cat\":\"strength\",\"desc\":\"Light dumbbell rotation that strengthens the small muscles behind the shoulder and between the shoulder blades.\"},{\"id\":\"7235\",\"n\":\"dumbbell standing scapular external rotation (front pov)\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rhomboids\",\"trapezius\"],\"st\":[\"Stand tall holding a light dumbbell with your elbow tucked and bent to 90 degrees.\",\"Keep your upper arm against your side.\",\"Rotate your forearm outward, away from your body.\",\"Squeeze your shoulder blade back.\",\"Return slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"7235.webp\",\"gif\":\"7235.mp4\",\"cat\":\"strength\",\"desc\":\"A light dumbbell rotation that trains the rear shoulder and rotator cuff.\"},{\"id\":\"4833\",\"n\":\"dumbbell standing single arm arnold press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Stand tall holding a dumbbell at shoulder height, palm facing you.\",\"Brace your core and keep your other arm at your side.\",\"Press the dumbbell up while rotating your palm to face forward.\",\"Fully extend your arm overhead.\",\"Lower while rotating back, then switch sides.\"],\"img\":\"4833.webp\",\"gif\":\"4833.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm Arnold press with a rotating grip. It works all heads of the shoulder while challenging core stability.\"},{\"id\":\"6757\",\"n\":\"dumbbell standing single arm biceps curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand tall holding a dumbbell at your side, palm facing forward.\",\"Keep your elbow tucked at your side.\",\"Curl the weight up toward your shoulder.\",\"Squeeze your biceps at the top.\",\"Lower slowly until the arm is straight.\",\"Finish the reps, then switch arms.\"],\"img\":\"6757.webp\",\"gif\":\"6757.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm standing curl. It builds the biceps and lets you focus on each arm separately.\"},{\"id\":\"5458\",\"n\":\"dumbbell standing single arm cross raise\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Stand holding a dumbbell by your opposite hip.\",\"Keep a slight bend in your elbow.\",\"Raise the dumbbell diagonally up and across to head height.\",\"Squeeze your chest at the top.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"5458.webp\",\"gif\":\"5458.mp4\",\"cat\":\"strength\",\"desc\":\"Raise one dumbbell diagonally across your body. Works the chest and front shoulder.\"},{\"id\":\"1178\",\"n\":\"dumbbell standing single leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Hold a dumbbell in one hand and stand on one foot on a step.\",\"Hold a wall or rail with your other hand for balance.\",\"Lower your heel to a full stretch.\",\"Press up onto your toes as high as possible.\",\"Complete your reps, then switch legs.\"],\"img\":\"1178.webp\",\"gif\":\"1178.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf raise holding a dumbbell for a challenging calf workout.\"},{\"id\":\"3713\",\"n\":\"dumbbell standing single leg calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Hold a dumbbell in one hand and stand on the opposite leg, lightly touching a wall for balance.\",\"Rise up onto the ball of your foot as high as you can.\",\"Pause at the top.\",\"Lower your heel slowly below the start if possible.\",\"Finish your reps, then switch legs.\"],\"img\":\"3713.webp\",\"gif\":\"3713.mp4\",\"cat\":\"strength\",\"desc\":\"A one-legged calf raise holding a dumbbell for extra load. It builds calf strength and ankle balance.\"},{\"id\":\"4017\",\"n\":\"dumbbell standing single spider curl\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand and hinge forward, bracing against a support.\",\"Let one arm hang with a dumbbell.\",\"Curl up.\",\"Squeeze.\",\"Lower and switch arms.\"],\"img\":\"4017.webp\",\"gif\":\"4017.mp4\",\"cat\":\"strength\",\"desc\":\"A standing one-arm spider curl bent forward. It isolates the biceps.\"},{\"id\":\"6964\",\"n\":\"dumbbell standing t spine press\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\",\"trapezius\"],\"st\":[\"Stand with your feet hip-width apart and the dumbbells at shoulder height.\",\"Brace your abs and lift your chest tall.\",\"Press the dumbbells overhead while gently extending your upper back.\",\"Keep your ribs down and avoid arching your lower back.\",\"Lower to your shoulders with control.\",\"Repeat for the planned reps.\"],\"img\":\"6964.webp\",\"gif\":\"6964.mp4\",\"cat\":\"strength\",\"desc\":\"A standing dumbbell press that adds upper back extension, training shoulder strength and posture together.\"},{\"id\":\"4901\",\"n\":\"dumbbell standing windmill\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"hamstrings\",\"lower back\"],\"st\":[\"Press a dumbbell overhead with one hand and stand with feet wide.\",\"Turn your toes slightly away from the weight.\",\"Push your hips out and hinge sideways.\",\"Slide your free hand down your leg toward the floor.\",\"Reverse the motion and stand tall.\",\"Keep your eyes on the weight, then switch sides.\"],\"img\":\"4901.webp\",\"gif\":\"4901.mp4\",\"cat\":\"strength\",\"desc\":\"A standing windmill with a dumbbell held overhead as you hinge to the side. It trains the obliques, hips and shoulder stability.\"},{\"id\":\"6359\",\"n\":\"dumbbell standing wrist curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand with a dumbbell in each hand, palms facing forward.\",\"Keep your arms still at your sides.\",\"Curl your wrists up, bringing the dumbbells toward your forearms.\",\"Squeeze at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6359.webp\",\"gif\":\"6359.mp4\",\"cat\":\"strength\",\"desc\":\"A standing wrist curl with dumbbells that builds forearm strength and grip.\"},{\"id\":\"6362\",\"n\":\"dumbbell standing wrist reverse curl\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand with a dumbbell in each hand, palms facing down.\",\"Keep your upper arms still.\",\"Lift the backs of your hands up by extending your wrists.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6362.webp\",\"gif\":\"6362.mp4\",\"cat\":\"strength\",\"desc\":\"Standing reverse wrist curls with dumbbells to strengthen the extensor muscles on top of your forearms.\"},{\"id\":\"4290\",\"n\":\"dumbbell static lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand in a long split stance, rear heel lifted.\",\"Keep your torso upright and core braced.\",\"Bend both knees and lower until the back knee nearly touches the floor.\",\"Press through the front heel to stand back up without moving your feet.\",\"Finish your reps, then switch legs.\"],\"img\":\"4290.webp\",\"gif\":\"4290.mp4\",\"cat\":\"strength\",\"desc\":\"A split-stance lunge done in place with dumbbells in hand. It builds strength in the front thigh and glutes without any stepping.\"},{\"id\":\"4758\",\"n\":\"dumbbell step back lunge and row\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lats\",\"upper back\",\"biceps\"],\"st\":[\"Stand holding dumbbells at your sides.\",\"Step one leg back and lower into a lunge.\",\"Hinge your torso slightly forward with a flat back.\",\"Row both dumbbells to your ribs.\",\"Lower them, push through the front foot to stand, and switch legs.\"],\"img\":\"4758.webp\",\"gif\":\"4758.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge followed by a row. It trains the legs and the back in one flowing movement.\"},{\"id\":\"9612\",\"n\":\"dumbbell step over box\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"grip muscles\"],\"st\":[\"Hold a dumbbell in each hand and stand beside a box.\",\"Step one foot up onto the box.\",\"Press through it and bring your other foot up.\",\"Step down to the far side one foot at a time.\",\"Repeat, alternating the leading leg.\"],\"img\":\"9612.webp\",\"gif\":\"9612.mp4\",\"cat\":\"strength\",\"desc\":\"Stepping across a box with dumbbells in your hands. It builds single-leg strength and balance.\"},{\"id\":\"2795\",\"n\":\"dumbbell step up lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand facing a sturdy box or step.\",\"Step one foot onto the box and drive up until you stand on it.\",\"Step the same foot back down behind you into a lunge.\",\"Push back up to the start, keeping your torso upright.\",\"Finish all reps on one leg, then switch sides.\"],\"img\":\"2795.webp\",\"gif\":\"2795.mp4\",\"cat\":\"strength\",\"desc\":\"A step up that flows into a lunge while holding dumbbells. Builds single leg strength and balance.\",\"fv\":\"2796\"},{\"id\":\"4986\",\"n\":\"dumbbell step up v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Hold a dumbbell in each hand and stand facing a sturdy bench.\",\"Place one foot fully on the bench.\",\"Drive through that heel to stand up tall on the bench.\",\"Lower your trailing foot back down under control.\",\"Finish your reps, then switch legs.\"],\"img\":\"4986.webp\",\"gif\":\"4986.mp4\",\"cat\":\"strength\",\"desc\":\"Step up onto a bench or box holding dumbbells. It trains your legs and glutes one side at a time.\"},{\"id\":\"4565\",\"n\":\"dumbbell step up with knee raise\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"core\",\"calves\"],\"st\":[\"Hold dumbbells at your sides and stand facing a bench or box.\",\"Place one foot fully on the box.\",\"Push through that heel and step up.\",\"Lift the other knee toward your chest at the top.\",\"Step down with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"4565.webp\",\"gif\":\"4565.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded step-up that finishes with a knee drive, working the legs and balance.\"},{\"id\":\"1556\",\"n\":\"dumbbell stiff leg deadlift on bench\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand on a sturdy bench holding a dumbbell in each hand in front of your thighs.\",\"Keep your knees nearly straight and push your hips back.\",\"Lower the dumbbells down your legs and below the bench level with a flat back.\",\"Pause when you feel a deep hamstring stretch.\",\"Squeeze your glutes to return to standing.\"],\"img\":\"1556.webp\",\"gif\":\"1556.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-legged deadlift with dumbbells while standing on a bench for extra depth. It targets the hamstrings and lower back.\"},{\"id\":\"3340\",\"n\":\"dumbbell stiff leg deadlift v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet hip width apart holding dumbbells in front of your thighs.\",\"Keep your knees slightly bent and back flat.\",\"Push your hips back and slide the dumbbells down your legs.\",\"Stop when you feel a hamstring stretch.\",\"Drive your hips forward to stand tall.\"],\"img\":\"3340.webp\",\"gif\":\"3340.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with nearly straight legs holding dumbbells. It stretches and strengthens the hamstrings and glutes.\",\"fv\":\"3894\"},{\"id\":\"3894\",\"n\":\"dumbbell stiff leg deadlift v. 3\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand holding a dumbbell in each hand in front of your thighs.\",\"Keep your knees almost straight.\",\"Hinge at the hips and slide the weights down your legs.\",\"Stop when you feel a stretch in the hamstrings.\",\"Drive your hips forward to stand, keeping your back flat.\"],\"img\":\"3894.webp\",\"gif\":\"3894.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with nearly straight legs that stretches and strengthens the hamstrings.\",\"mv\":\"3340\"},{\"id\":\"10949\",\"n\":\"dumbbell straight arm bicep swing\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Stand holding a dumbbell in each hand, palms forward.\",\"Keep your arms nearly straight.\",\"Swing the dumbbells forward and up in a controlled arc.\",\"Lower them back down.\",\"Keep your torso still and avoid momentum.\"],\"img\":\"10949.webp\",\"gif\":\"10949.mp4\",\"cat\":\"strength\",\"desc\":\"Swinging the dumbbells with straight arms to load the biceps. A shoulder and arm builder.\"},{\"id\":\"4248\",\"n\":\"dumbbell straight arm crunch\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"shoulders\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Hold a dumbbell with both hands, arms straight up.\",\"Curl your shoulders off the floor, reaching toward the ceiling.\",\"Squeeze your abs at the top.\",\"Lower slowly.\",\"Keep your arms straight and your neck relaxed.\"],\"img\":\"4248.webp\",\"gif\":\"4248.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch holding a dumbbell straight above your chest. It loads the abs while your arms stay locked.\"},{\"id\":\"6144\",\"n\":\"dumbbell straight arm crunch v. 2\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Lie on your back with your knees bent.\",\"Hold a dumbbell with straight arms over your chest.\",\"Curl your upper back off the floor, reaching up.\",\"Pause at the top.\",\"Lower slowly.\",\"Keep your lower back on the floor.\"],\"img\":\"6144.webp\",\"gif\":\"6144.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with your arms straight overhead holding a dumbbell. The load increases the demand on the abs.\"},{\"id\":\"3176\",\"n\":\"dumbbell straight arm pullover (knees at 90 degrees)\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on a bench with your feet up and knees at 90 degrees.\",\"Hold one dumbbell with both hands above your chest.\",\"Keep your arms nearly straight.\",\"Lower the dumbbell in an arc behind your head.\",\"Pull it back over your chest.\",\"Keep your ribs down and your back flat.\"],\"img\":\"3176.webp\",\"gif\":\"3176.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pullover with knees bent to 90 degrees on a bench. It works the chest and lats and keeps the trunk braced.\",\"nd\":[\"bench\"]},{\"id\":\"3188\",\"n\":\"dumbbell straight arm pullover (with hanging band technique)\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Hang a weight from the dumbbell with a band.\",\"Lie on a bench and hold it above your chest with straight arms.\",\"Lower it in an arc behind your head.\",\"Pull it back over your chest slowly.\",\"Keep your ribs down and your core tight.\",\"Use a light load to stay controlled.\"],\"img\":\"3188.webp\",\"gif\":\"3188.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm pullover with weights hung from the dumbbell by a band. The swing makes your shoulders and trunk work harder.\",\"nd\":[\"bench\"]},{\"id\":\"7113\",\"n\":\"dumbbell straight arm pullover v. 2\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on a bench holding one dumbbell above your chest with straight arms.\",\"Keep a slight softness in your elbows and brace your core.\",\"Lower the weight in an arc back over your head until you feel a stretch.\",\"Keep your ribs down and your hips on the bench.\",\"Pull the dumbbell back over your chest.\",\"Repeat with a smooth tempo.\"],\"img\":\"7113.webp\",\"gif\":\"7113.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover variation with straight arms that stretches and works the chest and lats through a long arc.\",\"nd\":[\"bench\"]},{\"id\":\"4251\",\"n\":\"dumbbell straight arm twisting sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent, holding a dumbbell over your chest.\",\"Sit up while keeping your arms straight.\",\"Twist toward one side at the top.\",\"Return to centre and lower slowly.\",\"Alternate sides on each rep.\",\"Keep your feet down and movement controlled.\"],\"img\":\"4251.webp\",\"gif\":\"4251.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up with a rotation while holding a dumbbell on straight arms. It works the abs and obliques.\"},{\"id\":\"4249\",\"n\":\"dumbbell straight leg russian twist\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Sit with your legs straight out and heels just off the floor.\",\"Lean back slightly with a flat back.\",\"Hold a dumbbell in both hands in front of your chest.\",\"Rotate your torso to one side, then the other.\",\"Keep your legs steady.\",\"Move smoothly and breathe.\"],\"img\":\"4249.webp\",\"gif\":\"4249.mp4\",\"cat\":\"strength\",\"desc\":\"A Russian twist with your legs straight and a dumbbell in hand. The longer lever makes it a tough oblique exercise.\"},{\"id\":\"4293\",\"n\":\"dumbbell straight legs deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet hip-width apart, holding a dumbbell in each hand in front of your thighs.\",\"Keep your legs almost straight with a soft knee and a flat back.\",\"Push your hips back and lower the weights along your legs until you feel a hamstring stretch.\",\"Drive your hips forward to stand tall and squeeze your glutes.\"],\"img\":\"4293.webp\",\"gif\":\"4293.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with nearly straight legs and dumbbells. It stretches and strengthens the hamstrings, glutes and lower back.\"},{\"id\":\"2910\",\"n\":\"dumbbell suitcase carry\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"forearms\",\"grip muscles\",\"trapezius\"],\"st\":[\"Pick up one dumbbell with a tall, braced posture and hold it at your side.\",\"Keep your shoulders level and your ribs stacked over your hips.\",\"Walk with steady steps without leaning toward the weight.\",\"Cover the set distance, then put the weight down safely.\",\"Switch hands and repeat.\"],\"img\":\"2910.webp\",\"gif\":\"2910.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying one heavy dumbbell at your side like a suitcase. It challenges your grip and forces your trunk to resist leaning.\"},{\"id\":\"8192\",\"n\":\"dumbbell sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"lower back\"],\"st\":[\"Stand with a wide stance, toes turned out, and a dumbbell between your feet.\",\"Hinge down and grab it with both hands.\",\"Keep your chest up and back flat.\",\"Drive through your feet to stand tall.\",\"Lower the weight under control.\"],\"img\":\"8192.webp\",\"gif\":\"8192.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a wide stance holding a dumbbell between your legs. It works the glutes, inner thighs and back.\",\"fv\":\"4759\"},{\"id\":\"2807\",\"n\":\"dumbbell sumo pull through v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hamstrings\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand with feet wide and toes turned out, holding one dumbbell with both hands.\",\"Hinge at the hips and swing the dumbbell back between your legs.\",\"Keep your back flat and chest up.\",\"Drive your hips forward and stand tall, swinging the dumbbell to hip height.\",\"Squeeze your glutes at the top.\"],\"img\":\"2807.webp\",\"gif\":\"2807.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance hinge where a dumbbell swings between the legs. Trains glutes, inner thighs and hamstrings.\",\"fv\":\"2808\"},{\"id\":\"5121\",\"n\":\"dumbbell sumo squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Stand with feet wide and toes turned out, holding a dumbbell with both hands in front of you.\",\"Keep your chest tall.\",\"Sit down until your thighs are about parallel.\",\"Push your knees out over your toes.\",\"Drive through your heels to stand.\"],\"img\":\"5121.webp\",\"gif\":\"5121.mp4\",\"cat\":\"strength\",\"desc\":\"Squat with a wide stance holding a dumbbell between your legs. It hits the glutes and inner thighs.\",\"fv\":\"2322\"},{\"id\":\"0435\",\"n\":\"dumbbell sumo squat (back on stability ball wall)\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Place a stability ball against a wall and lean your lower back on it.\",\"Hold a dumbbell with both hands in front of you and set your feet wide with toes turned out.\",\"Squat down as the ball rolls up your back.\",\"Lower until your thighs are about parallel.\",\"Push through your heels to stand.\",\"Keep your knees tracking over your toes.\"],\"img\":\"0435.webp\",\"gif\":\"0435.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance sumo squat holding a dumbbell with a stability ball between your back and the wall. The ball supports your back and keeps your posture upright.\"},{\"id\":\"2431\",\"n\":\"dumbbell sumo squat off benches\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Place a bench under each foot with a wide stance.\",\"Hold a dumbbell in front of you with both hands.\",\"Sit your hips down between the benches.\",\"Lower until you feel a deep stretch in your hips.\",\"Push through your heels to stand.\",\"Keep your chest up throughout.\"],\"img\":\"2431.webp\",\"gif\":\"2431.mp4\",\"cat\":\"strength\",\"desc\":\"A wide squat with feet on benches that extends the range of motion for the glutes and inner thighs.\"},{\"id\":\"3454\",\"n\":\"dumbbell superman\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rear deltoids\"],\"st\":[\"Lie face down holding light dumbbells with arms extended.\",\"Lift your chest, arms and legs.\",\"Squeeze your glutes.\",\"Hold for a moment.\",\"Lower with control.\",\"Keep your neck neutral.\"],\"img\":\"3454.webp\",\"gif\":\"3454.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded superman hold with dumbbells for the lower back and glutes.\",\"fv\":\"3455\"},{\"id\":\"2804\",\"n\":\"dumbbell supported squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a dumbbell in one hand and rest the other hand on a stable support.\",\"Stand with feet shoulder width apart and toes slightly out.\",\"Sit your hips back and down until your thighs are about parallel.\",\"Drive through your heels to stand, keeping your chest up.\",\"Switch the dumbbell hand halfway through if needed.\"],\"img\":\"2804.webp\",\"gif\":\"2804.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell squat with a hand on a support for balance. Lets you focus on a deep, steady squat pattern.\",\"fv\":\"2803\"},{\"id\":\"3452\",\"n\":\"dumbbell svend press\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand holding a dumbbell upright between your palms.\",\"Hold it at chest level.\",\"Squeeze your palms together.\",\"Press the weight straight out.\",\"Return to your chest.\",\"Keep the squeeze all the time.\"],\"img\":\"3452.webp\",\"gif\":\"3452.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-style squeeze press using a dumbbell held between your palms.\",\"fv\":\"3453\"},{\"id\":\"3368\",\"n\":\"dumbbell swing\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet wider than hips and hold one dumbbell in both hands.\",\"Hinge at the hips and swing the dumbbell between your legs.\",\"Snap your hips forward to swing it to chest height.\",\"Let your arms stay relaxed.\",\"Guide it back down and hinge into the next rep.\"],\"img\":\"3368.webp\",\"gif\":\"3368.mp4\",\"cat\":\"strength\",\"desc\":\"A hip driven swing using a dumbbell, building power in your glutes and hamstrings.\",\"fv\":\"3445\"},{\"id\":\"2968\",\"n\":\"dumbbell thruster\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\",\"hamstrings\"],\"st\":[\"Hold dumbbells at your shoulders and stand with your feet shoulder-width apart.\",\"Squat down with your chest up.\",\"Drive up through your heels and press the dumbbells overhead in one motion.\",\"Lock out your arms at the top.\",\"Lower the weights to your shoulders and go straight into the next rep.\"],\"img\":\"2968.webp\",\"gif\":\"2968.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat that flows into an overhead press. It is a hard whole-body move that raises your heart rate.\"},{\"id\":\"2969\",\"n\":\"dumbbell thruster v. 2\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\"],\"st\":[\"Hold a dumbbell in each hand at your shoulders.\",\"Squat down with your chest tall and knees tracking over your toes.\",\"Drive up through your heels as you stand.\",\"Use that momentum to press the dumbbells overhead.\",\"Lower them to your shoulders and go into the next squat.\"],\"img\":\"2969.webp\",\"gif\":\"2969.mp4\",\"cat\":\"strength\",\"desc\":\"A squat into overhead press with dumbbells that works the legs and shoulders in one flow.\"},{\"id\":\"4342\",\"n\":\"dumbbell twisted fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Lie on a bench with a dumbbell in each hand above your chest, palms facing in.\",\"Open your arms wide in an arc with elbows slightly bent.\",\"Rotate your wrists as you lower until you feel a chest stretch.\",\"Bring the dumbbells back together, twisting them to finish with palms inward.\",\"Control the weight on the way down.\"],\"img\":\"4342.webp\",\"gif\":\"4342.mp4\",\"cat\":\"strength\",\"desc\":\"A dumbbell fly where you rotate your wrists through the movement for a stronger chest squeeze.\",\"nd\":[\"bench\"]},{\"id\":\"1681\",\"n\":\"dumbbell two arm seated hammer curl on exercise ball\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"core\"],\"st\":[\"Sit upright on a stability ball with a dumbbell in each hand, palms facing in.\",\"Plant your feet wide for balance and keep your elbows by your sides.\",\"Curl both dumbbells up toward your shoulders without turning your wrists.\",\"Squeeze at the top, then lower slowly to full arm extension.\",\"Keep your chest tall and avoid swinging your torso.\"],\"img\":\"1681.webp\",\"gif\":\"1681.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a stability ball, you curl two dumbbells with palms facing each other. It hits the biceps and brachialis while the ball asks your core to stay steady.\"},{\"id\":\"11014\",\"n\":\"dumbbell underhand front raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"biceps\",\"core\"],\"st\":[\"Stand holding a dumbbell in each hand, palms facing forward.\",\"Keep your elbows slightly soft.\",\"Raise your arms in front of you to shoulder height.\",\"Pause at the top.\",\"Lower slowly and avoid leaning back.\"],\"img\":\"11014.webp\",\"gif\":\"11014.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with palms facing up. It targets the front of the shoulders.\"},{\"id\":\"8222\",\"n\":\"dumbbell underhand renegade row\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"core\",\"shoulders\"],\"st\":[\"Set up in a plank with your hands on dumbbells, palms facing forward.\",\"Widen your feet for balance.\",\"Row one dumbbell up to your ribs.\",\"Keep your hips level.\",\"Lower and alternate arms.\"],\"img\":\"8222.webp\",\"gif\":\"8222.mp4\",\"cat\":\"strength\",\"desc\":\"A renegade row with an underhand grip on the dumbbells. It builds core stability and works the lats and biceps.\"},{\"id\":\"6123\",\"n\":\"dumbbell unilateral scapula raise\",\"bp\":\"back\",\"eq\":\"dumbbell\",\"tg\":\"traps\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"upper back\",\"shoulders\"],\"st\":[\"Stand holding a dumbbell in one hand at your side.\",\"Keep your arm straight and your chest up.\",\"Lift your shoulder blade straight up toward your ear.\",\"Pause briefly at the top.\",\"Lower with control.\",\"Finish your reps, then switch arms.\"],\"img\":\"6123.webp\",\"gif\":\"6123.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm shrug-style movement that trains the muscles that lift and control the shoulder blade. It helps shoulder stability.\"},{\"id\":\"3336\",\"n\":\"dumbbell v up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"obliques\"],\"st\":[\"Lie flat with legs straight and a dumbbell held in both hands overhead.\",\"Brace your core.\",\"Lift your arms and legs together, forming a V shape.\",\"Touch the dumbbell near your shins.\",\"Lower back down slowly without dropping your legs.\"],\"img\":\"3336.webp\",\"gif\":\"3336.mp4\",\"cat\":\"strength\",\"desc\":\"A v up while holding a dumbbell, raising your arms and legs together to challenge the abs.\",\"fv\":\"3446\"},{\"id\":\"4250\",\"n\":\"dumbbell v up v. 2\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your legs straight, holding a dumbbell overhead.\",\"Brace your core.\",\"Lift your legs and torso together, reaching the dumbbell toward your feet.\",\"Form a V at the top.\",\"Lower slowly with control.\",\"Keep your lower back pressed down.\"],\"img\":\"4250.webp\",\"gif\":\"4250.mp4\",\"cat\":\"strength\",\"desc\":\"A V-up holding a dumbbell, raising your torso and legs together. It trains the whole abdominal wall.\"},{\"id\":\"5698\",\"n\":\"dumbbell walking calf raise\",\"bp\":\"lower legs\",\"eq\":\"dumbbell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Hold a dumbbell in each hand at your sides.\",\"Stand tall and rise onto the balls of your feet.\",\"Step forward and stay up on your toes.\",\"Alternate steps, keeping your heels lifted.\",\"Walk for the set distance, then lower your heels.\"],\"img\":\"5698.webp\",\"gif\":\"5698.mp4\",\"cat\":\"strength\",\"desc\":\"Walk forward while rising high onto your toes with each step, holding dumbbells. It builds calf strength and ankle stability.\"},{\"id\":\"4295\",\"n\":\"dumbbell walking lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand tall holding a dumbbell in each hand at your sides.\",\"Step forward with one leg and lower until both knees are about 90 degrees.\",\"Keep your torso upright and your front knee over your ankle.\",\"Push through the front foot and bring the back leg forward into the next step.\",\"Alternate legs for the desired number of steps.\"],\"img\":\"4295.webp\",\"gif\":\"4295.mp4\",\"cat\":\"strength\",\"desc\":\"Lunging forward step after step with a dumbbell in each hand. It builds leg and glute strength and balance.\"},{\"id\":\"1557\",\"n\":\"dumbbell walking lunges\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a dumbbell in each hand at your sides and stand tall.\",\"Step forward with one leg and lower until both knees are bent at about 90 degrees.\",\"Keep your torso upright and your front knee over your ankle.\",\"Push off your back foot and step through into a lunge with the other leg.\",\"Continue walking forward, alternating legs.\"],\"img\":\"1557.webp\",\"gif\":\"1557.mp4\",\"cat\":\"strength\",\"desc\":\"Lunges done on the move with dumbbells in your hands. A great move for leg strength, glutes and coordination.\"},{\"id\":\"1558\",\"n\":\"dumbbell wall squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Hold a dumbbell in each hand and lean your back against a wall.\",\"Walk your feet forward so your knees stay over your ankles when you squat.\",\"Slide down until your thighs are about parallel to the floor.\",\"Keep your back flat against the wall.\",\"Press through your heels to slide back up.\"],\"img\":\"1558.webp\",\"gif\":\"1558.mp4\",\"cat\":\"strength\",\"desc\":\"A wall squat made harder by holding dumbbells. It keeps your back supported while loading the legs.\"},{\"id\":\"10873\",\"n\":\"dumbbell weighted crunch (hands overhead)\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold one dumbbell upright with both hands and extend your arms overhead.\",\"Curl your shoulders off the floor, driving the dumbbell toward the ceiling.\",\"Pause and squeeze your abs.\",\"Lower slowly and repeat.\"],\"img\":\"10873.webp\",\"gif\":\"10873.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with a dumbbell held overhead. The extra load and long lever challenge your abs.\",\"fv\":\"10874\"},{\"id\":\"5108\",\"n\":\"dumbbell wood chop squat\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"quadriceps\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart, holding a dumbbell with both hands by one hip.\",\"Sit into a squat.\",\"Stand up and swing the dumbbell diagonally across to overhead on the other side.\",\"Rotate your torso and pivot your back foot as you go.\",\"Return and repeat, then switch sides.\"],\"img\":\"5108.webp\",\"gif\":\"5108.mp4\",\"cat\":\"strength\",\"desc\":\"Squat down and swing a dumbbell diagonally across your body. It trains legs, trunk rotation and shoulders in one movement.\"},{\"id\":\"10817\",\"n\":\"dumbbell wrist rotation\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit with your forearm resting on your thigh or a bench.\",\"Hold a light dumbbell with your palm facing up.\",\"Rotate your forearm so the palm turns down.\",\"Pause, then rotate back.\",\"Move slowly with control.\",\"Switch arms.\"],\"img\":\"10817.webp\",\"gif\":\"10817.mp4\",\"cat\":\"strength\",\"desc\":\"A forearm drill where you rotate a dumbbell through your palm. It builds wrist and forearm control.\"},{\"id\":\"10038\",\"n\":\"dumbbell wrist supination\",\"bp\":\"lower arms\",\"eq\":\"dumbbell\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"wrist flexors\"],\"st\":[\"Sit and rest your forearm on your thigh or a bench with the hand hanging free.\",\"Hold a light dumbbell with your palm facing down.\",\"Rotate your forearm so the palm turns up.\",\"Pause at the top.\",\"Rotate back slowly to the start.\",\"Finish your reps, then switch arms. Keep your elbow still.\"],\"img\":\"10038.webp\",\"gif\":\"10038.mp4\",\"cat\":\"strength\",\"desc\":\"Rotating a dumbbell so your palm turns up, working the muscles that twist the forearm.\"},{\"id\":\"5667\",\"n\":\"dumbbell z press\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\",\"trapezius\"],\"st\":[\"Sit on the floor with your legs extended in front of you.\",\"Hold the dumbbells at shoulder height, palms facing forward.\",\"Brace your core and sit tall without leaning back.\",\"Press the weights overhead until your arms are straight.\",\"Lower them back to your shoulders with control.\"],\"img\":\"5667.webp\",\"gif\":\"5667.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press done on the floor with legs straight out. With no back support, it trains the shoulders and demands a strong core.\"},{\"id\":\"6890\",\"n\":\"dumbbell z press v. 2\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\"],\"st\":[\"Sit on the floor with legs extended and dumbbells at your shoulders.\",\"Brace your core and keep your back tall.\",\"Press both dumbbells overhead until your arms are straight.\",\"Lower them to your shoulders under control.\",\"Avoid leaning back during the press.\"],\"img\":\"6890.webp\",\"gif\":\"6890.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press done seated on the floor with legs straight. The position removes leg drive and demands a strong core.\"},{\"id\":\"4887\",\"n\":\"dumbbells glute bridge v. 2\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Rest a dumbbell on each hip and hold them in place.\",\"Push through your heels and lift your hips.\",\"Squeeze your glutes at the top in a straight line from knees to shoulders.\",\"Lower your hips slowly.\",\"Keep your ribs down and avoid arching your back.\"],\"img\":\"4887.webp\",\"gif\":\"4887.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with dumbbells resting on your hips, a second variation. The added weight makes the glutes work harder.\"},{\"id\":\"2365\",\"n\":\"dumbbells straight arm pullover v. 2\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on a bench with your upper back supported and hold a dumbbell over your chest.\",\"Keep your arms nearly straight with a slight bend in the elbows.\",\"Lower the dumbbell in an arc behind your head until you feel a stretch.\",\"Keep your ribs down and your hips stable.\",\"Pull the dumbbell back over your chest using your lats.\",\"Repeat with control.\"],\"img\":\"2365.webp\",\"gif\":\"2365.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover with straight arms that stretches and works the lats and chest.\",\"nd\":[\"bench\"]},{\"id\":\"2323\",\"n\":\"dumbbells sumo squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Stand with your feet wider than your shoulders and toes pointing out.\",\"Hold one or two dumbbells with both hands in front of you.\",\"Sit your hips down and back, keeping your chest up.\",\"Lower until your thighs are about parallel to the floor.\",\"Push through your heels and squeeze your glutes to stand.\",\"Keep your knees in line with your toes.\"],\"img\":\"2323.webp\",\"gif\":\"2323.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance squat holding dumbbells that emphasises the glutes and inner thighs.\"},{\"id\":\"4555\",\"n\":\"dynamic 90 90 hip twist\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hip flexors\",\"obliques\"],\"st\":[\"Sit on the floor with both knees bent at 90 degrees, feet wide.\",\"Lean back a little and support yourself with your hands.\",\"Rotate both knees to one side so they drop toward the floor.\",\"Rotate smoothly to the other side.\",\"Keep your movements slow and controlled.\",\"Continue for 10-12 reps per side.\"],\"img\":\"4555.webp\",\"gif\":\"4555.mp4\",\"cat\":\"mobility\",\"desc\":\"A flowing hip rotation drill that moves the hips through internal and external rotation.\"},{\"id\":\"4671\",\"n\":\"dynamic back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"obliques\",\"shoulders\"],\"st\":[\"Stand with feet wider than hips and arms overhead.\",\"Reach up and over to one side.\",\"Return to center and reach to the other side.\",\"Let your torso rotate slightly as you go.\",\"Move smoothly for the reps.\"],\"img\":\"4671.webp\",\"gif\":\"4671.mp4\",\"cat\":\"stretching\",\"desc\":\"A moving stretch for the back and sides that warms up the spine and shoulders.\",\"fv\":\"0440\"},{\"id\":\"6301\",\"n\":\"eagle pose garudasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"shoulders\",\"upper back\",\"ankles\"],\"st\":[\"Stand and bend your knees slightly.\",\"Cross one thigh over the other, hooking the foot behind the calf if you can.\",\"Wrap your arms, one under the other, palms together.\",\"Sit your hips low and lift your elbows.\",\"Hold for 20-30 seconds, then switch.\"],\"img\":\"6301.webp\",\"gif\":\"6301.mp4\",\"cat\":\"yoga\",\"desc\":\"A balancing pose with legs and arms wrapped. It stretches the hips and shoulders and trains balance.\"},{\"id\":\"10902\",\"n\":\"eccentric single arm pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"grip muscles\",\"core\"],\"st\":[\"Get into the top position of a pull-up, with one hand on the bar and the other assisting or at rest.\",\"Let go of any help and shift your weight onto the working arm.\",\"Lower yourself as slowly as you can until your arm is straight.\",\"Keep your body tight and avoid swinging.\",\"Step back up to the top and repeat, then switch arms.\"],\"img\":\"10902.webp\",\"gif\":\"10902.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A slow lowering phase of a one-arm pull-up. It builds the strength needed for the full move.\"},{\"id\":\"10890\",\"n\":\"elastic bed toe jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on the elastic bed with feet together.\",\"Rise onto your toes.\",\"Jump using your ankles.\",\"Land softly on the balls of your feet.\",\"Stay quick and light.\",\"Continue for the set.\"],\"img\":\"10890.webp\",\"gif\":\"10890.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Toe jumps on an elastic bed. It trains calves and ankle bounce.\"},{\"id\":\"0256\",\"n\":\"elbow arm circles\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\",\"trapezius\"],\"st\":[\"Stand tall with your fingertips on your shoulders.\",\"Raise your elbows out to the sides.\",\"Draw big circles with your elbows.\",\"Do several circles forward.\",\"Reverse and circle backward.\",\"Keep your neck relaxed and your breathing steady.\"],\"img\":\"0256.webp\",\"gif\":\"0256.mp4\",\"cat\":\"mobility\",\"desc\":\"A shoulder warm-up where you draw circles with your elbows. It loosens the joint and prepares it for training.\"},{\"id\":\"2763\",\"n\":\"elbow extension\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Hold your upper arm still with the elbow bent.\",\"Straighten the arm slowly until it is almost fully extended.\",\"Pause briefly, keeping the shoulder relaxed and the upper arm fixed.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2763.webp\",\"gif\":\"2763.mp4\",\"cat\":\"mobility\",\"desc\":\"Straightening the elbow from a bent position, which works the back of the upper arm and keeps the joint moving.\"},{\"id\":\"1821\",\"n\":\"elbow extension and supination pronation forearm stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"biceps\"],\"st\":[\"Extend one arm in front of you with your elbow straight.\",\"Slowly rotate your palm up and down and let your other hand add gentle pressure at each end.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1821.webp\",\"gif\":\"1821.mp4\",\"cat\":\"stretching\",\"desc\":\"Straightening your elbow and rotating your forearm stretches the muscles on both sides of the lower arm.\"},{\"id\":\"1830\",\"n\":\"elbow extensor anconeus stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"wrist extensors\"],\"st\":[\"Extend one arm forward and bend the elbow fully with your palm down.\",\"Use your other hand to press your forearm toward your upper arm, then rotate it gently.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1830.webp\",\"gif\":\"1830.mp4\",\"cat\":\"stretching\",\"desc\":\"A forearm and elbow stretch for the small muscle at the back of the elbow along with the triceps. Useful after pressing or typing.\"},{\"id\":\"2764\",\"n\":\"elbow flexion\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Start with your arm straight down at your side, palm forward.\",\"Bend the elbow to bring your hand up toward your shoulder.\",\"Pause briefly, then lower back down slowly without swinging.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2764.webp\",\"gif\":\"2764.mp4\",\"cat\":\"mobility\",\"desc\":\"Bending the elbow to bring the hand toward the shoulder, working the front of the upper arm.\"},{\"id\":\"1814\",\"n\":\"elbow flexor stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Extend one arm in front of you with your palm facing up.\",\"Use your other hand to gently press the fingers down and back until you feel the stretch.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1814.webp\",\"gif\":\"1814.mp4\",\"cat\":\"stretching\",\"desc\":\"Extending your arm and turning the palm outward stretches the muscles that bend your elbow. It targets the biceps and brachialis.\"},{\"id\":\"1985\",\"n\":\"elbow out rotator stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall and lift one elbow out to the side, hand behind your head.\",\"Hold the elbow with your other hand.\",\"Gently press the elbow back and slightly down.\",\"Feel the stretch in the shoulder.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1985.webp\",\"gif\":\"1985.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the rotator cuff with the elbow lifted out to the side.\"},{\"id\":\"10665\",\"n\":\"elbow planche\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"chest\",\"triceps\",\"wrist flexors\"],\"st\":[\"Place your hands on the floor and tuck your elbows into your waist.\",\"Lean forward over your hands.\",\"Lift your feet off the floor one at a time.\",\"Hold your body level with a tight core.\",\"Keep your shoulders pressed forward.\",\"Lower down after the hold.\"],\"img\":\"10665.webp\",\"gif\":\"10665.mp4\",\"cat\":\"isometric\",\"desc\":\"A planche hold with your elbows tucked into your waist. It is an early step toward a full planche.\",\"hd\":1},{\"id\":\"3266\",\"n\":\"elbow push up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"triceps\"],\"st\":[\"Start in a forearm plank with body in a straight line.\",\"Press up onto one hand, then the other, into a high plank.\",\"Lower back down to your forearms one arm at a time.\",\"Keep your hips steady and avoid rocking side to side.\",\"Alternate which arm leads each rep.\"],\"img\":\"3266.webp\",\"gif\":\"3266.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Move between a forearm plank and a high plank, one arm at a time, to train the core and shoulders.\"},{\"id\":\"3503\",\"n\":\"elbow to knee side plank crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\",\"hip flexors\"],\"st\":[\"Set up in a side plank on your forearm, top hand behind your head.\",\"Lift your hips so your body is in line.\",\"Bring your top elbow and knee together in a crunch.\",\"Extend back to the side plank.\",\"Keep your hips lifted throughout.\",\"Finish your reps, then switch sides.\"],\"img\":\"3503.webp\",\"gif\":\"3503.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank where you crunch the top elbow toward the knee. It targets the obliques and core.\",\"fv\":\"3936\"},{\"id\":\"6210\",\"n\":\"elbow to knee side plank crunch (left)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"glutes\",\"shoulders\"],\"st\":[\"Set up in a left side plank on your forearm, top hand behind your head.\",\"Lift your top leg slightly.\",\"Bring your top elbow and knee together in front of you.\",\"Extend back out to the straight position.\",\"Repeat for reps, then do the other side.\"],\"img\":\"6210.webp\",\"gif\":\"6210.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank on the left with a crunch that brings elbow and knee together. It challenges the obliques.\"},{\"id\":\"3484\",\"n\":\"elbow to knee sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Curl up and rotate your torso, bringing one elbow toward the opposite knee.\",\"Pause briefly at the top.\",\"Lower your back to the floor with control.\",\"Repeat on the other side, alternating.\",\"Avoid pulling on your neck.\"],\"img\":\"3484.webp\",\"gif\":\"3484.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up that finishes by driving one elbow toward the opposite knee. It works the abs and obliques.\",\"fv\":\"7028\"},{\"id\":\"3086\",\"n\":\"elbow to knee twists\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"quadriceps\",\"core\"],\"st\":[\"Stand tall with your hands behind your head.\",\"Lift one knee up and across your body.\",\"Twist your torso to meet the knee with the opposite elbow.\",\"Return to standing.\",\"Alternate sides at a steady pace.\",\"Keep your chest lifted and breathe evenly.\"],\"img\":\"3086.webp\",\"gif\":\"3086.mp4\",\"cat\":\"cardio\",\"desc\":\"A standing move where you twist to bring an elbow toward the opposite knee. It raises your pulse and works the sides of your waist.\",\"fv\":\"0442\"},{\"id\":\"2978\",\"n\":\"elbow up and down dynamic plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"triceps\",\"obliques\"],\"st\":[\"Start in a forearm plank with your body in a straight line.\",\"Place one hand on the floor and press up to a high plank.\",\"Place the other hand down.\",\"Lower back to your forearms one arm at a time.\",\"Alternate the leading arm and keep your hips still.\"],\"img\":\"2978.webp\",\"gif\":\"2978.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Moving between a forearm plank and a high plank, one arm at a time. It builds the core and shoulders under constant tension.\",\"fv\":\"2979\"},{\"id\":\"4672\",\"n\":\"elbows back stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall with your hands behind your head and elbows pointing out.\",\"Draw your elbows back and squeeze your shoulder blades together.\",\"Lift your chest slightly.\",\"Hold for 20-30 seconds.\",\"Relax and repeat.\"],\"img\":\"4672.webp\",\"gif\":\"4672.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulling your elbows behind you to open up the chest and front of the shoulders.\",\"fv\":\"0444\"},{\"id\":\"3536\",\"n\":\"elevated inverted row between 3 chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Set a bar across two stable chairs and place a third chair at your feet.\",\"Lie under the bar and grip it overhand.\",\"Put your heels on the third chair.\",\"Pull your chest to the bar.\",\"Lower slowly to straight arms.\",\"Keep your body in a straight line.\"],\"img\":\"3536.webp\",\"gif\":\"3536.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A harder inverted row with the feet elevated on a third chair. It builds the back and arms.\"},{\"id\":\"3537\",\"n\":\"elevated inverted underhand grip row between 3 chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Set a bar across two stable chairs and a third chair at your feet.\",\"Lie under the bar and grip it underhand.\",\"Place your heels on the third chair.\",\"Pull your chest to the bar with elbows close.\",\"Lower slowly to straight arms.\",\"Keep your body straight.\"],\"img\":\"3537.webp\",\"gif\":\"3537.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row with an underhand grip and elevated feet. It emphasises the lats and biceps.\"},{\"id\":\"3812\",\"n\":\"elevated push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"upper chest\"],\"st\":[\"Place your hands on a bench or box slightly wider than your shoulders.\",\"Step back so your body forms a straight line.\",\"Lower your chest to the edge with your elbows at about 45 degrees.\",\"Press back up until your arms are straight.\",\"Keep your hips from sagging.\"],\"img\":\"3812.webp\",\"gif\":\"3812.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a raised surface. It is easier than a floor push-up and a good way to build chest strength.\"},{\"id\":\"4900\",\"n\":\"elevated seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit on a bench with the balls of your feet on a raised step.\",\"Rest weight or your hands on your thighs.\",\"Lower your heels as far as you comfortably can.\",\"Press up onto your toes as high as possible.\",\"Pause briefly at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4900.webp\",\"gif\":\"4900.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated calf raise with the balls of the feet on a raised surface for a deeper stretch. It targets the lower calf muscle.\"},{\"id\":\"5310\",\"n\":\"elevated side lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand tall next to a low step or platform.\",\"Step one foot sideways onto the platform.\",\"Push your hips back and bend that knee while the other leg stays straight.\",\"Keep your chest up and the planted foot flat.\",\"Push back to the start.\",\"Complete your reps, then switch sides.\"],\"img\":\"5310.webp\",\"gif\":\"5310.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side lunge performed with the lunging foot on a raised platform for extra range. Works glutes and inner thighs.\"},{\"id\":\"10549\",\"n\":\"elevated single leg bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one foot raised on a bench or step.\",\"Extend the other leg straight up.\",\"Drive through your heel and lift your hips.\",\"Squeeze your glute at the top without arching your back.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"10549.webp\",\"gif\":\"10549.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg glute bridge with your feet raised. It strongly works the glutes and hamstrings.\"},{\"id\":\"4902\",\"n\":\"elevated single leg hip thrust\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Rest your upper back on a bench and put one foot on the floor or a raised step.\",\"Lift the other leg off the ground.\",\"Drive through the planted heel and lift your hips.\",\"Squeeze the glute at the top with your torso level.\",\"Lower slowly under control.\",\"Complete your reps, then switch legs.\"],\"img\":\"4902.webp\",\"gif\":\"4902.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged hip thrust with the foot or upper back raised on a platform. It increases the range for the glutes.\"},{\"id\":\"4892\",\"n\":\"elevated single leg squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand on a bench or box on one leg with the other leg hanging off the edge.\",\"Reach your arms forward for balance.\",\"Sit your hips back and bend the standing knee to lower.\",\"Go as deep as you can while the knee tracks over your toes.\",\"Push through the foot to stand back up.\",\"Finish your reps, then switch legs.\"],\"img\":\"4892.webp\",\"gif\":\"4892.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one legged squat with the working foot raised on a step. It builds leg strength and balance.\"},{\"id\":\"9315\",\"n\":\"elevated split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand a stride length in front of a bench and rest your back foot on it.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Keep your front knee over your foot.\",\"Drive through the front heel to stand.\",\"Finish the reps, then switch legs.\"],\"img\":\"9315.webp\",\"gif\":\"9315.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A split squat with the rear foot on a bench builds leg strength and balance, one leg at a time.\"},{\"id\":\"4760\",\"n\":\"elevated standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand with the balls of your feet on a step or block, heels hanging off.\",\"Hold something for balance.\",\"Lower your heels below the step to stretch your calves.\",\"Rise up as high as you can on your toes.\",\"Pause at the top, then lower slowly.\"],\"img\":\"4760.webp\",\"gif\":\"4760.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise from a raised platform so your heels drop below the toes. The extra range works the calves hard.\"},{\"id\":\"5009\",\"n\":\"elevated standing calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand with the balls of your feet on a step and your heels hanging off.\",\"Hold something for balance.\",\"Rise high onto your toes.\",\"Pause and squeeze your calves.\",\"Lower your heels below the step slowly.\"],\"img\":\"5009.webp\",\"gif\":\"5009.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Standing calf raise from a raised platform for a full range of motion. It builds the calves.\"},{\"id\":\"4761\",\"n\":\"elevated standing single leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on one foot with the ball of that foot on a step, other foot lifted.\",\"Hold a wall or rail for balance.\",\"Lower your heel below the step.\",\"Press up onto your toes as high as you can.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"4761.webp\",\"gif\":\"4761.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf raise on a step with a full stretch at the bottom. It builds calf strength and balance.\"},{\"id\":\"7413\",\"n\":\"elevated two legs hip thrust\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\",\"lower back\"],\"st\":[\"Sit on the floor with your upper back against a bench and knees bent.\",\"Plant your feet hip-width apart.\",\"Drive through your heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\",\"Repeat for the planned reps.\"],\"img\":\"7413.webp\",\"gif\":\"7413.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip thrust with your upper back on a bench, driving both hips up to train the glutes.\"},{\"id\":\"2658\",\"n\":\"elliptical machine skiing\",\"bp\":\"cardio\",\"eq\":\"elliptical machine\",\"tg\":\"cardiovascular system\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Step onto the elliptical and hold the handles.\",\"Start striding in a smooth, ski-like rhythm, swinging your arms with your legs.\",\"Stay upright and keep your core engaged.\",\"Hold a steady pace for your chosen time.\",\"Slow down gradually to finish.\"],\"img\":\"2658.webp\",\"gif\":\"2658.mp4\",\"cat\":\"cardio\",\"desc\":\"A ski-style stride on the elliptical that keeps your heart rate up and works the whole body.\"},{\"id\":\"2192\",\"n\":\"elliptical machine walk\",\"bp\":\"cardio\",\"eq\":\"elliptical machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\"],\"st\":[\"Step onto the pedals and hold the handles.\",\"Start walking forward in a smooth rhythm.\",\"Stand tall and keep your shoulders relaxed.\",\"Set a resistance and pace you can keep up while breathing steadily.\",\"Continue for 15-45 minutes.\",\"Slow down for a minute before you step off.\"],\"img\":\"2192.webp\",\"gif\":\"2192.mp4\",\"cat\":\"cardio\",\"desc\":\"A steady, low-impact walk on the elliptical that builds endurance and works the legs without pounding the joints.\",\"fv\":\"2263\"},{\"id\":\"1337\",\"n\":\"exercise ball back stretch\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"lats\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"core\"],\"st\":[\"Sit on a stability ball and walk your feet forward.\",\"Lean back until your back rests over the ball.\",\"Let your arms fall overhead and relax.\",\"Breathe deeply and let your back open.\",\"Hold for 20-30 seconds.\"],\"img\":\"1337.webp\",\"gif\":\"1337.mp4\",\"cat\":\"stretching\",\"desc\":\"Draping your back over a stability ball to lengthen the spine and stretch the lats.\"},{\"id\":\"2469\",\"n\":\"exercise ball frog crunch\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie back on a stability ball with your lower back supported.\",\"Place the soles of your feet together with your knees out.\",\"Place your hands lightly by your head.\",\"Crunch up while pulling your knees toward your chest.\",\"Squeeze your abs.\",\"Lower slowly and repeat.\"],\"img\":\"2469.webp\",\"gif\":\"2469.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch on a stability ball with the legs in a frog position to hit the lower abs.\"},{\"id\":\"5036\",\"n\":\"exercise ball leg curl\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lie on your back with your heels on a stability ball.\",\"Lift your hips into a bridge.\",\"Curl the ball toward your glutes by bending your knees.\",\"Extend your legs again slowly.\",\"Keep your hips high the whole time.\"],\"img\":\"5036.webp\",\"gif\":\"5036.mp4\",\"cat\":\"strength\",\"desc\":\"Hamstring curl with your heels on a stability ball. It also challenges balance and the core.\"},{\"id\":\"1340\",\"n\":\"exercise ball lower back prone stretch\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"lats\",\"sm\":[\"lats\",\"glutes\",\"hamstrings\"],\"st\":[\"Kneel by a stability ball and lay your torso over it.\",\"Roll forward so your hips rest on the ball.\",\"Let your arms and head hang down in a relaxed way.\",\"Breathe slowly and let your lower back release.\",\"Hold for 20-30 seconds.\"],\"img\":\"1340.webp\",\"gif\":\"1340.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying face down over a stability ball to stretch the lower back.\"},{\"id\":\"1883\",\"n\":\"exercise ball lying abductor stretch\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie on your back with your calves resting on a stability ball.\",\"Cross one ankle over the opposite knee.\",\"Roll the ball gently to bring your legs toward your chest.\",\"Feel the stretch in the outer hip.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1883.webp\",\"gif\":\"1883.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying stretch using a stability ball for support while opening the outer hip.\"},{\"id\":\"1561\",\"n\":\"exercise ball seated quad stretch\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the edge of a stability ball with your torso upright.\",\"Hold on to something steady for balance if needed.\",\"Bend one knee and bring your heel toward your glutes, holding your ankle.\",\"Keep your knees close together and your hips square.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1561.webp\",\"gif\":\"1561.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle quad stretch using a stability ball for support. It opens up the front of the thigh.\"},{\"id\":\"5311\",\"n\":\"exercise ball serratus wall slide\",\"bp\":\"back\",\"eq\":\"stability ball\",\"tg\":\"serratus anterior\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"trapezius\",\"upper back\"],\"st\":[\"Place a stability ball against a wall and rest your forearms on it.\",\"Step back slightly so your body leans in.\",\"Slide your forearms up the ball as you reach overhead.\",\"Push into the ball and spread your shoulder blades at the top.\",\"Slide back down slowly.\",\"Keep your ribs down and avoid arching your lower back.\"],\"img\":\"5311.webp\",\"gif\":\"5311.mp4\",\"cat\":\"strength\",\"desc\":\"Slide your forearms up a wall on a stability ball to wake up the serratus anterior and improve shoulder control.\"},{\"id\":\"1562\",\"n\":\"exercise ball wall squat\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Place a stability ball between your lower back and a wall.\",\"Walk your feet forward about a step and stand shoulder-width apart.\",\"Bend your knees and let the ball roll down your back as you squat.\",\"Lower until your thighs are about parallel to the floor.\",\"Press through your heels to rise back up.\"],\"img\":\"1562.webp\",\"gif\":\"1562.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a stability ball between your back and the wall. The ball keeps the movement smooth and supports your back.\"},{\"id\":\"7859\",\"n\":\"explosive dynamic plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"chest\",\"hip flexors\"],\"st\":[\"Start in a high plank, hands under shoulders.\",\"Brace your core and squeeze your glutes.\",\"Move quickly, hopping or shifting your hands and feet.\",\"Keep your hips level and avoid sagging.\",\"Rest when your form slips.\"],\"img\":\"7859.webp\",\"gif\":\"7859.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A plank with fast, powerful movements from the hands or feet. It builds core strength and shoulder stability.\"},{\"id\":\"11783\",\"n\":\"explosive fingers\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Hold your hands out in front of you.\",\"Close both hands into tight fists.\",\"Open them fast, spreading your fingers as wide as possible.\",\"Repeat quickly for 20-30 reps.\",\"Keep your wrists relaxed.\"],\"img\":\"11783.webp\",\"gif\":\"11783.mp4\",\"cat\":\"mobility\",\"desc\":\"A quick open-and-close finger drill that warms up the hands and forearms.\"},{\"id\":\"11784\",\"n\":\"explosive hang squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Hang from a bar with arms straight and knees slightly bent.\",\"Lower into a deep squat position.\",\"Explode upward through your legs.\",\"Absorb the movement softly and return to the start.\",\"Keep your core tight and repeat.\"],\"img\":\"11784.webp\",\"gif\":\"11784.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat jump while hanging from a bar that lets you focus on explosive leg drive.\"},{\"id\":\"5460\",\"n\":\"explosive push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Lower your chest toward the floor.\",\"Push up explosively so your hands lift off.\",\"Land softly with bent elbows.\",\"Go straight into the next rep.\",\"Keep your body in a straight line.\"],\"img\":\"5460.webp\",\"gif\":\"5460.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push-up pushed fast enough for your hands to leave the floor. Builds upper-body power.\"},{\"id\":\"5220\",\"n\":\"extended side angle yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"glutes\",\"groin\"],\"st\":[\"Step your feet wide apart and turn one foot out.\",\"Bend the front knee over the ankle.\",\"Rest your forearm on your thigh and reach the other arm overhead.\",\"Lengthen the whole side body and look up if comfortable.\",\"Hold for 20-30 seconds and switch sides.\"],\"img\":\"5220.webp\",\"gif\":\"5220.mp4\",\"cat\":\"yoga\",\"desc\":\"A wide-legged yoga lunge with a long side stretch. It opens the hips and sides of the body.\"},{\"id\":\"1844\",\"n\":\"extension and inclination neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit or stand tall with your shoulders down.\",\"Tilt your head back slightly.\",\"Lower one ear toward the same shoulder.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1844.webp\",\"gif\":\"1844.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilts the head back and to the side to stretch the front and side of the neck.\"},{\"id\":\"1816\",\"n\":\"extension of arms in vertical stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\",\"chest\"],\"st\":[\"Stand tall with your arms raised straight overhead.\",\"Press your arms back slightly and reach long through your fingertips.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1816.webp\",\"gif\":\"1816.mp4\",\"cat\":\"stretching\",\"desc\":\"Arms stretched out vertically open up the front of the arm and shoulder. It lengthens the biceps and chest.\"},{\"id\":\"11793\",\"n\":\"external press shoulders mobilization\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\"],\"st\":[\"Stand tall with your elbow bent at your side.\",\"Press your forearm outward away from your body.\",\"Hold for a moment at the end of your comfortable range.\",\"Return slowly and repeat 8-12 times.\",\"Switch arms.\"],\"img\":\"11793.webp\",\"gif\":\"11793.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle shoulder mobility drill pressing outward to warm up the joint.\"},{\"id\":\"11796\",\"n\":\"external rotation shoulders mobilization\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\"],\"st\":[\"Stand tall with your elbow bent to 90 degrees at your side.\",\"Rotate your forearm outward away from your belly.\",\"Keep your elbow tucked in.\",\"Return slowly and repeat 8-12 times.\",\"Switch arms.\"],\"img\":\"11796.webp\",\"gif\":\"11796.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle shoulder mobility drill for external rotation.\"},{\"id\":\"1990\",\"n\":\"external shoulder rotation stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Stand next to a doorframe and bend your elbow to 90 degrees with your forearm on the frame.\",\"Slowly turn your body away from the arm until you feel the front of the shoulder stretch.\",\"Keep your elbow level with your shoulder.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1990.webp\",\"gif\":\"1990.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch that eases the shoulder into outward rotation.\"},{\"id\":\"1864\",\"n\":\"extra decline sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Set a decline bench to a steep angle and hook your feet under the pads.\",\"Lie back and cross your arms over your chest.\",\"Curl your torso up until you are sitting.\",\"Squeeze your abs at the top.\",\"Lower slowly back down.\"],\"img\":\"1864.webp\",\"gif\":\"1864.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A steeper decline sit-up that increases the load on the abs.\"},{\"id\":\"5450\",\"n\":\"ez bar 21s\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand holding an EZ bar with an underhand grip.\",\"Curl from the bottom to halfway up for 7 reps.\",\"Curl from halfway to the top for 7 reps.\",\"Do 7 full-range curls.\",\"Keep your elbows pinned to your sides.\",\"Use a lighter weight than normal.\"],\"img\":\"5450.webp\",\"gif\":\"5450.mp4\",\"cat\":\"strength\",\"desc\":\"A curl format with seven bottom-half reps, seven top-half reps and seven full reps. Gives your biceps a burn.\"},{\"id\":\"4130\",\"n\":\"ez bar california skullcrusher\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench holding an ez bar above your chest.\",\"Lower the bar toward your forehead.\",\"Let it travel back past your head slightly.\",\"Extend your arms to return.\",\"Keep your upper arms still.\"],\"img\":\"4130.webp\",\"gif\":\"4130.mp4\",\"cat\":\"strength\",\"desc\":\"A skullcrusher that mixes a pullover motion, loading the triceps from a long position.\",\"nd\":[\"bench\"]},{\"id\":\"4422\",\"n\":\"ez bar drag bicep curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Stand holding an ez bar with an underhand grip at your thighs.\",\"Keep the bar close to your body.\",\"Curl it up while moving your elbows back behind you.\",\"Let the bar slide up your torso to chest height.\",\"Lower slowly under control.\"],\"img\":\"4422.webp\",\"gif\":\"4422.mp4\",\"cat\":\"strength\",\"desc\":\"A curl where the bar drags up your torso with elbows pulled back. It keeps tension on the biceps and reduces shoulder help.\"},{\"id\":\"3986\",\"n\":\"ez bar front twist raise\",\"bp\":\"shoulders\",\"eq\":\"ez barbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"forearms\",\"core\"],\"st\":[\"Stand holding an EZ bar at thigh height.\",\"Raise it forward to chest height.\",\"Rotate your wrists as you lift.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"3986.webp\",\"gif\":\"3986.mp4\",\"cat\":\"strength\",\"desc\":\"Raise an EZ bar forward while rotating it. It trains the front delts with a twist.\"},{\"id\":\"3989\",\"n\":\"ez bar incline front raise\",\"bp\":\"shoulders\",\"eq\":\"ez barbell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"forearms\"],\"st\":[\"Sit on an incline bench with the EZ bar at thighs.\",\"Keep arms straight with a slight bend.\",\"Raise the bar to eye level.\",\"Lower under control.\",\"Keep your back on the pad.\"],\"img\":\"3989.webp\",\"gif\":\"3989.mp4\",\"cat\":\"strength\",\"desc\":\"A front raise with an EZ bar on an incline bench. It isolates the front delts.\"},{\"id\":\"4189\",\"n\":\"ez bar kneeling rollout\",\"bp\":\"waist\",\"eq\":\"ez barbell\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lats\",\"shoulders\"],\"st\":[\"Kneel holding the EZ bar on the floor.\",\"Brace your core.\",\"Roll forward with a flat back.\",\"Stop before your back sags.\",\"Pull the bar back to the start.\",\"Keep your hips in line.\"],\"img\":\"4189.webp\",\"gif\":\"4189.mp4\",\"cat\":\"strength\",\"desc\":\"Roll the EZ bar forward from a kneeling position and back. It strongly challenges the core.\"},{\"id\":\"4187\",\"n\":\"ez bar legs side pull in sit up\",\"bp\":\"waist\",\"eq\":\"ez barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back holding an EZ bar over your chest.\",\"Bend your knees.\",\"Sit up while pulling your knees to one side.\",\"Lower slowly.\",\"Repeat on the other side.\",\"Keep the bar stable.\"],\"img\":\"4187.webp\",\"gif\":\"4187.mp4\",\"cat\":\"strength\",\"desc\":\"A sit up with legs pulled to the side while holding an EZ bar. It works the abs and obliques.\"},{\"id\":\"1820\",\"n\":\"ez bar preacher arms stretch\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Sit at a preacher bench and rest your upper arms on the pad, holding an EZ bar.\",\"Let the bar lower under control until your arms are fully extended, using a light load.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1820.webp\",\"gif\":\"1820.mp4\",\"cat\":\"stretching\",\"desc\":\"Resting your arms on a preacher bench while holding an EZ bar lets the arms extend fully, stretching the biceps.\"},{\"id\":\"4188\",\"n\":\"ez bar reverse crunch\",\"bp\":\"waist\",\"eq\":\"ez barbell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back holding an EZ bar overhead.\",\"Lift your legs with knees bent.\",\"Curl your hips off the floor.\",\"Pause at the top.\",\"Lower slowly.\",\"Keep your arms steady.\"],\"img\":\"4188.webp\",\"gif\":\"4188.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse crunch holding an EZ bar behind your head. It targets the lower abs.\"},{\"id\":\"5308\",\"n\":\"ez bar russian twist sit up\",\"bp\":\"waist\",\"eq\":\"ez barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent and hold the EZ bar over your chest.\",\"Curl up into a sit-up position.\",\"At the top, rotate your torso to one side, moving the bar with you.\",\"Rotate back to center and lower yourself with control.\",\"Alternate sides each rep.\",\"Keep the weight light enough to move smoothly.\"],\"img\":\"5308.webp\",\"gif\":\"5308.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up that adds a twist while holding an EZ bar. Works the abs and obliques together.\"},{\"id\":\"3990\",\"n\":\"ez bar seated close grip shoulder press\",\"bp\":\"shoulders\",\"eq\":\"ez barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Sit upright holding the EZ bar with a close grip at your chest.\",\"Brace your core.\",\"Press the bar overhead.\",\"Lower it back to chest height.\",\"Keep your ribs down.\"],\"img\":\"3990.webp\",\"gif\":\"3990.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with a narrow grip on the EZ bar. It builds the shoulders and triceps.\"},{\"id\":\"5579\",\"n\":\"ez bar seated wrist curl\",\"bp\":\"lower arms\",\"eq\":\"ez barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit on a bench with forearms on your thighs and wrists past your knees.\",\"Hold the EZ bar with an underhand grip.\",\"Lower the bar by opening your fingers slightly.\",\"Curl your wrists up as high as you can.\",\"Keep your forearms still.\"],\"img\":\"5579.webp\",\"gif\":\"5579.mp4\",\"cat\":\"strength\",\"desc\":\"Seated wrist curl with an EZ bar to build the forearm flexors.\"},{\"id\":\"5309\",\"n\":\"ez bar shoulder press sit up\",\"bp\":\"waist\",\"eq\":\"ez barbell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with knees bent, holding the EZ bar at your chest.\",\"Sit up while keeping the bar close to your body.\",\"Once upright, press the bar overhead.\",\"Lower the bar back to your chest.\",\"Roll back down slowly to the floor.\",\"Brace your core and avoid yanking with your neck.\"],\"img\":\"5309.webp\",\"gif\":\"5309.mp4\",\"cat\":\"strength\",\"desc\":\"Combine a sit-up with an overhead press using an EZ bar. Trains the abs, shoulders and triceps in one flowing rep.\"},{\"id\":\"4190\",\"n\":\"ez bar up down twist\",\"bp\":\"waist\",\"eq\":\"ez barbell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Stand holding the EZ bar in front of you.\",\"Raise it overhead.\",\"Lower it diagonally across your body, twisting.\",\"Return overhead.\",\"Alternate sides.\",\"Move with control.\"],\"img\":\"4190.webp\",\"gif\":\"4190.mp4\",\"cat\":\"strength\",\"desc\":\"Move the EZ bar in an arc with a twist. It trains the obliques.\"},{\"id\":\"5240\",\"n\":\"ez barbell deadlift with biceps curl\",\"bp\":\"upper legs\",\"eq\":\"ez barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"biceps\",\"lower back\",\"forearms\"],\"st\":[\"Stand with an EZ bar in front of your thighs.\",\"Hinge at the hips and lower the bar along your legs.\",\"Stand tall by driving your hips forward.\",\"Curl the bar up to your chest.\",\"Lower it and repeat.\"],\"img\":\"5240.webp\",\"gif\":\"5240.mp4\",\"cat\":\"strength\",\"desc\":\"Deadlifting an EZ bar and finishing with a curl. It combines a hip hinge and an arm exercise.\"},{\"id\":\"5873\",\"n\":\"ez barbell lying triceps extension\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench holding an EZ bar above your chest.\",\"Keep your upper arms vertical.\",\"Bend your elbows to lower the bar toward your forehead.\",\"Extend your arms back to the start.\",\"Keep your elbows from flaring.\"],\"img\":\"5873.webp\",\"gif\":\"5873.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on a bench and lower an EZ bar toward your forehead, then press back up. It builds the triceps with minimal wrist strain.\",\"nd\":[\"bench\"],\"fv\":\"3646\"},{\"id\":\"6406\",\"n\":\"ez barbell preacher curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit at a preacher bench with your upper arms resting on the pad.\",\"Hold an EZ bar with an underhand grip.\",\"Curl the bar up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are almost straight and repeat.\"],\"img\":\"6406.webp\",\"gif\":\"6406.mp4\",\"cat\":\"strength\",\"desc\":\"Curling an EZ bar over a preacher pad, which keeps your upper arms still so your biceps do the work.\"},{\"id\":\"6364\",\"n\":\"ez barbell seated wrist reverse curl\",\"bp\":\"lower arms\",\"eq\":\"ez barbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit and rest your forearms on your thighs, holding an EZ bar overhand.\",\"Let your wrists hang past your knees.\",\"Extend your wrists to lift the bar.\",\"Squeeze at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6364.webp\",\"gif\":\"6364.mp4\",\"cat\":\"strength\",\"desc\":\"Seated reverse wrist curl with your forearms supported on your thighs, isolating the top of your forearms.\"},{\"id\":\"6365\",\"n\":\"ez barbell standing back wrist curl\",\"bp\":\"lower arms\",\"eq\":\"ez barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand holding an EZ bar behind your back with an underhand grip.\",\"Keep your elbows still and your chest up.\",\"Curl your wrists to raise the bar slightly.\",\"Squeeze at the top.\",\"Lower with control and repeat.\"],\"img\":\"6365.webp\",\"gif\":\"6365.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl with the EZ bar held behind your back, training your forearms and grip.\"},{\"id\":\"1226\",\"n\":\"ez barbell standing overhead press\",\"bp\":\"shoulders\",\"eq\":\"ez barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand holding an EZ bar at your upper chest with a comfortable grip.\",\"Brace your core and squeeze your glutes.\",\"Press the bar overhead until your arms are straight.\",\"Lower it slowly back to your chest.\",\"Keep your head neutral and avoid leaning back.\"],\"img\":\"1226.webp\",\"gif\":\"1226.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with an EZ bar. The angled grips can feel kinder on the wrists while you train the shoulders.\"},{\"id\":\"2900\",\"n\":\"ez barbell standing preacher curl\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"upper chest\"],\"st\":[\"Stand facing a preacher pad and hold an EZ bar with an underhand grip.\",\"Rest your upper arms on the pad with the arms extended.\",\"Curl the bar up toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until the arms are almost straight.\"],\"img\":\"2900.webp\",\"gif\":\"2900.mp4\",\"cat\":\"strength\",\"desc\":\"A preacher style curl performed standing at an angled pad. Isolates the biceps with strict form.\"},{\"id\":\"6268\",\"n\":\"ez barbell standing single arm neutral wrist curl\",\"bp\":\"lower arms\",\"eq\":\"ez barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand holding one end of an EZ bar.\",\"Keep your arm at your side.\",\"Curl your wrist up.\",\"Squeeze the forearm.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"6268.webp\",\"gif\":\"6268.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm wrist curl with a neutral grip on an EZ barbell. It targets the forearms.\"},{\"id\":\"7114\",\"n\":\"ez barbell standing upright row\",\"bp\":\"shoulders\",\"eq\":\"ez barbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Stand tall holding the EZ bar with a shoulder-width grip.\",\"Let the bar hang in front of your thighs.\",\"Pull it up along your body, leading with your elbows.\",\"Stop around chest height without shrugging hard.\",\"Lower the bar slowly to the start.\",\"Keep your torso upright throughout.\"],\"img\":\"7114.webp\",\"gif\":\"7114.mp4\",\"cat\":\"strength\",\"desc\":\"A vertical pull with an EZ bar that builds the side shoulders and upper traps.\"},{\"id\":\"6358\",\"n\":\"ez barbell standing wrist curl\",\"bp\":\"lower arms\",\"eq\":\"ez barbell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Stand holding an EZ bar with an underhand grip, arms hanging in front.\",\"Keep your elbows still and close to your body.\",\"Curl your wrists upward, lifting the bar a short distance.\",\"Squeeze at the top.\",\"Lower the bar slowly and repeat.\"],\"img\":\"6358.webp\",\"gif\":\"6358.mp4\",\"cat\":\"strength\",\"desc\":\"Wrist curls with an EZ bar held in front of you, targeting the muscles on the underside of your forearms.\"},{\"id\":\"6361\",\"n\":\"ez barbell standing wrist reverse curl\",\"bp\":\"lower arms\",\"eq\":\"ez barbell\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand holding an EZ bar with an overhand grip, arms hanging in front.\",\"Keep your elbows still at your sides.\",\"Extend your wrists to raise the bar upward.\",\"Hold briefly at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6361.webp\",\"gif\":\"6361.mp4\",\"cat\":\"strength\",\"desc\":\"Reverse wrist curls with an EZ bar, an overhand movement that trains the top of your forearms.\"},{\"id\":\"6786\",\"n\":\"faber test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"groin\"],\"st\":[\"Lie on your back with legs straight.\",\"Place one foot on the opposite knee.\",\"Let the bent knee drop out to the side.\",\"Relax and notice how far it goes.\",\"Hold for 20-30 seconds without forcing it.\",\"Switch legs.\"],\"img\":\"6786.webp\",\"gif\":\"6786.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle hip check where the ankle rests on the opposite knee and the knee drops out. It shows how mobile the hip is.\"},{\"id\":\"4283\",\"n\":\"feet and ankles rotation stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with one leg extended or crossed over your knee.\",\"Hold your lower leg steady.\",\"Draw slow circles with your foot.\",\"Do 10 circles in one direction.\",\"Switch to the other direction.\",\"Repeat on the other foot.\"],\"img\":\"4283.webp\",\"gif\":\"4283.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the foot in slow circles to mobilise the ankle. It warms up the joint and relieves stiffness.\",\"fv\":\"3246\"},{\"id\":\"3245\",\"n\":\"feet and ankles side to side stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with your legs extended.\",\"Keep your heels on the floor.\",\"Roll your feet slowly to the outside.\",\"Then roll them inward.\",\"Continue for 20-30 seconds.\"],\"img\":\"3245.webp\",\"gif\":\"3245.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch moving the feet side to side to loosen the ankles.\"},{\"id\":\"4282\",\"n\":\"feet and ankles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit on a chair or the floor with one leg extended.\",\"Point your toes away from you.\",\"Hold for 15 seconds.\",\"Pull your toes back toward your shin.\",\"Hold for another 15 seconds.\",\"Switch legs and repeat.\"],\"img\":\"4282.webp\",\"gif\":\"4282.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle stretch for the feet and ankles. It helps loosen stiff joints and the muscles around them.\",\"fv\":\"3247\"},{\"id\":\"5989\",\"n\":\"figure run\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Set two cones about 5 yards apart.\",\"Start next to one cone in an athletic stance.\",\"Run a figure-eight around both cones.\",\"Lean into the turns and keep your hips low.\",\"Run for 20-30 seconds, then change direction.\"],\"img\":\"5989.webp\",\"gif\":\"5989.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A run in a figure-eight around two cones, which builds agility, balance and quick turns.\"},{\"id\":\"2095\",\"n\":\"finger extension stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrist flexors\"],\"st\":[\"Extend one arm in front with the palm facing up.\",\"Use your other hand to hold the fingers.\",\"Gently pull the fingers back toward you.\",\"Keep your elbow straight and the wrist relaxed.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2095.webp\",\"gif\":\"2095.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch that bends the fingers back to lengthen the palm side of the forearm.\"},{\"id\":\"1827\",\"n\":\"finger extensor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"hands\"],\"st\":[\"Extend one arm forward with your palm facing down and your wrist relaxed.\",\"Use your other hand to gently press your fingers and hand down toward you.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1827.webp\",\"gif\":\"1827.mp4\",\"cat\":\"stretching\",\"desc\":\"Bending your fingers down stretches the muscles on the back of your forearm. Handy to loosen up after lots of gripping.\"},{\"id\":\"10031\",\"n\":\"finger flexion while extending thumb\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Hold one hand out with your palm open.\",\"Extend your thumb out to the side and keep it straight.\",\"Curl your four fingers slowly toward your palm.\",\"Open the fingers again.\",\"Repeat 10-15 times, then switch hands.\",\"Keep the movement smooth and pain free.\"],\"img\":\"10031.webp\",\"gif\":\"10031.mp4\",\"cat\":\"mobility\",\"desc\":\"A small hand mobility drill where you curl your fingers while holding the thumb straight. It helps finger and thumb control.\"},{\"id\":\"1826\",\"n\":\"finger flexor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\",\"grip muscles\"],\"st\":[\"Extend one arm forward with your palm facing up or out.\",\"Use your other hand to gently pull your fingers and palm back toward you.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1826.webp\",\"gif\":\"1826.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulling your fingers back stretches the muscles on the palm side of your forearm. Great after grip-heavy training or typing.\"},{\"id\":\"3981\",\"n\":\"finger push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"forearms\",\"grip muscles\"],\"st\":[\"Get into a high plank on your fingertips.\",\"Keep your body straight.\",\"Lower your chest to the floor.\",\"Press up.\",\"Reduce the range if your fingers tire.\"],\"img\":\"3981.webp\",\"gif\":\"3981.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push up supported on your fingertips. It challenges the hands and forearms as well as the chest.\"},{\"id\":\"2089\",\"n\":\"finger stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Hold one arm out in front of you with the elbow straight.\",\"Use the other hand to gently pull the fingers back until you feel a stretch in the palm and forearm.\",\"Keep the fingers straight and relaxed.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2089.webp\",\"gif\":\"2089.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple stretch that opens the fingers and forearm muscles, useful after typing or gripping.\"},{\"id\":\"2091\",\"n\":\"fingers down forearm stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"hands\"],\"st\":[\"Extend one arm in front of you with the palm facing down.\",\"Bend the wrist so the fingers point toward the floor.\",\"Use your other hand to press the back of the hand gently toward you.\",\"Keep your elbow straight.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2091.webp\",\"gif\":\"2091.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the top of the forearm with the fingers pointing down.\"},{\"id\":\"0950\",\"n\":\"fish pose matsyasana\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"upper back\",\"core\"],\"st\":[\"Lie on your back with legs straight and arms at your sides, palms down.\",\"Press your forearms into the floor and lift your chest.\",\"Arch your upper back and lower the crown of your head lightly toward the floor.\",\"Keep your legs relaxed and breathe deeply into the chest.\",\"Hold for 15-30 seconds, then lower slowly.\"],\"img\":\"0950.webp\",\"gif\":\"0950.mp4\",\"cat\":\"yoga\",\"desc\":\"Lie on your back and lift your chest into a gentle arch. It opens the chest and front of the neck and shoulders.\"},{\"id\":\"1052\",\"n\":\"fixed bar back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"lower back\"],\"st\":[\"Grip a fixed bar or post at about hip height.\",\"Step back until your arms are straight.\",\"Sink your hips back and let your chest drop.\",\"Feel the stretch along your back and sides.\",\"Hold for 20-30 seconds.\"],\"img\":\"1052.webp\",\"gif\":\"1052.mp4\",\"cat\":\"stretching\",\"desc\":\"Hold a fixed bar and sit your hips back to stretch your back and lats. It opens the upper body.\"},{\"id\":\"3396\",\"n\":\"flexion and extension hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"lower back\"],\"st\":[\"Lie on your back with your legs extended.\",\"Pull one knee toward your chest with both hands.\",\"Hold for 20-30 seconds.\",\"Extend the leg again and press it down to the floor.\",\"Repeat on the other leg.\",\"Breathe slowly and stay relaxed.\"],\"img\":\"3396.webp\",\"gif\":\"3396.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle hip stretch that moves through flexion and extension to loosen the hips and glutes.\",\"fv\":\"1950\"},{\"id\":\"2096\",\"n\":\"flexion finger stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Hold one arm out in front of you with the palm facing down.\",\"Use your other hand to press the fingers of the extended hand gently downward.\",\"Keep the elbow of the extended arm straight and the shoulders relaxed.\",\"Stop at a mild pull, never at pain.\",\"Hold for 20-30 seconds.\",\"Release and repeat on the other hand.\"],\"img\":\"2096.webp\",\"gif\":\"2096.mp4\",\"cat\":\"stretching\",\"desc\":\"Gently bends the fingers down to stretch the tight tissue on the top of the hand and fingers. Handy after typing or gripping work.\"},{\"id\":\"3279\",\"n\":\"floor crunch feet on bench\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back and rest your lower legs on a bench, knees bent at about 90 degrees.\",\"Place your hands lightly behind your head or across your chest.\",\"Curl your shoulders off the floor by squeezing your abs.\",\"Pause briefly at the top.\",\"Lower slowly and repeat without pulling on your neck.\"],\"img\":\"3279.webp\",\"gif\":\"3279.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with the calves resting on a bench, which keeps the hips bent and focuses the work on the abs.\"},{\"id\":\"3924\",\"n\":\"floor fly with towels\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Kneel or get into a plank with your hands on towels.\",\"Slide your hands out wide to the sides.\",\"Lower your chest toward the floor.\",\"Squeeze your chest to slide your hands back together.\",\"Keep your core tight.\",\"Do not let your hips sag.\"],\"img\":\"3924.webp\",\"gif\":\"3924.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor fly sliding hands on towels for a bodyweight chest isolation move.\"},{\"id\":\"2394\",\"n\":\"floor hyperextension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hamstrings\",\"core\"],\"st\":[\"Lie face down with your arms extended or by your head.\",\"Squeeze your glutes and lift your chest and legs slightly off the floor.\",\"Keep your neck neutral and look at the floor.\",\"Pause at the top for a second.\",\"Lower slowly to the floor.\",\"Repeat without forcing a big arch.\"],\"img\":\"2394.webp\",\"gif\":\"2394.mp4\",\"cat\":\"strength\",\"desc\":\"A floor-based back extension that strengthens the glutes and lower back.\"},{\"id\":\"2844\",\"n\":\"floor hyperextension v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\"],\"st\":[\"Lie face down with arms extended in front.\",\"Lengthen your neck.\",\"Lift your arms, chest and legs off the floor.\",\"Hold briefly.\",\"Lower slowly.\"],\"img\":\"2844.webp\",\"gif\":\"2844.mp4\",\"cat\":\"pilates\",\"desc\":\"A face-down back lift that strengthens the spine and glutes.\"},{\"id\":\"3225\",\"n\":\"floor t raise\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with your arms out to the sides in a T.\",\"Keep your forehead near the floor.\",\"Turn your thumbs up toward the ceiling.\",\"Squeeze your shoulder blades together and lift your arms.\",\"Pause for a second.\",\"Lower slowly and repeat.\"],\"img\":\"3225.webp\",\"gif\":\"3225.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you lift your arms out to the sides into a T. It strengthens the mid and upper back.\",\"fv\":\"3205\"},{\"id\":\"7217\",\"n\":\"floor t raise v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with your arms out to the sides in a T.\",\"Keep your forehead near the floor and neck neutral.\",\"Lift your arms off the floor by pinching your shoulder blades.\",\"Hold for a second at the top.\",\"Lower with control.\"],\"img\":\"7217.webp\",\"gif\":\"7217.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A face-down raise with the arms out to form a T. It strengthens the muscles between the shoulder blades.\"},{\"id\":\"3280\",\"n\":\"floor twisting crunch feet on bench\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your back with your calves on a bench and knees bent.\",\"Place your hands lightly behind your head.\",\"Curl up and rotate so one shoulder moves toward the opposite knee.\",\"Lower with control.\",\"Alternate sides on each rep.\"],\"img\":\"3280.webp\",\"gif\":\"3280.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with a rotation, with the legs on a bench, to train the abs and the obliques.\"},{\"id\":\"11648\",\"n\":\"floor w raise\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie face down with arms bent and elbows out to the sides.\",\"Rest your forehead lightly on the floor.\",\"Squeeze your shoulder blades together and lift your arms and chest slightly.\",\"Form a W shape with your arms and hold for a second.\",\"Lower slowly and repeat.\"],\"img\":\"11648.webp\",\"gif\":\"11648.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone raise that moves the arms into a W shape to strengthen the muscles between the shoulder blades.\"},{\"id\":\"2891\",\"n\":\"flutter kicks (hands under hips head up)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with hands tucked under your hips.\",\"Lift your head and shoulders slightly off the floor.\",\"Raise both legs a few inches above the ground.\",\"Kick your legs up and down in small alternating pulses.\",\"Keep your lower back pressed down and breathe steadily.\"],\"img\":\"2891.webp\",\"gif\":\"2891.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Fast alternating leg lifts with your head raised that fire up the lower abs.\"},{\"id\":\"1179\",\"n\":\"flutter kicks v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with hands under your hips.\",\"Lift both legs a few inches off the floor.\",\"Kick your legs up and down in small, quick alternating moves.\",\"Press your lower back into the floor.\",\"Continue for 20-40 seconds.\"],\"img\":\"1179.webp\",\"gif\":\"1179.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small alternating leg kicks that burn the lower abs.\",\"fv\":\"5734\"},{\"id\":\"1244\",\"n\":\"flutter kicks v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your legs straight and hands under your hips.\",\"Lift your legs a few inches off the floor.\",\"Kick your legs up and down in small alternating motions.\",\"Keep your lower back pressed to the floor.\",\"Continue for a set time and breathe steadily.\"],\"img\":\"1244.webp\",\"gif\":\"1244.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small alternating leg kicks while lying down. They fire up the lower abs and hip flexors.\",\"fv\":\"4643\"},{\"id\":\"4200\",\"n\":\"fly against chains\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Lie on a bench with chains.\",\"Hold weights above your chest.\",\"Open arms.\",\"Stretch your chest.\",\"Bring weights together.\",\"Keep elbows soft.\"],\"img\":\"4200.webp\",\"gif\":\"4200.mp4\",\"cat\":\"strength\",\"desc\":\"A chest fly with chains adding load.\",\"nd\":[\"bench\"]},{\"id\":\"7624\",\"n\":\"flying lizard yoga pose utthan pristhasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"glutes\",\"core\"],\"st\":[\"Start in a low lunge with your front foot between your hands.\",\"Lower your forearms to the floor or blocks.\",\"Drop your back knee or keep it lifted.\",\"Let your hips sink.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Step back and switch sides.\"],\"img\":\"7624.webp\",\"gif\":\"7624.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep lunge-based hip opener with a twist and reach, stretching the hips and inner thighs.\"},{\"id\":\"5027\",\"n\":\"foam roll serratus wall slide\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"serratus anterior\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Stand facing a wall with a foam roller under your forearms against the wall.\",\"Press your forearms firmly into the roller.\",\"Roll the roller up the wall as you reach overhead.\",\"Keep your core braced and neck relaxed.\",\"Roll back down under control.\"],\"img\":\"5027.webp\",\"gif\":\"5027.mp4\",\"cat\":\"mobility\",\"desc\":\"Wall slide with a foam roller under your forearms. It teaches smooth shoulder blade movement and serratus control.\"},{\"id\":\"2765\",\"n\":\"forearm pronation\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Hold your elbow close to your side bent at 90 degrees, palm facing up.\",\"Rotate your forearm so your palm turns down to face the floor.\",\"Keep the elbow still and pause briefly at the end.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2765.webp\",\"gif\":\"2765.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the forearm so the palm turns down. Helps forearm control and wrist mobility.\"},{\"id\":\"1815\",\"n\":\"forearm pronator stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"biceps\"],\"st\":[\"Extend one arm in front of you with your elbow straight and palm down.\",\"Use your other hand to rotate the palm outward until you feel a stretch along your forearm.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1815.webp\",\"gif\":\"1815.mp4\",\"cat\":\"stretching\",\"desc\":\"Rotating your forearm outward stretches the muscles that turn the palm down. Handy for anyone who types or lifts a lot.\"},{\"id\":\"2766\",\"n\":\"forearm supination\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Hold your elbow close to your side bent at 90 degrees, palm facing down.\",\"Rotate your forearm so your palm turns up to face the ceiling.\",\"Keep the elbow still and pause briefly at the end.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2766.webp\",\"gif\":\"2766.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the forearm so the palm turns up. Helps forearm control and wrist mobility.\"},{\"id\":\"2941\",\"n\":\"forearm wall slide\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand facing a wall with your forearms on it, elbows at shoulder height.\",\"Lean in slightly and keep your abs braced.\",\"Slide your forearms up the wall as you reach upward.\",\"Pause at the top without arching your back.\",\"Slide back down and repeat.\"],\"img\":\"2941.webp\",\"gif\":\"2941.mp4\",\"cat\":\"mobility\",\"desc\":\"Sliding your forearms up a wall to wake up the shoulder blade muscles. It improves overhead movement.\"},{\"id\":\"6880\",\"n\":\"forearms stand yoga pose pincha mayurasana\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"lats\",\"triceps\"],\"st\":[\"Start on your forearms and knees with your elbows under your shoulders.\",\"Press your forearms into the floor and tuck your toes.\",\"Lift your hips high and walk your feet toward your elbows.\",\"Swing or float one leg up, then bring the other to meet it.\",\"Keep your ribs in and your gaze between your hands.\",\"Hold briefly, then lower with control.\"],\"img\":\"6880.webp\",\"gif\":\"6880.mp4\",\"cat\":\"yoga\",\"desc\":\"A forearm balance that builds strong shoulders and core, also known as feathered peacock pose.\"},{\"id\":\"10995\",\"n\":\"forward and backward crab walk\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Sit with hands behind you and feet flat, then lift your hips.\",\"Keep your chest open and hips high.\",\"Walk forward with alternating hands and feet.\",\"Then walk backward the same way.\",\"Keep your core braced.\"],\"img\":\"10995.webp\",\"gif\":\"10995.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A walk on hands and feet facing up. It works the arms, glutes and core.\"},{\"id\":\"7543\",\"n\":\"forward backward hop\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"core\"],\"st\":[\"Stand tall with your feet together.\",\"Hop forward a short distance on the balls of your feet.\",\"Hop back to the start.\",\"Land softly with your knees slightly bent.\",\"Keep a quick tempo.\",\"Repeat for the planned time.\"],\"img\":\"7543.webp\",\"gif\":\"7543.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A light hop forward and back that builds ankle spring and coordination.\"},{\"id\":\"9248\",\"n\":\"forward backward shuffle\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Stand in an athletic stance with soft knees.\",\"Shuffle forward a few steps on the balls of your feet.\",\"Shuffle back to the start without crossing your feet.\",\"Keep your hips low and your chest up.\",\"Move quickly but stay balanced.\",\"Repeat for a set time.\"],\"img\":\"9248.webp\",\"gif\":\"9248.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Quick shuffling steps forward and back build footwork and conditioning. It keeps your heart rate up.\"},{\"id\":\"6764\",\"n\":\"forward bend back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\"],\"st\":[\"Stand with feet hip-width apart.\",\"Hinge forward at the hips with soft knees.\",\"Let your arms and head hang down.\",\"Relax your neck and shoulders.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Roll up slowly to stand.\"],\"img\":\"6764.webp\",\"gif\":\"6764.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing forward fold that lengthens the back and the backs of the legs.\"},{\"id\":\"1836\",\"n\":\"forward flexion neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Stand or sit tall with your shoulders down.\",\"Place both hands lightly behind your head.\",\"Let your elbows drop forward and ease your head toward your chest.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Release your hands and return to neutral.\"],\"img\":\"1836.webp\",\"gif\":\"1836.mp4\",\"cat\":\"stretching\",\"desc\":\"Bends the neck forward to lengthen the muscles at the back of the neck and upper shoulders.\"},{\"id\":\"1698\",\"n\":\"forward hops\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"hamstrings\",\"ankles\"],\"st\":[\"Stand on both feet with your knees slightly bent.\",\"Swing your arms and hop forward a short distance.\",\"Land softly on the balls of your feet.\",\"Reset your posture and hop again.\",\"Keep your hops controlled and your chest tall.\"],\"img\":\"1698.webp\",\"gif\":\"1698.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Short, springy hops forward that build leg power, elasticity and coordination.\"},{\"id\":\"11797\",\"n\":\"forward press shoulders mobilization\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"rotator cuff\"],\"st\":[\"Stand tall with your elbows bent in front of you.\",\"Press your arm forward until it is straight.\",\"Keep your shoulder relaxed.\",\"Return slowly and repeat 8-12 times.\",\"Switch arms.\"],\"img\":\"11797.webp\",\"gif\":\"11797.mp4\",\"cat\":\"mobility\",\"desc\":\"A shoulder mobility drill pressing the arm forward to warm up the joint.\"},{\"id\":\"3702\",\"n\":\"forward pulse lunge with hands overhead\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Stand tall and raise both arms straight overhead.\",\"Step one foot forward into a lunge and lower until both knees are about 90 degrees.\",\"Pulse up and down a few inches in the low position.\",\"Push back to standing.\",\"Switch legs and repeat.\"],\"img\":\"3702.webp\",\"gif\":\"3702.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge held in the bottom position where you pulse up and down with your arms overhead. It burns the legs and challenges balance.\"},{\"id\":\"3959\",\"n\":\"forward step front plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"hip flexors\"],\"st\":[\"Start in a high plank.\",\"Step one hand forward, then the other.\",\"Follow with your feet.\",\"Keep your hips level.\",\"Walk forward a few steps, then back.\"],\"img\":\"3959.webp\",\"gif\":\"3959.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Walk forward in a front plank, stepping hands and feet to challenge the core and shoulders.\"},{\"id\":\"3961\",\"n\":\"forward to side to rear lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand tall with your feet together and hands on your hips.\",\"Step one foot forward into a lunge, then push back to standing.\",\"Step the same foot out to the side, sit back into the hip, then return to center.\",\"Step the same foot backward into a lunge and push back to standing.\",\"Keep your chest up and knees tracking over your toes, then switch legs after your set.\"],\"img\":\"3961.webp\",\"gif\":\"3961.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge sequence that steps forward, to the side and then back with the same leg. It trains the legs and hips from three directions and challenges your balance.\"},{\"id\":\"5914\",\"n\":\"four limbed staff\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank.\",\"Shift slightly forward on your toes.\",\"Bend your elbows straight back and lower.\",\"Keep your body straight like a plank.\",\"Hold briefly, then press back up.\"],\"img\":\"5914.webp\",\"gif\":\"5914.mp4\",\"cat\":\"yoga\",\"desc\":\"A low plank with elbows hugged by your sides. Builds strength in the arms and core.\"},{\"id\":\"2757\",\"n\":\"frog hip thrust\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with the soles of your feet together and knees falling out.\",\"Keep your heels near your hips.\",\"Drive through the feet to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2757.webp\",\"gif\":\"2757.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip thrust with the soles of the feet together and knees out, which shifts work to the glutes and inner thighs.\"},{\"id\":\"3088\",\"n\":\"frog hops\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet wider than your shoulders and sink into a deep squat.\",\"Place your fingertips on the floor between your feet.\",\"Jump forward and up, swinging your arms.\",\"Land softly back in the squat.\",\"Reset and hop again right away.\",\"Keep your knees tracking over your toes.\"],\"img\":\"3088.webp\",\"gif\":\"3088.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Explosive hops from a deep squat, like a frog. They build leg power and get your heart pumping.\",\"fv\":\"0460\"},{\"id\":\"6292\",\"n\":\"frog pose mandukasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hip flexors\",\"glutes\"],\"st\":[\"Start on hands and knees on a mat.\",\"Slide your knees wide, with feet turned out and inline with knees.\",\"Lower onto your forearms.\",\"Push your hips back gently.\",\"Hold for 20-30 seconds, breathing slowly.\"],\"img\":\"6292.webp\",\"gif\":\"6292.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep hip opener on all fours with knees wide. It stretches the inner thighs and groin.\"},{\"id\":\"3870\",\"n\":\"frog reverse hyperextension (on a bench)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"adductors\"],\"st\":[\"Lie face down on a bench with your hips at the edge and hold the bench for support.\",\"Let your legs hang and bring the soles of your feet together, knees out.\",\"Squeeze your glutes and lift your legs up behind you.\",\"Pause when your thighs are in line with your torso.\",\"Lower slowly and repeat.\",\"Avoid arching your lower back too far.\"],\"img\":\"3870.webp\",\"gif\":\"3870.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse hyperextension with the legs in a frog position, aimed at the glutes and lower back.\",\"fv\":\"3179\"},{\"id\":\"3889\",\"n\":\"frog sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"inner thighs\"],\"st\":[\"Lie on your back with the soles of your feet together and knees falling out.\",\"Place your hands behind your head or reach forward.\",\"Curl up and sit all the way up.\",\"Reach your hands toward your feet at the top.\",\"Lower with control.\",\"Avoid pulling on your neck.\"],\"img\":\"3889.webp\",\"gif\":\"3889.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with the legs in a frog position that works the abs and hip flexors.\"},{\"id\":\"0461\",\"n\":\"frog squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"calves\"],\"st\":[\"Stand with your feet wider than shoulders and your toes turned out.\",\"Lower into a deep squat with your hands between your knees.\",\"Explode up into a jump.\",\"Land softly back in the deep squat.\",\"Keep your chest up and your knees out.\",\"Rest briefly between sets.\"],\"img\":\"0461.webp\",\"gif\":\"0461.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A wide squat that finishes with a jump, landing back in a deep position like a frog. It builds leg power and endurance.\"},{\"id\":\"3703\",\"n\":\"frogger\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"core\",\"shoulders\"],\"st\":[\"Start in a deep squat with your hands on the floor.\",\"Jump or step your feet back into a plank.\",\"Hop your feet to the outside of your hands.\",\"Stand up or jump up from the squat.\",\"Repeat at a steady quick pace.\"],\"img\":\"3703.webp\",\"gif\":\"3703.mp4\",\"cat\":\"cardio\",\"desc\":\"A fast floor drill where you hop your feet out and in from a squat to a plank. It works your legs, core and heart at once.\"},{\"id\":\"0462\",\"n\":\"front and back neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Slowly lower your chin toward your chest until you feel a stretch at the back of the neck.\",\"Hold for 20-30 seconds.\",\"Raise your head and slowly tip it back to look up.\",\"Hold for 20-30 seconds, staying comfortable.\",\"Move slowly and keep your breathing relaxed.\"],\"img\":\"0462.webp\",\"gif\":\"0462.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle neck stretch where you tip your head forward and then back to loosen the front and back of the neck.\"},{\"id\":\"1563\",\"n\":\"front back leg raises\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall next to a wall or support and hold on with one hand.\",\"Swing your outside leg forward with a straight knee.\",\"Swing it back behind you, squeezing your glute.\",\"Keep your torso upright and avoid arching your lower back.\",\"Do all reps on one side, then turn around and switch legs.\"],\"img\":\"1563.webp\",\"gif\":\"1563.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing leg swing forward and backward, loosening the hips. A nice warm-up for the hips and hamstrings.\"},{\"id\":\"2101\",\"n\":\"front cross over shin stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Stand tall and cross one leg in front of the other.\",\"Point the toes of the back foot against the floor and gently bend the knee until the shin and ankle stretch.\",\"Hold a wall or chair for balance.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2101.webp\",\"gif\":\"2101.mp4\",\"cat\":\"stretching\",\"desc\":\"Crossing one foot in front and pressing the toes down to stretch the front of the shin.\"},{\"id\":\"2303\",\"n\":\"front groin kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Lift your knee in front of you.\",\"Snap the lower leg forward and low.\",\"Keep your torso upright and balanced.\",\"Pull the leg back quickly.\",\"Return to stance and repeat, then switch legs.\"],\"img\":\"2303.webp\",\"gif\":\"2303.mp4\",\"cat\":\"combat\",\"desc\":\"A straight forward kick aimed low with the toes or the instep, practising speed and hip flexor power.\"},{\"id\":\"4585\",\"n\":\"front groin kick kickboxing (with boxing bag)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\",\"calves\"],\"st\":[\"Stand in a fighting stance facing the bag with hands up.\",\"Lift your rear knee toward your chest.\",\"Extend your leg and drive the ball of your foot into the bag.\",\"Lean back slightly to stay balanced.\",\"Pull your leg back quickly.\",\"Return to your stance and switch sides.\"],\"img\":\"4585.webp\",\"gif\":\"4585.mp4\",\"cat\":\"combat\",\"desc\":\"A straight front kick thrown low at a bag, training leg power and balance.\"},{\"id\":\"3468\",\"n\":\"front hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Place one heel forward on the floor with the toes up.\",\"Keep that leg straight.\",\"Hinge at the hips with a flat back.\",\"Feel the stretch behind your thigh.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"3468.webp\",\"gif\":\"3468.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple stretch for the back of the thigh.\"},{\"id\":\"4586\",\"n\":\"front kick kickboxing (with boxing bag)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\",\"calves\"],\"st\":[\"Stand in a fighting stance facing the bag.\",\"Lift your rear knee up in front of you.\",\"Extend your leg and push your heel or ball of your foot into the bag.\",\"Lean back slightly and keep your guard up.\",\"Pull the leg back to bend it.\",\"Plant your foot and switch sides.\"],\"img\":\"4586.webp\",\"gif\":\"4586.mp4\",\"cat\":\"combat\",\"desc\":\"A front push kick aimed at a bag that builds leg power, balance and hip flexibility.\"},{\"id\":\"4594\",\"n\":\"front kick kickboxing (with partner)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\",\"calves\"],\"st\":[\"Face your partner, who holds a kick pad at body height.\",\"Stand in a fighting stance with hands up.\",\"Raise your rear knee in front of you.\",\"Extend your leg and push the ball of your foot into the pad.\",\"Pull your leg back quickly.\",\"Switch sides after your reps.\"],\"img\":\"4594.webp\",\"gif\":\"4594.mp4\",\"cat\":\"combat\",\"desc\":\"A front push kick aimed at a partner's pad, training leg power, balance and timing.\"},{\"id\":\"4595\",\"n\":\"front knee kick kickboxing (with partner)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"lower abs\",\"core\"],\"st\":[\"Face your partner, who holds a pad at waist height.\",\"Stand in a fighting stance with hands up.\",\"Drive your rear knee up and forward into the pad.\",\"Rise slightly onto the toes of your standing foot.\",\"Keep your torso upright.\",\"Lower the leg and switch sides.\"],\"img\":\"4595.webp\",\"gif\":\"4595.mp4\",\"cat\":\"combat\",\"desc\":\"A knee strike driven forward into a partner's pad, working the thighs, hips and core.\"},{\"id\":\"2302\",\"n\":\"front leg hook kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Lift the lead knee and point it forward.\",\"Extend the leg and hook the heel across the target.\",\"Keep your supporting foot grounded and your core tight.\",\"Bring the leg back under control.\",\"Return to stance and repeat, then switch sides.\"],\"img\":\"2302.webp\",\"gif\":\"2302.mp4\",\"cat\":\"combat\",\"desc\":\"A hooking kick with the lead leg that swings the heel across the target, building balance and hip control.\"},{\"id\":\"6013\",\"n\":\"front leg kick\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall with your arms at your sides.\",\"Kick one straight leg up in front of you.\",\"Lower it under control.\",\"Switch legs in a smooth rhythm.\",\"Keep your torso upright.\"],\"img\":\"6013.webp\",\"gif\":\"6013.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A dynamic kick that warms up the hamstrings and hip flexors and builds coordination.\"},{\"id\":\"6094\",\"n\":\"front leg lift under knee tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"core\"],\"st\":[\"Stand tall with your feet hip-width apart and your hands out in front.\",\"Lift one knee up and forward to hip height.\",\"Reach both hands under that thigh and tap beneath the knee.\",\"Lower the foot with control and switch legs.\",\"Keep your chest up and stay light on your feet.\",\"Alternate sides at a steady, bouncy pace.\"],\"img\":\"6094.webp\",\"gif\":\"6094.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A standing move where you drive a knee up and tap beneath it with your hands. It warms up the hips and works the abs.\",\"fv\":\"5602\"},{\"id\":\"0463\",\"n\":\"front plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Lie face down and prop yourself on your forearms, elbows under your shoulders.\",\"Lift your hips and knees off the floor, resting on your toes.\",\"Keep your body in a straight line from head to heels.\",\"Squeeze your abs and glutes.\",\"Hold for 20-60 seconds while breathing steadily.\",\"Don't let your hips sag or pike up.\"],\"img\":\"0463.webp\",\"gif\":\"0463.mp4\",\"cat\":\"isometric\",\"desc\":\"The classic forearm plank. Holding a straight line from head to heels builds core endurance and stability.\",\"hd\":1,\"fv\":\"0465\"},{\"id\":\"2347\",\"n\":\"front plank butt (form check)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"shoulders\",\"lower back\"],\"st\":[\"Place your forearms on the floor with elbows under your shoulders.\",\"Extend your legs behind you with your toes on the floor.\",\"Lift your body into a straight line from head to heels.\",\"Avoid pushing your butt up or letting your hips sag.\",\"Squeeze your abs and glutes to keep the line.\",\"Hold for 20-40 seconds and breathe steadily.\"],\"img\":\"2347.webp\",\"gif\":\"2347.mp4\",\"cat\":\"isometric\",\"desc\":\"A front plank form check that compares a raised butt with a straight body line.\"},{\"id\":\"3750\",\"n\":\"front plank side hop\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\",\"hip flexors\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Brace your core.\",\"Hop both feet a short way to one side.\",\"Hop them back to the other side.\",\"Keep your shoulders stable and your hips low.\"],\"img\":\"3750.webp\",\"gif\":\"3750.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Hop your feet side to side from a high plank for a core and cardio challenge.\"},{\"id\":\"2890\",\"n\":\"front plank to push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a forearm plank with elbows under shoulders.\",\"Place one hand on the floor and press up, then the other.\",\"Reach a high plank with straight arms.\",\"Lower back to your forearms one arm at a time.\",\"Alternate the leading arm each rep and keep your hips level.\"],\"img\":\"2890.webp\",\"gif\":\"2890.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A move that moves from forearm plank to full push-up position, training the chest, arms and core.\"},{\"id\":\"4023\",\"n\":\"front plank to toe tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"glutes\",\"obliques\"],\"st\":[\"Start in a front plank with your body in a straight line from head to heels.\",\"Brace your abs and squeeze your glutes.\",\"Lift one foot and tap the toes out to the side without twisting your hips.\",\"Bring the foot back to the start.\",\"Repeat on the other leg and keep alternating.\"],\"img\":\"4023.webp\",\"gif\":\"4023.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A forearm or high plank where you reach a foot out to tap the floor. It trains core stability and hip control.\"},{\"id\":\"3814\",\"n\":\"front plank toe tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Brace your abs and keep your hips level.\",\"Tap one toe out to the side and bring it back.\",\"Repeat with the other foot.\",\"Keep your body steady and avoid rocking.\"],\"img\":\"3814.webp\",\"gif\":\"3814.mp4\",\"cat\":\"isometric\",\"desc\":\"A front plank where you tap one foot out to the side at a time. It challenges core stability and hips.\"},{\"id\":\"3854\",\"n\":\"front plank walkout\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"hip flexors\",\"chest\"],\"st\":[\"Stand tall with your feet hip width apart.\",\"Hinge forward and place your hands on the floor.\",\"Walk your hands out to a front plank.\",\"Hold briefly with your hips level.\",\"Walk your hands back and stand up.\"],\"img\":\"3854.webp\",\"gif\":\"3854.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From standing, you walk your hands out to a plank and back. It trains your core, shoulders and hamstring flexibility.\"},{\"id\":\"5466\",\"n\":\"front plank with arm and leg lift (form check)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"lower back\"],\"st\":[\"Start in a forearm or high plank with your body in a straight line.\",\"Brace your abs and squeeze your glutes.\",\"Lift one arm forward and the opposite leg back.\",\"Hold for a couple of seconds.\",\"Return and switch sides.\",\"Keep your hips level.\"],\"img\":\"5466.webp\",\"gif\":\"5466.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank where you lift an arm and the opposite leg. Challenges your core stability.\",\"fv\":\"2896\"},{\"id\":\"2897\",\"n\":\"front plank with arm and leg lift (push up position)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Lift one arm and the opposite leg at the same time.\",\"Hold them in line with your body for a moment.\",\"Lower them back to the floor with control.\",\"Switch to the other arm and leg and repeat.\"],\"img\":\"2897.webp\",\"gif\":\"2897.mp4\",\"cat\":\"isometric\",\"desc\":\"A high plank holding the opposite arm and leg in the air, which tests balance and core strength.\"},{\"id\":\"2894\",\"n\":\"front plank with arm lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Set up in a forearm plank with elbows under shoulders.\",\"Squeeze your glutes and keep a straight line from head to heels.\",\"Lift one arm forward without letting your hips twist.\",\"Return it and lift the other arm.\",\"Alternate in a slow, controlled rhythm.\"],\"img\":\"2894.webp\",\"gif\":\"2894.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank where one arm lifts at a time, challenging core stability and anti-rotation.\"},{\"id\":\"2895\",\"n\":\"front plank with arm lift (push up position)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Set your feet slightly wider for balance.\",\"Lift one hand and reach it forward without twisting your hips.\",\"Place it down and switch arms.\",\"Keep your core braced throughout.\"],\"img\":\"2895.webp\",\"gif\":\"2895.mp4\",\"cat\":\"isometric\",\"desc\":\"A high plank where you lift one arm at a time, training anti-rotation core strength.\"},{\"id\":\"3501\",\"n\":\"front plank with leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Set up in a forearm plank with elbows under your shoulders.\",\"Keep your body in a straight line.\",\"Lift one leg a few inches without rotating your hips.\",\"Lower it and lift the other leg.\",\"Keep your core tight and your hips level.\",\"Breathe steadily.\"],\"img\":\"3501.webp\",\"gif\":\"3501.mp4\",\"cat\":\"isometric\",\"desc\":\"A forearm plank with alternating leg lifts. It builds core stability and glute strength.\",\"fv\":\"2898\"},{\"id\":\"2305\",\"n\":\"front snap kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Lift your knee toward your chest.\",\"Snap your lower leg forward to the target.\",\"Pull the leg back quickly along the same line.\",\"Keep your supporting foot grounded.\",\"Return to stance and repeat, then switch legs.\"],\"img\":\"2305.webp\",\"gif\":\"2305.mp4\",\"cat\":\"combat\",\"desc\":\"A quick forward kick that snaps out from the knee, building leg speed and balance.\"},{\"id\":\"4587\",\"n\":\"front snap kick kickboxing (with boxing bag)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand in a fighting stance facing the bag.\",\"Raise your knee quickly.\",\"Snap your lower leg out to hit the bag with the ball of your foot.\",\"Recoil right away to bend the knee again.\",\"Keep your hands up.\",\"Set your foot down and switch sides.\"],\"img\":\"4587.webp\",\"gif\":\"4587.mp4\",\"cat\":\"combat\",\"desc\":\"A quick snapping front kick at a bag that trains speed and control in the thigh and hip.\"},{\"id\":\"4596\",\"n\":\"front snap kick kickboxing (with partner)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Face your partner, who holds a pad at body height.\",\"Raise your knee quickly.\",\"Snap your lower leg out to hit the pad with the ball of your foot.\",\"Recoil right away to bend the knee again.\",\"Keep your hands up.\",\"Set your foot down and switch sides.\"],\"img\":\"4596.webp\",\"gif\":\"4596.mp4\",\"cat\":\"combat\",\"desc\":\"A quick snapping front kick into a partner's pad that trains speed and leg control.\"},{\"id\":\"3954\",\"n\":\"front to side plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Start in a front plank on your forearms or hands.\",\"Rotate your body to one side, lifting one arm up.\",\"Hold briefly in a side plank.\",\"Return to the front plank.\",\"Alternate sides.\"],\"img\":\"3954.webp\",\"gif\":\"3954.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Rotate from a front plank into a side plank to train the core.\"},{\"id\":\"3248\",\"n\":\"front toe touching\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"obliques\"],\"st\":[\"Stand with feet hip-width apart.\",\"Hinge forward and reach toward your toes.\",\"Let your head hang relaxed.\",\"Rise slowly.\",\"Repeat at a steady pace.\"],\"img\":\"3248.webp\",\"gif\":\"3248.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing movement reaching down to touch your toes for a warm-up of the hamstrings and back.\"},{\"id\":\"1483\",\"n\":\"full lotus yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"groin\",\"sm\":[\"groin\",\"ankles\",\"hip flexors\"],\"st\":[\"Sit tall on the floor with your legs extended.\",\"Bring one foot onto the opposite thigh, then the other foot on top of the other thigh.\",\"Only go as far as your hips allow, and never force your knees.\",\"Rest your hands on your knees and lengthen your spine.\",\"Hold for 20-30 seconds with calm breathing, then switch the leg order next time.\"],\"img\":\"1483.webp\",\"gif\":\"1483.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated yoga posture with both feet resting on opposite thighs. It opens the hips and needs good flexibility.\"},{\"id\":\"3500\",\"n\":\"full squat mobility\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hip flexors\",\"ankles\",\"lower back\"],\"st\":[\"Stand with feet slightly wider than your shoulders, toes turned out.\",\"Lower into a deep squat, keeping your heels down.\",\"Press your elbows against your inner knees with hands together.\",\"Shift gently side to side and hold the bottom.\",\"Keep your chest lifted.\",\"Stand up slowly.\"],\"img\":\"3500.webp\",\"gif\":\"3500.mp4\",\"cat\":\"mobility\",\"desc\":\"A deep squat hold with gentle movement to open the hips, ankles and lower back.\"},{\"id\":\"0951\",\"n\":\"garland pose malasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"groin\",\"ankles\",\"lower back\"],\"st\":[\"Stand with feet slightly wider than hips and toes turned out.\",\"Lower into a deep squat, keeping your heels down if you can.\",\"Bring your palms together at your chest.\",\"Press your elbows against your inner knees and lengthen your spine.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0951.webp\",\"gif\":\"0951.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep squat with elbows pressing the knees apart and palms together. It stretches the hips, groin and ankles.\"},{\"id\":\"2473\",\"n\":\"glute bridge one leg on bench\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one foot on a bench and the other leg extended.\",\"Brace your core.\",\"Push through the planted heel to lift your hips.\",\"Keep your hips level.\",\"Squeeze your glute at the top.\",\"Finish your reps, then switch legs.\"],\"img\":\"2473.webp\",\"gif\":\"2473.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg bridge with a foot on a bench that targets the glutes harder.\"},{\"id\":\"2475\",\"n\":\"glute bridge one leg on floor (bent knee)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one foot on the floor and the other knee pulled up.\",\"Place your arms by your sides.\",\"Push through the planted heel to lift your hips.\",\"Keep your pelvis level.\",\"Squeeze your glute at the top.\",\"Finish your reps, then switch legs.\"],\"img\":\"2475.webp\",\"gif\":\"2475.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg bridge with the free knee bent toward your chest.\"},{\"id\":\"2474\",\"n\":\"glute bridge one leg on floor (straight leg)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one knee bent and the other leg straight up.\",\"Keep your arms by your sides.\",\"Push through your planted heel to lift your hips.\",\"Keep your hips level.\",\"Squeeze your glute at the top.\",\"Finish your reps, then switch legs.\"],\"img\":\"2474.webp\",\"gif\":\"2474.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg bridge with the free leg straight, working the glutes and core.\"},{\"id\":\"2471\",\"n\":\"glute bridge two legs on floor\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Place your arms by your sides.\",\"Push through your heels to lift your hips.\",\"Make a straight line from shoulders to knees.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2471.webp\",\"gif\":\"2471.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor bridge with both feet down that strengthens the glutes and hamstrings.\"},{\"id\":\"6570\",\"n\":\"glute bridge walk\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Lift your hips into a glute bridge.\",\"Keep the hips high and walk your feet out a few small steps.\",\"Then walk them back in toward your body.\",\"Keep your hips level and avoid sagging.\",\"Lower with control when finished.\"],\"img\":\"6570.webp\",\"gif\":\"6570.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge held high while stepping the feet out and back. It adds a dynamic challenge for glutes and hamstrings.\"},{\"id\":\"10639\",\"n\":\"glute ham developer full sit up\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"glutes\"],\"st\":[\"Lock your feet in the machine and sit with your hips on the pad.\",\"Lean back until your torso is in line with or just below your hips.\",\"Cross your arms over your chest.\",\"Curl up until your chest reaches your thighs.\",\"Lower back slowly with a braced core.\",\"Avoid yanking on your neck.\"],\"img\":\"10639.webp\",\"gif\":\"10639.mp4\",\"cat\":\"strength\",\"desc\":\"A full-range sit-up on a glute ham developer. The extended range makes the abs and hip flexors work through a long path.\"},{\"id\":\"4762\",\"n\":\"glute ham developer hip extension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Set up on the GHD with your feet planted and hips just past the pad.\",\"Cross your arms over your chest.\",\"Lower your torso by hinging at the hips with a flat back.\",\"Squeeze your glutes to raise back to a straight line.\",\"Do not arch past neutral at the top.\"],\"img\":\"4762.webp\",\"gif\":\"4762.mp4\",\"cat\":\"strength\",\"desc\":\"A hip extension on a glute ham developer. You hinge at the hips with a straight body to work the glutes and hamstrings.\"},{\"id\":\"4763\",\"n\":\"glute ham developer sit up and russian twist\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lock your feet in the GHD and lie back with arms crossed or hands clasped.\",\"Sit up in a controlled way.\",\"At the top, rotate your torso to one side.\",\"Return to the middle and lower back down.\",\"Alternate the twist side each rep.\"],\"img\":\"4763.webp\",\"gif\":\"4763.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up on the glute ham developer ending with a twist. It trains the abs and the obliques.\"},{\"id\":\"11282\",\"n\":\"glute ham developer straight arms sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Set up on the GHD with your feet secured and hips on the pad.\",\"Extend your arms overhead and lean back.\",\"Curl up, bringing your arms forward.\",\"Reach your torso over your knees.\",\"Lower slowly with control.\"],\"img\":\"11282.webp\",\"gif\":\"11282.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up on a glute ham developer with your arms extended. The longer range makes your abs work harder.\"},{\"id\":\"4764\",\"n\":\"glute ham hyperextension twist\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"obliques\"],\"st\":[\"Position yourself on the bench with hips on the pad and feet locked in.\",\"Cross your arms on your chest.\",\"Lower your torso with a straight back.\",\"Raise up to a straight line and rotate your torso to one side.\",\"Untwist, lower, and alternate sides.\"],\"img\":\"4764.webp\",\"gif\":\"4764.mp4\",\"cat\":\"strength\",\"desc\":\"A hyperextension on the glute ham bench with a twist at the top. It works the lower back, glutes and obliques.\"},{\"id\":\"4456\",\"n\":\"glute ham raise v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"calves\",\"core\"],\"st\":[\"Set your feet on the platform with your thighs against the pad and knees just behind it.\",\"Start with your torso hanging down and your body straight.\",\"Curl your body up by bending your knees and squeezing your hamstrings.\",\"Finish with hips extended and torso upright.\",\"Lower slowly with control, keeping your hips locked.\",\"Repeat for reps.\"],\"img\":\"4456.webp\",\"gif\":\"4456.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A posterior chain exercise on a glute ham bench. Works the hamstrings and glutes through a long range of motion.\",\"fv\":\"5777\"},{\"id\":\"4890\",\"n\":\"glute ham raise with extended arms\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"calves\"],\"st\":[\"Set up on the glute ham bench with your ankles locked in and thighs supported.\",\"Extend your arms straight out in front of you.\",\"Lower your torso toward the floor with a straight body.\",\"Squeeze your hamstrings and glutes to pull yourself back up.\",\"Stop when your body is in a straight line.\",\"Move slowly and avoid arching your lower back.\"],\"img\":\"4890.webp\",\"gif\":\"4890.mp4\",\"cat\":\"strength\",\"desc\":\"A glute ham raise performed with the arms stretched out in front, making the lift harder. It strongly trains the hamstrings and glutes.\"},{\"id\":\"4765\",\"n\":\"glute ham single leg hyperextension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Set up on the bench with one foot planted and the other lifted behind you.\",\"Cross your arms over your chest.\",\"Lower your torso with a flat back.\",\"Raise to a straight line, squeezing your glute.\",\"Finish the reps, then switch legs.\"],\"img\":\"4765.webp\",\"gif\":\"4765.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hyperextension on the glute ham bench. It strengthens the glutes and hamstrings and the lower back.\"},{\"id\":\"6554\",\"n\":\"glute ham sit up\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"quadriceps\"],\"st\":[\"Set your feet under the pads of a glute ham bench, hips on the support.\",\"Cross your arms over your chest and lean back to a comfortable depth.\",\"Brace your abs and curl up until your torso is upright.\",\"Pause briefly at the top.\",\"Lower slowly under control.\",\"Keep your lower back from over-arching at the bottom.\"],\"img\":\"6554.webp\",\"gif\":\"6554.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up on a glute ham bench. The extra range of motion works the abs and hip flexors hard.\"},{\"id\":\"5051\",\"n\":\"glute ham twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hamstrings\",\"lower back\"],\"st\":[\"Lie on your back with knees bent, feet flat and arms out wide.\",\"Lift your hips into a bridge.\",\"Rotate your knees and hips to one side.\",\"Return to center and rotate to the other side.\",\"Stay controlled and keep your shoulders on the floor.\"],\"img\":\"5051.webp\",\"gif\":\"5051.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hips lifted into a bridge, you twist from side to side. It trains the trunk rotators and glutes.\"},{\"id\":\"3394\",\"n\":\"glute march\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Lift your hips into a bridge.\",\"Raise one knee toward your chest without letting your hips drop.\",\"Place that foot down and lift the other.\",\"Keep squeezing your glutes the whole time.\",\"Continue alternating for 10-20 marches.\"],\"img\":\"3394.webp\",\"gif\":\"3394.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip-bridge hold with alternating knee lifts that trains glutes and pelvic stability.\"},{\"id\":\"4547\",\"n\":\"good morning squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and hands behind your head.\",\"Push your hips back and hinge forward with a flat back.\",\"Come back up to standing.\",\"Bend your knees and sink into a squat with your chest tall.\",\"Stand up and repeat the hinge, then the squat.\",\"Keep your core braced and your weight over your mid-foot.\"],\"img\":\"4547.webp\",\"gif\":\"4547.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A combo of a hip hinge and a squat that warms up and strengthens the glutes, hamstrings and lower back.\"},{\"id\":\"0468\",\"n\":\"grasshopper push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"hip flexors\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Lower your chest toward the floor and bring one knee toward the opposite elbow.\",\"Push back up while returning the leg.\",\"Repeat with the other leg.\",\"Keep your core tight.\",\"Move at a steady pace.\"],\"img\":\"0468.webp\",\"gif\":\"0468.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where one knee swings under the body toward the opposite elbow. It combines chest work with core and hip mobility.\"},{\"id\":\"6300\",\"n\":\"half boat pose ardha navasana\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"quadriceps\"],\"st\":[\"Sit with knees bent and lean back a little.\",\"Lift your feet so your shins are parallel to the floor.\",\"Extend your arms forward.\",\"Keep your chest open and spine long.\",\"Hold for 15-30 seconds.\"],\"img\":\"6300.webp\",\"gif\":\"6300.mp4\",\"cat\":\"yoga\",\"desc\":\"A V-shaped balance on your sit bones. It strengthens the abs and hip flexors.\"},{\"id\":\"6294\",\"n\":\"half frog pose ardha bhekasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"chest\",\"shoulders\",\"core\"],\"st\":[\"Lie on your belly, propped on your forearms.\",\"Bend one knee and reach back to hold that foot.\",\"Gently press the foot toward your hip.\",\"Keep your hips grounded.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"6294.webp\",\"gif\":\"6294.mp4\",\"cat\":\"yoga\",\"desc\":\"A prone backbend with one foot pulled toward your hip. It stretches the quads and hip flexors.\"},{\"id\":\"10592\",\"n\":\"half kneeling hamstrings stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"lower back\"],\"st\":[\"Kneel on one knee with the other leg extended, heel on the floor.\",\"Keep your toes pointing up.\",\"Hinge forward from your hips with a flat back.\",\"Hold for 20-30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"10592.webp\",\"gif\":\"10592.mp4\",\"cat\":\"stretching\",\"desc\":\"From half kneeling, straighten the front leg and lean forward to stretch the hamstring. It lengthens the back of the thigh.\"},{\"id\":\"2935\",\"n\":\"half kneeling pvc pec mobilization stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Kneel on one knee and grip a pipe or stick with one hand while the other arm reaches out.\",\"Place the working forearm against a wall or post.\",\"Gently rotate your torso away until you feel a stretch across your chest.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"2935.webp\",\"gif\":\"2935.mp4\",\"cat\":\"stretching\",\"desc\":\"A chest opener using a PVC pipe from a half-kneeling position. It loosens tight pecs and the front of the shoulder.\"},{\"id\":\"8987\",\"n\":\"half kneeling side lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"glutes\",\"quadriceps\"],\"st\":[\"Start in a half kneeling position with one knee down and the other foot forward.\",\"Turn your front foot out to the side.\",\"Shift your hips sideways toward the straight leg.\",\"Keep your chest up and feel the inner thigh open.\",\"Return to the center with control.\",\"Do all reps, then switch sides.\"],\"img\":\"8987.webp\",\"gif\":\"8987.mp4\",\"cat\":\"mobility\",\"desc\":\"From a half kneeling position you shift your weight sideways to open the hips and inner thigh. It builds hip mobility.\"},{\"id\":\"10566\",\"n\":\"half kneeling torso twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"glutes\",\"upper back\"],\"st\":[\"Kneel on one knee with the other foot forward.\",\"Hold your arms crossed in front of your chest.\",\"Rotate your upper body toward the front leg.\",\"Return to the centre and keep your hips square.\",\"Finish your reps, then switch sides.\"],\"img\":\"10566.webp\",\"gif\":\"10566.mp4\",\"cat\":\"mobility\",\"desc\":\"From a half-kneeling stance, rotate your torso. It opens the spine and warms up the trunk.\"},{\"id\":\"0952\",\"n\":\"half moon pose ardha chandrasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"core\",\"hamstrings\",\"shoulders\"],\"st\":[\"Start in a wide-legged stance and turn one foot out.\",\"Bend over that leg and place your hand on the floor or a block ahead of the foot.\",\"Lift the back leg until it is parallel to the floor.\",\"Open your chest and stack your hips, reaching the top arm up.\",\"Hold for a few breaths, then lower and switch sides.\"],\"img\":\"0952.webp\",\"gif\":\"0952.mp4\",\"cat\":\"yoga\",\"desc\":\"Balance on one leg with the torso and top leg extended sideways. It strengthens the standing leg and hips and tests your balance.\"},{\"id\":\"6761\",\"n\":\"half pigeon hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"lower back\"],\"st\":[\"Start on all fours and bring one knee forward behind your wrist.\",\"Slide the other leg straight back.\",\"Square your hips to the floor.\",\"Fold forward gently over the front leg.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch sides.\"],\"img\":\"6761.webp\",\"gif\":\"6761.mp4\",\"cat\":\"stretching\",\"desc\":\"A floor stretch with one shin folded in front. It opens the outer hip and glutes.\"},{\"id\":\"6443\",\"n\":\"half seated leg circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"adductors\"],\"st\":[\"Sit on the floor leaning back slightly on your hands.\",\"Lift one leg a little off the floor.\",\"Draw slow circles in the air with that foot.\",\"Keep your core engaged and your torso steady.\",\"Switch directions, then switch legs.\"],\"img\":\"6443.webp\",\"gif\":\"6443.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated leg circles that loosen up your hips and gently work the muscles around them.\"},{\"id\":\"6006\",\"n\":\"half squat side reach\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"quadriceps\",\"glutes\"],\"st\":[\"Stand with feet wider than shoulder-width.\",\"Sit into a half squat.\",\"Reach one arm overhead and lean sideways.\",\"Return to center.\",\"Reach to the other side.\",\"Keep your chest up.\"],\"img\":\"6006.webp\",\"gif\":\"6006.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A half squat with a side bend that trains the obliques and legs while loosening the trunk.\",\"fv\":\"5937\"},{\"id\":\"5982\",\"n\":\"half sun salutation\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Stand in mountain pose and sweep your arms overhead.\",\"Fold forward with a long spine.\",\"Lift halfway up with a flat back.\",\"Fold again and rise up with your arms overhead.\",\"Lower your hands to your heart and repeat.\"],\"img\":\"5982.webp\",\"gif\":\"5982.mp4\",\"cat\":\"yoga\",\"desc\":\"A shortened sun salutation that keeps the upright flow. Gently warms the spine and legs.\"},{\"id\":\"1248\",\"n\":\"half wipers (bent leg)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your arms out to the sides for support.\",\"Lift your knees to 90 degrees.\",\"Lower both knees to one side, stopping before the floor.\",\"Bring them back to the middle and go to the other side.\",\"Keep your shoulders on the floor.\"],\"img\":\"1248.webp\",\"gif\":\"1248.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back and swinging bent legs side to side. It trains the obliques and lower abs.\"},{\"id\":\"1865\",\"n\":\"hammer grip pull up on dip cage\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"forearms\"],\"st\":[\"Grab the neutral grip handles with your palms facing each other.\",\"Hang with your arms fully extended.\",\"Pull your chest toward the handles by driving your elbows down.\",\"Pause with your chin above the bars.\",\"Lower slowly to a full hang.\"],\"img\":\"1865.webp\",\"gif\":\"1865.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull-up with palms facing each other on the dip cage handles, hitting the lats and arms.\",\"fv\":\"3898\"},{\"id\":\"8358\",\"n\":\"hamstring bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with knees bent and heels placed a bit farther from your hips.\",\"Press your heels into the floor.\",\"Lift your hips until your body forms a straight line from shoulders to knees.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"8358.webp\",\"gif\":\"8358.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bridge with the heels placed farther away so the hamstrings and glutes do more of the lifting.\"},{\"id\":\"10905\",\"n\":\"hamstring bridge leg kick v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and heels on the floor.\",\"Lift your hips into a bridge.\",\"Straighten one leg out in front, keeping hips level.\",\"Bring the foot back to the floor without dropping your hips.\",\"Alternate legs or finish one side first.\"],\"img\":\"10905.webp\",\"gif\":\"10905.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hamstring bridge with an added leg extension. It adds a balance challenge for hips and thighs.\"},{\"id\":\"10904\",\"n\":\"hamstring bridge v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and heels on the floor, a bit further from your hips.\",\"Press through your heels.\",\"Lift your hips until your body forms a straight line from shoulders to knees.\",\"Squeeze your hamstrings and glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"10904.webp\",\"gif\":\"10904.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bridge with heels planted that emphasises the back of the thighs. Good for the hamstrings and glutes.\"},{\"id\":\"1406\",\"n\":\"hamstring lying stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"lower back\"],\"st\":[\"Lie on your back with both legs extended.\",\"Raise one leg and hold behind the thigh or calf.\",\"Gently straighten the knee while pulling the leg toward you.\",\"Keep your other leg flat and your back relaxed.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1406.webp\",\"gif\":\"1406.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple lying hamstring stretch that eases tightness at the back of the thigh.\"},{\"id\":\"0470\",\"n\":\"hand opposite knee crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and your hands behind your head.\",\"Lift your shoulders and bring one knee up.\",\"Reach the opposite hand toward that knee.\",\"Lower and repeat on the other side.\",\"Keep your lower back on the floor.\",\"Do not pull on your neck.\"],\"img\":\"0470.webp\",\"gif\":\"0470.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where you bring a hand toward the opposite knee. It works the abs and the obliques.\"},{\"id\":\"3345\",\"n\":\"hand spring wrist curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\",\"hands\"],\"st\":[\"Sit with a forearm resting on your thigh or a bench, palm up.\",\"Hold the hand spring in that hand.\",\"Squeeze the handles together by curling your wrist and fingers.\",\"Hold briefly at full squeeze.\",\"Release slowly, finish your reps, then switch hands.\"],\"img\":\"3345.webp\",\"gif\":\"3345.mp4\",\"cat\":\"strength\",\"desc\":\"A wrist curl using a hand grip spring, strengthening your forearms and grip.\"},{\"id\":\"3834\",\"n\":\"handboard half crimp\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"hands\",\"shoulders\"],\"st\":[\"Place your fingers on the edge with the knuckles bent at about 90 degrees.\",\"Step off and hang with straight arms.\",\"Keep your shoulders engaged.\",\"Hold for 5-10 seconds.\",\"Rest fully between hangs.\"],\"img\":\"3834.webp\",\"gif\":\"3834.mp4\",\"cat\":\"isometric\",\"desc\":\"A hang from a hangboard in a half crimp grip. It builds finger strength for climbing.\",\"hd\":1},{\"id\":\"3836\",\"n\":\"handboard hang with 135 degree elbow\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"biceps\",\"lats\",\"shoulders\"],\"st\":[\"Grip the hold and pull up slightly so your elbows bend to about 135 degrees.\",\"Keep your shoulders back and your core tight.\",\"Hold for 5-10 seconds.\",\"Lower down under control.\",\"Rest before the next hold.\"],\"img\":\"3836.webp\",\"gif\":\"3836.mp4\",\"cat\":\"isometric\",\"desc\":\"A hangboard hold with your elbows bent to about 135 degrees. It builds grip and pulling strength in a partly pulled position.\",\"hd\":1},{\"id\":\"3835\",\"n\":\"handboard hang with 90 degree elbow\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"biceps\",\"lats\",\"shoulders\"],\"st\":[\"Grip the hold and pull yourself up until your elbows are at 90 degrees.\",\"Keep your shoulders back and your core tight.\",\"Hold for 5-10 seconds.\",\"Lower down under control.\",\"Rest before the next hold.\"],\"img\":\"3835.webp\",\"gif\":\"3835.mp4\",\"cat\":\"isometric\",\"desc\":\"A hangboard hold with your elbows bent to 90 degrees. It builds pulling strength and grip.\",\"hd\":1},{\"id\":\"3833\",\"n\":\"handboard open hand grip\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"hands\",\"shoulders\"],\"st\":[\"Grip the edge with fingers extended and a slight arch.\",\"Step off and hang with straight arms.\",\"Keep your shoulders engaged.\",\"Hold for 5-10 seconds.\",\"Lower down and rest before the next hang.\"],\"img\":\"3833.webp\",\"gif\":\"3833.mp4\",\"cat\":\"isometric\",\"desc\":\"A hang from a hangboard using an open hand grip. It builds finger strength with less strain on your joints.\",\"hd\":1},{\"id\":\"3832\",\"n\":\"handboard slope hang\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"lats\",\"shoulders\",\"hands\"],\"st\":[\"Grip the sloped hold with open hands.\",\"Step off the ground and hang with straight arms.\",\"Keep your shoulders active and your core tight.\",\"Hold for 5-10 seconds.\",\"Rest fully, then repeat.\"],\"img\":\"3832.webp\",\"gif\":\"3832.mp4\",\"cat\":\"isometric\",\"desc\":\"A hang from a sloped hangboard hold. It builds finger and forearm strength for climbing.\",\"hd\":1},{\"id\":\"3947\",\"n\":\"hands release push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Lower your whole body to the floor.\",\"Lift your hands off the floor briefly.\",\"Place them back and press up.\",\"Keep your body in a straight line.\"],\"img\":\"3947.webp\",\"gif\":\"3947.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where you lift your hands at the bottom, removing momentum and building chest strength.\"},{\"id\":\"0953\",\"n\":\"hands to feet pada hastasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\",\"core\"],\"st\":[\"Stand with feet hip-width apart.\",\"Hinge at the hips and fold forward with a long spine.\",\"Slide your hands under your feet with palms up, toes on your fingers.\",\"Pull gently to deepen the stretch while keeping your knees slightly soft.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0953.webp\",\"gif\":\"0953.mp4\",\"cat\":\"stretching\",\"desc\":\"Fold forward and slide your hands under your feet. It stretches the hamstrings, calves and back.\"},{\"id\":\"6545\",\"n\":\"handstand hold on wall\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"core\"],\"st\":[\"Place your hands on the floor a short distance from a wall.\",\"Kick up carefully until your heels rest on the wall.\",\"Push the floor away and keep your arms straight.\",\"Tighten your core and glutes.\",\"Hold for 15-30 seconds, then come down with control.\"],\"img\":\"6545.webp\",\"gif\":\"6545.mp4\",\"cat\":\"isometric\",\"desc\":\"A wall-supported handstand held in place, building shoulder strength, balance and body control.\",\"hd\":1,\"fv\":\"6695\"},{\"id\":\"3916\",\"n\":\"handstand shoulder press with wall (between benches)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"trapezius\",\"core\",\"upper chest\"],\"st\":[\"Place your hands on two benches and kick up into a handstand with your heels against the wall.\",\"Brace your core and keep your body straight.\",\"Lower your head between the benches by bending your elbows.\",\"Press back up to straight arms.\",\"Keep the movement controlled.\",\"Come down carefully when done.\"],\"img\":\"3916.webp\",\"gif\":\"3916.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wall-supported handstand press between two benches for strong shoulders and triceps.\"},{\"id\":\"4376\",\"n\":\"handstand walk\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper back\",\"wrist extensors\",\"forearms\"],\"st\":[\"Kick up into a handstand against a wall or with a spotter, hands shoulder-width apart.\",\"Squeeze your glutes and legs together and push tall through your shoulders.\",\"Shift your weight onto one hand and move the other forward a small step.\",\"Alternate hands in short, controlled steps, keeping your core tight.\",\"Come down safely with control, and practise on soft ground.\"],\"img\":\"4376.webp\",\"gif\":\"4376.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced bodyweight skill where you walk on your hands while inverted. It builds shoulder strength, balance and body control.\"},{\"id\":\"5146\",\"n\":\"hangback bar stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"grip muscles\"],\"st\":[\"Hold a bar with an overhand grip.\",\"Lean your body back and let your arms and shoulders lengthen.\",\"Relax your ribs and breathe slowly.\",\"Hold for 20-30 seconds.\",\"Step out of the stretch carefully.\"],\"img\":\"5146.webp\",\"gif\":\"5146.mp4\",\"cat\":\"stretching\",\"desc\":\"Hang from a bar with your body leaning back to stretch your lats and shoulders.\"},{\"id\":\"9044\",\"n\":\"hanging advanced tucked front lever hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"core\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with straight arms.\",\"Lift your body to horizontal in a tucked position.\",\"Open your hips slightly so your back is flat.\",\"Keep your shoulder blades pulled down.\",\"Hold for 5-10 seconds.\",\"Lower down slowly.\"],\"img\":\"9044.webp\",\"gif\":\"9044.mp4\",\"cat\":\"isometric\",\"desc\":\"A harder front lever hold with the knees tucked but the hips open. It demands strong lats and core.\",\"hd\":1},{\"id\":\"10735\",\"n\":\"hanging alternating knee raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"forearms\",\"grip muscles\"],\"st\":[\"Hang from a bar with arms straight.\",\"Brace your core and keep your body still.\",\"Lift one knee toward your chest.\",\"Lower it slowly and lift the other knee.\",\"Avoid swinging.\",\"Alternate for the reps.\"],\"img\":\"10735.webp\",\"gif\":\"10735.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging ab move where you lift one knee at a time. It strengthens the lower abs and hip flexors.\"},{\"id\":\"4373\",\"n\":\"hanging deadbug\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"grip muscles\"],\"st\":[\"Hang from a pull-up bar with a firm grip.\",\"Lift your knees to hip height.\",\"Extend one leg while keeping control of your torso.\",\"Return and switch legs.\",\"Avoid swinging.\"],\"img\":\"4373.webp\",\"gif\":\"4373.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging variation of the dead bug, extending opposite arm and leg. It builds core control.\"},{\"id\":\"4766\",\"n\":\"hanging flutter kick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"forearms\",\"grip muscles\"],\"st\":[\"Hang from a pull-up bar with arms straight.\",\"Tighten your core and lift your legs slightly in front of you.\",\"Kick your legs up and down in alternating small movements.\",\"Keep your swing minimal.\",\"Continue for the set time or reps.\"],\"img\":\"4766.webp\",\"gif\":\"4766.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you alternate small, fast kicks with straight legs. It trains the lower abs and grip.\"},{\"id\":\"9045\",\"n\":\"hanging front lever hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"core\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with an overhand grip.\",\"Pull your shoulder blades down and tighten your core.\",\"Raise your whole body to horizontal with your legs straight.\",\"Keep your arms locked and your body in one line.\",\"Hold for as long as you can with good form.\",\"Lower down slowly.\"],\"img\":\"9045.webp\",\"gif\":\"9045.mp4\",\"cat\":\"isometric\",\"desc\":\"The full front lever: a straight horizontal body hold under a bar. It is an advanced test of back and core strength.\",\"hd\":1},{\"id\":\"7251\",\"n\":\"hanging front lever raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"lats\",\"hip flexors\",\"grip muscles\"],\"st\":[\"Hang from a pull-up bar with a firm grip.\",\"Pull your shoulders down and tighten your core.\",\"Raise your straight body up toward horizontal, keeping your arms straight.\",\"Hold the top position for a moment.\",\"Lower slowly without swinging.\"],\"img\":\"7251.webp\",\"gif\":\"7251.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging straight-body raise toward a front lever position that challenges your abs and lats.\"},{\"id\":\"4891\",\"n\":\"hanging half windmill\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"grip muscles\",\"hip flexors\"],\"st\":[\"Hang from a pull-up bar with a firm overhand grip.\",\"Raise both legs together toward one side of the bar.\",\"Sweep them across the front in a half circle.\",\"Lower the legs on the other side under control.\",\"Keep the swing small and your shoulders active.\",\"Repeat, alternating the direction.\"],\"img\":\"4891.webp\",\"gif\":\"4891.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a hang you lift the legs and sweep them to one side in a half circle. It builds oblique strength and grip.\"},{\"id\":\"6547\",\"n\":\"hanging hollow hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"grip muscles\"],\"st\":[\"Grab a pull-up bar with an overhand grip and hang with straight arms.\",\"Brace your abs and tuck your pelvis slightly.\",\"Lift your legs forward a little so your body forms a gentle hollow shape.\",\"Keep your shoulders active and avoid swinging.\",\"Hold the position for as long as you can with good form.\",\"Lower down under control.\"],\"img\":\"6547.webp\",\"gif\":\"6547.mp4\",\"cat\":\"isometric\",\"desc\":\"A hold hanging from a bar with the body in a slight hollow curve. It builds deep abdominal tension and grip.\",\"hd\":1},{\"id\":\"4767\",\"n\":\"hanging knee circle raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"lower abs\",\"grip muscles\"],\"st\":[\"Hang from a bar with arms straight and legs together.\",\"Raise your knees toward your chest.\",\"Move them in a circle to one side and back down.\",\"Keep your body from swinging.\",\"Alternate the circle direction each rep.\"],\"img\":\"4767.webp\",\"gif\":\"4767.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from a bar, you raise your knees in a circular path. It targets the lower abs and obliques.\"},{\"id\":\"9819\",\"n\":\"hanging knee raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"grip muscles\",\"lats\"],\"st\":[\"Hang from a pull-up bar with arms straight.\",\"Brace your abs and avoid swinging.\",\"Raise your knees toward your chest.\",\"Tilt your pelvis up at the top.\",\"Lower slowly and repeat.\"],\"img\":\"9819.webp\",\"gif\":\"9819.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a hang, you bring your knees up toward your chest to work the lower abs.\"},{\"id\":\"3890\",\"n\":\"hanging knees to elbows\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"grip muscles\",\"lats\",\"obliques\"],\"st\":[\"Hang from a pull-up bar with a firm grip.\",\"Brace your core and tuck your knees.\",\"Raise your knees up toward your elbows.\",\"Curl your pelvis up at the top.\",\"Lower slowly without swinging.\",\"Repeat for the desired reps.\"],\"img\":\"3890.webp\",\"gif\":\"3890.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging leg raise where the knees travel up to the elbows, working the abs and hip flexors hard.\"},{\"id\":\"11877\",\"n\":\"hanging l sit\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"forearms\"],\"st\":[\"Hang from a bar with straight arms.\",\"Lift your legs straight in front until they are parallel to the floor.\",\"Keep your toes pointed and your knees locked.\",\"Avoid swinging.\",\"Hold for 10-20 seconds, then lower.\"],\"img\":\"11877.webp\",\"gif\":\"11877.mp4\",\"cat\":\"isometric\",\"desc\":\"A hanging hold with legs straight out in front that challenges the abs and grip.\",\"hd\":1},{\"id\":\"4177\",\"n\":\"hanging scapular shrug\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"lats\",\"sm\":[\"lats\",\"grip muscles\",\"trapezius\"],\"st\":[\"Hang from a pull up bar with straight arms.\",\"Relax your shoulders up toward your ears.\",\"Pull your shoulder blades down, lifting your body slightly.\",\"Pause briefly.\",\"Relax back to the hang.\",\"Keep your elbows straight.\"],\"img\":\"4177.webp\",\"gif\":\"4177.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hang from a bar where you pull your shoulder blades down and up. It strengthens the upper back and improves shoulder control.\"},{\"id\":\"9489\",\"n\":\"hanging side lean\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"grip muscles\"],\"st\":[\"Hang from a pull-up bar with an overhand grip and legs together.\",\"Brace your abs and keep your arms straight.\",\"Lean your legs and hips toward one side, bending through the waist.\",\"Return to centre under control.\",\"Lean to the other side and alternate for the planned reps.\"],\"img\":\"9489.webp\",\"gif\":\"9489.mp4\",\"cat\":\"calisthenics\",\"desc\":\"While hanging from a bar, you lean your body to each side to work the obliques and grip.\"},{\"id\":\"3891\",\"n\":\"hanging toes to bar\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"grip muscles\",\"lats\",\"obliques\"],\"st\":[\"Hang from a bar with a firm grip.\",\"Engage your lats and brace your core.\",\"Raise your straight legs up until your toes touch the bar.\",\"Pause briefly at the top.\",\"Lower your legs with control.\",\"Avoid excessive swinging.\"],\"img\":\"3891.webp\",\"gif\":\"3891.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A tough hanging core move that brings the toes all the way up to the bar.\"},{\"id\":\"9043\",\"n\":\"hanging tucked front lever hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"core\",\"shoulders\"],\"st\":[\"Hang from a pull-up bar with an overhand grip.\",\"Pull your shoulder blades down and tuck your knees to your chest.\",\"Lean back and raise your hips until your back is horizontal.\",\"Keep your arms straight.\",\"Hold for 5-15 seconds.\",\"Lower back down with control.\"],\"img\":\"9043.webp\",\"gif\":\"9043.mp4\",\"cat\":\"isometric\",\"desc\":\"Hanging from a bar, you hold your body horizontal with your knees tucked. It builds lats and core strength.\",\"hd\":1},{\"id\":\"5917\",\"n\":\"happy baby pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"groin\",\"lower back\",\"glutes\"],\"st\":[\"Lie on your back and bend your knees toward your chest.\",\"Hold the outsides of your feet.\",\"Open your knees wide toward your armpits.\",\"Rock gently side to side and hold for 5 slow breaths.\",\"Release your feet and rest.\"],\"img\":\"5917.webp\",\"gif\":\"5917.mp4\",\"cat\":\"yoga\",\"desc\":\"Lying on your back and holding your feet with knees wide. Opens the hips and relaxes the lower back.\"},{\"id\":\"3365\",\"n\":\"hawaiian squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand with feet slightly wider than your shoulders and toes turned out.\",\"Brace your core and keep your chest up.\",\"Sit your hips down and back into a deep squat.\",\"Pause at the bottom without rounding your back.\",\"Drive through your feet to stand up.\"],\"img\":\"3365.webp\",\"gif\":\"3365.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A deep bodyweight squat variation that builds leg strength and hip mobility.\"},{\"id\":\"10736\",\"n\":\"headbanger\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"glutes\",\"hamstrings\"],\"st\":[\"Stand with feet hip-width apart and hands behind your head.\",\"Soften your knees.\",\"Hinge forward at the hips with a flat back.\",\"Nod your head slightly and return to standing.\",\"Move at a smooth pace.\",\"Keep your neck relaxed.\"],\"img\":\"10736.webp\",\"gif\":\"10736.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle bending drill that works the back and hips. The motion loosens your spine and posterior chain.\"},{\"id\":\"3872\",\"n\":\"heel drops\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on the edge of a step with the balls of your feet on it.\",\"Hold a rail for balance.\",\"Rise onto your toes.\",\"Slowly lower your heels below the step level.\",\"Pause and feel the stretch in your calves.\",\"Raise up and repeat.\"],\"img\":\"3872.webp\",\"gif\":\"3872.mp4\",\"cat\":\"mobility\",\"desc\":\"A controlled drop of the heels off a step that stretches and strengthens the calves and ankles.\"},{\"id\":\"6435\",\"n\":\"heel glute bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and heels on the floor, toes lifted.\",\"Keep your arms by your sides.\",\"Press through your heels and raise your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\"],\"img\":\"6435.webp\",\"gif\":\"6435.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bridge with heels pushed into the floor and toes lifted. It biases the glutes and hamstrings.\"},{\"id\":\"5059\",\"n\":\"heel press\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand with the ball of one foot on a low step or wall, heel on the floor.\",\"Hold something for balance.\",\"Press your heel gently down and back.\",\"Keep your knee straight for the calf.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"5059.webp\",\"gif\":\"5059.mp4\",\"cat\":\"stretching\",\"desc\":\"Pressing the heel down toward the floor to lengthen the calf. It helps ankle flexibility.\"},{\"id\":\"2309\",\"n\":\"heel push kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Lift the knee and point the toes up.\",\"Push your heel straight forward, leaning back slightly.\",\"Keep your supporting foot grounded.\",\"Bring the leg back and set it down.\",\"Repeat, then switch legs.\"],\"img\":\"2309.webp\",\"gif\":\"2309.mp4\",\"cat\":\"combat\",\"desc\":\"A pushing front kick that drives the heel forward to create distance, working hips and quads.\"},{\"id\":\"5970\",\"n\":\"heel to toe walk\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"core\",\"glutes\"],\"st\":[\"Stand tall with your arms out to the sides.\",\"Place your right heel directly in front of your left toes.\",\"Shift your weight forward and step again with the other foot.\",\"Keep your eyes forward and your core gently braced.\",\"Walk 10-15 steps, then turn around and return.\"],\"img\":\"5970.webp\",\"gif\":\"5970.mp4\",\"cat\":\"mobility\",\"desc\":\"A slow line walk with each heel touching the toes of the other foot, which trains balance and steady stride control.\"},{\"id\":\"10294\",\"n\":\"heel walk\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Stand tall with arms relaxed at your sides.\",\"Lift your toes and forefoot off the floor so you balance on your heels.\",\"Walk forward with small, controlled steps.\",\"Keep your toes pulled up the whole time.\",\"Walk for 20-30 seconds, then rest.\"],\"img\":\"10294.webp\",\"gif\":\"10294.mp4\",\"cat\":\"mobility\",\"desc\":\"Walking on your heels with the toes lifted, strengthening the shins and loosening the ankles.\",\"fv\":\"11539\"},{\"id\":\"8956\",\"n\":\"heels squat slide wall\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your back against a wall and your feet a little forward.\",\"Press your heels into the floor.\",\"Slide down the wall until your thighs are near parallel.\",\"Keep your knees tracking over your toes.\",\"Press through your heels to slide back up.\",\"Keep your back in contact with the wall.\"],\"img\":\"8956.webp\",\"gif\":\"8956.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Sliding down a wall into a squat with your heels planted teaches good squat depth and control. It trains the quads and glutes.\"},{\"id\":\"0954\",\"n\":\"hero pose virasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\",\"hip flexors\"],\"st\":[\"Kneel with knees together and feet slightly wider than your hips.\",\"Sit your hips down between your heels, using a block if needed.\",\"Rest your hands on your thighs and lengthen your spine.\",\"Relax your shoulders and breathe evenly.\",\"Hold for 30-60 seconds, then come out slowly.\"],\"img\":\"0954.webp\",\"gif\":\"0954.mp4\",\"cat\":\"yoga\",\"desc\":\"Kneel and sit between your feet, stretching the thighs and ankles. A grounded seat for breathing or meditation.\"},{\"id\":\"9312\",\"n\":\"high bar incline push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Set a bar at about waist or chest height.\",\"Place your hands on it slightly wider than your shoulders.\",\"Walk your feet back so your body is in a straight line.\",\"Lower your chest to the bar.\",\"Press back up to straight arms.\",\"Keep your core and glutes tight.\"],\"img\":\"9312.webp\",\"gif\":\"9312.mp4\",\"cat\":\"calisthenics\",\"desc\":\"With your hands on a high bar, you do an easier incline push up. A great stepping stone toward floor push ups.\"},{\"id\":\"4917\",\"n\":\"high bar inverted row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Set a bar at about chest height and grab it overhand.\",\"Walk your feet forward until your arms are straight.\",\"Keep your body in a straight line.\",\"Pull your chest toward the bar.\",\"Squeeze your shoulder blades together.\",\"Lower yourself slowly.\"],\"img\":\"4917.webp\",\"gif\":\"4917.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row on a high bar, which makes the pull more upright and easier. It builds the back and arms.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"10864\",\"n\":\"high box step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Stand facing a high box.\",\"Place one foot fully on top.\",\"Drive through that heel to stand up.\",\"Bring the other foot up.\",\"Step down with control.\",\"Switch leading legs.\"],\"img\":\"10864.webp\",\"gif\":\"10864.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Stepping up onto a tall box. It builds the quads and glutes.\"},{\"id\":\"5990\",\"n\":\"high hurdle jump to sprint and cut\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a high hurdle with feet shoulder-width apart.\",\"Swing your arms and jump over it, tucking your knees.\",\"Land softly with bent knees.\",\"Sprint forward right away.\",\"Plant and cut sharply to one side.\",\"Walk back and repeat, alternating cut directions.\"],\"img\":\"5990.webp\",\"gif\":\"5990.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jump over a high hurdle, land and sprint into a sharp cut, training explosive power and reactive agility.\"},{\"id\":\"3678\",\"n\":\"high jump rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"shoulders\"],\"st\":[\"Hold the rope handles and stand tall.\",\"Swing the rope overhead.\",\"Jump higher than usual.\",\"Land softly with bent knees.\",\"Keep your rhythm.\"],\"img\":\"3678.webp\",\"gif\":\"3678.mp4\",\"cat\":\"cardio\",\"desc\":\"Jump rope with higher jumps to add power and intensity.\"},{\"id\":\"3677\",\"n\":\"high knee jump rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"calves\",\"quadriceps\"],\"st\":[\"Hold the rope handles and swing the rope overhead.\",\"Run over the rope.\",\"Lift your knees to hip height.\",\"Stay on the balls of your feet.\",\"Keep your torso upright.\"],\"img\":\"3677.webp\",\"gif\":\"3677.mp4\",\"cat\":\"cardio\",\"desc\":\"Jump rope while driving your knees high for a hard cardio effort.\",\"fv\":\"8370\"},{\"id\":\"5478\",\"n\":\"high knee lunge on bosu ball\",\"bp\":\"upper legs\",\"eq\":\"bosu ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with one foot on the bosu dome and the other behind you.\",\"Lower into a lunge with your torso upright.\",\"Drive through the front foot and bring the back knee up high.\",\"Land softly and balanced, then repeat.\",\"Switch legs after your set.\"],\"img\":\"5478.webp\",\"gif\":\"5478.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Explosive lunge-and-drive-knee movement off a bosu ball that trains leg power and balance.\"},{\"id\":\"3556\",\"n\":\"high knee run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"calves\",\"core\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Run in place, driving your knees up toward waist height.\",\"Pump your arms in rhythm.\",\"Land softly on the balls of your feet.\",\"Keep your chest tall.\",\"Continue for 30-60 seconds.\"],\"img\":\"3556.webp\",\"gif\":\"3556.mp4\",\"cat\":\"cardio\",\"desc\":\"A running-in-place move with high knees. It raises the heart rate.\",\"fv\":\"3817\"},{\"id\":\"3091\",\"n\":\"high knee skips\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand tall and relaxed.\",\"Skip forward, driving one knee up high.\",\"Hop lightly on the other foot.\",\"Swing the opposite arm forward with each knee.\",\"Alternate legs in a smooth rhythm.\",\"Keep your chest up and land softly.\"],\"img\":\"3091.webp\",\"gif\":\"3091.mp4\",\"cat\":\"cardio\",\"desc\":\"A bouncy skip with high knee lifts. It warms up the legs and raises your heart rate.\",\"fv\":\"0477\"},{\"id\":\"3701\",\"n\":\"high knee sprints\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand tall with your arms bent at your sides.\",\"Start running in place, driving each knee up to hip height.\",\"Pump your arms in rhythm with your legs.\",\"Stay on the balls of your feet and keep your chest up.\",\"Go hard for 20 to 30 seconds, then rest.\"],\"img\":\"3701.webp\",\"gif\":\"3701.mp4\",\"cat\":\"cardio\",\"desc\":\"Running in place at full speed with your knees driving high. A quick way to raise your heart rate and warm up your legs.\"},{\"id\":\"3092\",\"n\":\"high knee squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Squat down with your chest up.\",\"Drive up through your feet to stand.\",\"Lift one knee toward your chest as you reach the top.\",\"Lower the foot and go back into the squat.\",\"Alternate knees on each rep.\"],\"img\":\"3092.webp\",\"gif\":\"3092.mp4\",\"cat\":\"cardio\",\"desc\":\"A squat followed by a high knee drive as you stand. It combines leg strength with a cardio push.\",\"fv\":\"0478\"},{\"id\":\"4435\",\"n\":\"high knee squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Squat down with your chest lifted.\",\"Stand up explosively and drive one knee up toward your chest.\",\"Land softly and drop into the next squat.\",\"Alternate knees on each rep.\"],\"img\":\"4435.webp\",\"gif\":\"4435.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat followed by a high knee drive, combining leg strength with a bit of cardio.\",\"fv\":\"3957\"},{\"id\":\"0479\",\"n\":\"high knee step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\",\"calves\"],\"st\":[\"Stand in front of a sturdy bench or step.\",\"Place one foot fully on it.\",\"Drive through that foot to step up and lift the other knee high.\",\"Step back down with control.\",\"Keep your torso upright.\",\"Repeat, then switch legs.\"],\"img\":\"0479.webp\",\"gif\":\"0479.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-up on a bench or box finishing with a high knee drive. It trains the legs and balance.\"},{\"id\":\"5537\",\"n\":\"high knee tap\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"quadriceps\"],\"st\":[\"Stand tall with hands out in front at waist height.\",\"Drive one knee up to tap your hand.\",\"Lower it and switch quickly to the other knee.\",\"Stay light on the balls of your feet.\",\"Keep a fast, steady pace for time.\"],\"img\":\"5537.webp\",\"gif\":\"5537.mp4\",\"cat\":\"cardio\",\"desc\":\"Fast knee-drive drill where you tap your knees to your hands, great for warming up and raising the heart rate.\",\"fv\":\"6095\"},{\"id\":\"4634\",\"n\":\"high knee to butt kick\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"hip flexors\",\"calves\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Drive one knee up to hip height.\",\"Lower it and kick the same heel toward your glutes.\",\"Alternate sides at a steady, light pace.\",\"Keep your core braced and stay on the balls of your feet.\"],\"img\":\"4634.webp\",\"gif\":\"4634.mp4\",\"cat\":\"cardio\",\"desc\":\"A running-in-place drill that alternates a high knee with a heel kick to raise your heart rate.\"},{\"id\":\"0480\",\"n\":\"high knee twist\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"quadriceps\",\"core\"],\"st\":[\"Stand tall with your hands behind your head.\",\"Lift one knee high and twist your torso to meet it with the opposite elbow.\",\"Lower and switch sides.\",\"Keep a quick, steady rhythm.\",\"Land softly on the balls of your feet.\",\"Go for 30-60 seconds.\"],\"img\":\"0480.webp\",\"gif\":\"0480.mp4\",\"cat\":\"cardio\",\"desc\":\"A running-in-place move where you twist to bring the elbow to the lifted knee. It raises your heart rate and engages the trunk.\"},{\"id\":\"10759\",\"n\":\"high knee walk\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\",\"calves\"],\"st\":[\"Stand tall with your arms relaxed.\",\"Lift one knee toward your chest.\",\"Step forward and lower it to the floor.\",\"Repeat on the other side.\",\"Keep your torso upright.\",\"Walk 10-20 steps per leg.\"],\"img\":\"10759.webp\",\"gif\":\"10759.mp4\",\"cat\":\"mobility\",\"desc\":\"A walking warm-up where you lift each knee high. It primes the hips and legs.\"},{\"id\":\"0481\",\"n\":\"high knees butt kicks\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"hip flexors\",\"calves\"],\"st\":[\"Stand tall with your arms ready to pump.\",\"Run in place and drive your knees up high.\",\"Switch to kicking your heels toward your buttocks.\",\"Alternate between the two patterns.\",\"Stay light on your feet.\",\"Keep going for 30-60 seconds.\"],\"img\":\"0481.webp\",\"gif\":\"0481.mp4\",\"cat\":\"cardio\",\"desc\":\"A cardio drill alternating high knee lifts with heel flicks to the buttocks. It warms up the legs and lifts your heart rate.\"},{\"id\":\"3952\",\"n\":\"high knees lunge\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hip flexors\"],\"st\":[\"Stand tall.\",\"Step forward into a lunge.\",\"Push off and drive the back knee up high.\",\"Step back and repeat on the other side.\",\"Keep your pace steady for 30-60 seconds.\"],\"img\":\"3952.webp\",\"gif\":\"3952.mp4\",\"cat\":\"cardio\",\"desc\":\"Step into a lunge and drive the knee high to raise the heart rate.\"},{\"id\":\"5891\",\"n\":\"high lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\",\"shoulders\"],\"st\":[\"Step one foot back into a long lunge with your back heel lifted.\",\"Bend your front knee to about 90 degrees over your ankle.\",\"Sweep your arms overhead and stand tall.\",\"Hold for 5 slow breaths.\",\"Step forward and switch legs.\"],\"img\":\"5891.webp\",\"gif\":\"5891.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep lunge with the back heel lifted and arms overhead. Strengthens the legs and stretches the hips.\"},{\"id\":\"2767\",\"n\":\"hip abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall holding a support, with your weight on one leg.\",\"Lift the other leg straight out to the side, toes pointing forward.\",\"Pause briefly, then lower slowly without leaning your torso.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2767.webp\",\"gif\":\"2767.mp4\",\"cat\":\"mobility\",\"desc\":\"Lifting the leg out to the side away from the body, working the outer hip and glutes.\"},{\"id\":\"1903\",\"n\":\"hip abduction with flexion in front stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Sit on the floor with one leg bent in front of you.\",\"Place the other leg to the side.\",\"Lean your torso forward over the front shin.\",\"Keep your hips grounded.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1903.webp\",\"gif\":\"1903.mp4\",\"cat\":\"stretching\",\"desc\":\"Brings the leg forward and out to open the outer hip.\"},{\"id\":\"2768\",\"n\":\"hip adduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall holding a support, with your weight on one leg.\",\"Lift the other leg slightly out to the side.\",\"Bring it back in and across the front of the standing leg, then pause.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2768.webp\",\"gif\":\"2768.mp4\",\"cat\":\"mobility\",\"desc\":\"Bringing the leg inward across the body, working the inner thigh.\"},{\"id\":\"1931\",\"n\":\"hip and knee flexion squatting stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet a little wider than your shoulders and toes turned slightly out.\",\"Sink down into a deep squat and press your elbows against your inner knees to open the hips.\",\"Keep your heels on the floor and your chest tall.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1931.webp\",\"gif\":\"1931.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep squat hold that opens the hips and loosens the knees and ankles.\"},{\"id\":\"5526\",\"n\":\"hip circle with hula hoop\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hip flexors\"],\"st\":[\"Stand with feet shoulder width apart, holding the hoop against your lower back.\",\"Give it a push and start swinging your hips in circles.\",\"Keep the motion smooth and steady.\",\"Stay tall with a braced core.\",\"Continue for a set time, then switch direction.\"],\"img\":\"5526.webp\",\"gif\":\"5526.mp4\",\"cat\":\"cardio\",\"desc\":\"Hooping around your waist with a hula hoop for light cardio and core engagement.\"},{\"id\":\"4286\",\"n\":\"hip circles stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"lower back\"],\"st\":[\"Stand with your feet slightly wider than shoulder width.\",\"Place your hands on your hips.\",\"Rotate your hips in a wide circle.\",\"Do 10 circles in one direction.\",\"Reverse and circle the other way.\",\"Keep your shoulders still and your knees soft.\"],\"img\":\"4286.webp\",\"gif\":\"4286.mp4\",\"cat\":\"mobility\",\"desc\":\"Big circles with your hips that loosen the joint and the muscles around it. A good warm-up for leg days.\",\"fv\":\"1847\"},{\"id\":\"4870\",\"n\":\"hip clam shell\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your side with knees bent and feet together.\",\"Keep your feet touching.\",\"Lift your top knee.\",\"Lower slowly.\",\"Switch sides after your reps.\"],\"img\":\"4870.webp\",\"gif\":\"4870.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying clamshell opening of the knees. It strengthens the outer hips.\"},{\"id\":\"0482\",\"n\":\"hip crunch (knees bent)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and lifted over your hips.\",\"Place your hands at your sides.\",\"Curl your hips off the floor by bringing your knees toward your chest.\",\"Pause at the top.\",\"Lower slowly back to the start.\",\"Use your abs instead of swinging your legs.\"],\"img\":\"0482.webp\",\"gif\":\"0482.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse-crunch style move lifting the hips off the floor with the knees bent. It works the lower abs.\"},{\"id\":\"2769\",\"n\":\"hip extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall holding a support, with your weight on one leg.\",\"Swing the other leg straight back, keeping your knee mostly straight.\",\"Squeeze the glute at the top, avoiding any arching of your lower back.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2769.webp\",\"gif\":\"2769.mp4\",\"cat\":\"mobility\",\"desc\":\"Moving the leg back behind the body, which works the glutes and hamstrings.\"},{\"id\":\"2115\",\"n\":\"hip extension on knees\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"quadriceps\"],\"st\":[\"Kneel on a soft surface with knees hip-width apart and thighs upright.\",\"Place your hands on your hips or the back of your pelvis.\",\"Squeeze your glutes and push your hips forward.\",\"Keep your ribs down and avoid over-arching your lower back.\",\"Hold for a moment, then return to the start.\",\"Repeat for 8-12 reps.\"],\"img\":\"2115.webp\",\"gif\":\"2115.mp4\",\"cat\":\"mobility\",\"desc\":\"Opens the front of the hips from a kneeling position by pushing the pelvis forward, which also wakes up the glutes.\"},{\"id\":\"4673\",\"n\":\"hip extension stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand or kneel with one foot forward in a lunge position.\",\"Tuck your pelvis under and squeeze the back glute.\",\"Lean slightly forward to feel the stretch at the front of the hip.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"4673.webp\",\"gif\":\"4673.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing or kneeling stretch that lengthens the front of the hip while the glutes work.\",\"fv\":\"0483\"},{\"id\":\"2112\",\"n\":\"hip extension supported from back\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat on the floor.\",\"Place your arms by your sides for support.\",\"Push through your heels and lift the hips until the body forms a straight line.\",\"Squeeze your glutes at the top without arching the lower back.\",\"Lower the hips back down with control.\",\"Repeat for 10-12 reps.\"],\"img\":\"2112.webp\",\"gif\":\"2112.mp4\",\"cat\":\"mobility\",\"desc\":\"Lifts the hips while the upper back is supported, teaching the glutes to extend the hip through a full range.\"},{\"id\":\"6787\",\"n\":\"hip external rotation test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit or lie with the knee bent 90 degrees.\",\"Keep the thigh still.\",\"Swing the lower leg inward so the hip rotates outward.\",\"Stop where you feel a stretch or end of range.\",\"Note how far each side goes.\",\"Repeat on the other leg.\"],\"img\":\"6787.webp\",\"gif\":\"6787.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple check of how far the hip turns outward. You do it gently to see your range.\"},{\"id\":\"1944\",\"n\":\"hip external rotator stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent.\",\"Cross one ankle over the opposite knee and pull the lower thigh toward your chest until the buttock stretches.\",\"Keep your head and shoulders relaxed on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1944.webp\",\"gif\":\"1944.mp4\",\"cat\":\"stretching\",\"desc\":\"A floor stretch for the deep hip rotators and buttock muscles.\"},{\"id\":\"2770\",\"n\":\"hip flexion\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall holding a support, with your weight on one leg.\",\"Lift the other knee up in front of you toward hip height.\",\"Pause briefly, then lower slowly without rounding your back.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2770.webp\",\"gif\":\"2770.mp4\",\"cat\":\"mobility\",\"desc\":\"Lifting the thigh forward and up, working the hip flexors and front of the thigh.\"},{\"id\":\"4674\",\"n\":\"hip flexor stretch (rear foot elevated)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Place the top of your back foot on a bench behind you.\",\"Step your front foot forward into a lunge.\",\"Tuck your pelvis and push your hips forward.\",\"Keep your chest tall and hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"4674.webp\",\"gif\":\"4674.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep lunge stretch with the back foot raised on a bench, targeting the quads and hip flexors.\",\"fv\":\"2568\"},{\"id\":\"6788\",\"n\":\"hip internal rotation test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hip flexors\"],\"st\":[\"Sit or lie with the knee bent 90 degrees.\",\"Keep the thigh still.\",\"Swing the lower leg outward so the hip rotates inward.\",\"Stop where you feel a stretch or end of range.\",\"Note how far each side goes.\",\"Repeat on the other leg.\"],\"img\":\"6788.webp\",\"gif\":\"6788.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple check of how far the hip turns inward. You do it gently to see your range.\"},{\"id\":\"2771\",\"n\":\"hip lateral rotation (external rotation)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hip flexors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Sit tall on a bench or chair, one knee bent at 90 degrees.\",\"Keep your thigh still and swing your lower leg inward, which rotates the hip outward.\",\"Pause briefly, then return to the starting position under control.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2771.webp\",\"gif\":\"2771.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the thigh outward at the hip, working the deep hip rotators and glutes.\"},{\"id\":\"11010\",\"n\":\"hip lift low back off floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with legs raised toward the ceiling.\",\"Press your arms into the floor.\",\"Lift your hips so your lower back comes off the floor.\",\"Lower slowly with control.\",\"Avoid swinging.\"],\"img\":\"11010.webp\",\"gif\":\"11010.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying move where you lift the hips so the lower back leaves the floor. It targets the lower abs.\",\"fv\":\"1853\"},{\"id\":\"2772\",\"n\":\"hip medial rotation (internal rotation)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Sit tall on a bench or chair, one knee bent at 90 degrees.\",\"Keep your thigh still and swing your lower leg outward, which rotates the hip inward.\",\"Pause briefly, then return to the starting position under control.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2772.webp\",\"gif\":\"2772.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the thigh inward at the hip, working the muscles that turn the leg in.\"},{\"id\":\"0486\",\"n\":\"hip raise bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and your feet flat.\",\"Place your arms at your sides.\",\"Drive through your heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\",\"Keep your ribs down and your neck relaxed.\"],\"img\":\"0486.webp\",\"gif\":\"0486.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip bridge that lifts the hips off the floor from a lying position. It builds the glutes and hamstrings.\"},{\"id\":\"0485\",\"n\":\"hip raise bridge v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and your feet flat.\",\"Place your arms at your sides.\",\"Press through your heels and lift your hips toward the ceiling.\",\"Squeeze your glutes at the top.\",\"Lower slowly to the floor.\",\"Keep your ribs down and avoid overarching.\"],\"img\":\"0485.webp\",\"gif\":\"0485.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A second version of the hip bridge lifting the hips from the floor. It strengthens the glutes and hamstrings.\"},{\"id\":\"0487\",\"n\":\"hip raise crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your legs lifted and knees bent.\",\"Place your hands at your sides or under your hips.\",\"Curl your hips off the floor, bringing your knees toward your chest.\",\"Hold briefly at the top.\",\"Lower with control.\",\"Avoid using momentum.\"],\"img\":\"0487.webp\",\"gif\":\"0487.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse crunch that lifts the hips while the legs rise over the torso. It targets the lower abs.\"},{\"id\":\"4385\",\"n\":\"hip roll plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Start in a forearm plank with feet slightly wider than hip-width.\",\"Brace your abs and keep your shoulders stable.\",\"Rotate your hips to one side, lowering them toward the floor.\",\"Roll back through the middle to the other side.\",\"Keep the movement controlled and breathe steadily.\"],\"img\":\"4385.webp\",\"gif\":\"4385.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank with a rolling twist of the hips from side to side. It works the obliques and deep core muscles.\"},{\"id\":\"4615\",\"n\":\"hip swirls\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and hands on your hips.\",\"Slightly bend your knees.\",\"Move your hips in a large smooth circle, as if drawing it with your belt buckle.\",\"Do several circles one way, then switch direction.\",\"Keep your shoulders still and relaxed.\"],\"img\":\"4615.webp\",\"gif\":\"4615.mp4\",\"cat\":\"mobility\",\"desc\":\"Standing hip circles that loosen the hip joints and warm up the pelvis.\",\"fv\":\"5114\"},{\"id\":\"2072\",\"n\":\"hip thrusts\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Sit on the floor with your upper back against a bench and knees bent.\",\"Plant your feet flat, hip-width apart.\",\"Drive through your heels to lift your hips until your torso is level.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2072.webp\",\"gif\":\"2072.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute-focused bridge with the upper back on a bench, lifting the hips to build strong glutes.\",\"fv\":\"2145\"},{\"id\":\"2845\",\"n\":\"hip twist supported arms\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Sit with your hands behind you and legs lifted.\",\"Keep your chest open.\",\"Rotate your hips to one side.\",\"Circle your legs back to the centre.\",\"Switch sides.\"],\"img\":\"2845.webp\",\"gif\":\"2845.mp4\",\"cat\":\"pilates\",\"desc\":\"A seated twist with the legs lifted, working the obliques and core.\"},{\"id\":\"6344\",\"n\":\"holding squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Sit down into a squat until your thighs are about parallel to the floor.\",\"Keep your chest up and your knees tracking over your toes.\",\"Hold the position while breathing steadily.\",\"Hold for 20-40 seconds, then stand up.\"],\"img\":\"6344.webp\",\"gif\":\"6344.mp4\",\"cat\":\"isometric\",\"desc\":\"A static squat hold that builds endurance in your thighs and glutes and teaches a solid bottom position.\",\"hd\":1},{\"id\":\"1246\",\"n\":\"hollow hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your arms overhead and legs straight.\",\"Press your lower back into the floor.\",\"Lift your shoulders and legs a few inches off the ground.\",\"Hold the shape and breathe steadily.\",\"Hold for 20-30 seconds, then rest.\"],\"img\":\"1246.webp\",\"gif\":\"1246.mp4\",\"cat\":\"isometric\",\"desc\":\"A gymnastics-style hold with your shoulders and legs lifted. It builds deep core strength.\",\"hd\":1,\"fv\":\"7157\"},{\"id\":\"5649\",\"n\":\"hollow rock\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Lie on your back and lift your arms and legs into a hollow position.\",\"Press your lower back into the floor.\",\"Rock back and forth like a boat.\",\"Keep your body rigid.\",\"Continue for reps or time.\"],\"img\":\"5649.webp\",\"gif\":\"5649.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Rocking on your back in a hollow body position to challenge your core.\"},{\"id\":\"4588\",\"n\":\"hook kick kickboxing (with boxing bag)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"quadriceps\",\"core\"],\"st\":[\"Stand in a fighting stance facing the bag.\",\"Pivot on your standing foot and lift your rear knee out to the side.\",\"Rotate your hips and swing your leg in an arc.\",\"Hit the bag with the top of your foot or shin.\",\"Keep your hands up and your torso steady.\",\"Bring the leg back and switch sides.\"],\"img\":\"4588.webp\",\"gif\":\"4588.mp4\",\"cat\":\"combat\",\"desc\":\"A roundhouse-style kick that swings in an arc into the bag, building hip rotation and power.\"},{\"id\":\"4597\",\"n\":\"hook kick kickboxing (with partner)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"quadriceps\",\"core\"],\"st\":[\"Face your partner, who holds a kick pad to the side.\",\"Stand in a fighting stance with hands up.\",\"Pivot on your standing foot and lift your rear knee out.\",\"Rotate your hips and swing your leg in an arc into the pad.\",\"Keep your torso steady.\",\"Bring the leg back and switch sides.\"],\"img\":\"4597.webp\",\"gif\":\"4597.mp4\",\"cat\":\"combat\",\"desc\":\"A roundhouse-style hook kick delivered to a partner's pad, building hip rotation and power.\"},{\"id\":\"9679\",\"n\":\"hopping high knee tap\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand tall with one hand held out in front at waist height.\",\"Hop on one leg while driving the opposite knee up to tap your hand.\",\"Land softly and quickly switch legs.\",\"Keep your chest upright.\",\"Continue at a lively pace for 20-30 seconds.\"],\"img\":\"9679.webp\",\"gif\":\"9679.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A hopping drill where you drive a knee up and tap it with your hand. It raises the heart rate and builds coordination.\"},{\"id\":\"7341\",\"n\":\"hopping pendulum\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"core\"],\"st\":[\"Stand on one leg with a slight knee bend.\",\"Hop sideways to land on the other foot.\",\"Swing the free leg across behind you for balance.\",\"Land softly and stay controlled.\",\"Keep alternating at a steady pace.\"],\"img\":\"7341.webp\",\"gif\":\"7341.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Side to side hopping that swings your legs like a pendulum, training balance and leg power.\"},{\"id\":\"6341\",\"n\":\"humble warrior pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"shoulders\",\"chest\"],\"st\":[\"Step into a wide lunge with the front knee bent.\",\"Clasp your hands behind your back.\",\"Fold your torso inside your front thigh.\",\"Let your arms float overhead.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"6341.webp\",\"gif\":\"6341.mp4\",\"cat\":\"yoga\",\"desc\":\"A lunge with a forward fold and clasped hands behind you. It stretches the hips, hamstrings and shoulders.\"},{\"id\":\"2846\",\"n\":\"hundred\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back and lift your head and shoulders.\",\"Raise your legs to a tabletop or extend them.\",\"Pump your arms up and down in small beats.\",\"Breathe in for five beats and out for five.\",\"Aim for one hundred beats.\"],\"img\":\"2846.webp\",\"gif\":\"2846.mp4\",\"cat\":\"pilates\",\"desc\":\"The classic Pilates warm-up where you pump your arms while holding your legs up, building abdominal endurance.\"},{\"id\":\"11656\",\"n\":\"hydrotherapy walking on spot\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"hip flexors\",\"core\"],\"st\":[\"Stand in waist-to-chest-deep water with your feet hip width apart.\",\"Lift one knee up in front of you, then lower it and lift the other.\",\"Swing your arms naturally and keep your posture tall.\",\"Walk at a relaxed, steady pace without leaning forward.\",\"Continue for 2-5 minutes at an easy to moderate effort.\"],\"img\":\"11656.webp\",\"gif\":\"11656.mp4\",\"cat\":\"rehab\",\"desc\":\"Gentle walking in place in chest-deep water, a low-impact way to move the legs and raise your heart rate.\"},{\"id\":\"1860\",\"n\":\"hyperextension v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Set the pad at hip level and hook your heels under the rollers.\",\"Cross your arms over your chest and keep your body straight.\",\"Bend forward at the hips with a flat back.\",\"Lift your torso until it forms a straight line with your legs.\",\"Do not overarch at the top, then lower with control.\"],\"img\":\"1860.webp\",\"gif\":\"1860.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Back extension on a bench that strengthens the lower back, glutes and hamstrings.\"},{\"id\":\"5598\",\"n\":\"inchworm and mountain climbers\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hamstrings\",\"quadriceps\"],\"st\":[\"Stand tall, then hinge forward and walk your hands out to a plank.\",\"Brace your core and keep a straight line.\",\"Drive your knees to your chest alternately for several reps.\",\"Walk your hands back to your feet.\",\"Stand up and repeat.\"],\"img\":\"5598.webp\",\"gif\":\"5598.mp4\",\"cat\":\"cardio\",\"desc\":\"Combo of an inchworm walk-out followed by mountain climbers for a full-body workout.\"},{\"id\":\"4768\",\"n\":\"incline alternate flutter kicks\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie back on an incline bench and hold the edges behind your head.\",\"Lift your legs a few inches off the floor.\",\"Kick your legs up and down alternately in small motions.\",\"Keep your lower back pressed down.\",\"Continue for the set time or reps.\"],\"img\":\"4768.webp\",\"gif\":\"4768.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on an incline, you alternate straight-leg flutter kicks. It trains the lower abs.\"},{\"id\":\"5160\",\"n\":\"incline close grip push up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Place your hands close together on a bench or sturdy box, just under your chest.\",\"Step back until your body is straight from head to heels.\",\"Lower your chest toward the edge, elbows tucked close to your ribs.\",\"Press back up until your arms are straight.\",\"Keep your hips from sagging throughout.\"],\"img\":\"5160.webp\",\"gif\":\"5160.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with hands close together on a raised surface. The easier angle keeps the focus on your triceps.\"},{\"id\":\"11315\",\"n\":\"incline close grip push up with chair against wall\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Brace a chair against a wall and place your hands close together on the seat.\",\"Walk your feet back until your body is in a straight line.\",\"Lower your chest toward the chair, elbows close to your body.\",\"Press back up until your arms are straight.\",\"Keep your hips in line.\"],\"img\":\"11315.webp\",\"gif\":\"11315.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A close grip incline push-up with your hands on a chair. It is a good way to build triceps strength.\"},{\"id\":\"9049\",\"n\":\"incline hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on an incline bench and hold the top edge behind your head.\",\"Bring your legs up so your knees are over your hips.\",\"Curl your pelvis up to lift your hips off the bench.\",\"Pause at the top.\",\"Lower slowly without swinging.\",\"Keep the movement small and controlled.\"],\"img\":\"9049.webp\",\"gif\":\"9049.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on an incline bench, you lift your hips off the pad by curling the pelvis. It targets the lower abs.\"},{\"id\":\"10593\",\"n\":\"incline jack plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hip flexors\",\"glutes\"],\"st\":[\"Place your hands on a bench in an incline plank.\",\"Brace your core and keep your body straight.\",\"Jump your feet wide.\",\"Jump them back together.\",\"Keep your hips level and the pace steady.\"],\"img\":\"10593.webp\",\"gif\":\"10593.mp4\",\"cat\":\"cardio\",\"desc\":\"A plank with hands on a raised surface, jumping your feet in and out like a jumping jack. It builds core and gets the heart rate up.\"},{\"id\":\"1851\",\"n\":\"incline push press\",\"bp\":\"chest\",\"eq\":\"barbell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"quadriceps\"],\"st\":[\"Set an incline bench and hold the bar at your upper chest.\",\"Dip slightly through your legs to start momentum.\",\"Drive the bar up while pressing with your arms.\",\"Lock out above your chest, then lower under control.\",\"Keep your core braced and your lower back from arching.\"],\"img\":\"1851.webp\",\"gif\":\"1851.mp4\",\"cat\":\"strength\",\"desc\":\"An incline press with a small leg drive that lets you move heavier loads and trains the upper chest and shoulders.\"},{\"id\":\"5637\",\"n\":\"incline push up (on bench)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place hands on a bench slightly wider than shoulders.\",\"Walk your feet back into a straight line.\",\"Lower your chest to the bench.\",\"Press back up.\",\"Keep your core tight.\"],\"img\":\"5637.webp\",\"gif\":\"5637.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Push-up with hands elevated on a bench, an easier version of the push-up.\"},{\"id\":\"6550\",\"n\":\"incline push up on a smith bar\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Set the Smith bar at about waist height and rack it securely.\",\"Place your hands on the bar slightly wider than your shoulders.\",\"Keep your body in a straight line.\",\"Lower your chest to the bar.\",\"Push back up to straight arms.\"],\"img\":\"6550.webp\",\"gif\":\"6550.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on a Smith bar, making it easier than a floor push-up while still training your chest.\"},{\"id\":\"3180\",\"n\":\"incline reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down on an incline bench with hips at the edge.\",\"Hold the sides of the bench.\",\"Raise both legs until they are in line with your torso.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"3180.webp\",\"gif\":\"3180.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse hyperextension on an incline bench that trains the glutes and lower back.\"},{\"id\":\"3348\",\"n\":\"incline shoulder tap\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Place your hands on a bench or box and extend into a plank position.\",\"Spread your feet slightly wider for balance.\",\"Lift one hand and tap the opposite shoulder.\",\"Keep your hips level and body in a straight line.\",\"Alternate sides at a steady pace.\"],\"img\":\"3348.webp\",\"gif\":\"3348.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank on an incline where you tap each shoulder, building core and shoulder stability.\"},{\"id\":\"1190\",\"n\":\"incline twisting sit up v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on an incline bench with your feet secured.\",\"Place your hands lightly behind your head.\",\"Curl up while rotating your torso to one side.\",\"Lower slowly.\",\"Alternate sides each rep.\"],\"img\":\"1190.webp\",\"gif\":\"1190.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An incline sit-up with a twist to work the obliques as well as the abs.\"},{\"id\":\"7175\",\"n\":\"inline skating\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Put on skates, helmet and pads, and stand with your knees slightly bent.\",\"Push one skate out to the side and glide on the other.\",\"Alternate pushes with a relaxed arm swing.\",\"Keep your chest up and your weight over the skates.\",\"Skate at a steady pace for 10-30 minutes.\",\"Slow down gradually to stop.\"],\"img\":\"7175.webp\",\"gif\":\"7175.mp4\",\"cat\":\"cardio\",\"desc\":\"Gliding on inline skates for steady cardio that also works the legs and balance.\"},{\"id\":\"11785\",\"n\":\"internal rotation shoulders mobilization\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\"],\"st\":[\"Stand or sit tall with one elbow bent to 90 degrees at your side.\",\"Rotate your forearm across your belly.\",\"Move slowly through a comfortable range.\",\"Return to the start and repeat 8-12 times.\",\"Switch arms.\"],\"img\":\"11785.webp\",\"gif\":\"11785.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle shoulder mobility drill that trains internal rotation.\"},{\"id\":\"1991\",\"n\":\"internal shoulder rotation stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Stand tall and place one hand behind your lower back with the elbow bent.\",\"Use the other hand or a towel to gently draw the hand up your back until the back of the shoulder stretches.\",\"Keep your shoulders level and do not twist.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1991.webp\",\"gif\":\"1991.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch that eases the shoulder into inward rotation.\"},{\"id\":\"4988\",\"n\":\"inverse leg curl with bench pads\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Anchor your ankles under the bench pads and kneel upright.\",\"Cross your arms or hold them in front of you.\",\"Lean forward slowly from the knees, keeping hips and torso in a straight line.\",\"Lower as far as you can control.\",\"Pull yourself back up with your hamstrings.\"],\"img\":\"4988.webp\",\"gif\":\"4988.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight hamstring curl where you lower your torso against the pads. It is very demanding for the back of the thighs.\",\"fv\":\"8111\"},{\"id\":\"3486\",\"n\":\"inverted chin curl with bent knee between chairs\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"lats\",\"brachialis\"],\"st\":[\"Place a sturdy bar across two stable chairs and lie underneath it.\",\"Grip the bar underhand, arms straight, knees bent.\",\"Keep your hips up and body in a line.\",\"Curl yourself up by bending the elbows, keeping them close.\",\"Lower with control until the arms are straight.\",\"Check the chairs are stable before each set.\"],\"img\":\"3486.webp\",\"gif\":\"3486.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An underhand-grip hang under a bar between two chairs, curling your body up with the biceps. Bent knees keep it manageable.\"},{\"id\":\"3382\",\"n\":\"inverted row bent knee under table\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Lie under a sturdy table and grip the edge with both hands.\",\"Bend your knees and plant your feet on the floor.\",\"Lift your hips so your body forms a line from knees to shoulders.\",\"Pull your chest to the table edge, squeezing your shoulder blades.\",\"Lower slowly and repeat.\"],\"img\":\"3382.webp\",\"gif\":\"3382.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An easier inverted row with bent knees, pulling up to a sturdy table to build back strength.\"},{\"id\":\"3388\",\"n\":\"inverted row between chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Set a sturdy bar or table edge between two stable chairs and lie under it.\",\"Grip the support with straight arms and your body in a plank line.\",\"Pull your chest toward the support.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly until your arms are straight.\",\"Keep your hips up the whole time.\"],\"img\":\"3388.webp\",\"gif\":\"3388.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row under a sturdy support between two chairs for the upper back and arms.\",\"fv\":\"3520\"},{\"id\":\"4769\",\"n\":\"inverted row slide\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Lie under a bar or rings and grab with an overhand grip.\",\"Keep your body straight with heels on a slick surface.\",\"Pull your chest toward the bar while your feet slide forward.\",\"Squeeze your shoulder blades together.\",\"Lower slowly with control.\"],\"img\":\"4769.webp\",\"gif\":\"4769.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row where your feet slide along the floor as you pull. It builds the lats and mid back.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"4974\",\"n\":\"inverted row slide on floor\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Lie under a bar or lower support with sliders under your heels.\",\"Grab the bar overhand.\",\"Pull your chest toward the bar.\",\"Keep your body straight.\",\"Lower slowly.\",\"Keep your hips up.\"],\"img\":\"4974.webp\",\"gif\":\"4974.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row where you pull your body along the floor on sliders. It trains the back with core demand.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"3381\",\"n\":\"inverted row under table\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\",\"core\"],\"st\":[\"Lie under a sturdy table and grip the edge with both hands.\",\"Extend your legs with heels on the floor and body in a straight line.\",\"Pull your chest toward the table edge, squeezing your shoulder blades.\",\"Lower with control until your arms are straight.\",\"Keep your hips up the whole time.\"],\"img\":\"3381.webp\",\"gif\":\"3381.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull your chest up to the underside of a sturdy table to train the back and arms using your own weight.\"},{\"id\":\"3749\",\"n\":\"inverted row with bed sheet\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Anchor a bed sheet securely and hold both ends.\",\"Lean back with your body straight.\",\"Pull your chest toward your hands.\",\"Squeeze your shoulder blades together.\",\"Lower yourself slowly.\"],\"img\":\"3749.webp\",\"gif\":\"3749.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row using a bed sheet looped around a sturdy anchor, such as a closed door.\"},{\"id\":\"3485\",\"n\":\"inverted row with bent knee between chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Set a sturdy bar across two stable chairs and lie underneath it.\",\"Grip the bar overhand, arms straight, knees bent and feet flat.\",\"Keep your body in a straight line from shoulders to knees.\",\"Pull your chest up toward the bar, squeezing your shoulder blades.\",\"Lower slowly until your arms are straight again.\",\"Make sure the chairs cannot slide.\"],\"img\":\"3485.webp\",\"gif\":\"3485.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A home row where you hang under a bar or broom handle set across two chairs, knees bent to make it easier. It trains the back and biceps.\"},{\"id\":\"4049\",\"n\":\"inverted shrug\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"shoulders\",\"grip muscles\"],\"st\":[\"Set up under a bar or rings and hang with straight arms.\",\"Keep your body in a straight line.\",\"Pull your shoulder blades down and back to rise a little.\",\"Hold briefly, then lower to a full hang.\",\"Repeat for controlled reps.\"],\"img\":\"4049.webp\",\"gif\":\"4049.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging inverted, you move your shoulder blades to lift the body slightly. It builds the traps and scapular control.\"},{\"id\":\"4043\",\"n\":\"inverted shrug (on parallel bars)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"shoulders\",\"grip muscles\"],\"st\":[\"Grip the parallel bars and hang in an inverted position with arms straight.\",\"Keep your body stable and your elbows locked.\",\"Draw your shoulder blades down and together, pulling your body up a little.\",\"Lower back to a full hang under control.\",\"Repeat for controlled reps.\"],\"img\":\"4043.webp\",\"gif\":\"4043.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging from parallel bars, you shrug your shoulder blades up and down. It builds the traps and shoulder control.\"},{\"id\":\"3538\",\"n\":\"inverted underhand grip row between chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\",\"forearms\"],\"st\":[\"Set a bar across two stable chairs.\",\"Lie under it and grip underhand.\",\"Keep your legs straight with heels on the floor.\",\"Pull your chest to the bar.\",\"Lower slowly.\",\"Keep your body in a line.\"],\"img\":\"3538.webp\",\"gif\":\"3538.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row with an underhand grip on a bar between two chairs.\"},{\"id\":\"4770\",\"n\":\"inverted wide row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lie under a bar and grab it with a wide overhand grip.\",\"Keep your body in a straight line, heels on the floor.\",\"Pull your chest up toward the bar.\",\"Squeeze your shoulder blades together.\",\"Lower under control to straight arms.\"],\"img\":\"4770.webp\",\"gif\":\"4770.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row with a wide grip. The wide hands shift the work to the upper back and rear shoulders.\"},{\"id\":\"4911\",\"n\":\"inverted wide to narrow row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Set a bar or straps at waist height and lie underneath.\",\"Grab it with a wide grip and straighten your body.\",\"Pull your chest toward the bar.\",\"Bring your hands closer on the way up or between reps.\",\"Lower yourself with control.\",\"Keep your body in a straight line.\"],\"img\":\"4911.webp\",\"gif\":\"4911.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row where you start with a wide grip and finish narrow. It trains the whole back and the arms.\"},{\"id\":\"1193\",\"n\":\"iron cross plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Start in a plank position with hands under your shoulders.\",\"Spread your arms and legs wide in an X shape.\",\"Brace your core and keep your hips level.\",\"Breathe steadily.\",\"Hold for 20-40 seconds.\"],\"img\":\"1193.webp\",\"gif\":\"1193.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank variation with arms and legs spread wide to challenge the core.\",\"hd\":1},{\"id\":\"9320\",\"n\":\"isometric hold close grip chin up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"upper back\"],\"st\":[\"Grip the bar with palms facing you and hands close together.\",\"Pull yourself up until your chin is over the bar.\",\"Hold for 5 to 15 seconds.\",\"Keep your shoulders down and core tight.\",\"Lower slowly under control.\",\"Rest and repeat.\"],\"img\":\"9320.webp\",\"gif\":\"9320.mp4\",\"cat\":\"isometric\",\"desc\":\"A close grip chin-up held at the top or halfway. It builds pulling strength and grip.\",\"hd\":1},{\"id\":\"9325\",\"n\":\"isometric hold push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a straight-arm plank with hands under your shoulders.\",\"Lower halfway down until your elbows are bent.\",\"Hold the position for 10 to 20 seconds.\",\"Keep your body straight from head to heels.\",\"Press back up.\",\"Rest and repeat.\"],\"img\":\"9325.webp\",\"gif\":\"9325.mp4\",\"cat\":\"isometric\",\"desc\":\"A push-up held in place at the top or bottom. It builds chest, arm and core strength.\",\"hd\":1},{\"id\":\"9311\",\"n\":\"isometric hold wide hand push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push-up position with hands wider than your shoulders.\",\"Lower your chest until your elbows are bent.\",\"Hold this position for 10 to 20 seconds.\",\"Keep your body in a straight line.\",\"Press back up to the start.\",\"Rest and repeat.\"],\"img\":\"9311.webp\",\"gif\":\"9311.mp4\",\"cat\":\"isometric\",\"desc\":\"A wide-grip push-up held halfway down. It builds chest strength under tension.\",\"hd\":1},{\"id\":\"9607\",\"n\":\"isometric mid thighs pull\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"upper back\",\"grip muscles\"],\"st\":[\"Set a bar in a rack at mid-thigh height and grip it just outside your legs.\",\"Stand with a flat back and slightly bent knees.\",\"Brace your core and chest up.\",\"Pull up on the bar as hard as you can without it moving.\",\"Hold for 5 seconds, then release gradually.\"],\"img\":\"9607.webp\",\"gif\":\"9607.mp4\",\"cat\":\"isometric\",\"desc\":\"A max-effort pull against a fixed bar at mid-thigh height. It builds force production through the hips and back.\",\"hd\":1},{\"id\":\"9995\",\"n\":\"isometric wrist extension\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit with your forearm resting on a table, palm down and wrist at the edge.\",\"Place your other hand on top of the working hand.\",\"Try to lift the hand up while the top hand resists.\",\"Hold for 5-10 seconds with no movement.\",\"Relax slowly.\",\"Repeat, then switch arms.\"],\"img\":\"9995.webp\",\"gif\":\"9995.mp4\",\"cat\":\"isometric\",\"desc\":\"A static hold where you press the back of your hand upward against resistance. It strengthens the wrist extensors without moving the joint.\",\"hd\":1},{\"id\":\"7619\",\"n\":\"jack burpee v. 2\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"chest\",\"shoulders\",\"core\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Squat down, place your hands on the floor and jump your feet back to a plank.\",\"Lower your chest to the floor and push up, or skip the push-up if you prefer.\",\"Jump your feet back toward your hands.\",\"Jump up, spreading your arms and legs like a jumping jack, then repeat.\"],\"img\":\"7619.webp\",\"gif\":\"7619.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee that finishes with a jumping jack. It raises your heart rate and works the whole body.\"},{\"id\":\"3970\",\"n\":\"jack burpee with push up\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"quadriceps\",\"core\",\"shoulders\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Squat down, place your hands on the floor and jump your feet back into a plank.\",\"Lower your chest to the floor in a push-up and press back up.\",\"Jump your feet back toward your hands.\",\"Explode up into a jumping jack, landing softly, then flow into the next rep.\"],\"img\":\"3970.webp\",\"gif\":\"3970.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee that adds a jumping jack finish and a push-up on the floor. It spikes your heart rate while working the chest, arms and legs.\"},{\"id\":\"0502\",\"n\":\"jack knife floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with legs straight and arms extended overhead.\",\"Brace your abs and press your lower back into the floor.\",\"Lift your arms and legs at the same time, folding up at the hips.\",\"Reach your hands toward your toes at the top.\",\"Lower with control until arms and legs hover just above the floor.\",\"Keep your movement smooth and avoid swinging.\"],\"img\":\"0502.webp\",\"gif\":\"0502.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you fold up to bring hands and feet together over your hips. It works the abs hard and builds hip flexor strength.\"},{\"id\":\"0503\",\"n\":\"jack knife on ball\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hip flexors\",\"core\"],\"st\":[\"Get into a push-up position with your shins or feet resting on a stability ball.\",\"Keep your hands under your shoulders and your body in a straight line.\",\"Roll the ball toward your hands as you lift your hips toward the ceiling.\",\"Keep your legs fairly straight and pull with your abs.\",\"Pause briefly at the top.\",\"Roll the ball back out to the plank without sagging your lower back.\"],\"img\":\"0503.webp\",\"gif\":\"0503.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with shins on a ball, you pike your hips up high. It hits the abs and challenges balance and shoulder stability.\"},{\"id\":\"1478\",\"n\":\"jack plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Brace your core and keep your hips level.\",\"Jump your feet apart, then jump them back together.\",\"Keep your upper body steady and your hips from rising.\",\"Continue at a steady pace for the planned time.\"],\"img\":\"1478.webp\",\"gif\":\"1478.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank where your feet jump in and out like a jumping jack, combining core stability with cardio.\"},{\"id\":\"2564\",\"n\":\"jack plank on medicine ball\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hip flexors\"],\"st\":[\"Place your hands on a medicine ball in a plank.\",\"Brace your abs and keep your body straight.\",\"Jump your feet wide.\",\"Jump them back together.\",\"Keep your hips level.\",\"Continue for the planned reps.\"],\"img\":\"2564.webp\",\"gif\":\"2564.mp4\",\"cat\":\"strength\",\"desc\":\"A plank with jumping jack feet on a medicine ball, challenging core stability.\"},{\"id\":\"0504\",\"n\":\"jack press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"calves\",\"glutes\"],\"st\":[\"Stand tall with a dumbbell in each hand at shoulder height.\",\"Jump your feet out wide as you press the dumbbells overhead.\",\"Lock out the arms without arching your back.\",\"Jump your feet together as you lower the weights to your shoulders.\",\"Land softly on the balls of your feet.\",\"Keep a steady rhythm for the set.\"],\"img\":\"0504.webp\",\"gif\":\"0504.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping jack combined with an overhead press. It raises your heart rate and works the shoulders and legs together.\"},{\"id\":\"0505\",\"n\":\"jack split crunches\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"quadriceps\"],\"st\":[\"Lie on your back with your arms extended overhead and legs together.\",\"Lift your shoulders and legs as you crunch up.\",\"Open your legs wide in a split while your hands reach forward.\",\"Bring the legs back together as you lower.\",\"Keep your lower back pressed down.\",\"Repeat at a smooth, steady pace.\"],\"img\":\"0505.webp\",\"gif\":\"0505.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with legs that split apart like a jumping jack while lying down. It trains the abs and keeps the legs working.\"},{\"id\":\"4438\",\"n\":\"jack step\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"shoulders\"],\"st\":[\"Stand with feet together and arms at your sides.\",\"Step one foot out to the side while raising your arms overhead.\",\"Step it back as you lower your arms.\",\"Repeat on the other side.\",\"Keep a steady pace for 30-60 seconds.\"],\"img\":\"4438.webp\",\"gif\":\"4438.mp4\",\"cat\":\"cardio\",\"desc\":\"A low-impact version of the jumping jack where you step out instead of jumping.\",\"fv\":\"0506\"},{\"id\":\"6103\",\"n\":\"jackknife\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Lie on your back with your legs extended and your arms by your sides.\",\"Lift both legs up toward the ceiling.\",\"Press your arms into the floor and lift your hips slightly.\",\"Raise your trunk and reach toward your toes.\",\"Roll back down slowly with control.\",\"Keep your movement smooth, without swinging.\"],\"img\":\"6103.webp\",\"gif\":\"6103.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates move where you lift your legs and trunk together to fold at the hips. It challenges the abs and balance.\",\"fv\":\"2847\"},{\"id\":\"3650\",\"n\":\"jump box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand facing a sturdy box with feet shoulder width apart.\",\"Swing your arms back and dip your hips.\",\"Jump up and land softly on top of the box.\",\"Stand fully upright.\",\"Step down carefully and reset.\"],\"img\":\"3650.webp\",\"gif\":\"3650.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive jump onto a box that builds leg power.\",\"fv\":\"0509\"},{\"id\":\"3887\",\"n\":\"jump box over\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a sturdy box with feet shoulder-width apart.\",\"Swing your arms back and load your hips.\",\"Jump onto the box and land softly with bent knees.\",\"Step or hop down on the other side.\",\"Turn around and repeat in the other direction.\",\"Reset your balance between reps.\"],\"img\":\"3887.webp\",\"gif\":\"3887.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump onto and over a box that builds explosive leg power and coordination.\"},{\"id\":\"4965\",\"n\":\"jump box v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand facing a box with feet shoulder width.\",\"Dip and swing your arms back.\",\"Jump onto the box with both feet.\",\"Land softly with bent knees.\",\"Stand tall on the box.\",\"Step down carefully.\"],\"img\":\"4965.webp\",\"gif\":\"4965.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A box jump that builds explosive leg power. It trains the whole lower body.\"},{\"id\":\"10053\",\"n\":\"jump from seated position\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Sit on a sturdy box or bench with feet flat.\",\"Lean slightly forward with arms ready.\",\"Explode upward, swinging your arms.\",\"Land softly on both feet with bent knees.\",\"Sit back down and reset.\",\"Repeat with a short pause each time.\"],\"img\":\"10053.webp\",\"gif\":\"10053.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive jump that starts from a seated position on a box or chair, building power in the legs.\"},{\"id\":\"0510\",\"n\":\"jump lunge to feet jack\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\",\"calves\",\"shoulders\"],\"st\":[\"Start standing tall with feet together.\",\"Step into a lunge and drop your back knee toward the floor.\",\"Jump and switch legs in the air, landing in a lunge on the other side.\",\"Jump up and land with feet wide as you swing your arms overhead, like a jumping jack.\",\"Jump the feet back together and return to the start.\",\"Land softly and keep your chest up.\"],\"img\":\"0510.webp\",\"gif\":\"0510.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping lunge that finishes with a jumping jack. It is a high-intensity move for legs and conditioning.\"},{\"id\":\"3892\",\"n\":\"jump on fit box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a plyo box with feet shoulder-width apart.\",\"Swing your arms back and bend your knees.\",\"Jump up and land softly on top of the box with both feet.\",\"Stand fully upright at the top.\",\"Step down carefully.\",\"Reset and repeat.\"],\"img\":\"3892.webp\",\"gif\":\"3892.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A box jump that builds explosive power in the legs and hips.\"},{\"id\":\"4168\",\"n\":\"jump pistol squat box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in front of a box on one leg, other leg forward.\",\"Squat down on one leg to touch the box.\",\"Drive through your heel and jump upward.\",\"Land softly on the same leg.\",\"Control your balance and reset.\",\"Complete reps, then switch legs.\"],\"img\":\"4168.webp\",\"gif\":\"4168.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A single leg squat to a box followed by a jump. It builds balance and explosive leg strength.\"},{\"id\":\"4964\",\"n\":\"jump shrug\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"quadriceps\",\"calves\"],\"st\":[\"Stand holding a barbell at hip height.\",\"Dip slightly with your knees.\",\"Jump explosively and extend fully.\",\"Shrug your shoulders at the top.\",\"Land softly with bent knees.\",\"Keep the bar close to your body.\"],\"img\":\"4964.webp\",\"gif\":\"4964.mp4\",\"cat\":\"olympic\",\"desc\":\"An explosive jump with a shrug at the top. It builds hip power for the Olympic lifts.\"},{\"id\":\"4829\",\"n\":\"jump skip rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"forearms\",\"feet\"],\"st\":[\"Hold the rope handles at hip height with elbows near your sides.\",\"Swing the rope over your head using your wrists.\",\"Jump just high enough to clear the rope.\",\"Land softly on the balls of your feet.\",\"Keep a steady rhythm for 30-60 seconds, rest, and repeat.\"],\"img\":\"4829.webp\",\"gif\":\"4829.mp4\",\"cat\":\"cardio\",\"desc\":\"Skipping rope with a jump on each turn. It builds stamina, coordination and calf strength.\"},{\"id\":\"1166\",\"n\":\"jump split\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Start in a split stance with a slight lunge dip.\",\"Drop down and jump up powerfully.\",\"Switch leg positions in mid-air.\",\"Land softly in a lunge with the other leg in front.\",\"Keep your torso upright and repeat at a steady pace.\"],\"img\":\"1166.webp\",\"gif\":\"1166.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive lunge jump where you switch legs in the air. It builds power and conditioning.\",\"fv\":\"0512\"},{\"id\":\"4771\",\"n\":\"jump split with hands on hip\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand tall with hands on your hips.\",\"Step into a lunge position.\",\"Jump and switch legs in the air.\",\"Land softly in a lunge on the other leg.\",\"Keep your chest up and repeat.\"],\"img\":\"4771.webp\",\"gif\":\"4771.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping lunge where you switch your legs in the air with hands on hips. It builds explosive leg power.\"},{\"id\":\"11781\",\"n\":\"jump step box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand facing a step box with your feet hip width apart.\",\"Dip into a quarter squat and swing your arms back.\",\"Jump explosively up onto the box, landing softly with bent knees.\",\"Stand tall on top, then step back down one foot at a time.\",\"Reset and repeat, staying quick but controlled.\"],\"img\":\"11781.webp\",\"gif\":\"11781.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive jump onto a low step box that builds power in the legs and trains soft, controlled landings.\"},{\"id\":\"4706\",\"n\":\"jump step jump\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"glutes\"],\"st\":[\"Stand with feet hip-width apart.\",\"Jump up and land softly with bent knees.\",\"Step to the side or forward.\",\"Jump again and land softly.\",\"Keep a steady rhythm.\"],\"img\":\"4706.webp\",\"gif\":\"4706.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping combination with a step in the middle to raise your heart rate and train leg power.\"},{\"id\":\"3765\",\"n\":\"jump step up\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand facing a sturdy box or step.\",\"Place one foot on top.\",\"Drive through it and jump up into the air.\",\"Land softly on the box and step back down.\",\"Switch legs and keep a steady rhythm.\"],\"img\":\"3765.webp\",\"gif\":\"3765.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A step up with an explosive jump at the top, which builds leg power and raises your heart rate.\",\"fv\":\"0515\"},{\"id\":\"5966\",\"n\":\"jump twist\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"obliques\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart in a slight squat.\",\"Jump up and rotate your hips and feet to one side.\",\"Land softly with bent knees.\",\"Jump again and twist to the other side.\",\"Keep your chest up and land quietly.\"],\"img\":\"5966.webp\",\"gif\":\"5966.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump with a midair trunk rotation that trains explosive leg power and core control.\"},{\"id\":\"10187\",\"n\":\"jump up side jump\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet hip width apart and your knees slightly bent.\",\"Jump straight up, swinging your arms for momentum.\",\"Land softly and immediately hop sideways to one side.\",\"Land on both feet with soft knees and reset your balance.\",\"Alternate the side of each hop and keep a steady rhythm.\"],\"img\":\"10187.webp\",\"gif\":\"10187.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A vertical jump followed by a hop to the side, building leg power and agility.\"},{\"id\":\"3094\",\"n\":\"jumping jack\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"glutes\",\"hip flexors\"],\"st\":[\"Stand with your feet together and your arms at your sides.\",\"Jump your feet apart as you swing your arms overhead.\",\"Jump back to the start position.\",\"Land softly on the balls of your feet.\",\"Keep a steady rhythm.\",\"Continue for 30-60 seconds.\"],\"img\":\"3094.webp\",\"gif\":\"3094.mp4\",\"cat\":\"cardio\",\"desc\":\"The classic jump where your arms and legs swing out and back. A simple full-body warm-up that raises your heart rate fast.\",\"fv\":\"0516\"},{\"id\":\"7555\",\"n\":\"jumping jack high knee\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"hip flexors\",\"shoulders\"],\"st\":[\"Stand tall with arms at your sides.\",\"Jump your feet out and raise your arms overhead.\",\"Jump back in and bring one knee high.\",\"Alternate knees each rep.\",\"Stay light on your feet.\"],\"img\":\"7555.webp\",\"gif\":\"7555.mp4\",\"cat\":\"cardio\",\"desc\":\"Jumping jack paired with a high knee for a lively cardio drill.\"},{\"id\":\"4169\",\"n\":\"jumping pistol squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on one leg with the other extended forward.\",\"Lower into a single leg squat.\",\"Explode upward off the standing leg.\",\"Land softly on the same leg.\",\"Sink back into the next squat.\",\"Complete reps, then switch legs.\"],\"img\":\"4169.webp\",\"gif\":\"4169.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A single leg squat with an explosive jump at the top. It trains leg power and balance.\"},{\"id\":\"1198\",\"n\":\"jumping pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"quadriceps\"],\"st\":[\"Stand under a pull-up bar and grip it slightly wider than your shoulders.\",\"Bend your knees and jump up, pulling your chin above the bar.\",\"Pause for a moment at the top.\",\"Lower yourself slowly until your arms are straight.\",\"Reset on the floor and repeat.\"],\"img\":\"1198.webp\",\"gif\":\"1198.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up that uses a small jump to help you up, then a slow lowering phase. Good for building pulling strength.\"},{\"id\":\"5148\",\"n\":\"jumping single leg lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in a lunge position.\",\"Lower down, then jump explosively off your front leg.\",\"Land softly on the same leg.\",\"Control the next repetition, keeping your torso upright.\",\"Switch legs after your reps.\"],\"img\":\"5148.webp\",\"gif\":\"5148.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lunge jump where you land on a single leg. It builds explosive leg power and balance.\"},{\"id\":\"9692\",\"n\":\"kettlebell alternating arm thruster\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a kettlebell in each hand at shoulder height.\",\"Squat down with your chest tall.\",\"Drive up and press one kettlebell overhead.\",\"Lower it back to your shoulder as you squat again.\",\"Press the other arm on the next rep.\"],\"img\":\"9692.webp\",\"gif\":\"9692.mp4\",\"cat\":\"strength\",\"desc\":\"A squat into a press with kettlebells, alternating arms. It is a full-body conditioning move.\"},{\"id\":\"2942\",\"n\":\"kettlebell angled press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Hold a kettlebell at your shoulder and stand tall.\",\"Brace your abs and squeeze your glutes.\",\"Press the bell up and slightly out to the side in a diagonal path.\",\"Lock out your arm without leaning back.\",\"Lower under control, finish the reps, then switch arms.\"],\"img\":\"2942.webp\",\"gif\":\"2942.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell press at an angle between a front and a side raise path. It suits natural shoulder movement and builds pressing strength.\"},{\"id\":\"2939\",\"n\":\"kettlebell around head rotation\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"forearms\",\"triceps\"],\"st\":[\"Hold a kettlebell by the horns at chest height.\",\"Stand tall with your abs braced.\",\"Circle the bell around your head, keeping it close.\",\"Keep your hips and ribs still.\",\"Finish the reps, then reverse direction.\"],\"img\":\"2939.webp\",\"gif\":\"2939.mp4\",\"cat\":\"mobility\",\"desc\":\"Circling a kettlebell around your head, also called a halo. It loosens the shoulders and warms up the upper back.\"},{\"id\":\"4444\",\"n\":\"kettlebell assisted bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a kettlebell at your chest in one hand and rest the other hand on a sturdy support, standing away from a bench.\",\"Place the top of your rear foot on a bench behind you.\",\"Step your front foot far enough forward to stay balanced.\",\"Lower straight down until your front thigh is about parallel to the floor.\",\"Keep your torso upright and your front knee tracking over your toes.\",\"Drive through the front heel to stand, then switch legs after your set.\"],\"img\":\"4444.webp\",\"gif\":\"4444.mp4\",\"cat\":\"strength\",\"desc\":\"A rear-foot-elevated split squat holding a kettlebell, with a free hand on a support. Builds single-leg strength in the quads and glutes.\"},{\"id\":\"10674\",\"n\":\"kettlebell back squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"upper back\"],\"st\":[\"Hold the kettlebell behind your neck on your upper back with both hands.\",\"Stand with feet shoulder-width apart.\",\"Brace your core and sit down and back.\",\"Lower to parallel while keeping your chest up.\",\"Drive through your heels to stand.\",\"Keep your elbows pointing down.\"],\"img\":\"10674.webp\",\"gif\":\"10674.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a kettlebell held across your upper back. It loads the legs and challenges your trunk.\"},{\"id\":\"3575\",\"n\":\"kettlebell backward lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell at your chest or by your side.\",\"Step one leg back and lower your back knee toward the floor.\",\"Keep your front shin vertical and torso tall.\",\"Push through the front heel to stand.\",\"Alternate legs for the set.\"],\"img\":\"3575.webp\",\"gif\":\"3575.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge holding a kettlebell, friendly on the knees while building glutes and thighs.\"},{\"id\":\"4167\",\"n\":\"kettlebell banded swing\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Set up with the band around your hips and the kettlebell in front of you.\",\"Hinge back and swing the bell between your legs.\",\"Drive your hips forward powerfully.\",\"Let the kettlebell rise to chest height.\",\"Guide it back between your legs as you hinge.\",\"Keep your back flat and arms relaxed.\"],\"img\":\"4167.webp\",\"gif\":\"4167.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell swing with a band adding tension at the hips. It builds hip drive and posterior chain power.\"},{\"id\":\"4538\",\"n\":\"kettlebell bent arm pullover with knees bent\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Hold a kettlebell by the horns above your chest with elbows slightly bent.\",\"Lower it back over your head, feeling a stretch in your lats.\",\"Keep your lower back close to the floor.\",\"Pull it back over your chest and repeat.\"],\"img\":\"4538.webp\",\"gif\":\"4538.mp4\",\"cat\":\"strength\",\"desc\":\"A floor pullover with a kettlebell and bent knees. It stretches and works the lats and chest.\"},{\"id\":\"5867\",\"n\":\"kettlebell bent over alternate twist row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"obliques\",\"core\"],\"st\":[\"Hinge forward with a flat back holding a kettlebell in each hand.\",\"Row one kettlebell toward your hip.\",\"Rotate your torso slightly as you pull.\",\"Lower the weight and repeat on the other side.\",\"Alternate sides for the set.\"],\"img\":\"5867.webp\",\"gif\":\"5867.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over kettlebell row with a rotation as you pull. It trains the back and challenges the core.\"},{\"id\":\"6156\",\"n\":\"kettlebell bent over row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Hold a kettlebell and hinge forward with a flat back.\",\"Let your arm hang straight down.\",\"Row the kettlebell toward your hip.\",\"Squeeze your shoulder blade back.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"6156.webp\",\"gif\":\"6156.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row using a kettlebell. It trains the lats and mid back.\",\"fv\":\"4537\"},{\"id\":\"5857\",\"n\":\"kettlebell biceps curl\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand holding a kettlebell by the handle with both hands or one.\",\"Keep your elbows at your sides.\",\"Curl the kettlebell toward your chest.\",\"Squeeze your biceps.\",\"Lower with control.\"],\"img\":\"5857.webp\",\"gif\":\"5857.mp4\",\"cat\":\"strength\",\"desc\":\"A standard curl holding a kettlebell, which pulls the weight slightly forward of the hand. It builds the biceps and grip.\"},{\"id\":\"3739\",\"n\":\"kettlebell bottom up one arm bench press\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"forearms\",\"grip muscles\"],\"st\":[\"Lie on a bench holding a kettlebell upside down above your chest.\",\"Squeeze the handle and keep your wrist stacked.\",\"Lower the bell slowly toward your chest.\",\"Press it back up while keeping it balanced.\",\"Use a light weight and switch arms after your reps.\"],\"img\":\"3739.webp\",\"gif\":\"3739.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press holding the kettlebell upside down, which forces tight control of the shoulder and wrist.\"},{\"id\":\"9697\",\"n\":\"kettlebell bottoms up single arm overhead carry\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"forearms\",\"grip muscles\",\"core\"],\"st\":[\"Clean a kettlebell so it is upside down with the bell above your fist.\",\"Press it overhead with a firm wrist.\",\"Brace your core and stand tall.\",\"Walk slowly in a straight line.\",\"Lower it safely and switch arms.\"],\"img\":\"9697.webp\",\"gif\":\"9697.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a kettlebell upside down overhead with one arm. It builds shoulder stability and a strong grip.\"},{\"id\":\"4230\",\"n\":\"kettlebell bottoms up to knee turkish get up\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"core\",\"quadriceps\",\"rotator cuff\"],\"st\":[\"Lie on your back holding a kettlebell upside down in one hand, arm straight up.\",\"Bend the same-side knee and plant the foot.\",\"Roll onto your elbow, then your hand.\",\"Lift your hips and sweep the straight leg back to kneel.\",\"Reverse the steps slowly to lie down.\",\"Keep your eyes on the bell and switch sides after your reps.\"],\"img\":\"4230.webp\",\"gif\":\"4230.mp4\",\"cat\":\"strength\",\"desc\":\"A Turkish get-up holding the bell upside down, moving only up to a kneeling position. It builds shoulder stability and core control.\"},{\"id\":\"4963\",\"n\":\"kettlebell box squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand in front of a box holding a kettlebell at your chest.\",\"Push your hips back and sit onto the box.\",\"Pause briefly.\",\"Drive through your feet to stand.\",\"Keep your chest up.\",\"Keep your elbows close.\"],\"img\":\"4963.webp\",\"gif\":\"4963.mp4\",\"cat\":\"strength\",\"desc\":\"A squat to a box holding a kettlebell at your chest. It trains the hips and legs.\"},{\"id\":\"3864\",\"n\":\"kettlebell burpee\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"quadriceps\",\"core\",\"glutes\"],\"st\":[\"Stand with a kettlebell on the floor between your feet.\",\"Squat down and place your hands on the floor beside it, or on the handle if you prefer.\",\"Jump your feet back into a plank.\",\"Lower your chest, push up, then jump your feet back in.\",\"Grab the kettlebell and stand, then press or swing it overhead if you like.\",\"Return it to the floor and repeat.\"],\"img\":\"3864.webp\",\"gif\":\"3864.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee that adds a kettlebell for extra load, giving you a hard full-body conditioning move.\"},{\"id\":\"5880\",\"n\":\"kettlebell calf raise and front squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Hold a kettlebell at your chest with both hands.\",\"Squat down with your chest up and knees tracking over your toes.\",\"Drive up to standing.\",\"At the top, rise onto your toes for a calf raise.\",\"Lower your heels and repeat with control.\"],\"img\":\"5880.webp\",\"gif\":\"5880.mp4\",\"cat\":\"strength\",\"desc\":\"A combo move that pairs a goblet-style front squat with a calf raise at the top, working the legs from hips to ankles.\"},{\"id\":\"4542\",\"n\":\"kettlebell clean and jerk\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"quadriceps\",\"triceps\",\"core\"],\"st\":[\"Stand over a kettlebell with feet shoulder-width apart and hinge to grab it.\",\"Swing it back between your legs, then drive your hips forward.\",\"Pull the bell up and guide it into the rack position at your shoulder.\",\"Dip slightly with your knees, then explode up.\",\"Punch the kettlebell overhead and lock out your arm.\",\"Lower it back to the rack, then to the floor with control. Switch sides.\"],\"img\":\"4542.webp\",\"gif\":\"4542.mp4\",\"cat\":\"olympic\",\"desc\":\"A kettlebell version of the classic lift: swing it to the shoulder, then drive it overhead with a leg push.\"},{\"id\":\"5855\",\"n\":\"kettlebell clean and press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"hamstrings\",\"core\",\"trapezius\"],\"st\":[\"Stand with a kettlebell between your feet and hinge to grip it.\",\"Drive your hips forward and pull the bell up to your shoulder.\",\"Brace your core and press the bell overhead.\",\"Lock out your arm with the bicep near your ear.\",\"Lower to the shoulder, then back to the floor, and switch sides.\"],\"img\":\"5855.webp\",\"gif\":\"5855.mp4\",\"cat\":\"strength\",\"desc\":\"Clean a kettlebell to the shoulder and press it overhead. It combines a hip drive with a shoulder press for full-body power.\"},{\"id\":\"5856\",\"n\":\"kettlebell concentration curl\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit with your legs apart and a kettlebell in one hand.\",\"Rest your elbow against your inner thigh.\",\"Curl the kettlebell up toward your shoulder.\",\"Squeeze at the top.\",\"Lower slowly and switch arms.\"],\"img\":\"5856.webp\",\"gif\":\"5856.mp4\",\"cat\":\"strength\",\"desc\":\"A seated one-arm curl with the elbow braced on your thigh. It isolates the biceps with a strict path.\"},{\"id\":\"7581\",\"n\":\"kettlebell contralateral reverse lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell in one hand.\",\"Step back with the opposite leg.\",\"Lower until the back knee nears the floor.\",\"Push through the front foot.\",\"Finish reps and switch sides.\"],\"img\":\"7581.webp\",\"gif\":\"7581.mp4\",\"cat\":\"strength\",\"desc\":\"Reverse lunge with the kettlebell in the opposite hand to the working leg.\"},{\"id\":\"6193\",\"n\":\"kettlebell cossack squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Hold a kettlebell at your chest and stand wide.\",\"Shift your weight to one side.\",\"Squat down with the other leg straight.\",\"Keep the bent knee over your toes.\",\"Push back to the center.\",\"Alternate sides.\"],\"img\":\"6193.webp\",\"gif\":\"6193.mp4\",\"cat\":\"strength\",\"desc\":\"A side-to-side squat holding a kettlebell. It builds hip mobility and leg strength.\"},{\"id\":\"4047\",\"n\":\"kettlebell dead bug\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lower abs\",\"hip flexors\",\"shoulders\"],\"st\":[\"Lie on your back and hold a kettlebell by the horns above your chest.\",\"Lift your knees to a tabletop position.\",\"Slowly extend one leg while pressing your lower back into the floor.\",\"Bring the leg back and switch.\",\"Keep the kettlebell steady and breathe.\"],\"img\":\"4047.webp\",\"gif\":\"4047.mp4\",\"cat\":\"strength\",\"desc\":\"Dead bug with a kettlebell held above the chest. The weight adds challenge to the core while the limbs move.\"},{\"id\":\"1565\",\"n\":\"kettlebell dead clean\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"upper back\",\"shoulders\",\"grip muscles\"],\"st\":[\"Stand over a kettlebell with feet hip-width apart and hinge down to grab the handle.\",\"Brace your core and keep your back flat.\",\"Drive your hips forward and pull the bell up close to your body.\",\"Rotate your hand around the handle and catch the bell at your shoulder.\",\"Lower it back to the floor under control and reset before the next rep.\"],\"img\":\"1565.webp\",\"gif\":\"1565.mp4\",\"cat\":\"olympic\",\"desc\":\"A clean that starts from a dead stop on the floor each rep, with no swing. It builds explosive hip drive and pulling power.\"},{\"id\":\"3322\",\"n\":\"kettlebell deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"grip muscles\"],\"st\":[\"Stand with feet hip width apart and the kettlebell between your feet.\",\"Push your hips back and bend your knees to grab the handle with both hands.\",\"Keep your chest up and back flat.\",\"Drive through your feet and stand tall, squeezing your glutes.\",\"Hinge back down to set the kettlebell on the floor and repeat.\"],\"img\":\"3322.webp\",\"gif\":\"3322.mp4\",\"cat\":\"strength\",\"desc\":\"A beginner friendly deadlift with a kettlebell between your feet. It teaches the hip hinge and builds glutes and hamstrings.\",\"fv\":\"3902\"},{\"id\":\"9609\",\"n\":\"kettlebell deadlift v. 2\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"grip muscles\"],\"st\":[\"Stand with feet hip-width apart and the kettlebell between your feet.\",\"Hinge and bend your knees to grip the handle with a flat back.\",\"Brace your core and push the floor away.\",\"Stand fully tall, squeezing your glutes.\",\"Lower the bell back to the floor with control.\"],\"img\":\"9609.webp\",\"gif\":\"9609.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge lifting a kettlebell from the floor. It teaches solid deadlift mechanics and builds the posterior chain.\"},{\"id\":\"3579\",\"n\":\"kettlebell deck squat\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Hold a kettlebell at your chest and squat down.\",\"Sit back and roll onto your back, keeping the bell close.\",\"Use momentum to roll forward onto your feet.\",\"Stand up out of the squat.\",\"Keep a tight grip and repeat smoothly.\"],\"img\":\"3579.webp\",\"gif\":\"3579.mp4\",\"cat\":\"strength\",\"desc\":\"Roll back onto the floor holding a kettlebell from a squat, then roll up into a squat again.\"},{\"id\":\"3580\",\"n\":\"kettlebell deep push up\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place two kettlebells shoulder width apart and grip the handles.\",\"Set up in a straight plank position.\",\"Lower your chest below your hands with elbows at about 45 degrees.\",\"Press back up to straight arms.\",\"Keep your body in a straight line.\"],\"img\":\"3580.webp\",\"gif\":\"3580.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with hands on kettlebell handles to lower the chest deeper than the floor allows.\"},{\"id\":\"2751\",\"n\":\"kettlebell dumbbell sumo squat off stepbox\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand on a step box in a wide stance with toes out.\",\"Hold a kettlebell or dumbbell in front of you.\",\"Sit down between your legs, keeping your chest up.\",\"Lower as far as comfortable.\",\"Push through your feet to stand.\"],\"img\":\"2751.webp\",\"gif\":\"2751.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo squat from a raised step box, adding range of motion for deeper work on the glutes and inner thighs.\"},{\"id\":\"5496\",\"n\":\"kettlebell elevated goblet squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Stand with heels on a low plate, holding a kettlebell at your chest.\",\"Keep your chest tall and elbows pointing down.\",\"Squat down between your knees as deep as comfortable.\",\"Drive through your feet to stand up.\",\"Keep your torso upright throughout.\"],\"img\":\"5496.webp\",\"gif\":\"5496.mp4\",\"cat\":\"strength\",\"desc\":\"Goblet squat with your heels raised on a plate or wedge so the knees travel forward and the quads work harder.\"},{\"id\":\"3576\",\"n\":\"kettlebell farmers carry\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"trapezius\",\"core\",\"glutes\"],\"st\":[\"Stand between two kettlebells and pick them up with a flat back.\",\"Stand tall with shoulders back and arms straight.\",\"Walk with short, controlled steps.\",\"Keep your core braced and avoid leaning.\",\"Set the weights down carefully after the distance.\"],\"img\":\"3576.webp\",\"gif\":\"3576.mp4\",\"cat\":\"strength\",\"desc\":\"Walk while holding heavy kettlebells at your sides to build grip, posture and total body stability.\"},{\"id\":\"4528\",\"n\":\"kettlebell farmers walk\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"trapezius\",\"core\",\"glutes\"],\"st\":[\"Pick up a kettlebell in each hand and stand tall.\",\"Pull your shoulders back and brace your core.\",\"Walk forward in controlled steps.\",\"Keep the kettlebells from swinging.\",\"Walk for a set distance or time, then set them down carefully.\"],\"img\":\"4528.webp\",\"gif\":\"4528.mp4\",\"cat\":\"strength\",\"desc\":\"Walking while carrying a heavy kettlebell in each hand. It builds grip, posture and core stability.\"},{\"id\":\"5858\",\"n\":\"kettlebell floor fly\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Lie on your back holding a kettlebell in each hand above your chest.\",\"Keep a slight bend in your elbows.\",\"Lower your arms out to the sides until the elbows touch the floor.\",\"Squeeze your chest to bring the weights back up.\",\"Repeat with control.\"],\"img\":\"5858.webp\",\"gif\":\"5858.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on the floor and open your arms out with kettlebells, stopping when your elbows touch down. It trains the chest.\"},{\"id\":\"3574\",\"n\":\"kettlebell forward lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell at your chest or by your side.\",\"Step forward with one leg into a long stride.\",\"Lower until both knees are bent about 90 degrees.\",\"Push through the front foot to return to standing.\",\"Alternate legs for the set.\"],\"img\":\"3574.webp\",\"gif\":\"3574.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge stepping forward while holding a kettlebell, working the thighs and glutes.\",\"fv\":\"4525\"},{\"id\":\"4533\",\"n\":\"kettlebell forward lunge and press\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a kettlebell at your shoulder in the rack position.\",\"Step forward into a lunge.\",\"As you push back up, press the kettlebell overhead.\",\"Lower the bell to your shoulder as you step back.\",\"Alternate legs or finish one side before switching.\"],\"img\":\"4533.webp\",\"gif\":\"4533.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge combined with an overhead press of a kettlebell. It trains legs and shoulders together.\"},{\"id\":\"5336\",\"n\":\"kettlebell forward lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell at chest height or by your side.\",\"Step forward into a lunge.\",\"Lower until both knees are bent about 90 degrees.\",\"Keep your front knee over your ankle.\",\"Push back to the start.\",\"Alternate legs.\"],\"img\":\"5336.webp\",\"gif\":\"5336.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge holding a kettlebell, a second variation. It builds the thighs and glutes.\"},{\"id\":\"4441\",\"n\":\"kettlebell front rack walking lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"shoulders\"],\"st\":[\"Clean two kettlebells to the front rack, elbows tucked and close to your ribs.\",\"Stand tall with your feet hip width apart.\",\"Step forward and lower until both knees are around 90 degrees.\",\"Push through the front foot and bring the back leg forward into the next step.\",\"Keep your torso upright and the bells steady against your chest.\",\"Continue alternating legs for the planned distance.\"],\"img\":\"4441.webp\",\"gif\":\"4441.mp4\",\"cat\":\"strength\",\"desc\":\"Walking lunges with kettlebells held in the front rack position. Builds leg strength while the core works to keep you upright.\"},{\"id\":\"5859\",\"n\":\"kettlebell front raise\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand tall holding a kettlebell with both hands by the sides of the handle.\",\"Keep your arms nearly straight.\",\"Raise the kettlebell to shoulder height.\",\"Pause briefly.\",\"Lower slowly without swinging.\"],\"img\":\"5859.webp\",\"gif\":\"5859.mp4\",\"cat\":\"strength\",\"desc\":\"Lift a kettlebell straight in front of you to shoulder height. It works the front of the shoulder.\"},{\"id\":\"5301\",\"n\":\"kettlebell full squat from deficit\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand on a low platform holding a kettlebell at chest height.\",\"Brace your core.\",\"Sit your hips down as deep as you can.\",\"Keep your chest up and heels down.\",\"Drive through your feet to stand.\",\"Keep the kettlebell close to your body.\"],\"img\":\"5301.webp\",\"gif\":\"5301.mp4\",\"cat\":\"strength\",\"desc\":\"A deep squat with a kettlebell while standing on a raised platform. It increases range of motion for the legs.\"},{\"id\":\"3571\",\"n\":\"kettlebell full swing\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"shoulders\"],\"st\":[\"Stand with feet shoulder width apart, kettlebell on the floor in front.\",\"Hinge at the hips and grip the handle with both hands.\",\"Hike the bell back, then drive your hips forward to swing it overhead.\",\"Let it fall back between your legs while hinging again.\",\"Keep your back flat and repeat in a smooth rhythm.\"],\"img\":\"3571.webp\",\"gif\":\"3571.mp4\",\"cat\":\"strength\",\"desc\":\"An explosive hip hinge that swings the kettlebell overhead, training the glutes, hamstrings and shoulders.\"},{\"id\":\"2916\",\"n\":\"kettlebell goblet carry\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"biceps\",\"upper back\",\"forearms\",\"quadriceps\"],\"st\":[\"Hold a kettlebell by the horns close to your chest, elbows tucked.\",\"Stand tall with your ribs down and abs braced.\",\"Walk with steady steps without leaning back.\",\"Cover the set distance, keeping the bell high and still.\",\"Set the kettlebell down with a flat back.\"],\"img\":\"2916.webp\",\"gif\":\"2916.mp4\",\"cat\":\"strength\",\"desc\":\"Walking while hugging a kettlebell at chest height. It trains posture, the trunk and the upper back.\"},{\"id\":\"3732\",\"n\":\"kettlebell goblet curtsey lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell by the horns at your chest and stand tall.\",\"Step one leg back and across behind the other.\",\"Lower until your front thigh is near parallel.\",\"Push through your front heel to return.\",\"Finish your reps, then switch legs.\"],\"img\":\"3732.webp\",\"gif\":\"3732.mp4\",\"cat\":\"strength\",\"desc\":\"A curtsey lunge holding a kettlebell at your chest. It targets the glutes and outer hips.\"},{\"id\":\"3187\",\"n\":\"kettlebell goblet squat jump\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Hold a kettlebell at your chest with both hands.\",\"Squat down with your chest tall.\",\"Explode upward into a jump.\",\"Land softly with bent knees.\",\"Reset and go into the next squat.\"],\"img\":\"3187.webp\",\"gif\":\"3187.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A goblet squat that finishes with an explosive jump for leg power.\"},{\"id\":\"2993\",\"n\":\"kettlebell goblet squat mobility\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell by the horns against your chest.\",\"Stand with your feet wider than your shoulders and toes slightly out.\",\"Squat down as deep as you comfortably can with your chest up.\",\"Use your elbows to push your knees out and pause at the bottom.\",\"Rock gently side to side to open the hips.\",\"Drive through your feet to stand back up.\"],\"img\":\"2993.webp\",\"gif\":\"2993.mp4\",\"cat\":\"mobility\",\"desc\":\"A goblet squat held low with a kettlebell as a counterweight, used to loosen the hips and ankles.\"},{\"id\":\"4817\",\"n\":\"kettlebell good morning\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Hold a kettlebell by the horns against your chest.\",\"Stand with feet shoulder-width apart and knees slightly bent.\",\"Push your hips back and hinge forward with a flat back.\",\"Lower until you feel a stretch in your hamstrings.\",\"Squeeze your glutes to stand tall again.\"],\"img\":\"4817.webp\",\"gif\":\"4817.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a kettlebell held at the chest. It strengthens the hamstrings, glutes and lower back.\"},{\"id\":\"6425\",\"n\":\"kettlebell good morning v. 2\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand with feet hip-width apart, holding a kettlebell at your chest.\",\"Keep your knees slightly bent.\",\"Push your hips back and tip your torso forward, back flat.\",\"Lower until you feel your hamstrings stretch.\",\"Squeeze your glutes to return upright.\"],\"img\":\"6425.webp\",\"gif\":\"6425.mp4\",\"cat\":\"strength\",\"desc\":\"Holding a kettlebell at your chest, you hinge at the hips to train hamstrings, glutes and your lower back.\"},{\"id\":\"7230\",\"n\":\"kettlebell gorilla row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"grip muscles\",\"core\"],\"st\":[\"Place two kettlebells on the floor between your wide stance.\",\"Hinge at the hips with a flat back and grab both handles.\",\"Row one kettlebell to your hip while the other stays down.\",\"Lower it and row the other side.\",\"Keep your hips and shoulders square.\"],\"img\":\"7230.webp\",\"gif\":\"7230.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance row between two kettlebells, alternating arms. It trains the lats and the core.\"},{\"id\":\"8331\",\"n\":\"kettlebell half kneeling halo\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"triceps\",\"core\"],\"st\":[\"Kneel on one knee with the other foot forward and hold the kettlebell upside down at chest height.\",\"Squeeze your glutes and keep your ribs down.\",\"Circle the bell around your head slowly, keeping it close.\",\"Complete the reps, then reverse the direction.\",\"Switch the kneeling leg and repeat.\"],\"img\":\"8331.webp\",\"gif\":\"8331.mp4\",\"cat\":\"mobility\",\"desc\":\"A kettlebell circle around the head from a half kneeling stance that mobilises the shoulders and challenges core stability.\"},{\"id\":\"4446\",\"n\":\"kettlebell half kneeling one arm bottoms up press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"forearms\",\"grip muscles\",\"rotator cuff\"],\"st\":[\"Kneel on one knee with the opposite foot flat in front, back upright.\",\"Hold a kettlebell by the handle with the bell pointing up, at shoulder height.\",\"Squeeze the handle tight and brace your core.\",\"Press straight overhead while keeping the bell balanced.\",\"Lower under control back to the shoulder.\",\"Finish your reps, then switch sides.\"],\"img\":\"4446.webp\",\"gif\":\"4446.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press with the kettlebell held upside down from a half-kneeling stance. Challenges shoulder stability, grip and core.\"},{\"id\":\"2934\",\"n\":\"kettlebell half kneeling shoulder press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"glutes\",\"upper chest\"],\"st\":[\"Kneel on one knee with the other foot forward and a kettlebell racked at your shoulder.\",\"Brace your abs and squeeze the glute of the kneeling leg.\",\"Press the bell straight overhead.\",\"Lower it back under control.\",\"Finish the reps, then switch sides.\"],\"img\":\"2934.webp\",\"gif\":\"2934.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm kettlebell press from a half-kneeling stance. The position teaches hip stability while you press.\"},{\"id\":\"11286\",\"n\":\"kettlebell half kneeling side lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"groin\",\"core\"],\"st\":[\"Start in a half kneeling position holding a kettlebell at your chest.\",\"Straighten the front leg to the side as you shift your weight back.\",\"Feel a stretch in your inner thigh.\",\"Return to the start.\",\"Finish your reps, then switch sides.\"],\"img\":\"11286.webp\",\"gif\":\"11286.mp4\",\"cat\":\"mobility\",\"desc\":\"A half kneeling side lunge with a kettlebell. It opens the inner thigh and hips while loading the legs.\"},{\"id\":\"3323\",\"n\":\"kettlebell half turkish get up\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"core\",\"obliques\",\"quadriceps\"],\"st\":[\"Lie on your back with a kettlebell pressed up in one hand and the same side knee bent.\",\"Keep your eyes on the bell and your arm vertical.\",\"Roll onto the opposite elbow, then onto your hand.\",\"Come up to a tall seated position with your arm still locked overhead.\",\"Reverse the steps slowly to lie back down, then switch sides.\"],\"img\":\"3323.webp\",\"gif\":\"3323.mp4\",\"cat\":\"strength\",\"desc\":\"The first half of a turkish get up, moving from lying to a seated position with the kettlebell overhead. It builds shoulder stability and core strength.\"},{\"id\":\"6820\",\"n\":\"kettlebell incline fly\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Lie on an incline bench holding a kettlebell in each hand above your chest.\",\"Keep a soft bend in the elbows.\",\"Open your arms wide in an arc until you feel a chest stretch.\",\"Squeeze the chest to bring the weights back together.\",\"Control the weights and keep your wrists stable.\"],\"img\":\"6820.webp\",\"gif\":\"6820.mp4\",\"cat\":\"strength\",\"desc\":\"A fly on an incline bench using kettlebells. It stretches and works the upper chest.\"},{\"id\":\"7582\",\"n\":\"kettlebell ipsilateral reverse lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"obliques\",\"core\"],\"st\":[\"Hold a kettlebell in one hand.\",\"Step back with the leg on the same side.\",\"Lower under control.\",\"Keep your torso upright.\",\"Push back up and switch sides.\"],\"img\":\"7582.webp\",\"gif\":\"7582.mp4\",\"cat\":\"strength\",\"desc\":\"Reverse lunge with the kettlebell on the same side as the working leg.\"},{\"id\":\"10562\",\"n\":\"kettlebell ipsilateral reverse lunge high knee\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Hold a kettlebell in one hand and stand tall.\",\"Step back with the leg on the same side as the bell.\",\"Lower into a lunge.\",\"Drive up and lift that knee high as you stand.\",\"Finish your reps, then switch sides.\"],\"img\":\"10562.webp\",\"gif\":\"10562.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge holding a kettlebell on the same side as the working leg, ending with a high knee. It trains balance and leg drive.\"},{\"id\":\"3734\",\"n\":\"kettlebell kickstand one leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Hold a kettlebell and stand with one foot slightly behind, toes on the ground as a kickstand.\",\"Hinge at the hips over your front leg.\",\"Lower the bell toward the floor with a flat back.\",\"Drive through your front heel to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"3734.webp\",\"gif\":\"3734.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg deadlift with the back foot lightly touching the floor for support, so you can focus on the working leg.\"},{\"id\":\"2927\",\"n\":\"kettlebell kneeling one arm bottoms up press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"rotator cuff\",\"core\",\"forearms\",\"grip muscles\"],\"st\":[\"Kneel on both knees and hold a kettlebell bottoms up at shoulder height.\",\"Squeeze the handle tight and keep your wrist straight.\",\"Press the bell straight overhead.\",\"Lower slowly to your shoulder, keeping the bell balanced.\",\"Finish the reps, then switch arms.\"],\"img\":\"2927.webp\",\"gif\":\"2927.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing a kettlebell held upside down from a kneeling position. The unstable load demands shoulder control and grip.\"},{\"id\":\"2932\",\"n\":\"kettlebell kneeling one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\",\"glutes\"],\"st\":[\"Kneel on both knees with a kettlebell racked at your shoulder.\",\"Squeeze your glutes and brace your abs.\",\"Press the kettlebell overhead until your arm is straight.\",\"Lower it slowly back to your shoulder.\",\"Finish the reps, then switch arms.\"],\"img\":\"2932.webp\",\"gif\":\"2932.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm kettlebell press from a kneeling position. Kneeling takes the legs out of it and challenges your trunk.\"},{\"id\":\"4045\",\"n\":\"kettlebell lateral lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Hold the kettlebell at your chest with both hands and stand tall.\",\"Take a big step to one side.\",\"Sit your hips back and bend that knee while the other leg stays straight.\",\"Keep your chest up and both feet flat.\",\"Push back to the start and alternate sides.\"],\"img\":\"4045.webp\",\"gif\":\"4045.mp4\",\"cat\":\"strength\",\"desc\":\"Side lunge holding a kettlebell at the chest. It trains the thighs, glutes and inner thighs in the frontal plane.\"},{\"id\":\"3740\",\"n\":\"kettlebell lateral raise\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand holding a kettlebell in one hand at your side.\",\"Keep a soft bend in your elbow.\",\"Raise your arm out to the side to shoulder height.\",\"Lower it slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"3740.webp\",\"gif\":\"3740.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise using a kettlebell, which trains the side delts.\"},{\"id\":\"3577\",\"n\":\"kettlebell lunge clean and press\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start standing with a kettlebell hanging in one hand.\",\"Step back into a lunge while cleaning the bell to your shoulder.\",\"Rise from the lunge and press the bell overhead.\",\"Lower the bell to the shoulder, then to your side.\",\"Alternate legs and switch hands after the set.\"],\"img\":\"3577.webp\",\"gif\":\"3577.mp4\",\"cat\":\"strength\",\"desc\":\"Combine a lunge with a kettlebell clean and overhead press for a full body strength move.\"},{\"id\":\"5069\",\"n\":\"kettlebell lunge with twist\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"quadriceps\"],\"st\":[\"Stand holding a kettlebell at chest height with both hands.\",\"Step forward into a lunge, front knee over your ankle.\",\"Rotate your torso toward the front leg, keeping hips square.\",\"Turn back to center and push off the front foot to return.\",\"Alternate legs for each rep.\"],\"img\":\"5069.webp\",\"gif\":\"5069.mp4\",\"cat\":\"strength\",\"desc\":\"Lunge forward while holding a kettlebell at your chest and rotate over the front leg. Trains legs and trunk rotation together.\"},{\"id\":\"4845\",\"n\":\"kettlebell lying on floor chest press\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on the floor holding a kettlebell in each hand at chest level.\",\"Keep your elbows at about 45 degrees from your body.\",\"Press the kettlebells up until your arms are straight.\",\"Lower until your upper arms touch the floor.\",\"Press again.\"],\"img\":\"4845.webp\",\"gif\":\"4845.mp4\",\"cat\":\"strength\",\"desc\":\"A floor press with kettlebells. The floor limits range and keeps the focus on the chest and triceps.\"},{\"id\":\"4846\",\"n\":\"kettlebell lying on floor single arm bottoms up chest press\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"forearms\",\"core\"],\"st\":[\"Lie on the floor and hold a kettlebell upside down in one hand.\",\"Keep your wrist straight and the bell steady.\",\"Press it up to full extension.\",\"Lower slowly until your upper arm touches the floor.\",\"Switch sides after your reps.\"],\"img\":\"4846.webp\",\"gif\":\"4846.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm floor press with the kettlebell upside down. It demands stability in the wrist and shoulder.\"},{\"id\":\"5861\",\"n\":\"kettlebell lying triceps extension skull crusher\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench holding a kettlebell above your chest.\",\"Keep your upper arms still.\",\"Bend your elbows to lower the weight toward your forehead.\",\"Extend your arms back to the start.\",\"Repeat with control.\"],\"img\":\"5861.webp\",\"gif\":\"5861.mp4\",\"cat\":\"strength\",\"desc\":\"Lie back and lower a kettlebell toward your forehead, then extend. It builds the triceps with elbows fixed.\",\"nd\":[\"bench\"]},{\"id\":\"3738\",\"n\":\"kettlebell one arm bench press\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on a bench holding a kettlebell above your chest.\",\"Keep your wrist straight and your feet planted.\",\"Lower the bell to the side of your chest.\",\"Press it back up to full extension.\",\"Finish your reps, then switch arms.\"],\"img\":\"3738.webp\",\"gif\":\"3738.mp4\",\"cat\":\"strength\",\"desc\":\"A bench press with one kettlebell at a time, adding stability demand for the shoulder and core.\"},{\"id\":\"4543\",\"n\":\"kettlebell one arm clean\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Stand over a kettlebell with feet shoulder-width apart and hinge at the hips to grab the handle.\",\"Hike it back between your legs.\",\"Snap your hips forward and pull the bell close to your body.\",\"Rotate your hand around the bell so it lands softly in the rack at your shoulder.\",\"Stand tall with your elbow tucked in.\",\"Lower the bell back down with control and switch arms.\"],\"img\":\"4543.webp\",\"gif\":\"4543.mp4\",\"cat\":\"olympic\",\"desc\":\"A powerful hip-driven pull that brings a kettlebell from the floor to the rack position on one shoulder.\"},{\"id\":\"1566\",\"n\":\"kettlebell one arm overhead squat (thighs)\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"glutes\",\"triceps\"],\"st\":[\"Press a kettlebell overhead with one arm and lock out your elbow.\",\"Stand with feet shoulder-width apart and keep your ribs down.\",\"Squat down with your chest up while keeping the bell stable over your shoulder.\",\"Go as low as you can with good control.\",\"Drive up through your heels, then switch arms after your reps.\"],\"img\":\"1566.webp\",\"gif\":\"1566.mp4\",\"cat\":\"strength\",\"desc\":\"A squat while holding a kettlebell locked out overhead with one arm. It trains leg strength together with shoulder stability and core control.\"},{\"id\":\"1568\",\"n\":\"kettlebell one arm swing\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet slightly wider than shoulders and hold a kettlebell with one hand.\",\"Hinge at the hips and swing the bell back between your legs.\",\"Snap your hips forward and let the bell float up to chest height.\",\"Keep your arm relaxed and your back flat.\",\"Let the bell fall back and hinge again, then switch hands after your reps.\"],\"img\":\"1568.webp\",\"gif\":\"1568.mp4\",\"cat\":\"strength\",\"desc\":\"A one-armed kettlebell swing driven by the hips. It builds the posterior chain and conditioning.\"},{\"id\":\"4541\",\"n\":\"kettlebell one arm thruster\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a kettlebell in the rack position at one shoulder, feet shoulder-width apart.\",\"Squat down with your torso upright and elbow close to your body.\",\"Stand up powerfully through your heels.\",\"Press the kettlebell overhead as you rise, finishing with a straight arm.\",\"Lower it back to the rack and go into the next squat.\",\"Switch arms after your set.\"],\"img\":\"4541.webp\",\"gif\":\"4541.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell squat-to-press combo done with one arm that works the legs, shoulders and core in one flow.\"},{\"id\":\"1569\",\"n\":\"kettlebell one legged deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Hold a kettlebell in one hand and stand on the opposite leg with a soft knee.\",\"Hinge forward at the hip and extend your free leg straight back.\",\"Lower the bell toward the floor while keeping your back flat.\",\"Stop when your torso is about parallel to the floor.\",\"Squeeze your glute to return upright, then switch legs.\"],\"img\":\"1569.webp\",\"gif\":\"1569.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge holding a kettlebell. It trains the hamstrings and glutes and challenges your balance.\"},{\"id\":\"1567\",\"n\":\"kettlebell open palm clean\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"upper back\",\"forearms\"],\"st\":[\"Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.\",\"Hinge down and grab the handle with one hand.\",\"Hike the bell back, then drive your hips forward to pull it up.\",\"Keep your hand open and guide the bell to rest at your shoulder.\",\"Lower it back with control and repeat, then switch sides.\"],\"img\":\"1567.webp\",\"gif\":\"1567.mp4\",\"cat\":\"olympic\",\"desc\":\"A kettlebell clean where your palm stays open and you catch the bell on your forearm. It teaches a smooth hip-driven pull.\"},{\"id\":\"3680\",\"n\":\"kettlebell overhand grip swing\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"shoulders\",\"grip muscles\"],\"st\":[\"Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.\",\"Hinge at the hips and grip the handle with an overhand grip.\",\"Hike the bell back between your legs.\",\"Snap your hips forward and swing it to chest height.\",\"Let it fall back and hinge again, keeping your back flat.\"],\"img\":\"3680.webp\",\"gif\":\"3680.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell swing with an overhand grip that builds explosive hip power and a strong posterior chain.\"},{\"id\":\"4244\",\"n\":\"kettlebell overhead carry\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"trapezius\",\"forearms\",\"obliques\"],\"st\":[\"Clean and press a kettlebell overhead with one arm.\",\"Lock out your elbow with the bell stable.\",\"Stand tall with your ribs down.\",\"Walk forward with slow, controlled steps.\",\"Keep your wrist straight and avoid leaning.\",\"Lower the bell and repeat on the other arm.\"],\"img\":\"4244.webp\",\"gif\":\"4244.mp4\",\"cat\":\"strength\",\"desc\":\"Walking while holding a kettlebell locked out overhead. It builds shoulder stability, core control and grip.\"},{\"id\":\"5860\",\"n\":\"kettlebell overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold a kettlebell by the horns with both hands overhead.\",\"Keep your elbows pointing forward.\",\"Lower the weight behind your head by bending your elbows.\",\"Extend your arms until they are straight.\",\"Repeat without flaring your elbows.\"],\"img\":\"5860.webp\",\"gif\":\"5860.mp4\",\"cat\":\"strength\",\"desc\":\"Hold a kettlebell behind your head and straighten your arms overhead. It isolates the triceps.\"},{\"id\":\"7229\",\"n\":\"kettlebell plank pass through\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Start in a high plank with a kettlebell beside one hand.\",\"Spread your feet wide for balance.\",\"Grab the kettlebell and slide it across under your body.\",\"Place it down on the other side.\",\"Keep your hips level and repeat in the other direction.\"],\"img\":\"7229.webp\",\"gif\":\"7229.mp4\",\"cat\":\"strength\",\"desc\":\"From a plank you slide a kettlebell under your body from one hand to the other. It works the core and shoulder stability.\"},{\"id\":\"4521\",\"n\":\"kettlebell press up\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place two kettlebells on the floor shoulder-width apart and grip the handles.\",\"Extend your legs into a plank position.\",\"Lower your chest between the handles with elbows at about 45 degrees.\",\"Keep your body in a straight line.\",\"Press back up until your arms are straight and repeat.\"],\"img\":\"4521.webp\",\"gif\":\"4521.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on kettlebell handles for a deeper range of motion. It builds the chest and arms.\"},{\"id\":\"3735\",\"n\":\"kettlebell pullover 3 month position\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie on your back holding a kettlebell with both hands above your chest.\",\"Keep your arms slightly bent.\",\"Lower the bell back over your head in an arc.\",\"Stop when you feel a stretch in your lats.\",\"Pull it back over your chest.\"],\"img\":\"3735.webp\",\"gif\":\"3735.mp4\",\"cat\":\"strength\",\"desc\":\"A lying pullover with a kettlebell that stretches and works the lats and chest.\"},{\"id\":\"9518\",\"n\":\"kettlebell pullover dead bug\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"lats\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back holding a kettlebell above your chest and knees at tabletop.\",\"Brace your core and keep your lower back down.\",\"Lower the kettlebell overhead while extending the opposite leg.\",\"Return to the start under control.\",\"Switch sides and repeat.\"],\"img\":\"9518.webp\",\"gif\":\"9518.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug combined with a kettlebell pullover, where arms and legs extend in opposite directions.\"},{\"id\":\"4536\",\"n\":\"kettlebell rear delt row\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"rear deltoids\",\"biceps\"],\"st\":[\"Hinge forward with a flat back holding a kettlebell in each hand.\",\"Let the weights hang below your chest.\",\"Pull your elbows out wide and up toward the ceiling.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4536.webp\",\"gif\":\"4536.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with elbows flared to hit the rear shoulders. It builds upper back and posture muscles.\"},{\"id\":\"5070\",\"n\":\"kettlebell rear lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall holding a kettlebell at your chest or by your side.\",\"Step one foot back and lower until both knees are about 90 degrees.\",\"Keep your torso upright and front heel down.\",\"Push through the front foot to return to standing.\",\"Complete your reps, then switch legs.\"],\"img\":\"5070.webp\",\"gif\":\"5070.mp4\",\"cat\":\"strength\",\"desc\":\"Step back into a lunge while holding a kettlebell. Stepping backward is kind on the knees and loads the glutes and quads.\"},{\"id\":\"2753\",\"n\":\"kettlebell resistance band full squat from deficit\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand on a low platform, band under your feet and a kettlebell at your chest.\",\"Sit down into the deepest squat you can control.\",\"Keep your heels flat and chest up.\",\"Push through your feet to stand.\",\"Keep tension in the band all the way up.\"],\"img\":\"2753.webp\",\"gif\":\"2753.mp4\",\"cat\":\"strength\",\"desc\":\"A deep squat from a raised platform with a band for added resistance, training the legs and glutes.\"},{\"id\":\"4861\",\"n\":\"kettlebell romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Hold a kettlebell in front of your thighs.\",\"Soften your knees.\",\"Push your hips back and lower the bell along your legs.\",\"Keep your back flat.\",\"Squeeze your glutes to stand.\"],\"img\":\"4861.webp\",\"gif\":\"4861.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a kettlebell. It builds the hamstrings and glutes.\"},{\"id\":\"9485\",\"n\":\"kettlebell romanian deadlift to squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Hold a kettlebell with both hands in front of your thighs.\",\"Hinge at the hips and slide the bell down your legs with a flat back.\",\"Squeeze your glutes to return to standing.\",\"Bend your knees and lower into a squat, keeping the bell close to your chest.\",\"Stand up and repeat for the planned reps.\"],\"img\":\"9485.webp\",\"gif\":\"9485.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift flowing straight into a squat while holding a kettlebell. It trains the hips and thighs with a nice rhythm.\"},{\"id\":\"5886\",\"n\":\"kettlebell rotational deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"obliques\",\"core\"],\"st\":[\"Stand with feet hip-width apart holding a kettlebell in both hands.\",\"Push your hips back and lower the bell toward the outside of one foot.\",\"Rotate your torso slightly as you reach, keeping your back flat.\",\"Drive your hips forward to stand and unwind.\",\"Repeat to the same side, then switch.\"],\"img\":\"5886.webp\",\"gif\":\"5886.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a rotation toward the floor, training the glutes and hamstrings while the trunk learns to twist under load.\"},{\"id\":\"4393\",\"n\":\"kettlebell russian twist\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor with knees bent and lean back a little.\",\"Hold a kettlebell by the horns at your chest.\",\"Lift your feet slightly if you can, and keep your back straight.\",\"Rotate your torso to one side, then the other.\",\"Move with control and keep your chest lifted.\"],\"img\":\"4393.webp\",\"gif\":\"4393.mp4\",\"cat\":\"strength\",\"desc\":\"A seated twisting exercise with a kettlebell that targets the abs and obliques.\"},{\"id\":\"6833\",\"n\":\"kettlebell seated lateral raise\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Sit upright on a bench holding a kettlebell in each hand at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides to shoulder height.\",\"Pause at the top.\",\"Lower slowly without swinging.\"],\"img\":\"6833.webp\",\"gif\":\"6833.mp4\",\"cat\":\"strength\",\"desc\":\"A seated side raise using kettlebells. It isolates the side delts without leg drive.\"},{\"id\":\"3737\",\"n\":\"kettlebell seated one arm military press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Sit on a bench with a kettlebell held at your shoulder.\",\"Sit tall with your core braced.\",\"Press the bell straight overhead until your arm is straight.\",\"Lower it slowly to your shoulder.\",\"Finish your reps, then switch arms.\"],\"img\":\"3737.webp\",\"gif\":\"3737.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press with one kettlebell, which removes leg drive and keeps the work on the shoulder.\"},{\"id\":\"6194\",\"n\":\"kettlebell shrug\",\"bp\":\"back\",\"eq\":\"kettlebell\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand holding kettlebells at your sides.\",\"Keep your arms straight.\",\"Lift your shoulders straight up toward your ears.\",\"Pause for a second at the top.\",\"Lower slowly.\",\"Keep your chest tall and neck relaxed.\"],\"img\":\"6194.webp\",\"gif\":\"6194.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug holding kettlebells at your sides. It builds the upper traps and grip.\"},{\"id\":\"4396\",\"n\":\"kettlebell side bend v. 2\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"core\"],\"st\":[\"Stand tall, holding a kettlebell in one hand at your side.\",\"Keep your feet hip-width apart and your core braced.\",\"Bend sideways toward the weighted side without twisting.\",\"Use your obliques to return to upright.\",\"Finish your reps, then switch hands.\"],\"img\":\"4396.webp\",\"gif\":\"4396.mp4\",\"cat\":\"strength\",\"desc\":\"A standing side bend with a kettlebell that trains the obliques and the muscles along the side of the trunk.\"},{\"id\":\"4098\",\"n\":\"kettlebell side lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall holding a kettlebell at your chest.\",\"Take a big step to the side.\",\"Sit back into that hip while keeping the other leg straight.\",\"Push off the bent leg to return to standing.\",\"Complete all reps, then switch sides.\"],\"img\":\"4098.webp\",\"gif\":\"4098.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral lunge holding a kettlebell, working glutes, quads and inner thighs.\",\"fv\":\"4526\"},{\"id\":\"5879\",\"n\":\"kettlebell side plank\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Lie on your side with your elbow under your shoulder.\",\"Lift your hips into a straight line.\",\"Hold a kettlebell in your top hand pointing up.\",\"Hold for 20-30 seconds.\",\"Lower and switch sides.\"],\"img\":\"5879.webp\",\"gif\":\"5879.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank holding a kettlebell above you. It builds core and shoulder stability.\",\"hd\":1},{\"id\":\"4524\",\"n\":\"kettlebell side squat step\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\"],\"st\":[\"Hold a kettlebell at your chest with both hands.\",\"Step out to the side and sit back into a squat.\",\"Keep your chest up and knees tracking over your toes.\",\"Push through your heels and bring your feet together.\",\"Alternate directions or complete all steps on one side before switching.\"],\"img\":\"4524.webp\",\"gif\":\"4524.mp4\",\"cat\":\"strength\",\"desc\":\"Stepping sideways into a squat while holding a kettlebell at your chest. It works the thighs and hips.\"},{\"id\":\"10192\",\"n\":\"kettlebell side swing\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hamstrings\",\"shoulders\"],\"st\":[\"Stand with feet wider than shoulders and a kettlebell in both hands.\",\"Hinge at the hips and swing the bell back between your legs.\",\"Snap your hips forward and swing the bell up toward chest height, angled to one side.\",\"Let it swing back down with a flat back.\",\"Finish the reps on one side, then switch.\"],\"img\":\"10192.webp\",\"gif\":\"10192.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell swing that travels to the side, adding rotation work for the obliques to the hip snap.\"},{\"id\":\"8366\",\"n\":\"kettlebell side swing v. 2\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hamstrings\",\"shoulders\"],\"st\":[\"Stand with feet wider than hips and hold a kettlebell with both hands.\",\"Hinge at the hips and swing the bell between your legs.\",\"Drive your hips forward and swing it up and across to one side.\",\"Let it fall back through your legs and swing to the other side.\",\"Keep your back flat throughout.\"],\"img\":\"8366.webp\",\"gif\":\"8366.mp4\",\"cat\":\"strength\",\"desc\":\"A swing performed to the side of the body that hits the obliques and hips while the legs drive the kettlebell.\"},{\"id\":\"11284\",\"n\":\"kettlebell single arm alternate fly\",\"bp\":\"chest\",\"eq\":\"kettlebell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"upper chest\"],\"st\":[\"Lie on your back holding a kettlebell over your chest in one hand.\",\"Keep a soft bend in your elbow.\",\"Lower the kettlebell out to the side in an arc.\",\"Bring it back over your chest.\",\"Switch hands and alternate.\"],\"img\":\"11284.webp\",\"gif\":\"11284.mp4\",\"cat\":\"strength\",\"desc\":\"A lying chest fly with a kettlebell, alternating arms. It trains the chest and challenges your control.\"},{\"id\":\"4530\",\"n\":\"kettlebell single arm clean\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"biceps\",\"core\"],\"st\":[\"Stand over a kettlebell and hinge to grip it with one hand.\",\"Swing it back slightly between your legs.\",\"Drive your hips forward and pull the bell up close to your body.\",\"Rotate your hand around so it lands softly in the rack position.\",\"Lower it back down under control, repeat, then switch arms.\"],\"img\":\"4530.webp\",\"gif\":\"4530.mp4\",\"cat\":\"olympic\",\"desc\":\"Pulling a kettlebell from the floor to the shoulder with one arm. It trains explosive hip power and coordination.\"},{\"id\":\"4531\",\"n\":\"kettlebell single arm clean and press\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hinge and swing the kettlebell back, then clean it to your shoulder.\",\"Settle into a stable rack position with your core tight.\",\"Bend your knees slightly, then press the bell straight overhead.\",\"Lock out your elbow with your biceps near your ear.\",\"Lower it to your shoulder, then to the floor. Switch arms after your set.\"],\"img\":\"4531.webp\",\"gif\":\"4531.mp4\",\"cat\":\"strength\",\"desc\":\"A clean followed by an overhead press with one kettlebell. It links hip power with shoulder strength.\"},{\"id\":\"5071\",\"n\":\"kettlebell single arm overhead lunge\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\"],\"st\":[\"Press a kettlebell overhead with one arm and keep that arm straight.\",\"Step forward into a lunge and lower your back knee toward the floor.\",\"Keep your ribs down and the weight stacked over your shoulder.\",\"Push back to standing.\",\"Finish your reps, then switch the kettlebell to the other arm.\"],\"img\":\"5071.webp\",\"gif\":\"5071.mp4\",\"cat\":\"strength\",\"desc\":\"Lunge while holding one kettlebell locked out overhead. The overhead load challenges balance, shoulder stability and the legs.\"},{\"id\":\"4535\",\"n\":\"kettlebell single arm sit up\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"obliques\"],\"st\":[\"Lie on your back with knees bent and a kettlebell held straight up in one hand.\",\"Keep your eyes on the kettlebell and your arm locked.\",\"Curl up and sit all the way to standing or upright.\",\"Control your descent back to the floor.\",\"Finish your reps, then switch arms.\"],\"img\":\"4535.webp\",\"gif\":\"4535.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up while holding a kettlebell overhead with one arm. It adds shoulder stability to an abdominal move.\"},{\"id\":\"4527\",\"n\":\"kettlebell single arm swing\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet slightly wider than your shoulders and the kettlebell in front of you.\",\"Hinge back and swing the bell between your legs.\",\"Snap your hips forward to swing it to chest height.\",\"Let the arm stay relaxed; the hips do the work.\",\"Let the bell fall back and hinge again. Switch hands after your set.\"],\"img\":\"4527.webp\",\"gif\":\"4527.mp4\",\"cat\":\"strength\",\"desc\":\"A hip-driven swing with one hand on a kettlebell. It builds explosive posterior chain power.\"},{\"id\":\"4518\",\"n\":\"kettlebell single arm thruster\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a kettlebell at your shoulder with one hand in the rack position.\",\"Squat down with your chest up and elbow close.\",\"Drive up through your legs.\",\"Use that momentum to press the kettlebell overhead.\",\"Lower it back to your shoulder, repeat, then switch arms.\"],\"img\":\"4518.webp\",\"gif\":\"4518.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat into an overhead press with one kettlebell. It combines legs and shoulders in one flowing move.\"},{\"id\":\"4123\",\"n\":\"kettlebell single front squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"adductors\"],\"st\":[\"Hold a kettlebell at your shoulder with one hand.\",\"Stand with your feet shoulder-width apart.\",\"Squat down with your chest tall.\",\"Drive through your heels to stand.\",\"Switch sides after your set.\"],\"img\":\"4123.webp\",\"gif\":\"4123.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat holding one kettlebell on one side, challenging legs and core stability.\"},{\"id\":\"4523\",\"n\":\"kettlebell single leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"calves\"],\"st\":[\"Hold a kettlebell in one hand and stand on the opposite leg.\",\"Hinge forward at the hips while extending the free leg back.\",\"Lower the kettlebell toward the floor with a flat back.\",\"Keep your hips level and your standing knee slightly bent.\",\"Drive your hips forward to stand, then switch legs.\"],\"img\":\"4523.webp\",\"gif\":\"4523.mp4\",\"cat\":\"strength\",\"desc\":\"A balance-focused hip hinge on one leg with a kettlebell. It trains the hamstrings and glutes.\"},{\"id\":\"10561\",\"n\":\"kettlebell single leg deadlift pass\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"forearms\"],\"st\":[\"Stand on one leg holding a kettlebell in one hand.\",\"Hinge at the hips and reach the bell toward the floor.\",\"Pass the bell to the other hand below your knee.\",\"Stand back up using your glute and hamstring.\",\"Finish your reps, then switch legs.\"],\"img\":\"10561.webp\",\"gif\":\"10561.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg deadlift where you pass a kettlebell from hand to hand. It trains balance and the hip hinge.\"},{\"id\":\"3522\",\"n\":\"kettlebell single leg glute bridge pullover\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lats\",\"core\",\"chest\"],\"st\":[\"Lie on your back with one foot flat, other leg raised.\",\"Hold a kettlebell by the horns above your chest.\",\"Lift your hips into a bridge.\",\"Lower the kettlebell back overhead in an arc.\",\"Bring it back up as you hold the bridge.\",\"Lower your hips, then switch legs.\"],\"img\":\"3522.webp\",\"gif\":\"3522.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg glute bridge with a kettlebell pullover, working glutes and lats.\"},{\"id\":\"4134\",\"n\":\"kettlebell single leg step up\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a kettlebell and stand facing a box.\",\"Place one foot on the box.\",\"Drive through that heel to step up.\",\"Lower slowly.\",\"Finish all reps, then switch legs.\"],\"img\":\"4134.webp\",\"gif\":\"4134.mp4\",\"cat\":\"strength\",\"desc\":\"A step up holding a kettlebell, training each leg separately.\"},{\"id\":\"1187\",\"n\":\"kettlebell sit up\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent and hold a kettlebell at your chest.\",\"Brace your core.\",\"Curl up until your torso is upright.\",\"Keep the kettlebell close to you.\",\"Lower slowly back down.\"],\"img\":\"1187.webp\",\"gif\":\"1187.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up holding a kettlebell for extra resistance on the abs.\",\"fv\":\"4522\"},{\"id\":\"5072\",\"n\":\"kettlebell sit up press\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent, holding a kettlebell at your chest.\",\"Curl and sit up using your abs.\",\"Press the kettlebell overhead as you reach the top.\",\"Lower it back to your chest.\",\"Roll back down slowly and repeat.\"],\"img\":\"5072.webp\",\"gif\":\"5072.mp4\",\"cat\":\"strength\",\"desc\":\"Sit up from the floor with a kettlebell and press it overhead at the top. A core and shoulder combo move.\"},{\"id\":\"10367\",\"n\":\"kettlebell sitting tibialis press\",\"bp\":\"lower legs\",\"eq\":\"kettlebell\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit on a bench or box with a kettlebell hanging from the top of one foot.\",\"Plant your heel on the floor.\",\"Lift the toes up toward your shin to raise the kettlebell.\",\"Pause, then lower slowly.\",\"Use a light weight. Finish the reps, then switch feet.\"],\"img\":\"10367.webp\",\"gif\":\"10367.mp4\",\"cat\":\"strength\",\"desc\":\"A seated press that lifts a kettlebell on the top of the foot to strengthen the muscles at the front of the shin.\"},{\"id\":\"3578\",\"n\":\"kettlebell slingshot\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"forearms\",\"upper back\"],\"st\":[\"Stand with feet shoulder width apart and hold the kettlebell in one hand.\",\"Pass it behind your back to the other hand.\",\"Bring it around your waist to the front.\",\"Keep your hips square and core tight.\",\"Repeat in the same direction, then reverse.\"],\"img\":\"3578.webp\",\"gif\":\"3578.mp4\",\"cat\":\"strength\",\"desc\":\"Pass a kettlebell around your waist in a circle to build core control and coordination.\"},{\"id\":\"4532\",\"n\":\"kettlebell snatch\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"trapezius\",\"core\"],\"st\":[\"Stand over the kettlebell and hinge to grip it with one hand.\",\"Swing it back between your legs.\",\"Drive your hips forward and pull the bell up close to your body.\",\"Punch your hand through to catch it overhead with a straight arm.\",\"Lower it back under control and repeat, then switch arms.\"],\"img\":\"4532.webp\",\"gif\":\"4532.mp4\",\"cat\":\"olympic\",\"desc\":\"Swinging a kettlebell from between your legs to overhead in one motion. It builds power through the whole body.\"},{\"id\":\"3573\",\"n\":\"kettlebell sots press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"triceps\",\"core\"],\"st\":[\"Hold kettlebells in the rack position and sink into a deep squat.\",\"Keep your chest up and heels flat.\",\"Press the bells overhead while staying in the squat.\",\"Lower them back to the shoulders with control.\",\"Stand up and repeat once the set is done.\"],\"img\":\"3573.webp\",\"gif\":\"3573.mp4\",\"cat\":\"strength\",\"desc\":\"Press kettlebells overhead from the bottom of a deep squat to challenge shoulder stability and hip mobility.\"},{\"id\":\"4210\",\"n\":\"kettlebell split snatch\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Stand over a kettlebell in a hip hinge with a flat back.\",\"Swing it back, then drive your hips forward.\",\"As the bell rises, step into a split stance and punch it overhead.\",\"Lock out your arm with the bell resting behind your wrist.\",\"Stand up, bring your feet together and lower the bell to a swing.\",\"Switch arms after your reps.\"],\"img\":\"4210.webp\",\"gif\":\"4210.mp4\",\"cat\":\"olympic\",\"desc\":\"A snatch where you drop into a split stance as the kettlebell goes overhead. It trains hip power, shoulder stability and coordination.\"},{\"id\":\"4059\",\"n\":\"kettlebell split squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a kettlebell at your chest and take a long split stance.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Press through the front heel to stand.\",\"Finish the reps, then switch legs.\"],\"img\":\"4059.webp\",\"gif\":\"4059.mp4\",\"cat\":\"strength\",\"desc\":\"Split squat holding a kettlebell, working the thighs and glutes one leg at a time.\",\"fv\":\"8893\"},{\"id\":\"10673\",\"n\":\"kettlebell squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Hold a kettlebell by the horns at your chest.\",\"Stand with feet shoulder-width apart.\",\"Sit your hips down and back while keeping your chest tall.\",\"Lower until your thighs are parallel or lower.\",\"Push through your heels to stand.\",\"Keep your elbows close to your body.\"],\"img\":\"10673.webp\",\"gif\":\"10673.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a kettlebell at your chest. The weight in front helps you stay upright and use your legs.\"},{\"id\":\"8892\",\"n\":\"kettlebell staggered stance deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with one foot slightly behind the other.\",\"Hold a kettlebell in front of your thighs.\",\"Hinge at the hips and lower the bell toward the floor.\",\"Keep your back flat and weight mostly on the front foot.\",\"Drive your hips forward to stand tall.\",\"Switch stances after your set.\"],\"img\":\"8892.webp\",\"gif\":\"8892.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a staggered stance holding a kettlebell. It loads one leg more than the other.\"},{\"id\":\"11287\",\"n\":\"kettlebell standing behind back romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Hold a kettlebell behind your back in both hands, feet hip width.\",\"Soften your knees and brace your core.\",\"Push your hips back and hinge forward with a flat back.\",\"Stop when you feel your hamstrings stretch.\",\"Drive your hips forward to stand tall.\"],\"img\":\"11287.webp\",\"gif\":\"11287.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift holding a kettlebell behind you. It trains the hamstrings and glutes and reinforces a straight back.\"},{\"id\":\"3736\",\"n\":\"kettlebell standing bottoms up one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"forearms\",\"grip muscles\",\"core\"],\"st\":[\"Hold a kettlebell upside down by the handle at shoulder height.\",\"Squeeze the handle and brace your core.\",\"Press the bell straight overhead, keeping it balanced.\",\"Lower it back to your shoulder with control.\",\"Finish your reps, then switch arms.\"],\"img\":\"3736.webp\",\"gif\":\"3736.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press holding the kettlebell upside down, which demands wrist and shoulder control.\"},{\"id\":\"5854\",\"n\":\"kettlebell standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"kettlebell\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Hold a kettlebell in one hand and stand on the balls of your feet on a step if you like.\",\"Keep your knees nearly straight.\",\"Rise as high as you can on your toes.\",\"Pause at the top.\",\"Lower your heels slowly.\"],\"img\":\"5854.webp\",\"gif\":\"5854.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise holding a kettlebell for resistance. It builds calf strength and ankle stability.\",\"fv\":\"6697\"},{\"id\":\"5863\",\"n\":\"kettlebell standing one arm extension\",\"bp\":\"upper arms\",\"eq\":\"kettlebell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand tall with a kettlebell held overhead in one hand.\",\"Keep your upper arm close to your head.\",\"Lower the weight behind your head by bending the elbow.\",\"Straighten your arm back to the top.\",\"Switch sides after your set.\"],\"img\":\"5863.webp\",\"gif\":\"5863.mp4\",\"cat\":\"strength\",\"desc\":\"Hold a kettlebell overhead in one hand and lower it behind your head. It isolates one triceps at a time.\"},{\"id\":\"4534\",\"n\":\"kettlebell standing slingshots\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"forearms\",\"obliques\"],\"st\":[\"Stand tall holding a kettlebell by the handle with both hands.\",\"Pass it behind your back from one hand to the other.\",\"Bring it around to the front and pass it again.\",\"Keep your hips steady and your core tight.\",\"Reverse direction halfway through your set.\"],\"img\":\"4534.webp\",\"gif\":\"4534.mp4\",\"cat\":\"strength\",\"desc\":\"Passing a kettlebell around your body in circles while standing. It works the shoulders, core and grip.\"},{\"id\":\"12018\",\"n\":\"kettlebell standing slingshots (advanced)\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"forearms\",\"core\"],\"st\":[\"Stand with your feet hip width apart holding a kettlebell by the handle.\",\"Pass it around your waist from one hand to the other behind your back.\",\"Continue the circle to the front, keeping the movement smooth.\",\"Keep your core tight and your hips still.\",\"After several reps, reverse the direction.\"],\"img\":\"12018.webp\",\"gif\":\"12018.mp4\",\"cat\":\"strength\",\"desc\":\"Passing a kettlebell around your torso in quick circles. It challenges the core, grip and coordination.\"},{\"id\":\"4400\",\"n\":\"kettlebell step up\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a sturdy box or bench holding a kettlebell at your chest or by your side.\",\"Place one foot fully on the box.\",\"Press through that heel to stand tall on top.\",\"Lower back down slowly with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"4400.webp\",\"gif\":\"4400.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up on a bench or box while holding a kettlebell, working the quads and glutes one leg at a time.\"},{\"id\":\"4440\",\"n\":\"kettlebell step up v. 2\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand facing a bench or box holding a kettlebell.\",\"Place one foot flat on the box.\",\"Press through that heel to stand up.\",\"Lower back down slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"4440.webp\",\"gif\":\"4440.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with a kettlebell, held in a different position, to train the quads and glutes unilaterally.\"},{\"id\":\"3733\",\"n\":\"kettlebell straight leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand holding a kettlebell with both hands in front of your thighs.\",\"Keep your legs almost straight with a soft knee.\",\"Hinge at the hips and lower the bell along your legs.\",\"Keep your back flat.\",\"Drive your hips forward to stand.\"],\"img\":\"3733.webp\",\"gif\":\"3733.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-legged deadlift with a kettlebell that stretches and strengthens the hamstrings.\"},{\"id\":\"3572\",\"n\":\"kettlebell strict press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Hold the kettlebell at shoulder height in the rack position.\",\"Stand tall with glutes and abs tight.\",\"Press the bell straight overhead until your arm is locked out.\",\"Lower it back to the shoulder under control.\",\"Finish your reps, then switch arms.\"],\"img\":\"3572.webp\",\"gif\":\"3572.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press with a kettlebell and no leg drive, focused on shoulder strength.\"},{\"id\":\"10327\",\"n\":\"kettlebell strong russian twist\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor with knees bent and lean back slightly.\",\"Hold a kettlebell at your chest with both hands.\",\"Rotate your torso to bring the bell beside one hip.\",\"Rotate to the other side in a smooth motion.\",\"Keep your chest lifted and feet raised for more challenge.\"],\"img\":\"10327.webp\",\"gif\":\"10327.mp4\",\"cat\":\"strength\",\"desc\":\"A seated Russian twist with a kettlebell, taking the weight side to side to work the obliques and abs.\"},{\"id\":\"4133\",\"n\":\"kettlebell suitcase deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"obliques\",\"grip muscles\"],\"st\":[\"Stand beside a kettlebell and hinge to grip it.\",\"Keep your back flat.\",\"Stand up without leaning sideways.\",\"Lower it back to the floor.\",\"Switch hands after your set.\"],\"img\":\"4133.webp\",\"gif\":\"4133.mp4\",\"cat\":\"strength\",\"desc\":\"A one-sided deadlift holding the kettlebell at your side like a suitcase, training the core as well.\"},{\"id\":\"4046\",\"n\":\"kettlebell sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet wide and toes angled out, the kettlebell between your feet.\",\"Hinge and bend your knees to grip the handle with both hands.\",\"Keep your back flat and chest up.\",\"Drive through your feet to stand tall and squeeze your glutes.\",\"Lower the kettlebell under control.\"],\"img\":\"4046.webp\",\"gif\":\"4046.mp4\",\"cat\":\"strength\",\"desc\":\"Deadlift from a wide stance with a kettlebell between your feet. It trains the glutes, thighs and back.\"},{\"id\":\"4132\",\"n\":\"kettlebell sumo deadlift with high pull\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"trapezius\",\"shoulders\",\"quadriceps\",\"upper back\"],\"st\":[\"Stand wide over a kettlebell and grip it with both hands.\",\"Drive up through your legs.\",\"Pull it to chin height with elbows high.\",\"Lower it under control.\",\"Keep your back flat.\"],\"img\":\"4132.webp\",\"gif\":\"4132.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo deadlift flowing into a high pull, working legs, hips and upper back.\"},{\"id\":\"4089\",\"n\":\"kettlebell sumo squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet wider than shoulders and toes turned out, holding a kettlebell with both hands in front of you.\",\"Brace your core and keep your chest tall.\",\"Sit your hips down and back, pushing your knees out over your toes.\",\"Lower until your thighs are about parallel.\",\"Drive through your heels to stand and squeeze your glutes.\"],\"img\":\"4089.webp\",\"gif\":\"4089.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance squat holding a kettlebell between your legs, working your glutes, inner thighs and quads.\"},{\"id\":\"5073\",\"n\":\"kettlebell sumo squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Stand with feet wide and toes turned out, holding a kettlebell with both hands in front of you.\",\"Keep your chest tall and back flat.\",\"Sit down between your legs until your thighs are about parallel.\",\"Push your knees out over your toes.\",\"Drive through your heels to stand and squeeze your glutes.\"],\"img\":\"5073.webp\",\"gif\":\"5073.mp4\",\"cat\":\"strength\",\"desc\":\"Squat with a wide stance and a kettlebell hanging between your legs. It works the glutes, inner thighs and quads.\"},{\"id\":\"7563\",\"n\":\"kettlebell swing clean grip front squat\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet shoulder-width apart and the kettlebell on the floor in front of you.\",\"Hinge back and swing the bell between your legs.\",\"Drive your hips forward to swing, catching it in a clean position at your chest.\",\"Squat down with your chest tall.\",\"Stand back up and lower the bell to swing again.\",\"Keep your back flat throughout.\"],\"img\":\"7563.webp\",\"gif\":\"7563.mp4\",\"cat\":\"strength\",\"desc\":\"A combo that swings the kettlebell into a clean grip and finishes with a front squat for legs and hips.\"},{\"id\":\"5335\",\"n\":\"kettlebell swing clean grip front squat overhead press\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Stand over the kettlebell and swing it back between your legs.\",\"Swing it up, then clean it to the rack position at your shoulder.\",\"Squat down with the bell held in front of you.\",\"Stand up and press the bell overhead.\",\"Lower it back with control for the next rep.\",\"Switch arms after your set.\"],\"img\":\"5335.webp\",\"gif\":\"5335.mp4\",\"cat\":\"strength\",\"desc\":\"A kettlebell complex that links a swing, clean, front squat and press. A full-body strength and conditioning flow.\"},{\"id\":\"7751\",\"n\":\"kettlebell swing clean grip front squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet shoulder-width apart and the kettlebell on the floor in front of you.\",\"Hinge back and swing the bell between your legs.\",\"Drive your hips forward to swing, catching it in a clean position at your chest.\",\"Squat down with your chest tall.\",\"Stand back up and lower the bell to swing again.\",\"Keep your back flat throughout.\"],\"img\":\"7751.webp\",\"gif\":\"7751.mp4\",\"cat\":\"strength\",\"desc\":\"A combo that swings the kettlebell into a clean grip and finishes with a front squat for legs and hips.\"},{\"id\":\"7548\",\"n\":\"kettlebell swing to goblet squat\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"grip muscles\"],\"st\":[\"Swing the kettlebell up to chest height from a hip hinge.\",\"Catch it at your chest in a goblet hold.\",\"Sit into a deep squat.\",\"Stand up and lower the bell back between your legs.\",\"Hinge and swing again.\"],\"img\":\"7548.webp\",\"gif\":\"7548.mp4\",\"cat\":\"strength\",\"desc\":\"Kettlebell swing flowing into a goblet squat for hips, legs and grip.\"},{\"id\":\"4057\",\"n\":\"kettlebell turkish get up to hand\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"quadriceps\",\"shoulders\",\"obliques\"],\"st\":[\"Lie on your back with a kettlebell pressed up in one hand and the same-side knee bent.\",\"Keep your eyes on the kettlebell.\",\"Roll up onto your opposite elbow, then onto your hand.\",\"Hold the seated position with your arm vertical.\",\"Reverse the steps to lie back down, then switch sides.\"],\"img\":\"4057.webp\",\"gif\":\"4057.mp4\",\"cat\":\"strength\",\"desc\":\"The first part of a Turkish get up, rising from the floor to a seated position on your hand while holding a kettlebell overhead.\"},{\"id\":\"5099\",\"n\":\"kettlebell unilateral farmers walk\",\"bp\":\"full body\",\"eq\":\"kettlebell\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"obliques\",\"trapezius\",\"core\"],\"st\":[\"Pick up a kettlebell in one hand and stand tall.\",\"Brace your core and keep your shoulders level.\",\"Walk with steady steps without leaning to the loaded side.\",\"Walk for a set distance or time.\",\"Switch hands and repeat.\"],\"img\":\"5099.webp\",\"gif\":\"5099.mp4\",\"cat\":\"strength\",\"desc\":\"Walk while carrying a kettlebell in one hand. It builds grip and demands a strong trunk to stay upright.\",\"fv\":\"4529\"},{\"id\":\"4408\",\"n\":\"kettlebell upright row\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Stand tall holding a kettlebell with both hands in front of your thighs.\",\"Keep it close to your body.\",\"Pull it up toward your chest, leading with your elbows.\",\"Stop at about chest height.\",\"Lower slowly under control.\"],\"img\":\"4408.webp\",\"gif\":\"4408.mp4\",\"cat\":\"strength\",\"desc\":\"A vertical pull with a kettlebell that works the shoulders and upper traps.\"},{\"id\":\"8371\",\"n\":\"kettlebell weighted russian twist\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor with your knees bent and lean back slightly.\",\"Hold a kettlebell with both hands at your chest.\",\"Keep your back straight and rotate your torso to one side.\",\"Touch the kettlebell lightly near the floor.\",\"Rotate to the other side in a controlled way.\",\"Keep your feet down or lifted if you can stay stable.\"],\"img\":\"8371.webp\",\"gif\":\"8371.mp4\",\"cat\":\"strength\",\"desc\":\"A seated twist holding a kettlebell. It builds the obliques and trunk rotation strength.\"},{\"id\":\"8025\",\"n\":\"kettlebell wood chop\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Hold a kettlebell with both hands and stand with your feet wide.\",\"Start with it high beside one shoulder.\",\"Rotate and chop down to the opposite knee.\",\"Pivot your back foot as you turn.\",\"Return with control and switch sides.\"],\"img\":\"8025.webp\",\"gif\":\"8025.mp4\",\"cat\":\"strength\",\"desc\":\"A rotational chop holding a kettlebell from high to low across the body. It trains the obliques and builds rotational power.\"},{\"id\":\"5862\",\"n\":\"kettlebell wrist curl\",\"bp\":\"lower arms\",\"eq\":\"kettlebell\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit with your forearm on your thigh, palm up, holding a kettlebell.\",\"Let your wrist extend downward.\",\"Curl your hand up toward you.\",\"Squeeze at the top.\",\"Lower slowly and switch arms.\"],\"img\":\"5862.webp\",\"gif\":\"5862.mp4\",\"cat\":\"strength\",\"desc\":\"Curl a kettlebell with only your wrists while your forearm rests on your thigh. It builds forearm strength and grip.\"},{\"id\":\"9703\",\"n\":\"kettlebell z press\",\"bp\":\"shoulders\",\"eq\":\"kettlebell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"upper back\"],\"st\":[\"Sit on the floor with legs extended and hold a kettlebell at your shoulder.\",\"Sit tall and brace your core.\",\"Press the kettlebell overhead until your arm is straight.\",\"Lower it slowly to your shoulder.\",\"Finish your reps, then switch arms.\"],\"img\":\"9703.webp\",\"gif\":\"9703.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press done seated on the floor with legs straight. It removes leg drive and challenges the core.\"},{\"id\":\"4403\",\"n\":\"kettlebells sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"kettlebell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand with feet wide and toes turned out, kettlebells on the floor between your feet.\",\"Hinge down and grip the handles with a flat back.\",\"Push through your feet and stand up, squeezing your glutes.\",\"Keep the kettlebells close to your body.\",\"Lower back down by hinging at the hips.\"],\"img\":\"4403.webp\",\"gif\":\"4403.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance deadlift with a kettlebell or two that trains the glutes, inner thighs and legs.\"},{\"id\":\"4898\",\"n\":\"kick side jump\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"core\"],\"st\":[\"Stand tall with your knees slightly bent.\",\"Jump up off both feet.\",\"Kick one leg out to the side at the top.\",\"Land softly on both feet with soft knees.\",\"Repeat, alternating the kicking leg.\",\"Keep a controlled, bouncy rhythm.\"],\"img\":\"4898.webp\",\"gif\":\"4898.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lively jump that ends with a kick out to the side. It lifts your heart rate and trains leg power.\"},{\"id\":\"4159\",\"n\":\"kick through push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push up position with hands under your shoulders.\",\"Lower your chest and press back up.\",\"Lift one hand and rotate, sweeping the opposite leg through underneath you.\",\"Return the leg and hand to the starting position.\",\"Repeat the push up and kick on the other side.\",\"Stay controlled and keep your core braced.\"],\"img\":\"4159.webp\",\"gif\":\"4159.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push up followed by a quick kick of one leg through underneath your body. It builds chest strength with coordination.\"},{\"id\":\"5810\",\"n\":\"kicks leg bent\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Get on all fours with hands under shoulders and knees under hips.\",\"Keep your core tight and back flat.\",\"Lift one leg with the knee bent, pressing your foot toward the ceiling.\",\"Squeeze your glute at the top.\",\"Lower and repeat, then switch legs.\"],\"img\":\"5810.webp\",\"gif\":\"5810.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling glute kick back with the knee bent. It targets the glutes with a controlled squeeze.\",\"fv\":\"0557\"},{\"id\":\"0556\",\"n\":\"kicks leg bent v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Keep your core tight and your back flat.\",\"Lift one leg with the knee bent at 90 degrees.\",\"Press the sole of your foot toward the ceiling until your thigh is in line with your back.\",\"Squeeze your glute at the top.\",\"Lower with control and finish all reps, then switch sides.\"],\"img\":\"0556.webp\",\"gif\":\"0556.mp4\",\"cat\":\"calisthenics\",\"desc\":\"On hands and knees, you press one bent leg up toward the ceiling. It targets the glutes with a simple, controlled kickback.\"},{\"id\":\"5151\",\"n\":\"kipping handstand push up\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Kick up into a handstand against a wall.\",\"Lower your head toward the floor under control.\",\"Bend your hips and knees slightly, then drive them back out as you press.\",\"Press up to lockout.\",\"Keep your core tight and move carefully.\"],\"img\":\"5151.webp\",\"gif\":\"5151.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Use a leg kick to help drive yourself up from a handstand push-up. It lets you handle more reps and volume overhead.\"},{\"id\":\"2773\",\"n\":\"knee extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Sit tall on a bench or chair with your feet off the floor.\",\"Straighten one knee until the leg is almost fully extended.\",\"Squeeze your thigh at the top, then lower slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2773.webp\",\"gif\":\"2773.mp4\",\"cat\":\"mobility\",\"desc\":\"Straightening the knee, which works the front of the thigh.\"},{\"id\":\"2774\",\"n\":\"knee flexion\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall holding a support, with your weight on one leg.\",\"Bend the other knee to bring your heel up toward your glutes.\",\"Keep your thighs side by side, pause, then lower slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2774.webp\",\"gif\":\"2774.mp4\",\"cat\":\"mobility\",\"desc\":\"Bending the knee to bring the heel toward the glutes, working the back of the thigh.\"},{\"id\":\"6231\",\"n\":\"knee push up chest pullback\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a knee push-up position.\",\"Lower your chest to the floor.\",\"Press back up.\",\"Push your hips back toward your heels.\",\"Return to the start.\",\"Keep your core tight.\"],\"img\":\"6231.webp\",\"gif\":\"6231.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A knee push-up followed by a pullback of the hips. It trains the chest and adds a mobility element.\"},{\"id\":\"4287\",\"n\":\"knee raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"glutes\"],\"st\":[\"Stand tall with your arms at your sides.\",\"Lift one knee up toward your chest.\",\"Hold it for a moment.\",\"Lower the foot with control.\",\"Alternate legs.\",\"Keep your standing leg steady and your back straight.\"],\"img\":\"4287.webp\",\"gif\":\"4287.mp4\",\"cat\":\"mobility\",\"desc\":\"Lifting your knee toward your chest to warm up the hips and activate the hip flexors. A simple dynamic drill.\",\"fv\":\"3252\"},{\"id\":\"10563\",\"n\":\"knee to box calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Place a foot flat a short distance from a box or step.\",\"Keep your heel down.\",\"Push your knee forward to touch the box.\",\"Hold for 20-30 seconds, feeling a calf stretch.\",\"Switch legs and repeat.\"],\"img\":\"10563.webp\",\"gif\":\"10563.mp4\",\"cat\":\"stretching\",\"desc\":\"Press one knee forward toward a box with your foot flat to stretch the calf. It improves ankle flexibility.\"},{\"id\":\"0559\",\"n\":\"knee to chest stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back with both legs straight.\",\"Bend one knee and clasp your hands around the shin or behind the thigh.\",\"Gently pull the knee toward your chest.\",\"Keep the other leg relaxed on the floor.\",\"Hold for 20-30 seconds while breathing slowly.\",\"Release and switch sides.\"],\"img\":\"0559.webp\",\"gif\":\"0559.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back, you hug one knee toward your chest. It stretches the glutes and eases the lower back.\"},{\"id\":\"1570\",\"n\":\"knee tuck jump\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"calves\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and arms ready.\",\"Dip into a quarter squat and swing your arms back.\",\"Jump explosively and tuck both knees toward your chest.\",\"Extend your legs again before landing.\",\"Land softly on bent knees and reset before the next jump.\"],\"img\":\"1570.webp\",\"gif\":\"1570.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive vertical jump where you pull your knees into your chest at the top. Great for power and conditioning.\"},{\"id\":\"4990\",\"n\":\"knee tuck oblique crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with your hands behind your head.\",\"Lift your shoulders off the floor.\",\"Tuck one knee in while rotating your opposite elbow toward it.\",\"Return and repeat to the other side.\",\"Move with control instead of pulling on your neck.\"],\"img\":\"4990.webp\",\"gif\":\"4990.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Drive a knee toward the opposite elbow to crunch the side of your waist. It trains the obliques and lower abs.\"},{\"id\":\"8894\",\"n\":\"knee tuck push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push-up position with a straight body.\",\"Lower your chest toward the floor.\",\"Press back up.\",\"Pull one knee toward your chest.\",\"Return the leg and repeat on the other side.\",\"Keep your hips level.\"],\"img\":\"8894.webp\",\"gif\":\"8894.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with a knee tuck toward the chest at the top. It combines upper body pressing with an ab crunch.\"},{\"id\":\"5242\",\"n\":\"kneeling abdominal draw in\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Kneel on all fours with your hands under your shoulders.\",\"Relax your belly toward the floor.\",\"Draw your navel up toward your spine.\",\"Hold for 10-15 seconds while breathing normally.\",\"Release slowly and repeat.\"],\"img\":\"5242.webp\",\"gif\":\"5242.mp4\",\"cat\":\"isometric\",\"desc\":\"Pulling your belly in while kneeling. It teaches deep abdominal control.\"},{\"id\":\"2109\",\"n\":\"kneeling abdominal stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Kneel with your knees hip width apart and place your hands on your lower back.\",\"Push your hips forward and lean back until the abdominal muscles stretch.\",\"Tuck your chin a little and avoid dropping your head back.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2109.webp\",\"gif\":\"2109.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling backbend that opens the front of the torso.\"},{\"id\":\"4919\",\"n\":\"kneeling assisted sliding chin up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Kneel below a bar and grab it with an underhand grip.\",\"Place a towel or slider under your knees.\",\"Pull your chest toward the bar.\",\"Use your legs lightly to help.\",\"Lower slowly to straight arms.\",\"Keep your shoulders away from your ears.\"],\"img\":\"4919.webp\",\"gif\":\"4919.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling, assisted chin up where you slide on the floor to reduce the load. It helps you build toward full chin ups.\"},{\"id\":\"5029\",\"n\":\"kneeling back rotation\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Kneel on all fours with one hand behind your head.\",\"Keep your hips still and your core lightly braced.\",\"Rotate your elbow down toward the other arm, then open toward the ceiling.\",\"Follow the elbow with your eyes.\",\"Do your reps, then switch sides.\"],\"img\":\"5029.webp\",\"gif\":\"5029.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the upper back from a kneeling position. It improves spinal rotation and loosens the mid back.\"},{\"id\":\"1812\",\"n\":\"kneeling back rotation stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"lower back\"],\"st\":[\"Start on your hands and knees with your hands under your shoulders.\",\"Place one hand behind your head and rotate your elbow up toward the ceiling.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1812.webp\",\"gif\":\"1812.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling on all fours and rotating through your trunk mobilises and stretches your mid back. Slow and controlled works best.\",\"fv\":\"4297\"},{\"id\":\"2929\",\"n\":\"kneeling battling ropes\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"forearms\",\"grip muscles\",\"lats\"],\"st\":[\"Kneel in front of the anchored ropes and hold an end in each hand.\",\"Brace your abs and keep your chest up.\",\"Raise and lower your arms alternately to create waves.\",\"Keep the waves quick and steady.\",\"Work for a set time, then rest.\"],\"img\":\"2929.webp\",\"gif\":\"2929.mp4\",\"cat\":\"cardio\",\"desc\":\"Making waves with heavy ropes while kneeling. It raises your heart rate and burns the shoulders and arms.\"},{\"id\":\"10543\",\"n\":\"kneeling bend knee chair supported\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"calves\"],\"st\":[\"Hold the back of a chair and kneel on one knee on a soft surface.\",\"Keep your torso upright.\",\"Slowly sit back toward your heel to bend the knee.\",\"Stay within a comfortable range.\",\"Return to the start and switch sides after your reps.\"],\"img\":\"10543.webp\",\"gif\":\"10543.mp4\",\"cat\":\"mobility\",\"desc\":\"Kneeling beside a chair for support, you gently bend the knee. It builds comfortable knee range of motion.\"},{\"id\":\"1785\",\"n\":\"kneeling chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"lats\"],\"st\":[\"Kneel in front of a bench or chair and rest your forearms or hands on it.\",\"Sit your hips back and let your chest drop toward the floor until you feel the stretch.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1785.webp\",\"gif\":\"1785.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling with your arms reaching forward onto a support lets your chest sink down. It stretches the chest and shoulders.\"},{\"id\":\"3489\",\"n\":\"kneeling cobra push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"lower back\",\"core\"],\"st\":[\"Kneel on a mat and place your hands under your shoulders.\",\"Keep a straight line from head to knees.\",\"Lower your chest to the floor with elbows close.\",\"Press up and let your hips sink forward, lifting your chest into a cobra.\",\"Shift your hips back to the start.\",\"Repeat smoothly.\"],\"img\":\"3489.webp\",\"gif\":\"3489.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling version of the cobra push-up that is easier on the arms and core. It works the chest and gently extends the spine.\"},{\"id\":\"1901\",\"n\":\"kneeling face down adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"hip flexors\"],\"st\":[\"Kneel on a mat, then lower your chest and forearms to the floor.\",\"Slide your knees wide apart and sink your hips back toward your heels until you feel the inner thighs stretch.\",\"Keep your breathing slow and stay relaxed, without bouncing.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1901.webp\",\"gif\":\"1901.mp4\",\"cat\":\"stretching\",\"desc\":\"A floor stretch that opens up the inner thighs while you rest face down on your forearms.\"},{\"id\":\"5057\",\"n\":\"kneeling forward hip circles\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"adductors\"],\"st\":[\"Kneel with your hands on your hips.\",\"Push your hips forward slightly.\",\"Draw large circles with your hips, leading forward and around.\",\"Do several circles in one direction.\",\"Switch direction and repeat.\"],\"img\":\"5057.webp\",\"gif\":\"5057.mp4\",\"cat\":\"mobility\",\"desc\":\"Circle your hips in a kneeling position. It warms up the hip joints and glutes.\"},{\"id\":\"6747\",\"n\":\"kneeling glute press\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Get on all fours with hands under shoulders and knees under hips.\",\"Brace your core and keep your back flat.\",\"Press one foot back and up, leading with the heel.\",\"Squeeze the glute at the top without arching your back.\",\"Lower with control.\",\"Finish the reps, then switch legs.\"],\"img\":\"6747.webp\",\"gif\":\"6747.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling move pressing one leg back to fire the glute. Great for learning to feel the glutes work.\"},{\"id\":\"4893\",\"n\":\"kneeling half triceps extension\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Kneel facing the cable stack and hold the attachment with elbows bent.\",\"Tuck your elbows close to your sides.\",\"Press the handle down until your arms are straight.\",\"Squeeze the triceps at the bottom.\",\"Let the hands rise only halfway, keeping tension.\",\"Keep your upper arms still throughout.\"],\"img\":\"4893.webp\",\"gif\":\"4893.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling cable triceps extension done in a short range at the lockout. It isolates the triceps.\"},{\"id\":\"1892\",\"n\":\"kneeling heel down achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Kneel on one knee with the other foot forward.\",\"Lean forward, keeping your front heel on the floor.\",\"Press your front knee over your toes.\",\"Feel the stretch behind the ankle.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1892.webp\",\"gif\":\"1892.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling stretch with the heel pressed down to lengthen the Achilles.\"},{\"id\":\"0560\",\"n\":\"kneeling hip flexor\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Kneel on one knee with the other foot flat in front of you.\",\"Place a pad under your back knee if needed.\",\"Tuck your pelvis and squeeze the glute of the back leg.\",\"Shift your hips gently forward until you feel a stretch at the front of the hip.\",\"Hold for 20-30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"0560.webp\",\"gif\":\"0560.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling lunge stretch that opens the front of the hip and thigh. Good after sitting or leg training.\"},{\"id\":\"1053\",\"n\":\"kneeling hip flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Kneel on one knee with the other foot forward in a lunge.\",\"Tuck your pelvis under and squeeze your back glute.\",\"Shift your hips forward gently.\",\"Hold for 20-30 seconds, keeping your torso tall.\",\"Switch sides and repeat.\"],\"img\":\"1053.webp\",\"gif\":\"1053.mp4\",\"cat\":\"stretching\",\"desc\":\"A lunge-style stretch on one knee that lengthens the front of the hip. It helps with tightness from sitting.\",\"fv\":\"7253\"},{\"id\":\"4669\",\"n\":\"kneeling hip thrust\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Kneel upright with your hips over your knees and your arms by your sides.\",\"Sit your hips back toward your heels.\",\"Drive your hips forward, squeezing your glutes.\",\"Stand tall at the top without leaning back.\",\"Return slowly and repeat.\"],\"img\":\"4669.webp\",\"gif\":\"4669.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip thrust from a kneeling position. It works the glutes and teaches strong hip extension.\"},{\"id\":\"6771\",\"n\":\"kneeling iliopsoas stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Kneel on one knee with the other foot forward.\",\"Tuck your pelvis and brace your abs.\",\"Shift your weight forward until you feel the stretch at the front of the hip.\",\"Raise the arm on the kneeling side overhead.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch legs.\"],\"img\":\"6771.webp\",\"gif\":\"6771.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling lunge stretch for the deep hip flexor. It helps loosen the front of the hip.\"},{\"id\":\"11792\",\"n\":\"kneeling isometric biceps hold\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Kneel upright with your elbows bent at about 90 degrees.\",\"Hold your hands in front of you with palms up.\",\"Keep your elbows pinned to your sides.\",\"Squeeze your biceps and hold the position.\",\"Hold for 20-30 seconds, then rest.\"],\"img\":\"11792.webp\",\"gif\":\"11792.mp4\",\"cat\":\"isometric\",\"desc\":\"A static curl hold that builds biceps endurance.\",\"hd\":1},{\"id\":\"4559\",\"n\":\"kneeling lat stretch on bench\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Kneel in front of a bench and place both elbows on top of it.\",\"Keep your hands together or hold a light stick.\",\"Sit your hips back and let your chest sink toward the floor.\",\"Keep your lower back relaxed.\",\"Hold for 20-30 seconds while breathing slowly.\",\"Come back up carefully.\"],\"img\":\"4559.webp\",\"gif\":\"4559.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling stretch with the arms on a bench that opens the lats and shoulders.\"},{\"id\":\"4693\",\"n\":\"kneeling leg half circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Start on all fours, hands under shoulders.\",\"Lift one leg out straight behind you.\",\"Sweep it in a half circle out to the side.\",\"Return the same way.\",\"Keep your hips square and switch sides.\"],\"img\":\"4693.webp\",\"gif\":\"4693.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling leg arc that works the glutes and outer hip through a half circle.\",\"fv\":\"4814\"},{\"id\":\"1898\",\"n\":\"kneeling leg out adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Kneel on all fours with your knees under your hips.\",\"Extend one leg out to the side with the foot flat.\",\"Sit your hips back toward the opposite heel.\",\"Keep your back straight and your extended leg straight.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1898.webp\",\"gif\":\"1898.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling stretch with one leg extended to the side to open the inner thigh and groin.\"},{\"id\":\"4984\",\"n\":\"kneeling modified hindu push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"lower back\"],\"st\":[\"Start on your knees and hands with hips high, like a pike.\",\"Bend your elbows and swoop your chest down and forward close to the floor.\",\"Push through your arms to glide your chest up and forward, arching slightly.\",\"Reverse the path, pushing your hips back up to the start.\",\"Move smoothly and keep your core engaged.\"],\"img\":\"4984.webp\",\"gif\":\"4984.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An easier knee-supported version of the hindu push up. The flowing dip and sweep trains the chest, shoulders and triceps and opens the spine.\"},{\"id\":\"5058\",\"n\":\"kneeling neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Kneel tall with your back straight.\",\"Tilt your head to one side, ear toward shoulder.\",\"Place a hand lightly on your head for a gentle pull.\",\"Keep the opposite shoulder low.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"5058.webp\",\"gif\":\"5058.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling side neck stretch. It releases tension in the sides and back of the neck.\"},{\"id\":\"1988\",\"n\":\"kneeling one arm cross body stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\"],\"st\":[\"Kneel on a mat and slide one arm across the floor in front of you, palm down.\",\"Sink your chest toward the floor and keep reaching until the shoulder and upper back stretch.\",\"Keep your hips over your knees.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1988.webp\",\"gif\":\"1988.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling stretch where you reach one arm across the body to open the back of the shoulder.\"},{\"id\":\"3417\",\"n\":\"kneeling one arm reach roll lift\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"obliques\"],\"st\":[\"Start on hands and knees with hands under shoulders.\",\"Reach one arm forward along the floor.\",\"Roll that arm up and across, rotating your chest.\",\"Lift it toward the ceiling, following your hand with your eyes.\",\"Return and repeat, then switch arms.\"],\"img\":\"3417.webp\",\"gif\":\"3417.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling drill where one arm reaches, rolls and lifts to open the upper back and shoulders.\"},{\"id\":\"3238\",\"n\":\"kneeling plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\",\"lower abs\"],\"st\":[\"Kneel and place your forearms on the floor under your shoulders.\",\"Lift your hips so your body is in a line from your knees to your head.\",\"Brace your core and squeeze your glutes.\",\"Keep your neck neutral.\",\"Hold for 20-45 seconds.\",\"Lower and rest.\"],\"img\":\"3238.webp\",\"gif\":\"3238.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank held on the knees. It's an easier version that builds core strength.\",\"hd\":1,\"fv\":\"4996\"},{\"id\":\"10882\",\"n\":\"kneeling plyo push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Kneel in a push-up position with hands under shoulders.\",\"Keep a straight line from knees to head.\",\"Lower your chest toward the floor.\",\"Push up explosively so your hands leave the floor.\",\"Land softly with bent elbows.\",\"Go straight into the next rep.\"],\"img\":\"10882.webp\",\"gif\":\"10882.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive push-up from the knees. It builds pressing power.\"},{\"id\":\"5170\",\"n\":\"kneeling pulse\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Kneel on all fours with your hands under your shoulders.\",\"Lift one leg back with the knee bent at about 90 degrees.\",\"Pulse the foot upward in small, controlled movements.\",\"Keep your hips square and your back flat.\",\"Finish the set, then switch legs.\"],\"img\":\"5170.webp\",\"gif\":\"5170.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small pulsing leg lifts from a kneeling position. It gives your glutes a burning, focused workout.\",\"fv\":\"4656\"},{\"id\":\"3265\",\"n\":\"kneeling push up to child pose\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"glutes\"],\"st\":[\"Start on your hands and knees with hands slightly wider than your shoulders.\",\"Lower your chest toward the floor, elbows at about 45 degrees.\",\"Press back up to the start.\",\"Push your hips back onto your heels and reach your arms forward into child pose.\",\"Return to the start and repeat.\"],\"img\":\"3265.webp\",\"gif\":\"3265.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A knee push-up that ends by sitting your hips back into child pose, building the chest and giving the back a stretch.\"},{\"id\":\"7895\",\"n\":\"kneeling rotation torso rear fly to thread through\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\",\"obliques\",\"shoulders\"],\"st\":[\"Start on hands and knees.\",\"Place one hand behind your head and rotate your torso open, elbow to the ceiling.\",\"Return and thread that arm under your chest.\",\"Let your shoulder reach toward the floor.\",\"Keep your hips still.\",\"Finish all reps, then switch sides.\"],\"img\":\"7895.webp\",\"gif\":\"7895.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling thoracic mobility move combining a rear fly and a thread-the-needle reach.\"},{\"id\":\"3492\",\"n\":\"kneeling rotational push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Start in a kneeling push-up position, hands under shoulders.\",\"Lower your chest toward the floor.\",\"Press up and rotate your torso, lifting one arm toward the ceiling.\",\"Look at your raised hand for a moment.\",\"Bring the hand back down and lower for the next rep.\",\"Alternate sides each rep.\"],\"img\":\"3492.webp\",\"gif\":\"3492.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling push-up that ends with a rotation and one arm reaching up. It trains the chest and trunk control.\"},{\"id\":\"6770\",\"n\":\"kneeling sartorius stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\"],\"st\":[\"Kneel on one knee in a half-kneeling position.\",\"Tuck your pelvis and squeeze the glute of the back leg.\",\"Shift your hips forward slightly.\",\"Lean slightly to the side of the back leg.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch legs.\"],\"img\":\"6770.webp\",\"gif\":\"6770.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling stretch for the long strap muscle across the front of the thigh and hip.\"},{\"id\":\"4117\",\"n\":\"kneeling scapular push up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"chest\",\"shoulders\",\"core\"],\"st\":[\"Kneel in a plank position with straight arms.\",\"Keep your elbows locked.\",\"Let your chest sink by pinching your shoulder blades together.\",\"Push the floor away to spread them apart.\",\"Keep your core braced.\"],\"img\":\"4117.webp\",\"gif\":\"4117.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling push up that moves only the shoulder blades, strengthening the muscles that stabilize them.\",\"fv\":\"9760\"},{\"id\":\"4506\",\"n\":\"kneeling shoulder tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"obliques\",\"chest\"],\"st\":[\"Start on hands and knees, then lift your knees slightly into a kneeling plank.\",\"Keep a straight line from head to knees.\",\"Lift one hand and tap the opposite shoulder.\",\"Place it back down without rocking your hips.\",\"Alternate sides at a steady pace.\",\"Keep your abs tight throughout.\"],\"img\":\"4506.webp\",\"gif\":\"4506.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling plank with alternating shoulder taps. Trains anti-rotation core control and shoulder stability.\",\"fv\":\"4661\"},{\"id\":\"4658\",\"n\":\"kneeling shoulder tap push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a kneeling push-up position with hands under your shoulders.\",\"Lower your chest toward the floor.\",\"Press back up to straight arms.\",\"Lift one hand and tap the opposite shoulder, then switch.\",\"Keep your hips steady and repeat.\"],\"img\":\"4658.webp\",\"gif\":\"4658.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A kneeling push-up followed by a quick shoulder tap with each hand. It builds the chest and shoulder stability.\"},{\"id\":\"4691\",\"n\":\"kneeling side leg to kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\"],\"st\":[\"Kneel on all fours with hands under shoulders.\",\"Lift one leg out to the side, bent.\",\"Extend it into a kick out to the side.\",\"Bend it back in and lower.\",\"Finish the reps and switch legs.\"],\"img\":\"4691.webp\",\"gif\":\"4691.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling side kick that works the glutes and outer hips while challenging balance.\",\"fv\":\"4813\"},{\"id\":\"6748\",\"n\":\"kneeling single hamstring curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Get on all fours with hands under shoulders.\",\"Keep your back flat and core tight.\",\"Bend one knee and curl your heel toward your glute.\",\"Squeeze the hamstring at the top.\",\"Lower the foot slowly.\",\"Finish the reps, then switch legs.\"],\"img\":\"6748.webp\",\"gif\":\"6748.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hamstring curl done from a kneeling position, one leg at a time. It works the back of the thigh.\"},{\"id\":\"5278\",\"n\":\"kneeling staggered push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Kneel and place your hands on the floor, one slightly forward of the other.\",\"Keep your body straight from knees to head.\",\"Lower your chest toward the floor.\",\"Press back up.\",\"Keep your elbows at about 45 degrees.\",\"Switch hand positions on the next set.\"],\"img\":\"5278.webp\",\"gif\":\"5278.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up from your knees with hands set at staggered heights. It builds the chest in a more manageable way.\"},{\"id\":\"4772\",\"n\":\"kneeling straight leg kickback v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Get on all fours with hands under shoulders and knees under hips.\",\"Extend one leg straight behind you with the toes on the floor.\",\"Squeeze the glute and lift the straight leg to hip height.\",\"Pause briefly, then lower the leg without letting the back arch.\",\"Keep your hips level and your core tight.\",\"Finish your reps, then switch legs.\"],\"img\":\"4772.webp\",\"gif\":\"4772.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling kickback with the working leg kept straight, a second variation. It targets the glutes and the back of the thigh.\"},{\"id\":\"6209\",\"n\":\"kneeling straight leg kickback v. 2 (left)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Start on all fours.\",\"Extend your left leg straight behind you.\",\"Lift it to hip height.\",\"Squeeze the glute at the top.\",\"Lower with control.\",\"Keep your hips level.\"],\"img\":\"6209.webp\",\"gif\":\"6209.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling kickback with a straight leg on the left side. It targets the glutes.\"},{\"id\":\"4896\",\"n\":\"kneeling straight leg side kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Get on all fours with hands under shoulders and knees under hips.\",\"Extend one leg out to the side with the knee straight.\",\"Lift the leg to about hip height.\",\"Keep your hips and back steady.\",\"Lower with control without touching down.\",\"Finish your reps, then switch legs.\"],\"img\":\"4896.webp\",\"gif\":\"4896.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling side kick with a straight leg. It works the outer hip and glutes.\"},{\"id\":\"3526\",\"n\":\"kneeling t spine mobility\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"shoulders\"],\"st\":[\"Kneel on all fours.\",\"Place one hand behind your head.\",\"Rotate your elbow toward the opposite arm.\",\"Open up and rotate toward the ceiling.\",\"Follow your elbow with your eyes.\",\"Do your reps, then switch sides.\"],\"img\":\"3526.webp\",\"gif\":\"3526.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling rotation drill for upper back mobility.\"},{\"id\":\"3540\",\"n\":\"kneeling t spine mobility stretching\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"shoulders\"],\"st\":[\"Kneel on all fours.\",\"Place one hand behind your head.\",\"Rotate your elbow up toward the ceiling.\",\"Hold for 20-30 seconds.\",\"Return to start.\",\"Switch sides.\"],\"img\":\"3540.webp\",\"gif\":\"3540.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling thoracic rotation stretch.\"},{\"id\":\"8052\",\"n\":\"kneeling thoracic rotation\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"shoulders\"],\"st\":[\"Kneel on all fours with your hands under your shoulders.\",\"Place one hand behind your head.\",\"Rotate your upper body and point that elbow toward the ceiling.\",\"Follow your elbow with your eyes and keep your hips square.\",\"Return and touch the elbow toward the opposite arm.\",\"Do your reps, then switch sides.\"],\"img\":\"8052.webp\",\"gif\":\"8052.mp4\",\"cat\":\"mobility\",\"desc\":\"A kneeling rotation that opens up the mid back. Good for loosening your upper spine before training or after sitting.\"},{\"id\":\"10743\",\"n\":\"kneeling to box jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Kneel in front of a sturdy box.\",\"Swing your arms back and drive your hips forward.\",\"Pop up from your knees onto your feet.\",\"Jump onto the box in one motion.\",\"Land softly and stand tall.\",\"Step down and reset.\"],\"img\":\"10743.webp\",\"gif\":\"10743.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive move that goes from kneeling straight into a box jump. It trains hip drive and power.\"},{\"id\":\"10750\",\"n\":\"kneeling to stand\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"calves\"],\"st\":[\"Kneel with your torso upright.\",\"Place one foot forward into a lunge.\",\"Push through that foot to stand.\",\"Bring your back foot to meet it.\",\"Reverse the motion to return to kneeling.\",\"Alternate the lead leg.\"],\"img\":\"10750.webp\",\"gif\":\"10750.mp4\",\"cat\":\"mobility\",\"desc\":\"A smooth transition from kneeling to standing. It builds leg strength and control.\"},{\"id\":\"8533\",\"n\":\"kneeling to standing squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Kneel on both knees with your torso upright.\",\"Step one foot forward and then the other so both feet are flat.\",\"Press up to stand, then sit back into a squat.\",\"Return to kneeling under control.\",\"Alternate which foot steps first.\"],\"img\":\"8533.webp\",\"gif\":\"8533.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A flowing move from kneeling up into a squat, working the legs, glutes and balance.\"},{\"id\":\"1913\",\"n\":\"kneeling toe up hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Kneel on one knee and extend the other leg in front, heel on the floor and toes pulled up.\",\"Place your hands on the floor or the front thigh for support.\",\"Hinge forward at the hips with a flat back until you feel a pull behind the extended leg.\",\"Keep the extended knee straight but not locked.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1913.webp\",\"gif\":\"1913.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling on one knee with the other leg extended and toes up to stretch the hamstring and calf.\"},{\"id\":\"3557\",\"n\":\"kneeling wide hand push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\",\"core\"],\"st\":[\"Kneel on a mat and place your hands wider than your shoulders.\",\"Keep a straight line from head to knees.\",\"Lower your chest toward the floor.\",\"Press back up to straight arms.\",\"Keep your core tight.\",\"Do not let your hips sag.\"],\"img\":\"3557.webp\",\"gif\":\"3557.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A kneeling push-up with the hands wider apart. It puts more emphasis on the chest.\"},{\"id\":\"0561\",\"n\":\"kneeling wrist flexor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\"],\"st\":[\"Kneel on the floor and place your palms down with fingers pointing toward your knees.\",\"Keep your palms flat and arms straight.\",\"Slowly sit your hips back to increase the stretch.\",\"Stop when you feel a pull along the inner forearms.\",\"Hold for 20-30 seconds.\",\"Ease off gently and shake out your hands.\"],\"img\":\"0561.webp\",\"gif\":\"0561.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling on the floor, you press your palms down to stretch the underside of the forearms. Useful for lifters with tight wrists.\"},{\"id\":\"4192\",\"n\":\"knuckle push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"wrist flexors\"],\"st\":[\"Make fists and place them under your shoulders.\",\"Keep your body straight.\",\"Lower your chest.\",\"Press up.\",\"Keep wrists neutral.\",\"Brace your core.\"],\"img\":\"4192.webp\",\"gif\":\"4192.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push up on your knuckles to keep wrists straight. It builds chest and arm strength.\"},{\"id\":\"5971\",\"n\":\"l drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Place three cones in an L shape, about 5 yards apart.\",\"Sprint from the start cone to the second and touch it.\",\"Backpedal to the start.\",\"Sprint to the second again, turn around the cone and weave around the third.\",\"Return to the start along the same line.\",\"Stay low through turns.\"],\"img\":\"5971.webp\",\"gif\":\"5971.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A cone drill run in an L shape that sharpens sprinting, backpedaling and quick cuts.\"},{\"id\":\"1402\",\"n\":\"l sit\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"triceps\",\"shoulders\",\"quadriceps\"],\"st\":[\"Sit between two supports or on the floor and place your hands beside your hips.\",\"Press down through your hands to lift your hips and legs off the floor.\",\"Extend your legs straight in front of you.\",\"Keep your shoulders pressed down and your core tight.\",\"Hold for as long as you can with good form, then lower.\"],\"img\":\"1402.webp\",\"gif\":\"1402.mp4\",\"cat\":\"isometric\",\"desc\":\"An isometric hold where your body is supported by your arms and your legs stay straight out in front, forming an L.\",\"hd\":1},{\"id\":\"10951\",\"n\":\"l sit leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"triceps\",\"lower abs\"],\"st\":[\"Sit on the floor with your hands on parallettes or flat beside you.\",\"Press down to lift your hips.\",\"Extend your legs in front of you.\",\"Raise your legs higher and lower them back to the L position.\",\"Keep your arms straight and shoulders down.\"],\"img\":\"10951.webp\",\"gif\":\"10951.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A raise from an L-sit position. It builds strong abs and hip flexors.\"},{\"id\":\"10731\",\"n\":\"l sit rope climb\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"core\",\"hip flexors\"],\"st\":[\"Grip the rope and hang with your legs raised in front of you.\",\"Keep your legs straight and together.\",\"Pull with one hand over the other while staying in the L position.\",\"Reach up and repeat.\",\"Lower under control.\",\"Stop if your legs drop.\"],\"img\":\"10731.webp\",\"gif\":\"10731.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A rope climb done with your legs held out in an L shape. It is a tough test for the lats, grip and abs.\"},{\"id\":\"5972\",\"n\":\"ladder drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"ankles\",\"core\"],\"st\":[\"Lay an agility ladder flat on the ground.\",\"Stand at the start in an athletic stance.\",\"Step quickly with both feet into each square, one after another.\",\"Stay light on the balls of your feet.\",\"Pump your arms and keep your eyes up.\",\"Jog back and repeat for several rounds.\"],\"img\":\"5972.webp\",\"gif\":\"5972.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A footwork drill through an agility ladder that builds quick feet, rhythm and coordination.\"},{\"id\":\"10056\",\"n\":\"landmine banded press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Set up a landmine with a band attached and hold the end of the bar at your shoulder.\",\"Stand with feet staggered and core braced.\",\"Press the bar up and forward until your arm is straight.\",\"Lower it to your shoulder under control.\",\"Finish your reps, then switch arms.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"10056.webp\",\"gif\":\"10056.mp4\",\"cat\":\"strength\",\"desc\":\"A landmine press with a band adding extra resistance on the way up.\"},{\"id\":\"10052\",\"n\":\"landmine cossack squat\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet wide, holding the end of a landmine bar at your chest.\",\"Shift to one side and bend that knee deeply.\",\"Keep the other leg straight with the toes up.\",\"Push through the bent leg to return to centre.\",\"Shift to the other side.\",\"Keep your chest tall and heel down on the working side.\"],\"img\":\"10052.webp\",\"gif\":\"10052.mp4\",\"cat\":\"strength\",\"desc\":\"A side-to-side deep squat holding a landmine end at your chest. It works the glutes, inner thighs and hip mobility.\"},{\"id\":\"7883\",\"n\":\"landmine deadlift\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\",\"core\",\"grip muscles\"],\"st\":[\"Load one end of the barbell in a landmine and stand facing it, feet hip-width.\",\"Hinge back and grip the bar end with both hands.\",\"Brace your abs and keep your back flat.\",\"Drive your hips forward to stand.\",\"Lower the bar under control.\",\"Repeat for the planned reps.\"],\"img\":\"7883.webp\",\"gif\":\"7883.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with the end of a landmine bar, easier on the back and good for hips and hamstrings.\"},{\"id\":\"3923\",\"n\":\"landmine floor one arm chest fly\",\"bp\":\"chest\",\"eq\":\"landmine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"core\"],\"st\":[\"Lie on the floor holding the landmine bar end with one hand.\",\"Extend the arm above your chest.\",\"Lower the bar out to the side in an arc.\",\"Stop when your arm touches the floor.\",\"Squeeze your chest to bring the bar back up.\",\"Switch sides.\"],\"img\":\"3923.webp\",\"gif\":\"3923.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm fly on the floor with a landmine bar, training the chest and stability.\"},{\"id\":\"4246\",\"n\":\"landmine front squat\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Load the landmine bar and hold the end against your chest with both hands.\",\"Stand with your feet shoulder-width apart.\",\"Brace and squat down, keeping your chest tall.\",\"Go as deep as you can with a flat back.\",\"Drive up through your whole foot.\",\"Keep your elbows pointing down.\"],\"img\":\"4246.webp\",\"gif\":\"4246.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding the end of a landmine bar at your chest. The angled bar helps keep you upright and easy on the back.\"},{\"id\":\"5628\",\"n\":\"landmine hack squat\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the end of a landmine bar at your chest.\",\"Stand with feet shoulder width.\",\"Squat down with your chest up.\",\"Drive through your heels to stand.\",\"Keep the bar close.\"],\"img\":\"5628.webp\",\"gif\":\"5628.mp4\",\"cat\":\"strength\",\"desc\":\"Squat with a landmine bar held at your chest, mimicking a hack squat.\"},{\"id\":\"9695\",\"n\":\"landmine half kneeling shoulders press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"glutes\"],\"st\":[\"Kneel on one knee and hold the end of the landmine at your shoulder.\",\"Brace your core and squeeze your glutes.\",\"Press the end up and forward until your arm is straight.\",\"Lower slowly to your shoulder.\",\"Complete your reps, then switch sides.\"],\"img\":\"9695.webp\",\"gif\":\"9695.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm landmine press from a half-kneeling position, easy on the shoulder and tough on the core.\",\"fv\":\"10767\"},{\"id\":\"11092\",\"n\":\"landmine kneeling 180s\",\"bp\":\"waist\",\"eq\":\"landmine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Kneel facing the landmine and hold the end of the bar with both hands in front of your chest.\",\"Keep your hips squared and core tight.\",\"Swing the bar in an arc to one side by rotating your torso.\",\"Swing across to the other side in a controlled sweep.\",\"Keep a steady rhythm for the set.\"],\"img\":\"11092.webp\",\"gif\":\"11092.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling rotational move with a landmine bar, swinging it in a wide arc side to side. It builds strong, rotating abs.\"},{\"id\":\"3525\",\"n\":\"landmine kneeling one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Kneel facing the end of a landmine barbell.\",\"Hold the end at shoulder height with one hand.\",\"Keep your core tight and torso upright.\",\"Press the end up and forward until your arm is straight.\",\"Lower with control.\",\"Complete your reps, then switch arms.\"],\"img\":\"3525.webp\",\"gif\":\"3525.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling single-arm press with a landmine. It trains the shoulders and builds core stability.\",\"fv\":\"10768\"},{\"id\":\"5636\",\"n\":\"landmine kneeling one arm shoulder press v. 2\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Kneel holding the end of a landmine bar at your shoulder.\",\"Brace your core and keep your torso upright.\",\"Press the bar up and forward until your arm is straight.\",\"Lower slowly.\",\"Switch sides after your set.\"],\"img\":\"5636.webp\",\"gif\":\"5636.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling one-arm landmine press for shoulder strength with an angled path.\"},{\"id\":\"3921\",\"n\":\"landmine kneeling squeeze press\",\"bp\":\"chest\",\"eq\":\"landmine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Kneel facing the landmine and hold the bar end close to your chest with both hands pressed together.\",\"Brace your core.\",\"Press the bar forward and up.\",\"Squeeze your hands together as you press.\",\"Lower it slowly.\",\"Keep your torso upright.\"],\"img\":\"3921.webp\",\"gif\":\"3921.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling landmine press with the hands squeezed together, working the chest and core.\"},{\"id\":\"5282\",\"n\":\"landmine kneeling thruster press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"triceps\",\"glutes\",\"core\"],\"st\":[\"Kneel facing the landmine and hold the end of the bar at your chest.\",\"Sit your hips back toward your heels.\",\"Drive through your hips and press the bar up.\",\"Straighten your arms fully at the top.\",\"Lower back to your chest with control.\"],\"img\":\"5282.webp\",\"gif\":\"5282.mp4\",\"cat\":\"strength\",\"desc\":\"From a kneeling position, you drive the landmine bar up into a press. It builds shoulder power.\"},{\"id\":\"4039\",\"n\":\"landmine one arm bent over bench row\",\"bp\":\"back\",\"eq\":\"landmine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Set the landmine bar next to a bench and place one hand and knee on the bench.\",\"Grip the bar end with your free hand and keep your back flat.\",\"Pull your elbow up toward your hip.\",\"Pause and squeeze your shoulder blade.\",\"Lower slowly, finish the reps, then switch sides.\"],\"img\":\"4039.webp\",\"gif\":\"4039.mp4\",\"cat\":\"strength\",\"desc\":\"A supported one arm landmine row with your free hand and knee on a bench. It keeps the lower back relaxed while you pull.\"},{\"id\":\"4038\",\"n\":\"landmine one arm bent over row\",\"bp\":\"back\",\"eq\":\"landmine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\",\"lower back\"],\"st\":[\"Load the landmine bar and stand over it with a hip hinge, knees soft.\",\"Grip the bar end with one hand and keep your back flat.\",\"Pull the bar toward your hip, squeezing your shoulder blade back.\",\"Lower slowly until the arm is straight.\",\"Finish the reps, then switch arms.\"],\"img\":\"4038.webp\",\"gif\":\"4038.mp4\",\"cat\":\"strength\",\"desc\":\"One arm row with the end of a landmine bar. It builds the lats and mid back with a smooth arc.\"},{\"id\":\"5034\",\"n\":\"landmine one arm bent over row v. 2\",\"bp\":\"back\",\"eq\":\"landmine\",\"tg\":\"lats\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\",\"biceps\",\"lower back\",\"forearms\"],\"st\":[\"Stand over the end of a landmine bar and hinge your hips back with a flat back.\",\"Grab the bar end or attachment with one hand.\",\"Pull the bar up toward your hip, leading with your elbow.\",\"Squeeze your back at the top.\",\"Lower slowly, then switch sides.\"],\"img\":\"5034.webp\",\"gif\":\"5034.mp4\",\"cat\":\"strength\",\"desc\":\"One-arm row with the end of a landmine barbell. It builds the lats and upper back.\"},{\"id\":\"5307\",\"n\":\"landmine one leg stiff leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"grip muscles\"],\"st\":[\"Hold the end of the landmine bar in front of you with both hands.\",\"Stand on one leg with a slight knee bend.\",\"Hinge at the hips and lower the bar while your free leg reaches back.\",\"Keep your back flat and hips square.\",\"Squeeze your glutes to return to standing.\",\"Finish your reps, then switch legs.\"],\"img\":\"5307.webp\",\"gif\":\"5307.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge holding a landmine bar. It trains hamstrings and glutes and challenges your balance.\"},{\"id\":\"7627\",\"n\":\"landmine overhead rear lunge\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Hold the end of the landmine bar at your shoulder.\",\"Step one foot back into a lunge.\",\"As you rise, press the bar overhead.\",\"Lower the bar to your shoulder while you lunge back again.\",\"Complete your reps and switch legs.\"],\"img\":\"7627.webp\",\"gif\":\"7627.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge while pressing a landmine bar overhead. It trains the legs, glutes and shoulders together.\"},{\"id\":\"5074\",\"n\":\"landmine press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"core\"],\"st\":[\"Anchor one end of a barbell and hold the other end at your shoulder with both hands.\",\"Stand with feet staggered and core braced.\",\"Press the bar up and forward until your arms are straight.\",\"Lower it back to your shoulder under control.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"5074.webp\",\"gif\":\"5074.mp4\",\"cat\":\"strength\",\"desc\":\"Press the end of an angled barbell up and forward. The arc is friendly to the shoulder and trains pressing and trunk stability.\"},{\"id\":\"3919\",\"n\":\"landmine rear lunge\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the end of a landmine bar at your chest.\",\"Stand tall with feet hip-width apart.\",\"Step one foot back and lower into a lunge.\",\"Keep your front knee over your ankle.\",\"Push through the front foot to stand.\",\"Alternate legs.\"],\"img\":\"3919.webp\",\"gif\":\"3919.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge holding a landmine bar at the chest, working the quads and glutes.\"},{\"id\":\"4040\",\"n\":\"landmine rear lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"shoulders\"],\"st\":[\"Hold the bar end against your chest with both hands.\",\"Stand tall with feet hip-width apart.\",\"Step one foot back and lower until both knees are bent about 90 degrees.\",\"Keep your front heel down and your torso upright.\",\"Push through the front foot to return, then switch legs.\"],\"img\":\"4040.webp\",\"gif\":\"4040.mp4\",\"cat\":\"strength\",\"desc\":\"Reverse lunge holding the end of a landmine bar at your chest. The bar adds load and encourages an upright torso.\"},{\"id\":\"4202\",\"n\":\"landmine resistance band one arm shoulder press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Hold the landmine end at your shoulder.\",\"Brace your core.\",\"Press up and forward.\",\"Lock out.\",\"Lower slowly.\",\"Switch arms.\"],\"img\":\"4202.webp\",\"gif\":\"4202.mp4\",\"cat\":\"strength\",\"desc\":\"One arm landmine press with a band.\"},{\"id\":\"4113\",\"n\":\"landmine romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"forearms\"],\"st\":[\"Stand holding the end of the bar close to your thighs.\",\"Soften your knees and push your hips back.\",\"Lower the bar along your legs with a flat back.\",\"Feel a stretch in your hamstrings.\",\"Drive your hips forward to stand tall.\"],\"img\":\"4113.webp\",\"gif\":\"4113.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge using a landmine barbell, training hamstrings and glutes.\"},{\"id\":\"4247\",\"n\":\"landmine romanian deadlift v. 2\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"forearms\"],\"st\":[\"Hold the end of the landmine bar with both hands in front of your thighs.\",\"Stand with soft knees and a flat back.\",\"Push your hips back and slide the bar down your legs.\",\"Lower until you feel a hamstring stretch.\",\"Drive your hips forward to stand.\",\"Squeeze your glutes at the top.\"],\"img\":\"4247.webp\",\"gif\":\"4247.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift using the landmine bar for an angled load. It builds the hamstrings and glutes with a good hip hinge.\"},{\"id\":\"5094\",\"n\":\"landmine single arm press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Anchor a barbell and hold the free end at your shoulder with one hand.\",\"Stand with feet staggered and core tight.\",\"Press the bar up and forward until your arm is straight.\",\"Lower it back to your shoulder.\",\"Complete your reps, then switch arms.\"],\"img\":\"5094.webp\",\"gif\":\"5094.mp4\",\"cat\":\"strength\",\"desc\":\"Press the end of a landmine barbell with one arm. The angled path is shoulder friendly and challenges your trunk.\",\"fv\":\"10766\"},{\"id\":\"10190\",\"n\":\"landmine single arm push press\",\"bp\":\"shoulders\",\"eq\":\"landmine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"quadriceps\",\"glutes\"],\"st\":[\"Stand facing the landmine end and hold it at your shoulder with one hand.\",\"Dip a few inches by bending your knees.\",\"Drive up with your legs and press the bar up and forward until your arm is straight.\",\"Lower the end back to your shoulder with control.\",\"Keep your ribs down and brace your core. Finish the reps, then switch arms.\"],\"img\":\"10190.webp\",\"gif\":\"10190.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm push press with a landmine, using leg drive to move the bar up and the shoulder to control it.\"},{\"id\":\"6546\",\"n\":\"landmine single leg hip thrust\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Rest your upper back on a bench with a padded landmine bar across your hips.\",\"Plant one foot on the floor and extend the other leg or hold it up.\",\"Drive through the planted heel and lift your hips.\",\"Squeeze the glute at the top with your torso level.\",\"Lower with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"6546.webp\",\"gif\":\"6546.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip thrust with a landmine bar across the hips. It hits each glute separately and challenges balance.\"},{\"id\":\"3918\",\"n\":\"landmine single leg landmine rdl\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Hold the end of a landmine bar with both hands.\",\"Stand on one leg with a soft knee.\",\"Hinge at the hips and extend the other leg behind you.\",\"Lower the bar toward the floor with a flat back.\",\"Squeeze your glute to stand.\",\"Switch legs after your reps.\"],\"img\":\"3918.webp\",\"gif\":\"3918.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg Romanian deadlift holding a landmine bar, challenging balance and the hamstrings.\"},{\"id\":\"6553\",\"n\":\"landmine single leg romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Hold the end of a landmine bar at your chest and stand on one leg.\",\"Keep a soft bend in the standing knee.\",\"Hinge at the hip and send the free leg back for balance.\",\"Lower the bar toward the floor with a flat back.\",\"Squeeze your glute and return to standing.\",\"Complete the reps, then switch legs.\"],\"img\":\"6553.webp\",\"gif\":\"6553.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip hinge holding a landmine bar. It builds hamstring and glute strength along with balance.\"},{\"id\":\"7626\",\"n\":\"landmine squat\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Hold the end of the landmine bar against your chest with both hands.\",\"Stand with your feet shoulder-width apart.\",\"Sit your hips down and back, keeping your chest tall.\",\"Squat until your thighs are about parallel to the floor.\",\"Drive through your whole foot to stand back up.\"],\"img\":\"7626.webp\",\"gif\":\"7626.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding the end of a landmine bar at your chest. The angled bar helps you stay upright and load the legs.\"},{\"id\":\"2976\",\"n\":\"landmine squat and press\",\"bp\":\"full body\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\",\"hamstrings\"],\"st\":[\"Hold the end of the landmine bar at your chest with both hands.\",\"Stand with your feet shoulder-width apart.\",\"Squat down with your chest up.\",\"Drive up and press the bar away until your arms are straight.\",\"Lower the bar to your chest and repeat.\"],\"img\":\"2976.webp\",\"gif\":\"2976.mp4\",\"cat\":\"strength\",\"desc\":\"A squat that flows into a press with a landmine bar. It works legs and shoulders in one smooth motion.\",\"fv\":\"2977\"},{\"id\":\"10675\",\"n\":\"landmine squat jump\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\",\"shoulders\"],\"st\":[\"Hold the end of a landmine bar at your chest.\",\"Stand with feet shoulder-width apart.\",\"Squat down with a tall chest.\",\"Jump up explosively through your feet.\",\"Land softly with bent knees.\",\"Reset and repeat.\"],\"img\":\"10675.webp\",\"gif\":\"10675.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat holding a landmine bar at your chest, followed by a jump. It builds explosive leg power.\"},{\"id\":\"3529\",\"n\":\"landmine stand up high knee\",\"bp\":\"full body\",\"eq\":\"landmine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"hip flexors\"],\"st\":[\"Hold the end of a landmine barbell at your chest.\",\"Stand from a squat, driving through your legs.\",\"Raise one knee high as you stand.\",\"Lower the foot and squat again.\",\"Keep the barbell close to your chest.\",\"Alternate legs each rep.\"],\"img\":\"3529.webp\",\"gif\":\"3529.mp4\",\"cat\":\"strength\",\"desc\":\"A landmine move combining a stand-up with a high knee drive. It trains the legs and core.\"},{\"id\":\"4090\",\"n\":\"landmine sumo squat\",\"bp\":\"upper legs\",\"eq\":\"landmine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"core\",\"hamstrings\"],\"st\":[\"Stand facing the landmine anchor with a wide stance and hold the bar end against your chest.\",\"Brace your core and keep your elbows tucked in.\",\"Sit down between your legs, knees tracking over your toes.\",\"Lower until your thighs are about parallel.\",\"Press through your heels to stand tall.\"],\"img\":\"4090.webp\",\"gif\":\"4090.mp4\",\"cat\":\"strength\",\"desc\":\"A wide stance squat holding the end of a landmine barbell at your chest, which trains glutes and legs with an upright torso.\"},{\"id\":\"2121\",\"n\":\"lateral bend lying down\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Lie on your back with legs together and arms stretched overhead.\",\"Slide both feet and both hands to the same side so the body forms a gentle arc.\",\"Keep your hips and shoulders on the floor.\",\"Breathe slowly and relax into the curve.\",\"Hold for 20-30 seconds.\",\"Return to centre and bend to the other side.\"],\"img\":\"2121.webp\",\"gif\":\"2121.mp4\",\"cat\":\"stretching\",\"desc\":\"Curves the body sideways while lying down, which stretches the flank without any need to balance.\"},{\"id\":\"2124\",\"n\":\"lateral bend on floor by kneeling\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Kneel on a mat and extend one arm sideways along the floor.\",\"Walk your hands to one side and sink your hips the other way until the side of the waist stretches.\",\"Keep your hips over your knees.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2124.webp\",\"gif\":\"2124.mp4\",\"cat\":\"stretching\",\"desc\":\"A kneeling side bend where you reach along the floor to stretch the side of the waist.\"},{\"id\":\"3095\",\"n\":\"lateral bound\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"calves\",\"core\"],\"st\":[\"Stand on one leg with a slight bend in the knee.\",\"Push off hard to leap sideways.\",\"Land on the opposite foot and bend to absorb the impact.\",\"Hold the landing for a second to stay balanced.\",\"Bound back the other way.\",\"Keep your chest up and your knee over your toes.\"],\"img\":\"3095.webp\",\"gif\":\"3095.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A sideways leap from one leg to the other. It builds lateral power and balance.\",\"fv\":\"0563\"},{\"id\":\"0564\",\"n\":\"lateral box jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand beside a sturdy box or step.\",\"Bend your knees and swing your arms back.\",\"Jump up and sideways, landing with both feet on the box.\",\"Land softly with bent knees and stand tall.\",\"Step down carefully.\",\"Repeat, then switch the side you start from.\"],\"img\":\"0564.webp\",\"gif\":\"0564.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A sideways jump onto a box that builds explosive power in the legs. It also trains landing control.\"},{\"id\":\"6958\",\"n\":\"lateral hurdle jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand beside a low hurdle with feet together.\",\"Swing your arms and jump sideways over it.\",\"Land softly on both feet with knees bent.\",\"Jump straight back over the other way.\",\"Keep your ground contact quick and controlled.\"],\"img\":\"6958.webp\",\"gif\":\"6958.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side-to-side jump over a low hurdle. It builds explosive power and quick landings.\"},{\"id\":\"11782\",\"n\":\"lateral jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\",\"adductors\"],\"st\":[\"Stand on both feet with your knees slightly bent and your arms ready.\",\"Push off and jump sideways, covering a comfortable distance.\",\"Land softly on both feet with your knees tracking over your toes.\",\"Immediately jump back to the starting side.\",\"Keep your chest up and repeat for the planned reps or time.\"],\"img\":\"11782.webp\",\"gif\":\"11782.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side-to-side jump that develops lateral power, balance and leg stability.\"},{\"id\":\"5973\",\"n\":\"lateral ladder drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"calves\",\"quadriceps\",\"core\"],\"st\":[\"Stand sideways at the start of an agility ladder.\",\"Step both feet into the first square, one at a time.\",\"Move sideways to the next square with quick steps.\",\"Keep your hips low and your feet light.\",\"Finish the ladder, then repeat facing the other way.\"],\"img\":\"5973.webp\",\"gif\":\"5973.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A sideways run through an agility ladder to build lateral speed and foot coordination.\"},{\"id\":\"4967\",\"n\":\"lateral raise arms (form check)\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rear deltoids\"],\"st\":[\"Stand tall with dumbbells at your sides.\",\"Raise your arms out to the sides.\",\"Stop at shoulder height.\",\"Lower slowly.\",\"Keep a slight bend in your elbows.\",\"Compare with the incorrect position to correct your form.\"],\"img\":\"4967.webp\",\"gif\":\"4967.mp4\",\"cat\":\"strength\",\"desc\":\"A form check drawing for the lateral raise, showing correct and incorrect technique. It reminds you how to train the side delts safely.\"},{\"id\":\"3741\",\"n\":\"lateral raise with towel\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Hold a towel with both hands and stand on its middle with one foot, or pull its ends apart.\",\"Keep your elbows slightly bent.\",\"Raise your arms out to the sides to shoulder height.\",\"Lower slowly.\",\"Keep tension on the towel throughout.\"],\"img\":\"3741.webp\",\"gif\":\"3741.mp4\",\"cat\":\"strength\",\"desc\":\"A no-equipment side raise using a towel for resistance, so you can train the delts at home.\"},{\"id\":\"1470\",\"n\":\"lateral side plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Lie on your side with your forearm under your shoulder and your legs straight.\",\"Stack your feet or stagger them for balance.\",\"Lift your hips to form a straight line from head to feet.\",\"Keep your core tight and your hips from sagging.\",\"Hold for the planned time, then switch sides.\"],\"img\":\"1470.webp\",\"gif\":\"1470.mp4\",\"cat\":\"isometric\",\"desc\":\"A classic side plank that trains the obliques and hip stabilisers.\",\"hd\":1},{\"id\":\"1469\",\"n\":\"lateral side plank (bent leg)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Lie on your side with your forearm under your shoulder and your knees bent.\",\"Stack your hips and shoulders in a line.\",\"Lift your hips off the floor until your body forms a straight line from knee to head.\",\"Keep your core tight and your hips from sagging.\",\"Hold for the planned time, then switch sides.\"],\"img\":\"1469.webp\",\"gif\":\"1469.mp4\",\"cat\":\"isometric\",\"desc\":\"An easier side plank with the bottom knee bent, building oblique and hip stability.\",\"hd\":1},{\"id\":\"0565\",\"n\":\"lateral speed step\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"ankles\"],\"st\":[\"Stand in a slight athletic stance with knees bent.\",\"Step quickly to one side, pushing off the opposite foot.\",\"Bring the trailing foot in and step back the other way.\",\"Stay on the balls of your feet.\",\"Keep your chest up and arms moving naturally.\",\"Work at a fast but controlled pace for the set.\"],\"img\":\"0565.webp\",\"gif\":\"0565.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Quick side-to-side steps that build foot speed and agility. It warms up the legs and trains coordination.\"},{\"id\":\"5154\",\"n\":\"lateral step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Stand sideways next to a box.\",\"Place your near foot on the box.\",\"Press through that foot to step up.\",\"Lower back down slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"5154.webp\",\"gif\":\"5154.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Step sideways onto a box or step. It works the quads and glutes and builds single-leg strength.\",\"fv\":\"0566\"},{\"id\":\"5155\",\"n\":\"lateral step up with knee drive\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand sideways next to a box with one foot on top.\",\"Press through that foot to step up.\",\"Drive your other knee up toward your chest.\",\"Lower back down with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"5155.webp\",\"gif\":\"5155.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Step sideways onto a box and drive the other knee up. It adds balance and hip flexion to the lateral step up.\"},{\"id\":\"2125\",\"n\":\"lateral stretch on floor lying down\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Lie on your back with your arms extended overhead.\",\"Shift your feet and your upper body to one side to form a gentle banana curve until the opposite side stretches.\",\"Keep both shoulders and hips on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2125.webp\",\"gif\":\"2125.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying side stretch that gently lengthens one side of the body.\"},{\"id\":\"0567\",\"n\":\"lateral twist box jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"obliques\"],\"st\":[\"Stand facing a sturdy box with feet shoulder-width apart.\",\"Dip into a quarter squat and swing your arms back.\",\"Jump up and rotate your hips to land sideways on the box.\",\"Land softly with bent knees.\",\"Step down and reset.\",\"Alternate the twist direction each rep.\"],\"img\":\"0567.webp\",\"gif\":\"0567.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A box jump with a twist in the air that adds rotation. It builds explosive leg power and trunk control.\"},{\"id\":\"4858\",\"n\":\"lateral walk push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank.\",\"Do one push-up.\",\"Step your hands and feet to the side.\",\"Do another push-up.\",\"Alternate direction after a set.\"],\"img\":\"4858.webp\",\"gif\":\"4858.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up combined with side steps. It trains the chest and shoulders with extra coordination.\"},{\"id\":\"5997\",\"n\":\"lay down push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie face down with your hands under your shoulders.\",\"Brace your core and glutes.\",\"Push your body up into a straight plank.\",\"Lower yourself all the way down until your chest rests on the floor.\",\"Relax briefly, then push up again.\"],\"img\":\"5997.webp\",\"gif\":\"5997.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up that starts from lying flat on the floor each rep, so every rep begins from a dead stop and builds pressing strength.\",\"fv\":\"6029\"},{\"id\":\"5695\",\"n\":\"lean forward stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand or sit in a stable position with one leg in front of the other.\",\"Keep your back long and chest open.\",\"Hinge forward from your hips until you feel a stretch in the glutes and hamstrings.\",\"Hold for 20-30 seconds.\",\"Return upright and switch sides.\"],\"img\":\"5695.webp\",\"gif\":\"5695.mp4\",\"cat\":\"stretching\",\"desc\":\"A forward-leaning stretch that opens the hips and the back of the legs.\"},{\"id\":\"1880\",\"n\":\"leaning abductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Stand next to a wall and lean on it with one hand.\",\"Cross your outer leg behind the inner one.\",\"Lean your hips toward the wall.\",\"Keep both feet flat.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1880.webp\",\"gif\":\"1880.mp4\",\"cat\":\"stretching\",\"desc\":\"Leaning stretch for the outer hip and thigh.\"},{\"id\":\"2104\",\"n\":\"leaning heel back achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall and place your hands on it at chest height.\",\"Step one foot back and keep that heel on the floor.\",\"Bend both knees slightly and lean forward until you feel a pull low in the back calf.\",\"Keep the back heel flat and the toes pointing forward.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"2104.webp\",\"gif\":\"2104.mp4\",\"cat\":\"stretching\",\"desc\":\"Targets the lower calf and Achilles tendon area by leaning into a wall with the back heel pressed down and the knee bent.\"},{\"id\":\"4920\",\"n\":\"leg assisted ring pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Hold the rings with a firm grip and stand with a bend in the knees.\",\"Place your feet on the floor for light help.\",\"Pull your elbows down and your chest between the rings.\",\"Use your legs only as much as you need.\",\"Lower with control.\",\"Keep your core tight.\"],\"img\":\"4920.webp\",\"gif\":\"4920.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A ring pull up where your feet on the floor help you up. It is a good step toward full pull ups.\"},{\"id\":\"0568\",\"n\":\"leg bench side bridge\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side with your top leg resting on a bench.\",\"Place your forearm on the floor under your shoulder.\",\"Lift your hips so your body forms a straight line.\",\"Keep your hips stacked and your core tight.\",\"Hold for 20-30 seconds.\",\"Lower and repeat on the other side.\"],\"img\":\"0568.webp\",\"gif\":\"0568.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with the top leg resting on a bench. It hits the obliques and builds side-body stability.\",\"hd\":1},{\"id\":\"0569\",\"n\":\"leg curl (on stability ball)\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"calves\"],\"st\":[\"Lie on your back with your heels on a stability ball and legs straight.\",\"Press your hips up so your body forms a line.\",\"Pull the ball toward your glutes by bending your knees.\",\"Keep your hips lifted throughout.\",\"Pause at the top.\",\"Roll the ball back out slowly.\"],\"img\":\"0569.webp\",\"gif\":\"0569.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back with heels on a ball, you curl it toward your hips. It works the hamstrings and core together.\"},{\"id\":\"3606\",\"n\":\"leg extension crunch (with stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Sit on a stability ball and walk your feet out until your back is supported.\",\"Place your hands lightly behind your head.\",\"Crunch up as you extend one leg.\",\"Lower slowly and bend the knee.\",\"Alternate legs for the set.\"],\"img\":\"3606.webp\",\"gif\":\"3606.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch on a stability ball combined with extending the legs for a deep ab workout.\"},{\"id\":\"4386\",\"n\":\"leg extension plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"shoulders\",\"hip flexors\"],\"st\":[\"Get into a forearm or high plank with a flat back.\",\"Brace your abs and squeeze your glutes.\",\"Lift one leg straight behind you without rotating your hips.\",\"Lower it with control.\",\"Repeat on the other leg and alternate.\"],\"img\":\"4386.webp\",\"gif\":\"4386.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank where you lift and extend one leg at a time, testing core stability and strengthening the glutes.\"},{\"id\":\"4616\",\"n\":\"leg front kick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Stand tall with your arms out for balance or hands on your hips.\",\"Shift your weight onto one foot.\",\"Swing the other leg forward and up in a controlled kick, keeping it fairly straight.\",\"Lower it with control without leaning back.\",\"Complete your reps, then switch legs.\"],\"img\":\"4616.webp\",\"gif\":\"4616.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing leg swing forward that warms up the hip flexors and hamstrings and challenges your balance.\",\"fv\":\"5082\"},{\"id\":\"6789\",\"n\":\"leg length test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie flat on your back with legs straight and feet together.\",\"Relax your hips and arms.\",\"Compare the position of your heels or ankles.\",\"Bend your knees and lift your hips, then lower and straighten again.\",\"Check again for any difference.\",\"Stay relaxed throughout.\"],\"img\":\"6789.webp\",\"gif\":\"6789.mp4\",\"cat\":\"mobility\",\"desc\":\"A lying check comparing the length of both legs. It is done gently and with a relaxed body.\"},{\"id\":\"3982\",\"n\":\"leg lift to chest front plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"glutes\"],\"st\":[\"Start in a high plank.\",\"Draw one knee toward your chest.\",\"Return it to the floor.\",\"Alternate legs.\",\"Keep your hips level.\"],\"img\":\"3982.webp\",\"gif\":\"3982.mp4\",\"cat\":\"plyometrics\",\"desc\":\"From a front plank, drive one knee to the chest and alternate. It trains the core and hip flexors.\"},{\"id\":\"4690\",\"n\":\"leg over knee glute bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and one ankle crossed over the other knee.\",\"Press through the grounded foot.\",\"Lift your hips until your body forms a line.\",\"Squeeze your glutes at the top.\",\"Lower slowly and switch sides.\"],\"img\":\"4690.webp\",\"gif\":\"4690.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg style glute bridge with one ankle resting on the opposite knee.\",\"fv\":\"4670\"},{\"id\":\"2849\",\"n\":\"leg pull\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Start in a high plank.\",\"Brace your core.\",\"Lift one leg a few inches.\",\"Lower and switch legs.\",\"Keep your hips level.\"],\"img\":\"2849.webp\",\"gif\":\"2849.mp4\",\"cat\":\"pilates\",\"desc\":\"A plank-based Pilates move where you lift one leg at a time, training core stability.\"},{\"id\":\"2874\",\"n\":\"leg pull front supported\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"hamstrings\"],\"st\":[\"Start in a high plank with hands under your shoulders.\",\"Keep your body in one straight line from head to heels.\",\"Lift one leg a few inches without shifting your hips.\",\"Lower it and repeat on the other leg.\",\"Keep your abs tight and your neck long.\"],\"img\":\"2874.webp\",\"gif\":\"2874.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates plank variation with a leg lift that builds core and shoulder stability.\"},{\"id\":\"2848\",\"n\":\"leg pull side\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Start in a side plank on one hand.\",\"Keep your body in a straight line.\",\"Lift your top leg.\",\"Hold briefly.\",\"Lower and switch sides.\"],\"img\":\"2848.webp\",\"gif\":\"2848.mp4\",\"cat\":\"pilates\",\"desc\":\"A side-plank style Pilates move where one leg lifts, challenging the obliques and shoulders.\"},{\"id\":\"2850\",\"n\":\"leg raise (bent knee)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with arms by your sides.\",\"Bend your knees.\",\"Raise your legs until your thighs are vertical.\",\"Lower slowly without arching.\",\"Keep your lower back on the floor.\"],\"img\":\"2850.webp\",\"gif\":\"2850.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg raise with bent knees that makes it easier to focus on the lower abs.\"},{\"id\":\"4058\",\"n\":\"leg raise dragon flag\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"lats\",\"core\"],\"st\":[\"Lie on a bench and grip it behind your head.\",\"Lift your hips and legs so your body is straight from shoulders to toes.\",\"Keep your body rigid and lower slowly without sitting.\",\"Raise your legs back up under control.\",\"Stop before your lower back arches.\"],\"img\":\"4058.webp\",\"gif\":\"4058.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Advanced core move where the body stays straight while you raise and lower the legs from a bench. It strongly trains the abs.\",\"nd\":[\"bench\"]},{\"id\":\"1852\",\"n\":\"leg raise hip lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"glutes\"],\"st\":[\"Lie on your back with your legs straight and your hands by your sides.\",\"Raise your legs to vertical.\",\"Curl your hips up off the floor, pushing your feet toward the ceiling.\",\"Lower your hips, then your legs, with control.\",\"Keep your movement smooth and avoid swinging.\"],\"img\":\"1852.webp\",\"gif\":\"1852.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying leg raise finished with a hip lift that targets the lower abs.\"},{\"id\":\"1855\",\"n\":\"leg raise hip lift with head up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your legs straight and your hands by your sides.\",\"Lift your head and shoulders slightly off the floor.\",\"Raise your legs to vertical.\",\"Push your hips a little off the floor, lifting your feet toward the ceiling.\",\"Lower your hips and legs slowly with control.\"],\"img\":\"1855.webp\",\"gif\":\"1855.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying leg raise finished with a hip lift while the head stays raised, working the whole abdominal wall.\"},{\"id\":\"5032\",\"n\":\"leg raise oblique crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with your hands behind your head.\",\"Lift your legs together toward the ceiling.\",\"Crunch your shoulders up and toward one side as the legs tilt the other way.\",\"Lower and repeat to the other side.\",\"Keep movements slow and controlled.\"],\"img\":\"5032.webp\",\"gif\":\"5032.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise your legs and crunch to the side. It targets the lower abs and the obliques together.\"},{\"id\":\"1854\",\"n\":\"leg raise slightly bent knee\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your hands under your hips.\",\"Bend your knees slightly and lift your feet off the floor.\",\"Raise your legs until they are above your hips.\",\"Lower slowly without letting your back arch.\",\"Keep your core tight throughout.\"],\"img\":\"1854.webp\",\"gif\":\"1854.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A leg raise with slightly bent knees, a gentler version for the lower abs.\"},{\"id\":\"0955\",\"n\":\"leg to side\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"groin\",\"core\"],\"st\":[\"Lie on your back with both legs straight.\",\"Lift one leg and let it open out to the side, keeping the other leg down.\",\"Keep your hips squared and your lower back relaxed.\",\"Hold the stretch gently, breathing steadily.\",\"Return to the middle and repeat with the other leg.\"],\"img\":\"0955.webp\",\"gif\":\"0955.mp4\",\"cat\":\"stretching\",\"desc\":\"Bring one leg out to the side to stretch the inner thigh. It improves hip mobility and flexibility.\"},{\"id\":\"4381\",\"n\":\"legs up the wall yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"calves\",\"glutes\"],\"st\":[\"Sit sideways next to a wall and lie back as you swing your legs up the wall.\",\"Move your hips close to the wall, with your arms relaxed at your sides.\",\"Keep your knees soft if the hamstrings feel tight.\",\"Breathe slowly and relax your shoulders and jaw.\",\"Hold for 1-5 minutes, then bend your knees and roll to one side to come up.\"],\"img\":\"4381.webp\",\"gif\":\"4381.mp4\",\"cat\":\"yoga\",\"desc\":\"A restful pose where your legs rest up a wall, gently stretching the backs of the legs and easing tension in the lower back.\"},{\"id\":\"5583\",\"n\":\"lever ab coaster crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit on the machine, set the seat and grab the handles.\",\"Place your legs on the pads and keep your back against the support.\",\"Exhale and crunch your torso and knees toward each other.\",\"Pause when your abs are fully squeezed.\",\"Return slowly without letting the weight stack touch down.\"],\"img\":\"5583.webp\",\"gif\":\"5583.mp4\",\"cat\":\"strength\",\"desc\":\"A machine crunch on a curved track that lets you curl your trunk and knees together. Builds the abs under load.\"},{\"id\":\"6561\",\"n\":\"lever ab swing\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit in the machine and secure yourself with the pads.\",\"Hold the handles and brace your core.\",\"Swing your legs to one side using your abs.\",\"Return to the centre with control.\",\"Repeat on the other side.\"],\"img\":\"6561.webp\",\"gif\":\"6561.mp4\",\"cat\":\"strength\",\"desc\":\"A rotating ab machine movement where you swing your legs and trunk to work the abs.\"},{\"id\":\"5349\",\"n\":\"lever abduction leg raise\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hip flexors\"],\"st\":[\"Set up in the machine with the pad on the outside of your leg.\",\"Hold the supports for stability.\",\"Raise your leg out to the side in a controlled motion.\",\"Pause at the top.\",\"Lower slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"5349.webp\",\"gif\":\"5349.mp4\",\"cat\":\"strength\",\"desc\":\"Raise the leg out to the side against lever resistance. Targets the outer hips.\"},{\"id\":\"2746\",\"n\":\"lever abduction squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"adductors\"],\"st\":[\"Set the machine and step in with the pads on your shoulders.\",\"Squat down with control, keeping your chest up.\",\"Drive up through your feet.\",\"Push your knees slightly outward as you rise.\",\"Keep your core braced.\"],\"img\":\"2746.webp\",\"gif\":\"2746.mp4\",\"cat\":\"strength\",\"desc\":\"A machine squat that adds an outward leg push to work the outer hips and glutes.\"},{\"id\":\"2747\",\"n\":\"lever adduction thrust\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Sit in the machine with the pads between or around your legs as set.\",\"Brace your core.\",\"Thrust your hips up while squeezing your legs inward.\",\"Hold the squeeze briefly at the top.\",\"Lower with control.\"],\"img\":\"2747.webp\",\"gif\":\"2747.mp4\",\"cat\":\"strength\",\"desc\":\"A machine hip thrust that squeezes the legs inward, training the inner thighs and glutes.\"},{\"id\":\"1032\",\"n\":\"lever alternate biceps curl\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit with your upper arms resting on the pad and grab the handles.\",\"Curl one handle up toward your shoulder.\",\"Squeeze the biceps at the top.\",\"Lower it slowly while curling the other arm.\",\"Keep your shoulders relaxed and avoid swinging.\"],\"img\":\"1032.webp\",\"gif\":\"1032.mp4\",\"cat\":\"strength\",\"desc\":\"A machine curl done one arm at a time, so each biceps works independently.\",\"fv\":\"11658\"},{\"id\":\"1874\",\"n\":\"lever alternate leg extension (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit with your back against the pad and your shins behind the rollers.\",\"Hold the handles.\",\"Extend one leg until it is straight.\",\"Lower it slowly.\",\"Repeat with the other leg and keep alternating.\"],\"img\":\"1874.webp\",\"gif\":\"1874.mp4\",\"cat\":\"strength\",\"desc\":\"One leg at a time on a plate-loaded extension machine, evening out strength between the legs.\"},{\"id\":\"3096\",\"n\":\"lever alternating narrow grip seated row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Sit with your chest against the pad and grab the narrow handles.\",\"Pull one handle back, driving your elbow behind you.\",\"Squeeze your shoulder blade at the end.\",\"Return slowly and pull with the other arm.\",\"Alternate sides and keep your torso still.\"],\"img\":\"3096.webp\",\"gif\":\"3096.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded seated row with a narrow grip, one arm at a time for balanced back strength.\"},{\"id\":\"8375\",\"n\":\"lever angled leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the machine with your back flat on the pad and feet on the platform shoulder-width apart.\",\"Release the safety handles.\",\"Lower the platform until your knees are bent about 90 degrees.\",\"Press through your whole foot until your legs are nearly straight.\",\"Do not lock your knees out.\"],\"img\":\"8375.webp\",\"gif\":\"8375.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded angled press that works the thighs and glutes with a stable seated position.\"},{\"id\":\"9387\",\"n\":\"lever angled single leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Sit on the machine and place one foot on the platform.\",\"Release the safety handles.\",\"Lower the platform until your knee is bent about 90 degrees.\",\"Press through your heel to push it back.\",\"Do not lock your knee at the top.\",\"Finish the reps, then switch legs.\"],\"img\":\"9387.webp\",\"gif\":\"9387.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing with one leg on an angled leg press machine focuses the work on the quads and glutes.\"},{\"id\":\"2749\",\"n\":\"lever assisted leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the machine and place your feet on the platform about shoulder width apart.\",\"Release the safety handles.\",\"Lower the platform by bending your knees until they reach about 90 degrees.\",\"Push through your heels to extend the legs.\",\"Do not lock your knees fully.\"],\"img\":\"2749.webp\",\"gif\":\"2749.mp4\",\"cat\":\"strength\",\"desc\":\"A machine leg press with assistance, building the thighs and glutes with a controlled path.\"},{\"id\":\"2266\",\"n\":\"lever back extension v. 2\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Adjust the machine and sit with your back against the pad.\",\"Cross your arms or hold the handles as the machine allows.\",\"Push back by extending at the hips and lower back.\",\"Stop when your torso is in a neutral, tall position.\",\"Return slowly to the start.\",\"Repeat for the planned reps.\"],\"img\":\"2266.webp\",\"gif\":\"2266.mp4\",\"cat\":\"strength\",\"desc\":\"A machine back extension that strengthens the muscles along the lower back with support from the pad.\",\"fv\":\"5184\"},{\"id\":\"4213\",\"n\":\"lever banded chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Adjust the seat so the handles line up with your mid chest.\",\"Sit back with your shoulder blades pinned to the pad.\",\"Grip the handles and press forward until your arms are nearly straight.\",\"Feel the band tension build as you lock out.\",\"Lower slowly until you feel a stretch across your chest.\",\"Keep your wrists straight.\"],\"img\":\"4213.webp\",\"gif\":\"4213.mp4\",\"cat\":\"strength\",\"desc\":\"A machine chest press with bands adding extra resistance at the top. It builds the chest and triceps with a stable path.\"},{\"id\":\"10328\",\"n\":\"lever belt bulgarian split squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Set up in the belt squat machine and place your back foot on the bench behind you.\",\"Stand tall with the front foot far enough forward.\",\"Lower straight down until your front thigh is parallel.\",\"Press through the front heel to stand.\",\"Keep your torso upright. Finish the reps, then switch legs.\"],\"img\":\"10328.webp\",\"gif\":\"10328.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with your back foot raised, loaded through a belt machine to hit the quads and glutes.\"},{\"id\":\"9866\",\"n\":\"lever belt deadlift (straight bar)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand on the platform with the belt around your hips and grip the straight bar.\",\"Bend your knees and hinge with a flat back.\",\"Brace your core.\",\"Drive your feet down and stand tall.\",\"Lower with control.\"],\"img\":\"9866.webp\",\"gif\":\"9866.mp4\",\"cat\":\"strength\",\"desc\":\"A belt-machine deadlift using a straight bar, so the load hangs from your hips.\"},{\"id\":\"9865\",\"n\":\"lever belt deadlift (v bar)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand on the platform with the belt around your hips and grip the V bar.\",\"Bend your knees and hinge with a flat back.\",\"Brace your core.\",\"Drive your feet down and stand tall.\",\"Lower with control.\"],\"img\":\"9865.webp\",\"gif\":\"9865.mp4\",\"cat\":\"strength\",\"desc\":\"A belt-machine deadlift using a V handle, so the load hangs from your hips.\"},{\"id\":\"9494\",\"n\":\"lever belt romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"quadriceps\"],\"st\":[\"Wear the belt and stand tall with soft knees.\",\"Push your hips back and lower your torso with a flat back.\",\"Stop when you feel a stretch in the hamstrings.\",\"Squeeze your glutes and drive your hips forward to stand.\",\"Repeat with smooth control.\"],\"img\":\"9494.webp\",\"gif\":\"9494.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge using a belt machine so the weight hangs from your hips. It trains the hamstrings and glutes without loading the back.\"},{\"id\":\"9876\",\"n\":\"lever belt romanian deadlift (straight bar)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Step into the machine, set the belt securely and hold the straight bar with an overhand grip.\",\"Stand tall with your knees slightly bent and your chest up.\",\"Push your hips back and slide the bar down along your thighs.\",\"Lower until you feel a strong hamstring stretch while your back stays flat.\",\"Drive your hips forward to stand back up.\",\"Squeeze your glutes at the top without leaning back.\"],\"img\":\"9876.webp\",\"gif\":\"9876.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift on a belt-loaded lever machine using a straight bar. It builds the hamstrings and glutes while sparing the grip and spine from heavy free weight.\"},{\"id\":\"9877\",\"n\":\"lever belt romanian deadlift (v bar)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Step into the machine, secure the belt and take the V bar with both hands.\",\"Stand tall with soft knees and your shoulders back.\",\"Hinge at the hips, pushing them back as the bar slides down your thighs.\",\"Lower until your hamstrings are well stretched, keeping your back flat.\",\"Drive your hips forward and stand up straight.\",\"Squeeze your glutes at the top.\"],\"img\":\"9877.webp\",\"gif\":\"9877.mp4\",\"cat\":\"strength\",\"desc\":\"A belt-loaded lever machine Romanian deadlift using a V bar for a neutral grip. It targets the hamstrings and glutes with a comfortable hand position.\"},{\"id\":\"11529\",\"n\":\"lever belt single leg romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Fasten the belt and stand on one leg on the platform with a slight knee bend.\",\"Hinge at the hips and push them back as your torso lowers.\",\"Let the free leg extend behind you for balance.\",\"Lower until you feel a hamstring stretch, keeping your back flat.\",\"Drive your hips forward to stand tall, then switch legs after your reps.\"],\"img\":\"11529.webp\",\"gif\":\"11529.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge on a belt-loaded lever machine that trains hamstrings and glutes with extra balance support.\"},{\"id\":\"2950\",\"n\":\"lever belt squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Step into the belt and stand on the platforms with the belt snug on your hips.\",\"Stand tall and brace your abs.\",\"Squat down until your thighs are about parallel.\",\"Push through your heels to stand back up.\",\"Keep your chest up and knees tracking over your toes.\"],\"img\":\"2950.webp\",\"gif\":\"2950.mp4\",\"cat\":\"strength\",\"desc\":\"A squat on a machine where the weight hangs from a belt at your hips. It loads the legs without stressing your spine.\"},{\"id\":\"11055\",\"n\":\"lever belt sumo deadlift (v bar)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"lower back\"],\"st\":[\"Stand wide on the platform with toes angled out and grip the V bar.\",\"Sit your hips back, chest up, and keep your arms straight.\",\"Push through your heels to stand fully upright.\",\"Squeeze your glutes at the top.\",\"Lower under control, letting your knees track over your toes.\"],\"img\":\"11055.webp\",\"gif\":\"11055.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo deadlift on a belt squat style lever machine holding a V bar. It loads the legs and hips with less strain on the back.\"},{\"id\":\"9493\",\"n\":\"lever belt sumo squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Attach the belt around your hips and stand with a wide stance, toes out.\",\"Keep your chest tall and brace your core.\",\"Bend your knees and sit down between your legs.\",\"Lower until your thighs are about parallel.\",\"Drive through your feet to stand up.\"],\"img\":\"9493.webp\",\"gif\":\"9493.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance squat on a belt squat machine where the load hangs from your hips, sparing your spine. It works the glutes and inner thighs.\"},{\"id\":\"6514\",\"n\":\"lever bent over neutral grip row (with chest support)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lean your chest on the pad and take a neutral grip on the handles.\",\"Start with your arms extended.\",\"Pull the handles toward your ribs, elbows close to your body.\",\"Squeeze at the end.\",\"Return slowly and repeat.\"],\"img\":\"6514.webp\",\"gif\":\"6514.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row with palms facing each other, building your mid-back and lats.\"},{\"id\":\"6513\",\"n\":\"lever bent over row (with chest support)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lean your chest against the pad and grab the handles.\",\"Keep your shoulders relaxed.\",\"Pull the handles toward your body, driving your elbows back.\",\"Squeeze your shoulder blades together.\",\"Lower slowly and repeat.\"],\"img\":\"6513.webp\",\"gif\":\"6513.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported lever row that lets you pull heavy while your lower back stays out of the way.\"},{\"id\":\"10866\",\"n\":\"lever bent over single arm lats focused row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Set the machine and lean forward from the hips with a flat back.\",\"Grip the handle with one hand and let the arm reach forward.\",\"Pull the elbow back and down toward your hip.\",\"Squeeze your lat at the end of the pull.\",\"Return slowly, then switch sides after your reps.\"],\"img\":\"10866.webp\",\"gif\":\"10866.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm machine row done from a bent-over stance. It targets the lats with a strong squeeze.\"},{\"id\":\"6515\",\"n\":\"lever bent over single arm neutral grip row (with chest support)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rear deltoids\",\"biceps\"],\"st\":[\"Lean your chest against the pad and grip one handle, palm in.\",\"Start with your arm extended.\",\"Pull the handle back, driving your elbow past your torso.\",\"Squeeze your back at the end.\",\"Return slowly, finish your reps, then switch arms.\"],\"img\":\"6515.webp\",\"gif\":\"6515.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm chest-supported row with a neutral grip, letting you focus on each side of your back.\"},{\"id\":\"6517\",\"n\":\"lever bent over single arm wide grip row (with chest support)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"biceps\"],\"st\":[\"Lean your chest on the pad and grip one wide handle.\",\"Start with your arm extended.\",\"Pull the handle back with your elbow flaring out.\",\"Squeeze at the end.\",\"Return slowly, finish your reps, then switch arms.\"],\"img\":\"6517.webp\",\"gif\":\"6517.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm chest-supported row on a wide handle, hitting the upper back and rear shoulder on one side.\"},{\"id\":\"6516\",\"n\":\"lever bent over wide grip row (with chest support)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"biceps\"],\"st\":[\"Lean your chest on the pad and take the wide handles.\",\"Start with your arms extended.\",\"Pull the handles back with your elbows flared out.\",\"Squeeze your shoulder blades together.\",\"Return slowly and repeat.\"],\"img\":\"6516.webp\",\"gif\":\"6516.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row with a wide grip that shifts more work to the upper back and rear shoulders.\"},{\"id\":\"4899\",\"n\":\"lever bent over wide row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\",\"rhomboids\"],\"st\":[\"Load the machine and set your chest against the support.\",\"Grab the wide handles with arms extended.\",\"Pull the handles toward your lower chest, elbows flaring out.\",\"Squeeze your shoulder blades together.\",\"Return slowly until your arms are straight.\",\"Keep your chest on the pad throughout.\"],\"img\":\"4899.webp\",\"gif\":\"4899.mp4\",\"cat\":\"strength\",\"desc\":\"A plate loaded machine row with a wide grip while bent over. It builds the upper back and rear shoulders.\"},{\"id\":\"4336\",\"n\":\"lever biceps curl\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Adjust the seat so your elbows line up with the machine pivot.\",\"Grip the handles with palms up.\",\"Curl the handles toward your shoulders.\",\"Squeeze your biceps at the top.\",\"Lower slowly until your arms are nearly straight.\"],\"img\":\"4336.webp\",\"gif\":\"4336.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl on a plate-loaded lever machine that guides the path. It builds the front of the upper arm.\"},{\"id\":\"1863\",\"n\":\"lever cable rear pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Adjust the seat and grip the handles overhead.\",\"Sit tall with your chest up.\",\"Pull the handles down, driving your elbows toward your sides.\",\"Squeeze your shoulder blades together at the bottom.\",\"Return slowly to full stretch.\"],\"img\":\"1863.webp\",\"gif\":\"1863.mp4\",\"cat\":\"strength\",\"desc\":\"Machine pulldown behind the line of the body that trains the lats and upper back.\"},{\"id\":\"1862\",\"n\":\"lever cable shoulder press\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Adjust the seat so the handles are at shoulder height.\",\"Sit back with your feet flat and grip the handles.\",\"Press upward until your arms are nearly straight.\",\"Pause briefly at the top.\",\"Lower slowly back to the start.\"],\"img\":\"1862.webp\",\"gif\":\"1862.mp4\",\"cat\":\"strength\",\"desc\":\"Seated machine press that builds the shoulders and triceps along a guided path.\"},{\"id\":\"1220\",\"n\":\"lever calf raise (bench press machine)\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit on the machine and place the balls of your feet on the lower platform or press plate.\",\"Push to straighten your legs and release the safety.\",\"Lower your heels as far as is comfortable.\",\"Rise up onto your toes as high as possible.\",\"Pause at the top and lower under control.\"],\"img\":\"1220.webp\",\"gif\":\"1220.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise done on a chest press style lever machine, using the seat and handles to load the calves.\"},{\"id\":\"1447\",\"n\":\"lever calf stretch (plate loaded)\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Set up on the machine and place the ball of one foot on the platform with the heel free.\",\"Keep your knee straight and stand tall.\",\"Let the heel sink down until you feel a stretch in the calf.\",\"Hold for 20-30 seconds, breathing steadily, then release slowly.\",\"Switch legs and repeat.\"],\"img\":\"1447.webp\",\"gif\":\"1447.mp4\",\"cat\":\"stretching\",\"desc\":\"A calf stretch on a plate-loaded lever machine, using the platform to push the heel down and lengthen the lower leg.\"},{\"id\":\"1038\",\"n\":\"lever chair squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Position yourself in the machine with the pads on your shoulders and feet shoulder width apart.\",\"Release the safety and brace your core.\",\"Bend your knees and sit back and down.\",\"Drive through your heels to stand back up.\",\"Keep your chest up and knees tracking over your toes.\"],\"img\":\"1038.webp\",\"gif\":\"1038.mp4\",\"cat\":\"strength\",\"desc\":\"A machine squat performed with a chair-like support, a stable way to train the legs.\"},{\"id\":\"1455\",\"n\":\"lever chest press v. 2\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"shoulders\"],\"st\":[\"Adjust the seat so the handles line up with the middle of your chest.\",\"Sit back with your shoulder blades against the pad and feet flat.\",\"Press the handles forward until your arms are almost straight.\",\"Pause, then return slowly until you feel a stretch across the chest.\",\"Keep your wrists straight and your back on the pad throughout.\"],\"img\":\"1455.webp\",\"gif\":\"1455.mp4\",\"cat\":\"strength\",\"desc\":\"A machine chest press with a lever arm that guides the push. It builds the chest and triceps.\"},{\"id\":\"2277\",\"n\":\"lever chest press v. 4\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Adjust the seat so the handles are at mid-chest height.\",\"Sit back with your shoulder blades pulled together.\",\"Press the handles forward until your arms are almost straight.\",\"Do not lock your elbows.\",\"Return slowly until you feel a stretch in the chest.\",\"Repeat for the planned reps.\"],\"img\":\"2277.webp\",\"gif\":\"2277.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded chest press that trains the pecs and triceps along a guided path.\"},{\"id\":\"6881\",\"n\":\"lever cross lat pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\"],\"st\":[\"Adjust the seat and thigh pad, then grab the handles.\",\"Sit tall with your chest up.\",\"Pull the handles down and across toward your torso.\",\"Squeeze your lats at the bottom.\",\"Return slowly to a full stretch.\"],\"img\":\"6881.webp\",\"gif\":\"6881.mp4\",\"cat\":\"strength\",\"desc\":\"A machine pulldown where the arms cross the body path. It builds the lats and upper back.\"},{\"id\":\"3344\",\"n\":\"lever crossovers\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Set the seat height and grip the handles with a slight elbow bend.\",\"Sit tall with your back against the pad.\",\"Sweep your arms together in front of your chest.\",\"Squeeze your chest at the center.\",\"Return slowly until you feel a stretch.\"],\"img\":\"3344.webp\",\"gif\":\"3344.mp4\",\"cat\":\"strength\",\"desc\":\"A machine crossover that brings your arms together across the body, isolating the chest.\"},{\"id\":\"2278\",\"n\":\"lever decline chest press v. 2\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat and sit with your back against the pad.\",\"Grip the handles with elbows bent.\",\"Press forward and slightly downward until your arms are almost straight.\",\"Keep your shoulders down and your chest up.\",\"Return slowly under control.\",\"Repeat for the planned reps.\"],\"img\":\"2278.webp\",\"gif\":\"2278.mp4\",\"cat\":\"strength\",\"desc\":\"A decline-angle machine press that emphasises the lower part of the chest.\"},{\"id\":\"1858\",\"n\":\"lever decline sit up\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie back on the decline seat and hook your feet under the pads.\",\"Cross your arms or hold the handles.\",\"Curl your torso up toward your knees.\",\"Squeeze your abs at the top.\",\"Lower back slowly under control.\"],\"img\":\"1858.webp\",\"gif\":\"1858.mp4\",\"cat\":\"strength\",\"desc\":\"Decline sit-up on a lever machine that adds resistance for stronger abdominal work.\"},{\"id\":\"1039\",\"n\":\"lever full squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"adductors\"],\"st\":[\"Step into the machine with the pads on your shoulders and feet shoulder width apart.\",\"Release the safety and brace your core.\",\"Squat as deep as you comfortably can.\",\"Drive through your heels to stand.\",\"Keep your chest up and knees over your toes.\"],\"img\":\"1039.webp\",\"gif\":\"1039.mp4\",\"cat\":\"strength\",\"desc\":\"A full range machine squat that builds the thighs and glutes with a guided path.\"},{\"id\":\"6601\",\"n\":\"lever glute press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\"],\"st\":[\"Position yourself on the machine and set your feet on the platform.\",\"Brace your core.\",\"Press the platform away by driving through your heels.\",\"Squeeze your glutes at the end.\",\"Return slowly and repeat.\"],\"img\":\"6601.webp\",\"gif\":\"6601.mp4\",\"cat\":\"strength\",\"desc\":\"A glute press on a lever machine that targets your glutes by pushing your hips and legs back against resistance.\"},{\"id\":\"6733\",\"n\":\"lever good morning on the hack squat machine\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\"],\"st\":[\"Set up under the shoulder pads with feet shoulder-width apart.\",\"Unlock the machine and stand tall.\",\"Push your hips back and lean your torso forward with a flat back.\",\"Lower until you feel a hamstring stretch.\",\"Drive your hips forward to stand.\",\"Keep your knees slightly bent throughout.\"],\"img\":\"6733.webp\",\"gif\":\"6733.mp4\",\"cat\":\"strength\",\"desc\":\"A good morning done on a hack squat machine. The machine supports your back while you hinge at the hips.\"},{\"id\":\"5516\",\"n\":\"lever hack squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Set your shoulders under the pads and feet shoulder width on the platform.\",\"Release the safety handles.\",\"Lower until your thighs are at least parallel to the platform.\",\"Press through your whole foot to stand.\",\"Do not lock your knees hard at the top.\"],\"img\":\"5516.webp\",\"gif\":\"5516.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded hack squat machine that lets you load the quads and glutes with back support.\"},{\"id\":\"2662\",\"n\":\"lever high row (plate loaded) v. 2\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Adjust the seat and chest pad so you can grip the handles with arms extended.\",\"Sit tall with your chest on the pad.\",\"Pull the handles down and back, driving the elbows toward your hips.\",\"Squeeze the shoulder blades together.\",\"Return slowly and keep your shoulders down.\"],\"img\":\"2662.webp\",\"gif\":\"2662.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded high row machine that pulls from above to train the lats and upper back.\"},{\"id\":\"2663\",\"n\":\"lever high row (plate loaded) v. 3\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Adjust the seat and chest pad so you can grip the handles with arms extended.\",\"Sit tall with your chest on the pad.\",\"Pull the handles down and back, driving the elbows toward your hips.\",\"Squeeze the shoulder blades together.\",\"Return slowly and keep your shoulders down.\"],\"img\":\"2663.webp\",\"gif\":\"2663.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded high row machine that pulls from above to train the lats and upper back.\"},{\"id\":\"2146\",\"n\":\"lever hip thrust\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"adductors\"],\"st\":[\"Sit on the machine with your upper back against the pad and the belt across your hips.\",\"Plant your feet flat, about hip width apart.\",\"Drive through your heels and lift your hips until your torso and thighs are in line.\",\"Squeeze your glutes at the top for a moment.\",\"Lower with control and repeat, keeping your chin tucked.\"],\"img\":\"2146.webp\",\"gif\":\"2146.mp4\",\"cat\":\"strength\",\"desc\":\"A machine version of the hip thrust that loads the glutes with a fixed path of motion.\"},{\"id\":\"7384\",\"n\":\"lever hip thrust (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit with your back against the pad and belt secured over your hips.\",\"Plant your feet flat, shoulder width apart.\",\"Drive your hips up until your body is level.\",\"Squeeze your glutes at the top.\",\"Lower with control.\"],\"img\":\"7384.webp\",\"gif\":\"7384.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded machine hip thrust for heavy glute work.\",\"fv\":\"3549\"},{\"id\":\"2742\",\"n\":\"lever hip thrust (with stepbox) v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit in the machine with your feet on the step box and the pad across your hips.\",\"Brace your core and drive through your heels.\",\"Lift your hips until your body is straight from shoulders to knees.\",\"Squeeze your glutes at the top.\",\"Lower slowly to the start.\"],\"img\":\"2742.webp\",\"gif\":\"2742.mp4\",\"cat\":\"strength\",\"desc\":\"A machine hip thrust with the feet raised on a step box, for a deeper glute contraction.\"},{\"id\":\"2743\",\"n\":\"lever hip thrust v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit in the machine with your back against the pad and your feet flat.\",\"Secure the hip pad over your lap.\",\"Drive through your heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower with control without letting the weight crash.\"],\"img\":\"2743.webp\",\"gif\":\"2743.mp4\",\"cat\":\"strength\",\"desc\":\"A machine hip thrust that loads the glutes in a controlled path.\"},{\"id\":\"2147\",\"n\":\"lever hip thrust with resistance band\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"quadriceps\"],\"st\":[\"Sit on the machine with your upper back on the pad and a band around your thighs above the knees.\",\"Place your feet flat and push your knees gently out against the band.\",\"Drive through your heels and lift your hips until your torso and thighs are in line.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat, keeping the knees pressed out.\"],\"img\":\"2147.webp\",\"gif\":\"2147.mp4\",\"cat\":\"strength\",\"desc\":\"A machine hip thrust with a band around the thighs, adding hip abductor work to the glute drive.\"},{\"id\":\"2951\",\"n\":\"lever horizontal leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Sit on the machine with your back flat against the pad and feet on the platform.\",\"Set your feet about shoulder-width apart.\",\"Press the platform away until your legs are nearly straight.\",\"Do not lock your knees.\",\"Lower slowly until your knees are bent about 90 degrees and repeat.\"],\"img\":\"2951.webp\",\"gif\":\"2951.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press on a horizontal lever machine. It builds the quads and glutes with back support.\",\"fv\":\"2377\"},{\"id\":\"2659\",\"n\":\"lever incline chest press (plate loaded)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat so the handles are level with your upper chest.\",\"Sit back and grip the handles with feet flat on the floor.\",\"Press forward until your arms are nearly straight.\",\"Squeeze the chest, then return slowly.\",\"Keep your back against the pad and your shoulders down.\"],\"img\":\"2659.webp\",\"gif\":\"2659.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine press on an incline that targets the upper chest and the front of the shoulders.\"},{\"id\":\"11718\",\"n\":\"lever incline chest supported reverse delt fly (plate loaded)\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\",\"trapezius\"],\"st\":[\"Sit with your chest against the incline pad and grab the handles.\",\"Start with arms forward and slightly bent.\",\"Sweep your arms out and back in a wide arc.\",\"Squeeze your shoulder blades at the end.\",\"Return slowly without letting the weight crash.\"],\"img\":\"11718.webp\",\"gif\":\"11718.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported reverse fly on a plate-loaded lever machine that isolates the rear delts.\"},{\"id\":\"5843\",\"n\":\"lever incline fly\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Sit in the machine with your back against the pad.\",\"Grip the handles with elbows slightly bent.\",\"Bring the handles together in front of your upper chest.\",\"Squeeze your chest.\",\"Return slowly to a comfortable stretch.\"],\"img\":\"5843.webp\",\"gif\":\"5843.mp4\",\"cat\":\"strength\",\"desc\":\"A machine fly with an incline angle that emphasizes the upper chest. The handles move in a fixed arc.\"},{\"id\":\"1195\",\"n\":\"lever incline hammer chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat so the handles sit at upper chest height.\",\"Sit back with your shoulder blades pinned to the pad and grip the neutral handles.\",\"Press the handles up and forward until your arms are almost straight.\",\"Lower slowly until you feel a stretch across the chest.\",\"Keep your wrists straight and your back against the pad.\"],\"img\":\"1195.webp\",\"gif\":\"1195.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing on an incline chest machine with neutral hammer handles. It builds the upper chest and is gentle on the shoulders.\",\"fv\":\"3608\"},{\"id\":\"4371\",\"n\":\"lever incline one arm chest press (plate loaded)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Sit on the machine and grip one handle.\",\"Set your back firmly against the pad.\",\"Press the handle forward and up.\",\"Squeeze your chest at the top.\",\"Return slowly, then switch arms.\"],\"img\":\"4371.webp\",\"gif\":\"4371.mp4\",\"cat\":\"strength\",\"desc\":\"A one-armed incline press on a plate-loaded lever machine. It trains the upper chest one side at a time.\"},{\"id\":\"10867\",\"n\":\"lever incline prone neutral grip row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Lie face down on the incline pad with your chest supported.\",\"Grip the neutral handles and extend your arms.\",\"Pull your elbows back past your torso, squeezing the shoulder blades together.\",\"Pause for a moment.\",\"Let the handles return slowly until your arms are straight.\"],\"img\":\"10867.webp\",\"gif\":\"10867.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported machine row on an incline with a neutral grip. It builds the mid back without loading the lower back.\"},{\"id\":\"10646\",\"n\":\"lever incline prone row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Lie chest-down on the incline pad and grab the handles.\",\"Let your arms extend fully.\",\"Pull the handles back, driving your elbows toward your hips.\",\"Squeeze your shoulder blades together.\",\"Lower slowly until your arms are straight.\",\"Keep your head neutral.\"],\"img\":\"10646.webp\",\"gif\":\"10646.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row on an incline lever machine. The support keeps your back steady so the upper back does the work.\"},{\"id\":\"10113\",\"n\":\"lever isometric squat hip abduction\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\"],\"st\":[\"Set the machine pads against the outsides of your knees.\",\"Lower into a half squat and keep your chest up.\",\"Press your knees outward against the pads.\",\"Hold the position steadily for the target time.\",\"Release and stand up slowly.\"],\"img\":\"10113.webp\",\"gif\":\"10113.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a squat while pressing out against a machine pad. It trains the outer hips and glutes.\",\"hd\":1},{\"id\":\"2748\",\"n\":\"lever kneeling reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Kneel on the machine pad and hold the handles.\",\"Place the back of your working leg against the lever pad.\",\"Press the leg back and up until your hip is fully extended.\",\"Squeeze your glute at the top.\",\"Lower slowly and switch legs.\"],\"img\":\"2748.webp\",\"gif\":\"2748.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling machine kickback that extends the hip and works the glutes.\"},{\"id\":\"1870\",\"n\":\"lever lateral pulldown (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\"],\"st\":[\"Adjust the seat and grip the handles overhead.\",\"Sit tall with your chest up.\",\"Pull down until the handles reach chest level.\",\"Squeeze your shoulder blades together.\",\"Return slowly to full stretch.\"],\"img\":\"1870.webp\",\"gif\":\"1870.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded machine pulldown that trains the lats and upper back.\"},{\"id\":\"1876\",\"n\":\"lever lateral raise (plate loaded)\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rear deltoids\"],\"st\":[\"Adjust the seat and place your arms against the pads.\",\"Sit upright.\",\"Raise your arms out to the sides until about shoulder height.\",\"Pause at the top.\",\"Lower slowly to the start.\"],\"img\":\"1876.webp\",\"gif\":\"1876.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded machine raise that targets the side of the shoulders.\"},{\"id\":\"3343\",\"n\":\"lever lateral raise v. 2\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Adjust the seat so your shoulders line up with the machine pivots.\",\"Sit tall and place your arms against the pads.\",\"Raise your arms out to the sides to shoulder height.\",\"Pause briefly at the top.\",\"Lower slowly without letting the weights rest.\"],\"img\":\"3343.webp\",\"gif\":\"3343.mp4\",\"cat\":\"strength\",\"desc\":\"A machine lateral raise that isolates the side delts with smooth, guided resistance.\"},{\"id\":\"2665\",\"n\":\"lever lateral wide pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Adjust the seat and thigh pad, then grip the wide handles.\",\"Sit tall with your chest up.\",\"Pull the handles down toward your upper chest, leading with the elbows.\",\"Squeeze the lats, then let the handles rise slowly.\",\"Avoid leaning far back or using momentum.\"],\"img\":\"2665.webp\",\"gif\":\"2665.mp4\",\"cat\":\"strength\",\"desc\":\"A machine pulldown with a wide grip that targets the lats for a broad back.\"},{\"id\":\"7327\",\"n\":\"lever leg extension (inward toes)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shins\"],\"st\":[\"Sit in the machine with the pad on your lower shins.\",\"Turn your toes slightly inward.\",\"Extend your knees until your legs are straight.\",\"Squeeze your quads for a second.\",\"Lower the weight slowly.\"],\"img\":\"7327.webp\",\"gif\":\"7327.mp4\",\"cat\":\"strength\",\"desc\":\"Leg extension with toes angled in to shift the emphasis on the quads.\"},{\"id\":\"1873\",\"n\":\"lever leg extension (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit with your back against the pad and your shins behind the roller.\",\"Hold the handles.\",\"Extend your knees until your legs are straight.\",\"Squeeze your quads at the top.\",\"Lower slowly under control.\"],\"img\":\"1873.webp\",\"gif\":\"1873.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded leg extension that isolates the front of the thighs.\"},{\"id\":\"6523\",\"n\":\"lever linear hack squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on the platform with your back against the pad and shoulders under the supports.\",\"Place your feet shoulder-width apart.\",\"Lower into a squat until your thighs are about parallel.\",\"Press through your feet to stand.\",\"Keep your back against the pad throughout.\"],\"img\":\"6523.webp\",\"gif\":\"6523.mp4\",\"cat\":\"strength\",\"desc\":\"A hack squat on a linear lever machine that loads your thighs and glutes along a fixed path.\"},{\"id\":\"4214\",\"n\":\"lever low row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit with your chest against the pad and your feet planted.\",\"Grab both handles with straight arms.\",\"Pull the handles toward your lower ribs, squeezing your shoulder blades.\",\"Pause for a moment at the end.\",\"Let the arms extend slowly under control.\",\"Do not lean back to move the weight.\"],\"img\":\"4214.webp\",\"gif\":\"4214.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine row pulling from low to your torso. It builds the mid back and lats with a guided path.\"},{\"id\":\"4062\",\"n\":\"lever lying banded t bar row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Lie chest down on the support and grip the handles.\",\"Keep your head neutral.\",\"Pull your elbows back and squeeze your shoulder blades.\",\"Pause at the top.\",\"Lower slowly against the band tension.\"],\"img\":\"4062.webp\",\"gif\":\"4062.mp4\",\"cat\":\"strength\",\"desc\":\"Chest-supported T bar row on a lever machine with bands for extra resistance as you pull.\"},{\"id\":\"1041\",\"n\":\"lever lying chest press (plate loaded)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie back on the machine bench and grip the handles at chest level.\",\"Plant your feet and keep your shoulders pulled back.\",\"Press the handles up until your arms are almost straight.\",\"Lower slowly until you feel a stretch in the chest.\",\"Keep your back on the pad throughout.\"],\"img\":\"1041.webp\",\"gif\":\"1041.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded press from a lying position, working the chest with a guided path.\",\"fv\":\"3610\"},{\"id\":\"2276\",\"n\":\"lever lying crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie back on the machine and place your hands or arms as indicated.\",\"Hook your feet or grip the handles for stability.\",\"Curl your torso up by contracting your abs.\",\"Pause briefly at the top.\",\"Lower slowly back to the start.\",\"Repeat for the planned reps.\"],\"img\":\"2276.webp\",\"gif\":\"2276.mp4\",\"cat\":\"strength\",\"desc\":\"A machine crunch performed lying back, letting you load the abs while the lower back stays supported.\"},{\"id\":\"2314\",\"n\":\"lever lying crunch v. 2\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"obliques\",\"hip flexors\"],\"st\":[\"Lie back on the machine and set your feet or hands as the machine requires.\",\"Grip the handles lightly and set your lower back against the pad.\",\"Curl your ribs toward your hips to crunch up.\",\"Exhale and squeeze your abs at the top.\",\"Lower slowly without letting the weight stack rest.\",\"Repeat for the planned reps.\"],\"img\":\"2314.webp\",\"gif\":\"2314.mp4\",\"cat\":\"strength\",\"desc\":\"A machine crunch performed lying back, targeting the abdominal muscles with adjustable resistance.\"},{\"id\":\"9676\",\"n\":\"lever lying knee flexion\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie face down on the machine with the pad above your heels.\",\"Grip the handles and keep your hips down.\",\"Curl your heels toward your glutes.\",\"Squeeze at the top.\",\"Lower slowly back to the start.\"],\"img\":\"9676.webp\",\"gif\":\"9676.mp4\",\"cat\":\"strength\",\"desc\":\"The classic lying leg curl on a machine, isolating the hamstrings.\"},{\"id\":\"11567\",\"n\":\"lever lying leg curl to reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"calves\"],\"st\":[\"Lie face down on the machine with the pads behind your lower legs.\",\"Curl your heels toward your glutes, then lower with control.\",\"Move into the reverse hyperextension position with the pad behind your legs.\",\"Squeeze your glutes to raise your legs until they line up with your torso.\",\"Lower slowly and avoid swinging.\"],\"img\":\"11567.webp\",\"gif\":\"11567.mp4\",\"cat\":\"strength\",\"desc\":\"A combo move on a lever machine: curl the legs up, then lift the hips and legs to work hamstrings and glutes together.\"},{\"id\":\"1856\",\"n\":\"lever lying leg raise (bent knee)\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie back on the machine and grip the handles.\",\"Bend your knees and place your legs under the pads.\",\"Curl your knees up toward your chest.\",\"Pause briefly at the top.\",\"Lower slowly until you feel tension, then repeat.\"],\"img\":\"1856.webp\",\"gif\":\"1856.mp4\",\"cat\":\"strength\",\"desc\":\"Machine-based lying leg raise with bent knees that loads the lower abs and hip flexors.\"},{\"id\":\"1590\",\"n\":\"lever lying single leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\"],\"st\":[\"Lie face down on the machine and place one leg under the pad above your heel.\",\"Hold the handles and keep your hips pressed down.\",\"Curl your heel up toward your glutes.\",\"Squeeze your hamstring at the top.\",\"Lower slowly, then switch legs after your reps.\"],\"img\":\"1590.webp\",\"gif\":\"1590.mp4\",\"cat\":\"strength\",\"desc\":\"A lying hamstring curl on a machine using one leg at a time. It helps balance strength between legs.\",\"fv\":\"4427\"},{\"id\":\"1194\",\"n\":\"lever lying t bar row\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Lie chest-down on the pad and grab the handles.\",\"Start with your arms straight.\",\"Pull the handles toward your torso.\",\"Squeeze your shoulder blades.\",\"Lower under control.\"],\"img\":\"1194.webp\",\"gif\":\"1194.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported T-bar row lying on the machine pad.\",\"fv\":\"11307\"},{\"id\":\"5326\",\"n\":\"lever multy mode rope lat pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\",\"grip muscles\"],\"st\":[\"Sit at the machine and grab the rope handles.\",\"Set your thighs under the pads and sit tall.\",\"Pull the handles down toward your upper chest.\",\"Drive your elbows down and back.\",\"Let the handles rise slowly until your arms are straight.\",\"Avoid leaning back too far.\"],\"img\":\"5326.webp\",\"gif\":\"5326.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown on a lever machine using rope handles. The multi-mode setup lets you vary the pulling path.\"},{\"id\":\"3102\",\"n\":\"lever narrow grip seated row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Sit with your chest against the pad and take the narrow handles.\",\"Pull both handles toward your torso.\",\"Squeeze your shoulder blades together at the end.\",\"Pause briefly.\",\"Return slowly with control.\"],\"img\":\"3102.webp\",\"gif\":\"3102.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine row with a narrow grip for the lats and mid back.\"},{\"id\":\"2282\",\"n\":\"lever neck extension (plate loaded)\",\"bp\":\"neck\",\"eq\":\"leverage machine\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Set the weight light and adjust the pad to rest on the back of your head.\",\"Sit tall and bring your chin slightly down.\",\"Press your head back against the pad slowly.\",\"Move only through a comfortable range.\",\"Return slowly to the start.\",\"Repeat for the planned reps with control.\"],\"img\":\"2282.webp\",\"gif\":\"2282.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine movement that strengthens the muscles at the back of the neck.\"},{\"id\":\"2283\",\"n\":\"lever neck left side flexion (plate loaded)\",\"bp\":\"neck\",\"eq\":\"leverage machine\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Set the weight light and position the pad against the left side of your head.\",\"Sit tall with your shoulders relaxed.\",\"Tilt your head to the left against the resistance.\",\"Keep the movement small and smooth.\",\"Return slowly to the centre.\",\"Repeat for the planned reps with control.\"],\"img\":\"2283.webp\",\"gif\":\"2283.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded neck exercise that bends the head sideways to the left to strengthen the side neck muscles.\"},{\"id\":\"2284\",\"n\":\"lever neck right side flexion (plate loaded)\",\"bp\":\"neck\",\"eq\":\"leverage machine\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Set the weight light and position the pad against the right side of your head.\",\"Sit tall with your shoulders relaxed.\",\"Tilt your head to the right against the resistance.\",\"Keep the movement small and smooth.\",\"Return slowly to the centre.\",\"Repeat for the planned reps with control.\"],\"img\":\"2284.webp\",\"gif\":\"2284.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded neck exercise that bends the head sideways to the right to strengthen the side neck muscles.\"},{\"id\":\"2974\",\"n\":\"lever one arm chest press (plate loaded)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Sit on the machine with your back against the pad and grip one handle.\",\"Set your feet flat on the floor.\",\"Press the handle forward until your arm is nearly straight.\",\"Pause briefly.\",\"Return slowly, finish the reps, then switch arms.\"],\"img\":\"2974.webp\",\"gif\":\"2974.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm chest press on a plate-loaded machine. It lets each side work on its own.\",\"fv\":\"2975\"},{\"id\":\"5576\",\"n\":\"lever one arm incline chest press (plate loaded)\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Sit on the machine and grip one handle.\",\"Keep your back against the pad.\",\"Press the handle up and forward until the arm is nearly straight.\",\"Lower slowly with control.\",\"Finish reps, then switch arms.\"],\"img\":\"5576.webp\",\"gif\":\"5576.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded machine press on an incline, one arm at a time, for upper chest.\"},{\"id\":\"4215\",\"n\":\"lever one arm low row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit with your chest on the pad and grab one handle.\",\"Start with your arm extended and shoulder relaxed forward.\",\"Pull the handle back, driving your elbow past your torso.\",\"Squeeze your shoulder blade toward your spine.\",\"Lower slowly until your arm is straight.\",\"Finish your reps, then switch sides.\"],\"img\":\"4215.webp\",\"gif\":\"4215.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm version of the plate-loaded low row. Working one side at a time helps fix strength differences in your back.\"},{\"id\":\"1235\",\"n\":\"lever one arm seated row (seated row machine)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Sit at the machine with your chest on the pad and grab one handle.\",\"Start with your arm extended.\",\"Pull the handle toward your torso, driving your elbow back.\",\"Squeeze your shoulder blade, then return slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"1235.webp\",\"gif\":\"1235.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm row on a seated machine. It lets you load one side of the back at a time.\"},{\"id\":\"5815\",\"n\":\"lever one arm side chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Sit in the machine with your back against the pad.\",\"Grip one handle at chest level.\",\"Press the handle forward until your arm is straight.\",\"Squeeze your chest at the end.\",\"Return slowly and switch arms after your set.\"],\"img\":\"5815.webp\",\"gif\":\"5815.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm press on a chest press machine. Training one side at a time helps balance strength between arms.\"},{\"id\":\"1571\",\"n\":\"lever one leg extension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the machine and adjust the pad so it rests on your lower shin.\",\"Set one foot under the pad and keep the other foot on the floor or footrest.\",\"Extend your working leg until it is almost straight.\",\"Squeeze your quad at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"1571.webp\",\"gif\":\"1571.mp4\",\"cat\":\"strength\",\"desc\":\"A machine leg extension done one leg at a time. It isolates the quads and helps even out strength between sides.\"},{\"id\":\"6355\",\"n\":\"lever outdoor seated chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Sit with your back flat against the pad and grip the handles at chest height.\",\"Keep your shoulders down and back.\",\"Press the handles forward until your arms are almost straight.\",\"Pause briefly.\",\"Let the handles come back slowly and repeat.\"],\"img\":\"6355.webp\",\"gif\":\"6355.mp4\",\"cat\":\"strength\",\"desc\":\"A seated chest press on an outdoor lever machine that works your chest, front shoulders and triceps.\"},{\"id\":\"6356\",\"n\":\"lever outdoor seated lat pulldown\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit down and grab the handles overhead.\",\"Lean back very slightly and lift your chest.\",\"Pull the handles down toward your upper chest, driving your elbows down.\",\"Squeeze your back at the bottom.\",\"Let your arms rise slowly until fully stretched, then repeat.\"],\"img\":\"6356.webp\",\"gif\":\"6356.mp4\",\"cat\":\"strength\",\"desc\":\"Pulling the handles down from overhead on an outdoor lever machine to build your lats and upper back.\"},{\"id\":\"6354\",\"n\":\"lever outdoor seated leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit on the seat with your back against the pad.\",\"Place your feet on the footplates, shoulder-width apart.\",\"Push the plates away until your legs are nearly straight.\",\"Do not lock your knees at the top.\",\"Bend your knees to return slowly and repeat.\"],\"img\":\"6354.webp\",\"gif\":\"6354.mp4\",\"cat\":\"strength\",\"desc\":\"Seated leg press on an outdoor lever machine, pushing the pads away with your legs to train thighs and glutes.\"},{\"id\":\"7864\",\"n\":\"lever overhead triceps extension\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Adjust the seat and sit with your back supported.\",\"Grip the handles overhead with your elbows pointing up.\",\"Extend your arms until they are almost straight.\",\"Squeeze your triceps at the top.\",\"Lower slowly behind your head.\"],\"img\":\"7864.webp\",\"gif\":\"7864.mp4\",\"cat\":\"strength\",\"desc\":\"A machine overhead triceps extension. The lever path keeps the movement smooth and the focus on the triceps.\"},{\"id\":\"1029\",\"n\":\"lever parallel chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Adjust the seat so the handles are at mid-chest height and sit back.\",\"Grip the handles with your elbows slightly below shoulder level.\",\"Press the handles forward until your arms are almost straight.\",\"Return slowly until you feel a stretch in the chest.\",\"Keep your back against the pad.\"],\"img\":\"1029.webp\",\"gif\":\"1029.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine press with parallel handles, working the chest with a stable path.\"},{\"id\":\"1030\",\"n\":\"lever pec deck fly\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rear deltoids\",\"chest\"],\"st\":[\"Sit on the pec deck with your back flat and the arms at chest level.\",\"Place your forearms or hands on the pads with elbows slightly bent.\",\"Bring the arms together in front of your chest.\",\"Squeeze for a moment, then open slowly until you feel a chest stretch.\",\"Keep your shoulders down and back.\"],\"img\":\"1030.webp\",\"gif\":\"1030.mp4\",\"cat\":\"strength\",\"desc\":\"A machine fly where the arms sweep together in front, isolating the chest.\",\"fv\":\"2427\"},{\"id\":\"4951\",\"n\":\"lever pendulum squat (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Load the machine and step onto the platform.\",\"Place your shoulders under the pads.\",\"Unlock the machine and lower in a controlled squat.\",\"Go as deep as comfortable.\",\"Push through your feet to stand.\",\"Keep your chest up and heels down.\"],\"img\":\"4951.webp\",\"gif\":\"4951.mp4\",\"cat\":\"strength\",\"desc\":\"A squat on a pendulum machine that swings along an arc. It loads the quads heavily.\",\"fv\":\"5778\"},{\"id\":\"1040\",\"n\":\"lever pistol squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Step into the machine and put one foot on the platform with the other leg lifted or extended.\",\"Brace your core and release the safety.\",\"Lower slowly into a deep squat on one leg.\",\"Press through your heel to stand.\",\"Keep your knee in line with your toes. Finish the reps, then switch legs.\"],\"img\":\"1040.webp\",\"gif\":\"1040.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg squat on a machine that supports balance while you load one leg through full depth.\"},{\"id\":\"1872\",\"n\":\"lever preacher curl (plate loaded)\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Adjust the seat so your upper arms rest on the pad.\",\"Grip the handles with your palms up.\",\"Curl up until your biceps are fully contracted.\",\"Pause briefly.\",\"Lower slowly until your arms are almost straight.\"],\"img\":\"1872.webp\",\"gif\":\"1872.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded preacher curl that isolates the biceps with the arms supported.\",\"fv\":\"3103\"},{\"id\":\"2660\",\"n\":\"lever preacher curl (plate loaded) v. 2\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Adjust the seat so your upper arms rest flat on the pad.\",\"Grip the handles with palms up.\",\"Curl the handles toward your shoulders.\",\"Squeeze at the top, then lower slowly.\",\"Do not lift your elbows off the pad or let the weight drop.\"],\"img\":\"2660.webp\",\"gif\":\"2660.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded preacher machine curl that isolates the biceps with your upper arms supported.\"},{\"id\":\"5299\",\"n\":\"lever preacher curl (turned torso)\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Sit at the machine and adjust the seat so your arms rest on the pad.\",\"Turn your torso slightly toward the working arm.\",\"Curl the handle up toward your shoulder.\",\"Squeeze at the top.\",\"Lower slowly, then switch arms.\"],\"img\":\"5299.webp\",\"gif\":\"5299.mp4\",\"cat\":\"strength\",\"desc\":\"A machine preacher curl with a slight torso turn. It keeps steady tension on the biceps.\"},{\"id\":\"5447\",\"n\":\"lever pronated grip seated row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Sit at the machine with your chest on the pad.\",\"Grab the handles with palms facing down.\",\"Pull your elbows back and squeeze your shoulder blades together.\",\"Pause briefly.\",\"Return slowly until your arms extend.\",\"Keep your torso steady.\"],\"img\":\"5447.webp\",\"gif\":\"5447.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded seated row with an overhand grip. Targets the upper back and lats.\"},{\"id\":\"5448\",\"n\":\"lever pronated grip seated scapular retraction shrug (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Sit in the machine with your chest on the pad.\",\"Grip the handles overhand with arms straight.\",\"Pull your shoulder blades together without bending your elbows much.\",\"Hold for a second.\",\"Let your shoulder blades spread slowly.\",\"Avoid shrugging toward your ears.\"],\"img\":\"5448.webp\",\"gif\":\"5448.mp4\",\"cat\":\"strength\",\"desc\":\"A short seated row focusing on pulling your shoulder blades together. Isolates the mid back.\"},{\"id\":\"7884\",\"n\":\"lever push up with towels\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place your hands on towels on the floor in a plank.\",\"Keep your body in a straight line.\",\"Lower your chest toward the floor.\",\"Press back up.\",\"Keep your elbows at about 45 degrees.\",\"Repeat for the planned reps.\"],\"img\":\"7884.webp\",\"gif\":\"7884.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands on towels, adding instability for the chest and shoulders.\"},{\"id\":\"4378\",\"n\":\"lever reverse grip high row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\",\"rear deltoids\"],\"st\":[\"Sit at the machine with your chest against the pad and grab the handles underhand.\",\"Set your shoulders back and down.\",\"Pull the handles toward your lower ribs, driving your elbows back.\",\"Squeeze your back at the end of the pull.\",\"Slowly extend your arms without letting your shoulders round forward.\"],\"img\":\"4378.webp\",\"gif\":\"4378.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine row with an underhand grip that trains the lats and upper back while the biceps assist.\"},{\"id\":\"4174\",\"n\":\"lever reverse shoulder press (plate loaded)\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Adjust the seat and sit with your back against the pad.\",\"Grip the handles with a reverse grip.\",\"Press the handles up until your arms are extended.\",\"Pause at the top.\",\"Lower slowly to shoulder level.\",\"Keep your core braced.\"],\"img\":\"4174.webp\",\"gif\":\"4174.mp4\",\"cat\":\"strength\",\"desc\":\"A plate loaded press with a reverse grip on a lever machine. It targets the front shoulders.\"},{\"id\":\"5784\",\"n\":\"lever reverse vertical hack squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Set the machine and stand with your chest against the pad, feet on the platform.\",\"Grip the handles and brace your core.\",\"Bend your knees and lower until your thighs are about parallel.\",\"Press through your whole foot to stand.\",\"Keep your knees tracking over your toes.\"],\"img\":\"5784.webp\",\"gif\":\"5784.mp4\",\"cat\":\"strength\",\"desc\":\"A machine squat facing the pad with a vertical lever path. Hits the thighs and glutes with back-friendly support.\"},{\"id\":\"8712\",\"n\":\"lever romanian deadlift (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand in the machine and grip the handles with a flat back.\",\"Keep a soft bend in your knees.\",\"Hinge at the hips, pushing them back as you lower.\",\"Stop when you feel the hamstrings stretch.\",\"Drive your hips forward to stand.\"],\"img\":\"8712.webp\",\"gif\":\"8712.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge on a plate-loaded machine that trains the hamstrings and glutes.\"},{\"id\":\"1237\",\"n\":\"lever row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Adjust the seat and chest pad, then grab the handles.\",\"Sit tall with your chest against the pad.\",\"Pull the handles toward your torso, squeezing your shoulder blades.\",\"Pause for a moment.\",\"Return slowly until your arms are straight.\"],\"img\":\"1237.webp\",\"gif\":\"1237.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine row. The guided path lets you pull heavy with good back engagement.\"},{\"id\":\"5527\",\"n\":\"lever seated bent over rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit on the machine with your chest on the pad and grip the handles.\",\"Keep a slight bend in your elbows.\",\"Open your arms out and back, squeezing your shoulder blades.\",\"Pause, then return slowly.\",\"Do not shrug.\"],\"img\":\"5527.webp\",\"gif\":\"5527.mp4\",\"cat\":\"strength\",\"desc\":\"Machine rear-delt fly where you lean forward and sweep your arms back.\"},{\"id\":\"7176\",\"n\":\"lever seated calf press v. 2\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Sit in the machine and place the balls of your feet on the platform.\",\"Extend your knees almost fully.\",\"Press up as high as you can onto your toes.\",\"Pause at the top.\",\"Lower your heels slowly for a good stretch.\"],\"img\":\"7176.webp\",\"gif\":\"7176.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine calf press that pushes through the balls of the feet. It builds the calf muscles.\"},{\"id\":\"2666\",\"n\":\"lever seated calf raise (plate loaded) v. 2\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit with the balls of your feet on the platform and the pad over your thighs.\",\"Release the safety and lower your heels for a stretch.\",\"Press up through the balls of your feet as high as you can.\",\"Pause and squeeze the calves.\",\"Lower slowly to full stretch.\"],\"img\":\"2666.webp\",\"gif\":\"2666.mp4\",\"cat\":\"strength\",\"desc\":\"A seated plate-loaded calf raise that focuses on the soleus under the calf.\"},{\"id\":\"2268\",\"n\":\"lever seated crunch (hands pad)\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit on the machine and adjust the seat so your hands reach the pad.\",\"Place your hands on the pads and brace your feet.\",\"Curl your torso forward by contracting your abs.\",\"Pause briefly at the bottom.\",\"Return slowly to the upright start.\",\"Repeat for the planned reps.\"],\"img\":\"2268.webp\",\"gif\":\"2268.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine crunch where the hands press on a pad, working the abs against steady resistance.\"},{\"id\":\"3881\",\"n\":\"lever seated full crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Adjust the seat and sit with the pads in position.\",\"Hold the handles and keep your feet planted.\",\"Exhale and curl your torso forward, bringing your ribs toward your hips.\",\"Squeeze your abs at the bottom.\",\"Return slowly to the start.\",\"Keep your hips on the seat.\"],\"img\":\"3881.webp\",\"gif\":\"3881.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine crunch that works the full abdominal wall with adjustable resistance.\"},{\"id\":\"2962\",\"n\":\"lever seated hammer grip shoulder press\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\"],\"st\":[\"Sit with your back against the pad and grip the neutral handles.\",\"Keep your feet flat on the floor.\",\"Press the handles overhead until your arms are almost straight.\",\"Pause briefly.\",\"Lower slowly to shoulder height and repeat.\"],\"img\":\"2962.webp\",\"gif\":\"2962.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine shoulder press with a neutral hammer grip. It trains the delts with a joint-friendly hand position.\"},{\"id\":\"1869\",\"n\":\"lever seated hip abduction v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Sit with your back against the pad and your legs inside the pads.\",\"Hold the handles for stability.\",\"Push your legs apart smoothly.\",\"Pause at the widest point.\",\"Return slowly without letting the weights crash.\"],\"img\":\"1869.webp\",\"gif\":\"1869.mp4\",\"cat\":\"strength\",\"desc\":\"Seated machine move that pushes the legs outward to train the outer hips.\",\"fv\":\"2553\"},{\"id\":\"1867\",\"n\":\"lever seated hip adduction v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Sit on the machine with your back against the pad.\",\"Place your legs against the pads, set wide.\",\"Squeeze your legs together smoothly.\",\"Pause for a moment when they meet.\",\"Open slowly back to the start.\"],\"img\":\"1867.webp\",\"gif\":\"1867.mp4\",\"cat\":\"strength\",\"desc\":\"Seated machine move that squeezes the legs together to train the inner thighs.\",\"fv\":\"2552\"},{\"id\":\"3768\",\"n\":\"lever seated horizontal leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Sit on the machine with your back against the pad and feet on the platform.\",\"Release the safety and press the platform away.\",\"Stop just before your knees lock.\",\"Lower the weight slowly until your knees are bent about 90 degrees.\",\"Keep your hips down and your back flat on the pad.\"],\"img\":\"3768.webp\",\"gif\":\"3768.mp4\",\"cat\":\"strength\",\"desc\":\"A seated leg press on a lever machine that builds the quads and glutes.\"},{\"id\":\"3882\",\"n\":\"lever seated left side crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Sit in the machine with the pads positioned for a left side crunch.\",\"Hold the handles and brace your core.\",\"Exhale and crunch your torso toward the left.\",\"Squeeze your side at the bottom.\",\"Return slowly to the start.\",\"Avoid using momentum.\"],\"img\":\"3882.webp\",\"gif\":\"3882.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine crunch to the left side that trains the obliques.\"},{\"id\":\"8604\",\"n\":\"lever seated leg curl (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Sit in the machine and adjust the pad above your ankles.\",\"Keep your back against the support.\",\"Curl your heels down and back as far as you can.\",\"Squeeze your hamstrings briefly.\",\"Return slowly without letting the weight crash.\"],\"img\":\"8604.webp\",\"gif\":\"8604.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded seated curl that isolates the hamstrings.\"},{\"id\":\"3386\",\"n\":\"lever seated leg extension v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on the machine with your back against the pad.\",\"Hook your lower shins under the roller and align your knees with the pivot.\",\"Extend your legs until they are nearly straight.\",\"Squeeze your quads briefly at the top.\",\"Lower slowly back to the start.\",\"Avoid swinging or lifting your hips.\"],\"img\":\"3386.webp\",\"gif\":\"3386.mp4\",\"cat\":\"strength\",\"desc\":\"A machine isolation move for the front of the thighs.\"},{\"id\":\"7108\",\"n\":\"lever seated leg extension v. 3\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\"],\"st\":[\"Sit with your back against the pad and shins behind the roller.\",\"Align your knees with the machine pivot.\",\"Extend your legs until they are nearly straight.\",\"Squeeze your quads at the top.\",\"Lower with control.\"],\"img\":\"7108.webp\",\"gif\":\"7108.mp4\",\"cat\":\"strength\",\"desc\":\"A machine leg extension that isolates the front of the thigh. It builds quad size and strength.\"},{\"id\":\"2267\",\"n\":\"lever seated leg press\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Adjust the seat and sit with your back flat against the pad.\",\"Place your feet on the platform about shoulder-width apart.\",\"Push through your heels until your legs are nearly straight.\",\"Do not lock your knees.\",\"Bend your knees slowly to return.\",\"Repeat for the planned reps.\"],\"img\":\"2267.webp\",\"gif\":\"2267.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine leg press that drives the legs forward to build thigh and glute strength with back support.\",\"fv\":\"2608\"},{\"id\":\"3385\",\"n\":\"lever seated leg press v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit on the machine and set your back firmly against the pad.\",\"Place your feet on the platform about shoulder-width apart.\",\"Release the safety and lower the weight until your knees bend to about 90 degrees.\",\"Press through your whole foot to extend your legs.\",\"Stop just short of locking your knees.\",\"Lower under control and repeat.\"],\"img\":\"3385.webp\",\"gif\":\"3385.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine press that loads the thighs and glutes with a stable path.\"},{\"id\":\"1216\",\"n\":\"lever seated one leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit on the machine and place the ball of one foot on the platform.\",\"Set the pad on your thigh and release the safety.\",\"Lower your heel for a stretch.\",\"Press up as high as you can onto your toes.\",\"Pause, lower slowly, then switch legs.\"],\"img\":\"1216.webp\",\"gif\":\"1216.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg seated calf raise on a machine. Working each leg alone helps balance strength and targets the soleus.\"},{\"id\":\"1586\",\"n\":\"lever seated one leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\"],\"st\":[\"Sit on the machine with your back against the pad and adjust the leg pad above your heel.\",\"Place one leg under the pad and rest the other foot on the footrest.\",\"Curl your heel down and back as far as you can.\",\"Squeeze your hamstring at the bottom.\",\"Return slowly, then switch legs after your reps.\"],\"img\":\"1586.webp\",\"gif\":\"1586.mp4\",\"cat\":\"strength\",\"desc\":\"A seated hamstring curl on a machine with one leg at a time. It isolates each hamstring.\"},{\"id\":\"1573\",\"n\":\"lever seated one leg squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the machine with your back against the pad and shoulders under the supports.\",\"Place one foot on the platform at about shoulder width.\",\"Lower under control by bending your knee.\",\"Keep your heel flat and your knee in line with your toes.\",\"Press back up, then switch legs after your reps.\"],\"img\":\"1573.webp\",\"gif\":\"1573.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine squat done on one leg. It lets you load each leg separately with good support.\"},{\"id\":\"1572\",\"n\":\"lever seated one leg wide squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Sit in the machine with your back against the pad and shoulders under the supports.\",\"Place one foot wide on the platform and keep the other leg off the load.\",\"Lower by bending your working knee as far as is comfortable.\",\"Keep your knee tracking over your toes.\",\"Press back up, then switch legs after your reps.\"],\"img\":\"1572.webp\",\"gif\":\"1572.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine squat using one leg in a wide stance. It loads the quads, glutes and inner thighs with back support.\"},{\"id\":\"3883\",\"n\":\"lever seated right side crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Sit in the machine with the pads positioned for a right side crunch.\",\"Hold the handles and brace your core.\",\"Exhale and crunch your torso toward the right.\",\"Squeeze your side at the bottom.\",\"Return slowly to the start.\",\"Avoid using momentum.\"],\"img\":\"3883.webp\",\"gif\":\"3883.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine crunch to the right side that trains the obliques.\"},{\"id\":\"2664\",\"n\":\"lever seated row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Adjust the seat so the handles line up with your mid chest.\",\"Sit with your chest against the pad and grip the handles.\",\"Pull your elbows back and squeeze the shoulder blades.\",\"Pause briefly, then return slowly.\",\"Keep your torso tight against the pad.\"],\"img\":\"2664.webp\",\"gif\":\"2664.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded seated row machine with a chest pad that builds the mid back and lats.\"},{\"id\":\"2265\",\"n\":\"lever seated row v. 2\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\"],\"st\":[\"Adjust the seat and chest pad, then sit with your chest against the pad.\",\"Grip the handles with arms extended.\",\"Pull the handles toward your torso by driving the elbows back.\",\"Squeeze your shoulder blades together.\",\"Return slowly until your arms are straight again.\",\"Repeat for the planned reps.\"],\"img\":\"2265.webp\",\"gif\":\"2265.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded seated row that trains the upper back and lats through a guided pulling path.\"},{\"id\":\"11056\",\"n\":\"lever seated scapular retraction (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Sit with your chest against the pad and grab the handles with straight arms.\",\"Let your shoulder blades spread forward slightly.\",\"Squeeze your shoulder blades together without bending your elbows.\",\"Hold the squeeze for a second.\",\"Return slowly to the start.\"],\"img\":\"11056.webp\",\"gif\":\"11056.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine move where you pull your shoulder blades together. It strengthens the muscles between your shoulder blades.\"},{\"id\":\"1454\",\"n\":\"lever seated shoulder press\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Adjust the seat so the handles start near shoulder height and sit with your back on the pad.\",\"Grip the handles and brace your core.\",\"Press the handles overhead until your arms are nearly straight.\",\"Pause briefly at the top without shrugging.\",\"Lower slowly back to shoulder height and repeat.\"],\"img\":\"1454.webp\",\"gif\":\"1454.mp4\",\"cat\":\"strength\",\"desc\":\"A machine overhead press that builds the shoulders and triceps with a fixed, stable path.\",\"fv\":\"2883\"},{\"id\":\"7177\",\"n\":\"lever seated single calf press\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\"],\"st\":[\"Sit in the machine and place the ball of one foot on the platform.\",\"Rest the other foot on the floor or the support.\",\"Press up through your toes as high as you can.\",\"Pause and squeeze your calf.\",\"Lower your heel slowly for a full stretch.\",\"Finish all reps, then switch sides.\"],\"img\":\"7177.webp\",\"gif\":\"7177.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine press working one calf at a time to build lower leg strength.\"},{\"id\":\"10763\",\"n\":\"lever seated single leg curl (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Sit on the machine and set the pad above your ankle.\",\"Hold the handles and keep your back against the seat.\",\"Curl one leg down and back.\",\"Squeeze at the bottom.\",\"Return slowly.\",\"Finish the reps, then switch legs.\"],\"img\":\"10763.webp\",\"gif\":\"10763.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg seated hamstring curl on a plate-loaded machine. It builds each hamstring separately.\"},{\"id\":\"7107\",\"n\":\"lever seated single leg press v. 2\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the machine and put one foot on the platform.\",\"Keep your back against the pad.\",\"Press the platform away until your leg is almost straight.\",\"Lower slowly until your knee bends to about 90 degrees.\",\"Finish your reps, then switch legs.\"],\"img\":\"7107.webp\",\"gif\":\"7107.mp4\",\"cat\":\"strength\",\"desc\":\"A machine press done with one leg at a time. It helps fix strength imbalances between legs.\"},{\"id\":\"1232\",\"n\":\"lever seated squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Sit in the machine with your back against the pad and shoulders under the supports.\",\"Place your feet on the platform about shoulder width apart.\",\"Push through your feet to extend your legs.\",\"Lower slowly until your knees are comfortably bent.\",\"Keep your knees in line with your toes.\"],\"img\":\"1232.webp\",\"gif\":\"1232.mp4\",\"cat\":\"strength\",\"desc\":\"A squat on a seated lever machine with a supported torso. It loads the thighs and glutes with a guided path.\"},{\"id\":\"1453\",\"n\":\"lever seated twist\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the machine, adjust the pads and place your arms or hands as designed.\",\"Sit tall with your hips facing forward.\",\"Rotate your torso to one side with a smooth, controlled turn.\",\"Pause briefly, then return to the centre without letting the weight stack slam.\",\"Repeat to the other side and keep alternating.\"],\"img\":\"1453.webp\",\"gif\":\"1453.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine twist that trains the trunk rotators and abs against a controlled load.\",\"fv\":\"2444\"},{\"id\":\"1574\",\"n\":\"lever seated wide squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Sit in the machine with your back against the pad and shoulders under the supports.\",\"Set both feet wide on the platform with toes slightly out.\",\"Lower by bending your knees until your thighs are about parallel.\",\"Keep your knees pointing in the same direction as your toes.\",\"Press through your heels to stand back up.\"],\"img\":\"1574.webp\",\"gif\":\"1574.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine squat with a wide stance. It puts extra emphasis on the glutes and inner thighs.\"},{\"id\":\"1221\",\"n\":\"lever shrug (bench press machine)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"forearms\"],\"st\":[\"Set the machine so the handles are at your sides and grip them firmly.\",\"Stand or sit tall with your arms straight.\",\"Lift your shoulders straight up toward your ears.\",\"Pause at the top for a moment.\",\"Lower your shoulders slowly without rolling them.\"],\"img\":\"1221.webp\",\"gif\":\"1221.mp4\",\"cat\":\"strength\",\"desc\":\"Shrugging with a lever press machine as the load. It builds the upper traps with a stable, guided path.\"},{\"id\":\"1034\",\"n\":\"lever side hip abduction\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Stand next to the machine and place the outer side of your leg against the pad.\",\"Hold the support for balance.\",\"Push your leg out to the side in a smooth motion.\",\"Pause briefly, then return slowly.\",\"Keep your torso upright. Finish the reps, then switch legs.\"],\"img\":\"1034.webp\",\"gif\":\"1034.mp4\",\"cat\":\"strength\",\"desc\":\"A machine move that presses the leg out to the side, working the outer hips.\",\"fv\":\"2759\"},{\"id\":\"1035\",\"n\":\"lever side hip adduction\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Stand next to the machine with the inner side of your leg against the pad.\",\"Hold the support for balance.\",\"Pull your leg across your body, squeezing your inner thigh.\",\"Return slowly to the start.\",\"Keep your hips level and avoid leaning. Finish the reps, then switch legs.\"],\"img\":\"1035.webp\",\"gif\":\"1035.mp4\",\"cat\":\"strength\",\"desc\":\"A machine move that pulls the leg across the body, working the inner thighs.\"},{\"id\":\"8990\",\"n\":\"lever side seated single arm rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit sideways on the machine with your chest against the pad.\",\"Grab the handle with the outside hand.\",\"Start with your arm in front of you and a soft bend in your elbow.\",\"Pull the handle out and back until your arm is in line with your shoulder.\",\"Return slowly without letting the weight stack touch down.\",\"Finish the reps, then switch sides.\"],\"img\":\"8990.webp\",\"gif\":\"8990.mp4\",\"cat\":\"strength\",\"desc\":\"Seated sideways on a machine, you pull one arm back in a wide arc. It isolates the rear delt.\"},{\"id\":\"9862\",\"n\":\"lever single arm preacher curl (plate loaded)\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit at the machine with your upper arm resting on the pad and grip the handle.\",\"Start with your arm almost straight.\",\"Curl the handle up toward your shoulder.\",\"Squeeze at the top.\",\"Lower slowly, then switch arms.\"],\"img\":\"9862.webp\",\"gif\":\"9862.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm curl on a plate-loaded preacher machine, isolating the biceps.\"},{\"id\":\"11309\",\"n\":\"lever single arm reverse grip lateral pulldown (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit in the machine and grab one handle with an underhand grip.\",\"Sit tall and brace your core.\",\"Pull the handle down, driving your elbow toward your side.\",\"Squeeze your lat at the bottom.\",\"Return slowly, finish your reps, then switch arms.\"],\"img\":\"11309.webp\",\"gif\":\"11309.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm pulldown on a plate-loaded machine using an underhand grip. It trains the lats and biceps one side at a time.\",\"fv\":\"11308\"},{\"id\":\"5178\",\"n\":\"lever single leg extension (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit in the machine and adjust the pad to rest on your lower shin.\",\"Place one foot under the pad and keep the other planted.\",\"Extend your knee until your leg is almost straight.\",\"Pause briefly and squeeze your quads.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"5178.webp\",\"gif\":\"5178.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine extension done one leg at a time. It isolates the quads and evens out left-right differences.\"},{\"id\":\"2148\",\"n\":\"lever single leg hip thrust\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Sit on the machine with your upper back on the pad and the belt across your hips.\",\"Plant one foot flat and lift the other leg off the floor.\",\"Drive through the planted heel and raise your hips until your torso is level.\",\"Squeeze your glute at the top, keeping your hips level.\",\"Lower with control, finish your reps, then switch legs.\"],\"img\":\"2148.webp\",\"gif\":\"2148.mp4\",\"cat\":\"strength\",\"desc\":\"A one sided machine hip thrust that hits each glute on its own and challenges hip stability.\"},{\"id\":\"9509\",\"n\":\"lever sitting toe raise\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Sit at the machine with the pads over your thighs and balls of your feet on the platform.\",\"Lower your heels for a calf stretch.\",\"Press up onto your toes as high as you can.\",\"Pause briefly at the top.\",\"Lower slowly and repeat.\"],\"img\":\"9509.webp\",\"gif\":\"9509.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine raise where your knees stay bent, which emphasises the soleus under the calf.\"},{\"id\":\"1875\",\"n\":\"lever squat (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Step under the shoulder pads and set your feet shoulder width.\",\"Release the safeties and stand tall.\",\"Sit down and back until your thighs are parallel.\",\"Drive through your heels to stand.\",\"Keep your chest up and your knees tracking over your toes.\"],\"img\":\"1875.webp\",\"gif\":\"1875.mp4\",\"cat\":\"strength\",\"desc\":\"Plate-loaded squat machine that lets you load the legs with a supported back.\",\"fv\":\"5788\"},{\"id\":\"10671\",\"n\":\"lever stack seated chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Set the seat so the handles are level with your mid chest.\",\"Sit back and pull your shoulder blades together.\",\"Press the handles forward until your arms are nearly straight.\",\"Pause without locking out.\",\"Return slowly to a gentle chest stretch.\",\"Keep your feet flat.\"],\"img\":\"10671.webp\",\"gif\":\"10671.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine press with a weight stack. It is a stable way to build the chest and triceps.\"},{\"id\":\"10669\",\"n\":\"lever stack seated incline chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Adjust the seat so the handles are at upper-chest height.\",\"Sit back with your feet flat and shoulder blades pinched.\",\"Press the handles forward and up until your arms are almost straight.\",\"Pause briefly.\",\"Return slowly to a stretch across your chest.\",\"Keep your back against the pad.\"],\"img\":\"10669.webp\",\"gif\":\"10669.mp4\",\"cat\":\"strength\",\"desc\":\"A seated press on an incline lever machine with a weight stack. It emphasises the upper chest.\"},{\"id\":\"10670\",\"n\":\"lever stack seated incline single arm chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Sit on the machine and grab one handle at upper-chest height.\",\"Brace your core to avoid twisting.\",\"Press the handle forward and up.\",\"Pause, then lower slowly.\",\"Keep your shoulder pulled back.\",\"Do all reps, then switch arms.\"],\"img\":\"10670.webp\",\"gif\":\"10670.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm incline press on a lever machine. Working one side at a time evens out strength differences.\"},{\"id\":\"10672\",\"n\":\"lever stack seated single arm chest press\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Sit with your back against the pad and grip one handle.\",\"Brace your core and keep your torso square.\",\"Press the handle forward in a smooth line.\",\"Pause, then lower slowly.\",\"Keep your shoulder down.\",\"Do the reps, then switch arms.\"],\"img\":\"10672.webp\",\"gif\":\"10672.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm seated press on a lever machine. It builds the chest on each side and trains the core to resist twisting.\"},{\"id\":\"11054\",\"n\":\"lever staggered stance hip thrust (plate loaded)\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Sit in the machine with the pad over your hips.\",\"Stagger your feet.\",\"Drive through your heels.\",\"Lift your hips fully.\",\"Squeeze your glutes.\",\"Lower slowly and switch the stance.\"],\"img\":\"11054.webp\",\"gif\":\"11054.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded machine hip thrust with a staggered stance. It targets the glutes.\"},{\"id\":\"1031\",\"n\":\"lever standing hip extension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand facing the machine and rest your hands on the support.\",\"Place the back of your working leg against the lever pad.\",\"Push the leg back and slightly up by squeezing the glute.\",\"Return slowly to the start.\",\"Keep your torso upright without arching your back. Finish the reps, then switch legs.\"],\"img\":\"1031.webp\",\"gif\":\"1031.mp4\",\"cat\":\"strength\",\"desc\":\"A standing machine move that drives one leg back to work the glutes.\",\"fv\":\"3649\"},{\"id\":\"8847\",\"n\":\"lever standing lateral raise\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand in the machine with pads against your arms.\",\"Keep your torso upright.\",\"Raise your arms out to the sides to shoulder height.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"8847.webp\",\"gif\":\"8847.mp4\",\"cat\":\"strength\",\"desc\":\"A standing machine lateral raise that isolates the side shoulders.\"},{\"id\":\"4347\",\"n\":\"lever standing leg curl\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Stand facing the machine and set the pad behind your working ankle.\",\"Hold the supports for balance.\",\"Curl your heel toward your glutes.\",\"Squeeze your hamstring at the top.\",\"Lower slowly, then switch legs.\"],\"img\":\"4347.webp\",\"gif\":\"4347.mp4\",\"cat\":\"strength\",\"desc\":\"A standing single-leg curl on a lever machine. It targets the hamstrings one side at a time.\"},{\"id\":\"1036\",\"n\":\"lever standing leg raise\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Stand facing the machine with your hands on the support.\",\"Place the front of your thigh against the pad.\",\"Raise your leg forward until the thigh is about parallel with the floor.\",\"Lower slowly to the start.\",\"Keep your torso tall. Finish the reps, then switch legs.\"],\"img\":\"1036.webp\",\"gif\":\"1036.mp4\",\"cat\":\"strength\",\"desc\":\"A standing machine raise that lifts the leg forward to train the hip flexors and the front of the thigh.\"},{\"id\":\"9398\",\"n\":\"lever standing pec fly\",\"bp\":\"chest\",\"eq\":\"leverage machine\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"biceps\"],\"st\":[\"Stand in the machine with your hands on the handles.\",\"Keep your elbows slightly bent.\",\"Bring the handles together in front of your chest.\",\"Squeeze your chest at the end.\",\"Return slowly until you feel a stretch.\",\"Keep your chest tall and your back still.\"],\"img\":\"9398.webp\",\"gif\":\"9398.mp4\",\"cat\":\"strength\",\"desc\":\"Standing at a machine, you bring your arms together in front of your chest. It isolates the chest.\"},{\"id\":\"1037\",\"n\":\"lever standing rear kick\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand facing the machine and hold the handles for support.\",\"Place the back of your working leg against the pad.\",\"Kick the leg back by squeezing the glute.\",\"Pause at the top, then return slowly.\",\"Keep your torso upright. Finish the reps, then switch legs.\"],\"img\":\"1037.webp\",\"gif\":\"1037.mp4\",\"cat\":\"strength\",\"desc\":\"A standing machine kickback that squeezes the glutes as you press the leg behind you.\",\"fv\":\"3613\"},{\"id\":\"0938\",\"n\":\"lever stepper\",\"bp\":\"cardio\",\"eq\":\"leverage machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Step onto the pedals and hold the handles lightly for balance.\",\"Push one pedal down while the other rises, keeping a smooth rhythm.\",\"Stand tall and keep your knees pointing forward.\",\"Continue at a comfortable pace for several minutes, adjusting resistance as needed.\",\"Slow down gradually before stepping off.\"],\"img\":\"0938.webp\",\"gif\":\"0938.mp4\",\"cat\":\"cardio\",\"desc\":\"Climb on a lever stepper machine at a steady pace. It raises your heart rate and works the legs and glutes.\"},{\"id\":\"11880\",\"n\":\"lever t bar close grip row (plate loaded)\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Stand on the platform with your chest supported.\",\"Grab the close-grip handle with straight arms.\",\"Pull the handle toward your torso, elbows close.\",\"Squeeze your shoulder blades together.\",\"Lower slowly to full extension.\"],\"img\":\"11880.webp\",\"gif\":\"11880.mp4\",\"cat\":\"strength\",\"desc\":\"A plate-loaded T-bar row with a close grip for thick back work.\"},{\"id\":\"5327\",\"n\":\"lever t bar romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\",\"core\"],\"st\":[\"Stand at the T-bar lever and grip the handles.\",\"Lift to stand with a slight bend in your knees.\",\"Push your hips back and lower the bar along your thighs.\",\"Stop when you feel a strong hamstring stretch.\",\"Drive your hips forward to stand.\",\"Keep your back flat all the way.\"],\"img\":\"5327.webp\",\"gif\":\"5327.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift on a T-bar lever machine. Targets the hamstrings and glutes with a guided path.\"},{\"id\":\"10065\",\"n\":\"lever torso rotation\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit in the machine and secure your torso against the pads.\",\"Grip the handles.\",\"Rotate your torso to one side while keeping your hips still.\",\"Pause at the end.\",\"Return to centre and rotate the other way.\",\"Go slowly and avoid momentum.\"],\"img\":\"10065.webp\",\"gif\":\"10065.mp4\",\"cat\":\"strength\",\"desc\":\"A machine rotation that trains the abs and obliques with controlled twisting.\"},{\"id\":\"1857\",\"n\":\"lever total abdominal crunch\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Adjust the seat and sit with your chest against the pad.\",\"Hold the handles and set your feet firmly.\",\"Curl your torso forward by contracting your abs.\",\"Pause at the bottom.\",\"Return slowly to the start without letting the weight drop.\"],\"img\":\"1857.webp\",\"gif\":\"1857.mp4\",\"cat\":\"strength\",\"desc\":\"Seated machine crunch that works the abs through a full range, loading the crunch with plates.\"},{\"id\":\"1871\",\"n\":\"lever triceps dip (plate loaded)\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit upright and grip the handles beside you.\",\"Set your elbows tight to your sides.\",\"Press down until your arms are straight.\",\"Squeeze your triceps.\",\"Return slowly to the start.\"],\"img\":\"1871.webp\",\"gif\":\"1871.mp4\",\"cat\":\"strength\",\"desc\":\"Seated plate-loaded dip machine that builds the triceps.\"},{\"id\":\"1033\",\"n\":\"lever triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\"],\"st\":[\"Sit and adjust the seat so your upper arms rest on the pad.\",\"Grab the handles with your elbows bent.\",\"Press the handles down until your arms are straight.\",\"Squeeze the triceps for a second.\",\"Return slowly without lifting your shoulders.\"],\"img\":\"1033.webp\",\"gif\":\"1033.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine extension that isolates the triceps through a stable path.\"},{\"id\":\"2198\",\"n\":\"lever triceps extension v. 3\",\"bp\":\"upper arms\",\"eq\":\"leverage machine\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Adjust the seat and sit with your upper arms on the pad.\",\"Grip the handles with your elbows bent.\",\"Press down by straightening your elbows.\",\"Squeeze your triceps at the bottom.\",\"Return slowly to the start without lifting your shoulders.\",\"Repeat for the planned reps.\"],\"img\":\"2198.webp\",\"gif\":\"2198.mp4\",\"cat\":\"strength\",\"desc\":\"A machine-based triceps extension that lets you load the back of the arm with a steady, guided path.\",\"fv\":\"2820\"},{\"id\":\"5333\",\"n\":\"lever trunk rotation\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"core\"],\"st\":[\"Sit in the machine and adjust the pads so your hips are fixed.\",\"Hold the handles or brace your arms on the pads.\",\"Rotate your torso to one side in a smooth motion.\",\"Pause briefly at the end.\",\"Return to center slowly.\",\"Complete your reps, then switch sides.\"],\"img\":\"5333.webp\",\"gif\":\"5333.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your torso against machine resistance. Trains the obliques and trunk rotation strength.\"},{\"id\":\"0608\",\"n\":\"lever twist\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit in the machine and adjust the pads so your torso is secure.\",\"Grip the handles and keep your hips facing forward.\",\"Rotate your torso to one side in a controlled way.\",\"Pause briefly at the end of the range.\",\"Return to the centre and rotate to the other side.\",\"Move slowly and avoid using momentum.\"],\"img\":\"0608.webp\",\"gif\":\"0608.mp4\",\"cat\":\"strength\",\"desc\":\"A seated machine twist that trains the abs and obliques through rotation.\"},{\"id\":\"8799\",\"n\":\"leverage single leg deadlift on hack squat machine\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"quadriceps\"],\"st\":[\"Step onto the machine platform and set your back against the pad.\",\"Place one foot on the platform and lift the other slightly.\",\"Hinge at the hip and lower with control.\",\"Drive through the standing foot to come back up.\",\"Squeeze your glute at the top.\",\"Do your reps, then switch legs.\"],\"img\":\"8799.webp\",\"gif\":\"8799.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg deadlift performed on a hack squat machine. It trains the glutes and hamstrings with extra stability.\"},{\"id\":\"9929\",\"n\":\"leverage single leg squat on hack squat machine\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Set your back against the pad and step onto the platform.\",\"Place one foot on the platform and lift the other slightly.\",\"Lower into a squat with control.\",\"Keep your knee tracking over your toes.\",\"Press back up through the working leg.\",\"Do your reps, then switch legs.\"],\"img\":\"9929.webp\",\"gif\":\"9929.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg squat on a hack squat machine. It adds stability while loading one leg at a time.\"},{\"id\":\"9848\",\"n\":\"leverage standing hip thrust\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Adjust the machine so the pad sits across your hips.\",\"Stand with your feet hip width apart.\",\"Lower your hips back slightly.\",\"Drive your hips forward and squeeze your glutes.\",\"Return slowly to the start.\",\"Keep your ribs down.\"],\"img\":\"9848.webp\",\"gif\":\"9848.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hip thrust on a lever machine. It targets the glutes with a smooth, guided path.\"},{\"id\":\"5892\",\"n\":\"lizard pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"glutes\"],\"st\":[\"Start in a low lunge with your back knee down or lifted.\",\"Walk your front foot to the outer edge of your mat.\",\"Place both hands inside the front foot.\",\"Hold for 5 slow breaths.\",\"Switch legs.\"],\"img\":\"5892.webp\",\"gif\":\"5892.mp4\",\"cat\":\"yoga\",\"desc\":\"A low lunge with both hands inside the front foot. Opens the hips and groin.\"},{\"id\":\"1484\",\"n\":\"locust yoga pose (iron man pose)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\"],\"st\":[\"Lie face down with your arms along your sides and palms facing up.\",\"Press your pelvis into the floor and engage your glutes.\",\"Lift your chest, arms and legs off the floor together.\",\"Look slightly forward and keep your neck long.\",\"Hold for 10-20 seconds, then lower slowly and rest.\"],\"img\":\"1484.webp\",\"gif\":\"1484.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga pose on your belly where you lift legs and chest at once. It strengthens the lower back and glutes.\"},{\"id\":\"4009\",\"n\":\"long arm crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie on your back with arms straight overhead.\",\"Bend your knees.\",\"Crunch up reaching forward.\",\"Lower slowly.\",\"Keep your arms by your ears.\"],\"img\":\"4009.webp\",\"gif\":\"4009.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with the arms extended overhead, which lengthens the lever and makes it harder. It focuses on the abs.\",\"fv\":\"4265\"},{\"id\":\"9701\",\"n\":\"long distance lunge (low lunge)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"hip flexors\",\"groin\"],\"st\":[\"Stand tall with hands on your hips.\",\"Take a very long step forward.\",\"Sink down until your back knee hovers above the floor.\",\"Keep your torso upright and front knee over the ankle.\",\"Push back to the start and switch legs.\"],\"img\":\"9701.webp\",\"gif\":\"9701.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge with an extra-long stride into a low position. It stretches the hips while working the glutes and thighs.\"},{\"id\":\"4906\",\"n\":\"long lever decline sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Lie on a decline bench with your feet secured.\",\"Extend your arms overhead.\",\"Curl your torso up, raising your arms with it.\",\"Sit up until your chest is over your thighs.\",\"Lower slowly back down.\",\"Keep your arms reaching forward the whole time.\"],\"img\":\"4906.webp\",\"gif\":\"4906.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A decline sit-up with the arms extended overhead. The long lever makes it a tougher core exercise.\"},{\"id\":\"4924\",\"n\":\"long lever lying back extension\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rhomboids\"],\"st\":[\"Lie face down with your arms extended overhead.\",\"Squeeze your glutes to stabilize.\",\"Lift your chest and arms off the floor.\",\"Pause briefly at the top.\",\"Lower with control.\",\"Keep your neck neutral by looking down.\"],\"img\":\"4924.webp\",\"gif\":\"4924.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone back extension with the arms stretched long overhead. It strengthens the lower back and glutes.\"},{\"id\":\"9324\",\"n\":\"long lever standing hip extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Stand tall holding a support if needed.\",\"Keep your leg straight.\",\"Lift it back behind you.\",\"Stop when your hips begin to tilt.\",\"Squeeze your glute at the top.\",\"Lower it slowly and switch legs.\"],\"img\":\"9324.webp\",\"gif\":\"9324.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Standing on one leg, you extend the straight leg behind you. It strengthens the glutes and trains balance.\"},{\"id\":\"5885\",\"n\":\"lotus pose breathing\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\"],\"st\":[\"Sit on the floor with your legs crossed and each foot resting on the opposite thigh if comfortable.\",\"Rest your hands on your knees and lengthen your spine.\",\"Inhale slowly through your nose and fill your belly and chest.\",\"Exhale slowly and fully.\",\"Keep your shoulders relaxed and breathe steadily for 1-2 minutes.\"],\"img\":\"5885.webp\",\"gif\":\"5885.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated cross-legged breathing practice that calms the mind and lengthens the spine while the hips stay open.\"},{\"id\":\"0956\",\"n\":\"lotus yoga pose padmasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"ankles\",\"core\"],\"st\":[\"Sit tall with legs stretched out in front of you.\",\"Bend one knee and place that foot high on the opposite thigh.\",\"Bend the other knee and place that foot on top, if your hips allow it.\",\"Rest your hands on your knees and lengthen your spine.\",\"Breathe slowly for 30-60 seconds, then switch which leg goes on top.\"],\"img\":\"0956.webp\",\"gif\":\"0956.mp4\",\"cat\":\"yoga\",\"desc\":\"Sit cross-legged with each foot resting on the opposite thigh. It opens the hips and encourages a calm, upright posture.\"},{\"id\":\"0610\",\"n\":\"low jacks\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"adductors\"],\"st\":[\"Start in a half squat with hands in front of your chest.\",\"Jump your feet out wide, staying low.\",\"Jump them back together and keep your knees bent.\",\"Keep your chest up and weight on your heels.\",\"Stay in the squat throughout.\",\"Keep a steady pace for 30-60 seconds.\"],\"img\":\"0610.webp\",\"gif\":\"0610.mp4\",\"cat\":\"cardio\",\"desc\":\"Jumping jacks performed from a squat position. They raise your heart rate and burn the legs.\"},{\"id\":\"6007\",\"n\":\"low lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"groin\"],\"st\":[\"Step one foot forward into a lunge and lower your back knee.\",\"Keep your front knee over your ankle.\",\"Push your hips forward and lift your chest.\",\"Reach your arms overhead if you like.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"6007.webp\",\"gif\":\"6007.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep lunge stretch that opens the hip flexors and quads.\",\"fv\":\"5893\"},{\"id\":\"6008\",\"n\":\"low lunge (left)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"groin\"],\"st\":[\"Step your right foot forward and lower your left knee to the floor.\",\"Keep your front knee over your ankle.\",\"Push your hips forward and lift your chest.\",\"Reach your arms overhead if you like.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"6008.webp\",\"gif\":\"6008.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep lunge stretch on the left side that opens the hip flexors and quads.\",\"fv\":\"6009\"},{\"id\":\"6618\",\"n\":\"low lunge yoga pose anjaneyasana i\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"groin\"],\"st\":[\"Start in a lunge with the front knee over the ankle.\",\"Lower the back knee to the floor and untuck the toes.\",\"Sink your hips forward and down.\",\"Raise both arms overhead and lift your chest.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Step back and switch legs.\"],\"img\":\"6618.webp\",\"gif\":\"6618.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga low lunge with the back knee down and arms overhead. It opens the hips and stretches the front of the thigh.\"},{\"id\":\"2105\",\"n\":\"lower trunk flexor stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie face down with your hands under your shoulders.\",\"Press up through your hands and let your hips sink toward the floor until the lower abdomen stretches.\",\"Keep your hips on the floor and your shoulders relaxed.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2105.webp\",\"gif\":\"2105.mp4\",\"cat\":\"stretching\",\"desc\":\"A backbend style stretch that lengthens the front of the abdomen and hips.\"},{\"id\":\"0612\",\"n\":\"lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Take a big step forward with one leg.\",\"Lower your hips until both knees are bent about 90 degrees.\",\"Keep your torso upright and front knee over your ankle.\",\"Push through the front heel to return to standing.\",\"Repeat and switch legs.\"],\"img\":\"0612.webp\",\"gif\":\"0612.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A classic step forward and drop for the legs. It builds the quads and glutes and improves balance.\"},{\"id\":\"0611\",\"n\":\"lunge push up\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"quadriceps\",\"glutes\",\"shoulders\"],\"st\":[\"Stand tall with feet together.\",\"Step back into a lunge and lower your back knee toward the floor.\",\"Place your hands on the floor and step into a plank.\",\"Lower into a push-up and press back up.\",\"Step back into the lunge and stand up.\",\"Alternate the lunging leg each rep.\"],\"img\":\"0611.webp\",\"gif\":\"0611.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge flowing into a push-up. It combines leg and upper body work for a full-body challenge.\"},{\"id\":\"4930\",\"n\":\"lunge stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Step one foot forward into a lunge, back knee down on a mat.\",\"Keep your torso upright.\",\"Push your hips gently forward.\",\"Feel the stretch in the front of the back hip and thigh.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"4930.webp\",\"gif\":\"4930.mp4\",\"cat\":\"stretching\",\"desc\":\"A low lunge held to stretch the front of the hip and thigh. It opens up the hips.\"},{\"id\":\"4959\",\"n\":\"lunge thighs (form check)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Stand tall with feet hip width.\",\"Step forward into a lunge.\",\"Keep your front knee over your ankle.\",\"Keep your torso upright.\",\"Push back up to the start.\",\"Compare with the incorrect position to correct your form.\"],\"img\":\"4959.webp\",\"gif\":\"4959.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A form check drawing for the lunge, showing correct and incorrect positions. It reminds you how to train the thighs safely.\"},{\"id\":\"3581\",\"n\":\"lunge with leg lift\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Stand tall and step one leg forward into a lunge.\",\"Lower until both knees reach about 90 degrees.\",\"Press up and lift the rear leg behind or beside you.\",\"Hold briefly with your core tight.\",\"Lower and repeat, then switch sides.\"],\"img\":\"3581.webp\",\"gif\":\"3581.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge followed by lifting the back leg, working the glutes and balance.\",\"fv\":\"3807\"},{\"id\":\"1054\",\"n\":\"lunging straight leg calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"hamstrings\",\"ankles\"],\"st\":[\"Step into a lunge with hands on a wall or knee.\",\"Keep the back leg straight with heel down.\",\"Lean forward until you feel a stretch.\",\"Keep your foot pointing forward.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1054.webp\",\"gif\":\"1054.mp4\",\"cat\":\"stretching\",\"desc\":\"Lunge forward with the back leg straight to stretch the calf. It improves ankle mobility.\"},{\"id\":\"1168\",\"n\":\"lying (prone) abdominal stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie face down with your hands under your shoulders.\",\"Press up slowly, straightening your arms as far as is comfortable.\",\"Keep your hips on the floor and relax your glutes.\",\"Look forward and feel the stretch along your belly.\",\"Hold for 20-30 seconds, then lower down.\"],\"img\":\"1168.webp\",\"gif\":\"1168.mp4\",\"cat\":\"stretching\",\"desc\":\"A face-down stretch that lengthens the abdominals, similar to a cobra position.\",\"fv\":\"1055\"},{\"id\":\"4459\",\"n\":\"lying ab press\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with arms and legs extended.\",\"Brace your abs and press your lower back to the floor.\",\"Lift your shoulders and bring your knees toward your chest.\",\"Reach your hands to your knees and squeeze.\",\"Return slowly without letting your feet touch down.\",\"Repeat for reps.\"],\"img\":\"4459.webp\",\"gif\":\"4459.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying core move where you press your arms and legs together to crunch the abs. Targets the front of the trunk.\",\"fv\":\"4460\"},{\"id\":\"9024\",\"n\":\"lying abdominal scissors crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your hands behind your head.\",\"Lift your shoulders and your legs slightly off the floor.\",\"Scissor your legs up and down in alternating motion.\",\"Crunch your ribs toward your hips.\",\"Keep your lower back pressed down.\",\"Continue for a set count of reps.\"],\"img\":\"9024.webp\",\"gif\":\"9024.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you crunch up while scissoring your legs. It works the upper and lower abs together.\"},{\"id\":\"11047\",\"n\":\"lying abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Lie on your side with your legs straight and stacked.\",\"Rest your head on your lower arm and keep your hips stacked.\",\"Lift your top leg up and slightly back without rolling your torso.\",\"Pause at the top, then lower with control.\",\"Finish your reps, then roll over and do the other side.\"],\"img\":\"11047.webp\",\"gif\":\"11047.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying leg raise that targets the outer hip. It is a simple way to strengthen the muscles that keep your pelvis steady.\"},{\"id\":\"1882\",\"n\":\"lying abductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie on your back with your legs straight.\",\"Bring one knee up and across your body.\",\"Use the opposite hand to ease it toward the floor.\",\"Keep your shoulders flat on the ground.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1882.webp\",\"gif\":\"1882.mp4\",\"cat\":\"stretching\",\"desc\":\"Floor stretch that pulls one leg across the body to open the outer hip.\"},{\"id\":\"4883\",\"n\":\"lying air cycles\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with your hands by your head or at your sides.\",\"Lift your shoulders and legs slightly off the floor.\",\"Pedal your legs as if riding a bicycle.\",\"Keep your lower back pressed into the floor.\",\"Breathe steadily and keep a smooth rhythm.\",\"Lower your legs and rest when your form slips.\"],\"img\":\"4883.webp\",\"gif\":\"4883.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A floor cycling move that keeps the core working while the legs pedal in the air. It builds abdominal endurance.\",\"fv\":\"4925\"},{\"id\":\"6024\",\"n\":\"lying alternate frog kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down with your arms under your forehead.\",\"Bend one knee to 90 degrees with the sole toward the ceiling.\",\"Lift that thigh off the floor by squeezing the glute.\",\"Lower and switch legs.\",\"Keep your hips on the floor.\"],\"img\":\"6024.webp\",\"gif\":\"6024.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone move where you alternate kicking each bent leg up, to work the glutes.\",\"fv\":\"6022\"},{\"id\":\"0614\",\"n\":\"lying alternate hip extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down with arms by your sides or under your forehead.\",\"Keep your legs straight and your hips pressed down.\",\"Lift one leg off the floor while squeezing your glute.\",\"Lower it with control.\",\"Lift the other leg and alternate.\",\"Avoid arching your lower back.\"],\"img\":\"0614.webp\",\"gif\":\"0614.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you lift one leg at a time. It strengthens the glutes and the muscles along your lower back.\"},{\"id\":\"5050\",\"n\":\"lying alternate toe touch floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with both legs raised toward the ceiling.\",\"Extend your arms up.\",\"Crunch up and reach one hand toward the opposite foot.\",\"Lower and reach with the other hand.\",\"Keep your legs steady.\"],\"img\":\"5050.webp\",\"gif\":\"5050.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back with legs raised, you reach up to touch your toes alternately. It works the abs and obliques.\",\"fv\":\"6091\"},{\"id\":\"3826\",\"n\":\"lying around the world\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rear deltoids\",\"chest\",\"rotator cuff\"],\"st\":[\"Lie on your back with your arms by your sides.\",\"Raise your arms to the ceiling.\",\"Sweep them in a wide arc overhead toward the floor.\",\"Continue the arc back down to your sides.\",\"Move slowly and keep your ribs down.\"],\"img\":\"3826.webp\",\"gif\":\"3826.mp4\",\"cat\":\"mobility\",\"desc\":\"Lying on your back, you sweep your arms in a big arc overhead. It opens up your shoulders and chest.\",\"fv\":\"4943\"},{\"id\":\"3228\",\"n\":\"lying back extension\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\",\"trapezius\"],\"st\":[\"Lie face down with your hands beside your head.\",\"Keep your legs straight and your feet on the floor.\",\"Lift your chest using your lower back.\",\"Pause briefly at the top.\",\"Lower slowly.\",\"Keep your neck in line with your spine.\"],\"img\":\"3228.webp\",\"gif\":\"3228.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A face-down lift of your chest off the floor. It strengthens the lower back muscles.\",\"fv\":\"3208\"},{\"id\":\"3229\",\"n\":\"lying back extension with press\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"upper back\",\"shoulders\"],\"st\":[\"Lie face down with your hands near your shoulders.\",\"Lift your chest off the floor.\",\"Press your arms forward in front of you.\",\"Pull them back to your shoulders.\",\"Lower your chest slowly.\",\"Keep your neck long throughout.\"],\"img\":\"3229.webp\",\"gif\":\"3229.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying back extension where you also press your arms forward at the top. It adds shoulder work to a back extension.\",\"fv\":\"3209\"},{\"id\":\"4932\",\"n\":\"lying bent knee figure 8\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"adductors\"],\"st\":[\"Lie on your back with knees bent.\",\"Lift one knee above the hip.\",\"Trace a slow figure eight in the air with your knee.\",\"Keep the movement smooth and controlled.\",\"Keep your pelvis steady on the floor.\",\"Switch legs after a set.\"],\"img\":\"4932.webp\",\"gif\":\"4932.mp4\",\"cat\":\"mobility\",\"desc\":\"A lying hip mobility move where you draw a figure eight with the bent knee. It loosens the hips.\"},{\"id\":\"10540\",\"n\":\"lying bent knee tibialis press\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Slide one foot under the other for light resistance.\",\"Lift the toes of the lower foot toward your shin.\",\"Pause at the top, then lower slowly.\",\"Finish your reps, then switch feet.\"],\"img\":\"10540.webp\",\"gif\":\"10540.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back with knees bent, you press your foot toward your shin. It targets the front of the lower leg.\"},{\"id\":\"5472\",\"n\":\"lying bent legs raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with hands under your hips or by your sides.\",\"Bend your knees and lift your feet off the floor.\",\"Curl your hips up slightly as you bring your knees toward your chest.\",\"Lower your legs slowly without letting your lower back arch.\",\"Repeat for the target reps.\"],\"img\":\"5472.webp\",\"gif\":\"5472.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Floor ab exercise where you lift bent knees toward your chest, working the lower abs with less lever length than straight legs.\"},{\"id\":\"3558\",\"n\":\"lying biceps curl with towel\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie on your back and hold a towel in both hands, arms extended.\",\"Pull the towel taut and curl your hands toward your shoulders.\",\"Keep your upper arms still and your elbows close to your sides.\",\"Squeeze at the top, then lower slowly to the start.\",\"Repeat for the planned reps.\"],\"img\":\"3558.webp\",\"gif\":\"3558.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on your back and curl a towel held in both hands toward your chest, using your own resistance to work the biceps.\"},{\"id\":\"5250\",\"n\":\"lying bicycle crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your hands behind your head.\",\"Lift your shoulders and bring your knees up.\",\"Extend one leg while turning your opposite elbow toward the other knee.\",\"Switch sides in a smooth pedalling motion.\",\"Keep your lower back pressed down.\"],\"img\":\"5250.webp\",\"gif\":\"5250.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying alternating crunch that pedals the legs while the elbow meets the opposite knee. It works the abs and obliques.\"},{\"id\":\"4929\",\"n\":\"lying calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Lie on your back and lift one leg toward the ceiling.\",\"Hold behind the thigh or use a strap on your foot.\",\"Pull your toes toward your shin.\",\"Keep the knee as straight as you comfortably can.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"4929.webp\",\"gif\":\"4929.mp4\",\"cat\":\"stretching\",\"desc\":\"A calf stretch done lying on your back. It stretches the lower leg with little effort from the rest of your body.\"},{\"id\":\"5062\",\"n\":\"lying chin tucks\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie on your back with your head resting on the floor and knees bent.\",\"Gently draw your chin toward your throat.\",\"Press the back of your head lightly into the floor.\",\"Hold for 3-5 seconds.\",\"Release and repeat.\"],\"img\":\"5062.webp\",\"gif\":\"5062.mp4\",\"cat\":\"rehab\",\"desc\":\"A small nodding motion lying on your back. It trains the deep neck muscles and improves head posture.\"},{\"id\":\"4880\",\"n\":\"lying criss cross legs\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with legs raised slightly off the floor.\",\"Press your lower back down.\",\"Cross one leg over the other.\",\"Switch and cross the other way.\",\"Continue smoothly.\"],\"img\":\"4880.webp\",\"gif\":\"4880.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you cross your legs back and forth. It works the lower abs.\"},{\"id\":\"1936\",\"n\":\"lying cross over knee pull down stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent.\",\"Cross one ankle over the opposite knee.\",\"Use your hand to guide the crossed knee gently down and across your body.\",\"Keep your shoulders on the floor.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1936.webp\",\"gif\":\"1936.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back and guiding a crossed knee down across the body to stretch the outer hip and glutes.\"},{\"id\":\"1935\",\"n\":\"lying cross over knee pull up stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent.\",\"Cross one ankle over the opposite knee.\",\"Hold the knee of the lower leg or behind the thigh and pull it up toward your chest.\",\"Keep your head and shoulders relaxed on the floor.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1935.webp\",\"gif\":\"1935.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back and drawing a crossed knee up toward the opposite shoulder to stretch the glutes and hips.\"},{\"id\":\"0615\",\"n\":\"lying crossover stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"obliques\"],\"st\":[\"Lie on your back with arms out to the sides.\",\"Bend one knee and bring it across your body.\",\"Let it lower toward the floor on the opposite side.\",\"Keep both shoulders flat on the floor.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"0615.webp\",\"gif\":\"0615.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back, you cross one leg over the other. It stretches the outer hip and lower back.\"},{\"id\":\"6005\",\"n\":\"lying crunch (straight legs)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with your legs straight.\",\"Place your hands behind your head or across your chest.\",\"Curl your shoulders off the floor.\",\"Pause and squeeze your abs.\",\"Lower slowly without pulling on your neck.\"],\"img\":\"6005.webp\",\"gif\":\"6005.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with straight legs on the floor that trains the upper abs.\",\"fv\":\"6004\"},{\"id\":\"2851\",\"n\":\"lying double leg kick\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\"],\"st\":[\"Lie face down with your hands clasped behind your back.\",\"Kick both heels toward your glutes.\",\"Lift your chest and extend your arms back.\",\"Lower down.\",\"Repeat smoothly.\"],\"img\":\"2851.webp\",\"gif\":\"2851.mp4\",\"cat\":\"pilates\",\"desc\":\"A face-down Pilates move that opens the chest and strengthens the back.\"},{\"id\":\"3752\",\"n\":\"lying double legs biceps curl with towel\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"hamstrings\"],\"st\":[\"Lie on your back and wrap a towel around both feet, holding the ends.\",\"Lift your legs slightly and press them against the towel.\",\"Curl the towel toward your chest while your legs resist.\",\"Lower slowly.\",\"Keep your elbows at your sides.\"],\"img\":\"3752.webp\",\"gif\":\"3752.mp4\",\"cat\":\"strength\",\"desc\":\"A lying curl where you pull a towel wrapped around your feet with your hands, so your legs provide resistance.\"},{\"id\":\"3830\",\"n\":\"lying double legs hammer curl with towel\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Lie on your back and loop a towel around both feet.\",\"Hold the ends with palms facing each other.\",\"Pull the towel toward your chest while pushing your feet against it.\",\"Pause, then slowly extend your arms.\",\"Keep your elbows near your sides.\"],\"img\":\"3830.webp\",\"gif\":\"3830.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you loop a towel around your feet and curl it with a hammer grip. It trains your biceps.\"},{\"id\":\"4886\",\"n\":\"lying flat hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with arms by your sides or under your hips.\",\"Raise your legs so they point to the ceiling.\",\"Tighten your abs and lift your hips a few centimetres.\",\"Hold for a moment at the top.\",\"Lower your hips slowly to the floor.\",\"Keep the motion small and controlled.\"],\"img\":\"4886.webp\",\"gif\":\"4886.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip raise done lying flat on the floor. It works the lower abs by lifting your hips with a controlled curl.\"},{\"id\":\"9451\",\"n\":\"lying floor 6 inch hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your legs straight and arms by your sides.\",\"Press your lower back into the floor and brace your abs.\",\"Lift your heels and shoulders about 15 cm off the floor.\",\"Keep your lower back flat and breathe steadily.\",\"Hold for 20-30 seconds, then lower and rest.\"],\"img\":\"9451.webp\",\"gif\":\"9451.mp4\",\"cat\":\"isometric\",\"desc\":\"A floor hold where you lie on your back with your legs and shoulders lifted about six inches. It trains deep abdominal tension and endurance.\",\"hd\":1},{\"id\":\"5079\",\"n\":\"lying floor fly\",\"bp\":\"chest\",\"eq\":\"dumbbell\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie on your back holding dumbbells above your chest, palms facing in.\",\"Keep a slight bend in your elbows.\",\"Open your arms out until your upper arms touch the floor.\",\"Squeeze your chest to bring the weights back together.\",\"Keep your wrists straight and the motion slow.\"],\"img\":\"5079.webp\",\"gif\":\"5079.mp4\",\"cat\":\"strength\",\"desc\":\"Lie on the floor and sweep dumbbells out and together in an arc. The floor limits the range, which is gentle on the shoulders.\"},{\"id\":\"9321\",\"n\":\"lying floor horizontal flutter kick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with your legs straight and hands under your hips.\",\"Lift your feet a few inches off the floor.\",\"Kick your legs up and down in small alternating motions.\",\"Keep your lower back pressed down.\",\"Breathe steadily.\",\"Continue for 20 to 40 seconds.\"],\"img\":\"9321.webp\",\"gif\":\"9321.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small alternating kicks while lying down. It trains the lower abs and hip flexors.\"},{\"id\":\"3827\",\"n\":\"lying floor hyperextension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down with your arms extended or by your sides.\",\"Squeeze your glutes and lift your chest and legs slightly.\",\"Pause briefly at the top.\",\"Lower back down with control.\",\"Keep your neck neutral.\"],\"img\":\"3827.webp\",\"gif\":\"3827.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you lift your chest and legs off the floor. It strengthens your lower back and glutes.\"},{\"id\":\"3829\",\"n\":\"lying floor hyperextension with towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\",\"upper back\"],\"st\":[\"Lie face down holding a taut towel in front of you.\",\"Lift your chest and legs off the floor.\",\"Keep pulling the towel apart.\",\"Pause at the top.\",\"Lower back down with control.\"],\"img\":\"3829.webp\",\"gif\":\"3829.mp4\",\"cat\":\"strength\",\"desc\":\"A lying back extension while holding a towel taut. It builds your lower back and glutes with extra upper back work.\"},{\"id\":\"9318\",\"n\":\"lying floor negative dragon flag\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"lats\"],\"st\":[\"Lie on a mat and hold something fixed behind your head.\",\"Raise your body into a straight line on your upper back.\",\"Brace your core.\",\"Lower your body slowly keeping it straight.\",\"Stop just above the floor.\",\"Bring your legs back up and reset.\"],\"img\":\"9318.webp\",\"gif\":\"9318.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on the floor, you lower your straight body slowly for the dragon flag. A tough ab and core strengthener.\"},{\"id\":\"9319\",\"n\":\"lying floor negative half dragon flag\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"lats\"],\"st\":[\"Lie on a mat and hold something fixed behind your head.\",\"Lift your hips and tuck your knees.\",\"Brace your core.\",\"Lower your body slowly with bent knees.\",\"Stop just above the floor.\",\"Reset and repeat.\"],\"img\":\"9319.webp\",\"gif\":\"9319.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A gentler dragon flag lowering with your knees bent. It builds the strength needed for the full move.\"},{\"id\":\"3495\",\"n\":\"lying floor row with bent knee\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a secure anchor, such as a towel around a sturdy post, with arms straight.\",\"Pull your body toward your hands by driving the elbows back.\",\"Squeeze your shoulder blades together.\",\"Lower slowly to straight arms.\",\"Keep your hips on or near the floor.\"],\"img\":\"3495.webp\",\"gif\":\"3495.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A row done lying on the floor, pulling against an anchored handle or towel, with knees bent. It works the back and biceps with no equipment.\"},{\"id\":\"9322\",\"n\":\"lying floor single leg negative dragon flag\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"lats\"],\"st\":[\"Lie on a mat and hold something fixed behind your head.\",\"Raise your body into a straight line with one leg tucked.\",\"Extend the other leg straight.\",\"Lower slowly while keeping your hips level.\",\"Stop just above the floor.\",\"Reset and switch legs.\"],\"img\":\"9322.webp\",\"gif\":\"9322.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dragon flag lowering with one leg extended and one tucked. It's a step between the half and full versions.\"},{\"id\":\"7538\",\"n\":\"lying floor slide\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent and arms in a goalpost position.\",\"Keep your back and wrists on the floor.\",\"Slide your arms up overhead.\",\"Return slowly to the start.\",\"Move within your comfortable range.\"],\"img\":\"7538.webp\",\"gif\":\"7538.mp4\",\"cat\":\"mobility\",\"desc\":\"Floor slide that improves shoulder mobility and activates the upper back.\"},{\"id\":\"10550\",\"n\":\"lying floor svend press\",\"bp\":\"chest\",\"eq\":\"weight plate\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on your back holding a plate between your palms at your chest.\",\"Squeeze the plate firmly.\",\"Press it straight up until your arms are extended.\",\"Keep squeezing as you lower it back to your chest.\",\"Repeat with steady control.\"],\"img\":\"10550.webp\",\"gif\":\"10550.mp4\",\"cat\":\"strength\",\"desc\":\"Press a plate out from your chest while lying on the floor, squeezing it with both hands. It targets the inner chest.\"},{\"id\":\"6025\",\"n\":\"lying frog kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down, knees bent and heels together.\",\"Let your knees fall slightly out.\",\"Lift both thighs off the floor by squeezing your glutes.\",\"Pause at the top.\",\"Lower with control and repeat.\"],\"img\":\"6025.webp\",\"gif\":\"6025.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone move where both knees bend outward like a frog and kick up, to work the glutes.\",\"fv\":\"6023\"},{\"id\":\"3263\",\"n\":\"lying full leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with legs straight and hands under your hips or by your sides.\",\"Press your lower back gently into the floor.\",\"Lift both legs together until they point at the ceiling.\",\"Lower them slowly, stopping just above the floor.\",\"Keep your legs straight and do not let your back arch.\"],\"img\":\"3263.webp\",\"gif\":\"3263.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise both straight legs from the floor to work the lower abs and hip flexors.\"},{\"id\":\"3412\",\"n\":\"lying glute squeeze\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat on the floor.\",\"Squeeze your glutes and lift your hips slightly.\",\"Hold the squeeze for 2 seconds.\",\"Lower your hips without relaxing completely.\",\"Repeat for 12-15 reps.\"],\"img\":\"3412.webp\",\"gif\":\"3412.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Squeeze your glutes while lying down to activate them before heavier lower body work.\"},{\"id\":\"1056\",\"n\":\"lying glute stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie on your back.\",\"Cross one ankle over the opposite knee.\",\"Pull the bottom leg toward your chest.\",\"Keep your head and shoulders relaxed.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1056.webp\",\"gif\":\"1056.mp4\",\"cat\":\"stretching\",\"desc\":\"Pull a knee toward your chest while lying down. It releases the glutes.\"},{\"id\":\"1577\",\"n\":\"lying hip flexor\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\"],\"st\":[\"Lie on your back near the edge of a bench or bed.\",\"Hug one knee to your chest.\",\"Let the other leg hang off the edge with the knee relaxed.\",\"Keep your lower back pressed down and breathe slowly.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1577.webp\",\"gif\":\"1577.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying stretch that opens the front of the hip. Handy after long periods of sitting.\"},{\"id\":\"0616\",\"n\":\"lying hip flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie on your back near the edge of a bench or bed.\",\"Pull one knee toward your chest and hold it.\",\"Let the other leg hang down relaxed over the edge.\",\"Keep your lower back flat.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"0616.webp\",\"gif\":\"0616.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying near the edge of a surface, you let one leg hang to stretch the front of the hip. It eases tightness from sitting.\"},{\"id\":\"0617\",\"n\":\"lying hip leg raise (on floor)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Lie on your side with your legs straight and stacked.\",\"Rest your head on your arm and keep your core tight.\",\"Raise your top leg toward the ceiling.\",\"Keep your toes pointing forward.\",\"Lower slowly without touching the other leg.\",\"Finish all reps, then switch sides.\"],\"img\":\"0617.webp\",\"gif\":\"0617.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying leg lift done on the floor. It works the outer hip and glutes.\"},{\"id\":\"1065\",\"n\":\"lying hip lift (on stability ball)\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your heels resting on the stability ball.\",\"Press your arms into the floor for support.\",\"Lift your hips until your body forms a straight line.\",\"Squeeze your glutes at the top.\",\"Lower your hips under control.\",\"Keep the ball steady throughout.\"],\"img\":\"1065.webp\",\"gif\":\"1065.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with your feet or upper back on a stability ball. The unstable surface adds a balance challenge.\",\"fv\":\"0618\"},{\"id\":\"0619\",\"n\":\"lying hip straight leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Lie on your back with both legs straight.\",\"Brace your abs and press your lower back down.\",\"Lift one straight leg to about hip height.\",\"Lower it slowly toward the floor.\",\"Keep the other leg flat.\",\"Finish your reps, then switch legs.\"],\"img\":\"0619.webp\",\"gif\":\"0619.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you raise a straight leg toward the ceiling. It trains the hip muscles and leg control.\"},{\"id\":\"6019\",\"n\":\"lying hyperextension hold\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie face down with your arms extended.\",\"Lift your chest, arms and legs a few inches.\",\"Keep your neck neutral.\",\"Squeeze your glutes and hold for 15-30 seconds.\",\"Lower slowly.\"],\"img\":\"6019.webp\",\"gif\":\"6019.mp4\",\"cat\":\"isometric\",\"desc\":\"A prone hold that lifts the chest and legs, building lower back endurance.\",\"hd\":1,\"fv\":\"6018\"},{\"id\":\"4885\",\"n\":\"lying incline hip raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie back on an incline surface and hold the top with your hands.\",\"Bring your legs up with knees slightly bent.\",\"Curl your pelvis and lift your hips off the surface.\",\"Pause with your feet pointing toward the ceiling.\",\"Lower your hips slowly.\",\"Avoid swinging your legs.\"],\"img\":\"4885.webp\",\"gif\":\"4885.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip raise done lying on an incline. It trains the lower abs by curling your pelvis toward your ribs.\"},{\"id\":\"8194\",\"n\":\"lying knee raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your legs extended.\",\"Press your lower back into the floor.\",\"Draw your knees up toward your chest.\",\"Pause briefly.\",\"Lower slowly without arching.\"],\"img\":\"8194.webp\",\"gif\":\"8194.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From lying on your back, you draw your knees toward your chest. It works the lower abs.\"},{\"id\":\"2116\",\"n\":\"lying knee roll over stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"glutes\"],\"st\":[\"Lie on your back with arms out to the sides and knees bent.\",\"Keep your shoulders flat on the floor.\",\"Slowly lower both knees to one side.\",\"Turn your head the other way if it feels comfortable.\",\"Hold for 20-30 seconds.\",\"Bring the knees back to centre and roll to the other side.\"],\"img\":\"2116.webp\",\"gif\":\"2116.mp4\",\"cat\":\"stretching\",\"desc\":\"Rolls the knees to one side while lying on your back to twist the lower spine and loosen the hips and sides.\"},{\"id\":\"1810\",\"n\":\"lying knee to chest stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\",\"hamstrings\"],\"st\":[\"Lie on your back with both legs extended.\",\"Pull one knee toward your chest with both hands while the other leg stays flat.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1810.webp\",\"gif\":\"1810.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulling one knee toward your chest while lying down stretches your glutes and lower back. A classic, easy hip release.\"},{\"id\":\"4957\",\"n\":\"lying lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Lie on a bench under a high pulley.\",\"Grab the bar overhand.\",\"Pull the bar down toward your chest.\",\"Squeeze your lats.\",\"Return slowly with straight arms.\",\"Keep your core braced.\"],\"img\":\"4957.webp\",\"gif\":\"4957.mp4\",\"cat\":\"strength\",\"desc\":\"A lat pulldown done lying down. It trains the lats with a different angle.\",\"nd\":[\"bench\"]},{\"id\":\"1905\",\"n\":\"lying leaning against the wall stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"hamstrings\"],\"st\":[\"Lie on your back with your hips close to a wall.\",\"Rest your legs straight up the wall.\",\"Let your legs fall slowly out to the sides.\",\"Relax and let gravity do the work.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Bring your legs together to finish.\"],\"img\":\"1905.webp\",\"gif\":\"1905.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie with your legs resting on a wall and let them fall open to stretch the inner thighs.\"},{\"id\":\"4994\",\"n\":\"lying leg cross\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"adductors\",\"hip flexors\"],\"st\":[\"Lie on your back with your hands by your sides.\",\"Lift both legs a little off the floor with your lower back pressed down.\",\"Open them wide, then cross one leg over the other.\",\"Open again and cross with the other leg on top.\",\"Keep your core tight throughout.\"],\"img\":\"4994.webp\",\"gif\":\"4994.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you cross straight legs over each other. It works the lower abs and inner thighs.\"},{\"id\":\"4987\",\"n\":\"lying leg figure eight\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\",\"adductors\"],\"st\":[\"Lie on your back with your hands under your hips and legs lifted.\",\"Press your lower back into the floor.\",\"Trace a figure eight in the air with your feet, slowly and in control.\",\"Keep your legs close together.\",\"Change direction halfway through the set.\"],\"img\":\"4987.webp\",\"gif\":\"4987.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you trace a figure eight in the air with your legs. It keeps the lower abs and hip flexors under tension.\"},{\"id\":\"1884\",\"n\":\"lying leg hang abductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your back on a bench.\",\"Cross one leg over your body and let it hang off the side.\",\"Keep your shoulders flat.\",\"Let gravity lower the leg slowly.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1884.webp\",\"gif\":\"1884.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie on a bench and let one leg hang across for a gravity-assisted hip stretch.\",\"nd\":[\"bench\"]},{\"id\":\"3393\",\"n\":\"lying leg hip raise on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with arms by your sides or holding something behind your head.\",\"Raise your legs to vertical.\",\"Lift your hips off the floor, pushing your feet toward the ceiling.\",\"Lower your hips slowly.\",\"Lower your legs without arching your back.\",\"Keep movements smooth, not swinging.\"],\"img\":\"3393.webp\",\"gif\":\"3393.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor leg raise that lifts the hips off the ground for a stronger lower-abs contraction.\"},{\"id\":\"4018\",\"n\":\"lying leg hip raise on floor v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your legs raised.\",\"Press your arms into the floor.\",\"Lift your hips off the floor.\",\"Lower with control.\",\"Avoid swinging.\"],\"img\":\"4018.webp\",\"gif\":\"4018.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lift your hips off the floor with your legs raised. It focuses on the lower abs.\"},{\"id\":\"4156\",\"n\":\"lying leg hip side raise on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"adductors\"],\"st\":[\"Lie on your side with legs stacked and straight.\",\"Rest your head on your lower arm and brace your core.\",\"Lift both legs together a short way off the floor.\",\"Pause at the top, squeezing your side.\",\"Lower slowly without touching the floor.\",\"Complete reps, then switch sides.\"],\"img\":\"4156.webp\",\"gif\":\"4156.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side lying raise where you lift both legs together toward the ceiling. It works the obliques and the sides of your trunk.\"},{\"id\":\"2852\",\"n\":\"lying leg lift side\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Lie on your side with legs stacked.\",\"Support your head with your arm.\",\"Lift your top leg.\",\"Lower slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"2852.webp\",\"gif\":\"2852.mp4\",\"cat\":\"pilates\",\"desc\":\"A side-lying leg lift that works the outer hip.\"},{\"id\":\"1163\",\"n\":\"lying leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with legs straight and hands under your hips.\",\"Press your lower back gently into the floor.\",\"Lift your legs together until they point at the ceiling.\",\"Lower them slowly, stopping just above the floor.\",\"Keep your back from arching throughout.\"],\"img\":\"1163.webp\",\"gif\":\"1163.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor exercise that raises straight legs to hit the lower abs.\",\"fv\":\"3262\"},{\"id\":\"4419\",\"n\":\"lying leg raise (modified)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your hands by your sides.\",\"Bend your knees slightly and press your lower back into the floor.\",\"Raise your legs until your hips flex to about 90 degrees.\",\"Lower them slowly without arching your back.\",\"Stop short of the floor and repeat.\"],\"img\":\"4419.webp\",\"gif\":\"4419.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An easier lying leg raise that trains the lower abs. Bent knees reduce the strain on the lower back.\"},{\"id\":\"1245\",\"n\":\"lying leg raise and hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your legs straight and your hands by your sides.\",\"Press your lower back into the floor.\",\"Raise your legs until they are vertical.\",\"Lower them to just above the floor and hold for a couple of seconds.\",\"Repeat without letting your back arch.\"],\"img\":\"1245.webp\",\"gif\":\"1245.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raising your legs from the floor and holding them up. It targets the lower abs.\",\"fv\":\"7118\"},{\"id\":\"3268\",\"n\":\"lying leg raise to side\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with arms out to the sides and legs raised straight up.\",\"Keep your shoulders on the floor.\",\"Lower both legs toward one side, stopping just above the floor.\",\"Bring them back up through the middle.\",\"Repeat to the other side and keep alternating.\"],\"img\":\"3268.webp\",\"gif\":\"3268.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lower your legs to the side from a raised position to hit the lower abs and obliques.\"},{\"id\":\"4808\",\"n\":\"lying leg raise v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with legs straight and arms by your sides.\",\"Press your lower back gently into the floor.\",\"Lift both legs together until they point to the ceiling.\",\"Lower them slowly, stopping before your back arches.\",\"Keep your legs as straight as you comfortably can.\",\"Breathe steadily through each rep.\"],\"img\":\"4808.webp\",\"gif\":\"4808.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raising your legs while lying on your back. It works the lower abs and the hip flexors.\"},{\"id\":\"4975\",\"n\":\"lying leg raise v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with legs straight and arms by your sides.\",\"Press your lower back gently into the floor.\",\"Lift both legs together until they point to the ceiling.\",\"Lower them slowly, stopping before your back arches.\",\"Keep your legs as straight as you comfortably can.\",\"Breathe steadily through each rep.\"],\"img\":\"4975.webp\",\"gif\":\"4975.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raising your legs while lying on your back. It works the lower abs and the hip flexors.\"},{\"id\":\"3475\",\"n\":\"lying leg tuck hip back stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back.\",\"Hug both knees toward your chest.\",\"Rock gently if comfortable.\",\"Hold for 20-30 seconds.\",\"Relax your shoulders.\",\"Release slowly.\"],\"img\":\"3475.webp\",\"gif\":\"3475.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying tuck stretch easing the hips and lower back.\"},{\"id\":\"3477\",\"n\":\"lying leg tuck hip back to right stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back and tuck your knees.\",\"Lower your knees to the right.\",\"Keep both shoulders down.\",\"Hold for 20-30 seconds.\",\"Breathe slowly.\",\"Return to center.\"],\"img\":\"3477.webp\",\"gif\":\"3477.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying tuck stretch with the knees guided to the right.\"},{\"id\":\"3472\",\"n\":\"lying leg tuck hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back.\",\"Pull one knee toward your chest.\",\"Keep your other leg relaxed.\",\"Hold for 20-30 seconds.\",\"Release slowly.\",\"Switch legs.\"],\"img\":\"3472.webp\",\"gif\":\"3472.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying hip stretch pulling the knee in toward the chest.\",\"fv\":\"1945\"},{\"id\":\"3474\",\"n\":\"lying leg tuck hip stretch with overhead hands\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back with your arms overhead.\",\"Pull one knee toward your chest.\",\"Keep your arms reaching.\",\"Hold for 20-30 seconds.\",\"Release slowly.\",\"Switch legs.\"],\"img\":\"3474.webp\",\"gif\":\"3474.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying knee-tuck stretch with arms extended overhead for a longer line.\"},{\"id\":\"3476\",\"n\":\"lying leg tuck hip twist stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back and pull your knees in.\",\"Drop both knees to one side.\",\"Keep your shoulders on the floor.\",\"Hold for 20-30 seconds.\",\"Return to the center.\",\"Switch sides.\"],\"img\":\"3476.webp\",\"gif\":\"3476.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying stretch with a spinal twist to open the hips and back.\"},{\"id\":\"3478\",\"n\":\"lying leg tuck hip twist to left stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back and tuck your knees.\",\"Lower your knees to the left.\",\"Keep both shoulders down.\",\"Hold for 20-30 seconds.\",\"Breathe slowly.\",\"Return to center.\"],\"img\":\"3478.webp\",\"gif\":\"3478.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying tuck stretch with the knees guided to the left.\"},{\"id\":\"3243\",\"n\":\"lying lower back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie on your back.\",\"Pull both knees toward your chest.\",\"Wrap your arms around your shins.\",\"Hold for 20-30 seconds.\",\"Release slowly.\"],\"img\":\"3243.webp\",\"gif\":\"3243.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying stretch hugging both knees toward your chest to release the lower back.\"},{\"id\":\"3242\",\"n\":\"lying lower back stretch (bent knee)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent.\",\"Pull one knee toward your chest with both hands.\",\"Keep your lower back relaxed on the floor.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"3242.webp\",\"gif\":\"3242.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle lying stretch that draws the knee toward your chest to ease the lower back.\"},{\"id\":\"10781\",\"n\":\"lying neck extension\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Lie face down with your forehead hanging near the edge of a bench or resting just off the floor.\",\"Keep your shoulders relaxed.\",\"Lift your head a few centimeters, keeping your chin slightly tucked.\",\"Pause briefly.\",\"Lower slowly.\",\"Use small, controlled reps.\"],\"img\":\"10781.webp\",\"gif\":\"10781.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you lift the head slightly to train the back of the neck.\"},{\"id\":\"1842\",\"n\":\"lying neck extension stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\"],\"st\":[\"Lie on your back with your head near the edge of a bench or bed, shoulders supported.\",\"Slowly let your head relax backward past the edge.\",\"Support it with your hands if it feels heavy.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Use your hands to lift your head back up carefully.\"],\"img\":\"1842.webp\",\"gif\":\"1842.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the front of the neck by letting the head drop back from the edge of a bench or bed.\"},{\"id\":\"1841\",\"n\":\"lying neck extensor stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Lie on your back with your knees bent.\",\"Clasp your hands behind your head.\",\"Gently lift your head and ease your chin toward your chest.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Lower your head back down slowly.\"],\"img\":\"1841.webp\",\"gif\":\"1841.mp4\",\"cat\":\"stretching\",\"desc\":\"Lets gravity help stretch the back of the neck while you lie on your back.\"},{\"id\":\"10780\",\"n\":\"lying neck flexion\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\"],\"st\":[\"Lie on your back with your knees bent.\",\"Relax your shoulders.\",\"Tuck your chin and lift your head slightly off the floor.\",\"Hold for a second.\",\"Lower slowly.\",\"Keep the motion small and smooth.\"],\"img\":\"10780.webp\",\"gif\":\"10780.mp4\",\"cat\":\"strength\",\"desc\":\"Gentle chin tuck while lying on your back. It strengthens the front neck muscles.\"},{\"id\":\"2853\",\"n\":\"lying neck pull\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"sternocleidomastoid\",\"core\"],\"st\":[\"Lie on your back with hands behind your head.\",\"Curl your head and shoulders up.\",\"Roll up to sit.\",\"Reach forward.\",\"Roll down with control.\"],\"img\":\"2853.webp\",\"gif\":\"2853.mp4\",\"cat\":\"pilates\",\"desc\":\"A roll up from lying with your hands behind your head, training the abs.\"},{\"id\":\"8146\",\"n\":\"lying pelvic floor relaxation and deep breathing\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Rest your hands on your lower belly.\",\"Breathe in slowly through your nose and let your belly rise.\",\"Let your pelvic floor and hips soften as you inhale.\",\"Breathe out slowly through your mouth.\",\"Continue for 1 to 2 minutes at a relaxed pace.\"],\"img\":\"8146.webp\",\"gif\":\"8146.mp4\",\"cat\":\"rehab\",\"desc\":\"A gentle lying breathing drill that lets the pelvic floor and belly relax. It helps you learn calm, deep breathing.\"},{\"id\":\"7294\",\"n\":\"lying pelvic tilt\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Take a breath in with a neutral spine.\",\"Exhale, tilting your pelvis so your lower back presses into the floor.\",\"Hold for a moment.\",\"Release back to neutral.\",\"Repeat slowly.\"],\"img\":\"7294.webp\",\"gif\":\"7294.mp4\",\"cat\":\"mobility\",\"desc\":\"A small floor movement that teaches you to control the tilt of your pelvis and relax the lower back.\"},{\"id\":\"11954\",\"n\":\"lying pretzel stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"quadriceps\"],\"st\":[\"Lie on your side with your hips stacked and your bottom leg bent in front.\",\"Bend the top knee and bring that foot back toward your glutes, holding it with your hand.\",\"Gently roll your top knee back and open your chest toward the floor.\",\"Hold for 20-30 seconds while breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"11954.webp\",\"gif\":\"11954.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying twist that pulls one leg across and bends the other back, stretching the glutes, hips and thighs.\"},{\"id\":\"5040\",\"n\":\"lying prone a\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with your arms out at about 45 degrees, palms down.\",\"Rest your forehead lightly or look at the floor.\",\"Lift your arms and chest slightly while squeezing your shoulder blades.\",\"Hold for a second.\",\"Lower with control and repeat.\"],\"img\":\"5040.webp\",\"gif\":\"5040.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, arms form an A shape and lift. It strengthens the upper back and shoulder blade muscles.\"},{\"id\":\"5041\",\"n\":\"lying prone t\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with arms straight out to the sides, thumbs up.\",\"Keep your neck neutral.\",\"Lift your arms off the floor by squeezing your shoulder blades.\",\"Hold briefly.\",\"Lower slowly.\"],\"img\":\"5041.webp\",\"gif\":\"5041.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, arms out to the sides in a T and lifted. It trains the muscles between the shoulder blades.\"},{\"id\":\"5042\",\"n\":\"lying prone w\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with elbows bent and hands by your head.\",\"Keep your neck neutral.\",\"Lift your elbows and hands off the floor, pulling the shoulder blades together.\",\"Hold for a second.\",\"Lower with control.\"],\"img\":\"5042.webp\",\"gif\":\"5042.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you pull the arms into a W shape. It builds the rear shoulders and mid back.\"},{\"id\":\"5043\",\"n\":\"lying prone w to t\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down in a W with elbows bent.\",\"Lift your arms slightly off the floor.\",\"Straighten your arms out to the sides into a T.\",\"Pull back to the W while keeping your shoulder blades squeezed.\",\"Repeat smoothly.\"],\"img\":\"5043.webp\",\"gif\":\"5043.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you move from a W to a T shape. It trains the back of the shoulders and upper back.\"},{\"id\":\"5044\",\"n\":\"lying prone w to y\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down in a W with elbows bent.\",\"Lift your arms slightly off the floor.\",\"Reach your arms forward and wide into a Y.\",\"Pull back into the W with your shoulder blades squeezed.\",\"Keep your neck relaxed and repeat.\"],\"img\":\"5044.webp\",\"gif\":\"5044.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you move from a W to a Y shape. It works the upper back and lower traps.\"},{\"id\":\"6350\",\"n\":\"lying prone y raise\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with your arms stretched overhead in a Y shape.\",\"Keep your forehead near the floor and your neck long.\",\"Lift your arms off the floor by squeezing your shoulder blades.\",\"Pause for a second at the top.\",\"Lower your arms slowly and repeat.\"],\"img\":\"6350.webp\",\"gif\":\"6350.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you lift your arms into a Y shape to strengthen the muscles that stabilise your shoulder blades.\"},{\"id\":\"8546\",\"n\":\"lying prone y to t to w\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"lower back\"],\"st\":[\"Lie face down with your forehead near the floor and arms extended overhead in a Y.\",\"Lift your arms slightly and hold.\",\"Move them out to a T, then bend the elbows into a W.\",\"Squeeze your shoulder blades together.\",\"Reverse the order and repeat.\"],\"img\":\"8546.webp\",\"gif\":\"8546.mp4\",\"cat\":\"mobility\",\"desc\":\"A prone sequence of arm positions that strengthens the upper back and shoulder blade muscles.\"},{\"id\":\"4832\",\"n\":\"lying rear lateral raise\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie face down on a bench holding a light dumbbell in each hand.\",\"Let your arms hang down with a slight bend in your elbows.\",\"Raise your arms out to the sides until they reach shoulder height.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly.\"],\"img\":\"4832.webp\",\"gif\":\"4832.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you raise light dumbbells out to the sides. It targets the rear shoulders and upper back.\",\"nd\":[\"bench\"]},{\"id\":\"6752\",\"n\":\"lying rectus abdominis activation crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Place your hands lightly on your abs or behind your head.\",\"Exhale and curl your shoulders off the floor.\",\"Feel the abs tighten at the top.\",\"Lower back slowly.\",\"Keep your neck relaxed.\"],\"img\":\"6752.webp\",\"gif\":\"6752.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A small, focused crunch from lying down. It helps you feel the front abdominal muscle working.\"},{\"id\":\"6753\",\"n\":\"lying scalene muscles activation\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Lie on your back with your head resting on the floor.\",\"Relax your shoulders away from your ears.\",\"Gently tilt your head to one side without lifting your shoulder.\",\"Feel a light engagement along the side of your neck.\",\"Return to the middle slowly.\",\"Alternate sides for several reps.\"],\"img\":\"6753.webp\",\"gif\":\"6753.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle lying exercise that wakes up the scalene muscles at the side of the neck. It supports neck control.\"},{\"id\":\"0621\",\"n\":\"lying scissor crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with hands behind your head.\",\"Lift your legs a few inches off the floor.\",\"Crunch your shoulders up.\",\"Scissor your legs, crossing one over the other.\",\"Keep your lower back pressed down.\",\"Switch which leg crosses on top each rep.\"],\"img\":\"0621.webp\",\"gif\":\"0621.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch combined with alternating leg scissors. It targets the abs and lower belly.\"},{\"id\":\"0622\",\"n\":\"lying scissor kick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with hands under your hips.\",\"Lift both legs a few inches off the floor.\",\"Raise one leg higher while the other stays low.\",\"Switch legs in a smooth scissor motion.\",\"Keep your lower back pressed to the floor.\",\"Breathe steadily throughout.\"],\"img\":\"0622.webp\",\"gif\":\"0622.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Alternating small leg kicks while lying down. It challenges the lower abs and hip flexors.\"},{\"id\":\"6214\",\"n\":\"lying scissors cross\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Lie on your back with your legs lifted.\",\"Press your lower back into the floor.\",\"Open your legs wide.\",\"Cross one leg over the other.\",\"Open and cross the other leg on top.\",\"Keep a steady rhythm.\"],\"img\":\"6214.webp\",\"gif\":\"6214.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying scissor kick where the legs cross over each other. It trains the inner thighs and lower abs.\",\"fv\":\"6213\"},{\"id\":\"3413\",\"n\":\"lying shoulder sweep\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"chest\",\"rotator cuff\"],\"st\":[\"Lie on your back with arms straight out to the sides.\",\"Sweep both arms up in an arc toward overhead.\",\"Keep your arms as close to the floor as you comfortably can.\",\"Return along the same path.\",\"Move slowly for 10-12 reps.\"],\"img\":\"3413.webp\",\"gif\":\"3413.mp4\",\"cat\":\"mobility\",\"desc\":\"Slide your arms along the floor in a wide arc to mobilise the shoulders.\"},{\"id\":\"4609\",\"n\":\"lying side to side knee\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"core\"],\"st\":[\"Lie on your back with arms out to the sides and knees bent, feet flat.\",\"Keep your shoulders on the floor.\",\"Slowly drop both knees to one side as far as is comfortable.\",\"Bring them back to the middle and drop them to the other side.\",\"Move at an easy pace and breathe through each rep.\"],\"img\":\"4609.webp\",\"gif\":\"4609.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle lying rotation that sways your bent knees side to side to loosen the lower back and hips.\"},{\"id\":\"0623\",\"n\":\"lying simultaneous alternating leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with your arms by your sides.\",\"Raise one leg toward the ceiling while the other hovers near the floor.\",\"Switch the legs at the same time.\",\"Keep both legs mostly straight.\",\"Press your lower back into the floor.\",\"Move at a controlled pace.\"],\"img\":\"0623.webp\",\"gif\":\"0623.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying down, you lift legs in opposite directions at the same time. It works the lower abs and hips.\"},{\"id\":\"1180\",\"n\":\"lying simultaneous alternating straight leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with your legs straight and your hands under your hips or at your sides.\",\"Press your lower back into the floor and brace your abs.\",\"Raise one leg while the other lowers toward the floor, keeping both straight.\",\"Switch legs in a smooth scissor pattern without letting your back arch.\",\"Continue for the planned reps or time.\"],\"img\":\"1180.webp\",\"gif\":\"1180.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor core move where both legs work together in an alternating pattern, challenging the lower abs and hip flexors.\"},{\"id\":\"10742\",\"n\":\"lying single arm slide from y to t\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"shoulders\"],\"st\":[\"Lie face down with your arms overhead in a Y.\",\"Lift one arm slightly off the floor.\",\"Slide it out and down into a T position.\",\"Hold for a moment.\",\"Slide it back to the Y.\",\"Switch arms after each set.\"],\"img\":\"10742.webp\",\"gif\":\"10742.mp4\",\"cat\":\"mobility\",\"desc\":\"A prone shoulder drill where one arm slides from a Y shape to a T shape. It wakes up the mid back and shoulder blades.\"},{\"id\":\"10739\",\"n\":\"lying single arm triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\"],\"st\":[\"Lie on your back with knees bent.\",\"Raise one arm and bend the elbow, hand reaching behind your head.\",\"Use your other hand to press the elbow gently toward the floor.\",\"Hold for 20-30 seconds.\",\"Keep your ribs down.\",\"Switch arms.\"],\"img\":\"10739.webp\",\"gif\":\"10739.mp4\",\"cat\":\"stretching\",\"desc\":\"A floor stretch for the back of your upper arm. Lying down lets you relax into it.\"},{\"id\":\"2854\",\"n\":\"lying single leg circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with one leg extended up.\",\"Keep your pelvis still.\",\"Draw small circles with that leg.\",\"Reverse direction.\",\"Switch legs.\"],\"img\":\"2854.webp\",\"gif\":\"2854.mp4\",\"cat\":\"pilates\",\"desc\":\"A hip mobility move where one leg draws circles in the air.\"},{\"id\":\"7622\",\"n\":\"lying single leg hamstring stretch against wall\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"lower back\"],\"st\":[\"Lie on your back with your hips close to a wall.\",\"Rest one heel on the wall with your leg as straight as feels comfortable.\",\"Keep the other leg flat on the floor.\",\"Relax and breathe, letting the hamstring lengthen.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"7622.webp\",\"gif\":\"7622.mp4\",\"cat\":\"stretching\",\"desc\":\"Lie by a wall and rest one leg up against it to stretch the hamstring. Easy to relax into and good after leg days.\"},{\"id\":\"2855\",\"n\":\"lying single leg kick\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"upper back\"],\"st\":[\"Lie face down and prop yourself on your forearms.\",\"Keep your chest lifted.\",\"Kick one heel toward your glute twice.\",\"Lower and switch legs.\",\"Keep your hips down.\"],\"img\":\"2855.webp\",\"gif\":\"2855.mp4\",\"cat\":\"pilates\",\"desc\":\"A face-down move kicking one heel toward the glute while the chest stays lifted.\"},{\"id\":\"11801\",\"n\":\"lying single leg quadriceps mobilization\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"ankles\"],\"st\":[\"Lie on your side or stomach with your legs extended.\",\"Bend one knee and bring your heel toward your glute, holding the ankle if needed.\",\"Move the knee in and out of the bend in a slow, controlled rhythm.\",\"Keep your hips level and stay within a comfortable range.\",\"Repeat for 10-15 reps, then switch legs.\"],\"img\":\"11801.webp\",\"gif\":\"11801.mp4\",\"cat\":\"mobility\",\"desc\":\"A lying quad mobilization that gently bends the knee to loosen the front of the thigh.\"},{\"id\":\"10913\",\"n\":\"lying single leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"lower abs\"],\"st\":[\"Lie on your back with one knee bent and that foot flat.\",\"Straighten the other leg and tighten the thigh.\",\"Raise it to the height of your bent knee.\",\"Pause briefly.\",\"Lower slowly. Finish your reps and switch legs.\"],\"img\":\"10913.webp\",\"gif\":\"10913.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying leg raise on one leg. It strengthens the thigh and hip flexors.\",\"fv\":\"3267\"},{\"id\":\"3831\",\"n\":\"lying single leg reverse biceps curl with towel\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"biceps\",\"grip muscles\"],\"st\":[\"Lie on your back and loop a towel around one foot.\",\"Hold the ends with an overhand grip.\",\"Pull the towel toward you while the foot resists.\",\"Pause at the top.\",\"Lower slowly, then switch legs.\"],\"img\":\"3831.webp\",\"gif\":\"3831.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you curl a towel looped around one foot with an overhand grip. It targets your forearms and biceps.\"},{\"id\":\"1776\",\"n\":\"lying single straight leg hip extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down with your legs straight and your forehead on your hands.\",\"Tighten your abs and glutes.\",\"Raise one straight leg a few inches off the floor.\",\"Pause briefly at the top without arching your lower back.\",\"Lower under control and repeat, then switch legs.\"],\"img\":\"1776.webp\",\"gif\":\"1776.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you lift one straight leg off the floor. It strengthens your glutes and hamstrings with a gentle load on the lower back.\"},{\"id\":\"3496\",\"n\":\"lying straight leg marches\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back, arms by your sides.\",\"Press your lower back gently into the floor.\",\"Raise one straight leg toward the ceiling.\",\"Lower it as you raise the other leg.\",\"Keep alternating in a slow, steady march.\",\"Keep your back from arching.\"],\"img\":\"3496.webp\",\"gif\":\"3496.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Alternating straight-leg raises while lying on your back, like a slow march. It trains the lower abs and hip flexors.\"},{\"id\":\"1181\",\"n\":\"lying straight leg raise v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with your legs straight and your hands under your hips.\",\"Press your lower back into the floor.\",\"Raise both legs together until they point to the ceiling.\",\"Lower them slowly, stopping just above the floor.\",\"Keep your core braced and your back from arching.\"],\"img\":\"1181.webp\",\"gif\":\"1181.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying leg raise that targets the lower abs and hip flexors while you keep your legs long.\"},{\"id\":\"9977\",\"n\":\"lying supine abdominal breathing\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\"],\"st\":[\"Lie on your back with your knees bent and your hands on your belly.\",\"Breathe in slowly through your nose.\",\"Feel your belly rise under your hands.\",\"Breathe out slowly through your mouth.\",\"Let your belly lower gently.\",\"Continue for 1 to 2 minutes.\"],\"img\":\"9977.webp\",\"gif\":\"9977.mp4\",\"cat\":\"rehab\",\"desc\":\"A calm lying breathing drill that focuses on belly breathing. It helps you relax and learn core control.\"},{\"id\":\"9969\",\"n\":\"lying supine heel slide\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"calves\"],\"st\":[\"Lie on your back with both legs straight.\",\"Slowly slide one heel along the floor toward your buttocks.\",\"Bend the knee as far as feels comfortable.\",\"Pause for a second.\",\"Slide the heel back out until the leg is straight.\",\"Repeat for your reps, then switch legs.\"],\"img\":\"9969.webp\",\"gif\":\"9969.mp4\",\"cat\":\"rehab\",\"desc\":\"A gentle floor move where you slide your heel toward your hips and back. It restores knee and hip bend with low strain.\"},{\"id\":\"9971\",\"n\":\"lying supine straight knee raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with one knee bent and the other leg straight.\",\"Tighten the thigh of the straight leg so the knee is locked.\",\"Lift the leg to the height of your bent knee.\",\"Hold for a moment.\",\"Lower slowly to the floor.\",\"Finish your reps, then switch legs.\"],\"img\":\"9971.webp\",\"gif\":\"9971.mp4\",\"cat\":\"rehab\",\"desc\":\"A lying straight-leg raise that lifts the leg with the knee locked. It wakes up the quads and hip flexors in a gentle way.\"},{\"id\":\"3539\",\"n\":\"lying t spine mobility stretching\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"chest\"],\"st\":[\"Lie on your side with knees bent and arms in front.\",\"Lift your top arm and open it toward the other side.\",\"Follow your hand with your eyes.\",\"Hold for 20-30 seconds.\",\"Return to the start.\",\"Switch sides.\"],\"img\":\"3539.webp\",\"gif\":\"3539.mp4\",\"cat\":\"mobility\",\"desc\":\"A lying rotation stretch for the upper back.\"},{\"id\":\"11572\",\"n\":\"lying thoracic extensions on foam roller\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"spine\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"core\"],\"st\":[\"Lie on your back with the roller under your upper back.\",\"Support your head with your hands.\",\"Keep your hips on the floor and knees bent.\",\"Gently lean back over the roller.\",\"Return to neutral and shift the roller up or down.\",\"Move slowly and breathe out as you extend.\"],\"img\":\"11572.webp\",\"gif\":\"11572.mp4\",\"cat\":\"mobility\",\"desc\":\"Lying over a foam roller, you gently arch the upper back to open up the thoracic spine.\"},{\"id\":\"6002\",\"n\":\"lying toe tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent at 90 degrees over your hips.\",\"Press your lower back into the floor.\",\"Lower one foot to tap the floor.\",\"Bring it back to tabletop.\",\"Alternate legs with control.\"],\"img\":\"6002.webp\",\"gif\":\"6002.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a tabletop position, alternate lowering a foot to tap the floor while keeping the lower back steady.\",\"fv\":\"6003\"},{\"id\":\"5275\",\"n\":\"lying toe touch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\"],\"st\":[\"Lie on your back with your legs straight up.\",\"Reach your arms up toward your toes.\",\"Lift your shoulders off the floor and touch your toes.\",\"Lower your shoulders slowly.\",\"Keep your legs steady.\"],\"img\":\"5275.webp\",\"gif\":\"5275.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying with the legs up, reach your hands toward your toes. It trains the upper abs.\"},{\"id\":\"5274\",\"n\":\"lying tuck crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your legs extended just off the floor.\",\"Place your hands behind your head.\",\"Pull your knees in and crunch your chest toward them.\",\"Squeeze your abs at the top.\",\"Extend and lower slowly.\"],\"img\":\"5274.webp\",\"gif\":\"5274.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where your knees pull in as your chest comes up. It trains the abs.\"},{\"id\":\"3414\",\"n\":\"lying upper body rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"upper back\"],\"st\":[\"Lie on your side with knees bent and arms stretched in front of you.\",\"Keep your knees stacked.\",\"Lift the top arm and open it across to the other side, following it with your eyes.\",\"Return the arm to the start.\",\"Do 10 reps, then switch sides.\"],\"img\":\"3414.webp\",\"gif\":\"3414.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotate your upper body while lying down to loosen the mid-back.\"},{\"id\":\"1798\",\"n\":\"lying whole body stretch\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Lie on your back with your arms overhead and your legs straight.\",\"Reach your fingertips up and your toes down, as if you want to get taller.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1798.webp\",\"gif\":\"1798.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying flat and reaching long through your arms and legs gives your whole body a gentle stretch. A nice reset after training.\"},{\"id\":\"4420\",\"n\":\"marching on spot\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand tall with your arms bent at your sides.\",\"Lift one knee up toward hip height.\",\"Lower it and lift the other knee.\",\"Swing your arms in rhythm with your steps.\",\"Keep a steady pace for 1-3 minutes.\"],\"img\":\"4420.webp\",\"gif\":\"4420.mp4\",\"cat\":\"cardio\",\"desc\":\"A low-impact cardio move where you march in place to raise your heart rate and warm up the legs.\",\"fv\":\"5690\"},{\"id\":\"4375\",\"n\":\"medicine ball around head rotation\",\"bp\":\"shoulders\",\"eq\":\"medicine ball\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"obliques\"],\"st\":[\"Stand tall with feet hip-width apart, holding a medicine ball at chest height.\",\"Brace your core and keep your hips still.\",\"Pass the ball around your head in a smooth circle, keeping it close.\",\"Complete several circles, then reverse the direction.\",\"Keep your ribs down and avoid leaning back as the ball passes behind you.\"],\"img\":\"4375.webp\",\"gif\":\"4375.mp4\",\"cat\":\"mobility\",\"desc\":\"Circle a medicine ball around your head to warm up the shoulders and challenge your core and balance.\"},{\"id\":\"10109\",\"n\":\"medicine ball backward overhead toss\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"quadriceps\"],\"st\":[\"Stand holding a medicine ball in front of your thighs.\",\"Squat down and swing the ball between your legs.\",\"Drive up and extend your hips.\",\"Throw the ball up and backward over your head.\",\"Retrieve the ball and reset.\",\"Keep your arms long and make sure the space behind you is clear.\"],\"img\":\"10109.webp\",\"gif\":\"10109.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A backward throw of a medicine ball over the head from a squat. It builds hip and back power.\"},{\"id\":\"3439\",\"n\":\"medicine ball backward throw\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"core\"],\"st\":[\"Stand with a medicine ball held between your legs.\",\"Squat slightly, then explode up.\",\"Swing the ball up and back over your head.\",\"Release it behind you at full extension.\",\"Retrieve the ball.\",\"Reset your stance and repeat.\"],\"img\":\"3439.webp\",\"gif\":\"3439.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive overhead throw behind you that trains the hips and posterior chain.\"},{\"id\":\"5144\",\"n\":\"medicine ball chest pass against wall\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Stand facing a wall with the ball held at your chest.\",\"Take a small step back and set your feet.\",\"Push the ball forcefully at the wall.\",\"Catch it with soft elbows as it returns.\",\"Bring it back to your chest and repeat.\"],\"img\":\"5144.webp\",\"gif\":\"5144.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Throw a medicine ball hard against a wall from your chest and catch it on the rebound. It builds explosive pressing power.\"},{\"id\":\"3422\",\"n\":\"medicine ball crunch\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hold a medicine ball on your chest.\",\"Curl your shoulders off the floor.\",\"Squeeze your abs at the top.\",\"Lower slowly.\",\"Keep your chin off your chest.\",\"Breathe out as you crunch up.\"],\"img\":\"3422.webp\",\"gif\":\"3422.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch holding a medicine ball to add resistance for the abs.\",\"fv\":\"3423\"},{\"id\":\"9010\",\"n\":\"medicine ball crunch on stability ball\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\"],\"st\":[\"Sit on the ball and roll down until your lower back is supported.\",\"Hold the medicine ball against your chest or overhead.\",\"Brace your core and crunch your ribs toward your hips.\",\"Pause at the top.\",\"Lower back over the ball with control.\",\"Keep your feet firmly on the floor.\"],\"img\":\"9010.webp\",\"gif\":\"9010.mp4\",\"cat\":\"strength\",\"desc\":\"Crunching on a stability ball while holding a medicine ball adds range and load to the abs.\"},{\"id\":\"4253\",\"n\":\"medicine ball crunch v. 2\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a medicine ball against your chest or overhead.\",\"Curl your shoulders off the floor.\",\"Reach the ball toward your knees.\",\"Lower slowly.\",\"Keep your lower back on the floor.\"],\"img\":\"4253.webp\",\"gif\":\"4253.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch holding a medicine ball for extra resistance. It targets the abs with a simple, adjustable load.\"},{\"id\":\"4099\",\"n\":\"medicine ball half kneeling chest push\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Kneel on one knee with the other foot forward and hold a medicine ball at your chest.\",\"Brace your core and stay tall.\",\"Push the ball forward explosively or against a wall.\",\"Catch it or bring it back to your chest.\",\"Switch the kneeling leg after your set.\"],\"img\":\"4099.webp\",\"gif\":\"4099.mp4\",\"cat\":\"strength\",\"desc\":\"A half kneeling chest pass motion with a medicine ball that trains pushing power and core stability.\"},{\"id\":\"10197\",\"n\":\"medicine ball horizontal smash\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\",\"obliques\"],\"st\":[\"Stand sideways to a wall or rebound surface holding a medicine ball at chest height.\",\"Wind the ball slightly away from the target.\",\"Rotate and throw the ball hard against the wall with both hands.\",\"Catch it, reset your stance and go again.\",\"Use your hips and keep your core tight. Finish the reps, then switch sides.\"],\"img\":\"10197.webp\",\"gif\":\"10197.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive sideways medicine ball slam that builds rotational power in the chest, core and shoulders.\"},{\"id\":\"5238\",\"n\":\"medicine ball lunge with biceps curl\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"biceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand holding a medicine ball at your thighs.\",\"Step forward into a lunge.\",\"Curl the ball up toward your chest as you lower.\",\"Push back to standing while lowering the ball.\",\"Alternate legs on each rep.\"],\"img\":\"5238.webp\",\"gif\":\"5238.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge combined with a medicine ball curl. It trains the legs and arms in one go.\"},{\"id\":\"10598\",\"n\":\"medicine ball lying floor close press catch\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Lie on your back with knees bent, holding a medicine ball above your chest.\",\"Press the ball up quickly with your hands close together.\",\"Catch it as it comes down with soft elbows.\",\"Lower it to just above your chest.\",\"Keep your back flat and ribs down.\",\"Repeat for controlled, crisp reps.\"],\"img\":\"10598.webp\",\"gif\":\"10598.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A floor press throw with narrow hands. It builds explosive pushing power through the chest and triceps.\"},{\"id\":\"5031\",\"n\":\"medicine ball lying leg raise\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"quadriceps\"],\"st\":[\"Lie on your back with a medicine ball squeezed between your feet.\",\"Press your lower back into the floor.\",\"Raise your legs until they are vertical.\",\"Lower them slowly without letting your back arch.\",\"Keep your grip on the ball firm.\"],\"img\":\"5031.webp\",\"gif\":\"5031.mp4\",\"cat\":\"strength\",\"desc\":\"Leg raise gripping a medicine ball between your feet. The extra load makes the lower abs work harder.\"},{\"id\":\"10118\",\"n\":\"medicine ball overhead slam circle\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"glutes\",\"triceps\"],\"st\":[\"Stand with feet shoulder width apart holding a medicine ball overhead.\",\"Circle the ball to one side and around as you start to bend your knees.\",\"Slam the ball hard into the floor in front of you.\",\"Catch it on the bounce or pick it up, and reset overhead.\",\"Alternate the circle direction every set and keep your core braced.\"],\"img\":\"10118.webp\",\"gif\":\"10118.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A medicine ball slam combined with a circular sweep, building power through the core, lats and shoulders.\"},{\"id\":\"4243\",\"n\":\"medicine ball overhead throw\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"glutes\",\"triceps\"],\"st\":[\"Stand with your feet shoulder-width apart holding a medicine ball overhead.\",\"Lean back slightly and brace your core.\",\"Throw the ball forward or against a wall as hard as you can.\",\"Follow through with your arms.\",\"Catch or pick up the ball and reset.\",\"Keep your back from over-arching.\"],\"img\":\"4243.webp\",\"gif\":\"4243.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Throwing a medicine ball up and forward from overhead. It builds full-body explosive power through the core and shoulders.\"},{\"id\":\"10108\",\"n\":\"medicine ball overhead toss\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"glutes\",\"hip flexors\"],\"st\":[\"Stand holding a medicine ball overhead.\",\"Reach back slightly and brace your abs.\",\"Throw the ball forward powerfully.\",\"Follow through with your arms.\",\"Pick up the ball and reset.\",\"Keep your back neutral.\"],\"img\":\"10108.webp\",\"gif\":\"10108.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive throw of a medicine ball from behind the head forward. It builds power from hips to arms.\"},{\"id\":\"10595\",\"n\":\"medicine ball pullover catch\",\"bp\":\"back\",\"eq\":\"medicine ball\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\",\"shoulders\"],\"st\":[\"Lie on your back with knees bent, holding a medicine ball overhead.\",\"Pull the ball forward over your chest to throw it up toward a partner or wall.\",\"Catch the ball with soft elbows as it returns.\",\"Let it travel back overhead in a controlled arc.\",\"Keep your lower back pressed to the floor.\",\"Repeat at a steady rhythm.\"],\"img\":\"10595.webp\",\"gif\":\"10595.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lying throw and catch that sends a medicine ball overhead and back. It trains explosive lat and core strength.\"},{\"id\":\"1697\",\"n\":\"medicine ball reverse wood chop squat\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"quadriceps\",\"glutes\",\"shoulders\"],\"st\":[\"Hold a medicine ball overhead to one side and stand with your feet shoulder width apart.\",\"Squat down while chopping the ball diagonally across your body.\",\"Rotate your torso and bring the ball toward the opposite knee.\",\"Stand up as you return the ball overhead.\",\"Alternate sides each set.\"],\"img\":\"1697.webp\",\"gif\":\"1697.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a diagonal chop from high to low, working legs and core together.\"},{\"id\":\"1699\",\"n\":\"medicine ball rotational throw\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\",\"hip flexors\"],\"st\":[\"Stand sideways to a wall holding a medicine ball at your hip.\",\"Rotate away from the wall and load your back hip.\",\"Explosively rotate and throw the ball into the wall.\",\"Catch it on the rebound and repeat.\",\"Switch sides after the planned reps.\"],\"img\":\"1699.webp\",\"gif\":\"1699.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A powerful rotational throw that trains the core, hips and shoulders to work together.\"},{\"id\":\"1693\",\"n\":\"medicine ball single leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"ankles\"],\"st\":[\"Hold a medicine ball at your chest and stand on one leg with a soft knee.\",\"Hinge at the hips while your free leg extends behind you.\",\"Lower the ball toward the floor with a flat back.\",\"Squeeze your glute to return to standing.\",\"Finish all reps, then switch legs.\"],\"img\":\"1693.webp\",\"gif\":\"1693.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge holding a medicine ball that trains the hamstrings, glutes and balance.\"},{\"id\":\"1704\",\"n\":\"medicine ball single leg wood chop\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Stand on one leg holding a medicine ball overhead to one side.\",\"Chop the ball diagonally down across your body.\",\"Rotate your torso and pivot your standing foot.\",\"Return the ball overhead with control.\",\"Complete the reps, then switch legs.\"],\"img\":\"1704.webp\",\"gif\":\"1704.mp4\",\"cat\":\"strength\",\"desc\":\"A wood chop done on one leg that adds a balance challenge to the core rotation.\"},{\"id\":\"0625\",\"n\":\"medicine ball sit up (wall)\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"chest\"],\"st\":[\"Sit on the floor facing a wall, knees bent, holding a medicine ball.\",\"Lean back and lower your back to the floor.\",\"Sit up and throw the ball at the wall.\",\"Catch it on the rebound.\",\"Lower back down with control.\",\"Repeat for reps.\"],\"img\":\"0625.webp\",\"gif\":\"0625.mp4\",\"cat\":\"strength\",\"desc\":\"A sit-up that includes a ball throw to a wall. It builds the abs with an explosive finish.\"},{\"id\":\"10558\",\"n\":\"medicine ball sit up slam\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"shoulders\",\"lats\"],\"st\":[\"Lie on your back with knees bent, holding a medicine ball overhead.\",\"Sit up in one motion, bringing the ball forward.\",\"Slam the ball down in front of your feet.\",\"Catch it on the bounce or pick it up.\",\"Lie back with control and repeat.\"],\"img\":\"10558.webp\",\"gif\":\"10558.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Sit up while raising a medicine ball overhead and slam it down. It combines a crunch with power.\"},{\"id\":\"10758\",\"n\":\"medicine ball skater hop\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"core\",\"hip flexors\"],\"st\":[\"Hold a medicine ball at your chest.\",\"Hop sideways onto one leg.\",\"Land softly with a bent knee.\",\"Pause briefly, then push off to the other side.\",\"Keep your chest up.\",\"Alternate for the reps.\"],\"img\":\"10758.webp\",\"gif\":\"10758.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lateral hop from leg to leg while holding a medicine ball. It trains balance and side-to-side power.\"},{\"id\":\"10552\",\"n\":\"medicine ball split stance torso twist\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Stand in a split stance and hold a medicine ball at chest height.\",\"Brace your core.\",\"Rotate your torso to one side, keeping your hips steady.\",\"Return to the centre and rotate the other way.\",\"Complete all reps, then switch the front foot.\"],\"img\":\"10552.webp\",\"gif\":\"10552.mp4\",\"cat\":\"strength\",\"desc\":\"Rotate your torso side to side with a medicine ball in a split stance. It trains the trunk rotators.\"},{\"id\":\"3877\",\"n\":\"medicine ball squat jump\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a medicine ball at your chest with both hands.\",\"Stand with feet shoulder-width apart.\",\"Sink into a squat with your chest up.\",\"Jump up as high as you can.\",\"Land softly with bent knees.\",\"Reset and repeat.\"],\"img\":\"3877.webp\",\"gif\":\"3877.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat jump while holding a medicine ball, building explosive power in the legs.\"},{\"id\":\"3442\",\"n\":\"medicine ball standing overhead throw\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart holding the ball overhead.\",\"Arch back slightly.\",\"Throw the ball forward and down with force.\",\"Follow through with your arms.\",\"Pick up the ball.\",\"Reset and repeat.\"],\"img\":\"3442.webp\",\"gif\":\"3442.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive overhead throw with a medicine ball, working the upper body and trunk.\"},{\"id\":\"4383\",\"n\":\"medicine ball step behind rotational throw\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\",\"quadriceps\"],\"st\":[\"Stand sideways to a wall, holding a medicine ball at hip height.\",\"Step your rear foot behind you and load your weight onto it.\",\"Rotate your hips and torso toward the wall.\",\"Throw the ball hard into the wall at chest height.\",\"Catch it, reset, and switch sides after your set.\"],\"img\":\"4383.webp\",\"gif\":\"4383.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive rotational throw that starts with a step behind. It builds power through the hips and trunk.\"},{\"id\":\"5161\",\"n\":\"medicine ball throw squat with wall\",\"bp\":\"shoulders\",\"eq\":\"medicine ball\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"quadriceps\",\"glutes\",\"core\"],\"st\":[\"Stand facing a wall at arm's length and hold a medicine ball at your chest.\",\"Squat down with your chest up and knees tracking over your toes.\",\"Drive up explosively and throw the ball at the wall.\",\"Catch the ball on the rebound with soft hands.\",\"Reset your stance and repeat for controlled reps.\"],\"img\":\"5161.webp\",\"gif\":\"5161.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Squat down with a medicine ball, then drive up and throw it against a wall. It trains explosive power through the legs and shoulders.\"},{\"id\":\"5894\",\"n\":\"meditation\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Sit comfortably cross-legged, with hips slightly higher than your knees.\",\"Lengthen your spine and relax your shoulders.\",\"Rest your hands on your knees.\",\"Close your eyes and settle into easy breathing.\",\"Stay for 3-10 minutes.\"],\"img\":\"5894.webp\",\"gif\":\"5894.mp4\",\"cat\":\"yoga\",\"desc\":\"Seated stillness with a tall spine. Calms the mind and trains upright posture.\"},{\"id\":\"2879\",\"n\":\"mermaid\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"shoulders\"],\"st\":[\"Sit with your legs folded to one side in a comfortable position.\",\"Place one hand on the mat beside you.\",\"Reach the other arm overhead and bend sideways over the supporting hand.\",\"Hold for a breath, feeling the side stretch.\",\"Return to tall sitting and switch sides.\"],\"img\":\"2879.webp\",\"gif\":\"2879.mp4\",\"cat\":\"pilates\",\"desc\":\"A seated Pilates side stretch that opens the sides of the torso and ribs.\"},{\"id\":\"3825\",\"n\":\"mid air lateral raises with switching palms\",\"bp\":\"shoulders\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"trapezius\",\"forearms\"],\"st\":[\"Stand with a light dumbbell in each hand at your sides.\",\"Raise your arms out to shoulder height with palms down.\",\"Turn your palms up in mid air, then back down.\",\"Lower the weights slowly.\",\"Keep your elbows slightly bent.\"],\"img\":\"3825.webp\",\"gif\":\"3825.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral raise where you turn your palms over at the top. It works the side of your shoulders from two angles.\"},{\"id\":\"8585\",\"n\":\"mid back elbow squeeze\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\",\"trapezius\"],\"st\":[\"Stand or sit tall with your hands by your head or elbows bent in front.\",\"Pull your elbows back and down.\",\"Squeeze your shoulder blades together.\",\"Hold for a second at the end.\",\"Return slowly to the start.\",\"Keep your neck relaxed.\"],\"img\":\"8585.webp\",\"gif\":\"8585.mp4\",\"cat\":\"strength\",\"desc\":\"A simple drill that squeezes the elbows back to engage the mid back. It trains the muscles between the shoulder blades.\"},{\"id\":\"4288\",\"n\":\"middle back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"lats\",\"trapezius\"],\"st\":[\"Stand or sit and clasp your hands in front of you.\",\"Straighten your arms and push them forward.\",\"Round your upper back and tuck your chin.\",\"Feel the stretch between your shoulder blades.\",\"Hold for 20-30 seconds.\",\"Release slowly and repeat.\"],\"img\":\"4288.webp\",\"gif\":\"4288.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch that rounds the middle back and spreads the shoulder blades. It relieves tension from sitting or rowing.\",\"fv\":\"0626\"},{\"id\":\"5895\",\"n\":\"mindful breathing meditation\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Sit tall in a comfortable position and relax your shoulders.\",\"Rest your hands on your lap.\",\"Breathe in slowly through your nose.\",\"Breathe out slowly and notice the pause.\",\"Continue for 3-10 minutes.\"],\"img\":\"5895.webp\",\"gif\":\"5895.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated practice of following your breath. Lowers tension and trains focus.\"},{\"id\":\"1969\",\"n\":\"mobilization of ankle stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"soleus\",\"shins\"],\"st\":[\"Stand facing a wall with one foot forward, toes a few inches from it.\",\"Keep your front heel on the floor.\",\"Bend the front knee and glide it toward the wall.\",\"Return and repeat slowly for 10-15 reps, then switch feet.\"],\"img\":\"1969.webp\",\"gif\":\"1969.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle rocking stretch that improves ankle movement and loosens the calf.\"},{\"id\":\"9048\",\"n\":\"mountain climber cross kick\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Brace your core.\",\"Drive one knee across your body toward the opposite elbow.\",\"Return the foot and switch legs quickly.\",\"Keep your hips low and level.\",\"Keep up a steady pace for a set time.\"],\"img\":\"9048.webp\",\"gif\":\"9048.mp4\",\"cat\":\"cardio\",\"desc\":\"A mountain climber variation where you bring each knee across toward the opposite elbow. It raises your heart rate and works the obliques.\"},{\"id\":\"4976\",\"n\":\"mountain climber jump\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"quadriceps\",\"shoulders\",\"hip flexors\"],\"st\":[\"Start in a high plank.\",\"Drive one knee toward your chest.\",\"Switch legs with a small jump.\",\"Keep your hips low.\",\"Maintain a fast, steady pace.\",\"Rest when your form slips.\"],\"img\":\"4976.webp\",\"gif\":\"4976.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A mountain climber with a jump between the feet. It raises your heart rate and works the core.\"},{\"id\":\"0629\",\"n\":\"mountain climber lunge\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hip flexors\",\"core\",\"shoulders\"],\"st\":[\"Start in a plank with hands under your shoulders.\",\"Step one foot forward outside your hand.\",\"Lower your hips into a lunge stretch.\",\"Return the foot back to the plank.\",\"Switch legs.\",\"Keep your core tight and move at a steady pace.\"],\"img\":\"0629.webp\",\"gif\":\"0629.mp4\",\"cat\":\"cardio\",\"desc\":\"A mountain climber that steps the foot all the way outside the hand into a lunge. It raises the heart rate and opens the hips.\"},{\"id\":\"5156\",\"n\":\"mountain climber slide with towel\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hip flexors\",\"quadriceps\",\"core\"],\"st\":[\"Place your feet on towels on a smooth floor and get into a plank.\",\"Keep your core tight and shoulders over your wrists.\",\"Slide one knee toward your chest.\",\"Slide it back and switch legs.\",\"Keep a steady pace and a flat back.\"],\"img\":\"5156.webp\",\"gif\":\"5156.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank, slide your feet on towels to bring your knees to your chest. A core and cardio move that is easy on the joints.\"},{\"id\":\"5213\",\"n\":\"mountain climber v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"quadriceps\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Brace your core.\",\"Drive one knee toward your chest.\",\"Switch legs quickly.\",\"Keep your hips low and level.\",\"Continue for 20-40 seconds.\"],\"img\":\"5213.webp\",\"gif\":\"5213.mp4\",\"cat\":\"cardio\",\"desc\":\"A mountain climber in plank position, a second variation. It raises your heart rate and works the core.\"},{\"id\":\"5896\",\"n\":\"mountain pose\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Stand with your feet together or hip-width apart.\",\"Spread your toes and press evenly through both feet.\",\"Lengthen your spine and draw your shoulders back and down.\",\"Let your arms hang with palms forward.\",\"Hold for 5 slow breaths.\"],\"img\":\"5896.webp\",\"gif\":\"5896.mp4\",\"cat\":\"yoga\",\"desc\":\"The basic standing pose with a tall, balanced posture. A base for most other poses.\"},{\"id\":\"8130\",\"n\":\"moving child pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"shoulders\",\"glutes\"],\"st\":[\"Start on all fours with your knees slightly wider than your hips.\",\"Sit your hips back toward your heels and reach your arms forward.\",\"Let your chest sink toward the floor.\",\"Rock forward and back slowly, then walk your hands to each side.\",\"Breathe deeply and relax your neck.\",\"Move gently for 30 to 60 seconds.\"],\"img\":\"8130.webp\",\"gif\":\"8130.mp4\",\"cat\":\"stretching\",\"desc\":\"A flowing version of child's pose that rocks the body to stretch the back, hips and shoulders.\"},{\"id\":\"5228\",\"n\":\"myotatic crunch on bosu ball\",\"bp\":\"waist\",\"eq\":\"bosu ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie back over a Bosu ball with your lower back supported.\",\"Place your hands beside your head and your feet flat.\",\"Let your torso extend gently over the ball.\",\"Crunch up, bringing your ribs toward your hips.\",\"Lower slowly through the full range.\"],\"img\":\"5228.webp\",\"gif\":\"5228.mp4\",\"cat\":\"strength\",\"desc\":\"A deep, stretched crunch over a Bosu ball. The extra range loads the abs strongly.\"},{\"id\":\"6138\",\"n\":\"namaskarasana yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"inner thighs\"],\"st\":[\"Stand with your feet wider than your hips and toes turned out.\",\"Lower into a deep squat.\",\"Press your palms together at the chest.\",\"Use your elbows to gently press your knees outward.\",\"Keep your chest lifted and hold for 20-30 seconds.\",\"Stand up slowly.\"],\"img\":\"6138.webp\",\"gif\":\"6138.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep squatting pose with the palms pressed together in front of the chest. It opens the hips and inner thighs.\"},{\"id\":\"0632\",\"n\":\"narrow leg bench bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with your feet close together on a bench.\",\"Bend your knees and keep arms by your sides.\",\"Drive through your heels and lift your hips.\",\"Squeeze your glutes at the top.\",\"Hold briefly.\",\"Lower slowly.\"],\"img\":\"0632.webp\",\"gif\":\"0632.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge with your feet close together on a bench. It places more load on the glutes and hamstrings.\"},{\"id\":\"4773\",\"n\":\"narrow seated chin up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Sit under a low bar with your hands close together, palms facing you.\",\"Extend your legs in front with heels on the floor.\",\"Pull your chest up toward the bar.\",\"Squeeze your back and arms at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"4773.webp\",\"gif\":\"4773.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated chin-up with a narrow underhand grip, using your legs for some help. It builds the lats and biceps.\"},{\"id\":\"3392\",\"n\":\"narrow squat from deficit\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"calves\"],\"st\":[\"Stand with your heels on a low platform and your feet close together.\",\"Hold your arms in front for balance.\",\"Squat down, keeping your knees over your toes.\",\"Go as deep as comfortable with your chest up.\",\"Drive up through your feet.\",\"Stand tall without locking out hard.\"],\"img\":\"3392.webp\",\"gif\":\"3392.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A close-stance squat with your heels raised on a small step to emphasize the quads.\"},{\"id\":\"4913\",\"n\":\"narrow top half pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Grab a pull-up bar with a narrow grip and pull up to the top position.\",\"Lower yourself to about halfway.\",\"Pull back up until your chin clears the bar.\",\"Keep your chest up and your elbows close.\",\"Avoid swinging.\",\"Repeat for your reps.\"],\"img\":\"4913.webp\",\"gif\":\"4913.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A partial pull-up with a narrow grip, done in the top half of the range. It focuses on the upper phase of the pull.\"},{\"id\":\"0633\",\"n\":\"neck bridge prone\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"sternocleidomastoid\"],\"st\":[\"Kneel on a mat and lean forward so the top of your head rests lightly on the floor.\",\"Place your hands on the floor for support.\",\"Take some weight through your neck by rocking forward and back slowly.\",\"Keep your movements small and controlled.\",\"Return to the start and rest between sets.\",\"Never bounce and keep most weight on your hands at first.\"],\"img\":\"0633.webp\",\"gif\":\"0633.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A face-down neck bridge that strengthens the muscles at the back of the neck. Start gently and keep the load light.\"},{\"id\":\"3994\",\"n\":\"neck circle stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Stand or sit tall with relaxed shoulders.\",\"Drop your chin toward your chest.\",\"Slowly roll your head to one side.\",\"Continue in a smooth circle.\",\"Do 5 circles, then reverse.\"],\"img\":\"3994.webp\",\"gif\":\"3994.mp4\",\"cat\":\"stretching\",\"desc\":\"Gentle circles of the head to loosen the neck. It eases stiffness in the neck muscles.\"},{\"id\":\"1833\",\"n\":\"neck extension stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Slowly tilt your head back to look up at the ceiling, keeping your jaw relaxed.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1833.webp\",\"gif\":\"1833.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilting your head back stretches the front of the neck. Go slowly and stay within a comfortable range.\"},{\"id\":\"1838\",\"n\":\"neck extensor and rotational stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Sit tall with your shoulders relaxed.\",\"Turn your head about 45 degrees to one side.\",\"Rest a hand on the back of your head and ease your nose toward your armpit.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1838.webp\",\"gif\":\"1838.mp4\",\"cat\":\"stretching\",\"desc\":\"Combines forward bending with a turn of the head to stretch the back and side of the neck.\"},{\"id\":\"1837\",\"n\":\"neck extensor stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Sit tall with your back straight.\",\"Tuck your chin toward your chest.\",\"Rest one hand on the back of your head and add very light pressure down.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Remove your hand and lift your head slowly.\"],\"img\":\"1837.webp\",\"gif\":\"1837.mp4\",\"cat\":\"stretching\",\"desc\":\"Lengthens the extensor muscles at the back of the neck by tucking the chin down.\"},{\"id\":\"1840\",\"n\":\"neck flexor and rotational stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\"],\"st\":[\"Sit or stand tall with your shoulders down.\",\"Turn your head slightly to one side.\",\"Tilt your chin up and back until you feel a stretch along the front of your neck.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1840.webp\",\"gif\":\"1840.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the front and side of the neck by combining a head tilt back with a turn.\"},{\"id\":\"1839\",\"n\":\"neck flexor stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Lift your chin and slowly tilt your head back.\",\"Keep the movement small and comfortable.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Return your head to neutral.\"],\"img\":\"1839.webp\",\"gif\":\"1839.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilts the head back to stretch the muscles at the front of the neck.\"},{\"id\":\"1834\",\"n\":\"neck protraction stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Keep your eyes level and slide your chin and head straight forward.\",\"Stop when you feel a stretch at the back of the neck.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Draw your head back to neutral and relax.\"],\"img\":\"1834.webp\",\"gif\":\"1834.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle stretch that glides the head forward to open the back of the neck and the base of the skull.\"},{\"id\":\"6765\",\"n\":\"neck stretch with hand assisted\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Place one hand on the side of your head.\",\"Gently tilt your head toward the shoulder, using light pressure.\",\"Keep the opposite shoulder down.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Release slowly and switch sides.\"],\"img\":\"6765.webp\",\"gif\":\"6765.mp4\",\"cat\":\"stretching\",\"desc\":\"A neck stretch where your hand adds gentle pressure. It eases the side and back of the neck.\"},{\"id\":\"8084\",\"n\":\"negative biceps leg concentration curl\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Sit with your legs apart and hold a weight in one hand.\",\"Rest the back of your upper arm against your inner thigh.\",\"Curl the weight up with help from your other hand if needed.\",\"Lower it very slowly over about 3 to 4 seconds.\",\"Keep your upper arm still against your leg.\",\"Do your reps, then switch arms.\"],\"img\":\"8084.webp\",\"gif\":\"8084.mp4\",\"cat\":\"strength\",\"desc\":\"A seated concentration curl braced against the thigh with a slow lowering phase. It emphasises the biceps through the negative.\"},{\"id\":\"4982\",\"n\":\"negative dragon flag\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"lats\",\"lower back\"],\"st\":[\"Lie on a bench and grip the edge behind your head.\",\"Raise your body into a straight vertical line on your upper back.\",\"Lower your body slowly as one stiff plank, keeping hips from bending.\",\"Stop just above the bench with your core tight.\",\"Bend your knees to return to the start, then repeat.\"],\"img\":\"4982.webp\",\"gif\":\"4982.mp4\",\"cat\":\"calisthenics\",\"desc\":\"The lowering half of the dragon flag. You control a straight body down toward the bench, which builds serious core strength.\",\"nd\":[\"bench\"],\"fv\":\"5264\"},{\"id\":\"11090\",\"n\":\"negative front lever raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"lower abs\",\"grip muscles\",\"upper back\"],\"st\":[\"Hang from a bar and pull your body up so your hips and legs are above you.\",\"Straighten your body and keep your arms locked.\",\"Lower slowly toward a horizontal position, keeping your body in a straight line.\",\"Stop when you cannot hold the line, then bend your knees to come back up.\",\"Rest and repeat for a few careful reps.\"],\"img\":\"11090.webp\",\"gif\":\"11090.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced hanging move where you lower slowly toward a front lever. It builds serious core and lat strength.\"},{\"id\":\"5556\",\"n\":\"negative push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start at the top of a push-up with straight arms.\",\"Brace your core and keep a straight line.\",\"Lower your chest to the floor over 3-5 seconds.\",\"Drop to your knees or reset at the bottom.\",\"Return to the top and repeat.\"],\"img\":\"5556.webp\",\"gif\":\"5556.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Push-up focusing on the slow lowering phase to build strength for full reps.\"},{\"id\":\"8882\",\"n\":\"neutral wrist roller\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Hold the wrist roller with a neutral, thumbs-up grip and your arms out in front.\",\"Let the weight hang from the rope with the rope unwound.\",\"Roll the bar with your wrists to wind the rope up.\",\"Keep your arms steady and your shoulders relaxed.\",\"When the weight reaches the bar, lower it slowly by unwinding.\",\"Stop if your forearms burn too much to keep control.\"],\"img\":\"8882.webp\",\"gif\":\"8882.mp4\",\"cat\":\"strength\",\"desc\":\"You wind a rope with a weight on it by turning a bar with a neutral grip. It builds forearm and grip endurance.\"},{\"id\":\"7746\",\"n\":\"nordic hamstring curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Kneel on a pad with your ankles held down firmly.\",\"Keep your body straight from knees to head.\",\"Lower forward as slowly as you can.\",\"Catch yourself with your hands at the bottom.\",\"Push back up and repeat.\"],\"img\":\"7746.webp\",\"gif\":\"7746.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Kneel with your feet anchored and lower your body forward slowly. It is a demanding hamstring strengthener.\"},{\"id\":\"3330\",\"n\":\"oblique crunches with bent knee leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your hands by your head and knees bent.\",\"Lift your shoulders and knees at the same time.\",\"Twist and bring one elbow toward the opposite knee.\",\"Hold briefly, then lower with control.\",\"Alternate sides through the set.\"],\"img\":\"3330.webp\",\"gif\":\"3330.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side crunch combined with a bent knee lift. It trains the obliques and lower abs together.\"},{\"id\":\"3331\",\"n\":\"oblique crunches with straight leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with legs raised straight and hands by your head.\",\"Lift your shoulders off the floor.\",\"Rotate to bring one elbow toward the opposite hip.\",\"Keep your legs steady and low back pressed down.\",\"Return slowly and alternate sides.\"],\"img\":\"3331.webp\",\"gif\":\"3331.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A twisting crunch with your legs lifted straight, making your core work harder through the lever.\"},{\"id\":\"3515\",\"n\":\"oblique v up on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on one side with legs together and an arm extended overhead.\",\"Lift your legs and upper body at the same time.\",\"Reach your top hand toward your feet.\",\"Lower with control, not resting.\",\"Keep your movement smooth.\",\"Do your reps, then switch sides.\"],\"img\":\"3515.webp\",\"gif\":\"3515.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying V-up that targets the obliques.\"},{\"id\":\"5241\",\"n\":\"old school reverse extensions\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Lie face down over a bench with your hips at the edge.\",\"Hold the bench and keep your legs hanging down.\",\"Lift your legs behind you until your body is straight.\",\"Pause and squeeze your glutes.\",\"Lower slowly without swinging.\"],\"img\":\"5241.webp\",\"gif\":\"5241.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A classic reverse hyper lift on a bench, raising the legs behind you. It trains the lower back and glutes.\",\"fv\":\"5263\"},{\"id\":\"3983\",\"n\":\"one arm front plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"glutes\"],\"st\":[\"Start in a high plank with feet wide.\",\"Lift one hand off the floor.\",\"Hold your hips steady.\",\"Hold for 20-30 seconds.\",\"Switch arms.\"],\"img\":\"3983.webp\",\"gif\":\"3983.mp4\",\"cat\":\"isometric\",\"desc\":\"A front plank held with one arm lifted. It tests anti-rotation core strength.\",\"hd\":1},{\"id\":\"1801\",\"n\":\"one arm lat stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"triceps\"],\"st\":[\"Stand tall and hold a pole or frame with one hand above head height.\",\"Lean away from the arm and sit your hips slightly back to feel a stretch along your side.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1801.webp\",\"gif\":\"1801.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching one arm overhead and leaning to the side stretches a single lat. Good for finding tight spots on each side.\"},{\"id\":\"1976\",\"n\":\"one arm shoulder flexor stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"chest\"],\"st\":[\"Stand next to a wall or post and place one hand on it behind you with the arm straight.\",\"Slowly turn your body away until you feel the front of the shoulder stretch.\",\"Keep the arm straight and the shoulder relaxed.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1976.webp\",\"gif\":\"1976.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretching one arm back and down to lengthen the front of the shoulder.\"},{\"id\":\"2814\",\"n\":\"one arm twisted clean and press\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"triceps\",\"obliques\",\"quadriceps\",\"core\"],\"st\":[\"Stand with feet shoulder width apart, holding a weight in one hand low in front of you.\",\"Pull it up to your shoulder with a hip drive and a slight turn of the body.\",\"Turn your feet and hips back to face forward as you dip your knees.\",\"Press the weight overhead until your arm locks.\",\"Lower with control and repeat, then switch sides.\"],\"img\":\"2814.webp\",\"gif\":\"2814.mp4\",\"cat\":\"strength\",\"desc\":\"A one arm clean with a body twist followed by a press overhead. Builds power and coordination from hips to shoulder.\"},{\"id\":\"1357\",\"n\":\"one handed hang\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"lats\",\"hands\"],\"st\":[\"Stand under a pull-up bar and grip it with one hand.\",\"Lift your feet and hang with your arm straight.\",\"Keep your shoulder active and your body still.\",\"Hold for 10-20 seconds.\",\"Lower yourself carefully and switch hands.\"],\"img\":\"1357.webp\",\"gif\":\"1357.mp4\",\"cat\":\"isometric\",\"desc\":\"Hanging from a bar with just one hand. It builds grip strength and gives the shoulder a stretch.\",\"hd\":1},{\"id\":\"1049\",\"n\":\"one leg kickback (with bench support)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Place your hands on a bench and step back into a hinged position.\",\"Keep your back flat and your core braced.\",\"Kick one leg straight back and up, squeezing your glute.\",\"Lower without letting your hips rotate.\",\"Finish your reps, then switch legs.\"],\"img\":\"1049.webp\",\"gif\":\"1049.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Support yourself on a bench and kick one leg back and up. It works the glutes without any equipment.\"},{\"id\":\"1578\",\"n\":\"one leg quarter squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand on one leg with the other foot lifted slightly off the floor.\",\"Extend your arms in front for balance.\",\"Bend your knee and sink down about a quarter of the way.\",\"Keep your knee in line with your toes and your chest up.\",\"Stand back up, then switch legs after your reps.\"],\"img\":\"1578.webp\",\"gif\":\"1578.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A shallow single-leg squat that is easy on the knees. It builds balance and leg strength.\"},{\"id\":\"4212\",\"n\":\"one leg star balance\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"calves\",\"ankles\",\"hamstrings\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Reach your free foot forward and tap lightly, then return.\",\"Tap out to the side, then return.\",\"Tap behind you, then return.\",\"Keep your hips level and chest tall.\",\"Switch legs after a set of taps.\"],\"img\":\"4212.webp\",\"gif\":\"4212.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Balance on one leg while reaching the other foot toward points of an imaginary star. It builds stability, control and ankle strength.\"},{\"id\":\"6298\",\"n\":\"one legged upward bow pose eka pada urdhva dhanurasana\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"hip flexors\"],\"st\":[\"Come into wheel pose with hands and feet pressing down.\",\"Shift weight onto one foot.\",\"Lift the other leg toward the ceiling.\",\"Keep your hips high and level.\",\"Hold briefly, lower, then switch legs.\"],\"img\":\"6298.webp\",\"gif\":\"6298.mp4\",\"cat\":\"yoga\",\"desc\":\"A wheel pose with one leg lifted into the air. It adds balance and strength demand to the backbend.\"},{\"id\":\"4153\",\"n\":\"one side archer push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a wide push up position with hands well outside your shoulders.\",\"Keep your body in a straight line.\",\"Shift your weight to one arm and bend that elbow while the other arm stays straight.\",\"Lower your chest toward the bent arm side.\",\"Push back up and shift to the centre.\",\"Alternate or complete reps on one side, then switch.\"],\"img\":\"4153.webp\",\"gif\":\"4153.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push up where one arm does most of the work while the other extends out to the side. It builds unilateral chest and arm strength.\"},{\"id\":\"4601\",\"n\":\"open book stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"chest\"],\"st\":[\"Lie on your side with your knees bent and stacked, arms straight in front of you.\",\"Keep your knees together and lift the top arm up and over.\",\"Rotate your chest open toward the ceiling, following your hand with your eyes.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Return the arm and repeat, then switch sides.\"],\"img\":\"4601.webp\",\"gif\":\"4601.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying rotation that opens the chest and mid back, good for thoracic mobility and tight shoulders.\"},{\"id\":\"7216\",\"n\":\"opposite arm and leg raise against wall\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Stand facing a wall in a bent over position with your hands on it.\",\"Brace your core.\",\"Lift one arm and the opposite leg at the same time.\",\"Hold for a second without twisting.\",\"Lower and repeat on the other side.\"],\"img\":\"7216.webp\",\"gif\":\"7216.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wall-supported raise of the opposite arm and leg. It trains balance and lower back stability.\"},{\"id\":\"4992\",\"n\":\"opposite crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with hands lightly behind your head.\",\"Lift one leg bent while curling your torso up.\",\"Bring the opposite elbow toward the raised knee.\",\"Lower slowly with control.\",\"Alternate sides on each rep.\"],\"img\":\"4992.webp\",\"gif\":\"4992.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Crunch where opposite arm and leg move toward each other. It hits the abs and obliques together.\"},{\"id\":\"1788\",\"n\":\"over head straight arm stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"triceps\"],\"st\":[\"Stand tall and raise both straight arms overhead with your palms facing forward.\",\"Reach up and slightly back, keeping your ribs down and your core lightly braced.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1788.webp\",\"gif\":\"1788.mp4\",\"cat\":\"stretching\",\"desc\":\"Straight arms overhead lengthen the chest, shoulders and sides of your back. A simple full-reach stretch.\"},{\"id\":\"4665\",\"n\":\"overhead clap\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"triceps\"],\"st\":[\"Stand tall with your feet hip-width apart and arms at your sides.\",\"Raise both arms out to the sides and overhead.\",\"Clap your hands above your head.\",\"Lower your arms back to your sides with control.\",\"Keep your ribs down and move smoothly through your reps.\"],\"img\":\"4665.webp\",\"gif\":\"4665.mp4\",\"cat\":\"mobility\",\"desc\":\"Reaching your arms overhead and clapping to warm up the shoulders. It improves shoulder mobility and activation.\"},{\"id\":\"7417\",\"n\":\"overhead sit up with legs on bench\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"shoulders\"],\"st\":[\"Lie on your back with your calves resting on a bench, knees bent.\",\"Extend your arms overhead.\",\"Curl your torso up, keeping your arms by your ears.\",\"Reach toward your knees.\",\"Lower slowly.\"],\"img\":\"7417.webp\",\"gif\":\"7417.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Sit-up with arms overhead and calves on a bench for a longer lever on the abs.\"},{\"id\":\"3745\",\"n\":\"overhead triceps extension with bed sheet\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold a bed sheet with both hands behind your head, one hand pulling up, one down.\",\"Keep your elbows pointing forward.\",\"Press your top hand overhead against the resistance.\",\"Return slowly to the start.\",\"Finish your reps, then swap hand positions.\"],\"img\":\"3745.webp\",\"gif\":\"3745.mp4\",\"cat\":\"strength\",\"desc\":\"A home triceps exercise that uses a bed sheet as resistance.\"},{\"id\":\"5080\",\"n\":\"palm up palm down rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"forearms\"],\"st\":[\"Stand tall and raise your arms out to your sides at shoulder height.\",\"Turn your palms up so your thumbs point back.\",\"Rotate them down so your thumbs point forward.\",\"Keep your shoulders relaxed and your arms level.\",\"Repeat smoothly for 10-15 rotations.\"],\"img\":\"5080.webp\",\"gif\":\"5080.mp4\",\"cat\":\"mobility\",\"desc\":\"Hold your arms out and rotate your palms up and down. A simple warm-up for the shoulders and forearms.\",\"fv\":\"4666\"},{\"id\":\"2090\",\"n\":\"palms out forearm stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Stand or sit tall and interlace your fingers.\",\"Turn your palms outward and straighten your arms in front of you.\",\"Push your hands gently away until you feel the stretch in the forearms.\",\"Keep your shoulders relaxed.\",\"Hold for 20-30 seconds, then release.\"],\"img\":\"2090.webp\",\"gif\":\"2090.mp4\",\"cat\":\"stretching\",\"desc\":\"Clasped hands pressed forward with the palms facing out to stretch the forearms.\"},{\"id\":\"7554\",\"n\":\"parallel bars bent knee inverted row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\",\"core\"],\"st\":[\"Lie under parallel bars and grab them.\",\"Bend your knees with feet on the floor.\",\"Keep your body straight from shoulders to knees.\",\"Pull your chest to the bars.\",\"Lower slowly.\"],\"img\":\"7554.webp\",\"gif\":\"7554.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Easier bodyweight row under parallel bars with knees bent.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"9510\",\"n\":\"partner assisted pull up\",\"bp\":\"back\",\"eq\":\"assisted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Hang from a pull-up bar with an overhand grip.\",\"Have your partner hold your legs or hips.\",\"Pull your chest toward the bar.\",\"Pause at the top.\",\"Lower yourself slowly.\",\"Ask your partner to give just enough help.\"],\"img\":\"9510.webp\",\"gif\":\"9510.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up where a partner supports your legs or hips. It lets you build pulling strength while you work toward full reps.\"},{\"id\":\"5991\",\"n\":\"partner shuffle\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"calves\",\"glutes\"],\"st\":[\"Face a partner about 2 yards away in an athletic stance.\",\"Have your partner move left or right.\",\"Shuffle sideways to mirror them without crossing your feet.\",\"Keep your hips low and chest up.\",\"Work for 20-30 seconds, then swap roles.\"],\"img\":\"5991.webp\",\"gif\":\"5991.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A mirror drill where you shuffle sideways in response to a partner, training lateral quickness and reaction.\"},{\"id\":\"5017\",\"n\":\"pause squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"lower back\",\"core\"],\"st\":[\"Set the bar on your upper back and stand shoulder width apart.\",\"Brace your core and squat down to depth.\",\"Pause in the bottom for about two seconds, staying tight.\",\"Drive up through your whole foot.\",\"Keep your chest up and knees tracking over your toes.\"],\"img\":\"5017.webp\",\"gif\":\"5017.mp4\",\"cat\":\"strength\",\"desc\":\"Squat with a hold in the bottom position. It builds strength out of the hole and control.\"},{\"id\":\"6120\",\"n\":\"pavanamuktasana yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your legs straight.\",\"Bend your knees and draw them into your chest.\",\"Wrap your arms around your shins and hug them in.\",\"Keep your head and shoulders relaxed on the floor.\",\"Breathe slowly and hold for 20-30 seconds.\",\"Release and extend your legs.\"],\"img\":\"6120.webp\",\"gif\":\"6120.mp4\",\"cat\":\"yoga\",\"desc\":\"The wind-relieving pose, where you hug your knees to your chest while lying down. It stretches the hips and lower back.\"},{\"id\":\"6293\",\"n\":\"peacock pose mayurasana\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"wrist flexors\",\"shoulders\",\"core\"],\"st\":[\"Kneel and place your hands on the floor with fingers pointing back toward your feet.\",\"Bring your elbows together under your belly.\",\"Lean forward and rest your torso on your upper arms.\",\"Extend your legs back and lift them.\",\"Hold for a few breaths, then lower.\"],\"img\":\"6293.webp\",\"gif\":\"6293.mp4\",\"cat\":\"yoga\",\"desc\":\"An advanced arm balance with your torso held horizontally on your elbows. It builds core and wrist strength.\"},{\"id\":\"1943\",\"n\":\"pigeon hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Start on hands and knees and slide one knee forward behind your wrist.\",\"Extend the other leg straight behind you.\",\"Lower your hips toward the floor and keep your chest tall.\",\"Fold forward over the front leg for a deeper stretch if comfortable.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1943.webp\",\"gif\":\"1943.mp4\",\"cat\":\"yoga\",\"desc\":\"A yoga-style hip opener with one shin folded in front, stretching the glutes and the hip flexors of the back leg.\",\"fv\":\"2280\"},{\"id\":\"3904\",\"n\":\"pike press (between benches)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Place your hands on two benches shoulder-width apart and your feet on the floor.\",\"Lift your hips into a pike shape.\",\"Bend your elbows and lower your head between the benches.\",\"Press back up to straight arms.\",\"Keep your core tight.\",\"Keep your hips high throughout.\"],\"img\":\"3904.webp\",\"gif\":\"3904.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push-up with the hands on two benches so you can lower deeper, building the shoulders.\"},{\"id\":\"2921\",\"n\":\"pike push up\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Start in a push-up position, then walk your feet in and lift your hips into an inverted V.\",\"Keep your arms and back straight.\",\"Bend your elbows and lower the top of your head toward the floor.\",\"Press back up until your arms are straight.\",\"Keep your core tight throughout.\"],\"img\":\"2921.webp\",\"gif\":\"2921.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with hips lifted high so you press more overhead. It builds shoulder strength using only your body weight.\"},{\"id\":\"3401\",\"n\":\"pike push up (between benches)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Put your feet on one bench and your hands on the floor or a second bench.\",\"Raise your hips into a pike.\",\"Lower your head between your hands.\",\"Keep elbows at about 45 degrees.\",\"Press back up to straight arms.\",\"Keep your core tight.\"],\"img\":\"3401.webp\",\"gif\":\"3401.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push-up with your feet on one bench and your hands between benches for extra depth.\"},{\"id\":\"3402\",\"n\":\"pike push up (between chairs)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Set two sturdy chairs shoulder-width apart and grip them.\",\"Walk your feet back and lift your hips into a pike.\",\"Bend your elbows to lower your head between the chairs.\",\"Keep your back flat and elbows slightly in.\",\"Press back up.\",\"Make sure the chairs are stable.\"],\"img\":\"3402.webp\",\"gif\":\"3402.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push-up with your hands on two chairs so your head can drop lower.\"},{\"id\":\"2831\",\"n\":\"pike push up (on bench)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"upper back\"],\"st\":[\"Place your feet on a bench and your hands on the floor, hips raised in an inverted V.\",\"Keep your legs straight and your core braced.\",\"Bend your elbows and lower your head toward the floor.\",\"Press back up until your arms are straight.\",\"Keep your elbows at about 45 degrees to your body.\"],\"img\":\"2831.webp\",\"gif\":\"2831.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push up with your feet raised on a bench, shifting more load to the shoulders. A bodyweight alternative to the overhead press.\",\"fv\":\"2832\"},{\"id\":\"3383\",\"n\":\"pike push up (on bench) v. 2\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Place your feet on a bench and your hands on the floor, hips piked high.\",\"Walk your hands back until your body forms an inverted V.\",\"Bend your elbows and lower your head toward the floor.\",\"Keep your elbows at about 45 degrees from your body.\",\"Press back up until your arms are straight.\",\"Keep your core tight throughout.\"],\"img\":\"3383.webp\",\"gif\":\"3383.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push-up with your feet on a bench, loading the shoulders more than a flat push-up does.\"},{\"id\":\"9488\",\"n\":\"pike stand\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"hamstrings\",\"core\"],\"st\":[\"Start on all fours and walk your feet in while lifting your hips high.\",\"Form an upside-down V with straight arms and legs.\",\"Press the floor away and let your head hang between your arms.\",\"Keep your heels reaching toward the floor.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"9488.webp\",\"gif\":\"9488.mp4\",\"cat\":\"stretching\",\"desc\":\"A folded stance with hips high and head down, shifting weight over your hands. It opens the hamstrings and loads the shoulders.\"},{\"id\":\"3960\",\"n\":\"pike to cobra\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"lower back\"],\"st\":[\"Start on hands and toes with your hips high in an inverted V.\",\"Bend your elbows and glide your chest forward and down between your hands.\",\"Sweep forward and up, straightening your arms and lifting your chest into a cobra.\",\"Keep your legs active and look slightly forward.\",\"Reverse the path, pushing your hips back up into the pike, and repeat smoothly.\"],\"img\":\"3960.webp\",\"gif\":\"3960.mp4\",\"cat\":\"mobility\",\"desc\":\"A flowing bodyweight move that goes from a pike with hips high to a cobra with chest lifted. It warms up the shoulders, spine and hamstrings.\"},{\"id\":\"10854\",\"n\":\"pilates machine arm circle\",\"bp\":\"shoulders\",\"eq\":\"leverage machine\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"lats\",\"core\"],\"st\":[\"Lie on your back holding the straps with arms up.\",\"Bend your knees and brace your core.\",\"Lower your arms out to the sides.\",\"Circle them down and up in a smooth arc.\",\"Reverse the direction after a few reps.\",\"Keep your ribs down.\"],\"img\":\"10854.webp\",\"gif\":\"10854.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer arm circle holding straps. It works the shoulders and the upper back.\"},{\"id\":\"10855\",\"n\":\"pilates machine chest expansion\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"triceps\",\"core\"],\"st\":[\"Kneel facing the straps with your torso upright.\",\"Hold the straps with straight arms.\",\"Pull the straps back behind your body.\",\"Turn your head gently to each side.\",\"Return slowly to the start.\",\"Keep your chest lifted and ribs down.\"],\"img\":\"10855.webp\",\"gif\":\"10855.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer move pulling the straps behind you. It opens the chest and works the upper back.\"},{\"id\":\"10658\",\"n\":\"pilates machine hundred\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on the carriage holding the straps.\",\"Lift your head and legs.\",\"Pump your arms in small movements.\",\"Breathe in for five counts and out for five.\",\"Continue for 100 pumps.\"],\"img\":\"10658.webp\",\"gif\":\"10658.mp4\",\"cat\":\"pilates\",\"desc\":\"Pump your arms against the straps while holding your legs up. It builds core endurance.\"},{\"id\":\"10853\",\"n\":\"pilates machine long spine\",\"bp\":\"back\",\"eq\":\"leverage machine\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"glutes\"],\"st\":[\"Lie on your back with your feet against the shoulder rests.\",\"Press your legs straight up.\",\"Roll your hips off the pad.\",\"Lift your hips over your shoulders.\",\"Roll down slowly one vertebra at a time.\",\"Avoid pressing on your neck.\"],\"img\":\"10853.webp\",\"gif\":\"10853.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer roll-over that mobilises the spine. It stretches the back and works the abs.\"},{\"id\":\"10657\",\"n\":\"pilates machine lying calf raise\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Lie on the carriage with legs straight, balls of feet on the bar.\",\"Press your heels down.\",\"Rise up onto your toes.\",\"Return slowly.\",\"Keep your knees locked softly.\"],\"img\":\"10657.webp\",\"gif\":\"10657.mp4\",\"cat\":\"pilates\",\"desc\":\"Press the carriage with just your toes on a reformer. It builds calf strength.\"},{\"id\":\"10847\",\"n\":\"pilates machine lying frog and leg circle\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"inner thighs\",\"core\"],\"st\":[\"Lie on the reformer with your feet in the straps or on the bar.\",\"Bend your knees and open them out, heels together, in a frog shape.\",\"Press your legs straight.\",\"Circle them out, around and back together.\",\"Reverse the circle direction after a few reps.\",\"Keep your back steady on the pad.\"],\"img\":\"10847.webp\",\"gif\":\"10847.mp4\",\"cat\":\"pilates\",\"desc\":\"Reformer leg work: frog press followed by circles. It trains the hips and inner thighs with control.\"},{\"id\":\"10655\",\"n\":\"pilates machine lying knee extension\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"core\"],\"st\":[\"Lie on the carriage with feet on the bar.\",\"Bend your knees.\",\"Press out until legs are straight.\",\"Return slowly.\",\"Keep your lower back stable.\"],\"img\":\"10655.webp\",\"gif\":\"10655.mp4\",\"cat\":\"pilates\",\"desc\":\"Straighten your knees on a reformer with feet flat. It trains the front thighs.\"},{\"id\":\"10656\",\"n\":\"pilates machine lying knee extension on heels\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on the carriage with heels on the bar.\",\"Bend your knees.\",\"Press out through the heels until straight.\",\"Return slowly.\",\"Keep your hips level.\"],\"img\":\"10656.webp\",\"gif\":\"10656.mp4\",\"cat\":\"pilates\",\"desc\":\"Straighten your knees on a reformer pressing through the heels. It works the thighs.\"},{\"id\":\"10654\",\"n\":\"pilates machine lying knee extension on toes\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"core\"],\"st\":[\"Lie on the carriage with feet on the bar, on your toes.\",\"Bend your knees with a neutral spine.\",\"Press the carriage away until legs straighten.\",\"Return under control.\",\"Keep your hips still.\"],\"img\":\"10654.webp\",\"gif\":\"10654.mp4\",\"cat\":\"pilates\",\"desc\":\"Straighten your knees on a reformer with feet on toes. It trains the front thighs.\"},{\"id\":\"10849\",\"n\":\"pilates machine lying pelvic lift\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with your feet on the bar and knees bent.\",\"Press your arms into the pad.\",\"Lift your hips one vertebra at a time.\",\"Hold at the top.\",\"Roll down slowly.\",\"Keep your ribs relaxed.\"],\"img\":\"10849.webp\",\"gif\":\"10849.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer bridge that lifts the hips. It strengthens the glutes and hamstrings.\"},{\"id\":\"10848\",\"n\":\"pilates machine lying running\",\"bp\":\"lower legs\",\"eq\":\"leverage machine\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"core\"],\"st\":[\"Lie on the reformer with the balls of your feet on the bar.\",\"Straighten both legs.\",\"Lower one heel while bending the other knee.\",\"Alternate smoothly.\",\"Keep your pelvis still.\",\"Maintain steady breathing.\"],\"img\":\"10848.webp\",\"gif\":\"10848.mp4\",\"cat\":\"pilates\",\"desc\":\"Reformer footwork that alternates the legs like running. It trains the calves, quads and glutes.\"},{\"id\":\"10856\",\"n\":\"pilates machine overhead\",\"bp\":\"waist\",\"eq\":\"leverage machine\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\"],\"st\":[\"Sit or kneel on the carriage holding the straps overhead.\",\"Brace your core.\",\"Press the straps forward and down in a controlled arc.\",\"Return to the overhead position.\",\"Keep your spine tall.\",\"Move smoothly with breath.\"],\"img\":\"10856.webp\",\"gif\":\"10856.mp4\",\"cat\":\"pilates\",\"desc\":\"Reformer work with straps overhead. It trains the shoulders, abs and posture.\"},{\"id\":\"10852\",\"n\":\"pilates machine russian split\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Place one foot on the carriage and one on the platform.\",\"Stand tall with your core braced.\",\"Slide the carriage back while lowering into a split squat.\",\"Pause.\",\"Press back to the start.\",\"Switch sides after your set.\"],\"img\":\"10852.webp\",\"gif\":\"10852.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer split stance with the carriage sliding. It works the legs, glutes and balance.\"},{\"id\":\"10851\",\"n\":\"pilates machine russian squat\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set your feet on the carriage and platform.\",\"Stand tall and brace your core.\",\"Bend your knees into a squat.\",\"Keep your chest lifted and knees over toes.\",\"Press back up to standing.\",\"Move with the carriage smoothly.\"],\"img\":\"10851.webp\",\"gif\":\"10851.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer squat variation that builds the legs. It focuses on controlled bending and straightening.\"},{\"id\":\"10850\",\"n\":\"pilates machine side split\",\"bp\":\"upper legs\",\"eq\":\"leverage machine\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"glutes\",\"core\"],\"st\":[\"Stand with one foot on the carriage and one on the platform.\",\"Brace your core.\",\"Slide the carriage out to widen your stance.\",\"Pause.\",\"Draw it back under control with your inner thighs.\",\"Keep your hips square.\"],\"img\":\"10850.webp\",\"gif\":\"10850.mp4\",\"cat\":\"pilates\",\"desc\":\"A reformer move where you open and close the legs sideways. It works the inner thighs and balance.\"},{\"id\":\"2984\",\"n\":\"pistol squat to box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Stand in front of a box with one leg extended forward.\",\"Brace your core and reach your arms forward for balance.\",\"Sit back and down slowly on the standing leg until you touch the box.\",\"Drive through your heel to stand.\",\"Finish the reps, then switch legs.\"],\"img\":\"2984.webp\",\"gif\":\"2984.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat down to a box. The box gives you a target for depth as you build strength.\",\"fv\":\"2985\"},{\"id\":\"4004\",\"n\":\"place jog\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"hip flexors\"],\"st\":[\"Stand tall with your arms bent.\",\"Jog in place, lifting your knees.\",\"Land softly on the balls of your feet.\",\"Keep a steady pace.\",\"Continue for 1-5 minutes.\"],\"img\":\"4004.webp\",\"gif\":\"4004.mp4\",\"cat\":\"cardio\",\"desc\":\"Jogging on the spot as a warm-up or light cardio. It raises your heart rate without equipment.\",\"fv\":\"0644\"},{\"id\":\"7415\",\"n\":\"planche dip on parallel bars\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\",\"hands\"],\"st\":[\"Support yourself on parallel bars with straight arms.\",\"Lean forward and shift your weight over your hands.\",\"Bend your elbows to lower your body under control.\",\"Keep your core tight and elbows close.\",\"Press back up to straight arms.\"],\"img\":\"7415.webp\",\"gif\":\"7415.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Dip with a leaning body angle that loads the shoulders and triceps hard.\"},{\"id\":\"10664\",\"n\":\"planche press\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"core\",\"triceps\",\"wrist flexors\"],\"st\":[\"Start in a deep planche lean with hands under your shoulders.\",\"Protract your shoulders and squeeze your glutes.\",\"Lean forward and lift your feet from the floor.\",\"Press into the ground and hold the position.\",\"Lower under control.\",\"Warm up your wrists first.\"],\"img\":\"10664.webp\",\"gif\":\"10664.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced gymnastics skill where you press from a lean into a planche shape. It builds shoulder strength and a strong core.\"},{\"id\":\"6804\",\"n\":\"plank alternate anti gravity pull up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"core\",\"lats\"],\"st\":[\"Start in a forearm or high plank with your body in a straight line.\",\"Brace your core and squeeze your glutes.\",\"Pull one arm up and back toward your ribs.\",\"Return it to the floor under control.\",\"Alternate arms without rocking your hips.\"],\"img\":\"6804.webp\",\"gif\":\"6804.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank you alternately pull one arm up toward your chest as if climbing. It builds core stability and shoulder control.\"},{\"id\":\"10554\",\"n\":\"plank alternating hit the ball\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"obliques\"],\"st\":[\"Start in a straight-arm plank with a ball in front of you.\",\"Tighten your core and glutes.\",\"Lift one hand and tap the ball.\",\"Return the hand and tap with the other.\",\"Keep your hips as still as possible.\"],\"img\":\"10554.webp\",\"gif\":\"10554.mp4\",\"cat\":\"isometric\",\"desc\":\"From a plank, tap a ball with alternating hands. It challenges your core to stay stable.\"},{\"id\":\"1440\",\"n\":\"plank arm lifts\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"glutes\",\"upper back\"],\"st\":[\"Get into a forearm or high plank with your body in a straight line.\",\"Brace your abs and squeeze your glutes.\",\"Lift one arm forward without letting your hips rotate.\",\"Place it back down with control and lift the other.\",\"Keep your neck neutral and alternate arms for the planned reps.\"],\"img\":\"1440.webp\",\"gif\":\"1440.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank where you lift one arm at a time, training core stability and anti-rotation strength.\"},{\"id\":\"2358\",\"n\":\"plank butt (form check)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Set your forearms on the floor with elbows under the shoulders and legs extended.\",\"Compare the faulty version with the correct one: your butt stays level with your shoulders, not piked up or sagging down.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2358.webp\",\"gif\":\"2358.mp4\",\"cat\":\"isometric\",\"desc\":\"A side-by-side form check for hip position in a plank, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"3930\",\"n\":\"plank jack\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"hip flexors\"],\"st\":[\"Start in a forearm or high plank with your body in a straight line.\",\"Jump both feet out wide.\",\"Jump them back together.\",\"Keep your hips level and your abs tight throughout.\",\"Continue for the planned reps or time.\"],\"img\":\"3930.webp\",\"gif\":\"3930.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank where your feet jump apart and together like a jumping jack. It trains the core and raises your heart rate.\",\"fv\":\"4642\"},{\"id\":\"5157\",\"n\":\"plank jack on elbows\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"hip flexors\"],\"st\":[\"Get into a forearm plank with your elbows under your shoulders.\",\"Keep your body in a straight line.\",\"Jump your feet wide apart.\",\"Jump them back together.\",\"Keep your hips level and continue for 20-40 seconds.\"],\"img\":\"5157.webp\",\"gif\":\"5157.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Hold a forearm plank and jump your feet apart and together. It trains the core while raising your heart rate.\"},{\"id\":\"5158\",\"n\":\"plank jack slide with towel\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"adductors\",\"groin\"],\"st\":[\"Put your feet on towels on a smooth floor and get into a high plank.\",\"Brace your core.\",\"Slide your feet wide apart.\",\"Slide them back together.\",\"Keep your hips level and repeat.\"],\"img\":\"5158.webp\",\"gif\":\"5158.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank, slide your feet apart and together on towels. It works the core and hips without any impact.\"},{\"id\":\"2792\",\"n\":\"plank jump\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"quadriceps\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Jump both feet out wide.\",\"Jump them back together.\",\"Keep your hips level and core tight.\",\"Move at a steady pace.\"],\"img\":\"2792.webp\",\"gif\":\"2792.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping plank drill that raises your heart rate and challenges the core.\"},{\"id\":\"10326\",\"n\":\"plank jump in squat\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Start in a high plank with hands under shoulders.\",\"Jump both feet forward, landing outside your hands in a wide squat.\",\"Stand or hop up briefly if you like, then lower your hands.\",\"Jump your feet back to the plank.\",\"Keep a tight core and land softly.\"],\"img\":\"10326.webp\",\"gif\":\"10326.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A fast move from a plank to a squat jump position, raising the heart rate and training the legs and core.\"},{\"id\":\"9999\",\"n\":\"plank knee tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Start in a forearm or high plank.\",\"Brace your core.\",\"Lower one knee gently toward the floor.\",\"Return it and switch sides.\",\"Keep your hips level.\",\"Breathe steadily.\"],\"img\":\"9999.webp\",\"gif\":\"9999.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank with alternating knee taps to the floor. It trains the abs and anti-rotation control.\"},{\"id\":\"3852\",\"n\":\"plank lateral raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Brace your abs and keep your hips level.\",\"Lift one arm out to the side to shoulder height.\",\"Lower it with control.\",\"Alternate arms and avoid twisting.\"],\"img\":\"3852.webp\",\"gif\":\"3852.mp4\",\"cat\":\"strength\",\"desc\":\"A plank where you lift one arm out to the side. It challenges your core and shoulders.\"},{\"id\":\"9821\",\"n\":\"plank leg lift mountain climber\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with hands under your shoulders.\",\"Lift one leg straight back.\",\"Bring that knee in toward your chest.\",\"Return and switch legs.\",\"Keep your hips level and your core tight.\"],\"img\":\"9821.webp\",\"gif\":\"9821.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank with a leg lift into a mountain climber. It trains the core and raises the heart rate.\"},{\"id\":\"5159\",\"n\":\"plank on hands\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Place your hands under your shoulders and extend your legs behind you.\",\"Tuck your toes and lift your hips so the body forms a straight line.\",\"Squeeze your glutes and brace your abs.\",\"Keep your neck neutral and look at the floor.\",\"Hold for 20-40 seconds, then lower your knees.\"],\"img\":\"5159.webp\",\"gif\":\"5159.mp4\",\"cat\":\"isometric\",\"desc\":\"A straight-arm plank held on the hands. It builds trunk stiffness and shoulder stability.\",\"hd\":1},{\"id\":\"5165\",\"n\":\"plank pike slide with towel\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"hip flexors\",\"obliques\"],\"st\":[\"Put your toes on towels on a smooth floor and get into a straight-arm plank.\",\"Brace your abs and keep your arms straight.\",\"Slide your feet toward your hands as your hips rise into a pike.\",\"Pause briefly at the top.\",\"Slide your feet back to the plank without letting your hips drop.\"],\"img\":\"5165.webp\",\"gif\":\"5165.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with your feet on towels, slide your feet in to lift the hips into a pike. It hits your abs hard and challenges shoulder stability.\"},{\"id\":\"2961\",\"n\":\"plank push up row\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"chest\",\"triceps\",\"core\",\"shoulders\"],\"st\":[\"Start in a plank with a dumbbell in each hand and your feet wide.\",\"Do a push-up, keeping your body straight.\",\"Row one dumbbell up to your ribs without twisting your hips.\",\"Lower it and row the other side.\",\"Repeat the sequence with control.\"],\"img\":\"2961.webp\",\"gif\":\"2961.mp4\",\"cat\":\"strength\",\"desc\":\"A plank sequence combining a push-up and a row. It trains the chest, back and core in one flowing move.\"},{\"id\":\"9677\",\"n\":\"plank side jump\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"quadriceps\",\"core\"],\"st\":[\"Start in a high plank with hands under your shoulders.\",\"Brace your abs and keep your back flat.\",\"Jump both feet a short way to one side.\",\"Jump them back through the centre to the other side.\",\"Keep a steady rhythm for 20-30 seconds.\"],\"img\":\"9677.webp\",\"gif\":\"9677.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank, you hop your feet side to side. It challenges the core and gets your heart rate up.\"},{\"id\":\"2793\",\"n\":\"plank walk up\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\",\"chest\"],\"st\":[\"Start in a forearm plank.\",\"Place one hand and then the other on the floor to rise to a high plank.\",\"Lower one forearm and then the other back down.\",\"Keep your hips steady.\",\"Alternate the leading arm each rep.\"],\"img\":\"2793.webp\",\"gif\":\"2793.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Moving between a forearm and a high plank, building core and arm endurance.\"},{\"id\":\"1920\",\"n\":\"plantar flexion stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit on a chair or the floor with one leg extended.\",\"Point your toes away from you as far as is comfortable.\",\"Gently press the top of the foot with your hand for a little extra stretch.\",\"Keep the movement slow and avoid forcing the ankle.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1920.webp\",\"gif\":\"1920.mp4\",\"cat\":\"stretching\",\"desc\":\"Pointing the foot downward to stretch the front of the ankle and shin.\"},{\"id\":\"1926\",\"n\":\"plantar flexor and foot everter stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with one leg extended and hold the foot with your hand.\",\"Point the foot down and turn the sole slightly outward.\",\"Gently press the foot until you feel a stretch along the front and outer ankle.\",\"Move slowly and stop at a mild stretch.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1926.webp\",\"gif\":\"1926.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated ankle stretch that lengthens the calf and the outer side of the lower leg.\"},{\"id\":\"1927\",\"n\":\"plantar flexor and foot inverter stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with one leg extended and hold the foot with your hand.\",\"Point the foot down and turn the sole slightly inward.\",\"Gently press the foot until you feel a stretch along the front and inner ankle.\",\"Move slowly and stop at a mild stretch.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1927.webp\",\"gif\":\"1927.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated ankle stretch that lengthens the front of the lower leg and the inner side of the ankle.\"},{\"id\":\"1234\",\"n\":\"plate hyperextension\",\"bp\":\"back\",\"eq\":\"weight plate\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Set the hyperextension bench so your hips are just past the pad.\",\"Hold a weight plate against your chest and cross your arms over it.\",\"Lower your torso toward the floor with a flat back.\",\"Raise your torso until your body forms a straight line.\",\"Squeeze your glutes at the top and avoid overarching.\"],\"img\":\"1234.webp\",\"gif\":\"1234.mp4\",\"cat\":\"strength\",\"desc\":\"A back extension holding a plate at your chest. It strengthens the lower back, glutes and hamstrings.\"},{\"id\":\"1044\",\"n\":\"plate pinch\",\"bp\":\"lower arms\",\"eq\":\"weight plate\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"hands\",\"wrist flexors\"],\"st\":[\"Pick up two smooth plates and stack them with the smooth sides facing out.\",\"Pinch them together with your fingertips and thumb.\",\"Stand tall with your arm hanging by your side.\",\"Hold for 20-30 seconds without letting the plates slip.\",\"Switch hands and repeat.\"],\"img\":\"1044.webp\",\"gif\":\"1044.mp4\",\"cat\":\"isometric\",\"desc\":\"Pinch a weight plate between your fingers and thumb and hold it. It builds finger and thumb grip strength.\",\"hd\":1},{\"id\":\"7882\",\"n\":\"plate push\",\"bp\":\"chest\",\"eq\":\"weight plate\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Stand with a weight plate held at your chest, elbows bent.\",\"Brace your abs and bend your knees slightly.\",\"Push the plate out explosively with both arms.\",\"Fully extend your arms.\",\"Pull the plate back to your chest with control.\",\"Repeat for the planned reps.\"],\"img\":\"7882.webp\",\"gif\":\"7882.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive push of a weight plate out from your chest for upper-body power.\"},{\"id\":\"1485\",\"n\":\"plow yoga pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"upper back\"],\"st\":[\"Lie on your back with your arms by your sides.\",\"Lift your legs and hips up and over, supporting your lower back with your hands if needed.\",\"Lower your toes toward the floor behind your head.\",\"Keep your neck relaxed and do not turn your head.\",\"Hold for 15-30 seconds, then roll down slowly one vertebra at a time.\"],\"img\":\"1485.webp\",\"gif\":\"1485.mp4\",\"cat\":\"yoga\",\"desc\":\"An inverted yoga pose where the legs are lowered behind the head. It stretches the spine, shoulders and hamstrings.\"},{\"id\":\"3108\",\"n\":\"plyo jacks\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"shoulders\"],\"st\":[\"Stand with your feet together.\",\"Jump your feet wide and land in a quarter squat.\",\"Swing your arms out as you land.\",\"Jump your feet back together.\",\"Land softly each time.\",\"Keep a quick, controlled pace.\"],\"img\":\"3108.webp\",\"gif\":\"3108.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping jack with a squat landing. The extra depth makes it harder on the legs and your heart.\",\"fv\":\"0645\"},{\"id\":\"11717\",\"n\":\"plyo push up v. 2\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with hands under your shoulders.\",\"Lower your chest toward the floor with control.\",\"Explode upward so your hands leave the ground.\",\"Land softly with slightly bent elbows.\",\"Reset your body line and repeat.\"],\"img\":\"11717.webp\",\"gif\":\"11717.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive push-up variation where your hands leave the floor, building upper-body power.\"},{\"id\":\"4675\",\"n\":\"plyo side lunge stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"groin\"],\"st\":[\"Stand with feet wide apart.\",\"Shift your weight to one side and sit into a side lunge.\",\"Straighten the other leg and feel the inner thigh stretch.\",\"Push off to hop to the other side.\",\"Continue alternating at a controlled pace.\"],\"img\":\"4675.webp\",\"gif\":\"4675.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bouncy side lunge that stretches the inner thighs and trains light explosive movement.\",\"fv\":\"0646\"},{\"id\":\"0647\",\"n\":\"plyo sit squat (wall)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with your back close to a wall, feet shoulder width apart.\",\"Lower into a wall sit with your thighs parallel to the floor.\",\"Drive through your feet and jump up explosively.\",\"Land softly with bent knees.\",\"Drop straight back into the sit and repeat.\",\"Keep your chest tall and land quietly.\"],\"img\":\"0647.webp\",\"gif\":\"0647.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping variation of the wall sit. You drop into a wall squat and then explode upward, building leg power.\"},{\"id\":\"5745\",\"n\":\"plyo squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Sit into a squat with your chest up.\",\"Explode upward and jump as high as you can.\",\"Land softly on bent knees and go straight into the next squat.\",\"Keep your knees tracking over your toes.\"],\"img\":\"5745.webp\",\"gif\":\"5745.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat followed by an explosive jump. Builds power and conditioning in the legs.\"},{\"id\":\"5974\",\"n\":\"plyometric agility drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"glutes\",\"core\"],\"st\":[\"Set out a few markers within a small area.\",\"Stand in an athletic stance on the balls of your feet.\",\"Hop or step quickly between the markers in changing directions.\",\"Land softly with bent knees.\",\"Work for 20-30 seconds, rest, then repeat.\"],\"img\":\"5974.webp\",\"gif\":\"5974.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A mix of quick hops and direction changes that builds explosive power and agility.\"},{\"id\":\"9070\",\"n\":\"pogo jump 2 foot\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"quadriceps\"],\"st\":[\"Stand tall with your knees nearly straight.\",\"Hop off the balls of your feet.\",\"Keep your heels off the ground.\",\"Bounce quickly with minimal knee bend.\",\"Stay light and quiet on landing.\",\"Go for a set time or number of hops.\"],\"img\":\"9070.webp\",\"gif\":\"9070.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Small, quick hops off the balls of both feet. It builds calf and ankle stiffness and bounce.\"},{\"id\":\"6793\",\"n\":\"posterior chain flexibility test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"calves\",\"glutes\"],\"st\":[\"Stand with your feet together and your knees straight.\",\"Hinge at the hips and slowly reach down toward your toes.\",\"Let your head and arms hang relaxed without bouncing.\",\"Note how far your fingertips reach.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Rise slowly, rolling up one vertebra at a time.\"],\"img\":\"6793.webp\",\"gif\":\"6793.mp4\",\"cat\":\"stretching\",\"desc\":\"A forward-fold style check of how flexible the back of your body is, from calves up to your lower back.\"},{\"id\":\"5145\",\"n\":\"posterior neck isometric\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Sit or stand tall with your hands clasped behind your head.\",\"Keep your chin level.\",\"Press your head back into your hands without letting it move.\",\"Hold for 5-10 seconds.\",\"Relax and repeat a few times.\"],\"img\":\"5145.webp\",\"gif\":\"5145.mp4\",\"cat\":\"isometric\",\"desc\":\"Press the back of your head into your hands without moving. It strengthens the muscles at the back of the neck.\",\"hd\":1},{\"id\":\"5188\",\"n\":\"power clean thruster\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"hamstrings\",\"core\"],\"st\":[\"Set up with the barbell over mid-foot and grip it just outside your knees.\",\"Pull the bar explosively and catch it on your shoulders in a quarter squat.\",\"Stand, then sink into a full front squat.\",\"Drive up and press the bar overhead.\",\"Lower the bar to your shoulders and then to the floor with control.\"],\"img\":\"5188.webp\",\"gif\":\"5188.mp4\",\"cat\":\"olympic\",\"desc\":\"A power clean flowing straight into a front squat and overhead press. It is a big full-body power movement.\"},{\"id\":\"3555\",\"n\":\"power push aways\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"shoulders\",\"core\"],\"st\":[\"Stand facing a wall and lean in with arms extended.\",\"Push away from the wall forcefully.\",\"Retract your shoulder blades as you reach back.\",\"Return to the wall with control.\",\"Keep your core tight.\",\"Reset between reps.\"],\"img\":\"3555.webp\",\"gif\":\"3555.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An explosive push away from a wall or support to train the upper back.\"},{\"id\":\"2908\",\"n\":\"power sled anti rotation forward walk\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Set a light load and stand side-on to the pull, gripping the handle at chest height.\",\"Brace your abs and keep your hips and shoulders square.\",\"Walk forward in controlled steps without letting the torso twist.\",\"Walk the set distance, then reset and repeat.\",\"Switch sides and do the same distance.\"],\"img\":\"2908.webp\",\"gif\":\"2908.mp4\",\"cat\":\"strength\",\"desc\":\"Walking a loaded sled forward while resisting twist from a side-on pull or hold. It builds hip and trunk stability under load.\"},{\"id\":\"2907\",\"n\":\"power sled backward push\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\",\"hamstrings\"],\"st\":[\"Stand behind the sled with your back to it and grip the handles.\",\"Brace your core and lean slightly into the load.\",\"Walk forward in powerful steps, pushing the sled.\",\"Keep your stride steady and breathing controlled.\",\"Cover a set distance, then rest.\"],\"img\":\"2907.webp\",\"gif\":\"2907.mp4\",\"cat\":\"strength\",\"desc\":\"Pushing a power sled while walking backward. Builds quad strength and conditioning.\"},{\"id\":\"2901\",\"n\":\"power sled biceps curl\",\"bp\":\"upper arms\",\"eq\":\"sled machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand facing the sled and grip the handle or strap with an underhand grip.\",\"Keep your elbows tucked at your sides.\",\"Curl your hands up toward your shoulders, moving the sled.\",\"Squeeze your biceps at the top.\",\"Lower slowly and keep your torso still.\"],\"img\":\"2901.webp\",\"gif\":\"2901.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl using a power sled as the resistance. Adds a unique load for arm strength.\"},{\"id\":\"5143\",\"n\":\"power sled drag\",\"bp\":\"full body\",\"eq\":\"sled machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Load a sled and attach a harness or straps.\",\"Lean slightly forward and brace your core.\",\"Walk with powerful steps, pushing through the balls of your feet.\",\"Keep your back straight.\",\"Cover a set distance, then rest and repeat.\"],\"img\":\"5143.webp\",\"gif\":\"5143.mp4\",\"cat\":\"strength\",\"desc\":\"Drag a loaded sled behind you by walking backward or forward. It builds leg drive and conditioning.\"},{\"id\":\"2909\",\"n\":\"power sled high pull\",\"bp\":\"shoulders\",\"eq\":\"sled machine\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"biceps\",\"glutes\"],\"st\":[\"Stand facing the sled and hold the handles or rope with arms long.\",\"Hinge slightly at the hips with a flat back.\",\"Drive your hips forward and pull the handles up toward your chest, elbows high.\",\"Pause briefly at the top.\",\"Lower under control and repeat.\"],\"img\":\"2909.webp\",\"gif\":\"2909.mp4\",\"cat\":\"strength\",\"desc\":\"A pull from low to chest height on a sled, using hip drive. It trains the shoulders and upper back with a bit of power.\"},{\"id\":\"9939\",\"n\":\"power sled pull\",\"bp\":\"back\",\"eq\":\"sled machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"hamstrings\",\"glutes\",\"forearms\"],\"st\":[\"Attach a rope or strap to a loaded sled and grip it with both hands.\",\"Face the sled, hinge slightly and set your feet.\",\"Pull the rope hand over hand while walking backward.\",\"Keep your chest up and your back straight.\",\"Drive through your legs as the sled comes toward you.\",\"Stop when the sled reaches you and reset.\"],\"img\":\"9939.webp\",\"gif\":\"9939.mp4\",\"cat\":\"strength\",\"desc\":\"A drag-style move where you pull a loaded sled toward you with a rope or strap, walking backward. It trains the back, arms and legs together.\"},{\"id\":\"2563\",\"n\":\"power sled pull row\",\"bp\":\"back\",\"eq\":\"sled machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"hamstrings\",\"core\"],\"st\":[\"Attach a rope or handles to a loaded sled.\",\"Hold the rope with your knees slightly bent.\",\"Pull the sled toward you with a rowing motion.\",\"Squeeze your shoulder blades.\",\"Keep your back flat.\",\"Repeat for the planned distance.\"],\"img\":\"2563.webp\",\"gif\":\"2563.mp4\",\"cat\":\"strength\",\"desc\":\"A row performed while pulling a loaded sled for back and grip strength.\"},{\"id\":\"4428\",\"n\":\"power sled push\",\"bp\":\"full body\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\",\"shoulders\"],\"st\":[\"Load the sled and grip the handles at chest or hip height.\",\"Lean forward with a straight body line.\",\"Drive through your legs with powerful steps.\",\"Keep your core tight and push the sled forward.\",\"Maintain a steady pace for the set distance.\"],\"img\":\"4428.webp\",\"gif\":\"4428.mp4\",\"cat\":\"strength\",\"desc\":\"A heavy sled push that builds leg drive and conditioning.\",\"fv\":\"2524\"},{\"id\":\"2904\",\"n\":\"power sled rear batwing\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"upper back\",\"core\"],\"st\":[\"Hold the sled handles and hinge slightly at the hips.\",\"Keep your back flat and knees soft.\",\"Pull the handles back and out to the sides like wings.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the start.\"],\"img\":\"2904.webp\",\"gif\":\"2904.mp4\",\"cat\":\"strength\",\"desc\":\"A movement with a power sled where you pull the handles out and back like wings. Works the hamstrings, back and rear shoulders.\"},{\"id\":\"2906\",\"n\":\"power sled rear drag\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Face the sled, holding its handles or straps with a slight lean back.\",\"Keep your chest up and core braced.\",\"Walk backward in steady steps, pulling the sled with you.\",\"Keep your knees soft and drive through your legs.\",\"Cover a set distance, then rest.\"],\"img\":\"2906.webp\",\"gif\":\"2906.mp4\",\"cat\":\"strength\",\"desc\":\"Walking backward while dragging a power sled. Great for quads and conditioning with low joint stress.\"},{\"id\":\"5193\",\"n\":\"power sled rear drag v. 2\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Load the sled and grip the handles or strap in front of you.\",\"Lean slightly back with your chest up.\",\"Walk backward in small, powerful steps.\",\"Keep your knees soft and your core tight.\",\"Cover your distance, then rest and repeat.\"],\"img\":\"5193.webp\",\"gif\":\"5193.mp4\",\"cat\":\"strength\",\"desc\":\"Dragging a weighted sled backward while walking. It builds thigh strength with very little joint impact.\"},{\"id\":\"2905\",\"n\":\"power sled rear fly\",\"bp\":\"shoulders\",\"eq\":\"sled machine\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"core\"],\"st\":[\"Hold the sled handles with arms out in front and hinge slightly at the hips.\",\"Keep a slight bend in your elbows.\",\"Sweep your arms out to the sides, squeezing your shoulder blades.\",\"Pause briefly.\",\"Return slowly.\"],\"img\":\"2905.webp\",\"gif\":\"2905.mp4\",\"cat\":\"strength\",\"desc\":\"A rear fly done with a power sled for resistance. Works the rear shoulders and upper back.\"},{\"id\":\"2830\",\"n\":\"power sled rear lunge\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold the sled handles and stand tall with your feet together.\",\"Step one foot back into a lunge, lowering your back knee toward the floor.\",\"Keep your torso upright and your front knee over your ankle.\",\"Push through the front foot to return to standing.\",\"Alternate legs on each rep.\"],\"img\":\"2830.webp\",\"gif\":\"2830.mp4\",\"cat\":\"strength\",\"desc\":\"A rear lunge while pushing or holding a power sled. Builds leg strength with extra resistance.\",\"fv\":\"2829\"},{\"id\":\"2902\",\"n\":\"power sled rear lunge row\",\"bp\":\"back\",\"eq\":\"sled machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"quadriceps\",\"glutes\",\"biceps\",\"core\"],\"st\":[\"Hold the sled handles with arms extended and feet together.\",\"Step back into a rear lunge, lowering your back knee.\",\"As you rise, row the handles toward your ribs, squeezing your shoulder blades.\",\"Return to standing and extend your arms.\",\"Alternate legs on each rep.\"],\"img\":\"2902.webp\",\"gif\":\"2902.mp4\",\"cat\":\"strength\",\"desc\":\"A rear lunge combined with a row using a power sled. Works legs and back together.\"},{\"id\":\"2903\",\"n\":\"power sled rear lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold the sled handles and stand tall with feet together.\",\"Step one foot back into a lunge, lowering your back knee toward the floor.\",\"Keep your torso upright.\",\"Push through the front foot to return to standing.\",\"Alternate legs on each rep.\"],\"img\":\"2903.webp\",\"gif\":\"2903.mp4\",\"cat\":\"strength\",\"desc\":\"A rear lunge using a power sled for resistance. Builds glute and thigh strength.\"},{\"id\":\"4119\",\"n\":\"power sled triceps extension\",\"bp\":\"upper arms\",\"eq\":\"sled machine\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Set up on the sled and grip the handles or bar.\",\"Keep your elbows tucked.\",\"Extend your arms to straighten them.\",\"Squeeze your triceps at the end.\",\"Return slowly.\"],\"img\":\"4119.webp\",\"gif\":\"4119.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension done on a sled machine, giving steady load through the whole motion.\"},{\"id\":\"3197\",\"n\":\"prancing\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"hip flexors\",\"quadriceps\",\"core\"],\"st\":[\"Stand tall and relaxed.\",\"Move forward in a bouncy trot.\",\"Lift each knee up with a springy step.\",\"Stay on the balls of your feet.\",\"Swing your arms in rhythm.\",\"Continue for 30-60 seconds.\"],\"img\":\"3197.webp\",\"gif\":\"3197.mp4\",\"cat\":\"cardio\",\"desc\":\"A light, springy trot with high knees, like a pony. It's a fun cardio warm-up.\"},{\"id\":\"4876\",\"n\":\"prayer push\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Stand or sit tall and press your palms together at chest height.\",\"Point your fingers up and keep your elbows out.\",\"Push your palms firmly into each other.\",\"Hold the squeeze for 5-10 seconds.\",\"Relax and shake out your arms.\",\"Repeat for several rounds.\"],\"img\":\"4876.webp\",\"gif\":\"4876.mp4\",\"cat\":\"isometric\",\"desc\":\"Pressing your palms together in front of your chest. It activates the chest and shoulders without any equipment.\"},{\"id\":\"4387\",\"n\":\"prayer squat yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"hip flexors\",\"groin\"],\"st\":[\"Stand with feet wider than hips and toes turned out.\",\"Lower into a deep squat, keeping your heels down if you can.\",\"Press your palms together at your chest.\",\"Use your elbows to gently press your knees outward.\",\"Hold for 30-60 seconds while breathing slowly.\"],\"img\":\"4387.webp\",\"gif\":\"4387.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep squat with palms together that opens the hips and inner thighs and builds ankle and hip mobility.\"},{\"id\":\"2348\",\"n\":\"preacher curl wrists (form check)\",\"bp\":\"upper arms\",\"eq\":\"ez barbell\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\"],\"st\":[\"Sit at the preacher bench with your upper arms flat on the pad.\",\"Compare the faulty version with the correct one: your wrists stay neutral and straight rather than bending back or curling in.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2348.webp\",\"gif\":\"2348.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for wrist position during a preacher curl, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"4966\",\"n\":\"press under\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"core\",\"glutes\"],\"st\":[\"Hold a barbell overhead with a wide grip.\",\"Press up so your arms lock out.\",\"Drop into a squat while keeping the bar overhead.\",\"Keep your arms locked.\",\"Stand up tall.\",\"Keep your core braced.\"],\"img\":\"4966.webp\",\"gif\":\"4966.mp4\",\"cat\":\"olympic\",\"desc\":\"An Olympic style drill where you press yourself down under a barbell overhead. It builds shoulder stability and speed.\"},{\"id\":\"0649\",\"n\":\"pretzel stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"lower back\"],\"st\":[\"Lie on one side and bend your top knee.\",\"Pull the bottom foot toward your glutes.\",\"Rotate your top knee back toward the floor behind you.\",\"Keep your shoulders relaxed.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"0649.webp\",\"gif\":\"0649.mp4\",\"cat\":\"stretching\",\"desc\":\"A twisting stretch lying on your side. It loosens the hips, trunk and lower back.\"},{\"id\":\"4388\",\"n\":\"prisoner get up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Kneel on the floor, with your hands behind your head.\",\"Keep your chest tall and your core braced.\",\"Step one foot forward and drive up through it to stand.\",\"Lower back down with control to kneeling.\",\"Alternate the leading leg on each rep.\"],\"img\":\"4388.webp\",\"gif\":\"4388.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight get-up with your hands behind your head. It builds leg strength, balance and hip control.\"},{\"id\":\"4118\",\"n\":\"prisoner jump squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with your hands behind your head and feet shoulder-width apart.\",\"Squat down until your thighs are about parallel.\",\"Explode upward into a jump.\",\"Land softly on bent knees.\",\"Go straight into the next rep.\"],\"img\":\"4118.webp\",\"gif\":\"4118.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump squat with hands behind your head for an explosive leg workout.\"},{\"id\":\"1580\",\"n\":\"prisoner squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand with feet shoulder-width apart and place your hands behind your head.\",\"Pull your elbows back and keep your chest up.\",\"Push your hips back and bend your knees to lower down.\",\"Go until your thighs are about parallel to the floor.\",\"Drive through your heels to stand back up.\"],\"img\":\"1580.webp\",\"gif\":\"1580.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat with your hands behind your head. It keeps your chest open and builds leg strength.\"},{\"id\":\"5060\",\"n\":\"prone cervical extension\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"sternocleidomastoid\"],\"st\":[\"Lie face down with your forehead on the floor or a towel.\",\"Keep your arms by your sides.\",\"Slowly lift your head a few inches, keeping your chin tucked.\",\"Pause briefly.\",\"Lower slowly and repeat.\"],\"img\":\"5060.webp\",\"gif\":\"5060.mp4\",\"cat\":\"mobility\",\"desc\":\"Lying face down, you gently lift your head. It trains the muscles at the back of the neck.\"},{\"id\":\"5061\",\"n\":\"prone cervical extension isometric hold\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"sternocleidomastoid\"],\"st\":[\"Lie face down with your arms by your sides.\",\"Tuck your chin slightly.\",\"Lift your head a few inches off the floor.\",\"Hold steady while breathing normally.\",\"Hold for 10-20 seconds, then lower slowly.\"],\"img\":\"5061.webp\",\"gif\":\"5061.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold your head lifted while lying face down. It builds endurance in the neck extensors.\",\"hd\":1},{\"id\":\"3230\",\"n\":\"prone cobra hands interlocked\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"upper back\",\"rear deltoids\",\"trapezius\"],\"st\":[\"Lie face down with your hands clasped behind your lower back.\",\"Keep your neck long and look at the floor.\",\"Lift your chest off the floor.\",\"Reach your hands toward your feet.\",\"Hold for 15-30 seconds.\",\"Lower slowly and rest.\"],\"img\":\"3230.webp\",\"gif\":\"3230.mp4\",\"cat\":\"isometric\",\"desc\":\"A face-down hold with your hands clasped behind you. It trains the back extensors and opens the chest.\",\"hd\":1,\"fv\":\"3210\"},{\"id\":\"3226\",\"n\":\"prone cobra palms under thighs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"upper back\",\"trapezius\",\"hamstrings\"],\"st\":[\"Lie face down with your palms under your thighs.\",\"Keep your neck long and look at the floor.\",\"Lift your chest off the ground using your back muscles.\",\"Squeeze your glutes.\",\"Hold for 15-30 seconds.\",\"Lower slowly and rest.\"],\"img\":\"3226.webp\",\"gif\":\"3226.mp4\",\"cat\":\"isometric\",\"desc\":\"A face-down hold where you lift your chest with your palms tucked under your thighs. It builds lower back and upper back endurance.\",\"hd\":1,\"fv\":\"3206\"},{\"id\":\"2878\",\"n\":\"prone press swan\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"triceps\",\"shoulders\"],\"st\":[\"Lie face down with hands beside your chest and legs together.\",\"Press your pubic bone into the mat and engage your glutes.\",\"Press through your hands to lift your chest.\",\"Keep your neck long and shoulders away from your ears.\",\"Lower slowly with control and repeat.\"],\"img\":\"2878.webp\",\"gif\":\"2878.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates back extension on your belly that lifts the chest and strengthens the spine.\"},{\"id\":\"2940\",\"n\":\"prone single arm trap raise\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"rear deltoids\",\"trapezius\"],\"st\":[\"Lie face down with one arm hanging or reaching overhead, thumb up.\",\"Keep your forehead down and neck relaxed.\",\"Lift your arm in a Y shape by squeezing your shoulder blade down and back.\",\"Pause at the top.\",\"Lower slowly, finish the reps, then switch arms.\"],\"img\":\"2940.webp\",\"gif\":\"2940.mp4\",\"cat\":\"strength\",\"desc\":\"A raise lying face down on a bench or floor with one arm. It targets the lower and middle traps and shoulder blade control.\"},{\"id\":\"5822\",\"n\":\"prone y raise\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"trapezius\",\"lower back\",\"rhomboids\"],\"st\":[\"Lie face down with arms stretched overhead in a Y.\",\"Turn your thumbs up.\",\"Lift your arms, squeezing your shoulder blades.\",\"Hold briefly at the top.\",\"Lower with control.\"],\"img\":\"5822.webp\",\"gif\":\"5822.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lie face down and lift your arms overhead in a Y. It builds the lower traps and the muscles that support the shoulder blades.\"},{\"id\":\"3824\",\"n\":\"pseudo planche push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\",\"upper chest\"],\"st\":[\"Start in a plank with your hands turned out beside your lower ribs.\",\"Lean your shoulders forward beyond your hands.\",\"Lower your chest with your elbows close to your body.\",\"Press up while keeping the lean.\",\"Keep your core braced.\"],\"img\":\"3824.webp\",\"gif\":\"3824.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands near your hips and your body leaning forward. It strongly loads shoulders and chest.\"},{\"id\":\"7385\",\"n\":\"pull up (negative)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"grip muscles\"],\"st\":[\"Jump or step up so your chin is above the bar.\",\"Grip the bar slightly wider than your shoulders.\",\"Lower yourself slowly over 3-5 seconds.\",\"Stop at a full hang with straight arms.\",\"Step back up and repeat.\"],\"img\":\"7385.webp\",\"gif\":\"7385.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Slow lowering phase of a pull-up that builds strength for full pull-ups.\",\"fv\":\"4774\"},{\"id\":\"3487\",\"n\":\"pull up with bent knee between chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"rhomboids\"],\"st\":[\"Set a sturdy bar across two stable chairs, high enough to sit under.\",\"Sit or lie beneath it and grip the bar slightly wider than your shoulders.\",\"Keep your knees bent with feet on the floor for light help.\",\"Pull your chest toward the bar by driving elbows down.\",\"Lower slowly until your arms are straight.\",\"Use your legs as little as you can.\"],\"img\":\"3487.webp\",\"gif\":\"3487.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A beginner-friendly pull-up built from a bar across two chairs, with the feet on the floor and knees bent. It builds lats and arm pulling strength.\"},{\"id\":\"3822\",\"n\":\"pulse row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rear deltoids\",\"biceps\",\"rhomboids\"],\"st\":[\"Hinge forward at the hips with a flat back and arms hanging.\",\"Pull your elbows back and squeeze your shoulder blades.\",\"Pulse in short movements at the top.\",\"Lower your arms under control.\",\"Keep your neck neutral.\"],\"img\":\"3822.webp\",\"gif\":\"3822.mp4\",\"cat\":\"strength\",\"desc\":\"A rowing movement with small pulses at the top of the pull. It builds endurance in your upper back.\",\"fv\":\"2923\"},{\"id\":\"3459\",\"n\":\"pulse up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with legs pointing to the ceiling.\",\"Place your hands by your sides.\",\"Lift your hips slightly with a small pulse.\",\"Lower and repeat.\",\"Keep movement small.\",\"Do 15-20 pulses.\"],\"img\":\"3459.webp\",\"gif\":\"3459.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small upward pulses with your legs raised, targeting the lower abs.\"},{\"id\":\"6027\",\"n\":\"punch step forward\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"quadriceps\",\"core\"],\"st\":[\"Stand in a boxing stance with fists up.\",\"Step forward with your lead foot.\",\"Throw a punch as you step.\",\"Return to your stance.\",\"Alternate sides and keep a steady rhythm.\"],\"img\":\"6027.webp\",\"gif\":\"6027.mp4\",\"cat\":\"combat\",\"desc\":\"A shadow-boxing drill pairing a forward step with a punch for cardio and coordination.\",\"fv\":\"6028\"},{\"id\":\"5897\",\"n\":\"puppy pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"triceps\"],\"st\":[\"Start on hands and knees with your hips over your knees.\",\"Walk your hands forward and lower your chest toward the floor.\",\"Keep your hips high above your knees.\",\"Rest your forehead down and hold for 5 slow breaths.\",\"Walk your hands back to return.\"],\"img\":\"5897.webp\",\"gif\":\"5897.mp4\",\"cat\":\"yoga\",\"desc\":\"A half child's pose with arms reaching forward and hips high. Opens the shoulders and the back.\"},{\"id\":\"1200\",\"n\":\"push press\",\"bp\":\"shoulders\",\"eq\":\"barbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"quadriceps\",\"core\"],\"st\":[\"Hold the barbell at your upper chest with your elbows slightly in front of the bar.\",\"Dip a few inches by bending your knees, keeping your torso upright.\",\"Drive up through your legs and press the bar overhead.\",\"Lock out with the bar over your mid foot, then lower it back to your chest.\",\"Brace your core and avoid leaning back.\"],\"img\":\"1200.webp\",\"gif\":\"1200.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press helped by a quick leg dip and drive. It lets you handle heavier loads for the shoulders and triceps.\"},{\"id\":\"4556\",\"n\":\"push through reach\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Slide one arm under your body, palm up, reaching across.\",\"Let your shoulder and head lower toward the floor.\",\"Hold briefly, then pull the arm back.\",\"Reach it up toward the ceiling, following with your eyes.\",\"Repeat, then switch sides.\"],\"img\":\"4556.webp\",\"gif\":\"4556.mp4\",\"cat\":\"mobility\",\"desc\":\"A quadruped drill that threads one arm under the body to free up the upper back and shoulders.\"},{\"id\":\"0654\",\"n\":\"push up (knee chest)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"hip flexors\",\"core\",\"shoulders\"],\"st\":[\"Start in a plank with your hands under your shoulders.\",\"Lower into a push-up.\",\"Press back up.\",\"Drive one knee toward your chest.\",\"Return that foot to the plank.\",\"Alternate legs each rep.\"],\"img\":\"0654.webp\",\"gif\":\"0654.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where you pull a knee toward your chest on each rep. It adds core and conditioning work.\"},{\"id\":\"1182\",\"n\":\"push up (on knees)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Kneel on the floor with your hands slightly wider than shoulder width.\",\"Keep your body in a straight line from your head to your knees.\",\"Lower your chest toward the floor by bending your elbows.\",\"Press back up until your arms are straight.\",\"Keep your core tight and your hips from sagging.\"],\"img\":\"1182.webp\",\"gif\":\"1182.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An easier push-up variation from the knees that builds chest, shoulder and arm strength.\"},{\"id\":\"0657\",\"n\":\"push up (one arm on stability ball)\",\"bp\":\"chest\",\"eq\":\"stability ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Get into a push-up position with one hand on a stability ball and one on the floor.\",\"Keep your body in a straight line.\",\"Lower your chest toward the floor.\",\"Press back up.\",\"Keep your core tight.\",\"Finish your reps, then switch the ball hand.\"],\"img\":\"0657.webp\",\"gif\":\"0657.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with one hand on a stability ball. It makes the chest and shoulders work harder to stay stable.\"},{\"id\":\"1486\",\"n\":\"push up (with push up handles)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place the handles shoulder-width apart and grip them in a plank position.\",\"Keep your body in a straight line from head to heels.\",\"Lower your chest until it is between the handles, elbows about 45 degrees from your body.\",\"Press back up until your arms are straight.\",\"Keep your core tight and your hips from sagging.\"],\"img\":\"1486.webp\",\"gif\":\"1486.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up on handles that lets you go a little deeper and keeps the wrists neutral. It trains the chest, shoulders and triceps.\"},{\"id\":\"4775\",\"n\":\"push up and triceps dip on parallel bars\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place hands on parallel bars and support yourself in a plank.\",\"Lower into a push-up with your elbows out.\",\"Press back up to a plank.\",\"Shift your hands to the edge of the bars, body upright.\",\"Dip down and press up, then repeat the cycle.\"],\"img\":\"4775.webp\",\"gif\":\"4775.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A combined move on parallel bars that pairs a push-up with a dip. It works the chest and triceps.\"},{\"id\":\"2351\",\"n\":\"push up end position (form check)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank and lower yourself under control.\",\"Compare the faulty version with the correct one: your chest nearly touches the floor, elbows angled back, and hips stay in line.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2351.webp\",\"gif\":\"2351.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-by-side form check for the bottom position of a push-up, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"3985\",\"n\":\"push up hand by hand\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank.\",\"Lower into a push up.\",\"Step one hand wider, then the other.\",\"Do another push up.\",\"Step your hands back in.\"],\"img\":\"3985.webp\",\"gif\":\"3985.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push up where your hands shift one at a time to walk in and out. It adds shoulder stability to the chest drill.\"},{\"id\":\"4830\",\"n\":\"push up in child pose\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"lats\"],\"st\":[\"Kneel and sit back on your heels with your arms stretched forward.\",\"Place your hands on the floor at chest height.\",\"Shift forward and lower your chest between your hands.\",\"Push the floor away to rise.\",\"Sit back to the starting pose and repeat.\"],\"img\":\"4830.webp\",\"gif\":\"4830.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up performed from a kneeling child's pose position. It trains the chest and triceps with a gentle range.\"},{\"id\":\"5030\",\"n\":\"push up jack\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"calves\"],\"st\":[\"Start in a high plank with your feet together.\",\"Lower into a push up with control.\",\"Push back up and jump your feet wide.\",\"Jump your feet back together.\",\"Keep your body straight and move rhythmically.\"],\"img\":\"5030.webp\",\"gif\":\"5030.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push up combined with a jumping jack leg motion. It raises your heart rate while training chest and shoulders.\"},{\"id\":\"3984\",\"n\":\"push up pike toe touch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a high plank.\",\"Do a push up.\",\"Lift your hips into a pike.\",\"Reach one hand to the opposite toe.\",\"Return to plank and alternate.\"],\"img\":\"3984.webp\",\"gif\":\"3984.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push up followed by a pike with a reach to the toes. It trains the chest, shoulders and core.\"},{\"id\":\"6537\",\"n\":\"push up pull\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"lats\"],\"st\":[\"Start in a high plank with your hands under your shoulders.\",\"Lower your chest to the floor in a push-up.\",\"Press back up to the top.\",\"Drag one hand across the floor as if pulling yourself forward.\",\"Alternate sides and keep your core tight.\"],\"img\":\"6537.webp\",\"gif\":\"6537.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up combined with a pulling motion, adding upper-back work to a classic chest exercise.\"},{\"id\":\"2350\",\"n\":\"push up start position (form check)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Set your hands on the floor under your shoulders and extend your legs back.\",\"Compare the faulty version with the correct one: your body forms one straight line from head to heels with hands under the shoulders.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2350.webp\",\"gif\":\"2350.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-by-side form check for the starting position of a push-up, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"4162\",\"n\":\"push up to knee tap\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a push up position with a straight body.\",\"Lower your chest toward the floor.\",\"Press back up to straight arms.\",\"Bring one knee toward the same side elbow.\",\"Return the foot and repeat on the other side.\",\"Keep your hips level and your core braced.\"],\"img\":\"4162.webp\",\"gif\":\"4162.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push up where you pull a knee toward your elbow after each rep. It adds a core challenge to a standard push up.\"},{\"id\":\"4859\",\"n\":\"push up to side plank v. 2\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Start in a high plank.\",\"Lower into a push-up.\",\"Push up and rotate into a side plank, raising one arm.\",\"Return to plank.\",\"Alternate sides each rep.\"],\"img\":\"4859.webp\",\"gif\":\"4859.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up that finishes by rotating into a side plank. It trains the chest and trunk.\"},{\"id\":\"3977\",\"n\":\"push up toe touch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank.\",\"Lower your chest and push back up.\",\"Lift your hips and reach one hand to the opposite foot.\",\"Return to plank.\",\"Alternate hands each rep.\"],\"img\":\"3977.webp\",\"gif\":\"3977.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push up followed by a hand reaching to the opposite toe. It adds core and mobility work to the chest drill.\"},{\"id\":\"0665\",\"n\":\"push up w\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Get into a plank and place your hands in a W position.\",\"Keep your body straight from head to heels.\",\"Lower your chest toward the floor.\",\"Keep your elbows angled slightly out.\",\"Press back up.\",\"Repeat without letting your hips sag.\"],\"img\":\"0665.webp\",\"gif\":\"0665.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up variation with the hands placed in a W shape. It focuses on the chest and shoulders.\"},{\"id\":\"4860\",\"n\":\"push up with knee drive\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"hip flexors\",\"shoulders\"],\"st\":[\"Start in a high plank.\",\"Lower into a push-up.\",\"Push back up.\",\"Drive one knee toward your chest.\",\"Return and alternate legs.\"],\"img\":\"4860.webp\",\"gif\":\"4860.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up followed by a knee drive toward the chest. It combines upper-body strength with core work.\"},{\"id\":\"4329\",\"n\":\"push with chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place a stable chair against a wall and set your hands on the seat edge.\",\"Walk your feet back until your body is straight.\",\"Lower your chest toward the seat, elbows at about 45 degrees.\",\"Push back up until your arms are straight.\",\"Keep your core tight and hips level.\"],\"img\":\"4329.webp\",\"gif\":\"4329.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up variation with hands on a sturdy chair. It makes pressing easier while still training chest and arms.\"},{\"id\":\"4602\",\"n\":\"pvc external rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Hold a PVC pipe in both hands with your elbows tucked at your sides and bent to 90 degrees.\",\"Keep your elbows pinned and rotate the pipe so one hand moves outward.\",\"Return to the start and rotate the other way.\",\"Move slowly and keep your ribs down and your wrists straight.\",\"Continue alternating for the planned reps.\"],\"img\":\"4602.webp\",\"gif\":\"4602.mp4\",\"cat\":\"mobility\",\"desc\":\"Using a light pipe to practice rotating the shoulders outward, building control and range for overhead lifts.\"},{\"id\":\"4603\",\"n\":\"pvc front rack stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"wrist flexors\",\"triceps\"],\"st\":[\"Stand tall holding a PVC pipe across your upper chest in a front rack grip.\",\"Lift your elbows forward and up as high as you comfortably can.\",\"Keep your chest up and your lower back from arching.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Lower the elbows and repeat.\"],\"img\":\"4603.webp\",\"gif\":\"4603.mp4\",\"cat\":\"stretching\",\"desc\":\"A pipe-assisted stretch for the lats, shoulders and wrists that helps you get into a comfortable front rack position.\"},{\"id\":\"4604\",\"n\":\"pvc good morning\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and a PVC pipe across your upper back.\",\"Soften your knees slightly and push your hips straight back.\",\"Lower your torso until you feel a stretch in the hamstrings, keeping your back flat.\",\"Drive your hips forward to stand tall again.\",\"Keep the pipe in contact with your head, upper back and tailbone if you can.\"],\"img\":\"4604.webp\",\"gif\":\"4604.mp4\",\"cat\":\"mobility\",\"desc\":\"A hip hinge drill with a light pipe on your back, teaching you to bend at the hips with a flat spine.\"},{\"id\":\"4605\",\"n\":\"pvc hip hinge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Hold a PVC pipe vertically along your spine, one hand at the neck and one at the lower back.\",\"Keep the pipe touching head, upper back and tailbone.\",\"Push your hips back with soft knees and tip forward.\",\"Stop when you feel the hamstrings stretch, then squeeze your glutes to stand.\",\"Keep the pipe contact the whole time.\"],\"img\":\"4605.webp\",\"gif\":\"4605.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple hinge pattern drill using a pipe along your spine to check posture while you bend at the hips.\"},{\"id\":\"4606\",\"n\":\"pvc overhead squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"upper back\"],\"st\":[\"Hold a PVC pipe overhead with a wide grip and arms locked out.\",\"Stand with feet slightly wider than shoulders.\",\"Squat down by sitting between your hips, keeping the pipe over your mid-foot.\",\"Go as deep as you can with your chest up and heels down.\",\"Drive through your feet to stand back up.\"],\"img\":\"4606.webp\",\"gif\":\"4606.mp4\",\"cat\":\"mobility\",\"desc\":\"A squat with a light pipe held overhead that checks your mobility and trains posture through the whole body.\"},{\"id\":\"4607\",\"n\":\"pvc pass through\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"rotator cuff\"],\"st\":[\"Stand holding a PVC pipe in front of your thighs with a wide overhand grip.\",\"Keep your arms straight and raise the pipe overhead.\",\"Continue moving it down behind your back as far as comfortable.\",\"Reverse the path back to the front with control.\",\"Widen your grip if the shoulders feel pinched.\"],\"img\":\"4607.webp\",\"gif\":\"4607.mp4\",\"cat\":\"mobility\",\"desc\":\"Swinging a pipe from the front of your thighs to behind your back to open the shoulders and chest.\"},{\"id\":\"5898\",\"n\":\"pyramid pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\",\"glutes\"],\"st\":[\"Step one foot back with both feet facing forward.\",\"Keep both legs straight and your hips square.\",\"Hinge forward from your hips with a long back.\",\"Hold for 5 slow breaths.\",\"Rise slowly and switch legs.\"],\"img\":\"5898.webp\",\"gif\":\"5898.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing forward fold with one leg back. Deeply stretches the back of the front leg.\"},{\"id\":\"4299\",\"n\":\"quadriceps lying stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shins\"],\"st\":[\"Lie on your side with your legs stacked and your head resting on one arm.\",\"Bend the top knee and grab that ankle with your top hand.\",\"Pull your heel toward your glutes while keeping your knees close together.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"4299.webp\",\"gif\":\"4299.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the front of the thigh done lying on your side or front. It loosens tight quads after leg work.\",\"fv\":\"0939\"},{\"id\":\"4300\",\"n\":\"quadriceps stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shins\"],\"st\":[\"Stand tall, using a wall or support for balance if needed.\",\"Bend one knee and grab the ankle behind you.\",\"Pull your heel toward your glutes, keeping your knees together and hips square.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"4300.webp\",\"gif\":\"4300.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch for the front of the thigh. Easy to do anywhere to ease tight quads.\",\"fv\":\"0940\"},{\"id\":\"1954\",\"n\":\"quadriceps stretch on box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Stand facing away from a box or bench and place the top of one foot on it behind you.\",\"Stand tall on the front leg with a soft knee.\",\"Tuck your pelvis and lower the hips slightly until you feel a stretch in the front of the thigh.\",\"Hold a support for balance if needed.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1954.webp\",\"gif\":\"1954.mp4\",\"cat\":\"stretching\",\"desc\":\"A quad stretch with the back foot resting on a box or bench, opening the front of the thigh.\"},{\"id\":\"4968\",\"n\":\"quadruped leg curl\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Get on all fours with your hands under your shoulders.\",\"Brace your core.\",\"Curl one heel toward your glutes.\",\"Squeeze the hamstring.\",\"Lower slowly.\",\"Finish reps, then switch legs.\"],\"img\":\"4968.webp\",\"gif\":\"4968.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hamstring curl from hands and knees position. It works the back of the thigh.\"},{\"id\":\"10747\",\"n\":\"quick feet in out run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand tall with feet together.\",\"Jog in place.\",\"Quickly move your feet in and out.\",\"Stay light on your toes.\",\"Continue for the set time.\"],\"img\":\"10747.webp\",\"gif\":\"10747.mp4\",\"cat\":\"cardio\",\"desc\":\"Run in place with feet moving in and out quickly. It boosts your heart rate.\"},{\"id\":\"3196\",\"n\":\"quick feet run\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall with your knees slightly bent.\",\"Run on the spot as fast as you can with small steps.\",\"Stay on the balls of your feet.\",\"Pump your arms.\",\"Keep your chest up.\",\"Continue for 20-30 seconds.\"],\"img\":\"3196.webp\",\"gif\":\"3196.mp4\",\"cat\":\"cardio\",\"desc\":\"Running on the spot with very fast, small steps. It's a classic warm-up and speed drill.\",\"fv\":\"6102\"},{\"id\":\"3588\",\"n\":\"quickly swing arms in place\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"core\"],\"st\":[\"Stand with feet hip width apart and knees soft.\",\"Swing both arms across your chest and open wide.\",\"Keep your torso upright and relaxed.\",\"Increase speed gradually.\",\"Continue for 30-60 seconds.\"],\"img\":\"3588.webp\",\"gif\":\"3588.mp4\",\"cat\":\"mobility\",\"desc\":\"Swing your arms quickly while standing to warm up the shoulders and raise your heart rate.\"},{\"id\":\"3589\",\"n\":\"quickly trot in place\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"hip flexors\"],\"st\":[\"Stand tall with arms bent at your sides.\",\"Lift your knees and run lightly on the spot.\",\"Land softly on the balls of your feet.\",\"Pump your arms with each step.\",\"Keep the pace for 30-60 seconds or longer.\"],\"img\":\"3589.webp\",\"gif\":\"3589.mp4\",\"cat\":\"cardio\",\"desc\":\"Trot in place at a quick pace to warm up and get your heart rate up.\"},{\"id\":\"0667\",\"n\":\"raise single leg push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Start in a push-up position.\",\"Lift one leg off the floor.\",\"Lower your chest toward the floor.\",\"Press back up without twisting your hips.\",\"Keep your body in a line.\",\"Switch the lifted leg every set.\"],\"img\":\"0667.webp\",\"gif\":\"0667.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up performed with one leg lifted. It challenges the chest, shoulders and core stability.\"},{\"id\":\"1959\",\"n\":\"raised foot shin stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Stand next to a wall and lift one foot behind you onto a low support with the top of the foot down.\",\"Keep your torso upright and your standing leg soft.\",\"Press your hips forward gently until you feel the shin stretch.\",\"Keep the movement slow and controlled.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1959.webp\",\"gif\":\"1959.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch with the foot raised on a support, easing the shin and top of the ankle.\"},{\"id\":\"1911\",\"n\":\"raised leg knee flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Place one heel on a low bench or step in front of you with the leg straight.\",\"Stand tall with the standing knee soft.\",\"Hinge forward from the hips, keeping your back flat, until you feel a stretch behind the raised thigh.\",\"Keep your toes pointing up and breathe slowly.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1911.webp\",\"gif\":\"1911.mp4\",\"cat\":\"stretching\",\"desc\":\"A hamstring stretch with one leg raised onto a support, easing tension in the back of the thigh.\"},{\"id\":\"1794\",\"n\":\"reach forward upper back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"lats\",\"shoulders\"],\"st\":[\"Stand or sit and clasp your hands or hold a support in front of you at chest height.\",\"Round your upper back and push your hands forward while dropping your head between your arms.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1794.webp\",\"gif\":\"1794.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching forward with rounded shoulders opens up the space between your shoulder blades. It helps relieve a tight upper back.\"},{\"id\":\"1797\",\"n\":\"reach up back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"triceps\"],\"st\":[\"Stand tall and reach both arms overhead with your palms facing each other.\",\"Reach up and lean slightly back, keeping your lower back relaxed and your ribs down.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1797.webp\",\"gif\":\"1797.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching both arms up and slightly back lengthens the lats and upper back. A simple stretch to open your sides.\"},{\"id\":\"1828\",\"n\":\"reaching down triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\"],\"st\":[\"Raise one arm overhead, bend the elbow and drop your hand behind your head.\",\"Use your other hand to press your elbow gently back and down.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1828.webp\",\"gif\":\"1828.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching your hand down your upper back stretches the triceps and the back of the shoulder. A common warm-up and cooldown stretch.\"},{\"id\":\"1983\",\"n\":\"reaching up shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"lats\",\"sm\":[\"lats\",\"triceps\"],\"st\":[\"Stand tall with your feet hip width apart.\",\"Reach one or both arms overhead and up as high as you can, then press them slightly backward.\",\"Do not arch your lower back as you reach.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1983.webp\",\"gif\":\"1983.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching overhead to stretch the shoulders and the sides of the upper body.\"},{\"id\":\"1795\",\"n\":\"reaching upper back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"lats\",\"shoulders\"],\"st\":[\"Stand with your feet hip-width apart and reach both arms forward at chest height.\",\"Round your upper back and spread your shoulder blades apart as you reach farther.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1795.webp\",\"gif\":\"1795.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching your arms out as you round your upper back stretches the muscles between and around your shoulder blades.\"},{\"id\":\"2304\",\"n\":\"rear axe kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Swing your rear leg straight up in front of you.\",\"Reach the top with the leg extended.\",\"Bring the heel sharply down.\",\"Keep your supporting leg slightly bent and balanced.\",\"Return to stance and repeat, then switch sides.\"],\"img\":\"2304.webp\",\"gif\":\"2304.mp4\",\"cat\":\"combat\",\"desc\":\"A kick with the back leg that rises high and then drops down like an axe, training flexibility and control.\"},{\"id\":\"3744\",\"n\":\"rear delt fly with bed sheet\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Hold a bed sheet taut in both hands in front of you.\",\"Keep your arms nearly straight.\",\"Pull your hands apart, opening your arms out to the sides.\",\"Squeeze your shoulder blades together.\",\"Return slowly and keep tension on the sheet.\"],\"img\":\"3744.webp\",\"gif\":\"3744.mp4\",\"cat\":\"strength\",\"desc\":\"A no-equipment fly that uses a bed sheet pulled apart to work the rear shoulders.\"},{\"id\":\"3746\",\"n\":\"rear delt row with bed sheet\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"biceps\"],\"st\":[\"Loop a bed sheet around a sturdy anchor and hold the ends.\",\"Lean back with your arms straight.\",\"Pull your hands toward your chest, elbows flared out.\",\"Squeeze your shoulder blades.\",\"Return slowly.\"],\"img\":\"3746.webp\",\"gif\":\"3746.mp4\",\"cat\":\"strength\",\"desc\":\"A rowing pattern that uses a bed sheet anchored around a door handle or post to work the upper back.\"},{\"id\":\"2301\",\"n\":\"rear leg hook kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Shift your weight onto the lead foot.\",\"Lift the rear knee and extend the leg across the target.\",\"Hook the heel around in an arc.\",\"Bring the leg back under control.\",\"Return to stance and repeat, then switch sides.\"],\"img\":\"2301.webp\",\"gif\":\"2301.mp4\",\"cat\":\"combat\",\"desc\":\"A martial arts kick with the back leg that swings in an arc to strike with the heel, training hip mobility and control.\"},{\"id\":\"5312\",\"n\":\"rear lunge from deficit\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand on a low step with your feet hip-width apart.\",\"Step one foot back and down off the step.\",\"Lower until the front thigh is about parallel.\",\"Keep your torso tall and front knee stable.\",\"Push through the front heel to return to the step.\",\"Finish your reps, then switch legs.\"],\"img\":\"5312.webp\",\"gif\":\"5312.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse lunge starting from a raised platform so you go deeper. Great for glutes and quads.\"},{\"id\":\"2933\",\"n\":\"rear lunge with battling ropes\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\",\"upper back\"],\"st\":[\"Stand holding the ends of the battle ropes, feet hip-width apart.\",\"Step one foot back into a lunge while making a wave with the ropes.\",\"Push through your front heel to return to standing.\",\"Alternate legs, keeping the rope waves going.\",\"Work for a set time, then rest.\"],\"img\":\"2933.webp\",\"gif\":\"2933.mp4\",\"cat\":\"cardio\",\"desc\":\"Alternating rear lunges while making waves with heavy ropes. It combines leg work with a hard cardio effort.\"},{\"id\":\"5582\",\"n\":\"rear shift lunge from deficit\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand on a low step with feet together.\",\"Step one leg back and down to the floor.\",\"Lower into a lunge with the front knee over the foot.\",\"Push through the front heel to step back up.\",\"Complete reps and switch legs.\"],\"img\":\"5582.webp\",\"gif\":\"5582.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lunge stepping backward from a raised surface, which increases the range of motion.\"},{\"id\":\"1808\",\"n\":\"reclining lower trunk extensor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and your feet flat.\",\"Draw both knees toward your chest and hold them with your hands.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1808.webp\",\"gif\":\"1808.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back and pulling your knees in stretches your lower back and hips. A soothing option after long periods of sitting.\"},{\"id\":\"1939\",\"n\":\"recumbent hip external rotator and hip extensor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\"],\"st\":[\"Lie on your back and bend both knees.\",\"Bring one knee toward your chest and turn it slightly outward.\",\"Hold the shin and ankle and draw the leg closer.\",\"Keep your lower back resting on the floor.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1939.webp\",\"gif\":\"1939.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying stretch for the deep hip rotators and glutes, pulling the knee toward the chest.\"},{\"id\":\"2099\",\"n\":\"recumbent hip external rotator and hip extensor stretch (crossed leg)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Cross one ankle over the opposite knee, then pull the legs toward your chest until the buttock stretches.\",\"Keep your head and shoulders relaxed on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2099.webp\",\"gif\":\"2099.mp4\",\"cat\":\"stretching\",\"desc\":\"A reclined figure four stretch for the buttocks and deep hip muscles.\"},{\"id\":\"1921\",\"n\":\"recumbent knee flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie on your back with both legs straight.\",\"Lift one leg toward the ceiling, holding behind the thigh or calf.\",\"Keep the knee as straight as is comfortable and the other leg flat on the floor.\",\"Gently draw the leg toward you until you feel a pull behind the thigh.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1921.webp\",\"gif\":\"1921.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back, you lift one straight leg to stretch the hamstring with the lower back supported.\"},{\"id\":\"1922\",\"n\":\"recumbent knee flexor stretch with towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Lie on your back and loop a towel around the ball of one foot.\",\"Raise that leg toward the ceiling, holding both ends of the towel.\",\"Keep the knee nearly straight and the other leg flat on the floor.\",\"Gently pull the towel until you feel a stretch behind the thigh.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1922.webp\",\"gif\":\"1922.mp4\",\"cat\":\"stretching\",\"desc\":\"A lying hamstring stretch where a towel around the foot lets you pull the leg closer without strain.\"},{\"id\":\"9408\",\"n\":\"repeated small jumps\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"ankles\"],\"st\":[\"Stand tall with feet hip-width apart and arms relaxed at your sides.\",\"Hop up a few centimetres by pushing through the balls of your feet.\",\"Land softly on the balls of your feet and rebound straight away.\",\"Keep your knees almost straight and your chest tall.\",\"Continue for 20-30 seconds at a quick, steady rhythm.\"],\"img\":\"9408.webp\",\"gif\":\"9408.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Quick, low hops on the spot that keep your feet barely off the floor. They warm up the calves and ankles and build bouncy reactive strength.\"},{\"id\":\"7999\",\"n\":\"resistance band 45 degree hip extension glute focused\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Set up on a 45 degree hip extension bench with the band anchored under your feet and held across your upper back.\",\"Cross your arms or hold the band at your shoulders.\",\"Hinge forward at the hips with a flat back until you feel your hamstrings stretch.\",\"Drive your hips forward and squeeze your glutes to come back up.\",\"Stop when your body is in a straight line.\",\"Do not over-arch your lower back at the top.\"],\"img\":\"7999.webp\",\"gif\":\"7999.mp4\",\"cat\":\"strength\",\"desc\":\"A hip extension on a 45 degree bench with a band added for extra glute load. It builds the glutes and the back of the thighs.\"},{\"id\":\"3875\",\"n\":\"resistance band 45 degrees hyperextension\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set up on a 45 degree hyperextension bench with your hips just over the pad.\",\"Loop a band across your upper back and under your feet or the base.\",\"Cross your arms over your chest or hold them lightly.\",\"Lower your torso with a straight back.\",\"Raise your torso until your body is in a straight line.\",\"Do not over-arch at the top.\"],\"img\":\"3875.webp\",\"gif\":\"3875.mp4\",\"cat\":\"strength\",\"desc\":\"A hyperextension on an angled bench with a band adding load for the lower back and glutes.\"},{\"id\":\"4109\",\"n\":\"resistance band adduction split squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"inner thighs\"],\"st\":[\"Anchor the band to the side and loop it around the working leg.\",\"Step into a split stance.\",\"Lower your back knee toward the floor.\",\"Press back up while resisting the band.\",\"Finish all reps, then switch legs.\"],\"img\":\"4109.webp\",\"gif\":\"4109.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with a band pulling you outward, adding inner thigh work.\"},{\"id\":\"2420\",\"n\":\"resistance band air bike\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with a band looped around your feet.\",\"Hold the ends with your hands or place them by your head.\",\"Lift your shoulders and bring your knees up.\",\"Pedal your legs while twisting your elbow toward the opposite knee.\",\"Keep your lower back flat.\",\"Continue for the planned reps.\"],\"img\":\"2420.webp\",\"gif\":\"2420.mp4\",\"cat\":\"strength\",\"desc\":\"A bicycle crunch with a band adding resistance to the leg movement.\"},{\"id\":\"7212\",\"n\":\"resistance band air bike v. 2\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back, hands behind your head, band around your feet.\",\"Lift your shoulders and bring one knee toward your chest.\",\"Rotate your opposite elbow toward that knee.\",\"Extend the other leg against the band.\",\"Alternate in a pedalling motion.\",\"Keep a steady rhythm.\"],\"img\":\"7212.webp\",\"gif\":\"7212.mp4\",\"cat\":\"strength\",\"desc\":\"An air bike crunch with band tension for extra work on the abs and hips.\"},{\"id\":\"10184\",\"n\":\"resistance band alternating split stance pallof press\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Anchor the band at chest height and stand sideways to it in a split stance.\",\"Hold the handle at your chest with both hands.\",\"Press the band straight out in front of you without letting your torso turn.\",\"Hold for a second, then bring the hands back to your chest.\",\"Switch which foot is forward on each set or rep and keep your hips square.\"],\"img\":\"10184.webp\",\"gif\":\"10184.mp4\",\"cat\":\"isometric\",\"desc\":\"A Pallof press from a split stance that resists the band pull and trains anti-rotation strength.\"},{\"id\":\"3866\",\"n\":\"resistance band anti rotation dead bug\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\",\"shoulders\"],\"st\":[\"Anchor a band at the side and lie on your back, holding the band above your chest with both hands.\",\"Raise your knees to a tabletop position.\",\"Brace your core so the band does not pull you sideways.\",\"Slowly extend one leg and the opposite arm back.\",\"Return and switch sides.\",\"Keep your lower back flat on the floor.\"],\"img\":\"3866.webp\",\"gif\":\"3866.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug with a band pulling you sideways, so your core works hard to keep your torso from twisting.\"},{\"id\":\"5147\",\"n\":\"resistance band assisted front rack stretch\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"wrist flexors\",\"shoulders\"],\"st\":[\"Loop a band around a sturdy anchor and hold it with both hands in a front rack position.\",\"Step back and let the band help your elbows lift.\",\"Keep your elbows high and chest tall.\",\"Hold for 20-30 seconds.\",\"Release the tension slowly.\"],\"img\":\"5147.webp\",\"gif\":\"5147.mp4\",\"cat\":\"stretching\",\"desc\":\"Use a band to pull yourself into a front rack position. It stretches your wrists, lats and shoulders.\"},{\"id\":\"4204\",\"n\":\"resistance band assisted nordic hamstring curl\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Kneel with ankles secured.\",\"Hold the band.\",\"Lower your body forward.\",\"Use the band to help.\",\"Pull back up.\",\"Keep hips extended.\"],\"img\":\"4204.webp\",\"gif\":\"4204.mp4\",\"cat\":\"strength\",\"desc\":\"A nordic curl using a band for assistance.\"},{\"id\":\"10660\",\"n\":\"resistance band assisted single arm pull up\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Loop a band over the bar and place your foot or knee in it.\",\"Hang with one hand on the bar and the other holding your wrist or the band.\",\"Pull your chin toward the bar, driving the elbow down.\",\"Pause at the top.\",\"Lower with control to a full hang.\",\"Switch arms after each set.\"],\"img\":\"10660.webp\",\"gif\":\"10660.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-arm pull-up with a band under your foot or knee to reduce the load. It builds toward unassisted single-arm pulling.\"},{\"id\":\"10903\",\"n\":\"resistance band assisted single arm pull up v. 2\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"grip muscles\"],\"st\":[\"Hang a band from the bar and place a foot or knee in the loop.\",\"Grip the bar with one hand and keep the other arm across your chest.\",\"Pull your chin toward the bar, driving your elbow down.\",\"Pause at the top.\",\"Lower under control. Finish your reps and switch arms.\"],\"img\":\"10903.webp\",\"gif\":\"10903.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-arm pull-up where a band takes some of your body weight. It helps you work toward an unassisted rep.\"},{\"id\":\"2149\",\"n\":\"resistance band bent leg kickback (kneeling)\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Anchor the band low and loop it around one foot, then get on all fours.\",\"Keep your back flat and your core braced.\",\"Press the foot with the bent knee up toward the ceiling against the band.\",\"Squeeze your glute at the top without arching your lower back.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"2149.webp\",\"gif\":\"2149.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling kickback with a band that isolates the glutes by pressing the bent leg up and back.\"},{\"id\":\"2418\",\"n\":\"resistance band bent leg side kick (kneeling)\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"quadriceps\"],\"st\":[\"Kneel on all fours with a band around your thighs.\",\"Keep your core braced and your back flat.\",\"Lift one bent leg out to the side against the band.\",\"Pause when your thigh is about hip height.\",\"Lower slowly without twisting your torso.\",\"Finish your reps, then switch legs.\"],\"img\":\"2418.webp\",\"gif\":\"2418.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling side kick with a band that targets the glutes and outer hips.\"},{\"id\":\"4570\",\"n\":\"resistance band bent over neutral grip row\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"lower back\"],\"st\":[\"Stand on the band with feet hip-width apart and hinge forward.\",\"Hold the handles with a neutral grip, arms straight.\",\"Keep your back flat and neck neutral.\",\"Pull both handles toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower with control.\"],\"img\":\"4570.webp\",\"gif\":\"4570.mp4\",\"cat\":\"strength\",\"desc\":\"A two-handed bent-over band row with palms facing in, hitting the lats and mid-back.\"},{\"id\":\"4114\",\"n\":\"resistance band bent over rear delt fly\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\",\"trapezius\"],\"st\":[\"Stand on the band and hinge forward holding the handles.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides.\",\"Squeeze your shoulder blades together.\",\"Lower slowly.\"],\"img\":\"4114.webp\",\"gif\":\"4114.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over fly with a band that targets the rear delts and upper back.\"},{\"id\":\"3858\",\"n\":\"resistance band bent over row\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"rear deltoids\"],\"st\":[\"Stand on the middle of the band with feet hip-width apart and hold an end in each hand.\",\"Hinge at the hips with a flat back until your torso is nearly parallel to the floor.\",\"Let your arms hang straight down.\",\"Pull your elbows back toward your hips, squeezing your shoulder blades together.\",\"Pause briefly, then lower with control.\",\"Keep your neck neutral throughout.\"],\"img\":\"3858.webp\",\"gif\":\"3858.mp4\",\"cat\":\"strength\",\"desc\":\"A hinged rowing move with a band that works the muscles between and around the shoulder blades.\"},{\"id\":\"3511\",\"n\":\"resistance band bird dog\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\"],\"st\":[\"Start on hands and knees with a band looped under one hand and around the opposite foot.\",\"Brace your core and keep your back flat.\",\"Extend that arm forward and the opposite leg back against the band.\",\"Pause, then return under control.\",\"Do all reps, then switch sides.\"],\"img\":\"3511.webp\",\"gif\":\"3511.mp4\",\"cat\":\"strength\",\"desc\":\"A bird dog with a band for extra resistance, training the lower back, glutes and core stability.\"},{\"id\":\"7207\",\"n\":\"resistance band bulgarian squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand in front of a bench, band under your front foot and held at your shoulders.\",\"Rest the top of your back foot on the bench.\",\"Lower straight down until your front thigh is parallel.\",\"Keep your torso tall.\",\"Press through your front heel to rise.\",\"Finish all reps, then switch sides.\"],\"img\":\"7207.webp\",\"gif\":\"7207.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat with the rear foot elevated and a band adding resistance.\"},{\"id\":\"3857\",\"n\":\"resistance band cable squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Anchor the band at chest height and hold the handles at your chest, facing away from the anchor.\",\"Stand with feet shoulder-width apart and brace your core.\",\"Sit your hips back and down until your thighs are about parallel to the floor.\",\"Keep your chest tall and knees tracking over your toes.\",\"Push through your heels to stand up.\",\"Repeat for the desired reps.\"],\"img\":\"3857.webp\",\"gif\":\"3857.mp4\",\"cat\":\"strength\",\"desc\":\"A squat against band tension that builds the quads and glutes while the band pulls you forward, so your core has to work too.\"},{\"id\":\"2425\",\"n\":\"resistance band calf raise\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Sit or stand with the band under the balls of your feet.\",\"Hold the ends firmly.\",\"Press up onto your toes against the band.\",\"Pause at the top and squeeze your calves.\",\"Lower your heels slowly.\",\"Repeat for the planned reps.\"],\"img\":\"2425.webp\",\"gif\":\"2425.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise with a band that builds lower leg strength.\"},{\"id\":\"2150\",\"n\":\"resistance band clam\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your side with a loop band just above your knees and knees bent.\",\"Stack your hips and keep your feet together.\",\"Open the top knee away from the bottom one like a clam.\",\"Keep your pelvis still and do not roll backward.\",\"Lower the knee slowly.\",\"Complete the reps, then switch sides.\"],\"img\":\"2150.webp\",\"gif\":\"2150.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying clam with a band around the thighs that strengthens the outer hip and glutes.\",\"fv\":\"5780\"},{\"id\":\"3787\",\"n\":\"resistance band deadlift with single arm row\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"lats\",\"upper back\",\"biceps\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Stand with soft knees and the band under light tension.\",\"Push your hips back and lower your torso with a flat back.\",\"Drive your hips forward to stand, then row the handle to your ribs.\",\"Lower the handle under control. Finish your reps, then switch sides.\"],\"img\":\"3787.webp\",\"gif\":\"3787.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge paired with a one-arm band row. It works your posterior chain and your upper back.\"},{\"id\":\"8327\",\"n\":\"resistance band drag curl\",\"bp\":\"upper arms\",\"eq\":\"resistance band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the band with feet hip-width apart and hold the handles at your thighs.\",\"Keep your chest up and core braced.\",\"Curl by dragging your hands up your body while the elbows move behind you.\",\"Squeeze at the top for a moment.\",\"Lower under control until your arms are straight.\"],\"img\":\"8327.webp\",\"gif\":\"8327.mp4\",\"cat\":\"strength\",\"desc\":\"A curl variation where the elbows travel back as you pull, putting the biceps under steady band tension.\"},{\"id\":\"2417\",\"n\":\"resistance band duck walk\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\"],\"st\":[\"Place a loop band around your thighs or knees.\",\"Lower into a half squat with your chest up.\",\"Step sideways or forward with a wide stride.\",\"Keep tension on the band and your knees out.\",\"Bring your other foot in, staying low.\",\"Walk for the planned distance, then return.\"],\"img\":\"2417.webp\",\"gif\":\"2417.mp4\",\"cat\":\"strength\",\"desc\":\"A low squat walk with a band around the legs that fires up the glutes and hips.\"},{\"id\":\"4447\",\"n\":\"resistance band elevated glute bridge\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\",\"adductors\"],\"st\":[\"Lie on your back with your feet on a bench and a band around your thighs just above the knees.\",\"Bend your knees and place your arms by your sides.\",\"Push your knees out against the band and drive through your heels.\",\"Lift your hips until your body forms a straight line from shoulders to knees.\",\"Squeeze your glutes at the top for a moment.\",\"Lower your hips slowly and repeat.\"],\"img\":\"4447.webp\",\"gif\":\"4447.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with your feet raised and a band adding resistance. Targets the glutes with a deep range of motion.\",\"nd\":[\"bench\"]},{\"id\":\"10650\",\"n\":\"resistance band explosive push up\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Loop the band across your upper back and hold the ends under your palms.\",\"Set up in a push-up position with a straight body.\",\"Lower your chest to the floor with control.\",\"Push up hard so your hands briefly leave the floor.\",\"Land softly with elbows slightly bent.\",\"Keep your hips in line.\"],\"img\":\"10650.webp\",\"gif\":\"10650.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A push-up with a band across your back and a fast push at the top. It trains explosive chest and triceps power.\"},{\"id\":\"2151\",\"n\":\"resistance band external rotation\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Anchor a band at elbow height and stand sideways to it.\",\"Hold the handle with the hand farther from the anchor.\",\"Tuck your elbow against your side with the elbow bent to 90 degrees.\",\"Rotate your forearm outward, away from your belly.\",\"Return slowly to the start.\",\"Finish the reps, then switch arms.\"],\"img\":\"2151.webp\",\"gif\":\"2151.mp4\",\"cat\":\"strength\",\"desc\":\"Rotates the arm outward against band tension to strengthen the small muscles that stabilise the shoulder.\"},{\"id\":\"8877\",\"n\":\"resistance band fingers extension\",\"bp\":\"lower arms\",\"eq\":\"resistance band\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"hands\"],\"st\":[\"Loop a light band around your fingers and thumb of one hand.\",\"Rest your forearm on a table or your thigh.\",\"Start with the fingers curled in a relaxed fist.\",\"Spread your fingers open against the band's pull.\",\"Close them back slowly with control.\",\"Do all reps, then switch hands.\"],\"img\":\"8877.webp\",\"gif\":\"8877.mp4\",\"cat\":\"rehab\",\"desc\":\"Opening your fingers against a band strengthens the small extensor muscles of the hand and forearm. It is a good balance for all the gripping you do.\"},{\"id\":\"2423\",\"n\":\"resistance band floor hyperextension\",\"bp\":\"back\",\"eq\":\"band\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rhomboids\"],\"st\":[\"Lie face down and anchor a band under your hands or around your upper back.\",\"Squeeze your glutes and lift your chest slightly off the floor.\",\"Keep your neck neutral.\",\"Pause for a second at the top.\",\"Lower slowly to the floor.\",\"Repeat without overarching.\"],\"img\":\"2423.webp\",\"gif\":\"2423.mp4\",\"cat\":\"strength\",\"desc\":\"A floor back extension with band resistance for the lower back and glutes.\"},{\"id\":\"3127\",\"n\":\"resistance band foot eversion\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\",\"feet\"],\"st\":[\"Sit with your leg extended and a band around your forefoot.\",\"Anchor the band on the inside of your foot.\",\"Keep your leg still.\",\"Turn the sole of your foot outward against the band.\",\"Return slowly.\",\"Complete your reps, then switch feet.\"],\"img\":\"3127.webp\",\"gif\":\"3127.mp4\",\"cat\":\"rehab\",\"desc\":\"Turning the sole of the foot outward against a band to train the muscles on the outer side of the ankle.\"},{\"id\":\"3125\",\"n\":\"resistance band foot external rotation\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\",\"feet\"],\"st\":[\"Sit with one leg out and a band looped around the forefoot.\",\"Anchor the other end to a fixed point on the inside.\",\"Keep your heel still on the floor.\",\"Turn your foot outward against the band.\",\"Return slowly to the start.\",\"Complete your reps, then switch feet.\"],\"img\":\"3125.webp\",\"gif\":\"3125.mp4\",\"cat\":\"rehab\",\"desc\":\"A seated ankle drill where you turn the foot outward against a band. It strengthens the outer ankle muscles.\"},{\"id\":\"3128\",\"n\":\"resistance band foot inversion\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit with your leg extended and a band around your forefoot.\",\"Anchor the band on the outside of your foot.\",\"Keep your leg still.\",\"Turn the sole of your foot inward against the band.\",\"Return slowly.\",\"Complete your reps, then switch feet.\"],\"img\":\"3128.webp\",\"gif\":\"3128.mp4\",\"cat\":\"rehab\",\"desc\":\"Turning the sole of the foot inward against a band to train the muscles on the inner side of the ankle.\"},{\"id\":\"3126\",\"n\":\"resistance band foot plantar flexion\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Sit with your leg straight and a band looped around the ball of your foot.\",\"Hold the band ends in your hands.\",\"Point your toes away from you against the band.\",\"Pause at the end of the range.\",\"Return slowly.\",\"Finish your reps, then switch feet.\"],\"img\":\"3126.webp\",\"gif\":\"3126.mp4\",\"cat\":\"rehab\",\"desc\":\"Pointing the foot against a band to strengthen the calf and ankle.\"},{\"id\":\"2152\",\"n\":\"resistance band front plank with kicked leg\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Place a band around your feet or ankles and get into a forearm or high plank.\",\"Brace your core so your body forms a straight line.\",\"Kick one leg back and up against the band without shifting your hips.\",\"Return the leg with control.\",\"Alternate legs, keeping your hips level throughout.\"],\"img\":\"2152.webp\",\"gif\":\"2152.mp4\",\"cat\":\"strength\",\"desc\":\"A plank hold while one leg kicks back against a band, working the glutes and core together.\"},{\"id\":\"3791\",\"n\":\"resistance band front plank with single arm pulldown\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\",\"obliques\"],\"st\":[\"Anchor the band overhead and set up in a forearm or high plank.\",\"Brace your abs and keep your hips level.\",\"Pull the band down with one hand toward your hip without twisting.\",\"Return the arm slowly to the start.\",\"Alternate arms and keep your body in one straight line.\"],\"img\":\"3791.webp\",\"gif\":\"3791.mp4\",\"cat\":\"strength\",\"desc\":\"A front plank with a one-arm band pulldown. It trains core stability while your arm works against the band.\"},{\"id\":\"2153\",\"n\":\"resistance band full squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Stand on the band with your feet shoulder width apart and hold the handles at your shoulders.\",\"Keep your chest up and your core braced.\",\"Sit your hips back and down into a full squat.\",\"Keep your knees tracking over your toes and heels on the floor.\",\"Drive up through your feet to stand tall.\"],\"img\":\"2153.webp\",\"gif\":\"2153.mp4\",\"cat\":\"strength\",\"desc\":\"A deep squat with a band for added resistance, training the thighs and glutes.\"},{\"id\":\"2154\",\"n\":\"resistance band glute bridge\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Lie on your back with your knees bent and a band around your thighs just above the knees.\",\"Place your feet flat, hip width apart.\",\"Push your knees gently out against the band.\",\"Drive through your heels and lift your hips until your body forms a straight line.\",\"Squeeze your glutes, then lower slowly and repeat.\"],\"img\":\"2154.webp\",\"gif\":\"2154.mp4\",\"cat\":\"strength\",\"desc\":\"A floor bridge with a band around the thighs to keep the glutes working hard.\"},{\"id\":\"7198\",\"n\":\"resistance band glute bridge abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and the band just above your knees.\",\"Press through your heels to lift your hips.\",\"At the top, push your knees apart against the band.\",\"Bring the knees back together.\",\"Lower your hips slowly.\",\"Repeat for the planned reps.\"],\"img\":\"7198.webp\",\"gif\":\"7198.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with a band around the knees, pressing out to light up the side glutes.\"},{\"id\":\"2555\",\"n\":\"resistance band glute bridge v. 2\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with a loop band around your thighs.\",\"Bend your knees with feet flat.\",\"Push your knees out against the band.\",\"Lift your hips until your body forms a straight line.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2555.webp\",\"gif\":\"2555.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with a band around the thighs that adds hip activation.\"},{\"id\":\"10870\",\"n\":\"resistance band glute bridge walk\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with a band above your knees and feet flat.\",\"Lift your hips into a bridge.\",\"Step your feet out and in sideways.\",\"Keep the band tight.\",\"Keep your hips high.\",\"Lower after the set.\"],\"img\":\"10870.webp\",\"gif\":\"10870.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge held with a band while stepping sideways. It targets glutes and outer hips.\"},{\"id\":\"4195\",\"n\":\"resistance band half kneeling face pull\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\"],\"st\":[\"Anchor the band at face height.\",\"Kneel on one knee.\",\"Pull the handles toward your face.\",\"Flare your elbows.\",\"Return slowly.\",\"Keep your chest up.\"],\"img\":\"4195.webp\",\"gif\":\"4195.mp4\",\"cat\":\"strength\",\"desc\":\"A face pull in a half kneeling stance with a band.\"},{\"id\":\"4687\",\"n\":\"resistance band hammer curl\",\"bp\":\"upper arms\",\"eq\":\"resistance band\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand on the middle of the band and hold the handles with palms facing in.\",\"Keep your elbows at your sides.\",\"Curl the handles up toward your shoulders.\",\"Squeeze at the top.\",\"Lower slowly under tension.\"],\"img\":\"4687.webp\",\"gif\":\"4687.mp4\",\"cat\":\"strength\",\"desc\":\"A curl with palms facing each other against tube resistance, training the biceps and forearms.\"},{\"id\":\"3788\",\"n\":\"resistance band high knee lunge with single arm row\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lats\",\"upper back\",\"core\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Step back into a lunge and lower until your front thigh is about parallel.\",\"Push through your front foot and drive the rear knee up to hip height.\",\"Row the handle to your ribs while balancing on one leg.\",\"Return to the start under control. Finish your reps, then switch sides.\"],\"img\":\"3788.webp\",\"gif\":\"3788.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge that finishes with a high knee, combined with a one-arm band row. It builds leg strength and balance.\"},{\"id\":\"2760\",\"n\":\"resistance band hip thrust\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit with your upper back against a bench and the band over your hips, anchored at both sides.\",\"Plant your feet flat.\",\"Drive your hips up against the band.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\"],\"img\":\"2760.webp\",\"gif\":\"2760.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with a resistance band over the hips, adding load that increases toward the top.\"},{\"id\":\"4050\",\"n\":\"resistance band hip thrusts\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\",\"adductors\"],\"st\":[\"Sit with your upper back against a bench and the band across your hips, anchored to each side.\",\"Plant your feet flat, knees bent.\",\"Drive your hips up until your torso is level.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4050.webp\",\"gif\":\"4050.mp4\",\"cat\":\"strength\",\"desc\":\"Hip thrust with a band across the hips for resistance. It is a direct glute builder.\"},{\"id\":\"7277\",\"n\":\"resistance band hip thrusts on knees\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Kneel with a band anchored low in front and looped around your hips.\",\"Start with your hips back and chest up.\",\"Drive your hips forward, squeezing your glutes hard.\",\"Pause at full hip extension.\",\"Return slowly and repeat.\"],\"img\":\"7277.webp\",\"gif\":\"7277.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling hip thrust against a band that targets the glutes without any bench.\",\"fv\":\"3236\"},{\"id\":\"4240\",\"n\":\"resistance band horizontal pallof press\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Anchor a band at chest height and stand sideways to it.\",\"Hold the handle at your chest with both hands.\",\"Step away until the band is taut and brace your core.\",\"Press your hands straight out in front of you.\",\"Hold for a second without twisting, then bring them back.\",\"Complete your reps and switch sides.\"],\"img\":\"4240.webp\",\"gif\":\"4240.mp4\",\"cat\":\"strength\",\"desc\":\"A standing Pallof press with a resistance band anchored at chest height. It trains your core to resist rotation.\"},{\"id\":\"4379\",\"n\":\"resistance band inverted row\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\",\"core\"],\"st\":[\"Anchor the band to a sturdy bar or rack and hold it while lying under the anchor point.\",\"Keep your body in a straight line with heels on the floor.\",\"Pull your chest up toward your hands, squeezing your shoulder blades together.\",\"Pause briefly at the top.\",\"Lower yourself under control until your arms are straight.\"],\"img\":\"4379.webp\",\"gif\":\"4379.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row with a band added for extra load. It builds the upper back and biceps while your core keeps the body straight.\"},{\"id\":\"9996\",\"n\":\"resistance band isometric thumb extension\",\"bp\":\"lower arms\",\"eq\":\"resistance band\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrist extensors\"],\"st\":[\"Loop a light resistance band around your thumb and the base of your fingers.\",\"Rest your hand on a table or your thigh.\",\"Push your thumb out against the band.\",\"Hold the tension for 5-10 seconds without moving.\",\"Release slowly.\",\"Repeat, then switch hands.\"],\"img\":\"9996.webp\",\"gif\":\"9996.mp4\",\"cat\":\"isometric\",\"desc\":\"A thumb hold against a band that builds strength in the muscles that extend the thumb. It is small and controlled.\",\"hd\":1},{\"id\":\"3794\",\"n\":\"resistance band jump lunge with single arm row\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"lats\",\"upper back\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Start in a lunge position with your chest up.\",\"Jump and switch legs in mid-air.\",\"Land softly in a lunge and pull the handle to your ribs.\",\"Keep your front knee over your ankle on each landing.\",\"Switch rowing arm for the next set.\"],\"img\":\"3794.webp\",\"gif\":\"3794.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jumping lunge combined with a one-arm band row. It raises your heart rate and builds leg power.\"},{\"id\":\"3878\",\"n\":\"resistance band jump squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand on a band with feet shoulder-width apart and hold the other end at your shoulders.\",\"Squat down until your thighs are about parallel.\",\"Jump up explosively against the band.\",\"Land softly through your toes and heels.\",\"Sink immediately into the next squat.\",\"Keep your knees in line with your toes.\"],\"img\":\"3878.webp\",\"gif\":\"3878.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump squat with a band adding resistance for a more powerful leg drive.\"},{\"id\":\"2465\",\"n\":\"resistance band jumping jack\",\"bp\":\"full body\",\"eq\":\"band\",\"tg\":\"cardiovascular system\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"calves\",\"quadriceps\"],\"st\":[\"Stand with a loop band around your thighs or ankles.\",\"Keep your knees soft and your core tight.\",\"Jump your feet apart while raising your arms overhead.\",\"Push against the band as you land.\",\"Jump back to the start with your arms down.\",\"Keep a steady rhythm.\"],\"img\":\"2465.webp\",\"gif\":\"2465.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping jack with a band that raises your heart rate and adds a challenge to the hips and shoulders.\"},{\"id\":\"5202\",\"n\":\"resistance band kneeling ab crunch\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Anchor the band overhead and kneel facing it.\",\"Hold the handles beside your head.\",\"Crunch your ribs toward your hips, rounding your spine.\",\"Squeeze your abs at the bottom.\",\"Return slowly to the start without sitting back on your heels.\"],\"img\":\"5202.webp\",\"gif\":\"5202.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling crunch pulled down against a resistance band. It adds load to the abs.\"},{\"id\":\"5206\",\"n\":\"resistance band kneeling ab crunch v. 2\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Anchor the band overhead and kneel facing it.\",\"Hold the band at your forehead or beside your head.\",\"Pull your elbows toward your knees as you curl down.\",\"Hold the squeeze for a second.\",\"Return slowly while keeping the tension.\"],\"img\":\"5206.webp\",\"gif\":\"5206.mp4\",\"cat\":\"strength\",\"desc\":\"A second variation of the kneeling band crunch. It loads the abs through the full crunch range.\"},{\"id\":\"7208\",\"n\":\"resistance band kneeling back kick\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Start on hands and knees with the band around your foot and hands.\",\"Keep your back flat and your core braced.\",\"Kick one leg straight back and up.\",\"Squeeze your glute at the top.\",\"Lower slowly.\",\"Finish all reps, then switch sides.\"],\"img\":\"7208.webp\",\"gif\":\"7208.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling donkey-kick style move with band resistance for the glutes.\"},{\"id\":\"7209\",\"n\":\"resistance band kneeling leg half circle\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Start on hands and knees with the band around your thighs or foot.\",\"Lift one leg out to the side with a bent knee.\",\"Sweep it in a half circle, back and up.\",\"Keep your hips level and your core tight.\",\"Reverse the circle to return.\",\"Finish all reps, then switch sides.\"],\"img\":\"7209.webp\",\"gif\":\"7209.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling leg sweep against a band that works the glutes and outer hips.\"},{\"id\":\"6741\",\"n\":\"resistance band kneeling leg half circle on bench\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Place a band around your thighs or ankles and kneel on a bench with hands on its edge.\",\"Keep your back flat and hips level.\",\"Lift one leg out behind you.\",\"Sweep it in a half circle out to the side.\",\"Return along the same path under control.\",\"Finish the reps, then switch legs.\"],\"img\":\"6741.webp\",\"gif\":\"6741.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling band move on a bench, sweeping the leg in a half circle. It works the glutes from several angles.\"},{\"id\":\"11059\",\"n\":\"resistance band kneeling leg kickback on bench\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Anchor the band and loop it around one foot, then kneel on a bench with hands on the front.\",\"Brace your core and keep your back flat.\",\"Kick the working leg back and up until the hip is fully extended.\",\"Squeeze the glute for a moment at the top.\",\"Lower slowly under control without letting the band yank your leg.\",\"Finish your reps, then switch legs.\"],\"img\":\"11059.webp\",\"gif\":\"11059.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling on a bench, you kick one leg back against band tension to work the glutes.\"},{\"id\":\"2155\",\"n\":\"resistance band kneeling side plank\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Wrap a band around your thighs and lie on one side with your knees bent.\",\"Place your elbow under your shoulder.\",\"Lift your hips so your body forms a straight line from knees to head.\",\"Push your top knee gently out against the band.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2155.webp\",\"gif\":\"2155.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank from the knees with a band, training the sides of the waist and the hips with less load than a full plank.\",\"hd\":1},{\"id\":\"9988\",\"n\":\"resistance band kneeling sissy squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\",\"glutes\"],\"st\":[\"Set the band at a stable anchor and kneel with it around your body or hands.\",\"Keep your hips forward and your body in a straight line from knees to head.\",\"Lean back slowly, keeping your hips extended.\",\"Go as far as you can control.\",\"Use your quads to pull yourself back up.\",\"Keep your core braced and your movement smooth.\"],\"img\":\"9988.webp\",\"gif\":\"9988.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling sissy squat with a resistance band for assistance or load. It places a big stretch on the quads.\"},{\"id\":\"4776\",\"n\":\"resistance band kneeling woodchop\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Anchor a band high and kneel sideways to it.\",\"Hold the handle with both hands.\",\"Pull the band diagonally down across your body.\",\"Rotate your torso as you chop.\",\"Return slowly, then switch sides.\"],\"img\":\"4776.webp\",\"gif\":\"4776.mp4\",\"cat\":\"strength\",\"desc\":\"A diagonal chop with a resistance band while kneeling. It trains the obliques and core.\"},{\"id\":\"10594\",\"n\":\"resistance band lateral hit\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Anchor the band at chest height beside you and hold the handle at your chest.\",\"Stand tall in a stable stance with your core braced.\",\"Press the handle forward and across your body in a quick controlled motion.\",\"Return slowly to your chest without letting the band pull you around.\",\"Keep your hips square throughout.\",\"Finish all reps, then switch sides.\"],\"img\":\"10594.webp\",\"gif\":\"10594.mp4\",\"cat\":\"strength\",\"desc\":\"A standing band press that sweeps across the body from the side. It builds chest power and trains the trunk to resist rotation.\"},{\"id\":\"7206\",\"n\":\"resistance band lateral step and squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Put the band around your thighs and stand tall.\",\"Step one foot out to the side.\",\"Sit down into a squat.\",\"Stand up and bring your feet together.\",\"Keep the knees from caving in.\",\"Finish all reps, then switch sides.\"],\"img\":\"7206.webp\",\"gif\":\"7206.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways step into a squat with band tension to train the glutes and legs.\"},{\"id\":\"4036\",\"n\":\"resistance band leg curl\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Attach the band to a low anchor and loop the handle around one ankle.\",\"Face the anchor and hold a support for balance.\",\"Curl your heel toward your glute.\",\"Keep your knees close and your hips steady.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"4036.webp\",\"gif\":\"4036.mp4\",\"cat\":\"strength\",\"desc\":\"Leg curl with a tube band around the ankle, building the hamstrings.\",\"fv\":\"2422\"},{\"id\":\"7281\",\"n\":\"resistance band leg kickback\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Loop a band around your ankles or anchor it low and loop it on one foot.\",\"Stand tall holding something for balance.\",\"Kick the working leg straight back.\",\"Squeeze your glute at the top without arching your back.\",\"Return slowly, then switch legs.\"],\"img\":\"7281.webp\",\"gif\":\"7281.mp4\",\"cat\":\"strength\",\"desc\":\"Standing band kickback that isolates the glutes.\",\"fv\":\"2156\"},{\"id\":\"2419\",\"n\":\"resistance band leg lift\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Place a loop band around your ankles or thighs.\",\"Get on all fours or stand with support.\",\"Lift one leg back or out against the band.\",\"Squeeze your glutes at the top.\",\"Lower slowly without arching your back.\",\"Finish your reps, then switch legs.\"],\"img\":\"2419.webp\",\"gif\":\"2419.mp4\",\"cat\":\"strength\",\"desc\":\"A leg lift against band tension that trains the glutes and hips.\"},{\"id\":\"3862\",\"n\":\"resistance band long jump\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Anchor a band behind you and loop it around your hips.\",\"Stand tall with feet shoulder-width apart and slightly bend your knees.\",\"Swing your arms back and load your hips.\",\"Jump forward as far as you can against the band.\",\"Land softly on both feet with bent knees.\",\"Reset and repeat.\"],\"img\":\"3862.webp\",\"gif\":\"3862.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive forward jump against band resistance that builds power in the legs and hips.\"},{\"id\":\"2424\",\"n\":\"resistance band lunge\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand on the middle of a band and hold the ends at your shoulders.\",\"Step forward into a lunge.\",\"Lower your back knee toward the floor.\",\"Keep your front knee over your ankle and your torso tall.\",\"Push through your front heel to return.\",\"Alternate legs for the planned reps.\"],\"img\":\"2424.webp\",\"gif\":\"2424.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge with band resistance that works the legs and glutes.\"},{\"id\":\"10899\",\"n\":\"resistance band lying abduction\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Loop a band around both legs just above the knees and lie on your side.\",\"Stack your hips and bend your knees slightly.\",\"Lift the top knee or leg away from the bottom one against the band.\",\"Pause at the top.\",\"Lower slowly. Finish your reps and switch sides.\"],\"img\":\"10899.webp\",\"gif\":\"10899.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg lift against a band that works the outer hip. Good for glute and hip stability.\",\"fv\":\"2421\"},{\"id\":\"7199\",\"n\":\"resistance band lying bent knee hip abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Lie on your side with the band above your knees and your knees bent.\",\"Stack your hips and rest your head on your arm.\",\"Lift your top knee up against the band without rolling back.\",\"Pause, then lower slowly.\",\"Keep your feet together like a clamshell.\",\"Finish all reps, then switch sides.\"],\"img\":\"7199.webp\",\"gif\":\"7199.mp4\",\"cat\":\"strength\",\"desc\":\"A lying hip abduction with bent knees that targets the outer hip and glutes.\"},{\"id\":\"11285\",\"n\":\"resistance band lying floor chest press\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on your back with the band under your upper back and a handle in each hand.\",\"Start with your hands at chest level.\",\"Press your hands straight up until your arms extend.\",\"Squeeze your chest.\",\"Lower slowly back to the start.\"],\"img\":\"11285.webp\",\"gif\":\"11285.mp4\",\"cat\":\"strength\",\"desc\":\"A floor chest press using a resistance band. It trains the chest and triceps with tension that increases at the top.\"},{\"id\":\"7211\",\"n\":\"resistance band lying hyperextension abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hamstrings\"],\"st\":[\"Lie face down with the band around your ankles.\",\"Rest your forehead on your hands.\",\"Lift both legs slightly off the floor.\",\"Open your legs out against the band.\",\"Bring them back together and lower slowly.\",\"Keep the movement small and controlled.\"],\"img\":\"7211.webp\",\"gif\":\"7211.mp4\",\"cat\":\"strength\",\"desc\":\"A face-down hip extension combined with outward leg movement against a band.\"},{\"id\":\"8142\",\"n\":\"resistance band lying leg press\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Lie on your back and loop a band around your feet, holding the ends.\",\"Bring your knees toward your chest.\",\"Press your feet away until your legs are almost straight.\",\"Control the band as it pulls you back.\",\"Repeat for your reps.\"],\"img\":\"8142.webp\",\"gif\":\"8142.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press performed lying on your back using a band around your feet. It works the quads and glutes.\"},{\"id\":\"2157\",\"n\":\"resistance band lying leg raise\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Place a band around your thighs or ankles and lie on your side with your legs straight.\",\"Rest your head on your arm and keep your hips stacked.\",\"Raise the top leg against the band without rolling backward.\",\"Pause at the top.\",\"Lower slowly, finish your reps, then switch sides.\"],\"img\":\"2157.webp\",\"gif\":\"2157.mp4\",\"cat\":\"strength\",\"desc\":\"A side lying leg raise against a band that works the outer hip and glutes.\"},{\"id\":\"7201\",\"n\":\"resistance band lying leg raise v. 2\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"quadriceps\"],\"st\":[\"Lie on your back with the band around your feet or anchored behind your head.\",\"Press your lower back into the floor.\",\"Raise your legs together toward the ceiling.\",\"Lower them slowly without arching your back.\",\"Stop just above the floor.\",\"Repeat for the planned reps.\"],\"img\":\"7201.webp\",\"gif\":\"7201.mp4\",\"cat\":\"strength\",\"desc\":\"A leg raise with band tension that challenges the lower abs and hip flexors.\"},{\"id\":\"4569\",\"n\":\"resistance band one arm bent over row\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Stand on the band with a staggered stance and hinge forward.\",\"Hold the handle in one hand with your arm extended.\",\"Brace your core and keep your back flat.\",\"Pull your elbow back toward your hip.\",\"Squeeze your shoulder blade at the top.\",\"Lower slowly, then switch sides.\"],\"img\":\"4569.webp\",\"gif\":\"4569.mp4\",\"cat\":\"strength\",\"desc\":\"A single-arm row using a resistance band, working the lats and mid-back.\"},{\"id\":\"2159\",\"n\":\"resistance band one leg glute bridge\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with a loop band above your knees and knees bent.\",\"Lift one foot off the floor and extend that leg.\",\"Drive through the other heel and lift your hips.\",\"Squeeze the glutes at the top and keep the hips level.\",\"Lower with control.\",\"Finish the reps, then switch legs.\"],\"img\":\"2159.webp\",\"gif\":\"2159.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg glute bridge with a band added, making your glutes and hamstrings work harder on each side.\",\"fv\":\"2556\"},{\"id\":\"2158\",\"n\":\"resistance band one leg glute bridge with straight leg\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Lie on your back with a band around your thighs and one knee bent, foot flat.\",\"Extend the other leg straight, in line with your thigh.\",\"Drive through the planted heel and lift your hips.\",\"Keep your hips level and squeeze your glute at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"2158.webp\",\"gif\":\"2158.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg bridge with a band and the free leg held straight, demanding strong glutes and a level pelvis.\"},{\"id\":\"2161\",\"n\":\"resistance band one leg kickback\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Loop a band around your ankles or anchor it and loop it around one foot.\",\"Stand holding a support, or get on all fours, with your core braced.\",\"Kick one leg back against the band, keeping the knee straight.\",\"Squeeze your glute and avoid arching your lower back.\",\"Return slowly, finish your reps, then switch legs.\"],\"img\":\"2161.webp\",\"gif\":\"2161.mp4\",\"cat\":\"strength\",\"desc\":\"A standing or all fours kickback with a band that targets the glutes one leg at a time.\"},{\"id\":\"3903\",\"n\":\"resistance band one leg kickback (bent position)\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Loop a resistance band around your ankle and anchor the other end low in front of you.\",\"Hold a support and lean forward slightly.\",\"Brace your core and keep your hips level.\",\"Kick your leg back and up against the band.\",\"Squeeze your glute at the top.\",\"Return slowly, then switch legs after your reps.\"],\"img\":\"3903.webp\",\"gif\":\"3903.mp4\",\"cat\":\"strength\",\"desc\":\"A standing glute kickback with a band while leaning forward, isolating one hip at a time.\",\"fv\":\"2160\"},{\"id\":\"10553\",\"n\":\"resistance band overhead hit\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"lats\",\"triceps\"],\"st\":[\"Anchor a band overhead and hold the handles with both hands.\",\"Stand with a staggered stance and your arms raised.\",\"Pull the handles down and forward in a controlled hit.\",\"Brace your core as you finish.\",\"Return slowly and repeat.\"],\"img\":\"10553.webp\",\"gif\":\"10553.mp4\",\"cat\":\"strength\",\"desc\":\"Swing a resistance band from overhead down in front of you in a chopping motion. It builds powerful chest and core strength.\"},{\"id\":\"5205\",\"n\":\"resistance band overhead shoulder press\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand on the middle of the band and hold a handle in each hand at your shoulders.\",\"Brace your abs and stand tall.\",\"Press both handles overhead until your arms are straight.\",\"Pause briefly.\",\"Lower slowly back to shoulder height.\"],\"img\":\"5205.webp\",\"gif\":\"5205.mp4\",\"cat\":\"strength\",\"desc\":\"A two-handed overhead press using a resistance band. It is an easy way to train the shoulders anywhere.\"},{\"id\":\"8364\",\"n\":\"resistance band overhead shoulder press v. 2\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\"],\"st\":[\"Stand on the band with feet shoulder-width apart and hold the handles at shoulder height.\",\"Brace your core and keep ribs down.\",\"Press the handles overhead until your arms are straight.\",\"Lower them back to your shoulders under control.\",\"Repeat without leaning back.\"],\"img\":\"8364.webp\",\"gif\":\"8364.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with a band, training the shoulders and triceps with tension that rises toward the top.\"},{\"id\":\"4186\",\"n\":\"resistance band overhead squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Stand on the band and hold it overhead with wide grip.\",\"Brace your core.\",\"Squat down keeping arms overhead.\",\"Keep your chest up.\",\"Drive up through your feet.\",\"Keep your arms in line with your ears.\"],\"img\":\"4186.webp\",\"gif\":\"4186.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a band held overhead. It improves mobility and leg strength.\"},{\"id\":\"8365\",\"n\":\"resistance band pass through\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"upper back\"],\"st\":[\"Hold the band in front of your thighs with a wide grip and straight arms.\",\"Stand tall.\",\"Raise the band overhead and keep going back behind your body.\",\"Reverse the path to return to the front.\",\"Widen your grip if it feels too tight.\"],\"img\":\"8365.webp\",\"gif\":\"8365.mp4\",\"cat\":\"mobility\",\"desc\":\"A band stretch that moves overhead and behind you, opening up the shoulders and chest.\"},{\"id\":\"7210\",\"n\":\"resistance band plank jack\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"glutes\",\"hip flexors\"],\"st\":[\"Place the band above your knees and get into a high plank.\",\"Brace your abs and keep your hips level.\",\"Jump your feet out wide.\",\"Jump them back together.\",\"Keep your hands under your shoulders.\",\"Repeat at a steady pace.\"],\"img\":\"7210.webp\",\"gif\":\"7210.mp4\",\"cat\":\"strength\",\"desc\":\"A plank with jumping feet and a band around the legs, working your core while the hips resist.\"},{\"id\":\"2162\",\"n\":\"resistance band plank march\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\",\"glutes\"],\"st\":[\"Place a loop band around your thighs or ankles and get into a forearm or high plank.\",\"Keep a straight line from head to heels.\",\"Lift one knee toward your chest against the band.\",\"Return it quietly and lift the other knee.\",\"Keep your hips from rocking side to side.\",\"Alternate for the planned time or reps.\"],\"img\":\"2162.webp\",\"gif\":\"2162.mp4\",\"cat\":\"strength\",\"desc\":\"Marching the knees while holding a plank with a band around the legs, which challenges the core and hips together.\",\"fv\":\"2557\"},{\"id\":\"4568\",\"n\":\"resistance band pull apart\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Hold a resistance band in front of you at chest height, arms straight.\",\"Keep your hands about shoulder-width apart.\",\"Pull the band apart by moving your hands out to the sides.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the start.\",\"Keep your ribs down and shoulders relaxed.\"],\"img\":\"4568.webp\",\"gif\":\"4568.mp4\",\"cat\":\"strength\",\"desc\":\"A simple band pull-apart to strengthen the back of the shoulders and upper back.\"},{\"id\":\"5317\",\"n\":\"resistance band pull apart (45 degrees)\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\",\"upper back\"],\"st\":[\"Hold a resistance band in both hands in front of you.\",\"Raise your arms to about 45 degrees above horizontal.\",\"Pull the band apart by moving your hands out to the sides.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the start.\",\"Keep your ribs down and your shoulders away from your ears.\"],\"img\":\"5317.webp\",\"gif\":\"5317.mp4\",\"cat\":\"strength\",\"desc\":\"Pull a band apart with your arms angled upward at about 45 degrees. Strengthens the rear shoulders and upper back.\"},{\"id\":\"5837\",\"n\":\"resistance band pull through\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Anchor the band low and face away from it, holding the band between your legs.\",\"Step forward until you feel tension, feet shoulder-width apart.\",\"Push your hips back with a flat back.\",\"Squeeze your glutes and drive your hips forward to stand tall.\",\"Keep your arms relaxed and straight.\"],\"img\":\"5837.webp\",\"gif\":\"5837.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge where you pull a band through your legs. Teaches the hinge and strengthens the glutes and hamstrings.\"},{\"id\":\"4412\",\"n\":\"resistance band pullapart (pronated at 90 degrees)\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"upper back\",\"trapezius\"],\"st\":[\"Stand holding a band in front of you at shoulder height with an overhand grip.\",\"Keep your arms straight and your core braced.\",\"Pull your hands apart until the band touches your chest.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the start.\"],\"img\":\"4412.webp\",\"gif\":\"4412.mp4\",\"cat\":\"strength\",\"desc\":\"A band pull-apart with an overhand grip and arms at 90 degrees that hits the rear delts and upper back.\"},{\"id\":\"2930\",\"n\":\"resistance band pullapart (supination at 90 degrees)\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Hold a band in front of you at chest height with palms up and elbows bent at 90 degrees.\",\"Keep your elbows tucked near your sides.\",\"Rotate your forearms outward, pulling the band apart.\",\"Squeeze your shoulder blades together briefly.\",\"Return slowly and repeat.\"],\"img\":\"2930.webp\",\"gif\":\"2930.mp4\",\"cat\":\"strength\",\"desc\":\"A band pull-apart with palms facing up and elbows bent at 90 degrees. It targets the rear delts and external shoulder rotation.\"},{\"id\":\"3798\",\"n\":\"resistance band punch\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Anchor the band behind you and hold a handle in each hand at your shoulders.\",\"Stand in a staggered stance with a braced core.\",\"Punch one hand forward and rotate your torso slightly.\",\"Return the hand and punch with the other side.\",\"Keep the movement quick but controlled.\"],\"img\":\"3798.webp\",\"gif\":\"3798.mp4\",\"cat\":\"strength\",\"desc\":\"A standing forward punch against a resistance band. It trains your chest, shoulders and triceps.\"},{\"id\":\"4571\",\"n\":\"resistance band push up\",\"bp\":\"chest\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Loop the band across your upper back and hold the ends under your hands.\",\"Get into a plank position with your body straight.\",\"Lower your chest toward the floor, elbows at about 45 degrees.\",\"Press up against the band until your arms are straight.\",\"Keep your core tight and hips level.\",\"Lower slowly for the next rep.\"],\"img\":\"4571.webp\",\"gif\":\"4571.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with a band across your back that adds resistance at the top of the movement.\"},{\"id\":\"4182\",\"n\":\"resistance band rear delt row\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Anchor the band at chest height and hold the handles.\",\"Step back for tension.\",\"Pull your hands out to the sides with elbows high.\",\"Squeeze your shoulder blades.\",\"Return slowly.\",\"Keep your torso upright.\"],\"img\":\"4182.webp\",\"gif\":\"4182.mp4\",\"cat\":\"strength\",\"desc\":\"A wide rowing motion with a resistance band. It strengthens the rear shoulders.\"},{\"id\":\"3321\",\"n\":\"resistance band rear fly\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"trapezius\"],\"st\":[\"Hold the band in both hands in front of you with arms straight.\",\"Stand tall with a soft knee bend and your core tight.\",\"Pull your hands apart and out to the sides at shoulder height.\",\"Squeeze your shoulder blades together at the end.\",\"Return slowly to the start without letting the band snap back.\"],\"img\":\"3321.webp\",\"gif\":\"3321.mp4\",\"cat\":\"strength\",\"desc\":\"A band version of the reverse fly that works the back of your shoulders and upper back, handy for posture.\"},{\"id\":\"8224\",\"n\":\"resistance band renegade row\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"upper back\",\"core\",\"shoulders\"],\"st\":[\"Anchor a band and get into a plank facing it.\",\"Hold the band in one hand.\",\"Row your elbow back to your ribs.\",\"Keep your hips level.\",\"Return slowly and alternate arms.\"],\"img\":\"8224.webp\",\"gif\":\"8224.mp4\",\"cat\":\"strength\",\"desc\":\"A renegade row using a resistance band. It trains the core while the lats and back do the pulling.\"},{\"id\":\"6418\",\"n\":\"resistance band reverse crunch\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with a band anchored and held in your hands.\",\"Bend your knees and bring them over your hips.\",\"Curl your hips off the floor, drawing your knees toward your chest.\",\"Pause at the top.\",\"Lower slowly without letting your lower back arch.\"],\"img\":\"6418.webp\",\"gif\":\"6418.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse crunch with a band for added resistance, curling your hips up to hit the lower abs.\"},{\"id\":\"6419\",\"n\":\"resistance band reverse crunch v. 2\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back and hold the band firmly with both hands.\",\"Lift your bent knees over your hips.\",\"Curl your pelvis upward, bringing your knees toward your chest.\",\"Hold for a moment at the top.\",\"Lower with control and repeat.\"],\"img\":\"6419.webp\",\"gif\":\"6419.mp4\",\"cat\":\"strength\",\"desc\":\"A variation of the band reverse crunch that uses a different setup to challenge your lower abs.\"},{\"id\":\"6738\",\"n\":\"resistance band reverse hyper with stability ball on flat bench\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down with your hips over a stability ball on a flat bench.\",\"Loop a band around your feet and anchor it low in front.\",\"Hold the bench for stability.\",\"Raise both legs until they are in line with your body.\",\"Squeeze your glutes at the top.\",\"Lower slowly against the band.\"],\"img\":\"6738.webp\",\"gif\":\"6738.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse hyper with your torso on a stability ball and a band adding resistance. It trains glutes and hamstrings while sparing the spine.\"},{\"id\":\"2163\",\"n\":\"resistance band reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down over a bench or box with a band anchored near your feet.\",\"Hold the bench edge and loop the band around your ankles.\",\"Squeeze your glutes and lift your legs until they are in line with your body.\",\"Avoid swinging or arching the lower back.\",\"Lower the legs slowly.\",\"Repeat for the planned reps.\"],\"img\":\"2163.webp\",\"gif\":\"2163.mp4\",\"cat\":\"strength\",\"desc\":\"Swings the legs up behind you against a band to train the glutes and the muscles along the lower back.\"},{\"id\":\"7200\",\"n\":\"resistance band seated bent knee abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Sit tall on a bench or chair with the band just above your knees.\",\"Plant your feet flat and hip-width apart.\",\"Press your knees out against the band.\",\"Hold briefly at the widest point.\",\"Bring the knees back slowly.\",\"Keep your back straight throughout.\"],\"img\":\"7200.webp\",\"gif\":\"7200.mp4\",\"cat\":\"strength\",\"desc\":\"A seated band move pressing the knees apart to work the outer hips.\"},{\"id\":\"11050\",\"n\":\"resistance band seated bent knee abduction feet floor off\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Sit tall with a band around your thighs and feet off the floor.\",\"Hold the seat edge.\",\"Open your knees against the band.\",\"Pause.\",\"Close slowly.\",\"Keep your back straight.\"],\"img\":\"11050.webp\",\"gif\":\"11050.mp4\",\"cat\":\"strength\",\"desc\":\"Seated knee abduction against band resistance with feet lifted. It trains the outer hips.\"},{\"id\":\"5480\",\"n\":\"resistance band seated calf stretch\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"hamstrings\"],\"st\":[\"Sit on the floor with one leg straight and loop the band around the ball of that foot.\",\"Hold the band ends with both hands and sit tall.\",\"Gently pull your toes toward you.\",\"Hold for 20-30 seconds, keeping your knee straight.\",\"Release and switch legs.\"],\"img\":\"5480.webp\",\"gif\":\"5480.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch where you pull the foot toward you with a band. Lengthens the calf and the back of the leg.\"},{\"id\":\"8611\",\"n\":\"resistance band seated eversion foot\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with one leg extended and loop the band around the forefoot, anchored on the inside.\",\"Keep your leg still.\",\"Turn your foot outward against the band.\",\"Return slowly.\",\"Finish the reps, then switch feet.\"],\"img\":\"8611.webp\",\"gif\":\"8611.mp4\",\"cat\":\"rehab\",\"desc\":\"A seated ankle drill that works the muscles on the outside of the lower leg.\"},{\"id\":\"4445\",\"n\":\"resistance band seated face pull\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"rotator cuff\",\"trapezius\"],\"st\":[\"Anchor a band at chest height and sit facing it, holding the ends with both hands.\",\"Sit tall with arms extended and the band under light tension.\",\"Pull the band toward your face, flaring your elbows out and high.\",\"Squeeze your shoulder blades together at the end.\",\"Pause briefly, then return slowly with control.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"4445.webp\",\"gif\":\"4445.mp4\",\"cat\":\"strength\",\"desc\":\"A seated band pull toward the face that targets the rear delts and upper back. Good for shoulder health and posture.\"},{\"id\":\"8612\",\"n\":\"resistance band seated inversion foot\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit with one leg extended and loop the band around the forefoot, anchored on the outside.\",\"Keep your leg still.\",\"Turn your foot inward against the band.\",\"Return slowly.\",\"Finish the reps, then switch feet.\"],\"img\":\"8612.webp\",\"gif\":\"8612.mp4\",\"cat\":\"rehab\",\"desc\":\"A seated ankle drill that works the muscles on the inside of the lower leg.\"},{\"id\":\"10753\",\"n\":\"resistance band seated knee raise\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Sit tall on a bench or chair with a band looped around your foot and anchored low.\",\"Hold the seat edge and brace your core.\",\"Lift one knee toward your chest against the band.\",\"Pause briefly at the top.\",\"Lower the foot slowly with control.\",\"Finish all reps, then switch legs.\"],\"img\":\"10753.webp\",\"gif\":\"10753.mp4\",\"cat\":\"strength\",\"desc\":\"Seated knee raise against band tension. It works the hip flexors and lower abs.\"},{\"id\":\"4903\",\"n\":\"resistance band seated leg curl\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Anchor the band at foot height and sit facing it.\",\"Loop the band around your heels.\",\"Extend your legs straight in front of you.\",\"Curl your heels back under the seat against the tension.\",\"Squeeze the hamstrings at the end.\",\"Return slowly without letting the band snap.\"],\"img\":\"4903.webp\",\"gif\":\"4903.mp4\",\"cat\":\"strength\",\"desc\":\"A seated hamstring curl using a resistance band anchored in front of you. It isolates the back of the thigh.\"},{\"id\":\"3508\",\"n\":\"resistance band seated single leg curl\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Sit on the floor with a band anchored in front and looped around one foot.\",\"Extend your leg with a slight tension on the band.\",\"Curl your heel toward your glutes, pulling against the band.\",\"Squeeze the hamstring briefly.\",\"Return with control.\",\"Complete your reps, then switch legs.\"],\"img\":\"3508.webp\",\"gif\":\"3508.mp4\",\"cat\":\"strength\",\"desc\":\"A seated leg curl with a band around the foot. It isolates the hamstrings.\"},{\"id\":\"10744\",\"n\":\"resistance band seated single leg hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Sit tall with one leg extended and a band around that foot.\",\"Hold the band ends in both hands.\",\"Keep your leg straight and gently pull your toes toward you.\",\"Hinge forward until you feel a stretch.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"10744.webp\",\"gif\":\"10744.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated hamstring stretch with a band around your foot. The band lets you control the pull.\"},{\"id\":\"10591\",\"n\":\"resistance band seated single leg hugging knee flexion\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hip flexors\"],\"st\":[\"Sit tall on a chair with a band around one foot.\",\"Hold the band ends in your hands.\",\"Pull the knee up and bend it toward your chest.\",\"Hold for a moment, then release slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"10591.webp\",\"gif\":\"10591.mp4\",\"cat\":\"strength\",\"desc\":\"Seated knee flexion with a band under your foot, hugging one knee. It adds resistance to the bend.\"},{\"id\":\"10746\",\"n\":\"resistance band seated single leg knee extension\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Sit on a bench and secure a band around one ankle.\",\"Anchor the other end behind you.\",\"Straighten your knee against the band.\",\"Squeeze the front of your thigh at the top.\",\"Lower slowly.\",\"Switch legs.\"],\"img\":\"10746.webp\",\"gif\":\"10746.mp4\",\"cat\":\"strength\",\"desc\":\"A seated knee extension against band tension. It isolates the quads one leg at a time.\"},{\"id\":\"10921\",\"n\":\"resistance band seated single leg knee extension hold\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit on a chair with a band anchored around one ankle behind you.\",\"Straighten that knee against the band.\",\"Hold the leg straight for 10-20 seconds.\",\"Keep the thigh tight and your back upright.\",\"Lower slowly and switch legs.\"],\"img\":\"10921.webp\",\"gif\":\"10921.mp4\",\"cat\":\"isometric\",\"desc\":\"A seated band-resisted knee extension that you hold at the top. It builds quad endurance.\",\"hd\":1},{\"id\":\"5024\",\"n\":\"resistance band serratus wall slide\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"serratus anterior\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Stand facing a wall with a band around your forearms just below the elbows.\",\"Place your forearms on the wall and push slightly outward against the band.\",\"Slide your arms up the wall, reaching overhead.\",\"Keep your ribs down and shoulder blades moving freely.\",\"Slide back down slowly.\"],\"img\":\"5024.webp\",\"gif\":\"5024.mp4\",\"cat\":\"strength\",\"desc\":\"Wall slide with a band around the forearms to engage the serratus. It improves shoulder blade control.\"},{\"id\":\"5026\",\"n\":\"resistance band serratus wall slide with foam roll\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"serratus anterior\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Put a band around your forearms and place a foam roller on the wall under them.\",\"Press your forearms into the roller and push slightly out against the band.\",\"Roll the roller up the wall as you reach overhead.\",\"Keep your ribs down and shoulders away from your ears.\",\"Roll back down slowly.\"],\"img\":\"5026.webp\",\"gif\":\"5026.mp4\",\"cat\":\"strength\",\"desc\":\"Wall slide with a band and a foam roller between your forearms and the wall. It adds stability and serratus activation.\"},{\"id\":\"6437\",\"n\":\"resistance band shoulder adduction\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rear deltoids\",\"triceps\",\"core\"],\"st\":[\"Anchor a band overhead and hold the handle with your arm raised.\",\"Stand tall with your core braced.\",\"Pull your arm down toward your side.\",\"Keep your elbow straight or slightly bent.\",\"Return slowly, then switch arms.\"],\"img\":\"6437.webp\",\"gif\":\"6437.mp4\",\"cat\":\"strength\",\"desc\":\"A band pulldown pulling the arm from out to your side down to your body. It trains the lats and shoulder control.\"},{\"id\":\"3513\",\"n\":\"resistance band shoulder stretch behind the back\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"biceps\",\"rotator cuff\"],\"st\":[\"Stand tall holding a band behind your back with both hands.\",\"Keep your arms straight and your hands wide.\",\"Lift your hands away from your back gently.\",\"Keep your chest open and your ribs down.\",\"Hold for 20-30 seconds.\",\"Release slowly.\"],\"img\":\"3513.webp\",\"gif\":\"3513.mp4\",\"cat\":\"stretching\",\"desc\":\"A shoulder and chest stretch holding a band behind the back. It opens the front of the shoulders.\"},{\"id\":\"4241\",\"n\":\"resistance band shuttle\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Anchor a band at hip height or place it around your waist with a partner or post.\",\"Get into a slight squat with your chest up.\",\"Shuffle sideways several steps against the tension.\",\"Keep your feet from crossing.\",\"Shuffle back the other way under control.\",\"Stay low throughout.\"],\"img\":\"4241.webp\",\"gif\":\"4241.mp4\",\"cat\":\"strength\",\"desc\":\"Quick side-to-side steps against band tension. It trains lateral leg power, agility and glute strength.\"},{\"id\":\"7202\",\"n\":\"resistance band side lunge\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand with the band under your feet or around your thighs, feet together.\",\"Step wide to one side.\",\"Sit your hips back and bend that knee, keeping the other leg straight.\",\"Keep your chest up and your heel down.\",\"Push back to the start.\",\"Finish all reps, then switch sides.\"],\"img\":\"7202.webp\",\"gif\":\"7202.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge with band tension that works the legs and hips from a different angle.\"},{\"id\":\"11644\",\"n\":\"resistance band side lying hip abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Lie on your side with the band around your thighs or ankles.\",\"Keep your legs straight and stacked.\",\"Lift the top leg up without rolling backward.\",\"Pause at the top.\",\"Lower slowly.\",\"Finish reps, then switch sides.\"],\"img\":\"11644.webp\",\"gif\":\"11644.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your side, you lift the top leg against band resistance to work the outer hip.\"},{\"id\":\"2164\",\"n\":\"resistance band side plank\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Place a band around your thighs and lie on one side with your legs straight.\",\"Put your elbow under your shoulder.\",\"Lift your hips so your body forms a straight line from head to feet.\",\"Press your top leg gently up against the band.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2164.webp\",\"gif\":\"2164.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with a band around the legs to fire up the hips and the sides of the waist.\",\"hd\":1},{\"id\":\"6737\",\"n\":\"resistance band side plank glute raise\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"core\"],\"st\":[\"Put a band around your thighs or ankles and get into a side plank on your forearm.\",\"Lift your hips so your body forms a straight line.\",\"Raise the top leg up against the band.\",\"Pause briefly.\",\"Lower the leg with control.\",\"Finish the reps, then switch sides.\"],\"img\":\"6737.webp\",\"gif\":\"6737.mp4\",\"cat\":\"strength\",\"desc\":\"A side plank with a band around the legs while raising the top leg. It works the outer hip and the side of the trunk.\"},{\"id\":\"3790\",\"n\":\"resistance band side step with horizontal pallof hold\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"obliques\",\"shoulders\"],\"st\":[\"Anchor the band at chest height and stand side-on to it.\",\"Press the handle straight out and sink into a quarter squat.\",\"Take small steps sideways away from the anchor, keeping your torso square.\",\"Step back in under control.\",\"Repeat for your set, then switch sides.\"],\"img\":\"3790.webp\",\"gif\":\"3790.mp4\",\"cat\":\"strength\",\"desc\":\"Side steps in a half squat while holding the band out in front of you. It works your hips and resists rotation through the core.\"},{\"id\":\"2165\",\"n\":\"resistance band side walk\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Place a band around your thighs or ankles and stand with your feet hip width apart.\",\"Bend your knees slightly into a quarter squat.\",\"Step sideways with the lead foot, keeping tension on the band.\",\"Bring the trailing foot in without letting the feet touch.\",\"Take 10-15 steps one way, then walk back the other way.\"],\"img\":\"2165.webp\",\"gif\":\"2165.mp4\",\"cat\":\"strength\",\"desc\":\"A lateral band walk that strengthens the outer hips and glutes.\"},{\"id\":\"6744\",\"n\":\"resistance band side walk squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\"],\"st\":[\"Put a band around your thighs or just above the knees.\",\"Drop into a quarter squat with chest up.\",\"Step sideways, keeping tension on the band.\",\"Bring the trailing foot in without letting the feet touch.\",\"Take several steps one way, then return the other way.\",\"Keep your knees pushed out.\"],\"img\":\"6744.webp\",\"gif\":\"6744.mp4\",\"cat\":\"strength\",\"desc\":\"A squat position with side steps against a band. It strengthens the outer hips and thighs.\"},{\"id\":\"5204\",\"n\":\"resistance band single arm overhead shoulder press\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand on the band with the handle in one hand at shoulder height.\",\"Brace your core and keep your ribs down.\",\"Press the handle straight overhead.\",\"Pause at the top without leaning.\",\"Lower with control, finish your reps, then switch arms.\"],\"img\":\"5204.webp\",\"gif\":\"5204.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm overhead press with a resistance band. It trains each shoulder separately and challenges your trunk.\"},{\"id\":\"3789\",\"n\":\"resistance band single stiff leg deadlift with single arm row\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"lats\",\"upper back\",\"core\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Stand on one leg with a soft knee and the band under light tension.\",\"Hinge forward at the hips while the free leg extends behind you.\",\"Keep your back flat, then pull the handle to your ribs.\",\"Lower the handle and stand tall again. Finish your reps, then switch sides.\"],\"img\":\"3789.webp\",\"gif\":\"3789.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge with a one-arm band row. It challenges your balance and trains hamstrings, glutes and back.\"},{\"id\":\"10003\",\"n\":\"resistance band sitting floor ankle dorsi flexion\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit on the floor with your legs straight and loop the band around the top of one foot.\",\"Hold the band ends or anchor them so there is light tension.\",\"Pull your toes toward your shin.\",\"Pause, then return slowly.\",\"Complete all reps, then switch feet.\"],\"img\":\"10003.webp\",\"gif\":\"10003.mp4\",\"cat\":\"rehab\",\"desc\":\"Pull your toes toward your shin against a band while seated. It strengthens the muscles at the front of the lower leg.\"},{\"id\":\"10366\",\"n\":\"resistance band sitting floor tibialis press\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit on the floor with your legs out and loop a band around your foot, anchored in front.\",\"Keep your leg straight and your heel on the floor.\",\"Pull your toes up toward your shin against the band.\",\"Hold briefly, then slowly release.\",\"Do all reps on one foot, then switch.\"],\"img\":\"10366.webp\",\"gif\":\"10366.mp4\",\"cat\":\"strength\",\"desc\":\"A seated move that pulls the toes toward the shins against a band to strengthen the front of the lower leg.\"},{\"id\":\"3795\",\"n\":\"resistance band skier\",\"bp\":\"full body\",\"eq\":\"resistance band\",\"tg\":\"lats\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\",\"triceps\"],\"st\":[\"Anchor the band overhead and hold a handle in each hand.\",\"Stand with soft knees and arms extended in front of you.\",\"Pull the handles down and back past your hips as you hinge forward.\",\"Return the arms up and stand tall in one smooth motion.\",\"Keep your back flat and move with control.\"],\"img\":\"3795.webp\",\"gif\":\"3795.mp4\",\"cat\":\"strength\",\"desc\":\"A skiing motion with the band: swing both arms down and back while hinging at the hips. It works your lats, hips and core.\"},{\"id\":\"3856\",\"n\":\"resistance band smith squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set the bar on the smith machine and attach the band as required.\",\"Place the bar on your upper back with your feet slightly forward.\",\"Lower into a squat until your thighs are about parallel.\",\"Drive through your heels to stand.\",\"Keep your chest up.\"],\"img\":\"3856.webp\",\"gif\":\"3856.mp4\",\"cat\":\"strength\",\"desc\":\"A smith machine squat with resistance band tension added. It builds your quads and glutes under a guided bar path.\"},{\"id\":\"8874\",\"n\":\"resistance band speed step\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\"],\"st\":[\"Place a band around your thighs or ankles.\",\"Stand in a quarter squat.\",\"Take quick small steps to the side.\",\"Keep tension on the band and your chest up.\",\"Move in both directions.\"],\"img\":\"8874.webp\",\"gif\":\"8874.mp4\",\"cat\":\"cardio\",\"desc\":\"A quick lateral stepping drill with a band around the legs to speed up the feet and fire the glutes.\"},{\"id\":\"2943\",\"n\":\"resistance band spider crawls\",\"bp\":\"full body\",\"eq\":\"resistance band\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"triceps\",\"hip flexors\",\"obliques\"],\"st\":[\"Place a band around your thighs and start in a push-up position.\",\"Brace your core.\",\"Bring one knee toward the same-side elbow while crawling forward.\",\"Alternate sides while keeping the band under tension.\",\"Crawl the set distance, then rest.\"],\"img\":\"2943.webp\",\"gif\":\"2943.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A spider crawl performed with a band around your legs. The band adds hip effort to a classic core and shoulder crawl.\"},{\"id\":\"3793\",\"n\":\"resistance band split jump with single arm row\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"lats\",\"upper back\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Start in a split stance with a slight bend in both knees.\",\"Jump up and switch legs in mid-air.\",\"Land softly in the opposite split stance and row the handle to your ribs.\",\"Alternate legs, and switch rowing arm for the next set.\"],\"img\":\"3793.webp\",\"gif\":\"3793.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive split jump with a one-arm band row. It builds power in your legs and trains your back.\"},{\"id\":\"4689\",\"n\":\"resistance band split squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand in a split stance with the band under your front foot and handles at your shoulders.\",\"Keep your torso upright.\",\"Lower your back knee toward the floor.\",\"Press through the front heel to rise.\",\"Complete your reps and switch legs.\"],\"img\":\"4689.webp\",\"gif\":\"4689.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with band resistance, building the quads and glutes one leg at a time.\"},{\"id\":\"3797\",\"n\":\"resistance band split squat with horizontal pallof hold\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"obliques\"],\"st\":[\"Anchor the band at chest height and stand side-on to it.\",\"Take a split stance and press the handle straight out with both hands.\",\"Lower your back knee toward the floor without letting the band twist you.\",\"Push through your front foot to rise.\",\"Finish your reps, then switch legs and anchor side.\"],\"img\":\"3797.webp\",\"gif\":\"3797.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat done while holding the band out in front of you. It builds single-leg strength and core stability.\"},{\"id\":\"4398\",\"n\":\"resistance band squat\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Stand on the band with feet shoulder-width apart and hold the handles at your shoulders.\",\"Brace your core and keep your chest tall.\",\"Sit your hips back and bend your knees to lower into a squat.\",\"Keep your knees tracking over your toes.\",\"Drive through your feet to stand up.\"],\"img\":\"4398.webp\",\"gif\":\"4398.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a resistance band for added load. It builds strength in the legs and hips.\",\"fv\":\"7197\"},{\"id\":\"7205\",\"n\":\"resistance band squat jump\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Place the band above your knees and stand with feet shoulder-width.\",\"Squat down with your chest up.\",\"Explode upward into a jump.\",\"Land softly, absorbing into the next squat.\",\"Keep your knees pressing out against the band.\",\"Repeat for the planned reps.\"],\"img\":\"7205.webp\",\"gif\":\"7205.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat jump with a band around the thighs to keep the knees driving outward.\"},{\"id\":\"7203\",\"n\":\"resistance band squat step out\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Place the band around your thighs and stand with feet hip-width.\",\"Sit into a squat and stay low.\",\"Step one foot out to the side against the band.\",\"Bring the other foot in to follow.\",\"Take several steps, then return the other way.\",\"Keep your knees pushed out.\"],\"img\":\"7203.webp\",\"gif\":\"7203.mp4\",\"cat\":\"strength\",\"desc\":\"A squat that steps sideways against a band, firing up the glutes and hips.\"},{\"id\":\"3796\",\"n\":\"resistance band squat with horizontal pallof hold\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"obliques\",\"shoulders\"],\"st\":[\"Anchor the band at chest height and stand side-on to it.\",\"Hold the handle with both hands at your chest, then press it straight out.\",\"Keep your hips and shoulders square as you squat down.\",\"Stand back up while holding the band steady.\",\"Complete your reps, then turn around and repeat on the other side.\"],\"img\":\"3796.webp\",\"gif\":\"3796.mp4\",\"cat\":\"strength\",\"desc\":\"A squat while holding the band out in front of you against sideways pull. It trains your legs and anti-rotation core strength.\"},{\"id\":\"3786\",\"n\":\"resistance band squat with single arm row\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lats\",\"upper back\",\"biceps\"],\"st\":[\"Anchor the band at a low point and hold the handle in one hand.\",\"Stand tall with feet shoulder width apart and the band under light tension.\",\"Sit your hips back and down into a squat while keeping your chest up.\",\"Stand up and, at the top, pull the handle to your ribs with your elbow close to your body, then let it return slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"3786.webp\",\"gif\":\"3786.mp4\",\"cat\":\"strength\",\"desc\":\"A squat combined with a one-arm band row. It trains your legs and your back together.\"},{\"id\":\"4028\",\"n\":\"resistance band squatting front warming up\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"quadriceps\",\"glutes\",\"core\"],\"st\":[\"Hold the band in front of you and sink into a comfortable deep squat.\",\"Keep your heels down and chest up.\",\"Move your hands apart, stretching the band at shoulder height.\",\"Bring your hands back together under control.\",\"Repeat for 10 to 15 easy reps, then stand up.\"],\"img\":\"4028.webp\",\"gif\":\"4028.mp4\",\"cat\":\"mobility\",\"desc\":\"A warm-up from a low squat position, moving a band in front of you to loosen the shoulders and hips together.\"},{\"id\":\"8363\",\"n\":\"resistance band standing 90 degrees shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Anchor the band at shoulder height and hold the handle with your elbow raised to shoulder level, bent 90 degrees.\",\"Keep the upper arm still.\",\"Rotate your hand up and back until the forearm points to the ceiling.\",\"Return slowly to the start.\",\"Do all reps, then switch arms.\"],\"img\":\"8363.webp\",\"gif\":\"8363.mp4\",\"cat\":\"rehab\",\"desc\":\"A band rotation with the upper arm raised to shoulder height, building rotator cuff strength for overhead positions.\"},{\"id\":\"5203\",\"n\":\"resistance band standing ab crunch\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Anchor the band high and stand facing it with your feet hip-width apart.\",\"Hold the handles at your head.\",\"Bend forward by crunching your ribs toward your pelvis.\",\"Squeeze your abs hard.\",\"Return slowly to standing.\"],\"img\":\"5203.webp\",\"gif\":\"5203.mp4\",\"cat\":\"strength\",\"desc\":\"A standing crunch against band tension. It trains the abs without lying on the floor.\"},{\"id\":\"2999\",\"n\":\"resistance band standing back achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Loop a resistance band around the front of the foot of your back leg.\",\"Hold the band ends in your hands and stand tall.\",\"Step that leg back with the heel on the floor.\",\"Pull the band gently so your toes move toward your shin.\",\"Hold for 20-30 seconds with your back leg fairly straight.\",\"Switch sides and repeat.\"],\"img\":\"2999.webp\",\"gif\":\"2999.mp4\",\"cat\":\"stretching\",\"desc\":\"A calf and Achilles stretch with a band that gently pulls the toes toward you while the leg is behind you.\"},{\"id\":\"4027\",\"n\":\"resistance band standing back warming up\",\"bp\":\"back\",\"eq\":\"resistance band\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"rotator cuff\"],\"st\":[\"Stand tall holding the band with both hands in front of you.\",\"Keep a slight bend in your elbows.\",\"Pull the band apart and back, squeezing your shoulder blades together.\",\"Pause briefly then return slowly.\",\"Repeat for 10 to 15 easy reps without arching your lower back.\"],\"img\":\"4027.webp\",\"gif\":\"4027.mp4\",\"cat\":\"mobility\",\"desc\":\"A band warm-up that pulls the arms behind the body to activate the upper back and rear shoulders.\"},{\"id\":\"10820\",\"n\":\"resistance band standing balance bent leg hip abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"ankles\"],\"st\":[\"Place a band around your ankles or knees.\",\"Balance on one leg with a soft knee.\",\"Bend the other knee and lift it out to the side.\",\"Keep your torso upright.\",\"Return slowly.\",\"Finish the reps, then switch legs.\"],\"img\":\"10820.webp\",\"gif\":\"10820.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hip abduction on one leg with a band. The bent working knee changes the angle.\"},{\"id\":\"6798\",\"n\":\"resistance band standing balance glute kickback\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Loop the band around your ankles or hold it under your standing foot.\",\"Stand on one leg with a slight bend in the knee and brace your abs.\",\"Kick the other leg straight back against the band.\",\"Squeeze your glute at the top without arching your lower back.\",\"Return slowly with control.\",\"Finish all reps, then switch sides.\"],\"img\":\"6798.webp\",\"gif\":\"6798.mp4\",\"cat\":\"strength\",\"desc\":\"A standing band kickback that builds the glutes while challenging your balance on one leg.\"},{\"id\":\"7204\",\"n\":\"resistance band standing balance glute kickback v. 2\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Place the band around your ankles and stand tall on one leg.\",\"Hold a wall or rail for balance if needed.\",\"Keep a slight bend in your standing knee.\",\"Kick the other leg back, squeezing the glute.\",\"Return slowly without leaning forward.\",\"Finish all reps, then switch sides.\"],\"img\":\"7204.webp\",\"gif\":\"7204.mp4\",\"cat\":\"strength\",\"desc\":\"A second take on the band glute kickback, balancing on one leg while the other presses back.\"},{\"id\":\"8085\",\"n\":\"resistance band standing balance hip abduction\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"ankles\"],\"st\":[\"Put a band around your ankles and stand on one leg.\",\"Hold something for balance if needed.\",\"Lift the free leg out to the side.\",\"Keep your torso upright.\",\"Lower slowly and switch legs after your set.\"],\"img\":\"8085.webp\",\"gif\":\"8085.mp4\",\"cat\":\"strength\",\"desc\":\"A standing hip abduction with a band that also challenges your balance. It targets the outer hips.\",\"fv\":\"6736\"},{\"id\":\"4025\",\"n\":\"resistance band standing down warming up\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall and hold the band overhead with both hands, a little wider than shoulder width.\",\"Keep your ribs down and core braced.\",\"Pull your hands down in front of you toward your chest.\",\"Return slowly overhead keeping tension.\",\"Repeat for 10 to 15 easy reps.\"],\"img\":\"4025.webp\",\"gif\":\"4025.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle band warm-up that pulls the arms down from overhead to prepare the shoulders and upper back.\"},{\"id\":\"6441\",\"n\":\"resistance band standing external rotation\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Anchor the band at elbow height and stand sideways to it.\",\"Hold the handle with the far hand, elbow bent 90 degrees and tucked at your side.\",\"Rotate the forearm outward, keeping the elbow pinned.\",\"Pause when your hand points forward or slightly out.\",\"Return slowly under control.\",\"Finish your reps, then switch sides.\"],\"img\":\"6441.webp\",\"gif\":\"6441.mp4\",\"cat\":\"rehab\",\"desc\":\"Rotating the forearm outward against a band, elbow at your side. It strengthens the small rotator cuff muscles that steady the shoulder.\"},{\"id\":\"3000\",\"n\":\"resistance band standing forward achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"resistance band\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Loop a resistance band around the ball of your front foot.\",\"Hold the band ends and stand tall.\",\"Place the front heel on the floor with the toes lifted.\",\"Pull the band so your toes draw toward you and lean slightly forward.\",\"Hold for 20-30 seconds with a comfortable stretch.\",\"Switch feet and repeat.\"],\"img\":\"3000.webp\",\"gif\":\"3000.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing calf stretch with a band around the forward foot, pulling the toes back to lengthen the Achilles area.\"},{\"id\":\"4026\",\"n\":\"resistance band standing front warming up\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"rotator cuff\"],\"st\":[\"Stand tall with feet hip-width apart and hold the band in front of you at shoulder height.\",\"Keep your arms mostly straight.\",\"Move your hands apart, stretching the band across your chest.\",\"Bring your hands back together slowly.\",\"Repeat for 10 to 15 easy reps.\"],\"img\":\"4026.webp\",\"gif\":\"4026.mp4\",\"cat\":\"mobility\",\"desc\":\"A band warm-up with the arms moving in front of the body, loosening the shoulders and chest before a workout.\"},{\"id\":\"3853\",\"n\":\"resistance band standing hip abduction\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hip flexors\"],\"st\":[\"Loop the band around your ankles or anchor it to one foot.\",\"Stand tall holding a support if needed.\",\"Lift one leg out to the side, keeping your toes forward.\",\"Return slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"3853.webp\",\"gif\":\"3853.mp4\",\"cat\":\"strength\",\"desc\":\"A standing leg lift to the side against band tension. It trains your outer hips and glutes.\"},{\"id\":\"11570\",\"n\":\"resistance band standing hip extension\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Loop the band around your ankles or secure it low, and stand tall.\",\"Hold a support for balance.\",\"Keep your core tight.\",\"Kick one leg straight back without arching the back.\",\"Squeeze the glute at the end.\",\"Return slowly, then switch legs.\"],\"img\":\"11570.webp\",\"gif\":\"11570.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you extend one leg behind you against band tension to work the glutes.\"},{\"id\":\"4024\",\"n\":\"resistance band standing overhead warming up\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rotator cuff\",\"triceps\"],\"st\":[\"Stand tall with feet hip-width apart and hold the band with both hands at chest height.\",\"Keep a slight tension in the band.\",\"Raise your arms overhead in a smooth arc.\",\"Lower back to chest height slowly.\",\"Repeat for 10 to 15 easy reps without shrugging.\"],\"img\":\"4024.webp\",\"gif\":\"4024.mp4\",\"cat\":\"mobility\",\"desc\":\"A light band warm-up that presses the arms overhead to wake up the shoulders before training.\"},{\"id\":\"8361\",\"n\":\"resistance band standing shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Anchor the band at elbow height and stand sideways to it.\",\"Hold the handle with the elbow tucked at your side, bent 90 degrees.\",\"Rotate your forearm outward away from your belly, keeping the elbow fixed.\",\"Pause, then return slowly.\",\"Complete the reps, then switch sides.\"],\"img\":\"8361.webp\",\"gif\":\"8361.mp4\",\"cat\":\"rehab\",\"desc\":\"A band drill that strengthens the small rotator cuff muscles on the back of the shoulder.\"},{\"id\":\"8360\",\"n\":\"resistance band standing shoulder internal rotation\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"lats\"],\"st\":[\"Anchor the band at elbow height and stand sideways to it.\",\"Tuck your elbow against your side with the forearm pointing forward.\",\"Rotate your forearm across your belly, keeping the elbow fixed.\",\"Return slowly to the start.\",\"Finish the reps, then switch sides.\"],\"img\":\"8360.webp\",\"gif\":\"8360.mp4\",\"cat\":\"rehab\",\"desc\":\"A light band drill that strengthens the internal rotators of the shoulder, handy for joint health.\"},{\"id\":\"11569\",\"n\":\"resistance band standing side leg raise\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hip flexors\"],\"st\":[\"Loop the band around your ankles or above the knees and stand tall.\",\"Hold onto something for balance if needed.\",\"Lift one leg out to the side with a straight knee.\",\"Pause at the top without leaning.\",\"Lower slowly.\",\"Finish your reps and switch legs.\"],\"img\":\"11569.webp\",\"gif\":\"11569.mp4\",\"cat\":\"strength\",\"desc\":\"Standing, you lift one leg out to the side against band tension, working the outer hips.\"},{\"id\":\"8362\",\"n\":\"resistance band standing single arm lateral raise\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand on the band and hold the handle in one hand at your side.\",\"Keep a slight bend in the elbow and your torso still.\",\"Raise your arm out to the side up to shoulder height.\",\"Lower slowly against the band.\",\"Complete the reps, then switch arms.\"],\"img\":\"8362.webp\",\"gif\":\"8362.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm side raise using band tension to train the middle part of the shoulder.\"},{\"id\":\"6440\",\"n\":\"resistance band standing single arm lateral shoulder extension\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\"],\"st\":[\"Anchor the band at about waist height and stand sideways to it.\",\"Hold the handle with the far hand, arm across your body.\",\"Keep your chest tall and core braced.\",\"Sweep the arm out and slightly back to the side with a soft elbow.\",\"Return slowly to the start without letting the band snap.\",\"Complete all reps, then turn around and switch arms.\"],\"img\":\"6440.webp\",\"gif\":\"6440.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm band move that pulls the arm out and back to the side. It works the shoulder and the muscles behind it.\"},{\"id\":\"6439\",\"n\":\"resistance band standing single arm shoulder flexion\",\"bp\":\"shoulders\",\"eq\":\"resistance band\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"core\"],\"st\":[\"Stand on the band with one foot and hold the handle at your thigh, palm down.\",\"Brace your core and keep your torso upright.\",\"Raise the arm forward to shoulder height with a slight elbow bend.\",\"Pause briefly at the top.\",\"Lower slowly against the band tension.\",\"Finish your reps, then switch arms.\"],\"img\":\"6439.webp\",\"gif\":\"6439.mp4\",\"cat\":\"strength\",\"desc\":\"Raising one arm forward against band tension. It trains the front of the shoulder with smooth control.\"},{\"id\":\"10741\",\"n\":\"resistance band standing single arm triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"resistance band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\"],\"st\":[\"Stand tall and hold a band behind your back with one hand low.\",\"Raise the other arm overhead and bend the elbow, holding the band.\",\"Gently pull down with the lower hand.\",\"Feel a stretch in the back of the upper arm.\",\"Hold for 20-30 seconds.\",\"Switch arms.\"],\"img\":\"10741.webp\",\"gif\":\"10741.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing triceps stretch with a band assisting. The band helps you ease into a deeper stretch.\"},{\"id\":\"10536\",\"n\":\"resistance band standing single leg knee extension\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"quads\",\"mg\":\"core\",\"sm\":[\"core\",\"ankles\"],\"st\":[\"Anchor a band behind you and loop it around one ankle or behind the knee.\",\"Stand tall and hold on for balance if needed.\",\"Straighten your knee against the band.\",\"Pause with the leg extended.\",\"Bend slowly back, then switch legs after your reps.\"],\"img\":\"10536.webp\",\"gif\":\"10536.mp4\",\"cat\":\"strength\",\"desc\":\"Standing on one leg with a band behind the knee, you straighten the other knee. It builds quad strength with gentle load.\"},{\"id\":\"8608\",\"n\":\"resistance band sumo squat\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Stand on the band with feet wider than shoulders and toes angled out.\",\"Hold the band at your chest or shoulders.\",\"Sit down between your legs, keeping your chest up.\",\"Push your knees out over your toes.\",\"Drive up through your heels and squeeze your glutes.\"],\"img\":\"8608.webp\",\"gif\":\"8608.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance squat with a band adding resistance to the glutes and inner thighs.\"},{\"id\":\"2166\",\"n\":\"resistance band supine hip bridge march\",\"bp\":\"upper legs\",\"eq\":\"resistance band\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with a band around your thighs and your knees bent.\",\"Lift your hips into a bridge and squeeze your glutes.\",\"Lift one foot off the floor, drawing the knee toward your chest.\",\"Lower it and lift the other foot, keeping your hips level.\",\"Continue alternating at a steady pace, then lower your hips.\"],\"img\":\"2166.webp\",\"gif\":\"2166.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge held while you march your knees one at a time against a band, testing hip stability.\"},{\"id\":\"10761\",\"n\":\"resistance band toe side walk\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"hip flexors\",\"feet\"],\"st\":[\"Place a band around your ankles.\",\"Rise onto your toes with knees slightly bent.\",\"Step sideways in small steps.\",\"Keep tension on the band.\",\"Do not let your heels drop.\",\"Walk one way, then back.\"],\"img\":\"10761.webp\",\"gif\":\"10761.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways walk on your toes against band tension. It works calves, ankles and outer hips.\"},{\"id\":\"2463\",\"n\":\"resistance band toe touch\",\"bp\":\"waist\",\"eq\":\"band\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"lower abs\"],\"st\":[\"Lie on your back with a band around your feet.\",\"Lift your legs toward the ceiling.\",\"Hold the band ends and reach toward your toes.\",\"Curl your shoulders off the floor.\",\"Lower with control.\",\"Repeat for the planned reps.\"],\"img\":\"2463.webp\",\"gif\":\"2463.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch variation where you reach up to your toes with band tension.\"},{\"id\":\"10760\",\"n\":\"resistance band toe walk\",\"bp\":\"lower legs\",\"eq\":\"band\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Place a band around your forefeet or ankles.\",\"Rise onto the balls of your feet.\",\"Walk forward in small controlled steps.\",\"Stay high on your toes.\",\"Keep your hips level.\",\"Walk for 20-30 steps.\"],\"img\":\"10760.webp\",\"gif\":\"10760.mp4\",\"cat\":\"strength\",\"desc\":\"A walk on your toes with a band around your feet. It builds calf and ankle strength.\"},{\"id\":\"4688\",\"n\":\"resistance band triceps pushdown\",\"bp\":\"upper arms\",\"eq\":\"resistance band\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Anchor the band high and hold the handles with elbows bent at your sides.\",\"Keep your elbows pinned.\",\"Press the handles down until your arms are straight.\",\"Squeeze your triceps for a moment.\",\"Return slowly to the start.\"],\"img\":\"4688.webp\",\"gif\":\"4688.mp4\",\"cat\":\"strength\",\"desc\":\"A pushdown against a band anchored overhead that isolates the triceps.\",\"fv\":\"5268\"},{\"id\":\"3512\",\"n\":\"resistance band upper body dead bug\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"obliques\",\"lats\"],\"st\":[\"Lie on your back with knees bent over your hips, holding a band in both hands above your chest.\",\"Press your lower back into the floor.\",\"Pull one hand overhead while stretching the band.\",\"Bring it back and alternate.\",\"Keep your ribs down and core braced.\",\"Move slowly.\"],\"img\":\"3512.webp\",\"gif\":\"3512.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug with a band held in the hands, pulling it as the arms move. It builds core stability.\"},{\"id\":\"3792\",\"n\":\"resistance band upper body lying air bike\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Lie on your back with the band anchored behind your head, a handle in each hand.\",\"Lift your shoulders and legs slightly off the floor.\",\"Alternate pulling one handle toward your opposite knee in a pedalling motion.\",\"Keep your lower back pressed down.\",\"Continue at a steady pace for your set.\"],\"img\":\"3792.webp\",\"gif\":\"3792.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you pedal your arms against the band like a bicycle. It hits your abs with added resistance.\"},{\"id\":\"7282\",\"n\":\"resistance band walk\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Place a band around your thighs or ankles.\",\"Sit into a slight squat with feet hip width apart.\",\"Step sideways, keeping tension in the band.\",\"Bring the trailing foot in without letting the band go slack.\",\"Walk back the other way to even it out.\"],\"img\":\"7282.webp\",\"gif\":\"7282.mp4\",\"cat\":\"strength\",\"desc\":\"Walking with a band around the legs to fire up the outer hips and glutes.\",\"fv\":\"2416\"},{\"id\":\"10331\",\"n\":\"resistance band weighted standing pronation twist curl (arm wrestler)\",\"bp\":\"upper arms\",\"eq\":\"resistance band\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"wrist flexors\"],\"st\":[\"Stand on a resistance band and hold the handle with your palm turned to the side.\",\"Curl the handle up while rotating your wrist.\",\"Finish with your palm facing you and the biceps squeezed.\",\"Lower slowly and untwist back to the start.\",\"Keep your elbow tucked. Finish the reps, then switch arms.\"],\"img\":\"10331.webp\",\"gif\":\"10331.mp4\",\"cat\":\"strength\",\"desc\":\"A curl that adds a forearm twist, mimicking arm wrestling to build the biceps and forearms.\"},{\"id\":\"8002\",\"n\":\"resistance band wide stance anti rotation chop\",\"bp\":\"waist\",\"eq\":\"resistance band\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Anchor the band at one side and stand sideways with your feet wide.\",\"Hold the handle with both hands.\",\"Brace your core.\",\"Press or chop diagonally while keeping your torso square.\",\"Return slowly. Switch sides after your set.\"],\"img\":\"8002.webp\",\"gif\":\"8002.mp4\",\"cat\":\"strength\",\"desc\":\"A band chop in a wide stance where you resist twisting. It strengthens the abs and obliques.\"},{\"id\":\"7850\",\"n\":\"reverse air cycling\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back and lift your hips slightly with hands under your glutes.\",\"Raise your legs.\",\"Pedal backward in a smooth circle.\",\"Keep your lower back pressed down.\",\"Continue for a set time or reps.\"],\"img\":\"7850.webp\",\"gif\":\"7850.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lie on your back with your hips raised, pedalling the legs in a backward motion. It targets the lower abs.\"},{\"id\":\"4777\",\"n\":\"reverse back extension on floor\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down with arms extended in front or under your head.\",\"Keep your legs straight.\",\"Raise both legs off the floor by squeezing your glutes.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"4777.webp\",\"gif\":\"4777.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you lift your legs behind you to extend the hips. It strengthens the glutes and lower back.\"},{\"id\":\"1782\",\"n\":\"reverse chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall and clasp your hands behind your back with straight arms.\",\"Lift your hands up and away from your body while opening your chest.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1782.webp\",\"gif\":\"1782.mp4\",\"cat\":\"stretching\",\"desc\":\"Clasping your hands behind your back and lifting them stretches the chest and front of the shoulders. It is a classic posture reset.\"},{\"id\":\"4330\",\"n\":\"reverse crunch kick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with arms by your sides and knees bent over your hips.\",\"Curl your hips off the floor, bringing your knees toward your chest.\",\"Kick your feet up toward the ceiling.\",\"Lower your hips slowly and bend your knees again.\",\"Avoid swinging; use your abs to lift.\"],\"img\":\"4330.webp\",\"gif\":\"4330.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse crunch finished with a leg kick upward, hitting the lower abs.\"},{\"id\":\"4097\",\"n\":\"reverse crunch to dead bug\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with knees bent over your hips.\",\"Curl your pelvis off the floor in a reverse crunch.\",\"Lower your hips and extend one leg and the opposite arm.\",\"Return to the start, then repeat on the other side.\",\"Keep your lower back flat.\"],\"img\":\"4097.webp\",\"gif\":\"4097.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse crunch that flows into a dead bug, training lower abs and control of the trunk.\"},{\"id\":\"4019\",\"n\":\"reverse crunch v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent.\",\"Lift your legs.\",\"Curl hips off the floor.\",\"Lower slowly.\",\"Do not swing.\"],\"img\":\"4019.webp\",\"gif\":\"4019.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Curl the knees and hips up toward the chest. It works the lower abs.\"},{\"id\":\"4778\",\"n\":\"reverse crunch v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your arms by your sides.\",\"Lift your knees to a tabletop position.\",\"Curl your hips off the floor, bringing your knees toward your chest.\",\"Pause at the top.\",\"Lower slowly without swinging.\"],\"img\":\"4778.webp\",\"gif\":\"4778.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you curl your hips off the floor to bring your knees toward your chest. It targets the lower abs.\"},{\"id\":\"4779\",\"n\":\"reverse flutter kick on floor (hand under head)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back and place your hands under your head.\",\"Lift your legs a few inches off the floor.\",\"Kick up and down alternately in small, quick motions.\",\"Keep your lower back pressed down.\",\"Continue for the set time.\"],\"img\":\"4779.webp\",\"gif\":\"4779.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face up with your hands under your head, you do small alternating kicks. It works the lower abs.\"},{\"id\":\"4980\",\"n\":\"reverse flutter kick on floor (hand under head) v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back with your hands under your head and legs extended.\",\"Lift both heels a few inches off the floor and press your lower back down.\",\"Kick one leg up higher while the other goes down, then switch in a steady rhythm.\",\"Keep your legs fairly straight and your core tight.\",\"Stop the set when your lower back starts to arch.\"],\"img\":\"4980.webp\",\"gif\":\"4980.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Alternating small leg kicks while lying on your back with hands under your head. It works the lower abs and hip flexors.\"},{\"id\":\"5803\",\"n\":\"reverse hyperextension on bench\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down on a bench with your hips at the edge and legs hanging.\",\"Hold the bench for support.\",\"Squeeze your glutes and lift your legs until level with your body.\",\"Pause at the top.\",\"Lower your legs slowly without swinging.\"],\"img\":\"5803.webp\",\"gif\":\"5803.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down over a bench and lift your legs behind you. It strengthens the glutes and lower back.\"},{\"id\":\"9009\",\"n\":\"reverse hyperextension on stability ball\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie face down over the ball with your hands on the floor.\",\"Let your legs hang down with your toes light on the floor.\",\"Squeeze your glutes and raise both legs until they are in line with your body.\",\"Pause at the top.\",\"Lower slowly without swinging.\",\"Keep your hands planted and your core tight.\"],\"img\":\"9009.webp\",\"gif\":\"9009.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down over a ball, you lift your legs behind you to work the glutes and lower back.\"},{\"id\":\"4916\",\"n\":\"reverse leg extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Get on all fours with your hands under your shoulders.\",\"Brace your core and keep your back flat.\",\"Extend one leg back and up.\",\"Squeeze the glute at the top.\",\"Lower the leg without touching the floor.\",\"Finish your reps, then switch legs.\"],\"img\":\"4916.webp\",\"gif\":\"4916.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone or quadruped move where you extend the leg backward. It focuses on the glutes.\"},{\"id\":\"0676\",\"n\":\"reverse lunge (leg kick)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Step one leg back into a lunge.\",\"Push through the front heel to stand.\",\"Kick the rear leg forward.\",\"Place the foot down behind you for the next rep.\",\"Finish reps, then switch legs.\"],\"img\":\"0676.webp\",\"gif\":\"0676.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse lunge that ends with a forward kick. It trains the glutes and legs, and tests balance.\"},{\"id\":\"11088\",\"n\":\"reverse lunge arm reach twist\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"obliques\",\"core\"],\"st\":[\"Stand tall with your arms by your sides.\",\"Step one leg back into a lunge and reach both arms overhead.\",\"Twist your torso toward the front leg.\",\"Untwist, then push through your front foot to stand.\",\"Alternate legs for the set.\"],\"img\":\"11088.webp\",\"gif\":\"11088.mp4\",\"cat\":\"mobility\",\"desc\":\"A reverse lunge with an overhead reach and a twist. It warms up the legs, hips and spine together.\"},{\"id\":\"7412\",\"n\":\"reverse lunge high knee forward lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall with hands on hips.\",\"Step back into a reverse lunge.\",\"Drive that back leg forward into a high knee.\",\"Step the same leg forward into a forward lunge.\",\"Push back to standing and switch legs after your reps.\"],\"img\":\"7412.webp\",\"gif\":\"7412.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Combo lunge: step back, drive the knee up, then step forward into a lunge.\"},{\"id\":\"0867\",\"n\":\"reverse plank\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Sit on the floor with legs straight and hands behind your hips, fingers pointing forward.\",\"Press into your hands and heels to lift your hips.\",\"Straighten your body from head to heels.\",\"Squeeze your glutes and keep your shoulders away from your ears.\",\"Hold for 20-45 seconds.\",\"Lower your hips with control.\"],\"img\":\"0867.webp\",\"gif\":\"0867.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank held face up, supported on your hands and heels. It strengthens the back of the body and opens up the chest.\",\"hd\":1},{\"id\":\"5045\",\"n\":\"reverse plank on elbows\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Sit with legs extended and elbows under your shoulders.\",\"Press into your elbows and lift your hips.\",\"Form a straight line from head to heels.\",\"Squeeze your glutes and breathe steadily.\",\"Hold for 20-40 seconds.\"],\"img\":\"5045.webp\",\"gif\":\"5045.mp4\",\"cat\":\"isometric\",\"desc\":\"A hold with your back to the floor, supported on your elbows. It strengthens the entire back of the body.\",\"hd\":1},{\"id\":\"4934\",\"n\":\"reverse plank v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"triceps\"],\"st\":[\"Sit with your legs straight and your hands behind you.\",\"Press into your hands and lift your hips.\",\"Form a straight line from head to heels.\",\"Keep your chin neutral.\",\"Squeeze your glutes.\",\"Hold for 20-30 seconds.\"],\"img\":\"4934.webp\",\"gif\":\"4934.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank done face up, with a slightly different arm setup. It strengthens the back of the body and the core.\",\"hd\":1},{\"id\":\"3751\",\"n\":\"reverse push up\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\"],\"st\":[\"Sit on the floor and place your hands behind you, fingers pointing toward your hips.\",\"Lift your hips off the floor.\",\"Bend your elbows and lower your hips.\",\"Press back up to straight arms.\",\"Keep your elbows pointing back.\"],\"img\":\"3751.webp\",\"gif\":\"3751.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pushup where your hands are behind you, working the triceps hard.\"},{\"id\":\"1971\",\"n\":\"reverse shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"biceps\"],\"st\":[\"Stand tall and clasp your hands behind your back.\",\"Straighten your arms and lift your hands up and away from your body until the shoulders and chest stretch.\",\"Keep your chest open and avoid leaning forward.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1971.webp\",\"gif\":\"1971.mp4\",\"cat\":\"stretching\",\"desc\":\"Clasping your hands behind your back and lifting them to open the front of the shoulders.\"},{\"id\":\"4897\",\"n\":\"reverse sliding leg curl on floor with towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lie on your back with your heels on a towel on a smooth floor.\",\"Lift your hips into a bridge.\",\"Slide your feet away from you by extending the knees.\",\"Pull the heels back toward your hips with your hamstrings.\",\"Keep your hips high the whole set.\",\"Lower to the floor when you finish.\"],\"img\":\"4897.webp\",\"gif\":\"4897.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hamstring curl on a towel where you slide the heels away and pull them back. It is a challenging bodyweight hamstring move.\"},{\"id\":\"5913\",\"n\":\"reverse warrior pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"glutes\",\"adductors\"],\"st\":[\"Step into a wide warrior II stance.\",\"Bend your front knee over your ankle.\",\"Reach your front arm up and lean back.\",\"Rest your back hand on your leg.\",\"Hold for 5 slow breaths, then switch.\"],\"img\":\"5913.webp\",\"gif\":\"5913.mp4\",\"cat\":\"yoga\",\"desc\":\"A lunge with a back bend and one arm reaching up. Stretches the side body and strengthens the legs.\"},{\"id\":\"5899\",\"n\":\"revolved chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Stand and sink your hips back into a chair pose.\",\"Bring your palms together at your chest.\",\"Twist and hook one elbow outside the opposite knee.\",\"Hold for 5 slow breaths with your knees together.\",\"Untwist and repeat on the other side.\"],\"img\":\"5899.webp\",\"gif\":\"5899.mp4\",\"cat\":\"yoga\",\"desc\":\"A chair squat with a twist. Strengthens the legs while rotating the spine.\"},{\"id\":\"5908\",\"n\":\"revolved head to knee pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lats\"],\"st\":[\"Sit with one leg extended and the other foot against your inner thigh.\",\"Rotate your chest toward the extended leg.\",\"Reach one arm overhead and bend over the leg.\",\"Hold for 5 slow breaths.\",\"Rise and switch sides.\"],\"img\":\"5908.webp\",\"gif\":\"5908.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated side bend and twist over one extended leg. Stretches the side body and hamstrings.\"},{\"id\":\"5900\",\"n\":\"revolved side angle pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"adductors\",\"shoulders\"],\"st\":[\"Step into a lunge with your back heel lifted.\",\"Bring your palms together at your chest.\",\"Twist and hook your elbow outside the front knee.\",\"Hold for 5 slow breaths.\",\"Switch sides.\"],\"img\":\"5900.webp\",\"gif\":\"5900.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep lunge with a twist and the arms stretched wide. Builds leg strength and opens the spine.\"},{\"id\":\"0957\",\"n\":\"revolved side angle pose parivrtta parsvakonasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"hamstrings\",\"shoulders\"],\"st\":[\"Step into a long lunge with the back heel lifted.\",\"Bring your palms together at your chest.\",\"Twist your torso and hook the opposite elbow outside the front knee.\",\"Press your palms together and look up or ahead.\",\"Hold for 3 to 5 breaths, then switch sides.\"],\"img\":\"0957.webp\",\"gif\":\"0957.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep lunge with a twist and hands pressed together. It strengthens the legs and wrings out the spine.\"},{\"id\":\"5901\",\"n\":\"revolved triangle pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"lower back\",\"calves\"],\"st\":[\"Stand with your feet wide, back foot turned slightly.\",\"Hinge forward with a flat back.\",\"Place one hand down and reach the other arm up as you twist.\",\"Hold for 5 slow breaths.\",\"Come up and switch sides.\"],\"img\":\"5901.webp\",\"gif\":\"5901.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing forward bend with a twist. Stretches the back of the legs and rotates the spine.\"},{\"id\":\"5214\",\"n\":\"riding outdoor bicycle\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\",\"glutes\"],\"st\":[\"Adjust your saddle so your leg is almost straight at the bottom of the pedal stroke.\",\"Wear a helmet and check your brakes.\",\"Start at an easy pace to warm up.\",\"Pedal smoothly at a steady, comfortable rhythm for 20-60 minutes.\",\"Cool down with a few minutes of easy pedalling.\"],\"img\":\"5214.webp\",\"gif\":\"5214.mp4\",\"cat\":\"cardio\",\"desc\":\"Cycling outdoors at an easy to moderate pace. It is a low-impact way to build endurance.\",\"fv\":\"5215\"},{\"id\":\"4977\",\"n\":\"ring alternate superman\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"core\"],\"st\":[\"Put your feet in the rings and get into a face-down plank.\",\"Brace your core and keep your hips level.\",\"Lift one arm forward while holding steady.\",\"Return it and switch to the other arm.\",\"Avoid letting your lower back sag.\",\"Alternate sides for the full set.\"],\"img\":\"4977.webp\",\"gif\":\"4977.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A superman variation with your feet in rings, lifting opposite arm and leg in turn. It builds the lower back and core.\"},{\"id\":\"7512\",\"n\":\"ring archer pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"core\",\"grip muscles\"],\"st\":[\"Hang from rings with a wide grip.\",\"Pull up toward one hand, leaving the other arm straight.\",\"Reach the top with your chin by that hand.\",\"Lower under control.\",\"Alternate sides each rep.\"],\"img\":\"7512.webp\",\"gif\":\"7512.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull-up on rings where you pull toward one hand with the other arm extended.\"},{\"id\":\"6234\",\"n\":\"ring arm curl\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"core\"],\"st\":[\"Hold the rings and lean back.\",\"Extend your arms.\",\"Curl your hands toward your head.\",\"Keep your elbows up.\",\"Lower slowly.\",\"Keep your body in a straight line.\"],\"img\":\"6234.webp\",\"gif\":\"6234.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight curl using gymnastic rings. It builds the biceps.\"},{\"id\":\"4922\",\"n\":\"ring chest fly\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"biceps\"],\"st\":[\"Set the rings low and hold them in a plank position.\",\"Keep your arms nearly straight with a small bend in the elbows.\",\"Open your arms out to the sides, lowering your chest.\",\"Pull the rings back together with your chest.\",\"Keep your body in a straight line.\",\"Go only as wide as you can control.\"],\"img\":\"4922.webp\",\"gif\":\"4922.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A fly in the rings from a push up position. It stretches and works the chest with a lot of core control.\"},{\"id\":\"9316\",\"n\":\"ring elevated pike push up from deficit\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Set the rings low and put your hands on them with your feet on a box.\",\"Raise your hips into a pike shape.\",\"Lower your head between the rings.\",\"Keep the rings steady and close to your body.\",\"Press back up to straight arms.\",\"Keep your core tight.\"],\"img\":\"9316.webp\",\"gif\":\"9316.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pike push up with feet elevated and hands on rings, so you go deeper. It builds strong overhead pressing.\"},{\"id\":\"4818\",\"n\":\"ring elevated row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Set the rings at about chest height and rest your heels on a bench.\",\"Grab the rings and hang with arms extended and body straight.\",\"Pull your chest toward your hands, driving your elbows back.\",\"Squeeze your shoulder blades together at the top.\",\"Lower with control without letting your hips sag.\"],\"img\":\"4818.webp\",\"gif\":\"4818.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A ring row with the feet raised, making the bodyweight pull harder. It builds the upper back and biceps.\"},{\"id\":\"6252\",\"n\":\"ring face pull\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\"],\"st\":[\"Hold the rings and lean back.\",\"Extend your arms.\",\"Pull the rings toward your face.\",\"Flare your elbows out.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\"],\"img\":\"6252.webp\",\"gif\":\"6252.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A face pull on rings. It builds the rear delts and upper back.\"},{\"id\":\"4921\",\"n\":\"ring high row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rear deltoids\"],\"st\":[\"Hold the rings and lean back with a straight body.\",\"Pull the rings toward your forehead.\",\"Flare your elbows out and squeeze your shoulder blades.\",\"Pause briefly at the top.\",\"Lower until your arms are straight.\",\"Keep your hips up the whole time.\"],\"img\":\"4921.webp\",\"gif\":\"4921.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A row with the rings pulled toward your face, higher than a normal row. It builds the upper back and rear shoulders.\",\"fv\":\"5269\"},{\"id\":\"9313\",\"n\":\"ring isometric hold reverse ab rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lats\",\"shoulders\"],\"st\":[\"Hang or set yourself up with the rings under your forearms.\",\"Brace your core and tuck your pelvis.\",\"Move into the rollout position and stop.\",\"Keep your body in a straight line.\",\"Hold for 10-20 seconds.\",\"Return slowly.\"],\"img\":\"9313.webp\",\"gif\":\"9313.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding a reverse rollout position on rings challenges the abs and shoulders. A tough anti-extension hold.\",\"hd\":1},{\"id\":\"4978\",\"n\":\"ring kneeling ab rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"lower abs\",\"hip flexors\"],\"st\":[\"Kneel and hold the rings at about knee height with a firm grip.\",\"Brace your abs and keep a straight line from head to knees.\",\"Roll the rings forward by extending your arms until you are long but still in control.\",\"Pull the rings back toward your knees by contracting your abs.\",\"Do not let your lower back sag at any point.\"],\"img\":\"4978.webp\",\"gif\":\"4978.mp4\",\"cat\":\"strength\",\"desc\":\"Kneeling ab rollout on gymnastic rings. The unstable rings make your core work hard to keep the body straight as you extend.\"},{\"id\":\"4819\",\"n\":\"ring leg curl\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"calves\"],\"st\":[\"Lie on your back with your heels in the ring straps and legs extended.\",\"Lift your hips into a bridge.\",\"Bend your knees to pull your heels toward your glutes.\",\"Keep your hips high the whole time.\",\"Extend your legs slowly to return.\"],\"img\":\"4819.webp\",\"gif\":\"4819.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back with heels in the rings, you bridge up and curl your feet in. It hits the hamstrings hard.\"},{\"id\":\"4912\",\"n\":\"ring leg curl v. 2\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lie on your back with your heels in the rings.\",\"Lift your hips into a bridge.\",\"Pull the rings toward your glutes by bending the knees.\",\"Pause and squeeze the hamstrings.\",\"Extend your legs slowly back out.\",\"Keep your hips high throughout.\"],\"img\":\"4912.webp\",\"gif\":\"4912.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hamstring curl with the heels in rings, second variation. It builds hamstrings and glutes with an unstable setup.\"},{\"id\":\"10950\",\"n\":\"ring long arms push up hold\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\",\"upper back\"],\"st\":[\"Set the rings low and take a plank with your hands on them.\",\"Keep your arms straight and rings close to your sides.\",\"Squeeze your glutes and abs.\",\"Hold for 15-30 seconds.\",\"Lower to the floor to rest.\"],\"img\":\"10950.webp\",\"gif\":\"10950.mp4\",\"cat\":\"isometric\",\"desc\":\"A push-up hold on rings with arms fully extended. It demands shoulder stability and core tension.\",\"hd\":1},{\"id\":\"6237\",\"n\":\"ring one arm biceps curl\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"core\"],\"st\":[\"Hold one ring and lean back.\",\"Extend your arm.\",\"Curl your hand toward your head.\",\"Keep your elbow up.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"6237.webp\",\"gif\":\"6237.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-arm curl on a ring. It builds the biceps with a lot of control.\"},{\"id\":\"7517\",\"n\":\"ring one arm pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"core\",\"grip muscles\"],\"st\":[\"Hang from one ring with a firm grip.\",\"Brace your core and keep your legs together.\",\"Pull your chin up toward the ring.\",\"Lower with control to a full hang.\",\"Complete reps, then switch arms.\"],\"img\":\"7517.webp\",\"gif\":\"7517.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Advanced single-arm pull on a ring that demands serious back and arm strength.\"},{\"id\":\"5522\",\"n\":\"ring pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Grab the rings and hang with arms straight.\",\"Brace your core and pull your shoulders down.\",\"Pull until the rings reach your chest or chin passes them.\",\"Turn your palms slightly in as you rise if comfortable.\",\"Lower slowly to a full hang.\"],\"img\":\"5522.webp\",\"gif\":\"5522.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull-up on gymnastic rings, which move freely and demand extra stability from the back and arms.\"},{\"id\":\"8750\",\"n\":\"ring pullover\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"chest\",\"core\"],\"st\":[\"Hang from the rings with an overhand grip.\",\"Pull your hips up and bring your knees to your chest.\",\"Rotate backward, pulling the body over the rings.\",\"Lower under control.\",\"Keep the movement smooth.\"],\"img\":\"8750.webp\",\"gif\":\"8750.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced ring move that sweeps the body over the rings, working the lats and core.\"},{\"id\":\"10661\",\"n\":\"ring resistance band assisted single arm pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Hang a band from the rings or bar and place your foot in it.\",\"Grip one ring with one hand and hold the other ring loosely or let it go.\",\"Pull your chest toward the ring.\",\"Keep your body tight and avoid swinging.\",\"Lower slowly to a full hang.\",\"Repeat, then switch sides.\"],\"img\":\"10661.webp\",\"gif\":\"10661.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A band-assisted single-arm pull-up on gymnastic rings. The rings add instability and grip demand.\"},{\"id\":\"4820\",\"n\":\"ring reverse ab rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"shoulders\",\"hip flexors\",\"core\"],\"st\":[\"Set up in a push-up position with your feet in the ring straps.\",\"Keep your arms straight and shoulders over your hands.\",\"Pull your knees toward your chest by curling your pelvis.\",\"Pause with your hips lifted and abs tight.\",\"Extend your legs back to a straight plank slowly.\"],\"img\":\"4820.webp\",\"gif\":\"4820.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging or reclined rollout that drives the knees in under the rings. It strongly trains the lower abs and core.\"},{\"id\":\"4923\",\"n\":\"ring reverse fly\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Hold the rings with arms straight and lean back.\",\"Keep your body in a straight line.\",\"Open your arms out to the sides.\",\"Squeeze your shoulder blades together.\",\"Return slowly to the start.\",\"Keep your elbows only slightly bent.\"],\"img\":\"4923.webp\",\"gif\":\"4923.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A reverse fly using rings while leaning back. It trains the rear shoulders and upper back.\"},{\"id\":\"10662\",\"n\":\"ring rocky pull up pulldown\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"core\",\"forearms\"],\"st\":[\"Hang from the rings with arms straight and shoulders engaged.\",\"Pull your chest up toward the rings.\",\"At the top, drive the rings down toward your hips.\",\"Pause with your arms close to your sides.\",\"Return to the top, then lower slowly.\",\"Keep your core braced.\"],\"img\":\"10662.webp\",\"gif\":\"10662.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A ring pull-up variation where you pull up, then press down toward the hips. It builds pulling strength and shoulder control.\"},{\"id\":\"4979\",\"n\":\"ring rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"lats\"],\"st\":[\"Kneel holding rings under your shoulders.\",\"Brace your core and tuck your pelvis.\",\"Roll your arms forward, extending your body.\",\"Go as far as you can with a flat back.\",\"Pull back to the start using your abs.\",\"Keep your ribs down.\"],\"img\":\"4979.webp\",\"gif\":\"4979.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A rollout using gymnastic rings. The unstable rings make your core work hard.\"},{\"id\":\"6259\",\"n\":\"ring single arm rear delt row\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"biceps\"],\"st\":[\"Hold one ring and lean back.\",\"Extend your arm.\",\"Pull your elbow out and back.\",\"Squeeze the rear delt.\",\"Lower slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"6259.webp\",\"gif\":\"6259.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-arm row on a ring that focuses on the rear delt. It builds shoulder strength.\"},{\"id\":\"10663\",\"n\":\"ring skin the cat\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\",\"biceps\"],\"st\":[\"Hang from the rings with a firm grip.\",\"Tuck your knees and lift your hips overhead.\",\"Rotate backward, passing your legs between your arms.\",\"Lower your feet toward the floor until you stretch your shoulders.\",\"Pause, then reverse the motion with control.\",\"Move slowly and stop if you feel pinching.\"],\"img\":\"10663.webp\",\"gif\":\"10663.mp4\",\"cat\":\"mobility\",\"desc\":\"A gymnastic move where you rotate backward through the rings. It builds shoulder mobility and control.\"},{\"id\":\"7228\",\"n\":\"ring wide pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Grab the rings with a wide overhand grip and hang with arms straight.\",\"Brace your core.\",\"Pull your chest toward the rings, driving elbows down and out.\",\"Pause at the top.\",\"Lower slowly to a full hang.\"],\"img\":\"7228.webp\",\"gif\":\"7228.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up on rings with a wide grip. The unstable rings make the lats and stabilizers work harder.\"},{\"id\":\"2856\",\"n\":\"rocker with open legs\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"core\"],\"st\":[\"Sit and hold your ankles with your legs in a V.\",\"Balance on your tailbone.\",\"Roll back onto your shoulders.\",\"Roll up to balance again.\",\"Keep your back rounded.\"],\"img\":\"2856.webp\",\"gif\":\"2856.mp4\",\"cat\":\"pilates\",\"desc\":\"A balance and rolling move with the legs open in a V shape.\"},{\"id\":\"1584\",\"n\":\"rocket jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Squat down while swinging your arms back.\",\"Explode upward and reach both arms overhead as you jump.\",\"Extend your whole body like a rocket.\",\"Land softly on bent knees and reset before the next jump.\"],\"img\":\"1584.webp\",\"gif\":\"1584.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A deep squat followed by a big vertical jump with your arms reaching up. It builds explosive leg power.\"},{\"id\":\"2857\",\"n\":\"rocking\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\"],\"st\":[\"Lie face down and reach back to hold your ankles.\",\"Lift your chest and legs.\",\"Rock forward and back.\",\"Keep your movement smooth.\",\"Lower down to finish.\"],\"img\":\"2857.webp\",\"gif\":\"2857.mp4\",\"cat\":\"pilates\",\"desc\":\"A rocking move on the stomach that stretches the front and strengthens the back.\"},{\"id\":\"2936\",\"n\":\"rocking ankle stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"shins\"],\"st\":[\"Kneel on one knee with the front foot flat on the floor.\",\"Keep your front heel down.\",\"Rock your front knee forward over your toes until you feel a stretch.\",\"Rock back and forth slowly for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"2936.webp\",\"gif\":\"2936.mp4\",\"cat\":\"stretching\",\"desc\":\"Rocking forward over a bent knee to open the ankle and calf. It helps ankle mobility for squats and walking.\"},{\"id\":\"2947\",\"n\":\"roll anterior calf foam rolling\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Kneel on the floor and place the roller under the front of your shin.\",\"Support yourself with your hands on the floor.\",\"Roll slowly up and down the shin muscle.\",\"Pause on tight spots for a few seconds.\",\"Switch legs and keep the pressure comfortable.\"],\"img\":\"2947.webp\",\"gif\":\"2947.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling the front of the lower leg on a foam roller. It can loosen the muscles beside your shin.\"},{\"id\":\"5386\",\"n\":\"roll around the world lying on floor\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"trapezius\",\"rhomboids\"],\"st\":[\"Lie on your back with the roller under your upper back.\",\"Place the roller under the upper back and shoulders and let your body weight settle onto it.\",\"Sweep your arms in a wide arc overhead, like a snow angel.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5386.webp\",\"gif\":\"5386.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the upper back and shoulders. Good before training or on rest days to loosen up.\",\"fv\":\"5425\"},{\"id\":\"4470\",\"n\":\"roll ball adductors\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Place the ball under your inner thigh (adductors) while lying face down with your thigh turned out.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4470.webp\",\"gif\":\"4470.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the inner thigh (adductors). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4498\",\"n\":\"roll ball bicep brachii\",\"bp\":\"upper arms\",\"eq\":\"massage ball\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Place the ball under your front of the upper arm (biceps brachii) on a table or against a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4498.webp\",\"gif\":\"4498.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the front of the upper arm (biceps brachii). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4465\",\"n\":\"roll ball calf\",\"bp\":\"lower legs\",\"eq\":\"massage ball\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Place the ball under your calf while seated with your leg extended.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4465.webp\",\"gif\":\"4465.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the calf. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4611\",\"n\":\"roll ball deltoid posterior\",\"bp\":\"shoulders\",\"eq\":\"massage ball\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\"],\"st\":[\"Place a small ball between the back of your shoulder and a wall.\",\"Lean in until you feel moderate pressure.\",\"Roll slowly up, down and sideways over the rear deltoid.\",\"Pause on tight spots for a few breaths.\",\"Switch to the other shoulder.\"],\"img\":\"4611.webp\",\"gif\":\"4611.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a ball on the back of the shoulder to ease tension in the rear delts.\"},{\"id\":\"4482\",\"n\":\"roll ball diaphragm\",\"bp\":\"waist\",\"eq\":\"massage ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\"],\"st\":[\"Place the ball under your area just under the lower ribs while lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Use gentle pressure and breathe slowly so your stomach stays relaxed.\",\"Repeat on the other side if needed.\"],\"img\":\"4482.webp\",\"gif\":\"4482.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the area just under the lower ribs. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4480\",\"n\":\"roll ball erector spinae\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"core\"],\"st\":[\"Place the ball under your muscles beside the lower spine (erector spinae) while lying on your back.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep the ball beside the spine, never on it.\",\"Repeat on the other side if needed.\"],\"img\":\"4480.webp\",\"gif\":\"4480.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the muscles beside the lower spine (erector spinae). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4478\",\"n\":\"roll ball external oblique\",\"bp\":\"waist\",\"eq\":\"massage ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Place the ball under your side of the trunk (external oblique) while lying on your side.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4478.webp\",\"gif\":\"4478.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the side of the trunk (external oblique). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4462\",\"n\":\"roll ball foot\",\"bp\":\"lower legs\",\"eq\":\"massage ball\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"soleus\",\"ankles\"],\"st\":[\"Place the ball under your foot sole while seated or standing.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4462.webp\",\"gif\":\"4462.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the foot sole. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4496\",\"n\":\"roll ball forearm extensors\",\"bp\":\"lower arms\",\"eq\":\"massage ball\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"hands\"],\"st\":[\"Place the ball under your top of the forearm (extensors) on a table with your palm facing down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4496.webp\",\"gif\":\"4496.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the top of the forearm (extensors). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4494\",\"n\":\"roll ball forearm flexors\",\"bp\":\"lower arms\",\"eq\":\"massage ball\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Place the ball under your inside of the forearm (flexors) on a table with your palm facing up.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4494.webp\",\"gif\":\"4494.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the inside of the forearm (flexors). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4497\",\"n\":\"roll ball forearm pronator\",\"bp\":\"lower arms\",\"eq\":\"massage ball\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Place the ball under your inner forearm near the elbow (pronator) on a table with your palm facing up.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4497.webp\",\"gif\":\"4497.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the inner forearm near the elbow (pronator). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4495\",\"n\":\"roll ball forearm supinator\",\"bp\":\"lower arms\",\"eq\":\"massage ball\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"brachialis\"],\"st\":[\"Place the ball under your upper forearm (supinator) on a table with your arm resting on it.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4495.webp\",\"gif\":\"4495.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the upper forearm (supinator). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4472\",\"n\":\"roll ball gluteus medius\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Place the ball under your side of the glutes (gluteus medius) while lying on your side or leaning on a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4472.webp\",\"gif\":\"4472.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the side of the glutes (gluteus medius). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4477\",\"n\":\"roll ball iliacus abdominal region\",\"bp\":\"waist\",\"eq\":\"massage ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Place the ball under your iliacus area at the inner hip bone while lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Use gentle pressure and breathe slowly so your stomach stays relaxed.\",\"Repeat on the other side if needed.\"],\"img\":\"4477.webp\",\"gif\":\"4477.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the iliacus area at the inner hip bone. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4475\",\"n\":\"roll ball iliospsoas\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Place the ball under your deep hip flexor (iliopsoas) while lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Use gentle pressure and breathe slowly so your stomach stays relaxed.\",\"Repeat on the other side if needed.\"],\"img\":\"4475.webp\",\"gif\":\"4475.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the deep hip flexor (iliopsoas). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4485\",\"n\":\"roll ball infraspinatus\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Place the ball under your back of the shoulder blade (infraspinatus) while leaning back against a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4485.webp\",\"gif\":\"4485.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the back of the shoulder blade (infraspinatus). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4486\",\"n\":\"roll ball infraspinatus v. 2\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Place the ball under your back of the shoulder blade (infraspinatus) while lying on your back on the floor.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4486.webp\",\"gif\":\"4486.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the back of the shoulder blade (infraspinatus). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4469\",\"n\":\"roll ball lateral vastus\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"quads\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\"],\"st\":[\"Place the ball under your outer thigh (lateral vastus) while lying on your side.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4469.webp\",\"gif\":\"4469.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the outer thigh (lateral vastus). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4493\",\"n\":\"roll ball latissimus dorsi\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\"],\"st\":[\"Place the ball under your side of the back (latissimus dorsi) while lying on your side with your arm overhead.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4493.webp\",\"gif\":\"4493.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the side of the back (latissimus dorsi). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4600\",\"n\":\"roll ball lower back\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie on your back with a small ball under one side of your lower back.\",\"Bend your knees and keep your feet flat on the floor.\",\"Shift your weight slowly so the ball rolls along the muscle next to the spine.\",\"Pause on tender spots for a few breaths, then move on.\",\"Switch sides and keep the pressure comfortable, never on the spine itself.\"],\"img\":\"4600.webp\",\"gif\":\"4600.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling a small ball under your lower back to release tight spots and loosen the muscles beside the spine.\"},{\"id\":\"4481\",\"n\":\"roll ball lumbar diagonal\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"obliques\"],\"st\":[\"Place the ball under your lower back at a diagonal angle while lying on your back with your hips slightly rotated.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep the ball beside the spine, never on it.\",\"Repeat on the other side if needed.\"],\"img\":\"4481.webp\",\"gif\":\"4481.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the lower back at a diagonal angle. A simple way to loosen tight spots before or after training.\"},{\"id\":\"6769\",\"n\":\"roll ball lying semispinalis capitis muscle activation\",\"bp\":\"neck\",\"eq\":\"massage ball\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Lie on your back with knees bent and a small ball under the base of your skull.\",\"Relax your head onto the ball.\",\"Make small nods or turns to roll over the muscle.\",\"Keep the pressure gentle.\",\"Breathe slowly.\",\"Continue for 30-60 seconds.\"],\"img\":\"6769.webp\",\"gif\":\"6769.mp4\",\"cat\":\"mobility\",\"desc\":\"Lying on your back with a ball under the base of the skull. It releases the deep muscles at the back of the neck.\"},{\"id\":\"3569\",\"n\":\"roll ball pectoral release\",\"bp\":\"chest\",\"eq\":\"massage ball\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Place a ball between your chest and a wall, just below the collarbone.\",\"Lean in until you feel pressure on the chest muscle.\",\"Roll slowly in small circles or up and down.\",\"Hold on tender spots for a few breaths.\",\"Switch sides after about 30-60 seconds.\"],\"img\":\"3569.webp\",\"gif\":\"3569.mp4\",\"cat\":\"mobility\",\"desc\":\"Pin a ball between your chest and a wall to release tight pectoral muscles.\"},{\"id\":\"4484\",\"n\":\"roll ball pectoralis major clavicular\",\"bp\":\"chest\",\"eq\":\"massage ball\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\"],\"st\":[\"Place the ball under your upper chest below the collarbone while leaning on a wall or lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4484.webp\",\"gif\":\"4484.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the upper chest below the collarbone. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4483\",\"n\":\"roll ball pectoralis major sternal\",\"bp\":\"chest\",\"eq\":\"massage ball\",\"tg\":\"pectorals\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Place the ball under your mid chest (sternal pectoralis major) while leaning on a wall or lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4483.webp\",\"gif\":\"4483.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the mid chest (sternal pectoralis major). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4463\",\"n\":\"roll ball peroneus\",\"bp\":\"lower legs\",\"eq\":\"massage ball\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Place the ball under your outer lower leg (peroneus muscles) while sitting on the floor with your leg extended.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4463.webp\",\"gif\":\"4463.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the outer lower leg (peroneus muscles). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4473\",\"n\":\"roll ball piriformis\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Place the ball under your deep glutes (piriformis) while sitting on the floor with your ankle over the opposite knee.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4473.webp\",\"gif\":\"4473.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the deep glutes (piriformis). A simple way to loosen tight spots before or after training.\"},{\"id\":\"3568\",\"n\":\"roll ball piriformis release\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\"],\"st\":[\"Sit on the floor and place a ball under one buttock.\",\"Cross that ankle over the opposite knee for more access.\",\"Shift your weight to find a tender spot and stay there.\",\"Breathe slowly for 20-30 seconds, then roll gently.\",\"Switch sides.\"],\"img\":\"3568.webp\",\"gif\":\"3568.mp4\",\"cat\":\"mobility\",\"desc\":\"Use a small ball under the buttock to ease tension in the piriformis and deep hip muscles.\"},{\"id\":\"4474\",\"n\":\"roll ball piriformis v. 2\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Place the ball under your deep glutes (piriformis) while lying on your back with your knee falling across your body.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4474.webp\",\"gif\":\"4474.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the deep glutes (piriformis). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4466\",\"n\":\"roll ball popliteal\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"soleus\"],\"st\":[\"Place the ball under your back of the knee (popliteal area) while sitting on the floor with your knee gently bent.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Use very light pressure here and stop if you feel tingling.\",\"Repeat on the other side if needed.\"],\"img\":\"4466.webp\",\"gif\":\"4466.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the back of the knee (popliteal area). A simple way to loosen tight spots before or after training.\"},{\"id\":\"6766\",\"n\":\"roll ball posterior tibialis (single leg) side lying on floor\",\"bp\":\"lower legs\",\"eq\":\"massage ball\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"shins\",\"ankles\"],\"st\":[\"Lie on your side with a small ball under the inside of your lower leg.\",\"Support yourself with your hands and the other leg.\",\"Slowly roll the leg along the ball from calf toward ankle.\",\"Pause on tender spots with light pressure.\",\"Breathe and relax the leg.\",\"Roll for 30-60 seconds, then switch legs.\"],\"img\":\"6766.webp\",\"gif\":\"6766.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling a ball under the inner lower leg while lying on your side. It releases the deep calf muscle that supports the arch.\"},{\"id\":\"4476\",\"n\":\"roll ball psoas abdominal region\",\"bp\":\"waist\",\"eq\":\"massage ball\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Place the ball under your psoas area beside the belly button while lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Use gentle pressure and breathe slowly so your stomach stays relaxed.\",\"Repeat on the other side if needed.\"],\"img\":\"4476.webp\",\"gif\":\"4476.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the psoas area beside the belly button. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4479\",\"n\":\"roll ball rectus abdominis\",\"bp\":\"waist\",\"eq\":\"massage ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"lower abs\"],\"st\":[\"Place the ball under your front abdomen (rectus abdominis) while lying face down.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Use gentle pressure and breathe slowly so your stomach stays relaxed.\",\"Repeat on the other side if needed.\"],\"img\":\"4479.webp\",\"gif\":\"4479.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the front abdomen (rectus abdominis). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4468\",\"n\":\"roll ball rectus femoris\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Place the ball under your front of the thigh (rectus femoris) while lying face down on the floor.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4468.webp\",\"gif\":\"4468.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the front of the thigh (rectus femoris). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4489\",\"n\":\"roll ball rhomboid\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\"],\"st\":[\"Place the ball under your area between the spine and shoulder blade (rhomboids) while leaning back against a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4489.webp\",\"gif\":\"4489.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the area between the spine and shoulder blade (rhomboids). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4487\",\"n\":\"roll ball scapula levator\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Place the ball under your top inner shoulder blade (levator scapulae) while leaning back against a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4487.webp\",\"gif\":\"4487.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the top inner shoulder blade (levator scapulae). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4488\",\"n\":\"roll ball scapula levator v. 2\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Place the ball under your top inner shoulder blade (levator scapulae) while lying on your back on the floor.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4488.webp\",\"gif\":\"4488.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the top inner shoulder blade (levator scapulae). A simple way to loosen tight spots before or after training.\"},{\"id\":\"6812\",\"n\":\"roll ball seated pectineus activation\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\",\"hip flexors\"],\"st\":[\"Sit tall on a chair with a ball between your knees.\",\"Place your feet flat and keep your back straight.\",\"Squeeze the ball gently with your thighs.\",\"Hold the squeeze for 5-10 seconds.\",\"Relax and repeat several times.\"],\"img\":\"6812.webp\",\"gif\":\"6812.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated move using a ball to wake up the inner upper thigh. It works the pectineus and the nearby adductors.\"},{\"id\":\"6767\",\"n\":\"roll ball side lying scalene muscles activation\",\"bp\":\"neck\",\"eq\":\"massage ball\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie on your side with a small ball under the side of your neck.\",\"Support your head with a pillow or your hand.\",\"Relax your shoulder.\",\"Gently press or nod to roll over the ball.\",\"Keep the pressure light.\",\"Do 30-60 seconds, then switch sides.\"],\"img\":\"6767.webp\",\"gif\":\"6767.mp4\",\"cat\":\"mobility\",\"desc\":\"Lying on your side with a ball at the neck to ease the scalene muscles. Use light pressure.\"},{\"id\":\"6768\",\"n\":\"roll ball side lying scalene muscles activation (side pov)\",\"bp\":\"neck\",\"eq\":\"massage ball\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie on your side with a small ball under the side of your neck.\",\"Support your head so your neck stays neutral.\",\"Relax your shoulder.\",\"Gently move your head to roll over the ball.\",\"Keep the pressure light.\",\"Do 30-60 seconds, then switch sides.\"],\"img\":\"6768.webp\",\"gif\":\"6768.mp4\",\"cat\":\"mobility\",\"desc\":\"The same side-lying scalene release as seen from the side. A ball at the neck eases the muscles with light pressure.\"},{\"id\":\"4471\",\"n\":\"roll ball tensor fasciae latae\",\"bp\":\"upper legs\",\"eq\":\"massage ball\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Place the ball under your front outer hip (tensor fasciae latae) while lying on your side.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4471.webp\",\"gif\":\"4471.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the front outer hip (tensor fasciae latae). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4464\",\"n\":\"roll ball tibialis anterior\",\"bp\":\"lower legs\",\"eq\":\"massage ball\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Place the ball under your shin (tibialis anterior) while kneeling or sitting on the floor.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4464.webp\",\"gif\":\"4464.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the shin (tibialis anterior). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4467\",\"n\":\"roll ball tibialis posterior\",\"bp\":\"lower legs\",\"eq\":\"massage ball\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"soleus\",\"ankles\"],\"st\":[\"Place the ball under your inner calf (tibialis posterior) while sitting on the floor with your leg rotated outward.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4467.webp\",\"gif\":\"4467.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the inner calf (tibialis posterior). A simple way to loosen tight spots before or after training.\"},{\"id\":\"4491\",\"n\":\"roll ball trapezius lower\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\"],\"st\":[\"Place the ball under your lower trapezius while leaning back against a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4491.webp\",\"gif\":\"4491.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the lower trapezius. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4492\",\"n\":\"roll ball trapezius lower v. 2\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\"],\"st\":[\"Place the ball under your lower trapezius while lying on your back on the floor.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4492.webp\",\"gif\":\"4492.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the lower trapezius. A simple way to loosen tight spots before or after training.\"},{\"id\":\"4490\",\"n\":\"roll ball trapezius upper\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\"],\"st\":[\"Place the ball under your upper trapezius while leaning back against a wall.\",\"Shift your weight onto the ball until you feel moderate, tolerable pressure.\",\"Roll slowly back and forth over a short range, about 2-3 cm at a time.\",\"When you find a tender spot, pause on it and breathe for 20-30 seconds.\",\"Keep your breathing steady and avoid rolling over bone or joints.\",\"Repeat on the other side if needed.\"],\"img\":\"4490.webp\",\"gif\":\"4490.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a small ball to ease tension in the upper trapezius. A simple way to loosen tight spots before or after training.\"},{\"id\":\"3570\",\"n\":\"roll ball upper trapezius release\",\"bp\":\"back\",\"eq\":\"massage ball\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\"],\"st\":[\"Stand with your back to a wall and place a ball on top of one shoulder.\",\"Lean into the wall to press the ball into the muscle.\",\"Move slowly by bending your knees.\",\"Pause on tender spots and breathe.\",\"Switch to the other shoulder.\"],\"img\":\"3570.webp\",\"gif\":\"3570.mp4\",\"cat\":\"mobility\",\"desc\":\"Roll a ball against a wall under the top of your shoulder to relieve tight upper trapezius muscles.\"},{\"id\":\"5374\",\"n\":\"roll biceps lying on floor\",\"bp\":\"upper arms\",\"eq\":\"roller\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Lie face down with the roller under one upper arm.\",\"Place the roller under the biceps and let your body weight settle onto it.\",\"Roll slowly from the elbow toward the shoulder.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5374.webp\",\"gif\":\"5374.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the biceps. Good before training or on rest days to loosen up.\",\"fv\":\"5413\"},{\"id\":\"5377\",\"n\":\"roll chest lying on floor\",\"bp\":\"chest\",\"eq\":\"roller\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\"],\"st\":[\"Lie face down with the roller under one side of your chest.\",\"Place the roller under the chest and let your body weight settle onto it.\",\"Roll slowly side to side across the muscle.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5377.webp\",\"gif\":\"5377.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the chest. Good before training or on rest days to loosen up.\",\"fv\":\"5416\"},{\"id\":\"5376\",\"n\":\"roll chest opener lying on floor\",\"bp\":\"chest\",\"eq\":\"roller\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie lengthwise on the roller along your spine with knees bent.\",\"Place the roller under the chest and let your body weight settle onto it.\",\"Open your arms out to the sides and let your chest relax.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5376.webp\",\"gif\":\"5376.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the chest. Good before training or on rest days to loosen up.\",\"fv\":\"5415\"},{\"id\":\"5387\",\"n\":\"roll erector spinae lying on floor\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\"],\"st\":[\"Lie on your back with the roller under your lower back.\",\"Place the roller under the lower back muscles and let your body weight settle onto it.\",\"Roll slowly with small movements and keep your core engaged.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5387.webp\",\"gif\":\"5387.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the lower back muscles. Good before training or on rest days to loosen up.\",\"fv\":\"5426\"},{\"id\":\"5398\",\"n\":\"roll foot\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Stand or sit with the roller under one foot.\",\"Place the roller under the sole of the foot and let your body weight settle onto it.\",\"Roll the sole from heel to toes, then switch feet.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5398.webp\",\"gif\":\"5398.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the sole of the foot. Good before training or on rest days to loosen up.\",\"fv\":\"5442\"},{\"id\":\"5373\",\"n\":\"roll forearms standing against wall\",\"bp\":\"lower arms\",\"eq\":\"roller\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Stand facing a wall with the roller held against it.\",\"Place the roller under the forearm and let your body weight settle onto it.\",\"Lean in and roll your forearm up and down the roller.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5373.webp\",\"gif\":\"5373.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the forearm. Good before training or on rest days to loosen up.\",\"fv\":\"5412\"},{\"id\":\"5378\",\"n\":\"roll front shoulder and chest lying on floor\",\"bp\":\"chest\",\"eq\":\"roller\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\",\"biceps\"],\"st\":[\"Lie face down with the roller under your front shoulder.\",\"Place the roller under the front shoulder and chest and let your body weight settle onto it.\",\"Roll small amounts toward the chest and back.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5378.webp\",\"gif\":\"5378.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the front shoulder and chest. Good before training or on rest days to loosen up.\",\"fv\":\"5417\"},{\"id\":\"5391\",\"n\":\"roll glute twist lying on floor\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\"],\"st\":[\"Lie on your back with the roller under one glute.\",\"Place the roller under the glutes and let your body weight settle onto it.\",\"Let the knees drop to one side and twist gently.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5391.webp\",\"gif\":\"5391.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the glutes. Good before training or on rest days to loosen up.\",\"fv\":\"5429\"},{\"id\":\"5390\",\"n\":\"roll glutes sitting on floor\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\"],\"st\":[\"Sit on the roller with your hands behind you.\",\"Place the roller under the glutes and let your body weight settle onto it.\",\"Roll slowly back and forth under your glutes.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5390.webp\",\"gif\":\"5390.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the glutes. Good before training or on rest days to loosen up.\",\"fv\":\"5428\"},{\"id\":\"5392\",\"n\":\"roll hamstrings and glute sitting on floor\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Sit with the roller under your thighs and hands behind you.\",\"Place the roller under the hamstrings and glutes and let your body weight settle onto it.\",\"Lift your hips and roll from the knee toward the glutes.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5392.webp\",\"gif\":\"5392.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the hamstrings and glutes. Good before training or on rest days to loosen up.\",\"fv\":\"5430\"},{\"id\":\"2200\",\"n\":\"roll hip thrust\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your heels on a stability ball and your arms by your sides.\",\"Brace your core and press your heels into the ball.\",\"Lift your hips until your body forms a straight line from shoulders to knees.\",\"Squeeze your glutes at the top for a second.\",\"Lower your hips slowly without letting the ball drift away.\",\"Repeat for the planned reps, keeping the ball steady.\"],\"img\":\"2200.webp\",\"gif\":\"2200.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust done by rolling a ball under your body, which trains the glutes and challenges your balance.\"},{\"id\":\"4599\",\"n\":\"roll iliopsoas\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"core\"],\"st\":[\"Lie face down with the roller under the front of one hip, just inside the hip bone.\",\"Support your weight on your forearms.\",\"Shift your weight gently over the roller.\",\"Roll slowly a small distance up and down.\",\"Pause on tight spots while breathing deeply.\",\"Roll for 30-60 seconds, then switch sides.\"],\"img\":\"4599.webp\",\"gif\":\"4599.mp4\",\"cat\":\"mobility\",\"desc\":\"A roller or ball release for the deep hip flexor area at the front of the pelvis.\"},{\"id\":\"5388\",\"n\":\"roll kneeling upper back rotation\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"obliques\",\"shoulders\"],\"st\":[\"Kneel beside the roller and place one hand on it.\",\"Place the roller under the upper back and let your body weight settle onto it.\",\"Slide the roller forward as you rotate your chest open.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5388.webp\",\"gif\":\"5388.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the upper back. Good before training or on rest days to loosen up.\",\"fv\":\"5433\"},{\"id\":\"2949\",\"n\":\"roll lat foam rolling\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"triceps\"],\"st\":[\"Lie on your side with the roller under your armpit area and your arm extended.\",\"Support yourself with your lower arm and legs.\",\"Roll slowly along your side toward the ribs.\",\"Pause on tight spots for a few seconds.\",\"Switch sides and keep the pressure comfortable.\"],\"img\":\"2949.webp\",\"gif\":\"2949.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling the side of your back on a foam roller. It can loosen tight lats before overhead work.\"},{\"id\":\"5383\",\"n\":\"roll lower back (side) lying on floor\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"obliques\"],\"st\":[\"Lie on your side with the roller under your lower back.\",\"Place the roller under the side of the lower back and let your body weight settle onto it.\",\"Roll slowly up and down in a small range.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5383.webp\",\"gif\":\"5383.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the side of the lower back. Good before training or on rest days to loosen up.\",\"fv\":\"5422\"},{\"id\":\"5382\",\"n\":\"roll middle back lying on floor\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"trapezius\"],\"st\":[\"Lie on your back with the roller under your mid back, hands behind your head.\",\"Place the roller under the middle back and let your body weight settle onto it.\",\"Roll slowly up and down.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5382.webp\",\"gif\":\"5382.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the middle back. Good before training or on rest days to loosen up.\",\"fv\":\"5421\"},{\"id\":\"5372\",\"n\":\"roll neck decompress lying on floor\",\"bp\":\"neck\",\"eq\":\"roller\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Lie on your back with the roller under the base of your skull.\",\"Place the roller under the neck and let your body weight settle onto it.\",\"Gently nod your chin and let your head relax into the roller.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5372.webp\",\"gif\":\"5372.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the neck. Good before training or on rest days to loosen up.\",\"fv\":\"5411\"},{\"id\":\"5371\",\"n\":\"roll neck rotation lying on floor\",\"bp\":\"neck\",\"eq\":\"roller\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Lie on your back with the roller under the base of your skull.\",\"Place the roller under the neck and let your body weight settle onto it.\",\"Gently turn your head slowly from side to side.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5371.webp\",\"gif\":\"5371.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the neck. Good before training or on rest days to loosen up.\",\"fv\":\"5410\"},{\"id\":\"2572\",\"n\":\"roll overs into v sits\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Sit with knees bent and arms reaching forward.\",\"Roll back, lifting your legs up and over toward your head.\",\"Roll forward with control and extend your legs.\",\"Land in a balanced V sit, with arms reaching toward your feet.\",\"Move smoothly and use your abs to drive the motion.\"],\"img\":\"2572.webp\",\"gif\":\"2572.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You roll back over your shoulders and then roll forward into a V sit, working the abs and building control.\"},{\"id\":\"2948\",\"n\":\"roll pec foam rolling\",\"bp\":\"chest\",\"eq\":\"roller\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie face down and place the roller under one side of your chest.\",\"Extend that arm out to the side.\",\"Roll slowly side to side and up and down.\",\"Pause on tight spots for a few seconds.\",\"Switch sides and keep the pressure comfortable.\"],\"img\":\"2948.webp\",\"gif\":\"2948.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling the chest on a foam roller. It can loosen tight pecs before pressing or after desk work.\"},{\"id\":\"5397\",\"n\":\"roll peroneal (single leg) side lying on floor\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\"],\"st\":[\"Lie on your side with the roller under the outer lower leg, other foot behind for support.\",\"Place the roller under the outer lower leg and let your body weight settle onto it.\",\"Roll gently from the knee to the ankle, then switch legs.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5397.webp\",\"gif\":\"5397.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the outer lower leg. Good before training or on rest days to loosen up.\",\"fv\":\"5441\"},{\"id\":\"5396\",\"n\":\"roll peroneal side lying on floor\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\"],\"st\":[\"Lie on your side with the roller under your outer lower leg.\",\"Place the roller under the outer lower leg and let your body weight settle onto it.\",\"Roll gently from the knee to the ankle.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5396.webp\",\"gif\":\"5396.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the outer lower leg. Good before training or on rest days to loosen up.\",\"fv\":\"5440\"},{\"id\":\"5389\",\"n\":\"roll pigeon stretch\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\"],\"st\":[\"Sit on the roller and cross one ankle over the opposite knee.\",\"Place the roller under the glutes and hip and let your body weight settle onto it.\",\"Lean toward the crossed leg and roll gently.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5389.webp\",\"gif\":\"5389.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the glutes and hip. Good before training or on rest days to loosen up.\",\"fv\":\"5427\"},{\"id\":\"5379\",\"n\":\"roll posterior shoulder lying on floor\",\"bp\":\"shoulders\",\"eq\":\"roller\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rotator cuff\",\"lats\"],\"st\":[\"Lie on your side with the roller under your rear shoulder.\",\"Place the roller under the back of the shoulder and let your body weight settle onto it.\",\"Roll slowly along the back of the shoulder.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5379.webp\",\"gif\":\"5379.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the back of the shoulder. Good before training or on rest days to loosen up.\",\"fv\":\"5418\"},{\"id\":\"5393\",\"n\":\"roll quadriceps (vastus lateralis) lying on floor\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"quads\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\"],\"st\":[\"Lie on your side with the roller under the outer thigh.\",\"Place the roller under the outer thigh and let your body weight settle onto it.\",\"Roll from the hip down to above the knee.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5393.webp\",\"gif\":\"5393.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the outer thigh. Good before training or on rest days to loosen up.\",\"fv\":\"5432\"},{\"id\":\"3567\",\"n\":\"roll recumbent hip external rotator and hip extensor stretch (crossed leg)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Lie on your back with both knees bent and feet flat.\",\"Cross one ankle over the opposite knee.\",\"Pull the bottom thigh toward your chest with both hands.\",\"Keep your head and shoulders relaxed on the floor.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Release slowly and repeat on the other side if needed.\"],\"img\":\"3567.webp\",\"gif\":\"3567.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your back with one ankle crossed over the other knee, pull the legs in to stretch the glutes and deep hip rotators.\",\"fv\":\"2201\"},{\"id\":\"5381\",\"n\":\"roll rhomboids\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\"],\"st\":[\"Sit with the roller behind your upper back and cross your arms.\",\"Place the roller under the rhomboids and let your body weight settle onto it.\",\"Roll up and down between your shoulder blades.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5381.webp\",\"gif\":\"5381.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the rhomboids. Good before training or on rest days to loosen up.\",\"fv\":\"5420\"},{\"id\":\"5380\",\"n\":\"roll shoulder back rotation lying on floor\",\"bp\":\"shoulders\",\"eq\":\"roller\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\",\"rear deltoids\"],\"st\":[\"Lie on your side with the roller under your upper back.\",\"Place the roller under the shoulder and upper back and let your body weight settle onto it.\",\"Rotate your top arm back and forth to open the shoulder.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5380.webp\",\"gif\":\"5380.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the shoulder and upper back. Good before training or on rest days to loosen up.\",\"fv\":\"5419\"},{\"id\":\"5385\",\"n\":\"roll shoulder blade reach lying on floor\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"shoulders\"],\"st\":[\"Lie on your side with the roller under your shoulder blade.\",\"Place the roller under the shoulder blade and let your body weight settle onto it.\",\"Reach your top arm forward and back as you roll.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5385.webp\",\"gif\":\"5385.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the shoulder blade. Good before training or on rest days to loosen up.\",\"fv\":\"5424\"},{\"id\":\"4598\",\"n\":\"roll tensor fasciae latae\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your side with the roller under the front of your outer hip.\",\"Support yourself with your forearm and opposite foot.\",\"Slowly roll up and down a few inches.\",\"Pause on tender spots for a few seconds.\",\"Breathe slowly and keep the movement gentle.\",\"Roll for 30-60 seconds, then switch sides.\"],\"img\":\"4598.webp\",\"gif\":\"4598.mp4\",\"cat\":\"mobility\",\"desc\":\"A foam roller release for the outer front hip, easing tightness around the tensor fasciae latae.\"},{\"id\":\"5384\",\"n\":\"roll thoracic spine lying on floor\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"spine\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\"],\"st\":[\"Lie on your back with the roller under your upper back, arms crossed.\",\"Place the roller under the thoracic spine and let your body weight settle onto it.\",\"Lift your hips and roll up and down the upper back.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5384.webp\",\"gif\":\"5384.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the thoracic spine. Good before training or on rest days to loosen up.\",\"fv\":\"5423\"},{\"id\":\"5394\",\"n\":\"roll tibialis anterior\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Kneel on all fours with the roller under your shins.\",\"Place the roller under the shin and let your body weight settle onto it.\",\"Roll gently from below the knee to the ankle.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5394.webp\",\"gif\":\"5394.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the shin. Good before training or on rest days to loosen up.\",\"fv\":\"5436\"},{\"id\":\"5395\",\"n\":\"roll tibialis anterior (single leg) lying on floor\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Rest one shin on the roller, supporting yourself on your hands.\",\"Place the roller under the shin and let your body weight settle onto it.\",\"Roll gently from below the knee to the ankle, then switch legs.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5395.webp\",\"gif\":\"5395.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the shin. Good before training or on rest days to loosen up.\",\"fv\":\"5437\"},{\"id\":\"5375\",\"n\":\"roll triceps side lying on floor\",\"bp\":\"upper arms\",\"eq\":\"roller\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\"],\"st\":[\"Lie on your side with the roller under the back of your upper arm.\",\"Place the roller under the triceps and let your body weight settle onto it.\",\"Roll slowly from the elbow toward the armpit.\",\"Pause on tender spots and breathe slowly for 20-30 seconds.\",\"Keep your core braced and avoid rolling over joints or bone.\",\"Roll for 30-60 seconds, then switch sides if needed.\"],\"img\":\"5375.webp\",\"gif\":\"5375.mp4\",\"cat\":\"mobility\",\"desc\":\"Self-massage with a foam roller to ease tightness in the triceps. Good before training or on rest days to loosen up.\",\"fv\":\"5414\"},{\"id\":\"2858\",\"n\":\"roll up v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with arms overhead.\",\"Lift your arms and curl your head and chest up.\",\"Roll up one vertebra at a time.\",\"Reach over your legs.\",\"Roll back down slowly.\"],\"img\":\"2858.webp\",\"gif\":\"2858.mp4\",\"cat\":\"pilates\",\"desc\":\"A slow roll up from lying to sitting, training abdominal control and spine flexibility.\"},{\"id\":\"3566\",\"n\":\"roll upper back\",\"bp\":\"back\",\"eq\":\"roller\",\"tg\":\"upper back\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"lats\"],\"st\":[\"Sit with a foam roller behind your upper back and lie back onto it.\",\"Cross your arms over your chest and lift your hips.\",\"Roll slowly between your shoulder blades and mid back.\",\"Pause on tender spots for a few breaths.\",\"Avoid rolling your lower back and continue for about a minute.\"],\"img\":\"3566.webp\",\"gif\":\"3566.mp4\",\"cat\":\"mobility\",\"desc\":\"Roll your upper back over a foam roller to loosen tight spots and improve thoracic mobility.\"},{\"id\":\"2991\",\"n\":\"rollball seated single leg shoulder flexor depressor retractor\",\"bp\":\"shoulders\",\"eq\":\"stability ball\",\"tg\":\"delts\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"lats\",\"trapezius\",\"core\"],\"st\":[\"Sit tall on a stability ball with your feet on the floor.\",\"Lift one foot slightly off the ground and hold your balance.\",\"Raise your arms forward, then press your shoulders down away from your ears.\",\"Pull your shoulder blades back and together without arching your back.\",\"Return slowly to the start and complete your reps.\",\"Switch legs and repeat on the other side.\"],\"img\":\"2991.webp\",\"gif\":\"2991.mp4\",\"cat\":\"rehab\",\"desc\":\"A seated shoulder control drill on a ball with one leg lifted. It challenges balance while you raise, lower and pull back the shoulder blades.\"},{\"id\":\"2859\",\"n\":\"rolling back\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\"],\"st\":[\"Sit with your knees tucked and hold your shins.\",\"Round your back.\",\"Roll back onto your shoulders.\",\"Roll back up to balance.\",\"Keep your chin tucked.\"],\"img\":\"2859.webp\",\"gif\":\"2859.mp4\",\"cat\":\"pilates\",\"desc\":\"A rolling move that massages the spine and trains abdominal control.\"},{\"id\":\"0679\",\"n\":\"rolling bridge\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Curl your pelvis up and peel your spine off the floor.\",\"Lift to a bridge position.\",\"Pause at the top.\",\"Roll back down one vertebra at a time.\",\"Move slowly and breathe.\"],\"img\":\"0679.webp\",\"gif\":\"0679.mp4\",\"cat\":\"pilates\",\"desc\":\"A slow bridge where you roll up and down your spine. It strengthens the abs and glutes and improves spinal control.\"},{\"id\":\"2860\",\"n\":\"rollover\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"hamstrings\"],\"st\":[\"Lie on your back with legs raised.\",\"Roll your legs overhead.\",\"Open them to hip width.\",\"Roll down slowly.\",\"Keep your arms pressing down.\"],\"img\":\"2860.webp\",\"gif\":\"2860.mp4\",\"cat\":\"pilates\",\"desc\":\"A controlled move where the legs travel overhead and back, challenging the abs.\"},{\"id\":\"3329\",\"n\":\"roman chair sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"obliques\"],\"st\":[\"Sit on the roman chair with your feet locked under the pads.\",\"Cross your arms over your chest and lean back slightly.\",\"Curl your torso up until your chest nears your thighs.\",\"Pause at the top and keep your neck relaxed.\",\"Lower back slowly under control and repeat.\"],\"img\":\"3329.webp\",\"gif\":\"3329.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit up on a roman chair that gives you a big range of motion for your abs and hip flexors.\"},{\"id\":\"3942\",\"n\":\"romanian chair sit up v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor and rest your lower legs on a chair or bench, knees bent.\",\"Cross your arms over your chest.\",\"Curl your torso up until your chest nears your knees.\",\"Lower slowly back to the floor.\",\"Do not pull on your neck.\"],\"img\":\"3942.webp\",\"gif\":\"3942.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit up done with your legs supported on a chair, which keeps the movement strict. It trains the abs and hip flexors.\"},{\"id\":\"0681\",\"n\":\"rotate push up (on knees)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"obliques\",\"shoulders\"],\"st\":[\"Start in a push-up position on your knees.\",\"Lower your chest toward the floor.\",\"Press back up.\",\"Rotate your torso and lift one arm toward the ceiling.\",\"Return the arm to the floor.\",\"Alternate sides.\"],\"img\":\"0681.webp\",\"gif\":\"0681.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A knee push-up that adds a rotation to reach upward. It works the chest and the trunk.\"},{\"id\":\"1831\",\"n\":\"rotating neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Slowly turn your head to one side, then to the other, as far as is comfortable.\",\"Keep your chin level and avoid pushing into any pain.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1831.webp\",\"gif\":\"1831.mp4\",\"cat\":\"stretching\",\"desc\":\"Turning your head slowly from side to side stretches the muscles around the neck. It is a gentle way to ease stiffness.\"},{\"id\":\"2111\",\"n\":\"rotating stomach stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie face down and prop yourself up on your forearms or hands.\",\"Keep your hips on the floor and lift your chest.\",\"Slowly turn your head and shoulders toward one side.\",\"Stay relaxed and avoid pushing into pain in the lower back.\",\"Hold for 20-30 seconds.\",\"Return to centre and rotate to the other side.\"],\"img\":\"2111.webp\",\"gif\":\"2111.mp4\",\"cat\":\"stretching\",\"desc\":\"Combines a gentle lift of the chest with a twist to stretch the stomach muscles and the sides of the trunk.\"},{\"id\":\"1982\",\"n\":\"rotation shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Stand tall and bend one elbow to 90 degrees at your side.\",\"Slowly rotate your forearm outward or inward, using the other hand to assist, until you feel the shoulder stretch.\",\"Keep your elbow tucked in close to your body.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1982.webp\",\"gif\":\"1982.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle rotation stretch for the shoulder joint.\"},{\"id\":\"0683\",\"n\":\"rotational jacks\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"calves\",\"shoulders\"],\"st\":[\"Stand tall with feet together and arms at your sides.\",\"Jump your feet wide and twist your torso to one side.\",\"Jump back together.\",\"Repeat and twist to the other side.\",\"Keep your knees soft.\",\"Maintain a steady pace.\"],\"img\":\"0683.webp\",\"gif\":\"0683.mp4\",\"cat\":\"cardio\",\"desc\":\"Jumping jacks with a twist added to the upper body. They raise your heart rate and engage the trunk.\"},{\"id\":\"3553\",\"n\":\"rotational push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Start in a push-up position.\",\"Lower your chest to the floor.\",\"Press up and rotate, reaching one arm toward the ceiling.\",\"Return the hand to the floor.\",\"Lower again for the next rep.\",\"Alternate sides.\"],\"img\":\"3553.webp\",\"gif\":\"3553.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with a rotation and arm reach at the top. It works the chest and trunk.\"},{\"id\":\"1984\",\"n\":\"rotator cuff stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Stand tall and bring one arm across your body at chest height.\",\"Hold the arm just above the elbow with the other hand and draw it in until the back of the shoulder stretches.\",\"Keep the shoulder blade down and relaxed.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1984.webp\",\"gif\":\"1984.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch aimed at the small stabilizing muscles around the shoulder joint.\"},{\"id\":\"5471\",\"n\":\"rounded back extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Set the pad at hip height and hook your heels under the rollers.\",\"Cross your arms on your chest and let your upper back round slightly.\",\"Lower your torso until you feel a stretch in the hamstrings.\",\"Squeeze your glutes and lift until your body is nearly in line.\",\"Stop before overarching and repeat with control.\"],\"img\":\"5471.webp\",\"gif\":\"5471.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hip-extension variation on a back extension bench where you keep a relaxed, rounded upper back to bias the glutes and hamstrings.\"},{\"id\":\"2308\",\"n\":\"roundhouse kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"hip flexors\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Pivot on your supporting foot and turn the hip over.\",\"Lift the knee and swing the leg in an arc across the target.\",\"Extend the lower leg at the end.\",\"Pull the leg back and return to stance.\",\"Repeat, then switch legs.\"],\"img\":\"2308.webp\",\"gif\":\"2308.mp4\",\"cat\":\"combat\",\"desc\":\"A kick that swings in an arc to hit with the shin or instep, powered by a hip turn.\"},{\"id\":\"1161\",\"n\":\"rowing (with rowing machine)\",\"bp\":\"cardio\",\"eq\":\"leverage machine\",\"tg\":\"cardiovascular system\",\"mg\":\"lats\",\"sm\":[\"lats\",\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Sit on the machine, strap in your feet and grab the handle with straight arms.\",\"Push through your legs first, then lean back slightly.\",\"Pull the handle to your lower ribs with elbows close.\",\"Reverse the order: arms out, hips hinge, then knees bend to slide forward.\",\"Keep a smooth rhythm for 10-30 minutes at a comfortable pace.\"],\"img\":\"1161.webp\",\"gif\":\"1161.mp4\",\"cat\":\"cardio\",\"desc\":\"Steady rowing on an indoor machine for full-body cardio conditioning.\",\"fv\":\"2262\"},{\"id\":\"4392\",\"n\":\"rowing boat yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"core\",\"lower back\"],\"st\":[\"Sit with your knees bent and your feet on the floor.\",\"Lean back slightly, keeping your chest lifted and back long.\",\"Lift your feet and extend your legs into a V shape.\",\"Reach your arms forward alongside your legs.\",\"Hold for 20-30 seconds while breathing steadily.\"],\"img\":\"4392.webp\",\"gif\":\"4392.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated V-shaped balance, also called boat pose, that works the abs and hip flexors.\"},{\"id\":\"3271\",\"n\":\"run and half knee bend\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Jog on the spot for a few steps.\",\"Pause into a shallow knee bend, hips back and chest up.\",\"Stand tall and go straight back into running.\",\"Repeat for 30-60 seconds.\"],\"img\":\"3271.webp\",\"gif\":\"3271.mp4\",\"cat\":\"cardio\",\"desc\":\"Alternate running in place with a shallow knee bend to keep the heart rate up while the legs work.\"},{\"id\":\"3269\",\"n\":\"run and hop\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"glutes\"],\"st\":[\"Stand tall with feet under your hips.\",\"Run on the spot at a steady pace, pumping your arms.\",\"Every few steps, hop off one foot and land softly.\",\"Stay light on the balls of your feet.\",\"Keep going for 30-60 seconds at a pace you can hold.\"],\"img\":\"3269.webp\",\"gif\":\"3269.mp4\",\"cat\":\"cardio\",\"desc\":\"Run in place and add a hop to lift the heart rate and wake up the legs.\"},{\"id\":\"3270\",\"n\":\"run and jack jump\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"glutes\"],\"st\":[\"Stand tall and start jogging on the spot.\",\"After a few steps, jump your feet wide while raising your arms overhead.\",\"Jump your feet back together and lower the arms.\",\"Resume running and repeat the pattern.\",\"Keep your landings soft and keep going for 30-60 seconds.\"],\"img\":\"3270.webp\",\"gif\":\"3270.mp4\",\"cat\":\"cardio\",\"desc\":\"Run in place and throw in a jumping jack every few steps for a full-body cardio burst.\"},{\"id\":\"3272\",\"n\":\"run and semi squat jump\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Stand tall and run on the spot for a few steps.\",\"Drop into a half squat with your chest up.\",\"Jump up, swinging your arms.\",\"Land softly with bent knees and go back to running.\",\"Repeat for 30-60 seconds.\"],\"img\":\"3272.webp\",\"gif\":\"3272.mp4\",\"cat\":\"cardio\",\"desc\":\"Combine running in place with a half squat jump for a cardio drill that also trains the legs.\"},{\"id\":\"2197\",\"n\":\"run on treadmill\",\"bp\":\"cardio\",\"eq\":\"stationary bike\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Step onto the belt and clip the safety key to your clothing.\",\"Start at a walk and raise the speed gradually to a comfortable jog.\",\"Keep your chest tall and your arms swinging loosely at your sides.\",\"Land softly under your hips and keep your steps quick.\",\"Run for 10-30 minutes at a pace where you can still breathe steadily.\",\"Slow to a walk for a few minutes to cool down.\"],\"img\":\"2197.webp\",\"gif\":\"2197.mp4\",\"cat\":\"cardio\",\"desc\":\"Running at a steady pace on a treadmill to build endurance and burn energy.\"},{\"id\":\"0686\",\"n\":\"russian twist (on stability ball arms straight)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Lie with your upper back on a stability ball.\",\"Lift your hips so your body is flat like a table.\",\"Extend your arms straight above your chest.\",\"Rotate your torso to one side.\",\"Return to center and rotate to the other side.\",\"Keep your hips lifted throughout.\"],\"img\":\"0686.webp\",\"gif\":\"0686.mp4\",\"cat\":\"strength\",\"desc\":\"A rotating move with your upper back on a stability ball and arms straight. It targets the obliques and core stability.\"},{\"id\":\"1247\",\"n\":\"russian twist (with medicine ball)\",\"bp\":\"waist\",\"eq\":\"medicine ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Sit with your knees bent and lean back slightly, holding a medicine ball at your chest.\",\"Lift your feet slightly if you can.\",\"Rotate your torso to one side and tap the ball by your hip.\",\"Rotate to the other side.\",\"Keep your chest tall and move with control.\"],\"img\":\"1247.webp\",\"gif\":\"1247.mp4\",\"cat\":\"strength\",\"desc\":\"Rotating a medicine ball from side to side while seated. It works the obliques.\"},{\"id\":\"5938\",\"n\":\"russian twist chop\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"hip flexors\"],\"st\":[\"Sit with your knees bent and lean back slightly.\",\"Clasp your hands together in front of you.\",\"Twist and chop your arms diagonally across your body.\",\"Return to center and chop the other way.\",\"Keep your chest tall and your core tight.\"],\"img\":\"5938.webp\",\"gif\":\"5938.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated twist with a diagonal chopping arm motion. Works the abs and obliques.\"},{\"id\":\"4646\",\"n\":\"russian twist with hands on chest\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor with your knees bent and lean back slightly.\",\"Cross your hands over your chest.\",\"Lift your feet slightly off the floor if you can.\",\"Rotate your torso to one side, then to the other.\",\"Move with control and keep your chest lifted.\"],\"img\":\"4646.webp\",\"gif\":\"4646.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated twist with your hands crossed on your chest. It trains the obliques and core rotation.\"},{\"id\":\"4219\",\"n\":\"safety bar elevated heel squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"calves\",\"hamstrings\"],\"st\":[\"Place plates or a wedge under your heels in front of the rack.\",\"Unrack the safety bar and step onto the platform.\",\"Keep your chest upright and brace your core.\",\"Squat down with your knees tracking over your toes.\",\"Pause briefly at the bottom.\",\"Press up and rack the bar when done.\"],\"img\":\"4219.webp\",\"gif\":\"4219.mp4\",\"cat\":\"strength\",\"desc\":\"A safety bar squat with your heels raised on a small platform. The elevation lets your knees travel forward to target the quads.\"},{\"id\":\"4218\",\"n\":\"safety bar front squat\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\",\"hamstrings\"],\"st\":[\"Set the safety bar on a rack and step under the pad.\",\"Hold the handles, rest the pad on your shoulders and unrack.\",\"Step back and set your feet shoulder-width apart.\",\"Squat down while keeping your chest tall and elbows up.\",\"Go as deep as you can with good form.\",\"Drive up through your whole foot to stand.\"],\"img\":\"4218.webp\",\"gif\":\"4218.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a safety squat bar held in front using its handles. It loads the quads and keeps your torso upright.\"},{\"id\":\"5911\",\"n\":\"safety bar good morning\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Set the safety bar on your upper back and shoulders and hold the handles.\",\"Stand with feet shoulder-width apart and knees slightly bent.\",\"Push your hips back and lower your torso until it is near parallel to the floor.\",\"Keep your back flat and neck neutral.\",\"Drive your hips forward to stand tall.\"],\"img\":\"5911.webp\",\"gif\":\"5911.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a safety squat bar resting on your shoulders, strengthening the hamstrings, glutes and lower back.\"},{\"id\":\"6295\",\"n\":\"sage marichi i pose marichyasana\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"glutes\",\"shoulders\"],\"st\":[\"Sit with one leg straight and the other knee bent, foot flat beside the straight leg.\",\"Wrap your opposite arm around the bent knee.\",\"Sit tall, then twist toward the bent knee.\",\"Keep your spine long.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"6295.webp\",\"gif\":\"6295.mp4\",\"cat\":\"yoga\",\"desc\":\"A seated forward fold with a twist and a bent knee. It stretches the back, hips and hamstrings.\"},{\"id\":\"1692\",\"n\":\"sagittal plane lunge with overhead medicine ball press\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold a medicine ball at chest height and stand tall.\",\"Step forward into a lunge and lower your back knee toward the floor.\",\"Press the ball overhead as you rise.\",\"Lower the ball and step back to the start.\",\"Alternate legs for the planned reps.\"],\"img\":\"1692.webp\",\"gif\":\"1692.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge combined with an overhead medicine ball press that links leg strength with shoulder work.\"},{\"id\":\"10427\",\"n\":\"sandbag over the shoulder toss (weighted)\",\"bp\":\"upper legs\",\"eq\":\"sandbag\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"core\",\"shoulders\"],\"st\":[\"Stand over the sandbag with feet shoulder width apart.\",\"Hinge down, grip the bag and keep your back flat.\",\"Drive your hips forward and pull the bag up the front of your body.\",\"Extend fully and throw the bag back over your shoulder.\",\"Reset and repeat, facing the same way.\"],\"img\":\"10427.webp\",\"gif\":\"10427.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Explosively hinge and heave a sandbag backwards over your shoulder. It trains hip power and full body force.\"},{\"id\":\"2861\",\"n\":\"saw\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lower back\"],\"st\":[\"Sit with legs wide and arms out.\",\"Rotate your torso to one side.\",\"Reach your hand past your opposite foot.\",\"Return to centre.\",\"Switch sides.\"],\"img\":\"2861.webp\",\"gif\":\"2861.mp4\",\"cat\":\"pilates\",\"desc\":\"A seated twist that reaches toward the opposite foot, training the obliques and stretching the back of the legs.\"},{\"id\":\"3130\",\"n\":\"scapula elevation depression\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"trapezius\",\"shoulders\"],\"st\":[\"Stand or sit tall with your arms at your sides.\",\"Shrug your shoulders up toward your ears.\",\"Hold for a second.\",\"Press your shoulders down away from your ears.\",\"Move slowly through the full range.\",\"Keep your arms relaxed and your head still.\"],\"img\":\"3130.webp\",\"gif\":\"3130.mp4\",\"cat\":\"mobility\",\"desc\":\"A drill where you shrug your shoulders up and then press them down. It builds control of the shoulder blades.\"},{\"id\":\"3129\",\"n\":\"scapula retraction protraction\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"lats\",\"trapezius\",\"shoulders\"],\"st\":[\"Stand or sit tall with your arms forward at shoulder height.\",\"Pull your shoulder blades together behind you.\",\"Hold for a moment.\",\"Then push your hands forward and let the blades spread apart.\",\"Move slowly between the two positions.\",\"Keep your neck relaxed and your ribs down.\"],\"img\":\"3129.webp\",\"gif\":\"3129.mp4\",\"cat\":\"mobility\",\"desc\":\"A shoulder blade drill where you pull the blades together and then spread them apart. It improves control of the scapulae.\"},{\"id\":\"10948\",\"n\":\"scapular pull up swing\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"grip muscles\",\"core\"],\"st\":[\"Hang from a pull-up bar with straight arms.\",\"Pull your shoulder blades down without bending your elbows.\",\"Swing your body forward and back in a small arc.\",\"Keep the motion controlled.\",\"Lower to a full hang and repeat.\"],\"img\":\"10948.webp\",\"gif\":\"10948.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A scapular pull-up with a gentle swing. It builds shoulder blade control and grip.\"},{\"id\":\"11015\",\"n\":\"scapular pull up v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"trapezius\",\"grip muscles\"],\"st\":[\"Hang from a pull-up bar with an overhand grip, arms straight.\",\"Let your shoulders relax up toward your ears.\",\"Pull your shoulder blades down and together to lift your body a few centimetres.\",\"Keep your elbows locked straight the whole time.\",\"Pause briefly, then lower slowly back to the full hang.\"],\"img\":\"11015.webp\",\"gif\":\"11015.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hang from a bar and move only your shoulder blades. It builds the shoulder control you need for solid pull-ups.\"},{\"id\":\"2945\",\"n\":\"scapular slide back to wall\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Stand with your back flat against a wall and your elbows bent at your sides.\",\"Press your forearms and head lightly into the wall.\",\"Slide your arms up the wall while keeping your shoulder blades down.\",\"Stop before your back arches.\",\"Slide down slowly and repeat.\"],\"img\":\"2945.webp\",\"gif\":\"2945.mp4\",\"cat\":\"mobility\",\"desc\":\"Sliding your shoulder blades along a wall to improve their control. It helps shoulder blade mobility and posture.\"},{\"id\":\"11652\",\"n\":\"sciatic nerve glide floss\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\",\"glutes\"],\"st\":[\"Sit tall at the edge of a chair with your hands on the seat or resting in your lap.\",\"Slowly straighten one knee while you lower your chin toward your chest.\",\"Bend the knee back down while you lift your head and look up.\",\"Keep the motion smooth and gentle, never forcing into a strong stretch or tingling.\",\"Repeat for 10-15 slow reps, then switch legs.\"],\"img\":\"11652.webp\",\"gif\":\"11652.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated nerve glide that alternates straightening the leg and moving the head to ease the back of the leg and improve mobility.\"},{\"id\":\"2862\",\"n\":\"scissors\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"hamstrings\"],\"st\":[\"Lie on your back with your hips lifted and hands supporting them.\",\"Raise your legs up.\",\"Lower one leg while the other stays up.\",\"Switch legs.\",\"Keep the movement steady.\"],\"img\":\"2862.webp\",\"gif\":\"2862.mp4\",\"cat\":\"pilates\",\"desc\":\"A leg-switching move lying on your back, building lower abdominal strength.\"},{\"id\":\"3586\",\"n\":\"scissors (advanced)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with legs extended and hands under your hips.\",\"Lift your head, shoulders and legs slightly off the floor.\",\"Cross one leg over the other in a scissor motion.\",\"Alternate sides in a controlled rhythm.\",\"Keep your lower back pressed down.\"],\"img\":\"3586.webp\",\"gif\":\"3586.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hold both legs low and cross them repeatedly like scissors, working the lower abs.\",\"fv\":\"2893\"},{\"id\":\"2892\",\"n\":\"scissors (beginner)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with arms by your sides.\",\"Lift both legs a little off the floor.\",\"Open them wide, then cross one over the other.\",\"Alternate which leg is on top with each rep.\",\"Keep your lower back flat on the floor.\"],\"img\":\"2892.webp\",\"gif\":\"2892.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A beginner floor exercise crossing the legs like scissors to train the lower abs.\"},{\"id\":\"4631\",\"n\":\"scorpion stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"lower back\"],\"st\":[\"Lie face down with your arms out to the sides.\",\"Bend one knee and swing that foot up and across your body.\",\"Reach toward the opposite hand and keep shoulders on the floor.\",\"Hold for 20-30 seconds.\",\"Return and switch sides.\"],\"img\":\"4631.webp\",\"gif\":\"4631.mp4\",\"cat\":\"stretching\",\"desc\":\"A face-down rotational stretch that opens the hips, chest and lower back.\"},{\"id\":\"2877\",\"n\":\"seal\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\",\"core\"],\"st\":[\"Sit balanced on your tailbone with knees open and hands inside your ankles.\",\"Tuck your chin and round your back into a ball.\",\"Roll back to your shoulders and clap your feet together.\",\"Roll up to the balance position and clap again.\",\"Keep the roll smooth and avoid rolling onto your neck.\"],\"img\":\"2877.webp\",\"gif\":\"2877.mp4\",\"cat\":\"pilates\",\"desc\":\"A rolling Pilates exercise that massages the spine and builds ab control.\"},{\"id\":\"2944\",\"n\":\"seal push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper back\",\"lower back\",\"core\"],\"st\":[\"Lie face down with your hands under your shoulders and legs straight.\",\"Push your upper body up with your arms like a seal.\",\"Keep your hips on the floor and your core tight.\",\"Lower slowly to the floor.\",\"Repeat for smooth, controlled reps.\"],\"img\":\"2944.webp\",\"gif\":\"2944.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where your hands lift off the floor and reach out at the top. It builds chest and back strength together.\"},{\"id\":\"4022\",\"n\":\"seated 8 leg crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"core\"],\"st\":[\"Sit on the floor, lean back slightly and support yourself with your hands behind you.\",\"Lift both feet off the floor and brace your core.\",\"Draw a figure eight in the air with your legs, slow and controlled.\",\"Keep your chest lifted and your lower back from collapsing.\",\"Lower your feet and rest, then repeat.\"],\"img\":\"4022.webp\",\"gif\":\"4022.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Seated crunch where the legs trace a figure eight in the air. It works the lower abs and hip flexors while you balance on your seat.\"},{\"id\":\"3944\",\"n\":\"seated alternate crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit on the floor, lean back slightly and lift your feet.\",\"Place your hands behind your head.\",\"Bring one knee in while rotating your torso toward it.\",\"Return and repeat on the other side.\",\"Keep your chest open and move with control.\"],\"img\":\"3944.webp\",\"gif\":\"3944.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated crunch where you bring one knee and the opposite elbow together, then switch sides. It works the abs and obliques.\"},{\"id\":\"8615\",\"n\":\"seated alternate dynamic chest stretch on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Open one arm out to the side and rotate the trunk slightly.\",\"Feel the stretch across your chest.\",\"Return and switch arms in a smooth rhythm.\"],\"img\":\"8615.webp\",\"gif\":\"8615.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated dynamic stretch that opens the chest by alternating arms.\"},{\"id\":\"8744\",\"n\":\"seated alternate knee extension on chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Straighten one knee by lifting the foot until the leg is level.\",\"Squeeze your thigh, then lower slowly.\",\"Switch legs and keep alternating.\"],\"img\":\"8744.webp\",\"gif\":\"8744.mp4\",\"cat\":\"strength\",\"desc\":\"A seated leg extension done by alternating legs, working the thighs without equipment.\"},{\"id\":\"2998\",\"n\":\"seated ankle stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\",\"feet\"],\"st\":[\"Sit on a chair or the floor with one leg extended.\",\"Point your toes away from you so the top of the foot lengthens.\",\"Slowly circle or press the foot until you feel a comfortable stretch.\",\"Hold for 20-30 seconds without forcing it.\",\"Release and switch legs.\",\"Repeat 2-3 times on each side.\"],\"img\":\"2998.webp\",\"gif\":\"2998.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle seated stretch for the front of the ankle and shin that eases stiffness after sitting or training.\"},{\"id\":\"11006\",\"n\":\"seated arm crossover and chest out on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\"],\"st\":[\"Sit tall on a chair.\",\"Cross your arms in front of your chest and hug yourself.\",\"Open your arms wide and push your chest out.\",\"Hold the open position for 5-10 seconds.\",\"Repeat.\"],\"img\":\"11006.webp\",\"gif\":\"11006.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that crosses the arms and then opens the chest. It loosens the upper body.\"},{\"id\":\"8619\",\"n\":\"seated arm crossover on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Open your arms wide to the sides at shoulder height.\",\"Sweep them together so they cross in front of your chest.\",\"Open back out and alternate which arm is on top.\"],\"img\":\"8619.webp\",\"gif\":\"8619.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated arm crossover that works the chest and warms up the shoulders.\"},{\"id\":\"5128\",\"n\":\"seated back squeeze\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit tall with arms at your sides or elbows bent.\",\"Draw your shoulder blades back and together.\",\"Hold the squeeze for 2-3 seconds.\",\"Release slowly.\",\"Keep your neck relaxed.\",\"Repeat for your reps.\"],\"img\":\"5128.webp\",\"gif\":\"5128.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Squeezing your shoulder blades together while seated. It strengthens the upper back and improves posture.\"},{\"id\":\"5134\",\"n\":\"seated ballerina\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\"],\"st\":[\"Sit tall with arms by your sides.\",\"Sweep your arms out and up in a wide arc.\",\"Bring your hands overhead.\",\"Lower them back with control.\",\"Keep the movement graceful.\",\"Repeat at an easy pace.\"],\"img\":\"5134.webp\",\"gif\":\"5134.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated arm movement like a ballet arm sweep. It loosens the shoulders and warms up the upper body.\"},{\"id\":\"5133\",\"n\":\"seated behind back raise\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"triceps\"],\"st\":[\"Sit tall with hands clasped behind your back.\",\"Straighten your arms.\",\"Lift your hands slightly away from your body.\",\"Squeeze your shoulder blades together.\",\"Lower slowly.\",\"Keep your chest lifted.\"],\"img\":\"5133.webp\",\"gif\":\"5133.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lifting your arms behind your back while seated. It strengthens the upper back and rear shoulders.\"},{\"id\":\"11048\",\"n\":\"seated bent knee abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Sit tall with your knees bent and feet on the floor.\",\"Place your hands on your outer knees.\",\"Press your knees outward against your hands.\",\"Hold briefly.\",\"Release slowly.\",\"Keep your back straight.\"],\"img\":\"11048.webp\",\"gif\":\"11048.mp4\",\"cat\":\"strength\",\"desc\":\"Seated, you press your knees outward. It trains the outer hips.\"},{\"id\":\"11049\",\"n\":\"seated bent knee abduction feet floor off\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Sit tall and lift your feet off the floor.\",\"Hold the seat edge.\",\"Open your knees outward.\",\"Pause.\",\"Close slowly.\",\"Keep your back straight.\"],\"img\":\"11049.webp\",\"gif\":\"11049.mp4\",\"cat\":\"strength\",\"desc\":\"Seated knee abduction with the feet lifted. It trains the outer hips and core.\"},{\"id\":\"1937\",\"n\":\"seated bent knee to chest buttock stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Sit on the floor with your legs out in front.\",\"Bend one knee, hold it with both hands and gently pull it toward your chest.\",\"Keep your back tall and avoid rounding it as you pull.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1937.webp\",\"gif\":\"1937.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulling a bent knee toward your chest to stretch the buttock muscles.\"},{\"id\":\"4928\",\"n\":\"seated calf stretch v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit with one leg straight in front of you.\",\"Loop your hands or a strap around the ball of your foot.\",\"Gently pull your toes toward you.\",\"Feel the stretch in the calf.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"4928.webp\",\"gif\":\"4928.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch for the calves, a second variation. It helps loosen tight lower legs.\"},{\"id\":\"5078\",\"n\":\"seated chest clam\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\"],\"st\":[\"Sit tall with your fingers lightly behind your head.\",\"Start with your elbows pointing forward.\",\"Slowly open your elbows out and back as far as is comfortable.\",\"Squeeze your shoulder blades together.\",\"Hold for 20-30 seconds while breathing steadily.\"],\"img\":\"5078.webp\",\"gif\":\"5078.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit tall and open your elbows wide like a clam to stretch the front of the chest and shoulders.\",\"fv\":\"4946\"},{\"id\":\"8618\",\"n\":\"seated chest press on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Bring your hands to chest height and press your palms together.\",\"Press forward until your arms are straight.\",\"Draw them back to your chest slowly.\"],\"img\":\"8618.webp\",\"gif\":\"8618.mp4\",\"cat\":\"strength\",\"desc\":\"A seated pressing motion done with bodyweight tension to work the chest and triceps.\"},{\"id\":\"5063\",\"n\":\"seated chin tuck\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Sit tall on a chair with your shoulders relaxed and eyes forward.\",\"Keep your chin level, not tilted up or down.\",\"Slide your head straight back as if making a double chin.\",\"Hold for 2-3 seconds without tensing your jaw.\",\"Return slowly to the start and repeat for 10-12 reps.\"],\"img\":\"5063.webp\",\"gif\":\"5063.mp4\",\"cat\":\"mobility\",\"desc\":\"Gently glide your chin straight back while seated to wake up the deep neck flexors and ease a forward head posture.\"},{\"id\":\"4781\",\"n\":\"seated chin up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Sit under a bar with an underhand grip, shoulder-width apart.\",\"Extend your legs in front of you.\",\"Pull your chin toward the bar.\",\"Squeeze your back and biceps at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"4781.webp\",\"gif\":\"4781.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated chin-up where your legs help a little while you pull up with an underhand grip. It builds back and arm strength.\"},{\"id\":\"4780\",\"n\":\"seated chin up (low bar position)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Set a bar at a low height and sit under it.\",\"Grab it with an underhand grip, arms extended.\",\"Extend your legs in front with heels on the floor.\",\"Pull your chest toward the bar.\",\"Lower slowly to straight arms.\"],\"img\":\"4780.webp\",\"gif\":\"4780.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated chin-up using a low bar with an underhand grip. It lets you train the lats and biceps with a reduced load.\"},{\"id\":\"4782\",\"n\":\"seated commando pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Sit under a bar and grab it with one hand in front of the other.\",\"Extend your legs in front of you.\",\"Pull your body up and bring your head to one side.\",\"Lower under control.\",\"Alternate sides each rep or each set.\"],\"img\":\"4782.webp\",\"gif\":\"4782.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated pull-up with a staggered grip, pulling your head to alternating sides of the bar. It trains the lats and grip.\"},{\"id\":\"8424\",\"n\":\"seated cross body punch on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Raise your fists to guard position.\",\"Punch one arm across your body, rotating the trunk slightly.\",\"Pull it back and punch with the other arm.\",\"Keep a quick, smooth rhythm.\"],\"img\":\"8424.webp\",\"gif\":\"8424.mp4\",\"cat\":\"cardio\",\"desc\":\"A seated punching drill that raises your heart rate and works the chest, shoulders and trunk.\"},{\"id\":\"8620\",\"n\":\"seated decline chest press on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Start with your hands at chest height.\",\"Press them diagonally down and forward until your arms are straight.\",\"Return slowly to the chest and repeat.\"],\"img\":\"8620.webp\",\"gif\":\"8620.mp4\",\"cat\":\"strength\",\"desc\":\"A seated press angled downward to bias the lower chest.\"},{\"id\":\"8616\",\"n\":\"seated elbow chest fly on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Raise your elbows to chest height with forearms up.\",\"Squeeze your elbows together in front of you.\",\"Open them out again under control.\",\"Keep your shoulders away from your ears.\"],\"img\":\"8616.webp\",\"gif\":\"8616.mp4\",\"cat\":\"strength\",\"desc\":\"A seated chest fly with bent elbows that squeezes the pecs by pressing the arms together.\"},{\"id\":\"8617\",\"n\":\"seated external rotation on a chair\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Tuck your elbows at your sides bent to 90 degrees.\",\"Rotate your forearms outward, squeezing your shoulder blades.\",\"Return slowly and repeat.\"],\"img\":\"8617.webp\",\"gif\":\"8617.mp4\",\"cat\":\"rehab\",\"desc\":\"A seated rotation drill for the back of the shoulders and rotator cuff.\"},{\"id\":\"10909\",\"n\":\"seated feet circle\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit tall on a chair with both feet lifted off the floor.\",\"Keep your knees still.\",\"Circle both feet in the same direction, as wide as feels comfortable.\",\"Reverse the direction after several turns.\",\"Keep your breathing relaxed.\"],\"img\":\"10909.webp\",\"gif\":\"10909.mp4\",\"cat\":\"mobility\",\"desc\":\"Circling both feet while seated. A simple way to mobilise the ankles.\"},{\"id\":\"3441\",\"n\":\"seated flexion and extension neck\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit tall with your shoulders relaxed.\",\"Lower your chin gently toward your chest.\",\"Hold for a moment.\",\"Slowly lift your head and look up slightly.\",\"Move through a comfortable range only.\",\"Repeat 8-10 times smoothly.\"],\"img\":\"3441.webp\",\"gif\":\"3441.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated neck mobility drill moving the head forward and back.\"},{\"id\":\"3962\",\"n\":\"seated flutter kick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Sit with your hands behind you and lean back slightly.\",\"Lift both legs off the floor.\",\"Kick your legs up and down in short alternating moves.\",\"Keep your core tight and your back from rounding.\",\"Continue for time.\"],\"img\":\"3962.webp\",\"gif\":\"3962.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small alternating leg kicks while seated and leaning back. It trains the lower abs and hip flexors.\"},{\"id\":\"5481\",\"n\":\"seated foot slide\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit tall on a chair with your feet flat on the floor.\",\"Keep your heel down and slide the foot forward along the floor.\",\"Pull it back, letting the heel lift slightly toward the end.\",\"Move smoothly through a comfortable range.\",\"Repeat, then switch feet.\"],\"img\":\"5481.webp\",\"gif\":\"5481.mp4\",\"cat\":\"mobility\",\"desc\":\"Gentle seated mobility drill sliding the foot along the floor to warm up the ankle and calf.\"},{\"id\":\"6763\",\"n\":\"seated forearms stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Sit tall and extend one arm in front of you, palm up.\",\"With the other hand, gently pull the fingers back toward you.\",\"Keep the elbow straight and shoulders relaxed.\",\"Hold for 20-30 seconds.\",\"Turn the palm down to stretch the other side, then switch arms.\"],\"img\":\"6763.webp\",\"gif\":\"6763.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch for the muscles of the forearm. It eases tight wrists after typing or gripping.\"},{\"id\":\"8433\",\"n\":\"seated forward bend stretch on a chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"calves\"],\"st\":[\"Sit near the front of a sturdy chair and extend one leg with the heel on the floor.\",\"Keep your back long.\",\"Hinge forward from the hips and reach toward your toes.\",\"Hold for 20-30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"8433.webp\",\"gif\":\"8433.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated forward fold that stretches the hamstrings and lower back.\"},{\"id\":\"8434\",\"n\":\"seated forward roll up on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"lower back\"],\"st\":[\"Sit tall on the edge of a chair with your arms crossed or reaching forward.\",\"Tuck your chin and round your lower back.\",\"Roll your spine forward one segment at a time.\",\"Reach toward your knees and pause.\",\"Roll back up slowly to a tall position.\",\"Keep the motion smooth and controlled.\"],\"img\":\"8434.webp\",\"gif\":\"8434.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated roll-up that curls the spine forward one segment at a time. It trains the abs and spinal control.\"},{\"id\":\"7255\",\"n\":\"seated frog half to full sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"groin\"],\"st\":[\"Sit on the floor with the soles of your feet together and knees dropped out.\",\"Lower your back halfway to the floor under control.\",\"Pause, then lower fully to lie flat.\",\"Curl your torso back up to sitting, using your abs.\",\"Keep your feet together and avoid yanking on your neck.\"],\"img\":\"7255.webp\",\"gif\":\"7255.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Sit-up started from a seated frog position, with knees out and soles together, to work the abs and open the hips.\"},{\"id\":\"4554\",\"n\":\"seated glute stretch v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Sit on a chair or the floor with your back tall.\",\"Cross one ankle over the opposite knee.\",\"Keep your back straight and lean your chest forward slowly.\",\"Feel the stretch in the glute of the crossed leg.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"4554.webp\",\"gif\":\"4554.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated figure-four stretch that lengthens the glutes and outer hip.\"},{\"id\":\"1169\",\"n\":\"seated groin stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\"],\"st\":[\"Sit tall on the floor and bring the soles of your feet together.\",\"Hold your feet or ankles and let your knees fall out.\",\"Keep your back straight and chest lifted.\",\"Lean forward slightly from the hips until you feel a stretch.\",\"Hold for 20-30 seconds and breathe slowly.\"],\"img\":\"1169.webp\",\"gif\":\"1169.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated butterfly-style stretch for the inner thighs.\",\"fv\":\"1057\"},{\"id\":\"10462\",\"n\":\"seated hamstring stretch on a chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Sit near the front edge of a chair.\",\"Extend one leg straight with your heel on the floor and toes up.\",\"Hinge forward from your hips with a flat back until you feel a stretch.\",\"Hold for 20-30 seconds, breathing steadily.\",\"Switch legs and repeat.\"],\"img\":\"10462.webp\",\"gif\":\"10462.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle seated stretch for the back of the thigh, done on a chair. It helps loosen tight hamstrings.\"},{\"id\":\"7310\",\"n\":\"seated hamstring stretch with chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Sit on the front edge of a chair.\",\"Straighten one leg with the heel on the floor and toes up.\",\"Keep the other foot flat and your back long.\",\"Hinge forward at the hips until you feel a stretch.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch legs.\"],\"img\":\"7310.webp\",\"gif\":\"7310.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch using a chair to lengthen the back of the thigh without a deep fold.\"},{\"id\":\"6749\",\"n\":\"seated hip external rotation\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit tall on a bench or chair with feet flat.\",\"Lift one foot slightly off the floor.\",\"Keep your knee still and rotate the lower leg inward so the thigh turns outward.\",\"Pause when you feel the hip working.\",\"Return slowly.\",\"Finish the reps, then switch legs.\"],\"img\":\"6749.webp\",\"gif\":\"6749.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated rotation turning the thigh outward. It improves hip mobility and activates the deep rotators.\"},{\"id\":\"1918\",\"n\":\"seated hip external rotator and hip extensor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\"],\"st\":[\"Sit upright on the floor or a chair and cross one ankle over the opposite knee.\",\"Gently press the raised knee down and lean your chest forward with a long back until the buttock stretches.\",\"Keep your spine long instead of collapsing forward.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1918.webp\",\"gif\":\"1918.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated figure four style stretch for the buttocks and deep hip rotators.\"},{\"id\":\"1919\",\"n\":\"seated hip stretch with opposite leg from behind\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\"],\"st\":[\"Sit on the floor with one leg bent in front of you and the other leg bent behind.\",\"Lean your chest forward over the front shin until you feel the stretch deep in the hip and buttock.\",\"Keep both sit bones as level as you can.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1919.webp\",\"gif\":\"1919.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated hip stretch with one leg folded in front and the other tucked behind you.\"},{\"id\":\"1938\",\"n\":\"seated hip stretch with slightly bent leg\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\"],\"st\":[\"Sit on the floor with one leg slightly bent in front of you and the other leg folded comfortably.\",\"Hinge forward from the hips with a long back until you feel the hip and buttock stretch.\",\"Keep the knee of the front leg soft throughout.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1938.webp\",\"gif\":\"1938.mp4\",\"cat\":\"stretching\",\"desc\":\"A relaxed seated hip stretch with the front leg slightly bent, easy on the knee.\"},{\"id\":\"3509\",\"n\":\"seated in out leg raise on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Sit on the floor, hands behind you for support.\",\"Lean back slightly with legs extended and lifted.\",\"Pull your knees toward your chest.\",\"Extend your legs back out without touching the floor.\",\"Keep your back long and your core tight.\",\"Breathe steadily.\"],\"img\":\"3509.webp\",\"gif\":\"3509.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated leg tuck, with legs pulled in then extended out. It trains the lower abs and hip flexors.\",\"fv\":\"4274\"},{\"id\":\"8622\",\"n\":\"seated incline chest press on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"triceps\",\"shoulders\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Start with your hands near your chest.\",\"Press them diagonally up and forward until your arms are straight.\",\"Lower back to the chest slowly.\"],\"img\":\"8622.webp\",\"gif\":\"8622.mp4\",\"cat\":\"strength\",\"desc\":\"A seated press angled upward to emphasise the upper chest.\"},{\"id\":\"9317\",\"n\":\"seated isometric hold pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"grip muscles\"],\"st\":[\"Set up a bar so you can sit under it.\",\"Grab the bar with an overhand grip.\",\"Pull yourself up until your chin is above the bar.\",\"Hold the top position.\",\"Hold for 5-10 seconds.\",\"Lower down slowly.\"],\"img\":\"9317.webp\",\"gif\":\"9317.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding the top of a pull up while seated helps you build pulling strength. It works the lats and arms.\",\"hd\":1},{\"id\":\"11654\",\"n\":\"seated knee down\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\",\"glutes\"],\"st\":[\"Sit tall on the floor or a bench with the soles of your feet together or one leg crossed in.\",\"Let one knee drop slowly out to the side toward the floor.\",\"Keep your back straight and your chest lifted as the knee lowers.\",\"Pause briefly at the end of the comfortable range, then lift the knee back up.\",\"Repeat for 8-12 reps per side.\"],\"img\":\"11654.webp\",\"gif\":\"11654.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated hip opener that lets one knee drop to the side to loosen the hips and inner thighs.\"},{\"id\":\"1914\",\"n\":\"seated knee flexor and hip adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"groin\",\"lower back\"],\"st\":[\"Sit on the floor with your legs spread wide and knees straight.\",\"Sit tall with your toes pointing up.\",\"Hinge forward from the hips, walking your hands out in front of you.\",\"Stop when you feel a stretch along the inner thighs and backs of the legs.\",\"Hold for 20-30 seconds, breathing slowly, then sit back up.\"],\"img\":\"1914.webp\",\"gif\":\"1914.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated wide leg stretch that opens the inner thighs while lengthening the hamstrings.\"},{\"id\":\"1915\",\"n\":\"seated knee flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Sit on the floor with one leg straight out in front of you.\",\"Reach toward your toes with a long back until you feel the back of the thigh stretch.\",\"Keep your knee straight but not locked, and avoid rounding your back too much.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1915.webp\",\"gif\":\"1915.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated reach toward the toes that lengthens the hamstrings.\"},{\"id\":\"1934\",\"n\":\"seated knee up extended rotation stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the floor with one leg extended and the other knee bent and crossed over it.\",\"Rotate your torso toward the bent knee, using the opposite elbow to guide it, until the hip stretches.\",\"Keep your spine long and look over your back shoulder.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1934.webp\",\"gif\":\"1934.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated twist with the raised knee and the back leg extended, giving the hip a longer stretch.\"},{\"id\":\"1933\",\"n\":\"seated knee up rotation stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the floor with one leg straight and the other knee bent, foot flat on the floor.\",\"Cross the bent leg over the straight one, and rotate your torso toward the raised knee, hugging it with the opposite arm.\",\"Sit tall and twist from the middle of your back.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1933.webp\",\"gif\":\"1933.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated twist with one knee raised that stretches the hip and buttock.\"},{\"id\":\"8423\",\"n\":\"seated lean back on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Cross your arms over your chest.\",\"Lean back slowly while keeping your back straight.\",\"Stop where you can still hold your form, then return to upright using your abs.\"],\"img\":\"8423.webp\",\"gif\":\"8423.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated lean back that wakes up the abs by holding the torso against gravity.\"},{\"id\":\"1804\",\"n\":\"seated lower trunk extensor lateral flexor stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"obliques\",\"glutes\"],\"st\":[\"Sit tall on a chair or bench with your feet flat on the floor.\",\"Fold forward and reach your hands toward one foot, letting your trunk bend slightly to that side.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1804.webp\",\"gif\":\"1804.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated, you fold forward and sideways to stretch both the lower back and the side of your trunk. It targets one side at a time.\"},{\"id\":\"2114\",\"n\":\"seated lower trunk lateral flexor stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Sit tall on the floor or a chair with your legs crossed or feet flat.\",\"Reach one arm overhead and bend sideways away from it until you feel the side of the waist stretch.\",\"Keep both hips grounded and avoid leaning forward.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2114.webp\",\"gif\":\"2114.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated side bend that lengthens the muscles along the side of the waist.\"},{\"id\":\"11787\",\"n\":\"seated median nerve mobilization\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"biceps\",\"shoulders\"],\"st\":[\"Sit tall and lift one arm out to the side, palm up.\",\"Extend your wrist and fingers backward.\",\"Tilt your head slightly away from that arm.\",\"Return slowly and repeat 8-10 times.\",\"Stay within a mild stretch, then switch arms.\"],\"img\":\"11787.webp\",\"gif\":\"11787.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle seated nerve glide for the median nerve running down the arm to the hand.\"},{\"id\":\"10555\",\"n\":\"seated neck flexion to extension on chair\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\",\"trapezius\"],\"st\":[\"Sit tall on a chair with your shoulders relaxed.\",\"Slowly lower your chin toward your chest.\",\"Gently lift your head and look slightly upward.\",\"Keep the motion smooth and pain free.\",\"Repeat for several slow reps.\"],\"img\":\"10555.webp\",\"gif\":\"10555.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated, you slowly nod your head forward and back. It loosens the neck.\"},{\"id\":\"5195\",\"n\":\"seated neck side stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Sit tall and relax your shoulders.\",\"Tilt your ear toward one shoulder.\",\"Rest your hand lightly on your head for a gentle added stretch.\",\"Hold for 20-30 seconds.\",\"Return to centre and switch sides.\"],\"img\":\"5195.webp\",\"gif\":\"5195.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated lateral neck stretch. It loosens the side of the neck and upper traps.\",\"fv\":\"7824\"},{\"id\":\"5162\",\"n\":\"seated neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit tall on a chair with your shoulders relaxed.\",\"Place one hand on the back of your head.\",\"Gently guide your chin toward your chest until you feel a stretch.\",\"Hold for 20-30 seconds while breathing slowly.\",\"Release slowly and repeat.\"],\"img\":\"5162.webp\",\"gif\":\"5162.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle seated stretch for the back of the neck. It helps ease tension from desk time.\"},{\"id\":\"5131\",\"n\":\"seated neck tap\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Sit tall with your shoulders relaxed.\",\"Bring one hand up toward the side of your neck.\",\"Tap lightly.\",\"Switch to the other hand.\",\"Keep your head level.\",\"Continue at a gentle pace.\"],\"img\":\"5131.webp\",\"gif\":\"5131.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated move tapping toward your neck area. It gently mobilises the neck and shoulders.\"},{\"id\":\"8653\",\"n\":\"seated open up and under swing on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"lats\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Swing both arms open to the sides.\",\"Rotate and sweep them under and across your body.\",\"Open back out and alternate directions with a smooth rhythm.\"],\"img\":\"8653.webp\",\"gif\":\"8653.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated swing that opens the chest and then sweeps the arms underneath, warming up the trunk and shoulders.\"},{\"id\":\"8369\",\"n\":\"seated over head straight arm stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"triceps\"],\"st\":[\"Sit tall on a chair or bench.\",\"Interlace your fingers and straighten your arms.\",\"Raise them overhead with palms facing up.\",\"Lift your chest and reach slightly back.\",\"Breathe normally and hold for 20 to 30 seconds.\",\"Release slowly.\"],\"img\":\"8369.webp\",\"gif\":\"8369.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated overhead reach that stretches the chest and shoulders. It helps open up the upper body after desk time.\"},{\"id\":\"8431\",\"n\":\"seated overhead stretch on a chair\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"obliques\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Interlace your fingers and raise your arms overhead.\",\"Turn your palms to the ceiling and reach up tall.\",\"Hold for 20-30 seconds while breathing steadily.\"],\"img\":\"8431.webp\",\"gif\":\"8431.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple seated stretch that opens up the sides of your back and shoulders.\"},{\"id\":\"8654\",\"n\":\"seated overhead triceps extension on a chair\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Raise your arms overhead and bend your elbows so your hands drop behind your head.\",\"Extend your arms back up until straight.\",\"Lower slowly and keep your elbows pointing forward.\"],\"img\":\"8654.webp\",\"gif\":\"8654.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension that works the triceps using your own arm resistance.\"},{\"id\":\"11651\",\"n\":\"seated patella mobilization\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"ankles\"],\"st\":[\"Sit tall on a chair or bench with one leg extended and the thigh muscle relaxed.\",\"Place your fingertips or the heel of your hand on the edges of your kneecap.\",\"Gently glide the kneecap side to side and up and down in small, slow motions.\",\"Keep the quad relaxed and stay in a comfortable range with no sharp pain.\",\"Move for 30-60 seconds, then switch legs.\"],\"img\":\"11651.webp\",\"gif\":\"11651.mp4\",\"cat\":\"mobility\",\"desc\":\"Gentle kneecap sliding while seated that loosens the tissue around the knee and warms up the front of the thigh.\"},{\"id\":\"8621\",\"n\":\"seated pec dec on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Raise your forearms in front of you with elbows bent at shoulder height.\",\"Squeeze your forearms together.\",\"Open them back to the sides under control.\"],\"img\":\"8621.webp\",\"gif\":\"8621.mp4\",\"cat\":\"strength\",\"desc\":\"A seated pec dec motion without a machine, squeezing the chest by bringing the forearms together.\"},{\"id\":\"10564\",\"n\":\"seated pronation supination foot\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit on a chair with one foot lifted slightly off the floor.\",\"Roll the sole of your foot inward.\",\"Roll it outward as far as is comfortable.\",\"Keep the lower leg still.\",\"Finish your reps, then switch feet.\"],\"img\":\"10564.webp\",\"gif\":\"10564.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated, you roll the foot inward and outward. It mobilizes the ankle and foot.\"},{\"id\":\"4785\",\"n\":\"seated pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Sit under a bar and grab it with an overhand grip.\",\"Extend your legs in front of you.\",\"Pull your chest up toward the bar.\",\"Squeeze your back at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"4785.webp\",\"gif\":\"4785.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up from a seated position with your legs assisting. It builds lats and arms while reducing the load.\"},{\"id\":\"4783\",\"n\":\"seated pull up (legs elevated)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"core\",\"forearms\"],\"st\":[\"Place your feet on a bench and sit under a bar.\",\"Grab it with an overhand grip, arms extended.\",\"Pull your chest up toward the bar.\",\"Squeeze your shoulder blades at the top.\",\"Lower slowly to straight arms.\"],\"img\":\"4783.webp\",\"gif\":\"4783.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated pull-up with your feet raised on a bench, which increases the load. It builds the back and arms.\"},{\"id\":\"4784\",\"n\":\"seated pull up (low bar position)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Set a bar low and sit beneath it.\",\"Grab it with an overhand grip, a little wider than your shoulders.\",\"Extend your legs in front with heels on the floor.\",\"Pull your chest to the bar.\",\"Lower under control.\"],\"img\":\"4784.webp\",\"gif\":\"4784.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated pull-up on a low bar. It reduces the load compared with a full pull-up, which is good for building strength.\"},{\"id\":\"3550\",\"n\":\"seated pull up between chairs\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"rhomboids\"],\"st\":[\"Set a bar across two sturdy chairs.\",\"Sit on the floor beneath it and grip the bar.\",\"Keep your legs bent for light help.\",\"Pull your chest toward the bar.\",\"Lower with control.\",\"Use your legs as little as possible.\"],\"img\":\"3550.webp\",\"gif\":\"3550.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated pull-up using a bar between two chairs, with the legs assisting.\"},{\"id\":\"5132\",\"n\":\"seated pulse back squeeze\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"rear deltoids\"],\"st\":[\"Sit tall with elbows bent.\",\"Draw your shoulder blades together.\",\"Pulse your elbows back in small movements.\",\"Keep your shoulders down.\",\"Maintain the squeeze throughout.\",\"Continue for 20-30 seconds.\"],\"img\":\"5132.webp\",\"gif\":\"5132.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small pulses while squeezing your shoulder blades together seated. It strengthens the upper back.\"},{\"id\":\"2100\",\"n\":\"seated quadriceps stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Sit sideways on a bench or sturdy seat with one leg hanging off the side.\",\"Bend the hanging knee and bring the heel back toward your glutes.\",\"Hold the foot or ankle with your hand and gently pull the heel closer.\",\"Keep your torso upright and your knees close together.\",\"Hold for 20-30 seconds.\",\"Release and switch legs.\"],\"img\":\"2100.webp\",\"gif\":\"2100.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the front of the thigh from a seated position by folding one leg back while the other stays supported.\"},{\"id\":\"7562\",\"n\":\"seated quadriceps stretch v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit sideways on a bench or chair edge.\",\"Bend one knee, tucking your foot behind you.\",\"Hold your ankle and gently pull it toward your glutes.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"7562.webp\",\"gif\":\"7562.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated stretch for the front of your thigh.\"},{\"id\":\"11786\",\"n\":\"seated radial nerve mobilization\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"wrist flexors\",\"shoulders\"],\"st\":[\"Sit tall with one arm down at your side, palm facing back.\",\"Lower your shoulder slightly and rotate your arm inward.\",\"Bend your wrist gently and tilt your head away.\",\"Move slowly and stop at a mild pull, never pain.\",\"Repeat 8-10 times, then switch arms.\"],\"img\":\"11786.webp\",\"gif\":\"11786.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle seated nerve glide that moves the radial nerve along the arm.\"},{\"id\":\"6774\",\"n\":\"seated rhomboid stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Sit tall and clasp your hands in front of your chest.\",\"Push your arms forward and round your upper back.\",\"Tuck your chin slightly and spread the shoulder blades apart.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Release slowly and repeat.\"],\"img\":\"6774.webp\",\"gif\":\"6774.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that opens the space between the shoulder blades. It relieves tightness in the upper back.\"},{\"id\":\"8634\",\"n\":\"seated rotating boxing rolls on a chair\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"core\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Raise your fists in a boxing guard.\",\"Roll your arms in circles while rotating your trunk side to side.\",\"Keep a quick, rhythmic pace.\"],\"img\":\"8634.webp\",\"gif\":\"8634.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A seated drill of circular arm rolls and trunk rotation that lifts your heart rate.\"},{\"id\":\"5135\",\"n\":\"seated rotation stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit tall with legs crossed or extended.\",\"Place one hand behind you and the other on the opposite knee.\",\"Rotate your torso toward the back hand.\",\"Keep your spine long.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"5135.webp\",\"gif\":\"5135.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated twist held as a stretch. It opens the spine and the muscles around your waist.\"},{\"id\":\"3848\",\"n\":\"seated row with towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rear deltoids\",\"forearms\"],\"st\":[\"Sit with your legs extended and loop a towel around your feet.\",\"Hold the ends with arms straight.\",\"Pull the towel toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Extend your arms slowly.\"],\"img\":\"3848.webp\",\"gif\":\"3848.mp4\",\"cat\":\"strength\",\"desc\":\"A seated row using a towel for resistance. It trains your lats and upper back.\"},{\"id\":\"1975\",\"n\":\"seated shoulder flexor depressor retractor stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"chest\"],\"st\":[\"Sit tall on a chair or bench.\",\"Place your hands behind you on the seat, fingers pointing back.\",\"Press your shoulders down and back, opening your chest.\",\"Lean slightly forward until you feel the stretch.\",\"Hold for 20-30 seconds, then relax.\"],\"img\":\"1975.webp\",\"gif\":\"1975.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that lengthens the shoulder and chest by pressing the arms back and down.\"},{\"id\":\"3564\",\"n\":\"seated shoulder flexor depressor retractor stretch (bent knee)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\",\"lats\"],\"st\":[\"Sit on the floor with one knee bent and the other leg comfortable.\",\"Place your hands behind you on the floor, fingers pointing away.\",\"Slowly slide your hips forward while keeping your chest tall.\",\"Feel the stretch in the front of your shoulders.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Release slowly and repeat on the other side if needed.\"],\"img\":\"3564.webp\",\"gif\":\"3564.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that opens the front of the shoulder and lengthens the muscles that lift and pull the arm.\",\"fv\":\"4676\"},{\"id\":\"8633\",\"n\":\"seated shoulder press on a chair\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"trapezius\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Raise your hands to shoulder height with elbows bent.\",\"Press them overhead until your arms are straight.\",\"Lower back to your shoulders under control.\"],\"img\":\"8633.webp\",\"gif\":\"8633.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead press without equipment that trains the shoulders and triceps.\"},{\"id\":\"8652\",\"n\":\"seated shoulder tap on a chair\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Reach one hand across to tap the opposite shoulder.\",\"Return and tap with the other hand.\",\"Keep the pace steady.\"],\"img\":\"8652.webp\",\"gif\":\"8652.mp4\",\"cat\":\"cardio\",\"desc\":\"A seated drill where you tap each shoulder with the opposite hand, adding light coordination and shoulder work.\"},{\"id\":\"8311\",\"n\":\"seated side bend on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Reach one arm overhead and lean slowly to the opposite side without twisting.\",\"Pause briefly, then return to upright.\",\"Repeat on the other side and keep alternating.\"],\"img\":\"8311.webp\",\"gif\":\"8311.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle seated side bend that works the obliques and loosens the sides of the trunk.\"},{\"id\":\"3978\",\"n\":\"seated side to side leg raise crunch on floor\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Sit and lean back on your hands, legs lifted.\",\"Swing both knees to one side while crunching in.\",\"Return through the middle.\",\"Swing to the other side.\",\"Keep the motion smooth and controlled.\"],\"img\":\"3978.webp\",\"gif\":\"3978.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Seated crunch with the legs swinging to one side and then the other. It works the abs and obliques.\"},{\"id\":\"10557\",\"n\":\"seated side to side neck bend on chair\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\",\"trapezius\"],\"st\":[\"Sit tall on a chair with your shoulders relaxed.\",\"Slowly tilt your head so your ear moves toward one shoulder.\",\"Return to the centre.\",\"Tilt toward the other shoulder.\",\"Repeat for several slow reps.\"],\"img\":\"10557.webp\",\"gif\":\"10557.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated, you tilt your ear toward each shoulder. It eases side neck tightness.\"},{\"id\":\"10556\",\"n\":\"seated side to side neck twist on chair\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\",\"trapezius\"],\"st\":[\"Sit tall on a chair with your shoulders relaxed.\",\"Slowly turn your head to look over one shoulder.\",\"Return to the centre.\",\"Turn to the other side.\",\"Repeat for several slow reps.\"],\"img\":\"10556.webp\",\"gif\":\"10556.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated, you turn your head from side to side. It restores easy neck rotation.\"},{\"id\":\"11650\",\"n\":\"seated single leg calf raise on a chair\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit on a chair with one foot flat on the floor, knee bent to 90 degrees.\",\"Lift the other foot off the floor or tuck it behind.\",\"Press through the ball of the working foot and raise your heel.\",\"Pause at the top, then lower slowly.\",\"Complete your reps, then switch legs.\"],\"img\":\"11650.webp\",\"gif\":\"11650.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated one-leg calf raise that mainly hits the soleus using only your body weight.\"},{\"id\":\"10908\",\"n\":\"seated single leg foot circle\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit tall on a chair and lift one foot slightly off the floor.\",\"Keep your lower leg still.\",\"Draw slow circles with your toes, as wide as is comfortable.\",\"Do half your reps clockwise, then switch to counterclockwise.\",\"Repeat on the other foot.\"],\"img\":\"10908.webp\",\"gif\":\"10908.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated ankle circles on one leg. They loosen the ankle and warm up the lower leg.\"},{\"id\":\"10910\",\"n\":\"seated single leg foot side to side\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit tall and lift one foot slightly off the floor.\",\"Keep your lower leg still.\",\"Turn your foot inward, then outward, in a smooth motion.\",\"Move through a comfortable range.\",\"Repeat for your reps, then switch feet.\"],\"img\":\"10910.webp\",\"gif\":\"10910.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated ankle move that sweeps the foot from side to side. It improves ankle mobility.\"},{\"id\":\"10919\",\"n\":\"seated single leg foot side to side v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Sit tall and lift one foot a little off the floor.\",\"Keep your leg still.\",\"Sweep the foot to the inside, then to the outside.\",\"Keep the motion smooth and pain free.\",\"Repeat, then switch feet.\"],\"img\":\"10919.webp\",\"gif\":\"10919.mp4\",\"cat\":\"mobility\",\"desc\":\"A second version of the side-to-side seated foot move for ankle mobility.\"},{\"id\":\"10745\",\"n\":\"seated single leg half circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Sit tall on the floor with hands behind you for support.\",\"Lift one leg slightly with the knee straight.\",\"Draw a half circle with your foot from one side to the other.\",\"Keep your torso steady.\",\"Repeat for the reps.\",\"Switch legs.\"],\"img\":\"10745.webp\",\"gif\":\"10745.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated hip mobility drill where you sweep one leg in a half circle. It warms up the hips.\"},{\"id\":\"0692\",\"n\":\"seated single leg hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Sit on the floor with one leg straight and the other bent.\",\"Keep your back long.\",\"Hinge forward from the hips and reach toward your toes.\",\"Stop when you feel a stretch.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"0692.webp\",\"gif\":\"0692.mp4\",\"cat\":\"stretching\",\"desc\":\"Sitting with one leg extended, you reach toward the foot. It stretches the back of the thigh.\"},{\"id\":\"10541\",\"n\":\"seated single leg hugging knee flexion\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hip flexors\"],\"st\":[\"Sit tall on a chair with feet flat.\",\"Lift one knee and clasp your hands around the shin.\",\"Gently pull the knee toward your chest and flex it.\",\"Hold for a moment, then release.\",\"Finish your reps, then switch legs.\"],\"img\":\"10541.webp\",\"gif\":\"10541.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated, you hug one knee toward your chest and bend it. It mobilizes the hip and knee gently.\"},{\"id\":\"10542\",\"n\":\"seated single leg hugging knee flexion with towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hip flexors\"],\"st\":[\"Sit tall on a chair and loop a towel around one shin.\",\"Hold the towel ends with both hands.\",\"Pull the knee gently toward your chest, bending it.\",\"Hold for a moment, then release.\",\"Finish your reps, then switch legs.\"],\"img\":\"10542.webp\",\"gif\":\"10542.mp4\",\"cat\":\"mobility\",\"desc\":\"The same hugging knee flexion, using a towel around the shin to help. It adds a gentle assisted bend.\"},{\"id\":\"10537\",\"n\":\"seated single leg knee extension\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit tall on a chair with your feet flat.\",\"Slowly straighten one knee to lift your foot.\",\"Squeeze your thigh at the top for a second.\",\"Lower the foot back to the floor with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"10537.webp\",\"gif\":\"10537.mp4\",\"cat\":\"rehab\",\"desc\":\"Seated on a chair, you straighten one knee to lift your foot. A gentle move that wakes up the thigh.\"},{\"id\":\"10538\",\"n\":\"seated single leg knee extension v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Sit tall on a chair, holding the seat edge for support.\",\"Straighten one knee until the leg is level.\",\"Hold for a second, tightening your thigh.\",\"Lower slowly to the start.\",\"Finish your reps, then switch legs.\"],\"img\":\"10538.webp\",\"gif\":\"10538.mp4\",\"cat\":\"rehab\",\"desc\":\"A variation of the seated knee extension. It builds thigh strength with a small, controlled range.\"},{\"id\":\"10534\",\"n\":\"seated single leg knee flexion\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Sit on a chair with your feet flat on the floor.\",\"Slide one foot back under the chair, bending the knee.\",\"Pause briefly at the end of the range.\",\"Return the foot slowly to the start.\",\"Finish your reps, then switch legs.\"],\"img\":\"10534.webp\",\"gif\":\"10534.mp4\",\"cat\":\"rehab\",\"desc\":\"Sitting down, you bend one knee by sliding your heel back. It is a gentle way to build knee mobility and hamstring control.\"},{\"id\":\"8946\",\"n\":\"seated single leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Sit tall on the edge of a bench with your hands beside you.\",\"Extend one leg straight out in front.\",\"Lift the leg a few inches higher while keeping the knee straight.\",\"Pause and lower it slowly.\",\"Keep your back straight and your core tight.\",\"Finish all reps, then switch legs.\"],\"img\":\"8946.webp\",\"gif\":\"8946.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Seated on a bench or floor, you lift one straight leg to train the hip flexors and thigh. It is a simple core and leg exercise.\"},{\"id\":\"10912\",\"n\":\"seated single leg squeezing toes\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit on a chair and place one foot flat on the floor.\",\"Curl your toes down and squeeze.\",\"Hold for a second or two.\",\"Relax and spread the toes.\",\"Finish your reps, then switch feet.\"],\"img\":\"10912.webp\",\"gif\":\"10912.mp4\",\"cat\":\"mobility\",\"desc\":\"A one-foot toe curl while seated. It trains the muscles under the foot.\"},{\"id\":\"10918\",\"n\":\"seated single leg squeezing toes v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit with one foot flat on the floor.\",\"Curl your toes down and hold the squeeze.\",\"Keep your heel planted.\",\"Release and spread your toes.\",\"Do all reps, then switch feet.\"],\"img\":\"10918.webp\",\"gif\":\"10918.mp4\",\"cat\":\"mobility\",\"desc\":\"Another one-foot toe squeeze while seated. It strengthens the small muscles in the foot.\"},{\"id\":\"10535\",\"n\":\"seated single leg tibialis press\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit with one foot resting flat and the other leg crossed over it.\",\"Hook the toes of the lower foot under your other foot for light resistance.\",\"Lift the toes and forefoot up toward your shin.\",\"Pause at the top, then lower slowly.\",\"Finish your reps, then switch feet.\"],\"img\":\"10535.webp\",\"gif\":\"10535.mp4\",\"cat\":\"strength\",\"desc\":\"Press the top of your foot upward against resistance while seated. It strengthens the shin muscle.\"},{\"id\":\"10917\",\"n\":\"seated single leg tibialis press v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Sit on a chair with one foot flat and the other crossed over it.\",\"Press the top foot up against the resistance of the bottom foot.\",\"Feel the front of your shin work.\",\"Hold for a second.\",\"Relax and repeat, then switch feet.\"],\"img\":\"10917.webp\",\"gif\":\"10917.mp4\",\"cat\":\"rehab\",\"desc\":\"A gentle seated press that engages the shin muscle. Useful for ankle control.\"},{\"id\":\"10920\",\"n\":\"seated single leg toes press\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit on a chair with one foot on the floor.\",\"Lift your heel slightly and press your toes into the floor.\",\"Hold briefly.\",\"Lower your heel again.\",\"Finish your reps, then switch feet.\"],\"img\":\"10920.webp\",\"gif\":\"10920.mp4\",\"cat\":\"mobility\",\"desc\":\"Pressing the toes into the floor while seated. It activates the foot and calf muscles.\"},{\"id\":\"5081\",\"n\":\"seated sky look\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\"],\"st\":[\"Sit tall with your shoulders relaxed.\",\"Slowly tip your head back to look up at the ceiling.\",\"Keep your mouth closed and move only as far as feels comfortable.\",\"Hold for 15-20 seconds.\",\"Return your head to neutral slowly.\"],\"img\":\"5081.webp\",\"gif\":\"5081.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit upright and slowly tip your head back to look up. It stretches the front of the neck.\",\"fv\":\"4947\"},{\"id\":\"10463\",\"n\":\"seated squeeze shoulder blades chest stretch on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"rhomboids\"],\"st\":[\"Sit tall on a chair with your feet flat.\",\"Reach your hands behind you and clasp them or hold the chair back.\",\"Pull your shoulder blades together and lift your chest.\",\"Hold for 20-30 seconds without arching your lower back.\",\"Relax and repeat.\"],\"img\":\"10463.webp\",\"gif\":\"10463.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit on a chair and squeeze your shoulder blades together to open the chest. It eases tight pecs from desk posture.\"},{\"id\":\"10911\",\"n\":\"seated squeezing toes\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit on a chair with both feet flat on the floor.\",\"Curl all your toes down as if gripping the floor.\",\"Squeeze for a couple of seconds.\",\"Relax and spread your toes wide.\",\"Repeat smoothly.\"],\"img\":\"10911.webp\",\"gif\":\"10911.mp4\",\"cat\":\"mobility\",\"desc\":\"Curling and squeezing the toes while seated. It wakes up the small muscles of the feet.\"},{\"id\":\"0693\",\"n\":\"seated straight leg calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"hamstrings\"],\"st\":[\"Sit on the floor with one leg straight.\",\"Loop a towel around the ball of your foot, or hold your toes.\",\"Pull your toes toward you.\",\"Keep your knee straight.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"0693.webp\",\"gif\":\"0693.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated with a straight leg, you pull your toes toward you. It stretches the calf muscles.\"},{\"id\":\"6759\",\"n\":\"seated tibialis anterior press\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Sit tall with your heels on the floor.\",\"Lift the toes of one foot as high as you can.\",\"Press them up against light resistance such as the other foot.\",\"Pause at the top.\",\"Lower slowly.\",\"Finish the reps, then switch feet.\"],\"img\":\"6759.webp\",\"gif\":\"6759.mp4\",\"cat\":\"strength\",\"desc\":\"A seated press with the front of the foot to train the shin muscle. It helps balance the lower leg.\"},{\"id\":\"1963\",\"n\":\"seated toe extensor and foot everter stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"shins\",\"ankles\"],\"st\":[\"Sit and cross one ankle over the opposite knee.\",\"Hold the top of the foot and toes with your hand.\",\"Curl the toes down and turn the sole gently outward.\",\"Feel the stretch along the top and outer edge of the foot.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1963.webp\",\"gif\":\"1963.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated stretch combining pointing the toes down with a turn of the sole outward.\"},{\"id\":\"1964\",\"n\":\"seated toe extensor and foot inverter stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"shins\",\"ankles\"],\"st\":[\"Sit and cross one ankle over the opposite knee.\",\"Hold the top of the foot and toes with your hand.\",\"Curl the toes down and turn the sole gently inward.\",\"Feel the stretch along the top and inner edge of the foot.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1964.webp\",\"gif\":\"1964.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated stretch combining pointing the toes down with a turn of the sole inward.\"},{\"id\":\"1962\",\"n\":\"seated toe extensor stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"shins\",\"ankles\"],\"st\":[\"Sit and cross one ankle over the opposite knee.\",\"Hold the top of the foot and toes with your hand.\",\"Gently curl the toes and foot downward until you feel a stretch on the top.\",\"Keep the motion gentle.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1962.webp\",\"gif\":\"1962.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch for the muscles that lift the toes, using your hand to point the toes downward.\"},{\"id\":\"1966\",\"n\":\"seated toe flexor and foot everter stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit and cross one ankle over the opposite knee.\",\"Hold the toes with your hand.\",\"Pull the toes back toward your shin and turn the sole gently outward.\",\"Feel the stretch along the sole and inner edge of the foot.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1966.webp\",\"gif\":\"1966.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated stretch pulling the toes back while turning the sole outward.\"},{\"id\":\"1967\",\"n\":\"seated toe flexor and foot inverter stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit and cross one ankle over the opposite knee.\",\"Hold the toes with your hand.\",\"Pull the toes back toward your shin and turn the sole gently inward.\",\"Feel the stretch along the sole and outer edge of the foot.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1967.webp\",\"gif\":\"1967.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated stretch pulling the toes back while turning the sole inward.\"},{\"id\":\"1965\",\"n\":\"seated toe flexor stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit and cross one ankle over the opposite knee.\",\"Hold the toes with your hand.\",\"Gently pull the toes back toward your shin.\",\"Feel the stretch along the sole of the foot.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1965.webp\",\"gif\":\"1965.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch pulling the toes back to lengthen the bottom of the foot.\"},{\"id\":\"0694\",\"n\":\"seated twist (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"lower back\"],\"st\":[\"Sit tall on a stability ball with feet flat.\",\"Hold your arms in front of your chest.\",\"Rotate your torso to one side.\",\"Keep your hips facing forward.\",\"Return to center and twist the other way.\",\"Move slowly and controlled.\"],\"img\":\"0694.webp\",\"gif\":\"0694.mp4\",\"cat\":\"mobility\",\"desc\":\"Seated on a stability ball, you rotate your torso. It warms up the trunk and trains balance.\"},{\"id\":\"4307\",\"n\":\"seated twist (straight arm)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"shoulders\"],\"st\":[\"Sit tall on the floor with your legs crossed or extended.\",\"Extend both arms straight out to the sides at shoulder height.\",\"Rotate your torso slowly to one side, keeping your spine long.\",\"Hold for a moment, then rotate to the other side.\",\"Repeat for 8-10 slow rotations each way.\"],\"img\":\"4307.webp\",\"gif\":\"4307.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated rotation with your arms held straight out, loosening the spine and working the waist gently.\",\"fv\":\"0695\"},{\"id\":\"11788\",\"n\":\"seated ulnar nerve mobilization\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"shoulders\"],\"st\":[\"Sit tall with one arm out to the side.\",\"Bend your elbow and bring your hand toward your face like a mask.\",\"Tilt your head slightly away.\",\"Straighten the arm back out, keeping it gentle.\",\"Repeat 8-10 times, then switch arms.\"],\"img\":\"11788.webp\",\"gif\":\"11788.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle seated nerve glide for the ulnar nerve on the inner side of the arm.\"},{\"id\":\"8655\",\"n\":\"seated underhand arm circle on a chair\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Sit tall near the front of a sturdy chair with your feet flat on the floor.\",\"Brace your core and keep your shoulders relaxed.\",\"Extend your arms out to the sides with palms facing up.\",\"Draw small circles, then gradually bigger.\",\"Reverse the direction after a set.\"],\"img\":\"8655.webp\",\"gif\":\"8655.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated arm circle with palms up to warm up the shoulder joints.\"},{\"id\":\"5129\",\"n\":\"seated upper body rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit tall with arms crossed on your chest.\",\"Keep your hips facing forward.\",\"Rotate your torso to one side.\",\"Return to the centre.\",\"Rotate to the other side.\",\"Move smoothly without forcing the twist.\"],\"img\":\"5129.webp\",\"gif\":\"5129.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated twist of the upper body. It mobilises the spine and warms up the obliques.\"},{\"id\":\"8303\",\"n\":\"seated upright twists on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Sit tall with feet flat and arms crossed over your chest.\",\"Rotate your torso to one side.\",\"Pause briefly.\",\"Rotate to the other side.\",\"Keep your hips still.\"],\"img\":\"8303.webp\",\"gif\":\"8303.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated trunk twist done tall on a chair. It loosens the spine and works the obliques gently.\"},{\"id\":\"2093\",\"n\":\"seated wrist ulnar deviator and flexor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Sit tall and extend one arm forward with the palm facing up.\",\"Use the other hand to bend the wrist back and tilt it toward the thumb side until the forearm stretches.\",\"Keep the elbow straight.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2093.webp\",\"gif\":\"2093.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated wrist stretch for the inner forearm and the little finger side of the wrist.\"},{\"id\":\"2994\",\"n\":\"self anterior calf foam rolling\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"soleus\"],\"st\":[\"Kneel on a mat with the foam roller under your shins.\",\"Support yourself with your hands in front.\",\"Shift your weight to roll along the front of your lower leg.\",\"Move slowly and pause on tight spots.\",\"Roll for 30-60 seconds per leg.\"],\"img\":\"2994.webp\",\"gif\":\"2994.mp4\",\"cat\":\"mobility\",\"desc\":\"A foam roller technique for the front of the lower leg that eases tightness.\"},{\"id\":\"3507\",\"n\":\"self assisted inverse leg curl v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Kneel with your ankles anchored under something stable.\",\"Keep your body straight from knees to head.\",\"Lower your torso forward slowly, using your hamstrings to resist.\",\"Catch yourself with your hands near the floor.\",\"Push off lightly and use your hamstrings to return.\",\"Keep your hips extended.\"],\"img\":\"3507.webp\",\"gif\":\"3507.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight Nordic-style leg curl where you lower yourself and use your hands to help back up. It builds strong hamstrings.\"},{\"id\":\"3499\",\"n\":\"self assisted inverted pullover\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"triceps\",\"core\",\"shoulders\"],\"st\":[\"Set a sturdy bar at hip height or lower and hang beneath it with an overhand grip.\",\"Keep your feet on the floor to help as needed.\",\"Pull your chest toward the bar and let your hips rise.\",\"Continue to rotate your torso up and over the bar toward your hands, as your range allows.\",\"Reverse slowly back to the start.\",\"Use your legs only as needed.\"],\"img\":\"3499.webp\",\"gif\":\"3499.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pullover-style move hanging under a bar, with the legs helping a bit. It builds the lats and shoulder strength.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"2103\",\"n\":\"separation between fingers stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Sit comfortably and bring one foot up to rest on the opposite knee.\",\"Hold the foot with your hand.\",\"Slide your fingers between the toes and gently spread them apart.\",\"Keep the movement slow and easy.\",\"Hold the spread for 15-20 seconds.\",\"Release and switch feet.\"],\"img\":\"2103.webp\",\"gif\":\"2103.mp4\",\"cat\":\"stretching\",\"desc\":\"Spreads the toes apart to wake up and loosen the small muscles of the foot.\"},{\"id\":\"2097\",\"n\":\"separation finger stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrist flexors\"],\"st\":[\"Hold one hand up in front of you with the palm facing you.\",\"Spread your fingers as far apart as feels comfortable.\",\"If you want more stretch, press between the fingers with your other hand.\",\"Keep the wrist straight and the shoulder relaxed.\",\"Hold for 20-30 seconds.\",\"Relax the hand and switch sides.\"],\"img\":\"2097.webp\",\"gif\":\"2097.mp4\",\"cat\":\"stretching\",\"desc\":\"Spreads the fingers wide apart to open up the hand and loosen the small muscles between the fingers.\"},{\"id\":\"5025\",\"n\":\"serratus wall slide\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Stand facing a wall with your forearms resting on it.\",\"Keep your elbows at shoulder width.\",\"Press into the wall and slide your arms up as high as you can.\",\"Keep your ribs down and neck relaxed.\",\"Slide back down slowly and repeat.\"],\"img\":\"5025.webp\",\"gif\":\"5025.mp4\",\"cat\":\"mobility\",\"desc\":\"Sliding the forearms up a wall to wake up the serratus anterior. It helps with shoulder blade movement.\"},{\"id\":\"4608\",\"n\":\"shin box switch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"groin\"],\"st\":[\"Sit on the floor with both knees bent at 90 degrees, one leg in front and one to the side.\",\"Sit tall and keep your hands on the floor if needed.\",\"Rotate your knees to the other side so the legs swap positions.\",\"Move smoothly without using your hands to push too hard.\",\"Repeat back and forth for the set.\"],\"img\":\"4608.webp\",\"gif\":\"4608.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated hip rotation drill where you switch both knees from one side to the other, loosening the hips.\"},{\"id\":\"2775\",\"n\":\"shoulder abduction\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with your arms at your sides.\",\"Raise one arm out to the side up to about shoulder height.\",\"Lower slowly without shrugging.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2775.webp\",\"gif\":\"2775.mp4\",\"cat\":\"mobility\",\"desc\":\"Raising the arm out to the side, working the side of the shoulder.\",\"fv\":\"8839\"},{\"id\":\"2776\",\"n\":\"shoulder adduction\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with one arm raised out to the side at shoulder height.\",\"Pull the arm down toward your side with control.\",\"Keep your torso still and finish with the arm next to your body.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2776.webp\",\"gif\":\"2776.mp4\",\"cat\":\"mobility\",\"desc\":\"Bringing the arm down toward the body from the side, working the lats and chest.\"},{\"id\":\"1979\",\"n\":\"shoulder adductor elevator and protractor stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Stand or sit tall and bring one arm across your chest.\",\"Use the opposite hand to press the arm toward you until the shoulder and upper back stretch.\",\"Keep your shoulders down away from your ears.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1979.webp\",\"gif\":\"1979.mp4\",\"cat\":\"stretching\",\"desc\":\"A cross body stretch that loosens the back of the shoulder and the muscles between the shoulder blades.\"},{\"id\":\"2087\",\"n\":\"shoulder adductor protractor and elevator stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"rhomboids\"],\"st\":[\"Stand tall and bring one arm across your chest.\",\"Hold it with the other arm just above the elbow.\",\"Gently pull while rounding the upper back slightly forward.\",\"Keep your neck relaxed.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2087.webp\",\"gif\":\"2087.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the back of the shoulder and the muscles along the upper back.\"},{\"id\":\"3516\",\"n\":\"shoulder backbend stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper chest\",\"biceps\",\"upper back\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Clasp your hands behind your back.\",\"Lift your arms up behind you and open your chest.\",\"Tilt back slightly if comfortable.\",\"Hold for 20-30 seconds.\",\"Release slowly.\"],\"img\":\"3516.webp\",\"gif\":\"3516.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle backbend stretch that opens the shoulders and chest.\"},{\"id\":\"2863\",\"n\":\"shoulder bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with knees bent.\",\"Lift your hips into a bridge.\",\"Extend one leg up.\",\"Lower it and switch legs.\",\"Roll down slowly.\"],\"img\":\"2863.webp\",\"gif\":\"2863.mp4\",\"cat\":\"pilates\",\"desc\":\"A bridge that lifts the hips and adds a leg raise, working the glutes and hamstrings.\"},{\"id\":\"4395\",\"n\":\"shoulder circle\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Stand tall with your arms relaxed by your sides.\",\"Lift your shoulders up toward your ears.\",\"Roll them back and down in a smooth circle.\",\"Complete several slow circles.\",\"Reverse the direction and repeat.\"],\"img\":\"4395.webp\",\"gif\":\"4395.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple warm-up where you roll the shoulders in circles to loosen the upper back and shoulder joints.\"},{\"id\":\"2777\",\"n\":\"shoulder extension\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"triceps\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with your arm straight down at your side.\",\"Swing the arm back behind you, keeping it straight.\",\"Avoid leaning forward, pause, then return to the start.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2777.webp\",\"gif\":\"2777.mp4\",\"cat\":\"mobility\",\"desc\":\"Moving the arm back behind the body, working the lats and rear shoulder.\"},{\"id\":\"1978\",\"n\":\"shoulder extensor adductor and retractor stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"upper back\",\"triceps\"],\"st\":[\"Stand tall and extend one arm behind you.\",\"Reach across to grab it with the other hand.\",\"Draw the arm gently back and across the body.\",\"Keep your chest open and your shoulders down.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1978.webp\",\"gif\":\"1978.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the back of the shoulder and the muscles between the shoulder blades.\"},{\"id\":\"6790\",\"n\":\"shoulder external rotation test\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand or lie with your elbow bent 90 degrees and tucked at your side.\",\"Keep your elbow against your body.\",\"Rotate your forearm outward slowly.\",\"Stop where you feel a stretch or end of range.\",\"Note how far each side goes.\",\"Repeat on the other arm.\"],\"img\":\"6790.webp\",\"gif\":\"6790.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple check of how far the shoulder turns outward. Move slowly and stay in a pain-free range.\"},{\"id\":\"2778\",\"n\":\"shoulder flexion\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"biceps\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with your arms at your sides, palms facing in.\",\"Raise one arm forward and up to about shoulder height or higher.\",\"Keep your ribs down, then lower slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2778.webp\",\"gif\":\"2778.mp4\",\"cat\":\"mobility\",\"desc\":\"Raising the arm forward and up in front of the body, working the front of the shoulder.\"},{\"id\":\"2931\",\"n\":\"shoulder flexion back to wall\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"rotator cuff\",\"core\"],\"st\":[\"Stand with your back, head and hips against a wall.\",\"Keep your arms at your sides with elbows straight.\",\"Raise your arms forward and up overhead as far as you can without arching your back.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2931.webp\",\"gif\":\"2931.mp4\",\"cat\":\"mobility\",\"desc\":\"Raising your arms overhead while your back stays against a wall. It improves shoulder mobility and posture.\"},{\"id\":\"6791\",\"n\":\"shoulder internal rotation test\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Reach one arm behind your back with the palm facing out.\",\"Slide your hand slowly up your spine as far as is comfortable.\",\"Note how high your thumb reaches, keeping your chest open.\",\"Lower the arm, then repeat with the other side to compare.\"],\"img\":\"6791.webp\",\"gif\":\"6791.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple check of how far your shoulder turns inward, handy for spotting tightness before you train.\"},{\"id\":\"2779\",\"n\":\"shoulder lateral rotation (external rotation)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand with your elbow at your side bent at 90 degrees, forearm pointing forward.\",\"Rotate your forearm outward, keeping the elbow tucked against your side.\",\"Pause briefly, then return slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2779.webp\",\"gif\":\"2779.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the upper arm outward, which works the rotator cuff muscles at the back of the shoulder.\"},{\"id\":\"6792\",\"n\":\"shoulder level test\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\"],\"st\":[\"Stand relaxed with your feet hip-width apart and arms hanging loose.\",\"Look straight ahead and let your shoulders settle naturally.\",\"Check in a mirror, or ask a friend, whether both shoulders are at the same height.\",\"Roll the shoulders once and re-check without shrugging.\",\"Note any difference and repeat now and then to track it.\"],\"img\":\"6792.webp\",\"gif\":\"6792.mp4\",\"cat\":\"mobility\",\"desc\":\"A quick posture check to see whether one shoulder sits higher than the other.\"},{\"id\":\"2780\",\"n\":\"shoulder medial rotation (internal rotation)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand with your elbow at your side bent at 90 degrees, forearm pointing forward.\",\"Rotate your forearm inward across your stomach, keeping the elbow tucked in.\",\"Pause briefly, then return slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2780.webp\",\"gif\":\"2780.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the upper arm inward, working the muscles that turn the shoulder in.\"},{\"id\":\"0698\",\"n\":\"shoulder press (with band)\",\"bp\":\"shoulders\",\"eq\":\"band\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand on the band with feet shoulder-width apart.\",\"Hold the band at shoulder height.\",\"Press your hands overhead until your arms are straight.\",\"Keep your core tight.\",\"Lower slowly back to the shoulders.\",\"Avoid leaning back.\"],\"img\":\"0698.webp\",\"gif\":\"0698.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press using a band for resistance. It builds the shoulders and triceps.\"},{\"id\":\"1487\",\"n\":\"shoulder stand yoga pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"trapezius\"],\"st\":[\"Lie on your back and lift your legs overhead, supporting your lower back with your hands.\",\"Walk your hands up toward your shoulder blades.\",\"Raise your legs straight up so your body forms a line over your shoulders.\",\"Keep your neck long and still, and do not turn your head.\",\"Hold for 15-30 seconds, then lower slowly.\"],\"img\":\"1487.webp\",\"gif\":\"1487.mp4\",\"cat\":\"yoga\",\"desc\":\"An inverted yoga pose balanced on the shoulders. It builds shoulder and core control and stretches the neck-side muscles.\"},{\"id\":\"1488\",\"n\":\"shoulder stretch behind the back\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"upper chest\"],\"st\":[\"Stand tall and clasp your hands behind your back.\",\"Straighten your arms and squeeze your shoulder blades together.\",\"Lift your hands gently away from your body until you feel a stretch.\",\"Keep your chest open and avoid arching your lower back.\",\"Hold for 20-30 seconds, breathing steadily, then release slowly.\"],\"img\":\"1488.webp\",\"gif\":\"1488.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple stretch that opens the front of the shoulders and chest by clasping the hands behind you.\"},{\"id\":\"10932\",\"n\":\"shoulder stretch behind the back with towel\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"triceps\",\"chest\"],\"st\":[\"Hold a towel with one hand over your shoulder and the other behind your lower back.\",\"Gently pull the towel upward with the lower hand.\",\"Keep your chest open and neck relaxed.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"10932.webp\",\"gif\":\"10932.mp4\",\"cat\":\"stretching\",\"desc\":\"A towel stretch behind the back that opens the shoulder.\"},{\"id\":\"2088\",\"n\":\"shoulder stretch with towel behind the back\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"chest\"],\"st\":[\"Hold a towel in one hand and raise that arm overhead, bending the elbow.\",\"Reach the other hand up from behind your back and grab the towel.\",\"Gently pull the towel down with the lower hand.\",\"Keep your head upright.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2088.webp\",\"gif\":\"2088.mp4\",\"cat\":\"stretching\",\"desc\":\"Using a towel behind the back to ease the shoulders into a deeper stretch.\"},{\"id\":\"2781\",\"n\":\"shoulder transverse abduction\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with one arm held out in front at shoulder height.\",\"Sweep the arm out and back in a horizontal arc as far as is comfortable.\",\"Keep the arm at shoulder height, pause, then return.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2781.webp\",\"gif\":\"2781.mp4\",\"cat\":\"mobility\",\"desc\":\"Moving the arm backward in a horizontal arc, working the rear delts and upper back.\"},{\"id\":\"2782\",\"n\":\"shoulder transverse adduction\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with one arm held out to the side at shoulder height.\",\"Sweep the arm forward and across your body in a horizontal arc.\",\"Keep the arm at shoulder height, pause, then return.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2782.webp\",\"gif\":\"2782.mp4\",\"cat\":\"mobility\",\"desc\":\"Moving the arm forward and across the body in a horizontal arc, working the chest.\"},{\"id\":\"2783\",\"n\":\"shoulder transverse extension\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with your arm held in front at shoulder height.\",\"Pull the arm back and out to the side, keeping it level.\",\"Squeeze your shoulder blade lightly, then return slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2783.webp\",\"gif\":\"2783.mp4\",\"cat\":\"mobility\",\"desc\":\"Drawing the arm back in a horizontal plane, working the rear shoulder and upper back.\"},{\"id\":\"2784\",\"n\":\"shoulder transverse flexion\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand tall with your arm held out to the side at shoulder height.\",\"Bring the arm forward in front of your chest, keeping it level.\",\"Pause briefly, then return slowly to the side.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2784.webp\",\"gif\":\"2784.mp4\",\"cat\":\"mobility\",\"desc\":\"Bringing the arm forward in a horizontal plane, working the chest and front shoulder.\"},{\"id\":\"5473\",\"n\":\"shoulder width neutral grip pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"upper back\",\"forearms\"],\"st\":[\"Grab neutral-grip handles about shoulder width apart and hang with arms straight.\",\"Brace your core and pull your shoulder blades down.\",\"Pull your chest toward your hands until your chin clears the bar.\",\"Lower yourself slowly to a full hang.\",\"Avoid swinging or kicking.\"],\"img\":\"5473.webp\",\"gif\":\"5473.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull-up with palms facing each other at shoulder width, a joint-friendly grip that builds the lats and arms.\"},{\"id\":\"3366\",\"n\":\"shrimp squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand on one leg and bend the other knee, holding that foot behind you.\",\"Reach your free arm forward for balance.\",\"Lower slowly until the back knee lightly touches the floor.\",\"Drive through the front foot to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"3366.webp\",\"gif\":\"3366.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat with the back foot held behind you, demanding strong quads and good balance.\"},{\"id\":\"4176\",\"n\":\"shrug (on parallel bars)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Support yourself on parallel bars with straight arms.\",\"Let your shoulders sink down.\",\"Push up to elevate your shoulders toward your ears.\",\"Pause at the top.\",\"Lower with control.\",\"Keep your elbows locked.\"],\"img\":\"4176.webp\",\"gif\":\"4176.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A shrug performed supported on parallel bars. It lifts and lowers the shoulders to train the traps.\"},{\"id\":\"4257\",\"n\":\"shuffle\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"calves\",\"adductors\"],\"st\":[\"Stand with your feet slightly wider than your shoulders and knees bent.\",\"Keep your chest up and your weight on your toes.\",\"Step sideways without crossing your feet.\",\"Move quickly for a few steps.\",\"Change direction and shuffle back.\",\"Stay low throughout.\"],\"img\":\"4257.webp\",\"gif\":\"4257.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Quick lateral steps in an athletic stance. It builds agility, coordination and leg endurance.\"},{\"id\":\"6803\",\"n\":\"side and front in out\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Sit on the floor leaning back, hands behind you for support.\",\"Lift your feet off the floor with knees bent.\",\"Extend your legs out to one side and pull them back in.\",\"Extend them straight in front and pull back in.\",\"Repeat the pattern on the other side.\"],\"img\":\"6803.webp\",\"gif\":\"6803.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated in and out leg drill that goes to the side and then to the front. It works the abs and obliques.\"},{\"id\":\"3965\",\"n\":\"side bear crawl\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"glutes\"],\"st\":[\"Get on hands and toes with knees just off the floor.\",\"Keep your back flat.\",\"Step the hand and foot on one side out, then bring the other pair along.\",\"Move several steps one way, then return.\",\"Stay low and keep your hips steady.\"],\"img\":\"3965.webp\",\"gif\":\"3965.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bear crawl moving sideways on hands and toes. It builds shoulder stability, core control and leg endurance.\"},{\"id\":\"4786\",\"n\":\"side bench squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand sideways to a bench with feet wide.\",\"Shift your weight to the leg nearest the bench.\",\"Sit back and down until you lightly touch the bench.\",\"Keep the other leg straight.\",\"Drive up through your heel and repeat, then switch sides.\"],\"img\":\"4786.webp\",\"gif\":\"4786.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side squat toward a bench with body weight only. It works the thighs and glutes one side at a time.\"},{\"id\":\"2864\",\"n\":\"side bend\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Sit tall on your side with your bottom hand pressed into the mat and your legs stacked.\",\"Lift your hips so your body forms a long diagonal line.\",\"Reach your top arm overhead and bend sideways over the supporting arm.\",\"Lift back up to the long line while keeping your hips high.\",\"Lower with control and repeat, then switch sides.\"],\"img\":\"2864.webp\",\"gif\":\"2864.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates side bend from a seated or side-supported position that works the obliques and the sides of the trunk.\"},{\"id\":\"0700\",\"n\":\"side bend (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"lower back\"],\"st\":[\"Lie sideways over a stability ball with feet braced.\",\"Place your hands behind your head.\",\"Lower your upper body over the ball.\",\"Lift back up by contracting the obliques.\",\"Keep your hips steady.\",\"Finish reps, then switch sides.\"],\"img\":\"0700.webp\",\"gif\":\"0700.mp4\",\"cat\":\"strength\",\"desc\":\"Lying sideways over a stability ball, you bend toward the ceiling. It targets the side of the waist.\"},{\"id\":\"0706\",\"n\":\"side bridge\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side with legs stacked.\",\"Place your elbow under your shoulder.\",\"Lift your hips until you form a straight line.\",\"Brace your abs.\",\"Hold for 20-30 seconds.\",\"Lower and switch sides.\"],\"img\":\"0706.webp\",\"gif\":\"0706.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank held on one forearm. It strengthens the sides of your trunk.\",\"hd\":1},{\"id\":\"0701\",\"n\":\"side bridge (bent knee)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side with your knees bent.\",\"Place your forearm under your shoulder.\",\"Lift your hips off the floor.\",\"Keep your body in a straight line from knees to head.\",\"Hold for 20-30 seconds.\",\"Lower and switch sides.\"],\"img\":\"0701.webp\",\"gif\":\"0701.mp4\",\"cat\":\"isometric\",\"desc\":\"An easier side plank with the knees bent. It builds the obliques and side stability.\",\"hd\":1},{\"id\":\"0702\",\"n\":\"side bridge (knee tuck)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\",\"shoulders\"],\"st\":[\"Start in a side plank on your forearm.\",\"Raise your top leg slightly.\",\"Pull your top knee toward your chest.\",\"Extend the leg back.\",\"Keep your hips lifted.\",\"Finish reps, then switch sides.\"],\"img\":\"0702.webp\",\"gif\":\"0702.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with a knee tuck for extra core work. It trains the obliques and hip flexors.\"},{\"id\":\"0703\",\"n\":\"side bridge hip abduction (star)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Start in a side plank on your forearm.\",\"Keep your body straight.\",\"Lift your top leg toward the ceiling.\",\"Hold briefly.\",\"Lower the leg with control.\",\"Switch sides after your reps.\"],\"img\":\"0703.webp\",\"gif\":\"0703.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with the top leg raised in a star shape. It works the outer hip and obliques.\"},{\"id\":\"3584\",\"n\":\"side bridge with arm leg swing\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\",\"hip flexors\"],\"st\":[\"Lie on one side and prop yourself on your forearm.\",\"Lift your hips into a straight line.\",\"Raise the top leg and arm.\",\"Swing them toward each other under control.\",\"Keep your hips high, then switch sides.\"],\"img\":\"3584.webp\",\"gif\":\"3584.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with the top arm and leg swinging, challenging the obliques and balance.\"},{\"id\":\"5047\",\"n\":\"side bridge with bent leg\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Lie on your side with knees bent and your forearm under your shoulder.\",\"Lift your hips so your body forms a line from shoulder to knee.\",\"Keep your hips stacked and core tight.\",\"Hold for 20-30 seconds.\",\"Lower and switch sides.\"],\"img\":\"5047.webp\",\"gif\":\"5047.mp4\",\"cat\":\"isometric\",\"desc\":\"Side plank with the knees bent for a gentler version. It builds the obliques and hip stability.\",\"hd\":1,\"fv\":\"4461\"},{\"id\":\"4458\",\"n\":\"side bridge with straight legs\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Lie on your side with your elbow under your shoulder and legs stacked.\",\"Lift your hips so your body forms a straight line.\",\"Keep your core tight and your neck neutral.\",\"Hold for 20-40 seconds without letting your hips sag.\",\"Lower down and repeat on the other side.\"],\"img\":\"4458.webp\",\"gif\":\"4458.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with both legs straight, held on one forearm. It strengthens the obliques and hips.\",\"hd\":1},{\"id\":\"0708\",\"n\":\"side crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and tilted to one side.\",\"Place your hands behind your head.\",\"Crunch up, lifting your shoulders.\",\"Squeeze your side.\",\"Lower with control.\",\"Finish reps, then switch sides.\"],\"img\":\"0708.webp\",\"gif\":\"0708.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch focusing on the sides of the waist. It strengthens the obliques.\"},{\"id\":\"0707\",\"n\":\"side crunch v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your side with your knees bent.\",\"Place your hands lightly behind your head.\",\"Lift your upper body and legs toward each other.\",\"Squeeze your side.\",\"Lower slowly.\",\"Finish reps, then switch sides.\"],\"img\":\"0707.webp\",\"gif\":\"0707.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying crunch that brings the ribs toward the hip. It works the obliques.\"},{\"id\":\"4812\",\"n\":\"side crunch v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your side with knees bent and one hand behind your head.\",\"Rest the other hand on the floor for balance.\",\"Lift your shoulders and knees toward each other.\",\"Squeeze the side of your waist at the top.\",\"Lower slowly without relaxing fully.\",\"Complete your reps, then switch sides.\"],\"img\":\"4812.webp\",\"gif\":\"4812.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side crunch, a second variation, aimed at the obliques. It shortens the side of the waist with a small controlled movement.\"},{\"id\":\"4787\",\"n\":\"side crunch with hands on chest\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your side with knees slightly bent and arms crossed over your chest.\",\"Brace your core and lift your shoulders and legs toward each other.\",\"Crunch sideways, squeezing the side of your waist.\",\"Pause at the top, then lower slowly.\",\"Keep the movement small and controlled, without pulling on your neck.\",\"Complete your reps, then switch sides.\"],\"img\":\"4787.webp\",\"gif\":\"4787.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying crunch with the arms crossed over the chest. It works the obliques along the side of the trunk.\"},{\"id\":\"8399\",\"n\":\"side floor tap plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Start in a high plank with hands under shoulders and feet wide.\",\"Keep your body in a straight line.\",\"Reach one hand out to tap the floor at the side without twisting your hips.\",\"Return it and tap with the other hand.\",\"Keep the pace steady and controlled.\"],\"img\":\"8399.webp\",\"gif\":\"8399.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank where you tap a hand to the floor at the side, challenging the obliques and anti-rotation control.\"},{\"id\":\"2562\",\"n\":\"side jump step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand beside a low step.\",\"Place your near foot on the step.\",\"Drive up with a small jump.\",\"Land softly on the step.\",\"Step down with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"2562.webp\",\"gif\":\"2562.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side-on step with a jump that trains power in the legs.\"},{\"id\":\"5124\",\"n\":\"side jump twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"calves\",\"quadriceps\"],\"st\":[\"Stand with your feet together and arms bent.\",\"Jump and twist your hips and legs to one side while your shoulders face forward.\",\"Land softly on the balls of your feet.\",\"Jump again and twist to the other side.\",\"Keep a steady rhythm for 30-45 seconds.\"],\"img\":\"5124.webp\",\"gif\":\"5124.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jump while twisting your hips and legs to the side. It warms up the core and legs.\"},{\"id\":\"2307\",\"n\":\"side kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"core\"],\"st\":[\"Stand sideways in a fighting stance with your hands up.\",\"Lift your knee toward your chest.\",\"Extend the leg sideways and push the heel to the target.\",\"Keep your supporting foot turned slightly away.\",\"Pull the leg back and set it down.\",\"Repeat, then switch legs.\"],\"img\":\"2307.webp\",\"gif\":\"2307.mp4\",\"cat\":\"combat\",\"desc\":\"A kick that thrusts the heel out to the side, using hip strength and balance.\",\"fv\":\"2865\"},{\"id\":\"3153\",\"n\":\"side kick burpee\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"chest\",\"sm\":[\"chest\",\"quadriceps\",\"glutes\",\"triceps\",\"core\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Drop your hands to the floor and jump your feet back to a plank.\",\"Do a push-up, then jump your feet back in.\",\"Stand up and kick one leg out to the side.\",\"Land and go straight into the next rep.\",\"Alternate kicking sides.\"],\"img\":\"3153.webp\",\"gif\":\"3153.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee that finishes with a side kick. It's a tough full-body conditioning move.\"},{\"id\":\"2875\",\"n\":\"side kick kneeling\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Kneel on one knee with the opposite leg extended to the side.\",\"Place your bottom hand on the mat and keep the top hand light behind your head.\",\"Kick the top leg forward, then sweep it back with control.\",\"Keep your torso steady and tall.\",\"Complete your reps, then switch sides.\"],\"img\":\"2875.webp\",\"gif\":\"2875.mp4\",\"cat\":\"pilates\",\"desc\":\"A kneeling Pilates side kick that works the outer hip and core stability.\"},{\"id\":\"6335\",\"n\":\"side kick through\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"hip flexors\"],\"st\":[\"Start in a high plank, then rotate onto one hand with your chest turned to the side.\",\"Lift your hips and keep your core tight.\",\"Sweep your top leg under your body and through the gap.\",\"Return the leg to the start with control.\",\"Repeat, then switch sides.\"],\"img\":\"6335.webp\",\"gif\":\"6335.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor move where you sweep one leg under your body from a side-facing support, working your obliques, shoulders and coordination.\"},{\"id\":\"1802\",\"n\":\"side lat stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Stand tall with your feet hip-width apart and raise one arm overhead.\",\"Lean to the opposite side from the raised arm, reaching over without twisting.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1802.webp\",\"gif\":\"1802.mp4\",\"cat\":\"stretching\",\"desc\":\"Bending sideways with an arm overhead lengthens the lat and the side of your trunk. A quick stretch for the flanks.\"},{\"id\":\"2972\",\"n\":\"side lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand tall with your feet together and hands in front of your chest.\",\"Step wide to one side.\",\"Bend that knee and sit your hips back, keeping the other leg straight.\",\"Push off the bent leg to return.\",\"Alternate sides.\"],\"img\":\"2972.webp\",\"gif\":\"2972.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Stepping out to the side into a deep lunge. It works the quads and glutes while opening the inner thighs.\",\"fv\":\"2973\"},{\"id\":\"1899\",\"n\":\"side lunge adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\",\"glutes\"],\"st\":[\"Stand with your feet wide apart.\",\"Shift your weight to one side and bend that knee.\",\"Keep the other leg straight with the foot flat.\",\"Keep your chest tall.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1899.webp\",\"gif\":\"1899.mp4\",\"cat\":\"stretching\",\"desc\":\"A wide side lunge that stretches the inner thigh of the straight leg.\"},{\"id\":\"0711\",\"n\":\"side lunge stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"hamstrings\"],\"st\":[\"Stand with your feet wide apart.\",\"Shift your weight to one side and bend that knee.\",\"Keep the other leg straight.\",\"Keep your chest up.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"0711.webp\",\"gif\":\"0711.mp4\",\"cat\":\"stretching\",\"desc\":\"A wide lunge to the side that stretches the inner thigh. It improves hip mobility.\"},{\"id\":\"8971\",\"n\":\"side lunge stretch v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Stand with your feet wide apart and toes pointing forward.\",\"Shift your weight to one side and bend that knee.\",\"Keep the other leg straight with the foot flat or toes up.\",\"Sit your hips back and feel the stretch on the inner thigh.\",\"Hold for 20-30 seconds.\",\"Switch sides and repeat.\"],\"img\":\"8971.webp\",\"gif\":\"8971.mp4\",\"cat\":\"stretching\",\"desc\":\"Sinking into a wide side lunge stretches the inner thigh and groin. A good opener before lower body work.\"},{\"id\":\"8289\",\"n\":\"side lying chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie on your side with your knees bent and arms in front of you.\",\"Lift your top arm and open it back like a book.\",\"Let your chest rotate open.\",\"Hold for 20-30 seconds.\",\"Return and switch sides.\"],\"img\":\"8289.webp\",\"gif\":\"8289.mp4\",\"cat\":\"stretching\",\"desc\":\"Lying on your side, you open one arm backward to stretch the chest. It loosens tight pecs.\"},{\"id\":\"2461\",\"n\":\"side lying clam\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Lie on your side with knees bent and feet stacked, head on your arm.\",\"Keep your hips stacked and your core lightly braced.\",\"Lift the top knee while keeping your feet together.\",\"Pause at the top, then lower slowly.\",\"Do all reps, then switch sides.\"],\"img\":\"2461.webp\",\"gif\":\"2461.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your side with knees bent, you open the top knee like a clam to strengthen the outer hip and glutes.\"},{\"id\":\"6751\",\"n\":\"side lying diagonal backward leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your side with legs stacked and your bottom arm supporting your head.\",\"Brace your core and keep your hips stacked.\",\"Lift the top leg up and slightly back on a diagonal.\",\"Squeeze your glute at the top.\",\"Lower slowly.\",\"Finish the reps, then switch sides.\"],\"img\":\"6751.webp\",\"gif\":\"6751.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying leg lift that goes back on a diagonal. It focuses on the glutes and outer hip.\"},{\"id\":\"10933\",\"n\":\"side lying external rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie on your side with your top elbow bent to 90 degrees against your ribs.\",\"Hold your forearm across your stomach.\",\"Rotate your forearm upward without moving your elbow.\",\"Lower slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"10933.webp\",\"gif\":\"10933.mp4\",\"cat\":\"rehab\",\"desc\":\"A light side-lying rotation for the back of the shoulder. Often used for shoulder stability.\"},{\"id\":\"0712\",\"n\":\"side lying feet raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"obliques\"],\"st\":[\"Lie on your side with legs straight.\",\"Support your head with your arm.\",\"Lift both feet off the floor together.\",\"Hold briefly.\",\"Lower slowly.\",\"Finish reps, then switch sides.\"],\"img\":\"0712.webp\",\"gif\":\"0712.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side-lying lift of both feet at once. It works the inner thighs and the sides of the waist.\"},{\"id\":\"5998\",\"n\":\"side lying hip adduction (left)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"glutes\",\"core\"],\"st\":[\"Lie on your left side with your legs straight.\",\"Bend your right knee and place that foot in front of you.\",\"Raise your left leg a few inches off the floor.\",\"Pause at the top.\",\"Lower slowly and repeat, then switch sides.\"],\"img\":\"5998.webp\",\"gif\":\"5998.mp4\",\"cat\":\"strength\",\"desc\":\"A lying leg lift that trains the inner thigh of the left leg.\",\"fv\":\"5999\"},{\"id\":\"7213\",\"n\":\"side lying internal rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\"],\"st\":[\"Lie on your side with your elbow bent to 90 degrees and tucked to your ribs.\",\"Rest the forearm on the floor in front of you.\",\"Rotate your forearm up toward your belly.\",\"Lower it slowly back to the floor.\",\"Finish your reps, then switch sides.\"],\"img\":\"7213.webp\",\"gif\":\"7213.mp4\",\"cat\":\"rehab\",\"desc\":\"A light rotation exercise lying on your side that turns the arm inward. It strengthens the rotator cuff gently.\"},{\"id\":\"3926\",\"n\":\"side lying leg circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"adductors\",\"core\"],\"st\":[\"Lie on your side with your legs stacked.\",\"Lift the top leg slightly.\",\"Draw small circles in the air.\",\"Do 10 circles, then reverse direction.\",\"Keep your pelvis still.\",\"Switch sides.\"],\"img\":\"3926.webp\",\"gif\":\"3926.mp4\",\"cat\":\"pilates\",\"desc\":\"A slow side-lying leg circle that works the outer hip and mobilizes the hip joint.\"},{\"id\":\"4051\",\"n\":\"side lying leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your side with your legs stacked and your head supported.\",\"Keep your hips stacked and core braced.\",\"Lift the top leg up with the toes pointing forward.\",\"Pause at the top.\",\"Lower slowly, finish the reps, then switch sides.\"],\"img\":\"4051.webp\",\"gif\":\"4051.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your side, you lift the top leg. It works the outer hip and glutes.\"},{\"id\":\"4884\",\"n\":\"side lying outward knee kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your side with your hips stacked and bottom leg bent.\",\"Bend the top knee and bring it toward your chest.\",\"Kick the top leg straight out to the side.\",\"Pull the knee back in under control.\",\"Keep your torso still the whole time.\",\"Complete your reps, then switch sides.\"],\"img\":\"4884.webp\",\"gif\":\"4884.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a side lying position you swing the top knee out and kick the leg outward. It works the outer hips and glutes.\"},{\"id\":\"4882\",\"n\":\"side lying scissors\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your side with your body in a straight line and head supported.\",\"Stack your legs and lift the top leg slightly.\",\"Raise the top leg up while the bottom leg lifts toward it.\",\"Bring them back together in a smooth scissor motion.\",\"Keep your hips stacked and still.\",\"Finish your reps, then switch sides.\"],\"img\":\"4882.webp\",\"gif\":\"4882.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your side, you open and close the legs like scissors. Good for the outer hips and the glutes.\",\"fv\":\"4655\"},{\"id\":\"5680\",\"n\":\"side mountain climber\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Start in a high plank with hands under your shoulders.\",\"Drive one knee out toward the same-side elbow.\",\"Return that foot and switch quickly to the other leg.\",\"Keep your hips low and your core tight.\",\"Continue at a brisk pace for the set time.\"],\"img\":\"5680.webp\",\"gif\":\"5680.mp4\",\"cat\":\"cardio\",\"desc\":\"A mountain climber where the knees drive toward the elbows on the side. It raises your heart rate and works the obliques and hips.\"},{\"id\":\"0713\",\"n\":\"side neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Sit or stand tall with your shoulders relaxed.\",\"Tilt your head so your ear moves toward one shoulder.\",\"Keep the opposite shoulder pressed down.\",\"Hold for 20-30 seconds.\",\"Return to centre and repeat on the other side.\",\"Don't pull hard on your head, a light weight of the hand is enough.\"],\"img\":\"0713.webp\",\"gif\":\"0713.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple side-bend stretch for the muscles along the side of your neck and top of the shoulders.\"},{\"id\":\"0715\",\"n\":\"side plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side with your elbow under your shoulder and legs stacked.\",\"Lift your hips so your body forms a straight line from head to feet.\",\"Keep your hips high and your neck neutral.\",\"Hold for 20-45 seconds.\",\"Lower with control and switch sides.\",\"Don't let your hips drop or roll forward.\"],\"img\":\"0715.webp\",\"gif\":\"0715.mp4\",\"cat\":\"isometric\",\"desc\":\"A sideways plank balanced on one forearm. It builds strength in the obliques and the muscles that stabilise your trunk.\",\"hd\":1},{\"id\":\"2899\",\"n\":\"side plank (beginner)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Lie on your side with knees bent and your elbow under your shoulder.\",\"Stack your hips and knees.\",\"Press into your forearm to lift your hips off the floor.\",\"Hold a straight line from knees to head.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2899.webp\",\"gif\":\"2899.mp4\",\"cat\":\"isometric\",\"desc\":\"A bent-knee side plank that builds oblique and hip strength for beginners.\",\"hd\":1},{\"id\":\"6466\",\"n\":\"side plank bent leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on one side and prop yourself on your forearm.\",\"Lift your hips so your body forms a line.\",\"Bend your top knee and lift it upward.\",\"Lower it without dropping your hips.\",\"Finish your reps, then switch sides.\"],\"img\":\"6466.webp\",\"gif\":\"6466.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with a bent top leg that you lift, challenging your obliques and outer hips.\"},{\"id\":\"2349\",\"n\":\"side plank butt (form check)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side with your forearm on the floor and elbow under your shoulder.\",\"Stack your feet and lift your hips off the floor.\",\"Make a straight line from your head to your feet.\",\"Avoid letting your butt stick out or your hips drop.\",\"Squeeze your abs and glutes to stay level.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2349.webp\",\"gif\":\"2349.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank form check that compares a piked butt with a straight body line.\"},{\"id\":\"9849\",\"n\":\"side plank clamshell\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Lie on your side in a side plank, supported on your forearm with knees bent.\",\"Lift your hips so your body is in a line.\",\"Keep your feet together and open your top knee upward.\",\"Close it under control.\",\"Finish your reps, then switch sides.\"],\"img\":\"9849.webp\",\"gif\":\"9849.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank where you open and close your top knee. It works the outer hips and the obliques.\"},{\"id\":\"3460\",\"n\":\"side plank hip adduction (bent knee)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\"],\"st\":[\"Set up in a side plank with the bottom knee bent.\",\"Keep your body straight.\",\"Lift your hips.\",\"Raise the bottom leg toward the top leg.\",\"Lower with control.\",\"Switch sides.\"],\"img\":\"3460.webp\",\"gif\":\"3460.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with the top leg lifting inward, working the inner thighs and obliques.\"},{\"id\":\"4863\",\"n\":\"side plank leg lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side and prop up on your forearm.\",\"Lift your hips into a side plank.\",\"Raise your top leg.\",\"Lower it slowly.\",\"Switch sides after your reps.\"],\"img\":\"4863.webp\",\"gif\":\"4863.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with the top leg lifted. It trains the obliques and hip stabilisers.\"},{\"id\":\"6207\",\"n\":\"side plank leg lift (left)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"core\"],\"st\":[\"Lie on your left side and prop up on your forearm.\",\"Lift your hips into a side plank.\",\"Raise your top leg slowly.\",\"Lower the leg without dropping your hips.\",\"Repeat for your set.\",\"Switch sides for the right-side version.\"],\"img\":\"6207.webp\",\"gif\":\"6207.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with a leg raise on the left side. It works the obliques and outer hip.\"},{\"id\":\"3264\",\"n\":\"side plank leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Lie on your side and prop yourself up on one forearm with elbow under the shoulder.\",\"Lift your hips so your body forms a straight line.\",\"Raise your top leg to about hip height, toes pointing forward.\",\"Lower it a little without dropping your hips.\",\"Finish your reps, then switch sides.\"],\"img\":\"3264.webp\",\"gif\":\"3264.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hold a side plank and lift the top leg to work the outer hips and the side of your trunk.\"},{\"id\":\"4334\",\"n\":\"side plank oblique crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Set up in a side plank on one forearm, feet stacked or staggered.\",\"Put your free hand behind your head.\",\"Bring your top knee and elbow together beneath your torso.\",\"Extend back to the side plank position.\",\"Complete your reps, then switch sides.\"],\"img\":\"4334.webp\",\"gif\":\"4334.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with a knee-to-elbow crunch. It trains the obliques and shoulder stability together.\"},{\"id\":\"6026\",\"n\":\"side plank pull\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Get into a side plank on your forearm with your body in a straight line.\",\"Reach your top arm overhead.\",\"Pull your elbow down toward your ribs.\",\"Keep your hips lifted.\",\"Finish your reps, then switch sides.\"],\"img\":\"6026.webp\",\"gif\":\"6026.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with a pulling arm motion, to build core stability and shoulder strength.\",\"fv\":\"6093\"},{\"id\":\"4991\",\"n\":\"side plank rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\",\"glutes\"],\"st\":[\"Set up in a side plank on one forearm or hand with your top arm raised.\",\"Lift your hips so your body is in a straight line.\",\"Thread your top arm under your torso, rotating your chest toward the floor.\",\"Rotate back and reach the arm up to the ceiling.\",\"Complete your reps, then switch sides.\"],\"img\":\"4991.webp\",\"gif\":\"4991.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with an arm rotation under the body. It builds the obliques and shoulder stability.\"},{\"id\":\"7854\",\"n\":\"side plank twist arm delt raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Set up in a side plank on your forearm.\",\"Raise your top arm up toward the ceiling.\",\"Rotate and thread your arm under your torso.\",\"Open back up and raise the arm again.\",\"Complete your reps, then switch sides.\"],\"img\":\"7854.webp\",\"gif\":\"7854.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side plank with a twist that ends in an arm raise. It challenges your obliques and shoulders.\"},{\"id\":\"0714\",\"n\":\"side plank v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side and prop up on your forearm.\",\"Stack your feet or stagger them.\",\"Lift your hips into a straight line.\",\"Keep your core tight.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"0714.webp\",\"gif\":\"0714.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank variation held on one forearm. It builds the obliques and shoulder stability.\",\"hd\":1},{\"id\":\"4811\",\"n\":\"side plank v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side and prop yourself on your forearm under your shoulder.\",\"Stack or stagger your feet.\",\"Lift your hips so your body forms a straight line.\",\"Keep your neck neutral and your core tight.\",\"Hold for 20-40 seconds.\",\"Lower down and repeat on the other side.\"],\"img\":\"4811.webp\",\"gif\":\"4811.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank hold, a second variation. It strengthens the obliques and the muscles that keep your trunk stable.\",\"hd\":1},{\"id\":\"4907\",\"n\":\"side plank with raised leg v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Set up in a side plank on your forearm with your body in a line.\",\"Lift your top leg to hip height.\",\"Keep your hips high and your core tight.\",\"Hold for 20-30 seconds without dropping.\",\"Lower down gently.\",\"Repeat on the other side.\"],\"img\":\"4907.webp\",\"gif\":\"4907.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with the top leg lifted, a second variation. It adds hip work to the oblique hold.\"},{\"id\":\"6208\",\"n\":\"side plank with raised leg v. 2 (left)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your left side and prop up on your left forearm, elbow under your shoulder.\",\"Stack your feet and lift your hips into a straight line.\",\"Raise your top leg to hip height.\",\"Hold for 20-30 seconds.\",\"Lower and repeat, then switch sides if you like.\"],\"img\":\"6208.webp\",\"gif\":\"6208.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank on the left side with the top leg lifted. It trains the obliques, hips and shoulder stability.\"},{\"id\":\"3922\",\"n\":\"side push up with towel\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Start in a push-up position with one hand on a towel on the floor.\",\"Slide that hand out to the side.\",\"Lower your chest toward the other hand.\",\"Push back up.\",\"Slide the towel hand back in.\",\"Switch sides.\"],\"img\":\"3922.webp\",\"gif\":\"3922.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up variation where one hand slides on a towel, shifting load to one side of the chest.\"},{\"id\":\"7154\",\"n\":\"side shuffle high knee\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"calves\",\"glutes\"],\"st\":[\"Stand with feet hip-width apart and knees slightly bent.\",\"Shuffle sideways for a few steps.\",\"Lift your knees high with each step.\",\"Stay light on your feet and pump your arms.\",\"Change direction and continue for 30-60 seconds.\"],\"img\":\"7154.webp\",\"gif\":\"7154.mp4\",\"cat\":\"cardio\",\"desc\":\"A lateral shuffle where each step brings the knee high. It raises your heart rate and builds agility.\"},{\"id\":\"3551\",\"n\":\"side shuttle\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"adductors\"],\"st\":[\"Stand with knees bent in an athletic stance.\",\"Shuffle to one side in quick steps.\",\"Touch the floor or change direction.\",\"Shuffle back the other way.\",\"Keep your chest up.\",\"Keep up the pace for 30-60 seconds.\"],\"img\":\"3551.webp\",\"gif\":\"3551.mp4\",\"cat\":\"cardio\",\"desc\":\"A lateral shuttle run at speed to raise the heart rate.\"},{\"id\":\"0718\",\"n\":\"side sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent.\",\"Place your hands behind your head.\",\"Sit up while reaching one elbow toward the opposite knee.\",\"Lower slowly.\",\"Keep your feet planted.\",\"Alternate sides.\"],\"img\":\"0718.webp\",\"gif\":\"0718.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up performed with a sideways angle. It emphasizes the obliques.\"},{\"id\":\"3458\",\"n\":\"side split\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Sit or stand with your legs as wide as comfortable.\",\"Keep your toes pointing up or forward.\",\"Lower slowly into the split.\",\"Keep your back long.\",\"Hold for 20-30 seconds.\",\"Come out gently.\"],\"img\":\"3458.webp\",\"gif\":\"3458.mp4\",\"cat\":\"stretching\",\"desc\":\"A wide-leg stretch for the inner thighs and groin.\"},{\"id\":\"4788\",\"n\":\"side split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand with feet wide and toes slightly out.\",\"Shift your weight to one side and bend that knee.\",\"Keep the other leg straight with the foot flat or toes up.\",\"Lower until your thigh is parallel.\",\"Push back to the middle and alternate sides.\"],\"img\":\"4788.webp\",\"gif\":\"4788.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide side-to-side squat on one leg at a time. It builds the thighs and mobilises the hips.\"},{\"id\":\"4789\",\"n\":\"side squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"inner thighs\"],\"st\":[\"Stand with feet wide and your arms in front for balance.\",\"Shift your weight to one leg and sit back and down.\",\"Keep the other leg straight.\",\"Keep your chest up and your heel down.\",\"Push back to the middle and switch sides.\"],\"img\":\"4789.webp\",\"gif\":\"4789.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side squat in a wide stance, bending one leg while the other stays straight. It works the thighs, glutes and inner legs.\"},{\"id\":\"3958\",\"n\":\"side step front plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank.\",\"Step one hand and foot out to the side.\",\"Bring the other hand and foot to meet them.\",\"Keep your hips level.\",\"Repeat in one direction, then reverse.\"],\"img\":\"3958.webp\",\"gif\":\"3958.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Walk your hands and feet sideways in a front plank to train the core and shoulders.\"},{\"id\":\"6011\",\"n\":\"side step rear delt row\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"upper back\",\"quadriceps\",\"glutes\"],\"st\":[\"Stand in a slight squat with your arms out in front.\",\"Step to the side.\",\"Pull your elbows back and squeeze your shoulder blades.\",\"Return your arms forward as you step back.\",\"Alternate sides at a steady pace.\"],\"img\":\"6011.webp\",\"gif\":\"6011.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side step paired with a rowing motion that works the rear shoulders and upper back while elevating your pulse.\",\"fv\":\"6012\"},{\"id\":\"0719\",\"n\":\"side stretch crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your side with your bottom arm extended overhead.\",\"Place your top hand behind your head.\",\"Stretch along your side.\",\"Crunch your top elbow toward your hip.\",\"Return to the stretch.\",\"Switch sides.\"],\"img\":\"0719.webp\",\"gif\":\"0719.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side crunch that combines a side stretch and a contraction. It works the obliques.\"},{\"id\":\"1588\",\"n\":\"side to side box shuffle\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"glutes\"],\"st\":[\"Stand next to a low box or step on one side.\",\"Place the foot closest to it on top.\",\"Hop across, landing the other foot on the box as the first foot goes down.\",\"Keep your steps light and quick.\",\"Continue shuffling side to side at a steady pace.\"],\"img\":\"1588.webp\",\"gif\":\"1588.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick-footed drill where you hop side to side over a box. It builds agility, lower leg stamina and conditioning.\"},{\"id\":\"5153\",\"n\":\"side to side hop\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"ankles\"],\"st\":[\"Stand on one foot with a slight knee bend.\",\"Hop sideways to the other foot.\",\"Land softly and balance for a second.\",\"Hop back to the first foot.\",\"Keep your hips level and repeat for 20-30 hops.\"],\"img\":\"5153.webp\",\"gif\":\"5153.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Hop laterally from one foot to the other. It builds ankle stability, leg power and agility.\",\"fv\":\"8186\"},{\"id\":\"8916\",\"n\":\"side to side hop v. 2\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"glutes\"],\"st\":[\"Stand on two feet with your knees slightly bent.\",\"Hop sideways to one side, landing softly on the balls of your feet.\",\"Immediately hop back to the other side.\",\"Keep your chest up and your hips low.\",\"Use your arms for balance and rhythm.\",\"Go for a set time or a set number of reps.\"],\"img\":\"8916.webp\",\"gif\":\"8916.mp4\",\"cat\":\"plyometrics\",\"desc\":\"You hop from one side to the other over an imaginary line. It builds lateral agility, leg power and conditioning.\"},{\"id\":\"10732\",\"n\":\"side to side jump over stepbox\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Stand beside a low box with your feet together.\",\"Bend your knees and swing your arms.\",\"Jump sideways over the box.\",\"Land softly on both feet.\",\"Jump back the other way at once.\",\"Keep the pace fast but controlled.\"],\"img\":\"10732.webp\",\"gif\":\"10732.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lateral jump back and forth over a step box. It builds agility and leg power.\"},{\"id\":\"3675\",\"n\":\"side to side jump rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"shoulders\",\"quadriceps\"],\"st\":[\"Hold the rope handles and stand tall.\",\"Swing the rope overhead.\",\"Hop side to side over the rope.\",\"Land softly on the balls of your feet.\",\"Keep a steady rhythm.\"],\"img\":\"3675.webp\",\"gif\":\"3675.mp4\",\"cat\":\"cardio\",\"desc\":\"Jump rope while hopping side to side to raise your heart rate and improve agility.\"},{\"id\":\"4630\",\"n\":\"side to side leg swings\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\"],\"st\":[\"Stand tall and hold a wall or support for balance.\",\"Shift onto one leg.\",\"Swing the other leg across your body, then out to the side.\",\"Keep your torso upright and the swing controlled.\",\"Do your reps, then switch legs.\"],\"img\":\"4630.webp\",\"gif\":\"4630.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic warm-up swinging one leg across your body and out to the side to loosen the hips.\",\"fv\":\"2574\"},{\"id\":\"4909\",\"n\":\"side to wide squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet together and arms in front.\",\"Step one foot out to the side into a wide stance.\",\"Sit down into a squat with your chest up.\",\"Stand up and bring your feet back together.\",\"Alternate the stepping side.\",\"Keep your knees tracking over your toes.\"],\"img\":\"4909.webp\",\"gif\":\"4909.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat that starts with feet together and steps out to a wide stance. It trains the glutes and legs.\"},{\"id\":\"3250\",\"n\":\"side toe touching\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lower back\"],\"st\":[\"Stand with your feet wide apart.\",\"Reach one hand toward the opposite foot.\",\"Keep your other arm extended behind you.\",\"Rise and switch sides.\",\"Alternate at an easy pace.\"],\"img\":\"3250.webp\",\"gif\":\"3250.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing toe touch with a sideways reach to warm up the obliques and hamstrings.\"},{\"id\":\"2866\",\"n\":\"side twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Set up in a side support with one hand on the mat and your feet stacked.\",\"Lift your hips and reach your top arm to the ceiling.\",\"Thread the top arm under your body as you rotate your torso.\",\"Open back up and reach to the ceiling again.\",\"Keep your hips lifted throughout, then switch sides.\"],\"img\":\"2866.webp\",\"gif\":\"2866.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates twist from a side-supported position that trains the obliques and shoulder stability.\"},{\"id\":\"3251\",\"n\":\"side two front toe touching\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lower back\"],\"st\":[\"Stand with feet wide apart.\",\"Turn your torso slightly to one side.\",\"Reach both hands to the foot on that side.\",\"Rise, then turn to the other side.\",\"Repeat at a steady pace.\"],\"img\":\"3251.webp\",\"gif\":\"3251.mp4\",\"cat\":\"mobility\",\"desc\":\"A wide-stance toe touch reaching both hands toward one side to loosen the trunk and legs.\"},{\"id\":\"2561\",\"n\":\"side up jump top bench\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand beside a sturdy bench.\",\"Bend your knees and swing your arms back.\",\"Jump up and sideways onto the bench.\",\"Land softly with your knees bent.\",\"Step down carefully.\",\"Repeat, alternating sides.\"],\"img\":\"2561.webp\",\"gif\":\"2561.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side-on jump onto a bench that builds explosive leg power.\"},{\"id\":\"0722\",\"n\":\"sideway leg bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"obliques\",\"core\"],\"st\":[\"Lie on your back with knees bent.\",\"Lift your hips into a bridge.\",\"Step or shift your legs to one side.\",\"Return to the center.\",\"Alternate sides.\",\"Keep your hips lifted.\"],\"img\":\"0722.webp\",\"gif\":\"0722.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bridge with a sideways leg shift. It trains the glutes and hips.\"},{\"id\":\"0723\",\"n\":\"sideways lifts vertical (straight legs)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with legs straight up.\",\"Place your arms by your sides.\",\"Lift your hips off the floor.\",\"Tilt your legs slightly to one side.\",\"Lower with control.\",\"Alternate sides.\"],\"img\":\"0723.webp\",\"gif\":\"0723.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying down with legs straight and vertical, you lift your hips sideways. It targets the lower abs and obliques.\"},{\"id\":\"0724\",\"n\":\"sideways lifts vertical turn (straight legs)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with legs straight up.\",\"Press your arms into the floor.\",\"Lift your hips and rotate them to one side.\",\"Lower slowly.\",\"Repeat to the other side.\",\"Keep legs straight.\"],\"img\":\"0724.webp\",\"gif\":\"0724.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A leg-up hip lift with a rotation. It works the lower abs and obliques.\"},{\"id\":\"5039\",\"n\":\"silent burpee\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"chest\",\"core\"],\"st\":[\"Stand with feet shoulder width apart.\",\"Squat down and place your hands on the floor.\",\"Step your feet back into a plank.\",\"Step your feet forward to your hands.\",\"Stand up tall.\",\"Keep a steady pace for 30-60 seconds.\"],\"img\":\"5039.webp\",\"gif\":\"5039.mp4\",\"cat\":\"cardio\",\"desc\":\"A low-impact burpee without the jump. It raises your heart rate while staying quiet and gentle on the joints.\"},{\"id\":\"11791\",\"n\":\"single arm fingers press with ball\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"grip muscles\"],\"st\":[\"Hold a small ball in one palm.\",\"Press down on it with your fingers.\",\"Spread and squeeze with control, keeping your wrist neutral.\",\"Hold the press for 2-3 seconds.\",\"Repeat for reps, then switch hands.\"],\"img\":\"11791.webp\",\"gif\":\"11791.mp4\",\"cat\":\"strength\",\"desc\":\"A hand-strengthening drill pressing the fingers into a ball.\"},{\"id\":\"11794\",\"n\":\"single arm fingers press with ball v. 2\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"grip muscles\"],\"st\":[\"Place a ball under one hand on a table or hold it in your palm.\",\"Spread your fingers over the ball.\",\"Press down and hold for 2-3 seconds.\",\"Release with control.\",\"Repeat for reps, then switch hands.\"],\"img\":\"11794.webp\",\"gif\":\"11794.mp4\",\"cat\":\"strength\",\"desc\":\"A second version of the fingers-on-ball drill for forearm and hand strength.\"},{\"id\":\"11091\",\"n\":\"single arm hanging toes to bar\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"grip muscles\",\"obliques\"],\"st\":[\"Hang from a bar with one hand and keep your shoulder active.\",\"Brace your core and keep your legs together.\",\"Lift your toes up toward the bar.\",\"Lower your legs slowly without swinging.\",\"Finish your reps, then switch hands.\"],\"img\":\"11091.webp\",\"gif\":\"11091.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging core move done from one hand. Lifting your toes to the bar trains the abs and grip.\"},{\"id\":\"7623\",\"n\":\"single arm lat stretch against wall\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"obliques\",\"triceps\"],\"st\":[\"Stand beside a wall and place one hand on it above head height.\",\"Step your feet back slightly.\",\"Press your hips away and lean your chest down toward the floor.\",\"Feel the stretch along your side and under the armpit.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"7623.webp\",\"gif\":\"7623.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretch one side of your back by reaching an arm overhead against a wall. It lengthens the lat and side of the torso.\"},{\"id\":\"5096\",\"n\":\"single arm overhead dumbbell squat\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\",\"hamstrings\"],\"st\":[\"Press a dumbbell overhead with one arm and keep it locked out.\",\"Stand with feet shoulder-width apart.\",\"Sit your hips back and down into a squat.\",\"Keep your ribs down and the weight over your shoulder.\",\"Drive up to standing, then switch arms after your reps.\"],\"img\":\"5096.webp\",\"gif\":\"5096.mp4\",\"cat\":\"strength\",\"desc\":\"Squat while holding a dumbbell overhead with one arm. It builds leg strength and demands good shoulder and trunk control.\"},{\"id\":\"3002\",\"n\":\"single arm push up (on knees)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\",\"obliques\"],\"st\":[\"Kneel and place one hand under your shoulder, with the other arm behind your back.\",\"Spread your knees a bit wider for balance.\",\"Keep a straight line from your head to your knees.\",\"Lower your chest toward the floor with control.\",\"Press back up without twisting your hips.\",\"Switch arms and repeat.\"],\"img\":\"3002.webp\",\"gif\":\"3002.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-arm push-up from the knees, a stepping stone toward the full single-arm version. It builds chest and trunk strength.\"},{\"id\":\"4617\",\"n\":\"single arm push up (wall supported)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Stand facing a wall at arm's length and place one hand on it at chest height.\",\"Keep your other arm behind your back or at your side.\",\"Bend your elbow to lower your chest toward the wall, body in a straight line.\",\"Press back to the start.\",\"Finish your reps, then switch arms.\"],\"img\":\"4617.webp\",\"gif\":\"4617.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An easier one-arm push-up using a wall, building the strength and stability needed for the full floor version.\"},{\"id\":\"4121\",\"n\":\"single arm push up on medicine ball\",\"bp\":\"chest\",\"eq\":\"medicine ball\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Place one hand on the ball and the other on the floor in a plank.\",\"Spread your feet for balance.\",\"Lower your chest toward the ball.\",\"Press back up.\",\"Finish your reps, then switch hands.\"],\"img\":\"4121.webp\",\"gif\":\"4121.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hard push up with one hand on a medicine ball, challenging balance and chest strength.\"},{\"id\":\"2946\",\"n\":\"single arm scapula push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Start in a plank with one hand on the floor, the other behind your back or on your hip.\",\"Keep your elbow locked straight.\",\"Let your chest sink slightly between your shoulder blades.\",\"Push the floor away to round your upper back slightly.\",\"Finish the reps, then switch arms.\"],\"img\":\"2946.webp\",\"gif\":\"2946.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A small push-up movement with one arm that moves only the shoulder blades. It builds control of the serratus anterior.\"},{\"id\":\"5844\",\"n\":\"single arm side straight arm lat pulldown\",\"bp\":\"back\",\"eq\":\"cable\",\"tg\":\"lats\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"rear deltoids\"],\"st\":[\"Stand facing a high cable with one handle in your hand.\",\"Keep your arm nearly straight and slightly angled.\",\"Pull the handle down toward your thigh by squeezing your lat.\",\"Hold briefly.\",\"Let it rise slowly and switch sides after your set.\"],\"img\":\"5844.webp\",\"gif\":\"5844.mp4\",\"cat\":\"strength\",\"desc\":\"A straight-arm cable pulldown from the side, one arm at a time. It isolates the lats without bending the elbow much.\"},{\"id\":\"6318\",\"n\":\"single curtsy lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Step one leg diagonally behind the other.\",\"Bend both knees and lower your hips.\",\"Keep your chest up and front knee over your toes.\",\"Push up and return, then switch sides.\"],\"img\":\"6318.webp\",\"gif\":\"6318.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge stepping one leg back and across behind you. It targets the glutes and outer hips.\"},{\"id\":\"5237\",\"n\":\"single dumbbell decline overhead sit up\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"shoulders\"],\"st\":[\"Lie on a decline bench with your feet secured.\",\"Hold one dumbbell with both hands above your head.\",\"Curl up and sit forward, keeping the weight overhead.\",\"Pause at the top.\",\"Lower slowly to the start.\"],\"img\":\"5237.webp\",\"gif\":\"5237.mp4\",\"cat\":\"strength\",\"desc\":\"A decline sit-up holding one dumbbell overhead. The load adds resistance for the abs.\"},{\"id\":\"1886\",\"n\":\"single heel drop achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand on a step with the ball of one foot on the edge.\",\"Hold a rail for balance.\",\"Lower your heel slowly below the step.\",\"Keep the knee straight for the calf, then slightly bent for the soleus.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1886.webp\",\"gif\":\"1886.mp4\",\"cat\":\"stretching\",\"desc\":\"Lets one heel drop off a step to stretch the Achilles and calf.\"},{\"id\":\"1925\",\"n\":\"single heel drop calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand on the edge of a step with the ball of one foot on it and hold a rail for balance.\",\"Slowly lower that heel below the step until you feel the calf stretch.\",\"Keep the knee straight to hit the calf, then bend it slightly to reach deeper into the soleus.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1925.webp\",\"gif\":\"1925.mp4\",\"cat\":\"stretching\",\"desc\":\"Dropping one heel off a step to stretch the calf through a full range.\"},{\"id\":\"1955\",\"n\":\"single lean back quadriceps stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\"],\"st\":[\"Kneel on both knees, then lift one foot out in front so that the other leg is folded.\",\"Place your hands behind you on the floor.\",\"Lean back slowly until you feel a stretch in the front of the folded thigh.\",\"Keep your hips lifted and avoid sagging into the lower back.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1955.webp\",\"gif\":\"1955.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling with one leg folded and leaning back to stretch the quadriceps.\"},{\"id\":\"5975\",\"n\":\"single leg balance cross punch\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"calves\",\"shoulders\"],\"st\":[\"Stand on one leg with a slight knee bend and fists up.\",\"Brace your core.\",\"Throw a cross punch, rotating your hips and shoulders.\",\"Pull your fist back to guard.\",\"Keep your standing foot steady.\",\"Finish your reps, then switch legs.\"],\"img\":\"5975.webp\",\"gif\":\"5975.mp4\",\"cat\":\"combat\",\"desc\":\"Cross punches thrown while balancing on one leg, which trains balance, rotation and core control.\"},{\"id\":\"4790\",\"n\":\"single leg bench squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand in front of a bench with your back to it and lift one foot off the floor.\",\"Reach your arms forward for balance.\",\"Sit your hips back and lower until you lightly touch the bench.\",\"Keep the working knee in line with your toes.\",\"Drive through the heel to stand back up.\",\"Finish your reps, then switch legs.\"],\"img\":\"4790.webp\",\"gif\":\"4790.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged squat down to a bench behind you. It builds leg strength and balance while the bench keeps the depth safe.\"},{\"id\":\"4245\",\"n\":\"single leg board jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand on one leg next to or in front of a board.\",\"Bend slightly and swing your arms.\",\"Jump up and across or onto the board.\",\"Land softly on the same leg with a bent knee.\",\"Hold the landing for a second.\",\"Finish your reps and switch legs.\"],\"img\":\"4245.webp\",\"gif\":\"4245.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A one-leg jump over or onto a board to build power and landing control. It trains single-leg explosiveness.\"},{\"id\":\"2920\",\"n\":\"single leg bodyweight deadlift with arm and leg extended\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand on one leg with arms reaching forward.\",\"Soften your standing knee slightly.\",\"Hinge at the hips as your free leg lifts behind you.\",\"Keep your back flat and body in a long line.\",\"Return to standing and repeat, then switch legs.\"],\"img\":\"2920.webp\",\"gif\":\"2920.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg hinge with your arms extended that trains hamstrings, glutes and balance.\"},{\"id\":\"5166\",\"n\":\"single leg box jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand facing a sturdy box on one foot.\",\"Swing your arms and dip into a short quarter squat.\",\"Jump up and land softly on the box on the same foot.\",\"Stand tall, then step down carefully.\",\"Finish all reps, then switch legs.\"],\"img\":\"5166.webp\",\"gif\":\"5166.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A one-legged jump onto a box. It builds explosive power and single-leg control.\"},{\"id\":\"0726\",\"n\":\"single leg bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent.\",\"Extend one leg straight.\",\"Drive through the planted heel and lift your hips.\",\"Squeeze your glute at the top.\",\"Lower with control.\",\"Finish reps, then switch legs.\"],\"img\":\"0726.webp\",\"gif\":\"0726.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge on one leg. It builds glute strength and hip stability.\"},{\"id\":\"3583\",\"n\":\"single leg bridge with hip flexion\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Lift one knee toward your chest.\",\"Press through the other foot to raise your hips.\",\"Keep your hips level and avoid arching.\",\"Lower slowly and switch sides after the set.\"],\"img\":\"3583.webp\",\"gif\":\"3583.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged glute bridge with the other knee drawn up, building glute strength and pelvic control.\"},{\"id\":\"6000\",\"n\":\"single leg bridge with outstretched leg (left)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Extend your left leg straight out.\",\"Drive through your right heel to lift your hips.\",\"Keep your hips level.\",\"Pause at the top.\",\"Lower slowly, finish your reps and switch legs.\"],\"img\":\"6000.webp\",\"gif\":\"6000.mp4\",\"cat\":\"strength\",\"desc\":\"A bridge on one leg with the other leg stretched out, to strengthen the glutes and hamstrings and test hip stability.\"},{\"id\":\"1589\",\"n\":\"single leg butt kick\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Stand on one leg with the other foot lifted.\",\"Hop lightly on your standing foot.\",\"Kick your free heel toward your glutes each hop.\",\"Land softly on the ball of your foot.\",\"Complete your reps, then switch legs.\"],\"img\":\"1589.webp\",\"gif\":\"1589.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A hopping drill where you flick one heel up to your glutes. It warms up the hamstrings and raises your heart rate.\"},{\"id\":\"10754\",\"n\":\"single leg calf jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on one leg with a slight knee bend and arms relaxed.\",\"Push through the ball of your foot and jump up using mainly your ankles.\",\"Keep the knee nearly straight in the air.\",\"Land softly on the ball of the same foot.\",\"Rebound right away into the next hop.\",\"Complete your reps, then switch legs.\"],\"img\":\"10754.webp\",\"gif\":\"10754.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Hopping on one leg using mostly the ankles. It builds calf power and springy ankles.\"},{\"id\":\"10755\",\"n\":\"single leg calf jump step box supported\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand beside a step box and rest a hand lightly on it for balance.\",\"Lift one foot off the floor.\",\"Hop up using mostly your ankle and calf.\",\"Land softly on the ball of your foot.\",\"Keep the hops small and quick.\",\"Switch legs after your set.\"],\"img\":\"10755.webp\",\"gif\":\"10755.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A single-leg calf hop with a step box nearby for balance. It trains ankle power with extra stability.\"},{\"id\":\"5052\",\"n\":\"single leg calf raise off step\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on one foot on the edge of a step, holding a rail for balance.\",\"Let your heel lower below the step.\",\"Rise as high as possible on your toes.\",\"Pause briefly.\",\"Lower slowly, then switch legs.\"],\"img\":\"5052.webp\",\"gif\":\"5052.mp4\",\"cat\":\"calisthenics\",\"desc\":\"One-legged calf raise from the edge of a step. It builds calf strength with a deep stretch.\"},{\"id\":\"4931\",\"n\":\"single leg calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall with one foot back and heel on the floor.\",\"Place your hands on the wall.\",\"Lean forward with a straight back leg.\",\"Feel the stretch in the calf.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"4931.webp\",\"gif\":\"4931.mp4\",\"cat\":\"stretching\",\"desc\":\"A calf stretch done on one leg at a time. It lengthens the lower leg muscles.\"},{\"id\":\"3585\",\"n\":\"single leg deadlift with knee lift\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"hip flexors\"],\"st\":[\"Stand on one leg with a slight knee bend.\",\"Hinge forward as the other leg extends behind you.\",\"Return to upright by squeezing the glute.\",\"Drive the free knee up toward your chest.\",\"Finish the reps, then switch legs.\"],\"img\":\"3585.webp\",\"gif\":\"3585.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip hinge that ends with a knee drive, training balance, hamstrings and glutes.\"},{\"id\":\"4364\",\"n\":\"single leg dip on floor\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"glutes\"],\"st\":[\"Sit on the floor with hands behind you and knees bent.\",\"Lift your hips and extend one leg out.\",\"Bend your elbows to lower.\",\"Press back up.\",\"Switch legs after your reps.\"],\"img\":\"4364.webp\",\"gif\":\"4364.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor dip with one leg raised for extra challenge. It targets the triceps and core balance.\"},{\"id\":\"0728\",\"n\":\"single leg extension (on stability ball)\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"glutes\"],\"st\":[\"Sit on a stability ball with your feet flat.\",\"Keep your torso tall.\",\"Extend one leg until it is straight.\",\"Hold briefly.\",\"Lower the foot back down.\",\"Finish reps, then switch legs.\"],\"img\":\"0728.webp\",\"gif\":\"0728.mp4\",\"cat\":\"strength\",\"desc\":\"Balancing on a stability ball, you extend one leg at a time. It works the quads and balance.\"},{\"id\":\"1702\",\"n\":\"single leg foot touch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\",\"ankles\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Hinge at the hips and reach down toward your foot or the floor.\",\"Keep your back flat and your free leg extended behind you.\",\"Return to standing by squeezing your glute.\",\"Finish all reps, then switch legs.\"],\"img\":\"1702.webp\",\"gif\":\"1702.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg balance drill where you reach down to touch the floor or foot, training hip control and stability.\"},{\"id\":\"4791\",\"n\":\"single leg glute bridge (arms on chest)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with one knee bent, foot flat, and the other leg extended or raised.\",\"Cross your arms over your chest.\",\"Push through the planted heel and lift your hips.\",\"Squeeze the glute at the top so your body forms a straight line.\",\"Lower your hips slowly without touching the floor fully.\",\"Complete your reps, then switch legs.\"],\"img\":\"4791.webp\",\"gif\":\"4791.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged glute bridge with arms crossed on the chest. It focuses the work on the glutes and tests hip stability.\"},{\"id\":\"5167\",\"n\":\"single leg glute bridge with external rotation\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with one knee bent and the other leg lifted.\",\"Press through your planted heel and raise your hips.\",\"Turn the raised knee gently outward as you hold the top.\",\"Keep your hips level and squeeze your glutes.\",\"Lower with control, finish your reps, then switch sides.\"],\"img\":\"5167.webp\",\"gif\":\"5167.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged glute bridge with the hip turned outward. It targets the glutes and the small hip stabilisers.\"},{\"id\":\"4044\",\"n\":\"single leg glute bridge with knee to chest\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with one knee bent and the foot flat, the other knee pulled toward your chest.\",\"Brace your core.\",\"Push through the planted heel and lift your hips.\",\"Squeeze your glute at the top.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"4044.webp\",\"gif\":\"4044.mp4\",\"cat\":\"calisthenics\",\"desc\":\"One leg glute bridge where the free knee is hugged toward the chest. It strengthens the glutes and challenges hip stability.\"},{\"id\":\"9359\",\"n\":\"single leg hamstring bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one foot flat and the other leg raised.\",\"Press your heel into the floor.\",\"Lift your hips until your body forms a line.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\",\"Finish the reps, then switch legs.\"],\"img\":\"9359.webp\",\"gif\":\"9359.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged bridge with your heel planted that works the hamstrings and glutes.\"},{\"id\":\"3494\",\"n\":\"single leg heel touch squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand on one leg with the other foot slightly off the floor.\",\"Sit your hips back and bend the knee to squat down.\",\"Reach down toward the heel of your standing foot.\",\"Keep your chest as tall as you can.\",\"Push through your foot to rise.\",\"Complete your reps, then switch legs.\"],\"img\":\"3494.webp\",\"gif\":\"3494.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat where you reach down to touch the heel of the working foot. It challenges balance and leg strength.\"},{\"id\":\"3435\",\"n\":\"single leg hip bridge (straight leg)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with one knee bent and foot flat.\",\"Extend the other leg straight.\",\"Drive through your heel and lift your hips.\",\"Keep your pelvis level.\",\"Lower with control.\",\"Switch legs after your set.\"],\"img\":\"3435.webp\",\"gif\":\"3435.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg hip bridge with the other leg held straight, strongly working glutes and hamstrings.\",\"fv\":\"0729\"},{\"id\":\"4793\",\"n\":\"single leg hip thrust jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Sit with your upper back on a bench and one foot planted.\",\"Lift the other leg.\",\"Drive up through your heel and thrust your hips explosively.\",\"Let your hips leave the floor briefly.\",\"Land softly, finish the reps, then switch legs.\"],\"img\":\"4793.webp\",\"gif\":\"4793.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive one-leg hip thrust where you jump your hips off the floor. It trains glute power.\"},{\"id\":\"4792\",\"n\":\"single leg hip thrust v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Rest your upper back on a bench with one foot flat on the floor.\",\"Lift the other leg off the floor, knee bent or straight.\",\"Drive through the planted heel and raise your hips.\",\"Squeeze your glute at the top until your torso is level.\",\"Lower your hips under control.\",\"Finish your reps, then switch legs.\"],\"img\":\"4792.webp\",\"gif\":\"4792.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged hip thrust with your upper back on a bench, a second variation. It hits the glutes hard without any equipment.\"},{\"id\":\"2071\",\"n\":\"single leg hip thrusts\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Sit with your upper back against a bench and one foot flat on the floor.\",\"Extend the other leg or hold it up.\",\"Drive through the heel to lift your hips until your body is flat.\",\"Squeeze your glute at the top, then lower under control.\",\"Complete the reps, then switch legs.\"],\"img\":\"2071.webp\",\"gif\":\"2071.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg hip thrust that works the glutes hard and challenges balance and hip stability.\"},{\"id\":\"5482\",\"n\":\"single leg hopping\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"hamstrings\",\"ankles\"],\"st\":[\"Stand on one leg with a slight knee bend and arms ready.\",\"Hop up and forward or in place using your ankle and knee.\",\"Land softly on the ball of the same foot.\",\"Stay balanced and keep your hips level.\",\"Complete your reps, then switch legs.\"],\"img\":\"5482.webp\",\"gif\":\"5482.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Low-impact hopping on one leg to build ankle stiffness, balance and leg power.\"},{\"id\":\"4794\",\"n\":\"single leg jumping glute bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\",\"core\"],\"st\":[\"Lie on your back with one foot planted and the other leg lifted.\",\"Drive through the planted heel and thrust your hips up.\",\"Push hard enough that your hips leave the floor.\",\"Land softly back in the bridge.\",\"Finish the reps, then switch legs.\"],\"img\":\"4794.webp\",\"gif\":\"4794.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive one-leg glute bridge where you pop your hips off the floor. It builds glute power and balance.\"},{\"id\":\"7455\",\"n\":\"single leg lateral hop\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"ankles\"],\"st\":[\"Stand on one leg with a slight knee bend.\",\"Hop sideways a short distance.\",\"Land softly on the same foot and hold your balance.\",\"Hop back the other way.\",\"Complete reps, then switch legs.\"],\"img\":\"7455.webp\",\"gif\":\"7455.mp4\",\"cat\":\"plyometrics\",\"desc\":\"One-legged sideways hop that builds power and ankle stability.\"},{\"id\":\"3493\",\"n\":\"single leg low box squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand in front of a low box or bench on one leg.\",\"Extend the other leg forward and raise your arms for balance.\",\"Sit your hips back and lower until you lightly touch the box.\",\"Keep your chest up and knee tracking over your toes.\",\"Drive through the heel to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"3493.webp\",\"gif\":\"3493.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg squat down to a low box, giving you a target depth. It builds single-leg strength and balance.\"},{\"id\":\"11647\",\"n\":\"single leg pogo jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"quadriceps\",\"feet\"],\"st\":[\"Stand on one leg with a soft knee and your arms relaxed at your sides.\",\"Hop straight up by pushing through the ball of your foot, keeping the knee almost straight.\",\"Land softly on the ball of the same foot and rebound right away.\",\"Keep your hops small and quick, with your hips level and your core tight.\",\"Hop for the planned time or reps, then switch legs.\"],\"img\":\"11647.webp\",\"gif\":\"11647.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Small, springy hops on one leg that build calf and ankle stiffness, elasticity and balance.\"},{\"id\":\"1591\",\"n\":\"single leg push off\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand in front of a low step with one foot planted on it.\",\"Lean slightly forward and keep your core tight.\",\"Push off the step explosively with that leg and drive your opposite knee up.\",\"Land softly on the same foot.\",\"Complete your reps, then switch legs.\"],\"img\":\"1591.webp\",\"gif\":\"1591.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive single-leg push off the floor or a step. It builds leg drive useful for running and jumping.\"},{\"id\":\"0731\",\"n\":\"single leg sit (wall)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Lean your back against a wall and slide down into a wall sit.\",\"Shift your weight onto one foot.\",\"Lift the other leg and extend it in front of you.\",\"Hold for 10-30 seconds while keeping your back flat on the wall.\",\"Lower the leg and rest, then switch sides.\",\"Keep your standing knee over your ankle.\"],\"img\":\"0731.webp\",\"gif\":\"0731.mp4\",\"cat\":\"isometric\",\"desc\":\"A one-legged wall sit that doubles the load on each leg and challenges balance and quad endurance.\",\"hd\":1},{\"id\":\"3514\",\"n\":\"single leg sliding floor bridge curl on towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with one heel on a towel on a smooth floor.\",\"Lift the other leg straight up.\",\"Raise your hips into a bridge.\",\"Slide your heel away until the leg is nearly straight.\",\"Pull the heel back toward your glutes.\",\"Complete your reps, then switch legs.\"],\"img\":\"3514.webp\",\"gif\":\"3514.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg bridge curl with the heel on a towel. It's a tougher hamstring and glute exercise.\"},{\"id\":\"2375\",\"n\":\"single leg squat with support\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand next to a sturdy support and hold it lightly with one hand.\",\"Lift one foot slightly off the floor in front of you.\",\"Sit your hips back and lower on the standing leg.\",\"Keep your knee tracking over your toes.\",\"Push through your heel to stand back up.\",\"Finish your reps, then switch legs.\"],\"img\":\"2375.webp\",\"gif\":\"2375.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-leg squat using a support for balance, building strength in each leg.\"},{\"id\":\"1762\",\"n\":\"single leg squat with support (pistol)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand next to a sturdy support and hold it with one or both hands.\",\"Lift one leg out in front of you and balance on the other.\",\"Sit your hips back and bend your knee, lowering as far as you can control.\",\"Keep your heel down and your knee tracking over your toes.\",\"Press through your foot to stand, using the support only as needed, then switch legs.\"],\"img\":\"1762.webp\",\"gif\":\"1762.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pistol squat where you hold onto a support to help with balance. It builds single-leg strength and control on the way to an unassisted pistol.\"},{\"id\":\"3714\",\"n\":\"single leg stand\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"core\",\"calves\"],\"st\":[\"Stand tall with your feet together.\",\"Lift one foot off the floor and bend the knee slightly.\",\"Keep your hips level and eyes on a fixed point.\",\"Hold for 20 to 30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"3714.webp\",\"gif\":\"3714.mp4\",\"cat\":\"isometric\",\"desc\":\"A simple balance hold on one leg that trains stability in the ankle, hip and core.\",\"hd\":1},{\"id\":\"3715\",\"n\":\"single leg stand on bosu ball\",\"bp\":\"upper legs\",\"eq\":\"bosu ball\",\"tg\":\"glutes\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"core\",\"calves\"],\"st\":[\"Place a bosu ball dome-up in front of you.\",\"Step onto it with one foot near the center.\",\"Lift your other foot and hold it off the ground.\",\"Keep your hips level and your core tight.\",\"Hold for 20 to 30 seconds, then switch legs.\"],\"img\":\"3715.webp\",\"gif\":\"3715.mp4\",\"cat\":\"isometric\",\"desc\":\"A balance hold on one leg on an unstable bosu ball. It challenges the ankle and hip stabilisers.\",\"hd\":1},{\"id\":\"0733\",\"n\":\"single leg step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in front of a sturdy step.\",\"Place one foot fully on the step.\",\"Press through that heel and stand up.\",\"Bring the other foot up to the step.\",\"Lower slowly.\",\"Finish reps, then switch legs.\"],\"img\":\"0733.webp\",\"gif\":\"0733.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-up on a box or bench using one leg. It builds the legs and balance.\"},{\"id\":\"4795\",\"n\":\"single leg step up on bench\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a sturdy bench and place one foot fully on top.\",\"Lean slightly forward and press through that heel.\",\"Step up until the leg is straight and you stand tall.\",\"Lower yourself slowly back down with control.\",\"Avoid pushing off the trailing foot.\",\"Complete your reps, then switch legs.\"],\"img\":\"4795.webp\",\"gif\":\"4795.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-up onto a bench using one leg at a time. It builds strength in the thighs and glutes and helps balance.\"},{\"id\":\"3711\",\"n\":\"single leg step up v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a sturdy box or bench.\",\"Place one foot fully on it.\",\"Drive through that heel to stand tall on the box.\",\"Lower slowly back down.\",\"Finish your reps, then switch legs.\"],\"img\":\"3711.webp\",\"gif\":\"3711.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Step up onto a box or bench with one leg to build single-leg strength.\"},{\"id\":\"4309\",\"n\":\"single leg stretch (bent knee)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"quadriceps\"],\"st\":[\"Lie on your back, lift your head and shoulders, and bring both knees toward your chest.\",\"Place your hands on one shin and extend the other leg out low.\",\"Switch legs smoothly, drawing the other knee in.\",\"Keep your lower back pressed down and your abs tight.\",\"Continue alternating with a steady breath rhythm.\"],\"img\":\"4309.webp\",\"gif\":\"4309.mp4\",\"cat\":\"pilates\",\"desc\":\"A pilates move where you alternate pulling one knee in while the other leg extends. It builds core control and coordination.\"},{\"id\":\"2872\",\"n\":\"single leg stretch (bent knee) v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"obliques\"],\"st\":[\"Lie on your back and curl your head and shoulders off the mat.\",\"Pull one knee toward your chest, with hands on that shin.\",\"Extend the other leg long at a low angle.\",\"Switch legs in a steady rhythm.\",\"Keep your lower back anchored to the mat.\"],\"img\":\"2872.webp\",\"gif\":\"2872.mp4\",\"cat\":\"pilates\",\"desc\":\"A Pilates ab move with alternating knee pulls that builds core endurance and coordination.\"},{\"id\":\"1592\",\"n\":\"single leg stride jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand on one leg with a slight knee bend.\",\"Push off and leap forward as far as you can.\",\"Land on the opposite leg and absorb the impact with a soft knee.\",\"Hold the landing for a moment to stay balanced.\",\"Repeat, alternating legs or staying on one side.\"],\"img\":\"1592.webp\",\"gif\":\"1592.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A bounding jump from one leg to the other leg. It develops power and single-leg control.\"},{\"id\":\"5774\",\"n\":\"single leg thrusts\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Rest your upper back on a bench with one foot flat and the other leg lifted.\",\"Keep your arms out for balance.\",\"Drive through your heel to lift your hips until level.\",\"Squeeze your glute at the top.\",\"Lower with control and switch legs after your reps.\"],\"img\":\"5774.webp\",\"gif\":\"5774.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hip thrusts done on one leg with your upper back on a support. Builds glute strength and hip stability.\"},{\"id\":\"1703\",\"n\":\"single leg transverse bend\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\",\"ankles\"],\"st\":[\"Stand on one leg with a soft knee.\",\"Hinge forward at the hips and reach across your body.\",\"Rotate your torso slightly as you reach.\",\"Return to standing with control.\",\"Complete the reps, then switch legs.\"],\"img\":\"1703.webp\",\"gif\":\"1703.mp4\",\"cat\":\"mobility\",\"desc\":\"A single-leg bend with a twist that trains balance and mobility through the hips and torso.\"},{\"id\":\"4254\",\"n\":\"single leg vertical jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand on one leg with a slight knee bend.\",\"Swing your arms back.\",\"Jump straight up as high as you can.\",\"Land softly on the same leg.\",\"Reset your balance.\",\"Finish your reps and switch legs.\"],\"img\":\"4254.webp\",\"gif\":\"4254.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A vertical jump from one leg to build explosive power and balance. Each side gets its own work.\"},{\"id\":\"5198\",\"n\":\"single straight leg glute bridge hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with knees bent.\",\"Straighten one leg.\",\"Lift your hips with the planted foot.\",\"Hold with hips level.\",\"Hold for 20-30 seconds.\",\"Lower and switch legs.\"],\"img\":\"5198.webp\",\"gif\":\"5198.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding a glute bridge with one leg straight. It trains the glutes and challenges hip stability.\",\"hd\":1},{\"id\":\"6001\",\"n\":\"single straight leg glute bridge hold (left)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back with both knees bent.\",\"Straighten your left leg in line with your torso.\",\"Press through the right heel to lift your hips.\",\"Hold for 20-30 seconds with your hips level.\",\"Lower slowly.\"],\"img\":\"6001.webp\",\"gif\":\"6001.mp4\",\"cat\":\"isometric\",\"desc\":\"A glute bridge held with the left leg extended straight. Builds one-sided glute strength and pelvic control.\",\"hd\":1},{\"id\":\"4310\",\"n\":\"single straight leg stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"obliques\"],\"st\":[\"Lie on your back, lift your head and shoulders off the mat.\",\"Extend one leg straight up and the other hovering low.\",\"Hold the raised leg with both hands and pulse twice toward you.\",\"Switch legs and repeat, keeping your torso steady.\",\"Keep your lower back anchored throughout.\"],\"img\":\"4310.webp\",\"gif\":\"4310.mp4\",\"cat\":\"pilates\",\"desc\":\"A pilates exercise where you scissor your straight legs while holding the raised one. It trains the abs and tests hamstring flexibility.\",\"fv\":\"2867\"},{\"id\":\"0734\",\"n\":\"sit (wall)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your back against a wall and walk your feet forward.\",\"Slide down until your knees are bent to about 90 degrees.\",\"Keep your back flat against the wall and your weight on your heels.\",\"Hold the position while breathing steadily.\",\"Hold for 20-60 seconds, then slide back up the wall to finish.\"],\"img\":\"0734.webp\",\"gif\":\"0734.mp4\",\"cat\":\"isometric\",\"desc\":\"The wall sit, a hold that builds endurance in the thighs without any equipment.\",\"hd\":1,\"fv\":\"6696\"},{\"id\":\"1593\",\"n\":\"sit squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Stand in front of a chair or bench with feet shoulder-width apart.\",\"Push your hips back and lower yourself toward the seat.\",\"Lightly touch the seat without relaxing completely.\",\"Keep your chest up and your knees over your toes.\",\"Press through your heels to stand back up.\"],\"img\":\"1593.webp\",\"gif\":\"1593.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat down to a seat and back up. The chair gives you a depth target and builds confidence.\"},{\"id\":\"0736\",\"n\":\"sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Cross your arms over your chest or rest your fingertips by your head.\",\"Curl your torso up until your chest nears your thighs.\",\"Lower slowly back to the floor with control.\",\"Avoid yanking on your neck; lead with your chest.\"],\"img\":\"0736.webp\",\"gif\":\"0736.mp4\",\"cat\":\"calisthenics\",\"desc\":\"The classic sit up, curling your torso from the floor to upright. It builds strength in the abs and hip flexors.\"},{\"id\":\"3389\",\"n\":\"sit up with chair assisted\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back and rest your lower legs on a chair seat, knees bent.\",\"Cross your arms over your chest or place your hands by your ears.\",\"Curl your torso up toward your knees.\",\"Pause briefly at the top.\",\"Lower back down slowly.\",\"Do not pull on your neck.\"],\"img\":\"3389.webp\",\"gif\":\"3389.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up with your feet or legs supported on a chair to focus on the abs.\"},{\"id\":\"8202\",\"n\":\"sitting alternate abduction twist on a chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Sit tall near the edge of a chair.\",\"Lift one leg and open it out to the side.\",\"Twist your torso toward that leg.\",\"Return to centre.\",\"Alternate sides.\"],\"img\":\"8202.webp\",\"gif\":\"8202.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated move combining a leg out to the side with a twist. It gently works the hips and waist.\"},{\"id\":\"7693\",\"n\":\"sitting alternate knee to elbow twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Sit tall on the floor, leaning back slightly with your hands behind your head.\",\"Lift your feet off the floor.\",\"Twist and bring one elbow toward the opposite knee.\",\"Return to centre and repeat on the other side.\",\"Alternate sides at a steady pace.\"],\"img\":\"7693.webp\",\"gif\":\"7693.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a seated position, twist to bring an elbow toward the opposite knee. It works the abs and obliques.\"},{\"id\":\"1805\",\"n\":\"sitting bent over back stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hamstrings\",\"upper back\"],\"st\":[\"Sit on a bench or chair with your feet flat and your knees apart.\",\"Bend forward from your hips and let your head and arms hang between your knees.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1805.webp\",\"gif\":\"1805.mp4\",\"cat\":\"stretching\",\"desc\":\"Sitting and bending over lets your upper body hang to stretch your whole back. A relaxed stretch to release tension.\",\"fv\":\"4311\"},{\"id\":\"11095\",\"n\":\"sitting cat cow stretch on a chair\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"lower back\"],\"st\":[\"Sit tall on a chair with your hands on your knees and feet flat.\",\"Inhale, arch your back and lift your chest.\",\"Exhale, round your spine and tuck your chin.\",\"Move slowly between the two positions.\",\"Repeat for 8-10 breaths.\"],\"img\":\"11095.webp\",\"gif\":\"11095.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle spinal stretch you can do on a chair. It moves your back through flexion and extension to ease stiffness.\"},{\"id\":\"1807\",\"n\":\"sitting cross legged reach forward stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"hip flexors\"],\"st\":[\"Sit on the floor with your legs crossed and your back tall.\",\"Walk your hands forward along the floor and fold from your hips until you feel a stretch.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1807.webp\",\"gif\":\"1807.mp4\",\"cat\":\"stretching\",\"desc\":\"Sitting cross-legged and reaching forward opens your lower back and hips. It is a calm stretch that suits cooldowns.\"},{\"id\":\"1809\",\"n\":\"sitting feet together reach forward stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"adductors\",\"groin\"],\"st\":[\"Sit on the floor with the soles of your feet together and your knees falling out.\",\"Hold your feet and fold forward from your hips, keeping your spine long.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1809.webp\",\"gif\":\"1809.mp4\",\"cat\":\"stretching\",\"desc\":\"Sitting with your soles together and reaching forward stretches your back and inner thighs. A gentle hip and back opener.\"},{\"id\":\"9487\",\"n\":\"sitting floor leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Sit on the floor with your hands planted behind your hips and legs extended.\",\"Lean back slightly and brace your abs.\",\"Raise both legs together a short way off the floor.\",\"Lower them slowly without letting your heels drop to the ground.\",\"Repeat for the planned reps.\"],\"img\":\"9487.webp\",\"gif\":\"9487.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a seated position with hands behind you, you lift your legs to train the lower abs and hip flexors.\"},{\"id\":\"9272\",\"n\":\"sitting floor tibialis raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Sit on the floor with your legs straight and your hands behind you.\",\"Keep your heels on the floor.\",\"Pull your toes up toward your shins.\",\"Hold for a moment.\",\"Lower the toes slowly.\",\"Repeat for the set.\"],\"img\":\"9272.webp\",\"gif\":\"9272.mp4\",\"cat\":\"mobility\",\"desc\":\"Sitting on the floor, you pull your toes toward your shins to work the muscles at the front of the lower leg.\"},{\"id\":\"1940\",\"n\":\"sitting foot to chest buttocks stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hamstrings\"],\"st\":[\"Sit on the floor with your back tall and legs extended.\",\"Bend one knee and hold the foot and shin.\",\"Pull the foot gently toward your chest while keeping your spine upright.\",\"Feel the stretch deep in the buttock and hip.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1940.webp\",\"gif\":\"1940.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch pulling the foot toward the chest to open the hips and buttocks.\"},{\"id\":\"10139\",\"n\":\"sitting isometric hamstring curl hold with exercise ball\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Sit on the floor with legs out and the ball under your heels.\",\"Lean back on your hands.\",\"Press your heels into the ball and slide it in until knees bend.\",\"Hold the position steadily.\",\"Slowly extend your legs again.\"],\"img\":\"10139.webp\",\"gif\":\"10139.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a ball under your heels in a curled position. It builds endurance in the back of the thighs.\",\"hd\":1},{\"id\":\"2118\",\"n\":\"sitting lateral side stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Sit tall with your legs crossed or feet flat on the floor.\",\"Reach one arm overhead and lean sideways away from it, placing the other hand on the floor for support.\",\"Keep both sit bones grounded.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2118.webp\",\"gif\":\"2118.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated side bend that stretches the sides of the waist and the lats.\"},{\"id\":\"1803\",\"n\":\"sitting lower trunk extensor stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"hamstrings\"],\"st\":[\"Sit on the floor or a bench with your knees slightly bent and your feet flat.\",\"Round your back and fold your chest toward your thighs, letting your arms hang down.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1803.webp\",\"gif\":\"1803.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated and folding forward, you stretch the muscles along your lower back. A gentle way to ease lower back tightness.\"},{\"id\":\"1835\",\"n\":\"sitting neck flexion stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Sit tall on a chair with your hands resting in your lap.\",\"Slowly lower your chin toward your chest.\",\"Let the weight of your head do the work, without forcing it.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Lift your head back to neutral slowly.\"],\"img\":\"1835.webp\",\"gif\":\"1835.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated chin-to-chest stretch for the muscles along the back of the neck.\"},{\"id\":\"1951\",\"n\":\"sitting one leg external stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\"],\"st\":[\"Sit on the floor and bend one leg so the foot rests against the opposite thigh.\",\"Lean your chest forward over the bent leg while pressing the knee toward the floor until the hip stretches.\",\"Keep your back long.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1951.webp\",\"gif\":\"1951.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that opens one hip by turning the leg outward.\"},{\"id\":\"8200\",\"n\":\"sitting prayer chest squeeze on a chair\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Sit tall on a chair.\",\"Bring your palms together in front of your chest.\",\"Press your palms firmly into each other.\",\"Hold for 10-15 seconds.\",\"Release and repeat.\"],\"img\":\"8200.webp\",\"gif\":\"8200.mp4\",\"cat\":\"isometric\",\"desc\":\"Seated, you press your palms together in front of your chest. It trains the chest with no equipment.\",\"hd\":1},{\"id\":\"1948\",\"n\":\"sitting rotational hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Sit on the floor with your knees bent and both feet flat.\",\"Let both knees drop to one side and rotate your torso the opposite way until you feel the hip stretch.\",\"Keep your hands behind you for support.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1948.webp\",\"gif\":\"1948.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated rotation that works the hip through a twisting stretch.\"},{\"id\":\"8203\",\"n\":\"sitting russian twist on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Sit near the edge of a chair and lean back slightly.\",\"Clasp your hands in front of your chest.\",\"Rotate your torso to one side.\",\"Return to centre and rotate to the other side.\",\"Keep your chest tall.\"],\"img\":\"8203.webp\",\"gif\":\"8203.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A Russian twist done seated on a chair. It works the obliques with low impact.\"},{\"id\":\"6913\",\"n\":\"sitting scapular adduction\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Sit tall with arms relaxed at your sides or held in front.\",\"Keep your neck relaxed.\",\"Pull your shoulder blades together and slightly down.\",\"Hold the squeeze for 2-3 seconds.\",\"Release slowly and repeat.\"],\"img\":\"6913.webp\",\"gif\":\"6913.mp4\",\"cat\":\"strength\",\"desc\":\"A seated drill squeezing the shoulder blades together. It strengthens the muscles that support good posture.\",\"fv\":\"6614\"},{\"id\":\"6914\",\"n\":\"sitting scapular adduction v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Sit tall with elbows bent and hands by your ribs.\",\"Keep your neck relaxed.\",\"Draw your elbows back and pinch your shoulder blades together.\",\"Hold for 2-3 seconds.\",\"Return slowly and repeat.\"],\"img\":\"6914.webp\",\"gif\":\"6914.mp4\",\"cat\":\"strength\",\"desc\":\"A variation of the seated shoulder blade squeeze with the arms held out. It strengthens the upper back and posture muscles.\",\"fv\":\"6615\"},{\"id\":\"1972\",\"n\":\"sitting shoulders stretch on bench\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\"],\"st\":[\"Sit on the edge of a bench and place your hands behind you on it, fingers pointing back.\",\"Walk your hips slightly forward off the bench.\",\"Lower your hips gently until you feel a stretch at the front of the shoulders.\",\"Keep your back close to the bench and shoulders down.\",\"Hold for 20-30 seconds, then rise up.\"],\"img\":\"1972.webp\",\"gif\":\"1972.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated stretch that opens the front of the shoulders using a bench.\"},{\"id\":\"8195\",\"n\":\"sitting side bend on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Sit tall on a chair with feet flat.\",\"Place one hand behind your head.\",\"Bend sideways toward the floor.\",\"Return to upright using your side muscles.\",\"Repeat on the other side.\"],\"img\":\"8195.webp\",\"gif\":\"8195.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle seated side bend that works the obliques and loosens the sides. Easy to do at a desk.\",\"fv\":\"9161\"},{\"id\":\"1806\",\"n\":\"sitting side reach stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\",\"shoulders\"],\"st\":[\"Sit tall with your legs crossed or your feet flat and place one hand on the floor beside you.\",\"Reach your other arm up and over your head toward the side, lengthening along your flank.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1806.webp\",\"gif\":\"1806.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated, reaching over to the side stretches your lats and obliques. It is easy on the hips and good for desk breaks.\"},{\"id\":\"3633\",\"n\":\"sitting sumo left twist stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lower back\"],\"st\":[\"Sit with legs spread wide and back tall.\",\"Rotate your torso to the left.\",\"Reach both hands toward your left foot.\",\"Keep your hips grounded.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Release slowly and repeat on the other side if needed.\"],\"img\":\"3633.webp\",\"gif\":\"3633.mp4\",\"cat\":\"stretching\",\"desc\":\"From a wide seated position, twist toward the left leg to stretch the inner thigh and torso.\"},{\"id\":\"3631\",\"n\":\"sitting sumo mobility stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"hamstrings\",\"lower back\"],\"st\":[\"Sit on the floor with legs spread wide.\",\"Keep your back straight and toes pointing up.\",\"Lean forward from the hips.\",\"Place your hands on the floor in front of you.\",\"Stay for 20-30 seconds, then return slowly.\"],\"img\":\"3631.webp\",\"gif\":\"3631.mp4\",\"cat\":\"mobility\",\"desc\":\"Sit with legs wide and lean forward to open the inner thighs and hips.\"},{\"id\":\"3632\",\"n\":\"sitting sumo right twist stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lower back\"],\"st\":[\"Sit with legs spread wide and back tall.\",\"Rotate your torso to the right.\",\"Reach both hands toward your right foot.\",\"Keep your hips grounded.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Release slowly and repeat on the other side if needed.\"],\"img\":\"3632.webp\",\"gif\":\"3632.mp4\",\"cat\":\"stretching\",\"desc\":\"From a wide seated position, twist toward the right leg to stretch the inner thigh and torso.\"},{\"id\":\"3634\",\"n\":\"sitting sumo with arms up mobility stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"groin\",\"lower back\"],\"st\":[\"Sit with legs spread wide and back straight.\",\"Raise both arms overhead.\",\"Lean forward slowly from the hips.\",\"Keep your arms extended and your chest open.\",\"Hold for 20-30 seconds, then sit tall.\"],\"img\":\"3634.webp\",\"gif\":\"3634.mp4\",\"cat\":\"mobility\",\"desc\":\"A wide seated stretch with arms overhead to open the hips, inner thighs and shoulders.\"},{\"id\":\"8197\",\"n\":\"sitting swimmer on a chair\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"shoulders\"],\"st\":[\"Sit upright near the edge of a chair.\",\"Lean forward slightly with a flat back.\",\"Reach one arm forward and the other back, then alternate.\",\"Move in a steady rhythm.\",\"Keep your core braced.\"],\"img\":\"8197.webp\",\"gif\":\"8197.mp4\",\"cat\":\"mobility\",\"desc\":\"A seated move where your arms alternate in a swimming motion. A gentle shoulder warm-up for any time.\"},{\"id\":\"1889\",\"n\":\"sitting toe pull achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"shins\"],\"st\":[\"Sit on the floor with one leg straight.\",\"Loop a towel around the ball of your foot or grip your toes.\",\"Pull your toes toward your shin.\",\"Keep your knee straight.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1889.webp\",\"gif\":\"1889.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated stretch where you pull the toes toward you.\"},{\"id\":\"2102\",\"n\":\"sitting toe pull calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"shins\",\"feet\"],\"st\":[\"Sit on the floor with one leg straight out in front of you.\",\"Reach forward and grab the toes or the ball of the foot of that leg.\",\"Gently pull the toes toward your shin while keeping the knee straight.\",\"Sit tall and avoid rounding your back.\",\"Hold for 20-30 seconds.\",\"Release and switch legs.\"],\"img\":\"2102.webp\",\"gif\":\"2102.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulls the toes back toward the shin while sitting, giving the calf and the back of the lower leg a gentle stretch.\"},{\"id\":\"7263\",\"n\":\"sitting uppercut on chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Sit tall on the edge of a chair with your fists up by your chin.\",\"Brace your core.\",\"Rotate your torso and punch one fist upward in an uppercut.\",\"Snap it back and punch with the other hand.\",\"Keep a quick, steady rhythm for the set.\"],\"img\":\"7263.webp\",\"gif\":\"7263.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Seated punching move that fires the abs and shoulders with quick uppercut punches.\"},{\"id\":\"1902\",\"n\":\"sitting wide leg adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\",\"hamstrings\"],\"st\":[\"Sit on the floor with your legs spread wide.\",\"Keep your knees pointing up.\",\"Hinge forward from the hips with a long spine.\",\"Walk your hands forward until you feel the stretch.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Come up slowly.\"],\"img\":\"1902.webp\",\"gif\":\"1902.mp4\",\"cat\":\"stretching\",\"desc\":\"Seated straddle that stretches the inner thighs.\"},{\"id\":\"8199\",\"n\":\"sitting woodchopper on a chair\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Sit tall on a chair and clasp your hands together.\",\"Raise your arms diagonally up to one side.\",\"Chop down across your body to the opposite knee.\",\"Rotate through your torso.\",\"Alternate sides at an easy pace.\"],\"img\":\"8199.webp\",\"gif\":\"8199.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A seated woodchop with the hands clasped. It works the obliques with no equipment.\"},{\"id\":\"9025\",\"n\":\"sitting woodchopper on stability ball\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"shoulders\"],\"st\":[\"Sit tall on the ball with your feet wide.\",\"Hold the weight or handle high on one side.\",\"Rotate and chop diagonally down to the opposite hip.\",\"Keep your arms mostly straight and your hips steady.\",\"Return along the same path.\",\"Complete your reps, then switch sides.\"],\"img\":\"9025.webp\",\"gif\":\"9025.mp4\",\"cat\":\"strength\",\"desc\":\"Seated on a ball, you chop diagonally across your body. It trains the obliques and trunk control.\"},{\"id\":\"6878\",\"n\":\"sitting yoga pose siddhasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower back\",\"core\"],\"st\":[\"Sit on the floor and bend your knees.\",\"Place one heel against your inner thigh and the other foot in front of it.\",\"Rest your hands on your knees and lengthen your spine.\",\"Relax your shoulders and look straight ahead.\",\"Hold for 30-60 seconds, breathing slowly.\",\"Switch the cross of your legs and repeat.\"],\"img\":\"6878.webp\",\"gif\":\"6878.mp4\",\"cat\":\"yoga\",\"desc\":\"A calm cross-legged seat that opens the hips and teaches you to sit tall.\"},{\"id\":\"3109\",\"n\":\"skater\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hip flexors\",\"calves\",\"core\"],\"st\":[\"Stand on one leg with a slight bend in the knee.\",\"Leap sideways to the other leg.\",\"Land softly and sweep the back leg behind you.\",\"Swing your arms across your body for balance.\",\"Immediately bound back the other way.\",\"Keep your hips low and your chest forward.\"],\"img\":\"3109.webp\",\"gif\":\"3109.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A side-to-side leap like a speed skater. It trains leg power, balance and stamina.\",\"fv\":\"0737\"},{\"id\":\"3367\",\"n\":\"skater squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand on one leg with the other knee bent and the foot lifted behind you.\",\"Swing your arms forward for balance.\",\"Sit your hips back and lower on the standing leg.\",\"Lightly tap the back knee near the floor.\",\"Stand up through the front foot, then switch legs after your reps.\"],\"img\":\"3367.webp\",\"gif\":\"3367.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat with the free leg swept behind, like a speed skater, for leg strength and balance.\"},{\"id\":\"3676\",\"n\":\"skip jump rope\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"shoulders\"],\"st\":[\"Hold the rope handles and swing the rope overhead.\",\"Skip over the rope, alternating feet.\",\"Land softly on the balls of your feet.\",\"Keep your elbows near your sides.\",\"Continue at a steady pace.\"],\"img\":\"3676.webp\",\"gif\":\"3676.mp4\",\"cat\":\"cardio\",\"desc\":\"Jump rope with an alternating skip step for a lighter, rhythmic cardio workout.\"},{\"id\":\"3199\",\"n\":\"skips\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall and relaxed.\",\"Step forward and hop on the same foot.\",\"Switch and hop on the other foot.\",\"Swing the opposite arm forward with each step.\",\"Stay light on the balls of your feet.\",\"Keep a steady rhythm.\"],\"img\":\"3199.webp\",\"gif\":\"3199.mp4\",\"cat\":\"cardio\",\"desc\":\"A simple skipping step with a hop on each foot. A playful way to warm up and lift your heart rate.\"},{\"id\":\"2224\",\"n\":\"sled 45 degrees leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Sit in the seat with your back and head flat against the pad.\",\"Place your feet shoulder-width apart in the middle of the platform.\",\"Release the safety handles and lower the sled until your knees are bent to about 90 degrees.\",\"Keep your lower back pressed into the pad as you descend.\",\"Push through your whole foot to extend your legs without locking your knees.\",\"Lower under control and repeat.\"],\"img\":\"2224.webp\",\"gif\":\"2224.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press on a 45 degree sled that loads the thighs and hips while your back stays supported.\"},{\"id\":\"3616\",\"n\":\"sled 45 degrees narrow stance leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Sit in the sled with your back flat on the pad and feet close together on the platform.\",\"Release the safety handles.\",\"Lower the sled until your knees are bent to about 90 degrees.\",\"Press through your feet to extend your legs without locking your knees.\",\"Keep your hips on the seat.\"],\"img\":\"3616.webp\",\"gif\":\"3616.mp4\",\"cat\":\"strength\",\"desc\":\"A 45 degree sled leg press with feet close together to emphasise the quads.\"},{\"id\":\"3617\",\"n\":\"sled 45 degrees wide stance leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the sled with your back flat on the pad and feet wide on the platform, toes slightly out.\",\"Release the safety handles.\",\"Lower the sled with your knees tracking over your toes.\",\"Press back up without locking your knees.\",\"Keep your hips on the seat.\"],\"img\":\"3617.webp\",\"gif\":\"3617.mp4\",\"cat\":\"strength\",\"desc\":\"A 45 degree sled leg press with a wide foot position that brings in the inner thighs and glutes.\"},{\"id\":\"1575\",\"n\":\"sled 45° narrow stance leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the sled with your back flat against the pad and feet close together on the platform.\",\"Release the safety handles.\",\"Lower the sled by bending your knees toward your chest.\",\"Stop before your lower back lifts off the pad.\",\"Press through your heels to extend your legs without locking the knees.\"],\"img\":\"1575.webp\",\"gif\":\"1575.mp4\",\"cat\":\"strength\",\"desc\":\"A 45 degree sled leg press with feet close together. The narrow stance puts the focus on the quads.\"},{\"id\":\"10198\",\"n\":\"sled alternating single leg negative press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Sit in the sled with feet on the platform and release the safety.\",\"Press the platform up with both legs and lock out gently.\",\"Shift the load to one leg and lower it slowly for 3-4 seconds.\",\"Press back up with both legs.\",\"Alternate the lowering leg each rep and never let your lower back round.\"],\"img\":\"10198.webp\",\"gif\":\"10198.mp4\",\"cat\":\"strength\",\"desc\":\"A sled leg press done one leg at a time, with a slow lowering phase to build leg strength.\"},{\"id\":\"6734\",\"n\":\"sled angled single leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Sit in the angled sled and place one foot in the middle of the platform.\",\"Release the safety and lower the sled by bending the knee.\",\"Go as deep as you can with your back against the pad.\",\"Press through your heel to straighten the leg without locking out.\",\"Keep your hips flat on the seat.\",\"Finish the reps and switch legs.\"],\"img\":\"6734.webp\",\"gif\":\"6734.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg press on an angled sled. It loads each leg separately for strength and balance.\"},{\"id\":\"1992\",\"n\":\"sled full hack squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Set your shoulders under the pads and your feet shoulder-width on the platform.\",\"Unlock the safety and straighten your legs.\",\"Lower your hips slowly until your thighs are below parallel.\",\"Keep your back flat against the pad and knees tracking over your toes.\",\"Press through your whole foot to stand back up.\"],\"img\":\"1992.webp\",\"gif\":\"1992.mp4\",\"cat\":\"strength\",\"desc\":\"A hack squat on a sled machine through a full range of motion, loading the quads and glutes.\",\"fv\":\"2554\"},{\"id\":\"7593\",\"n\":\"sled glute dominant leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\"],\"st\":[\"Sit in the sled and place your feet high and wide on the platform.\",\"Release the safety and lower the sled until your knees reach about 90 degrees.\",\"Keep your lower back pressed into the seat.\",\"Push through your heels to extend your legs without locking the knees.\",\"Lower under control for each rep.\"],\"img\":\"7593.webp\",\"gif\":\"7593.mp4\",\"cat\":\"strength\",\"desc\":\"A sled leg press with a foot position that puts more load on the glutes. It also works the quads and hamstrings.\"},{\"id\":\"2345\",\"n\":\"sled hack squat legs (form check)\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Set your back and shoulders against the pads and place your feet on the platform.\",\"Compare the faulty version with the correct one: your knees track over your toes and your feet sit flat on the platform.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2345.webp\",\"gif\":\"2345.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for leg position on the hack squat sled, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"10764\",\"n\":\"sled lying single leg squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Lie back on the sled with one foot on the platform.\",\"Hold the handles and brace your core.\",\"Bend your knee and lower the sled toward you.\",\"Stop before your lower back lifts.\",\"Push through your heel to extend the leg.\",\"Do all reps, then switch legs.\"],\"img\":\"10764.webp\",\"gif\":\"10764.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg press-like squat on a sled while lying back. It builds leg strength with back support.\"},{\"id\":\"1579\",\"n\":\"sled one leg hack squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Position yourself in the hack squat sled with your back and shoulders against the pads.\",\"Place one foot in the middle of the platform and keep the other foot off.\",\"Release the safety and lower by bending your working knee.\",\"Go as deep as you can with control.\",\"Press up through your heel, then switch legs after your reps.\"],\"img\":\"1579.webp\",\"gif\":\"1579.mp4\",\"cat\":\"strength\",\"desc\":\"A hack squat on the sled using one leg at a time. It isolates each quad and glute with solid back support.\"},{\"id\":\"1583\",\"n\":\"sled reverse hack squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"calves\"],\"st\":[\"Face the pad of the hack squat sled with your chest against it and feet on the platform.\",\"Hold the handles and release the safety.\",\"Lower by bending your knees and pushing your hips back.\",\"Keep your chest pressed against the pad.\",\"Drive through your heels to stand back up.\"],\"img\":\"1583.webp\",\"gif\":\"1583.mp4\",\"cat\":\"strength\",\"desc\":\"A hack squat done facing the pad on the sled. It puts more load on the glutes and hamstrings.\"},{\"id\":\"8660\",\"n\":\"sled side leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Position yourself on the sled in a side-facing posture with one foot on the platform.\",\"Brace your core and keep your hips stable.\",\"Push the platform away with the working leg.\",\"Return slowly under control.\",\"Finish the reps, then switch sides.\"],\"img\":\"8660.webp\",\"gif\":\"8660.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways leg press on a sled that targets the glutes and outer hips.\"},{\"id\":\"4327\",\"n\":\"sled vertical leg press\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Lie on your back under the sled and place your feet shoulder-width on the platform.\",\"Release the safety catches and lower the platform until your knees are deeply bent.\",\"Keep your lower back flat on the pad.\",\"Press the platform up without locking your knees.\",\"Lower under control for each rep.\"],\"img\":\"4327.webp\",\"gif\":\"4327.mp4\",\"cat\":\"strength\",\"desc\":\"A leg press on a sled that moves straight up, pressing the weight vertically. It loads the thighs and glutes heavily.\"},{\"id\":\"4100\",\"n\":\"sled wide hack squat\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Set your back on the pad and place your feet wide and slightly turned out on the platform.\",\"Release the safety handles.\",\"Lower by bending your knees until your thighs are parallel to the platform.\",\"Press through your feet to extend your legs without locking out.\",\"Keep your hips and back against the pad.\"],\"img\":\"4100.webp\",\"gif\":\"4100.mp4\",\"cat\":\"strength\",\"desc\":\"A hack squat on a sled with a wide foot position, stressing the quads, glutes and inner thighs.\"},{\"id\":\"11374\",\"n\":\"sleepers stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Lie on your side with the bottom arm in front of you, elbow bent to 90 degrees.\",\"Keep your shoulder stacked and the upper arm at chest height.\",\"Use your top hand to gently press the bottom forearm toward the floor.\",\"Stop where you feel a mild stretch at the back of the shoulder.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"11374.webp\",\"gif\":\"11374.mp4\",\"cat\":\"stretching\",\"desc\":\"A side-lying stretch that opens up the back of the shoulder. Handy for keeping internal rotation smooth.\",\"fv\":\"9212\"},{\"id\":\"3498\",\"n\":\"sliding floor bridge curl on towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"calves\"],\"st\":[\"Lie on your back with your heels on towels on a smooth floor.\",\"Lift your hips into a bridge.\",\"Slide your heels away until your legs are nearly straight.\",\"Pull your heels back toward your glutes.\",\"Keep your hips high throughout.\",\"Lower your hips to finish the set.\"],\"img\":\"3498.webp\",\"gif\":\"3498.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge with the heels on towels, sliding the feet in and out. It strongly works the hamstrings and glutes.\"},{\"id\":\"3497\",\"n\":\"sliding floor pulldown on towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"triceps\",\"core\",\"shoulders\"],\"st\":[\"Kneel or lie face down with your hands on towels on a smooth floor.\",\"Start with your arms extended overhead.\",\"Press down and pull your arms back toward your hips, sliding the towels.\",\"Squeeze your lats at the end.\",\"Slide the hands back overhead with control.\",\"Keep your core braced.\"],\"img\":\"3497.webp\",\"gif\":\"3497.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Slide your hands along the floor on a towel, from overhead down toward your sides. It teaches a pulldown pattern for the lats.\"},{\"id\":\"4831\",\"n\":\"sliding floor pulldown on towel v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"core\",\"rhomboids\"],\"st\":[\"Kneel with your hands on a towel placed on a smooth floor, arms stretched forward.\",\"Brace your core and keep your back flat.\",\"Pull your elbows down and back as your hands slide toward you.\",\"Squeeze your lats at the bottom.\",\"Slide back out slowly to the start.\"],\"img\":\"4831.webp\",\"gif\":\"4831.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor pulldown where you slide your hands on a towel from overhead to your sides. It works the lats without any equipment.\"},{\"id\":\"4416\",\"n\":\"sliding leg bird dog\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"shoulders\"],\"st\":[\"Start on all fours with a sliding disc or towel under one foot.\",\"Brace your core and keep your hips level.\",\"Slide that leg straight back as you extend the opposite arm forward.\",\"Return to the start in a controlled way.\",\"Complete your reps, then switch sides.\"],\"img\":\"4416.webp\",\"gif\":\"4416.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bird dog variation where the leg slides along the floor, improving core stability and coordination.\"},{\"id\":\"3395\",\"n\":\"sliding leg curl on floor with towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lie on your back with your heels on towels on a smooth floor.\",\"Lift your hips into a bridge.\",\"Slide your heels away until your legs are nearly straight.\",\"Pull your heels back toward your hips.\",\"Keep your hips high throughout.\",\"Move slowly to stay in control.\"],\"img\":\"3395.webp\",\"gif\":\"3395.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hamstring curl where your heels slide on a towel over a smooth floor.\"},{\"id\":\"3742\",\"n\":\"sliding leg curl on floor with towel v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lie on your back with your heels on towels on a smooth floor.\",\"Lift your hips off the ground.\",\"Slide your heels toward your butt, curling your legs.\",\"Slowly slide them back out.\",\"Keep your hips high throughout.\"],\"img\":\"3742.webp\",\"gif\":\"3742.mp4\",\"cat\":\"strength\",\"desc\":\"A bodyweight hamstring curl where your heels slide on a towel across the floor.\"},{\"id\":\"4312\",\"n\":\"slopes towards stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"lower back\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Raise one arm overhead and keep the other hand resting on your hip.\",\"Lean slowly toward the opposite side, lengthening along the raised arm.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Return to upright and switch sides.\"],\"img\":\"4312.webp\",\"gif\":\"4312.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side-leaning stretch that opens up the lats and the side of the torso.\",\"fv\":\"0745\"},{\"id\":\"5225\",\"n\":\"smith back wide shrug\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"traps\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand with your back to the bar, set at thigh height, and grip it wide behind you.\",\"Lift the bar off the hooks and stand tall.\",\"Shrug your shoulders straight up.\",\"Pause at the top.\",\"Lower slowly and keep your arms straight.\"],\"img\":\"5225.webp\",\"gif\":\"5225.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-grip shrug with the Smith bar held behind your body. It shifts the load toward the back of the traps.\"},{\"id\":\"4179\",\"n\":\"smith banded full squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Attach the band to the Smith machine and set the bar on your back.\",\"Place feet slightly forward of the bar.\",\"Squat as deep as you can with control.\",\"Keep your chest up.\",\"Drive up through your heels.\",\"Stand tall without locking hard.\"],\"img\":\"4179.webp\",\"gif\":\"4179.mp4\",\"cat\":\"strength\",\"desc\":\"A deep Smith machine squat with a band adding resistance. It builds quads and glutes.\"},{\"id\":\"11303\",\"n\":\"smith bench squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Set a bench behind you and place the bar on your upper back.\",\"Unrack and step your feet slightly forward.\",\"Sit down until you lightly touch the bench.\",\"Keep your chest up and knees tracking over your toes.\",\"Drive through your heels to stand.\"],\"img\":\"11303.webp\",\"gif\":\"11303.mp4\",\"cat\":\"strength\",\"desc\":\"A squat on the Smith machine to a bench. The bench gives you a consistent depth and a stable path.\",\"fv\":\"11304\"},{\"id\":\"5316\",\"n\":\"smith bent over narrow pronated grip row\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"rhomboids\",\"biceps\",\"lower back\",\"rear deltoids\"],\"st\":[\"Set the bar at knee height and grip it with hands close together, palms down.\",\"Hinge forward with a flat back and unlock the bar.\",\"Pull the bar toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower the bar slowly.\",\"Keep your hips back and torso still.\"],\"img\":\"5316.webp\",\"gif\":\"5316.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row on the smith machine using a narrow overhand grip. Hits the lats and mid back.\"},{\"id\":\"11762\",\"n\":\"smith bent over row (chest supported)\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Set an incline bench under the bar and lie chest down on it.\",\"Grip the bar just wider than shoulder width.\",\"Pull the bar toward your lower ribs.\",\"Squeeze your shoulder blades together at the top.\",\"Lower slowly until your arms are straight.\"],\"img\":\"11762.webp\",\"gif\":\"11762.mp4\",\"cat\":\"strength\",\"desc\":\"A chest-supported row on the Smith machine that takes stress off the lower back.\"},{\"id\":\"1050\",\"n\":\"smith calf raise (with block)\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Place a block under the Smith bar and rest the bar on your upper back.\",\"Stand with the balls of your feet on the block.\",\"Lower your heels for a full stretch.\",\"Rise onto your toes as high as you can.\",\"Pause at the top, then lower slowly.\"],\"img\":\"1050.webp\",\"gif\":\"1050.mp4\",\"cat\":\"strength\",\"desc\":\"A standing calf raise under the Smith bar with the balls of your feet on a block. The block lets you stretch deeper.\"},{\"id\":\"1164\",\"n\":\"smith calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Set the bar on your shoulders and stand with the balls of your feet on a step.\",\"Keep your knees almost straight and your torso upright.\",\"Lower your heels for a full stretch.\",\"Rise onto your toes as high as you can.\",\"Pause at the top, then lower under control.\"],\"img\":\"1164.webp\",\"gif\":\"1164.mp4\",\"cat\":\"strength\",\"desc\":\"Calf raise under a Smith machine bar, working the calves with a fixed bar path for stable loading.\"},{\"id\":\"6606\",\"n\":\"smith curtsey lunge\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Set the bar on your upper back and unrack it, feet hip-width apart.\",\"Step one leg back and diagonally behind the other, like a curtsey.\",\"Lower until your front thigh is near parallel, chest tall.\",\"Press through the front heel to return to standing.\",\"Finish all reps, then switch sides.\"],\"img\":\"6606.webp\",\"gif\":\"6606.mp4\",\"cat\":\"strength\",\"desc\":\"A curtsey lunge on the smith machine that steps one leg behind and across the other. It hits the glutes and outer hips with a stable bar path.\"},{\"id\":\"6038\",\"n\":\"smith donkey kick\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Set the bar of the Smith machine at a low height.\",\"Get on all fours with one foot under the bar.\",\"Press the bar up by extending your hip.\",\"Squeeze your glute at the top.\",\"Lower slowly and repeat before switching legs.\"],\"img\":\"6038.webp\",\"gif\":\"6038.mp4\",\"cat\":\"strength\",\"desc\":\"A kick-back using the Smith machine bar under the foot, to target the glutes.\"},{\"id\":\"4546\",\"n\":\"smith drag curl\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"shoulders\"],\"st\":[\"Stand close to the smith bar with an underhand shoulder-width grip.\",\"Let the bar hang at arm length against your thighs.\",\"Pull your elbows back and drag the bar up along your torso.\",\"Squeeze your biceps at the top.\",\"Lower the bar along the same line with control.\",\"Keep your torso still and avoid leaning back.\"],\"img\":\"4546.webp\",\"gif\":\"4546.mp4\",\"cat\":\"strength\",\"desc\":\"A biceps curl where the bar is dragged up along the body, keeping the load on the biceps and reducing shoulder swing.\"},{\"id\":\"9042\",\"n\":\"smith elevated split squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Place a bench behind the smith machine and rest your back foot on it.\",\"Position the bar on your upper back and unrack it.\",\"Step the front foot forward.\",\"Lower your hips until the front thigh is near parallel.\",\"Drive up through the front foot.\",\"Complete the reps, then switch legs.\"],\"img\":\"9042.webp\",\"gif\":\"9042.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with the rear foot raised on a bench, done on a smith machine. It targets the quads and glutes with extra stability.\"},{\"id\":\"1594\",\"n\":\"smith frankenstein squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"shoulders\",\"hamstrings\"],\"st\":[\"Set the bar at upper chest height and rest it on your front shoulders.\",\"Extend your arms straight forward, like a zombie, to keep the bar in place.\",\"Unrack the bar and step into a stable stance.\",\"Squat down with your chest up and your torso upright.\",\"Drive through your heels to stand and rerack when finished.\"],\"img\":\"1594.webp\",\"gif\":\"1594.mp4\",\"cat\":\"strength\",\"desc\":\"A front-loaded squat on the smith machine with your arms stretched straight in front. It strongly challenges the quads and upper back posture.\"},{\"id\":\"6465\",\"n\":\"smith frog hip thrust\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Sit with your upper back on a bench and the Smith bar over your hips.\",\"Put the soles of your feet together, knees open.\",\"Drive your hips up until your body is level.\",\"Squeeze your glutes at the top.\",\"Lower under control and repeat.\"],\"img\":\"6465.webp\",\"gif\":\"6465.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded hip thrust on a Smith machine with the soles of your feet together, strongly targeting the glutes.\"},{\"id\":\"9041\",\"n\":\"smith front leg elevated split squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Set a low platform under the smith bar and put your front foot on it.\",\"Place the bar across your upper back and unrack it.\",\"Step the back foot behind you.\",\"Lower your back knee toward the floor.\",\"Press through the front heel to stand.\",\"Do all reps, then switch legs.\"],\"img\":\"9041.webp\",\"gif\":\"9041.mp4\",\"cat\":\"strength\",\"desc\":\"With the front foot raised on a step and the bar on your back, you sink into a deep split squat. It loads the quads and glutes.\"},{\"id\":\"1595\",\"n\":\"smith front squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\",\"upper back\"],\"st\":[\"Set the bar at shoulder height and rest it on the front of your shoulders with elbows up.\",\"Unrack it and step your feet slightly forward.\",\"Squat down until your thighs are about parallel to the floor.\",\"Keep your elbows high and your chest up.\",\"Press through your heels to stand and rerack when done.\"],\"img\":\"1595.webp\",\"gif\":\"1595.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat with the bar guided by the smith machine. It trains the quads with an upright torso.\"},{\"id\":\"1519\",\"n\":\"smith good morning off pins\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Set the bar on the pins at upper-chest height and duck under it.\",\"Stand tall with the bar on your upper back and knees slightly bent.\",\"Push your hips back, keeping your back flat.\",\"Stop when your torso is near parallel with the floor.\",\"Drive your hips forward to stand, then return the bar to the pins when done.\"],\"img\":\"1519.webp\",\"gif\":\"1519.mp4\",\"cat\":\"strength\",\"desc\":\"A good morning on the Smith machine starting from the pins. It builds the hamstrings, glutes and lower back.\"},{\"id\":\"5142\",\"n\":\"smith hang clean\",\"bp\":\"full body\",\"eq\":\"smith machine\",\"tg\":\"traps\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"quadriceps\"],\"st\":[\"Stand at the bar with it hanging at your knees, hands just outside your legs.\",\"Keep your back flat.\",\"Extend your hips and shrug explosively.\",\"Pull your elbows high and catch the bar on your shoulders.\",\"Lower the bar back to your knees and repeat.\"],\"img\":\"5142.webp\",\"gif\":\"5142.mp4\",\"cat\":\"olympic\",\"desc\":\"Pull a Smith machine bar from the knees up to your shoulders. The fixed track helps you learn the hang clean pattern.\"},{\"id\":\"2919\",\"n\":\"smith hex press\",\"bp\":\"chest\",\"eq\":\"smith machine\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench under the Smith bar and hold a weight plate between your palms if you like.\",\"Unrack the bar with a close grip and hold it over your chest.\",\"Squeeze your hands inward as you lower the bar to your mid chest.\",\"Press back up while still squeezing.\",\"Rerack the bar when done.\"],\"img\":\"2919.webp\",\"gif\":\"2919.mp4\",\"cat\":\"strength\",\"desc\":\"A press with the weights squeezed together, done on a Smith machine. The squeeze keeps tension on the chest throughout.\",\"nd\":[\"bench\"]},{\"id\":\"3110\",\"n\":\"smith hip thrust\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\",\"adductors\"],\"st\":[\"Sit on the floor with your upper back against a bench and the Smith bar over your hips.\",\"Pad the bar and roll it into the crease of your hips.\",\"Plant your feet hip width apart and unrack the bar.\",\"Drive through your heels and lift your hips until your body is level.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"3110.webp\",\"gif\":\"3110.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with the bar on a Smith machine, giving a steady path to load the glutes.\",\"fv\":\"5761\"},{\"id\":\"10116\",\"n\":\"smith incline close grip bench press\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"triceps\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"chest\"],\"st\":[\"Set an incline bench under the Smith bar and lie back with eyes under the bar.\",\"Grip the bar slightly narrower than shoulder width and unrack it.\",\"Lower the bar to your upper chest with elbows close to your sides.\",\"Press the bar up until your arms are straight.\",\"Keep your feet planted and your shoulder blades pulled back.\"],\"img\":\"10116.webp\",\"gif\":\"10116.mp4\",\"cat\":\"strength\",\"desc\":\"A close grip press on an incline bench using the guided Smith bar to hit the triceps and upper chest.\"},{\"id\":\"9385\",\"n\":\"smith jm bench press\",\"bp\":\"upper arms\",\"eq\":\"smith machine\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench under the smith bar with a shoulder width grip.\",\"Unrack the bar over your chest.\",\"Lower the bar toward your chin or upper chest by bending your elbows.\",\"Keep your elbows slightly in.\",\"Press the bar back up.\",\"Use a light weight and control the path.\"],\"img\":\"9385.webp\",\"gif\":\"9385.mp4\",\"cat\":\"strength\",\"desc\":\"A hybrid of a close grip bench press and skull crusher done on a smith machine. It loads the triceps.\"},{\"id\":\"3874\",\"n\":\"smith kneeling hip thrust\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Set the bar on the Smith machine at a low height and kneel facing away from it.\",\"Place the bar across your hips with a pad for comfort.\",\"Keep your torso upright and your core braced.\",\"Thrust your hips forward and squeeze your glutes.\",\"Slowly return to the start.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"3874.webp\",\"gif\":\"3874.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling hip thrust on the Smith machine that trains hip extension and the glutes.\"},{\"id\":\"1183\",\"n\":\"smith kneeling rear kick\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Set the bar at a low height and kneel on all fours facing it, with the sole of one foot under the bar.\",\"Brace your abs and keep your back flat.\",\"Press your foot up and back against the bar until your hip is fully extended.\",\"Squeeze your glute at the top, then lower under control.\",\"Finish your reps, then switch legs.\"],\"img\":\"1183.webp\",\"gif\":\"1183.mp4\",\"cat\":\"strength\",\"desc\":\"A glute kickback done kneeling with one foot pressing against a smith machine bar, a focused move for the glutes.\"},{\"id\":\"2952\",\"n\":\"smith kneeling rear kick (with partner)\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Get on all fours and place the sole of one foot on the Smith bar, with your partner steadying you if needed.\",\"Brace your core.\",\"Press the bar up by extending your hip.\",\"Squeeze your glute at the top.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"2952.webp\",\"gif\":\"2952.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling glute kick using a Smith machine with a partner helping. It works the glutes with a steady guided path.\"},{\"id\":\"0884\",\"n\":\"smith lateral step up\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Place a bench beside you and set the bar across your upper back.\",\"Stand with the bench at your side.\",\"Step up sideways with the near foot.\",\"Straighten your leg to lift your body.\",\"Lower slowly, finish reps, then switch sides.\"],\"img\":\"0884.webp\",\"gif\":\"0884.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways step up under the smith bar. It works the quads and glutes one leg at a time.\"},{\"id\":\"0885\",\"n\":\"smith lying lift (on hip)\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie on your side under the bar and set it at a comfortable height.\",\"Place your top foot or leg against the bar.\",\"Lift the leg up smoothly against the resistance.\",\"Lower with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"0885.webp\",\"gif\":\"0885.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying lift using the smith machine for resistance. It targets the outer hip and glutes.\"},{\"id\":\"2671\",\"n\":\"smith narrow row v. 2\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Set the bar at knee height and grip it with hands close together.\",\"Hinge forward at the hips with a flat back and slightly bent knees.\",\"Pull the bar toward your lower ribs, keeping elbows close to your body.\",\"Squeeze your back at the top.\",\"Lower the bar under control to full arm extension.\"],\"img\":\"2671.webp\",\"gif\":\"2671.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row on the smith machine with a narrow grip, working the lats and mid back.\"},{\"id\":\"0886\",\"n\":\"smith one leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand holding the bar at hip height on a single leg.\",\"Keep a slight bend in the standing knee.\",\"Hinge forward, sliding the bar down your leg.\",\"Keep your back flat and extend the free leg behind you.\",\"Drive your hips forward to stand, then switch legs.\"],\"img\":\"0886.webp\",\"gif\":\"0886.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg deadlift using the smith bar. It trains the hamstrings, glutes and balance.\"},{\"id\":\"4171\",\"n\":\"smith rack pull\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"upper back\",\"grip muscles\"],\"st\":[\"Set the bar at knee height in the Smith machine.\",\"Grip the bar and set your back flat.\",\"Drive through your feet and extend your hips.\",\"Stand tall and squeeze your glutes.\",\"Lower the bar to the start with control.\",\"Keep the bar close to your legs.\"],\"img\":\"4171.webp\",\"gif\":\"4171.mp4\",\"cat\":\"strength\",\"desc\":\"A partial deadlift from knee height on a Smith machine. It overloads the back and hips.\"},{\"id\":\"5825\",\"n\":\"smith rear lunge v. 2\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Set the bar on your upper back and stand tall.\",\"Step one foot back behind you.\",\"Lower until your front thigh is about parallel to the floor.\",\"Push through your front heel to return.\",\"Finish your reps, then switch legs.\"],\"img\":\"5825.webp\",\"gif\":\"5825.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge using the Smith machine for a fixed bar path. It works the glutes and quads with extra stability.\",\"fv\":\"0887\"},{\"id\":\"2745\",\"n\":\"smith reverse hyperextension\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down over a bench with your hips at the edge and legs hanging.\",\"Hook your heels under the smith bar if it is set low.\",\"Lift your legs by extending the hips until they are in line with your body.\",\"Squeeze your glutes at the top.\",\"Lower slowly without swinging.\"],\"img\":\"2745.webp\",\"gif\":\"2745.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse hyperextension on the smith machine that works the glutes and hamstrings with support from the lower back.\"},{\"id\":\"4370\",\"n\":\"smith seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"smith machine\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit on a bench under the bar with the balls of your feet on a raised block.\",\"Rest the bar across your thighs with a pad.\",\"Lift your heels as high as possible.\",\"Pause at the top.\",\"Lower slowly for a full stretch.\"],\"img\":\"4370.webp\",\"gif\":\"4370.mp4\",\"cat\":\"strength\",\"desc\":\"A seated calf raise with a barbell on a Smith machine, working the lower calf muscle.\"},{\"id\":\"10863\",\"n\":\"smith seated single arm neutral grip shoulders press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Set a bench under the smith bar and sit upright with your back supported.\",\"Hold the bar with one hand in a neutral grip and unhook it.\",\"Press the bar overhead until your arm is almost straight.\",\"Lower it slowly to around chin height.\",\"Keep your torso steady. Finish all reps, then switch arms.\"],\"img\":\"10863.webp\",\"gif\":\"10863.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm seated press on the smith machine with a neutral grip. It trains the shoulder while the bar path stays guided.\"},{\"id\":\"3945\",\"n\":\"smith single arm bent over row\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"upper back\"],\"st\":[\"Set the bar at a low height and hinge at the hips with a flat back.\",\"Grip the bar with one hand and brace the other on your thigh.\",\"Pull the bar toward your lower ribs.\",\"Lower it under control.\",\"Finish your reps, then switch arms.\"],\"img\":\"3945.webp\",\"gif\":\"3945.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm row against the Smith bar for a stable path. It builds the lats and upper back, one side at a time.\"},{\"id\":\"1596\",\"n\":\"smith squat to bench\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Place a bench behind you under the smith bar.\",\"Rest the bar on your upper back and unrack it.\",\"Sit your hips back and lower until you touch the bench lightly.\",\"Keep your chest up and your knees tracking your toes.\",\"Drive through your heels to stand and rerack when finished.\"],\"img\":\"1596.webp\",\"gif\":\"1596.mp4\",\"cat\":\"strength\",\"desc\":\"A smith machine squat down to a bench behind you. The bench gives a consistent depth target.\"},{\"id\":\"11053\",\"n\":\"smith staggered stance hip thrust\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Sit with your upper back on a bench and the bar over your hips.\",\"Stagger your feet, one slightly ahead.\",\"Drive through your heels.\",\"Lift your hips to full extension.\",\"Squeeze your glutes.\",\"Lower slowly and switch the stance.\"],\"img\":\"11053.webp\",\"gif\":\"11053.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust on the Smith machine with a staggered stance. It builds the glutes.\"},{\"id\":\"8800\",\"n\":\"smith staggered stance romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand under the smith bar with one foot slightly behind the other.\",\"Grip the bar and unrack it.\",\"Hinge at the hips with a flat back and the bar close to your legs.\",\"Lower until you feel a stretch in the hamstrings.\",\"Drive your hips forward to stand tall.\",\"Switch which foot is forward after your set.\"],\"img\":\"8800.webp\",\"gif\":\"8800.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift in a staggered stance on the smith machine. It focuses on the hamstrings and glutes of the front leg.\"},{\"id\":\"1224\",\"n\":\"smith standing shoulder press\",\"bp\":\"shoulders\",\"eq\":\"smith machine\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\"],\"st\":[\"Set the bar at shoulder height and stand under it with a shoulder width grip.\",\"Unrack the bar and hold it at your collarbone.\",\"Press up until your arms are straight.\",\"Lower the bar back to your shoulders slowly.\",\"Brace your core and keep your ribs down.\"],\"img\":\"1224.webp\",\"gif\":\"1224.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press on the Smith machine. The fixed bar path lets you focus on pushing.\"},{\"id\":\"11879\",\"n\":\"smith step up\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Set the bar across your upper back and stand in front of a bench.\",\"Place one foot on the bench.\",\"Drive through that heel to stand up fully.\",\"Step back down under control.\",\"Complete your reps, then switch legs.\"],\"img\":\"11879.webp\",\"gif\":\"11879.mp4\",\"cat\":\"strength\",\"desc\":\"A step-up with a Smith machine bar across your back for loaded leg work.\"},{\"id\":\"1597\",\"n\":\"smith stiff legged deadlift\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand close to the smith bar with feet hip-width apart and grip the bar overhand.\",\"Unrack it and keep your knees nearly straight.\",\"Push your hips back and slide the bar down your legs.\",\"Lower until you feel a deep stretch in your hamstrings.\",\"Squeeze your glutes to stand tall.\"],\"img\":\"1597.webp\",\"gif\":\"1597.mp4\",\"cat\":\"strength\",\"desc\":\"A stiff-legged deadlift using the smith machine bar. The fixed path lets you focus on feeling the hamstrings work.\",\"fv\":\"11217\"},{\"id\":\"6796\",\"n\":\"smith sumo chair squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Place a chair behind you and set the bar on your upper back.\",\"Take a wide stance with toes turned out.\",\"Sit back and down until you lightly touch the chair.\",\"Keep your knees tracking over your toes.\",\"Drive through your heels to stand up.\"],\"img\":\"6796.webp\",\"gif\":\"6796.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance squat on the smith machine down to a chair. The seat gives a consistent depth.\"},{\"id\":\"7374\",\"n\":\"smith sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"lower back\",\"quadriceps\"],\"st\":[\"Stand with feet wide, toes turned out, and grip the bar inside your knees.\",\"Brace your core and keep your chest up.\",\"Push your feet into the floor and stand tall.\",\"Lock out your hips at the top.\",\"Lower the bar by pushing your hips back.\"],\"img\":\"7374.webp\",\"gif\":\"7374.mp4\",\"cat\":\"strength\",\"desc\":\"Wide-stance deadlift on the smith machine that trains glutes and inner thighs.\",\"fv\":\"6557\"},{\"id\":\"11568\",\"n\":\"smith unilateral bulgarian split squat from deficit\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Set the bar on your upper back and stand with the front foot on a low plate or step.\",\"Place the rear foot on a bench behind you.\",\"Lower straight down until the front thigh is about parallel or deeper.\",\"Keep your torso upright and the front knee tracking over the toes.\",\"Push through the front heel to stand, then switch legs.\"],\"img\":\"11568.webp\",\"gif\":\"11568.mp4\",\"cat\":\"strength\",\"desc\":\"A Bulgarian split squat on a Smith machine with the front foot raised, giving extra depth for quads and glutes.\"},{\"id\":\"5223\",\"n\":\"smith wide shrug\",\"bp\":\"back\",\"eq\":\"smith machine\",\"tg\":\"traps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"grip muscles\",\"upper back\"],\"st\":[\"Set the bar at thigh height and grip it wider than shoulder width.\",\"Stand tall with your arms straight.\",\"Shrug your shoulders straight up toward your ears.\",\"Pause at the top.\",\"Lower slowly without rolling your shoulders.\"],\"img\":\"5223.webp\",\"gif\":\"5223.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug on the Smith machine with a wide grip. It builds the upper traps.\"},{\"id\":\"1598\",\"n\":\"smith zercher squat\",\"bp\":\"upper legs\",\"eq\":\"smith machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"biceps\",\"upper back\"],\"st\":[\"Set the bar at waist height and hook your elbows under it with your arms crossed.\",\"Unrack and stand with feet shoulder-width apart.\",\"Squat down while keeping your chest up and the bar close to your body.\",\"Go until your thighs are about parallel.\",\"Press through your heels to stand and rerack when done.\"],\"img\":\"1598.webp\",\"gif\":\"1598.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding the bar in the crooks of your elbows on the smith machine. It trains the legs while taxing the core and upper back.\"},{\"id\":\"10045\",\"n\":\"snow angel face to floor\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"glutes\",\"upper back\",\"trapezius\"],\"st\":[\"Lie face down with arms by your sides and legs together.\",\"Lift your chest and arms slightly off the floor.\",\"Sweep your arms out and overhead while opening your legs.\",\"Bring them back to the start in the same arc.\",\"Repeat in a smooth rhythm.\",\"Keep your neck long and look at the floor.\"],\"img\":\"10045.webp\",\"gif\":\"10045.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you sweep your arms and legs like a snow angel. It works the muscles along your back.\"},{\"id\":\"10046\",\"n\":\"snow angel face to sky\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"lower abs\"],\"st\":[\"Lie on your back with arms by your sides and legs together.\",\"Press your lower back toward the floor.\",\"Sweep your arms overhead while opening your legs.\",\"Bring them back together in the same arc.\",\"Repeat at a steady pace.\",\"Keep your abs braced and lower back flat.\"],\"img\":\"10046.webp\",\"gif\":\"10046.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face up, you sweep arms and legs out like a snow angel. It trains the abs and keeps your shoulders mobile.\"},{\"id\":\"7463\",\"n\":\"spider mountain climber\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank, hands under shoulders.\",\"Drive one knee toward the outside of your elbow.\",\"Return that foot and switch legs.\",\"Keep your hips low and your core braced.\",\"Move at a quick, controlled pace.\"],\"img\":\"7463.webp\",\"gif\":\"7463.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Mountain climber where each knee drives toward the same-side elbow, adding side work for the core.\"},{\"id\":\"6092\",\"n\":\"spider plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\",\"triceps\"],\"st\":[\"Start in a high or forearm plank.\",\"Keep your body in a straight line.\",\"Bring one knee toward the same elbow.\",\"Return to plank.\",\"Alternate sides without letting your hips sag.\"],\"img\":\"6092.webp\",\"gif\":\"6092.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A plank with alternating knee drives to the elbow, building core strength.\",\"fv\":\"3953\"},{\"id\":\"2310\",\"n\":\"spin back kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Turn your head and shoulders to look behind you.\",\"Pivot on your supporting foot.\",\"Kick your leg straight back with the heel leading.\",\"Keep your torso leaning slightly forward for balance.\",\"Return to stance and repeat, then switch sides.\"],\"img\":\"2310.webp\",\"gif\":\"2310.mp4\",\"cat\":\"combat\",\"desc\":\"A kick where you turn your back to the target and thrust the heel straight back, building rotation and balance.\"},{\"id\":\"2306\",\"n\":\"spin hook kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"calves\"],\"st\":[\"Stand in a fighting stance with your hands up.\",\"Turn your head and shoulders to look behind you.\",\"Spin on the ball of your supporting foot.\",\"Swing your kicking leg around and hook the heel across the target.\",\"Land in a balanced stance.\",\"Repeat, then switch sides.\"],\"img\":\"2306.webp\",\"gif\":\"2306.mp4\",\"cat\":\"combat\",\"desc\":\"A spinning kick where you turn your body and sweep the heel in a hook around the target. Great for balance and coordination.\"},{\"id\":\"4314\",\"n\":\"spinal stretch (on stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"spine\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"core\"],\"st\":[\"Kneel in front of a stability ball and place your forearms or hands on top.\",\"Roll the ball forward as you sink your hips back.\",\"Let your head drop between your arms and lengthen your spine.\",\"Hold for 20-30 seconds, breathing deeply.\",\"Roll the ball back in to come up.\"],\"img\":\"4314.webp\",\"gif\":\"4314.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle back stretch draped over or kneeling at a stability ball. It lengthens the spine and relaxes the torso.\",\"fv\":\"0779\"},{\"id\":\"2785\",\"n\":\"spine (lumbar) extension\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand with feet hip width apart and your hands on your hips.\",\"Lean back gently, arching your lower back within a comfortable range.\",\"Pause briefly, then return upright.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2785.webp\",\"gif\":\"2785.mp4\",\"cat\":\"mobility\",\"desc\":\"Gently arching the lower back backward, working the muscles along the spine.\"},{\"id\":\"2786\",\"n\":\"spine (lumbar) flexion\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"lower back\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand with feet hip width apart and knees slightly soft.\",\"Round your lower back forward and tuck your chin and pelvis in.\",\"Pause briefly, then return upright.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2786.webp\",\"gif\":\"2786.mp4\",\"cat\":\"mobility\",\"desc\":\"Curling the lower back forward, working the abs and mobilising the lumbar spine.\"},{\"id\":\"2787\",\"n\":\"spine (lumbar) lateral flexion\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand with feet hip width apart and your arms at your sides.\",\"Slide one hand down the outside of your leg as you bend sideways.\",\"Keep your hips level, return to upright, then bend to the other side.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2787.webp\",\"gif\":\"2787.mp4\",\"cat\":\"mobility\",\"desc\":\"Bending the trunk sideways, working the obliques and mobilising the spine.\"},{\"id\":\"2788\",\"n\":\"spine (lumbar) rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Stand with feet hip width apart and your arms crossed over your chest.\",\"Rotate your torso to one side while keeping the hips facing forward.\",\"Return to center, then rotate to the other side.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2788.webp\",\"gif\":\"2788.mp4\",\"cat\":\"mobility\",\"desc\":\"Twisting the trunk to each side, working the obliques and mobilising the spine.\"},{\"id\":\"3517\",\"n\":\"spine backbend stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"glutes\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Place your hands on your lower back.\",\"Squeeze your glutes and push your hips forward.\",\"Lean back gently, lifting your chest.\",\"Hold for 20-30 seconds.\",\"Return upright slowly.\"],\"img\":\"3517.webp\",\"gif\":\"3517.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle backbend that stretches the spine, hips and abs.\"},{\"id\":\"4315\",\"n\":\"spine stretch forward\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Sit tall with legs extended hip-width apart and arms reaching forward.\",\"Flex your feet and lift your torso up out of your hips.\",\"Curl your chin to your chest and round forward, reaching past your toes.\",\"Hold for a breath, then stack your spine back up slowly.\",\"Repeat for several slow reps.\"],\"img\":\"4315.webp\",\"gif\":\"4315.mp4\",\"cat\":\"pilates\",\"desc\":\"A seated pilates stretch where you round forward over your legs, one vertebra at a time. It mobilizes the spine and stretches the hamstrings.\"},{\"id\":\"2873\",\"n\":\"spine stretch forward v. 2\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Sit tall with legs extended hip-width apart and arms reaching forward.\",\"Draw your belly in and flex your feet.\",\"Curl forward one vertebra at a time, reaching over an imaginary ball.\",\"Hold for a breath at the bottom.\",\"Roll back up to tall sitting and repeat.\"],\"img\":\"2873.webp\",\"gif\":\"2873.mp4\",\"cat\":\"pilates\",\"desc\":\"A seated Pilates stretch that rounds the spine forward to lengthen the back and hamstrings.\"},{\"id\":\"2868\",\"n\":\"spine twist v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"lower back\"],\"st\":[\"Sit tall with your legs extended and arms reaching out to the sides.\",\"Flex your feet and grow tall through the crown of your head.\",\"Twist your torso to one side, pulsing gently for a small extra turn.\",\"Return to center without sagging in the chest.\",\"Twist to the other side and repeat.\"],\"img\":\"2868.webp\",\"gif\":\"2868.mp4\",\"cat\":\"pilates\",\"desc\":\"A seated Pilates twist that mobilises the spine and strengthens the obliques.\"},{\"id\":\"3113\",\"n\":\"split jacks\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hip flexors\",\"shoulders\"],\"st\":[\"Stand tall with your arms at your sides.\",\"Jump one foot forward and the other back as you swing opposite arms.\",\"Land softly with soft knees.\",\"Jump again and switch legs.\",\"Keep your torso upright.\",\"Continue at a steady pace for 30-45 seconds.\"],\"img\":\"3113.webp\",\"gif\":\"3113.mp4\",\"cat\":\"cardio\",\"desc\":\"A jumping move where your legs split front and back while your arms swing. It's a light, fast cardio burst.\",\"fv\":\"0780\"},{\"id\":\"3440\",\"n\":\"split jump to box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in a lunge position facing a box.\",\"Swing your arms and jump up.\",\"Land with both feet softly on the box.\",\"Stand tall.\",\"Step down carefully.\",\"Switch your front leg and repeat.\"],\"img\":\"3440.webp\",\"gif\":\"3440.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump from a split stance onto a box, building leg power.\"},{\"id\":\"3718\",\"n\":\"split lateral squat with roll\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"core\"],\"st\":[\"Stand with feet wide and toes forward.\",\"Shift your weight to one side and squat on that leg, keeping the other leg straight.\",\"Roll back with control and roll up again.\",\"Push back to the centre.\",\"Alternate sides.\"],\"img\":\"3718.webp\",\"gif\":\"3718.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lateral squat done from a split position, followed by a roll, for leg strength and coordination.\"},{\"id\":\"3482\",\"n\":\"split sprinter high lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\",\"calves\"],\"st\":[\"Stand tall and step one foot well back into a staggered stance.\",\"Bend both knees and lower into a lunge, back heel lifted.\",\"Swing the arm opposite the front leg forward and the other arm back, like sprinting.\",\"Keep your torso upright and the front knee over the ankle.\",\"Push through the front foot to rise, then repeat all reps.\",\"Switch legs and do the same number.\"],\"img\":\"3482.webp\",\"gif\":\"3482.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A high lunge with the arms driving like a sprinter's. It builds leg strength, balance and hip stability.\"},{\"id\":\"3481\",\"n\":\"split sprinter low lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Step into a long lunge.\",\"Lower your back knee near the floor.\",\"Keep your torso tall.\",\"Hold the low position briefly.\",\"Push up.\",\"Switch legs.\"],\"img\":\"3481.webp\",\"gif\":\"3481.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A low lunge hold in a sprinter stance for the legs and hips.\"},{\"id\":\"0781\",\"n\":\"split squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand in a long stride with one foot forward and the other back.\",\"Keep your torso upright and core tight.\",\"Bend both knees and lower until the back knee hovers just above the floor.\",\"Press through the front heel to stand back up.\",\"Finish all reps, then switch legs.\"],\"img\":\"0781.webp\",\"gif\":\"0781.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A staggered-stance squat where the back leg stays put. It works the quads and glutes one side at a time.\"},{\"id\":\"8755\",\"n\":\"split squat heel raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"soleus\"],\"st\":[\"Stand in a split stance with one foot well forward.\",\"Lower into a split squat with an upright torso.\",\"Push up through your front foot to stand.\",\"Rise onto the toes of your back foot or both feet.\",\"Lower your heel and repeat.\",\"Finish your reps, then switch legs.\"],\"img\":\"8755.webp\",\"gif\":\"8755.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A split squat with a heel raise added at the top. It works the quads, glutes and calves together.\"},{\"id\":\"2752\",\"n\":\"split squat v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand in a long stride with one foot forward and one back.\",\"Lower your back knee toward the floor.\",\"Keep your front knee over your ankle.\",\"Push through the front heel to rise.\",\"Finish your reps, then switch legs.\"],\"img\":\"2752.webp\",\"gif\":\"2752.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A static lunge-style squat that trains the legs one at a time with balance and control.\"},{\"id\":\"3716\",\"n\":\"split squat with roll\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Start in a split stance with your torso upright.\",\"Lower into a split squat until the front thigh is parallel.\",\"Sit back and roll onto your back with control.\",\"Roll up and return to the split stance.\",\"Stand and repeat, then switch legs.\"],\"img\":\"3716.webp\",\"gif\":\"3716.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A split squat paired with a backward roll to challenge your control and leg strength.\"},{\"id\":\"10819\",\"n\":\"split stance single leg calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand in a split stance, front foot flat and back toes lightly touching the floor.\",\"Keep most weight on the front leg.\",\"Rise onto the ball of the front foot.\",\"Pause at the top.\",\"Lower the heel slowly.\",\"Finish your reps, then switch sides.\"],\"img\":\"10819.webp\",\"gif\":\"10819.mp4\",\"cat\":\"strength\",\"desc\":\"A calf raise in a split stance, with most work on the front leg. It trains the calf with balance support.\"},{\"id\":\"11089\",\"n\":\"split stretch spine rolling\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Sit on the floor with your legs spread wide in a comfortable split.\",\"Sit tall and reach your arms forward.\",\"Round your spine and roll down slowly, one segment at a time.\",\"Roll back up slowly until you are upright.\",\"Repeat for 8-10 slow reps without forcing the stretch.\"],\"img\":\"11089.webp\",\"gif\":\"11089.mp4\",\"cat\":\"stretching\",\"desc\":\"A seated straddle position with a rolling spine movement. It loosens your back and inner thighs.\"},{\"id\":\"0958\",\"n\":\"spread leg forward fold upavista konasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"groin\",\"lower back\"],\"st\":[\"Sit on the floor with legs spread as wide as is comfortable.\",\"Flex your feet and keep your knees pointing up.\",\"Walk your hands forward and fold from the hips.\",\"Keep your spine long instead of rounding.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0958.webp\",\"gif\":\"0958.mp4\",\"cat\":\"stretching\",\"desc\":\"Sit with legs wide and fold forward over them. It stretches the inner thighs and hamstrings.\"},{\"id\":\"5216\",\"n\":\"sprint\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"glutes\",\"quadriceps\",\"calves\"],\"st\":[\"Warm up well with jogging and dynamic stretches.\",\"Start in a staggered stance and lean slightly forward.\",\"Drive your arms and knees as you accelerate.\",\"Run at maximum effort for 10-30 seconds.\",\"Slow down gradually and rest fully before the next sprint.\"],\"img\":\"5216.webp\",\"gif\":\"5216.mp4\",\"cat\":\"cardio\",\"desc\":\"Short, all-out running efforts. It builds speed and conditioning.\"},{\"id\":\"9040\",\"n\":\"sprint against wall\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"calves\"],\"st\":[\"Place your hands on a wall and lean forward with a straight body line.\",\"Brace your core.\",\"Drive one knee up while the other leg stays extended.\",\"Switch legs quickly in a running rhythm.\",\"Keep your hips level.\",\"Go hard for 10-20 seconds, then rest.\"],\"img\":\"9040.webp\",\"gif\":\"9040.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Leaning into a wall, you drive your knees in a fast running pattern. It practises sprint posture and builds speed.\"},{\"id\":\"3865\",\"n\":\"sprinter crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with your hands lightly behind your head.\",\"Lift your shoulders off the floor and bring one knee toward the opposite elbow.\",\"Extend the other leg out low above the floor.\",\"Switch sides in a smooth running rhythm.\",\"Keep your lower back pressed down.\",\"Continue for the set.\"],\"img\":\"3865.webp\",\"gif\":\"3865.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A running-style crunch where opposite elbow and knee drive together to work the abs and obliques.\"},{\"id\":\"0782\",\"n\":\"square hop\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"quadriceps\",\"glutes\"],\"st\":[\"Imagine a square on the floor and stand at one corner.\",\"Hop on both feet to the next corner, staying light on your toes.\",\"Keep hopping around the square in order.\",\"Land softly with slightly bent knees.\",\"Reverse direction halfway through your set.\"],\"img\":\"0782.webp\",\"gif\":\"0782.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick hopping drill where you jump around the corners of an imaginary square. It builds foot speed, agility and leg power.\"},{\"id\":\"1197\",\"n\":\"squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet about shoulder width apart and toes slightly out.\",\"Push your hips back and bend your knees to lower down.\",\"Go as deep as you can while keeping your heels down and chest up.\",\"Drive through your feet to stand back up.\",\"Keep your knees tracking over your toes.\"],\"img\":\"1197.webp\",\"gif\":\"1197.mp4\",\"cat\":\"calisthenics\",\"desc\":\"The basic bodyweight squat. It trains the thighs and glutes and teaches solid lower body mechanics.\",\"fv\":\"0787\"},{\"id\":\"0783\",\"n\":\"squat (arms overhead)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and reach both arms overhead.\",\"Keep your arms in line with your ears and your ribs down.\",\"Sit your hips back and down until your thighs are about parallel to the floor.\",\"Keep your heels down and knees tracking over your toes.\",\"Drive up through your feet to stand tall.\"],\"img\":\"0783.webp\",\"gif\":\"0783.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat with arms reaching overhead. It trains the legs and challenges shoulder mobility and trunk stability.\"},{\"id\":\"0784\",\"n\":\"squat (with band)\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Place the band as set up for the drill and stand with feet shoulder-width apart.\",\"Brace your core and keep your chest up.\",\"Sit your hips back and bend your knees to lower into a squat.\",\"Push your knees out against the band.\",\"Stand up by driving through your heels.\"],\"img\":\"0784.webp\",\"gif\":\"0784.mp4\",\"cat\":\"strength\",\"desc\":\"A squat with a loop band around the legs or under the feet to add resistance. It builds the quads and glutes and keeps the knees pushing out.\"},{\"id\":\"2362\",\"n\":\"squat back (form check)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"hamstrings\"],\"st\":[\"Set the bar on your upper back, brace your core and squat down.\",\"Compare the faulty version with the correct one: your back stays flat and braced without rounding at the bottom.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2362.webp\",\"gif\":\"2362.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for back position during a squat, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"4160\",\"n\":\"squat hold calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"soleus\"],\"st\":[\"Stand with feet shoulder width apart and lower into a half squat.\",\"Hold that depth with your chest up.\",\"Raise your heels as high as you can.\",\"Lower your heels slowly.\",\"Repeat while holding the squat position.\",\"Keep your knees tracking over your toes.\"],\"img\":\"4160.webp\",\"gif\":\"4160.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a squat while lifting and lowering your heels. It combines quad endurance with calf work.\"},{\"id\":\"7556\",\"n\":\"squat jack\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"calves\"],\"st\":[\"Start in a squat with hands at your chest.\",\"Jump your feet out wide.\",\"Hop back to the narrow squat stance.\",\"Stay low the whole time.\",\"Land softly and keep your chest up.\"],\"img\":\"7556.webp\",\"gif\":\"7556.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jumping jack variation that stays in a squat for a leg-burning cardio move.\"},{\"id\":\"0785\",\"n\":\"squat jacks\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Start in a squat with hands together at your chest.\",\"Jump your feet wide while staying low in the squat.\",\"Jump your feet back together, still low.\",\"Keep your chest lifted and knees over your toes.\",\"Continue at a steady, quick pace.\"],\"img\":\"0785.webp\",\"gif\":\"0785.mp4\",\"cat\":\"cardio\",\"desc\":\"A cardio move that mixes a squat with a jumping jack. It raises your heart rate and burns the legs.\"},{\"id\":\"2360\",\"n\":\"squat knees middle position (form check)\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\"],\"st\":[\"Stand with feet shoulder width apart and begin to squat.\",\"Compare the faulty version with the correct one: your knees keep tracking in line with your toes on the way up and down.\",\"Perform the lift slowly with a light load and keep the correct position throughout.\",\"Use a mirror or film a set from the side to check your own position.\",\"Fix the cue before adding weight, and rest between sets so form stays clean.\"],\"img\":\"2360.webp\",\"gif\":\"2360.mp4\",\"cat\":\"strength\",\"desc\":\"A side-by-side form check for knee position midway through a squat, showing the common mistake next to the correct technique so you can spot it in your own sets.\"},{\"id\":\"2988\",\"n\":\"squat mobility\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"ankles\"],\"st\":[\"Stand with feet slightly wider than shoulder width.\",\"Sink into a deep squat, keeping your heels down.\",\"Press your elbows gently against your knees.\",\"Rock side to side and sit tall.\",\"Spend 30-45 seconds there, then stand up.\"],\"img\":\"2988.webp\",\"gif\":\"2988.mp4\",\"cat\":\"mobility\",\"desc\":\"A deep squat hold and rock that opens the hips and ankles.\"},{\"id\":\"2989\",\"n\":\"squat mobility complex\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"ankles\"],\"st\":[\"Stand with your feet a little wider than shoulder width and toes turned out slightly.\",\"Sink into a deep squat and keep your heels on the floor.\",\"Press your elbows against your knees to open the hips and hold for a moment.\",\"Shift gently from side to side, then rock forward and back.\",\"Stand up tall and repeat the flow for 6-8 rounds.\",\"Keep your chest lifted and your back long throughout.\"],\"img\":\"2989.webp\",\"gif\":\"2989.mp4\",\"cat\":\"mobility\",\"desc\":\"A short flow of deep squat positions that opens up the hips, knees and ankles. Good as a warm-up before leg work.\"},{\"id\":\"6139\",\"n\":\"squat mobility twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hip flexors\"],\"st\":[\"Lower into a deep squat with your feet shoulder-width apart.\",\"Place one hand on the floor or inside your knee.\",\"Rotate your chest and reach the other arm up toward the ceiling.\",\"Follow your hand with your eyes.\",\"Return to the center and switch sides.\",\"Keep your heels on the floor.\"],\"img\":\"6139.webp\",\"gif\":\"6139.mp4\",\"cat\":\"mobility\",\"desc\":\"A deep squat paired with a trunk rotation. It opens the hips and upper back and improves rotation.\"},{\"id\":\"10551\",\"n\":\"squat mobilization\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"hip flexors\",\"calves\",\"lower back\"],\"st\":[\"Stand with feet slightly wider than your shoulders.\",\"Squat down as deep as is comfortable.\",\"Press your elbows against your knees and keep your chest up.\",\"Rock gently side to side.\",\"Stay for 20-30 seconds, then stand.\"],\"img\":\"10551.webp\",\"gif\":\"10551.mp4\",\"cat\":\"mobility\",\"desc\":\"A deep squat hold with gentle movements. It opens up the hips and ankles.\"},{\"id\":\"1400\",\"n\":\"squat side kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Squat down with your chest up.\",\"Stand up and kick your right leg out to the side.\",\"Return the foot to the floor and drop into the next squat.\",\"Alternate sides each rep.\"],\"img\":\"1400.webp\",\"gif\":\"1400.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Squatting down and then kicking one leg out to the side. It trains the thighs and glutes.\"},{\"id\":\"3705\",\"n\":\"squat thrust\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"core\",\"chest\",\"triceps\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Squat down and place your hands on the floor.\",\"Kick your feet back into a plank.\",\"Jump your feet back toward your hands.\",\"Stand up and repeat at a steady pace.\"],\"img\":\"3705.webp\",\"gif\":\"3705.mp4\",\"cat\":\"cardio\",\"desc\":\"A burpee without the push-up and jump. You drop to a plank and spring back to your feet for a steady conditioning move.\"},{\"id\":\"3927\",\"n\":\"squat tip toe\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and rise onto your toes.\",\"Hold your arms in front for balance.\",\"Squat down while staying up on your toes.\",\"Pause at the bottom.\",\"Stand back up.\",\"Keep your chest tall.\"],\"img\":\"3927.webp\",\"gif\":\"3927.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat performed on your tiptoes that challenges balance, the quads and the calves.\"},{\"id\":\"3706\",\"n\":\"squat tuck jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Lower into a squat with your arms back.\",\"Explode upward and pull your knees toward your chest.\",\"Land softly with bent knees.\",\"Sink straight into the next squat and repeat.\"],\"img\":\"3706.webp\",\"gif\":\"3706.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat that explodes into a tuck jump. It trains explosive leg power and fast landings.\"},{\"id\":\"3001\",\"n\":\"squats knee position\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Stand with your feet shoulder width apart and toes slightly out.\",\"Brace your core and lift your chest.\",\"Bend at the hips and knees to lower into a squat.\",\"Push your knees out so they follow the line of your toes.\",\"Go down as deep as feels controlled.\",\"Drive up through your whole foot to stand.\"],\"img\":\"3001.webp\",\"gif\":\"3001.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat focused on where your knees travel, helping you learn to track them over your toes.\"},{\"id\":\"1893\",\"n\":\"squatting achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"hip flexors\"],\"st\":[\"Stand with your feet shoulder width apart.\",\"Sink into a deep squat with your heels down.\",\"Hold on to a support if needed.\",\"Gently shift your weight forward over your toes.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Stand up slowly.\"],\"img\":\"1893.webp\",\"gif\":\"1893.mp4\",\"cat\":\"stretching\",\"desc\":\"Deep squat hold that opens the ankles and calves.\"},{\"id\":\"1961\",\"n\":\"squatting toe stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\",\"shins\"],\"st\":[\"Crouch down with your heels lifted and toes tucked under.\",\"Place your hands on the floor in front of you for support.\",\"Slowly sit back toward your heels until you feel the toes and soles stretch.\",\"Ease off if the stretch is too sharp.\",\"Hold for 20-30 seconds, then release.\"],\"img\":\"1961.webp\",\"gif\":\"1961.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep squat on the balls of the feet that stretches the toes and the bottom of the feet.\"},{\"id\":\"3861\",\"n\":\"stability ball body saw\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"lower back\"],\"st\":[\"Place your forearms on a stability ball and extend your legs into a plank.\",\"Squeeze your glutes and brace your abs so your body forms a straight line.\",\"Slowly push your elbows forward a few inches by shifting your body weight.\",\"Pull back to the start without letting your hips sag.\",\"Keep the movement small and controlled.\",\"Repeat for time or reps.\"],\"img\":\"3861.webp\",\"gif\":\"3861.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank with your forearms on a stability ball, rocking back and forth to challenge deep core control.\"},{\"id\":\"1706\",\"n\":\"stability ball front plank\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Kneel behind a stability ball and place your forearms on it.\",\"Walk your feet back until your body forms a straight line from head to heels.\",\"Brace your abs and squeeze your glutes.\",\"Keep your neck neutral and your hips from sagging or rising.\",\"Hold for 20-40 seconds, then lower to the floor.\"],\"img\":\"1706.webp\",\"gif\":\"1706.mp4\",\"cat\":\"isometric\",\"desc\":\"A forearm plank with your elbows on a stability ball. The wobbly surface makes your abs and shoulders work harder to hold a straight line.\",\"hd\":1},{\"id\":\"3178\",\"n\":\"stability ball reverse hyperextension (off a bench)\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down with your hips over the ball and hands on the floor.\",\"Hold the bench or the ball for stability.\",\"Lift your legs until they are in line with your body.\",\"Squeeze your glutes at the top.\",\"Lower with control.\"],\"img\":\"3178.webp\",\"gif\":\"3178.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse hyperextension over a ball at the edge of a bench for glutes and lower back.\"},{\"id\":\"2296\",\"n\":\"stability ball rollout\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"shoulders\",\"lats\"],\"st\":[\"Kneel in front of a stability ball and place your forearms on it.\",\"Brace your abs and keep your body in a straight line from knees to head.\",\"Roll the ball forward by extending your arms and body.\",\"Stop when you feel your core working hard without your back sagging.\",\"Pull the ball back by squeezing your abs.\",\"Repeat slowly.\"],\"img\":\"2296.webp\",\"gif\":\"2296.mp4\",\"cat\":\"strength\",\"desc\":\"Rolling a ball forward with your forearms to challenge the abs and core stability.\"},{\"id\":\"7019\",\"n\":\"stability ball rollout on knees\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"shoulders\",\"lats\",\"core\"],\"st\":[\"Kneel facing a stability ball with your forearms resting on top.\",\"Brace your abs and keep your hips in line with your back.\",\"Roll the ball forward, extending your body.\",\"Stop before your lower back sags.\",\"Pull the ball back in using your abs.\"],\"img\":\"7019.webp\",\"gif\":\"7019.mp4\",\"cat\":\"strength\",\"desc\":\"A kneeling rollout with the forearms on a stability ball. It builds deep core strength.\",\"fv\":\"2295\"},{\"id\":\"2937\",\"n\":\"stability ball rounded rollout\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\"],\"st\":[\"Kneel in front of a stability ball with forearms on top.\",\"Round your back slightly and tuck your pelvis.\",\"Roll the ball forward by extending your arms.\",\"Pull it back using your abs.\",\"Keep your hips from sagging and move slowly.\"],\"img\":\"2937.webp\",\"gif\":\"2937.mp4\",\"cat\":\"strength\",\"desc\":\"A rollout on a stability ball with a rounded back that trains the abs hard.\"},{\"id\":\"1695\",\"n\":\"stability ball single leg squat\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"ankles\"],\"st\":[\"Place a stability ball between your lower back and a wall.\",\"Lift one foot and balance on the other leg.\",\"Lower into a squat while the ball rolls down the wall.\",\"Press through your heel to stand back up.\",\"Complete the reps, then switch legs.\"],\"img\":\"1695.webp\",\"gif\":\"1695.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat with a stability ball between your back and a wall for support, building one-sided leg strength.\"},{\"id\":\"7418\",\"n\":\"staggered leg glute bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your knees bent, one foot forward of the other.\",\"Press through both heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Keep your hips level.\",\"Lower slowly.\",\"Switch the foot position halfway through.\"],\"img\":\"7418.webp\",\"gif\":\"7418.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge with one foot placed forward to shift more load to one side.\"},{\"id\":\"4894\",\"n\":\"staggered leg side bridge\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"shoulders\"],\"st\":[\"Lie on your side with your forearm under your shoulder.\",\"Stagger your feet, top foot in front of the bottom one.\",\"Lift your hips so your body forms a straight line.\",\"Hold the position while breathing steadily.\",\"Keep the hips high and avoid rolling forward.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"4894.webp\",\"gif\":\"4894.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with the feet placed one in front of the other for a different base. It trains the obliques and hips.\",\"hd\":1},{\"id\":\"3720\",\"n\":\"stair jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\",\"core\"],\"st\":[\"Stand at the bottom of a staircase with your feet together.\",\"Bend your knees and swing your arms back.\",\"Jump up onto a step, landing softly with both feet.\",\"Step back down carefully.\",\"Reset and repeat.\"],\"img\":\"3720.webp\",\"gif\":\"3720.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Explosive jumps up a flight of stairs that build leg power and speed.\"},{\"id\":\"3009\",\"n\":\"stair up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand at the bottom of a staircase, standing tall.\",\"Step up with one foot, placing your whole foot on the step.\",\"Press through your heel and bring the other foot up.\",\"Keep your torso upright and swing your arms naturally.\",\"Continue at a steady pace and alternate the leading leg.\"],\"img\":\"3009.webp\",\"gif\":\"3009.mp4\",\"cat\":\"cardio\",\"desc\":\"Stepping up stairs at a steady pace to train the legs and raise your heart rate.\"},{\"id\":\"11878\",\"n\":\"stall bar leg raise\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"forearms\"],\"st\":[\"Hang on a stall bar with arms straight.\",\"Brace your core and keep your body still.\",\"Raise your legs up in front of you.\",\"Lift as high as you can without swinging.\",\"Lower slowly and repeat.\"],\"img\":\"11878.webp\",\"gif\":\"11878.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hanging leg raise performed on stall bars.\"},{\"id\":\"0960\",\"n\":\"stand spread leg forward fold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"groin\",\"lower back\"],\"st\":[\"Stand with feet wide apart and toes pointing forward.\",\"Hinge forward at the hips with a long spine.\",\"Lower your hands to the floor or your shins.\",\"Relax your head and neck.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0960.webp\",\"gif\":\"0960.mp4\",\"cat\":\"stretching\",\"desc\":\"Fold forward from a wide-legged stance to stretch the inner thighs and hamstrings.\"},{\"id\":\"5126\",\"n\":\"standing ab twist\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand with feet shoulder-width apart, arms bent in front of your chest.\",\"Keep your hips facing forward.\",\"Rotate your upper body to one side.\",\"Come back through the center and rotate the other way.\",\"Keep a smooth rhythm for 20-30 twists.\"],\"img\":\"5126.webp\",\"gif\":\"5126.mp4\",\"cat\":\"mobility\",\"desc\":\"Twist your torso from side to side while standing. It warms up the trunk and works the obliques lightly.\",\"fv\":\"5085\"},{\"id\":\"5445\",\"n\":\"standing abdominal vacuum\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\"],\"st\":[\"Stand tall with your hands on your hips and feet hip-width apart.\",\"Exhale fully until your lungs feel empty.\",\"Pull your belly button toward your spine and hold it there.\",\"Hold for 10-20 seconds without breathing in deeply.\",\"Relax and breathe normally, then repeat.\"],\"img\":\"5445.webp\",\"gif\":\"5445.mp4\",\"cat\":\"isometric\",\"desc\":\"Drawing your belly in as far as you can while standing. Trains the deep abdominal muscles that keep your trunk tight.\"},{\"id\":\"2110\",\"n\":\"standing abs rotation stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"lower back\"],\"st\":[\"Stand tall with feet hip-width apart and arms relaxed.\",\"Place your hands on your hips or hold them out to the sides.\",\"Keep the hips facing forward and turn your upper body slowly to one side.\",\"Look over your shoulder and breathe steadily.\",\"Hold for 20-30 seconds.\",\"Return to the front and rotate to the other side.\"],\"img\":\"2110.webp\",\"gif\":\"2110.mp4\",\"cat\":\"stretching\",\"desc\":\"Rotates the upper body from a standing position to stretch the abs and obliques and loosen the trunk.\",\"fv\":\"4268\"},{\"id\":\"1888\",\"n\":\"standing achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand near a wall or support.\",\"Step one foot back with the heel down.\",\"Slightly bend the back knee to target the lower Achilles.\",\"Keep your back foot pointing forward.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1888.webp\",\"gif\":\"1888.mp4\",\"cat\":\"stretching\",\"desc\":\"Simple standing stretch for the Achilles tendon and calf.\"},{\"id\":\"3999\",\"n\":\"standing air bike\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Stand with hands behind your head.\",\"Lift one knee while rotating your torso.\",\"Touch your elbow to the knee.\",\"Switch sides in a pedaling rhythm.\",\"Stay upright.\"],\"img\":\"3999.webp\",\"gif\":\"3999.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing cycling crunch bringing the elbow to the opposite knee. It trains the abs and obliques.\",\"fv\":\"4275\"},{\"id\":\"3259\",\"n\":\"standing alternate arms circling\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with feet hip-width apart and arms hanging at your sides.\",\"Swing one arm forward, up and back in a large smooth circle.\",\"As that arm finishes, start the same circle with the other arm.\",\"Keep your ribs down and your neck relaxed.\",\"Continue alternating for 20-30 seconds, then reverse the direction.\"],\"img\":\"3259.webp\",\"gif\":\"3259.mp4\",\"cat\":\"mobility\",\"desc\":\"Big alternating arm circles that warm up the shoulder joints and loosen the upper back before pressing or pulling work.\"},{\"id\":\"9185\",\"n\":\"standing alternating shoulder flexion with rope\",\"bp\":\"shoulders\",\"eq\":\"rope\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"forearms\"],\"st\":[\"Stand tall holding a rope in one hand at your side.\",\"Raise your arm forward to shoulder height or above.\",\"Hold briefly at the top.\",\"Lower it slowly.\",\"Alternate arms each rep.\",\"Keep your ribs down and shoulders relaxed.\"],\"img\":\"9185.webp\",\"gif\":\"9185.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing drill that lifts one arm at a time in front of you while holding a rope. It warms the shoulders and improves control.\"},{\"id\":\"11289\",\"n\":\"standing ankle and hip drill\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"hip flexors\",\"glutes\"],\"st\":[\"Stand tall with your feet hip width.\",\"Shift your weight onto one foot.\",\"Rotate your ankle and hip through a smooth circle.\",\"Keep your upper body steady.\",\"Do 8-10 slow reps, then switch sides.\"],\"img\":\"11289.webp\",\"gif\":\"11289.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing drill that loosens the ankles and hips. It is a good warm-up for squats and lunges.\"},{\"id\":\"8188\",\"n\":\"standing ankle circles v. 2\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"shins\"],\"st\":[\"Stand tall and hold a wall or chair for balance.\",\"Lift one foot slightly off the floor.\",\"Draw slow circles with your toes.\",\"Do about 10 circles in one direction.\",\"Switch to the other direction.\",\"Change feet and repeat.\"],\"img\":\"8188.webp\",\"gif\":\"8188.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing mobility drill that rotates the ankle through its full range. It warms up the ankle joints.\"},{\"id\":\"3258\",\"n\":\"standing arms circling\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with feet shoulder-width apart.\",\"Extend both arms out to the sides.\",\"Make slow circles forward.\",\"Then reverse direction.\",\"Keep your shoulders relaxed.\"],\"img\":\"3258.webp\",\"gif\":\"3258.mp4\",\"cat\":\"mobility\",\"desc\":\"Big arm circles with both arms to warm up the shoulders.\"},{\"id\":\"3260\",\"n\":\"standing arms flinging\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\"],\"st\":[\"Stand tall with feet shoulder-width apart and arms out in front at chest height.\",\"Fling both arms wide open to the sides, squeezing your shoulder blades together.\",\"Swing them back across your body, letting one arm cross over the other.\",\"Keep the motion loose and controlled, without arching your back.\",\"Repeat for 15-20 swings.\"],\"img\":\"3260.webp\",\"gif\":\"3260.mp4\",\"cat\":\"mobility\",\"desc\":\"Open and close your arms in a relaxed fling to loosen the chest and shoulders. Handy as a quick warm-up.\"},{\"id\":\"10922\",\"n\":\"standing back achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall and step one foot back.\",\"Keep the back heel down and the knee slightly bent.\",\"Lean forward until you feel the stretch low in the calf.\",\"Hold for 20-30 seconds.\",\"Switch legs.\"],\"img\":\"10922.webp\",\"gif\":\"10922.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch for the back of the lower leg and the Achilles area.\"},{\"id\":\"3855\",\"n\":\"standing back extension and flexion\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"core\"],\"st\":[\"Stand with your feet hip width apart and hands on your hips.\",\"Gently arch your back and look slightly up.\",\"Round your back and tuck your chin.\",\"Move slowly between positions.\",\"Stay within a comfortable range.\"],\"img\":\"3855.webp\",\"gif\":\"3855.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing movement where you arch and then round your back. It warms up your spine.\"},{\"id\":\"1813\",\"n\":\"standing back rotation stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and your arms at chest height.\",\"Rotate your upper body to one side, keeping your hips facing forward.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1813.webp\",\"gif\":\"1813.mp4\",\"cat\":\"stretching\",\"desc\":\"Rotating through your trunk while standing stretches your back and obliques. It is a quick way to loosen up your torso.\",\"fv\":\"4316\"},{\"id\":\"6750\",\"n\":\"standing balance hip rotation\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"ankles\"],\"st\":[\"Stand tall on one leg with a soft knee, holding a wall if needed.\",\"Lift the other knee to hip height.\",\"Rotate the lifted knee out to the side, then back to the front.\",\"Keep your torso steady.\",\"Move slowly and smoothly.\",\"Finish the reps, then switch legs.\"],\"img\":\"6750.webp\",\"gif\":\"6750.mp4\",\"cat\":\"mobility\",\"desc\":\"A one-leg balance with controlled hip rotation. It works hip mobility and stability together.\"},{\"id\":\"3473\",\"n\":\"standing balance outer hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"ankles\"],\"st\":[\"Stand tall near a support.\",\"Cross one ankle over the opposite knee.\",\"Sit back slightly.\",\"Feel the stretch in your outer hip.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"3473.webp\",\"gif\":\"3473.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch for the outer hip that also challenges balance.\"},{\"id\":\"3504\",\"n\":\"standing balance quadriceps stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"ankles\",\"core\"],\"st\":[\"Stand tall, holding a wall for balance if needed.\",\"Bend one knee and grab your ankle behind you.\",\"Pull your heel toward your glutes with knees together.\",\"Keep your hips tucked and your chest up.\",\"Hold for 20-30 seconds.\",\"Release and switch legs.\"],\"img\":\"3504.webp\",\"gif\":\"3504.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing quad stretch with balance. It lengthens the front of the thigh and hips.\"},{\"id\":\"10188\",\"n\":\"standing bend alternating toe touch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"obliques\",\"lower back\"],\"st\":[\"Stand tall with your feet wider than your hips and arms out to the sides.\",\"Hinge forward and twist to reach one hand toward the opposite foot.\",\"Return to standing with arms out.\",\"Reach the other hand to the opposite foot.\",\"Keep a flat back and move at a lively pace.\"],\"img\":\"10188.webp\",\"gif\":\"10188.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick standing toe touch where you reach to opposite feet in turn, warming up the hamstrings and midsection.\"},{\"id\":\"9411\",\"n\":\"standing bent knee alternating calf raise with a chair support\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand behind a chair and hold it with both hands.\",\"Bend your knees slightly.\",\"Raise one heel as high as possible.\",\"Lower it slowly.\",\"Raise the other heel.\",\"Keep alternating without locking your knees.\"],\"img\":\"9411.webp\",\"gif\":\"9411.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An alternating calf raise with the knees bent, using a chair for balance. It works the soleus one side at a time.\"},{\"id\":\"9409\",\"n\":\"standing bent knee calf raise with a chair support\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand behind a chair and hold it for balance.\",\"Bend your knees slightly.\",\"Raise your heels as high as you can.\",\"Pause at the top.\",\"Lower your heels slowly.\",\"Keep your knees bent throughout.\"],\"img\":\"9409.webp\",\"gif\":\"9409.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A calf raise with the knees slightly bent while holding a chair. It targets the deeper soleus muscle.\"},{\"id\":\"4944\",\"n\":\"standing bent knee figure 8\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"adductors\"],\"st\":[\"Stand tall and hold a support if needed.\",\"Lift one knee in front of you.\",\"Trace a slow figure eight with your knee.\",\"Keep your standing leg steady.\",\"Keep your torso upright.\",\"Switch legs.\"],\"img\":\"4944.webp\",\"gif\":\"4944.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing hip mobility move where you draw a figure eight with the bent knee. It loosens the hips.\"},{\"id\":\"1900\",\"n\":\"standing bent knee hip adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Stand with your feet wide.\",\"Bend one knee and lower into that side.\",\"Keep your other leg straight.\",\"Push the bent knee gently out with your hand.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1900.webp\",\"gif\":\"1900.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing stretch with a bent knee that opens the inner thigh and hip.\"},{\"id\":\"3018\",\"n\":\"standing calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Rise up onto the balls of your feet as high as you can.\",\"Pause at the top for a second.\",\"Lower your heels slowly back to the floor.\",\"Hold a wall for balance if needed.\"],\"img\":\"3018.webp\",\"gif\":\"3018.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight calf raise that builds lower-leg strength and ankle stability.\"},{\"id\":\"4895\",\"n\":\"standing calf raise circle\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall with feet hip width apart and hold a support if needed.\",\"Rise onto the balls of your feet.\",\"Trace a small circle with your heels while staying high.\",\"Lower your heels slowly to the floor.\",\"Reverse the circle direction on the next rep.\",\"Keep your knees straight and your balance steady.\"],\"img\":\"4895.webp\",\"gif\":\"4895.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A calf raise that finishes with a small circle of the heels. It works the calves and the ankle control.\"},{\"id\":\"3120\",\"n\":\"standing calf raise with support\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand holding a wall or rail for balance.\",\"Place your feet hip-width apart.\",\"Rise up on your toes as high as you can.\",\"Pause and squeeze your calves.\",\"Lower slowly.\"],\"img\":\"3120.webp\",\"gif\":\"3120.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A calf raise holding on for balance, so you can focus on the calves.\"},{\"id\":\"1783\",\"n\":\"standing chest stretch (with training wall bars)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand beside wall bars and grip a bar at about shoulder height with one hand.\",\"Slowly turn your body away from the bars until you feel a stretch across your chest.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1783.webp\",\"gif\":\"1783.mp4\",\"cat\":\"stretching\",\"desc\":\"Holding a wall bar and turning away from it stretches your chest and shoulder. The bars let you pick the exact height that suits you.\"},{\"id\":\"5557\",\"n\":\"standing chest stretch against door\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Stand in a doorway with your forearm against the frame, elbow at shoulder height.\",\"Step through gently with the opposite foot.\",\"Turn away until you feel a chest stretch.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"5557.webp\",\"gif\":\"5557.mp4\",\"cat\":\"stretching\",\"desc\":\"Doorway stretch for the chest and front of the shoulders.\"},{\"id\":\"9942\",\"n\":\"standing cross legs core stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand tall and cross one leg in front of the other.\",\"Raise the arm on the same side as the back leg overhead.\",\"Reach and lean gently toward the opposite side.\",\"Feel the stretch along your side and abs.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Return to standing and repeat on the other side.\"],\"img\":\"9942.webp\",\"gif\":\"9942.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch with your legs crossed that lengthens the sides of the trunk. It loosens the obliques and waist.\"},{\"id\":\"10931\",\"n\":\"standing external rotation behind back with towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"shoulders\"],\"st\":[\"Stand tall holding a towel behind your back with both hands.\",\"Keep the lower hand still and pull the upper hand away.\",\"Rotate the upper shoulder outward.\",\"Hold briefly and release.\",\"Finish your reps, then switch hands.\"],\"img\":\"10931.webp\",\"gif\":\"10931.mp4\",\"cat\":\"rehab\",\"desc\":\"Holding a towel behind your back to rotate the shoulder outward. It improves shoulder control.\"},{\"id\":\"10930\",\"n\":\"standing external rotation slide with towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"shoulders\"],\"st\":[\"Stand side-on to a wall with a towel under your forearm.\",\"Keep your elbow at 90 degrees, tucked at your side.\",\"Slide your hand outward along the wall.\",\"Return slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"10930.webp\",\"gif\":\"10930.mp4\",\"cat\":\"rehab\",\"desc\":\"A towel slide that rotates the shoulder outward. It strengthens the back of the shoulder.\"},{\"id\":\"5902\",\"n\":\"standing figure four pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"core\",\"ankles\"],\"st\":[\"Stand tall and shift your weight onto one leg.\",\"Cross the other ankle over the standing thigh.\",\"Bend your standing knee and sit your hips back.\",\"Hold for 5 slow breaths with a long spine.\",\"Switch legs.\"],\"img\":\"5902.webp\",\"gif\":\"5902.mp4\",\"cat\":\"yoga\",\"desc\":\"A one-leg balance with the ankle crossed over the opposite knee. Stretches the outer hip.\"},{\"id\":\"10859\",\"n\":\"standing floor tibialis raise wall supported\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Stand with your back and hips against a wall, feet a little way out in front.\",\"Keep your legs straight and your heels planted on the floor.\",\"Pull your toes up toward your shins as high as you can.\",\"Pause briefly at the top.\",\"Lower your toes slowly and repeat.\"],\"img\":\"10859.webp\",\"gif\":\"10859.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Standing with your back against a wall, you lift your toes off the floor. It strengthens the muscles on the front of the shin.\"},{\"id\":\"6775\",\"n\":\"standing foot muscles activation\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\",\"shins\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Spread your toes wide and press all of them into the floor.\",\"Lift your toes while keeping the ball of the foot down.\",\"Lower them one by one.\",\"Keep your arch lifted.\",\"Repeat for 10-15 slow reps.\"],\"img\":\"6775.webp\",\"gif\":\"6775.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing drill that wakes up the small muscles of the feet. It builds foot control and balance.\"},{\"id\":\"0959\",\"n\":\"standing forward bend uttanasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\",\"core\"],\"st\":[\"Stand with feet hip-width apart.\",\"Hinge at your hips and fold forward, keeping your knees slightly soft.\",\"Let your hands rest on the floor or hold opposite elbows.\",\"Relax your neck and let the weight of your head drop.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0959.webp\",\"gif\":\"0959.mp4\",\"cat\":\"stretching\",\"desc\":\"Fold forward from standing and let the head hang. It lengthens the hamstrings and back.\"},{\"id\":\"10927\",\"n\":\"standing forward slide press with towel\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand facing a wall and place a towel under your hand against it.\",\"Keep your elbow bent and the hand at chest height.\",\"Slide the towel forward as your arm straightens.\",\"Slide it back slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"10927.webp\",\"gif\":\"10927.mp4\",\"cat\":\"rehab\",\"desc\":\"A towel slid forward along a wall that presses the arm out. It builds gentle shoulder control.\"},{\"id\":\"11653\",\"n\":\"standing glute squeeze\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Stand tall with your feet hip width apart and your arms relaxed.\",\"Tighten your abs lightly so your ribs stay stacked over your hips.\",\"Squeeze your glutes together as hard as you comfortably can.\",\"Hold for 3-5 seconds without leaning back or tucking your hips excessively.\",\"Relax fully, then repeat for 10-15 reps.\"],\"img\":\"11653.webp\",\"gif\":\"11653.mp4\",\"cat\":\"isometric\",\"desc\":\"A simple standing contraction that wakes up the glutes and helps you feel them working before heavier lifts.\"},{\"id\":\"5903\",\"n\":\"standing half bend\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"calves\",\"glutes\"],\"st\":[\"Stand with your feet hip-width apart.\",\"Hinge forward from your hips and bring your hands to your shins or thighs.\",\"Lengthen your spine until your back is flat.\",\"Hold for 5 slow breaths.\",\"Roll up slowly to stand.\"],\"img\":\"5903.webp\",\"gif\":\"5903.mp4\",\"cat\":\"yoga\",\"desc\":\"A halfway forward fold with a flat back. Lengthens the back of the legs.\"},{\"id\":\"11904\",\"n\":\"standing half kneeling hip flexors stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Kneel on one knee with the other foot forward and a pad under your knee.\",\"Keep your torso upright and tuck your pelvis under.\",\"Shift your weight forward until you feel a stretch at the front of the back hip.\",\"Keep your front knee over your ankle and your core engaged.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"11904.webp\",\"gif\":\"11904.mp4\",\"cat\":\"stretching\",\"desc\":\"A half-kneeling position that opens the front of the hip and the quad of the back leg.\"},{\"id\":\"0789\",\"n\":\"standing hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Stand tall and place one heel forward on the floor with the toes up.\",\"Keep that leg straight and the other knee slightly bent.\",\"Hinge forward at the hips with a flat back until you feel a stretch.\",\"Hold for 20-30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"0789.webp\",\"gif\":\"0789.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple standing stretch for the back of the thigh. It helps loosen tight hamstrings.\"},{\"id\":\"3630\",\"n\":\"standing hamstrings and back stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"calves\",\"glutes\"],\"st\":[\"Stand tall with feet hip width apart.\",\"Hinge forward at the hips with a long spine.\",\"Let your arms hang toward the floor.\",\"Keep your knees soft.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Release slowly and repeat on the other side if needed.\"],\"img\":\"3630.webp\",\"gif\":\"3630.mp4\",\"cat\":\"stretching\",\"desc\":\"Fold forward from standing to lengthen the hamstrings and lower back.\"},{\"id\":\"5286\",\"n\":\"standing hands position (pronation supination neutral)\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Stand tall with your arms hanging by your sides.\",\"Bend your elbows and hold your forearms in front of you.\",\"Rotate your palms down, then to neutral, then up.\",\"Move slowly and keep your elbows still.\",\"Repeat for several smooth rounds.\"],\"img\":\"5286.webp\",\"gif\":\"5286.mp4\",\"cat\":\"mobility\",\"desc\":\"A forearm drill that rotates the hands through pronation, neutral and supination. It builds wrist and forearm control.\"},{\"id\":\"1887\",\"n\":\"standing heel back achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\"],\"st\":[\"Stand facing a wall and step one foot back.\",\"Keep the back leg straight and the heel down.\",\"Bend your front knee and lean forward.\",\"Feel the stretch in the back calf.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1887.webp\",\"gif\":\"1887.mp4\",\"cat\":\"stretching\",\"desc\":\"Classic lunge-style calf stretch with the back heel kept down.\"},{\"id\":\"1912\",\"n\":\"standing high leg bent knee hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Stand tall and place one heel on a high support with the knee slightly bent.\",\"Lean your chest toward your thigh with a flat back until you feel the stretch behind the thigh.\",\"Straighten the knee a little more as you get looser.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1912.webp\",\"gif\":\"1912.mp4\",\"cat\":\"stretching\",\"desc\":\"A hamstring stretch with the foot raised high and the knee slightly bent for a deeper but friendlier pull.\"},{\"id\":\"0791\",\"n\":\"standing hip abduction\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Stand tall beside a wall or chair for balance.\",\"Keep your hips square and toes pointing forward.\",\"Lift one leg out to the side with the knee straight.\",\"Pause briefly at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"0791.webp\",\"gif\":\"0791.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raising a straight leg out to the side while standing. It strengthens the outer hip and glutes.\"},{\"id\":\"0790\",\"n\":\"standing hip abduction (bent knee)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Stand tall and hold onto a support if needed.\",\"Shift your weight onto one leg and bend the other knee.\",\"Lift the bent knee out to the side without leaning.\",\"Lower with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"0790.webp\",\"gif\":\"0790.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lifting a bent knee out to the side while standing. It works the outer hip and glutes and trains balance.\"},{\"id\":\"1941\",\"n\":\"standing hip adduction stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Stand tall and cross one leg behind the other, feet close together.\",\"Lean your torso away from the back leg and push the hip out slightly until you feel the outer hip stretch.\",\"Keep both feet flat on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1941.webp\",\"gif\":\"1941.mp4\",\"cat\":\"stretching\",\"desc\":\"Crossing one leg behind the other and leaning aside to stretch the outer hip.\"},{\"id\":\"5169\",\"n\":\"standing hip adduction v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\",\"core\"],\"st\":[\"Stand tall next to a wall or chair and hold on for balance.\",\"Lift the outer leg slightly off the floor.\",\"Swing it across the front of your standing leg.\",\"Return slowly to the start without leaning.\",\"Finish your reps, then turn around and switch legs.\"],\"img\":\"5169.webp\",\"gif\":\"5169.mp4\",\"cat\":\"strength\",\"desc\":\"Standing leg swings across the body to work the inner thigh. A simple move for the adductors.\"},{\"id\":\"3411\",\"n\":\"standing hip circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"obliques\"],\"st\":[\"Stand with feet shoulder-width apart and hands on your hips.\",\"Push your hips out to one side, then forward, back and around.\",\"Draw a large smooth circle.\",\"Keep your shoulders still.\",\"Do 10 circles, then reverse direction.\"],\"img\":\"3411.webp\",\"gif\":\"3411.mp4\",\"cat\":\"mobility\",\"desc\":\"Circle your hips to loosen the hip joints and warm up the glutes.\"},{\"id\":\"0792\",\"n\":\"standing hip extension (bent knee)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Stand tall holding a support, with your core tight.\",\"Shift onto one leg and bend the other knee.\",\"Press that heel back and up, squeezing your glute.\",\"Do not arch your lower back.\",\"Lower with control, then switch legs after your reps.\"],\"img\":\"0792.webp\",\"gif\":\"0792.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Driving a bent knee back behind you while standing. It targets the glutes with a short, controlled range.\"},{\"id\":\"2737\",\"n\":\"standing hip extension (straight leg)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Stand tall and hold a support for balance.\",\"Keep your standing knee slightly soft.\",\"Lift one straight leg back behind you without arching your lower back.\",\"Squeeze the glute at the top.\",\"Lower with control and switch legs after your reps.\"],\"img\":\"2737.webp\",\"gif\":\"2737.mp4\",\"cat\":\"strength\",\"desc\":\"A standing kickback with a straight leg that targets the glutes.\"},{\"id\":\"1949\",\"n\":\"standing hip flexor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Stand and step one foot forward and the other back into a staggered stance.\",\"Tuck your pelvis and squeeze the glute of the back leg.\",\"Shift your hips slightly forward until you feel a stretch at the front of the back hip.\",\"Keep your torso upright.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1949.webp\",\"gif\":\"1949.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing lunge-style stretch for the front of the hip and thigh.\"},{\"id\":\"11903\",\"n\":\"standing hip flexors stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Stand tall and hold a wall or support for balance.\",\"Bend one knee and bring your heel toward your glute, holding the ankle.\",\"Tuck your pelvis slightly and push your hips gently forward.\",\"Keep your knees close together and your chest upright.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"11903.webp\",\"gif\":\"11903.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch for the front of the hip and thigh, useful after long periods of sitting.\"},{\"id\":\"1877\",\"n\":\"standing hip out aductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Stand tall with your feet wider than hip width.\",\"Shift your weight onto one leg and bend that knee.\",\"Keep the other leg straight, foot flat.\",\"Push your hip out until you feel a stretch in the inner thigh.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1877.webp\",\"gif\":\"1877.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing stretch that pushes the hip out to the side to lengthen the inner thigh.\"},{\"id\":\"1942\",\"n\":\"standing iliotibial stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Stand next to a wall or support and cross your outer leg behind the other.\",\"Lean your hips toward the wall and reach the outer arm overhead until the outside of the hip and thigh stretches.\",\"Keep your chest facing forward.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1942.webp\",\"gif\":\"1942.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side lean that stretches the iliotibial band along the outside of the thigh.\"},{\"id\":\"10929\",\"n\":\"standing internal rotation slide with towel\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"rotator cuff\"],\"st\":[\"Stand side-on to a wall with a towel under your forearm.\",\"Bend your elbow to 90 degrees against your side.\",\"Slide your hand across your body along the wall.\",\"Return slowly.\",\"Finish your reps, then switch arms.\"],\"img\":\"10929.webp\",\"gif\":\"10929.mp4\",\"cat\":\"rehab\",\"desc\":\"A towel slide that rotates the shoulder inward. It works the rotator cuff gently.\"},{\"id\":\"10138\",\"n\":\"standing isometric biceps hold\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Stand tall with feet hip width apart and your elbows at your sides.\",\"Bend your elbows to about 90 degrees with palms facing up.\",\"Squeeze your fists and flex your biceps hard.\",\"Hold the position for 20-30 seconds, breathing steadily.\",\"Keep your shoulders relaxed and elbows pinned, then rest and repeat.\"],\"img\":\"10138.webp\",\"gif\":\"10138.mp4\",\"cat\":\"isometric\",\"desc\":\"A static curl hold where you keep the elbows bent and the biceps working without moving.\",\"hd\":1},{\"id\":\"9310\",\"n\":\"standing isometric hold calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall with your feet hip width apart.\",\"Rise onto the balls of your feet.\",\"Hold the top position for 20 to 30 seconds.\",\"Keep your ankles straight and stable.\",\"Lower your heels slowly.\",\"Rest briefly between holds.\"],\"img\":\"9310.webp\",\"gif\":\"9310.mp4\",\"cat\":\"isometric\",\"desc\":\"A standing calf raise held at the top. It builds calf endurance.\",\"hd\":1},{\"id\":\"10126\",\"n\":\"standing isometric shoulder external rotation with towel\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"upper back\"],\"st\":[\"Stand next to a wall with a towel between the back of your hand and the wall.\",\"Bend your elbow to 90 degrees, tucked at your side.\",\"Press your hand outward into the towel.\",\"Hold the effort for 10 to 20 seconds.\",\"Relax, then switch sides.\"],\"img\":\"10126.webp\",\"gif\":\"10126.mp4\",\"cat\":\"isometric\",\"desc\":\"Press the back of your hand into a towel on a wall while standing. It trains the rotator cuff without moving the joint.\",\"hd\":1},{\"id\":\"9990\",\"n\":\"standing isometric shoulder internal rotation against wall\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"lats\"],\"st\":[\"Stand sideways to a wall with your elbow bent to 90 degrees and tucked at your side.\",\"Place the inside of your fist or forearm against the wall.\",\"Press into the wall as if rotating your arm inward.\",\"Hold the contraction for 5-10 seconds.\",\"Relax and rest briefly.\",\"Keep your elbow at your side, then switch arms.\"],\"img\":\"9990.webp\",\"gif\":\"9990.mp4\",\"cat\":\"isometric\",\"desc\":\"An isometric hold pressing the inner forearm into a wall to work the shoulder rotators. There is no movement, only steady tension.\",\"hd\":1},{\"id\":\"1811\",\"n\":\"standing knee to chest stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall, using a wall for balance if needed.\",\"Lift one knee and pull it gently toward your chest with both hands.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1811.webp\",\"gif\":\"1811.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing on one leg and hugging the other knee to your chest stretches your glutes and tests your balance. A good warm-up move.\",\"fv\":\"8062\"},{\"id\":\"2117\",\"n\":\"standing lateral side stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Stand tall with your feet hip width apart.\",\"Reach one arm overhead and bend sideways away from it until you feel the side stretch.\",\"Keep your chest open and your hips level.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2117.webp\",\"gif\":\"2117.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side bend for the sides of the waist and ribs.\"},{\"id\":\"2108\",\"n\":\"standing lean back stomach stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Stand tall with your hands on your hips.\",\"Gently lean back and push your hips slightly forward until you feel a stretch across the stomach.\",\"Keep your movement small and avoid cranking your lower back.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"2108.webp\",\"gif\":\"2108.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing lean back that stretches the abdominal wall.\"},{\"id\":\"4933\",\"n\":\"standing leg circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\",\"core\"],\"st\":[\"Stand tall and hold a support for balance.\",\"Lift one leg slightly off the floor.\",\"Draw a smooth circle with the leg.\",\"Keep your torso still.\",\"Reverse the direction after several reps.\",\"Switch legs.\"],\"img\":\"4933.webp\",\"gif\":\"4933.mp4\",\"cat\":\"mobility\",\"desc\":\"Circles with a straight leg while standing. It loosens the hips and warms up the glutes.\"},{\"id\":\"1878\",\"n\":\"standing leg cross abductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Stand tall, next to a wall if you need balance.\",\"Cross one leg behind the other.\",\"Lean your hips toward the side of your back leg.\",\"Feel the stretch along the outer hip.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1878.webp\",\"gif\":\"1878.mp4\",\"cat\":\"stretching\",\"desc\":\"Cross one leg behind the other to stretch the outer hip and thigh.\"},{\"id\":\"1879\",\"n\":\"standing leg resting hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\"],\"st\":[\"Stand facing a bench or step.\",\"Place one heel on it with the knee slightly bent.\",\"Keep your chest tall and hinge forward at the hips.\",\"Feel the stretch in the hip and glute.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1879.webp\",\"gif\":\"1879.mp4\",\"cat\":\"stretching\",\"desc\":\"Rest one leg on a raised surface and lean in to stretch the hips.\"},{\"id\":\"4380\",\"n\":\"standing leg slide with towel\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"core\",\"hip flexors\"],\"st\":[\"Stand on a smooth floor with one foot on a towel and hold a support if needed.\",\"Bend the standing knee slightly and keep your chest tall.\",\"Slide the towel foot out to the side or back as far as you can control.\",\"Pull it back to the start using your hip and thigh muscles.\",\"Complete your reps, then switch legs.\"],\"img\":\"4380.webp\",\"gif\":\"4380.mp4\",\"cat\":\"strength\",\"desc\":\"A standing exercise where one foot slides on a towel to work the hips and thighs while the standing leg balances you.\"},{\"id\":\"1946\",\"n\":\"standing leg tuck hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\"],\"st\":[\"Stand tall, holding a wall or support for balance.\",\"Lift one knee and hold the shin and ankle with both hands.\",\"Pull the leg gently toward your chest and slightly across the body.\",\"Keep your standing leg soft and your back straight.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1946.webp\",\"gif\":\"1946.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch drawing one knee up and in to open the hip and glutes.\"},{\"id\":\"1881\",\"n\":\"standing leg under abductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Stand tall near a support.\",\"Pass one leg behind and under the other.\",\"Push your hips gently to the side of the back leg.\",\"Keep your torso upright.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1881.webp\",\"gif\":\"1881.mp4\",\"cat\":\"stretching\",\"desc\":\"Tuck one leg under the other in standing to stretch the outer hip.\"},{\"id\":\"1897\",\"n\":\"standing leg up adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"groin\"],\"st\":[\"Stand next to a bench or low support.\",\"Place one foot on it with the leg out to the side.\",\"Keep your hips square.\",\"Shift your weight toward the raised leg.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1897.webp\",\"gif\":\"1897.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretch for the inner thigh with one leg raised and out to the side.\"},{\"id\":\"1910\",\"n\":\"standing leg up hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Stand facing a low support and place one heel on it with the leg straight.\",\"Hinge forward from the hips with a long back until you feel the back of the thigh stretch.\",\"Keep your toes pointing up and your standing knee soft.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1910.webp\",\"gif\":\"1910.mp4\",\"cat\":\"stretching\",\"desc\":\"Rest one heel on a raised surface and lean forward to stretch the back of the thigh.\"},{\"id\":\"1600\",\"n\":\"standing long jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with feet shoulder-width apart at a clear starting line.\",\"Swing your arms back and bend your knees.\",\"Swing your arms forward and jump as far as you can.\",\"Land on both feet with your knees bent to absorb the impact.\",\"Reset and repeat.\"],\"img\":\"1600.webp\",\"gif\":\"1600.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump for distance from a standing start. It builds explosive power in the hips and legs.\",\"fv\":\"2548\"},{\"id\":\"3407\",\"n\":\"standing low body rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with feet slightly wider than your hips and knees soft.\",\"Hold your hands in front of your waist.\",\"Rotate your hips and trunk to one side.\",\"Return through the centre and rotate to the other side.\",\"Move smoothly for 10-15 reps per side.\"],\"img\":\"3407.webp\",\"gif\":\"3407.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing trunk rotation at lower body level to loosen the hips and waist.\"},{\"id\":\"2113\",\"n\":\"standing lower trunk lateral flexor stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with feet slightly wider than hip-width.\",\"Place one hand on your hip and reach the other arm overhead.\",\"Push the hips slightly to the side opposite your reach.\",\"Bend sideways from the waist without leaning forward or back.\",\"Hold for 20-30 seconds.\",\"Return to upright and switch sides.\"],\"img\":\"2113.webp\",\"gif\":\"2113.mp4\",\"cat\":\"stretching\",\"desc\":\"Bends the lower trunk sideways from a standing position to stretch the muscles along the flank and low back.\"},{\"id\":\"1058\",\"n\":\"standing one arm chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"biceps\"],\"st\":[\"Stand next to a wall or door frame.\",\"Place your forearm or hand on the wall at shoulder height.\",\"Slowly turn your body away from the arm.\",\"Hold for 20-30 seconds.\",\"Switch arms and repeat.\"],\"img\":\"1058.webp\",\"gif\":\"1058.mp4\",\"cat\":\"stretching\",\"desc\":\"Place one arm against a wall and turn away to open the chest. It eases tight pecs.\"},{\"id\":\"3257\",\"n\":\"standing one arm circling\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with feet shoulder-width apart.\",\"Extend one arm out to the side.\",\"Make slow circles, gradually larger.\",\"Reverse the direction.\",\"Switch arms.\"],\"img\":\"3257.webp\",\"gif\":\"3257.mp4\",\"cat\":\"mobility\",\"desc\":\"One-arm circles to warm up the shoulder joint.\"},{\"id\":\"1947\",\"n\":\"standing outer hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Stand next to a wall and cross one leg behind the other.\",\"Push your hips sideways toward the wall.\",\"Lean your upper body away from the hips until you feel the outer hip stretch.\",\"Keep both feet flat on the floor.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1947.webp\",\"gif\":\"1947.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side stretch that lengthens the outer hip and thigh.\"},{\"id\":\"9890\",\"n\":\"standing pelvic lift\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"hamstrings\",\"lower abs\"],\"st\":[\"Stand tall with your feet hip width apart and your hands on your hips.\",\"Soften your knees slightly.\",\"Tuck your tailbone under and lift the front of your pelvis by squeezing your glutes and lower abs.\",\"Hold for 2 seconds.\",\"Release slowly to a neutral pelvis.\",\"Keep your upper body still and breathe normally.\"],\"img\":\"9890.webp\",\"gif\":\"9890.mp4\",\"cat\":\"rehab\",\"desc\":\"A gentle standing move where you tilt and lift the pelvis by squeezing the glutes and abs. It teaches pelvic control and activates the hips.\"},{\"id\":\"6772\",\"n\":\"standing peroneus muscles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand near a wall for balance.\",\"Cross one foot behind and turn the sole so the outer edge presses into the floor.\",\"Gently shift your weight onto that foot.\",\"Feel the stretch along the outside of the lower leg.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch feet.\"],\"img\":\"6772.webp\",\"gif\":\"6772.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch for the muscles on the outside of the lower leg. It helps ankle mobility.\"},{\"id\":\"3409\",\"n\":\"standing phelps\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\",\"chest\"],\"st\":[\"Stand tall with feet shoulder-width apart.\",\"Swing both arms forward and up in big arcs.\",\"Swing them back down past your hips behind you.\",\"Keep the movement loose and rhythmic.\",\"Continue for 20-30 seconds.\"],\"img\":\"3409.webp\",\"gif\":\"3409.mp4\",\"cat\":\"mobility\",\"desc\":\"Swim-style arm swings that loosen the shoulders and chest as a warm-up.\"},{\"id\":\"1225\",\"n\":\"standing plate presses\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand tall holding a plate at the sides with both hands at chest height.\",\"Brace your core and keep your elbows slightly forward.\",\"Press the plate overhead until your arms are straight.\",\"Lower it slowly to your chest.\",\"Keep your ribs down and avoid arching.\"],\"img\":\"1225.webp\",\"gif\":\"1225.mp4\",\"cat\":\"strength\",\"desc\":\"Pressing a weight plate overhead with both hands. A simple way to train the shoulders and arms.\"},{\"id\":\"3673\",\"n\":\"standing pose (form check) front view\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\"],\"st\":[\"Stand with feet hip width apart.\",\"Keep your knees soft and hips level.\",\"Stack your shoulders over your hips.\",\"Look straight ahead.\",\"Compare yourself to the correct posture.\"],\"img\":\"3673.webp\",\"gif\":\"3673.mp4\",\"cat\":\"isometric\",\"desc\":\"A front-view form check showing a correct standing posture.\"},{\"id\":\"3674\",\"n\":\"standing pose (form check) side view\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\"],\"st\":[\"Stand with feet hip width apart.\",\"Keep your ears over your shoulders and hips.\",\"Keep a natural curve in your lower back.\",\"Relax your arms.\",\"Compare yourself to the correct posture.\"],\"img\":\"3674.webp\",\"gif\":\"3674.mp4\",\"cat\":\"isometric\",\"desc\":\"A side-view form check showing a correct standing posture.\"},{\"id\":\"1059\",\"n\":\"standing quadriceps stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Stand tall and hold something for balance if needed.\",\"Bend one knee and grab your ankle.\",\"Pull your heel toward your glute, knees together.\",\"Hold for 20-30 seconds.\",\"Switch legs and repeat.\"],\"img\":\"1059.webp\",\"gif\":\"1059.mp4\",\"cat\":\"stretching\",\"desc\":\"Pull your heel toward your glute while standing to stretch the front of the thigh. It is a classic quad stretch.\",\"fv\":\"8372\"},{\"id\":\"1896\",\"n\":\"standing raised leg hip adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Stand tall and place one foot on a bench or raised surface to the side.\",\"Keep your standing leg straight and your toes forward.\",\"Shift your weight toward the raised leg side until you feel a stretch.\",\"Keep your chest upright and your hips square.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1896.webp\",\"gif\":\"1896.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch with one leg raised on a support that opens the inner thigh.\"},{\"id\":\"1917\",\"n\":\"standing reach down hamstring crossed legs stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\"],\"st\":[\"Stand tall and cross one foot over the other.\",\"Hinge forward at the hips and reach toward the floor until the back of the thighs stretch.\",\"Keep both legs fairly straight and let your head hang relaxed.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1917.webp\",\"gif\":\"1917.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing forward fold with the legs crossed, which shifts the stretch to the back of the rear leg.\"},{\"id\":\"1916\",\"n\":\"standing reach down hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Stand with your feet hip width apart.\",\"Hinge at the hips and reach your hands down toward your shins or toes until you feel the back of the thighs stretch.\",\"Let your head and neck hang relaxed and keep a slight bend in the knees.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1916.webp\",\"gif\":\"1916.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing forward fold that stretches the hamstrings and calves.\"},{\"id\":\"1796\",\"n\":\"standing reach up back rotation stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\",\"lower back\"],\"st\":[\"Stand with your feet shoulder-width apart and reach one arm overhead.\",\"Rotate your upper body gently away from the raised arm and reach up and over.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1796.webp\",\"gif\":\"1796.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching one arm up and rotating your trunk stretches the lats and the muscles around your spine. It also gives your mid back some rotation.\",\"fv\":\"4321\"},{\"id\":\"1974\",\"n\":\"standing reverse shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\"],\"st\":[\"Stand tall and clasp your hands behind your back.\",\"Straighten your arms and squeeze your shoulder blades together.\",\"Lift your hands slightly away from your body.\",\"Keep your chest up and avoid arching your lower back.\",\"Hold for 20-30 seconds, then release.\"],\"img\":\"1974.webp\",\"gif\":\"1974.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing with your hands clasped behind you to open the front of the shoulders.\"},{\"id\":\"1895\",\"n\":\"standing rotational hip stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\"],\"st\":[\"Stand tall near a support.\",\"Cross one ankle over the opposite knee.\",\"Sit your hips back as if sitting into a chair.\",\"Feel the stretch in the hip of the crossed leg.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1895.webp\",\"gif\":\"1895.mp4\",\"cat\":\"stretching\",\"desc\":\"Rotates the hip in standing to stretch the glutes and deep hip muscles.\"},{\"id\":\"7232\",\"n\":\"standing scapular rotation\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"shoulders\"],\"st\":[\"Stand tall with arms relaxed at your sides.\",\"Lift your shoulders up toward your ears.\",\"Roll them back, then down.\",\"Bring them forward and up again in a circle.\",\"Reverse the direction after several reps.\"],\"img\":\"7232.webp\",\"gif\":\"7232.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing drill that moves the shoulder blades in circles. It improves shoulder mobility and control.\"},{\"id\":\"7233\",\"n\":\"standing scapular rotation (front pov)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rhomboids\",\"rotator cuff\",\"shoulders\"],\"st\":[\"Stand tall with your arms at your sides.\",\"Lift your shoulders gently up.\",\"Roll them back and down in a smooth circle.\",\"Reverse the direction.\",\"Keep your neck relaxed.\",\"Repeat for the planned reps.\"],\"img\":\"7233.webp\",\"gif\":\"7233.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing shoulder blade rotation that warms up the upper back and improves control of the scapulae.\"},{\"id\":\"4328\",\"n\":\"standing scissors\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand tall with one foot forward and one back, arms ready.\",\"Hop lightly and switch your leg positions in the air.\",\"Swing your arms opposite to your legs for balance.\",\"Land softly on the balls of your feet.\",\"Keep a quick, steady rhythm for the set.\"],\"img\":\"4328.webp\",\"gif\":\"4328.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A quick jumping drill where your legs swap front and back like scissors. Good for conditioning and coordination.\"},{\"id\":\"4399\",\"n\":\"standing seal yoga pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\",\"shoulders\"],\"st\":[\"Stand with feet hip-width apart and your hands on your lower back.\",\"Lengthen through your spine.\",\"Lift your chest and gently arch backward.\",\"Keep your neck relaxed and your legs strong.\",\"Hold for 15-30 seconds, then come back up slowly.\"],\"img\":\"4399.webp\",\"gif\":\"4399.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing back-bending pose that opens the chest and front of the hips and stretches the abdomen.\"},{\"id\":\"1957\",\"n\":\"standing shin stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Stand tall and hold a wall for balance.\",\"Place the top of one foot on the floor behind you with the toes curled under.\",\"Gently press the foot down by bending the standing knee.\",\"Feel the stretch along the front of the shin and ankle.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1957.webp\",\"gif\":\"1957.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing with the top of the foot on the floor to stretch the muscles at the front of the shin.\"},{\"id\":\"3416\",\"n\":\"standing shoulder circling\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall with arms relaxed at your sides.\",\"Lift your shoulders up and roll them back in a large circle.\",\"Keep your neck relaxed.\",\"Do 10 circles, then reverse the direction.\"],\"img\":\"3416.webp\",\"gif\":\"3416.mp4\",\"cat\":\"mobility\",\"desc\":\"Circle your shoulders to loosen the joint and ease tension in the upper back.\"},{\"id\":\"3253\",\"n\":\"standing side bend\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Stand with your feet shoulder-width apart.\",\"Raise one arm overhead.\",\"Bend sideways, reaching over to the other side.\",\"Return to upright.\",\"Switch sides and repeat.\"],\"img\":\"3253.webp\",\"gif\":\"3253.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing side bend that loosens the trunk and works the obliques.\"},{\"id\":\"3997\",\"n\":\"standing side bend (bent arm)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Stand tall with feet hip width apart.\",\"Bend one arm overhead.\",\"Lean to the opposite side.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"3997.webp\",\"gif\":\"3997.mp4\",\"cat\":\"stretching\",\"desc\":\"Bend sideways with one arm overhead and bent. It stretches the side of the trunk.\",\"fv\":\"3255\"},{\"id\":\"4322\",\"n\":\"standing side bend (bent arm) v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand with feet shoulder-width apart and one hand behind your head, elbow bent.\",\"Place your other hand on your hip.\",\"Bend sideways toward the hand on your hip without leaning forward.\",\"Squeeze your side to return upright.\",\"Finish your reps, then switch sides.\"],\"img\":\"4322.webp\",\"gif\":\"4322.mp4\",\"cat\":\"strength\",\"desc\":\"A bodyweight side bend with one arm bent behind your head, working the obliques.\"},{\"id\":\"4810\",\"n\":\"standing side bend v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Stand tall with feet hip width apart and one arm overhead.\",\"Brace your core lightly.\",\"Bend sideways at the waist, reaching over with the raised arm.\",\"Pause when you feel the side muscles work.\",\"Return to upright with control.\",\"Complete your reps, then switch sides.\"],\"img\":\"4810.webp\",\"gif\":\"4810.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing bend to the side, a second variation. It works the obliques and loosens the sides of the trunk.\"},{\"id\":\"4366\",\"n\":\"standing side crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Stand tall with your hands behind your head.\",\"Lift one knee out to the side.\",\"Crunch your elbow down toward it.\",\"Return to standing.\",\"Repeat on both sides.\"],\"img\":\"4366.webp\",\"gif\":\"4366.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A standing crunch where you lift a knee to the side toward your elbow. It works the obliques.\"},{\"id\":\"3929\",\"n\":\"standing side leg raise\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\"],\"st\":[\"Stand tall, hands on your hips or on a support.\",\"Keep your toes pointing forward and lift one leg out to the side.\",\"Raise it as high as you can without leaning your torso.\",\"Lower with control and repeat, then switch legs.\"],\"img\":\"3929.webp\",\"gif\":\"3929.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lift one leg out to the side while standing. It works the outer hip and helps with balance.\"},{\"id\":\"7306\",\"n\":\"standing side neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Stand tall with your shoulders relaxed.\",\"Tilt your head toward one shoulder.\",\"Rest a hand lightly on your head for slight pressure.\",\"Keep the opposite shoulder low.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch sides.\"],\"img\":\"7306.webp\",\"gif\":\"7306.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle side stretch for the neck and upper traps, useful after desk work.\"},{\"id\":\"2119\",\"n\":\"standing side stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"shoulders\"],\"st\":[\"Stand tall with feet hip-width apart.\",\"Raise one arm overhead with the palm facing inward.\",\"Lean your torso sideways away from the raised arm.\",\"Keep both hips level and your chest facing forward.\",\"Hold for 20-30 seconds.\",\"Return upright and repeat on the other side.\"],\"img\":\"2119.webp\",\"gif\":\"2119.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaches an arm overhead and leans to the side to lengthen the flank, lats and obliques.\"},{\"id\":\"2120\",\"n\":\"standing side stretch with stick\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart holding a stick with both hands overhead.\",\"Keep your arms straight and your shoulders relaxed.\",\"Lean your torso slowly to one side without twisting.\",\"Keep your hips steady and your chest facing forward.\",\"Hold for 20-30 seconds.\",\"Return to upright and lean to the other side.\"],\"img\":\"2120.webp\",\"gif\":\"2120.mp4\",\"cat\":\"stretching\",\"desc\":\"Uses a stick held overhead to guide a deeper side bend, stretching the flank and the lats.\"},{\"id\":\"5003\",\"n\":\"standing single leg calf raise (on a staircase)\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on the edge of a stair on one foot, holding the rail for balance.\",\"Let your heel drop below the step.\",\"Rise up onto your toes as high as you can.\",\"Pause at the top.\",\"Lower slowly, then switch legs after your set.\"],\"img\":\"5003.webp\",\"gif\":\"5003.mp4\",\"cat\":\"calisthenics\",\"desc\":\"One-legged calf raise from a stair step for a deep stretch. It builds calf strength and ankle stability.\"},{\"id\":\"4796\",\"n\":\"standing single leg calf raise balance\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand tall on one foot with the other lifted.\",\"Keep your hands on your hips or lightly on a wall.\",\"Rise up onto your toes as high as you can.\",\"Hold briefly at the top, steady.\",\"Lower slowly, finish the reps, then switch legs.\"],\"img\":\"4796.webp\",\"gif\":\"4796.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg calf raise that also challenges balance. It builds calf strength and ankle stability.\"},{\"id\":\"3712\",\"n\":\"standing single leg calf raise with support\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on one foot and hold a wall or rail for balance.\",\"Rise as high as you can onto the ball of your foot.\",\"Pause briefly at the top.\",\"Lower slowly below flat if you can do so comfortably.\",\"Finish your reps, then switch legs.\"],\"img\":\"3712.webp\",\"gif\":\"3712.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise your heel on one leg while holding a support for balance, building the calf.\"},{\"id\":\"10547\",\"n\":\"standing single leg calf rock\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on one leg next to a wall for balance.\",\"Rock your weight back onto your heel, lifting the toes.\",\"Roll forward onto the ball of your foot.\",\"Keep the movement smooth and controlled.\",\"Finish your reps, then switch legs.\"],\"img\":\"10547.webp\",\"gif\":\"10547.mp4\",\"cat\":\"mobility\",\"desc\":\"Balance on one leg and rock between heel and toes. It warms up the calf and ankle.\"},{\"id\":\"10548\",\"n\":\"standing single leg concentration calf raise\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Stand on one leg and hold a wall or rail lightly.\",\"Lower your heel slightly for a stretch.\",\"Rise high onto your toes, squeezing the calf.\",\"Pause for a second at the top.\",\"Lower slowly, finish your reps, then switch legs.\"],\"img\":\"10548.webp\",\"gif\":\"10548.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A one-legged calf raise performed slowly with full focus. It builds calf strength and ankle control.\"},{\"id\":\"10748\",\"n\":\"standing single leg front back side to side toe tap\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"core\",\"calves\"],\"st\":[\"Stand on one leg.\",\"Tap the other toe forward.\",\"Tap to the side, then back.\",\"Keep your balance.\",\"Switch legs.\"],\"img\":\"10748.webp\",\"gif\":\"10748.mp4\",\"cat\":\"mobility\",\"desc\":\"Tap your toes in different directions while balancing. It works hip stability.\"},{\"id\":\"4653\",\"n\":\"standing single leg high knee to butt kick (with support)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"hip flexors\",\"glutes\"],\"st\":[\"Stand next to a wall or support and hold it with one hand.\",\"Raise the opposite knee to hip height.\",\"Lower it and kick that heel up toward your glutes.\",\"Repeat smoothly for the reps.\",\"Switch sides and keep your torso upright.\"],\"img\":\"4653.webp\",\"gif\":\"4653.mp4\",\"cat\":\"mobility\",\"desc\":\"A supported single-leg drill that alternates a high knee and a heel kick, working balance and the hips.\"},{\"id\":\"10517\",\"n\":\"standing single leg hip swirl with chair support\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\",\"core\"],\"st\":[\"Stand beside a chair and hold it for balance.\",\"Lift one leg slightly off the floor.\",\"Draw slow, controlled circles with your leg.\",\"Do half of the reps one way, then reverse the direction.\",\"Switch legs and repeat.\"],\"img\":\"10517.webp\",\"gif\":\"10517.mp4\",\"cat\":\"mobility\",\"desc\":\"Hold a chair and swirl one leg in circles. It loosens the hip joint and warms up the glutes.\"},{\"id\":\"1601\",\"n\":\"standing straight leg hamstring contract relax on exercise ball\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Stand and rest one heel on a stability ball in front of you with your knee straight.\",\"Hinge forward at the hips until you feel a stretch in the back of the thigh.\",\"Gently press your heel into the ball for about 5 seconds, then relax.\",\"Lean a little deeper into the stretch.\",\"Hold for 20-30 seconds, then switch legs.\"],\"img\":\"1601.webp\",\"gif\":\"1601.mp4\",\"cat\":\"stretching\",\"desc\":\"A hamstring stretch with the heel on a stability ball, using a contract and relax method. It helps you ease deeper into the stretch.\"},{\"id\":\"7745\",\"n\":\"standing supinated face pull (with towels)\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"biceps\",\"rotator cuff\"],\"st\":[\"Loop a towel around a sturdy anchor and hold both ends, palms up.\",\"Lean back with your arms extended.\",\"Pull your hands toward your face, elbows wide.\",\"Squeeze your shoulder blades together.\",\"Lower yourself slowly. Walk your feet in to make it harder.\"],\"img\":\"7745.webp\",\"gif\":\"7745.mp4\",\"cat\":\"strength\",\"desc\":\"A face pull using a towel looped around a fixed anchor and an underhand grip. A simple way to train the rear delts without a cable.\"},{\"id\":\"3404\",\"n\":\"standing t raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Stand tall with arms in front of you at chest height.\",\"Open your arms out to the sides into a T.\",\"Squeeze your shoulder blades together.\",\"Pause, then return slowly.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"3404.webp\",\"gif\":\"3404.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lift your arms out to the sides into a T shape to train the upper back and rear shoulders.\"},{\"id\":\"6773\",\"n\":\"standing tibialis anterior stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Stand near a wall for balance.\",\"Place the top of one foot on the floor behind you with toes curled under.\",\"Gently bend the standing knee to press forward.\",\"Feel the stretch along the shin.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch feet.\"],\"img\":\"6773.webp\",\"gif\":\"6773.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch for the muscle at the front of the shin. Useful after running or lots of walking.\"},{\"id\":\"9803\",\"n\":\"standing tibialis raise wall supported\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"feet\"],\"st\":[\"Stand with your back against a wall and feet a little forward.\",\"Keep your legs straight.\",\"Lift your toes as high as you can, keeping your heels down.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"9803.webp\",\"gif\":\"9803.mp4\",\"cat\":\"strength\",\"desc\":\"Leaning against a wall, you lift your toes toward your shins to train the muscle at the front of your lower leg.\"},{\"id\":\"1908\",\"n\":\"standing toe down hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Stand with one heel on the floor in front of you.\",\"Point your toes down.\",\"Hinge forward from the hips with a flat back.\",\"Keep the front leg nearly straight.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1908.webp\",\"gif\":\"1908.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the back of the thigh with the toes lowered.\"},{\"id\":\"1958\",\"n\":\"standing toe extensor stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"feet\"],\"st\":[\"Stand next to a support and place the top of one foot on the floor behind you with the toes curled under.\",\"Gently bend your standing knee and press the toes down until you feel the stretch on top of the foot and shin.\",\"Keep the pressure light and controlled.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1958.webp\",\"gif\":\"1958.mp4\",\"cat\":\"stretching\",\"desc\":\"Pressing the tops of the toes against the floor to stretch the front of the foot and shin.\"},{\"id\":\"1968\",\"n\":\"standing toe flexor stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"soleus\"],\"st\":[\"Stand facing a wall and place the toes of one foot on it with the heel on the floor.\",\"Lean forward gently until you feel the stretch along the bottom of the foot and into the calf.\",\"Keep your heel firmly on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1968.webp\",\"gif\":\"1968.mp4\",\"cat\":\"stretching\",\"desc\":\"Pulling the toes back against a wall to stretch the sole of the foot and the calf.\"},{\"id\":\"1885\",\"n\":\"standing toe up achilles stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall with one foot forward.\",\"Place the ball of the forward foot against the wall, heel on the floor.\",\"Lean your hips toward the wall.\",\"Feel the stretch in the calf and Achilles.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Switch sides and repeat.\"],\"img\":\"1885.webp\",\"gif\":\"1885.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the calf and Achilles by lifting the toes against a wall.\"},{\"id\":\"1924\",\"n\":\"standing toe up calf stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"hamstrings\"],\"st\":[\"Stand facing a wall or step and place the ball of one foot against it with the heel on the floor.\",\"Keep the leg straight.\",\"Lean your hips gently toward the wall until you feel a stretch in the calf.\",\"Keep your heel down and your back tall.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1924.webp\",\"gif\":\"1924.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing with the toes lifted against a surface to stretch the calf.\"},{\"id\":\"1909\",\"n\":\"standing toe up hamstring stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"calves\",\"sm\":[\"calves\",\"lower back\"],\"st\":[\"Stand tall and step one foot forward, resting the heel on the floor with the toes pulled up.\",\"Keep the front leg straight and the back knee slightly bent.\",\"Hinge forward at the hips with a flat back until you feel a pull behind the thigh.\",\"Keep your chest open and avoid rounding your spine.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1909.webp\",\"gif\":\"1909.mp4\",\"cat\":\"stretching\",\"desc\":\"Standing stretch with one heel on the floor and toes pulled up, lengthening the back of the thigh and calf.\"},{\"id\":\"9653\",\"n\":\"standing torso twist arms swing\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"lower back\"],\"st\":[\"Stand with feet shoulder-width apart and arms relaxed.\",\"Rotate your torso to one side, letting your arms swing around.\",\"Let your back heel lift slightly if needed.\",\"Rotate smoothly to the other side.\",\"Continue at an easy rhythm for 30 seconds.\"],\"img\":\"9653.webp\",\"gif\":\"9653.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic standing twist where your arms swing with the rotation. It loosens up the spine and obliques.\"},{\"id\":\"9986\",\"n\":\"standing towel foot crunch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"shins\",\"ankles\"],\"st\":[\"Stand with one foot flat on a towel laid on a smooth floor.\",\"Keep your heel down.\",\"Curl your toes to pull the towel toward you.\",\"Release and repeat until the towel is bunched under your foot.\",\"Hold on to a support if you need balance.\",\"Do your reps, then switch feet.\"],\"img\":\"9986.webp\",\"gif\":\"9986.mp4\",\"cat\":\"strength\",\"desc\":\"A foot exercise where you scrunch a towel on the floor with your toes. It strengthens the muscles of the foot and arch.\"},{\"id\":\"3254\",\"n\":\"standing two side bend\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Clasp your hands overhead.\",\"Bend to one side, keeping your hips still.\",\"Return to the center.\",\"Bend to the other side and repeat.\"],\"img\":\"3254.webp\",\"gif\":\"3254.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing side bend with both arms overhead for a longer reach through the trunk.\"},{\"id\":\"3256\",\"n\":\"standing two side bend (bent arm)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart.\",\"Place your hands behind your head with elbows out.\",\"Bend to one side without twisting.\",\"Return to the center.\",\"Bend to the other side and repeat.\"],\"img\":\"3256.webp\",\"gif\":\"3256.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing side bend with your elbows bent that loosens the sides of the trunk.\"},{\"id\":\"3408\",\"n\":\"standing upper body rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\"],\"st\":[\"Stand with feet hip-width apart and hands clasped in front of your chest.\",\"Keep your hips facing forward.\",\"Rotate your upper body to one side as far as is comfortable.\",\"Return through the centre and rotate the other way.\",\"Keep it smooth for 10-15 reps per side.\"],\"img\":\"3408.webp\",\"gif\":\"3408.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing rotation of the upper body that mobilises the thoracic spine and warms up the waist.\"},{\"id\":\"1970\",\"n\":\"standing upright shoulders stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"chest\"],\"st\":[\"Stand tall with your feet hip-width apart.\",\"Clasp your hands behind your back.\",\"Straighten your arms and lift them gently away from your body.\",\"Keep your chest open and your neck relaxed.\",\"Hold for 20-30 seconds.\"],\"img\":\"1970.webp\",\"gif\":\"1970.mp4\",\"cat\":\"stretching\",\"desc\":\"A tall standing stretch that opens the shoulders and chest.\"},{\"id\":\"3405\",\"n\":\"standing w raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\",\"rhomboids\"],\"st\":[\"Stand tall with elbows bent and hands in front of your chest.\",\"Pull your elbows back and down, forming a W.\",\"Squeeze your shoulder blades together and rotate your hands outward.\",\"Pause briefly.\",\"Return slowly and repeat.\"],\"img\":\"3405.webp\",\"gif\":\"3405.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Pull your elbows back into a W shape to strengthen the mid-back and rotator cuff.\"},{\"id\":\"10928\",\"n\":\"standing wall serratus slide with towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"serratus anterior\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\"],\"st\":[\"Stand facing a wall with a towel under your forearm on the wall.\",\"Keep your elbow bent and your body upright.\",\"Slide your arm upward along the wall.\",\"Reach the top without shrugging.\",\"Slide back down slowly and switch arms.\"],\"img\":\"10928.webp\",\"gif\":\"10928.mp4\",\"cat\":\"rehab\",\"desc\":\"A towel slide up the wall that works the muscle along the ribs. It supports healthy shoulder blade motion.\"},{\"id\":\"10937\",\"n\":\"standing wall shoulder rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\"],\"st\":[\"Stand facing a wall and place your forearm against it.\",\"Bend your elbow to 90 degrees.\",\"Rotate your forearm up and down against the wall.\",\"Keep your shoulder relaxed.\",\"Switch arms after your reps.\"],\"img\":\"10937.webp\",\"gif\":\"10937.mp4\",\"cat\":\"mobility\",\"desc\":\"Rotating the shoulder against a wall. It gives gentle mobility and awareness.\"},{\"id\":\"11316\",\"n\":\"standing wall slide half squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your back against a wall and your feet slightly forward.\",\"Slide down until your knees are bent to about 45 degrees.\",\"Keep your back flat on the wall.\",\"Press through your heels to rise.\",\"Repeat for the set.\"],\"img\":\"11316.webp\",\"gif\":\"11316.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A half squat with your back sliding against a wall. It builds leg strength with support and good alignment.\"},{\"id\":\"11451\",\"n\":\"standing wall slide half squat hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand with your back against a wall and feet about a step in front of you.\",\"Slide down until your knees are bent to about 45-60 degrees.\",\"Keep your back flat on the wall and your knees over your ankles.\",\"Press through your whole foot and breathe steadily.\",\"Hold for 20-45 seconds, then slide back up.\"],\"img\":\"11451.webp\",\"gif\":\"11451.mp4\",\"cat\":\"isometric\",\"desc\":\"A wall-supported half squat held in place to build quad endurance with low joint stress.\",\"hd\":1},{\"id\":\"10926\",\"n\":\"standing wall slide quarter squat hold\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Stand with your back against a wall and feet slightly forward.\",\"Slide down until your knees bend about a quarter of the way.\",\"Keep your back flat to the wall.\",\"Hold for 15-30 seconds.\",\"Slide back up.\"],\"img\":\"10926.webp\",\"gif\":\"10926.mp4\",\"cat\":\"isometric\",\"desc\":\"A wall-supported quarter squat that you hold. It gently loads the thighs.\",\"hd\":1},{\"id\":\"1894\",\"n\":\"standing wide knees adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Stand with your feet wide apart and toes pointing slightly out.\",\"Bend your knees and place your hands on your thighs.\",\"Shift your weight from side to side, sinking into the stretch.\",\"Keep your chest tall and your back flat.\",\"Hold for 20-30 seconds on each side.\"],\"img\":\"1894.webp\",\"gif\":\"1894.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing wide-stance stretch for the inner thighs.\"},{\"id\":\"1904\",\"n\":\"standing wide leg adductor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\"],\"st\":[\"Stand with your feet wide apart, toes pointing slightly out.\",\"Shift your weight to one side and bend that knee while the other leg stays straight, and feel the inner thigh stretch.\",\"Keep your chest up and the straight leg's foot flat on the floor.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1904.webp\",\"gif\":\"1904.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side lunge position that lengthens the inner thighs.\"},{\"id\":\"3410\",\"n\":\"standing wring the towel\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"forearms\"],\"st\":[\"Stand with feet hip-width apart and hands clasped in front of you.\",\"Rotate your torso to one side while your hands twist across.\",\"Return to the centre and rotate the other way.\",\"Keep your hips mostly facing forward.\",\"Continue for 10-15 reps per side.\"],\"img\":\"3410.webp\",\"gif\":\"3410.mp4\",\"cat\":\"mobility\",\"desc\":\"Twist your torso with arms wrapped as if wringing a towel, mobilising the waist and shoulders.\"},{\"id\":\"3403\",\"n\":\"standing y raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"shoulders\",\"rhomboids\"],\"st\":[\"Stand tall with arms by your sides, thumbs pointing up.\",\"Raise both arms diagonally overhead to form a Y.\",\"Squeeze your shoulder blades down and back.\",\"Pause briefly, then lower slowly.\",\"Keep your neck long and avoid shrugging.\"],\"img\":\"3403.webp\",\"gif\":\"3403.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise your arms into a Y shape to strengthen the lower traps and shoulder stabilisers.\"},{\"id\":\"2889\",\"n\":\"starfish crunch (advanced)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with arms and legs spread wide.\",\"Brace your core and press your lower back into the floor.\",\"Crunch up, bringing your arms and legs toward the center.\",\"Slowly open back out to the starfish shape.\",\"Keep your movements controlled and repeat.\"],\"img\":\"2889.webp\",\"gif\":\"2889.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide-limb crunch that works the abs while your arms and legs open and close like a starfish.\"},{\"id\":\"3813\",\"n\":\"starfish crunch (beginner)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your arms and legs spread wide.\",\"Brace your abs and press your lower back down.\",\"Crunch up, bringing your elbows toward your knees as they pull in.\",\"Lower back to the starfish position under control.\",\"Breathe out as you crunch.\"],\"img\":\"3813.webp\",\"gif\":\"3813.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch where your arms and legs spread like a starfish and then come together. It is a beginner-friendly ab move.\",\"fv\":\"2888\"},{\"id\":\"11646\",\"n\":\"static glutes contraction (isometric)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\"],\"st\":[\"Lie on your back or stand with your body relaxed.\",\"Squeeze both glute muscles together.\",\"Keep your legs and back still.\",\"Hold the squeeze for 5-10 seconds.\",\"Release fully.\",\"Repeat for several reps.\"],\"img\":\"11646.webp\",\"gif\":\"11646.mp4\",\"cat\":\"isometric\",\"desc\":\"Squeezing the glutes and holding without moving, a simple way to activate the hips.\"},{\"id\":\"4000\",\"n\":\"static lunge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Step one foot forward and stay in a split stance.\",\"Lower your back knee toward the floor.\",\"Keep your front knee above the ankle.\",\"Push through the front heel.\",\"Finish reps, then switch legs.\"],\"img\":\"4000.webp\",\"gif\":\"4000.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lunge held in one place with no stepping. It builds the legs and balance.\"},{\"id\":\"3966\",\"n\":\"static lunge kick\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Step into a lunge with your front knee over your ankle.\",\"Lower down until both knees are bent.\",\"Drive up through the front foot.\",\"Swing the back leg forward in a kick.\",\"Return to the lunge and repeat, then switch legs.\"],\"img\":\"3966.webp\",\"gif\":\"3966.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A lunge held in place that ends with a kick from the back leg. It works the legs and balance.\"},{\"id\":\"3657\",\"n\":\"static position lying back with pad\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Place a pad on the floor or bench.\",\"Lie on your back with your head supported.\",\"Keep your spine neutral.\",\"Relax your arms at your sides.\",\"Hold the position and breathe.\"],\"img\":\"3657.webp\",\"gif\":\"3657.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a lying position on your back with a pad as a reference for setup and posture.\",\"fv\":\"3136\"},{\"id\":\"3660\",\"n\":\"static position lying front\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Lie face down on a mat.\",\"Extend your legs and rest your forehead down.\",\"Keep your arms alongside your body.\",\"Keep your hips relaxed.\",\"Hold and breathe.\"],\"img\":\"3660.webp\",\"gif\":\"3660.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a face-down position to practice setting up for prone exercises.\",\"fv\":\"3139\"},{\"id\":\"3661\",\"n\":\"static position seated back\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Sit tall with feet flat on the floor.\",\"Keep your back straight.\",\"Place your hands on your thighs.\",\"Relax your shoulders.\",\"Hold and breathe.\"],\"img\":\"3661.webp\",\"gif\":\"3661.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold an upright seated posture with no pad.\",\"fv\":\"3140\"},{\"id\":\"3658\",\"n\":\"static position seated back with pad\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\"],\"st\":[\"Sit on the seat with your back against the pad.\",\"Keep your feet flat on the floor.\",\"Press your back gently into the pad.\",\"Keep your shoulders relaxed.\",\"Hold the position and breathe.\"],\"img\":\"3658.webp\",\"gif\":\"3658.mp4\",\"cat\":\"isometric\",\"desc\":\"Sit with your back against a pad to hold a proper seated posture.\",\"fv\":\"3137\"},{\"id\":\"3659\",\"n\":\"static position standing\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\"],\"st\":[\"Stand with feet hip width apart.\",\"Keep your knees soft.\",\"Stack ribs over hips and shoulders back.\",\"Let your arms hang.\",\"Hold and breathe steadily.\"],\"img\":\"3659.webp\",\"gif\":\"3659.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a tall standing posture as a reference position.\",\"fv\":\"3138\"},{\"id\":\"11645\",\"n\":\"static quadriceps contraction (isometric)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\"],\"st\":[\"Sit or lie with one leg straight in front.\",\"Relax your upper body.\",\"Tighten the front of the thigh and press the knee down.\",\"Hold for 5-10 seconds.\",\"Relax fully.\",\"Repeat, then switch legs.\"],\"img\":\"11645.webp\",\"gif\":\"11645.mp4\",\"cat\":\"isometric\",\"desc\":\"Seated or lying with your leg straight, you tighten the thigh muscle and hold, an easy way to activate the quads.\"},{\"id\":\"4942\",\"n\":\"stationary arms throw\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Stand with feet shoulder width apart and arms at your sides.\",\"Swing your arms up and back in a throwing motion.\",\"Rotate through your torso slightly.\",\"Keep the movement smooth and rhythmic.\",\"Switch arms or alternate.\",\"Continue for 20-30 seconds.\"],\"img\":\"4942.webp\",\"gif\":\"4942.mp4\",\"cat\":\"mobility\",\"desc\":\"An arm swing from a stationary stance. It warms up the shoulders and upper back.\"},{\"id\":\"2279\",\"n\":\"stationary bike run v. 4\",\"bp\":\"cardio\",\"eq\":\"stationary bike\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\"],\"st\":[\"Adjust the seat so your knees stay slightly bent at the bottom of the stroke.\",\"Hold the handles and sit tall.\",\"Start pedalling at an easy pace to warm up.\",\"Raise the speed to a brisk rhythm you can sustain.\",\"Keep your upper body relaxed.\",\"Continue for 10-30 minutes, then slow down to cool off.\"],\"img\":\"2279.webp\",\"gif\":\"2279.mp4\",\"cat\":\"cardio\",\"desc\":\"A stationary bike session at a brisk pace, similar to running in effort, to build heart and leg endurance.\"},{\"id\":\"10411\",\"n\":\"steel mace halo (weighted)\",\"bp\":\"shoulders\",\"eq\":\"macebell\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\",\"core\",\"triceps\"],\"st\":[\"Stand tall with feet shoulder width apart and hold the mace upright near your chest.\",\"Brace your core and keep your ribs down.\",\"Circle the mace around your head in a smooth, controlled arc.\",\"Keep your elbows close and your head still.\",\"Do all reps, then reverse the direction.\"],\"img\":\"10411.webp\",\"gif\":\"10411.mp4\",\"cat\":\"strength\",\"desc\":\"Circle a steel mace around your head while standing tall. It trains shoulder control and stability under an awkward load.\"},{\"id\":\"10410\",\"n\":\"steel mace squat (weighted)\",\"bp\":\"upper legs\",\"eq\":\"macebell\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Rest the mace on your shoulders and hold it with both hands.\",\"Stand with feet about shoulder width apart.\",\"Sit your hips back and down until your thighs are about parallel.\",\"Keep your chest tall and knees tracking over your toes.\",\"Drive through your feet to stand back up.\"],\"img\":\"10410.webp\",\"gif\":\"10410.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a steel mace across the shoulders or upper back. It builds leg strength and a braced trunk.\"},{\"id\":\"8374\",\"n\":\"step out from squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hip flexors\"],\"st\":[\"Stand with your feet together.\",\"Squat down by pushing your hips back.\",\"Stand up while stepping one foot out to the side.\",\"Bring that foot back in and squat again.\",\"Alternate sides each rep.\",\"Keep your chest up and knees tracking over your toes.\"],\"img\":\"8374.webp\",\"gif\":\"8374.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat that steps one leg out to the side before returning. It works the legs and hips with a bit of lateral movement.\"},{\"id\":\"0801\",\"n\":\"step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a sturdy step or bench.\",\"Place one foot fully on it.\",\"Press through that heel to lift your body up until the leg is straight.\",\"Lower back down slowly.\",\"Finish your reps, then switch legs.\"],\"img\":\"0801.webp\",\"gif\":\"0801.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Stepping onto a bench or box one leg at a time. It builds leg strength and single-leg control.\"},{\"id\":\"11450\",\"n\":\"step up (1st and 2nd stairs steps)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing the stairs with your feet hip-width apart.\",\"Place one foot on the first step and push through the heel to climb up.\",\"Continue onto the second step, then step back down in control.\",\"Keep your torso tall and your knee tracking over your toes.\",\"Alternate the leading leg each rep or finish all reps on one side first.\"],\"img\":\"11450.webp\",\"gif\":\"11450.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A simple stair step-up done on the first and second steps. It builds leg strength and balance using everyday stairs.\"},{\"id\":\"0799\",\"n\":\"step up crossover\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"obliques\"],\"st\":[\"Stand facing a sturdy step or box.\",\"Step up with one foot and bring the other knee across your body.\",\"Step back down with control.\",\"Keep your chest tall and core tight.\",\"Alternate sides at a steady pace.\"],\"img\":\"0799.webp\",\"gif\":\"0799.mp4\",\"cat\":\"cardio\",\"desc\":\"A step up where you cross a knee or foot over your body. It raises your heart rate and works the legs and trunk.\"},{\"id\":\"9490\",\"n\":\"step up on box\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand facing a sturdy box or bench at a comfortable height.\",\"Place one foot fully on the box.\",\"Press through that heel and stand up on the box.\",\"Step back down with control.\",\"Finish your reps, then switch legs.\"],\"img\":\"9490.webp\",\"gif\":\"9490.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A simple step onto a box that trains the thighs and glutes one leg at a time.\"},{\"id\":\"3444\",\"n\":\"step up on chair\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Face a sturdy chair.\",\"Place one foot fully on the seat.\",\"Drive through that heel to stand up.\",\"Bring the other foot up.\",\"Step down with control.\",\"Do all reps on one leg, then switch.\"],\"img\":\"3444.webp\",\"gif\":\"3444.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-up onto a sturdy chair, a simple single-leg exercise.\"},{\"id\":\"0800\",\"n\":\"step up opposite elbow to knee twist\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Stand facing a sturdy step with hands by your head.\",\"Step up with your right foot and drive the left knee up.\",\"Twist to bring your right elbow toward your left knee.\",\"Step down carefully and reset.\",\"Repeat on the other side, alternating.\"],\"img\":\"0800.webp\",\"gif\":\"0800.mp4\",\"cat\":\"cardio\",\"desc\":\"A step up that finishes with a twist, bringing an elbow toward the opposite knee. It trains the legs, trunk and coordination.\"},{\"id\":\"6017\",\"n\":\"stepback pulldown\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"core\",\"quadriceps\"],\"st\":[\"Stand tall with your arms overhead.\",\"Step one foot back.\",\"Pull your elbows down and in as if doing a pulldown.\",\"Return your arms and foot to start.\",\"Alternate legs at a steady pace.\"],\"img\":\"6017.webp\",\"gif\":\"6017.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A step back with a downward arm pull that fires up the lats and legs.\",\"fv\":\"5766\"},{\"id\":\"4256\",\"n\":\"stepdown squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand on a step with one foot hanging off the edge.\",\"Hold your arms in front for balance.\",\"Squat down on the standing leg and lower the free heel to the floor.\",\"Keep your knee tracking over your toes.\",\"Press back up to the start.\",\"Finish your reps and switch legs.\"],\"img\":\"4256.webp\",\"gif\":\"4256.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-leg squat that lowers you off a step. It builds quad strength and knee control.\"},{\"id\":\"5399\",\"n\":\"stick assisted isometric core\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Stand tall with your feet hip-width apart and hold a stick in both hands.\",\"Raise the stick to the position you are cued for and keep your arms steady.\",\"Brace your abs as if preparing for a light punch and tuck the ribs down.\",\"Hold for 20-30 seconds while breathing steadily.\",\"Lower the stick slowly and shake out your arms.\"],\"img\":\"5399.webp\",\"gif\":\"5399.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding a stick overhead or in front while you brace your midsection. Builds trunk stability and teaches you to keep the ribs down.\",\"hd\":1},{\"id\":\"9980\",\"n\":\"stick assisted standing shoulder flexion\",\"bp\":\"shoulders\",\"eq\":\"assisted\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"rotator cuff\",\"triceps\"],\"st\":[\"Stand tall holding a stick with both hands at hip level, palms down.\",\"Keep the working arm relaxed and let the other hand lead.\",\"Raise the stick forward and overhead as far as is comfortable.\",\"Pause at the top.\",\"Lower slowly back to the start.\",\"Keep your ribs down and avoid arching your back.\"],\"img\":\"9980.webp\",\"gif\":\"9980.mp4\",\"cat\":\"mobility\",\"desc\":\"A shoulder mobility drill where a stick helps one arm lift forward and overhead. The other hand guides the movement.\"},{\"id\":\"9989\",\"n\":\"stick assisted standing shoulder internal rotation\",\"bp\":\"shoulders\",\"eq\":\"assisted\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"lats\"],\"st\":[\"Stand tall holding a stick behind your back, one hand low and the other high.\",\"Let the lower hand grip the stick as the working arm.\",\"With the top hand, gently pull the stick up so the lower hand rises along your back.\",\"Go until you feel a mild stretch.\",\"Hold for 2 seconds, then release.\",\"Keep your shoulders level, then switch sides.\"],\"img\":\"9989.webp\",\"gif\":\"9989.mp4\",\"cat\":\"mobility\",\"desc\":\"A mobility drill where you use a stick behind your back to help rotate the shoulder inward. It improves reach and range.\"},{\"id\":\"5400\",\"n\":\"stick lat stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"triceps\"],\"st\":[\"Stand tall and grip the stick with both hands, one end held high.\",\"Reach the stick overhead and lean gently away from the higher hand.\",\"Keep your hips square and your ribs from flaring out.\",\"Hold for 20-30 seconds, feeling the stretch along your side and back.\",\"Return to upright and switch sides.\"],\"img\":\"5400.webp\",\"gif\":\"5400.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing stretch that uses a stick to pull the arm overhead and open up the side of your back. Good for tight lats and overhead mobility.\"},{\"id\":\"5402\",\"n\":\"stick lunge with overhead raise stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Hold a stick in both hands and step into a long lunge.\",\"Lower your back knee toward the floor while keeping your torso upright.\",\"Raise the stick overhead with straight arms.\",\"Hold for 20-30 seconds, feeling the stretch at the front of the back hip.\",\"Step back and repeat on the other leg.\"],\"img\":\"5402.webp\",\"gif\":\"5402.mp4\",\"cat\":\"stretching\",\"desc\":\"A lunge combined with a stick held overhead. Opens the hip flexors of the back leg and the shoulders at the same time.\"},{\"id\":\"10589\",\"n\":\"stick lying front raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Lie on your back holding a stick with an overhand grip.\",\"Keep your arms straight.\",\"Raise the stick overhead as far as is comfortable.\",\"Return to your thighs slowly.\",\"Keep your ribs down throughout.\"],\"img\":\"10589.webp\",\"gif\":\"10589.mp4\",\"cat\":\"mobility\",\"desc\":\"Lying on your back, raise a light stick from your hips to overhead. It helps shoulder mobility.\"},{\"id\":\"10740\",\"n\":\"stick lying single arm triceps stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\"],\"st\":[\"Lie on your back holding a stick in both hands.\",\"Bend one arm and take that hand behind your head.\",\"Use the other hand to push the stick and press that elbow down.\",\"Hold for 20-30 seconds.\",\"Keep your neck relaxed.\",\"Switch arms.\"],\"img\":\"10740.webp\",\"gif\":\"10740.mp4\",\"cat\":\"stretching\",\"desc\":\"A triceps stretch on the floor using a stick to deepen the stretch. It opens the back of your upper arm and shoulder.\"},{\"id\":\"5407\",\"n\":\"stick overhead full sumo squat stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"adductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"shoulders\"],\"st\":[\"Stand with your feet wider than your shoulders and toes turned out.\",\"Raise the stick overhead with straight arms.\",\"Sit down between your legs, keeping your chest tall and knees tracking over your toes.\",\"Hold the bottom position for 20-30 seconds.\",\"Press up through your feet to stand.\"],\"img\":\"5407.webp\",\"gif\":\"5407.mp4\",\"cat\":\"stretching\",\"desc\":\"A deep wide-stance squat while holding a stick overhead. Opens the inner thighs and hips and challenges shoulder mobility.\"},{\"id\":\"5404\",\"n\":\"stick pass around stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"rotator cuff\",\"upper back\"],\"st\":[\"Stand tall and hold the stick in front of you with a wide overhand grip.\",\"Keep your arms straight and raise the stick overhead.\",\"Carry it back behind your body in a smooth arc.\",\"Return the same way to the start.\",\"Repeat for 8-10 slow passes and narrow your grip as you get more flexible.\"],\"img\":\"5404.webp\",\"gif\":\"5404.mp4\",\"cat\":\"stretching\",\"desc\":\"Swinging a stick from front to back in a wide arc to open up the shoulders. A classic warm-up for shoulder mobility.\"},{\"id\":\"9184\",\"n\":\"stick shoulder mobilization in abduction\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"lats\"],\"st\":[\"Hold a stick with both hands in front of you.\",\"Keep one arm relaxed and guide it with the other.\",\"Raise the stick sideways and up.\",\"Keep your torso upright.\",\"Pause at the top.\",\"Lower and switch sides.\"],\"img\":\"9184.webp\",\"gif\":\"9184.mp4\",\"cat\":\"mobility\",\"desc\":\"Using a stick, you guide one arm out and up to the side. It opens up shoulder range overhead.\"},{\"id\":\"10935\",\"n\":\"stick shoulder mobilization in abduction behind back\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"triceps\"],\"st\":[\"Stand tall holding a stick behind your back.\",\"Hold it with one hand low and the other high.\",\"Use the low hand to guide the top arm out and up.\",\"Move only in a comfortable range.\",\"Return slowly and switch sides.\"],\"img\":\"10935.webp\",\"gif\":\"10935.mp4\",\"cat\":\"mobility\",\"desc\":\"Using a stick to guide the arm out and back behind you. It improves shoulder range.\"},{\"id\":\"10936\",\"n\":\"stick shoulder rotation over head\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"chest\",\"upper back\"],\"st\":[\"Hold a stick with a wide grip in front of your thighs.\",\"Raise it overhead with straight arms.\",\"Continue the arc behind your back as far as comfortable.\",\"Return along the same path.\",\"Narrow your grip over time.\"],\"img\":\"10936.webp\",\"gif\":\"10936.mp4\",\"cat\":\"mobility\",\"desc\":\"Passing a stick overhead and around the body. It opens up the shoulders.\"},{\"id\":\"5401\",\"n\":\"stick shoulders stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"upper back\"],\"st\":[\"Stand tall and hold the stick behind your back with both hands.\",\"Keep your arms straight and lift the stick slightly away from your body.\",\"Stay tall and avoid arching your lower back.\",\"Hold for 20-30 seconds.\",\"Release slowly and repeat.\"],\"img\":\"5401.webp\",\"gif\":\"5401.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the front of your shoulders and chest using a stick for leverage. Helps with posture and overhead reach.\"},{\"id\":\"5405\",\"n\":\"stick side bend stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lats\"],\"st\":[\"Stand with feet hip-width apart and hold the stick overhead.\",\"Keep your arms straight and your chest open.\",\"Bend slowly to one side without leaning forward.\",\"Hold for 15-20 seconds.\",\"Return to center and bend to the other side.\"],\"img\":\"5405.webp\",\"gif\":\"5405.mp4\",\"cat\":\"stretching\",\"desc\":\"A standing side bend with a stick raised overhead. Lengthens the side of your trunk and the lats.\"},{\"id\":\"5406\",\"n\":\"stick side to front bend stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hamstrings\",\"lats\"],\"st\":[\"Stand with feet hip-width apart and hold the stick overhead.\",\"Bend sideways to one side and hold briefly.\",\"Then turn the torso forward and fold from your hips with a long back.\",\"Hold for 15-20 seconds, then rise slowly.\",\"Repeat on the other side.\"],\"img\":\"5406.webp\",\"gif\":\"5406.mp4\",\"cat\":\"stretching\",\"desc\":\"Combines a side bend with a forward fold while holding a stick overhead. Stretches the side body, lower back and hamstrings.\"},{\"id\":\"9187\",\"n\":\"stick standing front raise\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\"],\"st\":[\"Stand tall holding a stick at your thighs with an overhand grip.\",\"Keep your arms straight.\",\"Raise the stick in front of you to shoulder height or above.\",\"Keep your ribs down and your core tight.\",\"Lower slowly to the start.\",\"Repeat for smooth reps.\"],\"img\":\"9187.webp\",\"gif\":\"9187.mp4\",\"cat\":\"mobility\",\"desc\":\"Raising a stick in front of you with straight arms warms up the shoulders. It is a light, controlled drill.\"},{\"id\":\"9180\",\"n\":\"stick standing shoulder mobilization in extension\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"rotator cuff\"],\"st\":[\"Stand tall holding a stick behind your back with an overhand grip.\",\"Keep your arms straight.\",\"Lift the stick back and away from your body.\",\"Stay tall and avoid leaning forward.\",\"Hold for a moment.\",\"Lower slowly and repeat.\"],\"img\":\"9180.webp\",\"gif\":\"9180.mp4\",\"cat\":\"mobility\",\"desc\":\"Holding a stick behind your back, you lift it away to open the front of the shoulders. It improves shoulder extension.\"},{\"id\":\"9181\",\"n\":\"stick standing shoulder mobilization in external rotation\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Stand holding a stick with both hands, elbows tucked at your sides and bent.\",\"Push the stick with the stronger hand to rotate the other arm outward.\",\"Keep your elbow glued to your side.\",\"Move only as far as is comfortable.\",\"Return to the start slowly.\",\"Switch sides and repeat.\"],\"img\":\"9181.webp\",\"gif\":\"9181.mp4\",\"cat\":\"mobility\",\"desc\":\"Using a stick to guide the arm, you rotate the shoulder outward. It improves external rotation range.\"},{\"id\":\"5403\",\"n\":\"stick standing twist stretch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"upper back\"],\"st\":[\"Stand with feet shoulder-width apart and rest a stick across your upper back.\",\"Hold it with both hands and keep your hips facing forward.\",\"Rotate your upper body slowly to one side.\",\"Pause for a moment, then rotate to the other side.\",\"Repeat for 10-12 slow turns and keep your knees soft.\"],\"img\":\"5403.webp\",\"gif\":\"5403.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle standing rotation with a stick across your shoulders. Loosens the mid back and trunk.\"},{\"id\":\"6811\",\"n\":\"stick subscapularis muscle relax\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"shoulders\"],\"st\":[\"Hold a stick in one hand and bend your elbow to 90 degrees.\",\"Place the other hand on the stick and rotate the arm outward.\",\"Gently push into a comfortable stretch.\",\"Hold for 20-30 seconds.\",\"Release and repeat on the other arm.\"],\"img\":\"6811.webp\",\"gif\":\"6811.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle release for the muscle under the shoulder blade using a stick for leverage. It helps the shoulder feel looser.\"},{\"id\":\"5408\",\"n\":\"stick twist lunge stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"glutes\"],\"st\":[\"Hold the stick across your chest or in front with both hands and step into a lunge.\",\"Keep your front knee over your ankle.\",\"Twist your torso over the front leg.\",\"Hold for 15-20 seconds, breathing evenly.\",\"Untwist, step back and switch legs.\"],\"img\":\"5408.webp\",\"gif\":\"5408.mp4\",\"cat\":\"stretching\",\"desc\":\"A lunge with a trunk twist while holding a stick. Stretches the hip flexors and loosens the spine.\"},{\"id\":\"4402\",\"n\":\"straight angle yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"inner thighs\",\"groin\",\"lower back\"],\"st\":[\"Stand with your feet wide apart and toes pointing forward.\",\"Place your hands on your hips and lengthen your spine.\",\"Hinge forward at the hips with a flat back.\",\"Lower your hands to the floor or to your shins.\",\"Hold for 20-30 seconds, then rise slowly.\"],\"img\":\"4402.webp\",\"gif\":\"4402.mp4\",\"cat\":\"yoga\",\"desc\":\"A wide-legged forward fold that stretches the hamstrings and inner thighs.\"},{\"id\":\"1787\",\"n\":\"straight arms backward chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Stand tall with your feet hip-width apart and reach both straight arms behind you.\",\"Lift your arms slightly and open your chest without leaning back.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1787.webp\",\"gif\":\"1787.mp4\",\"cat\":\"stretching\",\"desc\":\"Reaching straight arms backward opens your chest and the front of your shoulders. Simple, quick and good between sets or after a desk session.\"},{\"id\":\"9047\",\"n\":\"straight hip single leg curl on stability ball\",\"bp\":\"upper legs\",\"eq\":\"stability ball\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"calves\"],\"st\":[\"Lie on your back with one heel on the ball and the other leg raised.\",\"Lift your hips so your body forms a line.\",\"Curl the ball toward your glutes with the one leg.\",\"Keep your hips high.\",\"Extend the leg slowly back out.\",\"Finish the reps and switch legs.\"],\"img\":\"9047.webp\",\"gif\":\"9047.mp4\",\"cat\":\"strength\",\"desc\":\"With your heels on a ball and hips lifted, you curl it in with one leg. It hits the hamstrings and glutes hard.\"},{\"id\":\"4840\",\"n\":\"straight leg dead bug\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back with arms and legs straight up toward the ceiling.\",\"Press your lower back into the floor.\",\"Lower one arm and the opposite leg toward the floor.\",\"Return to the start and switch sides.\",\"Keep your lower back flat the whole time.\"],\"img\":\"4840.webp\",\"gif\":\"4840.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dead bug with straight legs lowering alternately. It is a tougher core challenge with a long lever.\"},{\"id\":\"7419\",\"n\":\"straight leg glute bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with your legs straight and your heels on the floor.\",\"Press your heels down and lift your hips.\",\"Squeeze your glutes at the top.\",\"Keep your ribs down.\",\"Lower slowly.\",\"Repeat for the planned reps.\"],\"img\":\"7419.webp\",\"gif\":\"7419.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bridge with straight legs that shifts more work to the hamstrings and glutes.\"},{\"id\":\"4255\",\"n\":\"straight leg hip bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Lie on your back with your legs straight and heels on the floor.\",\"Place your arms by your sides.\",\"Press through your heels and lift your hips.\",\"Form a straight line from shoulders to heels.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\"],\"img\":\"4255.webp\",\"gif\":\"4255.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hip bridge with your legs straight and heels on the floor. It shifts more work to the hamstrings and glutes.\"},{\"id\":\"3114\",\"n\":\"straight leg kickback (kneeling)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Start on hands and knees with a flat back.\",\"Brace your core.\",\"Extend one leg straight back.\",\"Lift it to hip height and squeeze your glute.\",\"Lower without letting your back arch.\",\"Finish your reps, then switch legs.\"],\"img\":\"3114.webp\",\"gif\":\"3114.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From all fours, you extend one straight leg back and up. It isolates the glutes and hamstrings.\",\"fv\":\"1477\"},{\"id\":\"4008\",\"n\":\"straight leg sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Lie on your back with legs straight.\",\"Cross your arms over your chest.\",\"Curl up to sitting.\",\"Lower with control.\",\"Do not pull on your neck.\"],\"img\":\"4008.webp\",\"gif\":\"4008.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit up with straight legs. It trains the abs and hip flexors.\",\"fv\":\"5000\"},{\"id\":\"2733\",\"n\":\"strongman apollons axle\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"shoulders\",\"trapezius\",\"glutes\",\"triceps\"],\"st\":[\"Stand over the thick axle with feet shoulder width apart and grip it firmly.\",\"Pull it up the thighs with a flat back and clean it to your chest.\",\"Dip and drive with your legs, pressing the axle overhead until your arms lock.\",\"Bring it back down to your chest and then the floor with control.\"],\"img\":\"2733.webp\",\"gif\":\"2733.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting a thick axle bar from the floor to overhead. The fat grip makes it a brutal test for hands, forearms and shoulders.\"},{\"id\":\"2709\",\"n\":\"strongman arm over arm\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"core\",\"upper back\"],\"st\":[\"Face the load with the rope in both hands and feet set wide.\",\"Lean back slightly with a braced core.\",\"Pull the rope with one arm and then the other.\",\"Keep a steady rhythm.\",\"Reach and pull smoothly while keeping your back flat.\"],\"img\":\"2709.webp\",\"gif\":\"2709.mp4\",\"cat\":\"strength\",\"desc\":\"A heavy rope pull where you move hand over hand, training pulling strength and grip.\"},{\"id\":\"2724\",\"n\":\"strongman atlas stones\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"upper back\"],\"st\":[\"Straddle the stone and squat down to wrap your arms around it.\",\"Lift it to your lap by driving the hips forward.\",\"Roll the stone up your chest.\",\"Extend your hips to load it on the platform.\",\"Lower it back to the floor under control and reset.\"],\"img\":\"2724.webp\",\"gif\":\"2724.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting heavy round stones onto a platform, a classic test of full-body strength.\"},{\"id\":\"2734\",\"n\":\"strongman barbell farmers walk\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"trapezius\",\"core\",\"glutes\",\"shoulders\"],\"st\":[\"Stand inside the loaded bar and grip the handle, then lift it to hang at your sides.\",\"Keep your chest tall, shoulders back and core braced.\",\"Walk forward with short, quick steps for a set distance.\",\"Stop, lower the weights to the floor with a flat back, and rest.\"],\"img\":\"2734.webp\",\"gif\":\"2734.mp4\",\"cat\":\"strength\",\"desc\":\"Walking while carrying a heavy loaded bar at your sides. Builds grip strength, upper back and trunk stability.\"},{\"id\":\"3317\",\"n\":\"strongman car flip\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"lower back\",\"shoulders\",\"upper back\"],\"st\":[\"Squat low at the edge of the vehicle with a flat back and hands underneath.\",\"Brace your core and pull your chest up.\",\"Drive hard through your legs and lift the edge to hip height.\",\"Shift your hands and push up and over with your legs and arms.\",\"Let it roll over fully, then step back and reset for the next flip.\"],\"img\":\"3317.webp\",\"gif\":\"3317.mp4\",\"cat\":\"strength\",\"desc\":\"A strongman event where you lift one side of a heavy vehicle and flip it over. It takes full body strength and leg drive.\"},{\"id\":\"2716\",\"n\":\"strongman circle of conan\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\",\"grip muscles\"],\"st\":[\"Pick up the load and hold it against your body.\",\"Brace your core and keep your chest up.\",\"Walk in a circle with steady steps.\",\"Stay balanced and avoid leaning away.\",\"Set the load down under control when you finish.\"],\"img\":\"2716.webp\",\"gif\":\"2716.mp4\",\"cat\":\"strength\",\"desc\":\"A heavy walk in a circle holding a load, building grip, back and leg strength.\"},{\"id\":\"2717\",\"n\":\"strongman crucifix hold\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"forearms\",\"grip muscles\",\"core\"],\"st\":[\"Pick up a weight in each hand and stand tall.\",\"Raise your arms out to the sides until level with your shoulders.\",\"Hold the position with a braced core.\",\"Keep your shoulders down and wrists straight.\",\"Hold as long as you can, then lower with control.\"],\"img\":\"2717.webp\",\"gif\":\"2717.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding weights out to your sides at shoulder height, building shoulder endurance.\",\"hd\":1},{\"id\":\"2729\",\"n\":\"strongman deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"trapezius\"],\"st\":[\"Stand with feet hip width apart and the bar over mid foot.\",\"Hinge down and grip the bar just outside your knees, chest up and back flat.\",\"Brace your core and push the floor away, keeping the bar close to your legs.\",\"Stand tall by driving your hips forward, then lower the bar under control.\"],\"img\":\"2729.webp\",\"gif\":\"2729.mp4\",\"cat\":\"strength\",\"desc\":\"A heavy deadlift in strongman style, pulling a loaded bar from the floor to a full stand. Builds total posterior chain and grip strength.\"},{\"id\":\"2711\",\"n\":\"strongman duck walk\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the weight in front of you and lower into a deep squat.\",\"Keep your chest up.\",\"Take small steps while staying low.\",\"Keep your core braced and your knees tracking over your toes.\",\"Walk the full distance, then stand and rest.\"],\"img\":\"2711.webp\",\"gif\":\"2711.mp4\",\"cat\":\"strength\",\"desc\":\"A low squat-walk holding a load, building leg endurance and hip strength.\"},{\"id\":\"2732\",\"n\":\"strongman dumbbell one arm clean and jerk\",\"bp\":\"full body\",\"eq\":\"dumbbell\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"glutes\",\"quadriceps\",\"core\",\"trapezius\"],\"st\":[\"Stand over a dumbbell with feet shoulder width apart and grab it with one hand.\",\"Pull it explosively to your shoulder with a hip drive, dipping slightly under it.\",\"Dip your knees, then drive up and press the dumbbell overhead to a locked arm.\",\"Lower it back to the shoulder and then the floor with control, then switch arms.\"],\"img\":\"2732.webp\",\"gif\":\"2732.mp4\",\"cat\":\"olympic\",\"desc\":\"A one arm dumbbell clean followed by a jerk overhead. Trains explosive power from the legs through the shoulder.\"},{\"id\":\"3306\",\"n\":\"strongman fingal's fingers\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"hands\",\"wrist flexors\",\"core\"],\"st\":[\"Set up the implement in front of you.\",\"Grip it firmly with both hands.\",\"Brace your core and keep your back flat.\",\"Lift it using your legs and hips.\",\"Hold it steady for a moment.\",\"Lower it under control.\"],\"img\":\"3306.webp\",\"gif\":\"3306.mp4\",\"cat\":\"strength\",\"desc\":\"A strongman grip challenge based on the legend of Fingal's fingers. It tests hand and forearm strength.\"},{\"id\":\"2728\",\"n\":\"strongman front chest squat\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"upper back\"],\"st\":[\"Hold the load tight against your chest with your elbows up.\",\"Stand with feet shoulder width apart.\",\"Squat down keeping your chest tall.\",\"Drive up through your heels.\",\"Lock out the hips at the top.\"],\"img\":\"2728.webp\",\"gif\":\"2728.mp4\",\"cat\":\"strength\",\"desc\":\"A front squat with a heavy load hugged to the chest, building quads and trunk strength.\"},{\"id\":\"2718\",\"n\":\"strongman front hold\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"forearms\",\"core\",\"grip muscles\"],\"st\":[\"Pick up the weights and stand tall.\",\"Raise your arms forward to shoulder height.\",\"Hold with a braced core.\",\"Keep your shoulders down and avoid leaning back.\",\"Hold as long as you can, then lower with control.\"],\"img\":\"2718.webp\",\"gif\":\"2718.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding a load out in front of your body, building shoulder and core endurance.\",\"hd\":1},{\"id\":\"2726\",\"n\":\"strongman hercules hold\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"upper back\",\"shoulders\",\"core\"],\"st\":[\"Pick up the weights and stand tall.\",\"Hold your arms out to your sides.\",\"Brace your core and keep your shoulders down.\",\"Hold the position as long as you can.\",\"Lower under control when done.\"],\"img\":\"2726.webp\",\"gif\":\"2726.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding two heavy weights, arms out, for time to build grip and shoulder endurance.\",\"hd\":1},{\"id\":\"2722\",\"n\":\"strongman hood stones\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"upper back\"],\"st\":[\"Straddle the stone and squat down to hug it.\",\"Lift it to your lap by driving the hips forward.\",\"Roll the stone up your chest.\",\"Extend your hips to land it on the platform.\",\"Lower the stone under control and reset.\"],\"img\":\"2722.webp\",\"gif\":\"2722.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting a heavy stone to a platform, building power through the hips and back.\"},{\"id\":\"2714\",\"n\":\"strongman iceland cross\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"forearms\",\"grip muscles\",\"core\"],\"st\":[\"Pick up a weight in each hand and stand tall.\",\"Raise your arms out to the sides to shoulder height.\",\"Hold them there with a braced core.\",\"Keep your shoulders down and avoid shrugging.\",\"Hold as long as you can, then lower under control.\"],\"img\":\"2714.webp\",\"gif\":\"2714.mp4\",\"cat\":\"isometric\",\"desc\":\"A hold with a heavy weight in each hand, arms held out to the sides, building shoulder and grip endurance.\",\"hd\":1},{\"id\":\"2713\",\"n\":\"strongman iron block press\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Lift the block to your shoulders and set your feet hip width apart.\",\"Brace your core and squeeze your glutes.\",\"Press the block overhead until your arms lock out.\",\"Pause at the top.\",\"Lower it back to your shoulders under control.\"],\"img\":\"2713.webp\",\"gif\":\"2713.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press using a heavy iron block, building shoulder and arm strength.\"},{\"id\":\"3307\",\"n\":\"strongman keg toss\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"shoulders\",\"upper back\"],\"st\":[\"Stand with feet wide and the keg between your legs, gripping it low with both hands.\",\"Hinge at the hips, keep your chest up and your back flat.\",\"Drive your hips forward hard and pull the keg up your body.\",\"Extend fully and throw the keg up and back over the bar.\",\"Reset, step back to the start and repeat with control.\"],\"img\":\"3307.webp\",\"gif\":\"3307.mp4\",\"cat\":\"strength\",\"desc\":\"An explosive strongman lift where you heave a heavy keg up and over a bar behind you. It builds hip power and total body drive.\"},{\"id\":\"2721\",\"n\":\"strongman loading\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\",\"upper back\"],\"st\":[\"Stand over the first object with feet shoulder width apart.\",\"Hinge at the hips and grip it with a flat back.\",\"Lift it by driving through the hips.\",\"Carry it to the platform and load it.\",\"Return, repeat with the next object, and keep your core braced.\"],\"img\":\"2721.webp\",\"gif\":\"2721.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting heavy objects onto a platform in sequence, building full-body strength.\"},{\"id\":\"2707\",\"n\":\"strongman log lift\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"glutes\",\"core\"],\"st\":[\"Stand over the log with feet shoulder width apart and grip it with a firm hold.\",\"Lift it to your lap with a flat back and drive the hips forward.\",\"Rack it on your chest with elbows high.\",\"Dip your knees, then drive up and press the log overhead.\",\"Lock out, then lower with control.\",\"Start light and keep your core braced.\"],\"img\":\"2707.webp\",\"gif\":\"2707.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting a heavy log from the ground to overhead, building full-body strength and power.\"},{\"id\":\"2708\",\"n\":\"strongman mas wrestling\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"forearms\",\"mg\":\"grip muscles\",\"sm\":[\"grip muscles\",\"upper back\",\"core\"],\"st\":[\"Sit facing a partner with feet against theirs and both hands on a stick.\",\"Brace your core.\",\"Pull the stick toward you with a strong grip.\",\"Resist your partner while keeping your back straight.\",\"Keep the effort steady and control the end of each pull.\"],\"img\":\"2708.webp\",\"gif\":\"2708.mp4\",\"cat\":\"strength\",\"desc\":\"A grip and pull contest with a stick, building grip strength and total body tension.\"},{\"id\":\"2725\",\"n\":\"strongman power stairs\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Pick up the load and hold it against your chest.\",\"Brace your core and stand tall.\",\"Climb the stairs one step at a time.\",\"Push through your whole foot and keep your chest up.\",\"Set the load down under control at the top.\"],\"img\":\"2725.webp\",\"gif\":\"2725.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a heavy load up a flight of stairs, building leg power and grip.\"},{\"id\":\"2712\",\"n\":\"strongman sandbag walk\",\"bp\":\"full body\",\"eq\":\"sandbag\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\",\"grip muscles\"],\"st\":[\"Lift the sandbag off the floor and hug it against your chest.\",\"Stand tall with your core braced.\",\"Walk forward at a steady pace with short steps.\",\"Keep your posture upright and do not lean back.\",\"Set the bag down under control at the end.\"],\"img\":\"2712.webp\",\"gif\":\"2712.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a heavy sandbag over a set distance to train grip, back and core.\"},{\"id\":\"2727\",\"n\":\"strongman shield carry\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"upper back\",\"forearms\"],\"st\":[\"Lift the shield and hold it in front of you.\",\"Stand tall with your core braced.\",\"Walk forward at a steady pace.\",\"Keep your posture upright.\",\"Set it down under control when you finish.\"],\"img\":\"2727.webp\",\"gif\":\"2727.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a heavy shield-like load over a distance, training core and back strength.\"},{\"id\":\"2720\",\"n\":\"strongman squats with platform\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand with the platform loaded on your shoulders and feet shoulder width apart.\",\"Brace your core.\",\"Squat down with your chest up and knees tracking over toes.\",\"Drive back up through your heels.\",\"Stand tall and lock out at the top.\"],\"img\":\"2720.webp\",\"gif\":\"2720.mp4\",\"cat\":\"strength\",\"desc\":\"A squat while holding a heavy platform, building leg strength and trunk stability.\"},{\"id\":\"2715\",\"n\":\"strongman timber carry\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"upper back\",\"trapezius\"],\"st\":[\"Lift the timber onto your shoulder and balance it.\",\"Stand tall with your core braced.\",\"Walk with short, steady steps.\",\"Keep the load balanced and avoid leaning to one side.\",\"Set it down under control, then switch shoulders.\"],\"img\":\"2715.webp\",\"gif\":\"2715.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a heavy timber on your shoulder, training full-body strength and stability.\"},{\"id\":\"2730\",\"n\":\"strongman tire flip\",\"bp\":\"full body\",\"eq\":\"tire\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"lower back\",\"shoulders\",\"chest\"],\"st\":[\"Stand close to the tire and squat down, getting your fingers under its edge.\",\"Press your chest against the tire with a flat back and hips low.\",\"Explode up with your legs and hips, lifting the tire as you rise.\",\"Shove the tire over with your hands and shoulders, then step in and reset for the next flip.\"],\"img\":\"2730.webp\",\"gif\":\"2730.mp4\",\"cat\":\"strength\",\"desc\":\"Flipping a large tire end over end by driving up from a deep hinge. A full body power move that hits legs, back and chest.\"},{\"id\":\"2710\",\"n\":\"strongman truck pull\",\"bp\":\"full body\",\"eq\":\"rope\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"grip muscles\",\"core\"],\"st\":[\"Stand facing away from the truck with the rope held across your body.\",\"Lean forward and dig your feet in.\",\"Take short, powerful steps driving through the legs.\",\"Keep your core braced and the rope close.\",\"Pull the full distance, then rest.\"],\"img\":\"2710.webp\",\"gif\":\"2710.mp4\",\"cat\":\"strength\",\"desc\":\"Pulling a heavy truck with a rope over a distance, building leg drive and grip.\"},{\"id\":\"2719\",\"n\":\"strongman viking press\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand inside the frame and grab the handles.\",\"Lift the handles to shoulder height and set your feet.\",\"Brace your core and press overhead.\",\"Lock out your arms.\",\"Lower back to shoulder height under control.\"],\"img\":\"2719.webp\",\"gif\":\"2719.mp4\",\"cat\":\"strength\",\"desc\":\"An overhead press with a heavy viking-press frame, building shoulders and triceps.\"},{\"id\":\"2731\",\"n\":\"strongman weight for height\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"upper back\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"quadriceps\",\"core\",\"triceps\"],\"st\":[\"Hold the weight with both hands low in front of you, feet shoulder width apart.\",\"Swing it back between your legs while hinging at the hips.\",\"Drive your hips and legs up hard and swing the weight up and overhead.\",\"Release it over the bar, then step back and reset for the next throw.\"],\"img\":\"2731.webp\",\"gif\":\"2731.mp4\",\"cat\":\"strength\",\"desc\":\"Throwing a heavy weight up and over a high bar. It is an explosive power move that trains hips, back and shoulders together.\"},{\"id\":\"2723\",\"n\":\"strongman wheelbarrow\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"grip muscles\"],\"st\":[\"Grip the wheelbarrow handles and lift them with a flat back.\",\"Brace your core.\",\"Push forward with strong steps.\",\"Keep your arms straight and your body in line.\",\"Set it down under control at the end.\"],\"img\":\"2723.webp\",\"gif\":\"2723.mp4\",\"cat\":\"strength\",\"desc\":\"Pushing a loaded wheelbarrow over a distance, building leg drive and grip.\"},{\"id\":\"2735\",\"n\":\"strongman yoke walk\",\"bp\":\"full body\",\"eq\":\"barbell\",\"tg\":\"traps\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"quadriceps\",\"upper back\",\"calves\"],\"st\":[\"Step under the yoke so it rests across your upper back and grip the frame.\",\"Brace your core and stand up to lift it off the supports.\",\"Walk forward in quick, controlled steps, keeping your torso upright.\",\"At the end, lower the yoke back onto the supports with care.\"],\"img\":\"2735.webp\",\"gif\":\"2735.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a heavy yoke frame across your upper back and walking with it. Strengthens the legs, trunk and traps.\"},{\"id\":\"4936\",\"n\":\"sumo air squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Stand with feet wide and toes turned out.\",\"Hold your hands in front of your chest.\",\"Sit down between your legs.\",\"Keep your chest up and knees over the toes.\",\"Push through your heels to stand.\",\"Squeeze the glutes at the top.\"],\"img\":\"4936.webp\",\"gif\":\"4936.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat with a wide stance and toes turned out. It trains the glutes and inner thighs.\"},{\"id\":\"1199\",\"n\":\"sumo deadlift high pull\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"trapezius\",\"shoulders\",\"upper back\"],\"st\":[\"Stand with a wide stance and grip the barbell between your legs with hands close together.\",\"Keep your back flat and drive through your legs to stand up.\",\"As the bar passes your hips, pull it up to chest height with your elbows high.\",\"Lower the bar back along the same path.\",\"Keep the bar close to your body throughout.\"],\"img\":\"1199.webp\",\"gif\":\"1199.mp4\",\"cat\":\"strength\",\"desc\":\"A wide-stance deadlift finished with an upright row. It works the thighs, glutes and shoulders in one smooth motion.\"},{\"id\":\"1064\",\"n\":\"sumo squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet wide and toes turned out.\",\"Hold your hands together at your chest.\",\"Sit your hips down and back between your legs.\",\"Keep your knees over your toes and chest upright.\",\"Lower to thigh level.\",\"Push through your heels to stand and squeeze your glutes.\"],\"img\":\"1064.webp\",\"gif\":\"1064.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat in a wide stance with toes turned out. It targets the glutes and inner thighs.\",\"fv\":\"0802\"},{\"id\":\"4417\",\"n\":\"sumo squat floor touch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand with your feet wide and toes turned out.\",\"Push your hips back and squat down.\",\"Touch the floor with your fingertips between your feet.\",\"Keep your chest lifted and your knees tracking over your toes.\",\"Drive through your heels to stand.\"],\"img\":\"4417.webp\",\"gif\":\"4417.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide-stance squat in which you touch the floor between your feet. It trains the glutes, thighs and hip mobility.\"},{\"id\":\"5980\",\"n\":\"sun salutation a\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"triceps\",\"quadriceps\",\"lower back\"],\"st\":[\"Stand in mountain pose and sweep your arms overhead.\",\"Fold forward and step back to plank.\",\"Lower, then press into upward dog and downward dog.\",\"Step forward, rise and return to mountain.\",\"Repeat the flow at a steady pace.\"],\"img\":\"5980.webp\",\"gif\":\"5980.mp4\",\"cat\":\"yoga\",\"desc\":\"A flowing sequence linking breath and movement. Warms up the whole body.\"},{\"id\":\"5981\",\"n\":\"sun salutation b\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"shoulders\",\"core\",\"glutes\",\"triceps\"],\"st\":[\"Stand in mountain pose and sit into a chair pose with your arms overhead.\",\"Fold forward, step back to plank and flow through chaturanga.\",\"Press to downward dog.\",\"Step forward into warrior I on each side, then flow again.\",\"Link every move to your breath.\"],\"img\":\"5981.webp\",\"gif\":\"5981.mp4\",\"cat\":\"yoga\",\"desc\":\"A more powerful flow that adds chair pose and warrior I. Builds heat and leg strength.\"},{\"id\":\"3436\",\"n\":\"superman\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rear deltoids\"],\"st\":[\"Lie face down with arms extended in front.\",\"Lift your arms, chest and legs off the floor together.\",\"Squeeze your glutes and lower back.\",\"Hold for 1-2 seconds.\",\"Lower slowly.\",\"Keep your neck neutral.\"],\"img\":\"3436.webp\",\"gif\":\"3436.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor extension that lifts arms and legs to strengthen the lower back.\",\"fv\":\"0804\"},{\"id\":\"4825\",\"n\":\"superman chest stretch\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper chest\"],\"st\":[\"Lie face down on the floor with your arms extended out wide.\",\"Gently lift your chest off the floor.\",\"Draw your shoulder blades together and back.\",\"Keep your neck in a neutral position.\",\"Hold for 20-30 seconds, then relax.\"],\"img\":\"4825.webp\",\"gif\":\"4825.mp4\",\"cat\":\"stretching\",\"desc\":\"A face-down stretch with arms reaching out, opening the chest and front of the shoulders.\"},{\"id\":\"10345\",\"n\":\"superman pulse\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rear deltoids\"],\"st\":[\"Lie face down with arms extended in front.\",\"Lift your arms, chest and legs a few inches.\",\"Pulse them up and down in small movements.\",\"Keep your neck neutral.\",\"Lower and rest after your set.\"],\"img\":\"10345.webp\",\"gif\":\"10345.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lie face down and lift arms and legs with small pulses. It strengthens the lower back and glutes.\"},{\"id\":\"4939\",\"n\":\"superman row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"lower back\",\"rhomboids\"],\"st\":[\"Lie face down with arms extended in front.\",\"Lift your chest and arms slightly off the floor.\",\"Pull your elbows back toward your ribs as if rowing.\",\"Squeeze your shoulder blades together.\",\"Extend your arms forward again.\",\"Keep your neck neutral.\"],\"img\":\"4939.webp\",\"gif\":\"4939.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone superman with a rowing motion of the arms. It targets the upper back and the muscles along the spine.\"},{\"id\":\"3559\",\"n\":\"superman row with towel\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"lower back\",\"rhomboids\"],\"st\":[\"Lie face down with arms extended overhead, holding a towel taut.\",\"Lift your chest and arms slightly off the floor.\",\"Pull the towel down toward your upper chest, squeezing your shoulder blades.\",\"Extend your arms forward again with control.\",\"Keep your neck neutral and repeat.\"],\"img\":\"3559.webp\",\"gif\":\"3559.mp4\",\"cat\":\"strength\",\"desc\":\"Lie face down with a towel held taut overhead, lift your chest and pull the towel toward you, training the upper back and spine.\"},{\"id\":\"10050\",\"n\":\"superman to push up\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"lower back\",\"glutes\",\"core\"],\"st\":[\"Lie face down with arms extended in front.\",\"Lift your arms, chest and legs off the floor and hold briefly.\",\"Lower and place your hands under your shoulders.\",\"Press up into a push-up.\",\"Lower your chest back to the floor.\",\"Repeat, keeping your body straight.\"],\"img\":\"10050.webp\",\"gif\":\"10050.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A combo move where you lift into a superman on the floor, then press into a push-up.\"},{\"id\":\"5049\",\"n\":\"superman w\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"upper back\",\"trapezius\",\"hamstrings\"],\"st\":[\"Lie face down with elbows bent and hands by your head.\",\"Squeeze your glutes.\",\"Lift your chest, arms and legs slightly off the floor.\",\"Pull your shoulder blades together and hold for a second.\",\"Lower slowly.\"],\"img\":\"5049.webp\",\"gif\":\"5049.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Face down, lift your chest and legs with arms in a W. It builds the lower back and upper back.\"},{\"id\":\"5048\",\"n\":\"superman w to y\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"upper back\",\"trapezius\",\"hamstrings\"],\"st\":[\"Lie face down, arms in a W with elbows bent.\",\"Lift your chest and legs slightly off the floor.\",\"Reach your arms forward into a Y.\",\"Return to the W while keeping the lift.\",\"Lower fully after your reps.\"],\"img\":\"5048.webp\",\"gif\":\"5048.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, lift your body and move your arms from a W to a Y. It trains the whole back side.\"},{\"id\":\"5517\",\"n\":\"supinated grip inverted row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Lie under a bar set at about waist height and grip it with palms facing you.\",\"Hang with your body straight and heels on the floor.\",\"Pull your chest toward the bar, squeezing your shoulder blades.\",\"Pause briefly at the top.\",\"Lower with control until your arms are straight.\"],\"img\":\"5517.webp\",\"gif\":\"5517.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row hanging under a bar with an underhand grip. Builds the back and biceps.\",\"nd\":[\"pull-up bar\"]},{\"id\":\"5474\",\"n\":\"supinated narrow grip pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"upper back\",\"forearms\"],\"st\":[\"Grip the bar with palms facing you, hands close together.\",\"Hang with arms straight and shoulders pulled down.\",\"Pull your elbows down and in until your chin is above the bar.\",\"Lower under control to full arm extension.\",\"Keep your legs still and avoid swinging.\"],\"img\":\"5474.webp\",\"gif\":\"5474.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Chin-up style pull-up with a close underhand grip that puts extra work on the biceps along with the lats.\"},{\"id\":\"1818\",\"n\":\"supination bar suspension stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"lats\",\"shoulders\"],\"st\":[\"Grip a pull-up bar with an underhand, shoulder-width grip.\",\"Let your body hang with your arms straight, relaxing your shoulders downward.\",\"Take as much weight through your legs as you need to stay comfortable.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1818.webp\",\"gif\":\"1818.mp4\",\"cat\":\"stretching\",\"desc\":\"Hanging from a bar with palms facing you stretches the biceps and forearms. Let your body weight do the lengthening.\"},{\"id\":\"1491\",\"n\":\"supine spinal twist yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"chest\"],\"st\":[\"Lie on your back with your arms out to the sides.\",\"Pull one knee toward your chest.\",\"Guide that knee across your body toward the floor on the opposite side.\",\"Keep both shoulders on the floor and turn your head the other way if comfortable.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1491.webp\",\"gif\":\"1491.mp4\",\"cat\":\"yoga\",\"desc\":\"A relaxing lying twist that mobilises the spine and stretches the hips and sides of the trunk.\"},{\"id\":\"6705\",\"n\":\"supine windshield wipers\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower back\"],\"st\":[\"Lie on your back with arms out to the sides, palms down.\",\"Lift your legs straight up over your hips.\",\"Lower both legs to one side without touching the floor.\",\"Bring them back up through the middle.\",\"Lower to the other side and keep alternating.\"],\"img\":\"6705.webp\",\"gif\":\"6705.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back, you swing the legs side to side like wipers. It strengthens the obliques and trunk control.\"},{\"id\":\"6879\",\"n\":\"supported headstand yoga pose sirsasana\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Kneel and place your forearms on the mat with your fingers interlaced.\",\"Set the crown of your head lightly on the floor against your hands.\",\"Lift your knees and walk your feet toward your face.\",\"Lift your legs slowly, using your core, until they point to the ceiling.\",\"Keep most of the weight in your forearms and shoulders.\",\"Hold briefly, then lower with control and rest in child's pose.\"],\"img\":\"6879.webp\",\"gif\":\"6879.mp4\",\"cat\":\"yoga\",\"desc\":\"An inversion where your forearms and head share the load, building shoulder strength and balance.\"},{\"id\":\"1953\",\"n\":\"supported one leg standing hip flexor and knee extensor stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"glutes\"],\"st\":[\"Stand tall holding a wall or chair for support.\",\"Bend one knee and hold the ankle behind you.\",\"Pull the heel toward your glutes and push the hip slightly forward.\",\"Keep your knees close together.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1953.webp\",\"gif\":\"1953.mp4\",\"cat\":\"stretching\",\"desc\":\"A supported standing quad stretch that also opens the front of the hip.\"},{\"id\":\"4797\",\"n\":\"supported squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Stand holding a stable support at about chest height, feet shoulder width apart.\",\"Brace your core and keep your chest up.\",\"Sit your hips back and bend your knees to lower down.\",\"Go as deep as you can with your heels down.\",\"Push through your feet to stand back up.\",\"Use the support for balance, not to pull yourself up.\"],\"img\":\"4797.webp\",\"gif\":\"4797.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat where you hold onto something for balance. It is a friendly way to practise depth and build leg strength.\"},{\"id\":\"1159\",\"n\":\"suspender abduction lunge\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"adductors\"],\"st\":[\"Hold the handles and stand tall.\",\"Step out wide to one side.\",\"Bend that knee and push the hips back.\",\"Keep your chest up and the other leg straight.\",\"Push off to return.\",\"Alternate sides.\"],\"img\":\"1159.webp\",\"gif\":\"1159.mp4\",\"cat\":\"strength\",\"desc\":\"A side lunge with the straps for balance, working the outer hips and legs.\"},{\"id\":\"4798\",\"n\":\"suspender alternate superman\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"core\"],\"st\":[\"Place your feet in the suspension straps and get into a plank face down.\",\"Brace your core and keep your hips level.\",\"Lift one arm forward while keeping your body steady.\",\"Return it, then lift the other arm.\",\"Move slowly and avoid sagging your lower back.\",\"Alternate sides for the full set.\"],\"img\":\"4798.webp\",\"gif\":\"4798.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A superman variation with the feet in suspension straps, lifting opposite arm and leg in turn. It trains the lower back and core.\"},{\"id\":\"1070\",\"n\":\"suspender arm curl\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"core\"],\"st\":[\"Hold the handles and lean back with arms extended.\",\"Keep your body straight.\",\"Bend your elbows to pull yourself up.\",\"Squeeze the biceps.\",\"Lower slowly.\"],\"img\":\"1070.webp\",\"gif\":\"1070.mp4\",\"cat\":\"strength\",\"desc\":\"Curl yourself toward the straps while leaning back. It works the biceps.\"},{\"id\":\"1108\",\"n\":\"suspender arm curl to ears\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"core\"],\"st\":[\"Hold the handles with palms up and lean back with arms extended.\",\"Keep your body straight from head to heels.\",\"Bend your elbows and pull your hands toward your ears.\",\"Keep elbows high and out to the sides.\",\"Squeeze the biceps at the top.\",\"Lower with control until the arms are straight.\"],\"img\":\"1108.webp\",\"gif\":\"1108.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You curl your body up toward your hands with the straps at head height, a bodyweight biceps builder.\"},{\"id\":\"1071\",\"n\":\"suspender bent knee inverted row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Lie under the straps and grip the handles.\",\"Bend your knees with feet flat.\",\"Lift your hips and pull your chest toward the handles.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\"],\"img\":\"1071.webp\",\"gif\":\"1071.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Row yourself up under straps with knees bent. It builds the back.\"},{\"id\":\"1109\",\"n\":\"suspender biceps clutch\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"upper back\"],\"st\":[\"Grab the handles palms up and lean back with arms straight.\",\"Keep your body rigid.\",\"Curl yourself up, drawing the hands in beside your head.\",\"Hold the top position for a second and squeeze.\",\"Lower slowly to straight arms.\",\"Walk your feet closer to make it easier.\"],\"img\":\"1109.webp\",\"gif\":\"1109.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A strap curl where you hold the contraction close to the head, great for biceps peak work and arm control.\"},{\"id\":\"6232\",\"n\":\"suspender biceps curl\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"core\"],\"st\":[\"Hold the straps and lean back.\",\"Extend your arms.\",\"Curl your hands toward your forehead.\",\"Keep your elbows high.\",\"Lower slowly.\",\"Keep your body straight.\"],\"img\":\"6232.webp\",\"gif\":\"6232.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight biceps curl on suspension straps. It builds the biceps.\"},{\"id\":\"1110\",\"n\":\"suspender body saw\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lower back\",\"core\"],\"st\":[\"Place your feet in the straps and set up on your forearms.\",\"Brace your abs and keep your body straight.\",\"Shift your body backward by pushing through the forearms.\",\"Rock forward past the starting point in a short controlled motion.\",\"Keep your hips level, do not let your lower back arch.\",\"Continue for the planned reps or time.\"],\"img\":\"1110.webp\",\"gif\":\"1110.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a forearm plank with feet in the straps, you rock your body back and forth like a saw to challenge the core.\"},{\"id\":\"1154\",\"n\":\"suspender calf raise\",\"bp\":\"lower legs\",\"eq\":\"suspension trainer\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\",\"feet\"],\"st\":[\"Hold the handles and stand with feet hip width apart.\",\"Keep your body upright.\",\"Rise onto the balls of your feet as high as you can.\",\"Pause and squeeze the calves.\",\"Lower the heels slowly below the start if comfortable.\",\"Use the straps only for balance.\"],\"img\":\"1154.webp\",\"gif\":\"1154.mp4\",\"cat\":\"strength\",\"desc\":\"Holding the straps for balance, you rise onto your toes to train the calves.\"},{\"id\":\"1072\",\"n\":\"suspender chest dip\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Support yourself on the straps with arms straight.\",\"Lean slightly forward.\",\"Lower until elbows reach 90 degrees.\",\"Press back up.\",\"Keep the straps steady.\"],\"img\":\"1072.webp\",\"gif\":\"1072.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Dip between straps. It works the chest and triceps.\"},{\"id\":\"1073\",\"n\":\"suspender chest press\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Face away from the anchor and hold the handles at chest level.\",\"Lean forward in a straight line.\",\"Press your body away.\",\"Squeeze the chest.\",\"Return slowly.\"],\"img\":\"1073.webp\",\"gif\":\"1073.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Press yourself away from the straps. It works the chest.\"},{\"id\":\"1111\",\"n\":\"suspender close grip chest press\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Hold the handles close together and lean forward with arms straight.\",\"Keep your body in a straight line.\",\"Lower your chest between the handles, elbows tucked close.\",\"Pause when your chest is near your hands.\",\"Press back up until the arms are straight.\",\"Move your feet back to increase difficulty.\"],\"img\":\"1111.webp\",\"gif\":\"1111.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A narrow-hand push on the straps that shifts work toward the triceps and inner chest.\"},{\"id\":\"1112\",\"n\":\"suspender crunch\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"shoulders\"],\"st\":[\"Put your feet in the straps and set a straight-arm plank.\",\"Keep shoulders over hands.\",\"Pull your knees toward your chest while rounding your spine slightly.\",\"Squeeze your abs at the top.\",\"Extend your legs back to plank slowly.\",\"Avoid dropping the hips as you return.\"],\"img\":\"1112.webp\",\"gif\":\"1112.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with feet in the straps, you pull the knees in and curl the hips up, a direct ab move.\"},{\"id\":\"1113\",\"n\":\"suspender face pull\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rotator cuff\"],\"st\":[\"Hold the handles with palms facing in and lean back.\",\"Keep your body straight and arms extended.\",\"Pull the handles toward your forehead, elbows flaring high.\",\"Squeeze your shoulder blades together at the end.\",\"Lower slowly to full arm extension.\",\"Do not let your hips drop.\"],\"img\":\"1113.webp\",\"gif\":\"1113.mp4\",\"cat\":\"strength\",\"desc\":\"A strap row to the face with elbows high that targets the rear shoulders and upper back.\"},{\"id\":\"1074\",\"n\":\"suspender fly\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Face away from the anchor, hands at chest level.\",\"Lean forward with arms together.\",\"Open your arms wide.\",\"Pull back together.\",\"Keep your elbows slightly bent.\"],\"img\":\"1074.webp\",\"gif\":\"1074.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Open your arms wide against the straps. It stretches and works the chest.\"},{\"id\":\"4094\",\"n\":\"suspender forward lunge with rear fly\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"quadriceps\",\"glutes\"],\"st\":[\"Hold the straps with both hands, leaning back slightly with arms extended.\",\"Step one foot forward into a lunge.\",\"As you lower, pull your arms out wide in a rear fly.\",\"Push through the front foot to return to standing and bring your hands together.\",\"Switch legs on the next rep.\"],\"img\":\"4094.webp\",\"gif\":\"4094.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge combined with a rear delt fly on suspension straps, working legs, shoulders and upper back together.\"},{\"id\":\"1075\",\"n\":\"suspender front raise\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"chest\"],\"st\":[\"Hold the handles and lean back with arms down.\",\"Keep your body straight.\",\"Raise your arms overhead.\",\"Pause.\",\"Lower slowly.\"],\"img\":\"1075.webp\",\"gif\":\"1075.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Raise your body with arms in front using straps. It works the front delts.\"},{\"id\":\"1115\",\"n\":\"suspender handstand push up\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Set the straps low and place your hands in the handles in a pike position.\",\"Kick or walk your feet up into an inverted position with a tight core.\",\"Bend your elbows to lower your head between the handles.\",\"Press back up until your arms are straight.\",\"Keep your body steady, using a wall or spotter if needed.\",\"Come down carefully when finished.\"],\"img\":\"1115.webp\",\"gif\":\"1115.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An advanced inverted press with hands on the straps, working the triceps and shoulders strongly.\"},{\"id\":\"9704\",\"n\":\"suspender headstand\",\"bp\":\"full body\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"triceps\"],\"st\":[\"Set the straps at a low height.\",\"Place your forearms or hands on the floor.\",\"Lift your hips and place your feet in the straps.\",\"Press your body up into a stable position.\",\"Hold for 10 to 20 seconds.\",\"Lower slowly and rest.\"],\"img\":\"9704.webp\",\"gif\":\"9704.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A headstand variation using suspension straps for support. It builds balance and shoulder strength.\"},{\"id\":\"1157\",\"n\":\"suspender hip hinge\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"core\"],\"st\":[\"Hold the handles with arms straight and feet hip width apart.\",\"Soften your knees.\",\"Push your hips back with a flat back.\",\"Lean on the straps for balance.\",\"Drive your hips forward to stand tall.\",\"Squeeze the glutes at the top.\"],\"img\":\"1157.webp\",\"gif\":\"1157.mp4\",\"cat\":\"strength\",\"desc\":\"Holding the straps, you hinge the hips back and forth to train the glutes and hamstrings.\"},{\"id\":\"1116\",\"n\":\"suspender incline push up\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Hold the handles and walk your feet back so your body is at a slant.\",\"Keep your body straight and core tight.\",\"Lower your chest to the handles by bending the elbows.\",\"Keep elbows at about 45 degrees.\",\"Press up to straight arms.\",\"Walk your feet back to make it harder.\"],\"img\":\"1116.webp\",\"gif\":\"1116.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the hands in the straps and the body angled upward, a gentler version that builds the chest.\"},{\"id\":\"1117\",\"n\":\"suspender jump squat\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Hold the handles with slightly bent arms and stand tall.\",\"Lower into a squat with your chest up.\",\"Drive through your feet and jump up.\",\"Land softly on the balls of your feet and sink into the next squat.\",\"Use the straps for balance only.\",\"Keep knees tracking over toes.\"],\"img\":\"1117.webp\",\"gif\":\"1117.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Holding the straps for balance, you squat and jump explosively to build leg power.\"},{\"id\":\"1119\",\"n\":\"suspender lunge back crossover\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\"],\"st\":[\"Hold the handles and stand facing the anchor.\",\"Step one leg back and across behind the other.\",\"Lower until the front thigh is near parallel.\",\"Keep your chest tall and front knee over the ankle.\",\"Push through the front heel to stand.\",\"Finish your reps, then switch sides.\"],\"img\":\"1119.webp\",\"gif\":\"1119.mp4\",\"cat\":\"strength\",\"desc\":\"A rear lunge where the back leg crosses behind the front one, hitting the glutes and outer hips.\"},{\"id\":\"1120\",\"n\":\"suspender middle row\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\"],\"st\":[\"Grip the handles and lean back with arms straight.\",\"Keep your body in a straight line.\",\"Pull your chest toward your hands, elbows close by.\",\"Squeeze the shoulder blades together.\",\"Lower slowly to straight arms.\",\"Step forward to ease the load.\"],\"img\":\"1120.webp\",\"gif\":\"1120.mp4\",\"cat\":\"strength\",\"desc\":\"A strap row to mid-chest height that works the upper back and arms using your body weight.\"},{\"id\":\"1121\",\"n\":\"suspender mountain climber push up\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\",\"chest\"],\"st\":[\"Place your feet in the straps and set up in a high plank.\",\"Do one push-up, keeping your body straight.\",\"Drive one knee toward your chest, then the other.\",\"Alternate legs in a steady rhythm.\",\"Keep your hips level.\",\"Repeat the sequence for the set.\"],\"img\":\"1121.webp\",\"gif\":\"1121.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hard conditioning move combining a push-up with mountain climber knee drives while the feet sit in the straps.\"},{\"id\":\"1122\",\"n\":\"suspender oblique rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Hold the handles kneeling or standing, arms in front.\",\"Brace your core and keep your back flat.\",\"Roll forward and angle your arms toward one side.\",\"Go only as far as you can hold a flat back.\",\"Pull back to the start using your abs.\",\"Alternate sides each rep.\"],\"img\":\"1122.webp\",\"gif\":\"1122.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Rolling out on the straps with a slight side angle, you hit the obliques and deep core.\"},{\"id\":\"1123\",\"n\":\"suspender one arm biceps curl\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"brachialis\",\"obliques\"],\"st\":[\"Hold one handle palm up and lean back at an angle.\",\"Keep your feet planted and body straight.\",\"Bend the elbow and pull your body toward your hand.\",\"Squeeze the biceps at the top.\",\"Lower slowly to a straight arm.\",\"Finish your reps and switch arms.\"],\"img\":\"1123.webp\",\"gif\":\"1123.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You curl yourself up with one arm holding a single strap, a tough unilateral biceps move.\"},{\"id\":\"1124\",\"n\":\"suspender one arm chest press\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"obliques\"],\"st\":[\"Hold one handle, lean forward and place your feet wide for balance.\",\"Keep your hips square.\",\"Bend your elbow and lower your chest toward the hand.\",\"Resist twisting at the torso.\",\"Press back to a straight arm.\",\"Do all reps, then switch sides.\"],\"img\":\"1124.webp\",\"gif\":\"1124.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A single-arm push on one strap that trains the chest while the core fights rotation.\"},{\"id\":\"1125\",\"n\":\"suspender one arm leg push up\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"shoulders\"],\"st\":[\"Put your feet in the straps and set a plank with one hand on the floor.\",\"Brace your core firmly.\",\"Lower your chest by bending the supporting elbow.\",\"Keep your hips level and avoid twisting.\",\"Press back up.\",\"Complete your reps, then switch hands.\"],\"img\":\"1125.webp\",\"gif\":\"1125.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with feet in the straps and one hand lifted, building chest strength and total-body stability.\"},{\"id\":\"1126\",\"n\":\"suspender one leg chest press\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"glutes\"],\"st\":[\"Hold the handles, lean forward and lift one foot off the floor.\",\"Keep your body straight.\",\"Lower your chest between your hands.\",\"Press back up without letting the hips drop.\",\"Keep the raised leg in line with your body.\",\"Switch legs after your set.\"],\"img\":\"1126.webp\",\"gif\":\"1126.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A strap chest press with one foot lifted, adding a balance challenge to the pressing movement.\"},{\"id\":\"1156\",\"n\":\"suspender pendulum\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Put your feet in the straps and set a high plank.\",\"Brace your core.\",\"Swing your legs together to one side.\",\"Swing back through the center to the other side.\",\"Keep the movement slow and controlled.\",\"Keep your shoulders stable.\"],\"img\":\"1156.webp\",\"gif\":\"1156.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying or planking with the feet in the straps, you swing the legs side to side like a pendulum to train the obliques.\"},{\"id\":\"1127\",\"n\":\"suspender pull up v. 2\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Hold the handles overhead and hang with arms straight.\",\"Brace your core.\",\"Pull your chest up toward the handles, elbows down.\",\"Squeeze your back at the top.\",\"Lower slowly to full extension.\",\"Bend your knees or lean back to make it easier.\"],\"img\":\"1127.webp\",\"gif\":\"1127.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A strap-based pull-up variation that builds the lats and arms, with an angled body you can adjust.\"},{\"id\":\"1128\",\"n\":\"suspender push up\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Hold the handles and get into a plank with hands under shoulders.\",\"Keep your body in one line.\",\"Lower your chest between the handles.\",\"Keep the straps steady and elbows at about 45 degrees.\",\"Press up to straight arms.\",\"Do not let the hips sag.\"],\"img\":\"1128.webp\",\"gif\":\"1128.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with your hands in unstable straps, making the chest, arms and core work harder.\"},{\"id\":\"9503\",\"n\":\"suspender rear delt row\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\",\"biceps\"],\"st\":[\"Hold the handles and lean back with arms straight and body in a line.\",\"Brace your core and glutes.\",\"Pull your hands toward your chest with elbows flared out wide.\",\"Squeeze your shoulder blades together.\",\"Lower slowly until your arms are straight again.\"],\"img\":\"9503.webp\",\"gif\":\"9503.mp4\",\"cat\":\"strength\",\"desc\":\"A suspension-strap row with wide elbows that targets the rear delts and upper back.\",\"fv\":\"1089\"},{\"id\":\"1129\",\"n\":\"suspender rear lunge\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the handles and stand tall, facing the anchor.\",\"Step one leg back and lower into a lunge.\",\"Keep your front knee above the ankle.\",\"Press through the front heel to return.\",\"Use the straps for balance only.\",\"Alternate legs or finish one side first.\"],\"img\":\"1129.webp\",\"gif\":\"1129.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge with the hands on the straps for balance, working the thighs and glutes.\"},{\"id\":\"1130\",\"n\":\"suspender reverse fly wake up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"rhomboids\",\"trapezius\"],\"st\":[\"Hold the handles and lean back with arms straight in front.\",\"Keep your body in a line.\",\"Open your arms wide, pulling the shoulder blades together.\",\"Keep arms slightly bent and level with the shoulders.\",\"Return slowly to the start.\",\"Walk your feet forward to lighten the load.\"],\"img\":\"1130.webp\",\"gif\":\"1130.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse fly on the straps that works the rear shoulders and upper back to improve posture.\"},{\"id\":\"4799\",\"n\":\"suspender rollout v. 2\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"lats\"],\"st\":[\"Kneel facing the anchor and hold the suspension handles under your shoulders.\",\"Brace your core and tuck your pelvis slightly.\",\"Roll your arms forward as your body leans out in a straight line.\",\"Go only as far as you can keep your back flat.\",\"Pull back to the start using your abs.\",\"Keep your ribs down throughout.\"],\"img\":\"4799.webp\",\"gif\":\"4799.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A rollout using suspension handles, a second variation. It challenges the abs as you extend your body forward and pull back.\"},{\"id\":\"6220\",\"n\":\"suspender row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\"],\"st\":[\"Hold the straps and lean back.\",\"Keep your body in a straight line.\",\"Pull your chest toward your hands.\",\"Squeeze your shoulder blades.\",\"Lower slowly.\",\"Keep your core tight.\"],\"img\":\"6220.webp\",\"gif\":\"6220.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row on suspension straps. It builds the back and biceps.\",\"fv\":\"1092\"},{\"id\":\"1131\",\"n\":\"suspender side cross lunge\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Hold the handles and stand tall.\",\"Step one leg out and slightly behind the other, crossing the body.\",\"Sink back into the hip with a flat back.\",\"Push through the working foot to return.\",\"Keep your knee in line with your toes.\",\"Switch sides after your reps.\"],\"img\":\"1131.webp\",\"gif\":\"1131.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge stepping out to the side and across, with straps for support, training the glutes and inner thighs.\"},{\"id\":\"1132\",\"n\":\"suspender side lunge\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"hamstrings\"],\"st\":[\"Hold the handles and stand with feet together.\",\"Step out wide to one side.\",\"Bend that knee and push your hips back, keeping the other leg straight.\",\"Keep your chest up and heel down.\",\"Push off to return to the start.\",\"Alternate sides.\"],\"img\":\"1132.webp\",\"gif\":\"1132.mp4\",\"cat\":\"strength\",\"desc\":\"Stepping wide to the side while holding the straps works the thighs, glutes and inner legs.\"},{\"id\":\"1158\",\"n\":\"suspender side stretch\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"adductors\",\"mg\":\"groin\",\"sm\":[\"groin\",\"inner thighs\",\"hamstrings\"],\"st\":[\"Hold the handles and step your legs wide.\",\"Shift your weight to one side and bend that knee.\",\"Keep the other leg straight.\",\"Sit back into the stretch.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"1158.webp\",\"gif\":\"1158.mp4\",\"cat\":\"stretching\",\"desc\":\"Using the straps for support, you sink into a wide side stance to stretch the inner thighs.\"},{\"id\":\"1133\",\"n\":\"suspender single arm rear delt row\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"biceps\"],\"st\":[\"Hold one handle and lean back at an angle.\",\"Keep your hips level and free hand on your chest or hip.\",\"Pull the handle toward your shoulder with the elbow flared out.\",\"Squeeze the rear delt at the end.\",\"Lower slowly to a straight arm.\",\"Finish your reps, then switch arms.\"],\"img\":\"1133.webp\",\"gif\":\"1133.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm strap row with the elbow flared, aimed at the rear shoulder.\"},{\"id\":\"1155\",\"n\":\"suspender single leg deadlift\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Hold the handles and stand on one leg.\",\"Soften the standing knee.\",\"Hinge at the hip as the other leg extends behind you.\",\"Keep your back flat and hips square.\",\"Squeeze the glute to stand back up.\",\"Finish your reps, then switch legs.\"],\"img\":\"1155.webp\",\"gif\":\"1155.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg hip hinge with the straps for balance, training the hamstrings and glutes.\"},{\"id\":\"1135\",\"n\":\"suspender single leg plank\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Place your feet in the straps and rest on your forearms.\",\"Lift one leg a bit higher than the other.\",\"Keep your hips square and abs tight.\",\"Hold for 20-30 seconds.\",\"Lower and switch legs.\",\"Do not let the lower back arch.\"],\"img\":\"1135.webp\",\"gif\":\"1135.mp4\",\"cat\":\"isometric\",\"desc\":\"A forearm plank with feet in the straps and one leg raised, fighting rotation and sag.\",\"hd\":1},{\"id\":\"1134\",\"n\":\"suspender single leg plank straight arm\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"core\"],\"st\":[\"Put your feet in the straps and set a high plank.\",\"Lift one leg slightly higher.\",\"Keep your hips level and body straight.\",\"Hold for 20-30 seconds.\",\"Lower the leg and switch sides.\",\"Breathe steadily throughout.\"],\"img\":\"1134.webp\",\"gif\":\"1134.mp4\",\"cat\":\"isometric\",\"desc\":\"A straight-arm plank with feet in the straps and one leg lifted, which challenges core stability.\",\"hd\":1},{\"id\":\"1136\",\"n\":\"suspender single leg squat figure\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the handles and stand on one leg, other leg forward.\",\"Sit your hips back and bend the knee.\",\"Lower as far as you can control.\",\"Keep your knee over your toes and chest tall.\",\"Drive through the heel to stand.\",\"Finish your reps, then switch legs.\"],\"img\":\"1136.webp\",\"gif\":\"1136.mp4\",\"cat\":\"strength\",\"desc\":\"A one-leg squat holding the straps for support, building leg strength and balance.\"},{\"id\":\"1137\",\"n\":\"suspender sit up\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"core\"],\"st\":[\"Lie on your back with your feet in the straps and knees bent.\",\"Place your hands by your head or across your chest.\",\"Curl your torso up toward your knees.\",\"Squeeze the abs at the top.\",\"Lower back down slowly.\",\"Avoid pulling on your neck.\"],\"img\":\"1137.webp\",\"gif\":\"1137.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying down with your feet in the straps, you sit up to train the abs.\"},{\"id\":\"1138\",\"n\":\"suspender spiderman push up\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Put your feet in the straps and set a high plank.\",\"Lower into a push-up.\",\"As you descend, bring one knee toward the same elbow.\",\"Press up and extend the leg back.\",\"Alternate sides each rep.\",\"Keep your hips low and steady.\"],\"img\":\"1138.webp\",\"gif\":\"1138.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with feet in the straps where one knee drives toward the elbow as you lower.\"},{\"id\":\"1139\",\"n\":\"suspender split fly\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"chest\",\"sm\":[\"chest\",\"core\"],\"st\":[\"Hold the handles and step into a split stance leaning forward.\",\"Keep arms slightly bent and hands in front of you.\",\"Open your arms out wide to the sides.\",\"Squeeze at the end of the stretch without shrugging.\",\"Bring the arms back together under control.\",\"Switch the lead leg halfway through.\"],\"img\":\"1139.webp\",\"gif\":\"1139.mp4\",\"cat\":\"strength\",\"desc\":\"A fly on the straps with a split stance, opening the arms to work the shoulders and chest.\"},{\"id\":\"1140\",\"n\":\"suspender sprinter\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold the handles and lean slightly forward.\",\"Stand on one leg with the other knee raised.\",\"Drive one knee up as the opposite arm moves.\",\"Switch legs with a quick hop.\",\"Stay on the balls of your feet.\",\"Keep your core tight and pace steady.\"],\"img\":\"1140.webp\",\"gif\":\"1140.mp4\",\"cat\":\"plyometrics\",\"desc\":\"You hold the straps and drive the knees like a sprinter, a quick leg and cardio move.\"},{\"id\":\"1143\",\"n\":\"suspender squat\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the handles with arms extended.\",\"Stand with feet shoulder width apart.\",\"Sit your hips back and bend your knees.\",\"Lower until your thighs are parallel to the floor.\",\"Push through the heels to stand.\",\"Keep your chest tall and knees tracking over toes.\"],\"img\":\"1143.webp\",\"gif\":\"1143.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat where you hold the straps for balance and can lean back for depth.\"},{\"id\":\"1141\",\"n\":\"suspender squat arms overhead\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Hold the handles overhead with arms straight.\",\"Stand with feet shoulder width apart.\",\"Sit back and down into a squat.\",\"Keep your arms up and chest tall.\",\"Drive through your heels to stand.\",\"Do not let the lower back round.\"],\"img\":\"1141.webp\",\"gif\":\"1141.mp4\",\"cat\":\"strength\",\"desc\":\"A squat while holding the straps overhead, working the legs and mobility of the shoulders and torso.\"},{\"id\":\"6222\",\"n\":\"suspender squat jump\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Hold the straps with your arms extended.\",\"Lower into a squat.\",\"Jump up explosively.\",\"Land softly.\",\"Go straight into the next squat.\",\"Keep your chest tall.\"],\"img\":\"6222.webp\",\"gif\":\"6222.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A squat jump holding suspension straps for balance. It builds explosive leg power.\"},{\"id\":\"1144\",\"n\":\"suspender standing ab rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\"],\"st\":[\"Hold the handles in front of you and lean forward.\",\"Brace your abs and tuck the pelvis.\",\"Extend your arms overhead as your body leans out.\",\"Stop before your lower back arches.\",\"Pull back to the start with your abs.\",\"Take a smaller range if you need.\"],\"img\":\"1144.webp\",\"gif\":\"1144.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Standing with the straps, you lean forward and roll out with straight arms, a challenging core move.\"},{\"id\":\"1145\",\"n\":\"suspender star plank\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Put your feet in the straps and set a high plank.\",\"Spread your legs wide.\",\"Keep your hips level and body straight.\",\"Brace the abs.\",\"Hold for 20-30 seconds.\",\"Breathe steadily and do not sag.\"],\"img\":\"1145.webp\",\"gif\":\"1145.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank with the feet in the straps spread wide like a star, challenging the core and hips.\",\"hd\":1},{\"id\":\"1146\",\"n\":\"suspender star push up\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"shoulders\",\"glutes\"],\"st\":[\"Place your feet in the straps spread wide in a high plank.\",\"Keep your core tight.\",\"Lower your chest toward the floor.\",\"Keep elbows at about 45 degrees.\",\"Press back up.\",\"Hold the wide leg position the whole set.\"],\"img\":\"1146.webp\",\"gif\":\"1146.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up with the feet spread in the straps, which adds a big core and hip challenge.\"},{\"id\":\"1147\",\"n\":\"suspender supine crunch\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Lie on your back with your feet in the straps and legs up.\",\"Place your arms flat on the floor.\",\"Curl your hips up, pulling the knees toward your chest.\",\"Squeeze your abs at the top.\",\"Lower slowly to the start.\",\"Do not swing the legs.\"],\"img\":\"1147.webp\",\"gif\":\"1147.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying on your back with your feet in the straps, you curl the hips up to work the lower abs.\"},{\"id\":\"1148\",\"n\":\"suspender supine plank\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"hamstrings\"],\"st\":[\"Lie on your back with heels in the straps.\",\"Press through your heels and lift your hips.\",\"Make a straight line from shoulders to heels.\",\"Squeeze your glutes and keep abs tight.\",\"Hold for 20-30 seconds.\",\"Lower under control.\"],\"img\":\"1148.webp\",\"gif\":\"1148.mp4\",\"cat\":\"isometric\",\"desc\":\"A back-facing plank with the heels in the straps that strengthens the glutes, back and core.\",\"hd\":1},{\"id\":\"1149\",\"n\":\"suspender triceps extension push up\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\"],\"st\":[\"Hold the handles and lean forward with arms straight.\",\"Keep your body in a straight line.\",\"Bend your elbows and lower your forehead between the hands.\",\"Keep elbows pointing forward.\",\"Press back up to straight arms.\",\"Move your feet back for more challenge.\"],\"img\":\"1149.webp\",\"gif\":\"1149.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lowering your head toward the handles then pushing out, a strap extension that hammers the triceps.\"},{\"id\":\"1150\",\"n\":\"suspender triceps kickback\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"rear deltoids\"],\"st\":[\"Hold the handles and hinge forward with elbows by your sides.\",\"Keep your upper arms still.\",\"Straighten your arms and push them behind you.\",\"Squeeze the triceps at the end.\",\"Bend the elbows slowly to return.\",\"Keep your back flat.\"],\"img\":\"1150.webp\",\"gif\":\"1150.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Leaning forward with the straps, you straighten the elbow behind you to isolate the triceps.\"},{\"id\":\"1151\",\"n\":\"suspender twist side\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Place your feet in the straps and set a high plank.\",\"Brace your core.\",\"Twist your hips to one side, bringing the knees across.\",\"Return to the center with control.\",\"Twist to the other side.\",\"Keep your shoulders square.\"],\"img\":\"1151.webp\",\"gif\":\"1151.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a side-facing plank position with the straps, you twist to hit the obliques.\"},{\"id\":\"1152\",\"n\":\"suspender twist up\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Put your feet in the straps and set a high plank.\",\"Pull your knees up and rotate them toward one elbow.\",\"Pause and squeeze the obliques.\",\"Extend your legs back to plank.\",\"Repeat to the other side.\",\"Keep your hands firmly planted.\"],\"img\":\"1152.webp\",\"gif\":\"1152.mp4\",\"cat\":\"calisthenics\",\"desc\":\"You pull the knees up and twist across the body from a plank with the feet in the straps.\"},{\"id\":\"1106\",\"n\":\"suspender twisting jackknife\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\"],\"st\":[\"Set your feet in the straps and get into a straight-arm plank.\",\"Keep your shoulders stacked over your hands.\",\"Pull both knees toward your chest, twisting them toward one elbow.\",\"Pause briefly, then extend the legs back to plank.\",\"Alternate sides each rep.\",\"Keep your hips from sagging as you return.\"],\"img\":\"1106.webp\",\"gif\":\"1106.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with feet in the straps, you pull the knees toward one side of the chest, which hits the abs and obliques hard.\"},{\"id\":\"1153\",\"n\":\"suspender upper back stretch\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"trapezius\"],\"st\":[\"Hold the handles and step back so your arms are straight.\",\"Sit your hips back and lower your chest.\",\"Round the upper back gently and push the straps away.\",\"Feel the stretch between the shoulder blades.\",\"Hold for 20-30 seconds.\",\"Breathe slowly and return.\"],\"img\":\"1153.webp\",\"gif\":\"1153.mp4\",\"cat\":\"stretching\",\"desc\":\"Leaning back on the straps with your arms extended, you stretch the upper back and shoulders.\"},{\"id\":\"2834\",\"n\":\"suspender weighted inverted row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\",\"core\"],\"st\":[\"Hold the suspension handles and lean back with your body in a straight line, with weight on your torso.\",\"Keep your arms straight and heels on the floor.\",\"Pull your chest up toward the handles, squeezing your shoulder blades.\",\"Pause briefly at the top.\",\"Lower slowly to full arm extension.\"],\"img\":\"2834.webp\",\"gif\":\"2834.mp4\",\"cat\":\"strength\",\"desc\":\"An inverted row on suspension straps with added weight on your body. Builds the back and biceps.\",\"fv\":\"2833\"},{\"id\":\"4450\",\"n\":\"suspender wide grip inverted row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"rear deltoids\",\"core\",\"forearms\"],\"st\":[\"Hold the handles of a suspension trainer with a wide overhand grip and lean back, arms straight.\",\"Walk your feet forward to set the difficulty.\",\"Keep your body in a straight line from head to heels.\",\"Pull your chest toward the handles, squeezing your shoulder blades.\",\"Pause briefly at the top.\",\"Lower yourself with control until your arms are straight.\"],\"img\":\"4450.webp\",\"gif\":\"4450.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row hanging under straps with a wide grip. Works the upper back and lats while the core keeps you rigid.\"},{\"id\":\"1107\",\"n\":\"suspender y lateral raise\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"rear deltoids\"],\"st\":[\"Hold the handles and lean back with arms straight and body in a line.\",\"Keep your core tight and feet planted.\",\"Raise your arms up and out until they form a Y overhead.\",\"Pause at the top without shrugging.\",\"Lower slowly back to the start.\",\"Step your feet forward to make it harder.\"],\"img\":\"1107.webp\",\"gif\":\"1107.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Leaning back on the straps, you pull your arms up into a Y shape to train the shoulders and upper back.\"},{\"id\":\"5738\",\"n\":\"suspension chest press\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Hold the handles and lean forward with a straight body.\",\"Start with your hands by your chest and elbows bent.\",\"Press yourself away until your arms are straight.\",\"Keep your core tight and hips in line.\",\"Lower back slowly with control.\"],\"img\":\"5738.webp\",\"gif\":\"5738.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up style press on suspension straps. The unstable handles make your chest, arms and core work together.\"},{\"id\":\"5008\",\"n\":\"suspension chin up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Hold the handles palms facing you and lean back.\",\"Brace your core and keep your body straight.\",\"Pull your chest toward the handles.\",\"Squeeze your elbows close to your sides.\",\"Lower under control.\",\"Adjust your foot position to change difficulty.\"],\"img\":\"5008.webp\",\"gif\":\"5008.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up on suspension straps. It builds the lats and arms with a natural hand path.\"},{\"id\":\"5737\",\"n\":\"suspension fly\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\",\"biceps\"],\"st\":[\"Hold the handles and lean forward with your body in a straight line.\",\"Start with your arms out in front of you, slightly bent.\",\"Open your arms out to the sides, lowering your chest between the handles.\",\"Keep a slight bend in your elbows.\",\"Squeeze your chest to bring your arms back together.\"],\"img\":\"5737.webp\",\"gif\":\"5737.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight chest fly using suspension straps. You open your arms wide while leaning forward to stretch and load the chest.\"},{\"id\":\"5007\",\"n\":\"suspension hammer curl\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\"],\"st\":[\"Hold the handles with palms facing each other and lean back.\",\"Keep your body in a straight line.\",\"Curl your hands toward your head.\",\"Keep your elbows high and still.\",\"Lower slowly until arms are straight.\",\"Keep your core tight.\"],\"img\":\"5007.webp\",\"gif\":\"5007.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A hammer curl using suspension straps with palms facing each other. It works the biceps and the muscles beside them.\"},{\"id\":\"1076\",\"n\":\"suspension hamstring runner\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with both heels in the straps and lift your hips.\",\"Press your arms into the floor for balance.\",\"Curl one heel toward your glutes while the other leg extends.\",\"Switch legs in a smooth running rhythm.\",\"Keep your hips high and level.\",\"Continue for the set.\"],\"img\":\"1076.webp\",\"gif\":\"1076.mp4\",\"cat\":\"strength\",\"desc\":\"A hamstring curl with heels in straps, alternating legs like running. It trains the hamstrings and core control.\"},{\"id\":\"1077\",\"n\":\"suspension hip abduction\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Put one foot in a strap and stand tall on the other leg, holding the anchor for balance.\",\"Brace your core.\",\"Sweep the strapped leg out to the side.\",\"Pause briefly at the end.\",\"Bring it back under control.\",\"Finish your reps, then switch legs.\"],\"img\":\"1077.webp\",\"gif\":\"1077.mp4\",\"cat\":\"strength\",\"desc\":\"Standing leg raise to the side with one foot in a strap. It works the outer hip and stability muscles.\"},{\"id\":\"1078\",\"n\":\"suspension hip bridge\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Lie on your back with your heels in the straps and knees bent.\",\"Place your arms by your sides.\",\"Drive through your heels and lift your hips.\",\"Squeeze your glutes at the top in a straight line from shoulders to knees.\",\"Lower slowly without touching down.\",\"Repeat for reps.\"],\"img\":\"1078.webp\",\"gif\":\"1078.mp4\",\"cat\":\"strength\",\"desc\":\"A glute bridge with heels in straps, which adds an instability challenge. It builds glutes and hamstrings.\"},{\"id\":\"1079\",\"n\":\"suspension hyperextension\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Place your feet in the straps and lie face down, hands behind your head or across your chest.\",\"Brace your core.\",\"Lift your chest by extending your back and hips.\",\"Stop when your body forms a straight line.\",\"Lower slowly.\",\"Avoid overarching at the top.\"],\"img\":\"1079.webp\",\"gif\":\"1079.mp4\",\"cat\":\"strength\",\"desc\":\"Hip hinge back extension with feet in straps. It strengthens the lower back and glutes.\"},{\"id\":\"1819\",\"n\":\"suspension in pulley machine in supination stretch\",\"bp\":\"upper arms\",\"eq\":\"cable\",\"tg\":\"biceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"lats\",\"shoulders\"],\"st\":[\"Hold a pulley handle with an underhand grip and your arm straight.\",\"Lean your body weight back gently until you feel a stretch in the biceps and forearm.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1819.webp\",\"gif\":\"1819.mp4\",\"cat\":\"stretching\",\"desc\":\"Hanging lightly from a pulley handle with palms up stretches the biceps and forearm. The pulley lets you control how much weight you load.\"},{\"id\":\"1080\",\"n\":\"suspension inverted row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Hold the handles and lean back with arms extended and body straight.\",\"Brace your abs and glutes.\",\"Pull your chest toward your hands, driving elbows back.\",\"Squeeze your shoulder blades together.\",\"Lower with control to full arm extension.\",\"Walk your feet forward to make it harder.\"],\"img\":\"1080.webp\",\"gif\":\"1080.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row hanging under straps. It builds the upper back and biceps.\"},{\"id\":\"1082\",\"n\":\"suspension jackknife\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"shoulders\"],\"st\":[\"Start in a plank with your feet in the straps and hands under shoulders.\",\"Brace your core.\",\"Pull your knees toward your chest by rolling your hips up.\",\"Pause briefly.\",\"Extend your legs back to plank.\",\"Keep your shoulders stacked over your hands.\"],\"img\":\"1082.webp\",\"gif\":\"1082.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with feet in straps, you pull the knees toward the chest. It trains the abs and core control.\"},{\"id\":\"1081\",\"n\":\"suspension jackknife pike\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"shoulders\"],\"st\":[\"Start in a plank with your feet in the straps and hands under shoulders.\",\"Keep your legs straight.\",\"Lift your hips high toward the ceiling.\",\"Roll to an inverted V shape.\",\"Lower back to plank slowly.\",\"Keep your arms straight throughout.\"],\"img\":\"1081.webp\",\"gif\":\"1081.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with feet in straps, you pike the hips up. It hits the abs hard and challenges the shoulders.\"},{\"id\":\"1083\",\"n\":\"suspension leg curl\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Lie on your back with your heels in the straps and legs extended.\",\"Lift your hips off the floor.\",\"Curl your heels toward your glutes.\",\"Keep your hips high.\",\"Extend your legs slowly.\",\"Repeat for reps.\"],\"img\":\"1083.webp\",\"gif\":\"1083.mp4\",\"cat\":\"strength\",\"desc\":\"Hamstring curl with heels in straps while bridging. It works the hamstrings and glutes.\"},{\"id\":\"1084\",\"n\":\"suspension mountain climber\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Start in a plank with your feet in the straps.\",\"Keep your hands under your shoulders.\",\"Drive one knee toward your chest.\",\"Switch legs in a quick running rhythm.\",\"Keep your hips level.\",\"Continue for the set.\"],\"img\":\"1084.webp\",\"gif\":\"1084.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Mountain climbers with feet in straps, which adds instability. It trains the core and conditioning.\"},{\"id\":\"1086\",\"n\":\"suspension power pull\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"core\"],\"st\":[\"Hold the handles with arms straight and lean back.\",\"Keep your body in a straight line.\",\"Pull explosively with your arms and back.\",\"Bring your chest toward your hands.\",\"Lower slowly.\",\"Keep your core tight.\"],\"img\":\"1086.webp\",\"gif\":\"1086.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A powerful pull from a long position under the straps. It builds the lats and upper back.\"},{\"id\":\"1087\",\"n\":\"suspension pull through\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Face away from the anchor, holding the handles between your legs.\",\"Step forward to create tension.\",\"Hinge at the hips and let your hands pass between your legs.\",\"Drive your hips forward.\",\"Stand tall and squeeze your glutes.\",\"Keep your back flat.\"],\"img\":\"1087.webp\",\"gif\":\"1087.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a strap held between your legs. It trains the glutes and hamstrings.\"},{\"id\":\"1088\",\"n\":\"suspension pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Hang from the handles with arms extended.\",\"Brace your core.\",\"Pull your chest up between the handles.\",\"Lead with your elbows.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"1088.webp\",\"gif\":\"1088.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up using suspension handles. It builds the lats and arms.\"},{\"id\":\"1090\",\"n\":\"suspension reverse fly\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Hold the handles and lean back with arms extended.\",\"Keep your body straight.\",\"Open your arms out to the sides.\",\"Squeeze your shoulder blades.\",\"Return slowly.\",\"Do not shrug.\"],\"img\":\"1090.webp\",\"gif\":\"1090.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse fly using suspension handles. It trains the rear shoulders and upper back.\"},{\"id\":\"1091\",\"n\":\"suspension rollout\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"shoulders\",\"lats\"],\"st\":[\"Kneel holding the handles close to your chest.\",\"Brace your core.\",\"Push your arms forward as you lean out.\",\"Keep your back flat.\",\"Pull back to the start.\",\"Do not let your hips sag.\"],\"img\":\"1091.webp\",\"gif\":\"1091.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A rollout using suspension handles. It challenges the abs and shoulders.\"},{\"id\":\"1093\",\"n\":\"suspension self assisted chest dip\",\"bp\":\"chest\",\"eq\":\"suspension trainer\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\"],\"st\":[\"Hold the handles with arms straight and feet on the floor.\",\"Lean your chest forward.\",\"Lower your body by bending your elbows.\",\"Use your legs for light help.\",\"Press back up.\",\"Keep your shoulders down.\"],\"img\":\"1093.webp\",\"gif\":\"1093.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chest dip with your feet on the floor for help. It builds the chest and triceps.\"},{\"id\":\"1094\",\"n\":\"suspension self assisted pull up\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\"],\"st\":[\"Hold the handles with feet on the floor.\",\"Lean back.\",\"Pull your chest toward your hands.\",\"Use your legs for light help.\",\"Lower slowly.\",\"Keep your core tight.\"],\"img\":\"1094.webp\",\"gif\":\"1094.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up using your legs for help. It builds back and arms.\"},{\"id\":\"1095\",\"n\":\"suspension self assisted triceps dip\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Hold the handles with arms straight and feet on the floor.\",\"Keep your torso upright.\",\"Bend your elbows to lower.\",\"Use your legs for light help.\",\"Press back up.\",\"Keep your elbows close.\"],\"img\":\"1095.webp\",\"gif\":\"1095.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A triceps dip with your feet on the floor for help. It trains the triceps.\"},{\"id\":\"1096\",\"n\":\"suspension shoulder external rotation\",\"bp\":\"shoulders\",\"eq\":\"suspension trainer\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"rear deltoids\"],\"st\":[\"Hold the handles with elbows bent at 90 degrees.\",\"Lean back slightly.\",\"Rotate your forearms outward and upward.\",\"Keep your elbows by your sides.\",\"Return slowly.\",\"Keep the motion small.\"],\"img\":\"1096.webp\",\"gif\":\"1096.mp4\",\"cat\":\"strength\",\"desc\":\"External rotation using straps. It strengthens the rotator cuff.\"},{\"id\":\"1097\",\"n\":\"suspension side bend\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Hold a handle and stand sideways to the anchor.\",\"Brace your core.\",\"Bend sideways away from the anchor.\",\"Return to upright using your side muscles.\",\"Do all reps, then switch sides.\",\"Keep your hips still.\"],\"img\":\"1097.webp\",\"gif\":\"1097.mp4\",\"cat\":\"strength\",\"desc\":\"A side bend using a strap. It works the obliques.\"},{\"id\":\"1098\",\"n\":\"suspension side bridge\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"glutes\"],\"st\":[\"Lie on your side with feet in the straps and your elbow below your shoulder.\",\"Lift your hips.\",\"Hold a straight line.\",\"Breathe steadily.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"1098.webp\",\"gif\":\"1098.mp4\",\"cat\":\"isometric\",\"desc\":\"A side plank with your feet in the straps. It strengthens the obliques and stabilisers.\",\"hd\":1},{\"id\":\"1100\",\"n\":\"suspension single leg split squat\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Put your rear foot in the strap and step forward.\",\"Stand tall.\",\"Lower your hips, back knee down.\",\"Keep your front knee over your foot.\",\"Press up.\",\"Switch legs.\"],\"img\":\"1100.webp\",\"gif\":\"1100.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat with the rear foot in a strap. It builds the front leg and balance.\"},{\"id\":\"1099\",\"n\":\"suspension single leg split squat (self assisted)\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Hold the handles and place your back foot behind you.\",\"Stand tall.\",\"Lower your back knee toward the floor.\",\"Use your arms for light help.\",\"Press up through your front heel.\",\"Switch legs.\"],\"img\":\"1099.webp\",\"gif\":\"1099.mp4\",\"cat\":\"strength\",\"desc\":\"A split squat holding the handles for help. It trains the legs and balance.\"},{\"id\":\"1101\",\"n\":\"suspension single leg squat\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the handles and stand on one leg.\",\"Extend the other leg forward.\",\"Sit back and lower.\",\"Keep your knee over your toes.\",\"Stand up.\",\"Switch legs.\"],\"img\":\"1101.webp\",\"gif\":\"1101.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg squat holding the handles for balance. It builds leg strength.\"},{\"id\":\"1102\",\"n\":\"suspension straight hip leg curl\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\"],\"st\":[\"Lie on your back with heels in the straps.\",\"Lift your hips into a straight line.\",\"Curl your heels toward you.\",\"Keep your hips high.\",\"Extend slowly.\",\"Repeat.\"],\"img\":\"1102.webp\",\"gif\":\"1102.mp4\",\"cat\":\"strength\",\"desc\":\"A leg curl with your hips kept straight. It works the hamstrings.\"},{\"id\":\"5004\",\"n\":\"suspension sumo squat\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"quadriceps\",\"core\"],\"st\":[\"Stand facing the anchor holding the handles with a wide stance.\",\"Turn your toes out slightly.\",\"Sit your hips down, keeping knees over toes.\",\"Use the straps lightly for balance.\",\"Push through your heels to stand.\",\"Squeeze your glutes at the top.\"],\"img\":\"5004.webp\",\"gif\":\"5004.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide-stance squat holding suspension handles for support. It trains the inner thighs and glutes.\"},{\"id\":\"7275\",\"n\":\"suspension trainer front plank\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Set your feet in the straps and place your forearms or hands on the floor.\",\"Form a straight line from head to heels.\",\"Squeeze your glutes and brace your abs.\",\"Hold without letting your hips sag or rise.\",\"Keep breathing steadily for the whole hold.\"],\"img\":\"7275.webp\",\"gif\":\"7275.mp4\",\"cat\":\"isometric\",\"desc\":\"Front plank with feet in straps, making the hold wobbly and demanding for the whole core.\",\"hd\":1,\"fv\":\"1114\"},{\"id\":\"7278\",\"n\":\"suspension trainer lat stretch\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"core\"],\"st\":[\"Hold the straps and lean back with straight arms.\",\"Sit your hips back and drop your chest between your arms.\",\"Feel the stretch along the sides of your back.\",\"Hold for 20-30 seconds.\",\"Return slowly to standing.\"],\"img\":\"7278.webp\",\"gif\":\"7278.mp4\",\"cat\":\"stretching\",\"desc\":\"Hanging stretch using straps that opens the sides of your back and your shoulders.\",\"fv\":\"1118\"},{\"id\":\"7274\",\"n\":\"suspension trainer pike\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"shoulders\",\"hip flexors\",\"core\"],\"st\":[\"Place your feet in the straps and get into a plank with hands on the floor.\",\"Keep your arms straight and body in a line.\",\"Lift your hips toward the ceiling, pulling your feet in.\",\"Pause at the top with legs fairly straight.\",\"Lower back to plank with control.\"],\"img\":\"7274.webp\",\"gif\":\"7274.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Plank with feet in suspension straps, piking the hips up to work the abs and shoulders.\",\"fv\":\"1085\"},{\"id\":\"7279\",\"n\":\"suspension trainer squat power pull\",\"bp\":\"upper legs\",\"eq\":\"suspension trainer\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lats\",\"upper back\"],\"st\":[\"Hold the straps with arms extended and sink into a squat.\",\"Keep your chest tall and knees tracking over toes.\",\"Drive up through your legs.\",\"As you rise, pull the straps toward your chest.\",\"Lower your arms and sit back into the next squat.\"],\"img\":\"7279.webp\",\"gif\":\"7279.mp4\",\"cat\":\"strength\",\"desc\":\"Squat paired with an explosive pull on the straps, linking legs and back in one move.\",\"fv\":\"1142\"},{\"id\":\"1103\",\"n\":\"suspension triceps dip\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Hold the handles with arms straight.\",\"Keep your body upright.\",\"Lower by bending your elbows.\",\"Keep your elbows close.\",\"Press back up.\",\"Stay controlled.\"],\"img\":\"1103.webp\",\"gif\":\"1103.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip with suspension handles. It trains the triceps.\"},{\"id\":\"5876\",\"n\":\"suspension triceps extension\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold the handles and lean forward with a straight body.\",\"Start with your arms overhead and elbows bent.\",\"Extend your arms, keeping your upper arms still.\",\"Pause when your arms are straight.\",\"Lower back slowly.\"],\"img\":\"5876.webp\",\"gif\":\"5876.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lean into suspension straps and straighten your arms from a bent position. It trains the triceps using your body weight.\"},{\"id\":\"1104\",\"n\":\"suspension triceps extension v. 2\",\"bp\":\"upper arms\",\"eq\":\"suspension trainer\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"core\"],\"st\":[\"Hold the handles and lean forward.\",\"Keep your elbows bent and by your head.\",\"Straighten your arms.\",\"Keep your body straight.\",\"Return slowly.\",\"Keep your elbows still.\"],\"img\":\"1104.webp\",\"gif\":\"1104.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension leaning on straps. It isolates the triceps.\"},{\"id\":\"1105\",\"n\":\"suspension twist\",\"bp\":\"waist\",\"eq\":\"suspension trainer\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Start in a plank with your feet in the straps.\",\"Keep your arms straight.\",\"Rotate your hips to one side.\",\"Return to centre.\",\"Rotate to the other side.\",\"Keep your shoulders steady.\"],\"img\":\"1105.webp\",\"gif\":\"1105.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a plank with feet in straps, you twist the hips side to side. It trains the obliques.\"},{\"id\":\"5006\",\"n\":\"suspension underhand grip inverted row\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"rhomboids\"],\"st\":[\"Hold the handles palms up and lean back with a straight body.\",\"Brace your core.\",\"Pull your chest toward your hands.\",\"Squeeze your shoulder blades together.\",\"Lower yourself slowly.\",\"Walk your feet forward to make it harder.\"],\"img\":\"5006.webp\",\"gif\":\"5006.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row on suspension straps with an underhand grip. It builds the back and biceps.\"},{\"id\":\"4451\",\"n\":\"suspension wide grip inverted row on floor\",\"bp\":\"back\",\"eq\":\"suspension trainer\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"core\",\"rear deltoids\"],\"st\":[\"Hold the handles with a wide, overhand grip and lie back with your body straight.\",\"Keep your heels on the floor and your core tight.\",\"Pull your chest toward the handles, squeezing your shoulder blades.\",\"Pause briefly at the top.\",\"Lower yourself slowly until your arms are straight and repeat.\"],\"img\":\"4451.webp\",\"gif\":\"4451.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row hanging under suspension straps with a wide grip. It builds the upper back and shoulders.\"},{\"id\":\"5332\",\"n\":\"svend bench press\",\"bp\":\"chest\",\"eq\":\"weight plate\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"upper chest\"],\"st\":[\"Lie on a bench holding a plate between your palms at chest level.\",\"Squeeze your palms together hard.\",\"Press the plate straight up until your arms extend.\",\"Keep squeezing the plate throughout.\",\"Lower it back to your chest slowly.\",\"Keep your feet planted.\"],\"img\":\"5332.webp\",\"gif\":\"5332.mp4\",\"cat\":\"strength\",\"desc\":\"Press a weight plate away from your chest while squeezing it. A chest isolation move with constant tension.\"},{\"id\":\"2869\",\"n\":\"swan dive\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\"],\"st\":[\"Lie face down with your hands under your shoulders and legs together.\",\"Press up into a swan, lifting your chest off the mat.\",\"Let your arms float forward as you rock your chest and legs up.\",\"Rock back and forth in a smooth, controlled rhythm.\",\"Keep your neck long and your abs gently drawn in.\"],\"img\":\"2869.webp\",\"gif\":\"2869.mp4\",\"cat\":\"pilates\",\"desc\":\"A rocking Pilates move on your belly that builds back extensor strength and control.\"},{\"id\":\"4404\",\"n\":\"swaying palm tree yoga pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"core\"],\"st\":[\"Stand tall with feet together and arms overhead, palms joined.\",\"Reach up through your fingertips.\",\"Lean gently to one side without twisting.\",\"Breathe and hold for 15-20 seconds.\",\"Return to center and repeat on the other side.\"],\"img\":\"4404.webp\",\"gif\":\"4404.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing side stretch with your arms overhead that lengthens the sides of the body and opens the shoulders.\"},{\"id\":\"6098\",\"n\":\"swim leg circle\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"core\",\"hamstrings\"],\"st\":[\"Lie face down with your arms extended in front of you.\",\"Lift one leg slightly off the floor.\",\"Draw small, controlled circles with that leg.\",\"Reverse the direction after several circles.\",\"Lower the leg and repeat on the other side.\",\"Keep your hips pressed down and your core braced.\"],\"img\":\"6098.webp\",\"gif\":\"6098.mp4\",\"cat\":\"pilates\",\"desc\":\"A lying leg circle drill with a swimming-style rhythm. It loosens the hips and trains the glutes and core control.\",\"fv\":\"6099\"},{\"id\":\"1612\",\"n\":\"swimmer hips\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rhomboids\",\"shoulders\"],\"st\":[\"Lie face down with your arms extended overhead and your legs straight.\",\"Lift your chest slightly and brace your glutes.\",\"Raise one arm and the opposite leg a few inches.\",\"Switch sides in a controlled flutter.\",\"Keep your neck neutral and breathe steadily.\"],\"img\":\"1612.webp\",\"gif\":\"1612.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A prone floor move where opposite arm and leg lift in alternation, training the back and glutes.\"},{\"id\":\"3227\",\"n\":\"swimmer kicks\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"upper back\",\"core\"],\"st\":[\"Lie face down with your arms extended in front.\",\"Lift your chest and legs slightly off the floor.\",\"Kick your legs up and down in small, fast alternations.\",\"Keep your neck long.\",\"Breathe steadily.\",\"Continue for 20-30 seconds.\"],\"img\":\"3227.webp\",\"gif\":\"3227.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lying face down, you flutter your legs like a swimmer. It works the lower back and glutes.\",\"fv\":\"3207\"},{\"id\":\"2870\",\"n\":\"swimming\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"rear deltoids\"],\"st\":[\"Lie face down with arms extended overhead and legs long.\",\"Lift your arms, chest and legs slightly off the mat.\",\"Flutter opposite arm and leg up and down in a quick, small rhythm.\",\"Keep your abs drawn in and your neck long.\",\"Continue for 20-30 seconds, then rest.\"],\"img\":\"2870.webp\",\"gif\":\"2870.mp4\",\"cat\":\"pilates\",\"desc\":\"A prone Pilates exercise with alternating arm and leg flutters that trains the back and glutes.\"},{\"id\":\"2880\",\"n\":\"swimming all fours\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"rear deltoids\",\"core\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Reach one arm forward and the opposite leg back.\",\"Flutter them in small, quick pulses.\",\"Keep your spine neutral and your hips level.\",\"Switch sides and repeat.\"],\"img\":\"2880.webp\",\"gif\":\"2880.mp4\",\"cat\":\"pilates\",\"desc\":\"A quadruped Pilates move with opposite arm and leg lifts for back stability.\"},{\"id\":\"6944\",\"n\":\"swimming crawl style\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\",\"core\",\"triceps\"],\"st\":[\"Stand with feet shoulder-width apart and knees slightly bent.\",\"Swing one arm forward and over in a crawl stroke.\",\"Alternate arms in a smooth, continuous rhythm.\",\"Rotate your torso slightly with each stroke.\",\"Keep going at a steady pace for 30-60 seconds.\"],\"img\":\"6944.webp\",\"gif\":\"6944.mp4\",\"cat\":\"cardio\",\"desc\":\"A standing or floor drill that copies the front crawl arm stroke. It raises your heart rate and warms the shoulders.\"},{\"id\":\"5976\",\"n\":\"t drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\",\"adductors\"],\"st\":[\"Set four cones in a T with the top cones 5 yards apart.\",\"Sprint forward to the center cone and touch it.\",\"Shuffle sideways to the left cone and touch it.\",\"Shuffle across to the right cone, then back to the middle.\",\"Backpedal to the start.\",\"Keep your hips low and feet from crossing.\"],\"img\":\"5976.webp\",\"gif\":\"5976.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A cone drill in a T shape that trains sprinting, side shuffling and backpedaling.\"},{\"id\":\"4800\",\"n\":\"table top bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"triceps\",\"shoulders\"],\"st\":[\"Sit on the floor with knees bent and feet flat, hands behind you with fingers pointing toward your feet.\",\"Press through your hands and heels to lift your hips.\",\"Raise until your torso and thighs are level like a tabletop.\",\"Squeeze your glutes and keep your head in line with your spine.\",\"Hold briefly, then lower your hips back to the floor under control.\"],\"img\":\"4800.webp\",\"gif\":\"4800.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Face-up bridge on hands and feet that lifts the hips into a table shape. It builds the glutes, hamstrings and shoulder stability.\",\"fv\":\"7172\"},{\"id\":\"10057\",\"n\":\"table top bridge jack\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Sit with hands behind you, then lift hips into a tabletop with knees bent.\",\"Squeeze your glutes to keep your hips high.\",\"Hop your feet wide.\",\"Hop them back together.\",\"Keep going at a steady pace.\",\"Keep your hips high and don't let them sag.\"],\"img\":\"10057.webp\",\"gif\":\"10057.mp4\",\"cat\":\"calisthenics\",\"desc\":\"From a reverse tabletop, you hop your feet apart and together like a jumping jack. It works the glutes and legs.\"},{\"id\":\"4801\",\"n\":\"table top bridge rotation\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"core\",\"sm\":[\"core\",\"obliques\",\"shoulders\",\"hamstrings\"],\"st\":[\"Set up in a table top bridge with hips lifted and hands under your shoulders.\",\"Shift your weight onto one hand and both feet.\",\"Lift the free arm and reach it up and over your body as you rotate your chest.\",\"Keep your hips high and level throughout.\",\"Return the arm to the floor and repeat, then switch sides.\"],\"img\":\"4801.webp\",\"gif\":\"4801.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A table top bridge with an arm sweep and trunk rotation. It trains the glutes while opening the chest and challenging balance.\"},{\"id\":\"2871\",\"n\":\"teaser\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Lie on your back with legs extended and arms overhead.\",\"Roll up while lifting your legs to form a V shape.\",\"Reach your arms parallel to your legs and balance on your sit bones.\",\"Hold briefly with a flat, strong back.\",\"Roll down slowly with control and repeat.\"],\"img\":\"2871.webp\",\"gif\":\"2871.mp4\",\"cat\":\"pilates\",\"desc\":\"A classic Pilates V-sit that challenges abdominal strength and balance.\"},{\"id\":\"4405\",\"n\":\"the eagle yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"shoulders\",\"upper back\",\"hip flexors\"],\"st\":[\"Stand tall and bend both knees slightly.\",\"Lift one leg and wrap it across the other thigh.\",\"Cross your arms in front, one elbow over the other, palms together.\",\"Lift your elbows and sink your hips slightly.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"4405.webp\",\"gif\":\"4405.mp4\",\"cat\":\"yoga\",\"desc\":\"A balancing pose with wrapped legs and arms. It stretches the hips and shoulders and builds focus.\"},{\"id\":\"6795\",\"n\":\"thomas frontal test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"adductors\"],\"st\":[\"Sit at the end of a bench and lie back, pulling one knee to your chest.\",\"Let the other leg hang down off the edge, fully relaxed.\",\"Keep your lower back pressed down and your pelvis still.\",\"Watch whether the hanging leg drifts outward or the thigh lifts.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch legs and compare.\"],\"img\":\"6795.webp\",\"gif\":\"6795.mp4\",\"cat\":\"stretching\",\"desc\":\"The frontal-view version of the Thomas test, checking for tight hip flexors and inner thighs while you lie on a bench.\"},{\"id\":\"6794\",\"n\":\"thomas test\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"groin\"],\"st\":[\"Sit at the end of a bench, then lie back and hug one knee to your chest.\",\"Let the other leg hang off the edge with the thigh relaxed.\",\"Keep your lower back flat on the bench.\",\"Notice whether the hanging thigh rises above the bench or the knee straightens.\",\"Hold for 20-30 seconds, breathing calmly.\",\"Switch legs and compare.\"],\"img\":\"6794.webp\",\"gif\":\"6794.mp4\",\"cat\":\"stretching\",\"desc\":\"A hip flexor length test where you lie on the edge of a bench and see how freely the thigh hangs.\"},{\"id\":\"4553\",\"n\":\"thoracic bridge\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"core\"],\"st\":[\"Sit on the floor with your knees bent and one hand behind you.\",\"Lift your hips toward the ceiling.\",\"Reach your free arm up and over, rotating your chest toward the ceiling.\",\"Open your chest as far as feels comfortable.\",\"Return to the start under control.\",\"Repeat for reps, then switch sides.\"],\"img\":\"4553.webp\",\"gif\":\"4553.mp4\",\"cat\":\"mobility\",\"desc\":\"A bridge-like drill that opens the upper back and shoulders while rotating the spine.\"},{\"id\":\"5904\",\"n\":\"thread the needle pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"rhomboids\",\"sm\":[\"rhomboids\",\"shoulders\",\"rotator cuff\"],\"st\":[\"Start on hands and knees.\",\"Slide one arm under your chest and rest your shoulder on the floor.\",\"Keep your hips over your knees.\",\"Hold for 5 slow breaths.\",\"Return and switch arms.\"],\"img\":\"5904.webp\",\"gif\":\"5904.mp4\",\"cat\":\"yoga\",\"desc\":\"A gentle twist from hands and knees. Loosens the upper back and shoulders.\"},{\"id\":\"10032\",\"n\":\"thumb abduction\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrist extensors\"],\"st\":[\"Rest your hand on a table with the palm facing up.\",\"Keep your fingers relaxed and straight.\",\"Slowly move your thumb away from your palm.\",\"Pause at the end of the range.\",\"Return slowly to the start.\",\"Do 10-15 reps, then switch hands.\"],\"img\":\"10032.webp\",\"gif\":\"10032.mp4\",\"cat\":\"mobility\",\"desc\":\"A simple thumb movement where you lift the thumb away from the palm to improve hand mobility.\"},{\"id\":\"2094\",\"n\":\"thumb stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"hands\",\"sm\":[\"hands\",\"wrist flexors\"],\"st\":[\"Extend one arm with the palm facing up.\",\"Use your other hand to hold the thumb.\",\"Gently pull the thumb back and away from the palm.\",\"Stop at a mild stretch.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2094.webp\",\"gif\":\"2094.mp4\",\"cat\":\"stretching\",\"desc\":\"A gentle stretch for the thumb and the muscles at its base.\"},{\"id\":\"1928\",\"n\":\"tibial flexion stretch on wall bar\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Stand facing the wall bars and place the front of one foot against a low bar.\",\"Lean your body forward and press your heel toward the floor until the lower leg stretches.\",\"Hold the bars with your hands to stay balanced.\",\"Hold for 20-30 seconds, feeling a gentle pull rather than pain.\",\"Release slowly and repeat, switching sides if the stretch is one sided.\"],\"img\":\"1928.webp\",\"gif\":\"1928.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch using a wall bar to flex the ankle and lengthen the muscles of the lower leg.\"},{\"id\":\"1929\",\"n\":\"tibial stretch with semi flexed knee\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"soleus\",\"ankles\"],\"st\":[\"Stand facing a wall with one foot back and the toes pressed against the wall or floor.\",\"Bend the knee of the stretching leg slightly.\",\"Shift your weight forward until you feel a stretch low in the calf.\",\"Keep the heel on the floor.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"1929.webp\",\"gif\":\"1929.mp4\",\"cat\":\"stretching\",\"desc\":\"A bent-knee stretch that targets the lower calf and the muscles around the shin.\"},{\"id\":\"5905\",\"n\":\"tiger curl pose\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower back\",\"sm\":[\"lower back\",\"glutes\",\"hip flexors\"],\"st\":[\"Start on hands and knees with a neutral spine.\",\"Extend one leg behind you and look slightly forward.\",\"Round your back and draw the knee toward your nose.\",\"Extend again and repeat for 6-8 reps.\",\"Switch legs.\"],\"img\":\"5905.webp\",\"gif\":\"5905.mp4\",\"cat\":\"yoga\",\"desc\":\"From hands and knees, you extend one leg back and curl the knee toward your nose. Works the abs and mobilizes the spine.\"},{\"id\":\"4220\",\"n\":\"tiger tail forearm\",\"bp\":\"lower arms\",\"eq\":\"roller\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Rest your forearm on a table, palm up.\",\"Hold the tiger tail roller in your other hand.\",\"Roll slowly from wrist to elbow with moderate pressure.\",\"Pause on tender spots for a few seconds.\",\"Turn your palm down and repeat.\",\"Switch arms and roll for 30-60 seconds each.\"],\"img\":\"4220.webp\",\"gif\":\"4220.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling a handheld foam roller along your forearm to ease tight muscles. It is a quick self-massage for grip and wrists.\"},{\"id\":\"4221\",\"n\":\"tiger tail hamstring\",\"bp\":\"upper legs\",\"eq\":\"roller\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\"],\"st\":[\"Sit on the floor with one leg extended.\",\"Hold the roller by both handles on the back of your thigh.\",\"Roll from the knee toward your hip with steady pressure.\",\"Slow down on tight spots.\",\"Keep breathing and keep the leg relaxed.\",\"Switch legs after 30-60 seconds.\"],\"img\":\"4221.webp\",\"gif\":\"4221.mp4\",\"cat\":\"mobility\",\"desc\":\"Using a handheld roller on the back of your thigh to loosen tight hamstrings. It works well before or after leg training.\"},{\"id\":\"4222\",\"n\":\"tiger tail neck\",\"bp\":\"neck\",\"eq\":\"roller\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Sit or stand tall with relaxed shoulders.\",\"Hold the roller by both handles behind your neck.\",\"Roll gently up and down along one side with light pressure.\",\"Avoid pressing on the spine itself.\",\"Repeat on the other side.\",\"Roll for 30-60 seconds and stop if it hurts.\"],\"img\":\"4222.webp\",\"gif\":\"4222.mp4\",\"cat\":\"mobility\",\"desc\":\"Gently rolling a handheld roller along the back and sides of the neck. It helps loosen stiff neck and upper trap muscles.\"},{\"id\":\"4223\",\"n\":\"tiger tail peroneal\",\"bp\":\"lower legs\",\"eq\":\"roller\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\",\"soleus\"],\"st\":[\"Sit with your leg bent or extended and the outer shin facing up.\",\"Hold the roller by the handles on the outside of your lower leg.\",\"Roll from the ankle to just below the knee.\",\"Use gentle pressure and avoid the bone.\",\"Pause on any tight areas.\",\"Switch legs after 30-60 seconds.\"],\"img\":\"4223.webp\",\"gif\":\"4223.mp4\",\"cat\":\"mobility\",\"desc\":\"Rolling the outer side of your lower leg with a handheld roller. It eases tension in the muscles along the outside of the calf.\"},{\"id\":\"4407\",\"n\":\"tiger tail tricep\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"core\",\"shoulders\"],\"st\":[\"Set up facing your anchor or support, with your upper arms close to your body.\",\"Brace your core and keep your elbows still.\",\"Straighten your arms fully to engage the triceps.\",\"Squeeze at the bottom for a moment.\",\"Return slowly to the start.\"],\"img\":\"4407.webp\",\"gif\":\"4407.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps exercise using a bodyweight or stick-style handle, focused on straightening the elbows against resistance.\"},{\"id\":\"4406\",\"n\":\"tiger yoga pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"shoulders\",\"hip flexors\"],\"st\":[\"Start on all fours with hands under shoulders and knees under hips.\",\"Round your back and draw one knee toward your nose.\",\"Then extend that leg back and up while lifting your chest.\",\"Move smoothly with your breath.\",\"Do your reps, then switch legs.\"],\"img\":\"4406.webp\",\"gif\":\"4406.mp4\",\"cat\":\"yoga\",\"desc\":\"A hands-and-knees pose where one leg extends back and the spine arches, mobilising the back and hips.\"},{\"id\":\"5977\",\"n\":\"tight rope walk\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"core\",\"glutes\"],\"st\":[\"Place a line of tape on the floor or imagine one.\",\"Stand at one end with your arms out for balance.\",\"Walk heel to toe along the line.\",\"Keep your gaze ahead and your core braced.\",\"Turn at the end and walk back.\"],\"img\":\"5977.webp\",\"gif\":\"5977.mp4\",\"cat\":\"mobility\",\"desc\":\"Walking along an imaginary or taped line to train balance and foot control.\"},{\"id\":\"4904\",\"n\":\"toe jump\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\"],\"st\":[\"Stand tall with feet close together and knees slightly bent.\",\"Rise onto the balls of your feet.\",\"Hop up quickly using mainly your ankles.\",\"Land softly on the balls of your feet.\",\"Keep your hops small and rhythmic.\",\"Continue for 20-30 seconds.\"],\"img\":\"4904.webp\",\"gif\":\"4904.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Quick small hops on the balls of your feet. It trains the calves and ankles and builds a springy stride.\"},{\"id\":\"10762\",\"n\":\"toe side walk\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"feet\",\"glutes\"],\"st\":[\"Stand tall and rise onto your toes.\",\"Bend your knees slightly.\",\"Step sideways with small controlled steps.\",\"Stay high on your toes.\",\"Keep your hips level.\",\"Walk one way, then return.\"],\"img\":\"10762.webp\",\"gif\":\"10762.mp4\",\"cat\":\"strength\",\"desc\":\"A sideways walk on tiptoe. It builds calf strength and ankle stability.\"},{\"id\":\"1891\",\"n\":\"toe squat stretch\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"feet\",\"sm\":[\"feet\",\"ankles\"],\"st\":[\"Kneel on a mat with your toes tucked under.\",\"Sit back onto your heels slowly.\",\"Rest your hands on your thighs.\",\"Ease off if the stretch is too sharp.\",\"Hold for 20-30 seconds, breathing slowly.\",\"Release and shake out your feet.\"],\"img\":\"1891.webp\",\"gif\":\"1891.mp4\",\"cat\":\"stretching\",\"desc\":\"Kneeling on the toes to stretch the feet and front of the ankles.\"},{\"id\":\"0810\",\"n\":\"toe touch sit (wall)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Lean against a wall and slide down into a wall sit.\",\"Hold the squat position with your feet flat.\",\"Reach forward and down with your hands toward your toes.\",\"Return to an upright position against the wall.\",\"Repeat for the set, keeping the sit steady.\",\"Slide back up when finished and keep your knees at about 90 degrees.\"],\"img\":\"0810.webp\",\"gif\":\"0810.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wall sit with a toe touch added. The reach makes your trunk work while your legs hold the squat.\"},{\"id\":\"4802\",\"n\":\"toe walk\",\"bp\":\"lower legs\",\"eq\":\"body weight\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"feet\",\"ankles\"],\"st\":[\"Stand tall with feet hip-width apart and rise onto the balls of your feet.\",\"Keep your heels lifted as high as you comfortably can.\",\"Walk forward with small, controlled steps.\",\"Keep your core tight and your gaze forward.\",\"Walk for 20-30 steps, rest, and repeat.\"],\"img\":\"4802.webp\",\"gif\":\"4802.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Walking on the balls of your feet with heels lifted. It works the calves and the small stabilisers of the feet and ankles.\"},{\"id\":\"4983\",\"n\":\"top pull up hold\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"grip muscles\"],\"st\":[\"Grab a pull-up bar and pull yourself up.\",\"Bring your chin above the bar.\",\"Squeeze your shoulder blades down and back.\",\"Hold for 5-15 seconds.\",\"Lower yourself slowly.\",\"Keep your body still.\"],\"img\":\"4983.webp\",\"gif\":\"4983.mp4\",\"cat\":\"isometric\",\"desc\":\"Holding the top of a pull-up with your chin above the bar. It builds strength and grip in the finish position.\",\"hd\":1},{\"id\":\"8702\",\"n\":\"torque tank push\",\"bp\":\"upper legs\",\"eq\":\"sled machine\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Grip the handles of the tank and lean forward.\",\"Keep your back flat and core tight.\",\"Drive with short, powerful steps.\",\"Keep your hips low and push over the distance.\",\"Rest and repeat.\"],\"img\":\"8702.webp\",\"gif\":\"8702.mp4\",\"cat\":\"cardio\",\"desc\":\"A hard push of a torque tank sled across the floor that fires up the legs and the heart.\"},{\"id\":\"5978\",\"n\":\"toy soldier dynamic stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"core\"],\"st\":[\"Stand tall with your arms stretched out in front of you.\",\"Kick one straight leg up toward your hands.\",\"Lower it and step forward.\",\"Kick the other leg up.\",\"Keep your chest upright and walk for about 10 reps per side.\"],\"img\":\"5978.webp\",\"gif\":\"5978.mp4\",\"cat\":\"stretching\",\"desc\":\"A walking stretch where you kick straight legs up toward outstretched hands, warming up the hamstrings and hips.\"},{\"id\":\"1696\",\"n\":\"transverse plane dumbbell lunge\",\"bp\":\"upper legs\",\"eq\":\"dumbbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Hold a dumbbell in each hand and stand tall.\",\"Step diagonally back or across your body into a lunge.\",\"Lower until both knees are bent, keeping your chest upright.\",\"Push through the front foot to return to the start.\",\"Alternate sides for the planned reps.\"],\"img\":\"1696.webp\",\"gif\":\"1696.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge that steps diagonally or rotates, loading the legs from a different angle.\"},{\"id\":\"1602\",\"n\":\"transverse step up\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand sideways next to a bench or step.\",\"Place the inside foot fully on top.\",\"Drive through that heel and step up until your leg is straight.\",\"Bring your other foot up to meet it.\",\"Step back down with control, finish your reps, then switch sides.\"],\"img\":\"1602.webp\",\"gif\":\"1602.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A step-up performed side-on to the bench. It works the glutes and quads while challenging your balance.\"},{\"id\":\"1791\",\"n\":\"trap and neck stretch\",\"bp\":\"neck\",\"eq\":\"body weight\",\"tg\":\"traps\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Sit or stand tall and hold the edge of the seat or a hand behind your back to anchor one shoulder down.\",\"Tilt your head toward the opposite shoulder until you feel a stretch along your neck.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1791.webp\",\"gif\":\"1791.mp4\",\"cat\":\"stretching\",\"desc\":\"Tilting your head to the side while anchoring the opposite shoulder stretches the upper traps and the side of the neck.\"},{\"id\":\"4842\",\"n\":\"trap bar banded deadlift\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Attach bands to the trap bar and stand inside the bar.\",\"Grip the handles with a flat back and chest up.\",\"Drive through your feet to stand up.\",\"Lock your hips out at the top against the band.\",\"Lower slowly back to the floor.\"],\"img\":\"4842.webp\",\"gif\":\"4842.mp4\",\"cat\":\"strength\",\"desc\":\"A trap bar deadlift with bands adding resistance toward the top. It builds hip and leg power.\"},{\"id\":\"4104\",\"n\":\"trap bar bent over row\",\"bp\":\"back\",\"eq\":\"trap bar\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"lower back\"],\"st\":[\"Stand in the trap bar and hinge forward with a flat back, gripping the handles.\",\"Brace your core.\",\"Row the bar toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower the bar with control.\"],\"img\":\"4104.webp\",\"gif\":\"4104.mp4\",\"cat\":\"strength\",\"desc\":\"A bent over row using a trap bar, working your back and arms with a neutral grip.\"},{\"id\":\"4105\",\"n\":\"trap bar deadlift from deficit\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"lower back\",\"grip muscles\"],\"st\":[\"Stand on a low platform inside the trap bar.\",\"Squat down and grip the handles with a flat back.\",\"Brace and push the floor away.\",\"Stand tall and squeeze your glutes at the top.\",\"Lower the bar with control to the start.\"],\"img\":\"4105.webp\",\"gif\":\"4105.mp4\",\"cat\":\"strength\",\"desc\":\"A trap bar deadlift while standing on a raised platform, increasing range of motion for legs and back.\"},{\"id\":\"2912\",\"n\":\"trap bar farmers carry\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"traps\",\"mg\":\"forearms\",\"sm\":[\"forearms\",\"grip muscles\",\"glutes\",\"core\",\"quadriceps\"],\"st\":[\"Stand inside the trap bar and hinge down to grip the handles.\",\"Stand up with a flat back, shoulders back and chest tall.\",\"Walk with short, quick steps, keeping the bar still.\",\"Cover the set distance without leaning or shrugging.\",\"Lower the bar back to the floor with control.\"],\"img\":\"2912.webp\",\"gif\":\"2912.mp4\",\"cat\":\"strength\",\"desc\":\"Carrying a loaded trap bar at your sides while walking. It works grip, traps and the whole trunk together.\"},{\"id\":\"4166\",\"n\":\"trap bar jump squat\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Stand inside a trap bar with feet shoulder width apart.\",\"Grip the handles and stand tall.\",\"Squat down quickly with your chest up.\",\"Jump up explosively off the floor.\",\"Land softly with bent knees.\",\"Reset before the next rep.\"],\"img\":\"4166.webp\",\"gif\":\"4166.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive jump squat holding a trap bar. It develops lower body power.\"},{\"id\":\"7287\",\"n\":\"trap bar overhead press\",\"bp\":\"shoulders\",\"eq\":\"trap bar\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand inside the trap bar and hold it at shoulder height with a neutral grip.\",\"Brace your core and squeeze your glutes.\",\"Press the bar overhead until your arms lock out.\",\"Pause, then lower to your shoulders.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"7287.webp\",\"gif\":\"7287.mp4\",\"cat\":\"strength\",\"desc\":\"Overhead press using a trap bar, giving a neutral grip that can be easier on the shoulders.\"},{\"id\":\"3652\",\"n\":\"trap bar split stance rdl\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Stand inside a trap bar with one foot slightly behind.\",\"Hinge at the hips with a flat back.\",\"Lower the bar along your legs.\",\"Drive your hips forward to stand.\",\"Finish reps, then switch the stance.\"],\"img\":\"3652.webp\",\"gif\":\"3652.mp4\",\"cat\":\"strength\",\"desc\":\"A Romanian deadlift in a staggered stance using a trap bar for hamstring and glute strength.\"},{\"id\":\"5304\",\"n\":\"trap bar squat\",\"bp\":\"upper legs\",\"eq\":\"trap bar\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"lower back\",\"core\"],\"st\":[\"Stand inside the trap bar with feet shoulder-width apart and grip the handles.\",\"Brace your core and keep your chest tall.\",\"Sit your hips back and down until your thighs are about parallel.\",\"Drive through your whole foot to stand up.\",\"Lock out your hips at the top without leaning back.\",\"Keep your knees tracking over your toes.\"],\"img\":\"5304.webp\",\"gif\":\"5304.mp4\",\"cat\":\"strength\",\"desc\":\"Squat while standing inside a trap bar, which keeps the load at your sides. Builds legs and glutes with a friendly upright torso.\"},{\"id\":\"4103\",\"n\":\"trap bar standing shrug\",\"bp\":\"back\",\"eq\":\"trap bar\",\"tg\":\"traps\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"forearms\",\"grip muscles\",\"upper back\"],\"st\":[\"Stand inside the trap bar and lift it, holding the handles at your sides.\",\"Keep your arms straight and chest tall.\",\"Shrug your shoulders straight up toward your ears.\",\"Hold briefly at the top.\",\"Lower slowly and do not roll your shoulders.\"],\"img\":\"4103.webp\",\"gif\":\"4103.mp4\",\"cat\":\"strength\",\"desc\":\"A shrug done holding a trap bar at your sides, loading the traps with a neutral grip.\"},{\"id\":\"0961\",\"n\":\"tree pose vrksasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"core\",\"ankles\",\"calves\"],\"st\":[\"Stand tall and shift your weight onto one foot.\",\"Place the sole of the other foot on your inner calf or thigh, never on the knee.\",\"Bring your palms together at your chest or raise them overhead.\",\"Fix your eyes on one point to stay steady.\",\"Hold for 5 breaths, then switch legs.\"],\"img\":\"0961.webp\",\"gif\":\"0961.mp4\",\"cat\":\"yoga\",\"desc\":\"Balance on one leg with the other foot resting on your inner thigh. It builds balance, focus and hip strength.\"},{\"id\":\"0962\",\"n\":\"triangle pose trikonasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"adductors\",\"shoulders\",\"lats\"],\"st\":[\"Stand with feet wide apart and turn one foot out 90 degrees.\",\"Raise your arms to shoulder height.\",\"Reach toward the front foot, then lower that hand to your shin or the floor.\",\"Extend the other arm up and look toward it.\",\"Hold for 3 to 5 breaths, then switch sides.\"],\"img\":\"0962.webp\",\"gif\":\"0962.mp4\",\"cat\":\"stretching\",\"desc\":\"From a wide stance, reach sideways over the front leg with arms in a line. It stretches the hamstrings, hips and sides.\"},{\"id\":\"5110\",\"n\":\"triceps dip floor\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the floor with knees bent and hands behind you.\",\"Lift your hips off the floor.\",\"Bend your elbows to lower your hips.\",\"Push through your palms to straighten your arms.\",\"Keep your elbows pointing back.\",\"Keep your shoulders away from your ears.\"],\"img\":\"5110.webp\",\"gif\":\"5110.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor dip with hands behind you and hips lifted. It trains the triceps with just your bodyweight.\"},{\"id\":\"5130\",\"n\":\"triceps dip floor v. 2\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Sit on the floor with knees bent and hands behind you.\",\"Lift your hips off the floor.\",\"Bend your elbows to lower your hips.\",\"Push through your palms to straighten your arms.\",\"Keep your elbows pointing back.\",\"Keep your shoulders away from your ears.\"],\"img\":\"5130.webp\",\"gif\":\"5130.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor dip with hands behind you and hips lifted. It trains the triceps with just your bodyweight.\"},{\"id\":\"8143\",\"n\":\"triceps dip on high parallel bars\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"forearms\"],\"st\":[\"Grip the bars and lift yourself with straight arms.\",\"Keep your body upright and elbows close.\",\"Lower until your upper arms are about parallel to the floor.\",\"Press back up to straight arms.\",\"Avoid shrugging your shoulders.\"],\"img\":\"8143.webp\",\"gif\":\"8143.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A dip on high parallel bars with an upright torso. It builds the triceps and chest.\"},{\"id\":\"1492\",\"n\":\"triceps dip stretch\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"lats\"],\"st\":[\"Stand or sit tall and raise one arm overhead.\",\"Bend the elbow so your hand drops behind your head.\",\"Use your other hand to gently press the elbow back and down.\",\"Keep your ribs down and avoid arching your back.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"1492.webp\",\"gif\":\"1492.mp4\",\"cat\":\"stretching\",\"desc\":\"A stretch for the back of the upper arm, taken with the elbow bent overhead.\"},{\"id\":\"1191\",\"n\":\"triceps press (head below bench)\",\"bp\":\"upper arms\",\"eq\":\"dumbbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Lie on a bench with your head just past the end, holding a weight overhead.\",\"Keep your upper arms still and pointing up.\",\"Bend your elbows to lower the weight toward your head.\",\"Extend your arms to straight.\",\"Keep your elbows tucked in.\"],\"img\":\"1191.webp\",\"gif\":\"1191.mp4\",\"cat\":\"strength\",\"desc\":\"A triceps extension lying with your head off the bench edge for an extra stretch.\"},{\"id\":\"4803\",\"n\":\"triceps press (high bar position)\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\"],\"st\":[\"Set up with a barbell held at arm's length above your head, hands about shoulder-width apart.\",\"Keep your upper arms still and pointing up.\",\"Bend your elbows to lower the bar toward your forehead or just behind your head.\",\"Keep your elbows from flaring out.\",\"Extend your arms to press the bar back to the start.\"],\"img\":\"4803.webp\",\"gif\":\"4803.mp4\",\"cat\":\"strength\",\"desc\":\"Lying or seated barbell press where the bar travels from a high position over the head, isolating the triceps through a long range.\"},{\"id\":\"4804\",\"n\":\"triceps press (low bar position)\",\"bp\":\"upper arms\",\"eq\":\"barbell\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"chest\",\"core\"],\"st\":[\"Hold a barbell at arm's length over your chest, hands about shoulder-width apart.\",\"Keep your upper arms vertical and your elbows tucked.\",\"Bend only at the elbows to lower the bar toward your forehead.\",\"Pause briefly when the bar is low.\",\"Extend your arms to return the bar to the start.\"],\"img\":\"4804.webp\",\"gif\":\"4804.mp4\",\"cat\":\"strength\",\"desc\":\"A barbell triceps press where the bar travels lower, closer to your face or chest. It hits the triceps hard through the bottom of the movement.\"},{\"id\":\"1829\",\"n\":\"triceps stretch against wall\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"lats\"],\"st\":[\"Stand next to a wall and place your bent elbow on it above head height.\",\"Lean your body forward and down until you feel the stretch along the back of your upper arm.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1829.webp\",\"gif\":\"1829.mp4\",\"cat\":\"stretching\",\"desc\":\"Leaning into a wall with your elbow bent overhead stretches the triceps. The wall gives a steady anchor.\"},{\"id\":\"3700\",\"n\":\"tuck jump v. 2\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"core\"],\"st\":[\"Stand with your feet shoulder width apart and arms ready.\",\"Dip into a quarter squat and swing your arms up.\",\"Jump as high as you can and pull your knees toward your chest.\",\"Land softly on the balls of your feet with bent knees.\",\"Reset briefly and repeat.\"],\"img\":\"3700.webp\",\"gif\":\"3700.mp4\",\"cat\":\"plyometrics\",\"desc\":\"An explosive jump where you pull your knees toward your chest in the air. It builds power and gets your heart rate up quickly.\"},{\"id\":\"10989\",\"n\":\"tuck planche on parallette\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"triceps\",\"forearms\",\"upper back\"],\"st\":[\"Place your hands on parallettes and squat down.\",\"Lean forward over your hands, arms straight.\",\"Lift your feet with knees tucked toward the chest.\",\"Hold for a few seconds, rounding your upper back slightly.\",\"Lower your feet gently.\"],\"img\":\"10989.webp\",\"gif\":\"10989.mp4\",\"cat\":\"isometric\",\"desc\":\"A hold on parallettes with knees tucked and hips lifted. It builds shoulder and core strength.\",\"hd\":1},{\"id\":\"3969\",\"n\":\"tuck up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Sit on the floor, lean back slightly and hold the floor or your sides for support.\",\"Extend your legs out in front, hovering just above the floor.\",\"Pull your knees toward your chest while curling your torso forward.\",\"Pause briefly at the top with your abs tight.\",\"Extend back out under control without letting your feet touch down, and repeat.\"],\"img\":\"3969.webp\",\"gif\":\"3969.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Seated or reclined, you pull knees and chest together and then extend out again. It works the abs and hip flexors, especially the lower abs.\"},{\"id\":\"5514\",\"n\":\"twist crunch (legs up)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower abs\"],\"st\":[\"Lie on your back with knees bent and legs raised.\",\"Place your hands lightly behind your head.\",\"Crunch up and rotate one shoulder toward the opposite knee.\",\"Lower with control and repeat to the other side.\",\"Do not pull on your neck.\"],\"img\":\"5514.webp\",\"gif\":\"5514.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Crunch with legs raised and a rotation at the top that hits the abs and obliques.\",\"fv\":\"0819\"},{\"id\":\"3964\",\"n\":\"twist push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"obliques\"],\"st\":[\"Start in a high plank with hands under your shoulders.\",\"Lower your chest to the floor.\",\"Push up and rotate one arm toward the ceiling.\",\"Return the hand to the floor.\",\"Alternate sides each rep.\"],\"img\":\"3964.webp\",\"gif\":\"3964.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push up with a rotation at the top. It trains the chest and arms and adds core work.\"},{\"id\":\"0820\",\"n\":\"twist side bridge\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Lie on your side and prop up on one forearm, feet stacked.\",\"Lift your hips so your body forms a straight line.\",\"Reach your top arm under your torso, twisting slightly.\",\"Return to the straight line.\",\"Finish your reps, then switch sides.\"],\"img\":\"0820.webp\",\"gif\":\"0820.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A side bridge with a rotation of the top arm under your body. It challenges the obliques and shoulder stability.\"},{\"id\":\"0821\",\"n\":\"twist sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands by your head.\",\"Curl your torso up off the floor.\",\"Rotate to bring one elbow toward the opposite knee.\",\"Lower back down with control.\",\"Alternate sides each rep.\"],\"img\":\"0821.webp\",\"gif\":\"0821.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit up with a twist at the top. It adds oblique work to the usual abs focus.\"},{\"id\":\"0822\",\"n\":\"twist squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"core\"],\"st\":[\"Stand with feet shoulder-width apart and hands together at your chest.\",\"Sit down into a squat.\",\"As you stand, rotate your torso to one side.\",\"Return to the centre and squat again.\",\"Alternate twisting sides.\"],\"img\":\"0822.webp\",\"gif\":\"0822.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A squat that adds a torso twist as you stand. It trains the legs and rotational control.\"},{\"id\":\"3956\",\"n\":\"twist step stretch\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"glutes\"],\"st\":[\"Stand tall.\",\"Step forward into a lunge.\",\"Twist your torso toward the front leg.\",\"Return to centre and step back.\",\"Alternate sides for 8-10 reps each.\"],\"img\":\"3956.webp\",\"gif\":\"3956.mp4\",\"cat\":\"mobility\",\"desc\":\"Step into a lunge with a twist to open the hips and loosen the trunk.\"},{\"id\":\"4091\",\"n\":\"twist superman\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"obliques\",\"hamstrings\",\"core\"],\"st\":[\"Lie face down with your arms extended overhead and legs straight.\",\"Lift your arms, chest and legs off the floor.\",\"Rotate your torso slightly to one side while holding the lift.\",\"Return to the center, then rotate to the other side.\",\"Lower down with control and keep your neck neutral.\"],\"img\":\"4091.webp\",\"gif\":\"4091.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor exercise where you lift your limbs off the ground and add a rotation, training the lower back and glutes.\"},{\"id\":\"7585\",\"n\":\"twist turn lift\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with your knees bent and arms extended.\",\"Lift your shoulders and legs off the floor.\",\"Twist your torso and bring your knees toward one side.\",\"Turn back through the centre and lift again.\",\"Repeat to the other side, keeping the movement smooth and controlled.\"],\"img\":\"7585.webp\",\"gif\":\"7585.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A floor core move that combines a twist with a leg or torso lift. It works the abs and obliques through rotation.\"},{\"id\":\"5906\",\"n\":\"twisted leg lunge pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"glutes\",\"hip flexors\"],\"st\":[\"Step into a low lunge with your back knee down.\",\"Bring your palms together at your chest.\",\"Twist toward the front leg and hook your elbow outside the knee.\",\"Hold for 5 slow breaths.\",\"Switch legs.\"],\"img\":\"5906.webp\",\"gif\":\"5906.mp4\",\"cat\":\"yoga\",\"desc\":\"A lunge with a twist toward the front leg. Opens the hips and spine.\"},{\"id\":\"4620\",\"n\":\"twisting crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with knees bent and hands lightly behind your head.\",\"Curl your shoulders off the floor.\",\"Rotate your torso to bring one elbow toward the opposite knee.\",\"Lower with control and repeat on the other side.\",\"Avoid pulling on your neck.\"],\"img\":\"4620.webp\",\"gif\":\"4620.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with a rotation that adds work for the obliques on top of the abs.\",\"fv\":\"0824\"},{\"id\":\"0823\",\"n\":\"twisting crunch (arms straight)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\"],\"st\":[\"Lie on your back with knees bent and arms extended toward the ceiling.\",\"Curl your shoulders off the floor.\",\"Reach your straight arms toward one side of your knees.\",\"Lower slowly.\",\"Alternate sides, keeping your neck relaxed.\"],\"img\":\"0823.webp\",\"gif\":\"0823.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with straight arms reaching across to the side. It focuses on the abs and obliques.\"},{\"id\":\"3621\",\"n\":\"twisting crunch (straight arms)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and arms straight up.\",\"Lift your shoulders off the floor.\",\"Twist to reach one side.\",\"Return to center and twist the other way.\",\"Keep your lower back on the floor.\"],\"img\":\"3621.webp\",\"gif\":\"3621.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with a twist and arms extended to work the abs and obliques.\"},{\"id\":\"6016\",\"n\":\"twisting crunch v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and hands behind your head.\",\"Curl your shoulders off the floor.\",\"Twist to bring one elbow toward the opposite knee.\",\"Lower slowly.\",\"Alternate sides for your reps.\"],\"img\":\"6016.webp\",\"gif\":\"6016.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A crunch with a rotation to bring each elbow toward the opposite knee. Works the abs and obliques.\"},{\"id\":\"3249\",\"n\":\"two front toe touching\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"obliques\"],\"st\":[\"Stand with feet wide apart.\",\"Hinge forward with both arms reaching down.\",\"Touch the floor or your toes.\",\"Rise slowly.\",\"Repeat for the set.\"],\"img\":\"3249.webp\",\"gif\":\"3249.mp4\",\"cat\":\"mobility\",\"desc\":\"A wider standing toe touch that reaches down with both hands to warm up the legs and back.\"},{\"id\":\"1799\",\"n\":\"two handed hang back stretch (with training wall bars)\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"upper back\",\"forearms\"],\"st\":[\"Grip a wall bar overhead with both hands and walk your feet out slightly.\",\"Let your body hang and sink your hips back, relaxing your upper back and shoulders.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1799.webp\",\"gif\":\"1799.mp4\",\"cat\":\"stretching\",\"desc\":\"Hanging from wall bars with both hands lets gravity stretch your lats and decompress your back. Great after heavy pulling days.\"},{\"id\":\"6302\",\"n\":\"two legged inverted staff pose dwi pada viparita dandasana\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"triceps\",\"hip flexors\"],\"st\":[\"Start in a headstand or lie on your back with elbows on the floor.\",\"Arch your back and bring your feet toward the floor.\",\"Keep your forearms firm.\",\"Stay in the backbend, breathing steadily.\",\"Hold briefly, then come out carefully.\"],\"img\":\"6302.webp\",\"gif\":\"6302.mp4\",\"cat\":\"yoga\",\"desc\":\"A supported deep backbend resting on your forearms. It stretches the chest and spine.\"},{\"id\":\"3851\",\"n\":\"two legs hammer curl with towel v. 2\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Lie on your back and loop a towel around both feet.\",\"Hold the ends with palms facing each other.\",\"Pull the towel toward your chest while your legs resist.\",\"Pause briefly.\",\"Lower slowly.\"],\"img\":\"3851.webp\",\"gif\":\"3851.mp4\",\"cat\":\"strength\",\"desc\":\"A hammer curl using a towel looped around both feet. It trains your biceps and brachialis.\"},{\"id\":\"3850\",\"n\":\"two legs reverse biceps curl with towel v. 2\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Lie on your back and loop a towel around both feet.\",\"Hold the ends with an overhand grip.\",\"Pull the towel toward your chest while your legs resist.\",\"Pause briefly.\",\"Lower slowly.\"],\"img\":\"3850.webp\",\"gif\":\"3850.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse curl using a towel looped around both feet. It trains your biceps and forearms.\"},{\"id\":\"10439\",\"n\":\"two ropes climb\",\"bp\":\"back\",\"eq\":\"rope\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"forearms\",\"grip muscles\",\"core\",\"upper back\"],\"st\":[\"Grab one rope in each hand and hang with arms long.\",\"Pull up with one arm while you bend your elbow close to your body.\",\"Reach higher with the other hand and pull again.\",\"Keep your core tight and your legs steady.\",\"Climb to a safe height, then lower under control.\"],\"img\":\"10439.webp\",\"gif\":\"10439.mp4\",\"cat\":\"strength\",\"desc\":\"Climb up using two ropes, pulling with your arms one hand over the other. It builds a strong pull and grip.\"},{\"id\":\"10925\",\"n\":\"two to one leg jump\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"hamstrings\"],\"st\":[\"Stand with feet hip-width apart.\",\"Dip into a quarter squat and swing your arms back.\",\"Jump up and land on one foot.\",\"Absorb the landing with a bent knee and hold steady.\",\"Reset and alternate landing legs.\"],\"img\":\"10925.webp\",\"gif\":\"10925.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump taking off from two feet and landing on one. It builds power and landing control.\"},{\"id\":\"1223\",\"n\":\"underhand grip inverted back row\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"core\"],\"st\":[\"Set a bar at waist height and lie under it, gripping it with palms facing you.\",\"Straighten your body from heels to head.\",\"Pull your chest up to the bar, squeezing your shoulder blades.\",\"Lower yourself under control until your arms are straight.\",\"Keep your hips up the whole time.\"],\"img\":\"1223.webp\",\"gif\":\"1223.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight row under a low bar with an underhand grip. It builds the back and biceps.\"},{\"id\":\"6961\",\"n\":\"uneven pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Hang from the bar with one hand higher or on a towel and the other lower.\",\"Brace your core and pull your chest up.\",\"Lead with the working arm and pull your chin toward the bar.\",\"Lower yourself under control.\",\"Switch the hand positions on the next set.\"],\"img\":\"6961.webp\",\"gif\":\"6961.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A pull-up with the hands at different heights or one hand doing more work. It gently trains one-arm pulling strength.\"},{\"id\":\"4989\",\"n\":\"v sit cross punch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"shoulders\",\"triceps\"],\"st\":[\"Sit with knees bent and lean back, lifting your feet off the floor.\",\"Raise your fists in front of your chest.\",\"Punch one arm across your body while twisting your torso.\",\"Return to center and punch with the other arm.\",\"Keep your chest tall and your balance steady.\"],\"img\":\"4989.webp\",\"gif\":\"4989.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hold a V sit and punch across your body. You train the abs and obliques while balancing.\"},{\"id\":\"5046\",\"n\":\"v sit toe tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\",\"shoulders\"],\"st\":[\"Sit on the floor and lean back, lifting your legs into a V.\",\"Reach both arms forward.\",\"Crunch up and tap your toes with your fingers.\",\"Lower slightly back while keeping your feet up.\",\"Keep your chest open and repeat.\"],\"img\":\"5046.webp\",\"gif\":\"5046.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hold a V sit and reach to tap your toes. It strengthens the abs and challenges balance.\"},{\"id\":\"3622\",\"n\":\"v up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie flat with arms extended overhead.\",\"Raise legs and torso at the same time.\",\"Reach your hands toward your toes.\",\"Lower with control without touching the floor.\",\"Keep your legs as straight as you can.\"],\"img\":\"3622.webp\",\"gif\":\"3622.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lift your legs and torso together to form a V, a demanding core move.\",\"fv\":\"0825\"},{\"id\":\"4002\",\"n\":\"v up double crunch\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie flat with arms overhead.\",\"Lift your arms and legs into a V.\",\"Crunch in again.\",\"Lower with control.\",\"Keep your legs straight.\"],\"img\":\"4002.webp\",\"gif\":\"4002.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A V up where you crunch your arms and legs together twice. It hits the whole abdominal wall.\"},{\"id\":\"2815\",\"n\":\"v up down (with stability ball)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back holding the stability ball overhead with straight arms.\",\"Lift your arms and legs up together, curling into a V.\",\"Pass the ball from your hands to your feet.\",\"Lower back down slowly, holding the ball between your feet.\",\"Repeat, passing the ball back to your hands.\"],\"img\":\"2815.webp\",\"gif\":\"2815.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A V up where you pass a stability ball between hands and feet. Works the abs and builds control.\",\"fv\":\"2816\"},{\"id\":\"5344\",\"n\":\"v up hold\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"core\"],\"st\":[\"Sit on the floor with knees bent and lean back slightly.\",\"Lift your legs and straighten them to form a V.\",\"Reach your arms forward alongside your legs.\",\"Hold for 15-30 seconds.\",\"Keep your chest open and back from rounding.\",\"Lower with control.\"],\"img\":\"5344.webp\",\"gif\":\"5344.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a V-shaped position with legs and torso lifted. Builds strong abs and balance.\",\"hd\":1},{\"id\":\"4003\",\"n\":\"v up with clap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie flat with arms overhead.\",\"Lift your arms and legs into a V.\",\"Clap above your shins.\",\"Lower with control.\",\"Repeat smoothly.\"],\"img\":\"4003.webp\",\"gif\":\"4003.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A V up finishing with a clap above the legs. It trains the core and coordination.\",\"fv\":\"4271\"},{\"id\":\"5477\",\"n\":\"vertical leg raise (on parallel bars) v. 2\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"forearms\"],\"st\":[\"Support yourself on parallel bars with straight arms and shoulders pushed down.\",\"Keep your legs together and slightly bent or straight.\",\"Raise your legs until they reach hip height or higher, curling your pelvis.\",\"Lower them slowly without swinging.\",\"Repeat for the target reps.\"],\"img\":\"5477.webp\",\"gif\":\"5477.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Hanging-style leg raise performed supported on parallel bars, taking the legs high to challenge the lower abs.\"},{\"id\":\"3623\",\"n\":\"vertical leg raise (on parallel bars) v. 3\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"forearms\"],\"st\":[\"Support yourself on parallel bars with straight arms and shoulders down.\",\"Let your legs hang together.\",\"Raise your legs in front of you until they are about parallel to the floor or higher.\",\"Lower slowly without swinging.\",\"Keep your torso still.\"],\"img\":\"3623.webp\",\"gif\":\"3623.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Support yourself on parallel bars and lift your legs to train the lower abs and hip flexors.\"},{\"id\":\"0827\",\"n\":\"vertical mountain climber\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"core\",\"sm\":[\"core\",\"hip flexors\",\"quadriceps\"],\"st\":[\"Stand tall with hands raised in front of you at chest height.\",\"Drive one knee up toward your hands.\",\"Switch legs quickly, running in place.\",\"Stay on the balls of your feet.\",\"Keep a steady, brisk pace.\"],\"img\":\"0827.webp\",\"gif\":\"0827.mp4\",\"cat\":\"cardio\",\"desc\":\"A standing take on the mountain climber with fast knee drives. It lifts your heart rate and works the core.\"},{\"id\":\"5963\",\"n\":\"vertical sit up\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your legs raised straight toward the ceiling.\",\"Place your hands behind your head or across your chest.\",\"Curl your torso up and reach toward your feet.\",\"Pause at the top.\",\"Lower your upper body slowly to the floor.\"],\"img\":\"5963.webp\",\"gif\":\"5963.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A sit-up performed with the legs raised vertically, which keeps the focus on the abs by taking the hip flexors out of the pull.\"},{\"id\":\"2527\",\"n\":\"vibrate plate lunge\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Place one foot on the vibrating plate and step the other back.\",\"Lower into a lunge with your torso upright.\",\"Keep your front knee over your ankle.\",\"Hold the bottom briefly.\",\"Push up to return.\",\"Finish your reps, then switch legs.\"],\"img\":\"2527.webp\",\"gif\":\"2527.mp4\",\"cat\":\"strength\",\"desc\":\"A lunge with the front foot on a vibrating plate for added stability work.\"},{\"id\":\"2526\",\"n\":\"vibrate plate plank\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"glutes\"],\"st\":[\"Place your forearms or hands on the vibrating plate.\",\"Extend your legs behind you.\",\"Form a straight line from head to heels.\",\"Brace your abs and squeeze your glutes.\",\"Hold for 20-40 seconds.\",\"Come down carefully.\"],\"img\":\"2526.webp\",\"gif\":\"2526.mp4\",\"cat\":\"isometric\",\"desc\":\"A plank held on a vibrating platform that adds challenge to your core.\",\"hd\":1},{\"id\":\"2525\",\"n\":\"vibrate plate standing\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"core\"],\"st\":[\"Step onto the vibrating plate with your feet shoulder-width apart.\",\"Keep your knees slightly bent.\",\"Hold your posture tall and your core braced.\",\"Keep your weight balanced over your feet.\",\"Hold for 30-60 seconds.\",\"Step off carefully.\"],\"img\":\"2525.webp\",\"gif\":\"2525.mp4\",\"cat\":\"mobility\",\"desc\":\"A standing hold on a vibrating platform that engages the legs and core.\"},{\"id\":\"5983\",\"n\":\"vinyasa\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\",\"core\",\"lower back\"],\"st\":[\"Start in plank pose.\",\"Lower to chaturanga with your elbows by your ribs.\",\"Roll forward into upward dog with an open chest.\",\"Lift your hips to downward dog.\",\"Hold for a breath or two and repeat.\"],\"img\":\"5983.webp\",\"gif\":\"5983.mp4\",\"cat\":\"yoga\",\"desc\":\"A short flow of plank, chaturanga, upward dog and downward dog. Used to link poses together.\"},{\"id\":\"0828\",\"n\":\"walk (equipment)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"quadriceps\",\"hamstrings\"],\"st\":[\"Step onto the machine and set a comfortable speed.\",\"Stand tall with your shoulders relaxed.\",\"Swing your arms naturally as you walk.\",\"Land on your heel and roll through to your toes.\",\"Walk for 10-30 minutes at a pace where you can still talk.\",\"Slow down gradually at the end.\"],\"img\":\"0828.webp\",\"gif\":\"0828.mp4\",\"cat\":\"cardio\",\"desc\":\"Easy walking on a machine or track at a steady pace, great for warming up or building a base of aerobic fitness.\"},{\"id\":\"0829\",\"n\":\"walk (high knees)\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\",\"calves\"],\"st\":[\"Stand tall with your arms relaxed.\",\"Lift one knee to hip height.\",\"Step down and lift the other knee.\",\"Swing your arms naturally.\",\"Keep a steady rhythm for the set duration.\"],\"img\":\"0829.webp\",\"gif\":\"0829.mp4\",\"cat\":\"cardio\",\"desc\":\"Walking while lifting your knees high. It warms up the legs and gets your heart pumping.\"},{\"id\":\"10749\",\"n\":\"walk leg kick\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"hip flexors\"],\"st\":[\"Stand tall.\",\"Step forward and kick the opposite leg up.\",\"Alternate legs.\",\"Swing your arms.\",\"Continue for the set time.\"],\"img\":\"10749.webp\",\"gif\":\"10749.mp4\",\"cat\":\"cardio\",\"desc\":\"Walk while kicking each leg up. It warms the legs.\"},{\"id\":\"2140\",\"n\":\"walk wave machine\",\"bp\":\"cardio\",\"eq\":\"elliptical machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\"],\"st\":[\"Step onto the machine and hold the handles lightly.\",\"Start moving your legs in a smooth walking rhythm.\",\"Keep your posture tall and your core lightly braced.\",\"Pick a pace that lets you breathe steadily.\",\"Keep going for 10-30 minutes depending on your fitness.\",\"Slow down for the last minute before stepping off.\"],\"img\":\"2140.webp\",\"gif\":\"2140.mp4\",\"cat\":\"cardio\",\"desc\":\"A low-impact cardio machine session that works the legs in a smooth walking motion to raise your heart rate.\",\"fv\":\"3625\"},{\"id\":\"2258\",\"n\":\"walking\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Stand tall with your shoulders relaxed and your gaze ahead.\",\"Start walking with a natural stride.\",\"Swing your arms gently opposite to your legs.\",\"Land softly on your heel and roll through to the toes.\",\"Keep a pace that lets you breathe comfortably.\",\"Walk for 20-60 minutes.\"],\"img\":\"2258.webp\",\"gif\":\"2258.mp4\",\"cat\":\"cardio\",\"desc\":\"Plain walking at an easy to brisk pace, a simple way to build endurance and stay active.\",\"fv\":\"2261\"},{\"id\":\"9608\",\"n\":\"walking backward on a treadmill\",\"bp\":\"cardio\",\"eq\":\"leverage machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"calves\",\"glutes\"],\"st\":[\"Set the treadmill to a very slow speed and hold the handrails.\",\"Turn to face away from the direction of the belt.\",\"Step back gently, landing on the toes first.\",\"Keep your chest tall and take small steps.\",\"Continue for several minutes at a comfortable pace.\"],\"img\":\"9608.webp\",\"gif\":\"9608.mp4\",\"cat\":\"cardio\",\"desc\":\"Walking backwards at a gentle pace on a treadmill. It works the quads and gets your heart rate up in a joint-friendly way.\"},{\"id\":\"4259\",\"n\":\"walking on elliptical machine v. 7\",\"bp\":\"cardio\",\"eq\":\"elliptical machine\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Step onto the pedals and hold the handles lightly.\",\"Start moving in a smooth, walking-style stride.\",\"Stand tall with your shoulders relaxed and core braced.\",\"Choose a moderate resistance and keep a steady pace.\",\"Continue for 10 to 30 minutes, depending on your fitness, then cool down slowly.\"],\"img\":\"4259.webp\",\"gif\":\"4259.mp4\",\"cat\":\"cardio\",\"desc\":\"Steady walking motion on an elliptical trainer. It is a low-impact way to raise your heart rate and build endurance.\"},{\"id\":\"2259\",\"n\":\"walking on treadmill\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"calves\"],\"st\":[\"Step onto the belt and hold the rails while you start at a slow speed.\",\"Increase to a comfortable walking pace.\",\"Let go of the rails and swing your arms naturally.\",\"Keep your head up and your steps even.\",\"Add some incline if you want more challenge.\",\"Walk for 20-45 minutes and slow down before stepping off.\"],\"img\":\"2259.webp\",\"gif\":\"2259.mp4\",\"cat\":\"cardio\",\"desc\":\"Walking on a treadmill lets you control speed and incline for steady, low-impact cardio.\",\"fv\":\"2260\"},{\"id\":\"10590\",\"n\":\"walkout lat stretch\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"shoulders\",\"core\"],\"st\":[\"Stand and hinge forward to place your hands on the floor.\",\"Walk your hands out in front of you.\",\"Sit your hips back and press your chest down.\",\"Hold for 20-30 seconds.\",\"Walk your hands back in and stand up.\"],\"img\":\"10590.webp\",\"gif\":\"10590.mp4\",\"cat\":\"stretching\",\"desc\":\"Walk your hands out and sit your hips back to stretch the lats. It opens the sides of the back.\"},{\"id\":\"10997\",\"n\":\"wall assisted handstand to tuck planche negative\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"triceps\",\"upper back\",\"forearms\"],\"st\":[\"Kick up into a handstand with your heels on the wall.\",\"Brace your core and keep your arms straight.\",\"Slowly lower your body forward.\",\"Tuck your knees as you reach the planche position.\",\"Control the descent and then reset.\"],\"img\":\"10997.webp\",\"gif\":\"10997.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Lowering from a wall handstand into a tuck planche. It builds advanced shoulder strength.\"},{\"id\":\"2458\",\"n\":\"wall ball\",\"bp\":\"full body\",\"eq\":\"medicine ball\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand facing a wall holding a medicine ball at your chest.\",\"Squat down with your chest up.\",\"Drive up powerfully and throw the ball to a target on the wall.\",\"Catch the ball as it returns.\",\"Flow straight into the next squat.\",\"Keep a steady rhythm.\"],\"img\":\"2458.webp\",\"gif\":\"2458.mp4\",\"cat\":\"strength\",\"desc\":\"A squat-to-throw movement with a medicine ball that conditions the whole body.\"},{\"id\":\"0255\",\"n\":\"wall ball circles\",\"bp\":\"shoulders\",\"eq\":\"stability ball\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper back\",\"trapezius\"],\"st\":[\"Stand facing a wall and place a ball against it at shoulder height with one hand.\",\"Keep your arm straight but relaxed.\",\"Roll the ball in small circles on the wall.\",\"Do several circles in one direction.\",\"Reverse the direction.\",\"Keep your shoulder down, then switch arms.\"],\"img\":\"0255.webp\",\"gif\":\"0255.mp4\",\"cat\":\"mobility\",\"desc\":\"A shoulder drill rolling a ball in circles against a wall. It warms up the shoulder and builds control.\"},{\"id\":\"10998\",\"n\":\"wall facing single leg split handstand hold\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"triceps\",\"forearms\",\"upper back\"],\"st\":[\"Kick up into a handstand facing the wall.\",\"Keep your arms straight and push the floor away.\",\"Lift one leg off the wall.\",\"Hold for 10-20 seconds with control.\",\"Return the leg and come down safely.\"],\"img\":\"10998.webp\",\"gif\":\"10998.mp4\",\"cat\":\"isometric\",\"desc\":\"A wall-facing handstand with one leg split off the wall. It trains balance and shoulder endurance.\",\"hd\":1},{\"id\":\"2092\",\"n\":\"wall flexors stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Stand facing a wall and place one palm on it with the fingers pointing down.\",\"Keep your arm straight.\",\"Slowly turn your body away until you feel the stretch in the forearm.\",\"Keep your fingers flat on the wall.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"2092.webp\",\"gif\":\"2092.mp4\",\"cat\":\"stretching\",\"desc\":\"Pressing the palm against a wall to stretch the forearm flexors.\"},{\"id\":\"7389\",\"n\":\"wall plank\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"obliques\"],\"st\":[\"Stand facing a wall and place your forearms or hands on it.\",\"Walk your feet back until your body is in a slanted line.\",\"Brace your abs and squeeze your glutes.\",\"Keep your head neutral.\",\"Hold for 20-40 seconds.\",\"Step in to finish.\"],\"img\":\"7389.webp\",\"gif\":\"7389.mp4\",\"cat\":\"isometric\",\"desc\":\"A standing plank against a wall, an easy way to learn core bracing.\",\"hd\":1},{\"id\":\"4096\",\"n\":\"wall press heel tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"glutes\"],\"st\":[\"Lie on your back with your hips and knees bent at 90 degrees and feet flat on a wall.\",\"Press your lower back into the floor.\",\"Lower one heel to tap the floor while the other foot stays on the wall.\",\"Return and tap with the other heel.\",\"Move slowly without arching your back.\"],\"img\":\"4096.webp\",\"gif\":\"4096.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A lying core move with your feet pressed against a wall, tapping each heel alternately to challenge your lower abs.\"},{\"id\":\"5174\",\"n\":\"wall pulse\",\"bp\":\"upper arms\",\"eq\":\"body weight\",\"tg\":\"triceps\",\"mg\":\"chest\",\"sm\":[\"chest\",\"shoulders\"],\"st\":[\"Stand facing a wall and place your hands on it, close together at chest height.\",\"Step your feet back so your body leans in a straight line.\",\"Bend your elbows slightly to bring your chest toward the wall.\",\"Pulse in short, controlled movements.\",\"Keep your elbows tucked and your core tight.\"],\"img\":\"5174.webp\",\"gif\":\"5174.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Small pulses in a wall push-up position. It keeps constant tension on your triceps.\"},{\"id\":\"7557\",\"n\":\"wall sit (narrow stance)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Lean your back on a wall with feet close together.\",\"Slide down until your thighs are about parallel.\",\"Keep knees over ankles.\",\"Hold for 20-60 seconds.\",\"Slide back up slowly.\"],\"img\":\"7557.webp\",\"gif\":\"7557.mp4\",\"cat\":\"isometric\",\"desc\":\"Wall sit with feet close together to focus on the quads.\",\"hd\":1},{\"id\":\"7558\",\"n\":\"wall sit from deficit\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\"],\"st\":[\"Stand with your heels on a low platform and your back on a wall.\",\"Slide down until thighs are parallel.\",\"Keep your back flat.\",\"Hold for 20-45 seconds.\",\"Slide up carefully.\"],\"img\":\"7558.webp\",\"gif\":\"7558.mp4\",\"cat\":\"isometric\",\"desc\":\"Wall sit with heels raised for a tougher quad hold.\",\"hd\":1},{\"id\":\"5234\",\"n\":\"wall walks\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"core\",\"upper chest\"],\"st\":[\"Lie face down with your feet against a wall.\",\"Place your hands beside your chest and push up into a plank.\",\"Walk your feet up the wall as your hands walk toward it.\",\"Stop where you can keep your body straight and braced.\",\"Walk back down slowly with control.\"],\"img\":\"5234.webp\",\"gif\":\"5234.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Walk your feet up a wall into a handstand-like position, then walk back down. It builds shoulder strength and trunk control.\"},{\"id\":\"3465\",\"n\":\"warming up in lunge (five)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3465.webp\",\"gif\":\"3465.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 5 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"3464\",\"n\":\"warming up in lunge (four)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3464.webp\",\"gif\":\"3464.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 4 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"3461\",\"n\":\"warming up in lunge (one)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3461.webp\",\"gif\":\"3461.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 1 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"3467\",\"n\":\"warming up in lunge (seven)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3467.webp\",\"gif\":\"3467.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 7 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"3466\",\"n\":\"warming up in lunge (six)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3466.webp\",\"gif\":\"3466.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 6 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"3463\",\"n\":\"warming up in lunge (three)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3463.webp\",\"gif\":\"3463.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 3 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"3462\",\"n\":\"warming up in lunge (two)\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"hip flexors\"],\"st\":[\"Stand tall with your feet hip-width apart and your core braced.\",\"Step into the lunge position described by this variation with control.\",\"Keep your front knee over your ankle and your torso upright.\",\"Move smoothly through the full range without bouncing.\",\"Return to standing and repeat on the other side.\",\"Do 8-10 slow reps per side as part of a warm-up.\"],\"img\":\"3462.webp\",\"gif\":\"3462.mp4\",\"cat\":\"mobility\",\"desc\":\"A dynamic lunge warm-up drill (part 2 of 7) that opens the hips and prepares your legs.\"},{\"id\":\"4410\",\"n\":\"warrior ii yoga pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"shoulders\",\"core\"],\"st\":[\"Stand with your feet wide apart and turn your front foot out.\",\"Bend the front knee over the ankle.\",\"Extend your arms out to the sides at shoulder height.\",\"Gaze over your front fingertips and keep your torso upright.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"4410.webp\",\"gif\":\"4410.mp4\",\"cat\":\"yoga\",\"desc\":\"A strong standing pose with wide legs and arms outstretched, building leg strength, hip opening and stamina.\"},{\"id\":\"5907\",\"n\":\"warrior iii pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\",\"calves\"],\"st\":[\"Stand on one leg with your arms overhead.\",\"Hinge forward and lift the back leg behind you.\",\"Bring your torso and back leg level with the floor.\",\"Hold for 5 slow breaths with your hips square.\",\"Lower and switch legs.\"],\"img\":\"5907.webp\",\"gif\":\"5907.mp4\",\"cat\":\"yoga\",\"desc\":\"A one-leg balance with the torso and back leg parallel to the floor. Builds balance and strength.\"},{\"id\":\"3471\",\"n\":\"warrior pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Take a long stance.\",\"Bend your front knee over your ankle.\",\"Raise your arms.\",\"Keep your back leg straight.\",\"Hold for 20-30 seconds.\",\"Switch sides.\"],\"img\":\"3471.webp\",\"gif\":\"3471.mp4\",\"cat\":\"yoga\",\"desc\":\"A standing yoga pose that builds strength and stretches the hips.\"},{\"id\":\"0964\",\"n\":\"warrior pose i virabhadrasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hip flexors\",\"shoulders\",\"core\"],\"st\":[\"Step one foot back into a long stance, with the back foot turned out slightly.\",\"Bend the front knee over the ankle.\",\"Square your hips toward the front.\",\"Raise both arms overhead and lift your chest.\",\"Hold for 5 breaths, then switch sides.\"],\"img\":\"0964.webp\",\"gif\":\"0964.mp4\",\"cat\":\"stretching\",\"desc\":\"A lunge with arms raised overhead. It stretches the hip flexors and chest and strengthens the legs.\"},{\"id\":\"6291\",\"n\":\"warrior pose ii\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet wide, turn your front foot out and back foot slightly in.\",\"Bend your front knee over the ankle.\",\"Extend both arms parallel to the floor.\",\"Gaze over your front hand.\",\"Hold for 20-30 seconds, then switch sides.\"],\"img\":\"6291.webp\",\"gif\":\"6291.mp4\",\"cat\":\"yoga\",\"desc\":\"A wide lunge with arms extended to the sides. It strengthens the legs and opens the hips.\"},{\"id\":\"0963\",\"n\":\"warrior pose virabhadrasana v. 2\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"adductors\",\"shoulders\",\"core\"],\"st\":[\"Stand with feet wide and turn your front foot out.\",\"Bend the front knee over the ankle.\",\"Extend your arms out to the sides at shoulder height.\",\"Turn your head to look over the front hand.\",\"Hold for 5 breaths, then switch sides.\"],\"img\":\"0963.webp\",\"gif\":\"0963.mp4\",\"cat\":\"yoga\",\"desc\":\"A wide lunge with arms stretched to the sides. It strengthens the legs and builds stamina.\"},{\"id\":\"10710\",\"n\":\"weight plate lying crunch\",\"bp\":\"waist\",\"eq\":\"weight plate\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent.\",\"Hold the plate on your chest.\",\"Curl your shoulders up.\",\"Pause and squeeze.\",\"Lower slowly.\"],\"img\":\"10710.webp\",\"gif\":\"10710.mp4\",\"cat\":\"strength\",\"desc\":\"Crunch while holding a plate. It works the abs.\"},{\"id\":\"6698\",\"n\":\"weight plate standing biceps curl\",\"bp\":\"upper arms\",\"eq\":\"weight plate\",\"tg\":\"biceps\",\"mg\":\"brachialis\",\"sm\":[\"brachialis\",\"forearms\",\"grip muscles\"],\"st\":[\"Stand tall holding a plate at its sides with both hands, arms down.\",\"Keep your elbows tucked against your ribs.\",\"Curl the plate up toward your chest.\",\"Squeeze your biceps at the top.\",\"Lower the plate slowly to full arm extension.\"],\"img\":\"6698.webp\",\"gif\":\"6698.mp4\",\"cat\":\"strength\",\"desc\":\"A standing curl holding a single plate. The plate grip also challenges your hands and forearms.\"},{\"id\":\"7055\",\"n\":\"weight plate standing hands torsion\",\"bp\":\"lower arms\",\"eq\":\"weight plate\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\",\"grip muscles\"],\"st\":[\"Stand holding a plate at its sides in front of you.\",\"Keep your elbows bent and close to your sides.\",\"Rotate the plate left and right using your wrists and forearms.\",\"Move slowly and under control.\",\"Keep your shoulders relaxed.\"],\"img\":\"7055.webp\",\"gif\":\"7055.mp4\",\"cat\":\"strength\",\"desc\":\"A standing twisting move holding a plate that works the forearm rotators. It builds wrist and grip strength.\"},{\"id\":\"10677\",\"n\":\"weighted backpack running\",\"bp\":\"cardio\",\"eq\":\"weighted\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"glutes\",\"calves\",\"core\"],\"st\":[\"Strap a snug backpack with a modest load on your back.\",\"Start with an easy jog on flat ground.\",\"Keep your torso tall and your steps light.\",\"Maintain a pace where you can breathe steadily.\",\"Cut back the load if your form suffers.\",\"Run for 10-20 minutes.\"],\"img\":\"10677.webp\",\"gif\":\"10677.mp4\",\"cat\":\"cardio\",\"desc\":\"Running with a loaded backpack to raise the effort. It builds endurance and leg strength.\"},{\"id\":\"10676\",\"n\":\"weighted backpack walking\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"calves\",\"core\",\"upper back\"],\"st\":[\"Put on a backpack and tighten the straps snug.\",\"Stand tall with your shoulders back.\",\"Walk at a steady pace on flat ground.\",\"Take natural strides and breathe evenly.\",\"Keep your core lightly braced.\",\"Walk for 10-30 minutes depending on your fitness.\"],\"img\":\"10676.webp\",\"gif\":\"10676.mp4\",\"cat\":\"cardio\",\"desc\":\"Walking with a loaded backpack to add resistance. It builds leg endurance and trunk strength.\"},{\"id\":\"8891\",\"n\":\"weighted bag good morning\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"core\"],\"st\":[\"Place the weighted bag across your upper back and hold it in place.\",\"Stand with your feet hip width and your knees slightly bent.\",\"Push your hips back and lower your torso with a flat back.\",\"Go down until you feel a stretch in the hamstrings.\",\"Drive your hips forward to stand tall again.\",\"Keep your neck neutral all the way.\"],\"img\":\"8891.webp\",\"gif\":\"8891.mp4\",\"cat\":\"strength\",\"desc\":\"Hinging forward with a weighted bag on your back trains the hamstrings, glutes and lower back. It teaches a strong hip hinge.\"},{\"id\":\"8701\",\"n\":\"weighted bag walking lunge\",\"bp\":\"upper legs\",\"eq\":\"sandbag\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold the bag at your chest or on your shoulders.\",\"Stand tall.\",\"Step forward and lower until both knees are about 90 degrees.\",\"Push through the front foot and bring the back leg forward.\",\"Continue, alternating legs.\"],\"img\":\"8701.webp\",\"gif\":\"8701.mp4\",\"cat\":\"strength\",\"desc\":\"A walking lunge carrying a weighted bag, building the legs, glutes and core.\"},{\"id\":\"10861\",\"n\":\"weighted ball reverse hyperextension on ghd\",\"bp\":\"upper legs\",\"eq\":\"medicine ball\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\"],\"st\":[\"Lie face down on the GHD with hips at the edge and a ball between your feet.\",\"Hold the pad.\",\"Lift your legs until they line up with your torso.\",\"Squeeze your glutes at the top.\",\"Lower slowly.\",\"Do not swing.\"],\"img\":\"10861.webp\",\"gif\":\"10861.mp4\",\"cat\":\"strength\",\"desc\":\"Reverse hyper on a GHD, with a ball held between your feet. It trains glutes and hamstrings.\"},{\"id\":\"2127\",\"n\":\"weighted captain's chair leg raise\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"forearms\"],\"st\":[\"Position yourself on a captain's chair with your forearms on the pads and back against the backrest.\",\"Hold the weight securely between your feet or on your ankles.\",\"Brace your core and raise your knees or legs up toward your chest.\",\"Curl your pelvis slightly at the top.\",\"Lower your legs slowly without swinging.\",\"Repeat for the planned reps.\"],\"img\":\"2127.webp\",\"gif\":\"2127.mp4\",\"cat\":\"strength\",\"desc\":\"A captain's chair leg raise with added weight, building lower ab and hip flexor strength.\",\"fv\":\"11009\"},{\"id\":\"5910\",\"n\":\"weighted chain sumo deadlift\",\"bp\":\"upper legs\",\"eq\":\"barbell\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"adductors\",\"lower back\",\"grip muscles\"],\"st\":[\"Hang chains on a barbell and stand with a wide stance, toes pointed out.\",\"Grip the bar inside your knees with a flat back.\",\"Push the floor away and drive your knees out.\",\"Stand tall as the chains lift and the load increases.\",\"Lock out with your glutes, then lower the bar under control.\"],\"img\":\"5910.webp\",\"gif\":\"5910.mp4\",\"cat\":\"strength\",\"desc\":\"A sumo deadlift with chains hung on the bar, so the load gets heavier as you stand up. It builds the glutes, inner thighs and back.\"},{\"id\":\"4102\",\"n\":\"weighted chin up\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"rhomboids\"],\"st\":[\"Attach the weight with a belt and grip the bar with palms facing you.\",\"Hang with arms straight.\",\"Pull your chest toward the bar by driving your elbows down.\",\"Pause with your chin above the bar.\",\"Lower under control to full extension.\"],\"img\":\"4102.webp\",\"gif\":\"4102.mp4\",\"cat\":\"strength\",\"desc\":\"A chin up with added load, building pulling strength in your lats and biceps.\"},{\"id\":\"4129\",\"n\":\"weighted counterbalanced skater squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\"],\"st\":[\"Hold a weight out in front and stand on one leg.\",\"Bend your standing knee while reaching your rear leg back.\",\"Lower until your rear knee nearly touches the floor.\",\"Push back to standing.\",\"Finish your reps, then switch legs.\"],\"img\":\"4129.webp\",\"gif\":\"4129.mp4\",\"cat\":\"strength\",\"desc\":\"A single leg skater squat with a counterweight held in front for balance.\"},{\"id\":\"4128\",\"n\":\"weighted counterbalanced squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"core\",\"hamstrings\"],\"st\":[\"Hold a weight at chest height and stand with feet shoulder-width apart.\",\"Extend your arms forward as you descend.\",\"Squat until thighs are parallel.\",\"Keep your chest tall.\",\"Stand back up through your heels.\"],\"img\":\"4128.webp\",\"gif\":\"4128.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a weight out in front as a counterweight, helping you stay upright.\"},{\"id\":\"1250\",\"n\":\"weighted crunch (behind head)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your back with your knees bent and feet flat.\",\"Hold a weight behind your head with your elbows out.\",\"Curl your shoulders up, contracting your abs.\",\"Pause at the top.\",\"Lower slowly without pulling on your neck.\"],\"img\":\"1250.webp\",\"gif\":\"1250.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with a weight held behind your head. The extra load makes it harder on the abs.\"},{\"id\":\"0831\",\"n\":\"weighted crunch (bent knee)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a weight against your chest.\",\"Curl your shoulders up off the floor.\",\"Pause briefly at the top.\",\"Lower slowly and repeat.\"],\"img\":\"0831.webp\",\"gif\":\"0831.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with a weight held on your chest. The added load makes the abs work harder.\"},{\"id\":\"4252\",\"n\":\"weighted crunch v. 2\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"core\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a weight against your chest.\",\"Curl your shoulders and upper back off the floor.\",\"Squeeze your abs at the top.\",\"Lower slowly.\",\"Keep your chin off your chest.\"],\"img\":\"4252.webp\",\"gif\":\"4252.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with weight held on your chest or behind your head. The added load makes the abs work harder.\"},{\"id\":\"4127\",\"n\":\"weighted dead bug\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Lie on your back holding a weight above your chest.\",\"Raise your knees over your hips.\",\"Extend the opposite arm and leg.\",\"Return to the start.\",\"Alternate sides, keeping your back flat.\"],\"img\":\"4127.webp\",\"gif\":\"4127.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug with added weight to increase core work.\"},{\"id\":\"2130\",\"n\":\"weighted decline crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on a decline bench and hook your feet under the pads.\",\"Hold a weight plate or dumbbell against your chest.\",\"Curl your upper body up by contracting the abs.\",\"Pause briefly at the top without pulling on your neck.\",\"Lower back down with control.\",\"Repeat for the planned reps.\"],\"img\":\"2130.webp\",\"gif\":\"2130.mp4\",\"cat\":\"strength\",\"desc\":\"A decline bench crunch with a weight held at the chest, adding resistance for the abs.\"},{\"id\":\"10879\",\"n\":\"weighted dumbbell crunch (hands overhead) v. 2\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a dumbbell at one end with both hands, arms extended overhead.\",\"Crunch up and let the dumbbell travel in an arc toward your knees.\",\"Squeeze your abs at the top.\",\"Lower with control and repeat.\"],\"img\":\"10879.webp\",\"gif\":\"10879.mp4\",\"cat\":\"strength\",\"desc\":\"A second version of the overhead dumbbell crunch. It builds ab strength with a loaded reach.\",\"fv\":\"10880\"},{\"id\":\"8873\",\"n\":\"weighted dumbbell lying knee raise\",\"bp\":\"waist\",\"eq\":\"dumbbell\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Lie on your back with a dumbbell secured between your feet.\",\"Keep your lower back pressed down.\",\"Bring your knees toward your chest.\",\"Lower your feet slowly without touching the floor.\",\"Repeat for controlled reps.\"],\"img\":\"8873.webp\",\"gif\":\"8873.mp4\",\"cat\":\"strength\",\"desc\":\"A lying knee raise holding a dumbbell between your feet or legs, challenging the lower abs.\"},{\"id\":\"1603\",\"n\":\"weighted exercise ball wall squat\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\"],\"st\":[\"Place a stability ball between your lower back and a wall.\",\"Hold your weight at chest level or at your sides.\",\"Step your feet forward and squat as the ball rolls down your back.\",\"Lower until your thighs are about parallel to the floor.\",\"Press through your heels to rise back up.\"],\"img\":\"1603.webp\",\"gif\":\"1603.mp4\",\"cat\":\"strength\",\"desc\":\"A wall squat with a stability ball behind you while holding extra weight. It adds load to a back-supported squat.\"},{\"id\":\"3282\",\"n\":\"weighted floor crunch feet on bench\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\"],\"st\":[\"Lie on your back with your calves on a bench and knees bent.\",\"Hold a weight plate or dumbbell against your chest.\",\"Curl your shoulders off the floor by tightening your abs.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"3282.webp\",\"gif\":\"3282.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded crunch with the calves on a bench, for stronger abs once bodyweight crunches feel easy.\"},{\"id\":\"3283\",\"n\":\"weighted floor twisting crunch feet on bench\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your back with your calves on a bench and knees bent.\",\"Hold a light weight against your chest with both hands.\",\"Curl up and rotate one shoulder toward the opposite knee.\",\"Lower with control.\",\"Alternate sides each rep.\"],\"img\":\"3283.webp\",\"gif\":\"3283.mp4\",\"cat\":\"strength\",\"desc\":\"A loaded twisting crunch with the legs on a bench, building the abs and obliques.\"},{\"id\":\"3182\",\"n\":\"weighted frog pump\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\"],\"st\":[\"Lie on your back with the soles of your feet together and knees open.\",\"Rest a weight on your hips.\",\"Drive your hips up by squeezing your glutes.\",\"Pause at the top.\",\"Lower and repeat.\"],\"img\":\"3182.webp\",\"gif\":\"3182.mp4\",\"cat\":\"strength\",\"desc\":\"A frog-style glute bridge with extra weight on your hips for stronger glutes.\"},{\"id\":\"7588\",\"n\":\"weighted front raise hold\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\",\"forearms\"],\"st\":[\"Stand tall holding a weight plate with both hands at your thighs.\",\"Raise it straight in front of you to shoulder height.\",\"Keep your arms nearly straight and your ribs down.\",\"Hold the position, breathing steadily, for 20-40 seconds.\",\"Lower the plate slowly with control.\"],\"img\":\"7588.webp\",\"gif\":\"7588.mp4\",\"cat\":\"isometric\",\"desc\":\"Hold a weight plate out in front of you at shoulder height. It builds endurance in the front delts.\",\"hd\":1},{\"id\":\"5818\",\"n\":\"weighted full can exercise\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"rotator cuff\",\"sm\":[\"rotator cuff\",\"upper chest\",\"trapezius\"],\"st\":[\"Hold a light weight in each hand with thumbs pointing up.\",\"Stand tall with arms at your sides.\",\"Raise your arms diagonally forward to about shoulder height.\",\"Pause briefly.\",\"Lower slowly with control.\"],\"img\":\"5818.webp\",\"gif\":\"5818.mp4\",\"cat\":\"strength\",\"desc\":\"Raise light weights in front at a diagonal with thumbs up. It trains the shoulder muscles that lift the arm.\"},{\"id\":\"7411\",\"n\":\"weighted full squat from deficit\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"core\"],\"st\":[\"Stand with your heels on a low plate or platform, holding a weight at your chest.\",\"Brace your core and keep your chest up.\",\"Squat as deep as comfortable.\",\"Keep your knees tracking over your toes.\",\"Drive up to standing.\"],\"img\":\"7411.webp\",\"gif\":\"7411.mp4\",\"cat\":\"strength\",\"desc\":\"Deep weighted squat with heels raised to increase depth and quad work.\"},{\"id\":\"5529\",\"n\":\"weighted full squat with overhead press\",\"bp\":\"full body\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Hold the weight at your shoulders and stand with feet shoulder width.\",\"Squat down deeply with chest up.\",\"Drive up through your legs.\",\"Use that momentum to press the weight overhead.\",\"Lower it back to your shoulders and repeat.\"],\"img\":\"5529.webp\",\"gif\":\"5529.mp4\",\"cat\":\"strength\",\"desc\":\"Full-depth squat followed by an overhead press, a thruster-style move that works legs and shoulders together.\"},{\"id\":\"2986\",\"n\":\"weighted hammer grip pull up on dip cage\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"brachialis\",\"upper back\",\"forearms\",\"core\"],\"st\":[\"Attach a belt or vest with weight and grip the neutral handles of the cage.\",\"Hang with your arms straight and your core braced.\",\"Pull your chest up until your chin passes the handles.\",\"Pause briefly.\",\"Lower slowly to a full hang and repeat.\"],\"img\":\"2986.webp\",\"gif\":\"2986.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A weighted pull-up with a neutral hammer grip on a dip cage. It builds the lats and arms with extra load.\"},{\"id\":\"4181\",\"n\":\"weighted hang chin up\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"grip muscles\"],\"st\":[\"Attach weight and hang from the bar with palms facing you.\",\"Start from straight arms.\",\"Pull your chest toward the bar.\",\"Get your chin over the bar.\",\"Lower fully with control.\",\"Avoid swinging.\"],\"img\":\"4181.webp\",\"gif\":\"4181.mp4\",\"cat\":\"strength\",\"desc\":\"A chin up from a dead hang with added weight. It builds lats and biceps strength.\"},{\"id\":\"2754\",\"n\":\"weighted hip thrusts\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"core\"],\"st\":[\"Sit on the floor with your upper back against a bench and the weight across your hips.\",\"Plant your feet flat and bend your knees.\",\"Drive through your heels to lift your hips.\",\"Squeeze your glutes at the top.\",\"Lower slowly and repeat.\"],\"img\":\"2754.webp\",\"gif\":\"2754.mp4\",\"cat\":\"strength\",\"desc\":\"A hip thrust with added weight for building strong glutes.\"},{\"id\":\"5035\",\"n\":\"weighted hyperextension\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\"],\"st\":[\"Set the pad at hip level on a hyperextension bench with your feet secured.\",\"Hold a weight plate or dumbbell against your chest.\",\"Lower your torso with a straight back.\",\"Raise it until your body forms a straight line.\",\"Do not overarch at the top.\"],\"img\":\"5035.webp\",\"gif\":\"5035.mp4\",\"cat\":\"strength\",\"desc\":\"Back extension holding a weight at your chest. It trains the lower back, glutes and hamstrings.\",\"fv\":\"5782\"},{\"id\":\"5068\",\"n\":\"weighted incline svend press\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"shoulders\",\"triceps\"],\"st\":[\"Set a bench to an incline and sit back with a weight plate held between your palms at chest height.\",\"Squeeze the plate hard with both hands.\",\"Push it straight out until your arms are extended.\",\"Pull it back to your chest while still squeezing.\",\"Keep your back against the pad and shoulders down.\"],\"img\":\"5068.webp\",\"gif\":\"5068.mp4\",\"cat\":\"strength\",\"desc\":\"Squeeze a weight plate between your palms and push it forward while on an incline. It hits the inner chest with a constant squeeze.\"},{\"id\":\"1184\",\"n\":\"weighted inverted row\",\"bp\":\"back\",\"eq\":\"weighted\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"biceps\",\"rhomboids\",\"rear deltoids\"],\"st\":[\"Set a bar at waist height and lie under it with extra weight on your torso.\",\"Grip the bar just wider than shoulders.\",\"Keep your body straight from heels to head.\",\"Pull your chest to the bar.\",\"Lower under control.\"],\"img\":\"1184.webp\",\"gif\":\"1184.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An inverted row with extra weight placed on your body for added back challenge.\"},{\"id\":\"9517\",\"n\":\"weighted kettlebell dead bug\",\"bp\":\"waist\",\"eq\":\"kettlebell\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\",\"shoulders\"],\"st\":[\"Lie on your back holding a kettlebell above your chest with straight arms.\",\"Raise your knees to a tabletop position.\",\"Press your lower back into the floor.\",\"Extend one leg out while keeping your back flat.\",\"Return it and alternate sides.\"],\"img\":\"9517.webp\",\"gif\":\"9517.mp4\",\"cat\":\"strength\",\"desc\":\"A dead bug done while holding a kettlebell overhead, adding load to the core challenge.\"},{\"id\":\"0836\",\"n\":\"weighted leg extension crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"quadriceps\"],\"st\":[\"Lie on your back holding a weight at your chest.\",\"Start with knees bent and lifted.\",\"Curl up while straightening your legs forward.\",\"Bring your knees back in as you lower.\",\"Keep your lower back pressed to the floor.\"],\"img\":\"0836.webp\",\"gif\":\"0836.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch where your legs extend as you curl up, holding a weight. It hits the abs and lower abs hard.\"},{\"id\":\"0837\",\"n\":\"weighted lying hip abduction\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\"],\"st\":[\"Lie on your side with a weight on your top thigh or ankle.\",\"Keep your body in a straight line.\",\"Lift the top leg up and slightly back.\",\"Lower with control.\",\"Finish your reps, then switch sides.\"],\"img\":\"0837.webp\",\"gif\":\"0837.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying leg lift with added weight. It strengthens the outer hip and glutes.\"},{\"id\":\"1042\",\"n\":\"weighted lying neck extension\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"traps\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"sternocleidomastoid\"],\"st\":[\"Lie face down on a bench with your head past the edge and a light weight on the back of your head.\",\"Start with your chin tucked toward your chest.\",\"Slowly lift your head until your neck is in line with your torso.\",\"Pause briefly, then lower with control.\",\"Keep the load light and the motion smooth.\"],\"img\":\"1042.webp\",\"gif\":\"1042.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down, you lift your head against a light load. It strengthens the muscles at the back of the neck.\",\"nd\":[\"bench\"]},{\"id\":\"2408\",\"n\":\"weighted lying neck extension (with head harness)\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Lie face down on a bench with your head past the edge and the weighted harness fitted.\",\"Start with your chin tucked toward your chest.\",\"Raise your head slowly until your face looks forward.\",\"Pause, then lower back under control.\",\"Use a light weight and smooth reps, never jerking the neck.\"],\"img\":\"2408.webp\",\"gif\":\"2408.mp4\",\"cat\":\"strength\",\"desc\":\"Lying face down with a harness on your head, you lift against added weight to strengthen the muscles at the back of the neck.\",\"nd\":[\"bench\"]},{\"id\":\"1043\",\"n\":\"weighted lying neck flexion\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"traps\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"upper back\"],\"st\":[\"Lie on your back on a bench with your head past the edge and a light weight on your forehead.\",\"Hold the weight with a hand for control.\",\"Slowly curl your head up, tucking your chin.\",\"Pause briefly, then lower with control.\",\"Keep the load light and avoid jerking.\"],\"img\":\"1043.webp\",\"gif\":\"1043.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back, you lift your head against a light load. It strengthens the muscles at the front of the neck.\",\"nd\":[\"bench\"]},{\"id\":\"2409\",\"n\":\"weighted lying neck flexion (with head harness)\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Lie on your back on a bench with your head past the edge and the harness fitted.\",\"Let your head hang back slightly in a comfortable range.\",\"Curl your chin toward your chest slowly.\",\"Pause briefly at the top.\",\"Lower under control and keep the weight light with smooth reps.\"],\"img\":\"2409.webp\",\"gif\":\"2409.mp4\",\"cat\":\"strength\",\"desc\":\"Lying on your back with a weighted head harness, you lift your chin toward your chest to train the neck flexors.\",\"nd\":[\"bench\"]},{\"id\":\"4432\",\"n\":\"weighted lying neck head twist\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie face up with a light weight resting on your forehead.\",\"Keep your chin slightly tucked.\",\"Rotate your head slowly to one side.\",\"Return to the middle and rotate to the other side.\",\"Keep the movement small and controlled.\"],\"img\":\"4432.webp\",\"gif\":\"4432.mp4\",\"cat\":\"strength\",\"desc\":\"A lying neck twist with light resistance to work the muscles that rotate the head.\"},{\"id\":\"4431\",\"n\":\"weighted lying neck side to side\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie face up with a light weight on your forehead.\",\"Keep your shoulders relaxed.\",\"Slowly turn your head toward one side.\",\"Return to the middle and turn the other way.\",\"Use light weight and smooth movement.\"],\"img\":\"4431.webp\",\"gif\":\"4431.mp4\",\"cat\":\"strength\",\"desc\":\"A lying neck exercise moving the head side to side against light resistance to strengthen the neck.\"},{\"id\":\"0838\",\"n\":\"weighted lying side lifting head (with head harness)\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie on your side on a bench with your head just past the edge, wearing a head harness with a light weight.\",\"Let your head hang slightly toward the floor.\",\"Lift your head up toward the ceiling, moving only your neck.\",\"Pause briefly at the top.\",\"Lower slowly and repeat, then switch sides.\",\"Use a light weight and a controlled pace.\"],\"img\":\"0838.webp\",\"gif\":\"0838.mp4\",\"cat\":\"strength\",\"desc\":\"A side-lying neck raise using a head harness with a weight. It builds strength in the muscles at the side of the neck.\",\"nd\":[\"bench\"]},{\"id\":\"4429\",\"n\":\"weighted lying side neck raise\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie on your side with your head supported at the edge of the bench.\",\"Place a light weight or plate on the side of your head, held steady.\",\"Lift your head slowly toward the ceiling.\",\"Pause, then lower under control.\",\"Complete your reps, then switch sides. Use light weight.\"],\"img\":\"4429.webp\",\"gif\":\"4429.mp4\",\"cat\":\"strength\",\"desc\":\"A gentle neck exercise lying on your side and lifting the head against light resistance to strengthen the side neck muscles.\"},{\"id\":\"0839\",\"n\":\"weighted lying twist\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Lie on your back with knees bent and hold a weight above your chest.\",\"Keep your shoulders on the floor.\",\"Lower your knees to one side.\",\"Return to centre and lower to the other side.\",\"Move slowly and keep control.\"],\"img\":\"0839.webp\",\"gif\":\"0839.mp4\",\"cat\":\"strength\",\"desc\":\"A lying trunk twist holding a weight. It works the obliques and the core.\"},{\"id\":\"1062\",\"n\":\"weighted one leg hip thrust\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"quadriceps\"],\"st\":[\"Rest your upper back on a bench and place the weight on your hips.\",\"Plant one foot and lift the other leg off the floor.\",\"Push through your heel to raise your hips until your torso is level.\",\"Pause and squeeze your glute.\",\"Lower slowly.\",\"Complete the reps, then change legs.\"],\"img\":\"1062.webp\",\"gif\":\"1062.mp4\",\"cat\":\"strength\",\"desc\":\"A single-leg hip thrust with weight resting on your hips. It strengthens each glute separately and fixes side-to-side gaps.\"},{\"id\":\"4185\",\"n\":\"weighted overhead press step up\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\"],\"st\":[\"Hold weight at your shoulders and stand facing a bench.\",\"Step up with one foot.\",\"As you stand, press the weight overhead.\",\"Lower the weight as you step down.\",\"Alternate legs.\",\"Keep your core braced.\"],\"img\":\"4185.webp\",\"gif\":\"4185.mp4\",\"cat\":\"strength\",\"desc\":\"A step up combined with an overhead press. It trains legs and shoulders together.\"},{\"id\":\"10875\",\"n\":\"weighted plate 45 degrees side bend\",\"bp\":\"waist\",\"eq\":\"weight plate\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower back\"],\"st\":[\"Set up on a 45 degree bench or hyperextension frame, side-on, feet secured.\",\"Hold a plate against your chest.\",\"Lower your torso sideways with control.\",\"Bend back up until your body is in a straight line.\",\"Avoid twisting. Finish your reps and switch sides.\"],\"img\":\"10875.webp\",\"gif\":\"10875.mp4\",\"cat\":\"strength\",\"desc\":\"A side bend holding a plate, done with the body at a 45 degree angle. It works the obliques.\",\"fv\":\"10876\"},{\"id\":\"3860\",\"n\":\"weighted plate bent over row\",\"bp\":\"back\",\"eq\":\"weight plate\",\"tg\":\"upper back\",\"mg\":\"lats\",\"sm\":[\"lats\",\"rhomboids\",\"biceps\",\"grip muscles\"],\"st\":[\"Hold a weight plate firmly with both hands at its edges.\",\"Hinge forward at the hips with a flat back and slightly bent knees.\",\"Let the plate hang below your chest with arms extended.\",\"Pull the plate toward your lower ribs, keeping your elbows close.\",\"Squeeze your shoulder blades together, then lower with control.\",\"Keep your hips still and your neck neutral.\"],\"img\":\"3860.webp\",\"gif\":\"3860.mp4\",\"cat\":\"strength\",\"desc\":\"A rowing movement holding a weight plate, good for the mid back and for grip strength.\"},{\"id\":\"10871\",\"n\":\"weighted plate crunch (hands overhead)\",\"bp\":\"waist\",\"eq\":\"weight plate\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet flat.\",\"Hold a plate with both hands and extend your arms overhead.\",\"Curl your shoulders and upper back off the floor, reaching the plate upward.\",\"Pause at the top and squeeze your abs.\",\"Lower slowly without dropping your head back.\"],\"img\":\"10871.webp\",\"gif\":\"10871.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch holding a weight plate overhead. The long lever makes your abs work harder.\",\"fv\":\"10872\"},{\"id\":\"10877\",\"n\":\"weighted plate crunch (hands overhead) v. 2\",\"bp\":\"waist\",\"eq\":\"weight plate\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with knees bent and feet planted.\",\"Hold a plate with straight arms overhead.\",\"Crunch up, lifting your shoulder blades off the floor.\",\"Keep your arms by your ears as you rise.\",\"Lower back down slowly and repeat.\"],\"img\":\"10877.webp\",\"gif\":\"10877.mp4\",\"cat\":\"strength\",\"desc\":\"A second take on the overhead plate crunch. It trains the abs with a long, loaded lever.\",\"fv\":\"10878\"},{\"id\":\"10189\",\"n\":\"weighted plate deadlift rear lunge with overhead press\",\"bp\":\"full body\",\"eq\":\"weight plate\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"quadriceps\",\"shoulders\",\"triceps\",\"core\"],\"st\":[\"Stand holding a weight plate in front of your thighs.\",\"Hinge at the hips and lower the plate toward your shins, then stand up.\",\"Step one foot back into a reverse lunge as you press the plate overhead.\",\"Return the foot and bring the plate back to your thighs.\",\"Keep a flat back and repeat, alternating the lunging leg.\"],\"img\":\"10189.webp\",\"gif\":\"10189.mp4\",\"cat\":\"strength\",\"desc\":\"A plate flow that links a deadlift, a reverse lunge and an overhead press for a full body hit.\"},{\"id\":\"11317\",\"n\":\"weighted plate hyperextension v. 2\",\"bp\":\"back\",\"eq\":\"weight plate\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"lower back\"],\"st\":[\"Set up on a hyperextension bench with your feet secured and hold a plate against your chest.\",\"Keep your back straight and body in a line.\",\"Lower your torso with control.\",\"Raise until you are back in a straight line.\",\"Squeeze your glutes at the top without overarching.\"],\"img\":\"11317.webp\",\"gif\":\"11317.mp4\",\"cat\":\"strength\",\"desc\":\"A back extension holding a weight plate. The plate adds resistance for the lower back and glutes.\",\"fv\":\"11318\"},{\"id\":\"10114\",\"n\":\"weighted plate lu raise\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand tall holding a weight plate with both hands at thigh height.\",\"Raise the plate out and up in a wide arc until it is about overhead.\",\"Pause briefly, keeping your ribs down and core tight.\",\"Lower the plate back along the same path with control.\",\"Use a light plate and avoid leaning back.\"],\"img\":\"10114.webp\",\"gif\":\"10114.mp4\",\"cat\":\"strength\",\"desc\":\"A plate raise that sweeps the weight out and up in a U shape, working the shoulders and upper traps.\"},{\"id\":\"9610\",\"n\":\"weighted plate overhead forward lunge\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Hold a weight plate overhead with straight arms.\",\"Step forward into a long stride.\",\"Lower your back knee toward the floor.\",\"Keep your torso upright and the plate steady.\",\"Push back to the start and alternate legs.\"],\"img\":\"9610.webp\",\"gif\":\"9610.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge holding a plate overhead. It trains the legs while challenging shoulder stability and the core.\"},{\"id\":\"5498\",\"n\":\"weighted plate overhead march\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"core\",\"sm\":[\"core\",\"shoulders\",\"hip flexors\",\"glutes\"],\"st\":[\"Hold a weight plate overhead with straight arms.\",\"Stand tall with ribs down and core braced.\",\"Lift one knee toward hip height.\",\"Lower it and lift the other knee in a controlled march.\",\"Keep the plate steady and avoid leaning back.\"],\"img\":\"5498.webp\",\"gif\":\"5498.mp4\",\"cat\":\"strength\",\"desc\":\"Marching in place while holding a plate overhead, building leg strength, balance and shoulder stability.\"},{\"id\":\"11657\",\"n\":\"weighted plate overhead reverse lunge\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"shoulders\",\"core\"],\"st\":[\"Hold a weight plate overhead with straight arms.\",\"Stand tall with feet hip-width apart.\",\"Step one foot back and lower until both knees are about 90 degrees.\",\"Keep your ribs down and the plate stable over your head.\",\"Push through the front foot to return, then alternate legs.\"],\"img\":\"11657.webp\",\"gif\":\"11657.mp4\",\"cat\":\"strength\",\"desc\":\"A reverse lunge while holding a plate overhead, which trains the legs and challenges shoulder and core stability.\"},{\"id\":\"8076\",\"n\":\"weighted plate push up\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Have a partner place a plate on your upper back, or set it carefully yourself.\",\"Get into a high plank.\",\"Lower your chest to the floor, elbows at about 45 degrees.\",\"Press back up to straight arms.\",\"Keep your body in a straight line.\"],\"img\":\"8076.webp\",\"gif\":\"8076.mp4\",\"cat\":\"strength\",\"desc\":\"A push-up with a weight plate on your upper back. The added load makes it harder once regular push-ups feel easy.\"},{\"id\":\"10097\",\"n\":\"weighted plate side up squat\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Hold a weight plate at your chest with both hands.\",\"Stand with feet shoulder width apart.\",\"Squat down until your thighs are parallel.\",\"Keep your chest up and elbows in.\",\"Push through your heels to stand.\",\"Keep the plate close to your body.\"],\"img\":\"10097.webp\",\"gif\":\"10097.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a weight plate in front of your chest. The plate acts as a counterweight and helps keep your torso upright.\"},{\"id\":\"6549\",\"n\":\"weighted plate standing around the world\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"core\",\"sm\":[\"core\",\"upper back\",\"forearms\"],\"st\":[\"Stand tall and hold a weight plate with both hands at your waist.\",\"Brace your core and keep your feet planted.\",\"Raise the plate up and over to one side in a wide circle, then around your head.\",\"Bring it back down on the other side.\",\"Keep your hips still as the plate travels.\",\"Do half the reps in each direction.\"],\"img\":\"6549.webp\",\"gif\":\"6549.mp4\",\"cat\":\"strength\",\"desc\":\"Passing a plate in a circle around the body while standing. It works the shoulders and trunk through many angles.\"},{\"id\":\"4847\",\"n\":\"weighted plate standing high front raise\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"upper chest\",\"sm\":[\"upper chest\",\"trapezius\",\"core\"],\"st\":[\"Stand holding a weight plate with both hands at your thighs.\",\"Keep your arms nearly straight.\",\"Raise the plate up and overhead.\",\"Pause at the top.\",\"Lower slowly.\"],\"img\":\"4847.webp\",\"gif\":\"4847.mp4\",\"cat\":\"strength\",\"desc\":\"Raising a weight plate in front of you to above eye level. It trains the front shoulders and upper chest.\"},{\"id\":\"6485\",\"n\":\"weighted plate standing lateral raise\",\"bp\":\"shoulders\",\"eq\":\"weight plate\",\"tg\":\"delts\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"rotator cuff\"],\"st\":[\"Stand tall holding a plate in each hand at your sides.\",\"Keep a slight bend in your elbows.\",\"Raise your arms out to the sides up to shoulder height.\",\"Pause briefly.\",\"Lower slowly and repeat.\"],\"img\":\"6485.webp\",\"gif\":\"6485.mp4\",\"cat\":\"strength\",\"desc\":\"Holding a weight plate in each hand, you raise your arms out to the sides to build the middle shoulders.\"},{\"id\":\"6559\",\"n\":\"weighted plate tibialis anterior curl\",\"bp\":\"lower legs\",\"eq\":\"weight plate\",\"tg\":\"calves\",\"mg\":\"shins\",\"sm\":[\"shins\",\"ankles\"],\"st\":[\"Sit on a bench and rest a plate on your forefoot.\",\"Keep your heel on the floor.\",\"Pull your toes up toward your shin.\",\"Pause at the top.\",\"Lower slowly and repeat.\"],\"img\":\"6559.webp\",\"gif\":\"6559.mp4\",\"cat\":\"strength\",\"desc\":\"Lifting your toes up against the weight of a plate to strengthen the muscle on the front of your shin.\"},{\"id\":\"0842\",\"n\":\"weighted pullover (on stability ball)\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"lats\",\"mg\":\"chest\",\"sm\":[\"chest\",\"triceps\",\"core\"],\"st\":[\"Lie with your upper back on the ball, hips lifted.\",\"Hold a weight with both hands above your chest.\",\"Lower it back over your head with slightly bent arms.\",\"Pull it back up over your chest.\",\"Keep your core tight and hips high.\"],\"img\":\"0842.webp\",\"gif\":\"0842.mp4\",\"cat\":\"strength\",\"desc\":\"A pullover with a weight while lying across a stability ball. It stretches and works the lats and chest.\"},{\"id\":\"3910\",\"n\":\"weighted push up with vest\",\"bp\":\"chest\",\"eq\":\"weighted\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Put on a weighted vest and start in a plank with hands under shoulders.\",\"Brace your core and glutes.\",\"Lower your chest to the floor with elbows at about 45 degrees.\",\"Press back up to straight arms.\",\"Keep your body in a straight line.\",\"Repeat for the set.\"],\"img\":\"3910.webp\",\"gif\":\"3910.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up wearing a weighted vest for extra load on the chest and triceps.\"},{\"id\":\"0843\",\"n\":\"weighted reduction triangle\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"adductors\",\"mg\":\"inner thighs\",\"sm\":[\"inner thighs\",\"core\"],\"st\":[\"Sit or lie with knees bent and a weight resting on your thighs.\",\"Let your knees open into a triangle.\",\"Squeeze your knees together against the weight.\",\"Pause briefly.\",\"Open slowly and repeat.\"],\"img\":\"0843.webp\",\"gif\":\"0843.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted inner-thigh squeeze, bringing the legs together in a triangle shape. It works the adductors.\"},{\"id\":\"10387\",\"n\":\"weighted sandbag carry (bear hug)\",\"bp\":\"full body\",\"eq\":\"sandbag\",\"tg\":\"abs\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"glutes\",\"forearms\",\"grip muscles\"],\"st\":[\"Lift the sandbag and hug it against your chest.\",\"Stand tall with your core braced.\",\"Walk forward with steady steps.\",\"Keep your arms squeezing the bag tight.\",\"Carry for a set distance or time, then lower the bag with care.\"],\"img\":\"10387.webp\",\"gif\":\"10387.mp4\",\"cat\":\"strength\",\"desc\":\"A walking carry with a sandbag held to the chest, taxing the core, arms and grip.\"},{\"id\":\"10386\",\"n\":\"weighted sandbag carry (shoulders)\",\"bp\":\"full body\",\"eq\":\"sandbag\",\"tg\":\"traps\",\"mg\":\"core\",\"sm\":[\"core\",\"glutes\",\"upper back\",\"forearms\"],\"st\":[\"Lift the sandbag onto your shoulders and hold it there.\",\"Stand tall with your core braced.\",\"Walk forward with steady, controlled steps.\",\"Keep your ribs stacked over your hips.\",\"Carry for a set distance or time, then set the bag down carefully.\"],\"img\":\"10386.webp\",\"gif\":\"10386.mp4\",\"cat\":\"strength\",\"desc\":\"A walking carry with a sandbag across the shoulders, building posture and trunk strength.\"},{\"id\":\"10383\",\"n\":\"weighted sandbag deadlift\",\"bp\":\"upper legs\",\"eq\":\"sandbag\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"grip muscles\",\"forearms\"],\"st\":[\"Stand over a sandbag with feet hip width apart.\",\"Hinge at your hips, bend your knees and grip the bag.\",\"Brace your core and drive through your feet to stand tall with the bag.\",\"Push your hips back and lower the bag to the floor.\",\"Keep your back flat throughout.\"],\"img\":\"10383.webp\",\"gif\":\"10383.mp4\",\"cat\":\"strength\",\"desc\":\"A deadlift with a sandbag, building hip and back strength with an awkward, grippy load.\"},{\"id\":\"9940\",\"n\":\"weighted sandbag forward lunge\",\"bp\":\"upper legs\",\"eq\":\"sandbag\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"adductors\"],\"st\":[\"Hold a sandbag against your chest or across your shoulders and stand tall.\",\"Step forward with one leg into a long stride.\",\"Lower until both knees are about 90 degrees with your torso upright.\",\"Push through the front foot to return to standing.\",\"Repeat with the other leg.\",\"Keep your front knee over your ankle and the bag tight to your body.\"],\"img\":\"9940.webp\",\"gif\":\"9940.mp4\",\"cat\":\"strength\",\"desc\":\"A forward lunge holding a sandbag at your chest or on your shoulders. The awkward load challenges your legs and core.\"},{\"id\":\"10388\",\"n\":\"weighted sandbag military press\",\"bp\":\"shoulders\",\"eq\":\"sandbag\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\",\"trapezius\"],\"st\":[\"Hold a sandbag at your upper chest or shoulders.\",\"Stand with feet hip width apart and brace your core.\",\"Press the bag straight overhead.\",\"Lock out the arms, then lower the bag with control.\",\"Keep your ribs down and avoid leaning back.\"],\"img\":\"10388.webp\",\"gif\":\"10388.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press using a sandbag, which shifts as you push, so your shoulders and core must stay tight.\"},{\"id\":\"10730\",\"n\":\"weighted sandbag romanian deadlift\",\"bp\":\"upper legs\",\"eq\":\"sandbag\",\"tg\":\"hamstrings\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"lower back\",\"grip muscles\",\"core\"],\"st\":[\"Hold a sandbag in front of your thighs with a firm grip.\",\"Stand with feet hip-width apart and knees slightly bent.\",\"Push your hips back and slide the bag down your legs.\",\"Lower until you feel a stretch in your hamstrings.\",\"Drive your hips forward to stand tall.\",\"Keep your back flat.\"],\"img\":\"10730.webp\",\"gif\":\"10730.mp4\",\"cat\":\"strength\",\"desc\":\"A hip hinge with a sandbag held in front of your thighs. It builds the hamstrings and glutes.\"},{\"id\":\"10389\",\"n\":\"weighted sandbag row\",\"bp\":\"back\",\"eq\":\"sandbag\",\"tg\":\"lats\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"biceps\",\"rhomboids\",\"grip muscles\",\"lower back\"],\"st\":[\"Stand over a sandbag, hinge forward and grab it with both hands.\",\"Keep your back flat and knees slightly bent.\",\"Row the bag toward your lower ribs.\",\"Squeeze your shoulder blades together.\",\"Lower slowly back to full arm extension.\"],\"img\":\"10389.webp\",\"gif\":\"10389.mp4\",\"cat\":\"strength\",\"desc\":\"A bent-over row with a sandbag, training the back and grip.\"},{\"id\":\"10385\",\"n\":\"weighted sandbag shouldering\",\"bp\":\"full body\",\"eq\":\"sandbag\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"lower back\",\"trapezius\",\"quadriceps\",\"upper back\"],\"st\":[\"Stand over a sandbag and grip it firmly with both hands.\",\"Lift the bag, driving through your legs and hips.\",\"Pull it to your lap, then heave it up onto one shoulder.\",\"Lower it to the floor with control.\",\"Alternate shoulders each rep.\"],\"img\":\"10385.webp\",\"gif\":\"10385.mp4\",\"cat\":\"strength\",\"desc\":\"A lift that heaves the sandbag from the floor up onto your shoulder, building power and total body strength.\"},{\"id\":\"10384\",\"n\":\"weighted sandbag squat\",\"bp\":\"upper legs\",\"eq\":\"sandbag\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"core\",\"upper back\"],\"st\":[\"Hold a sandbag in a bear hug against your chest.\",\"Stand with feet shoulder width apart.\",\"Sit back and down into a squat with your chest up.\",\"Drive through your heels to stand up.\",\"Keep the bag tight to your body.\"],\"img\":\"10384.webp\",\"gif\":\"10384.mp4\",\"cat\":\"strength\",\"desc\":\"A squat holding a sandbag against the chest, training the legs and the core.\"},{\"id\":\"4155\",\"n\":\"weighted seated calf raise\",\"bp\":\"lower legs\",\"eq\":\"weighted\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit on a bench with feet flat and the weight resting on your thighs.\",\"Place the balls of your feet on a raised edge if possible.\",\"Lift your heels as high as you can.\",\"Pause and squeeze your calves.\",\"Lower your heels slowly below the edge for a stretch.\",\"Hold the weight steady throughout.\"],\"img\":\"4155.webp\",\"gif\":\"4155.mp4\",\"cat\":\"strength\",\"desc\":\"A seated calf raise with weight resting on your thighs. The bent knee focuses the work on the soleus beneath the calf.\"},{\"id\":\"5483\",\"n\":\"weighted seated calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"weighted\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\"],\"st\":[\"Sit with the balls of your feet on a raised edge and weight resting on your knees.\",\"Lower your heels until you feel a calf stretch.\",\"Press up through the balls of your feet as high as you can.\",\"Pause at the top, then lower slowly.\",\"Keep your knees bent throughout.\"],\"img\":\"5483.webp\",\"gif\":\"5483.mp4\",\"cat\":\"strength\",\"desc\":\"Seated calf raise with weight on your thighs that targets the soleus muscle under the calf.\"},{\"id\":\"5023\",\"n\":\"weighted seated leg raise on floor\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\",\"quadriceps\"],\"st\":[\"Sit on the floor with your hands behind you and weight secured to your legs or between your feet.\",\"Lean back slightly and brace your core.\",\"Raise your legs up while keeping them as straight as you can.\",\"Lower them slowly without touching the floor.\",\"Keep your back from rounding too far.\"],\"img\":\"5023.webp\",\"gif\":\"5023.mp4\",\"cat\":\"strength\",\"desc\":\"Seated leg raise with added weight. It challenges the lower abs and hip flexors.\"},{\"id\":\"0848\",\"n\":\"weighted seated neck extension (with head harness)\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"trapezius\",\"sm\":[\"trapezius\",\"upper back\",\"sternocleidomastoid\"],\"st\":[\"Sit on a bench wearing a head harness with a light weight hanging in front.\",\"Lean slightly forward and rest your hands on your thighs.\",\"Let your chin drop toward your chest in a controlled way.\",\"Raise your head back up until your neck is neutral.\",\"Repeat slowly for the set.\",\"Keep your back straight and use a light load.\"],\"img\":\"0848.webp\",\"gif\":\"0848.mp4\",\"cat\":\"strength\",\"desc\":\"A seated neck extension with a weighted head harness, working the muscles at the back of the neck.\"},{\"id\":\"4154\",\"n\":\"weighted seated neutral wrist curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit with your forearm resting on your thigh, hand hanging past the knee.\",\"Hold the weight with a neutral grip, thumb up.\",\"Curl your wrist up toward your forearm.\",\"Pause at the top.\",\"Lower slowly until your wrist is extended.\",\"Complete all reps, then switch arms.\"],\"img\":\"4154.webp\",\"gif\":\"4154.mp4\",\"cat\":\"strength\",\"desc\":\"A seated wrist curl with palms facing each other. It strengthens the forearms and wrists.\"},{\"id\":\"4234\",\"n\":\"weighted seated one arm reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit and rest one forearm on your thigh, palm down.\",\"Let your hand hang over your knee with the weight.\",\"Lower your wrist for a stretch.\",\"Lift your hand up as high as you can.\",\"Lower slowly under control.\",\"Complete your reps and switch arms.\"],\"img\":\"4234.webp\",\"gif\":\"4234.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm reverse wrist curl, palm down, seated with a weight. It strengthens the top of the forearm.\"},{\"id\":\"4233\",\"n\":\"weighted seated one arm wrist curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"grip muscles\"],\"st\":[\"Sit and rest one forearm on your thigh, palm up.\",\"Let the weight roll toward your fingertips.\",\"Curl your wrist up as far as you can.\",\"Pause at the top.\",\"Lower slowly.\",\"Finish your reps and switch arms.\"],\"img\":\"4233.webp\",\"gif\":\"4233.mp4\",\"cat\":\"strength\",\"desc\":\"A one-arm wrist curl, palm up, seated with a weight. It builds the forearm flexors and grip.\"},{\"id\":\"4232\",\"n\":\"weighted seated reverse wrist curl\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"grip muscles\"],\"st\":[\"Sit with your forearms on your thighs, palms facing down.\",\"Let your hands hang over your knees holding weights.\",\"Lower your wrists to stretch the forearms.\",\"Curl your wrists up as high as you can.\",\"Lower slowly.\",\"Keep your forearms still on your thighs.\"],\"img\":\"4232.webp\",\"gif\":\"4232.mp4\",\"cat\":\"strength\",\"desc\":\"Wrist curls with palms down while seated, using a weight. They build the muscles on top of the forearm.\"},{\"id\":\"5484\",\"n\":\"weighted seated single calf raise v. 2\",\"bp\":\"lower legs\",\"eq\":\"weighted\",\"tg\":\"calves\",\"mg\":\"soleus\",\"sm\":[\"soleus\",\"ankles\"],\"st\":[\"Sit with one forefoot on a raised edge and weight on that knee.\",\"Lower the heel for a full stretch.\",\"Press up onto the ball of your foot as high as possible.\",\"Pause, then lower under control.\",\"Finish your reps and switch legs.\"],\"img\":\"5484.webp\",\"gif\":\"5484.mp4\",\"cat\":\"strength\",\"desc\":\"One-leg seated calf raise with weight on the knee, working the soleus with extra focus on each side.\"},{\"id\":\"10539\",\"n\":\"weighted seated single leg knee extension v. 2\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"quads\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\"],\"st\":[\"Strap a light ankle weight on and sit tall on a chair.\",\"Hold the seat edge for support.\",\"Straighten the knee until your leg is level.\",\"Hold for a second and squeeze your thigh.\",\"Lower slowly, then switch legs after your reps.\"],\"img\":\"10539.webp\",\"gif\":\"10539.mp4\",\"cat\":\"strength\",\"desc\":\"A seated knee extension with a light weight on the ankle. It adds load to build thigh strength.\"},{\"id\":\"4231\",\"n\":\"weighted seated supination\",\"bp\":\"lower arms\",\"eq\":\"weighted\",\"tg\":\"forearms\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"wrist flexors\"],\"st\":[\"Sit with your forearm resting on your thigh, hand over the knee.\",\"Hold a weighted handle or dumbbell end in your hand.\",\"Start with your palm facing down.\",\"Rotate your forearm slowly until your palm faces up.\",\"Return slowly to the start.\",\"Switch arms after your reps.\"],\"img\":\"4231.webp\",\"gif\":\"4231.mp4\",\"cat\":\"strength\",\"desc\":\"Seated forearm rotation holding a weight to turn your palm upward. It builds forearm strength and wrist control.\"},{\"id\":\"4092\",\"n\":\"weighted seated triceps extension\",\"bp\":\"upper arms\",\"eq\":\"weighted\",\"tg\":\"triceps\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"forearms\"],\"st\":[\"Sit upright on a bench and hold the weight overhead with both hands.\",\"Keep your elbows pointing forward and close to your head.\",\"Lower the weight behind your head by bending your elbows.\",\"Extend your arms to straighten them fully.\",\"Keep your back straight and core tight.\"],\"img\":\"4092.webp\",\"gif\":\"4092.mp4\",\"cat\":\"strength\",\"desc\":\"A seated overhead extension with added weight that isolates the triceps.\"},{\"id\":\"4623\",\"n\":\"weighted seated tuck crunch on floor\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"lower abs\"],\"st\":[\"Sit on the floor holding a weight at your chest, leaning back slightly with legs extended.\",\"Lift your feet off the floor.\",\"Pull your knees in while bringing your chest forward.\",\"Extend your legs again without touching the floor.\",\"Keep your back long and breathe steadily.\"],\"img\":\"4623.webp\",\"gif\":\"4623.mp4\",\"cat\":\"strength\",\"desc\":\"A seated tuck that brings the knees and chest together while holding a weight, targeting the lower abs.\"},{\"id\":\"4158\",\"n\":\"weighted side crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\"],\"st\":[\"Lie on your side with knees bent and hold a weight against your chest.\",\"Support your head lightly.\",\"Crunch your top ribs toward your hip.\",\"Pause and squeeze your side.\",\"Lower slowly without losing tension.\",\"Complete all reps, then switch sides.\"],\"img\":\"4158.webp\",\"gif\":\"4158.mp4\",\"cat\":\"strength\",\"desc\":\"A side crunch holding a weight to load the obliques. It builds strength along the sides of the waist.\"},{\"id\":\"4430\",\"n\":\"weighted side lying side neck raise\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"sternocleidomastoid\",\"sm\":[\"sternocleidomastoid\",\"trapezius\"],\"st\":[\"Lie on your side with your head supported at the edge of the bench.\",\"Place a light weight or plate on the side of your head, held steady.\",\"Lift your head slowly toward the ceiling.\",\"Pause, then lower under control.\",\"Complete your reps, then switch sides. Use light weight.\"],\"img\":\"4430.webp\",\"gif\":\"4430.mp4\",\"cat\":\"strength\",\"desc\":\"A gentle neck exercise lying on your side and lifting the head against light resistance to strengthen the side neck muscles.\"},{\"id\":\"3587\",\"n\":\"weighted single leg lift\",\"bp\":\"upper legs\",\"eq\":\"weighted\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"core\",\"lower back\"],\"st\":[\"Wear ankle weights and get on hands and knees or lie face down.\",\"Brace your core and keep your hips level.\",\"Raise the weighted leg without swinging.\",\"Pause at the top and squeeze.\",\"Lower slowly and switch legs.\"],\"img\":\"3587.webp\",\"gif\":\"3587.mp4\",\"cat\":\"strength\",\"desc\":\"Lift one leg while loaded with ankle weight, targeting the glutes and hip extensors.\"},{\"id\":\"3876\",\"n\":\"weighted squat jump with plate\",\"bp\":\"upper legs\",\"eq\":\"weight plate\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"calves\",\"core\"],\"st\":[\"Hold a weight plate close to your chest.\",\"Stand with feet shoulder-width apart.\",\"Squat down until your thighs are near parallel.\",\"Jump up explosively, extending your hips, knees and ankles.\",\"Land softly and go straight into the next rep.\",\"Keep your chest up throughout.\"],\"img\":\"3876.webp\",\"gif\":\"3876.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A jump squat holding a plate at your chest, building leg power.\"},{\"id\":\"3332\",\"n\":\"weighted stability ball crunch (full range)\",\"bp\":\"waist\",\"eq\":\"stability ball\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"lower abs\"],\"st\":[\"Sit on a stability ball and walk your feet out until your back is supported.\",\"Hold a weight against your chest.\",\"Let your torso drape back over the ball for a full stretch.\",\"Curl up until your upper back clears the ball.\",\"Lower slowly back into the stretch and repeat.\"],\"img\":\"3332.webp\",\"gif\":\"3332.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch over a stability ball while holding a weight, using the ball for a longer range of motion in your abs.\"},{\"id\":\"2410\",\"n\":\"weighted standing neck extension (with head harness)\",\"bp\":\"neck\",\"eq\":\"weighted\",\"tg\":\"levator scapulae\",\"mg\":\"upper back\",\"sm\":[\"upper back\",\"trapezius\"],\"st\":[\"Fit the head harness with a light weight hanging in front.\",\"Stand and hinge forward, resting your hands on your thighs.\",\"Let your chin drop toward your chest.\",\"Lift your head until your gaze is forward.\",\"Lower slowly and keep the movement small and controlled.\"],\"img\":\"2410.webp\",\"gif\":\"2410.mp4\",\"cat\":\"strength\",\"desc\":\"Standing and bent forward with a weighted harness, you raise your head against the load to build the back of the neck.\"},{\"id\":\"4175\",\"n\":\"weighted standing shoulder press\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper chest\",\"core\"],\"st\":[\"Stand with feet shoulder width apart, weight at shoulder height.\",\"Brace your core and squeeze your glutes.\",\"Press the weight straight overhead.\",\"Lock out without leaning back.\",\"Lower slowly to your shoulders.\",\"Keep your ribs down.\"],\"img\":\"4175.webp\",\"gif\":\"4175.mp4\",\"cat\":\"strength\",\"desc\":\"A standing overhead press with weight in hand. It builds shoulder and triceps strength.\"},{\"id\":\"0855\",\"n\":\"weighted standing twist\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\"],\"st\":[\"Stand with feet shoulder-width apart holding a weight at your chest.\",\"Keep your hips facing forward.\",\"Rotate your torso to one side.\",\"Return to centre and rotate to the other side.\",\"Move smoothly without jerking.\"],\"img\":\"0855.webp\",\"gif\":\"0855.mp4\",\"cat\":\"strength\",\"desc\":\"A standing torso rotation holding a weight. It builds the obliques and trunk control.\"},{\"id\":\"11716\",\"n\":\"weighted stone standing power overhead press\",\"bp\":\"shoulders\",\"eq\":\"weighted\",\"tg\":\"delts\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"upper back\",\"core\",\"glutes\"],\"st\":[\"Lift the stone to your chest, hugging it close.\",\"Stand with feet hip-width apart and brace your core.\",\"Dip slightly and drive up through your legs.\",\"Press the stone overhead to full lockout.\",\"Lower it back to your chest with control.\"],\"img\":\"11716.webp\",\"gif\":\"11716.mp4\",\"cat\":\"strength\",\"desc\":\"A strongman-style overhead press with a heavy stone, using a small leg drive for power.\"},{\"id\":\"4101\",\"n\":\"weighted straight leg toe touch crunch\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"obliques\"],\"st\":[\"Lie on your back with your legs straight up and a weight held in both hands.\",\"Reach the weight toward your toes.\",\"Lift your shoulder blades off the floor.\",\"Lower slowly with control.\",\"Keep your legs vertical and your neck relaxed.\"],\"img\":\"4101.webp\",\"gif\":\"4101.mp4\",\"cat\":\"strength\",\"desc\":\"A crunch with straight legs raised, reaching toward your toes while holding a weight for extra resistance.\"},{\"id\":\"1188\",\"n\":\"weighted twisting crunch (on bench)\",\"bp\":\"waist\",\"eq\":\"weighted\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"hip flexors\",\"core\"],\"st\":[\"Lie back on a bench with your knees bent and a weight held on your chest.\",\"Brace your abs and curl your upper body up.\",\"Rotate your torso so one elbow moves toward the opposite knee.\",\"Lower back down slowly without letting go of tension.\",\"Alternate sides each rep.\"],\"img\":\"1188.webp\",\"gif\":\"1188.mp4\",\"cat\":\"strength\",\"desc\":\"A weighted crunch with a rotation done on a bench that trains the abs and obliques.\"},{\"id\":\"1189\",\"n\":\"weighted v crunch (on bosu ball)\",\"bp\":\"waist\",\"eq\":\"bosu ball\",\"tg\":\"abs\",\"mg\":\"lower abs\",\"sm\":[\"lower abs\",\"hip flexors\",\"core\"],\"st\":[\"Sit on a bosu ball and lean back slightly, holding a weight in front of you.\",\"Lift your feet off the floor with your legs bent or straight.\",\"Bring your chest and knees toward each other in a V shape.\",\"Lower back with control, keeping your spine long.\",\"Stay stable on the ball throughout.\"],\"img\":\"1189.webp\",\"gif\":\"1189.mp4\",\"cat\":\"strength\",\"desc\":\"A V-shaped crunch on a bosu ball with added weight, which challenges the abs and balance together.\"},{\"id\":\"6297\",\"n\":\"wheel pose urdhva dhanurasana\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"shoulders\",\"triceps\",\"hip flexors\"],\"st\":[\"Lie on your back, knees bent, hands beside your head with fingers toward your feet.\",\"Press into hands and feet and lift your hips.\",\"Straighten your arms as you lift the crown of your head off the floor.\",\"Press your chest toward the wall behind.\",\"Hold for a few breaths, then lower slowly.\"],\"img\":\"6297.webp\",\"gif\":\"6297.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep backbend pressing up from the floor. It opens the chest and shoulders and strengthens the back and legs.\"},{\"id\":\"1493\",\"n\":\"wheel pose yoga pose\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"shoulders\",\"sm\":[\"shoulders\",\"glutes\",\"quadriceps\",\"chest\"],\"st\":[\"Lie on your back with your knees bent and feet flat near your hips.\",\"Place your palms beside your head with fingers pointing toward your shoulders.\",\"Press through your hands and feet to lift your hips and then your head.\",\"Straighten your arms as far as comfortable and keep your thighs parallel.\",\"Hold for 5-15 seconds, then lower slowly with your chin tucked.\"],\"img\":\"1493.webp\",\"gif\":\"1493.mp4\",\"cat\":\"yoga\",\"desc\":\"A deep yoga backbend with hands and feet on the floor and the body arched upward. It opens the chest and strengthens the back.\"},{\"id\":\"4093\",\"n\":\"wheel rollout with wall support\",\"bp\":\"waist\",\"eq\":\"wheel roller\",\"tg\":\"abs\",\"mg\":\"lats\",\"sm\":[\"lats\",\"shoulders\",\"core\",\"lower abs\"],\"st\":[\"Kneel facing a wall with the ab wheel on the floor in front of you.\",\"Grip the handles and tuck your pelvis under.\",\"Roll forward until the wheel touches the wall.\",\"Pull the wheel back by contracting your abs.\",\"Keep your back flat and avoid sagging at the hips.\"],\"img\":\"4093.webp\",\"gif\":\"4093.mp4\",\"cat\":\"strength\",\"desc\":\"An ab wheel rollout where a wall stops the wheel, making it a safer way to train your abs and core.\"},{\"id\":\"4805\",\"n\":\"wide air squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\",\"core\"],\"st\":[\"Stand with feet well wider than your shoulders and toes angled out.\",\"Raise your arms in front for balance.\",\"Sit your hips down and back, pushing your knees out over your toes.\",\"Lower until your thighs are about parallel to the floor.\",\"Drive through your heels to stand back up.\"],\"img\":\"4805.webp\",\"gif\":\"4805.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A bodyweight squat with a wide stance and toes turned out. It puts extra work on the glutes and inner thighs.\"},{\"id\":\"9323\",\"n\":\"wide bench air squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"adductors\",\"hamstrings\"],\"st\":[\"Stand in front of a bench with your feet wide and toes turned out.\",\"Push your hips back and lower down.\",\"Lightly touch the bench.\",\"Keep your knees tracking over your toes.\",\"Press through your heels to stand.\",\"Keep your chest tall.\"],\"img\":\"9323.webp\",\"gif\":\"9323.mp4\",\"cat\":\"calisthenics\",\"desc\":\"An air squat with a wide stance, touching a bench to guide your depth. It works the glutes and inner thighs.\"},{\"id\":\"8189\",\"n\":\"wide chin up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"upper back\",\"forearms\",\"rhomboids\"],\"st\":[\"Hang from a bar with an underhand grip wider than shoulders.\",\"Brace your core.\",\"Pull until your chin is over the bar.\",\"Squeeze your back at the top.\",\"Lower slowly to a full hang.\"],\"img\":\"8189.webp\",\"gif\":\"8189.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A chin-up with a wider underhand grip. It hits the lats and biceps.\",\"fv\":\"4915\"},{\"id\":\"5805\",\"n\":\"wide glute pulse bridge\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hamstrings\",\"sm\":[\"hamstrings\",\"adductors\"],\"st\":[\"Lie on your back with your knees bent and feet wide apart.\",\"Lift your hips to the top of a bridge.\",\"Pulse your hips up and down in small, controlled movements.\",\"Keep your glutes squeezed throughout.\",\"Lower fully after your set.\"],\"img\":\"5805.webp\",\"gif\":\"5805.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A glute bridge with feet set wide and small pulses at the top. Burns the glutes with constant tension.\"},{\"id\":\"1866\",\"n\":\"wide grip pull up on dip cage\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"forearms\"],\"st\":[\"Grab the wide handles with your palms facing forward.\",\"Hang with your arms fully extended.\",\"Pull yourself up by driving your elbows down and back.\",\"Pause when your chin clears the bar.\",\"Lower slowly to a full hang.\"],\"img\":\"1866.webp\",\"gif\":\"1866.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Wide-grip pull-up performed on the dip cage that emphasises the lats.\"},{\"id\":\"0965\",\"n\":\"wide legged forward bend prasarita padottanasana\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"hamstrings\",\"mg\":\"adductors\",\"sm\":[\"adductors\",\"calves\",\"lower back\"],\"st\":[\"Stand with feet about one leg-length apart and toes pointing slightly in.\",\"Place your hands on your hips and hinge forward with a flat back.\",\"Lower your hands to the floor under your shoulders.\",\"Let your head hang long.\",\"Hold for 20-30 seconds while breathing slowly.\"],\"img\":\"0965.webp\",\"gif\":\"0965.mp4\",\"cat\":\"stretching\",\"desc\":\"Fold forward with your feet far apart. It stretches the hamstrings and inner thighs and eases the back.\"},{\"id\":\"7342\",\"n\":\"wide plank side tap\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with feet wider than your hips.\",\"Brace your core and keep your hips level.\",\"Lift one hand and tap your opposite hip or thigh.\",\"Return the hand and tap with the other side.\",\"Move slowly without rocking.\"],\"img\":\"7342.webp\",\"gif\":\"7342.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Wide-stance plank with alternating side taps that challenge core stability.\"},{\"id\":\"2740\",\"n\":\"wide push up (wall)\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Stand facing a wall and place your hands on it, wider than your shoulders.\",\"Step your feet back so your body leans in a straight line.\",\"Bend your elbows to bring your chest toward the wall.\",\"Push back to the start.\",\"Keep your hips in line with your shoulders.\"],\"img\":\"2740.webp\",\"gif\":\"2740.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A beginner-friendly standing push-up against a wall with a wide hand position to emphasise the chest.\"},{\"id\":\"4806\",\"n\":\"wide seated pull up\",\"bp\":\"back\",\"eq\":\"body weight\",\"tg\":\"lats\",\"mg\":\"biceps\",\"sm\":[\"biceps\",\"rhomboids\",\"forearms\",\"grip muscles\"],\"st\":[\"Sit under a pull-up bar and take a wide overhand grip.\",\"Hang with arms extended and your chest lifted.\",\"Pull your elbows down and toward your ribs to bring your chest toward the bar.\",\"Squeeze your shoulder blades together at the top.\",\"Lower yourself slowly to full arm extension.\"],\"img\":\"4806.webp\",\"gif\":\"4806.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A wide-grip pull from a seated start position. It trains the lats and upper back with a lower starting load than a full pull-up.\"},{\"id\":\"5865\",\"n\":\"wide stance jump squat to narrow stance jump squat\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"hamstrings\",\"adductors\",\"calves\"],\"st\":[\"Stand with your feet wide and squat down.\",\"Jump up, bringing your feet together mid-air.\",\"Land softly in a narrow stance and squat.\",\"Jump again, landing back in the wide stance.\",\"Keep your chest up and move at a steady pace.\"],\"img\":\"5865.webp\",\"gif\":\"5865.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Jump squats that alternate between a wide and a narrow stance. It builds explosive leg power and gets your heart rate up.\"},{\"id\":\"9246\",\"n\":\"wide stance thoracic rotation\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"spine\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"core\",\"upper back\"],\"st\":[\"Stand with your feet wide and your knees slightly bent.\",\"Hinge slightly forward with your hands behind your head.\",\"Rotate your chest to one side as far as you can.\",\"Keep your hips facing forward.\",\"Return to the center.\",\"Rotate to the other side and repeat.\"],\"img\":\"9246.webp\",\"gif\":\"9246.mp4\",\"cat\":\"mobility\",\"desc\":\"In a wide stance you rotate your upper back to loosen the thoracic spine. It helps with trunk twisting.\"},{\"id\":\"4807\",\"n\":\"wide to narrow push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"core\"],\"st\":[\"Start in a high plank with your hands wider than your shoulders.\",\"Lower your chest to the floor with your body in a straight line.\",\"Push back up to the top.\",\"Walk your hands in to a narrow, close position.\",\"Repeat a push-up, then step your hands back out wide.\"],\"img\":\"4807.webp\",\"gif\":\"4807.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A push-up where the hands move from a wide to a narrow position between reps. It shifts the load from chest to triceps.\"},{\"id\":\"1249\",\"n\":\"wipers (straight leg)\",\"bp\":\"waist\",\"eq\":\"body weight\",\"tg\":\"abs\",\"mg\":\"obliques\",\"sm\":[\"obliques\",\"lower abs\",\"hip flexors\"],\"st\":[\"Lie on your back with your arms out to the sides.\",\"Raise your legs straight up over your hips.\",\"Lower both legs to one side with control.\",\"Lift them back to the middle and lower to the other side.\",\"Keep your shoulders flat on the floor.\"],\"img\":\"1249.webp\",\"gif\":\"1249.mp4\",\"cat\":\"calisthenics\",\"desc\":\"Swinging straight legs from side to side like windshield wipers. It is a tough one for the obliques and lower abs.\"},{\"id\":\"4633\",\"n\":\"world's greatest stretch\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"glutes\",\"mg\":\"hip flexors\",\"sm\":[\"hip flexors\",\"hamstrings\",\"upper back\",\"obliques\"],\"st\":[\"Step into a long lunge with both hands on the floor inside your front foot.\",\"Drop your hips low.\",\"Rotate your chest toward the front leg and raise that arm.\",\"Return the hand to the floor and straighten the front leg.\",\"Switch sides and repeat.\"],\"img\":\"4633.webp\",\"gif\":\"4633.mp4\",\"cat\":\"mobility\",\"desc\":\"A multi-part warm-up combining a lunge, a rotation and a hamstring stretch.\"},{\"id\":\"1792\",\"n\":\"wrap around shoulder stretch\",\"bp\":\"shoulders\",\"eq\":\"body weight\",\"tg\":\"delts\",\"mg\":\"rear deltoids\",\"sm\":[\"rear deltoids\",\"upper back\",\"rhomboids\"],\"st\":[\"Stand tall and bring one arm across your chest at shoulder height.\",\"Hook it with your other forearm and pull it gently closer to your chest.\",\"Keep your shoulders relaxed and your breathing slow and steady.\",\"Hold for 20-30 seconds without bouncing.\",\"Release gently and repeat, switching sides if the stretch is one-sided.\"],\"img\":\"1792.webp\",\"gif\":\"1792.mp4\",\"cat\":\"stretching\",\"desc\":\"Wrapping one arm across your body and hooking it with the other stretches the back of the shoulder and upper back.\"},{\"id\":\"4938\",\"n\":\"wrist abduction\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"wrist flexors\"],\"st\":[\"Rest your forearm on a table with your hand off the edge.\",\"Keep your palm facing in.\",\"Tilt your hand up toward the thumb side.\",\"Return to neutral slowly.\",\"Keep your forearm still.\",\"Do equal reps on both wrists.\"],\"img\":\"4938.webp\",\"gif\":\"4938.mp4\",\"cat\":\"mobility\",\"desc\":\"A gentle wrist movement that tilts the hand toward the thumb side. It improves wrist mobility.\"},{\"id\":\"2789\",\"n\":\"wrist adduction\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"wrist extensors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Rest your forearm on a table with your hand hanging off the edge, thumb up.\",\"Tilt your hand down toward the little finger side.\",\"Pause briefly, then return to neutral under control.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2789.webp\",\"gif\":\"2789.mp4\",\"cat\":\"mobility\",\"desc\":\"Tilting the wrist toward the little finger side, working the forearm muscles that guide the wrist.\"},{\"id\":\"2790\",\"n\":\"wrist extension\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Rest your forearm on a table with your hand hanging off the edge, palm down.\",\"Raise your hand upward by bending the wrist back.\",\"Pause briefly, then lower slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2790.webp\",\"gif\":\"2790.mp4\",\"cat\":\"mobility\",\"desc\":\"Lifting the back of the hand up, working the top of the forearm.\"},{\"id\":\"11383\",\"n\":\"wrist extensor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\"],\"st\":[\"Extend one arm in front of you with the elbow straight and palm facing down.\",\"Bend the wrist so your fingers point toward the floor.\",\"With your other hand, gently pull the back of the hand toward you.\",\"Keep the stretch mild and your shoulder relaxed.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"11383.webp\",\"gif\":\"11383.mp4\",\"cat\":\"stretching\",\"desc\":\"Stretches the muscles on top of the forearm that lift the wrist. Good after typing, climbing or heavy gripping.\",\"fv\":\"1849\"},{\"id\":\"2791\",\"n\":\"wrist flexion\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\"],\"st\":[\"Stand or sit tall with a relaxed posture and the joint in a neutral starting position.\",\"Rest your forearm on a table with your hand hanging off the edge, palm up.\",\"Curl your hand upward by bending the wrist toward your forearm.\",\"Pause briefly, then lower slowly.\",\"Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time.\"],\"img\":\"2791.webp\",\"gif\":\"2791.mp4\",\"cat\":\"mobility\",\"desc\":\"Curling the hand toward the forearm, working the underside of the forearm.\"},{\"id\":\"1850\",\"n\":\"wrist flexor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Extend one arm in front of you with the palm up.\",\"Use your other hand to pull the fingers back toward you.\",\"Keep your elbow straight and your shoulder relaxed.\",\"Feel the stretch along the inner forearm.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"1850.webp\",\"gif\":\"1850.mp4\",\"cat\":\"stretching\",\"desc\":\"A simple forearm stretch for the wrist flexors, helpful after gripping or typing.\"},{\"id\":\"6982\",\"n\":\"wrist full push up\",\"bp\":\"chest\",\"eq\":\"body weight\",\"tg\":\"pectorals\",\"mg\":\"triceps\",\"sm\":[\"triceps\",\"shoulders\",\"wrist extensors\",\"core\"],\"st\":[\"Start in a plank with your hands under your shoulders.\",\"Spread your fingers and keep your wrists stacked.\",\"Lower your chest to the floor under control.\",\"Press back to the top.\",\"Keep your body straight from head to heels.\"],\"img\":\"6982.webp\",\"gif\":\"6982.mp4\",\"cat\":\"calisthenics\",\"desc\":\"A full push-up focusing on wrist position and control. It builds the chest while preparing the wrists for load.\"},{\"id\":\"1823\",\"n\":\"wrist radial deviator and extensor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"hands\"],\"st\":[\"Extend one arm in front of you with the palm down.\",\"Bend the wrist so your fingers point down.\",\"Gently tilt the hand toward the thumb side.\",\"Use the other hand to apply light pressure.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"1823.webp\",\"gif\":\"1823.mp4\",\"cat\":\"stretching\",\"desc\":\"A forearm stretch that targets the wrist extensors with radial deviation.\"},{\"id\":\"1824\",\"n\":\"wrist radial deviator and flexor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Extend one arm in front of you with the palm up.\",\"Use your other hand to pull the fingers back toward you.\",\"Gently tilt the hand toward the thumb side.\",\"Keep the elbow straight and your shoulder relaxed.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"1824.webp\",\"gif\":\"1824.mp4\",\"cat\":\"stretching\",\"desc\":\"A forearm stretch that targets the wrist flexors with radial deviation.\"},{\"id\":\"1822\",\"n\":\"wrist ulnar deviator and extensor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist extensors\",\"sm\":[\"wrist extensors\",\"hands\"],\"st\":[\"Extend one arm in front of you with the palm down.\",\"Bend the wrist so your fingers point down.\",\"Gently tilt the hand toward the little finger side.\",\"Use the other hand to apply light pressure.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"1822.webp\",\"gif\":\"1822.mp4\",\"cat\":\"stretching\",\"desc\":\"A forearm stretch that targets the wrist extensors with ulnar deviation, easing tightness after gripping or typing.\"},{\"id\":\"1825\",\"n\":\"wrist ulnar deviator and flexor stretch\",\"bp\":\"lower arms\",\"eq\":\"body weight\",\"tg\":\"forearms\",\"mg\":\"wrist flexors\",\"sm\":[\"wrist flexors\",\"hands\"],\"st\":[\"Extend one arm in front of you with the palm up.\",\"Use your other hand to pull the fingers back toward you.\",\"Gently tilt the hand toward the little finger side.\",\"Keep the elbow straight and your shoulder relaxed.\",\"Hold for 20-30 seconds, then switch arms.\"],\"img\":\"1825.webp\",\"gif\":\"1825.mp4\",\"cat\":\"stretching\",\"desc\":\"A forearm stretch that targets the wrist flexors with ulnar deviation.\"},{\"id\":\"2926\",\"n\":\"x band side walk\",\"bp\":\"upper legs\",\"eq\":\"band\",\"tg\":\"abductors\",\"mg\":\"glutes\",\"sm\":[\"glutes\",\"quadriceps\",\"hip flexors\",\"calves\"],\"st\":[\"Cross the band into an X and place it around your feet or lower legs, holding the ends as needed.\",\"Stand in a quarter squat with your chest up.\",\"Step sideways, keeping tension on the band.\",\"Bring the trailing foot in without letting your feet touch.\",\"Walk the set distance, then return the other way.\"],\"img\":\"2926.webp\",\"gif\":\"2926.mp4\",\"cat\":\"strength\",\"desc\":\"Stepping sideways against a band anchored in an X pattern. It fires up the hips and outer glutes.\"},{\"id\":\"5979\",\"n\":\"x drill\",\"bp\":\"full body\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"quadriceps\",\"sm\":[\"quadriceps\",\"hamstrings\",\"glutes\",\"calves\"],\"st\":[\"Set four cones in a square, with a center point.\",\"Sprint diagonally from one corner through the center to the opposite corner.\",\"Shuffle sideways along one edge to the next corner.\",\"Backpedal or sprint diagonally again.\",\"Stay low through turns and repeat.\"],\"img\":\"5979.webp\",\"gif\":\"5979.mp4\",\"cat\":\"plyometrics\",\"desc\":\"A cone drill in an X pattern that mixes sprints, shuffles and backpedals for agility.\"},{\"id\":\"6444\",\"n\":\"yoga vajrasana thunderbolt diamond pose\",\"bp\":\"upper legs\",\"eq\":\"body weight\",\"tg\":\"quads\",\"mg\":\"ankles\",\"sm\":[\"ankles\",\"shins\",\"feet\"],\"st\":[\"Kneel on the floor with your knees together.\",\"Point your toes back and sit on your heels.\",\"Rest your hands on your thighs.\",\"Lengthen your spine and breathe slowly.\",\"Hold for 30-60 seconds.\"],\"img\":\"6444.webp\",\"gif\":\"6444.mp4\",\"cat\":\"yoga\",\"desc\":\"Sitting back on your heels in a kneeling pose that stretches your thighs, shins and ankles while keeping your spine tall.\"},{\"id\":\"3198\",\"n\":\"zigzag hops\",\"bp\":\"cardio\",\"eq\":\"body weight\",\"tg\":\"cardiovascular system\",\"mg\":\"calves\",\"sm\":[\"calves\",\"glutes\",\"quadriceps\",\"hip flexors\"],\"st\":[\"Stand with your knees slightly bent.\",\"Hop forward and to one side.\",\"Land softly on both feet.\",\"Hop forward and to the other side.\",\"Keep your hops light and quick.\",\"Continue for 20-30 seconds.\"],\"img\":\"3198.webp\",\"gif\":\"3198.mp4\",\"cat\":\"plyometrics\",\"desc\":\"Hopping diagonally forward in a zigzag pattern. It trains agility and lower leg power.\"}]")
